### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var habitDescription: String
    var createdAt: Date
    var lastCompletedAt: Date?
    var currentStreak: Int
    var bestStreak: Int
    var completionDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        lastCompletedAt: Date? = nil,
        currentStreak: Int = 0,
        bestStreak: Int = 0,
        completionDates: [Date] = []
    ) {
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.lastCompletedAt = lastCompletedAt
        self.currentStreak = currentStreak
        self.bestStreak = bestStreak
        self.completionDates = completionDates
    }

    var isCompletedToday: Bool {
        guard let lastCompletedAt else { return false }
        return Calendar.current.isDateInToday(lastCompletedAt)
    }

    func markCompleted() {
        let now = Date()

        if !isCompletedToday {
            completionDates.append(now)

            if let last = lastCompletedAt,
               Calendar.current.isDate(last, inSameDayAs: Calendar.current.date(byAdding: .day, value: -1, to: now) ?? now) {
                currentStreak += 1
            } else {
                currentStreak = 1
            }

            bestStreak = max(bestStreak, currentStreak)
            lastCompletedAt = now
        }
    }

    func resetCompletionForToday() {
        guard isCompletedToday else { return }
        completionDates.removeAll { Calendar.current.isDateInToday($0) }
        lastCompletedAt = completionDates.last
        currentStreak = 0
    }
}
```

