### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetPerDay: Int
    var completedDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetPerDay: Int = 1
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerDay = targetPerDay
        self.completedDates = []
    }

    var todayCompletions: Int {
        let calendar = Calendar.current
        return completedDates.filter { calendar.isDateInToday($0) }.count
    }

    var isCompletedToday: Bool {
        todayCompletions >= targetPerDay
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let dates = Set(completedDates.map { calendar.startOfDay(for: $0) })
        var streak = 0
        var day = calendar.startOfDay(for: Date())

        while dates.contains(day) {
            streak += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: day) else { break }
            day = previousDay
        }

        return streak
    }

    func markCompleted() {
        completedDates.append(Date())
    }

    func undoLastCompletion() {
        if let lastIndex = completedDates.lastIndex(where: { Calendar.current.isDateInToday($0) }) {
            completedDates.remove(at: lastIndex)
        }
    }
}
```

