                .foregroundStyle(.secondary)
            Text("No habits yet")
                .font(.title3.bold())
            Text("Tap + to create your first habit.")
                .foregroundStyle(.secondary)
            Spacer()
        }
        .frame(maxWidth: .infinity)
    }

    private func deleteHabit(_ habit: Habit) {
        modelContext.delete(habit)
    }
