## 2) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    var id: UUID = UUID()
    var name: String
    var symbol: String
    var colorHex: String
    var createdAt: Date = Date()

    // Tracking
    var completionDates: [Date] = []

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted()

        guard let lastDate = sortedDates.last else { return 0 }

        var streakCount = 1
        var currentDate = lastDate

        for date in sortedDates.dropLast().reversed() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streakCount += 1
                currentDate = date
            } else {
                break
            }
        }

        return streakCount
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let calendar = Calendar.current
        return completionDates.contains { calendar.isDate($0, inSameDayAs: date) }
    }

    mutating func toggleCompletion(for date: Date = Date()) {
        let calendar = Calendar.current
        if let index = completionDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: date) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(date)
        }
    }
}
```

