            .sheet(isPresented: $showingAddHabit) {
                HabitEditorView { name, symbol, colorHex in
                    store.addHabit(name: name, symbol: symbol, colorHex: colorHex)
                }
            }
            .sheet(item: $editingHabit) { habit in
                HabitEditorView(existingHabit: habit) { name, symbol, colorHex in
                    var updated = habit
                    updated.name = name
                    updated.symbol = symbol
                    updated.colorHex = colorHex
                    store.updateHabit(updated)
                }
            }
        }
    }
