## 2) Data Model

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var colorHex: String
    var targetPerWeek: Int
    var completedDates: [Date]

    init(
        name: String,
        details: String = "",
        colorHex: String = "#4F46E5",
        targetPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerWeek = targetPerWeek
        self.completedDates = []
    }

    var todayCompleted: Bool {
        completedDates.contains(where: { Calendar.current.isDateInToday($0) })
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }

    var totalCompletions: Int {
        completedDates.count
    }

    mutating func toggleTodayCompletion() {
        let calendar = Calendar.current
        if let index = completedDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(Date())
        }
    }
}
```

