## 2) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var targetPerDay: Int
    var colorHex: String

    // Stored as [Date] of completion timestamps
    var completions: [Date]

    init(
        name: String,
        habitDescription: String = "",
        targetPerDay: Int = 1,
        colorHex: String = "#4F46E5"
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.targetPerDay = targetPerDay
        self.colorHex = colorHex
        self.completions = []
    }

    var todayCompletions: Int {
        let calendar = Calendar.current
        return completions.filter { calendar.isDateInToday($0) }.count
    }

    var isCompletedToday: Bool {
        todayCompletions >= targetPerDay
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let days = Set(completions.map { calendar.startOfDay(for: $0) })

        var streak = 0
        var date = calendar.startOfDay(for: Date())

        while days.contains(date) {
            streak += 1
            guard let previous = calendar.date(byAdding: .day, value: -1, to: date) else { break }
            date = previous
        }

        return streak
    }

    var totalCompletions: Int {
        completions.count
    }

    func markCompleted() {
        completions.append(Date())
    }

    func unmarkTodayCompletion() {
        let calendar = Calendar.current
        if let index = completions.lastIndex(where: { calendar.isDateInToday($0) }) {
            completions.remove(at: index)
        }
    }
}
```

