## 2) Model: `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var icon: String
    var colorHex: String
    var createdAt: Date

    // Tracking
    var completionDates: [Date]
    var currentStreak: Int
    var bestStreak: Int

    init(
        name: String,
        habitDescription: String = "",
        icon: String = "checkmark.circle.fill",
        colorHex: String = "#4CAF50"
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.icon = icon
        self.colorHex = colorHex
        self.createdAt = Date()
        self.completionDates = []
        self.currentStreak = 0
        self.bestStreak = 0
    }

    func isCompletedToday() -> Bool {
        Calendar.current.isDate(completionDates.last, inSameDayAs: Date())
    }

    func markCompletedToday() {
        let today = Date()

        guard !completionDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: today) }) else {
            return
        }

        completionDates.append(today)
        updateStreak()
    }

    func updateStreak() {
        let calendar = Calendar.current
        let sortedDates = completionDates.sorted()

        guard let lastDate = sortedDates.last else {
            currentStreak = 0
            return
        }

        var streak = 1
        var previousDate = lastDate

        for date in sortedDates.dropLast().reversed() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: previousDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                previousDate = date
            } else if calendar.isDate(date, inSameDayAs: previousDate) {
                continue
            } else {
                break
            }
        }

        currentStreak = streak
        bestStreak = max(bestStreak, currentStreak)
    }

    func completionCountThisWeek() -> Int {
        let calendar = Calendar.current
        let now = Date()
        guard let weekInterval = calendar.dateInterval(of: .weekOfYear, for: now) else { return 0 }

        return completionDates.filter { weekInterval.contains($0) }.count
    }
}
```

