## 1) `Habit.swift`

```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var notes: String
    var createdAt: Date
    var completionDates: [Date]

    init(id: UUID = UUID(),
         name: String,
         notes: String = "",
         createdAt: Date = Date(),
         completionDates: [Date] = []) {
        self.id = id
        self.name = name
        self.notes = notes
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streakCount += 1
                currentDate = date
            } else {
                break
            }
        }

        return streakCount
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        return completionDates.contains { calendar.isDate($0, inSameDayAs: today) }
    }
}
