## 8) Optional: Better streak calculation

The streak logic above is simple, but if you want a more accurate streak that handles gaps properly, replace the `streak` computed property in `Habit.swift` with this:

```swift
var streak: Int {
    let calendar = Calendar.current
    let uniqueDays = Set(completionDates.map { calendar.startOfDay(for: $0) })
    let sortedDays = uniqueDays.sorted(by: >)

    guard !sortedDays.isEmpty else { return 0 }

    var streak = 1
    var currentDay = sortedDays[0]

    for day in sortedDays.dropFirst() {
        guard let yesterday = calendar.date(byAdding: .day, value: -1, to: currentDay) else { break }
        if calendar.isDate(day, inSameDayAs: yesterday) {
            streak += 1
            currentDay = day
        } else {
            break
        }
    }

    return streak
}
