```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String, details: String = "") {
        self.id = UUID()
        self.name = name
        self.details = details
        self.createdAt = Date()
        self.completedDates = []
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates.sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = calendar.startOfDay(for: first)

        for date in sortedDates.dropFirst() {
            let nextDate = calendar.startOfDay(for: date)
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(nextDate, inSameDayAs: expected) {
                streak += 1
                currentDate = nextDate
            } else if calendar.isDate(nextDate, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }

        return streak
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completedDates.contains { calendar.isDateInToday($0) }
    }

    func toggleTodayCompletion() {
        let calendar = Calendar.current

        if let index = completedDates.firstIndex(where: { calendar.isDateInToday($0) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(Date())
        }
    }
}
```

