## 3) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetPerDay: Int
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetPerDay: Int = 1,
        isArchived: Bool = false
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetPerDay = targetPerDay
        self.isArchived = isArchived
    }

    var streak: Int {
        let calendar = Calendar.current
        let sorted = completions.sorted { $0.date > $1.date }

        var streakCount = 0
        var expectedDate = calendar.startOfDay(for: Date())

        while true {
            let hasCompletion = sorted.contains {
                calendar.isDate($0.date, inSameDayAs: expectedDate)
            }

            if hasCompletion {
                streakCount += 1
                guard let previousDay = calendar.date(byAdding: .day, value: -1, to: expectedDate) else {
                    break
                }
                expectedDate = previousDay
            } else {
                break
            }
        }

        return streakCount
    }

    var totalCompletions: Int {
        completions.count
    }

    var isCompletedToday: Bool {
        let today = Calendar.current.startOfDay(for: Date())
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: today) }
    }
}
