### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var icon: String
    var colorHex: String
    var createdAt: Date

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        icon: String = "checkmark.circle.fill",
        colorHex: String = "#4F46E5",
        createdAt: Date = .now
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.icon = icon
        self.colorHex = colorHex
        self.createdAt = createdAt
    }

    var streak: Int {
        let sorted = completions.sorted { $0.date > $1.date }
        guard let latest = sorted.first else { return 0 }

        let calendar = Calendar.current
        var currentDate = calendar.startOfDay(for: latest.date)
        var streakCount = 0

        let uniqueDays = Set(sorted.map { calendar.startOfDay(for: $0.date) })

        while uniqueDays.contains(currentDate) {
            streakCount += 1
            guard let previousDay = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
            currentDate = previousDay
        }

        return streakCount
    }

    func completed(on date: Date = .now) -> Bool {
        let calendar = Calendar.current
        let day = calendar.startOfDay(for: date)
        return completions.contains { calendar.startOfDay(for: $0.date) == day }
    }
}
