## 3) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(name: String, habitDescription: String = "", colorHex: String = "#4F46E5") {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
    }

    var streakCount: Int {
        let sortedDates = completions
            .map { Calendar.current.startOfDay(for: $0.date) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 1
        var currentDate = sortedDates[0]

        for date in sortedDates.dropFirst() {
            if let expected = Calendar.current.date(byAdding: .day, value: -1, to: currentDate),
               Calendar.current.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else if !Calendar.current.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let day = Calendar.current.startOfDay(for: date)
        return completions.contains { Calendar.current.isDate($0.date, inSameDayAs: day) }
    }
}
