## 2) Habit Model

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        colorHex: String = "#4F46E5",
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.completedDates = completedDates
    }

    var isCompletedToday: Bool {
        completedDates.contains(where: { Calendar.current.isDateInToday($0) })
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates.sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 1
        var currentDate = calendar.startOfDay(for: first)

        for date in sortedDates.dropFirst() {
            let nextDate = calendar.startOfDay(for: date)
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(nextDate, inSameDayAs: expected) {
                streakCount += 1
                currentDate = nextDate
            } else if calendar.isDate(nextDate, inSameDayAs: currentDate) {
                continue
            } else {
                break
            }
        }

        return streakCount
    }

    mutating func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let index = completedDates.firstIndex(where: { Calendar.current.isDateInToday($0) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }
}
```

