## 7) Better Streak Logic (Optional Improvement)

The streak logic above is simple. For a more accurate streak, use consecutive days ending today or yesterday:

```swift
extension Habit {
    var currentStreak: Int {
        let calendar = Calendar.current
        let uniqueDays = Set(completedDates.map { calendar.startOfDay(for: $0) }).sorted(by: >)

        guard !uniqueDays.isEmpty else { return 0 }

        var streak = 0
        var expectedDay = calendar.startOfDay(for: Date())

        if !uniqueDays.contains(expectedDay) {
            guard let yesterday = calendar.date(byAdding: .day, value: -1, to: expectedDay) else { return 0 }
            expectedDay = yesterday
        }

        for day in uniqueDays {
            if calendar.isDate(day, inSameDayAs: expectedDay) {
                streak += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: expectedDay) else { break }
                expectedDay = previous
            } else if day < expectedDay {
                continue
            } else {
                break
            }
        }

        return streak
    }
}
```

