## 3) `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetCountPerDay: Int
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        colorHex: String = "#4F46E5",
        targetCountPerDay: Int = 1,
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.targetCountPerDay = targetCountPerDay
        self.completedDates = completedDates
    }

    var completionsCount: Int {
        completedDates.count
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDay = first

        for date in sortedDates.dropFirst() {
            guard let expected = calendar.date(byAdding: .day, value: -1, to: currentDay) else { break }
            if calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDay = date
            } else if !calendar.isDate(date, inSameDayAs: currentDay) {
                break
            }
        }

        return streak
    }

    var isCompletedToday: Bool {
        let calendar = Calendar.current
        return completedDates.contains { calendar.isDateInToday($0) }
    }

    func markCompletedToday() {
        let calendar = Calendar.current
        if !completedDates.contains(where: { calendar.isDateInToday($0) }) {
            completedDates.append(.now)
        }
    }

    func removeCompletionToday() {
        let calendar = Calendar.current
        completedDates.removeAll { calendar.isDateInToday($0) }
    }
}
```

