## 2) Data Model

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String, habitDescription: String = "") {
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.completedDates = []
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates.sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var currentDate = calendar.startOfDay(for: Date())

        for date in sortedDates {
            let day = calendar.startOfDay(for: date)
            if calendar.isDate(day, inSameDayAs: currentDate) {
                streak += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
            } else if day == currentDate {
                streak += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
            } else if day < currentDate {
                let diff = calendar.dateComponents([.day], from: day, to: currentDate).day ?? 0
                if diff == 0 {
                    streak += 1
                    currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
                } else if diff == 1 {
                    streak += 1
                    currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
                } else {
                    break
                }
            }
        }

        return streak
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())
        return completedDates.contains { calendar.isDate($0, inSameDayAs: today) }
    }

    func toggleCompletionToday() {
        let calendar = Calendar.current
        let today = calendar.startOfDay(for: Date())

        if let index = completedDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: today) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }
}
```

