```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var emoji: String
    var createdAt: Date
    var colorHex: String
    var completedDates: [Date]

    init(
        name: String,
        emoji: String = "✅",
        colorHex: String = "#4F46E5"
    ) {
        self.id = UUID()
        self.name = name
        self.emoji = emoji
        self.createdAt = Date()
        self.colorHex = colorHex
        self.completedDates = []
    }

    var isCompletedToday: Bool {
        completedDates.contains(where: { Calendar.current.isDateInToday($0) })
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streakCount += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streakCount
    }

    func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let index = completedDates.firstIndex(where: {
            Calendar.current.isDateInToday($0)
        }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }
}
```

