## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var targetDaysPerWeek: Int
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \HabitLog.habit)
    var logs: [HabitLog] = []

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        targetDaysPerWeek: Int = 7,
        colorHex: String = "#4F46E5"
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.targetDaysPerWeek = targetDaysPerWeek
        self.colorHex = colorHex
    }

    var completedToday: Bool {
        logs.contains { Calendar.current.isDateInToday($0.date) }
    }

    var currentStreak: Int {
        let sortedDates = logs.map(\.date).sorted(by: >)
        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = Calendar.current.startOfDay(for: Date())

        for date in sortedDates {
            let day = Calendar.current.startOfDay(for: date)
            if Calendar.current.isDate(day, inSameDayAs: expectedDate) {
                streak += 1
                expectedDate = Calendar.current.date(byAdding: .day, value: -1, to: expectedDate) ?? expectedDate
            } else if day < expectedDate {
                break
            }
        }

        return streak
    }

    var totalCompletions: Int {
        logs.count
    }
}
```

