import SwiftUI
import SwiftData

struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @Bindable var habit: Habit

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit") {
                    Text(habit.name)
                    if !habit.habitDescription.isEmpty {
                        Text(habit.habitDescription)
                    }
                }

                Section("Progress") {
                    LabeledContent("Current Streak", value: "\(habit.currentStreak) days")
                    LabeledContent("Total Completions", value: "\(habit.totalCompletions)")
                    LabeledContent("Target Days / Week", value: "\(habit.targetDaysPerWeek)")
                }

                Section("Completions") {
                    if habit.logs.isEmpty {
                        Text("No completions yet.")
                            .foregroundStyle(.secondary)
                    } else {
                        ForEach(habit.logs.sorted(by: { $0.date > $1.date })) { log in
                            Text(log.date.shortFormatted)
                        }
                    }
                }

                Section {
                    Button {
                        toggleCompletionForToday()
                    } label: {
                        Text(habit.completedToday ? "Mark as Not Done Today" : "Mark as Done Today")
                    }
                }
            }
            .navigationTitle("Habit Details")
            .toolbar {
                ToolbarItem(placement: .topBarTrailing) {
                    Button("Save") {
                        // SwiftData auto-saves changes in many cases, but explicit save is fine.
                        try? modelContext.save()
                    }
                }
            }
        }
    }

    private func toggleCompletionForToday() {
        if let existing = habit.logs.first(where: { Calendar.current.isDateInToday($0.date) }) {
            modelContext.delete(existing)
        } else {
            let log = HabitLog(date: Date(), habit: habit)
            modelContext.insert(log)
            habit.logs.append(log)
        }

        try? modelContext.save()
    }
}
