```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        colorHex: String = "#4F46E5",
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.completedDates = completedDates
    }

    var isCompletedToday: Bool {
        completedDates.contains { Calendar.current.isDateInToday($0) }
    }

    var currentStreak: Int {
        let sortedDates = completedDates
            .map { Calendar.current.startOfDay(for: $0) }
            .sorted(by: >)

        guard !sortedDates.isEmpty else { return 0 }

        var streak = 0
        var expectedDate = Calendar.current.startOfDay(for: Date())

        for date in sortedDates {
            if Calendar.current.isDate(date, inSameDayAs: expectedDate) {
                streak += 1
                expectedDate = Calendar.current.date(byAdding: .day, value: -1, to: expectedDate) ?? expectedDate
            } else if date < expectedDate {
                break
            }
        }

        return streak
    }

    func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let index = completedDates.firstIndex(where: { Calendar.current.isDateInToday($0) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }
}
