## 8) Add `Color` hex support

Create this in any shared file, e.g. `Utilities/Color+Hex.swift`

```swift
import SwiftUI

extension Color {
    init(hex: String) {
        let hex = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        var int: UInt64 = 0
        Scanner(string: hex).scanHexInt64(&int)

        let a, r, g, b: UInt64
        switch hex.count {
        case 6:
            a = 255
            r = (int >> 16) & 255
            g = (int >> 8) & 255
            b = int & 255
        case 8:
            a = (int >> 24) & 255
            r = (int >> 16) & 255
            g = (int >> 8) & 255
            b = int & 255
        default:
            a = 255
            r = 79
            g = 70
            b = 229
        }

        self.init(
            .sRGB,
            red: Double(r) / 255,
            green: Double(g) / 255,
            blue: Double(b) / 255,
            opacity: Double(a) / 255
        )
    }
}
```

