## 2) Models

### `Models/Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var isArchived: Bool

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        isArchived: Bool = false
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completions = []
    }

    var streakCount: Int {
        let sortedDates = completions
            .map { $0.completedAt.startOfDay }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = Calendar.current.date(byAdding: .day, value: -1, to: currentDate),
               date == expected {
                streak += 1
                currentDate = date
            } else if date == currentDate {
                continue
            } else {
                break
            }
        }

        return streak
    }

    func isCompleted(on date: Date = .now) -> Bool {
        let day = date.startOfDay
        return completions.contains { $0.completedAt.startOfDay == day }
    }
}
```

