import SwiftUI
import SwiftData

struct HabitListView: View {
    @Environment(\.modelContext) private var modelContext
    @Query(sort: \Habit.createdAt, order: .reverse) private var habits: [Habit]

    @State private var showingAddHabit = false
    @State private var habitToEdit: Habit?

    var activeHabits: [Habit] {
        habits.filter { !$0.isArchived }
    }

    var body: some View {
        List {
            if activeHabits.isEmpty {
                ContentUnavailableView(
                    "No Habits Yet",
                    systemImage: "checklist",
                    description: Text("Add your first habit to start tracking progress.")
                )
            } else {
                ForEach(activeHabits) { habit in
                    HabitRowView(
                        habit: habit,
                        onEdit: { habitToEdit = habit },
                        onToggleToday: { toggleToday(for: habit) }
                    )
                }
                .onDelete(perform: deleteHabits)
            }
        }
        .navigationTitle("Habits")
        .toolbar {
            ToolbarItem(placement: .topBarTrailing) {
                Button {
                    showingAddHabit = true
                } label: {
                    Image(systemName: "plus")
                }
            }
        }
        .sheet(isPresented: $showingAddHabit) {
            AddEditHabitView()
        }
        .sheet(item: $habitToEdit) { habit in
            AddEditHabitView(habit: habit)
        }
    }

    private func toggleToday(for habit: Habit) {
        let today = Date().startOfDay

        if let existing = habit.completions.first(where: { $0.completedAt.startOfDay == today }) {
            modelContext.delete(existing)
        } else {
            let completion = HabitCompletion(completedAt: .now, habit: habit)
            habit.completions.append(completion)
            modelContext.insert(completion)
        }
    }

    private func deleteHabits(at offsets: IndexSet) {
        for index in offsets {
            modelContext.delete(activeHabits[index])
        }
    }
}
