```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completedDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = Date(),
        completedDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    var isCompletedToday: Bool {
        completedDates.contains(where: { Calendar.current.isDateInToday($0) })
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates.sorted(by: >)

        var streak = 0
        var currentDate = Date()

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: currentDate) {
                streak += 1
                currentDate = calendar.date(byAdding: .day, value: -1, to: currentDate) ?? currentDate
            } else if calendar.isDate(date, inSameDayAs: currentDate) == false {
                break
            }
        }

        return streak
    }

    mutating func toggleCompletionForToday() {
        if let index = completedDates.firstIndex(where: { Calendar.current.isDateInToday($0) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(Date())
        }
    }
}
