import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var targetDaysPerWeek: Int
    var colorHex: String

    @Relationship(deleteRule: .cascade, inverse: \HabitCompletion.habit)
    var completions: [HabitCompletion] = []

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        targetDaysPerWeek: Int = 7,
        colorHex: String = "#4F46E5"
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.targetDaysPerWeek = targetDaysPerWeek
        self.colorHex = colorHex
    }

    var streakCount: Int {
        let sortedDates = completions
            .map { $0.completedAt.startOfDay }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = Calendar.current.date(byAdding: .day, value: -1, to: currentDate),
               date == expected {
                streak += 1
                currentDate = date
            } else if date == currentDate {
                continue
            } else {
                break
            }
        }

        return streak
