## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetDaysPerWeek: Int
    var completedDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7,
        completedDates: [Date] = []
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.targetDaysPerWeek = targetDaysPerWeek
        self.completedDates = completedDates
    }

    var isCompletedToday: Bool {
        completedDates.contains { Calendar.current.isDate($0, inSameDayAs: .now) }
    }

    var streak: Int {
        let sortedDates = completedDates
            .map { Calendar.current.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streakCount = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = Calendar.current.date(byAdding: .day, value: -1, to: currentDate),
               Calendar.current.isDate(date, inSameDayAs: expected) {
                streakCount += 1
                currentDate = date
            } else if !Calendar.current.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streakCount
    }

    func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: .now)

        if let index = completedDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(today)
        }
    }

    func completionCountThisWeek() -> Int {
        let calendar = Calendar.current
        let now = Date()
        guard let weekInterval = calendar.dateInterval(of: .weekOfYear, for: now) else { return 0 }

        return completedDates.filter { weekInterval.contains($0) }.count
    }
}
```

