## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetDaysPerWeek: Int

    // Stored as dates normalized to startOfDay
    @Attribute(.transformable)
    var completionDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetDaysPerWeek = targetDaysPerWeek
        self.completionDates = []
    }

    func isCompleted(on date: Date = Date) -> Bool {
        let day = date.startOfDay
        return completionDates.contains { $0.startOfDay == day }
    }

    func toggleCompletion(for date: Date = Date) {
        let day = date.startOfDay
        if let index = completionDates.firstIndex(where: { $0.startOfDay == day }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(day)
            completionDates.sort()
        }
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates.map { $0.startOfDay }.sorted(by: >)
        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            guard let expected = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
            if date == expected {
                streak += 1
                currentDate = date
            } else if date < expected {
                break
            }
        }

        return streak
    }
}
