## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var isArchived: Bool

    // Store completion dates as normalized start-of-day dates
    @Attribute(.transformable)
    var completionDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        isArchived: Bool = false,
        completionDates: [Date] = []
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.isArchived = isArchived
        self.completionDates = completionDates
    }

    var completedCount: Int {
        completionDates.count
    }

    var currentStreak: Int {
        let dates = Set(completionDates.map { $0.startOfDay })
        guard !dates.isEmpty else { return 0 }

        var streak = 0
        var day = Date().startOfDay

        while dates.contains(day) {
            streak += 1
            guard let previousDay = Calendar.current.date(byAdding: .day, value: -1, to: day) else { break }
            day = previousDay
        }

        return streak
    }

    var isCompletedToday: Bool {
        completionDates.contains(where: { Calendar.current.isDateInToday($0) })
    }

    mutating func toggleCompletionForToday() {
        let today = Date().startOfDay

        if let index = completionDates.firstIndex(where: { Calendar.current.isDate($0, inSameDayAs: today) }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
            completionDates.sort()
        }
    }
}
```

