## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var details: String
    var createdAt: Date
    var targetDaysPerWeek: Int
    var completedDates: [Date]

    init(
        name: String,
        details: String = "",
        createdAt: Date = .now,
        targetDaysPerWeek: Int = 7,
        completedDates: [Date] = []
    ) {
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.targetDaysPerWeek = targetDaysPerWeek
        self.completedDates = completedDates
    }

    var isCompletedToday: Bool {
        completedDates.contains(where: { Calendar.current.isDate($0, inSameDayAs: .now) })
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expectedPrevious = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expectedPrevious) {
                streak += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }

    func markCompletedToday() {
        guard !isCompletedToday else { return }
        completedDates.append(.now)
    }

    func unmarkCompletedToday() {
        completedDates.removeAll { Calendar.current.isDate($0, inSameDayAs: .now) }
    }
}
```

