struct HabitDetailView: View {
    @Environment(\.modelContext) private var modelContext
    @State private var showingEdit = false

    let habit: Habit

    var body: some View {
        Form {
            Section("Overview") {
                LabeledContent("Name", value: habit.name)
                if !habit.habitDescription.isEmpty {
                    LabeledContent("Description", value: habit.habitDescription)
                }
                LabeledContent("Created", value: habit.createdAt.formatted(date: .abbreviated, time: .omitted))
            }

            Section("Progress") {
                LabeledContent("Total Completions", value: "\(habit.totalCompletions)")
                LabeledContent("Current Streak", value: "\(habit.currentStreak)")
                LabeledContent("Longest Streak", value: "\(habit.longestStreak)")
                LabeledContent("Last Completed") {
                    Text(habit.lastCompletedAt?.formatted(date: .abbreviated, time: .omitted) ?? "Never")
                }
            }

            Section {
                Button {
                    markCompletedToday()
                } label: {
                    Label("Mark Completed Today", systemImage: "checkmark.circle.fill")
                }
                .buttonStyle(.borderedProminent)

                Button(role: .destructive) {
                    habit.isArchived.toggle()
                } label: {
                    Label(habit.isArchived ? "Unarchive" : "Archive", systemImage: "archivebox")
                }
            }
        }
        .navigationTitle("Habit")
        .toolbar {
            Button("Edit") {
                showingEdit = true
            }
        }
        .sheet(isPresented: $showingEdit) {
            AddEditHabitView(habit: habit)
        }
    }

    private func markCompletedToday() {
        let calendar = Calendar.current
        let now = Date()

        if let last = habit.lastCompletedAt {
            if calendar.isDate(last, inSameDayAs: now) {
                return
            }

            if let yesterday = calendar.date(byAdding: .day, value: -1, to: now),
               calendar.isDate(last, inSameDayAs: yesterday) {
                habit.currentStreak += 1
            } else {
                habit.currentStreak = 1
            }
        } else {
            habit.currentStreak = 1
        }

        habit.totalCompletions += 1
        habit.lastCompletedAt = now
        habit.longestStreak = max(habit.longestStreak, habit.currentStreak)
    }
}
