## 2) `Models/Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var lastCompletedAt: Date?
    var completionDates: [Date]
    var targetPerDay: Int

    init(
        name: String,
        habitDescription: String = "",
        targetPerDay: Int = 1
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.lastCompletedAt = nil
        self.completionDates = []
        self.targetPerDay = targetPerDay
    }

    var isCompletedToday: Bool {
        completionDates.contains(where: { Calendar.current.isDateInToday($0) })
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 1
        var currentDate = first

        for date in sortedDates.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                streak += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return streak
    }

    func markCompleted() {
        let now = Date()
        if !completionDates.contains(where: { Calendar.current.isDateInToday($0) }) {
            completionDates.append(now)
            lastCompletedAt = now
        }
    }

    func unmarkCompletedToday() {
        completionDates.removeAll { Calendar.current.isDateInToday($0) }
        lastCompletedAt = completionDates.sorted().last
    }
}
