## 2) Data model

### `Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var details: String
    var createdAt: Date
    var colorHex: String
    var targetPerWeek: Int
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        details: String = "",
        createdAt: Date = Date(),
        colorHex: String = "#4F46E5",
        targetPerWeek: Int = 7,
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.details = details
        self.createdAt = createdAt
        self.colorHex = colorHex
        self.targetPerWeek = targetPerWeek
        self.completionDates = completionDates
    }

    var isCompletedToday: Bool {
        Calendar.current.isDate(completionDates.last, inSameDayAs: Date())
    }

    var currentStreak: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates.sorted(by: >)

        guard let first = sortedDates.first else { return 0 }

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for date in sortedDates {
            let day = calendar.startOfDay(for: date)
            if calendar.isDate(day, inSameDayAs: expectedDate) {
                streak += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expectedDate) ?? expectedDate
            } else if day < expectedDate {
                break
            }
        }

        return streak
    }

    func toggleCompletionForToday() {
        let today = Calendar.current.startOfDay(for: Date())

        if let index = completionDates.firstIndex(where: {
            Calendar.current.isDate($0, inSameDayAs: today)
        }) {
            completionDates.remove(at: index)
        } else {
            completionDates.append(today)
        }
    }
}
```

