## 2) Model

### `Models/Habit.swift`
```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var colorHex: String
    var targetDaysPerWeek: Int
    var completedDates: [Date]

    init(
        name: String,
        habitDescription: String = "",
        colorHex: String = "#4F46E5",
        targetDaysPerWeek: Int = 7,
        completedDates: [Date] = []
    ) {
        self.id = UUID()
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = Date()
        self.colorHex = colorHex
        self.targetDaysPerWeek = targetDaysPerWeek
        self.completedDates = completedDates
    }

    var streak: Int {
        let calendar = Calendar.current
        let sorted = completedDates
            .map { calendar.startOfDay(for: $0) }
            .sorted(by: >)

        guard let first = sorted.first else { return 0 }

        var currentStreak = 1
        var currentDate = first

        for date in sorted.dropFirst() {
            if let expected = calendar.date(byAdding: .day, value: -1, to: currentDate),
               calendar.isDate(date, inSameDayAs: expected) {
                currentStreak += 1
                currentDate = date
            } else if !calendar.isDate(date, inSameDayAs: currentDate) {
                break
            }
        }

        return currentStreak
    }

    var totalCompletions: Int {
        completedDates.count
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        let calendar = Calendar.current
        return completedDates.contains { calendar.isDate($0, inSameDayAs: date) }
    }

    func toggleCompletion(for date: Date = Date()) {
        let calendar = Calendar.current
        if let index = completedDates.firstIndex(where: { calendar.isDate($0, inSameDayAs: date) }) {
            completedDates.remove(at: index)
        } else {
            completedDates.append(date)
        }
    }
}
```

