        self.habit = habit
        _name = State(initialValue: habit?.name ?? "")
        _description = State(initialValue: habit?.habitDescription ?? "")
        _colorHex = State(initialValue: habit?.colorHex ?? "#4F46E5")
        _targetDaysPerWeek = State(initialValue: habit?.targetDaysPerWeek ?? 7)
    }

    var body: some View {
        NavigationStack {
            Form {
                Section("Habit") {
                    TextField("Name", text: $name)
                    TextField("Description", text: $description, axis: .vertical)
                        .lineLimit(3...6)
                }

                Section("Settings") {
                    TextField("Color Hex", text: $colorHex)
                    Stepper("Target Days Per Week: \(targetDaysPerWeek)", value: $targetDaysPerWeek, in: 1...7)
                }
            }
            .navigationTitle(habit == nil ? "New Habit" : "Edit Habit")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Cancel") { dismiss() }
                }

                ToolbarItem(placement: .confirmationAction) {
                    Button("Save") {
                        saveHabit()
                        dismiss()
                    }
                    .disabled(name.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
                }
            }
        }
    }

    private func saveHabit() {
        if let habit {
            habit.name = name
            habit.habitDescription = description
            habit.colorHex = colorHex
            habit.targetDaysPerWeek = targetDaysPerWeek
        } else {
            let newHabit = Habit(
                name: name,
                habitDescription: description,
                colorHex: colorHex,
                targetDaysPerWeek: targetDaysPerWeek
            )
            modelContext.insert(newHabit)
        }

        try? modelContext.save()
    }
}
