## 3) Model: `Habit.swift`

```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var id: UUID
    var name: String
    var habitDescription: String
    var createdAt: Date
    var completionDates: [Date]

    init(
        id: UUID = UUID(),
        name: String,
        habitDescription: String = "",
        createdAt: Date = .now,
        completionDates: [Date] = []
    ) {
        self.id = id
        self.name = name
        self.habitDescription = habitDescription
        self.createdAt = createdAt
        self.completionDates = completionDates
    }

    var isCompletedToday: Bool {
        completionDates.contains(where: { Calendar.current.isDateInToday($0) })
    }

    var streakCount: Int {
        let calendar = Calendar.current
        let sortedDates = completionDates.sorted(by: >)

        var streak = 0
        var expectedDate = calendar.startOfDay(for: Date())

        for date in sortedDates {
            let day = calendar.startOfDay(for: date)

            if day == expectedDate {
                streak += 1
                expectedDate = calendar.date(byAdding: .day, value: -1, to: expectedDate) ?? expectedDate
            } else if day < expectedDate {
                continue
            } else {
                break
            }
        }

        return streak
    }

    func markCompletedToday() {
        guard !isCompletedToday else { return }
        completionDates.append(Date())
    }

    func unmarkCompletedToday() {
        completionDates.removeAll { Calendar.current.isDateInToday($0) }
    }
}
