                LabeledContent("Streak", value: "\(habit.streakCount) days")
                LabeledContent("Completed today", value: habit.isCompletedToday ? "Yes" : "No")
                LabeledContent("Target", value: "\(habit.targetDaysPerWeek) days/week")
            }

            Section("Actions") {
                Button {
                    markCompletedToday()
                } label: {
                    Label("Mark Completed Today", systemImage: "checkmark.circle")
                }
                .disabled(habit.isCompletedToday)

                Button(role: .destructive) {
                    deleteLatestCompletionIfNeeded()
                } label: {
                    Label("Undo Today", systemImage: "arrow.uturn.backward")
                }
                .disabled(!habit.isCompletedToday)
            }

            Section("History") {
                if habit.completions.isEmpty {
                    Text("No completions yet.")
                        .foregroundStyle(.secondary)
                } else {
                    ForEach(habit.completions.sorted(by: { $0.completedAt > $1.completedAt })) { completion in
                        HStack {
                            Image(systemName: "checkmark.circle.fill")
                                .foregroundStyle(.green)
                            Text(completion.completedAt.formatted(date: .abbreviated, time: .shortened))
                        }
                    }
                }
            }
        }
        .navigationTitle("Habit")
        .navigationBarTitleDisplayMode(.inline)
    }

    private func markCompletedToday() {
        let completion = HabitCompletion(completedAt: Date(), habit: habit)
        modelContext.insert(completion)
        habit.completions.append(completion)
    }

    private func deleteLatestCompletionIfNeeded() {
        let today = Date().startOfDay
        if let completion = habit.completions.first(where: { $0.completedAt.startOfDay == today }) {
            modelContext.delete(completion)
            habit.completions.removeAll { $0.id == completion.id }
        }
    }
}
