### `Habit.swift`
```swift
import Foundation

struct Habit: Identifiable, Codable, Equatable {
    let id: UUID
    var name: String
    var completions: Set<String> // dates in "yyyy-MM-dd" format

    init(id: UUID = UUID(), name: String, completions: Set<String> = []) {
        self.id = id
        self.name = name
        self.completions = completions
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        completions.contains(Self.dateString(from: date))
    }

    mutating func toggleCompletion(for date: Date = Date()) {
        let key = Self.dateString(from: date)
        if completions.contains(key) {
            completions.remove(key)
        } else {
            completions.insert(key)
        }
    }

    var streak: Int {
        let calendar = Calendar.current
        var count = 0
        var currentDate = Date()

        while true {
            let key = Self.dateString(from: currentDate)
            if completions.contains(key) {
                count += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: currentDate) else { break }
                currentDate = previous
            } else {
                break
            }
        }

        return count
    }

    static func dateString(from date: Date) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone.current
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }
}
```

