```swift
import Foundation
import SwiftData

@Model
final class Habit {
    var name: String
    var createdAt: Date
    var completedDates: [Date]

    init(name: String, createdAt: Date = .now, completedDates: [Date] = []) {
        self.name = name
        self.createdAt = createdAt
        self.completedDates = completedDates
    }

    func isCompletedToday() -> Bool {
        let calendar = Calendar.current
        return completedDates.contains { calendar.isDate($0, inSameDayAs: Date()) }
    }

    func markCompletedToday() {
        guard !isCompletedToday() else { return }
        completedDates.append(Date())
    }

    var streak: Int {
        let calendar = Calendar.current
        let sortedDates = completedDates.sorted(by: >)

        var streakCount = 0
        var currentDay = Date()

        for date in sortedDates {
            if calendar.isDate(date, inSameDayAs: currentDay) {
                streakCount += 1
                currentDay = calendar.date(byAdding: .day, value: -1, to: currentDay) ?? currentDay
            } else if calendar.isDate(date, inSameDayAs: calendar.date(byAdding: .day, value: 0, to: currentDay) ?? currentDay) {
                continue
            } else {
                break
            }
        }

        return streakCount
    }
}
```

