### `Habit.swift`
```swift
import Foundation

struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var completions: Set<String> // dates stored as "yyyy-MM-dd"

    init(id: UUID = UUID(), name: String, completions: Set<String> = []) {
        self.id = id
        self.name = name
        self.completions = completions
    }

    func isCompleted(on date: Date = Date()) -> Bool {
        completions.contains(DateFormatter.dayString(from: date))
    }

    mutating func toggleCompletion(for date: Date = Date()) {
        let key = DateFormatter.dayString(from: date)
        if completions.contains(key) {
            completions.remove(key)
        } else {
            completions.insert(key)
        }
    }

    var streak: Int {
        // Minimal streak calculation: counts consecutive completed days ending today
        var count = 0
        var current = Date()
        let calendar = Calendar.current

        while true {
            let key = DateFormatter.dayString(from: current)
            if completions.contains(key) {
                count += 1
                guard let previous = calendar.date(byAdding: .day, value: -1, to: current) else { break }
                current = previous
            } else {
                break
            }
        }
        return count
    }
}

extension DateFormatter {
    static func dayString(from date: Date) -> String {
        let formatter = DateFormatter()
        formatter.calendar = Calendar.current
        formatter.locale = Locale(identifier: "en_US_POSIX")
        formatter.timeZone = TimeZone.current
        formatter.dateFormat = "yyyy-MM-dd"
        return formatter.string(from: date)
    }
}
```

