## 6) Repository

### `BankRepository.kt`
```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.local.SecureTokenStore
import com.example.bankapp.data.model.LoginRequest
import com.example.bankapp.data.remote.BankApi
import javax.inject.Inject

class BankRepository @Inject constructor(
    private val api: BankApi,
    private val tokenStore: SecureTokenStore
) {
    suspend fun login(username: String, password: String): Result<Unit> {
        return try {
            val response = api.login(LoginRequest(username, password))
            tokenStore.saveAccessToken(response.accessToken)
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getAccounts(): Result<Any> {
        return try {
            val token = tokenStore.getAccessToken() ?: return Result.failure(Exception("No token"))
            val accounts = api.getAccounts("Bearer $token")
            Result.success(accounts)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    suspend fun getTransactions(): Result<Any> {
        return try {
            val token = tokenStore.getAccessToken() ?: return Result.failure(Exception("No token"))
            val tx = api.getTransactions("Bearer $token")
            Result.success(tx)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    fun logout() {
        tokenStore.clear()
    }
}
```

