## 7) Repository

### `data/repository/BankRepository.kt`
```kotlin
package com.example.bankapp.data.repository

import com.example.bankapp.data.api.BankApi
import com.example.bankapp.data.model.Account
import com.example.bankapp.data.model.LoginRequest
import com.example.bankapp.data.model.Transaction
import com.example.bankapp.data.secure.SecureTokenStore
import javax.inject.Inject

class BankRepository @Inject constructor(
    private val api: BankApi,
    private val tokenStore: SecureTokenStore
) {
    suspend fun login(username: String, password: String): Boolean {
        val response = api.login(LoginRequest(username, password))
        tokenStore.saveAccessToken(response.accessToken)
        tokenStore.saveRefreshToken(response.refreshToken)
        return true
    }

    suspend fun getAccounts(): List<Account> = api.getAccounts()

    suspend fun getTransactions(accountId: String): List<Transaction> =
        api.getTransactions(accountId)

    fun isLoggedIn(): Boolean = !tokenStore.getAccessToken().isNullOrBlank()

    fun logout() = tokenStore.clear()
}
