import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import java.text.NumberFormat
import java.util.Locale

data class Transaction(
    val title: String,
    val amount: Double
)

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent {
            MaterialTheme {
                MiniBankApp()
            }
        }
    }
}

@Composable
fun MiniBankApp() {
    var balance by remember { mutableStateOf(1250.00) }
    var amountText by remember { mutableStateOf("") }
    val transactions = remember { mutableStateListOf(
        Transaction("Initial balance", 1250.00)
    ) }

    val formatter = remember {
        NumberFormat.getCurrencyInstance(Locale.US)
    }

    fun addTransaction(title: String, amount: Double) {
        transactions.add(0, Transaction(title, amount))
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        Text(
            text = "MiniBank",
            style = MaterialTheme.typography.headlineMedium,
            fontWeight = FontWeight.Bold
        )

        Spacer(modifier = Modifier.height(16.dp))

        Card(modifier = Modifier.fillMaxWidth()) {
            Column(modifier = Modifier.padding(16.dp)) {
                Text("Current Balance", style = MaterialTheme.typography.titleMedium)
                Text(
                    text = formatter.format(balance),
                    style = MaterialTheme.typography.headlineMedium,
                    fontWeight = FontWeight.Bold
                )
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        OutlinedTextField(
            value = amountText,
            onValueChange = { amountText = it },
            label = { Text("Amount") },
            modifier = Modifier.fillMaxWidth()
        )

        Spacer(modifier = Modifier.height(12.dp))

        Row(modifier = Modifier.fillMaxWidth()) {
            Button(
                onClick = {
                    val amount = amountText.toDoubleOrNull()
                    if (amount != null && amount > 0) {
                        balance += amount
                        addTransaction("Deposit", amount)
                        amountText = ""
                    }
                },
                modifier = Modifier.weight(1f)
            ) {
                Text("Deposit")
            }

            Spacer(modifier = Modifier.width(12.dp))

            Button(
                onClick = {
                    val amount = amountText.toDoubleOrNull()
                    if (amount != null && amount > 0 && amount <= balance) {
                        balance -= amount
                        addTransaction("Withdrawal", -amount)
                        amountText = ""
                    }
                },
                modifier = Modifier.weight(1f)
            ) {
                Text("Withdraw")
            }
        }

        Spacer(modifier = Modifier.height(20.dp))

        Text(
            text = "Transactions",
            style = MaterialTheme.typography.titleLarge,
            fontWeight = FontWeight.Bold
        )

        Spacer(modifier = Modifier.height(8.dp))

        LazyColumn(
            modifier = Modifier.fillMaxSize(),
            verticalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            items(transactions) { tx ->
                Card(modifier = Modifier.fillMaxWidth()) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text(tx.title)
                        Text(
                            text = formatter.format(tx.amount),
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                }
            }
        }
    }
}
