## 4) `BankViewModel.kt`

```kotlin
package com.example.minibank

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableDoubleStateOf
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel

class BankViewModel : ViewModel() {
    var screen by mutableStateOf(Screen.Login)
        private set

    var balance by mutableDoubleStateOf(1250.00)
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction("Salary", "+$2,000.00"),
            Transaction("Coffee Shop", "-$4.50"),
            Transaction("Electric Bill", "-$120.00")
        )
    )
        private set

    fun login(username: String, password: String) {
        if (username == "user" && password == "pass") {
            screen = Screen.Home
        }
    }

    fun logout() {
        screen = Screen.Login
    }

    fun transfer(amount: Double, recipient: String) {
        if (amount <= balance) {
            balance -= amount
            transactions = listOf(
                Transaction("Transfer to $recipient", "-$%.2f".format(amount))
            ) + transactions
        }
    }
}
