```kotlin
package com.example.minibank

import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.items
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewmodel.compose.viewModel
import java.text.NumberFormat
import java.util.Locale

data class Transaction(
    val id: Long,
    val type: String,
    val amount: Double
)

class BankViewModel : ViewModel() {
    var balance by mutableStateOf(1000.0)
        private set

    var transactions by mutableStateOf(
        listOf(
            Transaction(1, "Initial balance", 1000.0)
        )
    )
        private set

    fun deposit(amount: Double) {
        if (amount <= 0) return
        balance += amount
        transactions = listOf(
            Transaction(System.currentTimeMillis(), "Deposit", amount)
        ) + transactions
    }

    fun withdraw(amount: Double) {
        if (amount <= 0 || amount > balance) return
        balance -= amount
        transactions = listOf(
            Transaction(System.currentTimeMillis(), "Withdrawal", -amount)
        ) + transactions
    }
}

@Composable
fun BankApp(vm: BankViewModel = viewModel()) {
    var input by remember { mutableStateOf("") }

    val currency = remember {
        NumberFormat.getCurrencyInstance(Locale.US)
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        Text("Mini Bank", style = MaterialTheme.typography.headlineMedium)
        Spacer(modifier = Modifier.height(16.dp))

        Card(modifier = Modifier.fillMaxWidth()) {
            Column(modifier = Modifier.padding(16.dp)) {
                Text("Current Balance")
                Text(
                    text = currency.format(vm.balance),
                    style = MaterialTheme.typography.headlineLarge
                )
            }
        }

        Spacer(modifier = Modifier.height(16.dp))

        OutlinedTextField(
            value = input,
            onValueChange = { input = it },
            label = { Text("Amount") },
            modifier = Modifier.fillMaxWidth()
        )

        Spacer(modifier = Modifier.height(8.dp))

        Row(modifier = Modifier.fillMaxWidth()) {
            Button(
                onClick = {
                    input.toDoubleOrNull()?.let { vm.deposit(it) }
                    input = ""
                },
                modifier = Modifier.weight(1f)
            ) {
                Text("Deposit")
            }

            Spacer(modifier = Modifier.width(8.dp))

            Button(
                onClick = {
                    input.toDoubleOrNull()?.let { vm.withdraw(it) }
                    input = ""
                },
                modifier = Modifier.weight(1f)
            ) {
                Text("Withdraw")
            }
        }

        Spacer(modifier = Modifier.height(16.dp))
        Text("Transactions", style = MaterialTheme.typography.titleLarge)
        Spacer(modifier = Modifier.height(8.dp))

        LazyColumn(
            modifier = Modifier.fillMaxSize()
        ) {
            items(vm.transactions) { tx ->
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(vertical = 4.dp)
                ) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(16.dp),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text(tx.type)
                        Text(currency.format(tx.amount))
                    }
                }
            }
        }
    }
}
