@Composable
fun BankingHomeScreen(
    userName: String,
    onLogout: () -> Unit
) {
    var balance by remember { mutableStateOf(1250.00) }
    var recipient by remember { mutableStateOf("") }
    var amountText by remember { mutableStateOf("") }
    var transactions by remember {
        mutableStateOf(
            listOf(
                Transaction("Salary", 2000.00, "credit"),
                Transaction("Groceries", -120.50, "debit"),
                Transaction("Electricity Bill", -75.25, "debit")
            )
        )
    }
    var message by remember { mutableStateOf("") }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp)
    ) {
        Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
            Text("Welcome, $userName", style = MaterialTheme.typography.titleLarge)
            TextButton(onClick = onLogout) { Text("Logout") }
        }

        Spacer(Modifier.height(16.dp))

        Card(modifier = Modifier.fillMaxWidth()) {
            Column(Modifier.padding(16.dp)) {
                Text("Current Balance", style = MaterialTheme.typography.titleMedium)
                Text(
                    text = formatCurrency(balance),
                    style = MaterialTheme.typography.headlineMedium
                )
            }
        }

        Spacer(Modifier.height(16.dp))

        Card(modifier = Modifier.fillMaxWidth()) {
            Column(Modifier.padding(16.dp)) {
                Text("Transfer Money", style = MaterialTheme.typography.titleMedium)
                Spacer(Modifier.height(12.dp))

                OutlinedTextField(
                    value = recipient,
                    onValueChange = { recipient = it },
                    label = { Text("Recipient") },
                    modifier = Modifier.fillMaxWidth()
                )
                Spacer(Modifier.height(12.dp))

                OutlinedTextField(
                    value = amountText,
                    onValueChange = { amountText = it },
                    label = { Text("Amount") },
                    modifier = Modifier.fillMaxWidth()
                )
                Spacer(Modifier.height(12.dp))

                Button(
                    onClick = {
                        val amount = amountText.toDoubleOrNull()
                        if (recipient.isNotBlank() && amount != null && amount > 0 && balance >= amount) {
                            balance -= amount
                            transactions = listOf(
                                Transaction("Transfer to $recipient", -amount, "debit")
                            ) + transactions
                            message = "Transfer successful"
                            recipient = ""
                            amountText = ""
                        } else {
                            message = "Invalid transfer"
                        }
                    },
                    modifier = Modifier.fillMaxWidth()
                ) {
                    Text("Send")
                }

                if (message.isNotBlank()) {
                    Spacer(Modifier.height(8.dp))
                    Text(message)
                }
            }
        }

        Spacer(Modifier.height(16.dp))

        Text("Recent Transactions", style = MaterialTheme.typography.titleMedium)
        Spacer(Modifier.height(8.dp))

        LazyColumn(
            modifier = Modifier.fillMaxSize(),
            contentPadding = PaddingValues(bottom = 16.dp)
        ) {
            items(transactions) { tx ->
                TransactionRow(tx)
                Spacer(Modifier.height(8.dp))
            }
        }
    }
}

@Composable
fun TransactionRow(tx: Transaction) {
    Card(modifier = Modifier.fillMaxWidth()) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(16.dp),
            horizontalArrangement = Arrangement.SpaceBetween
        ) {
            Column {
                Text(tx.title, style = MaterialTheme.typography.bodyLarge)
                Text(tx.type)
            }
            Text(
                text = formatCurrency(tx.amount),
                color = if (tx.amount >= 0) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.error
            )
        }
    }
}

fun formatCurrency(value: Double): String {
    val formatter = NumberFormat.getCurrencyInstance(Locale.US)
    return formatter.format(value)
}
