```kotlin
package com.example.minibank

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import androidx.lifecycle.ViewModel
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

data class BankTransaction(
    val title: String,
    val amount: Double,
    val timestamp: String
)

class BankViewModel : ViewModel() {
    var isAuthenticated by mutableStateOf(false)
        private set

    var balance by mutableStateOf(1250.00)
        private set

    var transactions by mutableStateOf(
        listOf(
            BankTransaction("Salary", 2500.00, "2026-09-01 09:00"),
            BankTransaction("Rent", -900.00, "2026-09-03 12:30"),
            BankTransaction("Groceries", -350.00, "2026-09-05 18:15")
        )
    )
        private set

    fun login(pin: String): Boolean {
        // Demo-only PIN check
        return if (pin == "1234") {
            isAuthenticated = true
            true
        } else {
            false
        }
    }

    fun deposit(amount: Double) {
        if (amount <= 0) return
        balance += amount
        addTransaction("Deposit", amount)
    }

    fun withdraw(amount: Double): Boolean {
        if (amount <= 0 || amount > balance) return false
        balance -= amount
        addTransaction("Withdrawal", -amount)
        return true
    }

    private fun addTransaction(title: String, amount: Double) {
        val formatter = SimpleDateFormat("yyyy-MM-dd HH:mm", Locale.getDefault())
        val now = formatter.format(Date())
        transactions = listOf(
            BankTransaction(title, amount, now)
        ) + transactions
    }
}
