## 4) Local repository

This handles CRUD locally and adds operations to the sync queue.

```ts
// surveyRepository.ts
import { v4 as uuidv4 } from 'uuid';
import { getDb } from './db';

export type SurveyRecord = {
  id: string;
  siteId: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos: string[];
  updatedAt: string;
  deleted: boolean;
  version: number;
};

function nowIso() {
  return new Date().toISOString();
}

export async function createSurvey(input: Omit<SurveyRecord, 'id' | 'updatedAt' | 'deleted' | 'version'>) {
  const db = await getDb();
  const record: SurveyRecord = {
    id: uuidv4(),
    ...input,
    updatedAt: nowIso(),
    deleted: false,
    version: 1,
  };

  await db.executeSql(
    `INSERT INTO survey_records (id, siteId, latitude, longitude, notes, photos, updatedAt, deleted, version)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      record.id,
      record.siteId,
      record.latitude,
      record.longitude,
      record.notes,
      JSON.stringify(record.photos),
      record.updatedAt,
      0,
      record.version,
    ]
  );

  await enqueueOperation('create', record.id, record);
  return record;
}

export async function updateSurvey(id: string, patch: Partial<Omit<SurveyRecord, 'id'>>) {
  const db = await getDb();
  const current = await getSurveyById(id);
  if (!current) throw new Error('Survey not found');

  const updated: SurveyRecord = {
    ...current,
    ...patch,
    photos: patch.photos ?? current.photos,
    updatedAt: nowIso(),
    version: current.version + 1,
  };

  await db.executeSql(
    `UPDATE survey_records
     SET siteId = ?, latitude = ?, longitude = ?, notes = ?, photos = ?, updatedAt = ?, deleted = ?, version = ?
     WHERE id = ?`,
    [
      updated.siteId,
      updated.latitude,
      updated.longitude,
      updated.notes,
      JSON.stringify(updated.photos),
      updated.updatedAt,
      updated.deleted ? 1 : 0,
      updated.version,
      id,
    ]
  );

  await enqueueOperation('update', id, updated);
  return updated;
}

export async function deleteSurvey(id: string) {
  const db = await getDb();
  const current = await getSurveyById(id);
  if (!current) throw new Error('Survey not found');

  const updated: SurveyRecord = {
    ...current,
    deleted: true,
    updatedAt: nowIso(),
    version: current.version + 1,
  };

  await db.executeSql(
    `UPDATE survey_records SET deleted = 1, updatedAt = ?, version = ? WHERE id = ?`,
    [updated.updatedAt, updated.version, id]
  );

  await enqueueOperation('delete', id, updated);
  return updated;
}

export async function getSurveyById(id: string): Promise<SurveyRecord | null> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM survey_records WHERE id = ?`, [id]);
  if (result.rows.length === 0) return null;

  const row = result.rows.item(0);
  return {
    id: row.id,
    siteId: row.siteId,
    latitude: row.latitude,
    longitude: row.longitude,
    notes: row.notes ?? '',
    photos: row.photos ? JSON.parse(row.photos) : [],
    updatedAt: row.updatedAt,
    deleted: !!row.deleted,
    version: row.version,
  };
}

export async function listSurveys(): Promise<SurveyRecord[]> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM survey_records WHERE deleted = 0 ORDER BY updatedAt DESC`);
  const items: SurveyRecord[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    const row = result.rows.item(i);
    items.push({
      id: row.id,
      siteId: row.siteId,
      latitude: row.latitude,
      longitude: row.longitude,
      notes: row.notes ?? '',
      photos: row.photos ? JSON.parse(row.photos) : [],
      updatedAt: row.updatedAt,
      deleted: !!row.deleted,
      version: row.version,
    });
  }
  return items;
}

async function enqueueOperation(action: 'create' | 'update' | 'delete', entityId: string, payload: SurveyRecord) {
  const db = await getDb();
  await db.executeSql(
    `INSERT INTO sync_queue (id, entityType, entityId, action, payload, createdAt, retryCount)
     VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [uuidv4(), 'survey', entityId, action, JSON.stringify(payload), nowIso(), 0]
  );
}
