## 5) Sync service

This pushes queued changes to the server and pulls remote updates.

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import { getDb } from './db';

const API_BASE = 'https://your-api.example.com';

type QueueRow = {
  id: string;
  entityType: string;
  entityId: string;
  action: 'create' | 'update' | 'delete';
  payload: string;
  createdAt: string;
  retryCount: number;
};

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  const db = await getDb();

  // 1) Push local queue
  const [queueResult] = await db.executeSql(`SELECT * FROM sync_queue ORDER BY createdAt ASC`);
  for (let i = 0; i < queueResult.rows.length; i++) {
    const op: QueueRow = queueResult.rows.item(i);

    try {
      const payload = JSON.parse(op.payload);

      const res = await fetch(`${API_BASE}/sync/${op.entityType}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: op.action,
          entityId: op.entityId,
          payload,
        }),
      });

      if (!res.ok) {
        throw new Error(`Sync failed: ${res.status}`);
      }

      await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [op.id]);
    } catch (err) {
      await db.executeSql(
        `UPDATE sync_queue SET retryCount = retryCount + 1 WHERE id = ?`,
        [op.id]
      );
      // stop on first failure to avoid hammering server
      break;
    }
  }

  // 2) Pull remote changes since last sync
  const lastSync = await getSyncState('lastSyncAt');
  const pullRes = await fetch(`${API_BASE}/surveys/changes?since=${encodeURIComponent(lastSync ?? '')}`);
  if (pullRes.ok) {
    const data: { surveys: any[]; serverTime: string } = await pullRes.json();

    for (const remote of data.surveys) {
      await upsertRemoteSurvey(remote);
    }

    await setSyncState('lastSyncAt', data.serverTime);
  }
}

async function upsertRemoteSurvey(remote: any) {
  const db = await getDb();
  const [existingRes] = await db.executeSql(`SELECT version FROM survey_records WHERE id = ?`, [remote.id]);

  if (existingRes.rows.length === 0) {
    await db.executeSql(
      `INSERT INTO survey_records (id, siteId, latitude, longitude, notes, photos, updatedAt, deleted, version)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        remote.id,
        remote.siteId,
        remote.latitude,
        remote.longitude,
        remote.notes ?? '',
        JSON.stringify(remote.photos ?? []),
        remote.updatedAt,
        remote.deleted ? 1 : 0,
        remote.version ?? 1,
      ]
    );
    return;
  }

  const localVersion = existingRes.rows.item(0).version;
  if ((remote.version ?? 1) > localVersion) {
    await db.executeSql(
      `UPDATE survey_records
       SET siteId = ?, latitude = ?, longitude = ?, notes = ?, photos = ?, updatedAt = ?, deleted = ?, version = ?
       WHERE id = ?`,
      [
        remote.siteId,
        remote.latitude,
        remote.longitude,
        remote.notes ?? '',
        JSON.stringify(remote.photos ?? []),
        remote.updatedAt,
        remote.deleted ? 1 : 0,
        remote.version ?? 1,
        remote.id,
      ]
    );
  }
}

async function getSyncState(key: string): Promise<string | null> {
  const db = await getDb();
  const [res] = await db.executeSql(`SELECT value FROM sync_state WHERE key = ?`, [key]);
  if (res.rows.length === 0) return null;
  return res.rows.item(0).value;
}

async function setSyncState(key: string, value: string) {
  const db = await getDb();
  await db.executeSql(
    `INSERT INTO sync_state (key, value) VALUES (?, ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [key, value]
  );
}
```

