## 5) Local repository

### `surveyRepository.ts`
```ts
import { dbPromise } from './db';
import { Survey } from './types';
import { v4 as uuidv4 } from 'uuid';

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await dbPromise;
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );

  const rows = result.rows;
  const surveys: Survey[] = [];
  for (let i = 0; i < rows.length; i++) {
    surveys.push(rows.item(i));
  }
  return surveys;
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = await dbPromise;
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE id = ? LIMIT 1`,
    [id]
  );

  if (result.rows.length === 0) return null;
  return result.rows.item(0);
}

async function addToOutbox(
  entityType: 'survey',
  entityId: string,
  operation: 'create' | 'update' | 'delete',
  payload: any
) {
  const db = await dbPromise;
  await db.executeSql(
    `INSERT INTO outbox (id, entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [
      uuidv4(),
      entityType,
      entityId,
      operation,
      JSON.stringify(payload),
      new Date().toISOString(),
    ]
  );
}

export async function createSurvey(input: {
  name: string;
  latitude: number;
  longitude: number;
  notes?: string | null;
}) {
  const db = await dbPromise;
  const id = uuidv4();
  const now = new Date().toISOString();

  await db.executeSql(
    `INSERT INTO surveys (id, name, latitude, longitude, notes, updatedAt, deletedAt, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, NULL, 'pending')`,
    [id, input.name, input.latitude, input.longitude, input.notes ?? null, now]
  );

  await addToOutbox('survey', id, 'create', { id, ...input, updatedAt: now });

  return getSurveyById(id);
}

export async function updateSurvey(
  id: string,
  input: Partial<Pick<Survey, 'name' | 'latitude' | 'longitude' | 'notes'>>
) {
  const db = await dbPromise;
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const updated = {
    ...existing,
    ...input,
    updatedAt: new Date().toISOString(),
    syncStatus: 'pending' as const,
  };

  await db.executeSql(
    `UPDATE surveys
     SET name = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, syncStatus = 'pending'
     WHERE id = ?`,
    [
      updated.name,
      updated.latitude,
      updated.longitude,
      updated.notes ?? null,
      updated.updatedAt,
      id,
    ]
  );

  await addToOutbox('survey', id, 'update', updated);

  return getSurveyById(id);
}

export async function deleteSurvey(id: string) {
  const db = await dbPromise;
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();

  await db.executeSql(
    `UPDATE surveys
     SET deletedAt = ?, updatedAt = ?, syncStatus = 'pending'
     WHERE id = ?`,
    [now, now, id]
  );

  await addToOutbox('survey', id, 'delete', { id, deletedAt: now });

  return true;
}
```

