import { Survey } from './types';

const API_BASE = 'https://your-api.example.com';

export async function pushChanges(changes: any[]) {
  const res = await fetch(`${API_BASE}/sync/push`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ changes }),
  });

  if (!res.ok) {
    throw new Error(`Push failed: ${res.status}`);
  }

  return res.json();
}

export async function pullChanges(since: string): Promise<{ surveys: Survey[]; serverTime: string }> {
  const res = await fetch(`${API_BASE}/sync/pull?since=${encodeURIComponent(since)}`);

  if (!res.ok) {
    throw new Error(`Pull failed: ${res.status}`);
  }

  return res.json();
}
