## 7) Sync engine

### `syncService.ts`
```ts
import NetInfo from '@react-native-community/netinfo';
import { dbPromise } from './db';
import { pushChanges, pullChanges } from './syncApi';
import { Survey } from './types';

async function getOutboxItems() {
  const db = await dbPromise;
  const [result] = await db.executeSql(`SELECT * FROM outbox ORDER BY createdAt ASC`);
  const items: any[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

async function clearOutboxItem(id: string) {
  const db = await dbPromise;
  await db.executeSql(`DELETE FROM outbox WHERE id = ?`, [id]);
}

async function getSyncMeta(key: string): Promise<string | null> {
  const db = await dbPromise;
  const [result] = await db.executeSql(`SELECT value FROM sync_meta WHERE key = ?`, [key]);
  if (result.rows.length === 0) return null;
  return result.rows.item(0).value;
}

async function setSyncMeta(key: string, value: string) {
  const db = await dbPromise;
  await db.executeSql(
    `INSERT INTO sync_meta (key, value) VALUES (?, ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [key, value]
  );
}

async function applyServerSurvey(s: Survey) {
  const db = await dbPromise;
  const [existingResult] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [s.id]);

  if (existingResult.rows.length === 0) {
    await db.executeSql(
      `INSERT INTO surveys (id, name, latitude, longitude, notes, updatedAt, deletedAt, syncStatus)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'synced')`,
      [s.id, s.name, s.latitude, s.longitude, s.notes ?? null, s.updatedAt, s.deletedAt ?? null]
    );
    return;
  }

  const local = existingResult.rows.item(0);

  // Last-write-wins
  if (new Date(s.updatedAt).getTime() >= new Date(local.updatedAt).getTime()) {
    await db.executeSql(
      `UPDATE surveys
       SET name = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, deletedAt = ?, syncStatus = 'synced'
       WHERE id = ?`,
      [s.name, s.latitude, s.longitude, s.notes ?? null, s.updatedAt, s.deletedAt ?? null, s.id]
    );
  }
}

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return { ok: false, reason: 'offline' };

  const outbox = await getOutboxItems();
  const lastSync = (await getSyncMeta('lastSync')) ?? '1970-01-01T00:00:00.000Z';

  // 1) Push local changes
  if (outbox.length > 0) {
    const changes = outbox.map((item) => ({
      id: item.entityId,
      entityType: item.entityType,
      operation: item.operation,
      payload: JSON.parse(item.payload),
      createdAt: item.createdAt,
    }));

    const pushResult = await pushChanges(changes);

    // Assume server returns acked IDs
    for (const ackedId of pushResult.ackedOutboxIds ?? []) {
      await clearOutboxItem(ackedId);
    }
  }

  // 2) Pull remote changes
  const pullResult = await pullChanges(lastSync);

  for (const survey of pullResult.surveys) {
    await applyServerSurvey(survey);
  }

  await setSyncMeta('lastSync', pullResult.serverTime ?? new Date().toISOString());

  return { ok: true };
}
```

