### `server.ts`
```ts
import express from 'express';

const app = express();
app.use(express.json());

let surveys: any[] = [];
let serverTime = new Date().toISOString();

app.post('/sync/push', (req, res) => {
  const { changes } = req.body;

  const ackedOutboxIds: string[] = [];

  for (const change of changes) {
    const { id, operation, payload, createdAt } = change;

    if (operation === 'create') {
      const existing = surveys.find((s) => s.id === id);
      if (!existing) {
        surveys.push({ ...payload, deletedAt: null });
      }
    }

    if (operation === 'update') {
      const idx = surveys.findIndex((s) => s.id === id);
      if (idx >= 0) {
        if (new Date(payload.updatedAt).getTime() >= new Date(surveys[idx].updatedAt).getTime()) {
          surveys[idx] = { ...surveys[idx], ...payload };
        }
      }
    }

    if (operation === 'delete') {
      const idx = surveys.findIndex((s) => s.id === id);
      if (idx >= 0) {
        surveys[idx].deletedAt = payload.deletedAt ?? createdAt;
        surveys[idx].updatedAt = payload.deletedAt ?? createdAt;
      }
    }

    ackedOutboxIds.push(change.id);
  }

  serverTime = new Date().toISOString();
  res.json({ ok: true, ackedOutboxIds, serverTime });
});

app.get('/sync/pull', (req, res) => {
  const since = String(req.query.since || '1970-01-01T00:00:00.000Z');

  const changed = surveys.filter((s) => new Date(s.updatedAt).getTime() > new Date(since).getTime());

  res.json({
    surveys: changed,
    serverTime,
  });
});

app.listen(3000, () => console.log('Sync server running on :3000'));
```

