## 3.4 Local repository

**`src/repository.ts`**

```ts
import { v4 as uuidv4 } from 'uuid';
import { getDb } from './db';
import { SurveyRecord, PendingMutation } from './types';

export async function getAllLocalRecords(): Promise<SurveyRecord[]> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM survey_records WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );

  const records: SurveyRecord[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    records.push(result.rows.item(i));
  }
  return records;
}

export async function upsertLocalRecord(record: SurveyRecord) {
  const db = await getDb();
  await db.executeSql(
    `INSERT OR REPLACE INTO survey_records
     (id, siteName, latitude, longitude, notes, status, version, updatedAt, deletedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      record.id,
      record.siteName,
      record.latitude,
      record.longitude,
      record.notes,
      record.status,
      record.version,
      record.updatedAt,
      record.deletedAt ?? null,
    ]
  );
}

export async function createSurveyRecord(input: Omit<SurveyRecord, 'id' | 'version' | 'updatedAt' | 'deletedAt'>) {
  const now = new Date().toISOString();
  const record: SurveyRecord = {
    id: uuidv4(),
    ...input,
    version: 1,
    updatedAt: now,
    deletedAt: null,
  };

  await upsertLocalRecord(record);

  const mutation: PendingMutation = {
    id: uuidv4(),
    entityId: record.id,
    type: 'create',
    payload: JSON.stringify(record),
    createdAt: now,
  };

  await enqueueMutation(mutation);
  return record;
}

export async function updateSurveyRecord(id: string, patch: Partial<Omit<SurveyRecord, 'id'>>) {
  const db = await getDb();
  const [existingResult] = await db.executeSql(`SELECT * FROM survey_records WHERE id = ?`, [id]);

  if (existingResult.rows.length === 0) throw new Error('Record not found');

  const existing = existingResult.rows.item(0) as SurveyRecord;
  const updated: SurveyRecord = {
    ...existing,
    ...patch,
    version: existing.version + 1,
    updatedAt: new Date().toISOString(),
  };

  await upsertLocalRecord(updated);

  const mutation: PendingMutation = {
    id: uuidv4(),
    entityId: id,
    type: 'update',
    payload: JSON.stringify(patch),
    createdAt: updated.updatedAt,
  };

  await enqueueMutation(mutation);
  return updated;
}

export async function deleteSurveyRecord(id: string) {
  const db = await getDb();
  const [existingResult] = await db.executeSql(`SELECT * FROM survey_records WHERE id = ?`, [id]);

  if (existingResult.rows.length === 0) throw new Error('Record not found');

  const existing = existingResult.rows.item(0) as SurveyRecord;
  const deleted: SurveyRecord = {
    ...existing,
    deletedAt: new Date().toISOString(),
    version: existing.version + 1,
    updatedAt: new Date().toISOString(),
  };

  await upsertLocalRecord(deleted);

  const mutation: PendingMutation = {
    id: uuidv4(),
    entityId: id,
    type: 'delete',
    payload: JSON.stringify({ deletedAt: deleted.deletedAt }),
    createdAt: deleted.updatedAt,
  };

  await enqueueMutation(mutation);
}

export async function enqueueMutation(mutation: PendingMutation) {
  const db = await getDb();
  await db.executeSql(
    `INSERT INTO pending_mutations (id, entityId, type, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [mutation.id, mutation.entityId, mutation.type, mutation.payload, mutation.createdAt]
  );
}

export async function getPendingMutations(): Promise<PendingMutation[]> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM pending_mutations ORDER BY createdAt ASC`
  );

  const mutations: PendingMutation[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    mutations.push(result.rows.item(i));
  }
  return mutations;
}

export async function clearPendingMutations(ids: string[]) {
  const db = await getDb();
  for (const id of ids) {
    await db.executeSql(`DELETE FROM pending_mutations WHERE id = ?`, [id]);
  }
}
```

