## 3.5 Sync service

**`src/sync.ts`**

```ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingMutations, clearPendingMutations, upsertLocalRecord } from './repository';
import { getDb, getSyncCursor, setSyncCursor } from './db';
import { SyncResponse, SurveyRecord } from './types';

const API_URL = 'https://your-api.example.com';

async function postSync() {
  const mutations = await getPendingMutations();
  const lastSyncAt = await getSyncCursor();

  if (mutations.length === 0 && !lastSyncAt) return;

  const response = await fetch(`${API_URL}/sync`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      mutations,
      lastSyncAt,
    }),
  });

  if (!response.ok) {
    throw new Error(`Sync failed: ${response.status}`);
  }

  const data = (await response.json()) as SyncResponse;

  // Apply server changes locally
  for (const record of data.changes) {
    await upsertLocalRecord(record);
  }

  // Clear successfully applied mutations
  const appliedIds = data.applied.filter(a => a.success).map(a => a.mutationId);
  await clearPendingMutations(appliedIds);

  await setSyncCursor(data.serverTime);
}

export async function syncIfOnline() {
  const state = await NetInfo.fetch();
  if (!state.isConnected || !state.isInternetReachable) return;

  try {
    await postSync();
  } catch (err) {
    console.warn('Sync error:', err);
  }
}
```

