## 4.2 Express sync API

**`server/index.ts`**

```ts
import express from 'express';
import cors from 'cors';
import { v4 as uuidv4 } from 'uuid';

const app = express();
app.use(cors());
app.use(express.json());

type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  status: 'draft' | 'submitted';
  version: number;
  updatedAt: string;
  deletedAt?: string | null;
};

type PendingMutation = {
  id: string;
  entityId: string;
  type: 'create' | 'update' | 'delete';
  payload: string;
  createdAt: string;
};

const records = new Map<string, SurveyRecord>();

app.post('/sync', (req, res) => {
  const { mutations, lastSyncAt } = req.body as {
    mutations: PendingMutation[];
    lastSyncAt: string | null;
  };

  const applied: { mutationId: string; entityId: string; success: boolean; reason?: string }[] = [];

  for (const mutation of mutations || []) {
    try {
      const payload = JSON.parse(mutation.payload);

      if (mutation.type === 'create') {
        const record = payload as SurveyRecord;
        const existing = records.get(record.id);

        if (existing && existing.updatedAt > record.updatedAt) {
          applied.push({
            mutationId: mutation.id,
            entityId: mutation.entityId,
            success: false,
            reason: 'Conflict: server has newer record',
          });
          continue;
        }

        records.set(record.id, record);
        applied.push({ mutationId: mutation.id, entityId: mutation.entityId, success: true });
      }

      if (mutation.type === 'update') {
        const existing = records.get(mutation.entityId);
        if (!existing) {
          applied.push({
            mutationId: mutation.id,
            entityId: mutation.entityId,
            success: false,
            reason: 'Record not found on server',
          });
          continue;
        }

        const updated: SurveyRecord = {
          ...existing,
          ...payload,
          version: existing.version + 1,
          updatedAt: new Date().toISOString(),
        };

        records.set(updated.id, updated);
        applied.push({ mutationId: mutation.id, entityId: mutation.entityId, success: true });
      }

      if (mutation.type === 'delete') {
        const existing = records.get(mutation.entityId);
        if (!existing) {
          applied.push({
            mutationId: mutation.id,
            entityId: mutation.entityId,
            success: false,
            reason: 'Record not found on server',
          });
          continue;
        }

        const deleted: SurveyRecord = {
          ...existing,
          deletedAt: new Date().toISOString(),
          version: existing.version + 1,
          updatedAt: new Date().toISOString(),
        };

        records.set(deleted.id, deleted);
        applied.push({ mutationId: mutation.id, entityId: mutation.entityId, success: true });
      }
    } catch (err) {
      applied.push({
        mutationId: mutation.id,
        entityId: mutation.entityId,
        success: false,
        reason: 'Invalid payload',
      });
    }
  }

  const serverTime = new Date().toISOString();

  const changes = Array.from(records.values()).filter(record => {
    if (!lastSyncAt) return true;
    return record.updatedAt > lastSyncAt;
  });

  res.json({
    serverTime,
    applied,
    changes,
  });
});

app.get('/records', (_req, res) => {
  res.json(Array.from(records.values()));
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

