## 3) Local CRUD operations

### `surveyRepo.ts`

```ts
import * as SQLite from 'expo-sqlite';
import { v4 as uuidv4 } from 'uuid';

const db = SQLite.openDatabase('survey.db');

export type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  deleted: boolean;
  syncStatus: 'synced' | 'pending' | 'conflict';
};

function runSql(sql: string, params: any[] = []): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

function querySql<T>(sql: string, params: any[] = []): Promise<T[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        (_, result) => {
          const rows: T[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            rows.push(result.rows.item(i));
          }
          resolve(rows);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export async function getAllSurveys(): Promise<SurveyRecord[]> {
  return querySql<SurveyRecord>(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );
}

export async function getSurveyById(id: string): Promise<SurveyRecord | null> {
  const rows = await querySql<SurveyRecord>(
    `SELECT * FROM surveys WHERE id = ? LIMIT 1`,
    [id]
  );
  return rows[0] ?? null;
}

export async function saveSurvey(input: Omit<SurveyRecord, 'id' | 'updatedAt' | 'deleted' | 'syncStatus'> & { id?: string }): Promise<SurveyRecord> {
  const id = input.id ?? uuidv4();
  const updatedAt = new Date().toISOString();

  await runSql(
    `INSERT INTO surveys (id, siteName, latitude, longitude, notes, updatedAt, deleted, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, 0, 'pending')
     ON CONFLICT(id) DO UPDATE SET
       siteName=excluded.siteName,
       latitude=excluded.latitude,
       longitude=excluded.longitude,
       notes=excluded.notes,
       updatedAt=excluded.updatedAt,
       deleted=0,
       syncStatus='pending'`,
    [id, input.siteName, input.latitude, input.longitude, input.notes, updatedAt]
  );

  await runSql(
    `INSERT INTO sync_queue (entityId, action, payload, createdAt)
     VALUES (?, 'upsert', ?, ?)`,
    [
      id,
      JSON.stringify({
        id,
        siteName: input.siteName,
        latitude: input.latitude,
        longitude: input.longitude,
        notes: input.notes,
        updatedAt
      }),
      updatedAt
    ]
  );

  return {
    id,
    siteName: input.siteName,
    latitude: input.latitude,
    longitude: input.longitude,
    notes: input.notes,
    updatedAt,
    deleted: false,
    syncStatus: 'pending'
  };
}

export async function deleteSurvey(id: string): Promise<void> {
  const updatedAt = new Date().toISOString();

  await runSql(
    `UPDATE surveys SET deleted = 1, updatedAt = ?, syncStatus = 'pending' WHERE id = ?`,
    [updatedAt, id]
  );

  await runSql(
    `INSERT INTO sync_queue (entityId, action, payload, createdAt)
     VALUES (?, 'delete', ?, ?)`,
    [id, JSON.stringify({ id, updatedAt }), updatedAt]
  );
}
