## 4) Sync engine

This sync engine:
- checks if online
- sends queued changes to backend
- pulls remote changes since last sync
- updates local DB

### `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import * as SQLite from 'expo-sqlite';

const db = SQLite.openDatabase('survey.db');

const API_BASE = 'https://your-api.example.com';

type QueueItem = {
  id: number;
  entityId: string;
  action: 'upsert' | 'delete';
  payload: string;
  createdAt: string;
};

function runSql(sql: string, params: any[] = []): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

function querySql<T>(sql: string, params: any[] = []): Promise<T[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        sql,
        params,
        (_, result) => {
          const rows: T[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            rows.push(result.rows.item(i));
          }
          resolve(rows);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

async function isOnline(): Promise<boolean> {
  const state = await NetInfo.fetch();
  return !!state.isConnected && !!state.isInternetReachable;
}

async function getQueue(): Promise<QueueItem[]> {
  return querySql<QueueItem>(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );
}

async function clearQueueItem(id: number): Promise<void> {
  await runSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

async function getLastSyncAt(): Promise<string> {
  const rows = await querySql<{ value: string }>(
    `SELECT value FROM meta WHERE key = 'lastSyncAt' LIMIT 1`
  );
  return rows[0]?.value ?? '1970-01-01T00:00:00.000Z';
}

async function setLastSyncAt(value: string): Promise<void> {
  await runSql(
    `INSERT INTO meta (key, value) VALUES ('lastSyncAt', ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [value]
  );
}

export async function syncNow(): Promise<void> {
  if (!(await isOnline())) return;

  const queue = await getQueue();

  // Push local changes
  for (const item of queue) {
    const payload = JSON.parse(item.payload);

    const res = await fetch(`${API_BASE}/sync`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: item.action,
        record: payload
      })
    });

    if (!res.ok) {
      throw new Error(`Sync push failed for queue item ${item.id}`);
    }

    await clearQueueItem(item.id);
    await runSql(
      `UPDATE surveys SET syncStatus = 'synced' WHERE id = ?`,
      [item.entityId]
    );
  }

  // Pull remote changes
  const lastSyncAt = await getLastSyncAt();
  const pullRes = await fetch(`${API_BASE}/surveys/changes?since=${encodeURIComponent(lastSyncAt)}`);

  if (!pullRes.ok) {
    throw new Error('Failed to fetch remote changes');
  }

  const data: { records: any[]; serverTime: string } = await pullRes.json();

  for (const record of data.records) {
    await runSql(
      `INSERT INTO surveys (id, siteName, latitude, longitude, notes, updatedAt, deleted, syncStatus)
       VALUES (?, ?, ?, ?, ?, ?, ?, 'synced')
       ON CONFLICT(id) DO UPDATE SET
         siteName=excluded.siteName,
         latitude=excluded.latitude,
         longitude=excluded.longitude,
         notes=excluded.notes,
         updatedAt=excluded.updatedAt,
         deleted=excluded.deleted,
         syncStatus='synced'`,
      [
        record.id,
        record.siteName,
        record.latitude,
        record.longitude,
        record.notes,
        record.updatedAt,
        record.deleted ? 1 : 0
      ]
    );
  }

  await setLastSyncAt(data.serverTime);
}
```

