import React, { useEffect, useState } from 'react';
import { View, Text, Button, FlatList, TextInput } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { initDb } from './db';
import { getAllSurveys, saveSurvey, deleteSurvey, SurveyRecord } from './surveyRepo';
import { syncNow } from './syncService';

export default function App() {
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [online, setOnline] = useState(false);
  const [siteName, setSiteName] = useState('');
  const [notes, setNotes] = useState('');

  async function refresh() {
    setSurveys(await getAllSurveys());
  }

  useEffect(() => {
    (async () => {
      await initDb();
      await refresh();
    })();

    const unsub = NetInfo.addEventListener(state => {
      const connected = !!state.isConnected && !!state.isInternetReachable;
      setOnline(connected);
      if (connected) {
        syncNow()
          .then(refresh)
          .catch(console.error);
      }
    });

    return () => unsub();
  }, []);

  async function handleSave() {
    await saveSurvey({
      siteName,
      latitude: 40.7128,
      longitude: -74.006,
      notes
    });
    setSiteName('');
    setNotes('');
    await refresh();
  }

  async function handleSync() {
    await syncNow();
    await refresh();
  }

  return (
    <View style={{ padding: 20, marginTop: 50 }}>
      <Text>Offline-first Survey App</Text>
      <Text>Status: {online ? 'Online' : 'Offline'}</Text>

      <TextInput
