      <Button title="Sync Now" onPress={handleSync} />

      <FlatList
        data={surveys}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={{ paddingVertical: 12 }}>
            <Text>{item.siteName}</Text>
            <Text>{item.notes}</Text>
            <Text>{item.syncStatus}</Text>
            <Button title="Delete" onPress={() => deleteSurvey(item.id).then(refresh)} />
          </View>
        )}
      />
    </View>
  );
}
