const API_BASE = 'https://your-api.example.com';

export async function syncSurveyToServer(payload: any, action: 'create' | 'update' | 'delete') {
  const url = `${API_BASE}/surveys${action === 'delete' ? `/${payload.id}` : ''}`;

  const res = await fetch(url, {
    method: action === 'create' ? 'POST' : action === 'update' ? 'PUT' : 'DELETE',
    headers: {
      'Content-Type': 'application/json',
    },
    body: action === 'delete' ? undefined : JSON.stringify(payload),
  });

  if (!res.ok) {
    throw new Error(`Sync failed: ${res.status}`);
  }

  return res.json().catch(() => null);
}

export async function fetchServerSurveys(since?: string) {
  const url = since
    ? `${API_BASE}/surveys?since=${encodeURIComponent(since)}`
    : `${API_BASE}/surveys`;

  const res = await fetch(url);
  if (!res.ok) throw new Error('Failed to fetch surveys');
  return res.json();
}
