## 8) Sync engine

This is the core of offline-first behavior.

### `syncEngine.ts`
```ts
import { getQueueItems, removeQueueItem } from './syncQueue';
import { syncSurveyToServer, fetchServerSurveys } from './api';
import { upsertSurvey } from './surveyRepository';

export async function syncPendingChanges() {
  const queue = await getQueueItems();

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);
      await syncSurveyToServer(payload, item.action);
      await removeQueueItem(item.id);
    } catch (err) {
      console.warn('Failed to sync queue item', item.id, err);
      // keep item in queue for retry
      break;
    }
  }
}

export async function pullServerChanges(lastSyncAt?: string) {
  const remoteSurveys = await fetchServerSurveys(lastSyncAt);

  for (const s of remoteSurveys) {
    await upsertSurvey({
      id: s.id,
      siteName: s.siteName,
      latitude: s.latitude ?? null,
      longitude: s.longitude ?? null,
      notes: s.notes ?? '',
      updatedAt: s.updatedAt,
      deleted: s.deleted ? 1 : 0,
      syncStatus: 'synced',
    });
  }
}
```

