## `surveyRepository.ts`

```ts
import { v4 as uuidv4 } from 'uuid';
import { querySql, runSql } from './db';

export type Survey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  version: number;
  deleted: number;
};

type OperationType = 'create' | 'update' | 'delete';

export async function getAllSurveys(): Promise<Survey[]> {
  return querySql<Survey>(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const rows = await querySql<Survey>(`SELECT * FROM surveys WHERE id = ? LIMIT 1`, [id]);
  return rows[0] ?? null;
}

async function enqueueOperation(
  entityType: string,
  entityId: string,
  operation: OperationType,
  payload: any
) {
  await runSql(
    `INSERT INTO pending_operations (id, entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [
      uuidv4(),
      entityType,
      entityId,
      operation,
      JSON.stringify(payload),
      new Date().toISOString(),
    ]
  );
}

export async function createSurvey(input: {
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
}) {
  const id = uuidv4();
  const now = new Date().toISOString();

  await runSql(
    `INSERT INTO surveys (id, siteName, latitude, longitude, notes, updatedAt, version, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?, 0)`,
    [id, input.siteName, input.latitude, input.longitude, input.notes, now, 1]
  );

  await enqueueOperation('survey', id, 'create', {
    id,
    ...input,
    updatedAt: now,
    version: 1,
  });

  return id;
}

export async function updateSurvey(
  id: string,
  changes: Partial<Pick<Survey, 'siteName' | 'latitude' | 'longitude' | 'notes'>>
) {
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const nextVersion = existing.version + 1;

  await runSql(
    `UPDATE surveys
     SET siteName = COALESCE(?, siteName),
         latitude = COALESCE(?, latitude),
         longitude = COALESCE(?, longitude),
         notes = COALESCE(?, notes),
         updatedAt = ?,
         version = ?
     WHERE id = ?`,
    [
      changes.siteName ?? null,
      changes.latitude ?? null,
      changes.longitude ?? null,
      changes.notes ?? null,
      now,
      nextVersion,
      id,
    ]
  );

  await enqueueOperation('survey', id, 'update', {
    id,
    ...changes,
    updatedAt: now,
    version: nextVersion,
  });
}

export async function deleteSurvey(id: string) {
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const nextVersion = existing.version + 1;

  await runSql(
    `UPDATE surveys SET deleted = 1, updatedAt = ?, version = ? WHERE id = ?`,
    [now, nextVersion, id]
  );

  await enqueueOperation('survey', id, 'delete', {
    id,
    deleted: true,
    updatedAt: now,
    version: nextVersion,
  });
}
