# 4) Sync engine

This pushes local pending operations to the server, then pulls remote changes.

## `syncService.ts`

```ts
import { querySql, runSql } from './db';
import { isOnline } from './network';

type PendingOperation = {
  id: string;
  entityType: string;
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: string;
  createdAt: string;
};

const API_BASE = 'https://your-api.example.com';

async function getPendingOperations(): Promise<PendingOperation[]> {
  return querySql<PendingOperation>(
    `SELECT * FROM pending_operations ORDER BY createdAt ASC`
  );
}

async function removePendingOperation(id: string) {
  await runSql(`DELETE FROM pending_operations WHERE id = ?`, [id]);
}

async function getSyncToken(): Promise<string | null> {
  const rows = await querySql<{ value: string }>(
    `SELECT value FROM sync_state WHERE key = 'lastSyncToken' LIMIT 1`
  );
  return rows[0]?.value ?? null;
}

async function setSyncToken(token: string) {
  await runSql(
    `INSERT INTO sync_state (key, value)
     VALUES ('lastSyncToken', ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [token]
  );
}

export async function syncNow(): Promise<void> {
  if (!(await isOnline())) return;

  const pending = await getPendingOperations();
  const lastSyncToken = await getSyncToken();

  // 1) Push local changes
  for (const op of pending) {
    const payload = JSON.parse(op.payload);

    const response = await fetch(`${API_BASE}/sync/push`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        operation: op.operation,
        entityType: op.entityType,
        entityId: op.entityId,
        payload,
      }),
    });

    if (!response.ok) {
      // Stop on first failure so we can retry later
      throw new Error(`Push failed for ${op.id}`);
    }

    await removePendingOperation(op.id);
  }

  // 2) Pull remote changes
  const pullResponse = await fetch(
    `${API_BASE}/sync/pull?since=${encodeURIComponent(lastSyncToken ?? '')}`
  );

  if (!pullResponse.ok) {
    throw new Error('Pull failed');
  }

  const result: {
    changes: Array<{
      id: string;
      siteName: string;
      latitude: number;
      longitude: number;
      notes: string;
      updatedAt: string;
      version: number;
      deleted: number;
    }>;
    nextSyncToken: string;
  } = await pullResponse.json();

  // 3) Apply remote changes locally
  for (const survey of result.changes) {
    await runSql(
      `INSERT INTO surveys (id, siteName, latitude, longitude, notes, updatedAt, version, deleted)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         siteName = excluded.siteName,
         latitude = excluded.latitude,
         longitude = excluded.longitude,
         notes = excluded.notes,
         updatedAt = excluded.updatedAt,
         version = excluded.version,
         deleted = excluded.deleted`,
      [
        survey.id,
        survey.siteName,
        survey.latitude,
        survey.longitude,
        survey.notes,
        survey.updatedAt,
        survey.version,
        survey.deleted,
      ]
    );
  }

  await setSyncToken(result.nextSyncToken);
}
```

