# 7) Server API example

Here’s a minimal Node/Express backend to support sync.

## `server.ts`

```ts
import express from 'express';

const app = express();
app.use(express.json());

type Survey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  version: number;
  deleted: number;
};

const surveys = new Map<string, Survey>();
let syncCounter = 0;
const changeLog: { token: string; survey: Survey }[] = [];

function recordChange(survey: Survey) {
  const token = String(++syncCounter);
  changeLog.push({ token, survey });
}

app.post('/sync/push', (req, res) => {
  const { operation, payload } = req.body;

  const survey: Survey = payload;

  if (operation === 'delete') {
    const existing = surveys.get(survey.id);
    if (existing) {
      const updated = { ...existing, deleted: 1, updatedAt: survey.updatedAt, version: survey.version };
      surveys.set(survey.id, updated);
      recordChange(updated);
    }
    return res.json({ ok: true });
  }

  const existing = surveys.get(survey.id);
  if (!existing || survey.version >= existing.version) {
    surveys.set(survey.id, survey);
    recordChange(survey);
  }

  res.json({ ok: true });
});

app.get('/sync/pull', (req, res) => {
  const since = String(req.query.since ?? '');
  const changes = changeLog
    .filter(c => !since || Number(c.token) > Number(since))
    .map(c => c.survey);

  res.json({
    changes,
    nextSyncToken: String(syncCounter),
  });
});

app.listen(3000, () => {
  console.log('Sync server running on port 3000');
});
```

