# 3) Survey repository

## `surveyRepository.ts`

```ts
import { querySql, runSql } from './db';
import { v4 as uuidv4 } from 'uuid';

export type Survey = {
  id: string;
  serverId?: string | null;
  payload: any;
  status: 'pending' | 'synced' | 'error';
  updatedAt: number;
  deletedAt?: number | null;
  syncVersion: number;
};

export async function createSurvey(payload: any) {
  const id = uuidv4();
  const now = Date.now();

  await runSql(
    `INSERT INTO surveys (id, payload, status, updatedAt, syncVersion)
     VALUES (?, ?, ?, ?, ?)`,
    [id, JSON.stringify(payload), 'pending', now, 0]
  );

  await runSql(
    `INSERT INTO sync_queue (entityType, entityId, action, createdAt)
     VALUES (?, ?, ?, ?)`,
    ['survey', id, 'create', now]
  );

  return id;
}

export async function updateSurvey(id: string, payload: any) {
  const now = Date.now();

  await runSql(
    `UPDATE surveys
     SET payload = ?, status = ?, updatedAt = ?, syncVersion = syncVersion + 1
     WHERE id = ?`,
    [JSON.stringify(payload), 'pending', now, id]
  );

  await runSql(
    `INSERT INTO sync_queue (entityType, entityId, action, createdAt)
     VALUES (?, ?, ?, ?)`,
    ['survey', id, 'update', now]
  );
}

export async function deleteSurvey(id: string) {
  const now = Date.now();

  await runSql(
    `UPDATE surveys
     SET deletedAt = ?, status = ?, updatedAt = ?, syncVersion = syncVersion + 1
     WHERE id = ?`,
    [now, 'pending', now, id]
  );

  await runSql(
    `INSERT INTO sync_queue (entityType, entityId, action, createdAt)
     VALUES (?, ?, ?, ?)`,
    ['survey', id, 'delete', now]
  );
}

export async function getPendingSurveys(): Promise<Survey[]> {
  const rows = await querySql<any>(
    `SELECT * FROM surveys WHERE status != 'synced'`
  );

  return rows.map((r) => ({
    ...r,
    payload: JSON.parse(r.payload),
  }));
}

export async function getAllSurveys(): Promise<Survey[]> {
  const rows = await querySql<any>(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );

  return rows.map((r) => ({
    ...r,
    payload: JSON.parse(r.payload),
  }));
}

export async function markSurveySynced(id: string, serverId?: string) {
  await runSql(
    `UPDATE surveys
     SET status = 'synced', serverId = COALESCE(?, serverId)
     WHERE id = ?`,
    [serverId ?? null, id]
  );
}

export async function markSurveyError(id: string) {
  await runSql(
    `UPDATE surveys SET status = 'error' WHERE id = ?`,
    [id]
  );
}

export async function clearSyncQueueForEntity(entityId: string) {
  await runSql(
    `DELETE FROM sync_queue WHERE entityId = ?`,
    [entityId]
  );
}
