# 5) Sync service

This pushes local changes to the server and pulls remote updates.

## `syncService.ts`

```ts
import { getPendingSurveys, markSurveyError, markSurveySynced, clearSyncQueueForEntity } from './surveyRepository';
import { querySql, runSql } from './db';

const API_BASE = 'https://your-api.example.com';

async function pushSurvey(survey: any) {
  const response = await fetch(`${API_BASE}/surveys/sync`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      localId: survey.id,
      serverId: survey.serverId,
      payload: survey.payload,
      deletedAt: survey.deletedAt,
      syncVersion: survey.syncVersion,
      updatedAt: survey.updatedAt,
    }),
  });

  if (!response.ok) {
    throw new Error(`Failed to sync survey ${survey.id}`);
  }

  return response.json();
}

async function pullRemoteChanges(lastSyncAt: number) {
  const response = await fetch(`${API_BASE}/surveys/changes?since=${lastSyncAt}`);
  if (!response.ok) throw new Error('Failed to pull changes');

  return response.json();
}

export async function syncPendingData() {
  const now = Date.now();

  // Push local pending records
  const pending = await getPendingSurveys();

  for (const survey of pending) {
    try {
      const result = await pushSurvey(survey);

      await markSurveySynced(survey.id, result.serverId);
      await clearSyncQueueForEntity(survey.id);
    } catch (err) {
      console.error('Sync failed for survey', survey.id, err);
      await markSurveyError(survey.id);
    }
  }

  // Pull remote changes
  const lastSyncRows = await querySql<{ value: string }>(
    `SELECT value FROM meta WHERE key = 'lastSyncAt'`
  ).catch(() => []);

  const lastSyncAt = lastSyncRows.length ? Number(lastSyncRows[0].value) : 0;
  const remote = await pullRemoteChanges(lastSyncAt);

  for (const item of remote.surveys ?? []) {
    await runSql(
      `INSERT INTO surveys (id, serverId, payload, status, updatedAt, deletedAt, syncVersion)
       VALUES (?, ?, ?, 'synced', ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         serverId = excluded.serverId,
         payload = excluded.payload,
         status = 'synced',
         updatedAt = excluded.updatedAt,
         deletedAt = excluded.deletedAt,
         syncVersion = excluded.syncVersion`,
      [
        item.localId ?? item.id,
        item.serverId ?? null,
        JSON.stringify(item.payload),
        item.updatedAt ?? now,
        item.deletedAt ?? null,
        item.syncVersion ?? 0,
      ]
    );
  }

  await runSql(
    `CREATE TABLE IF NOT EXISTS meta (
      key TEXT PRIMARY KEY NOT NULL,
      value TEXT NOT NULL
    )`
  );

  await runSql(
    `INSERT INTO meta (key, value) VALUES ('lastSyncAt', ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [String(now)]
  );
}
```

