# 7) Example backend sync endpoint

Here’s a very simple Node/Express backend example.

## `server.js`

```js
const express = require('express');
const app = express();

app.use(express.json());

const surveys = new Map();
let changes = [];

app.post('/surveys/sync', (req, res) => {
  const { localId, serverId, payload, deletedAt, syncVersion, updatedAt } = req.body;

  const id = serverId || `srv_${localId}`;
  const existing = surveys.get(id);

  // Simple last-write-wins
  if (!existing || updatedAt >= existing.updatedAt) {
    surveys.set(id, {
      id,
      localId,
      payload,
      deletedAt,
      syncVersion,
      updatedAt,
    });

    changes.push({
      id,
      localId,
      payload,
      deletedAt,
      syncVersion,
      updatedAt,
    });
  }

  res.json({ serverId: id, ok: true });
});

app.get('/surveys/changes', (req, res) => {
  const since = Number(req.query.since || 0);
  const recent = changes.filter((c) => c.updatedAt > since);
  res.json({ surveys: recent });
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

