# 4) Sync queue helpers

```ts
// syncQueue.ts
import db from './db';

export const enqueueAction = (
  recordId: string,
  action: 'create' | 'update' | 'delete',
  payload: object
): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO sync_queue (recordId, action, payload, createdAt)
         VALUES (?, ?, ?, ?)`,
        [recordId, action, JSON.stringify(payload), new Date().toISOString()],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const getQueueItems = (): Promise<any[]> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM sync_queue ORDER BY id ASC`,
        [],
        (_, result) => resolve(result.rows._array),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};

export const clearQueueItem = (id: number): Promise<void> => {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `DELETE FROM sync_queue WHERE id = ?`,
        [id],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
};
```

