# 5) Sync service

This pushes queued changes to your backend when online.

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import { getQueueItems, clearQueueItem } from './syncQueue';
import { markSurveySynced } from './surveyRepo';

const API_URL = 'https://your-api.example.com';

export const isOnline = async (): Promise<boolean> => {
  const state = await NetInfo.fetch();
  return !!state.isConnected && !!state.isInternetReachable;
};

export const syncNow = async (): Promise<void> => {
  const online = await isOnline();
  if (!online) return;

  const queue = await getQueueItems();

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      let response: Response;

      if (item.action === 'create') {
        response = await fetch(`${API_URL}/surveys`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.action === 'update') {
        response = await fetch(`${API_URL}/surveys/${payload.remoteId}`, {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
      } else if (item.action === 'delete') {
        response = await fetch(`${API_URL}/surveys/${payload.remoteId}`, {
          method: 'DELETE',
        });
      } else {
        continue;
      }

      if (!response.ok) {
        throw new Error(`Sync failed for queue item ${item.id}`);
      }

      const data = item.action !== 'delete' ? await response.json() : null;

      if (item.action === 'create' && data?.id) {
        await markSurveySynced(item.recordId, data.id);
      }

      await clearQueueItem(item.id);
    } catch (err) {
      console.warn('Sync error:', err);
      // stop on first failure to retry later
      break;
    }
  }
};
```

