```ts
// App.tsx
import React, { useEffect, useState } from 'react';
import { View, Text, Button, FlatList, TextInput } from 'react-native';
import { v4 as uuidv4 } from 'uuid';
import NetInfo from '@react-native-community/netinfo';
import { initDb } from './db';
import { insertSurvey, getAllSurveys } from './surveyRepo';
import { enqueueAction } from './syncQueue';
import { syncNow } from './syncService';
import { SurveyRecord } from './types';

export default function App() {
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');
  const [online, setOnline] = useState(false);

  const loadSurveys = async () => {
    const data = await getAllSurveys();
    setSurveys(data);
  };

  useEffect(() => {
    initDb();
    loadSurveys();

    const unsubscribe = NetInfo.addEventListener(state => {
      const connected = !!state.isConnected && !!state.isInternetReachable;
      setOnline(connected);
      if (connected) {
        syncNow().then(loadSurveys);
      }
    });

    return () => unsubscribe();
  }, []);

  const addSurvey = async () => {
    const now = new Date().toISOString();
    const record: SurveyRecord = {
      id: uuidv4(),
      title,
      notes,
      latitude: 37.7749,
      longitude: -122.4194,
      createdAt: now,
      updatedAt: now,
      syncStatus: 'pending',
      deleted: 0,
    };

    await insertSurvey(record);
    await enqueueAction(record.id, 'create', record);
    setTitle('');
    setNotes('');
    await loadSurveys();

    if (online) {
      await syncNow();
      await loadSurveys();
    }
  };

  return (
    <View style={{ padding: 20, marginTop: 50 }}>
      <Text style={{ marginBottom: 10 }}>
        Status: {online ? 'Online' : 'Offline'}
      </Text>

      <TextInput
        placeholder="Survey title"
        value={title}
        onChangeText={setTitle}
        style={{ borderWidth: 1, marginBottom: 10, padding: 8 }}
      />
      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={{ borderWidth: 1, marginBottom: 10, padding: 8 }}
      />

      <Button title="Save Survey" onPress={addSurvey} />

      <Button title="Sync Now" onPress={syncNow} />

      <FlatList
        data={surveys}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={{ paddingVertical: 12, borderBottomWidth: 1 }}>
            <Text style={{ fontWeight: 'bold' }}>{item.title}</Text>
            <Text>{item.notes}</Text>
            <Text>Status: {item.syncStatus}</Text>
          </View>
        )}
      />
    </View>
  );
}
