# 5) Sync manager

This pushes queued changes to your backend API.

## `src/sync/syncManager.js`

```javascript
import NetInfo from '@react-native-community/netinfo';
import { runQuery } from '../db';

const API_URL = 'https://your-api.example.com';

const sendToServer = async (action, entityType, payload) => {
  const endpoint = `${API_URL}/sync`;

  const response = await fetch(endpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      action,
      entityType,
      payload,
    }),
  });

  if (!response.ok) {
    throw new Error(`Sync failed: ${response.status}`);
  }

  return response.json();
};

export const syncPendingChanges = async () => {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  const queueResult = await runQuery(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );

  const items = queueResult.rows._array;

  for (const item of items) {
    try {
      const payload = item.payload ? JSON.parse(item.payload) : null;

      await sendToServer(item.action, item.entityType, payload);

      await runQuery(`DELETE FROM sync_queue WHERE id = ?`, [item.id]);

      if (item.action === 'delete') {
        await runQuery(`DELETE FROM surveys WHERE id = ?`, [item.entityId]);
      } else {
        await runQuery(
          `UPDATE surveys SET synced = 1 WHERE id = ?`,
          [item.entityId]
        );
      }
    } catch (err) {
      console.warn('Sync error for item', item.id, err);
      break; // stop on first failure to preserve order
    }
  }
};
```

