# 3) Local repository

This layer handles all CRUD locally.

```ts
// surveyRepository.ts
import { getDb } from './db';
import { SurveyRecord } from './types';

const db = getDb();

export function insertSurvey(record: SurveyRecord): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `INSERT INTO surveys
         (id, serverId, title, notes, latitude, longitude, createdAt, updatedAt, syncStatus, deleted)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          record.id,
          record.serverId ?? null,
          record.title,
          record.notes,
          record.latitude,
          record.longitude,
          record.createdAt,
          record.updatedAt,
          record.syncStatus,
          record.deleted,
        ],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function updateSurvey(record: SurveyRecord): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET serverId = ?, title = ?, notes = ?, latitude = ?, longitude = ?,
             createdAt = ?, updatedAt = ?, syncStatus = ?, deleted = ?
         WHERE id = ?`,
        [
          record.serverId ?? null,
          record.title,
          record.notes,
          record.latitude,
          record.longitude,
          record.createdAt,
          record.updatedAt,
          record.syncStatus,
          record.deleted,
          record.id,
        ],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getPendingSurveys(): Promise<SurveyRecord[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE syncStatus = 'pending' OR syncStatus = 'failed'`,
        [],
        (_, result) => {
          const rows: SurveyRecord[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            rows.push(result.rows.item(i));
          }
          resolve(rows);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function getAllSurveys(): Promise<SurveyRecord[]> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`,
        [],
        (_, result) => {
          const rows: SurveyRecord[] = [];
          for (let i = 0; i < result.rows.length; i++) {
            rows.push(result.rows.item(i));
          }
          resolve(rows);
        },
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function markSynced(localId: string, serverId: string): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET serverId = ?, syncStatus = 'synced'
         WHERE id = ?`,
        [serverId, localId],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}

export function markFailed(localId: string): Promise<void> {
  return new Promise((resolve, reject) => {
    db.transaction(tx => {
      tx.executeSql(
        `UPDATE surveys
         SET syncStatus = 'failed'
         WHERE id = ?`,
        [localId],
        () => resolve(),
        (_, err) => {
          reject(err);
          return false;
        }
      );
    });
  });
}
```

