# 4) Sync service

This pushes pending records to your backend.

```ts
// syncService.ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingSurveys, markFailed, markSynced } from './surveyRepository';

const API_URL = 'https://your-api.example.com';

export async function isOnline(): Promise<boolean> {
  const state = await NetInfo.fetch();
  return !!state.isConnected && !!state.isInternetReachable;
}

export async function syncPendingSurveys(): Promise<void> {
  const online = await isOnline();
  if (!online) return;

  const pending = await getPendingSurveys();

  for (const survey of pending) {
    try {
      const response = await fetch(`${API_URL}/surveys`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          localId: survey.id,
          title: survey.title,
          notes: survey.notes,
          latitude: survey.latitude,
          longitude: survey.longitude,
          createdAt: survey.createdAt,
          updatedAt: survey.updatedAt,
        }),
      });

      if (!response.ok) {
        throw new Error(`Sync failed: ${response.status}`);
      }

      const data = await response.json();
      await markSynced(survey.id, data.serverId);
    } catch (err) {
      console.warn('Failed to sync survey', survey.id, err);
      await markFailed(survey.id);
    }
  }
}
```

