# 5) App initialization

Initialize DB and listen for connectivity changes.

```tsx
// App.tsx
import React, { useEffect, useState } from 'react';
import { View, Text, Button, FlatList, TextInput, Alert } from 'react-native';
import NetInfo from '@react-native-community/netinfo';
import { initDb } from './db';
import { insertSurvey, getAllSurveys } from './surveyRepository';
import { syncPendingSurveys } from './syncService';
import { SurveyRecord } from './types';
import { v4 as uuidv4 } from 'uuid';

export default function App() {
  const [title, setTitle] = useState('');
  const [notes, setNotes] = useState('');
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [online, setOnline] = useState(false);

  async function refresh() {
    const rows = await getAllSurveys();
    setSurveys(rows);
  }

  useEffect(() => {
    initDb();
    refresh();

    const unsubscribe = NetInfo.addEventListener(state => {
      const connected = !!state.isConnected && !!state.isInternetReachable;
      setOnline(connected);

      if (connected) {
        syncPendingSurveys().then(refresh);
      }
    });

    return () => unsubscribe();
  }, []);

  async function saveSurvey() {
    if (!title.trim()) {
      Alert.alert('Validation', 'Title is required');
      return;
    }

    const now = new Date().toISOString();
    const record: SurveyRecord = {
      id: uuidv4(),
      serverId: null,
      title,
      notes,
      latitude: 37.7749,
      longitude: -122.4194,
      createdAt: now,
      updatedAt: now,
      syncStatus: 'pending',
      deleted: 0,
    };

    await insertSurvey(record);
    setTitle('');
    setNotes('');
    await refresh();

    if (online) {
      await syncPendingSurveys();
      await refresh();
    }
  }

  return (
    <View style={{ flex: 1, padding: 20, paddingTop: 60 }}>
      <Text style={{ fontSize: 22, fontWeight: 'bold' }}>
        Field Survey App
      </Text>

      <Text style={{ marginVertical: 8 }}>
        Status: {online ? 'Online' : 'Offline'}
      </Text>

      <TextInput
        placeholder="Survey title"
        value={title}
        onChangeText={setTitle}
        style={{ borderWidth: 1, marginBottom: 10, padding: 10 }}
      />

      <TextInput
        placeholder="Notes"
        value={notes}
        onChangeText={setNotes}
        style={{ borderWidth: 1, marginBottom: 10, padding: 10, height: 80 }}
        multiline
      />

      <Button title="Save Survey" onPress={saveSurvey} />

      <Text style={{ marginTop: 20, fontSize: 18 }}>Saved Surveys</Text>

      <FlatList
        data={surveys}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <View style={{ paddingVertical: 12, borderBottomWidth: 1 }}>
            <Text style={{ fontWeight: 'bold' }}>{item.title}</Text>
            <Text>{item.notes}</Text>
            <Text>
              Sync: {item.syncStatus} {item.serverId ? `(server: ${item.serverId})` : ''}
            </Text>
          </View>
        )}
      />
    </View>
  );
}
