## 6) Repository for local CRUD

### `src/db/surveyRepo.ts`
```ts
import { getDb } from './index';
import { SurveyRecord } from '../types';
import { v4 as uuidv4 } from 'uuid';

export async function upsertSurvey(record: Omit<SurveyRecord, 'id' | 'updatedAt' | 'deleted' | 'syncStatus'> & { id?: string }) {
  const db = await getDb();
  const id = record.id ?? uuidv4();
  const updatedAt = new Date().toISOString();

  await db.executeSql(
    `
    INSERT INTO surveys (id, siteName, inspectorName, notes, latitude, longitude, updatedAt, deleted, syncStatus)
    VALUES (?, ?, ?, ?, ?, ?, ?, 0, 'pending')
    ON CONFLICT(id) DO UPDATE SET
      siteName=excluded.siteName,
      inspectorName=excluded.inspectorName,
      notes=excluded.notes,
      latitude=excluded.latitude,
      longitude=excluded.longitude,
      updatedAt=excluded.updatedAt,
      deleted=0,
      syncStatus='pending'
    `,
    [
      id,
      record.siteName,
      record.inspectorName,
      record.notes,
      record.latitude ?? null,
      record.longitude ?? null,
      updatedAt,
    ]
  );

  return id;
}

export async function getAllSurveys(): Promise<SurveyRecord[]> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`);
  const rows = result.rows;

  const items: SurveyRecord[] = [];
  for (let i = 0; i < rows.length; i++) {
    items.push(rows.item(i));
  }
  return items;
}

export async function getPendingSurveys(): Promise<SurveyRecord[]> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE syncStatus != 'synced' AND deleted = 0`);
  const rows = result.rows;

  const items: SurveyRecord[] = [];
  for (let i = 0; i < rows.length; i++) {
    items.push(rows.item(i));
  }
  return items;
}

export async function markSurveySynced(id: string) {
  const db = await getDb();
  await db.executeSql(`UPDATE surveys SET syncStatus = 'synced' WHERE id = ?`, [id]);
}

export async function markSurveyFailed(id: string) {
  const db = await getDb();
  await db.executeSql(`UPDATE surveys SET syncStatus = 'failed' WHERE id = ?`, [id]);
}

export async function deleteSurveyLocal(id: string) {
  const db = await getDb();
  await db.executeSql(`UPDATE surveys SET deleted = 1, syncStatus = 'pending', updatedAt = ? WHERE id = ?`, [
    new Date().toISOString(),
    id,
  ]);
}
