  );
}

export async function getQueueItems() {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM sync_queue ORDER BY id ASC`);
  const rows = result.rows;

  const items: any[] = [];
  for (let i = 0; i < rows.length; i++) items.push(rows.item(i));
  return items;
}

export async function removeQueueItem(id: number) {
  const db = await getDb();
  await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export async function clearQueue() {
  const db = await getDb();
  await db.executeSql(`DELETE FROM sync_queue`);
}
