## 10) Sync service

### `src/services/syncService.ts`
```ts
import { getQueueItems, removeQueueItem } from '../db/syncQueue';
import { markSurveySynced, markSurveyFailed } from '../db/surveyRepo';
import { deleteSurveyOnServer, pushSurveyToServer } from './api';

export async function syncPendingChanges() {
  const queue = await getQueueItems();

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      if (item.action === 'upsert') {
        await pushSurveyToServer(payload);
        await markSurveySynced(item.entityId);
      } else if (item.action === 'delete') {
        await deleteSurveyOnServer(item.entityId);
        await markSurveySynced(item.entityId);
      }

      await removeQueueItem(item.id);
    } catch (err) {
      console.warn('Sync failed for item', item.id, err);
      await markSurveyFailed(item.entityId);
      // Keep item in queue for retry
    }
  }
}
```

