## 7) Local data + sync queue service

### `src/services/sync.ts`
```ts
import { getDb } from "../db";
import { createSurveyRemote, updateSurveyRemote, deleteSurveyRemote } from "./api";
import { Survey } from "../types";

const db = getDb();

function now() {
  return new Date().toISOString();
}

export function saveSurveyLocal(survey: Survey) {
  db.runSync(
    `INSERT OR REPLACE INTO surveys
     (id, title, location, notes, latitude, longitude, createdAt, updatedAt, status, remoteId)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.location,
      survey.notes ?? null,
      survey.latitude ?? null,
      survey.longitude ?? null,
      survey.createdAt,
      survey.updatedAt,
      survey.status,
      survey.remoteId ?? null,
    ]
  );
}

export function enqueueSync(entityType: "survey", entityId: string, operation: "create" | "update" | "delete", payload: any) {
  db.runSync(
    `INSERT INTO sync_queue (id, entityType, entityId, operation, payload, createdAt, attempts)
     VALUES (?, ?, ?, ?, ?, ?, 0)`,
    [
      crypto.randomUUID(),
      entityType,
      entityId,
      operation,
      JSON.stringify(payload),
      now(),
    ]
  );
}

export function getAllSurveys(): Survey[] {
  const rows = db.getAllSync<any>(`SELECT * FROM surveys ORDER BY createdAt DESC`);
  return rows;
}

export function getPendingQueueItems() {
  return db.getAllSync<any>(`SELECT * FROM sync_queue ORDER BY createdAt ASC`);
}

export function deleteQueueItem(id: string) {
  db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export function markSurveySynced(id: string, remoteId: string) {
  db.runSync(
    `UPDATE surveys SET status = 'synced', remoteId = ?, updatedAt = ? WHERE id = ?`,
    [remoteId, now(), id]
  );
}

export async function syncPendingItems() {
  const items = getPendingQueueItems();

  for (const item of items) {
    try {
      const payload = JSON.parse(item.payload);

      if (item.entityType === "survey") {
        if (item.operation === "create") {
          const remote = await createSurveyRemote(payload);
          markSurveySynced(item.entityId, remote.id);
        } else if (item.operation === "update") {
          const localSurvey = db.getFirstSync<any>(
            `SELECT * FROM surveys WHERE id = ?`,
            [item.entityId]
          );

          if (localSurvey?.remoteId) {
            await updateSurveyRemote(localSurvey.remoteId, payload);
            db.runSync(`UPDATE surveys SET status = 'synced', updatedAt = ? WHERE id = ?`, [
              now(),
              item.entityId,
            ]);
          }
        } else if (item.operation === "delete") {
          const localSurvey = db.getFirstSync<any>(
            `SELECT * FROM surveys WHERE id = ?`,
            [item.entityId]
          );

          if (localSurvey?.remoteId) {
            await deleteSurveyRemote(localSurvey.remoteId);
          }
          db.runSync(`DELETE FROM surveys WHERE id = ?`, [item.entityId]);
        }
      }

      deleteQueueItem(item.id);
    } catch (err) {
      db.runSync(`UPDATE sync_queue SET attempts = attempts + 1 WHERE id = ?`, [item.id]);
      db.runSync(`UPDATE surveys SET status = 'failed' WHERE id = ?`, [item.entityId]);
    }
  }
}
```

