## 8) Zustand store

### `src/store/surveyStore.ts`
```ts
import { create } from "zustand";
import { Survey } from "../types";
import { getAllSurveys, saveSurveyLocal, enqueueSync, syncPendingItems } from "../services/sync";
import { isOnline } from "../services/connectivity";

type SurveyState = {
  surveys: Survey[];
  refresh: () => void;
  addSurvey: (survey: Omit<Survey, "status">) => Promise<void>;
  syncNow: () => Promise<void>;
};

export const useSurveyStore = create<SurveyState>((set, get) => ({
  surveys: [],
  refresh: () => set({ surveys: getAllSurveys() }),

  addSurvey: async (survey) => {
    const online = await isOnline();
    const status = online ? "pending" : "pending";

    const localSurvey: Survey = {
      ...survey,
      status,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    };

    saveSurveyLocal(localSurvey);
    enqueueSync("survey", localSurvey.id, "create", localSurvey);
    set({ surveys: getAllSurveys() });

    if (online) {
      await syncPendingItems();
      set({ surveys: getAllSurveys() });
    }
  },

  syncNow: async () => {
    const online = await isOnline();
    if (!online) return;
    await syncPendingItems();
    set({ surveys: getAllSurveys() });
  },
}));
```

