# 4) Local-first survey service

This service writes locally first, then adds to outbox.

## `surveyService.ts`

```ts
import { db, Survey, OutboxItem } from "./db";
import { v4 as uuidv4 } from "uuid";

function nowIso() {
  return new Date().toISOString();
}

export async function getSurveys(): Promise<Survey[]> {
  return db.surveys.where("deleted").equals(0 as any).toArray();
}

export async function createSurvey(input: Omit<Survey, "id" | "updatedAt" | "deleted" | "version">) {
  const survey: Survey = {
    id: uuidv4(),
    ...input,
    updatedAt: nowIso(),
    deleted: false,
    version: 0,
  };

  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(survey);
    const outboxItem: OutboxItem = {
      id: uuidv4(),
      entityType: "survey",
      entityId: survey.id,
      operation: "create",
      payload: survey,
      createdAt: nowIso(),
    };
    await db.outbox.put(outboxItem);
  });

  return survey;
}

export async function updateSurvey(id: string, patch: Partial<Survey>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found");

  const updated: Survey = {
    ...existing,
    ...patch,
    updatedAt: nowIso(),
  };

  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(updated);
    const outboxItem: OutboxItem = {
      id: uuidv4(),
      entityType: "survey",
      entityId: id,
      operation: "update",
      payload: patch,
      createdAt: nowIso(),
    };
    await db.outbox.put(outboxItem);
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found");

  const deleted: Survey = {
    ...existing,
    deleted: true,
    updatedAt: nowIso(),
  };

  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(deleted);
    const outboxItem: OutboxItem = {
      id: uuidv4(),
      entityType: "survey",
      entityId: id,
      operation: "delete",
      payload: { deleted: true },
      createdAt: nowIso(),
    };
    await db.outbox.put(outboxItem);
  });

  return deleted;
}
```

