# 5) Sync engine

This is the core of offline-first behavior.

It will:

1. check connectivity,
2. push outbox items to server,
3. pull remote changes since last sync,
4. update local DB,
5. clear synced outbox items.

## `sync.ts`

```ts
import { db, OutboxItem, Survey } from "./db";
import { apiFetch } from "./api";

function nowIso() {
  return new Date().toISOString();
}

async function getLastSyncAt(): Promise<string | null> {
  const row = await db.meta.get("lastSyncAt");
  return row?.value ?? null;
}

async function setLastSyncAt(value: string) {
  await db.meta.put({ key: "lastSyncAt", value });
}

export async function syncNow() {
  if (!navigator.onLine) return;

  const lastSyncAt = await getLastSyncAt();
  const outboxItems = await db.outbox.orderBy("createdAt").toArray();

  // 1) Push local changes
  for (const item of outboxItems) {
    try {
      await apiFetch("/sync/push", {
        method: "POST",
        body: JSON.stringify(item),
      });

      await db.outbox.delete(item.id);
    } catch (err) {
      console.error("Push failed, stopping sync:", err);
      return; // stop on first failure
    }
  }

  // 2) Pull remote changes
  try {
    const result = await apiFetch(`/sync/pull?since=${encodeURIComponent(lastSyncAt ?? "")}`);
    const remoteSurveys: Survey[] = result.surveys || [];

    await db.transaction("rw", db.surveys, async () => {
      for (const remote of remoteSurveys) {
        const local = await db.surveys.get(remote.id);

        // Simple conflict rule:
        // if remote version is newer, overwrite local
        if (!local || remote.version > local.version) {
          await db.surveys.put(remote);
        }
      }
    });

    await setLastSyncAt(nowIso());
  } catch (err) {
    console.error("Pull failed:", err);
    throw err;
  }
}
```

