# 8) Backend sync endpoints

Here’s a simple Express backend with push/pull endpoints.

## `server.ts`

```ts
import express from "express";
import cors from "cors";
import bodyParser from "body-parser";
import { v4 as uuidv4 } from "uuid";

type Survey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  deleted: boolean;
  version: number;
};

type OutboxItem = {
  id: string;
  entityType: "survey";
  entityId: string;
  operation: "create" | "update" | "delete";
  payload: Partial<Survey>;
  createdAt: string;
};

const app = express();
app.use(cors());
app.use(bodyParser.json());

const surveys = new Map<string, Survey>();

function nowIso() {
  return new Date().toISOString();
}

// Push local mutation to server
app.post("/sync/push", (req, res) => {
  const item: OutboxItem = req.body;

  if (item.entityType !== "survey") {
    return res.status(400).json({ error: "Unsupported entity type" });
  }

  const existing = surveys.get(item.entityId);

  if (item.operation === "create") {
    const payload = item.payload as Survey;
    surveys.set(item.entityId, {
      ...payload,
      version: 1,
      updatedAt: nowIso(),
    });
  }

  if (item.operation === "update") {
    if (!existing) return res.status(404).json({ error: "Survey not found" });

    surveys.set(item.entityId, {
      ...existing,
      ...item.payload,
      version: existing.version + 1,
      updatedAt: nowIso(),
    });
  }

  if (item.operation === "delete") {
    if (!existing) return res.status(404).json({ error: "Survey not found" });

    surveys.set(item.entityId, {
      ...existing,
      deleted: true,
      version: existing.version + 1,
      updatedAt: nowIso(),
    });
  }

  res.json({ ok: true });
});

// Pull remote changes since timestamp
app.get("/sync/pull", (req, res) => {
  const since = String(req.query.since || "");
  const all = Array.from(surveys.values());

  const changed = since
    ? all.filter(s => new Date(s.updatedAt).getTime() > new Date(since).getTime())
    : all;

  res.json({ surveys: changed });
});

app.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
```

