## 8) Local survey service

### `src/services/surveyService.ts`
```ts
import { getDb } from '../db';
import { newId } from '../utils/uuid';
import { Survey } from '../models/survey';

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );

  const items: Survey[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = await getDb();
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);

  if (result.rows.length === 0) return null;
  return result.rows.item(0);
}

export async function createSurvey(input: Omit<Survey, 'id' | 'updatedAt' | 'syncStatus'>) {
  const db = await getDb();
  const id = newId();
  const updatedAt = new Date().toISOString();

  await db.executeSql(
    `INSERT INTO surveys (id, title, notes, latitude, longitude, updatedAt, deletedAt, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      id,
      input.title,
      input.notes ?? null,
      input.latitude ?? null,
      input.longitude ?? null,
      updatedAt,
      null,
      'pending',
    ]
  );

  await db.executeSql(
    `INSERT INTO sync_queue (entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [
      'survey',
      id,
      'create',
      JSON.stringify({ id, ...input, updatedAt }),
      updatedAt,
    ]
  );

  return id;
}

export async function updateSurvey(
  id: string,
  input: Partial<Omit<Survey, 'id' | 'updatedAt' | 'syncStatus'>>
) {
  const db = await getDb();
  const existing = await getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const updatedAt = new Date().toISOString();
  const next = { ...existing, ...input, updatedAt, syncStatus: 'pending' as const };

  await db.executeSql(
    `UPDATE surveys
     SET title = ?, notes = ?, latitude = ?, longitude = ?, updatedAt = ?, syncStatus = ?
     WHERE id = ?`,
    [
      next.title,
      next.notes ?? null,
      next.latitude ?? null,
      next.longitude ?? null,
      updatedAt,
      'pending',
      id,
    ]
  );

  await db.executeSql(
    `INSERT INTO sync_queue (entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [
      'survey',
      id,
      'update',
      JSON.stringify({ id, ...input, updatedAt }),
      updatedAt,
    ]
  );
}

export async function deleteSurvey(id: string) {
  const db = await getDb();
  const updatedAt = new Date().toISOString();

  await db.executeSql(
    `UPDATE surveys SET deletedAt = ?, updatedAt = ?, syncStatus = ? WHERE id = ?`,
    [updatedAt, updatedAt, 'pending', id]
  );

  await db.executeSql(
    `INSERT INTO sync_queue (entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?)`,
    [
      'survey',
      id,
      'delete',
      JSON.stringify({ id, deletedAt: updatedAt }),
      updatedAt,
    ]
  );
}
```

