## 9) Sync engine

### `src/api/sync.ts`
```ts
import { getDb } from '../db';
import { api } from './client';

type QueueItem = {
  id: number;
  entityType: string;
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: string;
  createdAt: string;
};

export async function syncPendingChanges() {
  const db = await getDb();

  const [rowsResult] = await db.executeSql(
    `SELECT * FROM sync_queue ORDER BY id ASC`
  );

  const queue: QueueItem[] = [];
  for (let i = 0; i < rowsResult.rows.length; i++) {
    queue.push(rowsResult.rows.item(i));
  }

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);

      if (item.entityType === 'survey') {
        if (item.operation === 'create') {
          await api.post('/surveys', payload);
        } else if (item.operation === 'update') {
          await api.put(`/surveys/${item.entityId}`, payload);
        } else if (item.operation === 'delete') {
          await api.delete(`/surveys/${item.entityId}`);
        }
      }

      await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [item.id]);
      await db.executeSql(
        `UPDATE surveys SET syncStatus = ? WHERE id = ?`,
        ['synced', item.entityId]
      );
    } catch (error) {
      await db.executeSql(
        `UPDATE surveys SET syncStatus = ? WHERE id = ?`,
        ['error', item.entityId]
      );
      // stop on first failure to preserve order and allow retry later
      break;
    }
  }
}
```

