# 4) Survey repository

This handles CRUD locally and enqueues sync operations.

## `surveyRepository.ts`

```ts
import { getDb } from './db';
import { randomUUID } from 'expo-crypto';

export type Survey = {
  id: string;
  siteId: string;
  inspectorName: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos: string[];
  updatedAt: string;
  deleted: boolean;
  version: number;
};

const db = getDb();

export async function listSurveys(): Promise<Survey[]> {
  const rows = db.getAllSync<any>(
    `SELECT * FROM surveys WHERE deleted = 0 ORDER BY updatedAt DESC`
  );

  return rows.map((r) => ({
    ...r,
    photos: JSON.parse(r.photos),
    deleted: !!r.deleted,
  }));
}

export async function getSurvey(id: string): Promise<Survey | null> {
  const row = db.getFirstSync<any>(
    `SELECT * FROM surveys WHERE id = ?`,
    [id]
  );

  if (!row) return null;

  return {
    ...row,
    photos: JSON.parse(row.photos),
    deleted: !!row.deleted,
  };
}

export async function saveSurvey(input: Omit<Survey, 'updatedAt' | 'deleted' | 'version'> & Partial<Pick<Survey, 'id'>>) {
  const now = new Date().toISOString();
  const id = input.id ?? randomUUID();

  const existing = db.getFirstSync<any>(`SELECT version FROM surveys WHERE id = ?`, [id]);
  const version = existing ? existing.version : 0;

  db.runSync(
    `INSERT INTO surveys (id, siteId, inspectorName, latitude, longitude, notes, photos, updatedAt, deleted, version)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, ?)
     ON CONFLICT(id) DO UPDATE SET
       siteId = excluded.siteId,
       inspectorName = excluded.inspectorName,
       latitude = excluded.latitude,
       longitude = excluded.longitude,
       notes = excluded.notes,
       photos = excluded.photos,
       updatedAt = excluded.updatedAt,
       deleted = 0,
       version = surveys.version + 1`,
    [
      id,
      input.siteId,
      input.inspectorName,
      input.latitude,
      input.longitude,
      input.notes,
      JSON.stringify(input.photos ?? []),
      now,
      version,
    ]
  );

  enqueueOutbox({
    entityType: 'survey',
    entityId: id,
    operation: 'upsert',
    payload: {
      id,
      siteId: input.siteId,
      inspectorName: input.inspectorName,
      latitude: input.latitude,
      longitude: input.longitude,
      notes: input.notes,
      photos: input.photos ?? [],
      updatedAt: now,
      deleted: false,
    },
  });

  return getSurvey(id);
}

export async function deleteSurvey(id: string) {
  const now = new Date().toISOString();

  db.runSync(
    `UPDATE surveys SET deleted = 1, updatedAt = ?, version = version + 1 WHERE id = ?`,
    [now, id]
  );

  enqueueOutbox({
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { id, deleted: true, updatedAt: now },
  });
}

function enqueueOutbox(args: {
  entityType: string;
  entityId: string;
  operation: 'upsert' | 'delete';
  payload: any;
}) {
  db.runSync(
    `INSERT INTO outbox (id, entityType, entityId, operation, payload, createdAt, attempts)
     VALUES (?, ?, ?, ?, ?, ?, 0)`,
    [
      randomUUID(),
      args.entityType,
      args.entityId,
      args.operation,
      JSON.stringify(args.payload),
      new Date().toISOString(),
    ]
  );
}
```

