# 5) Sync service

This:
1. checks connectivity,
2. pushes outbox items,
3. pulls remote changes,
4. updates local DB.

## `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import { getDb } from './db';

const db = getDb();
const API_URL = 'https://your-api.example.com';

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return { ok: false, reason: 'offline' };

  await pushOutbox();
  await pullRemoteChanges();

  return { ok: true };
}

async function pushOutbox() {
  const items = db.getAllSync<any>(
    `SELECT * FROM outbox ORDER BY createdAt ASC LIMIT 100`
  );

  for (const item of items) {
    try {
      const payload = JSON.parse(item.payload);

      const res = await fetch(`${API_URL}/sync/push`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          entityType: item.entityType,
          entityId: item.entityId,
          operation: item.operation,
          payload,
        }),
      });

      if (!res.ok) {
        const text = await res.text();
        throw new Error(text);
      }

      db.runSync(`DELETE FROM outbox WHERE id = ?`, [item.id]);
    } catch (err: any) {
      db.runSync(
        `UPDATE outbox SET attempts = attempts + 1, lastError = ? WHERE id = ?`,
        [String(err?.message ?? err), item.id]
      );
    }
  }
}

async function pullRemoteChanges() {
  const lastSync = getSyncState('lastSync') ?? '1970-01-01T00:00:00.000Z';

  const res = await fetch(
    `${API_URL}/sync/pull?since=${encodeURIComponent(lastSync)}`
  );

  if (!res.ok) {
    throw new Error(`Pull failed: ${await res.text()}`);
  }

  const data = await res.json();
  const changes = data.changes as any[];

  for (const change of changes) {
    if (change.entityType === 'survey') {
      applyRemoteSurvey(change.payload);
    }
  }

  setSyncState('lastSync', new Date().toISOString());
}

function applyRemoteSurvey(s: any) {
  const local = db.getFirstSync<any>(`SELECT version FROM surveys WHERE id = ?`, [s.id]);

  if (!local || s.version > local.version) {
    db.runSync(
      `INSERT INTO surveys (id, siteId, inspectorName, latitude, longitude, notes, photos, updatedAt, deleted, version)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(id) DO UPDATE SET
         siteId = excluded.siteId,
         inspectorName = excluded.inspectorName,
         latitude = excluded.latitude,
         longitude = excluded.longitude,
         notes = excluded.notes,
         photos = excluded.photos,
         updatedAt = excluded.updatedAt,
         deleted = excluded.deleted,
         version = excluded.version`,
      [
        s.id,
        s.siteId,
        s.inspectorName,
        s.latitude,
        s.longitude,
        s.notes,
        JSON.stringify(s.photos ?? []),
        s.updatedAt,
        s.deleted ? 1 : 0,
        s.version ?? 0,
      ]
    );
  }
}

function getSyncState(key: string): string | null {
  const row = db.getFirstSync<any>(`SELECT value FROM sync_state WHERE key = ?`, [key]);
  return row?.value ?? null;
}

function setSyncState(key: string, value: string) {
  db.runSync(
    `INSERT INTO sync_state (key, value) VALUES (?, ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [key, value]
  );
}
```

