# 8) Backend sync API

Here’s a simple Express backend with PostgreSQL-style logic. You can adapt it to any DB.

## `server.js`

```js
import express from 'express';

const app = express();
app.use(express.json());

// In production, use PostgreSQL tables with proper indexing.
// This is a simplified in-memory example.
const surveys = new Map(); // id -> survey
const changes = []; // append-only log

app.post('/sync/push', (req, res) => {
  const { entityType, operation, payload } = req.body;

  if (entityType !== 'survey') {
    return res.status(400).send('Unsupported entity type');
  }

  if (operation === 'upsert') {
    const existing = surveys.get(payload.id);
    const version = (existing?.version ?? 0) + 1;

    const updated = {
      ...payload,
      version,
      updatedAt: payload.updatedAt ?? new Date().toISOString(),
      deleted: false,
    };

    surveys.set(payload.id, updated);
    changes.push({
      entityType: 'survey',
      payload: updated,
      changedAt: new Date().toISOString(),
    });

    return res.json({ ok: true, version });
  }

  if (operation === 'delete') {
    const existing = surveys.get(payload.id);
    const deleted = {
      ...(existing ?? { id: payload.id }),
      deleted: true,
      version: (existing?.version ?? 0) + 1,
      updatedAt: payload.updatedAt ?? new Date().toISOString(),
    };

    surveys.set(payload.id, deleted);
    changes.push({
      entityType: 'survey',
      payload: deleted,
      changedAt: new Date().toISOString(),
    });

    return res.json({ ok: true });
  }

  res.status(400).send('Unsupported operation');
});

app.get('/sync/pull', (req, res) => {
  const since = req.query.since ? new Date(req.query.since) : new Date(0);

  const result = changes.filter((c) => new Date(c.changedAt) > since);

  res.json({ changes: result });
});

app.listen(3000, () => {
  console.log('Sync server running on port 3000');
});
```

