# 2) Local repository

## `surveyRepository.ts`

```ts
import { getDb } from './db';
import { v4 as uuidv4 } from 'uuid';

export type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  version: number;
  deleted: boolean;
};

type PendingOperation = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: string;
  createdAt: string;
};

export async function listSurveys(): Promise<SurveyRecord[]> {
  const db = getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM survey_records WHERE deleted = 0 ORDER BY updatedAt DESC`
  );

  const rows = result.rows;
  const items: SurveyRecord[] = [];
  for (let i = 0; i < rows.length; i++) {
    items.push({
      ...rows.item(i),
      deleted: !!rows.item(i).deleted,
    });
  }
  return items;
}

export async function getSurvey(id: string): Promise<SurveyRecord | null> {
  const db = getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM survey_records WHERE id = ? LIMIT 1`,
    [id]
  );

  if (result.rows.length === 0) return null;
  const row = result.rows.item(0);
  return { ...row, deleted: !!row.deleted };
}

async function enqueueOperation(op: Omit<PendingOperation, 'id' | 'createdAt'>) {
  const db = getDb();
  await db.executeSql(
    `INSERT INTO pending_operations (id, entityType, entityId, operation, payload, createdAt)
     VALUES (?, ?, ?, ?, ?, ?)`,
    [
      uuidv4(),
      op.entityType,
      op.entityId,
      op.operation,
      op.payload,
      new Date().toISOString(),
    ]
  );
}

export async function createSurvey(input: Omit<SurveyRecord, 'id' | 'updatedAt' | 'version' | 'deleted'>) {
  const db = getDb();
  const id = uuidv4();
  const now = new Date().toISOString();

  const record: SurveyRecord = {
    id,
    ...input,
    updatedAt: now,
    version: 1,
    deleted: false,
  };

  await db.executeSql(
    `INSERT INTO survey_records (id, siteName, latitude, longitude, notes, updatedAt, version, deleted)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      record.id,
      record.siteName,
      record.latitude,
      record.longitude,
      record.notes,
      record.updatedAt,
      record.version,
      0,
    ]
  );

  await enqueueOperation({
    entityType: 'survey',
    entityId: id,
    operation: 'create',
    payload: JSON.stringify(record),
  });

  return record;
}

export async function updateSurvey(id: string, patch: Partial<Omit<SurveyRecord, 'id'>>) {
  const existing = await getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  const updated: SurveyRecord = {
    ...existing,
    ...patch,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  const db = getDb();
  await db.executeSql(
    `UPDATE survey_records
     SET siteName = ?, latitude = ?, longitude = ?, notes = ?, updatedAt = ?, version = ?, deleted = ?
     WHERE id = ?`,
    [
      updated.siteName,
      updated.latitude,
      updated.longitude,
      updated.notes,
      updated.updatedAt,
      updated.version,
      updated.deleted ? 1 : 0,
      id,
    ]
  );

  await enqueueOperation({
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: JSON.stringify(updated),
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await getSurvey(id);
  if (!existing) throw new Error('Survey not found');

  const deleted: SurveyRecord = {
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  const db = getDb();
  await db.executeSql(
    `UPDATE survey_records SET deleted = 1, updatedAt = ?, version = ? WHERE id = ?`,
    [deleted.updatedAt, deleted.version, id]
  );

  await enqueueOperation({
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: JSON.stringify(deleted),
  });
}
```

