# 4) Sync engine

This is the heart of the offline-first behavior.

## `syncService.ts`

```ts
import { getDb } from './db';
import { isOnline } from './network';

type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  version: number;
  deleted: boolean;
};

async function getPendingOperations() {
  const db = getDb();
  const [result] = await db.executeSql(
    `SELECT * FROM pending_operations ORDER BY createdAt ASC`
  );

  const ops = [];
  for (let i = 0; i < result.rows.length; i++) {
    ops.push(result.rows.item(i));
  }
  return ops;
}

async function deletePendingOperation(id: string) {
  const db = getDb();
  await db.executeSql(`DELETE FROM pending_operations WHERE id = ?`, [id]);
}

async function setSyncState(key: string, value: string) {
  const db = getDb();
  await db.executeSql(
    `INSERT INTO sync_state (key, value) VALUES (?, ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [key, value]
  );
}

async function getSyncState(key: string): Promise<string | null> {
  const db = getDb();
  const [result] = await db.executeSql(`SELECT value FROM sync_state WHERE key = ?`, [key]);
  if (result.rows.length === 0) return null;
  return result.rows.item(0).value;
}

export async function syncNow() {
  if (!(await isOnline())) return;

  const pendingOps = await getPendingOperations();

  // 1) Push local changes
  for (const op of pendingOps) {
    const response = await fetch('https://your-api.example.com/sync/op', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        operationId: op.id,
        entityType: op.entityType,
        entityId: op.entityId,
        operation: op.operation,
        payload: JSON.parse(op.payload),
      }),
    });

    if (response.ok) {
      await deletePendingOperation(op.id);
    } else if (response.status === 409) {
      // Conflict: server says stale version or conflicting update
      const conflict = await response.json();
      console.warn('Conflict detected', conflict);
      // You can store conflict info locally or prompt user
      continue;
    } else {
      // Stop on transient failure
      throw new Error(`Sync failed for op ${op.id}`);
    }
  }

  // 2) Pull remote changes
  const lastSync = (await getSyncState('lastSync')) || '1970-01-01T00:00:00.000Z';

  const pullResponse = await fetch(
    `https://your-api.example.com/sync/changes?since=${encodeURIComponent(lastSync)}`
  );

  if (!pullResponse.ok) {
    throw new Error('Failed to pull remote changes');
  }

  const data: { surveys: SurveyRecord[]; serverTime: string } = await pullResponse.json();

  const db = getDb();
  await db.executeSql('BEGIN TRANSACTION');
  try {
    for (const remote of data.surveys) {
      await db.executeSql(
        `INSERT INTO survey_records (id, siteName, latitude, longitude, notes, updatedAt, version, deleted)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(id) DO UPDATE SET
           siteName = excluded.siteName,
           latitude = excluded.latitude,
           longitude = excluded.longitude,
           notes = excluded.notes,
           updatedAt = excluded.updatedAt,
           version = excluded.version,
           deleted = excluded.deleted`,
        [
          remote.id,
          remote.siteName,
          remote.latitude,
          remote.longitude,
          remote.notes,
          remote.updatedAt,
          remote.version,
          remote.deleted ? 1 : 0,
        ]
      );
    }

    await setSyncState('lastSync', data.serverTime);
    await db.executeSql('COMMIT');
  } catch (e) {
    await db.executeSql('ROLLBACK');
    throw e;
  }
}
