# 5) Auto-sync hook

## `useAutoSync.ts`

```ts
import { useEffect } from 'react';
import { subscribeToConnectivity } from './network';
import { syncNow } from './syncService';

export function useAutoSync() {
  useEffect(() => {
    let syncing = false;

    const unsubscribe = subscribeToConnectivity(async online => {
      if (online && !syncing) {
        syncing = true;
        try {
          await syncNow();
        } catch (e) {
          console.error('Auto-sync failed', e);
        } finally {
          syncing = false;
        }
      }
    });

    return () => unsubscribe();
  }, []);
}
