# 7) Backend sync API example

Here’s a minimal Node/Express backend to support sync.

## `server.ts`

```ts
import express from 'express';
import bodyParser from 'body-parser';

const app = express();
app.use(bodyParser.json());

type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  version: number;
  deleted: boolean;
};

const surveys = new Map<string, SurveyRecord>();
let lastServerTime = new Date().toISOString();

app.post('/sync/op', (req, res) => {
  const { entityId, operation, payload } = req.body as {
    entityId: string;
    operation: 'create' | 'update' | 'delete';
    payload: SurveyRecord;
  };

  const existing = surveys.get(entityId);

  if (operation === 'create') {
    if (existing) {
      return res.status(409).json({ error: 'Already exists', existing });
    }
    surveys.set(entityId, payload);
  }

  if (operation === 'update') {
    if (!existing) {
      return res.status(409).json({ error: 'Missing record', entityId });
    }
    if (payload.version <= existing.version) {
      return res.status(409).json({ error: 'Version conflict', existing });
    }
    surveys.set(entityId, payload);
  }

  if (operation === 'delete') {
    if (!existing) {
      return res.status(409).json({ error: 'Missing record', entityId });
    }
    if (payload.version <= existing.version) {
      return res.status(409).json({ error: 'Version conflict', existing });
    }
    surveys.set(entityId, payload);
  }

  lastServerTime = new Date().toISOString();
  res.json({ ok: true, serverTime: lastServerTime });
});

app.get('/sync/changes', (req, res) => {
  const since = String(req.query.since || '1970-01-01T00:00:00.000Z');

  const changed = [...surveys.values()].filter(r => r.updatedAt > since);

  res.json({
    surveys: changed,
    serverTime: new Date().toISOString(),
  });
});

app.listen(3000, () => {
  console.log('Sync server running on http://localhost:3000');
});
```

