## `storage.ts`

```ts
import AsyncStorage from "@react-native-async-storage/async-storage";
import { SurveyRecord, SyncOperation } from "./types";

const SURVEYS_KEY = "surveys";
const OUTBOX_KEY = "outbox";

async function readJson<T>(key: string, fallback: T): Promise<T> {
  const raw = await AsyncStorage.getItem(key);
  if (!raw) return fallback;
  return JSON.parse(raw) as T;
}

async function writeJson<T>(key: string, value: T): Promise<void> {
  await AsyncStorage.setItem(key, JSON.stringify(value));
}

export async function getSurveys(): Promise<SurveyRecord[]> {
  return readJson<SurveyRecord[]>(SURVEYS_KEY, []);
}

export async function saveSurveys(records: SurveyRecord[]): Promise<void> {
  await writeJson(SURVEYS_KEY, records);
}

export async function upsertSurvey(record: SurveyRecord): Promise<void> {
  const surveys = await getSurveys();
  const idx = surveys.findIndex((s) => s.id === record.id);

  if (idx >= 0) {
    surveys[idx] = record;
  } else {
    surveys.push(record);
  }

  await saveSurveys(surveys);
}

export async function deleteSurveyLocal(id: string): Promise<void> {
  const surveys = await getSurveys();
  const updated = surveys.filter((s) => s.id !== id);
  await saveSurveys(updated);
}

export async function getOutbox(): Promise<SyncOperation[]> {
  return readJson<SyncOperation[]>(OUTBOX_KEY, []);
}

export async function saveOutbox(ops: SyncOperation[]): Promise<void> {
  await writeJson(OUTBOX_KEY, ops);
}

export async function enqueueOperation(op: SyncOperation): Promise<void> {
  const outbox = await getOutbox();
  outbox.push(op);
  await saveOutbox(outbox);
}

export async function removeOutboxOperation(id: string): Promise<void> {
  const outbox = await getOutbox();
  await saveOutbox(outbox.filter((op) => op.id !== id));
}
```

