## Sync engine

This is the heart of offline-first behavior.

### `sync.ts`

```ts
import NetInfo from "@react-native-community/netinfo";
import {
  getOutbox,
  saveOutbox,
  upsertSurvey,
  deleteSurveyLocal,
} from "./storage";
import {
  syncCreateSurvey,
  syncUpdateSurvey,
  syncDeleteSurvey,
  fetchAllSurveys,
} from "./api";
import { SyncOperation } from "./types";

let syncing = false;

export async function syncNow(): Promise<void> {
  if (syncing) return;
  syncing = true;

  try {
    const state = await NetInfo.fetch();
    if (!state.isConnected) return;

    const outbox = await getOutbox();

    for (const op of outbox) {
      try {
        if (op.type === "CREATE") {
          const serverRecord = await syncCreateSurvey(op.payload);
          await upsertSurvey(serverRecord);
        } else if (op.type === "UPDATE") {
          const serverRecord = await syncUpdateSurvey(op.payload);
          await upsertSurvey(serverRecord);
        } else if (op.type === "DELETE") {
          await syncDeleteSurvey(op.payload.id, op.payload.version);
          await deleteSurveyLocal(op.payload.id);
        }
      } catch (err) {
        op.retries += 1;
        // Keep failed op in queue for retry later
        continue;
      }
    }

    // Remove successfully synced ops by rebuilding queue
    const remaining = await getOutbox();
    const failedIds = new Set(
      remaining.filter((op) => op.retries > 0).map((op) => op.id)
    );

    const updatedOutbox = outbox.filter((op) => failedIds.has(op.id));
    await saveOutbox(updatedOutbox);

    // Optional: pull latest server state after pushing local changes
    const latest = await fetchAllSurveys();
    for (const record of latest) {
      await upsertSurvey(record);
    }
  } finally {
    syncing = false;
  }
}

export function startAutoSync(): () => void {
  const unsubscribe = NetInfo.addEventListener((state) => {
    if (state.isConnected) {
      syncNow().catch(console.error);
    }
  });

  return unsubscribe;
}
```

