## Survey service

This is what your UI calls.

### `surveyService.ts`

```ts
import { v4 as uuidv4 } from "uuid";
import { enqueueOperation, upsertSurvey, deleteSurveyLocal } from "./storage";
import { SurveyRecord, SyncOperation } from "./types";

export async function createSurvey(input: Omit<SurveyRecord, "id" | "createdAt" | "updatedAt" | "version">) {
  const now = new Date().toISOString();
  const record: SurveyRecord = {
    ...input,
    id: uuidv4(),
    createdAt: now,
    updatedAt: now,
    version: 1,
  };

  await upsertSurvey(record);

  const op: SyncOperation = {
    id: uuidv4(),
    type: "CREATE",
    entity: "survey",
    payload: record,
    createdAt: now,
    retries: 0,
  };

  await enqueueOperation(op);
  return record;
}

export async function updateSurvey(record: SurveyRecord) {
  const updated: SurveyRecord = {
    ...record,
    updatedAt: new Date().toISOString(),
    version: record.version + 1,
  };

  await upsertSurvey(updated);

  const op: SyncOperation = {
    id: uuidv4(),
    type: "UPDATE",
    entity: "survey",
    payload: updated,
    createdAt: updated.updatedAt,
    retries: 0,
  };

  await enqueueOperation(op);
  return updated;
}

export async function removeSurvey(record: SurveyRecord) {
  await deleteSurveyLocal(record.id);

  const op: SyncOperation = {
    id: uuidv4(),
    type: "DELETE",
    entity: "survey",
    payload: { id: record.id, version: record.version },
    createdAt: new Date().toISOString(),
    retries: 0,
  };

  await enqueueOperation(op);
}
```

