  notes?: string;
  photos?: string[];
  status: 'draft' | 'submitted' | 'synced';
  version: number;
  updatedAt: string;
  deletedAt?: string | null;
};

function nowIso() {
  return new Date().toISOString();
}

export function getAllSurveys(): SurveyRecord[] {
  const rows = db.getAllSync<any>(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );

  return rows.map((r) => ({
    ...r,
    photos: r.photos ? JSON.parse(r.photos) : [],
  }));
}

export function getSurveyById(id: string): SurveyRecord | null {
  const row = db.getFirstSync<any>(
    `SELECT * FROM surveys WHERE id = ? AND deletedAt IS NULL`,
    [id]
  );
  if (!row) return null;
  return {
    ...row,
    photos: row.photos ? JSON.parse(row.photos) : [],
  };
}

export function upsertSurveyLocal(
  survey: Omit<SurveyRecord, 'version' | 'updatedAt'> & Partial<Pick<SurveyRecord, 'version' | 'updatedAt'>>
) {
  const existing = getSurveyById(survey.id);
  const updatedAt = survey.updatedAt ?? nowIso();
  const version = survey.version ?? (existing?.version ?? 0);

  db.runSync(
    `INSERT INTO surveys (id, projectId, siteName, latitude, longitude, notes, photos, status, version, updatedAt, deletedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT(id) DO UPDATE SET
       projectId=excluded.projectId,
       siteName=excluded.siteName,
       latitude=excluded.latitude,
       longitude=excluded.longitude,
       notes=excluded.notes,
       photos=excluded.photos,
       status=excluded.status,
       version=excluded.version,
       updatedAt=excluded.updatedAt,
       deletedAt=excluded.deletedAt`,
    [
      survey.id,
      survey.projectId,
      survey.siteName,
      survey.latitude,
      survey.longitude,
      survey.notes ?? null,
      JSON.stringify(survey.photos ?? []),
      survey.status,
      version,
      updatedAt,
      survey.deletedAt ?? null,
    ]
  );
}

export function createSurveyLocal(input: Omit<SurveyRecord, 'id' | 'version' | 'updatedAt' | 'deletedAt'>) {
  const survey: SurveyRecord = {
    ...input,
    id: uuidv4(),
    version: 0,
    updatedAt: nowIso(),
    deletedAt: null,
  };

  upsertSurveyLocal(survey);
  return survey;
}

export function deleteSurveyLocal(id: string) {
  db.runSync(
    `UPDATE surveys SET deletedAt = ?, updatedAt = ? WHERE id = ?`,
    [nowIso(), nowIso(), id]
  );
}
