## 5) Sync queue repository

### `syncQueue.ts`
```ts
import { db } from './db';
import { v4 as uuidv4 } from 'uuid';

export type SyncOperation = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
  createdAt: string;
  retryCount: number;
  lastError?: string | null;
};

function nowIso() {
  return new Date().toISOString();
}

export function enqueueOperation(op: Omit<SyncOperation, 'id' | 'createdAt' | 'retryCount' | 'lastError'>) {
  db.runSync(
    `INSERT INTO sync_queue (id, entityType, entityId, operation, payload, createdAt, retryCount, lastError)
     VALUES (?, ?, ?, ?, ?, ?, 0, NULL)`,
    [
      uuidv4(),
      op.entityType,
      op.entityId,
      op.operation,
      JSON.stringify(op.payload),
      nowIso(),
    ]
  );
}

export function getPendingOperations(): SyncOperation[] {
  const rows = db.getAllSync<any>(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );

  return rows.map((r) => ({
    ...r,
    payload: JSON.parse(r.payload),
  }));
}

export function removeOperation(id: string) {
  db.runSync(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export function markOperationFailed(id: string, error: string) {
  db.runSync(
    `UPDATE sync_queue SET retryCount = retryCount + 1, lastError = ? WHERE id = ?`,
    [error, id]
  );
}
```

