## 7) Sync service

### `syncService.ts`
```ts
import NetInfo from '@react-native-community/netinfo';
import { getPendingOperations, removeOperation, markOperationFailed } from './syncQueue';
import { syncSurvey, pullSurveys } from './api';
import { upsertSurveyLocal } from './surveyRepository';

let syncing = false;

export async function syncNow() {
  if (syncing) return;
  syncing = true;

  try {
    const net = await NetInfo.fetch();
    if (!net.isConnected) return;

    const ops = getPendingOperations();

    for (const op of ops) {
      try {
        if (op.entityType === 'survey') {
          const result = await syncSurvey({
            operation: op.operation,
            payload: op.payload,
          });

          // Example: server returns canonical record
          if (result?.survey) {
            upsertSurveyLocal({
              ...result.survey,
              photos: result.survey.photos ?? [],
            });
          }

          removeOperation(op.id);
        }
      } catch (err: any) {
        markOperationFailed(op.id, err.message || 'Sync failed');
      }
    }

    // Optional: pull latest changes from server
    const latest = await pullSurveys();
    if (Array.isArray(latest?.surveys)) {
      for (const s of latest.surveys) {
        upsertSurveyLocal({
          ...s,
          photos: s.photos ?? [],
        });
      }
    }
  } finally {
    syncing = false;
  }
}
```

