```ts
import { createSurveyLocal, upsertSurveyLocal, deleteSurveyLocal } from './surveyRepository';
import { enqueueOperation } from './syncQueue';

export function createSurvey(input: {
  projectId: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes?: string;
  photos?: string[];
}) {
  const survey = createSurveyLocal({
    ...input,
    status: 'draft',
  });

  enqueueOperation({
    entityType: 'survey',
    entityId: survey.id,
    operation: 'create',
    payload: survey,
  });

  return survey;
}

export function updateSurvey(id: string, changes: Partial<{
  projectId: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  photos: string[];
  status: 'draft' | 'submitted' | 'synced';
}>) {
  const existing = require('./surveyRepository').getSurveyById(id);
  if (!existing) throw new Error('Survey not found');

  const updated = {
    ...existing,
    ...changes,
    updatedAt: new Date().toISOString(),
  };

  upsertSurveyLocal(updated);

  enqueueOperation({
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: updated,
  });

  return updated;
}

export function deleteSurvey(id: string) {
  deleteSurveyLocal(id);

  enqueueOperation({
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { id },
  });
}
