## 2) IndexedDB helper

This uses the native IndexedDB API with a small wrapper.

```ts
// src/db.ts
const DB_NAME = "field-survey-db";
const DB_VERSION = 1;

const RECORDS_STORE = "records";
const QUEUE_STORE = "mutationQueue";
const META_STORE = "meta";

export type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: number;
  syncedAt?: number;
  deleted?: boolean;
};

export type PendingMutation = {
  id: string;
  type: "upsert" | "delete";
  recordId: string;
  payload?: SurveyRecord;
  createdAt: number;
  retries: number;
};

function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;

      if (!db.objectStoreNames.contains(RECORDS_STORE)) {
        db.createObjectStore(RECORDS_STORE, { keyPath: "id" });
      }

      if (!db.objectStoreNames.contains(QUEUE_STORE)) {
        db.createObjectStore(QUEUE_STORE, { keyPath: "id" });
      }

      if (!db.objectStoreNames.contains(META_STORE)) {
        db.createObjectStore(META_STORE, { keyPath: "key" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function withStore<T>(
  storeName: string,
  mode: IDBTransactionMode,
  fn: (store: IDBObjectStore) => Promise<T> | T
): Promise<T> {
  const db = await openDB();
  return new Promise<T>((resolve, reject) => {
    const tx = db.transaction(storeName, mode);
    const store = tx.objectStore(storeName);

    Promise.resolve(fn(store))
      .then((result) => {
        tx.oncomplete = () => {
          db.close();
          resolve(result);
        };
        tx.onerror = () => {
          db.close();
          reject(tx.error);
        };
      })
      .catch((err) => {
        db.close();
        reject(err);
      });
  });
}

export async function getAllRecords(): Promise<SurveyRecord[]> {
  return withStore(RECORDS_STORE, "readonly", (store) => {
    return new Promise((resolve, reject) => {
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result as SurveyRecord[]);
      req.onerror = () => reject(req.error);
    });
  });
}

export async function getRecord(id: string): Promise<SurveyRecord | undefined> {
  return withStore(RECORDS_STORE, "readonly", (store) => {
    return new Promise((resolve, reject) => {
      const req = store.get(id);
      req.onsuccess = () => resolve(req.result as SurveyRecord | undefined);
      req.onerror = () => reject(req.error);
    });
  });
}

export async function saveRecord(record: SurveyRecord): Promise<void> {
  return withStore(RECORDS_STORE, "readwrite", (store) => {
    return new Promise((resolve, reject) => {
      const req = store.put(record);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  });
}

export async function deleteRecordLocal(id: string): Promise<void> {
  return withStore(RECORDS_STORE, "readwrite", (store) => {
    return new Promise((resolve, reject) => {
      const req = store.delete(id);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  });
}

export async function enqueueMutation(mutation: PendingMutation): Promise<void> {
  return withStore(QUEUE_STORE, "readwrite", (store) => {
    return new Promise((resolve, reject) => {
      const req = store.put(mutation);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  });
}

export async function getQueuedMutations(): Promise<PendingMutation[]> {
  return withStore(QUEUE_STORE, "readonly", (store) => {
    return new Promise((resolve, reject) => {
      const req = store.getAll();
      req.onsuccess = () => resolve(req.result as PendingMutation[]);
      req.onerror = () => reject(req.error);
    });
  });
}

export async function removeQueuedMutation(id: string): Promise<void> {
  return withStore(QUEUE_STORE, "readwrite", (store) => {
    return new Promise((resolve, reject) => {
      const req = store.delete(id);
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  });
}

export async function clearQueue(): Promise<void> {
  return withStore(QUEUE_STORE, "readwrite", (store) => {
    return new Promise((resolve, reject) => {
      const req = store.clear();
      req.onsuccess = () => resolve();
      req.onerror = () => reject(req.error);
    });
  });
}
