## 4) Sync manager

This handles reconnect and flushes the queue.

```ts
// src/sync.ts
import {
  getQueuedMutations,
  removeQueuedMutation,
  saveRecord,
  deleteRecordLocal,
  PendingMutation,
} from "./db";
import { pushMutation, fetchServerRecords } from "./api";

export async function syncNow(): Promise<void> {
  if (!navigator.onLine) return;

  // 1) Push queued local changes
  const queue = await getQueuedMutations();

  for (const mutation of queue) {
    try {
      await pushMutation(mutation);

      if (mutation.type === "delete") {
        await deleteRecordLocal(mutation.recordId);
      } else if (mutation.payload) {
        await saveRecord({
          ...mutation.payload,
          syncedAt: Date.now(),
        });
      }

      await removeQueuedMutation(mutation.id);
    } catch (err) {
      console.error("Sync failed for mutation:", mutation.id, err);
      // Keep it in queue for retry
    }
  }

  // 2) Pull latest server state and merge locally
  const serverRecords = await fetchServerRecords();
  for (const record of serverRecords) {
    await saveRecord({
      ...record,
      syncedAt: Date.now(),
    });
  }
}

export function startSyncListeners(onSynced?: () => void) {
  const handler = async () => {
    try {
      await syncNow();
      onSynced?.();
    } catch (err) {
      console.error("Background sync error:", err);
    }
  };

  window.addEventListener("online", handler);

  // Optional periodic retry
  const interval = window.setInterval(() => {
    if (navigator.onLine) handler();
  }, 30000);

  return () => {
    window.removeEventListener("online", handler);
    window.clearInterval(interval);
  };
}
```

