## 5) React app

A simple UI to create and list survey records.

```tsx
// src/App.tsx
import React, { useEffect, useState } from "react";
import {
  getAllRecords,
  saveRecord,
  enqueueMutation,
  deleteRecordLocal,
  SurveyRecord,
  PendingMutation,
} from "./db";
import { startSyncListeners, syncNow } from "./sync";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [records, setRecords] = useState<SurveyRecord[]>([]);
  const [siteName, setSiteName] = useState("");
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [notes, setNotes] = useState("");
  const [online, setOnline] = useState(navigator.onLine);

  async function refresh() {
    const all = await getAllRecords();
    setRecords(all.filter((r) => !r.deleted));
  }

  useEffect(() => {
    refresh();

    const cleanup = startSyncListeners(async () => {
      setOnline(navigator.onLine);
      await refresh();
    });

    const onOnline = () => setOnline(true);
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      cleanup();
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleAdd() {
    const record: SurveyRecord = {
      id: uuid(),
      siteName,
      latitude: Number(latitude),
      longitude: Number(longitude),
      notes,
      updatedAt: Date.now(),
    };

    await saveRecord(record);

    const mutation: PendingMutation = {
      id: uuid(),
      type: "upsert",
      recordId: record.id,
      payload: record,
      createdAt: Date.now(),
      retries: 0,
    };

    await enqueueMutation(mutation);

    setSiteName("");
    setLatitude("");
    setLongitude("");
    setNotes("");

    await refresh();

    if (navigator.onLine) {
      await syncNow();
      await refresh();
    }
  }

  async function handleDelete(id: string) {
    const existing = records.find((r) => r.id === id);
    if (!existing) return;

    const deletedRecord = { ...existing, deleted: true, updatedAt: Date.now() };
    await saveRecord(deletedRecord);

    const mutation: PendingMutation = {
      id: uuid(),
      type: "delete",
      recordId: id,
      createdAt: Date.now(),
      retries: 0,
    };

    await enqueueMutation(mutation);

    await refresh();

    if (navigator.onLine) {
      await syncNow();
      await refresh();
    }
  }

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h1>Field Survey App</h1>
      <p>
        Status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
