const serverRecords = new Map<string, SurveyRecord>();

app.get("/api/surveys", (_req, res) => {
  res.json(Array.from(serverRecords.values()).filter((r) => !r.deleted));
});

app.post("/api/sync", (req, res) => {
  const mutation = req.body as {
    type: "upsert" | "delete";
    recordId: string;
    payload?: SurveyRecord;
  };

  if (mutation.type === "upsert" && mutation.payload) {
    const existing = serverRecords.get(mutation.recordId);
    if (!existing || mutation.payload.updatedAt >= existing.updatedAt) {
      serverRecords.set(mutation.recordId, mutation.payload);
    }
  }

  if (mutation.type === "delete") {
    const existing = serverRecords.get(mutation.recordId);
    if (existing) {
      serverRecords.set(mutation.recordId, { ...existing, deleted: true });
    }
  }

  res.json({ ok: true });
});

app.listen(3001, () => {
  console.log("Server listening on http://localhost:3001");
});
```

