## 5) Repository for local CRUD

### `src/db/surveyRepo.ts`
```ts
import { v4 as uuidv4 } from 'uuid';
import { dbPromise } from './index';
import { Survey, SurveyInput } from '../types';
import { enqueueSyncAction } from './syncQueue';

export async function getAllSurveys(): Promise<Survey[]> {
  const db = await dbPromise;
  const [result] = await db.executeSql(
    `SELECT * FROM surveys WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );

  const rows: Survey[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    rows.push(result.rows.item(i));
  }
  return rows;
}

export async function getSurveyById(id: string): Promise<Survey | null> {
  const db = await dbPromise;
  const [result] = await db.executeSql(`SELECT * FROM surveys WHERE id = ?`, [id]);
  if (result.rows.length === 0) return null;
  return result.rows.item(0);
}

export async function createSurvey(input: SurveyInput): Promise<Survey> {
  const db = await dbPromise;
  const now = new Date().toISOString();
  const id = uuidv4();

  const survey: Survey = {
    id,
    ...input,
    createdAt: now,
    updatedAt: now,
    deletedAt: null,
    syncStatus: 'pending',
  };

  await db.executeSql(
    `INSERT INTO surveys (id, title, location, notes, latitude, longitude, createdAt, updatedAt, deletedAt, syncStatus)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      survey.id,
      survey.title,
      survey.location,
      survey.notes ?? null,
      survey.latitude ?? null,
      survey.longitude ?? null,
      survey.createdAt,
      survey.updatedAt,
      survey.deletedAt,
      survey.syncStatus,
    ]
  );

  await enqueueSyncAction('create', survey.id, survey);
  return survey;
}

export async function updateSurvey(id: string, input: Partial<SurveyInput>): Promise<Survey | null> {
  const existing = await getSurveyById(id);
  if (!existing) return null;

  const updated: Survey = {
    ...existing,
    ...input,
    updatedAt: new Date().toISOString(),
    syncStatus: 'pending',
  };

  const db = await dbPromise;
  await db.executeSql(
    `UPDATE surveys
     SET title = ?, location = ?, notes = ?, latitude = ?, longitude = ?, updatedAt = ?, syncStatus = ?
     WHERE id = ?`,
    [
      updated.title,
      updated.location,
      updated.notes ?? null,
      updated.latitude ?? null,
      updated.longitude ?? null,
      updated.updatedAt,
      updated.syncStatus,
      id,
    ]
  );

  await enqueueSyncAction('update', id, updated);
  return updated;
}

export async function deleteSurvey(id: string): Promise<boolean> {
  const existing = await getSurveyById(id);
  if (!existing) return false;

  const deletedAt = new Date().toISOString();
  const db = await dbPromise;

  await db.executeSql(
    `UPDATE surveys SET deletedAt = ?, updatedAt = ?, syncStatus = ? WHERE id = ?`,
    [deletedAt, deletedAt, 'pending', id]
  );

  await enqueueSyncAction('delete', id, { ...existing, deletedAt });
  return true;
}
