## 6) Sync queue

### `src/db/syncQueue.ts`
```ts
import { v4 as uuidv4 } from 'uuid';
import { dbPromise } from './index';
import { SyncActionType } from '../types';

export async function enqueueSyncAction(
  action: SyncActionType,
  entityId: string,
  payload: unknown
) {
  const db = await dbPromise;
  const itemId = uuidv4();

  await db.executeSql(
    `INSERT INTO sync_queue (id, entityType, entityId, action, payload, createdAt, attempts, lastError)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    [
      itemId,
      'survey',
      entityId,
      action,
      JSON.stringify(payload),
      new Date().toISOString(),
      0,
      null,
    ]
  );
}

export async function getPendingQueueItems() {
  const db = await dbPromise;
  const [result] = await db.executeSql(
    `SELECT * FROM sync_queue ORDER BY createdAt ASC`
  );

  const items: any[] = [];
  for (let i = 0; i < result.rows.length; i++) {
    items.push(result.rows.item(i));
  }
  return items;
}

export async function removeQueueItem(id: string) {
  const db = await dbPromise;
  await db.executeSql(`DELETE FROM sync_queue WHERE id = ?`, [id]);
}

export async function markQueueItemFailed(id: string, error: string) {
  const db = await dbPromise;
  await db.executeSql(
    `UPDATE sync_queue SET attempts = attempts + 1, lastError = ? WHERE id = ?`,
    [error, id]
  );
}
```

