## 8) Sync service

This example assumes a backend API with endpoints like:

- `POST /surveys`
- `PUT /surveys/:id`
- `DELETE /surveys/:id`

### `src/network/syncService.ts`
```ts
import { getPendingQueueItems, removeQueueItem, markQueueItemFailed } from '../db/syncQueue';
import { dbPromise } from '../db';
import { isOnline } from './connectivity';

const API_BASE = 'https://your-api.example.com';

async function sendToServer(action: string, payload: any) {
  const survey = payload;

  if (action === 'create') {
    const res = await fetch(`${API_BASE}/surveys`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(survey),
    });
    if (!res.ok) throw new Error(`Create failed: ${res.status}`);
    return res.json();
  }

  if (action === 'update') {
    const res = await fetch(`${API_BASE}/surveys/${survey.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(survey),
    });
    if (!res.ok) throw new Error(`Update failed: ${res.status}`);
    return res.json();
  }

  if (action === 'delete') {
    const res = await fetch(`${API_BASE}/surveys/${survey.id}`, {
      method: 'DELETE',
    });
    if (!res.ok) throw new Error(`Delete failed: ${res.status}`);
    return true;
  }

  throw new Error(`Unknown action: ${action}`);
}

export async function syncPendingChanges() {
  if (!(await isOnline())) return;

  const queue = await getPendingQueueItems();

  for (const item of queue) {
    try {
      const payload = JSON.parse(item.payload);
      await sendToServer(item.action, payload);

      await removeQueueItem(item.id);

      const db = await dbPromise;
      await db.executeSql(
        `UPDATE surveys SET syncStatus = ? WHERE id = ?`,
        ['synced', item.entityId]
      );
    } catch (err: any) {
      await markQueueItemFailed(item.id, err.message || 'Sync failed');

      const db = await dbPromise;
      await db.executeSql(
        `UPDATE surveys SET syncStatus = ? WHERE id = ?`,
        ['failed', item.entityId]
      );
    }
  }
}
```

