import React, { useCallback, useEffect, useState } from 'react';
import { View, Text, Button, FlatList, TouchableOpacity } from 'react-native';
import { Survey } from '../types';
import { getAllSurveys, deleteSurvey } from '../db/surveyRepo';
import { syncPendingChanges } from '../network/syncService';

export default function SurveyListScreen({ navigation }: any) {
  const [surveys, setSurveys] = useState<Survey[]>([]);

  const load = useCallback(async () => {
    setSurveys(await getAllSurveys());
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const handleSync = async () => {
    await syncPendingChanges();
    await load();
  };

  return (
    <View style={{ flex: 1, padding: 16 }}>
      <Button title="New Survey" onPress={() => navigation.navigate('SurveyForm')} />
      <Button title="Sync Now" onPress={handleSync} />

