import React, { useEffect, useState } from 'react';
import { View, Text } from 'react-native';
import SurveyForm from '../components/SurveyForm';
import { createSurvey, getSurveyById, updateSurvey } from '../db/surveyRepo';

export default function SurveyFormScreen({ route, navigation }: any) {
  const surveyId = route.params?.surveyId;
  const [initial, setInitial] = useState<any>(null);

  useEffect(() => {
    (async () => {
      if (surveyId) {
        const survey = await getSurveyById(surveyId);
        setInitial(survey);
      }
    })();
  }, [surveyId]);

  const handleSubmit = async (data: any) => {
    if (surveyId) {
      await updateSurvey(surveyId, data);
    } else {
      await createSurvey(data);
    }
    navigation.goBack();
  };

  if (surveyId && !initial) {
    return (
      <View style={{ padding: 16 }}>
        <Text>Loading...</Text>
      </View>
    );
  }

  return <SurveyForm initial={initial} onSubmit={handleSubmit} />;
}
