# 4) Local repository layer

This layer ensures the app can work offline without caring whether the server is reachable.

## `src/surveyRepository.ts`

```ts
import { v4 as uuidv4 } from "uuid";
import { db } from "./db";
import { Survey, SyncOperation } from "./types";

export class SurveyRepository {
  async listSurveys(): Promise<Survey[]> {
    return db.surveys.where("deleted").notEqual(1 as any).toArray();
  }

  async getSurvey(id: string): Promise<Survey | undefined> {
    return db.surveys.get(id);
  }

  async createSurvey(data: Omit<Survey, "id" | "createdAt" | "updatedAt" | "version">) {
    const now = new Date().toISOString();
    const survey: Survey = {
      id: uuidv4(),
      ...data,
      createdAt: now,
      updatedAt: now,
      version: 1,
    };

    await db.transaction("rw", db.surveys, db.syncQueue, async () => {
      await db.surveys.put(survey);
      const op: SyncOperation = {
        id: uuidv4(),
        entityType: "survey",
        entityId: survey.id,
        type: "create",
        payload: survey,
        createdAt: now,
        retries: 0,
      };
      await db.syncQueue.put(op);
    });

    return survey;
  }

  async updateSurvey(id: string, patch: Partial<Survey>) {
    const existing = await db.surveys.get(id);
    if (!existing) throw new Error("Survey not found");

    const now = new Date().toISOString();
    const updated: Survey = {
      ...existing,
      ...patch,
      updatedAt: now,
      version: existing.version + 1,
    };

    await db.transaction("rw", db.surveys, db.syncQueue, async () => {
      await db.surveys.put(updated);
      const op: SyncOperation = {
        id: uuidv4(),
        entityType: "survey",
        entityId: id,
        type: "update",
        payload: patch,
        createdAt: now,
        retries: 0,
      };
      await db.syncQueue.put(op);
    });

    return updated;
  }

  async deleteSurvey(id: string) {
    const existing = await db.surveys.get(id);
    if (!existing) throw new Error("Survey not found");

    const now = new Date().toISOString();
    const deleted: Survey = {
      ...existing,
      deleted: true,
      updatedAt: now,
      version: existing.version + 1,
    };

    await db.transaction("rw", db.surveys, db.syncQueue, async () => {
      await db.surveys.put(deleted);
      const op: SyncOperation = {
        id: uuidv4(),
        entityType: "survey",
        entityId: id,
        type: "delete",
        createdAt: now,
        retries: 0,
      };
      await db.syncQueue.put(op);
    });
  }

  async getPendingOperations(): Promise<SyncOperation[]> {
    return db.syncQueue.orderBy("createdAt").toArray();
  }

  async removePendingOperation(id: string) {
    await db.syncQueue.delete(id);
  }

  async clearQueue() {
    await db.syncQueue.clear();
  }
}

export const surveyRepository = new SurveyRepository();
```

