# 5) Sync service

This service:

- checks if online
- sends queued operations to server
- fetches remote updates
- resolves simple conflicts

---

## `src/syncService.ts`

```ts
import { db } from "./db";
import { surveyRepository } from "./surveyRepository";
import { Survey, SyncOperation } from "./types";

const API_BASE = "https://your-api.example.com";

async function apiFetch(path: string, options: RequestInit = {}) {
  const res = await fetch(`${API_BASE}${path}`, {
    headers: {
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
    ...options,
  });

  if (!res.ok) {
    throw new Error(`API error: ${res.status}`);
  }

  return res.json();
}

export class SyncService {
  private syncing = false;

  isOnline(): boolean {
    return navigator.onLine;
  }

  async syncNow() {
    if (this.syncing || !this.isOnline()) return;
    this.syncing = true;

    try {
      await this.pushQueue();
      await this.pullRemoteChanges();
      await db.meta.put({ key: "lastSyncAt", value: new Date().toISOString() });
    } finally {
      this.syncing = false;
    }
  }

  private async pushQueue() {
    const ops = await surveyRepository.getPendingOperations();

    for (const op of ops) {
      try {
        await this.pushOperation(op);
        await surveyRepository.removePendingOperation(op.id);
      } catch (err) {
        op.retries += 1;
        await db.syncQueue.put(op);
      }
    }
  }

  private async pushOperation(op: SyncOperation) {
    switch (op.type) {
      case "create":
        await apiFetch("/surveys", {
          method: "POST",
          body: JSON.stringify(op.payload),
        });
        break;

      case "update":
        await apiFetch(`/surveys/${op.entityId}`, {
          method: "PUT",
          body: JSON.stringify(op.payload),
        });
        break;

      case "delete":
        await apiFetch(`/surveys/${op.entityId}`, {
          method: "DELETE",
        });
        break;
    }
  }

  private async pullRemoteChanges() {
    const lastSyncAt = (await db.meta.get("lastSyncAt"))?.value;
    const remoteSurveys: Survey[] = await apiFetch(
      `/surveys/changes?since=${encodeURIComponent(lastSyncAt || "")}`
    );

    for (const remote of remoteSurveys) {
      const local = await db.surveys.get(remote.id);

      if (!local || new Date(remote.updatedAt) > new Date(local.updatedAt)) {
        await db.surveys.put(remote);
      }
    }
  }
}

export const syncService = new SyncService();
```

