## `server.ts`

```ts
import express from "express";
import cors from "cors";
import bodyParser from "body-parser";
import { v4 as uuidv4 } from "uuid";

type Survey = {
  id: string;
  title: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes?: string;
  status: "draft" | "submitted" | "reviewed";
  updatedAt: string;
  createdAt: string;
  deleted?: boolean;
  version: number;
};

const app = express();
app.use(cors());
app.use(bodyParser.json());

const surveys = new Map<string, Survey>();

app.post("/surveys", (req, res) => {
  const now = new Date().toISOString();
  const survey: Survey = {
    id: req.body.id || uuidv4(),
    title: req.body.title,
    siteName: req.body.siteName,
    latitude: req.body.latitude,
    longitude: req.body.longitude,
    notes: req.body.notes,
    status: req.body.status || "draft",
    createdAt: req.body.createdAt || now,
    updatedAt: now,
    version: 1,
  };

  surveys.set(survey.id, survey);
  res.json(survey);
});

app.put("/surveys/:id", (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).json({ error: "Not found" });

  const updated: Survey = {
    ...existing,
    ...req.body,
    id: existing.id,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  surveys.set(updated.id, updated);
  res.json(updated);
});

app.delete("/surveys/:id", (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).json({ error: "Not found" });

  const deleted: Survey = {
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  surveys.set(deleted.id, deleted);
  res.json({ success: true });
});

app.get("/surveys/changes", (req, res) => {
  const since = req.query.since ? new Date(String(req.query.since)) : new Date(0);

  const changed = Array.from(surveys.values()).filter(
    (s) => new Date(s.updatedAt) > since
  );

  res.json(changed);
});

app.listen(3001, () => {
  console.log("API running on http://localhost:3001");
});
```

