## Create/update survey locally

```ts
// surveyService.ts
import { db, Survey, OutboxItem } from './db';
import { v4 as uuidv4 } from 'uuid';

export async function saveSurveyOffline(
  survey: Partial<Survey> & { id?: string },
  operation: 'create' | 'update'
) {
  const now = new Date().toISOString();
  const id = survey.id ?? uuidv4();

  const existing = await db.surveys.get(id);
  const version = existing?.version ?? 0;

  const record: Survey = {
    id,
    projectId: survey.projectId!,
    title: survey.title ?? existing?.title ?? '',
    location: survey.location ?? existing?.location ?? { lat: 0, lng: 0 },
    answers: survey.answers ?? existing?.answers ?? {},
    notes: survey.notes ?? existing?.notes,
    photos: survey.photos ?? existing?.photos ?? [],
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
    deletedAt: null,
    version,
    syncStatus: 'pending'
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.put(record);

    const outboxItem: OutboxItem = {
      id: uuidv4(),
      entityType: 'survey',
      entityId: id,
      operation,
      payload: record,
      baseVersion: version,
      createdAt: now,
      retries: 0
    };

    await db.outbox.add(outboxItem);
  });

  return record;
}
```

