## Sync queued changes

```ts
// syncService.ts
import { db } from './db';

export async function syncOutbox() {
  const items = await db.outbox.orderBy('createdAt').toArray();
  if (!items.length) return;

  const response = await fetch('/api/sync', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({
      deviceId: getDeviceId(),
      items
    })
  });

  if (!response.ok) {
    throw new Error(`Sync failed: ${response.status}`);
  }

  const result = await response.json();

  for (const itemResult of result.results) {
    const outboxItem = items.find(i => i.id === itemResult.outboxId);
    if (!outboxItem) continue;

    if (itemResult.status === 'ok') {
      await db.outbox.delete(outboxItem.id);

      if (itemResult.serverRecord) {
        await db.surveys.update(outboxItem.entityId, {
          ...itemResult.serverRecord,
          syncStatus: 'synced'
        });
      }
    } else if (itemResult.status === 'conflict') {
      await db.surveys.update(outboxItem.entityId, {
        syncStatus: 'conflict'
      });

      await db.outbox.update(outboxItem.id, {
        retries: outboxItem.retries + 1,
        lastError: 'Version conflict'
      });
    } else {
      await db.outbox.update(outboxItem.id, {
        retries: outboxItem.retries + 1,
        lastError: itemResult.error ?? 'Unknown error'
      });
    }
  }
}
```

