# 9) Backend initial implementation

## Express sync endpoint

```ts
// server.ts
import express from 'express';

const app = express();
app.use(express.json());

type SyncItem = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
  baseVersion: number;
};

const surveys = new Map<string, any>();

app.post('/api/sync', (req, res) => {
  const items: SyncItem[] = req.body.items ?? [];

  const results = items.map(item => {
    const existing = surveys.get(item.entityId);

    if (item.operation === 'create') {
      if (existing) {
        return {
          outboxId: item.id,
          status: 'conflict',
          error: 'Survey already exists',
          serverRecord: existing
        };
      }

      const created = {
        ...item.payload,
        version: 1,
        updatedAt: new Date().toISOString()
      };
      surveys.set(item.entityId, created);

      return {
        outboxId: item.id,
        status: 'ok',
        serverRecord: created
      };
    }

    if (!existing) {
      return {
        outboxId: item.id,
        status: 'conflict',
        error: 'Survey not found'
      };
    }

    if (existing.version !== item.baseVersion) {
      return {
        outboxId: item.id,
        status: 'conflict',
        error: 'Version conflict',
        serverRecord: existing
      };
    }

    if (item.operation === 'update') {
      const updated = {
        ...existing,
        ...item.payload,
        version: existing.version + 1,
        updatedAt: new Date().toISOString()
      };
      surveys.set(item.entityId, updated);

      return {
        outboxId: item.id,
        status: 'ok',
        serverRecord: updated
      };
    }

    if (item.operation === 'delete') {
      surveys.delete(item.entityId);
      return {
        outboxId: item.id,
        status: 'ok'
      };
    }

    return {
      outboxId: item.id,
      status: 'error',
      error: 'Unsupported operation'
    };
  });

  res.json({ results });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

