## 3.2 IndexedDB schema

**`client/src/db/index.ts`**

```ts
import Dexie, { Table } from "dexie";

export interface SurveyRecord {
  id: string;
  siteId: string;
  observerName: string;
  latitude: number;
  longitude: number;
  notes?: string;
  createdAt: string;
  updatedAt: string;
  deletedAt?: string | null;
  version: number;
  syncStatus: "synced" | "pending" | "error";
}

export interface PendingMutation {
  id: string;
  entityType: "survey";
  entityId: string;
  operation: "create" | "update" | "delete";
  payload: Partial<SurveyRecord>;
  createdAt: string;
  retryCount: number;
}

class SurveyDB extends Dexie {
  surveys!: Table<SurveyRecord, string>;
  pendingMutations!: Table<PendingMutation, string>;

  constructor() {
    super("SurveyDB");
    this.version(1).stores({
      surveys: "id, updatedAt, syncStatus, deletedAt",
      pendingMutations: "id, entityType, entityId, createdAt, retryCount",
    });
  }
}

export const db = new SurveyDB();
```

