const API_BASE = "http://localhost:4000/api";

export async function fetchSurveys(since?: string) {
  const url = since ? `${API_BASE}/surveys?since=${encodeURIComponent(since)}` : `${API_BASE}/surveys`;
  const res = await fetch(url, { credentials: "include" });
  if (!res.ok) throw new Error("Failed to fetch surveys");
  return res.json();
}

export async function pushMutations(mutations: any[]) {
  const res = await fetch(`${API_BASE}/sync`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    credentials: "include",
    body: JSON.stringify({ mutations }),
  });
  if (!res.ok) throw new Error("Failed to sync mutations");
  return res.json();
}
