## 3.4 Sync manager

**`client/src/sync/syncManager.ts`**

```ts
import { db, PendingMutation, SurveyRecord } from "../db";
import { fetchSurveys, pushMutations } from "../api/client";

let syncing = false;

export async function saveSurveyOffline(input: Omit<SurveyRecord, "version" | "syncStatus" | "createdAt" | "updatedAt">) {
  const now = new Date().toISOString();

  const record: SurveyRecord = {
    ...input,
    createdAt: now,
    updatedAt: now,
    version: 1,
    syncStatus: "pending",
  };

  await db.transaction("rw", db.surveys, db.pendingMutations, async () => {
    await db.surveys.put(record);

    const mutation: PendingMutation = {
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: record.id,
      operation: "create",
      payload: record,
      createdAt: now,
      retryCount: 0,
    };

    await db.pendingMutations.add(mutation);
  });

  return record;
}

export async function updateSurveyOffline(id: string, changes: Partial<SurveyRecord>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found");

  const now = new Date().toISOString();
  const updated: SurveyRecord = {
    ...existing,
    ...changes,
    updatedAt: now,
    version: existing.version + 1,
    syncStatus: "pending",
  };

  await db.transaction("rw", db.surveys, db.pendingMutations, async () => {
    await db.surveys.put(updated);

    const mutation: PendingMutation = {
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: id,
      operation: "update",
      payload: changes,
      createdAt: now,
      retryCount: 0,
    };

    await db.pendingMutations.add(mutation);
  });

  return updated;
}

export async function deleteSurveyOffline(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const now = new Date().toISOString();
  const updated: SurveyRecord = {
    ...existing,
    deletedAt: now,
    updatedAt: now,
    version: existing.version + 1,
    syncStatus: "pending",
  };

  await db.transaction("rw", db.surveys, db.pendingMutations, async () => {
    await db.surveys.put(updated);

    const mutation: PendingMutation = {
      id: crypto.randomUUID(),
      entityType: "survey",
      entityId: id,
      operation: "delete",
      payload: { deletedAt: now },
      createdAt: now,
      retryCount: 0,
    };

    await db.pendingMutations.add(mutation);
  });
}

export async function syncNow() {
  if (syncing) return;
  syncing = true;

  try {
    const pending = await db.pendingMutations.orderBy("createdAt").toArray();

    if (pending.length > 0) {
      const result = await pushMutations(pending);

      // Mark local records as synced
      for (const mutation of pending) {
        const record = await db.surveys.get(mutation.entityId);
        if (record) {
          await db.surveys.update(record.id, { syncStatus: "synced" });
        }
      }

      await db.pendingMutations.clear();

      // Pull latest server state
      const serverSurveys = await fetchSurveys(result.lastSyncAt);
      for (const s of serverSurveys) {
        await db.surveys.put({
          ...s,
          syncStatus: "synced",
        });
      }
    }
  } catch (err) {
    console.error("Sync failed:", err);

    const pending = await db.pendingMutations.toArray();
    for (const m of pending) {
      await db.pendingMutations.update(m.id, { retryCount: m.retryCount + 1 });
    }
  } finally {
    syncing = false;
  }
}

export function startAutoSync() {
  window.addEventListener("online", () => syncNow());
  setInterval(() => {
    if (navigator.onLine) syncNow();
  }, 15000);
}
```

