```tsx
import React, { useEffect, useState } from "react";
import { db, SurveyRecord } from "./db";
import { SurveyForm } from "./components/SurveyForm";
import { SurveyList } from "./components/SurveyList";
import { deleteSurveyOffline, startAutoSync, syncNow } from "./sync/syncManager";

export default function App() {
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [online, setOnline] = useState(navigator.onLine);

  async function refresh() {
    const items = await db.surveys.where("deletedAt").equals(null as any).toArray();
    setSurveys(items);
  }

  useEffect(() => {
    refresh();
    startAutoSync();

    const onOnline = () => setOnline(true);
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ padding: 16 }}>
      <h1>Field Survey App</h1>
      <p>Status: {online ? "Online" : "Offline"}</p>
      <button onClick={syncNow}>Sync Now</button>

      <SurveyForm onSaved={refresh} />
      <SurveyList
        surveys={surveys}
        onDelete={async (id) => {
          await deleteSurveyOffline(id);
          await refresh();
        }}
      />
    </div>
  );
}
```

