## 4.4 Sync routes

**`server/src/routes/surveys.ts`**

```ts
import { Router } from "express";

export const surveysRouter = Router();

let surveys: any[] = [];
let lastSyncAt = new Date().toISOString();

surveysRouter.get("/surveys", (req, res) => {
  const since = req.query.since as string | undefined;

  if (!since) {
    return res.json(surveys.filter((s) => !s.deleted_at));
  }

  const changed = surveys.filter((s) => s.updated_at > since);
  res.json(changed);
});

surveysRouter.post("/sync", (req, res) => {
  const mutations = req.body.mutations || [];

  for (const m of mutations) {
    if (m.entityType !== "survey") continue;

    if (m.operation === "create") {
      const payload = m.payload;
      surveys.push({
        id: payload.id,
        site_id: payload.siteId,
        observer_name: payload.observerName,
        latitude: payload.latitude,
        longitude: payload.longitude,
        notes: payload.notes,
        created_at: payload.createdAt,
        updated_at: new Date().toISOString(),
        deleted_at: null,
        version: 1,
      });
    }

    if (m.operation === "update") {
      const idx = surveys.findIndex((s) => s.id === m.entityId);
      if (idx >= 0) {
        surveys[idx] = {
          ...surveys[idx],
          ...m.payload,
          updated_at: new Date().toISOString(),
          version: (surveys[idx].version || 1) + 1,
        };
      }
    }

    if (m.operation === "delete") {
      const idx = surveys.findIndex((s) => s.id === m.entityId);
      if (idx >= 0) {
        surveys[idx].deleted_at = new Date().toISOString();
        surveys[idx].updated_at = new Date().toISOString();
        surveys[idx].version = (surveys[idx].version || 1) + 1;
      }
    }
  }

  lastSyncAt = new Date().toISOString();
  res.json({ ok: true, lastSyncAt });
});
```

