## B. Local repository

This example uses a generic DB wrapper.

```ts
export class SurveyRepository {
  constructor(private db: any) {}

  async createSurvey(data: {
    id: string;
    title: string;
    location?: string;
    notes?: string;
  }) {
    const now = new Date().toISOString();

    await this.db.transaction(async (tx: any) => {
      await tx.run(
        `INSERT INTO surveys (id, title, location, notes, status, version, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [data.id, data.title, data.location ?? null, data.notes ?? null, 'draft', 0, now, now]
      );

      await tx.run(
        `INSERT INTO pending_mutations
         (id, entity_type, entity_id, operation, payload, base_version, created_at, retry_count)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          crypto.randomUUID(),
          'survey',
          data.id,
          'create',
          JSON.stringify(data),
          0,
          now,
          0,
        ]
      );
    });
  }

  async updateSurvey(id: string, patch: Partial<{ title: string; location: string; notes: string }>) {
    const now = new Date().toISOString();
    const survey = await this.getSurvey(id);
    if (!survey) throw new Error('Survey not found');

    const updated = { ...survey, ...patch, updated_at: now, version: survey.version };

    await this.db.transaction(async (tx: any) => {
      await tx.run(
        `UPDATE surveys SET title = ?, location = ?, notes = ?, updated_at = ? WHERE id = ?`,
        [updated.title, updated.location ?? null, updated.notes ?? null, now, id]
      );

      await tx.run(
        `INSERT INTO pending_mutations
         (id, entity_type, entity_id, operation, payload, base_version, created_at, retry_count)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          crypto.randomUUID(),
          'survey',
          id,
          'update',
          JSON.stringify(patch),
          survey.version,
          now,
          0,
        ]
      );
    });
  }

  async getSurvey(id: string) {
    return this.db.get(`SELECT * FROM surveys WHERE id = ? AND deleted_at IS NULL`, [id]);
  }

  async listSurveys() {
    return this.db.all(`SELECT * FROM surveys WHERE deleted_at IS NULL ORDER BY updated_at DESC`);
  }
}
```

