## C. Sync engine

```ts
export class SyncEngine {
  constructor(
    private db: any,
    private api: {
      pushMutation: (mutation: any) => Promise<any>;
      fetchSurvey: (id: string) => Promise<any>;
    }
  ) {}

  async syncPendingMutations() {
    const mutations = await this.db.all(
      `SELECT * FROM pending_mutations ORDER BY created_at ASC`
    );

    for (const mutation of mutations) {
      try {
        const payload = JSON.parse(mutation.payload);

        const result = await this.api.pushMutation({
          entityType: mutation.entity_type,
          entityId: mutation.entity_id,
          operation: mutation.operation,
          payload,
          baseVersion: mutation.base_version,
        });

        await this.db.transaction(async (tx: any) => {
          if (result.entity) {
            await tx.run(
              `UPDATE surveys
               SET title = ?, location = ?, notes = ?, status = ?, version = ?, updated_at = ?, deleted_at = ?
               WHERE id = ?`,
              [
                result.entity.title,
                result.entity.location ?? null,
                result.entity.notes ?? null,
                result.entity.status,
                result.entity.version,
                result.entity.updatedAt,
                result.entity.deletedAt ?? null,
                mutation.entity_id,
              ]
            );
          }

          await tx.run(`DELETE FROM pending_mutations WHERE id = ?`, [mutation.id]);
        });
      } catch (error: any) {
        await this.db.run(
          `UPDATE pending_mutations
           SET retry_count = retry_count + 1, last_error = ?
           WHERE id = ?`,
          [error.message ?? 'Sync failed', mutation.id]
        );
      }
    }
  }
}
```

