## 11) Minimal backend mutation handler

```ts
app.post('/sync/mutations', async (req, res) => {
  const { entityType, entityId, operation, payload, baseVersion } = req.body;

  if (entityType !== 'survey') {
    return res.status(400).json({ error: 'Unsupported entity type' });
  }

  const survey = await db.surveys.findById(entityId);

  if (operation === 'create') {
    if (survey) return res.status(409).json({ error: 'ALREADY_EXISTS' });

    const created = await db.surveys.create({
      id: entityId,
      ...payload,
      version: 1,
    });

    return res.json({ entity: created });
  }

  if (!survey) return res.status(404).json({ error: 'NOT_FOUND' });

  if (survey.version !== baseVersion) {
    return res.status(409).json({
      error: 'VERSION_CONFLICT',
      serverEntity: survey,
    });
  }

  const updated = await db.surveys.update(entityId, {
    ...payload,
    version: survey.version + 1,
  });

  return res.json({ entity: updated });
});
```

