import Dexie, { Table } from "dexie";

export type SyncStatus = "synced" | "pending" | "failed";

export interface Survey {
  id: string;
  name: string;
  location: string;
  status: string;
  createdAt: string;
  updatedAt: string;
  syncStatus: SyncStatus;
  deleted?: boolean;
}

export interface Observation {
  id: string;
  surveyId: string;
  type: string;
  value: string;
  notes?: string;
  createdAt: string;
  updatedAt: string;
  syncStatus: SyncStatus;
  deleted?: boolean;
}

export interface OutboxItem {
  id?: number;
  entityType: "survey" | "observation";
  entityId: string;
  operation: "create" | "update" | "delete";
  payload: any;
  createdAt: string;
  retryCount: number;
}

class SurveyDB extends Dexie {
  surveys!: Table<Survey, string>;
  observations!: Table<Observation, string>;
  outbox!: Table<OutboxItem, number>;

  constructor() {
    super("SurveyDB");
    this.version(1).stores({
      surveys: "id, updatedAt, syncStatus, deleted",
      observations: "id, surveyId, updatedAt, syncStatus, deleted",
      outbox: "++id, entityType, entityId, operation, createdAt",
    });
  }
}

export const db = new SurveyDB();
