## `src/sync.ts` — sync engine

```ts
import { db, OutboxItem, Survey, Observation } from "./db";
import api from "./api";

export async function enqueueSurveyMutation(
  operation: "create" | "update" | "delete",
  survey: Survey
) {
  await db.surveys.put({
    ...survey,
    syncStatus: navigator.onLine ? "synced" : "pending",
  });

  if (!navigator.onLine) {
    await db.outbox.add({
      entityType: "survey",
      entityId: survey.id,
      operation,
      payload: survey,
      createdAt: new Date().toISOString(),
      retryCount: 0,
    });
  } else {
    await db.outbox.add({
      entityType: "survey",
      entityId: survey.id,
      operation,
      payload: survey,
      createdAt: new Date().toISOString(),
      retryCount: 0,
    });
    await syncNow();
  }
}

export async function enqueueObservationMutation(
  operation: "create" | "update" | "delete",
  observation: Observation
) {
  await db.observations.put({
    ...observation,
    syncStatus: navigator.onLine ? "synced" : "pending",
  });

  await db.outbox.add({
    entityType: "observation",
    entityId: observation.id,
    operation,
    payload: observation,
    createdAt: new Date().toISOString(),
    retryCount: 0,
  });

  if (navigator.onLine) {
    await syncNow();
  }
}

export async function syncNow() {
  if (!navigator.onLine) return;

  const items = await db.outbox.orderBy("createdAt").toArray();

  for (const item of items) {
    try {
      await sendOutboxItem(item);
      if (item.id) await db.outbox.delete(item.id);

      if (item.entityType === "survey") {
        await db.surveys.update(item.entityId, { syncStatus: "synced" });
      } else {
        await db.observations.update(item.entityId, { syncStatus: "synced" });
      }
    } catch (err) {
      if (item.id) {
        await db.outbox.update(item.id, {
          retryCount: item.retryCount + 1,
        });
      }
    }
  }

  await pullRemoteChanges();
}

async function sendOutboxItem(item: OutboxItem) {
  const endpoint =
    item.entityType === "survey" ? "/sync/surveys" : "/sync/observations";

  await api.post(endpoint, {
    operation: item.operation,
    payload: item.payload,
    clientMutationId: `${item.entityType}-${item.entityId}-${item.createdAt}`,
  });
}

export async function pullRemoteChanges() {
  const lastSync = localStorage.getItem("lastSyncAt") || "1970-01-01T00:00:00.000Z";

  const res = await api.get("/sync/pull", {
    params: { since: lastSync },
  });

  const { surveys = [], observations = [], serverTime } = res.data;

  for (const survey of surveys) {
    await db.surveys.put({
      ...survey,
      syncStatus: "synced",
    });
  }

  for (const obs of observations) {
    await db.observations.put({
      ...obs,
      syncStatus: "synced",
    });
  }

  localStorage.setItem("lastSyncAt", serverTime || new Date().toISOString());
}

export function startSyncListeners() {
  window.addEventListener("online", () => syncNow());
  setInterval(() => {
    if (navigator.onLine) syncNow();
  }, 30000);
}
```

