import React, { useEffect, useState } from "react";
import { db, Survey } from "./db";
import { enqueueSurveyMutation, startSyncListeners, syncNow } from "./sync";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");

  async function refresh() {
    const all = await db.surveys.orderBy("updatedAt").reverse().toArray();
    setSurveys(all);
  }

  useEffect(() => {
    refresh();
    startSyncListeners();
  }, []);

  async function addSurvey() {
    const now = new Date().toISOString();
    const survey: Survey = {
      id: uuid(),
      name,
      location,
      status: "draft",
      createdAt: now,
      updatedAt: now,
      syncStatus: navigator.onLine ? "synced" : "pending",
    };

    await enqueueSurveyMutation("create", survey);
    setName("");
    setLocation("");
    await refresh();
  }

  async function markComplete(id: string) {
    const survey = await db.surveys.get(id);
    if (!survey) return;

    const updated = {
      ...survey,
      status: "complete",
      updatedAt: new Date().toISOString(),
      syncStatus: navigator.onLine ? "synced" : "pending",
    };

    await enqueueSurveyMutation("update", updated);
    await refresh();
  }

  async function forceSync() {
    await syncNow();
    await refresh();
  }

  return (
    <div style={{ padding: 24, fontFamily: "sans-serif" }}>
      <h1>Field Survey App</h1>
      <p>
        Network: <b>{navigator.onLine ? "Online" : "Offline"}</b>
