## `server.ts` — Express API

```ts
import express from "express";
import cors from "cors";
import { Pool } from "pg";

const app = express();
app.use(cors());
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
});

app.get("/api/health", (_req, res) => {
  res.json({ ok: true });
});

app.post("/api/sync/surveys", async (req, res) => {
  const { operation, payload, clientMutationId } = req.body;

  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    const existing = await client.query(
      "SELECT 1 FROM client_mutations WHERE client_mutation_id = $1",
      [clientMutationId]
    );
    if (existing.rowCount) {
      await client.query("COMMIT");
      return res.json({ ok: true, deduped: true });
    }

    if (operation === "create" || operation === "update") {
      await client.query(
        `
        INSERT INTO surveys (id, name, location, status, created_at, updated_at, deleted)
        VALUES ($1, $2, $3, $4, $5, $6, FALSE)
        ON CONFLICT (id) DO UPDATE SET
          name = EXCLUDED.name,
          location = EXCLUDED.location,
          status = EXCLUDED.status,
          updated_at = EXCLUDED.updated_at,
          deleted = FALSE
        `,
        [
          payload.id,
          payload.name,
          payload.location,
          payload.status,
          payload.createdAt,
          payload.updatedAt,
        ]
      );
    } else if (operation === "delete") {
      await client.query(
        `UPDATE surveys SET deleted = TRUE, updated_at = NOW() WHERE id = $1`,
        [payload.id]
      );
    }

    await client.query(
      `INSERT INTO client_mutations (client_mutation_id, entity_type, entity_id, operation)
       VALUES ($1, $2, $3, $4)`,
      [clientMutationId, "survey", payload.id, operation]
    );

    await client.query("COMMIT");
    res.json({ ok: true });
  } catch (e) {
    await client.query("ROLLBACK");
    res.status(500).json({ error: "sync failed" });
  } finally {
    client.release();
  }
});

app.post("/api/sync/observations", async (req, res) => {
  const { operation, payload, clientMutationId } = req.body;

  const client = await pool.connect();
  try {
    await client.query("BEGIN");

    const existing = await client.query(
      "SELECT 1 FROM client_mutations WHERE client_mutation_id = $1",
      [clientMutationId]
    );
    if (existing.rowCount) {
