## `src/sync.ts`
Sync engine.

```ts
import { db, OutboxItem, SurveyRecord } from "./db";
import { fetchSurveys, pushMutation } from "./api";

export async function syncNow() {
  if (!navigator.onLine) return;

  // 1. Push local mutations
  const outboxItems = await db.outbox.orderBy("createdAt").toArray();

  for (const item of outboxItems) {
    try {
      await pushMutation(item);

      await db.outbox.delete(item.id);

      const local = await db.surveys.get(item.entityId);
      if (local) {
        await db.surveys.update(item.entityId, {
          syncStatus: "synced",
          updatedAt: new Date().toISOString(),
        });
      }
    } catch (error: any) {
      await db.outbox.update(item.id, {
        attempts: item.attempts + 1,
        lastError: error?.message || "Sync failed",
      });
    }
  }

  // 2. Pull latest server state
  const remoteSurveys = await fetchSurveys();

  // 3. Merge remote into local
  for (const remote of remoteSurveys) {
    const local = await db.surveys.get(remote.id);

    if (!local) {
      await db.surveys.put({
        ...remote,
        syncStatus: "synced",
      });
      continue;
    }

    // Simple last-write-wins merge
    if (new Date(remote.updatedAt) > new Date(local.updatedAt)) {
      await db.surveys.put({
        ...remote,
        syncStatus: "synced",
      });
    }
  }
}
```

