```ts
import { db, SurveyRecord, OutboxItem } from "./db";

function uuid() {
  return crypto.randomUUID();
}

export async function createSurvey(input: Omit<SurveyRecord, "id" | "updatedAt" | "syncStatus">) {
  const id = uuid();
  const now = new Date().toISOString();

  const record: SurveyRecord = {
    id,
    ...input,
    updatedAt: now,
    syncStatus: "pending",
  };

  const outboxItem: OutboxItem = {
    id: uuid(),
    entityType: "survey",
    entityId: id,
    operation: "create",
    payload: record,
    createdAt: now,
    attempts: 0,
  };

  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(record);
    await db.outbox.put(outboxItem);
  });

  return record;
}

export async function updateSurvey(id: string, changes: Partial<SurveyRecord>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found");

  const updated: SurveyRecord = {
    ...existing,
    ...changes,
    updatedAt: new Date().toISOString(),
    syncStatus: "pending",
  };

  const outboxItem: OutboxItem = {
    id: uuid(),
    entityType: "survey",
    entityId: id,
    operation: "update",
    payload: changes,
    createdAt: updated.updatedAt,
    attempts: 0,
  };

  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.put(updated);
    await db.outbox.put(outboxItem);
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found");

  const now = new Date().toISOString();

  const outboxItem: OutboxItem = {
    id: uuid(),
    entityType: "survey",
    entityId: id,
    operation: "delete",
    payload: { deleted: true },
    createdAt: now,
    attempts: 0,
  };

  await db.transaction("rw", db.surveys, db.outbox, async () => {
    await db.surveys.update(id, {
      deleted: true,
      updatedAt: now,
      syncStatus: "pending",
    });
    await db.outbox.put(outboxItem);
  });
}
```

