```ts
import express from "express";
import cors from "cors";
import bodyParser from "body-parser";
import { randomUUID } from "crypto";

const app = express();
app.use(cors());
app.use(bodyParser.json());

type Survey = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes?: string;
  status: "draft" | "submitted" | "synced";
  updatedAt: string;
  deleted?: boolean;
};

const surveys = new Map<string, Survey>();

app.get("/api/surveys", (_req, res) => {
  res.json(Array.from(surveys.values()).filter((s) => !s.deleted));
});

app.post("/api/surveys", (req, res) => {
  const id = req.body.id || randomUUID();
  const survey: Survey = {
    id,
    siteName: req.body.siteName,
    latitude: req.body.latitude ?? 0,
    longitude: req.body.longitude ?? 0,
    notes: req.body.notes ?? "",
    status: req.body.status ?? "draft",
    updatedAt: req.body.updatedAt || new Date().toISOString(),
    deleted: false,
  };

  surveys.set(id, survey);
  res.status(201).json(survey);
});

app.put("/api/surveys/:id", (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).json({ error: "Not found" });

  const updated: Survey = {
    ...existing,
    ...req.body,
    updatedAt: new Date().toISOString(),
  };

  surveys.set(req.params.id, updated);
  res.json(updated);
});

app.delete("/api/surveys/:id", (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).json({ error: "Not found" });

  surveys.set(req.params.id, {
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
  });

  res.status(204).send();
});

app.listen(3001, () => {
  console.log("API running on http://localhost:3001");
});
```

