};

export type SyncMutation = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
  baseVersion?: number;
  createdAt: string;
  status: 'pending' | 'sent' | 'failed';
};

class FieldSurveyDB extends Dexie {
  surveys!: Table<SurveyRecord, string>;
  syncQueue!: Table<SyncMutation, string>;
  meta!: Table<{ key: string; value: any }, string>;

  constructor() {
    super('FieldSurveyDB');
    this.version(1).stores({
      surveys: 'id, projectId, updatedAt, version, deletedAt',
      syncQueue: 'id, entityType, entityId, status, createdAt',
      meta: 'key',
    });
  }
}

export const db = new FieldSurveyDB();
