```ts
// surveyRepository.ts
import { db, SurveyRecord, SyncMutation } from './db';
import { v4 as uuidv4 } from 'uuid';

export async function createSurvey(input: Omit<SurveyRecord, 'id' | 'createdAt' | 'updatedAt' | 'version'>) {
  const now = new Date().toISOString();
  const survey: SurveyRecord = {
    ...input,
    id: uuidv4(),
    createdAt: now,
    updatedAt: now,
    version: 0,
  };

  const mutation: SyncMutation = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: survey.id,
    operation: 'create',
    payload: survey,
    baseVersion: 0,
    createdAt: now,
    status: 'pending',
  };

  await db.transaction('rw', db.surveys, db.syncQueue, async () => {
    await db.surveys.put(survey);
    await db.syncQueue.put(mutation);
  });

  return survey;
}

export async function updateSurvey(id: string, changes: Partial<SurveyRecord>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const updated: SurveyRecord = {
    ...existing,
    ...changes,
    updatedAt: now,
  };

  const mutation: SyncMutation = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: changes,
    baseVersion: existing.version,
    createdAt: now,
    status: 'pending',
  };

  await db.transaction('rw', db.surveys, db.syncQueue, async () => {
    await db.surveys.put(updated);
    await db.syncQueue.put(mutation);
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const now = new Date().toISOString();
  const deleted = { ...existing, deletedAt: now, updatedAt: now };

  const mutation: SyncMutation = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { deletedAt: now },
    baseVersion: existing.version,
    createdAt: now,
    status: 'pending',
  };

  await db.transaction('rw', db.surveys, db.syncQueue, async () => {
    await db.surveys.put(deleted);
    await db.syncQueue.put(mutation);
  });
}
