## 4.4 Sync service

This service:
- checks connectivity
- sends pending mutations
- pulls server changes
- updates local DB
- stores last sync token

```ts
// syncService.ts
import { db, SyncMutation, SurveyRecord } from './db';

const API_BASE = 'https://your-api.example.com';

async function getAuthToken() {
  return localStorage.getItem('token') || '';
}

export async function syncNow() {
  if (!navigator.onLine) return;

  const token = await getAuthToken();
  if (!token) return;

  const lastSync = (await db.meta.get('lastSyncToken'))?.value || null;
  const pending = await db.syncQueue.where('status').equals('pending').toArray();

  // 1) Push pending mutations
  if (pending.length > 0) {
    const res = await fetch(`${API_BASE}/sync/push`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${token}`,
      },
      body: JSON.stringify({ mutations: pending }),
    });

    if (!res.ok) throw new Error('Push sync failed');

    const result = await res.json();
    // result.acknowledged: [{ mutationId, entityId, serverVersion }]
    for (const ack of result.acknowledged) {
      const mutation = pending.find(m => m.id === ack.mutationId);
      if (mutation) {
        await db.syncQueue.delete(mutation.id);
        const local = await db.surveys.get(ack.entityId);
        if (local) {
          await db.surveys.put({
            ...local,
            version: ack.serverVersion,
            updatedAt: new Date().toISOString(),
          });
        }
      }
    }
  }

  // 2) Pull remote changes
  const pullRes = await fetch(`${API_BASE}/sync/pull?since=${encodeURIComponent(lastSync ?? '')}`, {
    headers: { Authorization: `Bearer ${token}` },
  });

  if (!pullRes.ok) throw new Error('Pull sync failed');

  const pullData = await pullRes.json();
  const changes: SurveyRecord[] = pullData.changes || [];
  const newToken = pullData.syncToken;

  await db.transaction('rw', db.surveys, db.meta, async () => {
    for (const remote of changes) {
      const local = await db.surveys.get(remote.id);

      // Simple conflict handling:
      // if local is missing or older, accept remote
      if (!local || remote.version >= local.version) {
        await db.surveys.put(remote);
      }
    }

    await db.meta.put({ key: 'lastSyncToken', value: newToken });
  });
}

export function startSyncListeners() {
  window.addEventListener('online', () => {
    syncNow().catch(console.error);
  });

  // periodic sync while online
  setInterval(() => {
    if (navigator.onLine) {
      syncNow().catch(console.error);
    }
  }, 30000);
}
```

