### `src/sync.ts`
```ts
import { db } from "./db";
import { fetchChanges, pushMutation } from "./api";

const LAST_SYNC_KEY = "lastSyncAt";

export async function getLastSyncAt(): Promise<string> {
  const item = await db.meta.get(LAST_SYNC_KEY);
  return item?.value ?? "1970-01-01T00:00:00.000Z";
}

export async function setLastSyncAt(value: string) {
  await db.meta.put({ key: LAST_SYNC_KEY, value });
}

export async function syncNow() {
  if (!navigator.onLine) return;

  // 1) Push pending mutations
  const pending = await db.mutations.orderBy("createdAt").toArray();
  for (const mutation of pending) {
    try {
      await pushMutation(mutation);
      await db.mutations.delete(mutation.id);
    } catch (err) {
      const retries = mutation.retries + 1;
      await db.mutations.put({ ...mutation, retries });
      // Stop on first failure to avoid hammering server
      break;
    }
  }

  // 2) Pull remote changes
  const lastSyncAt = await getLastSyncAt();
  const changes = await fetchChanges(lastSyncAt);

  await db.transaction("rw", db.surveys, db.meta, async () => {
    for (const remote of changes.surveys) {
      const local = await db.surveys.get(remote.id);

      if (!local || remote.version >= local.version) {
        await db.surveys.put({ ...remote, syncStatus: "synced" });
      } else {
        // Local newer than remote => keep local, mark conflict
        await db.surveys.put({ ...local, syncStatus: "conflict" });
      }
    }

    await setLastSyncAt(changes.serverTime);
  });
}
```

