import React, { useEffect, useState } from "react";
import { db, SurveyRecord, PendingMutation } from "./db";
import { syncNow } from "./sync";
import { useOnlineStatus } from "./hooks/useOnlineStatus";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const online = useOnlineStatus();
  const [surveys, setSurveys] = useState<SurveyRecord[]>([]);
  const [siteName, setSiteName] = useState("");
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [notes, setNotes] = useState("");

  async function loadSurveys() {
    const items = await db.surveys.orderBy("updatedAt").reverse().toArray();
    setSurveys(items);
  }

  useEffect(() => {
    loadSurveys();
  }, []);

  useEffect(() => {
    if (online) {
      syncNow().then(loadSurveys);
    }
  }, [online]);

  async function addSurvey() {
    const now = new Date().toISOString();
    const id = uuid();

    const record: SurveyRecord = {
      id,
      siteName,
      latitude: Number(latitude),
      longitude: Number(longitude),
      notes,
      updatedAt: now,
      version: 1,
      syncStatus: "pending",
    };

    const mutation: PendingMutation = {
      id: uuid(),
      entityId: id,
      type: "create",
      payload: record,
      createdAt: now,
      retries: 0,
    };

    await db.transaction("rw", db.surveys, db.mutations, async () => {
      await db.surveys.put(record);
      await db.mutations.put(mutation);
    });

    setSiteName("");
    setLatitude("");
    setLongitude("");
    setNotes("");
    await loadSurveys();

    if (online) {
      await syncNow();
      await loadSurveys();
    }
  }

  return (
    <div style={{ padding: 24, fontFamily: "sans-serif" }}>
      <h1>Field Survey App</h1>
      <p>Status: {online ? "Online" : "Offline"}</p>

      <div style={{ marginBottom: 24 }}>
