### `server/index.ts`
```ts
import express from "express";
import cors from "cors";
import bodyParser from "body-parser";

const app = express();
app.use(cors());
app.use(bodyParser.json());

type SurveyRecord = {
  id: string;
  siteName: string;
  latitude: number;
  longitude: number;
  notes: string;
  updatedAt: string;
  version: number;
};

const surveys = new Map<string, SurveyRecord>();
const changeLog: { record: SurveyRecord; changedAt: string }[] = [];

app.get("/api/surveys", (_req, res) => {
  res.json(Array.from(surveys.values()));
});

app.get("/api/sync/changes", (req, res) => {
  const since = String(req.query.since ?? "1970-01-01T00:00:00.000Z");
  const changed = changeLog
    .filter(c => c.changedAt > since)
    .map(c => c.record);

  res.json({
    surveys: changed,
    serverTime: new Date().toISOString(),
  });
});

app.post("/api/sync/mutation", (req, res) => {
  const mutation = req.body as {
    type: "create" | "update" | "delete";
    entityId: string;
    payload: Partial<SurveyRecord>;
  };

  const now = new Date().toISOString();

  if (mutation.type === "create" || mutation.type === "update") {
    const existing = surveys.get(mutation.entityId);
    const nextVersion = (existing?.version ?? 0) + 1;

    const record: SurveyRecord = {
      id: mutation.entityId,
      siteName: mutation.payload.siteName ?? existing?.siteName ?? "",
      latitude: mutation.payload.latitude ?? existing?.latitude ?? 0,
      longitude: mutation.payload.longitude ?? existing?.longitude ?? 0,
      notes: mutation.payload.notes ?? existing?.notes ?? "",
      updatedAt: now,
      version: nextVersion,
    };

    surveys.set(record.id, record);
    changeLog.push({ record, changedAt: now });
    return res.json({ ok: true, record });
  }

  if (mutation.type === "delete") {
    surveys.delete(mutation.entityId);
    return res.json({ ok: true });
  }

  return res.status(400).json({ error: "Invalid mutation type" });
});

app.listen(3001, () => {
  console.log("API running on http://localhost:3001");
});
```

