## `src/surveyService.ts`

```ts
import { v4 as uuidv4 } from 'uuid';
import { db, SurveyRecord, SyncQueueItem } from './db';

function nowIso() {
  return new Date().toISOString();
}

export async function getSurveyRecords() {
  return db.surveyRecords
    .where('deletedAt')
    .equals(null as any)
    .or('deletedAt')
    .equals(undefined as any)
    .toArray();
}

export async function getSurveyRecord(id: string) {
  return db.surveyRecords.get(id);
}

export async function createSurveyRecord(
  input: Omit<SurveyRecord, 'id' | 'createdAt' | 'updatedAt' | 'version' | 'deletedAt'>
) {
  const record: SurveyRecord = {
    ...input,
    id: uuidv4(),
    createdAt: nowIso(),
    updatedAt: nowIso(),
    deletedAt: null,
    version: 1,
  };

  const queueItem: SyncQueueItem = {
    id: uuidv4(),
    entityType: 'surveyRecord',
    entityId: record.id,
    operation: 'create',
    payload: record,
    createdAt: nowIso(),
    retries: 0,
  };

  await db.transaction('rw', db.surveyRecords, db.syncQueue, async () => {
    await db.surveyRecords.add(record);
    await db.syncQueue.add(queueItem);
  });

  return record;
}

export async function updateSurveyRecord(
  id: string,
  updates: Partial<Omit<SurveyRecord, 'id' | 'createdAt' | 'version'>>
) {
  const existing = await db.surveyRecords.get(id);
  if (!existing) throw new Error('Record not found');

  const updated: SurveyRecord = {
    ...existing,
    ...updates,
    updatedAt: nowIso(),
    version: existing.version + 1,
  };

  const queueItem: SyncQueueItem = {
    id: uuidv4(),
    entityType: 'surveyRecord',
    entityId: id,
    operation: 'update',
    payload: updates,
    createdAt: nowIso(),
    retries: 0,
  };

  await db.transaction('rw', db.surveyRecords, db.syncQueue, async () => {
    await db.surveyRecords.put(updated);
    await db.syncQueue.add(queueItem);
  });

  return updated;
}

export async function deleteSurveyRecord(id: string) {
  const existing = await db.surveyRecords.get(id);
  if (!existing) throw new Error('Record not found');

  const deleted: SurveyRecord = {
    ...existing,
    deletedAt: nowIso(),
    updatedAt: nowIso(),
    version: existing.version + 1,
  };

  const queueItem: SyncQueueItem = {
    id: uuidv4(),
    entityType: 'surveyRecord',
    entityId: id,
    operation: 'delete',
    payload: { deletedAt: deleted.deletedAt },
    createdAt: nowIso(),
    retries: 0,
  };

  await db.transaction('rw', db.surveyRecords, db.syncQueue, async () => {
    await db.surveyRecords.put(deleted);
    await db.syncQueue.add(queueItem);
  });

  return deleted;
}
```

