## `src/syncService.ts`

```ts
import { db, SurveyRecord } from './db';
import { apiFetch } from './api';

function nowIso() {
  return new Date().toISOString();
}

export async function syncNow() {
  // 1) Push local queue
  const queue = await db.syncQueue.orderBy('createdAt').toArray();

  for (const item of queue) {
    try {
      if (item.entityType === 'surveyRecord') {
        if (item.operation === 'create') {
          await apiFetch('/survey-records', {
            method: 'POST',
            body: JSON.stringify(item.payload),
          });
        } else if (item.operation === 'update') {
          await apiFetch(`/survey-records/${item.entityId}`, {
            method: 'PATCH',
            body: JSON.stringify({
              ...item.payload,
              clientUpdatedAt: item.createdAt,
            }),
          });
        } else if (item.operation === 'delete') {
          await apiFetch(`/survey-records/${item.entityId}`, {
            method: 'DELETE',
          });
        }
      }

      await db.syncQueue.delete(item.id);
    } catch (err) {
      await db.syncQueue.update(item.id, {
        retries: item.retries + 1,
      });
      // stop on first failure to avoid cascading issues
      break;
    }
  }

  // 2) Pull remote changes since last sync
  const lastSync = (await db.meta.get('lastSync'))?.value || '1970-01-01T00:00:00.000Z';

  const remoteChanges: SurveyRecord[] = await apiFetch(
    `/survey-records/changes?since=${encodeURIComponent(lastSync)}`
  );

  for (const remote of remoteChanges) {
    const local = await db.surveyRecords.get(remote.id);

    if (!local) {
      await db.surveyRecords.put(remote);
      continue;
    }

    // Simple conflict strategy:
    // - if remote is newer, overwrite local
    // - otherwise keep local
    if (new Date(remote.updatedAt).getTime() > new Date(local.updatedAt).getTime()) {
      await db.surveyRecords.put(remote);
    }
  }

  await db.meta.put({
    key: 'lastSync',
    value: nowIso(),
  });
}
