# 7) Auto-sync when online

## `src/useSync.ts`

```ts
import { useEffect, useState } from 'react';
import { isOnline, onNetworkChange } from './network';
import { syncNow } from './syncService';

export function useSync() {
  const [online, setOnline] = useState(isOnline());
  const [syncing, setSyncing] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const cleanup = onNetworkChange(async (status) => {
      setOnline(status);
      if (status) {
        setSyncing(true);
        setError(null);
        try {
          await syncNow();
        } catch (e: any) {
          setError(e.message || 'Sync failed');
        } finally {
          setSyncing(false);
        }
      }
    });

    return cleanup;
  }, []);

  const manualSync = async () => {
    setSyncing(true);
    setError(null);
    try {
      await syncNow();
    } catch (e: any) {
      setError(e.message || 'Sync failed');
    } finally {
      setSyncing(false);
    }
  };

  return { online, syncing, error, manualSync };
}
```

