const bodyParser = require('body-parser');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(bodyParser.json());

const records = new Map(); // replace with DB in production

app.post('/survey-records', (req, res) => {
  const record = req.body;
  records.set(record.id, record);
  res.json(record);
});

app.patch('/survey-records/:id', (req, res) => {
  const id = req.params.id;
  const existing = records.get(id);

  if (!existing) {
    return res.status(404).json({ error: 'Not found' });
  }

  const updated = {
    ...existing,
    ...req.body,
    updatedAt: new Date().toISOString(),
    version: (existing.version || 1) + 1,
  };

  records.set(id, updated);
  res.json(updated);
});

app.delete('/survey-records/:id', (req, res) => {
  const id = req.params.id;
  const existing = records.get(id);

  if (!existing) {
    return res.status(404).json({ error: 'Not found' });
  }

  const deleted = {
    ...existing,
    deletedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    version: (existing.version || 1) + 1,
  };

  records.set(id, deleted);
  res.json({ ok: true });
});

app.get('/survey-records/changes', (req, res) => {
  const since = req.query.since || '1970-01-01T00:00:00.000Z';
  const changes = [...records.values()].filter(
    (r) => new Date(r.updatedAt).getTime() > new Date(since).getTime()
  );
  res.json(changes);
});

app.listen(3001, () => {
