```ts
import Dexie, { Table } from "dexie";

export type SurveyRecord = {
  id: string;
  siteId: string;
  observerName: string;
  latitude: number;
  longitude: number;
  notes?: string;
  photoUrls: string[];
  updatedAt: string;
  deletedAt?: string | null;
  version: number;
};

export type PendingMutation = {
  id: string;
  entityType: "survey";
  entityId: string;
  operation: "upsert" | "delete";
  payload: Partial<SurveyRecord>;
  createdAt: string;
};

export type SyncState = {
  key: string;
  lastSyncedAt: string | null;
};

class SurveyDB extends Dexie {
  surveys!: Table<SurveyRecord, string>;
  pendingMutations!: Table<PendingMutation, string>;
  syncState!: Table<SyncState, string>;

  constructor() {
    super("survey-app");
    this.version(1).stores({
      surveys: "id, updatedAt, deletedAt, version",
      pendingMutations: "id, entityType, entityId, createdAt",
      syncState: "key",
    });
  }
}

export const db = new SurveyDB();

export async function getLastSyncedAt(): Promise<string | null> {
  const row = await db.syncState.get("global");
  return row?.lastSyncedAt ?? null;
}

export async function setLastSyncedAt(ts: string) {
  await db.syncState.put({ key: "global", lastSyncedAt: ts });
}
