}

export async function pushMutations(mutations: PendingMutation[]) {
  return request<{ applied: string[]; conflicts: any[] }>("/sync/push", {
    method: "POST",
    body: JSON.stringify({ mutations }),
  });
}

export async function pullChanges(since: string | null) {
  const qs = since ? `?since=${encodeURIComponent(since)}` : "";
  return request<{ changes: SurveyRecord[]; serverTime: string }>(`/sync/pull${qs}`);
