## `src/sync.ts`
Sync engine.

```ts
import { db, getLastSyncedAt, setLastSyncedAt, PendingMutation, SurveyRecord } from "./db";
import { pullChanges, pushMutations } from "./api";

export async function saveSurveyLocal(record: SurveyRecord) {
  await db.surveys.put(record);

  const mutation: PendingMutation = {
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: record.id,
    operation: "upsert",
    payload: record,
    createdAt: new Date().toISOString(),
  };

  await db.pendingMutations.put(mutation);
}

export async function deleteSurveyLocal(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const deleted: SurveyRecord = {
    ...existing,
    deletedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    version: existing.version + 1,
  };

  await db.surveys.put(deleted);

  const mutation: PendingMutation = {
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: id,
    operation: "delete",
    payload: { deletedAt: deleted.deletedAt, version: deleted.version },
    createdAt: new Date().toISOString(),
  };

  await db.pendingMutations.put(mutation);
}

export async function syncNow() {
  if (!navigator.onLine) return;

  const lastSyncedAt = await getLastSyncedAt();
  const pending = await db.pendingMutations.orderBy("createdAt").toArray();

  if (pending.length > 0) {
    const pushResult = await pushMutations(pending);

    // Remove successfully applied mutations
    await db.pendingMutations.bulkDelete(pushResult.applied);

    // Handle conflicts if needed
    if (pushResult.conflicts.length > 0) {
      console.warn("Conflicts detected:", pushResult.conflicts);
    }
  }

  const pullResult = await pullChanges(lastSyncedAt);
  for (const remote of pullResult.changes) {
    const local = await db.surveys.get(remote.id);

    // Simple last-write-wins based on updatedAt
    if (!local || new Date(remote.updatedAt) > new Date(local.updatedAt)) {
      await db.surveys.put(remote);
    }
  }

  await setLastSyncedAt(pullResult.serverTime);
}
```

