import Dexie, { Table } from 'dexie';

export type SurveyRecord = {
  id: string;
  serverId?: string;
  title: string;
  notes?: string;
  latitude: number;
  longitude: number;
  photos: string[];
  createdAt: string;
  updatedAt: string;
  deletedAt?: string | null;
  syncStatus: 'synced' | 'pending' | 'error';
  version: number;
};

export type OutboxItem = {
  id: string;
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
  createdAt: string;
  retryCount: number;
  lastError?: string;
};

class SurveyDB extends Dexie {
  surveys!: Table<SurveyRecord, string>;
  outbox!: Table<OutboxItem, string>;

  constructor() {
    super('survey-app-db');
    this.version(1).stores({
      surveys: 'id, serverId, syncStatus, updatedAt',
      outbox: 'id, entityType, entityId, operation, createdAt'
    });
  }
}

