# 4) Local repository layer

This layer ensures every write is saved locally and queued for sync.

## `surveyRepository.ts`
```ts
import { db, SurveyRecord, OutboxItem } from './db';
import { v4 as uuidv4 } from 'uuid';

export async function createSurvey(input: Omit<SurveyRecord, 'id' | 'createdAt' | 'updatedAt' | 'syncStatus' | 'version'>) {
  const now = new Date().toISOString();
  const id = uuidv4();

  const record: SurveyRecord = {
    id,
    ...input,
    createdAt: now,
    updatedAt: now,
    syncStatus: 'pending',
    version: 0,
    deletedAt: null,
  };

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'create',
    payload: record,
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.add(record);
    await db.outbox.add(outboxItem);
  });

  return record;
}

export async function updateSurvey(id: string, changes: Partial<SurveyRecord>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const updated: SurveyRecord = {
    ...existing,
    ...changes,
    updatedAt: now,
    syncStatus: 'pending',
  };

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: changes,
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.put(updated);
    await db.outbox.add(outboxItem);
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const updated: SurveyRecord = {
    ...existing,
    deletedAt: now,
    updatedAt: now,
    syncStatus: 'pending',
  };

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { deletedAt: now },
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.put(updated);
    await db.outbox.add(outboxItem);
  });

  return updated;
}

export async function listSurveys() {
  return db.surveys.where('deletedAt').equals(null as any).toArray();
}
