# 5) Sync engine

This is the heart of offline-first behavior.

## `syncService.ts`
```ts
import { db } from './db';

const API_BASE = '/api';

async function apiFetch(path: string, options: RequestInit = {}) {
  const token = localStorage.getItem('authToken');
  const headers = new Headers(options.headers || {});
  headers.set('Content-Type', 'application/json');
  if (token) headers.set('Authorization', `Bearer ${token}`);

  const res = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers,
  });

  if (!res.ok) {
    const text = await res.text();
    throw new Error(text || `HTTP ${res.status}`);
  }

  return res.json();
}

export async function syncOutbox() {
  const items = await db.outbox.orderBy('createdAt').toArray();
  if (!items.length) return;

  for (const item of items) {
    try {
      if (item.entityType === 'survey') {
        if (item.operation === 'create') {
          const created = await apiFetch('/surveys', {
            method: 'POST',
            body: JSON.stringify(item.payload),
          });

          await db.transaction('rw', db.surveys, db.outbox, async () => {
            const local = await db.surveys.get(item.entityId);
            if (local) {
              await db.surveys.put({
                ...local,
                serverId: created.id,
                syncStatus: 'synced',
                version: created.version ?? local.version + 1,
              });
            }
            await db.outbox.delete(item.id);
          });
        }

        if (item.operation === 'update') {
          const local = await db.surveys.get(item.entityId);
          if (!local) continue;

          const updated = await apiFetch(`/surveys/${local.serverId || local.id}`, {
            method: 'PATCH',
            body: JSON.stringify({
              ...item.payload,
              version: local.version,
            }),
          });

          await db.transaction('rw', db.surveys, db.outbox, async () => {
            await db.surveys.put({
              ...local,
              ...item.payload,
              syncStatus: 'synced',
              version: updated.version ?? local.version + 1,
            });
            await db.outbox.delete(item.id);
          });
        }

        if (item.operation === 'delete') {
          const local = await db.surveys.get(item.entityId);
          if (!local) continue;

          await apiFetch(`/surveys/${local.serverId || local.id}`, {
            method: 'DELETE',
            body: JSON.stringify({ version: local.version }),
          });

          await db.transaction('rw', db.surveys, db.outbox, async () => {
            await db.surveys.delete(item.entityId);
            await db.outbox.delete(item.id);
          });
        }
      }
    } catch (err: any) {
      await db.outbox.update(item.id, {
        retryCount: item.retryCount + 1,
        lastError: err.message,
      });

      await db.surveys.update(item.entityId, {
        syncStatus: 'error',
      });
    }
  }
}
```

