import express from 'express';
import cors from 'cors';
import bodyParser from 'body-parser';
import { v4 as uuidv4 } from 'uuid';

const app = express();
app.use(cors());
app.use(bodyParser.json());

type Survey = {
  id: string;
  title: string;
  notes?: string;
  latitude: number;
  longitude: number;
  photos: string[];
  version: number;
  deletedAt?: string | null;
};

const surveys = new Map<string, Survey>();

app.post('/api/surveys', (req, res) => {
  const id = uuidv4();
  const survey: Survey = {
    id,
    ...req.body,
    version: 1,
  };
  surveys.set(id, survey);
  res.json(survey);
});

app.patch('/api/surveys/:id', (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).send('Not found');

  if (req.body.version !== existing.version) {
    return res.status(409).json({
      message: 'Version conflict',
      serverVersion: existing.version,
      serverRecord: existing,
    });
  }

  const updated: Survey = {
    ...existing,
    ...req.body,
    version: existing.version + 1,
  };

  surveys.set(req.params.id, updated);
  res.json(updated);
});

app.delete('/api/surveys/:id', (req, res) => {
  const existing = surveys.get(req.params.id);
  if (!existing) return res.status(404).send('Not found');

  if (req.body.version !== existing.version) {
    return res.status(409).json({
      message: 'Version conflict',
      serverVersion: existing.version,
      serverRecord: existing,
    });
  }

  surveys.delete(req.params.id);
  res.status(204).send();
});

app.listen(3001, () => console.log('API running on :3001'));
```

