# 8) Sync service

## `src/api/sync.ts`
```ts
import { db } from '../db';
import { apiFetch } from './client';
import { SurveyRecord, OutboxOperation } from '../db/schema';

type PushResponse = {
  applied: Array<{ localOpId: string; serverId: string; version: number }>;
  conflicts: Array<{ localOpId: string; serverRecord: SurveyRecord; reason: string }>;
};

type PullResponse = {
  changes: SurveyRecord[];
  syncToken: string;
};

export async function syncNow() {
  if (!navigator.onLine) return;

  const lastSyncToken = (await db.meta.get('syncToken'))?.value ?? null;
  const outbox = await db.outbox.orderBy('createdAt').toArray();

  // 1) Push local changes
  if (outbox.length > 0) {
    const pushResult: PushResponse = await apiFetch('/sync/push', {
      method: 'POST',
      body: JSON.stringify({ operations: outbox }),
    });

    // Apply acknowledgements
    for (const ack of pushResult.applied) {
      const op = outbox.find(o => o.id === ack.localOpId);
      if (op) {
        await db.outbox.delete(op.id);
      }
    }

    // Mark conflicts locally
    for (const conflict of pushResult.conflicts) {
      const local = await db.surveys.get(conflict.serverRecord.id);
      if (local) {
        await db.surveys.put({
          ...local,
          status: 'conflict',
        });
      }
    }
  }

  // 2) Pull remote changes
  const pullResult: PullResponse = await apiFetch(
    `/sync/pull${lastSyncToken ? `?since=${encodeURIComponent(lastSyncToken)}` : ''}`
  );

  for (const remote of pullResult.changes) {
    const local = await db.surveys.get(remote.id);

    if (!local || remote.version >= local.version) {
      await db.surveys.put({
        ...remote,
        status: 'synced',
      });
    }
  }

  await db.meta.put({ key: 'syncToken', value: pullResult.syncToken });
}
```

