## 6) Survey service

This service writes locally first and queues sync operations.

### `src/features/surveys/surveyService.ts`
```ts
import { db, SurveyRecord, OutboxItem } from '../../db';
import { v4 as uuidv4 } from 'uuid';

export async function createSurvey(input: Omit<SurveyRecord, 'id' | 'createdAt' | 'updatedAt' | 'syncStatus' | 'version'>) {
  const now = new Date().toISOString();
  const id = uuidv4();

  const record: SurveyRecord = {
    ...input,
    id,
    createdAt: now,
    updatedAt: now,
    syncStatus: 'pending',
    version: 1,
  };

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'create',
    payload: record,
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.add(record);
    await db.outbox.add(outboxItem);
  });

  return record;
}

export async function updateSurvey(id: string, changes: Partial<SurveyRecord>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const updated: SurveyRecord = {
    ...existing,
    ...changes,
    updatedAt: now,
    syncStatus: 'pending',
    version: existing.version + 1,
  };

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'update',
    payload: updated,
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.put(updated);
    await db.outbox.add(outboxItem);
  });

  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error('Survey not found');

  const now = new Date().toISOString();
  const updated: SurveyRecord = {
    ...existing,
    deletedAt: now,
    updatedAt: now,
    syncStatus: 'pending',
    version: existing.version + 1,
  };

  const outboxItem: OutboxItem = {
    id: uuidv4(),
    entityType: 'survey',
    entityId: id,
    operation: 'delete',
    payload: { id, deletedAt: now, version: updated.version },
    createdAt: now,
    retryCount: 0,
  };

  await db.transaction('rw', db.surveys, db.outbox, async () => {
    await db.surveys.put(updated);
    await db.outbox.add(outboxItem);
  });

  return updated;
}
```

