## 11) Backend sync endpoint

A simple server endpoint that accepts queued operations.

### `POST /api/sync`
```ts
import express from 'express';

const app = express();
app.use(express.json());

const surveys = new Map<string, any>();

app.post('/api/sync', (req, res) => {
  const item = req.body;

  if (!item || !item.entityType || !item.operation) {
    return res.status(400).send('Invalid sync payload');
  }

  if (item.entityType === 'survey') {
    const payload = item.payload;

    if (item.operation === 'create' || item.operation === 'update') {
      const existing = surveys.get(payload.id);

      // naive conflict check
      if (existing && payload.version <= existing.version) {
        return res.status(409).json({
          message: 'Conflict detected',
          serverRecord: existing,
        });
      }

      surveys.set(payload.id, {
        ...payload,
        serverUpdatedAt: new Date().toISOString(),
      });

      return res.json({ ok: true, version: payload.version });
    }

    if (item.operation === 'delete') {
      surveys.delete(payload.id);
      return res.json({ ok: true });
    }
  }

  return res.status(400).send('Unsupported entity type');
});

app.listen(3000, () => console.log('API running on port 3000'));
```

