## `surveyRepository.ts`

```ts
import { getDb } from './db';
import { v4 as uuidv4 } from 'uuid';
import { SurveyRecord } from './models';

const db = getDb();

export function listSurveys(): SurveyRecord[] {
  const rows = db.getAllSync<any>(
    `SELECT * FROM survey_records WHERE deletedAt IS NULL ORDER BY updatedAt DESC`
  );
  return rows;
}

export function getSurvey(id: string): SurveyRecord | null {
  const row = db.getFirstSync<any>(
    `SELECT * FROM survey_records WHERE id = ?`,
    [id]
  );
  return row ?? null;
}

export function upsertSurveyOffline(input: Partial<SurveyRecord> & { projectId: string; title: string }) {
  const now = new Date().toISOString();
  const id = input.id ?? uuidv4();

  const existing = getSurvey(id);
  const nextVersion = (existing?.version ?? 0) + 1;

  db.runSync(
    `
    INSERT INTO survey_records (id, projectId, title, notes, latitude, longitude, status, updatedAt, deletedAt, version)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, NULL, ?)
    ON CONFLICT(id) DO UPDATE SET
      projectId=excluded.projectId,
      title=excluded.title,
      notes=excluded.notes,
      latitude=excluded.latitude,
      longitude=excluded.longitude,
      status=excluded.status,
      updatedAt=excluded.updatedAt,
      deletedAt=NULL,
      version=excluded.version
    `,
    [
      id,
      input.projectId,
      input.title,
      input.notes ?? null,
      input.latitude ?? null,
      input.longitude ?? null,
      input.status ?? 'draft',
      now,
      nextVersion,
    ]
  );

  return id;
}

export function deleteSurveyOffline(id: string) {
  const now = new Date().toISOString();
  db.runSync(
    `UPDATE survey_records SET deletedAt = ?, updatedAt = ?, version = version + 1 WHERE id = ?`,
    [now, now, id]
  );
}

export function enqueueMutation(mutation: {
  entityType: 'survey';
  entityId: string;
  operation: 'create' | 'update' | 'delete';
  payload: any;
}) {
  db.runSync(
    `INSERT INTO pending_mutations (id, entityType, entityId, operation, payload, createdAt, retryCount)
     VALUES (?, ?, ?, ?, ?, ?, 0)`,
    [
      uuidv4(),
      mutation.entityType,
      mutation.entityId,
      mutation.operation,
      JSON.stringify(mutation.payload),
      new Date().toISOString(),
    ]
  );
}
```

