## `syncService.ts`

```ts
import NetInfo from '@react-native-community/netinfo';
import axios from 'axios';
import { getDb } from './db';

const db = getDb();
const API_BASE = 'https://your-api.example.com';

export async function syncNow() {
  const net = await NetInfo.fetch();
  if (!net.isConnected) return;

  // 1) Push pending mutations
  const pending = db.getAllSync<any>(
    `SELECT * FROM pending_mutations ORDER BY createdAt ASC`
  );

  if (pending.length > 0) {
    try {
      const response = await axios.post(`${API_BASE}/sync/push`, {
        mutations: pending.map((m: any) => ({
          id: m.id,
          entityType: m.entityType,
          entityId: m.entityId,
          operation: m.operation,
          payload: JSON.parse(m.payload),
          createdAt: m.createdAt,
        })),
      });

      const ackedIds: string[] = response.data.ackedIds ?? [];
      for (const id of ackedIds) {
        db.runSync(`DELETE FROM pending_mutations WHERE id = ?`, [id]);
      }
    } catch (e) {
      // leave mutations queued for retry
      return;
    }
  }

  // 2) Pull remote changes
  const lastSyncRow = db.getFirstSync<any>(
    `SELECT value FROM sync_state WHERE key = 'lastSyncAt'`
  );
  const since = lastSyncRow?.value ?? '1970-01-01T00:00:00.000Z';

  const pullRes = await axios.get(`${API_BASE}/sync/pull`, {
    params: { since },
  });

  const changes = pullRes.data.changes ?? [];
  for (const record of changes) {
    db.runSync(
      `
      INSERT INTO survey_records (id, projectId, title, notes, latitude, longitude, status, updatedAt, deletedAt, version)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        projectId=excluded.projectId,
        title=excluded.title,
        notes=excluded.notes,
        latitude=excluded.latitude,
        longitude=excluded.longitude,
        status=excluded.status,
        updatedAt=excluded.updatedAt,
        deletedAt=excluded.deletedAt,
        version=excluded.version
      `,
      [
        record.id,
        record.projectId,
        record.title,
        record.notes ?? null,
        record.latitude ?? null,
        record.longitude ?? null,
        record.status,
        record.updatedAt,
        record.deletedAt ?? null,
        record.version,
      ]
    );
  }

  const now = new Date().toISOString();
  db.runSync(
    `INSERT INTO sync_state (key, value)
     VALUES ('lastSyncAt', ?)
     ON CONFLICT(key) DO UPDATE SET value = excluded.value`,
    [now]
  );
}
```

