## `server.js`

```js
const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(bodyParser.json());

const records = new Map(); // replace with real DB
const mutationLog = [];

app.post('/sync/push', (req, res) => {
  const { mutations = [] } = req.body;
  const ackedIds = [];

  for (const m of mutations) {
    const payload = m.payload;

    if (m.operation === 'create' || m.operation === 'update') {
      const existing = records.get(m.entityId);
      const nextVersion = (existing?.version ?? 0) + 1;

      records.set(m.entityId, {
        ...existing,
        ...payload,
        id: m.entityId,
        updatedAt: new Date().toISOString(),
        version: nextVersion,
        deletedAt: null,
      });
    } else if (m.operation === 'delete') {
      const existing = records.get(m.entityId);
      if (existing) {
        records.set(m.entityId, {
          ...existing,
          deletedAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
          version: (existing.version ?? 0) + 1,
        });
      }
    }

    mutationLog.push({ ...m, serverReceivedAt: new Date().toISOString() });
    ackedIds.push(m.id);
  }

  res.json({ ackedIds });
});

app.get('/sync/pull', (req, res) => {
  const since = req.query.since || '1970-01-01T00:00:00.000Z';

  const changes = Array.from(records.values()).filter(
    (r) => r.updatedAt > since
  );

  res.json({ changes });
});

app.get('/records', (req, res) => {
  res.json(Array.from(records.values()));
});

app.listen(3000, () => {
  console.log('API running on http://localhost:3000');
});
```

