### 3.4 Sync manager

This is the heart of offline-first behavior.

**`src/sync.ts`**

```ts
import { db, PendingMutation, SurveyRecord } from './db';
import { fetchRemoteRecords, pushMutations } from './api';

const LAST_SYNC_KEY = 'lastSyncAt';

export async function queueMutation(mutation: PendingMutation) {
  await db.pendingMutations.put(mutation);
}

export async function saveLocalRecord(record: SurveyRecord) {
  await db.surveyRecords.put(record);
}

export async function deleteLocalRecord(id: string) {
  const existing = await db.surveyRecords.get(id);
  if (existing) {
    await db.surveyRecords.put({ ...existing, deleted: true, updatedAt: new Date().toISOString() });
  }
}

export async function syncNow() {
  // 1. Push pending mutations
  const pending = await db.pendingMutations.orderBy('createdAt').toArray();

  if (pending.length > 0) {
    try {
      await pushMutations(pending);
      await db.pendingMutations.clear();
    } catch (err) {
      console.error('Push failed:', err);
      return;
    }
  }

  // 2. Pull remote updates
  const lastSync = await db.syncState.get(LAST_SYNC_KEY);
  const since = lastSync?.value;
  const remoteRecords = await fetchRemoteRecords(since);

  for (const record of remoteRecords) {
    const local = await db.surveyRecords.get(record.id);
    if (!local || new Date(record.updatedAt) > new Date(local.updatedAt)) {
      await db.surveyRecords.put(record);
    }
  }

  // 3. Update sync timestamp
  await db.syncState.put({ key: LAST_SYNC_KEY, value: new Date().toISOString() });
}
```

