import express from 'express';
import cors from 'cors';

const app = express();
app.use(cors());
app.use(express.json());

type SurveyRecord = {
  id: string;
  plotId: string;
  latitude: number;
  longitude: number;
  notes: string;
  measurements: {
    heightCm?: number;
    diameterCm?: number;
    species?: string;
  };
  updatedAt: string;
  createdAt: string;
  deleted?: boolean;
};

const records = new Map<string, SurveyRecord>();

app.get('/records', (req, res) => {
  const since = req.query.since as string | undefined;
  const all = [...records.values()].filter(r => !since || new Date(r.updatedAt) > new Date(since));
  res.json(all);
});

app.post('/sync', (req, res) => {
  const mutations = req.body.mutations || [];

  for (const m of mutations) {
    const payload = m.payload as SurveyRecord;

    if (m.type === 'create' || m.type === 'update') {
      const existing = records.get(m.recordId);
      if (!existing || new Date(payload.updatedAt) >= new Date(existing.updatedAt)) {
        records.set(m.recordId, payload);
      }
    }

    if (m.type === 'delete') {
      const existing = records.get(m.recordId);
      if (existing) {
        records.set(m.recordId, { ...existing, deleted: true, updatedAt: new Date().toISOString() });
      }
    }
  }

  res.json({ ok: true });
});

app.listen(3001, () => {
  console.log('Sync server running on http://localhost:3001');
});
