# 5) Sync engine

This is the heart of the app.

## `src/sync.ts`
```ts
import { db, OutboxItem, Survey } from "./db";
import { createSurvey, deleteSurvey, fetchSurveys, updateSurvey } from "./api";

let syncing = false;

function isOnline() {
  return navigator.onLine;
}

export async function saveSurveyLocal(survey: Survey) {
  await db.surveys.put(survey);
}

export async function queueOperation(item: OutboxItem) {
  await db.outbox.put(item);
}

export async function createSurveyOffline(survey: Survey) {
  await db.surveys.put(survey);
  await db.outbox.put({
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: survey.id,
    operation: "create",
    payload: survey,
    createdAt: new Date().toISOString(),
    retryCount: 0,
  });
}

export async function updateSurveyOffline(id: string, patch: Partial<Survey>) {
  const existing = await db.surveys.get(id);
  if (!existing) throw new Error("Survey not found locally");

  const updated: Survey = {
    ...existing,
    ...patch,
    updatedAt: new Date().toISOString(),
  };

  await db.surveys.put(updated);
  await db.outbox.put({
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: id,
    operation: "update",
    payload: patch,
    createdAt: new Date().toISOString(),
    retryCount: 0,
  });
}

export async function deleteSurveyOffline(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  await db.surveys.put({
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString(),
  });

  await db.outbox.put({
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: id,
    operation: "delete",
    payload: {},
    createdAt: new Date().toISOString(),
    retryCount: 0,
  });
}

export async function syncNow() {
  if (syncing || !isOnline()) return;
  syncing = true;

  try {
    // 1) Push local outbox
    const items = await db.outbox.orderBy("createdAt").toArray();

    for (const item of items) {
      try {
        if (item.operation === "create") {
          const serverSurvey = await createSurvey(item.payload as Survey);
          await db.surveys.put(serverSurvey);
        } else if (item.operation === "update") {
          const serverSurvey = await updateSurvey(item.entityId, item.payload);
          await db.surveys.put(serverSurvey);
        } else if (item.operation === "delete") {
          await deleteSurvey(item.entityId);
          await db.surveys.delete(item.entityId);
        }

        await db.outbox.delete(item.id);
      } catch (err) {
        item.retryCount += 1;
        await db.outbox.put(item);

        // stop on first failure to preserve order
        break;
      }
    }

    // 2) Pull latest server changes
    const latestLocalUpdate = await db.surveys.orderBy("updatedAt").last();
    const since = latestLocalUpdate?.updatedAt;
    const remoteSurveys = await fetchSurveys(since);

    for (const remote of remoteSurveys) {
      const local = await db.surveys.get(remote.id);

      // basic last-write-wins
      if (!local || new Date(remote.updatedAt) > new Date(local.updatedAt)) {
        await db.surveys.put(remote);
      }
    }
  } finally {
    syncing = false;
  }
}
```

