```tsx
import React, { useEffect, useState } from "react";
import { db, Survey } from "./db";
import {
  createSurveyOffline,
  deleteSurveyOffline,
  updateSurveyOffline,
  syncNow,
} from "./sync";
import { useOfflineSync } from "./useOfflineSync";

function newSurvey(): Survey {
  const now = new Date().toISOString();
  return {
    id: crypto.randomUUID(),
    siteName: "",
    latitude: 0,
    longitude: 0,
    notes: "",
    photos: [],
    createdAt: now,
    updatedAt: now,
    version: 1,
    deleted: false,
  };
}

export default function App() {
  const [surveys, setSurveys] = useState<Survey[]>([]);
  const [form, setForm] = useState<Survey>(newSurvey());
  const { online, syncing, manualSync } = useOfflineSync();

  async function refresh() {
    const items = await db.surveys.where("deleted").notEqual(1 as any).toArray();
    setSurveys(items);
  }

  useEffect(() => {
    refresh();
  }, []);

  async function handleSave() {
    if (!form.siteName.trim()) return;

    const existing = await db.surveys.get(form.id);
    const payload: Survey = {
      ...form,
      updatedAt: new Date().toISOString(),
      version: (existing?.version || 0) + 1,
    };

    await createSurveyOffline(payload);
    setForm(newSurvey());
    await refresh();

    if (online) {
      await syncNow();
      await refresh();
    }
  }

  async function handleDelete(id: string) {
    await deleteSurveyOffline(id);
    await refresh();
    if (online) {
      await syncNow();
      await refresh();
    }
  }

  async function handleEdit(s: Survey) {
    setForm(s);
  }

  async function handleUpdate() {
    await updateSurveyOffline(form.id, form);
    setForm(newSurvey());
    await refresh();
    if (online) {
      await syncNow();
      await refresh();
    }
  }

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h1>Field Survey App</h1>

      <div>
        Status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
        {syncing && <span> — syncing...</span>}
        <button onClick={manualSync} style={{ marginLeft: 12 }}>
          Sync now
        </button>
      </div>

      <hr />

      <h2>{form.id ? "Survey Form" : "New Survey"}</h2>
      <div style={{ display: "grid", gap: 8, maxWidth: 400 }}>
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
        />
        <input
          type="number"
          placeholder="Latitude"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: Number(e.target.value) })}
        />
        <input
          type="number"
          placeholder="Longitude"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: Number(e.target.value) })}
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button onClick={form.siteName ? handleUpdate : handleSave}>
          Save Survey
        </button>
      </div>

      <hr />

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <strong>{s.siteName}</strong> ({s.latitude}, {s.longitude})
            <div>{s.notes}</div>
            <button onClick={() => handleEdit(s)}>Edit</button>
            <button onClick={() => handleDelete(s.id)} style={{ marginLeft: 8 }}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
