## 8) Sync service

### `services/syncService.ts`
```ts
import { db } from "../db/db";
import { apiFetch } from "./api";
import { Survey, SyncQueueItem } from "../types/survey";

function nowIso() {
  return new Date().toISOString();
}

export async function queueSurveyCreate(survey: Omit<Survey, "version" | "syncStatus" | "createdAt" | "updatedAt">) {
  const record: Survey = {
    ...survey,
    createdAt: nowIso(),
    updatedAt: nowIso(),
    version: 1,
    syncStatus: "pending",
  };

  await db.surveys.put(record);

  const queueItem: SyncQueueItem = {
    id: crypto.randomUUID(),
    entityType: "survey",
    entityId: record.id,
    operation: "create",
    payload: record,
    createdAt: nowIso(),
    attempts: 0,
  };

  await db.syncQueue.put(queueItem);
  return record;
}

export async function syncPendingItems() {
  const items = await db.syncQueue.orderBy("createdAt").toArray();

  for (const item of items) {
    try {
      if (item.entityType === "survey") {
        if (item.operation === "create") {
          const saved = await apiFetch("/surveys", {
            method: "POST",
            body: JSON.stringify(item.payload),
          });

          await db.surveys.update(item.entityId, {
            ...saved,
            syncStatus: "synced",
          });
        }
      }

      await db.syncQueue.delete(item.id);
    } catch (error: any) {
      await db.syncQueue.update(item.id, {
        attempts: item.attempts + 1,
        lastError: error.message,
      });

      const survey = await db.surveys.get(item.entityId);
      if (survey) {
        await db.surveys.update(item.entityId, { syncStatus: "failed" });
      }
    }
  }
}

export async function pullLatestSurveys() {
  const remoteSurveys: Survey[] = await apiFetch("/surveys");
  await db.surveys.bulkPut(
    remoteSurveys.map((s) => ({
      ...s,
      syncStatus: "synced",
    }))
  );
}
```

