## 4) Sync service

This service:
- queues local changes
- pushes queued changes to server
- pulls server updates
- handles reconnect events

### `syncService.ts`
```ts
import { db, SurveyRecord, SyncQueueItem } from './db';

const API_BASE = '/api';

function uuid() {
  return crypto.randomUUID();
}

async function getAuthToken(): Promise<string> {
  // Replace with your auth implementation
  return localStorage.getItem('token') || '';
}

export async function queueSurveyChange(
  operation: 'create' | 'update' | 'delete',
  record: SurveyRecord
) {
  const item: SyncQueueItem = {
    id: uuid(),
    entityType: 'survey',
    entityId: record.id,
    operation,
    payload: record,
    createdAt: new Date().toISOString(),
    retryCount: 0
  };

  await db.syncQueue.add(item);
}

export async function saveSurveyLocal(record: SurveyRecord) {
  await db.surveys.put(record);
}

export async function createSurvey(record: Omit<SurveyRecord, 'version' | 'createdAt' | 'updatedAt'>) {
  const now = new Date().toISOString();
  const fullRecord: SurveyRecord = {
    ...record,
    createdAt: now,
    updatedAt: now,
    version: 0
  };

  await saveSurveyLocal(fullRecord);
  await queueSurveyChange('create', fullRecord);
  return fullRecord;
}

export async function updateSurvey(record: SurveyRecord) {
  const updated: SurveyRecord = {
    ...record,
    updatedAt: new Date().toISOString()
  };

  await saveSurveyLocal(updated);
  await queueSurveyChange('update', updated);
  return updated;
}

export async function deleteSurvey(id: string) {
  const existing = await db.surveys.get(id);
  if (!existing) return;

  const deletedRecord: SurveyRecord = {
    ...existing,
    deleted: true,
    updatedAt: new Date().toISOString()
  };

  await saveSurveyLocal(deletedRecord);
  await queueSurveyChange('delete', deletedRecord);
}

async function pushQueue() {
  const token = await getAuthToken();
  const queue = await db.syncQueue.orderBy('createdAt').toArray();

  for (const item of queue) {
    try {
      const res = await fetch(`${API_BASE}/sync/surveys`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify(item)
      });

      if (!res.ok) throw new Error(`Push failed: ${res.status}`);

      await db.syncQueue.delete(item.id);
    } catch (err) {
      await db.syncQueue.update(item.id, {
        retryCount: item.retryCount + 1
      });
      // stop on first failure to avoid hammering server
      break;
    }
  }
}

async function pullUpdates() {
  const token = await getAuthToken();
  const syncState = await db.syncState.get('main');
  const lastPulledAt = syncState?.lastPulledAt || null;

  const res = await fetch(
    `${API_BASE}/sync/surveys?since=${encodeURIComponent(lastPulledAt || '')}`,
    {
      headers: {
        Authorization: `Bearer ${token}`
      }
    }
  );

  if (!res.ok) throw new Error(`Pull failed: ${res.status}`);

  const data: { surveys: SurveyRecord[]; serverTime: string } = await res.json();

  for (const serverRecord of data.surveys) {
    const local = await db.surveys.get(serverRecord.id);

    if (!local || new Date(serverRecord.updatedAt) > new Date(local.updatedAt)) {
      await db.surveys.put(serverRecord);
    }
  }

  await db.syncState.put({
    key: 'main',
    lastPulledAt: data.serverTime,
    lastPushedAt: syncState?.lastPushedAt || null
  });
}

export async function syncNow() {
  await pushQueue();
  await pullUpdates();

  const syncState = await db.syncState.get('main');
  await db.syncState.put({
    key: 'main',
    lastPulledAt: syncState?.lastPulledAt || new Date().toISOString(),
    lastPushedAt: new Date().toISOString()
  });
}

export function startAutoSync() {
  const handleOnline = () => {
    syncNow().catch(console.error);
  };

  window.addEventListener('online', handleOnline);

  // attempt sync on startup if online
  if (navigator.onLine) {
    syncNow().catch(console.error);
  }

  return () => window.removeEventListener('online', handleOnline);
}
```

