# 6) Sync manager

This is the heart of offline-first syncing.

## `src/sync/syncManager.ts`

```ts
import { db } from '../db';
import { postMutation } from './api';

let syncing = false;

export async function syncOutbox() {
  if (syncing) return;
  syncing = true;

  try {
    const items = await db.outbox.orderBy('createdAt').toArray();

    for (const item of items) {
      try {
        const result = await postMutation(item);

        if (result?.serverId) {
          const survey = await db.surveys.get(item.entityId);
          if (survey) {
            await db.surveys.update(item.entityId, {
              serverId: result.serverId,
              status: 'synced',
              updatedAt: new Date().toISOString()
            });
          }
        }

        await db.outbox.delete(item.id);
      } catch (err: any) {
        await db.outbox.update(item.id, {
          attempts: item.attempts + 1,
          lastError: err.message || 'Unknown sync error'
        });
      }
    }
  } finally {
    syncing = false;
  }
}
```

