# 8) Survey hooks

## `src/hooks/useSurveys.ts`

```ts
import { useLiveQuery } from 'dexie-react-hooks';
import { db } from '../db';
import { v4 as uuidv4 } from 'uuid';

export function useSurveys() {
  const surveys = useLiveQuery(() =>
    db.surveys.where('deleted').notEqual(1).toArray()
  ) || [];

  async function createSurvey(data: {
    title: string;
    notes?: string;
    latitude: number;
    longitude: number;
  }) {
    const now = new Date().toISOString();
    const id = uuidv4();

    const survey = {
      id,
      title: data.title,
      notes: data.notes,
      latitude: data.latitude,
      longitude: data.longitude,
      status: 'draft' as const,
      createdAt: now,
      updatedAt: now,
      version: 1
    };

    await db.surveys.put(survey);

    await db.outbox.put({
      id: uuidv4(),
      entityType: 'survey',
      entityId: id,
      operation: 'create',
      payload: survey,
      createdAt: now,
      attempts: 0
    });

    return survey;
  }

  async function updateSurvey(id: string, changes: Partial<any>) {
    const survey = await db.surveys.get(id);
    if (!survey) return;

    const updated = {
      ...survey,
      ...changes,
      updatedAt: new Date().toISOString(),
      version: survey.version + 1
    };

    await db.surveys.put(updated);

    await db.outbox.put({
      id: uuidv4(),
      entityType: 'survey',
      entityId: id,
      operation: 'update',
      payload: updated,
      createdAt: updated.updatedAt,
      attempts: 0
    });
  }

  async function deleteSurvey(id: string) {
    const survey = await db.surveys.get(id);
    if (!survey) return;

    await db.surveys.update(id, {
      deleted: true,
      updatedAt: new Date().toISOString(),
      version: survey.version + 1
    });

    await db.outbox.put({
      id: uuidv4(),
      entityType: 'survey',
      entityId: id,
      operation: 'delete',
      payload: { id },
      createdAt: new Date().toISOString(),
      attempts: 0
    });
  }

  return { surveys, createSurvey, updateSurvey, deleteSurvey };
}
```

