# 11) Backend sync endpoint

This is a minimal server implementation.

## `server/index.ts`

```ts
import express from 'express';
import cors from 'cors';
import bodyParser from 'body-parser';
import { v4 as uuidv4 } from 'uuid';

const app = express();
app.use(cors());
app.use(bodyParser.json());

const surveys: any[] = [];

app.get('/api/surveys', (req, res) => {
  res.json(surveys.filter(s => !s.deleted));
});

app.post('/api/sync', (req, res) => {
  const mutation = req.body;

  if (mutation.entityType !== 'survey') {
    return res.status(400).json({ error: 'Unsupported entity type' });
  }

  if (mutation.operation === 'create') {
    const serverId = uuidv4();
    surveys.push({
      ...mutation.payload,
      serverId,
      deleted: false
    });
    return res.json({ ok: true, serverId });
  }

  if (mutation.operation === 'update') {
    const idx = surveys.findIndex(s => s.id === mutation.entityId || s.serverId === mutation.payload.serverId);
    if (idx >= 0) {
      surveys[idx] = {
        ...surveys[idx],
        ...mutation.payload
      };
      return res.json({ ok: true, serverId: surveys[idx].serverId });
    }
    return res.status(404).json({ error: 'Survey not found' });
  }

  if (mutation.operation === 'delete') {
    const idx = surveys.findIndex(s => s.id === mutation.entityId || s.serverId === mutation.payload.serverId);
    if (idx >= 0) {
      surveys[idx].deleted = true;
      return res.json({ ok: true });
    }
    return res.status(404).json({ error: 'Survey not found' });
  }

  return res.status(400).json({ error: 'Unknown operation' });
});

app.listen(3001, () => {
  console.log('Server running on port 3001');
});
```

