const Database = require('better-sqlite3');
const { v4: uuidv4 } = require('uuid');

const app = express();
app.use(cors());
app.use(express.json());

const db = new Database('survey.db');

db.exec(`
  CREATE TABLE IF NOT EXISTS surveys (
    id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    location TEXT NOT NULL,
    notes TEXT NOT NULL,
    updatedAt INTEGER NOT NULL,
    deleted INTEGER NOT NULL DEFAULT 0
  );
`);

app.get('/surveys', (req, res) => {
  const rows = db.prepare('SELECT * FROM surveys WHERE deleted = 0').all();
  res.json(rows);
});

app.post('/sync', (req, res) => {
  const mutations = req.body.mutations || [];
  const results = [];

  const upsertStmt = db.prepare(`
    INSERT INTO surveys (id, title, location, notes, updatedAt, deleted)
    VALUES (@id, @title, @location, @notes, @updatedAt, @deleted)
    ON CONFLICT(id) DO UPDATE SET
      title = excluded.title,
      location = excluded.location,
      notes = excluded.notes,
      updatedAt = excluded.updatedAt,
      deleted = excluded.deleted
    WHERE excluded.updatedAt >= surveys.updatedAt
  `);

  const deleteStmt = db.prepare(`
    INSERT INTO surveys (id, title, location, notes, updatedAt, deleted)
    VALUES (@id, @title, @location, @notes, @updatedAt, 1)
    ON CONFLICT(id) DO UPDATE SET
      deleted = 1,
      updatedAt = excluded.updatedAt
    WHERE excluded.updatedAt >= surveys.updatedAt
  `);

  const tx = db.transaction((mutations) => {
    for (const m of mutations) {
      if (m.type === 'upsert') {
        upsertStmt.run({
          ...m.record,
          deleted: m.record.deleted ? 1 : 0
        });
        results.push({ id: m.record.id, status: 'ok' });
      } else if (m.type === 'delete') {
        deleteStmt.run({
          ...m.record
        });
        results.push({ id: m.record.id, status: 'ok' });
      }
    }
  });

  tx(mutations);

  const serverSurveys = db.prepare('SELECT * FROM surveys WHERE deleted = 0').all();
  res.json({ ok: true, results, surveys: serverSurveys });
});

app.post('/surveys', (req, res) => {
  const { title, location, notes } = req.body;
  const id = uuidv4();
  const updatedAt = Date.now();

  db.prepare(`
    INSERT INTO surveys (id, title, location, notes, updatedAt, deleted)
    VALUES (?, ?, ?, ?, ?, 0)
  `).run(id, title, location, notes, updatedAt);

  res.json({ id, title, location, notes, updatedAt, deleted: 0 });
});

app.listen(3001, () => {
  console.log('Server running on http://localhost:3001');
});
