import { openDB } from 'idb';

export const dbPromise = openDB('survey-app', 1, {
  upgrade(db) {
    if (!db.objectStoreNames.contains('surveys')) {
      db.createObjectStore('surveys', { keyPath: 'id' });
    }
    if (!db.objectStoreNames.contains('pending')) {
      db.createObjectStore('pending', { keyPath: 'id' });
    }
  }
});

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll('surveys');
}

export async function saveSurvey(survey) {
  const db = await dbPromise;
  return db.put('surveys', survey);
}

export async function deleteSurveyLocal(id) {
  const db = await dbPromise;
  return db.delete('surveys', id);
}

export async function addPendingMutation(mutation) {
  const db = await dbPromise;
  return db.put('pending', mutation);
}

export async function getPendingMutations() {
  const db = await dbPromise;
  return db.getAll('pending');
}

export async function clearPendingMutation(id) {
  const db = await dbPromise;
  return db.delete('pending', id);
}
