## `src/App.jsx`

```jsx
import { useEffect, useState } from 'react';
import {
  getAllSurveys,
  saveSurvey,
  deleteSurveyLocal,
  addPendingMutation,
  getPendingMutations,
  clearPendingMutation
} from './db';
import { fetchSurveys, syncMutations } from './api';

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [title, setTitle] = useState('');
  const [location, setLocation] = useState('');
  const [notes, setNotes] = useState('');
  const [online, setOnline] = useState(navigator.onLine);
  const [syncing, setSyncing] = useState(false);

  async function loadLocal() {
    const local = await getAllSurveys();
    setSurveys(local.filter(s => !s.deleted));
  }

  async function refreshFromServer() {
    if (!navigator.onLine) return;
    const server = await fetchSurveys();
    for (const s of server) {
      await saveSurvey(s);
    }
    await loadLocal();
  }

  async function syncNow() {
    if (!navigator.onLine) return;
    setSyncing(true);
    try {
      const pending = await getPendingMutations();
      if (pending.length > 0) {
        const result = await syncMutations(pending);
        for (const m of pending) {
          await clearPendingMutation(m.id);
        }
        if (result.surveys) {
          for (const s of result.surveys) {
            await saveSurvey(s);
          }
        }
      }
      await refreshFromServer();
    } finally {
      setSyncing(false);
    }
  }

  useEffect(() => {
    loadLocal();
    refreshFromServer();

    const onOnline = () => {
      setOnline(true);
      syncNow();
    };
    const onOffline = () => setOnline(false);

    window.addEventListener('online', onOnline);
    window.addEventListener('offline', onOffline);

    return () => {
      window.removeEventListener('online', onOnline);
      window.removeEventListener('offline', onOffline);
    };
  }, []);

  async function addSurvey() {
    const survey = {
      id: uuid(),
      title,
      location,
      notes,
      updatedAt: Date.now(),
      deleted: false
    };

    await saveSurvey(survey);
    await addPendingMutation({
      id: uuid(),
      type: 'upsert',
      record: survey,
      createdAt: Date.now()
    });

    setTitle('');
    setLocation('');
    setNotes('');
    await loadLocal();

    if (navigator.onLine) {
      await syncNow();
    }
  }

  async function removeSurvey(id) {
    const existing = surveys.find(s => s.id === id);
    if (!existing) return;

    const deletedRecord = { ...existing, deleted: true, updatedAt: Date.now() };
    await saveSurvey(deletedRecord);
    await addPendingMutation({
      id: uuid(),
      type: 'delete',
      record: deletedRecord,
      createdAt: Date.now()
    });

    await loadLocal();

    if (navigator.onLine) {
      await syncNow();
    }
  }

  return (
    <div style={{ fontFamily: 'sans-serif', padding: 20, maxWidth: 800 }}>
      <h1>Offline Survey App</h1>
      <p>
        Status: <b>{online ? 'Online' : 'Offline'}</b> | Sync: {syncing ? 'Syncing...' : 'Idle'}
      </p>

      <div style={{ display: 'grid', gap: 8, marginBottom: 20 }}>
        <input
          placeholder="Survey title"
          value={title}
          onChange={e => setTitle(e.target.value)}
        />
        <input
          placeholder="Location"
          value={location}
          onChange={e => setLocation(e.target.value)}
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={e => setNotes(e.target.value)}
        />
        <button onClick={addSurvey} disabled={!title || !location}>
          Add Survey
        </button>
        <button onClick={syncNow}>Sync Now</button>
      </div>

      <h2>Surveys</h2>
      <ul>
        {surveys.map(s => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <b>{s.title}</b> — {s.location}
            <div>{s.notes}</div>
            <small>Updated: {new Date(s.updatedAt).toLocaleString()}</small>
            <div>
              <button onClick={() => removeSurvey(s.id)}>Delete</button>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

