```jsx
import React, { useEffect, useState } from "react";
import {
  getAllSurveys,
  saveSurvey,
  addToQueue,
  getQueue,
  removeFromQueue
} from "./db";
import { fetchSurveys, sendSurvey } from "./api";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState("");

  async function loadLocal() {
    const local = await getAllSurveys();
    setSurveys(local);
  }

  async function syncQueue() {
    if (!navigator.onLine) return;

    const queued = await getQueue();
    if (queued.length === 0) return;

    setStatus(`Syncing ${queued.length} queued record(s)...`);

    for (const item of queued) {
      try {
        const saved = await sendSurvey(item);
        await saveSurvey({ ...item, synced: true, serverId: saved.serverId });
        await removeFromQueue(item.localId);
      } catch (e) {
        console.error(e);
        setStatus("Sync failed. Will retry when online.");
        return;
      }
    }

    setStatus("Sync complete.");
    await loadLocal();
  }

  async function refreshFromServer() {
    if (!navigator.onLine) return;
    const remote = await fetchSurveys();
    const dbSurveys = remote.map((s) => ({
      ...s,
      localId: s.localId || s.serverId || uuid(),
      synced: true
    }));

    for (const s of dbSurveys) {
      await saveSurvey(s);
    }
    await loadLocal();
  }

  useEffect(() => {
    loadLocal();
    syncQueue();
    refreshFromServer();

    const onOnline = async () => {
      setOnline(true);
      setStatus("Back online.");
      await syncQueue();
      await refreshFromServer();
    };

    const onOffline = () => {
      setOnline(false);
      setStatus("Offline mode.");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      localId: uuid(),
      name,
      location,
      notes,
      createdAt: new Date().toISOString(),
      synced: false
    };

    await saveSurvey(survey);
    await addToQueue(survey);
    setSurveys((prev) => [survey, ...prev]);

    setName("");
    setLocation("");
    setNotes("");
    setStatus(online ? "Saved locally and queued for sync." : "Saved offline.");
  }

  return (
    <div style={{ fontFamily: "sans-serif", padding: 20, maxWidth: 700 }}>
      <h1>Field Survey App</h1>
      <p>
        Status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
      </p>
      <p>{status}</p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 10 }}>
        <input
          placeholder="Surveyor name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          required
        />
        <button type="submit">Save Survey</button>
      </form>

      <hr />

      <h2>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.localId}>
            <strong>{s.name}</strong> — {s.location}{" "}
            {s.synced ? "(synced)" : "(pending)"}
          </li>
        ))}
      </ul>
    </div>
  );
}
