## `server/index.js`
```js
import express from "express";
import cors from "cors";
import sqlite3 from "sqlite3";

const app = express();
const db = new sqlite3.Database("./survey.db");

app.use(cors());
app.use(express.json());

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      location TEXT NOT NULL,
      notes TEXT,
      createdAt TEXT NOT NULL,
      updatedAt TEXT NOT NULL
    )
  `);
});

app.get("/health", (req, res) => {
  res.json({ ok: true });
});

app.get("/surveys", (req, res) => {
  db.all("SELECT * FROM surveys ORDER BY createdAt DESC", [], (err, rows) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json(rows);
  });
});

app.post("/sync", (req, res) => {
  const { surveys } = req.body;

  if (!Array.isArray(surveys)) {
    return res.status(400).json({ error: "surveys must be an array" });
  }

  const stmt = db.prepare(`
    INSERT INTO surveys (id, name, location, notes, createdAt, updatedAt)
    VALUES (?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      name=excluded.name,
      location=excluded.location,
      notes=excluded.notes,
      updatedAt=excluded.updatedAt
  `);

  db.serialize(() => {
    for (const s of surveys) {
      stmt.run(
        s.id,
        s.name,
        s.location,
        s.notes || "",
        s.createdAt,
        s.updatedAt
      );
    }
    stmt.finalize((err) => {
      if (err) return res.status(500).json({ error: err.message });
      res.json({ ok: true, synced: surveys.length });
    });
  });
});

app.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

