## `client/src/db.js`
```js
import { openDB } from "idb";

export const dbPromise = openDB("survey-app", 1, {
  upgrade(db) {
    const store = db.createObjectStore("surveys", { keyPath: "id" });
    store.createIndex("status", "status");
  }
});

export async function saveSurvey(survey) {
  const db = await dbPromise;
  await db.put("surveys", survey);
}

export async function getAllSurveys() {
  const db = await dbPromise;
  return await db.getAll("surveys");
}

export async function getPendingSurveys() {
  const db = await dbPromise;
  return await db.getAllFromIndex("surveys", "status", "pending");
}

export async function markSynced(ids) {
  const db = await dbPromise;
  const tx = db.transaction("surveys", "readwrite");
  for (const id of ids) {
    const item = await tx.store.get(id);
    if (item) {
      item.status = "synced";
      item.updatedAt = new Date().toISOString();
      await tx.store.put(item);
    }
  }
  await tx.done;
}
```

