## `client/src/main.jsx`
```jsx
import React, { useEffect, useState } from "react";
import ReactDOM from "react-dom/client";
import { saveSurvey, getAllSurveys, getPendingSurveys, markSynced } from "./db";
import { syncSurveys, fetchServerSurveys } from "./api";

function App() {
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [message, setMessage] = useState("");

  async function refreshLocal() {
    const items = await getAllSurveys();
    setSurveys(items.sort((a, b) => b.createdAt.localeCompare(a.createdAt)));
  }

  async function handleSubmit(e) {
    e.preventDefault();

    const now = new Date().toISOString();
    const survey = {
      id: crypto.randomUUID(),
      name,
      location,
      notes,
      status: "pending",
      createdAt: now,
      updatedAt: now
    };

    await saveSurvey(survey);
    setName("");
    setLocation("");
    setNotes("");
    setMessage("Saved locally. Will sync when online.");
    await refreshLocal();
  }

  async function doSync() {
    if (!navigator.onLine) {
      setMessage("Offline. Sync postponed.");
      return;
    }

    const pending = await getPendingSurveys();
    if (pending.length === 0) {
      setMessage("Nothing to sync.");
      return;
    }

    try {
      await syncSurveys(pending);
      await markSynced(pending.map((p) => p.id));
      setMessage(`Synced ${pending.length} survey(s).`);
      await refreshLocal();
    } catch (err) {
      setMessage(`Sync error: ${err.message}`);
    }
  }

  useEffect(() => {
    refreshLocal();
    const onOnline = () => {
      setOnline(true);
      doSync();
    };
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 700, margin: "40px auto" }}>
      <h1>Offline Survey App</h1>
      <p>
        Status: <strong>{online ? "Online" : "Offline"}</strong>
      </p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 12 }}>
        <input
          placeholder="Surveyor name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <button type="submit">Save Survey</button>
      </form>

      <div style={{ marginTop: 16 }}>
        <button onClick={doSync}>Sync Now</button>
        <button
          onClick={async () => {
            const serverData = await fetchServerSurveys();
            setMessage(`Server has ${serverData.length} survey(s).`);
          }}
          style={{ marginLeft: 8 }}
        >
          Check Server
        </button>
      </div>

      {message && <p style={{ marginTop: 16 }}>{message}</p>}

      <h2>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.name}</strong> — {s.location} — {s.status}
          </li>
        ))}
      </ul>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
