## 5) Frontend logic: `public/app.js`

```js
const DB_NAME = "survey-app-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

let db;

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");

function setStatus(msg, online) {
  statusEl.textContent = msg;
  statusEl.className = online ? "status online" : "status offline";
}

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function idbGetAll() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const req = store.getAll();

    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function idbPut(record) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const req = store.put(record);

    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

function idbDelete(id) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const req = store.delete(id);

    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

function renderSurveys(records) {
  surveyList.innerHTML = "";
  records
    .sort((a, b) => b.createdAt - a.createdAt)
    .forEach(record => {
      const li = document.createElement("li");
      li.innerHTML = `
        <strong>${record.siteName}</strong><br/>
        ${record.notes}<br/>
        (${record.lat}, ${record.lng})<br/>
        <small>${new Date(record.createdAt).toLocaleString()} | ${record.synced ? "Synced" : "Pending sync"}</small>
      `;
      surveyList.appendChild(li);
    });
}

async function refreshUI() {
  const records = await idbGetAll();
  renderSurveys(records);
}

async function syncPending() {
  if (!navigator.onLine) {
    setStatus("Offline - changes will sync later", false);
    return;
  }

  const records = await idbGetAll();
  const pending = records.filter(r => !r.synced);

  if (pending.length === 0) {
    setStatus("Online - all data synced", true);
    return;
  }

  try {
    const res = await fetch("/api/surveys/sync", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ records: pending })
    });

    if (!res.ok) throw new Error("Sync failed");

    for (const record of pending) {
      await idbPut({ ...record, synced: true });
    }

    setStatus(`Online - synced ${pending.length} record(s)`, true);
    await refreshUI();
  } catch (err) {
    setStatus("Online but sync failed - will retry", false);
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const record = {
    id: crypto.randomUUID(),
    siteName: document.getElementById("siteName").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    lat: Number(document.getElementById("lat").value),
    lng: Number(document.getElementById("lng").value),
    createdAt: Date.now(),
    synced: false
  };

  await idbPut(record);
  form.reset();
  await refreshUI();
  await syncPending();
});

window.addEventListener("online", syncPending);
window.addEventListener("offline", () => setStatus("Offline - changes will sync later", false));

(async function init() {
  db = await openDB();
  await refreshUI();

  if (navigator.onLine) {
    setStatus("Online", true);
    await syncPending();
  } else {
    setStatus("Offline - changes will sync later", false);
  }
})();
```

