```jsx
import React, { useEffect, useState } from "react";
import { surveyStore, queueStore } from "./db";
import { fetchSurveys, postSurvey } from "./api";

export default function App() {
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState("Loading...");

  async function loadLocal() {
    const items = [];
    await surveyStore.iterate((value) => items.push(value));
    setSurveys(items.sort((a, b) => b.createdAt.localeCompare(a.createdAt)));
  }

  async function saveOfflineSurvey(survey) {
    await surveyStore.setItem(survey.id, survey);
    await queueStore.setItem(survey.id, survey);
  }

  async function syncQueue() {
    if (!navigator.onLine) {
      setStatus("Offline: saved locally");
      return;
    }

    const pending = [];
    await queueStore.iterate((value) => pending.push(value));

    for (const survey of pending) {
      try {
        const synced = await postSurvey(survey);
        await surveyStore.setItem(synced.id, { ...survey, ...synced, synced: true });
        await queueStore.removeItem(survey.id);
      } catch (err) {
        console.error(err);
      }
    }

    setStatus(pending.length ? "Synced pending surveys" : "Online");
    await loadLocal();
  }

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: crypto.randomUUID(),
      name,
      location,
      notes,
      createdAt: new Date().toISOString(),
      synced: false
    };

    await saveOfflineSurvey(survey);
    setName("");
    setLocation("");
    setNotes("");
    setStatus(navigator.onLine ? "Saved locally, syncing..." : "Saved locally offline");
    await loadLocal();
    await syncQueue();
  }

  useEffect(() => {
    loadLocal();
    syncQueue();

    const onOnline = () => syncQueue();
    window.addEventListener("online", onOnline);

    return () => window.removeEventListener("online", onOnline);
  }, []);

  return (
    <div style={{ maxWidth: 700, margin: "40px auto", fontFamily: "sans-serif" }}>
      <h1>Offline Field Survey App</h1>
      <p><strong>Status:</strong> {status}</p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 12, marginBottom: 24 }}>
        <input
          placeholder="Surveyor name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          required
        />
        <button type="submit">Save Survey</button>
      </form>

