```js
import express from "express";
import cors from "cors";
import fs from "fs/promises";
import path from "path";
import { fileURLToPath } from "url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const DB_PATH = path.join(__dirname, "db.json");

const app = express();
app.use(cors());
app.use(express.json());

async function readDB() {
  const raw = await fs.readFile(DB_PATH, "utf-8");
  return JSON.parse(raw);
}

async function writeDB(db) {
  await fs.writeFile(DB_PATH, JSON.stringify(db, null, 2));
}

app.get("/api/surveys", async (_req, res) => {
  const db = await readDB();
  res.json(db.surveys);
});

app.post("/api/surveys/bulk", async (req, res) => {
  const { surveys } = req.body;

  if (!Array.isArray(surveys)) {
    return res.status(400).json({ error: "surveys must be an array" });
  }

  const db = await readDB();
  const existingIds = new Set(db.surveys.map(s => s.id));

  const inserted = [];
  for (const survey of surveys) {
    if (!survey.id || existingIds.has(survey.id)) continue;
    db.surveys.push({
      ...survey,
      syncedAt: new Date().toISOString()
    });
    existingIds.add(survey.id);
    inserted.push(survey.id);
  }

  await writeDB(db);
  res.json({ ok: true, inserted });
});

app.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
```

