## `client/app.js`

```js
const API_URL = "http://localhost:3000/api/surveys";
const DB_NAME = "survey-app";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: "id" });
        store.createIndex("synced", "synced", { unique: false });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function id() {
  return crypto.randomUUID();
}

function setStatus(text) {
  document.getElementById("status").textContent = text;
}

function getAllLocalSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const req = store.getAll();

    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function saveLocalSurvey(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const req = store.put(survey);

    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

function updateLocalSurvey(survey) {
  return saveLocalSurvey(survey);
}

async function renderSurveys() {
  const surveys = await getAllLocalSurveys();
  const list = document.getElementById("surveyList");
  list.innerHTML = "";

  surveys
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach(s => {
      const li = document.createElement("li");
      li.textContent = `${s.siteName} (${s.lat}, ${s.lng}) - ${s.synced ? "Synced" : "Pending sync"}`;
      list.appendChild(li);
    });
}

async function syncSurveys() {
  if (!navigator.onLine) {
    setStatus("Offline: cannot sync right now.");
    return;
  }

  const surveys = await getAllLocalSurveys();
  const pending = surveys.filter(s => !s.synced);

  if (pending.length === 0) {
    setStatus("All surveys are already synced.");
    return;
  }

  try {
    const res = await fetch(`${API_URL}/bulk`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ surveys: pending })
    });

    if (!res.ok) throw new Error("Sync failed");

    for (const survey of pending) {
      await updateLocalSurvey({ ...survey, synced: true, syncedAt: new Date().toISOString() });
    }

    setStatus(`Synced ${pending.length} survey(s).`);
    await renderSurveys();
  } catch (err) {
    console.error(err);
    setStatus("Sync failed. Will retry when online.");
  }
}

document.getElementById("surveyForm").addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: id(),
    siteName: document.getElementById("siteName").value.trim(),
    lat: Number(document.getElementById("lat").value),
    lng: Number(document.getElementById("lng").value),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  await saveLocalSurvey(survey);
  e.target.reset();
  setStatus("Survey saved locally.");
  await renderSurveys();

  if (navigator.onLine) {
    await syncSurveys();
  }
});

document.getElementById("syncBtn").addEventListener("click", syncSurveys);

window.addEventListener("online", async () => {
  setStatus("Back online. Syncing...");
  await syncSurveys();
});

window.addEventListener("offline", () => {
  setStatus("Offline mode: surveys will be saved locally.");
});

async function init() {
  db = await openDB();
  await renderSurveys();

  if (navigator.onLine) {
    setStatus("Online.");
    await syncSurveys();
  } else {
    setStatus("Offline mode: surveys will be saved locally.");
  }
}

init();
```

