```jsx
import React, { useEffect, useState } from "react";
import localforage from "localforage";

const API_URL = "http://localhost:3001";

const store = localforage.createInstance({
  name: "survey-app",
  storeName: "surveys"
});

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [online, setOnline] = useState(navigator.onLine);
  const [surveys, setSurveys] = useState([]);
  const [form, setForm] = useState({
    siteName: "",
    latitude: "",
    longitude: "",
    notes: ""
  });

  useEffect(() => {
    const handleOnline = () => {
      setOnline(true);
      syncPending();
    };
    const handleOffline = () => setOnline(false);

    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);

    loadLocal();

    return () => {
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
    };
  }, []);

  async function loadLocal() {
    const items = [];
    await store.iterate((value) => {
      items.push(value);
    });
    items.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
    setSurveys(items);
  }

  async function saveLocal(record) {
    await store.setItem(record.id, record);
    await loadLocal();
  }

  async function submitSurvey(e) {
    e.preventDefault();

    const now = new Date().toISOString();
    const record = {
      id: uuid(),
      siteName: form.siteName,
      latitude: Number(form.latitude),
      longitude: Number(form.longitude),
      notes: form.notes,
      createdAt: now,
      updatedAt: now,
      synced: false
    };

    await saveLocal(record);
    setForm({ siteName: "", latitude: "", longitude: "", notes: "" });

    if (online) {
      await syncPending();
    }
  }

  async function syncPending() {
    const items = [];
    await store.iterate((value) => {
      if (!value.synced) items.push(value);
    });

    for (const item of items) {
      try {
        const res = await fetch(`${API_URL}/surveys`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(item)
        });

        if (!res.ok) throw new Error("Sync failed");

        const updated = { ...item, synced: true };
        await store.setItem(item.id, updated);
      } catch (err) {
        console.error("Sync error:", err);
        break;
      }
    }

    await loadLocal();
  }

  return (
    <div style={{ maxWidth: 700, margin: "40px auto", fontFamily: "sans-serif" }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
      </p>

      <form onSubmit={submitSurvey} style={{ display: "grid", gap: 12, marginBottom: 24 }}>
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
          required
        />
        <input
          placeholder="Latitude"
          type="number"
          step="any"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: e.target.value })}
          required
        />
        <input
          placeholder="Longitude"
          type="number"
          step="any"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save Survey</button>
      </form>

      <button onClick={syncPending} disabled={!online}>
        Sync Pending
      </button>

      <h2 style={{ marginTop: 24 }}>Saved Surveys</h2>
      <ul style={{ paddingLeft: 18 }}>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <div><strong>{s.siteName}</strong></div>
            <div>
              {s.latitude}, {s.longitude}
            </div>
            <div>{s.notes}</div>
            <div style={{ fontSize: 12, color: "#666" }}>
              {s.synced ? "Synced" : "Pending sync"} | {s.createdAt}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

