## 5) Frontend logic: `public/app.js`

This uses IndexedDB to store surveys locally and syncs them when online.

```js
const DB_NAME = "survey-db";
const DB_VERSION = 1;
const STORE_NAME = "surveys";

let db;

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");

function updateStatus() {
  const online = navigator.onLine;
  statusEl.textContent = online ? "Online" : "Offline";
  statusEl.className = online ? "status online" : "status offline";
}

window.addEventListener("online", async () => {
  updateStatus();
  await syncSurveys();
});

window.addEventListener("offline", updateStatus);

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (event) => {
      const db = event.target.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function addSurveyLocal(survey) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const req = store.put(survey);

    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

function getAllLocalSurveys() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const req = store.getAll();

    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function deleteLocalSurvey(id) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    const req = store.delete(id);

    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

async function renderSurveys() {
  const surveys = await getAllLocalSurveys();
  surveyList.innerHTML = "";

  surveys
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .forEach((survey) => {
      const li = document.createElement("li");
      li.innerHTML = `
        <strong>${survey.name}</strong><br />
        Location: ${survey.location}<br />
        Notes: ${survey.notes || ""}<br />
        <small>${new Date(survey.createdAt).toLocaleString()}</small>
      `;
      surveyList.appendChild(li);
    });
}

async function syncSurveys() {
  if (!navigator.onLine) return;

  const surveys = await getAllLocalSurveys();

  // In this minimal version, we treat all local records as pending sync.
  // A real app would track sync status separately.
  if (surveys.length === 0) return;

  try {
    const response = await fetch("/api/surveys/sync", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ items: surveys }),
    });

    if (!response.ok) throw new Error("Sync failed");

    // Clear local store after successful sync
    for (const survey of surveys) {
      await deleteLocalSurvey(survey.id);
    }

    await renderSurveys();
    updateStatus();
    console.log("Synced successfully");
  } catch (err) {
    console.error("Sync error:", err);
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString(),
  };

  await addSurveyLocal(survey);
  form.reset();
  await renderSurveys();

  if (navigator.onLine) {
    await syncSurveys();
  }
});

(async function init() {
  db = await openDB();
  updateStatus();
  await renderSurveys();

  if (navigator.onLine) {
    await syncSurveys();
  }
})();
```

