## 3) Backend: minimal Express server

### `server.js`

```js
const express = require("express");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const PORT = 3001;

// In-memory store for minimal demo
const db = new Map();

// Get all records
app.get("/records", (req, res) => {
  res.json(Array.from(db.values()));
});

// Batch upsert records
app.post("/sync", (req, res) => {
  const { records } = req.body;

  if (!Array.isArray(records)) {
    return res.status(400).json({ error: "records must be an array" });
  }

  const applied = [];
  for (const record of records) {
    const existing = db.get(record.id);

    if (!existing || new Date(record.updatedAt) > new Date(existing.updatedAt)) {
      db.set(record.id, { ...record });
      applied.push(record.id);
    }
  }

  res.json({
    success: true,
    applied,
    serverRecords: Array.from(db.values()),
  });
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

