### `src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import { getAllRecords, getPendingRecords, putRecord, putRecords } from "./db";
import { syncRecords, fetchServerRecords } from "./api";

export default function App() {
  const [records, setRecords] = useState([]);
  const [form, setForm] = useState({
    siteName: "",
    latitude: "",
    longitude: "",
    notes: "",
  });
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState("");

  async function loadRecords() {
    const local = await getAllRecords();
    setRecords(local);
  }

  async function handleSubmit(e) {
    e.preventDefault();

    const record = {
      id: uuidv4(),
      siteName: form.siteName,
      latitude: Number(form.latitude),
      longitude: Number(form.longitude),
      notes: form.notes,
      updatedAt: new Date().toISOString(),
      synced: false,
    };

    await putRecord(record);
    setForm({ siteName: "", latitude: "", longitude: "", notes: "" });
    await loadRecords();
    setStatus("Saved locally");
  }

  async function handleSync() {
    try {
      setStatus("Syncing...");
      const pending = await getPendingRecords();

      if (pending.length === 0) {
        setStatus("Nothing to sync");
        return;
      }

      const result = await syncRecords(pending);

      const syncedRecords = pending.map((r) => ({ ...r, synced: true }));
      await putRecords(syncedRecords);

      await loadRecords();
      setStatus(`Synced ${result.applied.length} record(s)`);
    } catch (err) {
      setStatus(`Sync failed: ${err.message}`);
    }
  }

  async function handlePull() {
    try {
      const serverRecords = await fetchServerRecords();
      const merged = serverRecords.map((r) => ({ ...r, synced: true }));
      await putRecords(merged);
      await loadRecords();
      setStatus("Pulled latest server data");
    } catch (err) {
      setStatus(`Pull failed: ${err.message}`);
    }
  }

  useEffect(() => {
    loadRecords();

    const onOnline = () => {
      setOnline(true);
      handleSync();
    };
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", padding: 20, maxWidth: 800 }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Status: <strong>{online ? "Online" : "Offline"}</strong>
      </p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 8, marginBottom: 20 }}>
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
          required
        />
        <input
          placeholder="Latitude"
          type="number"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: e.target.value })}
          required
        />
        <input
          placeholder="Longitude"
          type="number"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save locally</button>
      </form>

      <div style={{ display: "flex", gap: 8, marginBottom: 20 }}>
        <button onClick={handleSync}>Sync now</button>
        <button onClick={handlePull}>Pull server data</button>
      </div>

      <p>{status}</p>

      <h2>Local Records</h2>
      <ul>
        {records.map((r) => (
          <li key={r.id}>
            <strong>{r.siteName}</strong> — {r.latitude}, {r.longitude}
            <br />
            {r.notes}
            <br />
            <small>
              Updated: {r.updatedAt} | {r.synced ? "Synced" : "Pending"}
            </small>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

