## `server/index.js`

```js
import express from "express";
import cors from "cors";
import { randomUUID } from "crypto";
import db from "./db.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/health", (req, res) => {
  res.json({ ok: true });
});

// Get all surveys
app.get("/surveys", (req, res) => {
  db.all("SELECT * FROM surveys ORDER BY createdAt DESC", [], (err, rows) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json(rows);
  });
});

// Sync batch from client
app.post("/sync", (req, res) => {
  const { surveys } = req.body;

  if (!Array.isArray(surveys)) {
    return res.status(400).json({ error: "surveys must be an array" });
  }

  const results = [];
  const now = new Date().toISOString();

  db.serialize(() => {
    const stmt = db.prepare(`
      INSERT INTO surveys (id, siteName, latitude, longitude, notes, createdAt, updatedAt)
      VALUES (?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET
        siteName=excluded.siteName,
        latitude=excluded.latitude,
        longitude=excluded.longitude,
        notes=excluded.notes,
        updatedAt=excluded.updatedAt
    `);

    for (const s of surveys) {
      const id = s.id || randomUUID();
      stmt.run(
        id,
        s.siteName,
        s.latitude,
        s.longitude,
        s.notes || "",
        s.createdAt || now,
        now
      );
      results.push({ ...s, id, updatedAt: now, syncStatus: "synced" });
    }

    stmt.finalize((err) => {
      if (err) return res.status(500).json({ error: err.message });
      res.json({ ok: true, synced: results });
    });
  });
});

app.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

