import { openDB } from "idb";

export const dbPromise = openDB("survey-app", 1, {
  upgrade(db) {
    const store = db.createObjectStore("surveys", { keyPath: "id" });
    store.createIndex("syncStatus", "syncStatus");
  }
});

export async function getAllSurveys() {
  const db = await dbPromise;
  return db.getAll("surveys");
}

export async function saveSurvey(survey) {
  const db = await dbPromise;
  return db.put("surveys", survey);
}

export async function getPendingSurveys() {
  const db = await dbPromise;
  return db.getAllFromIndex("surveys", "syncStatus", "pending_sync");
}

export async function markSynced(id, serverData) {
  const db = await dbPromise;
  const existing = await db.get("surveys", id);
  if (!existing) return;
  await db.put("surveys", {
    ...existing,
    ...serverData,
    syncStatus: "synced"
  });
}
