## `client/src/sync.js`

```js
import { getPendingSurveys, markSynced } from "./db";

const API_URL = "http://localhost:3001";

export async function syncPendingSurveys() {
  if (!navigator.onLine) return { ok: false, reason: "offline" };

  const pending = await getPendingSurveys();
  if (pending.length === 0) return { ok: true, synced: 0 };

  const res = await fetch(`${API_URL}/sync`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ surveys: pending })
  });

  if (!res.ok) {
    throw new Error("Sync failed");
  }

  const data = await res.json();

  for (const item of data.synced) {
    await markSynced(item.id, item);
  }

  return { ok: true, synced: data.synced.length };
}
```

