import React, { useEffect, useState } from "react";
import { getAllSurveys, saveSurvey } from "./db";
import { syncPendingSurveys } from "./sync";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [form, setForm] = useState({
    siteName: "",
    latitude: "",
    longitude: "",
    notes: ""
  });
  const [message, setMessage] = useState("");

  async function refresh() {
    const all = await getAllSurveys();
    setSurveys(all.sort((a, b) => b.createdAt.localeCompare(a.createdAt)));
  }

  useEffect(() => {
    refresh();

    const onOnline = async () => {
      setOnline(true);
      try {
        const result = await syncPendingSurveys();
        if (result.synced) setMessage(`Synced ${result.synced} survey(s).`);
      } catch (e) {
        setMessage("Back online, but sync failed.");
      }
      refresh();
    };

    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: uuid(),
      siteName: form.siteName,
      latitude: Number(form.latitude),
      longitude: Number(form.longitude),
      notes: form.notes,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      syncStatus: navigator.onLine ? "pending_sync" : "pending_sync"
    };

    await saveSurvey(survey);
    setForm({ siteName: "", latitude: "", longitude: "", notes: "" });
    setMessage("Saved locally.");

    await refresh();

    if (navigator.onLine) {
      try {
        const result = await syncPendingSurveys();
        if (result.synced) setMessage(`Saved locally and synced ${result.synced} survey(s).`);
        await refresh();
      } catch {
        setMessage("Saved locally, sync will retry later.");
      }
    }
  }

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 800, margin: "2rem auto" }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
      </p>

      {message && <p>{message}</p>}

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: "0.75rem", marginBottom: "2rem" }}>
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
          required
        />
        <input
          placeholder="Latitude"
          type="number"
          step="any"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: e.target.value })}
          required
        />
        <input
          placeholder="Longitude"
          type="number"
          step="any"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save Survey</button>
      </form>

      <button
        onClick={async () => {
          try {
            const result = await syncPendingSurveys();
            setMessage(`Manual sync complete: ${result.synced || 0} item(s).`);
            await refresh();
          } catch (e) {
            setMessage("Manual sync failed.");
          }
        }}
      >
        Sync Now
      </button>

      <h2>Local Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: "1rem" }}>
            <strong>{s.siteName}</strong> — {s.latitude}, {s.longitude}
            <br />
            <small>Status: {s.syncStatus}</small>
            <br />
            <small>{s.notes}</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
