### `client/app.js`
```js
const API_BASE = "http://localhost:3001/api";
const DB_NAME = "survey-db";
const DB_VERSION = 1;
const STORE_NAME = "pending-surveys";

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const queueList = document.getElementById("queueList");
const syncedList = document.getElementById("syncedList");
const refreshSyncedBtn = document.getElementById("refreshSynced");

let db;

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function idbAdd(record) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.put(record);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function idbGetAll() {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const store = tx.objectStore(STORE_NAME);
    const request = store.getAll();
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function idbDelete(id) {
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    const store = tx.objectStore(STORE_NAME);
    store.delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

function setStatus() {
  const online = navigator.onLine;
  statusEl.textContent = online ? "Online" : "Offline - saving locally";
  statusEl.className = `status ${online ? "online" : "offline"}`;
}

function renderQueue(items) {
  queueList.innerHTML = "";
  if (items.length === 0) {
    queueList.innerHTML = "<li>No pending surveys</li>";
    return;
  }

  items.forEach(item => {
    const li = document.createElement("li");
    li.textContent = `${item.name} (${item.id})`;
    queueList.appendChild(li);
  });
}

async function renderLocalQueue() {
  const items = await idbGetAll();
  renderQueue(items);
}

async function renderSynced() {
  const res = await fetch(`${API_BASE}/surveys`);
  const items = await res.json();

  syncedList.innerHTML = "";
  if (items.length === 0) {
    syncedList.innerHTML = "<li>No synced surveys yet</li>";
    return;
  }

  items.forEach(item => {
    const li = document.createElement("li");
    li.textContent = `${item.name} — synced at ${item.syncedAt}`;
    syncedList.appendChild(li);
  });
}

async function syncPending() {
  if (!navigator.onLine) return;

  const pending = await idbGetAll();
  for (const survey of pending) {
    try {
      const res = await fetch(`${API_BASE}/surveys`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await idbDelete(survey.id);
      }
    } catch (err) {
      console.error("Sync failed:", err);
      return;
    }
  }

  await renderLocalQueue();
  await renderSynced();
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    lat: document.getElementById("lat").value ? Number(document.getElementById("lat").value) : null,
    lng: document.getElementById("lng").value ? Number(document.getElementById("lng").value) : null,
    createdAt: new Date().toISOString()
  };

  await idbAdd(survey);
  form.reset();
  await renderLocalQueue();

  if (navigator.onLine) {
    await syncPending();
  }
});

window.addEventListener("online", async () => {
  setStatus();
  await syncPending();
});

window.addEventListener("offline", setStatus);

refreshSyncedBtn.addEventListener("click", renderSynced);

(async function init() {
  db = await openDB();
  setStatus();
  await renderLocalQueue();
  await renderSynced();
  await syncPending();
})();
```

