## 2) Backend: `server.js`

This server stores survey records in memory for simplicity and exposes sync endpoints.

```js
const express = require("express");
const cors = require("cors");
const bodyParser = require("body-parser");

const app = express();
const PORT = 3000;

app.use(cors());
app.use(bodyParser.json());
app.use(express.static("public"));

// In-memory "database"
let surveys = new Map(); // id -> survey

// Return all surveys
app.get("/api/surveys", (req, res) => {
  res.json(Array.from(surveys.values()));
});

// Sync endpoint: accepts local changes and returns server state
app.post("/api/sync", (req, res) => {
  const { changes } = req.body;

  const applied = [];
  const conflicts = [];

  for (const change of changes || []) {
    const existing = surveys.get(change.id);

    if (!existing) {
      surveys.set(change.id, change);
      applied.push(change.id);
      continue;
    }

    // Simple last-write-wins based on updatedAt
    if (!existing.updatedAt || change.updatedAt >= existing.updatedAt) {
      surveys.set(change.id, change);
      applied.push(change.id);
    } else {
      conflicts.push({
        id: change.id,
        server: existing,
        client: change,
      });
    }
  }

  res.json({
    ok: true,
    applied,
    conflicts,
    serverState: Array.from(surveys.values()),
  });
});

// Seed example data
app.post("/api/seed", (req, res) => {
  const sample = {
    id: crypto.randomUUID(),
    name: "Sample Survey",
    location: "Plot A",
    notes: "Initial server record",
    updatedAt: Date.now(),
  };
  surveys.set(sample.id, sample);
  res.json(sample);
});

app.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

