## 5) Frontend logic: `public/app.js`

This uses **IndexedDB** for offline storage and a **sync queue**.

```js
const DB_NAME = "survey-db";
const DB_VERSION = 1;
const SURVEYS_STORE = "surveys";
const QUEUE_STORE = "queue";

let db;

const statusEl = document.getElementById("status");
const surveyForm = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");
const syncBtn = document.getElementById("syncBtn");

function setStatus(online) {
  statusEl.textContent = online ? "Online" : "Offline";
  statusEl.className = `status ${online ? "online" : "offline"}`;
}

window.addEventListener("online", () => {
  setStatus(true);
  sync();
});

window.addEventListener("offline", () => setStatus(false));

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = (e) => {
      const db = e.target.result;
      if (!db.objectStoreNames.contains(SURVEYS_STORE)) {
        db.createObjectStore(SURVEYS_STORE, { keyPath: "id" });
      }
      if (!db.objectStoreNames.contains(QUEUE_STORE)) {
        db.createObjectStore(QUEUE_STORE, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

function tx(storeName, mode = "readonly") {
  return db.transaction(storeName, mode).objectStore(storeName);
}

function getAll(storeName) {
  return new Promise((resolve, reject) => {
    const req = tx(storeName).getAll();
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function put(storeName, value) {
  return new Promise((resolve, reject) => {
    const req = tx(storeName, "readwrite").put(value);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

function del(storeName, key) {
  return new Promise((resolve, reject) => {
    const req = tx(storeName, "readwrite").delete(key);
    req.onsuccess = () => resolve();
    req.onerror = () => reject(req.error);
  });
}

async function renderSurveys() {
  const surveys = await getAll(SURVEYS_STORE);
  surveyList.innerHTML = "";

  surveys
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .forEach((s) => {
      const li = document.createElement("li");
      li.innerHTML = `
        <strong>${s.name}</strong><br/>
        <small>${s.location}</small><br/>
        <small>${s.notes || ""}</small><br/>
        <small>Updated: ${new Date(s.updatedAt).toLocaleString()}</small>
      `;
      surveyList.appendChild(li);
    });
}

async function addSurvey(name, location, notes) {
  const survey = {
    id: crypto.randomUUID(),
    name,
    location,
    notes,
    updatedAt: Date.now(),
  };

  await put(SURVEYS_STORE, survey);
  await put(QUEUE_STORE, { id: survey.id, type: "upsert", payload: survey });

  await renderSurveys();
}

async function sync() {
  if (!navigator.onLine) return;

  const queue = await getAll(QUEUE_STORE);
  if (queue.length === 0) return;

  try {
    const changes = queue.map((q) => q.payload);
    const res = await fetch("/api/sync", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ changes }),
    });

    const data = await res.json();

    // Update local store with server state
    for (const serverSurvey of data.serverState || []) {
      await put(SURVEYS_STORE, serverSurvey);
    }

    // Clear queue after successful sync
    for (const item of queue) {
      await del(QUEUE_STORE, item.id);
    }

    await renderSurveys();
    console.log("Sync complete", data);
  } catch (err) {
    console.error("Sync failed:", err);
  }
}

surveyForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const name = document.getElementById("name").value.trim();
  const location = document.getElementById("location").value.trim();
  const notes = document.getElementById("notes").value.trim();

  if (!name || !location) return;

  await addSurvey(name, location, notes);
  surveyForm.reset();

  if (navigator.onLine) {
    await sync();
  }
});

syncBtn.addEventListener("click", sync);

(async function init() {
  db = await openDB();
  setStatus(navigator.onLine);
  await renderSurveys();

  // Try syncing on startup if online
  if (navigator.onLine) {
    await sync();
  }
})();
```

