const form = document.getElementById("surveyForm");
const siteNameInput = document.getElementById("siteName");
const notesInput = document.getElementById("notes");
const surveyList = document.getElementById("surveyList");
const statusEl = document.getElementById("status");
const syncBtn = document.getElementById("syncBtn");

const LOCAL_KEY = "offline_surveys";
const API_BASE = "http://localhost:3000";

function getLocalSurveys() {
  return JSON.parse(localStorage.getItem(LOCAL_KEY) || "[]");
}

function saveLocalSurveys(surveys) {
  localStorage.setItem(LOCAL_KEY, JSON.stringify(surveys));
}

function renderSurveys() {
  const surveys = getLocalSurveys();
  surveyList.innerHTML = "";

  surveys.forEach((s) => {
    const li = document.createElement("li");
    li.innerHTML = `
      <strong>${s.siteName}</strong><br/>
      ${s.notes}<br/>
      <small>${new Date(s.createdAt).toLocaleString()} ${s.synced ? "(synced)" : "(pending sync)"}</small>
    `;
    surveyList.appendChild(li);
  });
}

function updateStatus() {
  statusEl.textContent = navigator.onLine
    ? "Online - ready to sync"
    : "Offline - saving locally";
}

async function syncSurveys() {
  if (!navigator.onLine) {
    updateStatus();
    return;
  }

  const surveys = getLocalSurveys();
  const pending = surveys.filter((s) => !s.synced);

  if (pending.length === 0) {
    updateStatus();
    return;
  }

  try {
    const res = await fetch(`${API_BASE}/api/sync`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ records: pending })
    });

    if (!res.ok) throw new Error("Sync failed");

    const updated = surveys.map((s) =>
      pending.some((p) => p.id === s.id) ? { ...s, synced: true } : s
    );

    saveLocalSurveys(updated);
    renderSurveys();
    updateStatus();
  } catch (err) {
    console.error(err);
    statusEl.textContent = "Sync failed - will retry later";
  }
}

form.addEventListener("submit", (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    siteName: siteNameInput.value.trim(),
    notes: notesInput.value.trim(),
    createdAt: new Date().toISOString(),
    synced: false
  };

  const surveys = getLocalSurveys();
  surveys.unshift(survey);
  saveLocalSurveys(surveys);

  form.reset();
  renderSurveys();
  updateStatus();

  // Try syncing immediately if online
  syncSurveys();
});

syncBtn.addEventListener("click", syncSurveys);

window.addEventListener("online", () => {
  updateStatus();
  syncSurveys();
});

window.addEventListener("offline", updateStatus);

updateStatus();
renderSurveys();
syncSurveys();
```

