## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { getAllSurveys, saveSurvey, deleteSurvey } from "./db";
import { fetchSurveys, syncSurveys } from "./api";
import "./styles.css";

function uid() {
  return crypto.randomUUID();
}

export default function App() {
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState("Loading...");
  const [online, setOnline] = useState(navigator.onLine);

  async function loadLocal() {
    const local = await getAllSurveys();
    setSurveys(local.sort((a, b) => b.createdAt - a.createdAt));
  }

  async function trySync() {
    if (!navigator.onLine) {
      setStatus("Offline: saved locally");
      return;
    }

    const local = await getAllSurveys();
    const pending = local.filter((s) => !s.synced);

    if (pending.length === 0) {
      setStatus("All data synced");
      return;
    }

    try {
      await syncSurveys(pending);
      for (const s of pending) {
        await saveSurvey({ ...s, synced: true });
      }
      setStatus(`Synced ${pending.length} record(s)`);
      await loadLocal();
    } catch {
      setStatus("Sync failed, will retry later");
    }
  }

  useEffect(() => {
    const onOnline = async () => {
      setOnline(true);
      await trySync();
    };
    const onOffline = () => {
      setOnline(false);
      setStatus("Offline: saved locally");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    (async () => {
      await loadLocal();
      await trySync();
      try {
        const remote = await fetchSurveys();
        setStatus(`Connected: ${remote.length} server record(s)`);
      } catch {
        setStatus("Offline or server unavailable");
      }
    })();

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: uid(),
      name,
      location,
      notes,
      createdAt: Date.now(),
      synced: false
    };

    await saveSurvey(survey);
    setName("");
    setLocation("");
    setNotes("");
    await loadLocal();
    await trySync();
  }

  return (
    <div className="container">
      <h1>Offline Field Survey App</h1>
      <p className={online ? "online" : "offline"}>
        {online ? "Online" : "Offline"} — {status}
      </p>

      <form onSubmit={handleSubmit} className="card">
        <input
          placeholder="Surveyor name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <button type="submit">Save Survey</button>
      </form>

      <div className="card">
        <h2>Saved Surveys</h2>
        {surveys.length === 0 ? (
          <p>No surveys yet.</p>
        ) : (
          <ul>
            {surveys.map((s) => (
              <li key={s.id}>
                <strong>{s.name}</strong> @ {s.location}
                <br />
                <small>{new Date(s.createdAt).toLocaleString()}</small>
                <br />
                <small>{s.synced ? "Synced" : "Pending sync"}</small>
                <br />
                {s.notes && <span>{s.notes}</span>}
                <br />
                <button
                  onClick={async () => {
                    await deleteSurvey(s.id);
                    await loadLocal();
                  }}
                >
                  Delete
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
```

