### `server/index.js`
```js
import express from "express";
import cors from "cors";
import sqlite3 from "sqlite3";
import { open } from "sqlite";

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());

const db = await open({
  filename: "./surveys.db",
  driver: sqlite3.Database
});

await db.exec(`
  CREATE TABLE IF NOT EXISTS surveys (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    location TEXT NOT NULL,
    notes TEXT,
    createdAt TEXT NOT NULL
  )
`);

app.get("/api/surveys", async (req, res) => {
  const rows = await db.all("SELECT * FROM surveys ORDER BY createdAt DESC");
  res.json(rows);
});

app.post("/api/surveys", async (req, res) => {
  const { id, name, location, notes, createdAt } = req.body;

  if (!id || !name || !location || !createdAt) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  try {
    await db.run(
      `INSERT INTO surveys (id, name, location, notes, createdAt)
       VALUES (?, ?, ?, ?, ?)`,
      [id, name, location, notes || "", createdAt]
    );
    res.status(201).json({ ok: true });
  } catch (err) {
    if (String(err).includes("UNIQUE")) {
      return res.status(200).json({ ok: true, duplicate: true });
    }
    res.status(500).json({ error: "Database error" });
  }
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

> Note: This uses `sqlite` package for `open()`. Install it too:
```bash
npm install sqlite
```

