### `client/app.js`
```js
const API_URL = "http://localhost:3000/api/surveys";
const DB_NAME = "field-survey-db";
const STORE_NAME = "pending-surveys";

const statusEl = document.getElementById("status");
const form = document.getElementById("surveyForm");
const surveyList = document.getElementById("surveyList");

function setStatus() {
  statusEl.textContent = navigator.onLine
    ? "Status: online"
    : "Status: offline (saving locally)";
}

window.addEventListener("online", async () => {
  setStatus();
  await syncPendingSurveys();
});

window.addEventListener("offline", setStatus);

setStatus();

function openDB() {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);

    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: "id" });
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function saveLocally(survey) {
  const db = await openDB();
  const tx = db.transaction(STORE_NAME, "readwrite");
  tx.objectStore(STORE_NAME).put(survey);
  return tx.complete;
}

async function getAllLocalSurveys() {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readonly");
    const request = tx.objectStore(STORE_NAME).getAll();
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function deleteLocalSurvey(id) {
  const db = await openDB();
  const tx = db.transaction(STORE_NAME, "readwrite");
  tx.objectStore(STORE_NAME).delete(id);
  return tx.complete;
}

async function syncPendingSurveys() {
  if (!navigator.onLine) return;

  const pending = await getAllLocalSurveys();

  for (const survey of pending) {
    try {
      const res = await fetch(API_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(survey)
      });

      if (res.ok) {
        await deleteLocalSurvey(survey.id);
      }
    } catch (err) {
      console.warn("Sync failed:", err);
      return;
    }
  }

  await loadSurveys();
}

async function loadSurveys() {
  surveyList.innerHTML = "";

  const local = await getAllLocalSurveys();

  local.forEach((survey) => {
    const li = document.createElement("li");
    li.textContent = `${survey.name} @ ${survey.location} (${survey.createdAt}) [pending sync]`;
    surveyList.appendChild(li);
  });

  if (navigator.onLine) {
    try {
      const res = await fetch(API_URL);
      const remote = await res.json();

      remote.forEach((survey) => {
        const li = document.createElement("li");
        li.textContent = `${survey.name} @ ${survey.location} (${survey.createdAt})`;
        surveyList.appendChild(li);
      });
    } catch (err) {
      console.warn("Could not load remote surveys:", err);
    }
  }
}

form.addEventListener("submit", async (e) => {
  e.preventDefault();

  const survey = {
    id: crypto.randomUUID(),
    name: document.getElementById("name").value.trim(),
    location: document.getElementById("location").value.trim(),
    notes: document.getElementById("notes").value.trim(),
    createdAt: new Date().toISOString()
  };

  if (!navigator.onLine) {
    await saveLocally(survey);
    form.reset();
    await loadSurveys();
    return;
  }

  try {
    const res = await fetch(API_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(survey)
    });

    if (res.ok) {
      form.reset();
      await loadSurveys();
    } else {
      await saveLocally(survey);
      form.reset();
      await loadSurveys();
    }
  } catch (err) {
    await saveLocally(survey);
    form.reset();
    await loadSurveys();
  }
});

loadSurveys();
```

