## 5) Important fix

The code above uses `tx.complete`, but **IndexedDB transactions don’t have `complete` in standard browser APIs**. Use a Promise wrapper instead.

Replace `saveLocally` and `deleteLocalSurvey` with this corrected version:

```js
async function saveLocally(survey) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).put(survey);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}

async function deleteLocalSurvey(id) {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(STORE_NAME, "readwrite");
    tx.objectStore(STORE_NAME).delete(id);
    tx.oncomplete = () => resolve();
    tx.onerror = () => reject(tx.error);
  });
}
```

