## `client/src/db.js`

This sets up IndexedDB for offline storage.

```js
import { openDB } from "idb";

export const dbPromise = openDB("survey-db", 1, {
  upgrade(db) {
    const store = db.createObjectStore("surveys", {
      keyPath: "id"
    });
    store.createIndex("synced", "synced");
  }
});

export async function saveSurvey(record) {
  const db = await dbPromise;
  await db.put("surveys", record);
}

export async function getAllSurveys() {
  const db = await dbPromise;
  return await db.getAll("surveys");
}

export async function getUnsyncedSurveys() {
  const db = await dbPromise;
  return await db.getAllFromIndex("surveys", "synced", false);
}

export async function markSurveySynced(id) {
  const db = await dbPromise;
  const record = await db.get("surveys", id);
  if (record) {
    record.synced = true;
    await db.put("surveys", record);
  }
}
```

