## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import {
  saveSurvey,
  getAllSurveys,
  getUnsyncedSurveys,
  markSurveySynced
} from "./db";

const API_URL = "http://localhost:3001";

export default function App() {
  const [siteName, setSiteName] = useState("");
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [notes, setNotes] = useState("");
  const [surveys, setSurveys] = useState([]);
  const [status, setStatus] = useState(navigator.onLine ? "Online" : "Offline");

  async function refreshLocalSurveys() {
    const all = await getAllSurveys();
    setSurveys(all.sort((a, b) => b.createdAt - a.createdAt));
  }

  async function syncSurveys() {
    if (!navigator.onLine) {
      setStatus("Offline - sync paused");
      return;
    }

    const unsynced = await getUnsyncedSurveys();
    if (unsynced.length === 0) {
      setStatus("Online - nothing to sync");
      return;
    }

    try {
      const response = await fetch(`${API_URL}/sync`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ records: unsynced })
      });

      if (!response.ok) throw new Error("Sync failed");

      for (const record of unsynced) {
        await markSurveySynced(record.id);
      }

      setStatus(`Synced ${unsynced.length} record(s)`);
      await refreshLocalSurveys();
    } catch (err) {
      setStatus("Sync error");
      console.error(err);
    }
  }

  async function handleSubmit(e) {
    e.preventDefault();

    const record = {
      id: crypto.randomUUID(),
      siteName,
      latitude: Number(latitude),
      longitude: Number(longitude),
      notes,
      createdAt: Date.now(),
      synced: false
    };

    await saveSurvey(record);
    setSiteName("");
    setLatitude("");
    setLongitude("");
    setNotes("");

    await refreshLocalSurveys();
    await syncSurveys();
  }

  useEffect(() => {
    refreshLocalSurveys();
    syncSurveys();

    const onOnline = () => {
      setStatus("Back online");
      syncSurveys();
    };

    const onOffline = () => setStatus("Offline");

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ maxWidth: 700, margin: "40px auto", fontFamily: "sans-serif" }}>
      <h1>Offline Survey App</h1>
      <p><strong>Status:</strong> {status}</p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 12 }}>
        <input
          placeholder="Site name"
          value={siteName}
          onChange={(e) => setSiteName(e.target.value)}
          required
        />
        <input
          placeholder="Latitude"
          value={latitude}
          onChange={(e) => setLatitude(e.target.value)}
          required
          type="number"
          step="any"
        />
        <input
          placeholder="Longitude"
          value={longitude}
          onChange={(e) => setLongitude(e.target.value)}
          required
          type="number"
          step="any"
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <button type="submit">Save Survey</button>
      </form>

      <h2 style={{ marginTop: 30 }}>Saved Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <div><strong>{s.siteName}</strong></div>
            <div>
              {s.latitude}, {s.longitude}
            </div>
            <div>{s.notes}</div>
            <div style={{ fontSize: 12, color: "#666" }}>
              {s.synced ? "Synced" : "Pending sync"}
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
```

