import express from "express";
import cors from "cors";
import db from "./db.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/api/surveys", (req, res) => {
  const rows = db.prepare("SELECT * FROM surveys ORDER BY createdAt DESC").all();
  res.json(rows);
});

app.post("/api/surveys", (req, res) => {
  const { id, name, location, notes, createdAt, updatedAt } = req.body;

  if (!id || !name || !location || !createdAt || !updatedAt) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const stmt = db.prepare(`
    INSERT INTO surveys (id, name, location, notes, createdAt, updatedAt)
    VALUES (@id, @name, @location, @notes, @createdAt, @updatedAt)
    ON CONFLICT(id) DO UPDATE SET
      name=excluded.name,
      location=excluded.location,
      notes=excluded.notes,
      updatedAt=excluded.updatedAt
  `);

  stmt.run({ id, name, location, notes: notes || "", createdAt, updatedAt });
  res.json({ ok: true });
});

app.listen(3001, () => {
