## `client/src/App.jsx`

```jsx
import { useEffect, useState } from "react";
import {
  saveSurveyLocal,
  getSurveysLocal,
  addPending
} from "./db";
import { syncPending } from "./sync";

const API = "http://localhost:3001/api/surveys";

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState("");

  async function loadLocal() {
    const local = await getSurveysLocal();
    setSurveys(local);
  }

  async function loadRemote() {
    try {
      const res = await fetch(API);
      if (!res.ok) throw new Error("Failed to fetch");
      const data = await res.json();
      setSurveys(data);
      for (const s of data) await saveSurveyLocal(s);
    } catch {
      // fallback to local
      await loadLocal();
    }
  }

  async function handleSubmit(e) {
    e.preventDefault();
    const form = new FormData(e.target);

    const survey = {
      id: crypto.randomUUID(),
      name: form.get("name"),
      location: form.get("location"),
      notes: form.get("notes"),
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    await saveSurveyLocal(survey);
    setSurveys((prev) => [survey, ...prev]);

    if (navigator.onLine) {
      try {
        const res = await fetch(API, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(survey)
        });
        if (!res.ok) throw new Error("Server rejected");
        setStatus("Saved and synced");
      } catch {
        await addPending(survey);
        setStatus("Saved locally, pending sync");
      }
    } else {
      await addPending(survey);
      setStatus("Saved locally, offline");
    }

    e.target.reset();
  }

  async function doSync() {
    if (!navigator.onLine) return;
    try {
      setStatus("Syncing...");
      await syncPending();
      await loadRemote();
      setStatus("Synced");
    } catch {
      setStatus("Sync failed, will retry later");
    }
  }

  useEffect(() => {
    loadRemote();

    const onOnline = async () => {
      setOnline(true);
      await doSync();
    };

    const onOffline = () => {
      setOnline(false);
      setStatus("Offline");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 700, margin: "2rem auto" }}>
      <h1>Field Survey App</h1>
      <p>
        Status: <strong>{online ? "Online" : "Offline"}</strong>
      </p>
      <p>{status}</p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: "0.75rem" }}>
        <input name="name" placeholder="Survey name" required />
        <input name="location" placeholder="Location" required />
        <textarea name="notes" placeholder="Notes" />
        <button type="submit">Save Survey</button>
      </form>

      <h2>Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id}>
            <strong>{s.name}</strong> — {s.location}
            <br />
            <small>{s.notes}</small>
          </li>
        ))}
      </ul>

      <button onClick={doSync} style={{ marginTop: "1rem" }}>
        Sync Now
      </button>
    </div>
  );
}
```

