import express from "express";
import cors from "cors";
import db from "./db.js";

const app = express();
app.use(cors());
app.use(express.json());

app.get("/health", (req, res) => {
  res.json({ ok: true });
});

app.get("/surveys", (req, res) => {
  const rows = db.prepare("SELECT * FROM surveys ORDER BY createdAt DESC").all();
  res.json(rows);
});

app.post("/surveys", (req, res) => {
  const { id, siteName, latitude, longitude, notes, createdAt, updatedAt } = req.body;

  if (!id || !siteName || latitude == null || longitude == null || !createdAt || !updatedAt) {
    return res.status(400).json({ error: "Missing required fields" });
  }

  const stmt = db.prepare(`
    INSERT INTO surveys (id, siteName, latitude, longitude, notes, createdAt, updatedAt)
    VALUES (@id, @siteName, @latitude, @longitude, @notes, @createdAt, @updatedAt)
    ON CONFLICT(id) DO UPDATE SET
      siteName=excluded.siteName,
      latitude=excluded.latitude,
      longitude=excluded.longitude,
      notes=excluded.notes,
      updatedAt=excluded.updatedAt
  `);

  stmt.run({ id, siteName, latitude, longitude, notes, createdAt, updatedAt });
  res.json({ ok: true });
});

app.listen(3001, () => {
