import { useEffect, useState } from "react";
import {
  addToQueue,
  getAllSurveys,
  getQueue,
  removeFromQueue,
  saveSurveyLocal
} from "./db";

const API = "http://localhost:3001";

function uuid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [online, setOnline] = useState(navigator.onLine);
  const [form, setForm] = useState({
    siteName: "",
    latitude: "",
    longitude: "",
    notes: ""
  });

  async function refreshLocal() {
    const local = await getAllSurveys();
    setSurveys(local);
  }

  async function syncQueue() {
    if (!navigator.onLine) return;

    const queue = await getQueue();
    for (const item of queue) {
      try {
        const res = await fetch(`${API}/surveys`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(item)
        });

        if (!res.ok) throw new Error("Sync failed");
        await removeFromQueue(item.id);
      } catch (e) {
        console.error("Sync error:", e);
        break;
      }
    }

    await refreshLocal();
  }

  useEffect(() => {
    refreshLocal();
    syncQueue();

    const onOnline = () => {
      setOnline(true);
      syncQueue();
    };
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  async function handleSubmit(e) {
    e.preventDefault();

    const survey = {
      id: uuid(),
      siteName: form.siteName,
      latitude: Number(form.latitude),
      longitude: Number(form.longitude),
      notes: form.notes,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    await saveSurveyLocal(survey);

    if (navigator.onLine) {
      try {
        const res = await fetch(`${API}/surveys`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(survey)
        });

        if (!res.ok) throw new Error("Server rejected");
      } catch {
        await addToQueue(survey);
      }
    } else {
      await addToQueue(survey);
    }

    setForm({ siteName: "", latitude: "", longitude: "", notes: "" });
    await refreshLocal();
  }

  return (
    <div style={{ maxWidth: 700, margin: "40px auto", fontFamily: "sans-serif" }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Status:{" "}
        <strong style={{ color: online ? "green" : "red" }}>
          {online ? "Online" : "Offline"}
        </strong>
      </p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 12, marginBottom: 24 }}>
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
          required
        />
        <input
          placeholder="Latitude"
          type="number"
          step="any"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: e.target.value })}
          required
        />
        <input
          placeholder="Longitude"
          type="number"
          step="any"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save Survey</button>
      </form>

      <button onClick={syncQueue} style={{ marginBottom: 16 }}>
        Sync Now
      </button>

