import { useEffect, useState } from "react";
import { getAllSurveys, saveSurvey, deleteSurvey } from "./db";
import { syncSurveys, fetchServerSurveys } from "./api";

function uid() {
  return crypto.randomUUID();
}

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [name, setName] = useState("");
  const [location, setLocation] = useState("");
  const [notes, setNotes] = useState("");
  const [online, setOnline] = useState(navigator.onLine);
  const [message, setMessage] = useState("");

  async function loadLocal() {
    const data = await getAllSurveys();
    setSurveys(data);
  }

  async function addSurvey(e) {
    e.preventDefault();

    const survey = {
      id: uid(),
      name,
      location,
      notes,
      createdAt: new Date().toISOString(),
      synced: false
    };

    await saveSurvey(survey);
    setName("");
    setLocation("");
    setNotes("");
    setMessage("Saved locally (offline-ready).");
    await loadLocal();
  }

  async function syncPending() {
    if (!navigator.onLine) {
      setMessage("Still offline. Cannot sync.");
      return;
    }

    const pending = (await getAllSurveys()).filter(s => !s.synced);

    if (pending.length === 0) {
      setMessage("Nothing to sync.");
      return;
    }

    try {
      await syncSurveys(pending);

      for (const record of pending) {
        await saveSurvey({ ...record, synced: true });
      }

      setMessage(`Synced ${pending.length} record(s).`);
      await loadLocal();
    } catch (err) {
      setMessage("Sync failed. Will retry when online.");
    }
  }

  async function refreshFromServer() {
    if (!navigator.onLine) return;
    try {
      const serverData = await fetchServerSurveys();
      setMessage(`Server has ${serverData.length} record(s).`);
    } catch {
      setMessage("Could not load server data.");
    }
  }

  useEffect(() => {
    loadLocal();
    refreshFromServer();

    const onOnline = () => {
      setOnline(true);
      setMessage("Back online.");
      syncPending();
    };

    const onOffline = () => {
      setOnline(false);
      setMessage("Offline mode enabled.");
    };

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 700, margin: "40px auto", padding: 16 }}>
      <h1>Offline Field Survey App</h1>
      <p>
        Status: <strong>{online ? "Online" : "Offline"}</strong>
      </p>

      <form onSubmit={addSurvey} style={{ display: "grid", gap: 8, marginBottom: 16 }}>
        <input
          placeholder="Surveyor name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          placeholder="Location"
          value={location}
          onChange={(e) => setLocation(e.target.value)}
          required
        />
        <textarea
          placeholder="Notes"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
        />
        <button type="submit">Save Survey Locally</button>
      </form>

      <button onClick={syncPending} style={{ marginBottom: 16 }}>
        Sync Pending Records
      </button>

      <button onClick={loadLocal} style={{ marginBottom: 16, marginLeft: 8 }}>
        Reload Local Data
      </button>

      <p>{message}</p>

      <h2>Local Records</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <div><strong>{s.name}</strong> @ {s.location}</div>
            <div>{s.notes}</div>
            <div style={{ fontSize: 12, color: "#666" }}>
              {s.createdAt} — {s.synced ? "Synced" : "Pending"}
            </div>
            <button onClick={async () => { await deleteSurvey(s.id); await loadLocal(); }}>
              Delete
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
