### `server/index.js`
```js
import express from "express";
import cors from "cors";
import sqlite3 from "sqlite3";

const app = express();
const db = new sqlite3.Database("./survey.db");

app.use(cors());
app.use(express.json());

db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS surveys (
      id TEXT PRIMARY KEY,
      siteName TEXT,
      observer TEXT,
      latitude REAL,
      longitude REAL,
      notes TEXT,
      createdAt TEXT,
      updatedAt TEXT
    )
  `);
});

// Get all surveys
app.get("/api/surveys", (req, res) => {
  db.all("SELECT * FROM surveys ORDER BY updatedAt DESC", [], (err, rows) => {
    if (err) return res.status(500).json({ error: err.message });
    res.json(rows);
  });
});

// Sync batch from client
app.post("/api/sync", (req, res) => {
  const { surveys } = req.body;

  if (!Array.isArray(surveys)) {
    return res.status(400).json({ error: "surveys must be an array" });
  }

  const stmt = db.prepare(`
    INSERT INTO surveys (id, siteName, observer, latitude, longitude, notes, createdAt, updatedAt)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      siteName=excluded.siteName,
      observer=excluded.observer,
      latitude=excluded.latitude,
      longitude=excluded.longitude,
      notes=excluded.notes,
      createdAt=excluded.createdAt,
      updatedAt=excluded.updatedAt
  `);

  db.serialize(() => {
    for (const s of surveys) {
      stmt.run(
        s.id,
        s.siteName,
        s.observer,
        s.latitude,
        s.longitude,
        s.notes,
        s.createdAt,
        s.updatedAt
      );
    }
    stmt.finalize((err) => {
      if (err) return res.status(500).json({ error: err.message });
      res.json({ ok: true, synced: surveys.length });
    });
  });
});

app.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

