### `client/src/App.jsx`
```jsx
import { useEffect, useState } from "react";
import { v4 as uuidv4 } from "uuid";
import { getAllSurveys, saveSurvey, getUnsyncedSurveys, markSynced } from "./db";
import { syncSurveys, fetchRemoteSurveys } from "./api";

export default function App() {
  const [surveys, setSurveys] = useState([]);
  const [form, setForm] = useState({
    siteName: "",
    observer: "",
    latitude: "",
    longitude: "",
    notes: ""
  });
  const [online, setOnline] = useState(navigator.onLine);
  const [status, setStatus] = useState("");

  async function loadLocal() {
    const local = await getAllSurveys();
    setSurveys(local.sort((a, b) => new Date(b.updatedAt) - new Date(a.updatedAt)));
  }

  async function loadRemoteAndMerge() {
    try {
      const remote = await fetchRemoteSurveys();
      // Minimal merge: remote data is shown separately only if needed
      // For this MVP, local remains source of truth until synced.
      console.log("Remote surveys:", remote);
    } catch {}
  }

  async function handleSubmit(e) {
    e.preventDefault();
    const now = new Date().toISOString();
    const survey = {
      id: uuidv4(),
      siteName: form.siteName,
      observer: form.observer,
      latitude: Number(form.latitude),
      longitude: Number(form.longitude),
      notes: form.notes,
      createdAt: now,
      updatedAt: now,
      synced: false
    };

    await saveSurvey(survey);
    setForm({ siteName: "", observer: "", latitude: "", longitude: "", notes: "" });
    await loadLocal();
    setStatus("Saved locally. Will sync when online.");
  }

  async function doSync() {
    const unsynced = await getUnsyncedSurveys();
    if (unsynced.length === 0) {
      setStatus("Nothing to sync.");
      return;
    }

    try {
      setStatus(`Syncing ${unsynced.length} record(s)...`);
      await syncSurveys(unsynced);
      await markSynced(unsynced.map((s) => s.id));
      await loadLocal();
      setStatus("Sync complete.");
    } catch (err) {
      setStatus("Sync failed. Will retry when online.");
    }
  }

  useEffect(() => {
    loadLocal();
    loadRemoteAndMerge();

    const onOnline = () => {
      setOnline(true);
      doSync();
    };
    const onOffline = () => setOnline(false);

    window.addEventListener("online", onOnline);
    window.addEventListener("offline", onOffline);

    return () => {
      window.removeEventListener("online", onOnline);
      window.removeEventListener("offline", onOffline);
    };
  }, []);

  useEffect(() => {
    if (online) doSync();
  }, [online]);

  return (
    <div style={{ fontFamily: "sans-serif", maxWidth: 800, margin: "40px auto" }}>
      <h1>Field Survey App</h1>
      <p>
        Status: <strong>{online ? "Online" : "Offline"}</strong>
      </p>
      <p>{status}</p>

      <form onSubmit={handleSubmit} style={{ display: "grid", gap: 8, marginBottom: 24 }}>
        <input
          placeholder="Site name"
          value={form.siteName}
          onChange={(e) => setForm({ ...form, siteName: e.target.value })}
          required
        />
        <input
          placeholder="Observer"
          value={form.observer}
          onChange={(e) => setForm({ ...form, observer: e.target.value })}
          required
        />
        <input
          placeholder="Latitude"
          type="number"
          step="any"
          value={form.latitude}
          onChange={(e) => setForm({ ...form, latitude: e.target.value })}
          required
        />
        <input
          placeholder="Longitude"
          type="number"
          step="any"
          value={form.longitude}
          onChange={(e) => setForm({ ...form, longitude: e.target.value })}
          required
        />
        <textarea
          placeholder="Notes"
          value={form.notes}
          onChange={(e) => setForm({ ...form, notes: e.target.value })}
        />
        <button type="submit">Save Survey Offline</button>
      </form>

      <button onClick={doSync} disabled={!online}>
        Sync Now
      </button>

      <h2>Saved Surveys</h2>
      <ul>
        {surveys.map((s) => (
          <li key={s.id} style={{ marginBottom: 12 }}>
            <strong>{s.siteName}</strong> — {s.observer} — {s.latitude}, {s.longitude}
            <br />
            <small>{s.notes}</small>
            <br />
            <small>{s.synced ? "Synced" : "Pending sync"}</small>
          </li>
        ))}
      </ul>
    </div>
  );
}
