### `src/server.js`
```js
require("dotenv").config();
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const jwt = require("jsonwebtoken");
const bcrypt = require("bcrypt");
const { PrismaClient } = require("@prisma/client");

const prisma = new PrismaClient();
const app = express();
const server = http.createServer(app);

app.use(cors({ origin: "*" }));
app.use(express.json());

const io = new Server(server, {
  cors: { origin: "*" },
});

const JWT_SECRET = process.env.JWT_SECRET || "dev_secret";

// --- Auth middleware ---
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) return res.status(401).json({ error: "Missing token" });

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

// --- Auth routes ---
app.post("/auth/register", async (req, res) => {
  const { email, password, displayName } = req.body;

  const existing = await prisma.user.findUnique({ where: { email } });
  if (existing) return res.status(400).json({ error: "Email already used" });

  const passwordHash = await bcrypt.hash(password, 10);
  const user = await prisma.user.create({
    data: {
      email,
      passwordHash,
      displayName,
      subscription: { create: { tier: "FREE", active: true } },
    },
  });

  const token = jwt.sign({ userId: user.id, email: user.email }, JWT_SECRET, {
    expiresIn: "7d",
  });

  res.json({ token, user: { id: user.id, email: user.email, displayName } });
});

app.post("/auth/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });

  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(401).json({ error: "Invalid credentials" });

  const token = jwt.sign({ userId: user.id, email: user.email }, JWT_SECRET, {
    expiresIn: "7d",
  });

  res.json({
    token,
    user: { id: user.id, email: user.email, displayName: user.displayName },
  });
});

// --- Conversations ---
app.post("/conversations", authMiddleware, async (req, res) => {
  const { memberIds } = req.body; // array of user IDs
  const userId = req.user.userId;

  const conversation = await prisma.conversation.create({
    data: {
      members: {
        create: [
          { userId },
          ...memberIds.filter((id) => id !== userId).map((id) => ({ userId: id })),
        ],
      },
    },
    include: { members: true },
  });

  res.json(conversation);
});

app.get("/conversations", authMiddleware, async (req, res) => {
  const userId = req.user.userId;

  const conversations = await prisma.conversation.findMany({
    where: { members: { some: { userId } } },
    include: {
      members: { include: { user: true } },
      messages: { orderBy: { createdAt: "desc" }, take: 1 },
    },
    orderBy: { updatedAt: "desc" },
  });

  res.json(conversations);
});

// --- Messages ---
app.get("/conversations/:id/messages", authMiddleware, async (req, res) => {
  const { id } = req.params;
  const messages = await prisma.message.findMany({
    where: { conversationId: id },
    orderBy: { createdAt: "asc" },
  });
  res.json(messages);
});

app.post("/conversations/:id/messages", authMiddleware, async (req, res) => {
  const { id } = req.params;
  const { content } = req.body;
  const senderId = req.user.userId;

  const message = await prisma.message.create({
    data: {
      conversationId: id,
      senderId,
      content,
    },
  });

  // Create notifications for other members
  const members = await prisma.conversationMember.findMany({
    where: { conversationId: id, userId: { not: senderId } },
  });

  const notifications = await prisma.notification.createMany({
    data: members.map((m) => ({
      userId: m.userId,
      type: "NEW_MESSAGE",
      title: "New message",
      body: content.slice(0, 80),
      data: { conversationId: id, messageId: message.id },
    })),
  });

  // Emit real-time message + notification
  io.to(id).emit("message:new", message);
  members.forEach((m) => {
    io.to(`user:${m.userId}`).emit("notification:new", {
      type: "NEW_MESSAGE",
      title: "New message",
      body: content.slice(0, 80),
      data: { conversationId: id, messageId: message.id },
    });
  });

  res.json({ message, notifications });
});

// --- Notifications ---
app.get("/notifications", authMiddleware, async (req, res) => {
  const userId = req.user.userId;
  const notifications = await prisma.notification.findMany({
    where: { userId },
    orderBy: { createdAt: "desc" },
  });
  res.json(notifications);
});

app.patch("/notifications/:id/read", authMiddleware, async (req, res) => {
  const { id } = req.params;
  const notification = await prisma.notification.update({
    where: { id },
    data: { isRead: true },
  });
  res.json(notification);
});

// --- Monetization / subscription ---
app.get("/me/subscription", authMiddleware, async (req, res) => {
  const sub = await prisma.subscription.findUnique({
    where: { userId: req.user.userId },
  });
  res.json(sub);
});

// Mock premium upgrade endpoint (replace with Stripe / App Store / Play Billing)
app.post("/me/upgrade", authMiddleware, async (req, res) => {
  const { tier = "PREMIUM" } = req.body;

  const sub = await prisma.subscription.upsert({
    where: { userId: req.user.userId },
    update: { tier, active: true, provider: "mock" },
    create: { userId: req.user.userId, tier, active: true, provider: "mock" },
  });

  io.to(`user:${req.user.userId}`).emit("subscription:updated", sub);
  res.json(sub);
});

// --- Socket.IO auth + rooms ---
io.use((socket, next) => {
  const token = socket.handshake.auth?.token;
  if (!token) return next(new Error("Unauthorized"));

  try {
    socket.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    next(new Error("Unauthorized"));
  }
});

io.on("connection", (socket) => {
  const userId = socket.user.userId;
  socket.join(`user:${userId}`);

  socket.on("conversation:join", (conversationId) => {
    socket.join(conversationId);
  });

  socket.on("message:send", async ({ conversationId, content }) => {
    const message = await prisma.message.create({
      data: {
        conversationId,
        senderId: userId,
        content,
      },
    });

    io.to(conversationId).emit("message:new", message);
  });

  socket.on("disconnect", () => {});
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => console.log(`Server running on ${PORT}`));
```

