import { Router } from "express";
import { PrismaClient } from "@prisma/client";
import { requireAuth, AuthRequest } from "../middleware/requireAuth";

const router = Router();
const prisma = new PrismaClient();

router.get("/conversations", requireAuth, async (req: AuthRequest, res) => {
  const userId = req.user!.id;

  const conversations = await prisma.conversation.findMany({
    where: {
      participants: { some: { userId } }
    },
    include: {
      participants: { include: { user: true } },
      messages: { orderBy: { createdAt: "desc" }, take: 1 }
    }
  });

  res.json(conversations);
});

router.post("/conversations", requireAuth, async (req: AuthRequest, res) => {
  const userId = req.user!.id;
  const { participantIds } = req.body as { participantIds: string[] };

  const conversation = await prisma.conversation.create({
    data: {
      participants: {
        create: [...new Set([userId, ...participantIds])].map((id) => ({ userId: id }))
      }
    },
    include: { participants: true }
  });

  res.json(conversation);
});

router.get("/messages/:conversationId", requireAuth, async (req, res) => {
  const { conversationId } = req.params;

  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

export default router;
