"use client";

import { useEffect, useState } from "react";
import { socket } from "../lib/socket";
import { apiFetch } from "../lib/api";

type Notification = {
  id: string;
  title: string;
  body: string;
  read: boolean;
};

export default function NotificationBell() {
  const [notifications, setNotifications] = useState<Notification[]>([]);

  useEffect(() => {
    apiFetch("/api/notifications").then(setNotifications).catch(console.error);

    socket.connect();

    socket.on("notification", (n) => {
      setNotifications((prev) => [{ id: crypto.randomUUID(), read: false, ...n }, ...prev]);
    });

    return () => {
      socket.off("notification");
    };
  }, []);

  const unread = notifications.filter((n) => !n.read).length;

  return (
    <div style={{ position: "relative" }}>
      <button>Notifications ({unread})</button>
      <div>
        {notifications.slice(0, 5).map((n) => (
          <div key={n.id} style={{ borderBottom: "1px solid #ddd", padding: 8 }}>
            <strong>{n.title}</strong>
            <div>{n.body}</div>
          </div>
        ))}
      </div>
    </div>
  );
}
