import { useEffect, useState } from "react";
import { api } from "../api";

export default function Chat({ token, socket }) {
  const [conversations, setConversations] = useState([]);
  const [activeConversation, setActiveConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    api("/chat/conversations", "GET", null, token).then(setConversations);
  }, [token]);

  useEffect(() => {
    if (!socket) return;

    socket.on("newMessage", (message) => {
      if (message.conversationId === activeConversation?.id) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on("notification", () => {});

    return () => {
      socket.off("newMessage");
      socket.off("notification");
    };
  }, [socket, activeConversation]);

  async function openConversation(conv) {
    setActiveConversation(conv);
    const msgs = await api(`/chat/conversations/${conv.id}/messages`, "GET", null, token);
    setMessages(msgs);
    socket.emit("joinConversation", conv.id);
  }

  function send() {
    if (!content.trim() || !activeConversation) return;
    socket.emit("sendMessage", {
      conversationId: activeConversation.id,
      content
    });
    setContent("");
  }

  return (
    <div>
      <h2>Chat</h2>
      <div style={{ display: "flex", gap: 20 }}>
        <div style={{ width: 250 }}>
          <h4>Conversations</h4>
          {conversations.map((c) => (
            <button key={c.id} onClick={() => openConversation(c)} style={{ display: "block" }}>
              {c.id.slice(0, 8)}
            </button>
          ))}
        </div>

        <div style={{ flex: 1 }}>
          <h4>Messages</h4>
          <div style={{ minHeight: 200, border: "1px solid #ccc", padding: 10 }}>
            {messages.map((m) => (
              <div key={m.id}>
                <strong>{m.sender?.name || "Unknown"}:</strong> {m.content}
              </div>
            ))}
          </div>

          <input value={content} onChange={(e) => setContent(e.target.value)} />
          <button onClick={send}>Send</button>
        </div>
      </div>
    </div>
  );
}
