import { useEffect, useState } from "react";
import Login from "./components/Login";
import Chat from "./components/Chat";
import Notifications from "./components/Notifications";
import PremiumBanner from "./components/PremiumBanner";
import { createSocket } from "./socket";
import { api } from "./api";

export default function App() {
  const [auth, setAuth] = useState(() => {
    const token = localStorage.getItem("token");
    const user = JSON.parse(localStorage.getItem("user") || "null");
    return token && user ? { token, user } : null;
  });

  const [socket, setSocket] = useState(null);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!auth?.token) return;

    const s = createSocket(auth.token);
    setSocket(s);

    s.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => s.disconnect();
  }, [auth]);

  async function handleAuth(data) {
    localStorage.setItem("token", data.token);
    localStorage.setItem("user", JSON.stringify(data.user));
    setAuth(data);
  }

  async function upgrade() {
    const data = await api("/billing/upgrade-demo", "POST", {}, auth.token);
    const updatedUser = { ...auth.user, plan: data.plan };
    localStorage.setItem("user", JSON.stringify(updatedUser));
    setAuth({ ...auth, user: updatedUser });
  }

  if (!auth) return <Login onAuth={handleAuth} />;

  return (
    <div style={{ padding: 20 }}>
      <h1>Social Messaging App</h1>
      <p>Logged in as {auth.user.email}</p>

      <PremiumBanner user={auth.user} onUpgrade={upgrade} />

      <Notifications notifications={notifications} />

      {socket && <Chat token={auth.token} socket={socket} />}
    </div>
  );
}
