## 4) Real-time messaging via Socket.IO

**`server/src/socket.ts`**
```ts
import { Server } from "socket.io";
import { PrismaClient } from "@prisma/client";

export function registerSocketHandlers(io: Server, prisma: PrismaClient) {
  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("joinConversation", async ({ conversationId, userId }) => {
      // Optional: verify user is part of conversation
      socket.join(conversationId);
      console.log(`User ${userId} joined conversation ${conversationId}`);
    });

    socket.on("sendMessage", async ({ conversationId, senderId, content }) => {
      const message = await prisma.message.create({
        data: {
          conversationId,
          senderId,
          content,
        },
        include: {
          sender: true,
        },
      });

      io.to(conversationId).emit("newMessage", message);

      // Create notifications for other participants
      const participants = await prisma.conversationParticipant.findMany({
        where: { conversationId },
      });

      const recipientIds = participants
        .map((p) => p.userId)
        .filter((id) => id !== senderId);

      for (const userId of recipientIds) {
        const notification = await prisma.notification.create({
          data: {
            userId,
            type: "message",
            title: "New message",
            body: `${message.sender.displayName}: ${content.slice(0, 80)}`,
          },
        });

        io.to(userId).emit("newNotification", notification);
      }
    });

    socket.on("joinUserRoom", ({ userId }) => {
      socket.join(userId);
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected:", socket.id);
    });
  });
}
```

