## `server/src/socket.js`

```js
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

export function setupSocket(httpServer) {
  const io = new Server(httpServer, {
    cors: { origin: process.env.CLIENT_URL, credentials: true }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("No token"));

    try {
      const user = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = user;
      next();
    } catch {
      next(new Error("Invalid token"));
    }
  });

  io.on("connection", (socket) => {
    socket.join(socket.user.id);

    socket.on("joinConversation", (conversationId) => {
      socket.join(conversationId);
    });

    socket.on("sendMessage", async ({ conversationId, content }) => {
      const message = await prisma.message.create({
        data: {
          content,
          conversationId,
          senderId: socket.user.id
        },
        include: { sender: true }
      });

      const members = await prisma.conversationMember.findMany({
        where: { conversationId },
        include: { user: true }
      });

      io.to(conversationId).emit("newMessage", message);

      for (const member of members) {
        if (member.userId !== socket.user.id) {
          const notification = await prisma.notification.create({
            data: {
              userId: member.userId,
              type: "message",
              title: "New message",
              body: `${socket.user.name} sent a message`
            }
          });

          io.to(member.userId).emit("notification", notification);
        }
      }
    });

    socket.on("markNotificationsRead", async () => {
      await prisma.notification.updateMany({
        where: { userId: socket.user.id, read: false },
        data: { read: true }
      });
      io.to(socket.user.id).emit("notificationsRead");
    });
  });

  return io;
}
```

