import express from "express";
import cors from "cors";
import http from "http";
import { PrismaClient } from "@prisma/client";
import authRoutes from "./auth.js";
import stripeRoutes from "./stripe.js";
import { authMiddleware } from "./middleware.js";
import { setupSocket } from "./socket.js";

const prisma = new PrismaClient();
const app = express();
const server = http.createServer(app);

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use("/stripe/webhook", express.raw({ type: "application/json" }));
app.use(express.json());

app.use("/auth", authRoutes);
app.use("/stripe", stripeRoutes);

const io = setupSocket(server);

app.get("/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user.id },
    include: { subscriptions: true }
  });
  res.json(user);
});

app.get("/conversations", authMiddleware, async (req, res) => {
  const conversations = await prisma.conversation.findMany({
    where: {
      members: { some: { userId: req.user.id } }
    },
    include: {
      members: { include: { user: true } },
      messages: { orderBy: { createdAt: "desc" }, take: 1 }
    }
  });
  res.json(conversations);
});

app.post("/conversations", authMiddleware, async (req, res) => {
  const { memberIds } = req.body;

  const conversation = await prisma.conversation.create({
    data: {
      members: {
        create: [req.user.id, ...memberIds].map((id) => ({ userId: id }))
      }
    }
  });

  res.json(conversation);
});

app.get("/conversations/:id/messages", authMiddleware, async (req, res) => {
  const messages = await prisma.message.findMany({
    where: { conversationId: req.params.id },
    orderBy: { createdAt: "asc" },
    include: { sender: true }
  });
  res.json(messages);
});

app.get("/notifications", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.id },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

app.get("/notifications/unread-count", authMiddleware, async (req, res) => {
  const count = await prisma.notification.count({
    where: { userId: req.user.id, read: false }
  });
  res.json({ count });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => console.log(`Server running on ${PORT}`));
