```jsx
import React, { useEffect, useState } from "react";
import { api } from "../api";
import MessageList from "../components/MessageList";
import MessageInput from "../components/MessageInput";
import NotificationBell from "../components/NotificationBell";

export default function Chat({ socket, user }) {
  const [conversations, setConversations] = useState([]);
  const [activeConversation, setActiveConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);

  useEffect(() => {
    api.get("/conversations").then((res) => setConversations(res.data));
    api.get("/notifications").then((res) => setNotifications(res.data));
    api.get("/notifications/unread-count").then((res) => setUnreadCount(res.data.count));
  }, []);

  useEffect(() => {
    if (!socket) return;

    socket.on("newMessage", (message) => {
      if (message.conversationId === activeConversation?.id) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on("notification", () => {
      setUnreadCount((c) => c + 1);
    });

    socket.on("notificationsRead", () => {
      setUnreadCount(0);
    });

    return () => {
      socket.off("newMessage");
      socket.off("notification");
      socket.off("notificationsRead");
    };
  }, [socket, activeConversation]);

  async function openConversation(conv) {
    setActiveConversation(conv);
    socket.emit("joinConversation", conv.id);
    const res = await api.get(`/conversations/${conv.id}/messages`);
    setMessages(res.data);
    socket.emit("markNotificationsRead");
  }

  function sendMessage(content) {
    if (!activeConversation || !content.trim()) return;
    socket.emit("sendMessage", { conversationId: activeConversation.id, content });
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "250px 1fr", gap: 16 }}>
      <aside>
        <h3>
          Inbox <NotificationBell count={unreadCount} />
        </h3>
        {conversations.map((c) => (
          <div key={c.id}>
            <button onClick={() => openConversation(c)}>
              Conversation {c.id.slice(0, 6)}
            </button>
          </div>
        ))}
      </aside>

      <main>
        <h2>{activeConversation ? `Chat ${activeConversation.id.slice(0, 6)}` : "Select a conversation"}</h2>
        {activeConversation && (
          <>
            <MessageList messages={messages} user={user} />
            <MessageInput onSend={sendMessage} />
          </>
        )}
      </main>
    </div>
  );
}
