```ts
import { Request, Response } from "express";
import Stripe from "stripe";
import { prisma } from "../prisma";
import { AuthRequest } from "../middleware/requireAuth";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "sk_test_xxx");

export async function createCheckoutSession(req: AuthRequest, res: Response) {
  const userId = req.user!.id;
  const { mode } = req.body; // "subscription" or "credits"

  const user = await prisma.user.findUnique({
    where: { id: userId },
    include: { subscription: true }
  });

  if (!user) return res.status(404).json({ error: "User not found" });

  const session = await stripe.checkout.sessions.create({
    mode: mode === "subscription" ? "subscription" : "payment",
    payment_method_types: ["card"],
    line_items: [
      mode === "subscription"
        ? { price: process.env.STRIPE_SUBSCRIPTION_PRICE_ID!, quantity: 1 }
        : { price: process.env.STRIPE_CREDITS_PRICE_ID!, quantity: 1 }
    ],
    success_url: `${process.env.CLIENT_URL}/billing?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/billing?canceled=1`,
    metadata: { userId, mode }
  });

  res.json({ url: session.url });
}

export async function stripeWebhook(req: Request, res: Response) {
  const sig = req.headers["stripe-signature"] as string;
  const endpointSecret = process.env.STRIPE_WEBHOOK_SECRET || "";

  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      endpointSecret
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  const alreadyProcessed = await prisma.paymentEvent.findUnique({
    where: { stripeEventId: event.id }
  });

  if (alreadyProcessed) return res.json({ received: true });

  await prisma.paymentEvent.create({
    data: { stripeEventId: event.id, type: event.type }
  });

  if (event.type === "checkout.session.completed") {
    const session = event.data.object as Stripe.Checkout.Session;
    const userId = session.metadata?.userId;
    const mode = session.metadata?.mode;

    if (userId && mode === "credits") {
      await prisma.wallet.upsert({
        where: { userId },
        update: { balance: { increment: 500 } },
        create: { userId, balance: 500 }
      });

      await prisma.notification.create({
        data: {
          userId,
          type: "payment",
          title: "Credits added",
          body: "Your wallet has been topped up with 500 credits."
        }
      });
    }
  }

  return res.json({ received: true });
}
