import { useEffect, useState } from "react";
import { createSocket } from "./socket";
import { api } from "./api";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [socket, setSocket] = useState<any>(null);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [messages, setMessages] = useState<any[]>([]);
  const [conversationId, setConversationId] = useState("");

  useEffect(() => {
    if (!token) return;

    const s = createSocket(token);
    setSocket(s);

    s.on("notification:new", (n: any) => {
      setNotifications((prev) => [n, ...prev]);
    });

    s.on("message:new", (msg: any) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => s.disconnect();
  }, [token]);

  async function loginDemo() {
    const data = await api("/auth/login", {
      method: "POST",
      body: JSON.stringify({ email: "demo@example.com", password: "password" })
    });
    localStorage.setItem("token", data.token);
    setToken(data.token);
  }

  async function sendMessage() {
    if (!socket || !conversationId) return;
    socket.emit("message:send", { conversationId, content: "Hello world!" });
  }

  async function buyCredits() {
    const data = await api(
      "/payments/checkout",
      {
        method: "POST",
        body: JSON.stringify({ mode: "credits" })
      },
      token
    );
