# 6) Example premium feature route

```ts
import { Router } from "express";
import { requireAuth, AuthRequest } from "../middleware/requireAuth";
import { Response } from "express";
import { prisma } from "../prisma";

const router = Router();

router.post("/premium-action", requireAuth, async (req: AuthRequest, res: Response) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user!.id },
    include: { subscription: true, wallet: true }
  });

  if (user?.subscription?.status !== "ACTIVE" && (user?.wallet?.balance || 0) <= 0) {
    return res.status(402).json({ error: "Payment required" });
  }

  if (user?.wallet && user.wallet.balance > 0) {
    await prisma.wallet.update({
      where: { userId: user.id },
      data: { balance: { decrement: 1 } }
    });
  }

  res.json({ ok: true, message: "Premium action completed" });
});

export default router;
```

