## `server/src/socket.js`

```js
import jwt from "jsonwebtoken";

export function setupSocket(io, prisma) {
  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = payload;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    socket.join(socket.user.id);

    socket.on("send_message", async ({ receiverId, content }) => {
      const senderId = socket.user.id;

      const sender = await prisma.user.findUnique({ where: { id: senderId } });
      if (!sender.isPremium && content.length > 200) {
        socket.emit("error_message", { error: "Upgrade to premium for long messages." });
        return;
      }

      const message = await prisma.message.create({
        data: { senderId, receiverId, content }
      });

      const notification = await prisma.notification.create({
        data: {
          userId: receiverId,
          type: "message",
          text: `New message from ${socket.user.username}`
        }
      });

      io.to(receiverId).emit("new_message", message);
      io.to(receiverId).emit("new_notification", notification);
    });

    socket.on("mark_read", async ({ messageId }) => {
      const message = await prisma.message.update({
        where: { id: messageId },
        data: { read: true }
      });

      io.to(message.senderId).emit("message_read", { messageId });
    });
  });
}
```

