## `client/src/pages/Chat.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { api } from "../api";
import { createSocket } from "../socket";
import MessageList from "../components/MessageList";
import MessageInput from "../components/MessageInput";
import NotificationBell from "../components/NotificationBell";

export default function Chat({ token, user }) {
  const [socket, setSocket] = useState(null);
  const [receiverId, setReceiverId] = useState("");
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const s = createSocket(token);
    setSocket(s);

    s.on("new_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    s.on("new_notification", (notif) => {
      setNotifications((prev) => [notif, ...prev]);
    });

    s.on("message_read", ({ messageId }) => {
      setMessages((prev) => prev.map(m => m.id === messageId ? { ...m, read: true } : m));
    });

    return () => s.disconnect();
  }, [token]);

  const loadMessages = async () => {
    if (!receiverId) return;
    const data = await api(`/api/messages/${receiverId}`, token);
    setMessages(data);
  };

  const sendMessage = (content) => {
    socket?.emit("send_message", { receiverId, content });
  };

  return (
    <div>
      <h2>Welcome, {user.username} {user.isPremium ? "(Premium)" : ""}</h2>

      <NotificationBell notifications={notifications} />

      <input
        placeholder="Receiver user ID"
        value={receiverId}
        onChange={e => setReceiverId(e.target.value)}
      />
      <button onClick={loadMessages}>Load Conversation</button>

      <MessageList messages={messages} onRead={(messageId) => socket?.emit("mark_read", { messageId })} />
      <MessageInput onSend={sendMessage} />
    </div>
  );
}
