## 8) Billing / monetization service

This example uses **Stripe subscriptions** and a simple **credits wallet**.

**`server/src/services/billingService.ts`**
```ts
import Stripe from "stripe";
import { prisma } from "../prisma.js";

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || "", {
  apiVersion: "2024-06-20"
});

export async function createCheckoutSession(userId: string, priceId: string) {
  const user = await prisma.user.findUnique({ where: { id: userId } });
  if (!user) throw new Error("User not found");

  let subscription = await prisma.subscription.findFirst({ where: { userId } });

  if (!subscription) {
    subscription = await prisma.subscription.create({
      data: {
        userId,
        status: "incomplete",
        plan: "starter"
      }
    });
  }

  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    payment_method_types: ["card"],
    line_items: [{ price: priceId, quantity: 1 }],
    success_url: `${process.env.CLIENT_ORIGIN}/billing/success`,
    cancel_url: `${process.env.CLIENT_ORIGIN}/billing/cancel`,
    customer_email: user.email,
    metadata: { userId }
  });

  return session;
}

export async function addCredits(userId: string, credits: number) {
  return prisma.wallet.upsert({
    where: { userId },
    create: { userId, balance: credits },
    update: { balance: { increment: credits } }
  });
}

export async function spendCredits(userId: string, credits: number) {
  const wallet = await prisma.wallet.findUnique({ where: { userId } });
  if (!wallet || wallet.balance < credits) {
    throw new Error("Insufficient credits");
  }

  return prisma.wallet.update({
    where: { userId },
    data: { balance: { decrement: credits } }
  });
}
```

