## 9) Routes

### Messages route

**`server/src/routes/messages.ts`**
```ts
import { Router } from "express";
import { requireAuth, AuthRequest } from "../auth.js";
import { sendMessage, getConversation } from "../services/messageService.js";
import { createNotification } from "../services/notificationService.js";

export function messagesRouter(io: any) {
  const router = Router();

  router.get("/conversation/:otherUserId", requireAuth, async (req: AuthRequest, res) => {
    const userId = req.user!.id;
    const otherUserId = req.params.otherUserId;
    const messages = await getConversation(userId, otherUserId);
    res.json(messages);
  });

  router.post("/", requireAuth, async (req: AuthRequest, res) => {
    const senderId = req.user!.id;
    const { receiverId, content } = req.body;

    if (!receiverId || !content) {
      return res.status(400).json({ error: "receiverId and content required" });
    }

    const message = await sendMessage(senderId, receiverId, content);

    const notification = await createNotification(
      receiverId,
      "message",
      "New message",
      `You received a message from ${senderId}`
    );

    io.to(`user:${receiverId}`).emit("message:new", message);
    io.to(`user:${receiverId}`).emit("notification:new", notification);

    res.json(message);
  });

  return router;
}
```

