```tsx
import React, { useEffect, useState } from "react";
import { apiFetch } from "../api";
import { createSocket } from "../socket";

export function Chat({ token, me, otherUserId }: { token: string; me: string; otherUserId: string }) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");
  const [socket, setSocket] = useState<any>(null);

  useEffect(() => {
    apiFetch(`/messages/conversation/${otherUserId}`, token).then(setMessages);

    const s = createSocket(token);
    setSocket(s);

    s.on("message:new", (msg: any) => {
      if (
        (msg.senderId === me && msg.receiverId === otherUserId) ||
        (msg.senderId === otherUserId && msg.receiverId === me)
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => s.disconnect();
  }, [token, otherUserId, me]);

  async function send() {
    const msg = await apiFetch("/messages", token, {
      method: "POST",
      body: JSON.stringify({ receiverId: otherUserId, content })
    });
    setMessages((prev) => [...prev, msg]);
    setContent("");
  }

  return (
    <div>
      <div style={{ border: "1px solid #ccc", height: 300, overflow: "auto" }}>
        {messages.map((m) => (
          <div key={m.id}>
            <b>{m.senderId === me ? "Me" : "Them"}:</b> {m.content}
          </div>
        ))}
      </div>

      <input value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={send}>Send</button>
    </div>
  );
}
```

