import express from "express";
import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, { apiVersion: "2024-06-20" });

export const stripeRouter = express.Router();

stripeRouter.post("/create-checkout-session", async (req, res) => {
  const { userId, amount } = req.body; // amount in cents

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "Wallet top-up" },
          unit_amount: amount
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/billing?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/billing?canceled=1`,
    metadata: { userId, amount: String(amount) }
  });

  res.json({ url: session.url });
});

stripeRouter.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  const sig = req.headers["stripe-signature"] as string;
  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET!
    );
  } catch (err: any) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object as Stripe.Checkout.Session;
    const userId = session.metadata?.userId;
    const amount = Number(session.metadata?.amount || 0);

    if (userId && amount > 0) {
      await prisma.wallet.upsert({
        where: { userId },
        update: { balance: { increment: amount } },
        create: { userId, balance: amount }
      });
    }
  }

  res.json({ received: true });
});
