import express from "express";
import cors from "cors";
import http from "http";
import dotenv from "dotenv";
import { Server } from "socket.io";
import { PrismaClient } from "@prisma/client";
import { authRouter } from "./auth";
import { authMiddleware, AuthRequest } from "./middleware";
import { setupSocket } from "./socket";
import { stripeRouter } from "./stripe";

dotenv.config();

const prisma = new PrismaClient();
const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    credentials: true
  }
});

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use("/api/stripe/webhook", express.raw({ type: "application/json" }));
app.use(express.json());

setupSocket(io);

app.use("/api/auth", authRouter);
app.use("/api/stripe", stripeRouter);

app.get("/api/me", authMiddleware, async (req: AuthRequest, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user!.id },
    include: { wallet: true }
  });
  res.json(user);
});

app.get("/api/messages/:roomId", authMiddleware, async (req: AuthRequest, res) => {
  const { roomId } = req.params;
  const messages = await prisma.message.findMany({
    where: { roomId },
    orderBy: { createdAt: "asc" }
  });
  res.json(messages);
});

app.get("/api/notifications", authMiddleware, async (req: AuthRequest, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user!.id },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

app.post("/api/notifications/:id/read", authMiddleware, async (req: AuthRequest, res) => {
  const { id } = req.params;
  await prisma.notification.update({
    where: { id },
    data: { read: true }
  });
  res.json({ ok: true });
});

app.post("/api/send-tip", authMiddleware, async (req: AuthRequest, res) => {
  const { recipientId, amount } = req.body; // cents
  const senderId = req.user!.id;

  const senderWallet = await prisma.wallet.findUnique({ where: { userId: senderId } });
  if (!senderWallet || senderWallet.balance < amount) {
    return res.status(400).json({ error: "Insufficient balance" });
  }

  await prisma.$transaction([
    prisma.wallet.update({
      where: { userId: senderId },
      data: { balance: { decrement: amount } }
    }),
    prisma.wallet.upsert({
      where: { userId: recipientId },
      update: { balance: { increment: amount } },
      create: { userId: recipientId, balance: amount }
    }),
    prisma.notification.create({
      data: {
        userId: recipientId,
        type: "tip",
        title: "You received a tip!",
        body: `You received a tip of $${(amount / 100).toFixed(2)}`
      }
    })
  ]);

  io.to(`user:${recipientId}`).emit("notification", {
    type: "tip",
    title: "You received a tip!",
    body: `You received a tip of $${(amount / 100).toFixed(2)}`
  });

  res.json({ ok: true });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

