```tsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";

type User = { id: string; email: string; username: string };

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  const [tokenReady, setTokenReady] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return setTokenReady(true);

    api.get("/me")
      .then((res) => setUser(res.data))
      .finally(() => setTokenReady(true));
  }, []);

  if (!tokenReady) return <div>Loading...</div>;

  if (!user) {
    return <AuthScreen onLogin={setUser} />;
  }

  return <ChatScreen user={user} onLogout={() => { localStorage.removeItem("token"); setUser(null); }} />;
}

function AuthScreen({ onLogin }: { onLogin: (u: User) => void }) {
  const [mode, setMode] = useState<"login" | "register">("login");
  const [email, setEmail] = useState("");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");

  const submit = async () => {
    const url = mode === "login" ? "/auth/login" : "/auth/register";
    const payload = mode === "login" ? { email, password } : { email, username, password };
    const res = await api.post(url, payload);
    localStorage.setItem("token", res.data.token);
    onLogin(res.data.user);
  };

  return (
    <div>
      <h1>{mode === "login" ? "Login" : "Register"}</h1>
      <input placeholder="email" value={email} onChange={(e) => setEmail(e.target.value)} />
      {mode === "register" && (
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
      )}
      <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
      <button onClick={submit}>{mode}</button>
      <button onClick={() => setMode(mode === "login" ? "register" : "login")}>
        Switch to {mode === "login" ? "register" : "login"}
      </button>
    </div>
  );
}

function ChatScreen({ user, onLogout }: { user: User; onLogout: () => void }) {
  const [roomId, setRoomId] = useState("general");
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState<any[]>([]);
  const [recipientId, setRecipientId] = useState("");

  useEffect(() => {
    const socket = createSocket(user.id);
    socket.emit("joinRoom", roomId);

    socket.on("newMessage", (msg) => setMessages((prev) => [...prev, msg]));
    socket.on("notification", (n) => setNotifications((prev) => [n, ...prev]));

    api.get(`/messages/${roomId}`).then((res) => setMessages(res.data));
    api.get("/notifications").then((res) => setNotifications(res.data));

    return () => socket.disconnect();
  }, [roomId, user.id]);

  const send = async () => {
    const socket = createSocket(user.id);
    socket.emit("sendMessage", {
      roomId,
      content,
      senderId: user.id,
      recipientId: recipientId || undefined
    });
    setContent("");
    socket.disconnect();
  };

  const tip = async () => {
    await api.post("/send-tip", { recipientId, amount: 100 }); // $1.00
    alert("Tip sent");
  };

  return (
    <div style={{ display: "flex", gap: 24 }}>
      <div style={{ width: 300 }}>
        <h2>Welcome, {user.username}</h2>
        <button onClick={onLogout}>Logout</button>

        <h3>Notifications</h3>
        {notifications.map((n) => (
          <div key={n.id || `${n.title}-${n.body}`}>{n.title}: {n.body}</div>
        ))}

        <h3>Monetization</h3>
        <a href="http://localhost:4000/api/stripe/create-checkout-session" onClick={async (e) => {
          e.preventDefault();
          const res = await api.post("/stripe/create-checkout-session", { userId: user.id, amount: 500 });
          window.location.href = res.data.url;
        }}>
          Add $5 to wallet
        </a>

        <div style={{ marginTop: 12 }}>
          <input placeholder="Recipient userId" value={recipientId} onChange={(e) => setRecipientId(e.target.value)} />
          <button onClick={tip}>Send $1 Tip</button>
        </div>
      </div>

      <div style={{ flex: 1 }}>
        <h2>Room: {roomId}</h2>
        <input value={roomId} onChange={(e) => setRoomId(e.target.value)} placeholder="room id" />
        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 12 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.senderId}</b>: {m.content}
            </div>
          ))}
        </div>
        <input value={content} onChange={(e) => setContent(e.target.value)} placeholder="message" />
        <button onClick={send}>Send</button>
      </div>
    </div>
  );
}
