import React, { useEffect, useState } from "react";
import { api } from "../api";

export default function Chat({ user, socket }) {
  const [conversations, setConversations] = useState([]);
  const [activeConversation, setActiveConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    api.get("/conversations").then(({ data }) => setConversations(data));
  }, []);

  useEffect(() => {
    if (!socket || !activeConversation) return;

    socket.emit("joinConversation", activeConversation.id);

    api.get(`/messages/${activeConversation.id}`).then(({ data }) => setMessages(data));

    const onNewMessage = (msg) => {
      if (msg.conversationId === activeConversation.id) {
        setMessages((prev) => [...prev, msg]);
      }
    };

    socket.on("newMessage", onNewMessage);
    return () => socket.off("newMessage", onNewMessage);
  }, [socket, activeConversation]);

  const send = () => {
    if (!content.trim() || !activeConversation) return;
    socket.emit("sendMessage", {
      conversationId: activeConversation.id,
      content
    });
    setContent("");
  };

  return (
    <div style={{ display: "grid", gridTemplateColumns: "250px 1fr", gap: 12 }}>
      <div>
        <h3>Conversations</h3>
        {conversations.map((c) => (
          <div key={c.id}>
            <button onClick={() => setActiveConversation(c)}>
              {c.id.slice(0, 8)}
            </button>
          </div>
        ))}
      </div>

      <div>
        <h3>Chat</h3>
        <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 8 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <strong>{m.sender.username}:</strong> {m.content}
            </div>
          ))}
        </div>

        <input
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="Type a message..."
        />
        <button onClick={send}>Send</button>
      </div>
    </div>
  );
}
