# 5) Chat controller

## `server/src/controllers/chat.controller.js`

```js
import { pool } from "../db.js";

export async function getConversations(req, res) {
  const userId = req.user.id;

  const result = await pool.query(
    `
    SELECT c.id, c.created_at
    FROM conversations c
    JOIN conversation_members cm ON cm.conversation_id = c.id
    WHERE cm.user_id = $1
    ORDER BY c.created_at DESC
    `,
    [userId]
  );

  res.json(result.rows);
}

export async function getMessages(req, res) {
  const { conversationId } = req.params;

  const result = await pool.query(
    `
    SELECT m.id, m.content, m.sender_id, m.created_at, u.username
    FROM messages m
    JOIN users u ON u.id = m.sender_id
    WHERE m.conversation_id = $1
    ORDER BY m.created_at ASC
    `,
    [conversationId]
  );

  res.json(result.rows);
}

export async function sendMessage(req, res) {
  const userId = req.user.id;
  const { conversationId, content } = req.body;

  if (!conversationId || !content) {
    return res.status(400).json({ error: "Missing conversationId or content" });
  }

  const result = await pool.query(
    `
    INSERT INTO messages (conversation_id, sender_id, content)
    VALUES ($1, $2, $3)
    RETURNING id, conversation_id, sender_id, content, created_at
    `,
    [conversationId, userId, content]
  );

  const message = result.rows[0];

  // Create notification for other members
  const members = await pool.query(
    `SELECT user_id FROM conversation_members WHERE conversation_id = $1 AND user_id != $2`,
    [conversationId, userId]
  );

  for (const member of members.rows) {
    await pool.query(
      `INSERT INTO notifications (user_id, type, content) VALUES ($1, $2, $3)`,
      [member.user_id, "message", `New message in conversation ${conversationId}`]
    );
  }

  res.json(message);
}
```

