        price_data: {
          currency: "usd",
          product_data: {
            name: "Premium Membership"
          },
          recurring: {
            interval: "month"
          },
          unit_amount: 999
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/billing?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/billing?canceled=1`,
    metadata: {
      userId: String(userId)
    }
  });

  res.json({ url: session.url });
}

export async function stripeWebhook(req, res) {
  const sig = req.headers["stripe-signature"];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;

    await pool.query(
      `
      UPDATE users SET is_premium = TRUE WHERE id = $1
      `,
      [userId]
    );

    await pool.query(
      `
      INSERT INTO subscriptions (user_id, stripe_customer_id, stripe_subscription_id, status)
      VALUES ($1, $2, $3, $4)
      `,
      [userId, session.customer, session.subscription, "active"]
    );
  }

  res.json({ received: true });
}
