# 9) Socket.IO real-time notifications + messages

## `server/src/socket.js`

```js
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import { pool } from "./db.js";

export function setupSocket(server) {
  const io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_URL,
      methods: ["GET", "POST"]
    }
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const user = jwt.verify(token, process.env.JWT_SECRET);
      socket.user = user;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.user.id;

    socket.join(`user:${userId}`);

    socket.on("joinConversation", (conversationId) => {
      socket.join(`conversation:${conversationId}`);
    });

    socket.on("sendMessage", async ({ conversationId, content }) => {
      const result = await pool.query(
        `
        INSERT INTO messages (conversation_id, sender_id, content)
        VALUES ($1, $2, $3)
        RETURNING id, conversation_id, sender_id, content, created_at
        `,
        [conversationId, userId, content]
      );

      const message = result.rows[0];

      io.to(`conversation:${conversationId}`).emit("newMessage", message);

      const members = await pool.query(
        `SELECT user_id FROM conversation_members WHERE conversation_id = $1 AND user_id != $2`,
        [conversationId, userId]
      );

      for (const member of members.rows) {
        const notif = await pool.query(
          `INSERT INTO notifications (user_id, type, content)
           VALUES ($1, $2, $3)
           RETURNING id, user_id, type, content, is_read, created_at`,
          [member.user_id, "message", `New message in conversation ${conversationId}`]
        );

        io.to(`user:${member.user_id}`).emit("notification", notif.rows[0]);
      }
    });
  });

  return io;
}
```

