import { protect } from "../middleware/auth.js";

export default function paymentsRoute(io) {
  const router = express.Router();

  router.post("/create-checkout-session", protect, async (req, res) => {
    try {
      const { amount } = req.body; // dollars
      const session = await stripe.checkout.sessions.create({
        mode: "payment",
        payment_method_types: ["card"],
        line_items: [
          {
            price_data: {
              currency: "usd",
              product_data: { name: "Wallet Top-Up" },
              unit_amount: Math.round(amount * 100)
            },
            quantity: 1
          }
        ],
        success_url: `${process.env.CLIENT_URL}/wallet?success=1`,
        cancel_url: `${process.env.CLIENT_URL}/wallet?canceled=1`,
        metadata: {
          userId: req.user._id.toString(),
          amount: String(amount)
        }
      });

      await Purchase.create({
        user: req.user._id,
        stripeSessionId: session.id,
        amount,
        currency: "usd",
        status: "pending"
      });

      res.json({ url: session.url });
    } catch (error) {
      res.status(500).json({ message: error.message });
    }
  });

  router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
    const sig = req.headers["stripe-signature"];

    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const { userId, amount } = session.metadata;

      await Purchase.findOneAndUpdate(
        { stripeSessionId: session.id },
        { status: "paid" }
      );

      const user = await User.findById(userId);
      if (user) {
        user.balance += Number(amount);
        await user.save();

        const notification = await Notification.create({
          user: user._id,
          type: "payment",
          title: "Wallet funded",
          body: `Your wallet was credited with $${amount}`
        });

        io.to(user._id.toString()).emit("walletUpdated", { balance: user.balance });
        io.to(user._id.toString()).emit("newNotification", notification);
      }
    }

    res.json({ received: true });
  });

  return router;
}
```

