```jsx
import { useEffect, useState } from "react";
import api from "../api/axios";

export default function ChatWindow({ socket, currentUser, recipientId }) {
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    const load = async () => {
      const { data } = await api.get(`/messages/${recipientId}`);
      setMessages(data);
    };
    if (recipientId) load();
  }, [recipientId]);

  useEffect(() => {
    if (!socket) return;

    socket.on("newMessage", (message) => {
      if (
        (message.sender === currentUser.id && message.recipient === recipientId) ||
        (message.sender === recipientId && message.recipient === currentUser.id)
      ) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => socket.off("newMessage");
  }, [socket, currentUser, recipientId]);

  const sendMessage = async () => {
    if (!content.trim()) return;
    await api.post("/messages", { recipientId, content });
    setContent("");
  };

  return (
    <div>
      <div style={{ border: "1px solid #ccc", minHeight: 300, padding: 10 }}>
        {messages.map((m) => (
          <div key={m._id}>
            <b>{m.sender === currentUser.id ? "You" : "Them"}:</b> {m.content}
          </div>
        ))}
      </div>

      <input value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
