## `server/src/routes/chat.js`

```js
import express from "express";
import Message from "../models/Message.js";
import Notification from "../models/Notification.js";
import User from "../models/User.js";
import { auth } from "../middleware/auth.js";

export default function chatRoutes(io) {
  const router = express.Router();

  router.get("/messages/:userId", auth, async (req, res) => {
    const otherUserId = req.params.userId;
    const myId = req.user._id;

    const messages = await Message.find({
      $or: [
        { sender: myId, recipient: otherUserId },
        { sender: otherUserId, recipient: myId }
      ]
    }).sort({ createdAt: 1 });

    res.json(messages);
  });

  router.post("/messages", auth, async (req, res) => {
    const { recipientId, content } = req.body;
    const senderId = req.user._id;

    const message = await Message.create({
      sender: senderId,
      recipient: recipientId,
      content
    });

    const recipient = await User.findById(recipientId);
    const notification = await Notification.create({
      user: recipientId,
      type: "message",
      title: "New message",
      body: `You received a message from ${req.user.username}`,
      meta: { messageId: message._id, senderId }
    });

    io.to(recipientId.toString()).emit("newMessage", message);
    io.to(recipientId.toString()).emit("newNotification", notification);

    res.json(message);
  });

  return router;
}
```

