```js
import express from "express";
import { stripe } from "../config/stripe.js";
import { auth } from "../middleware/auth.js";
import Purchase from "../models/Purchase.js";
import User from "../models/User.js";
import Notification from "../models/Notification.js";

export default function monetizationRoutes(io) {
  const router = express.Router();

  router.post("/create-checkout-session", auth, async (req, res) => {
    try {
      const { amount } = req.body; // in cents
      const session = await stripe.checkout.sessions.create({
        payment_method_types: ["card"],
        mode: "payment",
        line_items: [
          {
            price_data: {
              currency: "usd",
              product_data: { name: "Wallet Top-Up" },
              unit_amount: amount
            },
            quantity: 1
          }
        ],
        success_url: `${process.env.CLIENT_URL}/?success=1`,
        cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
        metadata: {
          userId: req.user._id.toString(),
          amount: amount.toString()
        }
      });

      await Purchase.create({
        user: req.user._id,
        stripeSessionId: session.id,
        amount,
        currency: "usd",
        status: "pending"
      });

      res.json({ url: session.url });
    } catch (err) {
      res.status(500).json({ message: err.message });
    }
  });

  router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
    let event;
    try {
      const sig = req.headers["stripe-signature"];
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;
      const amount = Number(session.metadata.amount);

      await Purchase.findOneAndUpdate(
        { stripeSessionId: session.id },
        { status: "paid" }
      );

      const user = await User.findByIdAndUpdate(
        userId,
        { $inc: { walletBalance: amount / 100 } },
        { new: true }
      );

      const notification = await Notification.create({
        user: userId,
        type: "purchase",
        title: "Wallet topped up",
        body: `Your wallet was credited with $${(amount / 100).toFixed(2)}.`,
        meta: { amount }
      });

      io.to(userId).emit("walletUpdated", { walletBalance: user.walletBalance });
      io.to(userId).emit("newNotification", notification);
    }

    res.json({ received: true });
  });

  return router;
}
