import { useEffect, useState } from "react";
import { api } from "../api/client";
import { useSocket } from "../context/SocketContext";
import { useAuth } from "../context/AuthContext";

export default function ChatWindow() {
  const { user } = useAuth();
  const { socket } = useSocket();
  const [recipientId, setRecipientId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    if (!socket) return;

    const onMessage = (msg) => {
      if (
        msg.sender === user.id || msg.recipient === user.id ||
        msg.sender === recipientId || msg.recipient === recipientId
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    };

    socket.on("newMessage", onMessage);
    return () => socket.off("newMessage", onMessage);
  }, [socket, user, recipientId]);

  const loadMessages = async () => {
    const { data } = await api.get(`/chat/messages/${recipientId}`);
    setMessages(data);
  };

  const send = async () => {
    await api.post("/chat/messages", { recipientId, content });
    setContent("");
    await loadMessages();
  };

  return (
    <div>
      <h3>Chat</h3>
      <input
        placeholder="Recipient User ID"
        value={recipientId}
        onChange={(e) => setRecipientId(e.target.value)}
      />
      <button onClick={loadMessages}>Load chat</button>

      <div style={{ border: "1px solid #ccc", minHeight: 200, margin: "1rem 0" }}>
        {messages.map((m) => (
          <div key={m._id}>
            <b>{m.sender === user.id ? "Me" : "Them"}:</b> {m.content}
          </div>
        ))}
      </div>

      <input
        placeholder="Message..."
        value={content}
        onChange={(e) => setContent(e.target.value)}
      />
      <button onClick={send}>Send</button>
    </div>
  );
}
