"use client";

import { useEffect, useState } from "react";
import { socket } from "@/lib/socket";
import { apiFetch } from "@/lib/api";

export default function ChatBox({ roomId, userId }: { roomId: string; userId: string }) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    socket.emit("joinRoom", roomId);

    apiFetch(`/api/chat/rooms/${roomId}/messages`).then(setMessages);

    socket.on("newMessage", (message) => {
      setMessages((prev) => [...prev, message]);
    });

    return () => {
      socket.off("newMessage");
    };
  }, [roomId]);

  const send = () => {
    if (!content.trim()) return;
    socket.emit("sendMessage", { roomId, userId, content });
    setContent("");
  };

  return (
    <div className="p-4 border rounded-lg">
      <div className="h-80 overflow-y-auto space-y-2 mb-4">
        {messages.map((m) => (
          <div key={m.id} className="p-2 bg-gray-100 rounded">
            <div className="text-sm text-gray-500">{m.user?.name || "You"}</div>
            <div>{m.content}</div>
          </div>
        ))}
