## `server/src/stripe.js`

```js
import express from "express";
import Stripe from "stripe";

export function stripeRoutes(prisma, io) {
  const router = express.Router();
  const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

  // Create checkout session for credits
  router.post("/create-checkout-session", async (req, res) => {
    const { userId, credits } = req.body;

    if (!userId || !credits || credits <= 0) {
      return res.status(400).json({ error: "Invalid request" });
    }

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: { name: `${credits} App Credits` },
            unit_amount: credits * 100
          },
          quantity: 1
        }
      ],
      metadata: { userId, credits: String(credits) },
      success_url: `${process.env.CLIENT_URL}/wallet?success=1`,
      cancel_url: `${process.env.CLIENT_URL}/wallet?canceled=1`
    });

    res.json({ url: session.url });
  });

  // Stripe webhook
  router.post(
    "/webhook",
    express.raw({ type: "application/json" }),
    async (req, res) => {
      const sig = req.headers["stripe-signature"];
      let event;

      try {
        event = stripe.webhooks.constructEvent(
          req.body,
          sig,
          process.env.STRIPE_WEBHOOK_SECRET
        );
      } catch (err) {
        return res.status(400).send(`Webhook Error: ${err.message}`);
      }

      if (event.type === "checkout.session.completed") {
        const session = event.data.object;
        const userId = session.metadata.userId;
        const credits = parseInt(session.metadata.credits, 10);

        await prisma.wallet.upsert({
          where: { userId },
          update: { balance: { increment: credits } },
          create: { userId, balance: credits }
        });

        await prisma.notification.create({
          data: {
            userId,
            type: "payment",
            title: "Payment successful",
            body: `Your wallet was credited with ${credits} credits.`
          }
        });

        io.to(userId).emit("notification", {
          type: "payment",
          title: "Payment successful",
          body: `Your wallet was credited with ${credits} credits.`
        });
      }

      res.json({ received: true });
    }
  );

  return router;
}
```

