import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import { Server } from "socket.io";
import { PrismaClient } from "@prisma/client";
import { authRoutes } from "./auth.js";
import { authMiddleware } from "./middleware.js";
import { setupSocket } from "./socket.js";
import { stripeRoutes } from "./stripe.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

const prisma = new PrismaClient();

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use("/stripe/webhook", express.raw({ type: "application/json" }));
app.use(express.json());

app.use("/auth", authRoutes(prisma));
app.use("/stripe", stripeRoutes(prisma, io));

setupSocket(io, prisma);

app.get("/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user.id },
    select: { id: true, email: true, username: true, createdAt: true }
  });
  res.json({ user });
});

app.get("/messages/:otherUserId", authMiddleware, async (req, res) => {
  const userId = req.user.id;
  const otherUserId = req.params.otherUserId;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: userId, receiverId: otherUserId },
        { senderId: otherUserId, receiverId: userId }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json({ messages });
});

app.get("/notifications", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.id },
    orderBy: { createdAt: "desc" }
  });
  res.json({ notifications });
});

app.get("/wallet", authMiddleware, async (req, res) => {
  const wallet = await prisma.wallet.findUnique({
    where: { userId: req.user.id }
  });
  res.json({ wallet });
});

app.post("/wallet/spend", authMiddleware, async (req, res) => {
  const { amount } = req.body;
  const wallet = await prisma.wallet.findUnique({ where: { userId: req.user.id } });

  if (!wallet || wallet.balance < amount) {
    return res.status(400).json({ error: "Insufficient balance" });
  }

  const updated = await prisma.wallet.update({
    where: { userId: req.user.id },
    data: { balance: { decrement: amount } }
  });

  res.json({ wallet: updated });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => console.log(`Server running on ${PORT}`));
```

