import React, { useEffect, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Chat from "./pages/Chat";
import Notifications from "./pages/Notifications";
import Wallet from "./pages/Wallet";

export default function App() {
  const [user, setUser] = useState(null);
  const [view, setView] = useState("login");
  const [socket, setSocket] = useState(null);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    api.get("/me")
      .then(({ data }) => {
        setUser(data.user);
        const s = createSocket(data.user.id);
        setSocket(s);

        s.on("notification", (n) => {
          setNotifications((prev) => [n, ...prev]);
        });
      })
      .catch(() => localStorage.removeItem("token"));
  }, []);

  if (!user) {
    return (
      <div>
        <button onClick={() => setView("login")}>Login</button>
        <button onClick={() => setView("register")}>Register</button>
        {view === "login" ? (
          <Login onAuth={setUser} />
        ) : (
          <Register onAuth={setUser} />
        )}
      </div>
    );
  }

  return (
    <div>
      <h1>Social Messaging App</h1>
      <p>Logged in as {user.username}</p>

      <button onClick={() => setView("chat")}>Chat</button>
      <button onClick={() => setView("notifications")}>Notifications</button>
      <button onClick={() => setView("wallet")}>Wallet</button>
      <button
        onClick={() => {
          localStorage.removeItem("token");
          window.location.reload();
        }}
      >
