import React, { useEffect, useState } from "react";
import { api } from "../api";

export default function Chat({ user, socket }) {
  const [otherUserId, setOtherUserId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    if (!socket) return;

    socket.on("new_message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    return () => socket.off("new_message");
  }, [socket]);

  const loadMessages = async () => {
    const { data } = await api.get(`/messages/${otherUserId}`);
    setMessages(data.messages);
  };

  const send = () => {
    socket.emit("send_message", { receiverId: otherUserId, content });
    setContent("");
  };

  return (
    <div>
      <h2>Chat</h2>
      <input
        placeholder="Other user ID"
        value={otherUserId}
        onChange={(e) => setOtherUserId(e.target.value)}
      />
      <button onClick={loadMessages}>Load</button>

      <div style={{ border: "1px solid #ccc", padding: 10, marginTop: 10 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <b>{m.senderId === user.id ? "You" : m.senderId}</b>: {m.content}
          </div>
        ))}
      </div>

      <input
        placeholder="Message..."
        value={content}
        onChange={(e) => setContent(e.target.value)}
      />
      <button onClick={send}>Send</button>
    </div>
  );
}
