import express from "express";
import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";
import { authMiddleware } from "./middleware.js";

const router = express.Router();
const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/checkout", authMiddleware, async (req, res) => {
  const { plan } = req.body; // e.g. "pro"
  const userId = req.user.id;

  const session = await stripe.checkout.sessions.create({
    mode: "subscription",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${plan.toUpperCase()} Plan` },
          recurring: { interval: "month" },
          unit_amount: plan === "pro" ? 999 : 1999
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    metadata: { userId, plan }
  });

  res.json({ url: session.url });
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  // In production, verify Stripe signature here.
  const event = JSON.parse(req.body.toString());

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const { userId, plan } = session.metadata;

    await prisma.subscription.upsert({
      where: { userId },
      update: { plan, status: "active", stripeCustomerId: session.customer || null },
      create: {
        userId,
        plan,
        status: "active",
        stripeCustomerId: session.customer || null
      }
    });
  }

  res.json({ received: true });
});

export default router;
