import express from "express";
import cors from "cors";
import http from "http";
import dotenv from "dotenv";
import { PrismaClient } from "@prisma/client";
import authRoutes from "./auth.js";
import stripeRoutes from "./stripe.js";
import { authMiddleware } from "./middleware.js";
import { initSocket } from "./socket.js";

dotenv.config();

const app = express();
const prisma = new PrismaClient();
const server = http.createServer(app);
initSocket(server);

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

app.use("/auth", authRoutes);
app.use("/stripe", stripeRoutes);

app.get("/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user.id },
    include: { subscriptions: true }
  });
  res.json(user);
});

app.get("/conversations", authMiddleware, async (req, res) => {
  const conversations = await prisma.conversation.findMany({
    where: {
      members: { some: { userId: req.user.id } }
    },
    include: {
      messages: {
        orderBy: { createdAt: "desc" },
        take: 1
      }
    }
  });

  res.json(conversations);
});

app.post("/conversations", authMiddleware, async (req, res) => {
  const { memberIds } = req.body; // array of user IDs
  const conversation = await prisma.conversation.create({
    data: {
      members: {
        create: [
          { userId: req.user.id },
          ...memberIds.map((id) => ({ userId: id }))
        ]
      }
    },
    include: { members: true }
  });

  res.json(conversation);
});

app.get("/messages/:conversationId", authMiddleware, async (req, res) => {
  const { conversationId } = req.params;
  const messages = await prisma.message.findMany({
    where: { conversationId },
    orderBy: { createdAt: "asc" },
    include: { sender: true }
  });
  res.json(messages);
});

app.get("/notifications", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.id },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

app.post("/notifications/:id/read", authMiddleware, async (req, res) => {
  const { id } = req.params;
  await prisma.notification.update({
    where: { id },
    data: { read: true }
  });
  res.json({ ok: true });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
