```jsx
import { useEffect, useState } from "react";
import { api } from "../api";
import { createSocket } from "../socket";

export default function Chat({ user, notifications, setNotifications }) {
  const [socket, setSocket] = useState(null);
  const [conversations, setConversations] = useState([]);
  const [activeConversation, setActiveConversation] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    const s = createSocket();
    setSocket(s);

    s.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    s.on("newMessage", (msg) => {
      if (msg.conversationId === activeConversation?.id) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => s.disconnect();
  }, [activeConversation, setNotifications]);

  useEffect(() => {
    api.get("/conversations").then((res) => setConversations(res.data));
  }, []);

  const openConversation = async (conv) => {
    setActiveConversation(conv);
    const res = await api.get(`/messages/${conv.id}`);
    setMessages(res.data);
    socket?.emit("joinConversation", conv.id);
  };

  const send = () => {
    if (!activeConversation || !content.trim()) return;
    socket.emit("sendMessage", {
      conversationId: activeConversation.id,
      content
    });
    setContent("");
  };

  return (
    <div>
      <h2>Welcome, {user.username}</h2>

      <div style={{ display: "flex", gap: 20 }}>
        <div>
          <h3>Conversations</h3>
