## `server/src/stripe.js`

```js
import express from "express";
import Stripe from "stripe";
import { PrismaClient } from "@prisma/client";

const router = express.Router();
const prisma = new PrismaClient();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/create-checkout-session", async (req, res) => {
  try {
    const { userId, pack } = req.body;

    const packs = {
      small: { amount: 499, credits: 500 },
      medium: { amount: 999, credits: 1200 },
      large: { amount: 1999, credits: 2500 }
    };

    const selected = packs[pack];
    if (!selected) return res.status(400).json({ error: "Invalid pack" });

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: { name: `${selected.credits} Credits Pack` },
            unit_amount: selected.amount
          },
          quantity: 1
        }
      ],
      metadata: { userId, credits: String(selected.credits) },
      success_url: `${process.env.CLIENT_URL}/wallet?success=1`,
      cancel_url: `${process.env.CLIENT_URL}/wallet?canceled=1`
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: "Stripe error" });
  }
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  const sig = req.headers["stripe-signature"];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const credits = parseInt(session.metadata.credits, 10);

    await prisma.user.update({
      where: { id: userId },
      data: { balance: { increment: credits } }
    });
  }

  res.json({ received: true });
});

export default router;
```

