## `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import { Server } from "socket.io";
import { PrismaClient } from "@prisma/client";
import authRoutes from "./auth.js";
import stripeRoutes from "./stripe.js";
import { authMiddleware } from "./middleware.js";
import { setupSocket } from "./socket.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

const prisma = new PrismaClient();

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use("/stripe/webhook", express.raw({ type: "application/json" }));
app.use(express.json());

app.use("/auth", authRoutes);
app.use("/stripe", stripeRoutes);

setupSocket(io);

app.get("/me", authMiddleware, async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user.id },
    select: { id: true, email: true, name: true, balance: true }
  });
  res.json(user);
});

app.get("/messages/:userId", authMiddleware, async (req, res) => {
  const { userId } = req.params;
  const me = req.user.id;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: userId },
        { senderId: userId, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.get("/notifications", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.user.id },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

app.post("/send-premium-message", authMiddleware, async (req, res) => {
  const { receiverId, content, cost = 10 } = req.body;

  const sender = await prisma.user.findUnique({ where: { id: req.user.id } });
  if (sender.balance < cost) {
    return res.status(400).json({ error: "Insufficient credits" });
  }

  const [message] = await prisma.$transaction([
    prisma.message.create({
      data: { senderId: sender.id, receiverId, content }
    }),
    prisma.user.update({
      where: { id: sender.id },
      data: { balance: { decrement: cost } }
    }),
    prisma.notification.create({
      data: {
        userId: receiverId,
        type: "premium_message",
        title: "Premium message received",
        body: content.slice(0, 80)
      }
    })
  ]);

  io.to(receiverId).emit("new_message", message);
  io.to(receiverId).emit("new_notification", {
    type: "premium_message",
    title: "Premium message received",
    body: content.slice(0, 80)
  });

  res.json({ ok: true });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => console.log(`Server running on ${PORT}`));
```

