import React, { useEffect, useState } from "react";
import { api } from "./api";
import { socket } from "./socket";
import Login from "./pages/Login";
import Register from "./pages/Register";
import Chat from "./pages/Chat";
import Wallet from "./pages/Wallet";

export default function App() {
  const [page, setPage] = useState("login");
  const [user, setUser] = useState(null);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) return;

    api.get("/me").then((res) => {
      setUser(res.data);
      socket.connect();
      socket.emit("join", res.data.id);
    });

    socket.on("new_notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => {
      socket.off("new_notification");
    };
  }, []);

  const onAuth = (data) => {
    localStorage.setItem("token", data.token);
    setUser(data.user);
    setPage("chat");
    socket.connect();
    socket.emit("join", data.user.id);
  };

  if (!user) {
    return (
      <div>
        <button onClick={() => setPage("login")}>Login</button>
        <button onClick={() => setPage("register")}>Register</button>
        {page === "login" ? <Login onAuth={onAuth} /> : <Register onAuth={onAuth} />}
      </div>
    );
  }

  return (
    <div style={{ padding: 20 }}>
      <h2>Welcome, {user.name}</h2>
      <p>Balance: {user.balance} credits</p>

      <button onClick={() => setPage("chat")}>Chat</button>
      <button onClick={() => setPage("wallet")}>Wallet</button>

      <div style={{ marginTop: 20 }}>
        {page === "chat" && <Chat user={user} />}
        {page === "wallet" && <Wallet user={user} setUser={setUser} />}
      </div>

      <h3>Notifications</h3>
      {notifications.map((n, idx) => (
        <div key={idx} style={{ border: "1px solid #ccc", margin: "8px 0", padding: 8 }}>
          <strong>{n.title}</strong>
          <div>{n.body}</div>
        </div>
      ))}
    </div>
  );
}
