import React, { useEffect, useState } from "react";
import { api } from "../api";
import { socket } from "../socket";

export default function Chat({ user }) {
  const [receiverId, setReceiverId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState([]);

  useEffect(() => {
    const handler = (msg) => setMessages((prev) => [...prev, msg]);
    socket.on("new_message", handler);
    return () => socket.off("new_message", handler);
  }, []);

  const loadMessages = async () => {
    const res = await api.get(`/messages/${receiverId}`);
    setMessages(res.data);
  };

  const send = () => {
    socket.emit("send_message", {
      senderId: user.id,
      receiverId,
      content
    });
    setContent("");
  };

  return (
    <div>
      <h3>Chat</h3>
      <input placeholder="Receiver User ID" value={receiverId} onChange={(e) => setReceiverId(e.target.value)} />
      <button onClick={loadMessages}>Load Conversation</button>

      <div style={{ marginTop: 10 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <b>{m.senderId === user.id ? "Me" : "Them"}:</b> {m.content}
          </div>
        ))}
      </div>

      <textarea value={content} onChange={(e) => setContent(e.target.value)} />
      <button onClick={send}>Send</button>

      <hr />
      <h4>Premium message</h4>
      <button
        onClick={async () => {
          await api.post("/send-premium-message", {
            receiverId,
            content: `Premium: ${content}`,
            cost: 10
          });
          setContent("");
        }}
      >
        Send Premium Message (10 credits)
      </button>
    </div>
  );
}
