"use client";

import { useEffect, useState } from "react";
import { createSocket } from "../lib/socket";
import { apiFetch } from "../lib/api";

export default function ChatWindow({
  conversationId,
  token,
}: {
  conversationId: string;
  token: string;
}) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");

  useEffect(() => {
    const socket = createSocket(token);

    socket.on("connect", () => {
      socket.emit("joinConversation", conversationId);
    });

    socket.on("message:new", (message) => {
      setMessages((prev) => [...prev, message]);
    });

    return () => {
      socket.disconnect();
    };
  }, [conversationId, token]);

  useEffect(() => {
    apiFetch(`/messages/${conversationId}`, {}, token).then(setMessages);
  }, [conversationId, token]);

  const send = async () => {
    await apiFetch(
      `/messages/${conversationId}`,
      {
        method: "POST",
        body: JSON.stringify({ content }),
      },
      token
    );
    setContent("");
  };

  return (
    <div className="space-y-4">
      <div className="border p-4 rounded h-96 overflow-y-auto">
        {messages.map((m) => (
          <div key={m.id} className="mb-2">
            <strong>{m.sender?.displayName || "User"}:</strong> {m.content}
          </div>
        ))}
      </div>

      <div className="flex gap-2">
        <input
          className="border rounded px-3 py-2 flex-1"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          placeholder="Type a message..."
        />
        <button className="bg-blue-600 text-white px-4 py-2 rounded" onClick={send}>
          Send
        </button>
      </div>
    </div>
  );
}
