## 7) Socket.IO Real-Time Layer

### `src/sockets/index.js`
```js
import { Server } from "socket.io";

const onlineUsers = new Map(); // userId -> socketId

export function initSocket(server) {
  const io = new Server(server, {
    cors: {
      origin: "*",
      methods: ["GET", "POST"]
    }
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("user:online", ({ userId }) => {
      onlineUsers.set(userId, socket.id);
      socket.join(`user:${userId}`);
      io.emit("presence:update", { userId, status: "online" });
    });

    socket.on("message:send", async (data) => {
      const { conversationId, senderId, recipientId, content } = data;

      const message = {
        id: crypto.randomUUID(),
        conversationId,
        senderId,
        content,
        createdAt: new Date().toISOString()
      };

      // Persist message in DB here

      io.to(`user:${recipientId}`).emit("message:new", message);
      io.to(`user:${recipientId}`).emit("notification:new", {
        type: "message",
        payload: { conversationId, senderId, preview: content.slice(0, 80) }
      });

      socket.emit("message:sent", message);
    });

    socket.on("typing:start", ({ conversationId, userId, recipientId }) => {
      io.to(`user:${recipientId}`).emit("typing:update", {
        conversationId,
        userId,
        isTyping: true
      });
    });

    socket.on("typing:stop", ({ conversationId, userId, recipientId }) => {
      io.to(`user:${recipientId}`).emit("typing:update", {
        conversationId,
        userId,
        isTyping: false
      });
    });

    socket.on("disconnect", () => {
      for (const [userId, socketId] of onlineUsers.entries()) {
        if (socketId === socket.id) {
          onlineUsers.delete(userId);
          io.emit("presence:update", { userId, status: "offline" });
          break;
        }
      }
      console.log("Socket disconnected:", socket.id);
    });
  });
}
```

