## 6) Real-Time Messaging + Notifications

### Socket setup

```ts
// src/sockets/index.ts
import { Server } from "socket.io";
import { Server as HttpServer } from "http";

let io: Server;

export const initSocket = (server: HttpServer) => {
  io = new Server(server, {
    cors: { origin: true, credentials: true },
  });

  io.on("connection", (socket) => {
    console.log("socket connected", socket.id);

    socket.on("join", (userId: string) => {
      socket.join(userId); // personal room for notifications
    });

    socket.on("joinConversation", (conversationId: string) => {
      socket.join(conversationId);
    });

    socket.on("typing", ({ conversationId, userId }) => {
      socket.to(conversationId).emit("typing", { conversationId, userId });
    });

    socket.on("disconnect", () => {
      console.log("socket disconnected", socket.id);
    });
  });

  return io;
};

export const getIO = () => {
  if (!io) throw new Error("Socket.io not initialized");
  return io;
};
```

### Send message service

```ts
// src/services/chat.service.ts
import { prisma } from "../config/db";
import { getIO } from "../sockets";

export async function sendMessage({
  conversationId,
  senderId,
  content,
}: {
  conversationId: string;
  senderId: string;
  content: string;
}) {
  const message = await prisma.message.create({
    data: { conversationId, senderId, content },
    include: { sender: true },
  });

  const participants = await prisma.conversationParticipant.findMany({
    where: { conversationId },
  });

  const io = getIO();

  // Emit message to conversation room
  io.to(conversationId).emit("message:new", message);

  // Create and emit notifications to other participants
  for (const p of participants) {
    if (p.userId !== senderId) {
      const notification = await prisma.notification.create({
        data: {
          userId: p.userId,
          type: "message",
          title: "New message",
          body: `${message.sender.displayName}: ${content.slice(0, 80)}`,
          data: { conversationId, messageId: message.id },
        },
      });

      io.to(p.userId).emit("notification:new", notification);
    }
  }

  return message;
}
```

