# 7) Real-Time Socket Setup

## `src/sockets/index.ts`
```ts
import { Server } from "socket.io";
import http from "http";
import jwt from "jsonwebtoken";

let io: Server;

export function initSocket(server: http.Server) {
  io = new Server(server, {
    cors: {
      origin: true,
      credentials: true,
    },
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET!) as any;
      socket.data.user = payload;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const user = socket.data.user;
    socket.join(`user:${user.id}`);

    socket.on("message:send", async (payload) => {
      // payload: { conversationId, body, recipientIds }
      // Save message in DB here, then emit to recipients
      io.to(`user:${payload.recipientId}`).emit("message:new", {
        conversationId: payload.conversationId,
        body: payload.body,
        senderId: user.id,
      });

      io.to(`user:${payload.recipientId}`).emit("notification:new", {
        type: "message",
        title: "New message",
        body: payload.body,
      });
    });

    socket.on("typing:start", ({ conversationId, recipientId }) => {
      io.to(`user:${recipientId}`).emit("typing:started", {
        conversationId,
        userId: user.id,
      });
    });

    socket.on("typing:stop", ({ conversationId, recipientId }) => {
      io.to(`user:${recipientId}`).emit("typing:stopped", {
        conversationId,
        userId: user.id,
      });
    });
  });

  return io;
}

export function getIO() {
  if (!io) throw new Error("Socket.io not initialized");
  return io;
}
```

