import { useEffect, useState } from "react";

export function ChatWindow({ socket, conversationId }: any) {
  const [messages, setMessages] = useState<any[]>([]);
  const [text, setText] = useState("");

  useEffect(() => {
    socket.on("message:new", (msg: any) => {
      if (msg.conversationId === conversationId) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    return () => {
      socket.off("message:new");
    };
  }, [socket, conversationId]);

  const sendMessage = () => {
    socket.emit("message:send", {
      conversationId,
      body: text,
      recipientId: "recipient-user-id", // resolve from conversation
    });
    setText("");
  };

  return (
    <div>
      <div className="border p-4 h-96 overflow-y-auto">
        {messages.map((m) => (
          <div key={m.id} className="mb-2">
            <strong>{m.senderId}:</strong> {m.body}
          </div>
        ))}
      </div>

      <div className="flex gap-2 mt-2">
        <input
          className="border flex-1 p-2"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Type a message..."
        />
        <button className="bg-blue-600 text-white px-4" onClick={sendMessage}>
          Send
        </button>
      </div>
    </div>
  );
}
