## `src/sockets/index.ts`
```ts
import { Server } from "socket.io";
import http from "http";
import { prisma } from "../prisma";

export function initSocket(server: http.Server) {
  const io = new Server(server, {
    cors: { origin: true, credentials: true },
  });

  io.on("connection", (socket) => {
    console.log("socket connected:", socket.id);

    socket.on("auth:join", async ({ userId }) => {
      socket.join(`user:${userId}`);
    });

    socket.on("chat:send_message", async (payload, ack) => {
      try {
        const { conversationId, senderId, content, contentType = "text" } = payload;

        const message = await prisma.message.create({
          data: {
            conversationId,
            senderId,
            content,
            contentType,
          },
        });

        const members = await prisma.conversationMember.findMany({
          where: { conversationId },
        });

        members.forEach((member) => {
          io.to(`user:${member.userId}`).emit("chat:message_created", message);
        });

        ack?.({ ok: true, message });
      } catch (error) {
        console.error(error);
        ack?.({ ok: false, error: "Failed to send message" });
      }
    });

    socket.on("chat:typing", ({ conversationId, userId, isTyping }) => {
      socket.to(`conversation:${conversationId}`).emit("chat:typing", {
        conversationId,
        userId,
        isTyping,
      });
    });

    socket.on("disconnect", () => {
      console.log("socket disconnected:", socket.id);
    });
  });
}
```

