# 10) Socket.IO real-time layer

## `server/src/sockets/index.ts`

```ts
import { Server } from "socket.io";
import { PrismaClient } from "@prisma/client";
import jwt from "jsonwebtoken";

export function registerSocketHandlers(io: Server, prisma: PrismaClient) {
  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const payload = jwt.verify(token, process.env.JWT_SECRET as string) as any;
      socket.data.userId = payload.userId;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", async (socket) => {
    const userId = socket.data.userId;
    socket.join(`user:${userId}`);

    socket.on("conversation:join", (conversationId: string) => {
      socket.join(`conversation:${conversationId}`);
    });

    socket.on("message:send", async (payload) => {
      const { conversationId, recipientId, content } = payload;

      const message = await prisma.message.create({
        data: {
          conversationId,
          senderId: userId,
          recipientId,
          content
        }
      });

      await prisma.notification.create({
        data: {
          userId: recipientId,
          type: "MESSAGE",
          title: "New message",
          body: content.slice(0, 80),
          data: { conversationId, messageId: message.id }
        }
      });

      io.to(`conversation:${conversationId}`).emit("message:new", message);
      io.to(`user:${recipientId}`).emit("notification:new", {
        type: "MESSAGE",
        title: "New message",
        body: content.slice(0, 80),
        conversationId,
        messageId: message.id
      });
    });

    socket.on("typing:start", ({ conversationId }) => {
      socket.to(`conversation:${conversationId}`).emit("typing:start", {
        conversationId,
        userId
      });
    });

    socket.on("typing:stop", ({ conversationId }) => {
      socket.to(`conversation:${conversationId}`).emit("typing:stop", {
        conversationId,
        userId
      });
    });

    socket.on("disconnect", () => {
      // presence cleanup can be added here
    });
  });
}
```

