## Simple chat screen example

## `client/src/screens/ChatScreen.tsx`

```tsx
import React, { useEffect, useState } from "react";
import { api } from "../services/api";
import { createSocket } from "../services/socket";

export default function ChatScreen({
  conversationId,
  recipientId
}: {
  conversationId: string;
  recipientId: string;
}) {
  const [messages, setMessages] = useState<any[]>([]);
  const [content, setContent] = useState("");
  const token = localStorage.getItem("token") || "";
  const socket = createSocket(token);

  useEffect(() => {
    api.get(`/messages/${conversationId}`).then((res) => setMessages(res.data));
    socket.emit("conversation:join", conversationId);

    socket.on("message:new", (message) => {
      if (message.conversationId === conversationId) {
        setMessages((prev) => [...prev, message]);
      }
    });

    return () => {
      socket.disconnect();
    };
  }, [conversationId]);

  const sendMessage = async () => {
    if (!content.trim()) return;

    socket.emit("message:send", {
      conversationId,
      recipientId,
      content
    });

    setContent("");
  };

  return (
    <div>
      <h2>Chat</h2>
      <div style={{ border: "1px solid #ccc", padding: 12, minHeight: 300 }}>
        {messages.map((m) => (
          <div key={m.id}>
            <strong>{m.senderId === recipientId ? "Them" : "You"}:</strong> {m.content}
          </div>
        ))}
      </div>

      <input
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Type a message..."
      />
      <button onClick={sendMessage}>Send</button>
    </div>
  );
}
```

