# 7) Backend Starter Code

## `server.ts`
```ts
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
app.use(cors({ origin: "*" }));
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" },
});

io.on("connection", (socket) => {
  console.log("socket connected:", socket.id);

  socket.on("auth:join", ({ userId }) => {
    socket.join(userId);
    socket.data.userId = userId;
    io.to(userId).emit("presence:update", { userId, status: "online" });
  });

  socket.on("message:send", async (payload) => {
    const { chatId, senderId, recipientId, content } = payload;

    // TODO: persist message in DB
    const message = {
      id: crypto.randomUUID(),
      chatId,
      senderId,
      content,
      createdAt: new Date().toISOString(),
    };

    io.to(recipientId).emit("message:new", message);
    io.to(senderId).emit("message:new", message);

    // TODO: create notification if recipient is offline
    io.to(recipientId).emit("notification:new", {
      type: "MESSAGE",
      title: "New message",
      body: content.slice(0, 80),
    });
  });

  socket.on("message:typing", ({ chatId, recipientId, isTyping }) => {
    io.to(recipientId).emit("chat:typing", {
      chatId,
      userId: socket.data.userId,
      isTyping,
    });
  });

  socket.on("disconnect", () => {
    const userId = socket.data.userId;
    if (userId) {
      io.to(userId).emit("presence:update", { userId, status: "offline" });
    }
  });
});

app.get("/health", (_, res) => res.json({ ok: true }));

server.listen(3000, () => {
  console.log("Server running on http://localhost:3000");
});
```

