# 8) Socket.IO Setup

## `server/src/sockets/index.ts`
```ts
import { Server } from "socket.io";
import http from "http";
import jwt from "jsonwebtoken";

let io: Server;

export const initSocket = (server: http.Server) => {
  io = new Server(server, {
    cors: {
      origin: true,
      credentials: true,
    },
  });

  io.use((socket, next) => {
    const token = socket.handshake.auth?.token;
    if (!token) return next(new Error("Unauthorized"));

    try {
      const decoded = jwt.verify(token, process.env.JWT_SECRET as string) as any;
      socket.data.userId = decoded.sub;
      next();
    } catch {
      next(new Error("Unauthorized"));
    }
  });

  io.on("connection", (socket) => {
    const userId = socket.data.userId;
    socket.join(`user:${userId}`);

    socket.on("message:send", async (payload) => {
      // persist message in DB here
      // emit to conversation members
      io.to(`user:${payload.recipientId}`).emit("message:new", payload);
      io.to(`user:${userId}`).emit("message:new", payload);
    });

    socket.on("typing:start", (payload) => {
      io.to(`user:${payload.recipientId}`).emit("typing:started", {
        userId,
        conversationId: payload.conversationId,
      });
    });

    socket.on("disconnect", () => {
      // update presence
    });
  });
};

export const getIO = () => {
  if (!io) throw new Error("Socket.IO not initialized");
  return io;
};
```

