const { Server } = require('socket.io');

function initSocket(server) {
  const io = new Server(server, {
    cors: {
      origin: '*',
      methods: ['GET', 'POST']
    }
  });

  io.on('connection', (socket) => {
    console.log('Socket connected:', socket.id);

    socket.on('join:user', (userId) => {
      socket.join(`user:${userId}`);
    });

    socket.on('join:conversation', (conversationId) => {
      socket.join(`conversation:${conversationId}`);
    });

    socket.on('message:send', async (payload) => {
      // payload: { conversationId, senderId, content }
      io.to(`conversation:${payload.conversationId}`).emit('message:new', payload);
      io.to(`user:${payload.senderId}`).emit('notification:new', {
        type: 'message_sent',
        title: 'Message sent',
        body: 'Your message was delivered.'
      });
    });

    socket.on('typing', ({ conversationId, userId, isTyping }) => {
      socket.to(`conversation:${conversationId}`).emit('typing', { userId, isTyping });
    });

    socket.on('disconnect', () => {
      console.log('Socket disconnected:', socket.id);
    });
  });

  return io;
}

module.exports = { initSocket };
