## 7) Real-Time Messaging with Socket.IO

### `src/sockets/index.ts`
```ts
import { Server } from "socket.io";
import { Server as HttpServer } from "http";

let io: Server;

export function initSocket(server: HttpServer) {
  io = new Server(server, {
    cors: {
      origin: "*",
      methods: ["GET", "POST"]
    }
  });

  io.on("connection", (socket) => {
    console.log("Socket connected:", socket.id);

    socket.on("join_conversation", (conversationId: string) => {
      socket.join(conversationId);
    });

    socket.on("send_message", async (payload) => {
      // payload: { conversationId, senderId, content }
      io.to(payload.conversationId).emit("new_message", {
        id: crypto.randomUUID(),
        ...payload,
        createdAt: new Date().toISOString()
      });

      // emit notification to participants (simplified)
      io.emit("notification", {
        type: "message",
        title: "New message",
        body: payload.content
      });
    });

    socket.on("typing", (payload) => {
      socket.to(payload.conversationId).emit("typing", {
        userId: payload.userId,
        conversationId: payload.conversationId
      });
    });

    socket.on("disconnect", () => {
      console.log("Socket disconnected:", socket.id);
    });
  });
}
```

