### `server/src/index.js`
```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import bcrypt from "bcryptjs";
import http from "http";
import { PrismaClient } from "@prisma/client";
import { signToken, requireAuth } from "./auth.js";
import { setupSocket } from "./socket.js";
import { stripe } from "./stripe.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const io = setupSocket(server);
const prisma = new PrismaClient();

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

// Auth
app.post("/api/register", async (req, res) => {
  const { email, password, name } = req.body;
  const passwordHash = await bcrypt.hash(password, 10);

  const user = await prisma.user.create({
    data: { email, passwordHash, name }
  });

  res.json({ token: signToken(user), user });
});

app.post("/api/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.passwordHash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({ token: signToken(user), user });
});

// Users
app.get("/api/users", requireAuth, async (req, res) => {
  const users = await prisma.user.findMany({
    where: { id: { not: req.user.id } },
    select: { id: true, name: true, email: true, premium: true, credits: true }
  });
  res.json(users);
});

// Messages
app.get("/api/messages/:userId", requireAuth, async (req, res) => {
  const me = req.user.id;
  const other = req.params.userId;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: other },
        { senderId: other, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.post("/api/messages", requireAuth, async (req, res) => {
  const { receiverId, text, boosted } = req.body;
  const senderId = req.user.id;

  const sender = await prisma.user.findUnique({ where: { id: senderId } });

  if (boosted && sender.credits < 1 && !sender.premium) {
    return res.status(402).json({ error: "Not enough credits" });
  }

  const message = await prisma.message.create({
    data: { senderId, receiverId, text, boosted: !!boosted }
  });

  if (boosted && !sender.premium) {
    await prisma.user.update({
      where: { id: senderId },
      data: { credits: { decrement: 1 } }
    });
  }

  io.to(receiverId).emit("message", message);
  io.to(receiverId).emit("notification", {
    type: "message",
    text: `New message from ${req.user.name}`
  });

  res.json(message);
});

// Monetization: create checkout session
app.post("/api/create-checkout-session", requireAuth, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: `${process.env.CLIENT_URL}/success`,
    cancel_url: `${process.env.CLIENT_URL}/pricing`,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "10 Credits Pack" },
          unit_amount: 499
        },
        quantity: 1
      }
    ],
    metadata: {
      userId: req.user.id,
      creditsAdded: "10"
    }
  });

  res.json({ url: session.url });
});

// Stripe webhook
app.post(
  "/api/webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        req.headers["stripe-signature"],
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;
      const creditsAdded = parseInt(session.metadata.creditsAdded, 10);

      await prisma.user.update({
        where: { id: userId },
        data: { credits: { increment: creditsAdded } }
      });

      await prisma.payment.create({
        data: {
          stripeSessionId: session.id,
          userId,
          amount: session.amount_total,
          creditsAdded
        }
      });

      io.to(userId).emit("notification", {
        type: "payment",
        text: `Payment successful. ${creditsAdded} credits added.`
      });
    }

    res.json({ received: true });
  }
);

server.listen(3001, () => console.log("Server running on http://localhost:3001"));
```

