```jsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [users, setUsers] = useState([]);
  const [selected, setSelected] = useState(null);
  const [messages, setMessages] = useState([]);
  const [text, setText] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [socket, setSocket] = useState(null);
  const [loginMode, setLoginMode] = useState(true);
  const [form, setForm] = useState({ email: "", password: "", name: "" });

  useEffect(() => {
    if (!token) return;
    const s = createSocket(token);
    setSocket(s);

    s.on("message", (msg) => {
      if (selected && (msg.senderId === selected.id || msg.receiverId === selected.id)) {
        setMessages((m) => [...m, msg]);
      }
    });

    s.on("notification", (n) => setNotifications((prev) => [n, ...prev]));

    return () => s.disconnect();
  }, [token, selected]);

  useEffect(() => {
    if (!token) return;
    api("/users", "GET", null, token).then(setUsers);
  }, [token]);

  useEffect(() => {
    if (!token || !selected) return;
    api(`/messages/${selected.id}`, "GET", null, token).then(setMessages);
  }, [token, selected]);

  async function submitAuth(e) {
    e.preventDefault();
    const path = loginMode ? "/login" : "/register";
    const data = await api(path, "POST", form);
    if (data.token) {
      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user));
      setToken(data.token);
      setUser(data.user);
    }
  }

  async function sendMessage(boosted = false) {
    if (!selected || !text) return;
    const msg = await api("/messages", "POST", {
      receiverId: selected.id,
      text,
      boosted
    }, token);

    setMessages((m) => [...m, msg]);
    setText("");
  }

  async function buyCredits() {
    const data = await api("/create-checkout-session", "POST", {}, token);
    window.location.href = data.url;
  }

  if (!token) {
    return (
      <div style={{ padding: 24 }}>
        <h2>{loginMode ? "Login" : "Register"}</h2>
        <form onSubmit={submitAuth}>
          {!loginMode && (
            <input
              placeholder="Name"
              value={form.name}
              onChange={(e) => setForm({ ...form, name: e.target.value })}
            />
          )}
          <br />
          <input
            placeholder="Email"
            value={form.email}
            onChange={(e) => setForm({ ...form, email: e.target.value })}
          />
          <br />
          <input
            type="password"
            placeholder="Password"
            value={form.password}
            onChange={(e) => setForm({ ...form, password: e.target.value })}
          />
          <br />
          <button type="submit">{loginMode ? "Login" : "Register"}</button>
        </form>
        <button onClick={() => setLoginMode(!loginMode)}>
          Switch to {loginMode ? "Register" : "Login"}
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <div style={{ width: 250, borderRight: "1px solid #ddd", padding: 16 }}>
        <h3>{user?.name}</h3>
        <p>Credits: {user?.credits ?? 0}</p>
        <p>Premium: {user?.premium ? "Yes" : "No"}</p>
        <button onClick={buyCredits}>Buy Credits</button>
        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => setSelected(u)}>
              {u.name} {u.premium ? "⭐" : ""}
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1, padding: 16 }}>
        <h3>Chat {selected ? `with ${selected.name}` : ""}</h3>
        <div style={{ height: 400, overflowY: "auto", border: "1px solid #ddd", padding: 8 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.senderId === user.id ? "You" : selected?.name}:</b> {m.text}
              {m.boosted ? " 🚀" : ""}
            </div>
          ))}
        </div>
        <div style={{ marginTop: 12 }}>
          <input
            value={text}
            onChange={(e) => setText(e.target.value)}
            placeholder="Type a message"
          />
          <button onClick={() => sendMessage(false)}>Send</button>
          <button onClick={() => sendMessage(true)}>Send Boosted (1 credit)</button>
        </div>

        <h4>Notifications</h4>
        <ul>
          {notifications.map((n, i) => (
            <li key={i}>{n.text}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}
