  content TEXT NOT NULL,
  isPremium INTEGER NOT NULL DEFAULT 0,
  createdAt TEXT NOT NULL DEFAULT (datetime('now')),
  FOREIGN KEY(senderId) REFERENCES users(id),
  FOREIGN KEY(recipientId) REFERENCES users(id)
);
`);

export default db;
