## `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import jwt from "jsonwebtoken";
import db from "./db.js";

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const PORT = 3001;
const JWT_SECRET = "dev_secret_change_me";

app.use(cors());
app.use(express.json());

function signToken(user) {
  return jwt.sign({ id: user.id, username: user.username }, JWT_SECRET, {
    expiresIn: "7d"
  });
}

function authMiddleware(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: "Missing token" });
  const token = auth.replace("Bearer ", "");
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

function getUserByUsername(username) {
  return db.prepare("SELECT * FROM users WHERE username = ?").get(username);
}

function getUserById(id) {
  return db.prepare("SELECT * FROM users WHERE id = ?").get(id);
}

function notifyUser(userId, payload) {
  io.to(`user:${userId}`).emit("notification", payload);
}

app.post("/auth/register", (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "Username required" });

  try {
    const info = db.prepare("INSERT INTO users (username, coins) VALUES (?, 100)").run(username);
    const user = getUserById(info.lastInsertRowid);
    return res.json({ token: signToken(user), user });
  } catch {
    return res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/auth/login", (req, res) => {
  const { username } = req.body;
  const user = getUserByUsername(username);
  if (!user) return res.status(404).json({ error: "User not found" });
  return res.json({ token: signToken(user), user });
});

app.get("/me", authMiddleware, (req, res) => {
  const user = getUserById(req.user.id);
  res.json({ user });
});

app.get("/messages/:room", authMiddleware, (req, res) => {
  const { room } = req.params;
  const messages = db.prepare(`
    SELECT m.*, u.username as senderUsername
    FROM messages m
    JOIN users u ON u.id = m.senderId
    WHERE m.room = ?
    ORDER BY m.id ASC
    LIMIT 100
  `).all(room);

  res.json({ messages });
});

app.post("/messages", authMiddleware, (req, res) => {
  const { room, content, recipientUsername, premium } = req.body;
  const sender = getUserById(req.user.id);
  if (!room || !content) return res.status(400).json({ error: "room and content required" });

  let recipientId = null;
  if (recipientUsername) {
    const recipient = getUserByUsername(recipientUsername);
    if (!recipient) return res.status(404).json({ error: "Recipient not found" });
    recipientId = recipient.id;
  }

  const isPremium = premium ? 1 : 0;
  const cost = isPremium ? 10 : 0;

  if (sender.coins < cost) {
    return res.status(400).json({ error: "Insufficient coins" });
  }

  if (cost > 0) {
    db.prepare("UPDATE users SET coins = coins - ? WHERE id = ?").run(cost, sender.id);
  }

  const info = db.prepare(`
    INSERT INTO messages (senderId, recipientId, room, content, isPremium)
    VALUES (?, ?, ?, ?, ?)
  `).run(sender.id, recipientId, room, content, isPremium);

  const message = db.prepare(`
    SELECT m.*, u.username as senderUsername
    FROM messages m
    JOIN users u ON u.id = m.senderId
    WHERE m.id = ?
  `).get(info.lastInsertRowid);

  io.to(`room:${room}`).emit("message", message);

  if (recipientId) {
    notifyUser(recipientId, {
      type: "message",
      title: isPremium ? "Premium message received" : "New message received",
      body: `${sender.username}: ${content}`,
      message
    });
  }

  if (cost > 0) {
    const updated = getUserById(sender.id);
    notifyUser(sender.id, {
      type: "balance",
      title: "Coins spent",
      body: `You spent ${cost} coins. Balance: ${updated.coins}`
    });
  }

  res.json({ message });
});

app.post("/wallet/topup", authMiddleware, (req, res) => {
  const { amount } = req.body;
  const topup = Number(amount || 0);
  if (topup <= 0) return res.status(400).json({ error: "Invalid amount" });

  db.prepare("UPDATE users SET coins = coins + ? WHERE id = ?").run(topup, req.user.id);
  const user = getUserById(req.user.id);

  notifyUser(req.user.id, {
    type: "balance",
    title: "Top-up successful",
    body: `Added ${topup} coins. Balance: ${user.coins}`
  });

  res.json({ user });
});

io.on("connection", (socket) => {
  socket.on("auth", ({ token }) => {
    try {
      const user = jwt.verify(token, JWT_SECRET);
      socket.user = user;
      socket.join(`user:${user.id}`);
    } catch {}
  });

  socket.on("joinRoom", ({ room }) => {
    socket.join(`room:${room}`);
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

