```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import { request } from "./api.js";

const SOCKET_URL = "http://localhost:3001";

export default function App() {
  const [username, setUsername] = useState("");
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [room, setRoom] = useState("general");
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [recipientUsername, setRecipientUsername] = useState("");
  const [premium, setPremium] = useState(false);
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => io(SOCKET_URL, { autoConnect: false }), []);

  useEffect(() => {
    if (!token) return;
    socket.connect();
    socket.emit("auth", { token });

    socket.on("message", (msg) => {
      if (msg.room === room) setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev].slice(0, 10));
    });

    return () => {
      socket.off("message");
      socket.off("notification");
      socket.disconnect();
    };
  }, [token, room, socket]);

  useEffect(() => {
    if (!token) return;
    request(`/me`, "GET", null, token).then((data) => setUser(data.user));
    request(`/messages/${room}`, "GET", null, token).then((data) => setMessages(data.messages || []));
    socket.emit("joinRoom", { room });
  }, [token, room, socket]);

  async function register() {
    const data = await request("/auth/register", "POST", { username });
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    }
  }

  async function login() {
    const data = await request("/auth/login", "POST", { username });
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    }
  }

  async function sendMessage() {
    const data = await request(
      "/messages",
      "POST",
      { room, content, recipientUsername: recipientUsername || undefined, premium },
      token
    );
    if (data.message) setContent("");
  }

  async function topup() {
    const data = await request("/wallet/topup", "POST", { amount: 50 }, token);
    if (data.user) setUser(data.user);
  }

  if (!token) {
    return (
      <div style={{ padding: 20, fontFamily: "sans-serif" }}>
        <h2>Social Messaging App</h2>
        <input
          placeholder="username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <button onClick={register}>Register</button>
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif", display: "grid", gap: 12 }}>
      <h2>Social Messaging App</h2>
      <div>
        Logged in as <b>{user?.username}</b> | Coins: <b>{user?.coins}</b>
        <button style={{ marginLeft: 12 }} onClick={topup}>Top up +50</button>
      </div>

      <div>
        <label>Room: </label>
        <input value={room} onChange={(e) => setRoom(e.target.value)} />
      </div>

      <div>
        <input
          placeholder="recipient username (optional)"
          value={recipientUsername}
          onChange={(e) => setRecipientUsername(e.target.value)}
        />
      </div>

      <div>
        <input
          placeholder="message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
          style={{ width: 300 }}
        />
        <label style={{ marginLeft: 10 }}>
          <input
            type="checkbox"
            checked={premium}
            onChange={(e) => setPremium(e.target.checked)}
          />
          Premium (10 coins)
        </label>
        <button onClick={sendMessage}>Send</button>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "2fr 1fr", gap: 20 }}>
        <div>
          <h3>Messages</h3>
          <div style={{ border: "1px solid #ccc", padding: 10, minHeight: 300 }}>
            {messages.map((m) => (
              <div key={m.id} style={{ marginBottom: 8 }}>
                <b>{m.senderUsername}</b>: {m.content} {m.isPremium ? "⭐" : ""}
              </div>
            ))}
          </div>
        </div>

        <div>
          <h3>Notifications</h3>
          <div style={{ border: "1px solid #ccc", padding: 10, minHeight: 300 }}>
            {notifications.map((n, i) => (
              <div key={i} style={{ marginBottom: 8 }}>
                <b>{n.title}</b>
                <div>{n.body}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
