## `server/src/stripe.js`

```js
import express from "express";
import Stripe from "stripe";

export function stripeRoutes(prisma, io) {
  const router = express.Router();
  const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

  router.post("/create-checkout-session", async (req, res) => {
    const { userId } = req.body;

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      line_items: [
        {
          price: process.env.STRIPE_PRICE_ID,
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/?success=1`,
      cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
      metadata: { userId }
    });

    res.json({ url: session.url });
  });

  // NOTE: In production, use raw body parsing for webhook verification.
  router.post("/webhook", express.raw({ type: "application/json" }), async (req, res) => {
    const sig = req.headers["stripe-signature"];
    let event;

    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        sig,
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = session.metadata.userId;

      await prisma.user.update({
        where: { id: userId },
        data: { coins: { increment: 100 } }
      });

      io.to(userId).emit("notification", {
        type: "payment",
        message: "Payment successful! 100 coins added."
      });
    }

    res.json({ received: true });
  });

  return router;
}
```

