## `server/src/socket.js`

```js
export function setupSocket(io, prisma) {
  io.on("connection", (socket) => {
    socket.on("join", (userId) => {
      socket.join(userId);
    });

    socket.on("send_message", async ({ userId, content, boosted }) => {
      const user = await prisma.user.findUnique({ where: { id: userId } });

      if (!user) return;

      if (boosted) {
        if (user.coins < 10) {
          socket.emit("notification", {
            type: "error",
            message: "Not enough coins for boosted message."
          });
          return;
        }

        await prisma.user.update({
          where: { id: userId },
          data: { coins: { decrement: 10 } }
        });
      }

      const message = await prisma.message.create({
        data: { userId, content, boosted: !!boosted },
        include: { user: true }
      });

      io.emit("new_message", {
        id: message.id,
        content: message.content,
        boosted: message.boosted,
        createdAt: message.createdAt,
        user: { id: message.user.id, email: message.user.email }
      });

      io.to(userId).emit("notification", {
        type: "message",
        message: boosted ? "Boosted message sent!" : "Message sent."
      });
    });
  });
}
```

