```jsx
import React, { useEffect, useState } from "react";
import { register, login, getMe, getMessages, createCheckoutSession } from "./api";
import { socket } from "./socket";

export default function App() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;

    getMe(token).then(setUser);
    getMessages(token).then(setMessages);

    socket.emit("join", JSON.parse(atob(token.split(".")[1])).id);

    socket.on("new_message", (msg) => setMessages((prev) => [...prev, msg]));
    socket.on("notification", (n) => setNotifications((prev) => [n, ...prev]));

    return () => {
      socket.off("new_message");
      socket.off("notification");
    };
  }, [token]);

  async function handleRegister() {
    const res = await register(email, password);
    if (res.token) {
      localStorage.setItem("token", res.token);
      setToken(res.token);
    }
  }

  async function handleLogin() {
    const res = await login(email, password);
    if (res.token) {
      localStorage.setItem("token", res.token);
      setToken(res.token);
    }
  }

  function sendMessage(boosted = false) {
    const userId = JSON.parse(atob(token.split(".")[1])).id;
    socket.emit("send_message", { userId, content, boosted });
    setContent("");
  }

  async function buyCoins() {
    const userId = JSON.parse(atob(token.split(".")[1])).id;
    const res = await createCheckoutSession(userId);
    window.location.href = res.url;
  }

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Social Messaging App</h2>
        <input placeholder="email" value={email} onChange={(e) => setEmail(e.target.value)} />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <div>
          <button onClick={handleRegister}>Register</button>
          <button onClick={handleLogin}>Login</button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding: 20, fontFamily: "sans-serif" }}>
      <h2>Social Messaging App</h2>
      <p>Logged in as: {user?.email}</p>
      <p>Coins: {user?.coins ?? 0}</p>

      <button onClick={buyCoins}>Buy 100 Coins</button>

      <div style={{ marginTop: 20 }}>
        <input
          placeholder="Type a message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <button onClick={() => sendMessage(false)}>Send</button>
        <button onClick={() => sendMessage(true)}>Send Boosted (-10 coins)</button>
      </div>

      <h3>Notifications</h3>
      <ul>
        {notifications.map((n, i) => (
          <li key={i}>{n.message}</li>
        ))}
      </ul>

      <h3>Messages</h3>
      <ul>
        {messages.map((m) => (
          <li key={m.id}>
            <strong>{m.user?.email}:</strong> {m.content} {m.boosted ? "⭐" : ""}
          </li>
        ))}
      </ul>
    </div>
  );
}
```

