import sqlite3 from "sqlite3";
import { open } from "sqlite";

export async function initDb() {
  const db = await open({
    filename: "./app.db",
    driver: sqlite3.Database
  });

  await db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password TEXT NOT NULL,
      credits INTEGER DEFAULT 0
    );

    CREATE TABLE IF NOT EXISTS messages (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      senderId INTEGER NOT NULL,
      receiverId INTEGER NOT NULL,
      content TEXT NOT NULL,
      isPremium INTEGER DEFAULT 0,
      createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
    );
  `);

  return db;
}
```

## `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import { Server } from "socket.io";
import { initDb } from "./db.js";

const JWT_SECRET = "dev_secret_change_me";
const PORT = 4000;

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const db = await initDb();

function createToken(user) {
  return jwt.sign({ id: user.id, username: user.username }, JWT_SECRET, {
    expiresIn: "7d"
  });
}

function authMiddleware(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ error: "No token" });

  const token = auth.split(" ")[1];
  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    res.status(401).json({ error: "Invalid token" });
  }
}

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  const hashed = await bcrypt.hash(password, 10);
  try {
    const result = await db.run(
      "INSERT INTO users (username, password, credits) VALUES (?, ?, ?)",
      [username, hashed, 0]
    );
    const user = { id: result.lastID, username };
    res.json({ token: createToken(user), user: { ...user, credits: 0 } });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({
    token: createToken(user),
    user: { id: user.id, username: user.username, credits: user.credits }
  });
});

app.get("/api/me", authMiddleware, async (req, res) => {
  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

app.get("/api/users", authMiddleware, async (req, res) => {
  const users = await db.all("SELECT id, username, credits FROM users WHERE id != ?", [req.user.id]);
  res.json(users);
});

app.get("/api/messages/:userId", authMiddleware, async (req, res) => {
  const otherId = Number(req.params.userId);
  const myId = req.user.id;

  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (senderId = ? AND receiverId = ?)
        OR (senderId = ? AND receiverId = ?)
     ORDER BY createdAt ASC`,
    [myId, otherId, otherId, myId]
  );

  res.json(messages);
});

app.post("/api/messages", authMiddleware, async (req, res) => {
  const { receiverId, content, isPremium } = req.body;
  const senderId = req.user.id;

  if (!receiverId || !content) return res.status(400).json({ error: "Missing fields" });

  const sender = await db.get("SELECT * FROM users WHERE id = ?", [senderId]);
  if (isPremium && sender.credits < 1) {
    return res.status(400).json({ error: "Not enough credits" });
  }

  if (isPremium) {
    await db.run("UPDATE users SET credits = credits - 1 WHERE id = ?", [senderId]);
  }

  const result = await db.run(
    "INSERT INTO messages (senderId, receiverId, content, isPremium) VALUES (?, ?, ?, ?)",
    [senderId, receiverId, content, isPremium ? 1 : 0]
  );

  const message = {
    id: result.lastID,
    senderId,
    receiverId,
    content,
    isPremium: isPremium ? 1 : 0,
    createdAt: new Date().toISOString()
  };

  const updatedSender = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [senderId]);

  io.to(`user:${receiverId}`).emit("new_message", message);
  io.to(`user:${receiverId}`).emit("notification", {
    type: "message",
    text: `New message from ${req.user.username}`
  });

  res.json({ message, sender: updatedSender });
});

app.post("/api/buy-credits", authMiddleware, async (req, res) => {
  const { amount } = req.body;
  const creditsToAdd = Number(amount || 0);

  if (creditsToAdd <= 0) return res.status(400).json({ error: "Invalid amount" });

  await db.run("UPDATE users SET credits = credits + ? WHERE id = ?", [creditsToAdd, req.user.id]);
  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);

  io.to(`user:${req.user.id}`).emit("notification", {
    type: "purchase",
    text: `You purchased ${creditsToAdd} credits`
  });

  res.json({ user });
});

io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    socket.join(`user:${userId}`);
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

