import React, { useEffect, useState } from "react";
import { api } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [isPremium, setIsPremium] = useState(false);
  const [notifications, setNotifications] = useState([]);

  async function loadMe(t) {
    const me = await api("/me", "GET", null, t);
    setUser(me);
    socket.auth = { token: t };
    socket.connect();
    socket.emit("join", me.id);
  }

  useEffect(() => {
    if (token) {
      loadMe(token).catch(() => {
        localStorage.removeItem("token");
        setToken("");
      });
    }
  }, []);

  useEffect(() => {
    if (!user) return;

    api("/users", "GET", null, token).then(setUsers);

    const onMessage = (msg) => {
      if (selectedUser && msg.senderId === selectedUser.id) {
        setMessages((prev) => [...prev, msg]);
      }
    };

    const onNotification = (n) => {
      setNotifications((prev) => [n, ...prev]);
    };

    socket.on("new_message", onMessage);
    socket.on("notification", onNotification);

    return () => {
      socket.off("new_message", onMessage);
      socket.off("notification", onNotification);
    };
  }, [user, selectedUser, token]);

  async function handleAuth() {
    const path = authMode === "login" ? "/login" : "/register";
    const data = await api(path, "POST", { username, password });
    localStorage.setItem("token", data.token);
    setToken(data.token);
    setUser(data.user);
    socket.auth = { token: data.token };
    socket.connect();
    socket.emit("join", data.user.id);
  }

  async function openChat(u) {
    setSelectedUser(u);
    const msgs = await api(`/messages/${u.id}`, "GET", null, token);
    setMessages(msgs);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    const data = await api(
      "/messages",
      "POST",
      { receiverId: selectedUser.id, content, isPremium },
      token
    );

    setMessages((prev) => [...prev, data.message]);
    setUser(data.sender);
    setContent("");
    setIsPremium(false);
  }

  async function buyCredits() {
    const amount = prompt("How many credits do you want to buy?", "5");
    if (!amount) return;
    const data = await api("/buy-credits", "POST", { amount: Number(amount) }, token);
    setUser(data.user);
  }

  if (!user) {
    return (
      <div style={{ padding: 20, fontFamily: "sans-serif" }}>
        <h1>Social Messaging App</h1>
        <div>
          <button onClick={() => setAuthMode("login")}>Login</button>
          <button onClick={() => setAuthMode("register")}>Register</button>
        </div>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <button onClick={handleAuth}>{authMode}</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <div style={{ width: 250, borderRight: "1px solid #ccc", padding: 12 }}>
        <h3>{user.username}</h3>
        <p>Credits: {user.credits}</p>
        <button onClick={buyCredits}>Buy Credits</button>
        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>
              {u.username} ({u.credits} cr)
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1, padding: 12 }}>
        <h2>{selectedUser ? `Chat with ${selectedUser.username}` : "Select a user"}</h2>

        <div style={{ marginBottom: 12 }}>
          <label>
            <input
              type="checkbox"
              checked={isPremium}
              onChange={(e) => setIsPremium(e.target.checked)}
            />
            Premium message (1 credit)
          </label>
        </div>

        <div style={{ border: "1px solid #ddd", height: 400, overflow: "auto", padding: 8 }}>
          {messages.map((m) => (
            <div
              key={m.id}
              style={{
                marginBottom: 8,
                padding: 8,
                background: m.isPremium ? "#fff3cd" : "#f5f5f5",
                borderRadius: 6
              }}
            >
              <b>{m.senderId === user.id ? "You" : selectedUser?.username}:</b> {m.content}
              {m.isPremium ? " ⭐" : ""}
            </div>
          ))}
        </div>

        <div style={{ marginTop: 12 }}>
          <input
            style={{ width: "70%" }}
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Type a message"
          />
          <button onClick={sendMessage}>Send</button>
        </div>

        <h3>Notifications</h3>
        <ul>
          {notifications.map((n, i) => (
            <li key={i}>{n.text}</li>
          ))}
        </ul>
      </div>
    </div>
  );
}
```

