import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import { Server } from "socket.io";
import Stripe from "stripe";
import { initDb, dbPromise } from "./db.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, methods: ["GET", "POST"] }
});

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

app.use(cors({ origin: process.env.CLIENT_URL }));
app.use(express.json());

await initDb();

app.post("/api/login", async (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "Username required" });

  const db = await dbPromise;
  let user = await db.get("SELECT * FROM users WHERE username = ?", username);

  if (!user) {
    await db.run("INSERT INTO users (username, credits, premium) VALUES (?, 0, 0)", username);
    user = await db.get("SELECT * FROM users WHERE username = ?", username);
  }

  res.json(user);
});

app.get("/api/messages/:room", async (req, res) => {
  const { room } = req.params;
  const db = await dbPromise;
  const messages = await db.all(
    "SELECT * FROM messages WHERE room = ? ORDER BY id ASC",
    room
  );
  res.json(messages);
});

app.post("/api/send", async (req, res) => {
  const { room, username, content, boosted } = req.body;
  if (!room || !username || !content) {
    return res.status(400).json({ error: "Missing fields" });
  }

  const db = await dbPromise;
  const user = await db.get("SELECT * FROM users WHERE username = ?", username);
  if (!user) return res.status(404).json({ error: "User not found" });

  let isBoosted = 0;
  if (boosted) {
    if (user.credits <= 0) return res.status(400).json({ error: "Not enough credits" });
    await db.run("UPDATE users SET credits = credits - 1 WHERE username = ?", username);
    isBoosted = 1;
  }

  const result = await db.run(
    "INSERT INTO messages (room, username, content, boosted) VALUES (?, ?, ?, ?)",
    room, username, content, isBoosted
  );

  const message = await db.get("SELECT * FROM messages WHERE id = ?", result.lastID);

  io.to(room).emit("message", message);
  io.to(room).emit("notification", {
    type: "message",
    text: `${username} sent a new message${isBoosted ? " (boosted)" : ""}`
  });

  res.json(message);
});

app.get("/api/user/:username", async (req, res) => {
  const db = await dbPromise;
  const user = await db.get("SELECT * FROM users WHERE username = ?", req.params.username);
  if (!user) return res.status(404).json({ error: "User not found" });
  res.json(user);
});

app.post("/api/create-checkout-session", async (req, res) => {
  const { username } = req.body;
  const db = await dbPromise;
  const user = await db.get("SELECT * FROM users WHERE username = ?", username);
  if (!user) return res.status(404).json({ error: "User not found" });

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    line_items: [
      {
        price: process.env.STRIPE_PRICE_ID,
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    metadata: { username }
  });

  res.json({ url: session.url });
});

app.post("/api/webhook/stripe", express.raw({ type: "application/json" }), async (req, res) => {
  // Minimal placeholder: in production verify Stripe signature here.
  res.sendStatus(200);
});

io.on("connection", (socket) => {
  socket.on("join", (room) => {
    socket.join(room);
  });
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
