import React, { useEffect, useState } from "react";
import axios from "axios";
import { io } from "socket.io-client";

const API = "http://localhost:4000";
const socket = io(API);

export default function App() {
  const [username, setUsername] = useState("");
  const [user, setUser] = useState(null);
  const [room, setRoom] = useState("general");
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [boosted, setBoosted] = useState(false);

  useEffect(() => {
    socket.on("message", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev].slice(0, 5));
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, []);

  const login = async () => {
    const res = await axios.post(`${API}/api/login`, { username });
    setUser(res.data);
    socket.emit("join", room);
    const msgs = await axios.get(`${API}/api/messages/${room}`);
    setMessages(msgs.data);
  };

  const sendMessage = async () => {
    await axios.post(`${API}/api/send`, {
      room,
      username: user.username,
      content,
      boosted
    });
    setContent("");
    setBoosted(false);
    const updated = await axios.get(`${API}/api/user/${user.username}`);
    setUser(updated.data);
  };

  const buyCredits = async () => {
    const res = await axios.post(`${API}/api/create-checkout-session`, {
      username: user.username
    });
    window.location.href = res.data.url;
  };

  if (!user) {
    return (
      <div className="container">
        <h1>Social Messaging App</h1>
        <input
          placeholder="Enter username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div className="container">
      <div className="topbar">
        <h2>Room: {room}</h2>
        <div>
          <span>@{user.username}</span>{" "}
          <span>Credits: {user.credits}</span>{" "}
          <span>{user.premium ? "Premium" : "Free"}</span>
        </div>
      </div>

      <div className="notifications">
        <h3>Notifications</h3>
        {notifications.map((n, i) => (
          <div key={i} className="notification">{n.text}</div>
        ))}
      </div>

      <div className="chat">
        {messages.map((m) => (
          <div key={m.id} className={`message ${m.boosted ? "boosted" : ""}`}>
            <strong>{m.username}:</strong> {m.content}
          </div>
        ))}
      </div>

      <div className="composer">
        <input
          placeholder="Type a message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <label>
          <input
            type="checkbox"
            checked={boosted}
            onChange={(e) => setBoosted(e.target.checked)}
          />
          Boosted message (1 credit)
        </label>
        <button onClick={sendMessage}>Send</button>
      </div>

      <div className="monetization">
        <button onClick={buyCredits}>Buy Credits</button>
      </div>
    </div>
  );
}
