import React, { useEffect, useState } from "react";
import { api, setAuthToken } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(JSON.parse(localStorage.getItem("user") || "null"));
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState("");
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;
    setAuthToken(token);
    socket.connect();
    socket.emit("auth", { userId: user.id });

    socket.on("new-message", (msg) => {
      if (selectedUser && (msg.senderId === selectedUser.id || msg.receiverId === selectedUser.id)) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    socket.on("online-users", () => {});

    return () => {
      socket.off("new-message");
      socket.off("notification");
      socket.off("online-users");
      socket.disconnect();
    };
  }, [token, user, selectedUser]);

  useEffect(() => {
    if (!token) return;
    (async () => {
      const res = await api.get("/users");
      setUsers(res.data);
      const n = await api.get("/notifications");
      setNotifications(n.data);
    })();
  }, [token]);

  useEffect(() => {
    if (!selectedUser) return;
    (async () => {
      const res = await api.get(`/messages/${selectedUser.id}`);
      setMessages(res.data);
    })();
  }, [selectedUser]);

  async function submitAuth(e) {
    e.preventDefault();
    const url = authMode === "login" ? "/login" : "/register";
    const res = await api.post(url, { username, password });
    localStorage.setItem("token", res.data.token);
    localStorage.setItem("user", JSON.stringify(res.data.user));
    setToken(res.data.token);
    setUser(res.data.user);
    setAuthToken(res.data.token);
  }

  function sendMessage() {
    if (!selectedUser || !message.trim()) return;
    socket.emit("send-message", {
      senderId: user.id,
      receiverId: selectedUser.id,
      content: message
    });
    setMessage("");
  }

