## `server/src/index.js`

```js
import "dotenv/config";
import express from "express";
import cors from "cors";
import bcrypt from "bcryptjs";
import http from "http";
import { Server } from "socket.io";
import { db, initDb } from "./db.js";
import { requireAuth, signToken } from "./auth.js";
import { setupSocket } from "./socket.js";
import { stripe } from "./stripe.js";

await initDb();

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

setupSocket(io, db);

// Auth
app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  const hash = await bcrypt.hash(password, 10);

  try {
    const result = await db.run(
      `INSERT INTO users (username, password_hash) VALUES (?, ?)`,
      [username, hash]
    );
    const user = { id: result.lastID, username };
    res.json({ token: signToken(user), user });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get(`SELECT * FROM users WHERE username = ?`, [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({
    token: signToken(user),
    user: { id: user.id, username: user.username, credits: user.credits }
  });
});

// Users
app.get("/api/users", requireAuth, async (req, res) => {
  const users = await db.all(`SELECT id, username, credits FROM users WHERE id != ?`, [
    req.user.id
  ]);
  res.json(users);
});

// Messages
app.get("/api/messages/:userId", requireAuth, async (req, res) => {
  const otherId = Number(req.params.userId);
  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (sender_id = ? AND receiver_id = ?)
        OR (sender_id = ? AND receiver_id = ?)
     ORDER BY created_at ASC`,
    [req.user.id, otherId, otherId, req.user.id]
  );
  res.json(messages);
});

// Notifications
app.get("/api/notifications", requireAuth, async (req, res) => {
  const notifications = await db.all(
    `SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC LIMIT 20`,
    [req.user.id]
  );
  res.json(notifications);
});

app.post("/api/notifications/read", requireAuth, async (req, res) => {
  await db.run(`UPDATE notifications SET read = 1 WHERE user_id = ?`, [req.user.id]);
  res.json({ ok: true });
});

// Stripe checkout
app.post("/api/create-checkout-session", requireAuth, async (req, res) => {
  const { credits } = req.body; // e.g. 100 credits
  const amount = credits; // 1 credit = $1 for demo

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${credits} Credits` },
          unit_amount: amount * 100
        },
        quantity: 1
      }
    ],
    metadata: {
      userId: String(req.user.id),
      credits: String(credits)
    }
  });

  await db.run(
    `INSERT INTO payments (user_id, stripe_session_id, amount, credits, status) VALUES (?, ?, ?, ?, ?)`,
    [req.user.id, session.id, amount, credits, "pending"]
  );

  res.json({ url: session.url });
});

// Stripe webhook
app.post(
  "/api/stripe-webhook",
  express.raw({ type: "application/json" }),
  async (req, res) => {
    let event;
    try {
      event = stripe.webhooks.constructEvent(
        req.body,
        req.headers["stripe-signature"],
        process.env.STRIPE_WEBHOOK_SECRET
      );
    } catch (err) {
      return res.status(400).send(`Webhook Error: ${err.message}`);
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      const userId = Number(session.metadata.userId);
      const credits = Number(session.metadata.credits);

      await db.run(`UPDATE users SET credits = credits + ? WHERE id = ?`, [
        credits,
        userId
      ]);

      await db.run(`UPDATE payments SET status = 'paid' WHERE stripe_session_id = ?`, [
        session.id
      ]);

      await db.run(
        `INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)`,
        [userId, "payment", `Payment successful: +${credits} credits`]
      );

      io.to(`user:${userId}`).emit("notification", {
        type: "payment",
        content: `Payment successful: +${credits} credits`
      });
    }

    res.json({ received: true });
  }
);

app.get("/api/me", requireAuth, async (req, res) => {
  const user = await db.get(`SELECT id, username, credits FROM users WHERE id = ?`, [
    req.user.id
  ]);
  res.json(user);
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => console.log(`Server running on ${PORT}`));
```

