```jsx
import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";
import { api } from "./api";

const socket = io("http://localhost:4000");

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;
    api("/me", "GET", null, token).then(setUser);
    api("/users", "GET", null, token).then(setUsers);
    api("/notifications", "GET", null, token).then(setNotifications);
  }, [token]);

  useEffect(() => {
    if (!user) return;
    socket.emit("join", user.id);

    socket.on("new_message", (msg) => {
      if (selectedUser && (msg.senderId === selectedUser.id || msg.receiverId === selectedUser.id)) {
        setMessages((m) => [...m, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [{ id: Date.now(), ...n }, ...prev]);
    });

    return () => {
      socket.off("new_message");
      socket.off("notification");
    };
  }, [user, selectedUser]);

  async function handleAuth() {
    const path = authMode === "login" ? "/login" : "/register";
    const data = await api(path, "POST", { username, password });
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    }
  }

  async function openChat(u) {
    setSelectedUser(u);
    const msgs = await api(`/messages/${u.id}`, "GET", null, token);
    setMessages(msgs);
  }

  function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    socket.emit("send_message", {
      senderId: user.id,
      receiverId: selectedUser.id,
      content
    });
    setContent("");
  }

  async function buyCredits() {
    const data = await api("/create-checkout-session", "POST", { credits: 10 }, token);
    window.location.href = data.url;
  }

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h2>{authMode === "login" ? "Login" : "Register"}</h2>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <br />
        <input
          placeholder="password"
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
        />
        <br />
        <button onClick={handleAuth}>{authMode}</button>
        <button onClick={() => setAuthMode(authMode === "login" ? "register" : "login")}>
          switch
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "grid", gridTemplateColumns: "250px 1fr 300px", height: "100vh" }}>
      <aside style={{ borderRight: "1px solid #ddd", padding: 12 }}>
        <h3>{user?.username}</h3>
        <p>Credits: {user?.credits ?? 0}</p>
        <button onClick={buyCredits}>Buy 10 Credits</button>
        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>{u.username}</button>
          </div>
        ))}
      </aside>

      <main style={{ padding: 12 }}>
        <h3>Chat {selectedUser ? `with ${selectedUser.username}` : ""}</h3>
        <div style={{ height: "70vh", overflow: "auto", border: "1px solid #ddd", padding: 8 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.sender_id === user.id ? "You" : selectedUser?.username}:</b> {m.content}
            </div>
          ))}
        </div>
        <div style={{ marginTop: 8 }}>
          <input value={content} onChange={(e) => setContent(e.target.value)} placeholder="Type a message" />
          <button onClick={sendMessage}>Send</button>
        </div>
      </main>

      <aside style={{ borderLeft: "1px solid #ddd", padding: 12 }}>
        <h4>Notifications</h4>
        {notifications.map((n) => (
          <div key={n.id} style={{ marginBottom: 8 }}>
            <small>{n.type}</small>
            <div>{n.content}</div>
          </div>
        ))}
      </aside>
    </div>
  );
}
