# 7) Payments / monetization

This MVP uses Stripe Checkout to buy credits.

## `server/src/routes/paymentRoutes.js`

```js
import express from "express";
import Stripe from "stripe";
import User from "../models/User.js";

const router = express.Router();
const stripe = new Stripe(process.env.STRIPE_SECRET_KEY);

router.post("/buy-credits", async (req, res) => {
  try {
    const { userId, credits } = req.body;

    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      payment_method_types: ["card"],
      line_items: [
        {
          price_data: {
            currency: "usd",
            product_data: { name: `${credits} Credits` },
            unit_amount: credits * 100
          },
          quantity: 1
        }
      ],
      success_url: `${process.env.CLIENT_URL}/success?userId=${userId}&credits=${credits}`,
      cancel_url: `${process.env.CLIENT_URL}/cancel`
    });

    res.json({ url: session.url });
  } catch (err) {
    res.status(500).json({ error: "Payment session failed" });
  }
});

router.post("/confirm-credits", async (req, res) => {
  try {
    const { userId, credits } = req.body;
    await User.findByIdAndUpdate(userId, { $inc: { credits } });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: "Could not add credits" });
  }
});

export default router;
```

> Note: In production, credit confirmation should be done via **Stripe webhooks**, not a client-side call.

