# 8) Socket real-time notifications

## `server/src/sockets/index.js`

```js
import Message from "../models/Message.js";
import User from "../models/User.js";

export function registerSocketHandlers(io) {
  io.on("connection", (socket) => {
    console.log("User connected:", socket.id);

    socket.on("joinRoom", (roomId) => {
      socket.join(roomId);
    });

    socket.on("sendMessage", async ({ roomId, senderId, content, isPremium }) => {
      try {
        const user = await User.findById(senderId);
        if (!user) return;

        if (isPremium) {
          if (user.credits < 1) {
            socket.emit("notification", {
              type: "error",
              message: "Not enough credits for premium message"
            });
            return;
          }
          user.credits -= 1;
          await user.save();
        }

        const message = await Message.create({
          roomId,
          sender: senderId,
          content,
          isPremium
        });

        const populated = await message.populate("sender", "username");

        io.to(roomId).emit("newMessage", populated);

        io.to(roomId).emit("notification", {
          type: "message",
          message: isPremium
            ? "A premium message was sent"
            : "New message received"
        });
      } catch (err) {
        socket.emit("notification", {
          type: "error",
          message: "Failed to send message"
        });
      }
    });

    socket.on("disconnect", () => {
      console.log("User disconnected:", socket.id);
    });
  });
}
```

