import { useEffect, useState } from "react";
import axios from "axios";
import { socket } from "./services/socket";

const API = import.meta.env.VITE_API_URL;

export default function App() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [user, setUser] = useState(null);
  const [roomId, setRoomId] = useState("general");
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notification, setNotification] = useState("");

  useEffect(() => {
    socket.on("newMessage", (msg) => {
      setMessages((prev) => [...prev, msg]);
    });

    socket.on("notification", (n) => {
      setNotification(n.message);
      setTimeout(() => setNotification(""), 3000);
    });

    return () => {
      socket.off("newMessage");
      socket.off("notification");
    };
  }, []);

  const register = async () => {
    await axios.post(`${API}/api/auth/register`, { username, password });
    alert("Registered");
  };

  const login = async () => {
    const res = await axios.post(`${API}/api/auth/login`, { username, password });
    setUser(res.data.user);
    socket.emit("joinRoom", roomId);

    const msgs = await axios.get(`${API}/api/chat/${roomId}`);
    setMessages(msgs.data);
  };

  const sendMessage = () => {
    socket.emit("sendMessage", {
      roomId,
      senderId: user.id,
      content,
      isPremium: false
    });
    setContent("");
  };

  const sendPremiumMessage = () => {
    socket.emit("sendMessage", {
      roomId,
      senderId: user.id,
      content,
      isPremium: true
    });
    setContent("");
  };

  const buyCredits = async () => {
    const res = await axios.post(`${API}/api/payments/buy-credits`, {
      userId: user.id,
      credits: 10
    });
    window.location.href = res.data.url;
  };

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Social Messaging App</h2>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <br />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <br />
        <button onClick={register}>Register</button>
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ padding: 20 }}>
      <h2>Welcome, {user.username}</h2>
      <p>Credits: {user.credits}</p>
      <button onClick={buyCredits}>Buy 10 Credits</button>

      <h3>Room: {roomId}</h3>
      <div style={{ border: "1px solid #ccc", height: 300, overflowY: "auto", padding: 10 }}>
        {messages.map((m) => (
          <div key={m._id}>
            <b>{m.sender?.username || "Unknown"}:</b> {m.content} {m.isPremium ? "⭐" : ""}
          </div>
        ))}
      </div>

      <p style={{ color: "green" }}>{notification}</p>

      <input value={content} onChange={(e) => setContent(e.target.value)} placeholder="Type a message" />
      <button onClick={sendMessage}>Send</button>
      <button onClick={sendPremiumMessage}>Send Premium</button>
    </div>
  );
}
