## Messages route with real-time notification

### `server/src/routes/messages.ts`

```ts
import { Router } from "express";
import { authMiddleware } from "../auth";

const router = Router();

router.post("/", authMiddleware, async (req: any, res) => {
  const { receiverId, content } = req.body;
  const prisma = req.prisma;
  const io = req.io;
  const senderId = req.userId;

  const sender = await prisma.user.findUnique({ where: { id: senderId } });
  if (!sender) return res.status(404).json({ error: "Sender not found" });

  // Monetization: 1 credit per message unless premium
  if (!sender.premium) {
    if (sender.credits <= 0) {
      return res.status(402).json({ error: "Not enough credits" });
    }
    await prisma.user.update({
      where: { id: senderId },
      data: { credits: { decrement: 1 } }
    });
  }

  const message = await prisma.message.create({
    data: { senderId, receiverId, content }
  });

  const notification = await prisma.notification.create({
    data: {
      userId: receiverId,
      type: "message",
      text: `New message from ${sender.name}`
    }
  });

  io.to(receiverId).emit("new_message", message);
  io.to(receiverId).emit("new_notification", notification);

  res.json({ message });
});

router.get("/:userId", authMiddleware, async (req: any, res) => {
  const prisma = req.prisma;
  const userId = req.params.userId;
  const me = req.userId;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me, receiverId: userId },
        { senderId: userId, receiverId: me }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json({ messages });
});

export default router;
```

