  apiVersion: "2024-06-20"
});

router.post("/checkout", authMiddleware, async (req: any, res) => {
  const { pack } = req.body; // "small" | "premium"
  const userId = req.userId;

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: `${process.env.CLIENT_URL}/billing?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/billing?canceled=1`,
    metadata: { userId, pack },
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: {
            name: pack === "premium" ? "Premium Unlock" : "Credits Pack"
          },
          unit_amount: pack === "premium" ? 999 : 499
        },
        quantity: 1
      }
    ]
  });

  res.json({ url: session.url });
});

router.post("/webhook", express.raw({ type: "application/json" }), async (req: any, res) => {
  // For minimal version, implement webhook verification in production.
  res.sendStatus(200);
});

export default router;
