"use client";

import { useEffect, useState } from "react";
import { api } from "@/lib/api";
import { createSocket } from "@/lib/socket";

export default function ChatPage() {
  const [token, setToken] = useState("");
  const [me, setMe] = useState<any>(null);
  const [receiverId, setReceiverId] = useState("");
  const [content, setContent] = useState("");
  const [messages, setMessages] = useState<any[]>([]);
  const [notifications, setNotifications] = useState<any[]>([]);

  useEffect(() => {
    const t = localStorage.getItem("token") || "";
    const u = JSON.parse(localStorage.getItem("user") || "null");
    setToken(t);
    setMe(u);

    if (!t) return;

    const socket = createSocket(t);
    socket.on("new_message", (msg) => setMessages((prev) => [...prev, msg]));
    socket.on("new_notification", (n) => setNotifications((prev) => [n, ...prev]));

    return () => socket.disconnect();
  }, []);

  const loadConversation = async () => {
    const data = await api(`/messages/${receiverId}`, "GET", undefined, token);
    setMessages(data.messages || []);
  };

  const send = async () => {
    const data = await api("/messages", "POST", { receiverId, content }, token);
    if (data.error) alert(data.error);
    else setContent("");
  };

  const loadNotifications = async () => {
    const data = await api("/notifications", "GET", undefined, token);
    setNotifications(data.notifications || []);
  };

  if (!me) return <div>Loading...</div>;

  return (
    <div style={{ padding: 24 }}>
      <h1>Chat</h1>
      <p>Logged in as: {me.name}</p>
      <p>Credits: {me.credits ?? 0} | Premium: {String(me.premium)}</p>

      <div>
        <input
          placeholder="Receiver User ID"
          value={receiverId}
          onChange={(e) => setReceiverId(e.target.value)}
