      </div>

      <div style={{ marginTop: 16 }}>
        <input
          placeholder="Message"
          value={content}
          onChange={(e) => setContent(e.target.value)}
        />
        <button onClick={send}>Send</button>
      </div>

      <h2>Messages</h2>
      <div>
        {messages.map((m) => (
          <div key={m.id}>
            <b>{m.senderId === me.id ? "Me" : "Them"}:</b> {m.content}
          </div>
        ))}
      </div>

      <h2>Notifications</h2>
      <button onClick={loadNotifications}>Refresh Notifications</button>
      <div>
        {notifications.map((n) => (
          <div key={n.id}>
            {n.read ? "✓" : "•"} {n.text}
          </div>
        ))}
      </div>

