## `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import jwt from "jsonwebtoken";
import { Server } from "socket.io";
import db from "./db.js";

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "http://localhost:5173", credentials: true }
});

const PORT = 3001;
const JWT_SECRET = "dev_secret_change_me";

app.use(cors({ origin: "http://localhost:5173", credentials: true }));
app.use(express.json());

const onlineUsers = new Map(); // userId -> socketId

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) return res.status(401).json({ error: "No token" });

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

app.post("/register", (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  try {
    const stmt = db.prepare("INSERT INTO users (username, password) VALUES (?, ?)");
    const info = stmt.run(username, password);
    const token = jwt.sign({ id: info.lastInsertRowid, username }, JWT_SECRET);
    res.json({ token, user: { id: info.lastInsertRowid, username, credits: 0 } });
  } catch (e) {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/login", (req, res) => {
  const { username, password } = req.body;
  const user = db.prepare("SELECT * FROM users WHERE username = ? AND password = ?").get(username, password);
  if (!user) return res.status(401).json({ error: "Invalid credentials" });

  const token = jwt.sign({ id: user.id, username: user.username }, JWT_SECRET);
  res.json({ token, user: { id: user.id, username: user.username, credits: user.credits } });
});

app.get("/me", authMiddleware, (req, res) => {
  const user = db.prepare("SELECT id, username, credits FROM users WHERE id = ?").get(req.user.id);
  res.json({ user });
});

app.get("/users", authMiddleware, (req, res) => {
  const users = db.prepare("SELECT id, username, credits FROM users WHERE id != ?").all(req.user.id);
  res.json({ users });
});

app.get("/messages/:userId", authMiddleware, (req, res) => {
  const otherId = Number(req.params.userId);
  const myId = req.user.id;

  const messages = db.prepare(`
    SELECT * FROM messages
    WHERE (senderId = ? AND receiverId = ?)
       OR (senderId = ? AND receiverId = ?)
    ORDER BY createdAt ASC
  `).all(myId, otherId, otherId, myId);

  res.json({ messages });
});

app.post("/buy-credits", authMiddleware, (req, res) => {
  const { amount } = req.body;
  const creditsToAdd = Number(amount || 0);

  if (creditsToAdd <= 0) return res.status(400).json({ error: "Invalid amount" });

  db.prepare("UPDATE users SET credits = credits + ? WHERE id = ?").run(creditsToAdd, req.user.id);
  const user = db.prepare("SELECT id, username, credits FROM users WHERE id = ?").get(req.user.id);

  res.json({ user });
});

app.post("/send-message", authMiddleware, (req, res) => {
  const { receiverId, content, isPremium } = req.body;
  const senderId = req.user.id;
  const premium = isPremium ? 1 : 0;

  if (!receiverId || !content) return res.status(400).json({ error: "Missing fields" });

  const sender = db.prepare("SELECT * FROM users WHERE id = ?").get(senderId);
  if (!sender) return res.status(404).json({ error: "Sender not found" });

  if (premium) {
    const cost = 1;
    if (sender.credits < cost) return res.status(400).json({ error: "Not enough credits" });
    db.prepare("UPDATE users SET credits = credits - ? WHERE id = ?").run(cost, senderId);
  }

  const info = db.prepare(`
    INSERT INTO messages (senderId, receiverId, content, isPremium)
    VALUES (?, ?, ?, ?)
  `).run(senderId, receiverId, content, premium);

  const message = db.prepare("SELECT * FROM messages WHERE id = ?").get(info.lastInsertRowid);
  const receiver = db.prepare("SELECT id, username, credits FROM users WHERE id = ?").get(receiverId);
  const updatedSender = db.prepare("SELECT id, username, credits FROM users WHERE id = ?").get(senderId);

  // Real-time delivery
  const receiverSocketId = onlineUsers.get(Number(receiverId));
  if (receiverSocketId) {
    io.to(receiverSocketId).emit("new-message", { message });
    io.to(receiverSocketId).emit("notification", {
      type: "message",
      text: `New ${premium ? "premium " : ""}message from ${sender.username}`
    });
  }

  res.json({ message, sender: updatedSender, receiver });
});

io.on("connection", (socket) => {
  socket.on("register-user", (userId) => {
    onlineUsers.set(Number(userId), socket.id);
    io.emit("presence-update", { userId: Number(userId), online: true });
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) {
        onlineUsers.delete(userId);
        io.emit("presence-update", { userId, online: false });
        break;
      }
    }
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

