import React, { useEffect, useState } from "react";
import { request } from "./api";
import { socket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authMode, setAuthMode] = useState("login");
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [premium, setPremium] = useState(false);
  const [buyAmount, setBuyAmount] = useState(10);

  useEffect(() => {
    if (!token) return;

    request("/me", "GET", null, token).then(({ user }) => {
      setUser(user);
      socket.auth = { token };
      socket.connect();
      socket.emit("register-user", user.id);
    });

    request("/users", "GET", null, token).then(({ users }) => setUsers(users));

    socket.on("new-message", ({ message }) => {
      if (selectedUser && message.senderId === selectedUser.id) {
        setMessages((prev) => [...prev, message]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    socket.on("presence-update", ({ userId, online }) => {
      setUsers((prev) =>
        prev.map((u) => (u.id === userId ? { ...u, online } : u))
      );
    });

    return () => {
      socket.off("new-message");
      socket.off("notification");
      socket.off("presence-update");
      socket.disconnect();
    };
  }, [token, selectedUser]);

  async function handleAuth() {
    const path = authMode === "login" ? "/login" : "/register";
    const data = await request(path, "POST", { username, password });
    localStorage.setItem("token", data.token);
    setToken(data.token);
    setUser(data.user);
  }

  async function openChat(u) {
    setSelectedUser(u);
    const { messages } = await request(`/messages/${u.id}`, "GET", null, token);
    setMessages(messages);
  }

  async function sendMessage() {
    if (!selectedUser || !content.trim()) return;
    const { message, sender } = await request(
      "/send-message",
      "POST",
      { receiverId: selectedUser.id, content, isPremium: premium },
      token
    );
    setMessages((prev) => [...prev, message]);
    setContent("");
    setUser(sender);
  }

  async function buyCredits() {
    const { user: updated } = await request(
      "/buy-credits",
      "POST",
      { amount: buyAmount },
      token
    );
    setUser(updated);
  }

  if (!user) {
    return (
      <div style={{ padding: 20, fontFamily: "sans-serif" }}>
        <h2>{authMode === "login" ? "Login" : "Register"}</h2>
        <input placeholder="username" value={username} onChange={(e) => setUsername(e.target.value)} />
        <br />
        <input placeholder="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
        <br />
        <button onClick={handleAuth}>{authMode}</button>
        <button onClick={() => setAuthMode(authMode === "login" ? "register" : "login")}>
          Switch to {authMode === "login" ? "register" : "login"}
        </button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", fontFamily: "sans-serif", height: "100vh" }}>
      <div style={{ width: 260, borderRight: "1px solid #ddd", padding: 16 }}>
        <h3>{user.username}</h3>
        <p>Credits: {user.credits}</p>

        <div>
          <input
            type="number"
            value={buyAmount}
            onChange={(e) => setBuyAmount(Number(e.target.value))}
            style={{ width: 80 }}
          />
          <button onClick={buyCredits}>Buy Credits</button>
        </div>

        <h4>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>
              {u.username} {u.online ? "🟢" : "⚪"}
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1, padding: 16 }}>
        {selectedUser ? (
          <>
            <h3>Chat with {selectedUser.username}</h3>
            <div style={{ height: 300, overflowY: "auto", border: "1px solid #ddd", padding: 8 }}>
              {messages.map((m) => (
                <div key={m.id}>
                  <b>{m.senderId === user.id ? "You" : selectedUser.username}:</b> {m.content}
                  {m.isPremium ? " ⭐" : ""}
                </div>
              ))}
            </div>

            <div style={{ marginTop: 12 }}>
              <input
                value={content}
                onChange={(e) => setContent(e.target.value)}
                placeholder="Type a message"
                style={{ width: 300 }}
              />
              <label style={{ marginLeft: 8 }}>
                <input
                  type="checkbox"
                  checked={premium}
                  onChange={(e) => setPremium(e.target.checked)}
                />
                Premium message (costs 1 credit)
              </label>
              <button onClick={sendMessage}>Send</button>
            </div>
          </>
        ) : (
          <p>Select a user to start chatting.</p>
        )}

        <h4>Notifications</h4>
        <div style={{ border: "1px solid #ddd", padding: 8, maxHeight: 150, overflowY: "auto" }}>
          {notifications.map((n, i) => (
            <div key={i}>{n.text}</div>
          ))}
        </div>
      </div>
    </div>
  );
}
