```js
import sqlite3 from "sqlite3";

const db = new sqlite3.Database("./app.db");

export function initDb() {
  db.serialize(() => {
    db.run(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        credits INTEGER NOT NULL DEFAULT 0
      )
    `);

    db.run(`
      CREATE TABLE IF NOT EXISTS messages (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        senderId INTEGER NOT NULL,
        receiverId INTEGER NOT NULL,
        content TEXT NOT NULL,
        isPremium INTEGER NOT NULL DEFAULT 0,
        createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);

    db.run(`
      CREATE TABLE IF NOT EXISTS notifications (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        userId INTEGER NOT NULL,
        type TEXT NOT NULL,
        content TEXT NOT NULL,
        read INTEGER NOT NULL DEFAULT 0,
        createdAt DATETIME DEFAULT CURRENT_TIMESTAMP
      )
    `);
  });
}

export function all(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.all(sql, params, (err, rows) => (err ? reject(err) : resolve(rows)));
  });
}

export function get(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.get(sql, params, (err, row) => (err ? reject(err) : resolve(row)));
  });
}

export function run(sql, params = []) {
  return new Promise((resolve, reject) => {
    db.run(sql, params, function (err) {
      if (err) reject(err);
      else resolve({ id: this.lastID, changes: this.changes });
    });
  });
}
```

## `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { initDb, all, get, run } from "./db.js";

initDb();

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const PORT = 3001;

// --- Helpers ---
async function createNotification(userId, type, content) {
  const result = await run(
    `INSERT INTO notifications (userId, type, content, read) VALUES (?, ?, ?, 0)`,
    [userId, type, content]
  );

  const notification = await get(`SELECT * FROM notifications WHERE id = ?`, [result.id]);
  io.to(`user:${userId}`).emit("notification", notification);
  return notification;
}

// --- Seed users if empty ---
async function seedUsers() {
  const users = await all(`SELECT * FROM users`);
  if (users.length === 0) {
    await run(`INSERT INTO users (name, credits) VALUES (?, ?)`, ["Alice", 10]);
    await run(`INSERT INTO users (name, credits) VALUES (?, ?)`, ["Bob", 5]);
    await run(`INSERT INTO users (name, credits) VALUES (?, ?)`, ["Charlie", 0]);
  }
}
await seedUsers();

// --- REST API ---
app.get("/users", async (req, res) => {
  const users = await all(`SELECT * FROM users`);
  res.json(users);
});

app.get("/messages/:userId", async (req, res) => {
  const userId = Number(req.params.userId);
  const messages = await all(
    `SELECT * FROM messages WHERE senderId = ? OR receiverId = ? ORDER BY createdAt ASC`,
    [userId, userId]
  );
  res.json(messages);
});

app.get("/notifications/:userId", async (req, res) => {
  const userId = Number(req.params.userId);
  const notifications = await all(
    `SELECT * FROM notifications WHERE userId = ? ORDER BY createdAt DESC`,
    [userId]
  );
  res.json(notifications);
});

app.post("/buy-credits", async (req, res) => {
  const { userId, amount } = req.body;
  const creditsToAdd = Number(amount || 0);

  if (creditsToAdd <= 0) {
    return res.status(400).json({ error: "Invalid amount" });
  }

  await run(`UPDATE users SET credits = credits + ? WHERE id = ?`, [creditsToAdd, userId]);
  const user = await get(`SELECT * FROM users WHERE id = ?`, [userId]);

  await createNotification(userId, "monetization", `You purchased ${creditsToAdd} credits.`);
  res.json(user);
});

app.post("/send-message", async (req, res) => {
  const { senderId, receiverId, content, isPremium } = req.body;

  if (!senderId || !receiverId || !content) {
    return res.status(400).json({ error: "Missing fields" });
  }

  const sender = await get(`SELECT * FROM users WHERE id = ?`, [senderId]);
  if (!sender) return res.status(404).json({ error: "Sender not found" });

  let premium = Number(isPremium || 0);

  // Monetization: premium messages cost 1 credit
  if (premium) {
    if (sender.credits < 1) {
      return res.status(402).json({ error: "Not enough credits for premium message" });
    }
    await run(`UPDATE users SET credits = credits - 1 WHERE id = ?`, [senderId]);
  }

  const result = await run(
    `INSERT INTO messages (senderId, receiverId, content, isPremium) VALUES (?, ?, ?, ?)`,
    [senderId, receiverId, content, premium]
  );

  const message = await get(`SELECT * FROM messages WHERE id = ?`, [result.id]);

  // Real-time message to receiver
  io.to(`user:${receiverId}`).emit("message", message);

  // Real-time notification to receiver
  await createNotification(
    receiverId,
    "message",
    `${sender.name} sent you ${premium ? "a premium message" : "a message"}`
  );

  res.json(message);
});

// --- Socket.IO ---
io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    socket.join(`user:${userId}`);
  });
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
