import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:3001";

export default function App() {
  const [users, setUsers] = useState([]);
  const [currentUser, setCurrentUser] = useState(null);
  const [receiverId, setReceiverId] = useState("");
  const [content, setContent] = useState("");
  const [isPremium, setIsPremium] = useState(false);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => io(API), []);

  useEffect(() => {
    fetch(`${API}/users`)
      .then((r) => r.json())
      .then(setUsers);
  }, []);

  useEffect(() => {
    if (!currentUser) return;

    socket.emit("join", currentUser.id);

    fetch(`${API}/messages/${currentUser.id}`)
      .then((r) => r.json())
      .then(setMessages);

    fetch(`${API}/notifications/${currentUser.id}`)
      .then((r) => r.json())
      .then(setNotifications);
  }, [currentUser, socket]);

  useEffect(() => {
    socket.on("message", (msg) => {
      if (currentUser && (msg.senderId === currentUser.id || msg.receiverId === currentUser.id)) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (notif) => {
      if (currentUser && notif.userId === currentUser.id) {
        setNotifications((prev) => [notif, ...prev]);
      }
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, [socket, currentUser]);

  async function buyCredits() {
    const amount = prompt("How many credits to buy?");
    if (!amount) return;

    const res = await fetch(`${API}/buy-credits`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ userId: currentUser.id, amount: Number(amount) })
    });

    const data = await res.json();
    if (res.ok) setCurrentUser(data);
    else alert(data.error);
  }

  async function sendMessage() {
    const res = await fetch(`${API}/send-message`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        senderId: currentUser.id,
        receiverId: Number(receiverId),
        content,
        isPremium
      })
    });

    const data = await res.json();
    if (res.ok) {
      setMessages((prev) => [...prev, data]);
      setContent("");
    } else {
      alert(data.error);
    }
  }

  if (!currentUser) {
    return (
      <div className="container">
        <h1>Social Messaging App</h1>
        <p>Select a user:</p>
        <div className="user-list">
          {users.map((u) => (
            <button key={u.id} onClick={() => setCurrentUser(u)}>
              {u.name} (credits: {u.credits})
            </button>
          ))}
        </div>
      </div>
    );
  }

  const otherUsers = users.filter((u) => u.id !== currentUser.id);

  return (
    <div className="container">
      <header className="topbar">
        <div>
          Logged in as <strong>{currentUser.name}</strong> — Credits: {currentUser.credits}
        </div>
        <div>
          <button onClick={buyCredits}>Buy Credits</button>
          <button onClick={() => setCurrentUser(null)}>Switch User</button>
        </div>
      </header>

      <div className="grid">
        <section className="panel">
          <h2>Send Message</h2>

          <label>
            To:
            <select value={receiverId} onChange={(e) => setReceiverId(e.target.value)}>
              <option value="">Select user</option>
              {otherUsers.map((u) => (
                <option key={u.id} value={u.id}>
                  {u.name}
                </option>
              ))}
            </select>
          </label>

          <label>
            Message:
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Type your message..."
            />
          </label>

          <label className="checkbox">
            <input
              type="checkbox"
              checked={isPremium}
              onChange={(e) => setIsPremium(e.target.checked)}
            />
            Premium message (costs 1 credit)
          </label>

          <button onClick={sendMessage}>Send</button>
        </section>

        <section className="panel">
          <h2>Messages</h2>
          <div className="list">
            {messages.map((m) => (
              <div key={m.id} className={`item ${m.isPremium ? "premium" : ""}`}>
                <div>
                  <strong>From:</strong> {m.senderId} <strong>To:</strong> {m.receiverId}
                </div>
                <div>{m.content}</div>
                {m.isPremium ? <small>Premium</small> : null}
              </div>
            ))}
          </div>
        </section>

        <section className="panel">
          <h2>Notifications</h2>
          <div className="list">
            {notifications.map((n) => (
              <div key={n.id} className="item">
                <div>{n.content}</div>
                <small>{n.type}</small>
              </div>
            ))}
          </div>
        </section>
      </div>
    </div>
  );
}
