## `server/src/socket.js`

```js
import { Server } from "socket.io";

export function initSocket(server, prisma) {
  const io = new Server(server, {
    cors: {
      origin: process.env.CLIENT_URL,
      credentials: true
    }
  });

  io.on("connection", (socket) => {
    socket.on("join", (userId) => {
      socket.join(userId);
    });

    socket.on("sendMessage", async ({ senderId, receiverId, content }) => {
      const message = await prisma.message.create({
        data: { senderId, receiverId, content }
      });

      const notification = await prisma.notification.create({
        data: {
          userId: receiverId,
          type: "message",
          content: `New message from ${senderId}`
        }
      });

      io.to(receiverId).emit("newMessage", message);
      io.to(receiverId).emit("newNotification", notification);
    });

    socket.on("tipUser", async ({ fromId, toId, amount }) => {
      const fromUser = await prisma.user.findUnique({ where: { id: fromId } });
      const toUser = await prisma.user.findUnique({ where: { id: toId } });

      if (!fromUser || !toUser) return;

      if (fromUser.coins < amount) {
        socket.emit("errorMessage", "Not enough coins");
        return;
      }

      await prisma.user.update({
        where: { id: fromId },
        data: { coins: { decrement: amount } }
      });

      await prisma.user.update({
        where: { id: toId },
        data: { coins: { increment: amount } }
      });

      const tip = await prisma.tip.create({
        data: { fromId, toId, amount }
      });

      const notification = await prisma.notification.create({
        data: {
          userId: toId,
          type: "tip",
          content: `You received a tip of ${amount} coins`
        }
      });

      io.to(toId).emit("newNotification", notification);
      io.to(toId).emit("tipReceived", tip);
    });
  });

  return io;
}
```

