  const hashed = await bcrypt.hash(password, 10);

  const user = await prisma.user.create({
    data: { email, password: hashed, name }
  });

  res.json({ token: signToken(user), user });
});

app.post("/auth/login", async (req, res) => {
  const { email, password } = req.body;
  const user = await prisma.user.findUnique({ where: { email } });

  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({ token: signToken(user), user });
});

app.get("/users", authMiddleware, async (_, res) => {
  const users = await prisma.user.findMany({
    select: { id: true, name: true, email: true, coins: true }
  });
  res.json(users);
});

app.get("/messages/:userId/:otherId", authMiddleware, async (req, res) => {
  const { userId, otherId } = req.params;

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: userId, receiverId: otherId },
        { senderId: otherId, receiverId: userId }
      ]
    },
    orderBy: { createdAt: "asc" }
  });

  res.json(messages);
});

app.get("/notifications/:userId", authMiddleware, async (req, res) => {
  const notifications = await prisma.notification.findMany({
    where: { userId: req.params.userId },
    orderBy: { createdAt: "desc" }
  });
  res.json(notifications);
});

app.post("/stripe/create-checkout-session", authMiddleware, async (req, res) => {
  const { userId, pack } = req.body;

  const packs = {
    small: { coins: 100, price: 499 },
    medium: { coins: 300, price: 999 },
    large: { coins: 1000, price: 2499 }
  };

  const selected = packs[pack];
  if (!selected) return res.status(400).json({ error: "Invalid pack" });

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    payment_method_types: ["card"],
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${selected.coins} Coins Pack` },
          unit_amount: selected.price
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    metadata: { userId, coins: String(selected.coins) }
  });

  res.json({ url: session.url });
});

app.post("/stripe/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  // Minimal version: in production verify signature properly.
  res.sendStatus(200);
});

app.post("/coins/grant", authMiddleware, async (req, res) => {
  const { userId, coins } = req.body;

  const user = await prisma.user.update({
    where: { id: userId },
    data: { coins: { increment: coins } }
  });

  const notification = await prisma.notification.create({
    data: {
      userId,
      type: "purchase",
      content: `You received ${coins} coins`
    }
  });

  io.to(userId).emit("newNotification", notification);
  res.json(user);
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
