## `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import { Server } from "socket.io";
import { initDb } from "./db.js";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const JWT_SECRET = "dev_secret_change_me";
const PORT = 4000;

const db = await initDb();

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(" ")[1];
  if (!token) return res.status(401).json({ error: "No token" });

  try {
    req.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    return res.status(401).json({ error: "Invalid token" });
  }
}

function emitNotification(userId, notification) {
  io.to(`user:${userId}`).emit("notification", notification);
}

function emitMessage(userId, message) {
  io.to(`user:${userId}`).emit("message", message);
}

/* ---------------- AUTH ---------------- */

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  if (!username || !password) return res.status(400).json({ error: "Missing fields" });

  const hashed = await bcrypt.hash(password, 10);

  try {
    const result = await db.run(
      "INSERT INTO users (username, password) VALUES (?, ?)",
      [username, hashed]
    );

    const token = jwt.sign({ id: result.lastID, username }, JWT_SECRET);
    res.json({ token, user: { id: result.lastID, username, credits: 10 } });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  const token = jwt.sign({ id: user.id, username: user.username }, JWT_SECRET);
  res.json({
    token,
    user: { id: user.id, username: user.username, credits: user.credits }
  });
});

/* ---------------- USERS ---------------- */

app.get("/api/me", authMiddleware, async (req, res) => {
  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

app.get("/api/users", authMiddleware, async (req, res) => {
  const users = await db.all("SELECT id, username FROM users WHERE id != ?", [req.user.id]);
  res.json(users);
});

/* ---------------- MESSAGES ---------------- */

app.get("/api/messages/:userId", authMiddleware, async (req, res) => {
  const otherId = Number(req.params.userId);
  const myId = req.user.id;

  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (senderId = ? AND receiverId = ?)
        OR (senderId = ? AND receiverId = ?)
     ORDER BY createdAt ASC`,
    [myId, otherId, otherId, myId]
  );

  res.json(messages);
});

app.post("/api/messages", authMiddleware, async (req, res) => {
  const { receiverId, content, isPremium = false } = req.body;
  const senderId = req.user.id;

  if (!receiverId || !content) return res.status(400).json({ error: "Missing fields" });

  const sender = await db.get("SELECT * FROM users WHERE id = ?", [senderId]);
  if (!sender) return res.status(404).json({ error: "Sender not found" });

  const cost = isPremium ? 2 : 0;
  if (sender.credits < cost) {
    return res.status(400).json({ error: "Not enough credits" });
  }

  if (cost > 0) {
    await db.run("UPDATE users SET credits = credits - ? WHERE id = ?", [cost, senderId]);
  }

  const result = await db.run(
    "INSERT INTO messages (senderId, receiverId, content, isPremium) VALUES (?, ?, ?, ?)",
    [senderId, receiverId, content, isPremium ? 1 : 0]
  );

  const message = {
    id: result.lastID,
    senderId,
    receiverId,
    content,
    isPremium: isPremium ? 1 : 0,
    createdAt: new Date().toISOString()
  };

  await db.run(
    "INSERT INTO notifications (userId, type, content) VALUES (?, ?, ?)",
    [receiverId, "message", `New message from ${sender.username}`]
  );

  emitMessage(receiverId, message);
  emitNotification(receiverId, {
    type: "message",
    content: `New message from ${sender.username}`
  });

  if (isPremium) {
    await db.run(
      "INSERT INTO notifications (userId, type, content) VALUES (?, ?, ?)",
      [receiverId, "premium_message", `Premium message from ${sender.username}`]
    );
    emitNotification(receiverId, {
      type: "premium_message",
      content: `Premium message from ${sender.username}`
    });
  }

  const updatedSender = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [senderId]);
  res.json({ message, user: updatedSender });
});

/* ---------------- NOTIFICATIONS ---------------- */

app.get("/api/notifications", authMiddleware, async (req, res) => {
  const notifications = await db.all(
    "SELECT * FROM notifications WHERE userId = ? ORDER BY createdAt DESC LIMIT 50",
    [req.user.id]
  );
  res.json(notifications);
});

app.post("/api/notifications/read", authMiddleware, async (req, res) => {
  await db.run("UPDATE notifications SET read = 1 WHERE userId = ?", [req.user.id]);
  res.json({ ok: true });
});

/* ---------------- MONETIZATION ---------------- */

// Minimal mock credit purchase endpoint
app.post("/api/buy-credits", authMiddleware, async (req, res) => {
  const { amount = 10 } = req.body;

  // In production, replace this with Stripe Checkout / Payment Intent verification.
  await db.run("UPDATE users SET credits = credits + ? WHERE id = ?", [amount, req.user.id]);

  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);
  res.json({ ok: true, user });
});

/* ---------------- SOCKET.IO ---------------- */

io.use((socket, next) => {
  const token = socket.handshake.auth?.token;
  if (!token) return next(new Error("No token"));
  try {
    socket.user = jwt.verify(token, JWT_SECRET);
    next();
  } catch {
    next(new Error("Invalid token"));
  }
});

io.on("connection", (socket) => {
  socket.join(`user:${socket.user.id}`);
  socket.emit("connected", { userId: socket.user.id });

  socket.on("disconnect", () => {});
});

server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

