import React, { useEffect, useState } from "react";
import { api, setAuthToken } from "./api";
import { createSocket } from "./socket";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [socket, setSocket] = useState(null);

  const [loginForm, setLoginForm] = useState({ username: "", password: "" });
  const [messageForm, setMessageForm] = useState({ content: "", premium: false });
  const [buyAmount, setBuyAmount] = useState(10);

  useEffect(() => {
    if (!token) return;
    setAuthToken(token);

    api.get("/me").then((res) => setUser(res.data));
    api.get("/users").then((res) => setUsers(res.data));
    api.get("/notifications").then((res) => setNotifications(res.data));

    const s = createSocket(token);
    s.on("message", (msg) => {
      if (selectedUser && msg.senderId === selectedUser.id) {
        setMessages((prev) => [...prev, msg]);
      }
    });
    s.on("notification", (n) => {
      setNotifications((prev) => [{ ...n, id: Date.now() }, ...prev]);
    });
    setSocket(s);

    return () => s.disconnect();
  }, [token, selectedUser]);

  useEffect(() => {
    if (!selectedUser || !token) return;
    api.get(`/messages/${selectedUser.id}`).then((res) => setMessages(res.data));
  }, [selectedUser, token]);

  async function register() {
    const res = await api.post("/register", loginForm);
    localStorage.setItem("token", res.data.token);
    setToken(res.data.token);
    setUser(res.data.user);
  }

  async function login() {
    const res = await api.post("/login", loginForm);
    localStorage.setItem("token", res.data.token);
    setToken(res.data.token);
    setUser(res.data.user);
  }

  async function sendMessage() {
    const res = await api.post("/messages", {
      receiverId: selectedUser.id,
      content: messageForm.content,
      isPremium: messageForm.premium
    });

    setMessages((prev) => [...prev, res.data.message]);
    setUser(res.data.user);
    setMessageForm({ content: "", premium: false });
  }

  async function buyCredits() {
    const res = await api.post("/buy-credits", { amount: buyAmount });
    setUser(res.data.user);
  }

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Social Messaging App</h2>
        <input
          placeholder="username"
          value={loginForm.username}
          onChange={(e) => setLoginForm({ ...loginForm, username: e.target.value })}
        />
        <input
          placeholder="password"
          type="password"
          value={loginForm.password}
          onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })}
        />
        <div style={{ marginTop: 10 }}>
          <button onClick={login}>Login</button>
          <button onClick={register} style={{ marginLeft: 8 }}>
            Register
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "sans-serif" }}>
      <div style={{ width: 250, borderRight: "1px solid #ddd", padding: 16 }}>
        <h3>{user?.username}</h3>
        <p>Credits: {user?.credits}</p>

        <h4>Buy Credits</h4>
        <input
          type="number"
          value={buyAmount}
          onChange={(e) => setBuyAmount(Number(e.target.value))}
        />
        <button onClick={buyCredits}>Buy</button>

        <h4 style={{ marginTop: 20 }}>Users</h4>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => setSelectedUser(u)}>
              {u.username}
            </button>
          </div>
        ))}

        <h4 style={{ marginTop: 20 }}>Notifications</h4>
        <div style={{ maxHeight: 200, overflow: "auto" }}>
          {notifications.map((n) => (
            <div key={n.id} style={{ fontSize: 12, marginBottom: 8 }}>
              <b>{n.type}</b>: {n.content}
            </div>
          ))}
        </div>
      </div>

      <div style={{ flex: 1, padding: 16 }}>
        {selectedUser ? (
          <>
            <h3>Chat with {selectedUser.username}</h3>
            <div style={{ height: 400, overflow: "auto", border: "1px solid #ddd", padding: 8 }}>
              {messages.map((m) => (
                <div key={m.id} style={{ marginBottom: 8 }}>
                  <b>{m.senderId === user.id ? "You" : selectedUser.username}:</b>{" "}
                  {m.content} {m.isPremium ? "⭐" : ""}
                </div>
              ))}
            </div>

            <div style={{ marginTop: 12 }}>
              <input
                style={{ width: "60%" }}
                value={messageForm.content}
                onChange={(e) => setMessageForm({ ...messageForm, content: e.target.value })}
                placeholder="Type a message"
              />
              <label style={{ marginLeft: 10 }}>
                <input
                  type="checkbox"
                  checked={messageForm.premium}
                  onChange={(e) => setMessageForm({ ...messageForm, premium: e.target.checked })}
                />
                Premium message (costs 2 credits)
              </label>
              <button onClick={sendMessage} style={{ marginLeft: 10 }}>
                Send
              </button>
            </div>
          </>
        ) : (
          <h3>Select a user to start chatting</h3>
        )}
      </div>
    </div>
  );
}
