## `server/src/index.js`

```js
import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import http from "http";
import { Server } from "socket.io";
import db from "./db.js";
import { stripe } from "./stripe.js";

dotenv.config();

const app = express();
const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: process.env.CLIENT_URL,
    methods: ["GET", "POST"]
  }
});

app.use(cors({ origin: process.env.CLIENT_URL }));
app.use(express.json());

const onlineUsers = new Map(); // userId -> socketId

function addNotification(userId, type, content) {
  db.run(
    `INSERT INTO notifications (userId, type, content) VALUES (?, ?, ?)`,
    [userId, type, content],
    function () {
      io.to(String(userId)).emit("notification", {
        id: this.lastID,
        userId,
        type,
        content,
        read: 0
      });
    }
  );
}

// Create or fetch user
app.post("/api/users", (req, res) => {
  const { name } = req.body;
  db.get(`SELECT * FROM users WHERE name = ?`, [name], (err, row) => {
    if (row) return res.json(row);

    db.run(`INSERT INTO users (name, coins) VALUES (?, 0)`, [name], function () {
      res.json({ id: this.lastID, name, coins: 0 });
    });
  });
});

// Get users
app.get("/api/users", (req, res) => {
  db.all(`SELECT * FROM users ORDER BY id DESC`, [], (err, rows) => {
    res.json(rows);
  });
});

// Get messages between two users
app.get("/api/messages", (req, res) => {
  const { userId, otherUserId } = req.query;
  db.all(
    `
    SELECT * FROM messages
    WHERE (senderId = ? AND receiverId = ?)
       OR (senderId = ? AND receiverId = ?)
    ORDER BY createdAt ASC
    `,
    [userId, otherUserId, otherUserId, userId],
    (err, rows) => res.json(rows)
  );
});

// Get notifications
app.get("/api/notifications/:userId", (req, res) => {
  db.all(
    `SELECT * FROM notifications WHERE userId = ? ORDER BY createdAt DESC`,
    [req.params.userId],
    (err, rows) => res.json(rows)
  );
});

// Send message
app.post("/api/messages", (req, res) => {
  const { senderId, receiverId, content } = req.body;

  db.run(
    `INSERT INTO messages (senderId, receiverId, content) VALUES (?, ?, ?)`,
    [senderId, receiverId, content],
    function () {
      const message = {
        id: this.lastID,
        senderId,
        receiverId,
        content,
        createdAt: new Date().toISOString()
      };

      io.to(String(receiverId)).emit("message", message);
      addNotification(receiverId, "message", `New message: ${content}`);

      res.json(message);
    }
  );
});

// Buy coins via Stripe Checkout
app.post("/api/create-checkout-session", async (req, res) => {
  const { userId, coins } = req.body;

  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: `${coins} Coins` },
          unit_amount: coins * 10 // 1 coin = $0.10
        },
        quantity: 1
      }
    ],
    metadata: { userId, coins }
  });

  res.json({ url: session.url });
});

// Stripe webhook to credit coins
app.post("/api/stripe-webhook", express.raw({ type: "application/json" }), (req, res) => {
  const sig = req.headers["stripe-signature"];
  let event;

  try {
    event = stripe.webhooks.constructEvent(
      req.body,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET
    );
  } catch (err) {
    return res.status(400).send(`Webhook Error: ${err.message}`);
  }

  if (event.type === "checkout.session.completed") {
    const session = event.data.object;
    const userId = session.metadata.userId;
    const coins = parseInt(session.metadata.coins, 10);

    db.run(`UPDATE users SET coins = coins + ? WHERE id = ?`, [coins, userId]);
    addNotification(userId, "purchase", `You purchased ${coins} coins.`);
  }

  res.json({ received: true });
});

// Tip user with coins
app.post("/api/tip", (req, res) => {
  const { fromUserId, toUserId, coins } = req.body;

  db.get(`SELECT coins FROM users WHERE id = ?`, [fromUserId], (err, fromUser) => {
    if (!fromUser || fromUser.coins < coins) {
      return res.status(400).json({ error: "Insufficient coins" });
    }

    db.run(`UPDATE users SET coins = coins - ? WHERE id = ?`, [coins, fromUserId]);
    db.run(`UPDATE users SET coins = coins + ? WHERE id = ?`, [coins, toUserId]);

    addNotification(toUserId, "tip", `You received a tip of ${coins} coins!`);
    addNotification(fromUserId, "tip", `You tipped ${coins} coins.`);

    res.json({ success: true });
  });
});

io.on("connection", (socket) => {
  socket.on("register", (userId) => {
    onlineUsers.set(userId, socket.id);
    socket.join(String(userId));
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
```

