```jsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { socket } from "./socket";

export default function App() {
  const [name, setName] = useState("");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [content, setContent] = useState("");
  const [notifications, setNotifications] = useState([]);
  const [coinsToBuy, setCoinsToBuy] = useState(100);
  const [tipAmount, setTipAmount] = useState(10);

  useEffect(() => {
    api.get("/users").then((res) => setUsers(res.data));
  }, []);

  useEffect(() => {
    if (!user) return;

    socket.emit("register", user.id);

    socket.on("message", (msg) => {
      if (
        selectedUser &&
        ((msg.senderId === selectedUser.id && msg.receiverId === user.id) ||
          (msg.senderId === user.id && msg.receiverId === selectedUser.id))
      ) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => {
      socket.off("message");
      socket.off("notification");
    };
  }, [user, selectedUser]);

  const login = async () => {
    const res = await api.post("/users", { name });
    setUser(res.data);
    const usersRes = await api.get("/users");
    setUsers(usersRes.data.filter((u) => u.id !== res.data.id));
    const notifRes = await api.get(`/notifications/${res.data.id}`);
    setNotifications(notifRes.data);
  };

  const openChat = async (u) => {
    setSelectedUser(u);
    const res = await api.get("/messages", {
      params: { userId: user.id, otherUserId: u.id }
    });
    setMessages(res.data);
  };

  const sendMessage = async () => {
    if (!content.trim()) return;
    const res = await api.post("/messages", {
      senderId: user.id,
      receiverId: selectedUser.id,
      content
    });
    setMessages((prev) => [...prev, res.data]);
    setContent("");
  };

  const buyCoins = async () => {
    const res = await api.post("/create-checkout-session", {
      userId: user.id,
      coins: coinsToBuy
    });
    window.location.href = res.data.url;
  };

  const tipUser = async () => {
    await api.post("/tip", {
      fromUserId: user.id,
      toUserId: selectedUser.id,
      coins: tipAmount
    });
    const updated = await api.get("/users");
    setUsers(updated.data.filter((u) => u.id !== user.id));
  };

  if (!user) {
    return (
      <div style={{ padding: 20 }}>
        <h1>Social Messaging App</h1>
        <input
          placeholder="Enter your name"
          value={name}
          onChange={(e) => setName(e.target.value)}
        />
        <button onClick={login}>Login / Create Account</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", gap: 20, padding: 20 }}>
      <div style={{ width: 250 }}>
        <h2>{user.name}</h2>
        <p>Coins: {user.coins}</p>

        <h3>Buy Coins</h3>
        <input
          type="number"
          value={coinsToBuy}
          onChange={(e) => setCoinsToBuy(Number(e.target.value))}
        />
        <button onClick={buyCoins}>Buy</button>

        <h3>Users</h3>
        {users.map((u) => (
          <div key={u.id}>
            <button onClick={() => openChat(u)}>
              {u.name} ({u.coins} coins)
            </button>
          </div>
        ))}

        <h3>Notifications</h3>
        {notifications.map((n) => (
          <div key={n.id} style={{ borderBottom: "1px solid #ddd" }}>
            {n.content}
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.name}</h2>
            <div style={{ border: "1px solid #ccc", height: 300, overflow: "auto", padding: 10 }}>
              {messages.map((m) => (
                <div key={m.id}>
                  <b>{m.senderId === user.id ? "You" : selectedUser.name}:</b> {m.content}
                </div>
              ))}
            </div>

            <input
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Type a message"
            />
            <button onClick={sendMessage}>Send</button>

            <div style={{ marginTop: 20 }}>
              <h3>Tip this user</h3>
              <input
                type="number"
                value={tipAmount}
                onChange={(e) => setTipAmount(Number(e.target.value))}
              />
              <button onClick={tipUser}>Send Tip</button>
            </div>
          </>
        ) : (
          <p>Select a user to start chatting.</p>
        )}
      </div>
    </div>
  );
}
```

