import express from "express";
import cors from "cors";
import dotenv from "dotenv";
import bcrypt from "bcryptjs";
import http from "http";
import { Server } from "socket.io";
import { db } from "./db.js";
import { authMiddleware, signToken } from "./auth.js";
import { stripe } from "./stripe.js";

dotenv.config();

const app = express();
const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: process.env.CLIENT_URL, credentials: true }
});

app.use(cors({ origin: process.env.CLIENT_URL, credentials: true }));
app.use(express.json());

const onlineUsers = new Map(); // userId -> socketId

io.on("connection", (socket) => {
  socket.on("register", (userId) => {
    onlineUsers.set(String(userId), socket.id);
  });

  socket.on("disconnect", () => {
    for (const [userId, socketId] of onlineUsers.entries()) {
      if (socketId === socket.id) onlineUsers.delete(userId);
    }
  });
});

function pushNotification(userId, notification) {
  const socketId = onlineUsers.get(String(userId));
  if (socketId) io.to(socketId).emit("notification", notification);
}

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body;
  const hash = await bcrypt.hash(password, 10);

  try {
    const result = await db.run(
      "INSERT INTO users (username, password_hash, credits) VALUES (?, ?, 10)",
      [username, hash]
    );
    const user = { id: result.lastID, username };
    res.json({ token: signToken(user), user: { ...user, credits: 10 } });
  } catch {
    res.status(400).json({ error: "Username already exists" });
  }
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body;
  const user = await db.get("SELECT * FROM users WHERE username = ?", [username]);
  if (!user) return res.status(400).json({ error: "Invalid credentials" });

  const ok = await bcrypt.compare(password, user.password_hash);
  if (!ok) return res.status(400).json({ error: "Invalid credentials" });

  res.json({
    token: signToken(user),
    user: { id: user.id, username: user.username, credits: user.credits }
  });
});

app.get("/api/me", authMiddleware, async (req, res) => {
  const user = await db.get("SELECT id, username, credits FROM users WHERE id = ?", [req.user.id]);
  res.json(user);
});

app.get("/api/messages/:userId", authMiddleware, async (req, res) => {
  const me = req.user.id;
  const other = req.params.userId;

  const messages = await db.all(
    `SELECT * FROM messages
     WHERE (sender_id = ? AND receiver_id = ?)
        OR (sender_id = ? AND receiver_id = ?)
     ORDER BY created_at ASC`,
    [me, other, other, me]
  );

  res.json(messages);
});

app.post("/api/messages", authMiddleware, async (req, res) => {
  const { receiverId, content, boosted } = req.body;
  const senderId = req.user.id;

  let boostCost = boosted ? 2 : 0;

  const sender = await db.get("SELECT credits FROM users WHERE id = ?", [senderId]);
  if (sender.credits < boostCost) {
    return res.status(400).json({ error: "Not enough credits" });
  }

  if (boostCost > 0) {
    await db.run("UPDATE users SET credits = credits - ? WHERE id = ?", [boostCost, senderId]);
  }

  const result = await db.run(
    "INSERT INTO messages (sender_id, receiver_id, content, boosted) VALUES (?, ?, ?, ?)",
    [senderId, receiverId, content, boosted ? 1 : 0]
  );

  const message = {
    id: result.lastID,
    sender_id: senderId,
    receiver_id: receiverId,
    content,
    boosted: boosted ? 1 : 0,
    created_at: new Date().toISOString()
  };

  await db.run(
    "INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)",
    [receiverId, "message", `New message from user ${senderId}`]
  );

  pushNotification(receiverId, {
    type: "message",
    content: `New message from user ${senderId}`
  });

  res.json(message);
});

app.get("/api/notifications", authMiddleware, async (req, res) => {
  const notifications = await db.all(
    "SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC",
    [req.user.id]
  );
  res.json(notifications);
});

app.post("/api/notifications/:id/read", authMiddleware, async (req, res) => {
  await db.run("UPDATE notifications SET read = 1 WHERE id = ? AND user_id = ?", [
    req.params.id,
    req.user.id
  ]);
  res.json({ ok: true });
});

app.post("/api/create-checkout-session", authMiddleware, async (req, res) => {
  const session = await stripe.checkout.sessions.create({
    mode: "payment",
    line_items: [
      {
        price_data: {
          currency: "usd",
          product_data: { name: "100 Credits" },
          unit_amount: 499
        },
        quantity: 1
      }
    ],
    success_url: `${process.env.CLIENT_URL}/?success=1`,
    cancel_url: `${process.env.CLIENT_URL}/?canceled=1`,
    metadata: { userId: String(req.user.id) }
  });

  res.json({ url: session.url });
});

app.post("/api/stripe/webhook", express.raw({ type: "application/json" }), async (req, res) => {
  // Minimal webhook placeholder
  res.json({ received: true });
});

server.listen(process.env.PORT || 4000, () => {
  console.log(`Server running on port ${process.env.PORT || 4000}`);
});
