```jsx
import React, { useEffect, useState } from "react";
import { api } from "./api";
import { socket } from "./socket";
import "./styles.css";

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [authForm, setAuthForm] = useState({ username: "", password: "" });
  const [otherUserId, setOtherUserId] = useState("");
  const [content, setContent] = useState("");
  const [boosted, setBoosted] = useState(false);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  useEffect(() => {
    if (!token) return;
    api("/me", "GET", null, token).then(setUser);
  }, [token]);

  useEffect(() => {
    if (!user) return;
    socket.emit("register", user.id);
    socket.on("notification", (n) => setNotifications((prev) => [n, ...prev]));
    return () => socket.off("notification");
  }, [user]);

  const login = async (isRegister) => {
    const path = isRegister ? "/register" : "/login";
    const data = await api(path, "POST", authForm);
    if (data.token) {
      localStorage.setItem("token", data.token);
      setToken(data.token);
      setUser(data.user);
    }
  };

  const loadMessages = async () => {
    const data = await api(`/messages/${otherUserId}`, "GET", null, token);
    setMessages(data);
  };

  const sendMessage = async () => {
    const data = await api(
      "/messages",
      "POST",
      { receiverId: Number(otherUserId), content, boosted },
      token
    );
    if (!data.error) {
      setMessages((prev) => [...prev, data]);
      setContent("");
      setBoosted(false);
      setUser((u) => ({ ...u, credits: u.credits - (boosted ? 2 : 0) }));
    }
  };

  const buyCredits = async () => {
    const data = await api("/create-checkout-session", "POST", {}, token);
    if (data.url) window.location.href = data.url;
  };

  if (!user) {
    return (
      <div className="container">
        <h1>Social Messaging App</h1>
        <input placeholder="username" onChange={(e) => setAuthForm({ ...authForm, username: e.target.value })} />
        <input placeholder="password" type="password" onChange={(e) => setAuthForm({ ...authForm, password: e.target.value })} />
        <button onClick={() => login(false)}>Login</button>
        <button onClick={() => login(true)}>Register</button>
      </div>
    );
  }

  return (
    <div className="container">
      <h1>Welcome, {user.username}</h1>
      <p>Credits: {user.credits}</p>
      <button onClick={buyCredits}>Buy Credits</button>

      <div className="panel">
        <input
          placeholder="Chat with user ID"
          value={otherUserId}
          onChange={(e) => setOtherUserId(e.target.value)}
        />
        <button onClick={loadMessages}>Load Chat</button>
      </div>

      <div className="panel">
        <input placeholder="Message" value={content} onChange={(e) => setContent(e.target.value)} />
        <label>
          <input type="checkbox" checked={boosted} onChange={(e) => setBoosted(e.target.checked)} />
          Boosted message (2 credits)
        </label>
        <button onClick={sendMessage}>Send</button>
      </div>

      <h2>Messages</h2>
      <div className="list">
        {messages.map((m) => (
          <div key={m.id} className={m.boosted ? "message boosted" : "message"}>
            <strong>{m.sender_id === user.id ? "You" : `User ${m.sender_id}`}</strong>: {m.content}
          </div>
        ))}
      </div>

      <h2>Notifications</h2>
      <div className="list">
        {notifications.map((n, i) => (
          <div key={i} className="notification">{n.content}</div>
        ))}
      </div>
    </div>
  );
}
