export function setupSocket(io, prisma) {
  io.on("connection", (socket) => {
    socket.on("join", (userId) => {
      socket.join(userId);
    });

    socket.on("send-message", async ({ senderId, receiverId, content, premium }) => {
      const message = await prisma.message.create({
        data: { senderId, receiverId, content, premium: !!premium }
      });

      const notification = await prisma.notification.create({
        data: {
          userId: receiverId,
          type: premium ? "premium_message" : "message",
          text: premium
            ? "You received a premium message!"
            : "You received a new message!"
        }
      });

      io.to(receiverId).emit("new-message", message);
      io.to(receiverId).emit("new-notification", notification);
    });
  });
}
