      senderId: sender.id,
      receiverId,
      content,
      premium: true
    }
  });

  const notification = await prisma.notification.create({
    data: {
      userId: receiverId,
      type: "premium_message",
      text: "You received a premium message!"
    }
  });

  io.to(receiverId).emit("new-message", message);
  io.to(receiverId).emit("new-notification", notification);

  res.json({ ok: true, message });
