## `client/src/App.jsx`

```jsx
import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";
import { api, setAuthToken } from "./api";

const socket = io("http://localhost:4000");

export default function App() {
  const [token, setToken] = useState(localStorage.getItem("token") || "");
  const [user, setUser] = useState(null);
  const [users, setUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [form, setForm] = useState({ email: "", password: "", displayName: "" });
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (!token) return;
    setAuthToken(token);
    socket.emit("join", JSON.parse(atob(token.split(".")[1])).id);

    api.get("/me").then((r) => setUser(r.data));
    api.get("/users").then((r) => setUsers(r.data));
    api.get("/notifications").then((r) => setNotifications(r.data));

    socket.on("new-message", (msg) => {
      if (selectedUser && (msg.senderId === selectedUser.id || msg.receiverId === selectedUser.id)) {
        setMessages((prev) => [...prev, msg]);
      }
    });

    socket.on("new-notification", (n) => {
      setNotifications((prev) => [n, ...prev]);
    });

    return () => {
      socket.off("new-message");
      socket.off("new-notification");
    };
  }, [token, selectedUser]);

  async function register() {
    const r = await api.post("/register", form);
    localStorage.setItem("token", r.data.token);
    setToken(r.data.token);
  }

  async function login() {
    const r = await api.post("/login", {
      email: form.email,
      password: form.password
    });
    localStorage.setItem("token", r.data.token);
    setToken(r.data.token);
  }

  async function loadMessages(u) {
    setSelectedUser(u);
    const r = await api.get(`/messages/${u.id}`);
    setMessages(r.data);
  }

  async function sendMessage(premium = false) {
    if (!selectedUser || !message.trim()) return;

    if (premium) {
      await api.post("/send-premium-message", {
        receiverId: selectedUser.id,
        content: message
      });
    } else {
      socket.emit("send-message", {
        senderId: user.id,
        receiverId: selectedUser.id,
        content: message,
        premium: false
      });
    }

    setMessage("");
    const r = await api.get(`/messages/${selectedUser.id}`);
    setMessages(r.data);
  }

  async function buyCredits() {
    await api.post("/buy-credits", { credits: 100 });
    const r = await api.get("/me");
    setUser(r.data);
  }

  if (!token) {
    return (
      <div style={{ padding: 20 }}>
        <h2>Social Messaging App</h2>
        <input placeholder="Display name" value={form.displayName} onChange={(e) => setForm({ ...form, displayName: e.target.value })} />
        <br />
        <input placeholder="Email" value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} />
        <br />
        <input placeholder="Password" type="password" value={form.password} onChange={(e) => setForm({ ...form, password: e.target.value })} />
        <br />
        <button onClick={register}>Register</button>
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div style={{ display: "flex", gap: 20, padding: 20 }}>
      <div style={{ width: 220 }}>
        <h3>Users</h3>
        <div>Logged in as: {user?.displayName}</div>
        <div>Credits: {user?.credits}</div>
        <button onClick={buyCredits}>Buy 100 Credits</button>
        <hr />
        {users.filter((u) => u.id !== user?.id).map((u) => (
          <div key={u.id}>
            <button onClick={() => loadMessages(u)}>
              {u.displayName} ({u.credits})
            </button>
          </div>
        ))}
      </div>

      <div style={{ flex: 1 }}>
        <h3>Chat {selectedUser ? `with ${selectedUser.displayName}` : ""}</h3>
        <div style={{ border: "1px solid #ccc", height: 300, overflow: "auto", padding: 10 }}>
          {messages.map((m) => (
            <div key={m.id}>
              <b>{m.senderId === user.id ? "Me" : selectedUser?.displayName}:</b> {m.content}
              {m.premium ? " ⭐" : ""}
            </div>
          ))}
        </div>
        <input value={message} onChange={(e) => setMessage(e.target.value)} placeholder="Type a message..." />
        <button onClick={() => sendMessage(false)}>Send</button>
        <button onClick={() => sendMessage(true)}>Send Premium (1 credit)</button>

        <h3>Notifications</h3>
        <ul>
          {notifications.map((n) => (
            <li key={n.id}>
              {n.text} {n.read ? "" : "(new)"}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}
```

