### `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { initDb } from "./db.js";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: { origin: "*" }
});

const db = await initDb();
const onlineUsers = new Map(); // username -> socketId

app.get("/api/users", async (req, res) => {
  const users = await db.all("SELECT username, credits FROM users ORDER BY username");
  res.json(users);
});

app.post("/api/login", async (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "Username required" });

  let user = await db.get("SELECT username, credits FROM users WHERE username = ?", username);
  if (!user) {
    await db.run("INSERT INTO users (username, credits) VALUES (?, ?)", username, 10);
    user = { username, credits: 10 };
  }

  res.json(user);
});

app.post("/api/buy-credits", async (req, res) => {
  const { username, amount = 10 } = req.body;
  if (!username) return res.status(400).json({ error: "Username required" });

  await db.run("UPDATE users SET credits = credits + ? WHERE username = ?", amount, username);
  const user = await db.get("SELECT username, credits FROM users WHERE username = ?", username);

  io.to(onlineUsers.get(username)).emit("credits-updated", user);
  res.json(user);
});

app.get("/api/messages/:user1/:user2", async (req, res) => {
  const { user1, user2 } = req.params;
  const messages = await db.all(
    `
    SELECT * FROM messages
    WHERE (sender = ? AND recipient = ?)
       OR (sender = ? AND recipient = ?)
    ORDER BY created_at ASC
    `,
    user1, user2, user2, user1
  );
  res.json(messages);
});

io.on("connection", (socket) => {
  socket.on("register", async ({ username }) => {
    if (!username) return;
    socket.username = username;
    onlineUsers.set(username, socket.id);

    io.emit("online-users", Array.from(onlineUsers.keys()));

    const user = await db.get("SELECT username, credits FROM users WHERE username = ?", username);
    socket.emit("credits-updated", user);
  });

  socket.on("send-message", async ({ sender, recipient, content, premium }) => {
    if (!sender || !recipient || !content) return;

    const senderUser = await db.get("SELECT credits FROM users WHERE username = ?", sender);
    if (!senderUser) return;

    if (premium) {
      if (senderUser.credits < 1) {
        socket.emit("notification", {
          type: "error",
          message: "Not enough credits for premium message."
        });
        return;
      }
      await db.run("UPDATE users SET credits = credits - 1 WHERE username = ?", sender);
    }

    await db.run(
      "INSERT INTO messages (sender, recipient, content, premium) VALUES (?, ?, ?, ?)",
      sender, recipient, content, premium ? 1 : 0
    );

    const message = await db.get("SELECT * FROM messages ORDER BY id DESC LIMIT 1");

    // Send to recipient if online
    const recipientSocketId = onlineUsers.get(recipient);
    if (recipientSocketId) {
      io.to(recipientSocketId).emit("new-message", message);
      io.to(recipientSocketId).emit("notification", {
        type: premium ? "premium-message" : "message",
        message: `New ${premium ? "premium " : ""}message from ${sender}`
      });
    }

    // Confirm sender
    socket.emit("message-sent", message);

    const updatedSender = await db.get("SELECT username, credits FROM users WHERE username = ?", sender);
    socket.emit("credits-updated", updatedSender);
  });

  socket.on("disconnect", () => {
    if (socket.username) {
      onlineUsers.delete(socket.username);
      io.emit("online-users", Array.from(onlineUsers.keys()));
    }
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

