import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API = "http://localhost:3001";

export default function App() {
  const [username, setUsername] = useState("");
  const [loggedIn, setLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const [onlineUsers, setOnlineUsers] = useState([]);
  const [recipient, setRecipient] = useState("");
  const [content, setContent] = useState("");
  const [premium, setPremium] = useState(false);
  const [messages, setMessages] = useState([]);
  const [notifications, setNotifications] = useState([]);

  const socket = useMemo(() => io(API), []);

  useEffect(() => {
    socket.on("online-users", setOnlineUsers);
    socket.on("new-message", (msg) => setMessages((prev) => [...prev, msg]));
    socket.on("message-sent", (msg) => setMessages((prev) => [...prev, msg]));
    socket.on("credits-updated", (u) => setUser(u));
    socket.on("notification", (n) => {
      setNotifications((prev) => [n, ...prev].slice(0, 5));
    });

    return () => socket.disconnect();
  }, [socket]);

  const login = async () => {
    const res = await fetch(`${API}/api/login`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username })
    });
    const data = await res.json();
    setUser(data);
    setLoggedIn(true);
    socket.emit("register", { username });
  };

  const loadMessages = async (otherUser) => {
    if (!username || !otherUser) return;
    const res = await fetch(`${API}/api/messages/${username}/${otherUser}`);
    const data = await res.json();
    setMessages(data);
  };

  const sendMessage = () => {
    if (!recipient || !content) return;
    socket.emit("send-message", {
      sender: username,
      recipient,
      content,
      premium
    });
    setContent("");
    setPremium(false);
  };

  const buyCredits = async () => {
    const res = await fetch(`${API}/api/buy-credits`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ username, amount: 10 })
    });
    const data = await res.json();
    setUser(data);
  };

  if (!loggedIn) {
    return (
      <div className="container">
        <h1>Social Messaging App</h1>
        <input
          placeholder="Enter username"
          value={username}
          onChange={(e) => setUsername(e.target.value)}
        />
        <button onClick={login}>Login</button>
      </div>
    );
  }

  return (
    <div className="container">
      <header className="header">
        <div>
          <h2>Welcome, {username}</h2>
          <p>Credits: {user?.credits ?? 0}</p>
        </div>
        <button onClick={buyCredits}>Buy 10 Credits</button>
      </header>

      <section className="panel">
        <h3>Online Users</h3>
        <div className="chips">
          {onlineUsers.filter((u) => u !== username).map((u) => (
            <button key={u} className="chip" onClick={() => { setRecipient(u); loadMessages(u); }}>
              {u}
            </button>
          ))}
        </div>
      </section>

      <section className="panel">
        <h3>Chat with: {recipient || "Select a user"}</h3>
        <div className="messages">
          {messages.map((m) => (
            <div key={m.id} className={`message ${m.premium ? "premium" : ""}`}>
              <strong>{m.sender}</strong>: {m.content}
              {m.premium ? <span className="badge">Premium</span> : null}
            </div>
          ))}
        </div>

        <div className="composer">
          <input
            placeholder="Message..."
            value={content}
            onChange={(e) => setContent(e.target.value)}
          />
          <label>
            <input
              type="checkbox"
              checked={premium}
              onChange={(e) => setPremium(e.target.checked)}
            />
            Premium (-1 credit)
          </label>
          <button onClick={sendMessage}>Send</button>
        </div>
      </section>

      <section className="panel">
        <h3>Notifications</h3>
        {notifications.map((n, i) => (
          <div key={i} className={`notification ${n.type}`}>
            {n.message}
          </div>
        ))}
      </section>
    </div>
  );
}
