require("dotenv").config();
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");
const db = require("./db");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

// --- Helpers ---
function getOrCreateUser(username) {
  let user = db.prepare("SELECT * FROM users WHERE username = ?").get(username);
  if (!user) {
    const info = db.prepare("INSERT INTO users (username) VALUES (?)").run(username);
    user = db.prepare("SELECT * FROM users WHERE id = ?").get(info.lastInsertRowid);
  }
  return user;
}

function createNotification(userId, type, content) {
  const info = db
    .prepare("INSERT INTO notifications (user_id, type, content) VALUES (?, ?, ?)")
    .run(userId, type, content);

  const notification = db.prepare("SELECT * FROM notifications WHERE id = ?").get(info.lastInsertRowid);
  io.to(`user:${userId}`).emit("notification", notification);
  return notification;
}

// --- API ---
app.post("/api/login", (req, res) => {
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: "username required" });

  const user = getOrCreateUser(username);
  res.json(user);
});

app.get("/api/users", (req, res) => {
  const users = db.prepare("SELECT id, username, is_premium FROM users ORDER BY id DESC").all();
  res.json(users);
});

app.get("/api/messages/:userId", (req, res) => {
  const userId = Number(req.params.userId);
  const messages = db.prepare(`
    SELECT m.*, u1.username AS sender_username, u2.username AS recipient_username
    FROM messages m
    JOIN users u1 ON m.sender_id = u1.id
    JOIN users u2 ON m.recipient_id = u2.id
    WHERE m.sender_id = ? OR m.recipient_id = ?
    ORDER BY m.created_at ASC
  `).all(userId, userId);

  res.json(messages);
});

app.get("/api/notifications/:userId", (req, res) => {
  const userId = Number(req.params.userId);
  const notifications = db
    .prepare("SELECT * FROM notifications WHERE user_id = ? ORDER BY created_at DESC")
    .all(userId);
  res.json(notifications);
});

app.post("/api/send-message", (req, res) => {
  const { senderId, recipientId, content } = req.body;
  if (!senderId || !recipientId || !content) {
    return res.status(400).json({ error: "senderId, recipientId, content required" });
  }

  const sender = db.prepare("SELECT * FROM users WHERE id = ?").get(senderId);
  const recipient = db.prepare("SELECT * FROM users WHERE id = ?").get(recipientId);
  if (!sender || !recipient) return res.status(404).json({ error: "user not found" });

  const info = db
    .prepare("INSERT INTO messages (sender_id, recipient_id, content) VALUES (?, ?, ?)")
    .run(senderId, recipientId, content);

  const message = db.prepare(`
    SELECT m.*, u1.username AS sender_username, u2.username AS recipient_username
    FROM messages m
    JOIN users u1 ON m.sender_id = u1.id
    JOIN users u2 ON m.recipient_id = u2.id
    WHERE m.id = ?
  `).get(info.lastInsertRowid);

  // Real-time message delivery
  io.to(`user:${recipientId}`).emit("message", message);

  // Real-time notification
  createNotification(recipientId, "message", `${sender.username} sent you a message`);

  res.json(message);
});

// Simple monetization demo: mark user as premium
app.post("/api/upgrade-premium", (req, res) => {
  const { userId } = req.body;
  if (!userId) return res.status(400).json({ error: "userId required" });

  db.prepare("UPDATE users SET is_premium = 1 WHERE id = ?").run(userId);
  const user = db.prepare("SELECT id, username, is_premium FROM users WHERE id = ?").get(userId);

  createNotification(userId, "billing", "Your account is now Premium!");
  res.json(user);
});

// Stripe-ready placeholder endpoint
app.post("/api/create-checkout-session", (req, res) => {
  // In production, create a Stripe Checkout Session here.
  res.json({
    url: "https://example.com/checkout-placeholder"
  });
});

// --- Socket.IO ---
io.on("connection", (socket) => {
  socket.on("join", (userId) => {
    socket.join(`user:${userId}`);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
