loginBtn.onclick = async () => {
  const username = usernameEl.value.trim();
  if (!username) return alert("Enter a username");

  const res = await fetch("/api/login", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ username })
  });

  currentUser = await res.json();
  currentUserEl.textContent = `Logged in as ${currentUser.username} (ID: ${currentUser.id}) ${currentUser.is_premium ? "⭐ Premium" : ""}`;

  socket.emit("join", currentUser.id);
  await loadUsers();
  await loadNotifications(currentUser.id);
  await loadMessages(currentUser.id);
};

sendBtn.onclick = async () => {
  if (!currentUser) return alert("Login first");

  const recipientId = Number(recipientIdEl.value);
  const content = messageContentEl.value.trim();
  if (!recipientId || !content) return alert("Recipient and message required");

  await fetch("/api/send-message", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      senderId: currentUser.id,
      recipientId,
      content
    })
  });

  messageContentEl.value = "";
  await loadMessages(currentUser.id);
};

premiumBtn.onclick = async () => {
  if (!currentUser) return alert("Login first");

  const res = await fetch("/api/upgrade-premium", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
