  alert(`Checkout placeholder URL: ${data.url}`);
};

socket.on("message", async (message) => {
  if (currentUser && (message.sender_id === currentUser.id || message.recipient_id === currentUser.id)) {
    await loadMessages(currentUser.id);
  }
});

socket.on("notification", async (notification) => {
  if (currentUser && notification.user_id === currentUser.id) {
    await loadNotifications(currentUser.id);
