# 10) Messages API

Create `app/api/messages/route.ts`:

```ts
import { NextResponse } from "next/server";
import { prisma } from "@/lib/db";
import { getCurrentUser } from "@/lib/auth";
import { emitMessage } from "@/lib/socket";

export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const otherUserId = searchParams.get("userId");

  const me = await getCurrentUser();

  if (!otherUserId) {
    return NextResponse.json({ error: "Missing userId" }, { status: 400 });
  }

  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: me.id, receiverId: otherUserId },
        { senderId: otherUserId, receiverId: me.id },
      ],
    },
    orderBy: { createdAt: "asc" },
  });

  return NextResponse.json(messages);
}

export async function POST(req: Request) {
  const me = await getCurrentUser();
  const body = await req.json();
  const { receiverId, content } = body;

  if (!receiverId || !content) {
    return NextResponse.json({ error: "Missing fields" }, { status: 400 });
  }

  const message = await prisma.message.create({
    data: {
      senderId: me.id,
      receiverId,
      content,
    },
  });

  const notification = await prisma.notification.create({
    data: {
      userId: receiverId,
      type: "message",
      text: `${me.name || me.email} sent you a message`,
    },
  });

  // Real-time emit
  emitMessage(receiverId, {
    type: "message",
    message,
  });

  emitMessage(receiverId, {
    type: "notification",
    notification,
  });

  return NextResponse.json(message);
}
```

