# 14) Socket.IO server

For real-time notifications, create `server.ts`:

```ts
import express from "express";
import next from "next";
import { createServer } from "http";
import { Server } from "socket.io";

const dev = process.env.NODE_ENV !== "production";
const app = next({ dev });
const handle = app.getRequestHandler();

const userSockets = new Map<string, string>();

app.prepare().then(() => {
  const server = express();
  const httpServer = createServer(server);
  const io = new Server(httpServer, {
    cors: {
      origin: "*",
    },
  });

  io.on("connection", (socket) => {
    socket.on("register", (userId: string) => {
      userSockets.set(userId, socket.id);
    });

    socket.on("disconnect", () => {
      for (const [userId, socketId] of userSockets.entries()) {
        if (socketId === socket.id) userSockets.delete(userId);
      }
    });
  });

  server.all("*", (req, res) => handle(req, res));

  httpServer.listen(3000, () => {
    console.log("> Ready on http://localhost:3000");
  });
});

export function emitMessage(userId: string, payload: any) {
  // This function is used by API routes; in a real app, store io in a singleton
  console.log("Emit to", userId, payload);
}
```

