<body>
  <header>
    <h1>Real-Time Analytics Dashboard</h1>
    <p><span class="status-dot"></span>Live data updates every 2 seconds</p>
  </header>

  <main class="dashboard">
    <section class="panel">
      <h2>Live Metrics</h2>

      <div class="stats">
        <div class="stat-card">
          <div class="label">Current Value</div>
          <div class="value" id="currentValue">0</div>
        </div>
        <div class="stat-card">
          <div class="label">Average</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="stat-card">
          <div class="label">Total Points</div>
          <div class="value" id="totalPoints">0</div>
        </div>
      </div>

      <canvas id="liveChart"></canvas>
    </section>

    <aside class="panel">
      <h2>Data Entry Form</h2>

      <form id="dataForm">
        <div>
          <label for="name">Label</label>
          <input type="text" id="name" placeholder="e.g. Sensor A" required />
        </div>

        <div>
          <label for="value">Value</label>
          <input type="number" id="value" placeholder="Enter a number" required />
        </div>

        <div>
          <label for="category">Category</label>
          <select id="category" required>
            <option value="">Select category</option>
            <option value="temperature">Temperature</option>
            <option value="pressure">Pressure</option>
            <option value="humidity">Humidity</option>
          </select>
        </div>

        <button type="submit" class="btn-primary">Add Data Point</button>
        <button type="button" id="randomBtn" class="btn-secondary">Generate Random Data</button>
        <button type="button" id="clearBtn" class="btn-danger">Clear Chart</button>

        <div class="message" id="formMessage"></div>
      </form>

      <div class="log" id="activityLog">
        <div class="log-item">Dashboard initialized.</div>
      </div>
    </aside>
  </main>

  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');
    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const totalPointsEl = document.getElementById('totalPoints');
    const form = document.getElementById('dataForm');
    const formMessage = document.getElementById('formMessage');
    const activityLog = document.getElementById('activityLog');
    const randomBtn = document.getElementById('randomBtn');
    const clearBtn = document.getElementById('clearBtn');

    const labels = [];
    const dataPoints = [];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Data',
          data: dataPoints,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.2)',
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointBackgroundColor: '#22c55e'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: '#1f2937' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: '#1f2937' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    function updateStats() {
      const total = dataPoints.reduce((sum, val) => sum + val, 0);
      const avg = dataPoints.length ? (total / dataPoints.length).toFixed(2) : 0;
      const current = dataPoints.length ? dataPoints[dataPoints.length - 1] : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      totalPointsEl.textContent = dataPoints.length;
    }

    function addLog(message) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      activityLog.prepend(item);
    }

    function addDataPoint(label, value) {
      labels.push(label);
      dataPoints.push(value);

      if (labels.length > 20) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();
      updateStats();
      addLog(`Added "${label}" with value ${value}.`);
    }

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('name').value.trim();
      const value = parseFloat(document.getElementById('value').value);
      const category = document.getElementById('category').value;

      if (!name || isNaN(value) || !category) {
        formMessage.textContent = 'Please fill out all fields correctly.';
        formMessage.style.color = '#ef4444';
        return;
      }

      const label = `${name} (${category})`;
      addDataPoint(label, value);

      form.reset();
      formMessage.textContent = 'Data point added successfully.';
      formMessage.style.color = '#22c55e';
    });

    randomBtn.addEventListener('click', () => {
      const categories = ['temperature', 'pressure', 'humidity'];
      const randomCategory = categories[Math.floor(Math.random() * categories.length)];
      const randomValue = Math.floor(Math.random() * 100) + 1;
      const randomLabel = `Auto-${randomCategory}-${dataPoints.length + 1}`;

      addDataPoint(randomLabel, randomValue);
      formMessage.textContent = 'Random data generated.';
      formMessage.style.color = '#38bdf8';
    });

    clearBtn.addEventListener('click', () => {
      labels.length = 0;
      dataPoints.length = 0;
      chart.update();
      updateStats();
      addLog('Chart cleared.');
      formMessage.textContent = 'Chart cleared.';
      formMessage.style.color = '#ef4444';
    });

    // Simulated real-time updates every 2 seconds
    setInterval(() => {
      const simulatedValue = Math.floor(Math.random() * 100) + 1;
      const timestamp = new Date().toLocaleTimeString();
      addDataPoint(timestamp, simulatedValue);
    }, 2000);

    // Initial stats
    updateStats();
  </script>
</body>
