            grid: { color: "rgba(55, 65, 81, 0.5)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const lastUpdateEl = document.getElementById("lastUpdate");
    const eventLogEl = document.getElementById("eventLog");

    function updateMetrics() {
      const activeUsers = Math.floor(50 + Math.random() * 450);
      const requestsPerMin = Math.floor(100 + Math.random() * 900);
      const errorRate = (Math.random() * 5).toFixed(1);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;
      lastUpdateEl.textContent = new Date().toLocaleTimeString();

      const newPoint = Math.floor(20 + Math.random() * 100);
      const timeLabel = new Date().toLocaleTimeString();

      labels.push(timeLabel);
      trafficData.push(newPoint);

      if (labels.length > 12) {
        labels.shift();
        trafficData.shift();
      }

      chart.update();
    }

    setInterval(updateMetrics, 2000);
    updateMetrics();

    const form = document.getElementById("eventForm");
    const nameInput = document.getElementById("name");
    const categoryInput = document.getElementById("category");
    const valueInput = document.getElementById("value");
    const notesInput = document.getElementById("notes");

    const nameError = document.getElementById("nameError");
    const categoryError = document.getElementById("categoryError");
    const valueError = document.getElementById("valueError");

    function clearErrors() {
      nameError.textContent = "";
      categoryError.textContent = "";
      valueError.textContent = "";
    }

    function addLogItem(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = message;
      eventLogEl.prepend(item);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      clearErrors();

      let valid = true;
      const name = nameInput.value.trim();
      const category = categoryInput.value;
      const value = Number(valueInput.value);
      const notes = notesInput.value.trim();

      if (!name) {
        nameError.textContent = "Event name is required.";
        valid = false;
      }

      if (!category) {
        categoryError.textContent = "Please select a category.";
        valid = false;
      }

      if (!valueInput.value || Number.isNaN(value) || value <= 0) {
        valueError.textContent = "Enter a valid value greater than 0.";
        valid = false;
      }

      if (!valid) return;

      addLogItem(
        `[${new Date().toLocaleTimeString()}] ${name} | ${category} | value: ${value}` +
        (notes ? ` | notes: ${notes}` : "")
      );

      // Simulate dashboard impact
      const currentTraffic = trafficData[trafficData.length - 1] || 50;
      trafficData[trafficData.length - 1] = currentTraffic + Math.min(value, 50);
      chart.update();

      form.reset();
    });
  </script>
</body>
</html>
