        <div class="delta" id="requestsDelta">Updating...</div>
      </div>
      <div class="stat">
        <div class="label">Error Rate</div>
        <div class="value" id="errorRate">0%</div>
        <div class="delta" id="errorDelta">Updating...</div>
      </div>
