            <input id="title" type="text" placeholder="Event title" required />
          </div>
          <div>
            <select id="status" required>
              <option value="good">Good</option>
              <option value="warn">Warning</option>
              <option value="bad">Error</option>
            </select>
          </div>
          <div>
            <input id="value" type="number" placeholder="Value" required min="0" />
          </div>
          <div class="full">
            <textarea id="notes" rows="4" placeholder="Notes"></textarea>
          </div>
          <div class="full">
            <button type="submit">Add Event</button>
          </div>
        </div>
