  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const avgLatencyEl = document.getElementById("avgLatency");

    const activeUsersDeltaEl = document.getElementById("activeUsersDelta");
    const requestsDeltaEl = document.getElementById("requestsDelta");
    const errorDeltaEl = document.getElementById("errorDelta");
    const latencyDeltaEl = document.getElementById("latencyDelta");

    const eventForm = document.getElementById("eventForm");
    const eventList = document.getElementById("eventList");
    const searchInput = document.getElementById("searchInput");
    const statusFilter = document.getElementById("statusFilter");

    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
    const trafficData = labels.map(() => Math.floor(Math.random() * 100) + 20);

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointHoverRadius: 5
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.5)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.5)" }
          }
        }
      }
    });

    let metrics = {
      activeUsers: 1240,
      requestsPerMin: 860,
      errorRate: 2.4,
      avgLatency: 180
    };

    let previousMetrics = { ...metrics };

    const events = [
      { title: "API response spike", status: "warn", value: 78, notes: "Traffic increased after deployment." },
      { title: "Cache warmup complete", status: "good", value: 100, notes: "Cache is fully populated." },
      { title: "Database timeout", status: "bad", value: 12, notes: "One node timed out during peak load." }
    ];

    function statusLabel(status) {
      return status === "good" ? "Good" : status === "warn" ? "Warning" : "Error";
    }

    function renderEvents() {
      const query = searchInput.value.toLowerCase().trim();
      const filter = statusFilter.value;

      eventList.innerHTML = "";

      const filtered = events.filter(event => {
        const matchesQuery =
          event.title.toLowerCase().includes(query) ||
          event.notes.toLowerCase().includes(query);
        const matchesFilter = filter === "all" || event.status === filter;
        return matchesQuery && matchesFilter;
      });

      if (!filtered.length) {
        eventList.innerHTML = `<div class="muted">No matching events.</div>`;
        return;
      }

      filtered.forEach(event => {
        const div = document.createElement("div");
        div.className = "item";
        div.innerHTML = `
          <div>
            <strong>${event.title}</strong>
            <small>${event.notes || "No notes provided."} · Value: ${event.value}</small>
          </div>
          <span class="badge ${event.status}">${statusLabel(event.status)}</span>
        `;
        eventList.appendChild(div);
      });
    }

    function updateMetric(el, deltaEl, current, previous, suffix = "") {
      el.textContent = suffix === "%" ? `${current.toFixed(1)}%` : `${Math.round(current)}${suffix}`;
      const delta = current - previous;
      const sign = delta >= 0 ? "+" : "";
      deltaEl.textContent = `${sign}${delta.toFixed(suffix === "%" ? 1 : 0)} since last update`;
      deltaEl.style.color = delta >= 0 ? "#86efac" : "#fca5a5";
    }

    function updateDashboard() {
      previousMetrics = { ...metrics };

      metrics.activeUsers += Math.floor(Math.random() * 40 - 10);
      metrics.requestsPerMin += Math.floor(Math.random() * 60 - 20);
      metrics.errorRate += (Math.random() * 1.2 - 0.4);
      metrics.avgLatency += Math.floor(Math.random() * 30 - 10);

      metrics.activeUsers = Math.max(0, metrics.activeUsers);
      metrics.requestsPerMin = Math.max(0, metrics.requestsPerMin);
      metrics.errorRate = Math.min(20, Math.max(0, metrics.errorRate));
      metrics.avgLatency = Math.max(20, metrics.avgLatency);

      updateMetric(activeUsersEl, activeUsersDeltaEl, metrics.activeUsers, previousMetrics.activeUsers);
      updateMetric(requestsPerMinEl, requestsDeltaEl, metrics.requestsPerMin, previousMetrics.requestsPerMin);
      updateMetric(errorRateEl, errorDeltaEl, metrics.errorRate, previousMetrics.errorRate, "%");
      updateMetric(avgLatencyEl, latencyDeltaEl, metrics.avgLatency, previousMetrics.avgLatency, " ms");

      trafficData.push(Math.floor(Math.random() * 100) + 20);
      trafficData.shift();
      chart.update();

      renderEvents();
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const title = document.getElementById("title").value.trim();
      const status = document.getElementById("status").value;
      const value = Number(document.getElementById("value").value);
      const notes = document.getElementById("notes").value.trim();

      if (!title || Number.isNaN(value)) return;

      events.unshift({
        title,
        status,
        value,
        notes
      });

      eventForm.reset();
      renderEvents();
    });

    searchInput.addEventListener("input", renderEvents);
    statusFilter.addEventListener("change", renderEvents);

    renderEvents();
    updateDashboard();
    setInterval(updateDashboard, 2000);
  </script>
</body>
