          </label>

          <label>
            User Name
            <input type="text" id="userName" placeholder="Enter user name" required />
          </label>

          <label>
            Value
            <input type="number" id="eventValue" placeholder="Enter value" min="1" required />
          </label>

          <label>
            Notes
            <textarea id="notes" placeholder="Optional notes"></textarea>
          </label>

          <button type="submit">Add Event</button>
        </form>

        <div class="log" id="eventLog"></div>
      </div>
    </section>
  </main>

  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const systemLoadEl = document.getElementById("systemLoad");

    const activeUsersChangeEl = document.getElementById("activeUsersChange");
    const requestsChangeEl = document.getElementById("requestsChange");
    const errorChangeEl = document.getElementById("errorChange");
    const loadChangeEl = document.getElementById("loadChange");

    const eventForm = document.getElementById("eventForm");
    const eventLog = document.getElementById("eventLog");

    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = Array.from({ length: 20 }, (_, i) => `T-${19 - i}`);
    const trafficData = labels.map(() => Math.floor(Math.random() * 100));

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 2,
          pointHoverRadius: 5
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          }
        }
      }
    });

    let prevStats = {
      activeUsers: 0,
      requestsPerMin: 0,
      errorRate: 0,
      systemLoad: 0
    };

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function updateStats() {
      const activeUsers = randomInt(120, 980);
      const requestsPerMin = randomInt(300, 2400);
      const errorRate = randomInt(0, 12);
      const systemLoad = randomInt(20, 95);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
      errorRateEl.textContent = `${errorRate}%`;
      systemLoadEl.textContent = `${systemLoad}%`;

      const activeDelta = activeUsers - prevStats.activeUsers;
      const reqDelta = requestsPerMin - prevStats.requestsPerMin;
      const errorDelta = errorRate - prevStats.errorRate;
      const loadDelta = systemLoad - prevStats.systemLoad;

      activeUsersChangeEl.textContent = `${activeDelta >= 0 ? "+" : ""}${activeDelta} since last update`;
      requestsChangeEl.textContent = `${reqDelta >= 0 ? "+" : ""}${reqDelta} since last update`;
      errorChangeEl.textContent = `${errorDelta >= 0 ? "+" : ""}${errorDelta}% since last update`;
      loadChangeEl.textContent = Math.abs(loadDelta) < 5 ? "Stable" : `${loadDelta >= 0 ? "+" : ""}${loadDelta}% since last update`;

      prevStats = { activeUsers, requestsPerMin, errorRate, systemLoad };

      trafficData.push(requestsPerMin / 20 + randomInt(-10, 10));
      trafficData.shift();
      trafficChart.update();
    }

    function addLogItem(type, user, value, notes) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.innerHTML = `
        <strong>${type.toUpperCase()}</strong> — ${user} (${value})
        <small>${notes || "No notes provided"} • ${new Date().toLocaleTimeString()}</small>
      `;
      eventLog.prepend(item);
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const type = document.getElementById("eventType").value;
      const user = document.getElementById("userName").value.trim();
      const value = document.getElementById("eventValue").value;
      const notes = document.getElementById("notes").value.trim();

      if (!user || !value) return;

      addLogItem(type, user, value, notes);

      eventForm.reset();
      document.getElementById("eventType").value = "signup";
    });

    updateStats();
    setInterval(updateStats, 1000);
  </script>
</body>
</html>
