    .chart-wrap {
      height: 360px;
    }

    form {
      display: grid;
      gap: 14px;
    }

    label {
      font-size: 14px;
      color: var(--muted);
    }

    input, select, button {
      width: 100%;
      padding: 12px 14px;
      border-radius: 10px;
      border: 1px solid var(--border);
      background: #0b1220;
      color: var(--text);
      font-size: 14px;
    }

    input:focus, select:focus {
      outline: 2px solid rgba(56, 189, 248, 0.35);
      border-color: var(--accent);
    }

    button {
      background: var(--accent);
      color: #00111a;
