          <div class="label">Average</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Entries</div>
          <div class="value" id="entryCount">0</div>
        </div>
      </div>

      <div class="toolbar">
        <button id="addRandomBtn">Add Random Data</button>
        <button id="toggleAutoBtn" class="secondary">Pause Auto Update</button>
        <button id="resetBtn" class="secondary">Reset</button>
      </div>

      <div class="chart-wrap">
        <canvas id="liveChart"></canvas>
      </div>
    </section>

    <aside class="card">
      <h2>Data Entry Form</h2>
      <form id="dataForm">
        <div>
          <label for="name">Name</label>
          <input type="text" id="name" placeholder="Enter a label" required />
        </div>

        <div>
          <label for="value">Value</label>
          <input type="number" id="value" placeholder="Enter a number" required />
        </div>

        <div>
          <label for="category">Category</label>
          <select id="category" required>
            <option value="">Select category</option>
            <option value="Sales">Sales</option>
            <option value="Traffic">Traffic</option>
            <option value="Users">Users</option>
          </select>
        </div>

        <button type="submit">Submit Data</button>
        <div id="formMessage" class="message"></div>
      </form>

      <div class="log">
        <h2>Submission Log</h2>
        <div id="logList"></div>
      </div>
