  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    const labels = ['T1', 'T2', 'T3', 'T4', 'T5'];
    const dataPoints = [12, 19, 8, 15, 22];

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const entryCountEl = document.getElementById('entryCount');
    const formMessageEl = document.getElementById('formMessage');
    const logListEl = document.getElementById('logList');

    let autoUpdate = true;
    let tick = 6;

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [...labels],
        datasets: [{
          label: 'Live Metric',
          data: [...dataPoints],
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: '#cbd5e1' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            ticks: { color: '#cbd5e1' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    function updateStats() {
      const values = chart.data.datasets[0].data;
      const current = values[values.length - 1] ?? 0;
      const avg = values.reduce((a, b) => a + b, 0) / values.length;

      currentValueEl.textContent = current.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      entryCountEl.textContent = values.length;
    }

    function addDataPoint(label, value) {
      chart.data.labels.push(label);
      chart.data.datasets[0].data.push(value);

      if (chart.data.labels.length > 12) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }

      chart.update();
      updateStats();
    }

    function addLogEntry(text) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = text;
      logListEl.prepend(item);
    }

    function showMessage(text, type) {
      formMessageEl.textContent = text;
      formMessageEl.className = `message ${type}`;
      setTimeout(() => {
        formMessageEl.textContent = '';
        formMessageEl.className = 'message';
      }, 2500);
    }

    document.getElementById('dataForm').addEventListener('submit', (e) => {
      e.preventDefault();

      const name = document.getElementById('name').value.trim();
      const value = Number(document.getElementById('value').value);
      const category = document.getElementById('category').value;

      if (!name || !category || Number.isNaN(value)) {
        showMessage('Please fill in all fields correctly.', 'error');
        return;
      }

      addDataPoint(name, value);
      addLogEntry(`[${category}] ${name}: ${value}`);
      showMessage('Data submitted successfully.', 'success');

      e.target.reset();
    });

    document.getElementById('addRandomBtn').addEventListener('click', () => {
      const randomValue = Math.floor(Math.random() * 100);
      addDataPoint(`T${tick++}`, randomValue);
      addLogEntry(`Auto-added data point: ${randomValue}`);
    });

    document.getElementById('toggleAutoBtn').addEventListener('click', (e) => {
      autoUpdate = !autoUpdate;
      e.target.textContent = autoUpdate ? 'Pause Auto Update' : 'Resume Auto Update';
    });

    document.getElementById('resetBtn').addEventListener('click', () => {
      chart.data.labels = [...labels];
      chart.data.datasets[0].data = [...dataPoints];
      chart.update();
      updateStats();
      logListEl.innerHTML = '';
      tick = 6;
      addLogEntry('Dashboard reset.');
    });

    setInterval(() => {
      if (!autoUpdate) return;
      const randomValue = Math.floor(Math.random() * 100);
      addDataPoint(`T${tick++}`, randomValue);
      addLogEntry(`Real-time update: ${randomValue}`);
    }, 3000);

    updateStats();
  </script>
</body>
</html>
