        <table>
          <thead>
            <tr>
              <th>Label</th>
              <th>Value</th>
              <th>Category</th>
              <th>Timestamp</th>
            </tr>
          </thead>
          <tbody id="dataTableBody"></tbody>
        </table>
      </section>
    </main>
  </div>

  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    const data = {
      labels: [],
      values: [],
      categories: [],
      timestamps: []
    };

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: data.labels,
        datasets: [{
          label: 'Metric Value',
          data: data.values,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.05)' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    const statusText = document.getElementById('statusText');
    const latestValue = document.getElementById('latestValue');
    const pointCount = document.getElementById('pointCount');
    const dataTableBody = document.getElementById('dataTableBody');

    const toggleBtn = document.getElementById('toggleBtn');
    const addRandomBtn = document.getElementById('addRandomBtn');
    const resetBtn = document.getElementById('resetBtn');
    const dataForm = document.getElementById('dataForm');

    let running = true;
    let autoInterval = null;

    function updateUI() {
      chart.update();
      latestValue.textContent = data.values[data.values.length - 1] ?? 0;
      pointCount.textContent = data.values.length;
      renderTable();
    }

    function addDataPoint(label, value, category) {
      const timestamp = new Date().toLocaleTimeString();

      data.labels.push(label);
      data.values.push(value);
      data.categories.push(category);
      data.timestamps.push(timestamp);

      // Keep last 20 points for readability
      if (data.labels.length > 20) {
        data.labels.shift();
        data.values.shift();
        data.categories.shift();
        data.timestamps.shift();
      }

      updateUI();
    }

    function renderTable() {
      dataTableBody.innerHTML = '';

      for (let i = data.labels.length - 1; i >= 0; i--) {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${data.labels[i]}</td>
          <td>${data.values[i]}</td>
          <td><span class="badge">${data.categories[i]}</span></td>
          <td>${data.timestamps[i]}</td>
        `;
        dataTableBody.appendChild(row);
      }
    }

    function generateRandomPoint() {
      const now = new Date();
      const label = now.toLocaleTimeString();
      const value = +(Math.random() * 100).toFixed(1);
      const categories = ['A', 'B', 'C'];
      const category = categories[Math.floor(Math.random() * categories.length)];
      addDataPoint(label, value, category);
    }

    function startAutoUpdates() {
      autoInterval = setInterval(() => {
        if (running) generateRandomPoint();
      }, 2000);
    }

    toggleBtn.addEventListener('click', () => {
      running = !running;
      statusText.textContent = running ? 'Running' : 'Paused';
      toggleBtn.textContent = running ? 'Pause Updates' : 'Resume Updates';
    });

    addRandomBtn.addEventListener('click', generateRandomPoint);

    resetBtn.addEventListener('click', () => {
      data.labels.length = 0;
      data.values.length = 0;
      data.categories.length = 0;
      data.timestamps.length = 0;
      updateUI();
    });

    dataForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = document.getElementById('labelInput').value.trim();
      const value = parseFloat(document.getElementById('valueInput').value);
      const category = document.getElementById('categoryInput').value;

      if (!label || Number.isNaN(value)) return;

      addDataPoint(label, value, category);
      dataForm.reset();
    });

    // Seed initial data
    for (let i = 0; i < 5; i++) {
      generateRandomPoint();
    }

    startAutoUpdates();
  </script>
</body>
</html>
```

