  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const recordCountEl = document.getElementById("recordCount");
    const dataTableBody = document.getElementById("dataTableBody");
    const liveClock = document.getElementById("liveClock");

    const toggleLiveBtn = document.getElementById("toggleLiveBtn");
    const addRandomBtn = document.getElementById("addRandomBtn");
    const resetBtn = document.getElementById("resetBtn");

    const entryForm = document.getElementById("entryForm");
    const nameInput = document.getElementById("name");
    const valueInput = document.getElementById("value");
    const categoryInput = document.getElementById("category");
    const nameError = document.getElementById("nameError");
    const valueError = document.getElementById("valueError");

    let data = [];
    let live = true;
    const maxPoints = 20;

    function nowTime() {
      return new Date().toLocaleTimeString();
    }

    function randomValue() {
      return Math.floor(Math.random() * 100);
    }

    function statusFromValue(value) {
      if (value >= 70) return "bad";
      if (value >= 40) return "warn";
      return "ok";
    }

    function addDataPoint(value, label = nowTime(), status = statusFromValue(value)) {
      data.push({ label, value, status });
      if (data.length > maxPoints) data.shift();
      updateDashboard();
    }

    function updateDashboard() {
      const values = data.map(d => d.value);
      const current = values.length ? values[values.length - 1] : 0;
      const avg = values.length ? (values.reduce((a, b) => a + b, 0) / values.length) : 0;

      currentValueEl.textContent = current.toFixed(0);
      averageValueEl.textContent = avg.toFixed(1);
      recordCountEl.textContent = data.length;

      renderTable();
      renderChart();
    }

    function renderTable() {
      dataTableBody.innerHTML = data.slice().reverse().map(item => `
        <tr>
          <td>${item.label}</td>
          <td>${item.value}</td>
          <td><span class="status ${item.status}">${item.status.toUpperCase()}</span></td>
        </tr>
      `).join("");
    }

    function renderChart() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, w, h);

      // Grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (h / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }

      if (data.length === 0) return;

      const padding = 30;
      const chartW = w - padding * 2;
      const chartH = h - padding * 2;
      const maxVal = Math.max(100, ...data.map(d => d.value));
      const stepX = data.length > 1 ? chartW / (data.length - 1) : chartW;

      // Line
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = padding + chartH - (point.value / maxVal) * chartH;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });
      ctx.stroke();

      // Points
      data.forEach((point, index) => {
        const x = padding + index * stepX;
        const y = padding + chartH - (point.value / maxVal) * chartH;

        ctx.fillStyle = point.status === "bad" ? "#ef4444" : point.status === "warn" ? "#facc15" : "#22c55e";
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function updateClock() {
      liveClock.textContent = new Date().toLocaleTimeString();
    }

    function validateForm() {
      let valid = true;
      nameError.textContent = "";
      valueError.textContent = "";

      if (!nameInput.value.trim()) {
        nameError.textContent = "Name is required.";
        valid = false;
      }

      const value = Number(valueInput.value);
      if (valueInput.value.trim() === "" || Number.isNaN(value)) {
        valueError.textContent = "Please enter a valid number.";
        valid = false;
      }

      return valid;
    }

    entryForm.addEventListener("submit", (e) => {
      e.preventDefault();
      if (!validateForm()) return;

      const value = Number(valueInput.value);
      const category = categoryInput.value;

      addDataPoint(value, nameInput.value.trim(), category);

      entryForm.reset();
      nameInput.focus();
    });

    toggleLiveBtn.addEventListener("click", () => {
      live = !live;
      toggleLiveBtn.textContent = live ? "Pause Live Updates" : "Resume Live Updates";
    });

    addRandomBtn.addEventListener("click", () => {
      addDataPoint(randomValue());
    });

    resetBtn.addEventListener("click", () => {
      data = [];
      updateDashboard();
    });

    // Seed initial data
    for (let i = 0; i < 8; i++) {
      addDataPoint(randomValue(), `T-${8 - i}`);
    }

    // Live updates
    setInterval(() => {
      updateClock();
      if (live) addDataPoint(randomValue());
    }, 1000);

    updateClock();
    updateDashboard();
  </script>
</body>
</html>
