</head>
<body>
  <div class="dashboard">
    <aside class="sidebar">
      <h1>Live Dashboard</h1>
      <p>Real-time visualization and form-driven data entry.</p>

      <div class="card">
        <h2>Metrics</h2>
        <div class="metric">
          <span>Current Value</span>
          <strong id="currentValue">0</strong>
        </div>
        <div class="metric">
          <span>Average</span>
          <strong id="averageValue">0</strong>
        </div>
        <div class="metric">
          <span>Data Points</span>
          <strong id="dataCount">0</strong>
        </div>
      </div>

      <div class="card">
        <h2>Controls</h2>
        <div class="btn-row">
          <button class="btn-primary" id="toggleStream">Pause Stream</button>
          <button class="btn-secondary" id="resetData">Reset</button>
        </div>
      </div>
    </aside>

    <main class="main">
      <div class="topbar">
        <div>
          <h1 style="margin:0;">Analytics Overview</h1>
          <p style="margin:6px 0 0; color: var(--muted);">Streaming data updates every second.</p>
        </div>
        <div class="status" id="streamStatus">
          <span class="status-dot"></span>
          Live
        </div>
      </div>

      <div class="grid">
        <section class="panel">
          <h2>Real-Time Chart</h2>
          <canvas id="liveChart"></canvas>
        </section>

        <section class="panel">
          <h2>Add Data Point</h2>
          <form id="dataForm">
            <div>
              <label for="labelInput">Label</label>
              <input type="text" id="labelInput" placeholder="e.g. 10:45 AM" required />
            </div>

            <div>
              <label for="valueInput">Value</label>
              <input type="number" id="valueInput" placeholder="Enter numeric value" required />
            </div>

            <div>
              <label for="categoryInput">Category</label>
              <select id="categoryInput">
                <option value="manual">Manual</option>
                <option value="sensor">Sensor</option>
                <option value="api">API</option>
              </select>
            </div>

            <button type="submit" class="btn-primary">Add Point</button>
          </form>

          <div class="log" id="eventLog"></div>
        </section>
      </div>
    </main>
  </div>

  <script>
    const ctx = document.getElementById('liveChart').getContext('2d');

    const labels = ['1', '2', '3', '4', '5'];
    const values = [12, 19, 8, 15, 22];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Value',
          data: values,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointBackgroundColor: '#22c55e'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(255,255,255,0.06)' }
          }
        },
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        }
      }
    });

    const currentValueEl = document.getElementById('currentValue');
    const averageValueEl = document.getElementById('averageValue');
    const dataCountEl = document.getElementById('dataCount');
    const eventLog = document.getElementById('eventLog');
    const dataForm = document.getElementById('dataForm');
    const toggleStreamBtn = document.getElementById('toggleStream');
    const resetDataBtn = document.getElementById('resetData');
    const streamStatus = document.getElementById('streamStatus');

    let streaming = true;
    let pointIndex = 6;

    function updateMetrics() {
      const data = chart.data.datasets[0].data;
      const current = data[data.length - 1];
      const average = data.reduce((sum, val) => sum + val, 0) / data.length;

      currentValueEl.textContent = current.toFixed(2);
      averageValueEl.textContent = average.toFixed(2);
      dataCountEl.textContent = data.length;
    }

    function logEvent(message) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLog.prepend(item);
    }

    function addDataPoint(label, value, source = 'stream') {
      chart.data.labels.push(label);
      chart.data.datasets[0].data.push(value);

      if (chart.data.labels.length > 20) {
        chart.data.labels.shift();
        chart.data.datasets[0].data.shift();
      }

      chart.update();
      updateMetrics();
      logEvent(`Added ${source} point: ${label} → ${value}`);
    }

    function generateRandomValue() {
      const last = chart.data.datasets[0].data.at(-1);
      const change = (Math.random() - 0.5) * 10;
      return Math.max(0, last + change);
    }

    const streamInterval = setInterval(() => {
      if (!streaming) return;
      const value = generateRandomValue();
      addDataPoint(pointIndex.toString(), value, 'stream');
      pointIndex++;
    }, 1000);

    dataForm.addEventListener('submit', (e) => {
      e.preventDefault();

      const label = document.getElementById('labelInput').value.trim();
      const value = parseFloat(document.getElementById('valueInput').value);
      const category = document.getElementById('categoryInput').value;

      if (!label || Number.isNaN(value)) return;

      addDataPoint(label, value, category);

      dataForm.reset();
    });

    toggleStreamBtn.addEventListener('click', () => {
      streaming = !streaming;
      toggleStreamBtn.textContent = streaming ? 'Pause Stream' : 'Resume Stream';
      streamStatus.innerHTML = streaming
        ? '<span class="status-dot"></span> Live'
        : '<span class="status-dot" style="background:#f59e0b; box-shadow:0 0 10px #f59e0b;"></span> Paused';

      logEvent(streaming ? 'Stream resumed' : 'Stream paused');
    });

    resetDataBtn.addEventListener('click', () => {
      chart.data.labels = ['1', '2', '3', '4', '5'];
      chart.data.datasets[0].data = [12, 19, 8, 15, 22];
      pointIndex = 6;
      chart.update();
      updateMetrics();
      eventLog.innerHTML = '';
      logEvent('Dashboard reset');
    });

    updateMetrics();
    logEvent('Dashboard initialized');
  </script>
</body>
</html>
