    function updateClock() {
      clockEl.textContent = new Date().toLocaleTimeString();
    }

    function addLog(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.innerHTML = `${message}<small>${new Date().toLocaleTimeString()}</small>`;
      activityLog.prepend(item);
    }

    function updateStats() {
      const latest = dataPoints[dataPoints.length - 1] ?? 0;
      const avg = dataPoints.reduce((a, b) => a + b, 0) / dataPoints.length;

      latestValueEl.textContent = latest.toFixed(2);
      avgValueEl.textContent = avg.toFixed(2);
      countValueEl.textContent = dataPoints.length;
