      dataPoints.push(value);

      if (labels.length > 20) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();
      updateStats();
      addLog(`Added point: <strong>${label}</strong> = ${value}`);
    }

    function randomPoint() {
      const nextLabel = (labels.length + 1).toString();
      const value = Math.floor(Math.random() * 30) + 5;
      addDataPoint(nextLabel, value);
    }

    toggleBtn.addEventListener("click", () => {
      isLive = !isLive;
      toggleBtn.textContent = isLive ? "Pause Updates" : "Resume Updates";
      document.getElementById("liveStatus").textContent = isLive
        ? "Live updates enabled"
        : "Live updates paused";
      addLog(isLive ? "Live updates resumed" : "Live updates paused");
    });

    addRandomBtn.addEventListener("click", randomPoint);

    resetBtn.addEventListener("click", () => {
      dataPoints = [12, 19, 8, 15, 22, 18];
      labels = ["1", "2", "3", "4", "5", "6"];
      chart.data.labels = labels;
      chart.data.datasets[0].data = dataPoints;
      chart.update();
      updateStats();
      activityLog.innerHTML = "";
      addLog("Dashboard reset to default data");
