<body>
  <header>
    <h1>Real-Time Analytics Dashboard</h1>
    <p>Live data visualization, interactive controls, and form-based data entry.</p>
  </header>

  <main class="dashboard">
    <section class="card">
      <h2>Live Chart</h2>

      <div class="stats">
        <div class="stat">
          <div class="label">Current Value</div>
          <div class="value" id="currentValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Average</div>
          <div class="value" id="averageValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Data Points</div>
          <div class="value" id="pointCount">0</div>
        </div>
      </div>

      <div class="controls">
        <button id="toggleLiveBtn" class="success">Pause Live Updates</button>
        <button id="resetBtn" class="danger">Reset Data</button>
        <button id="addRandomBtn" class="secondary">Add Random Point</button>
      </div>

      <div class="chart-wrap">
        <canvas id="liveChart"></canvas>
      </div>

      <div class="status" id="statusText">Live updates running...</div>
    </section>

    <aside class="card">
      <h2>Add Data Point</h2>
      <form id="dataForm">
        <div class="form-row">
          <label for="labelInput">Label</label>
          <input id="labelInput" type="text" placeholder="e.g. 10:30 AM" required />
        </div>

        <div class="form-row">
          <label for="valueInput">Value</label>
          <input id="valueInput" type="number" placeholder="Enter a number" required />
        </div>

        <div class="form-row">
          <label for="categoryInput">Category</label>
          <select id="categoryInput">
            <option value="manual">Manual</option>
            <option value="sensor">Sensor</option>
            <option value="api">API</option>
          </select>
        </div>

        <button type="submit">Add to Dashboard</button>
      </form>

      <div class="table-wrap">
        <h2>Recent Entries</h2>
        <table>
          <thead>
            <tr>
              <th>Label</th>
              <th>Value</th>
              <th>Category</th>
            </tr>
          </thead>
          <tbody id="dataTableBody"></tbody>
        </table>
      </div>
    </aside>
  </main>

  <script>
    const ctx = document.getElementById("liveChart").getContext("2d");

    const labels = [];
    const values = [];
    const categories = [];
    const maxPoints = 20;

    let liveRunning = true;
    let liveInterval = null;

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const pointCountEl = document.getElementById("pointCount");
    const statusTextEl = document.getElementById("statusText");
    const dataTableBody = document.getElementById("dataTableBody");

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Metric Value",
          data: values,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    function updateStats() {
      const count = values.length;
      const current = count ? values[count - 1] : 0;
      const avg = count ? (values.reduce((a, b) => a + b, 0) / count).toFixed(2) : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      pointCountEl.textContent = count;
    }

    function updateTable() {
      dataTableBody.innerHTML = "";

      const recent = labels.map((label, i) => ({
        label,
        value: values[i],
        category: categories[i]
      })).slice(-8).reverse();

      recent.forEach(item => {
        const row = document.createElement("tr");
        row.innerHTML = `
          <td>${item.label}</td>
          <td>${item.value}</td>
          <td>${item.category}</td>
        `;
        dataTableBody.appendChild(row);
      });
    }

    function addDataPoint(label, value, category = "manual") {
      labels.push(label);
      values.push(Number(value));
      categories.push(category);

      if (labels.length > maxPoints) {
        labels.shift();
        values.shift();
        categories.shift();
      }

      chart.update();
      updateStats();
      updateTable();
    }

    function addRandomPoint() {
      const now = new Date();
      const label = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
      const value = Math.floor(Math.random() * 100);
      addDataPoint(label, value, "sensor");
    }

    function startLiveUpdates() {
      if (liveInterval) clearInterval(liveInterval);

      liveInterval = setInterval(() => {
        if (liveRunning) addRandomPoint();
      }, 2000);
    }

    document.getElementById("toggleLiveBtn").addEventListener("click", () => {
      liveRunning = !liveRunning;
      document.getElementById("toggleLiveBtn").textContent = liveRunning ? "Pause Live Updates" : "Resume Live Updates";
      statusTextEl.textContent = liveRunning ? "Live updates running..." : "Live updates paused.";
    });

    document.getElementById("resetBtn").addEventListener("click", () => {
      labels.length = 0;
      values.length = 0;
      categories.length = 0;
      chart.update();
      updateStats();
      updateTable();
      statusTextEl.textContent = "Data reset.";
    });

    document.getElementById("addRandomBtn").addEventListener("click", addRandomPoint);

    document.getElementById("dataForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const label = document.getElementById("labelInput").value.trim();
      const value = document.getElementById("valueInput").value.trim();
      const category = document.getElementById("categoryInput").value;

      if (!label || value === "") return;

      addDataPoint(label, value, category);

      e.target.reset();
      statusTextEl.textContent = `Added new ${category} data point.`;
    });

    // Seed initial data
    for (let i = 0; i < 5; i++) {
      addRandomPoint();
    }

    startLiveUpdates();
  </script>
</body>
</html>
```

