  <script>
    const ctx = document.getElementById("trafficChart").getContext("2d");

    const state = {
      labels: [],
      requests: [],
      users: [],
      errors: [],
      events: []
    };

    const maxPoints = 50;

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function formatTime(date = new Date()) {
      return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    }

    function getCurrentMetricData(type) {
      return state[type];
    }

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels: state.labels,
        datasets: [{
          label: "Requests",
          data: state.requests,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    function updateChart() {
      const metricType = document.getElementById("metricType").value;
      const timeRange = parseInt(document.getElementById("timeRange").value, 10);

      chart.data.labels = state.labels.slice(-timeRange);
      chart.data.datasets[0].label = metricType.charAt(0).toUpperCase() + metricType.slice(1);
      chart.data.datasets[0].data = state[metricType].slice(-timeRange);

      const colors = {
        requests: "#38bdf8",
        users: "#22c55e",
        errors: "#ef4444"
      };

      chart.data.datasets[0].borderColor = colors[metricType];
      chart.data.datasets[0].backgroundColor = colors[metricType] + "26";
      chart.update();
    }

    function updateMetrics() {
      const latestRequests = state.requests.at(-1) ?? 0;
      const latestUsers = state.users.at(-1) ?? 0;
      const latestErrors = state.errors.at(-1) ?? 0;

      document.getElementById("activeUsers").textContent = latestUsers;
      document.getElementById("requestsPerMin").textContent = latestRequests;
      document.getElementById("errorRate").textContent = `${latestErrors}%`;

      const health = latestErrors < 3 ? "Good" : latestErrors < 7 ? "Warning" : "Critical";
      document.getElementById("systemHealth").textContent = health;

      document.getElementById("activeUsersTrend").innerHTML = `<span class="trend-up">Live update: ${latestUsers}</span>`;
      document.getElementById("requestsTrend").innerHTML = `<span class="trend-up">Live update: ${latestRequests}</span>`;
      document.getElementById("errorTrend").innerHTML = `<span class="${latestErrors < 5 ? "trend-up" : "trend-down"}">Live update: ${latestErrors}%</span>`;
      document.getElementById("healthTrend").innerHTML = health === "Good"
        ? `<span class="trend-up">Stable</span>`
        : health === "Warning"
          ? `<span style="color:#fbbf24;">Needs attention</span>`
          : `<span class="trend-down">Immediate action required</span>`;
    }

    function addEventRow(event) {
      const tbody = document.getElementById("eventsTable");
      const row = document.createElement("tr");
      row.innerHTML = `
        <td>${event.time}</td>
        <td>${event.name}</td>
        <td><span class="status ${event.category === "errors" ? "bad" : event.category === "users" ? "ok" : "warn"}">${event.category}</span></td>
        <td>${event.value}</td>
      `;
      tbody.prepend(row);

      while (tbody.children.length > 8) {
        tbody.removeChild(tbody.lastChild);
      }
    }

    function pushDataPoint(label, requests, users, errors) {
      state.labels.push(label);
      state.requests.push(requests);
      state.users.push(users);
      state.errors.push(errors);

      if (state.labels.length > maxPoints) {
        state.labels.shift();
        state.requests.shift();
        state.users.shift();
        state.errors.shift();
      }

      updateMetrics();
      updateChart();
    }

    function generateLiveData() {
      const label = formatTime();
      const requests = randomInt(50, 200);
      const users = randomInt(100, 500);
      const errors = randomInt(0, 10);

      pushDataPoint(label, requests, users, errors);
    }

    document.getElementById("metricType").addEventListener("change", updateChart);
    document.getElementById("timeRange").addEventListener("change", updateChart);

    let autoUpdateInterval = setInterval(generateLiveData, 2000);

    document.getElementById("autoUpdate").addEventListener("change", (e) => {
      if (autoUpdateInterval) {
        clearInterval(autoUpdateInterval);
        autoUpdateInterval = null;
      }

      if (e.target.value === "on") {
        autoUpdateInterval = setInterval(generateLiveData, 2000);
      }
    });

    document.getElementById("eventForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("eventName").value.trim();
      const value = Number(document.getElementById("eventValue").value);
      const category = document.getElementById("eventCategory").value;

      if (!name || Number.isNaN(value)) return;

      const event = {
        time: formatTime(),
        name,
        value,
        category
      };

      state.events.unshift(event);
      addEventRow(event);

      // Use form submission to influence live data
      const latestRequests = category === "requests" ? value : (state.requests.at(-1) ?? 100);
      const latestUsers = category === "users" ? value : (state.users.at(-1) ?? 200);
      const latestErrors = category === "errors" ? value : (state.errors.at(-1) ?? 1);

      pushDataPoint(formatTime(), latestRequests, latestUsers, latestErrors);

      e.target.reset();
    });

    document.getElementById("resetData").addEventListener("click", () => {
      state.labels = [];
      state.requests = [];
      state.users = [];
      state.errors = [];
      state.events = [];

      document.getElementById("eventsTable").innerHTML = "";
      updateMetrics();
      updateChart();
    });

    // Seed initial data
    for (let i = 0; i < 10; i++) {
      generateLiveData();
    }
  </script>
</body>
</html>
