</head>
<body>
  <header>
    <h1>Real-Time Analytics Dashboard</h1>
    <p>Live data visualization, KPI cards, and interactive form handling</p>
  </header>

  <main class="container">
    <section class="cards">
      <div class="card">
        <div class="label">Active Users</div>
        <div class="value" id="activeUsers">0</div>
        <div class="trend good" id="activeUsersTrend">+0% from last minute</div>
      </div>
      <div class="card">
        <div class="label">Requests / Min</div>
        <div class="value" id="requestsPerMin">0</div>
        <div class="trend warn" id="requestsTrend">Stable</div>
      </div>
      <div class="card">
        <div class="label">Error Rate</div>
        <div class="value" id="errorRate">0%</div>
        <div class="trend bad" id="errorTrend">No incidents</div>
      </div>
      <div class="card">
        <div class="label">Avg. Response Time</div>
        <div class="value" id="responseTime">0 ms</div>
        <div class="trend good" id="responseTrend">Healthy</div>
      </div>
    </section>

    <section class="grid">
      <div class="panel">
        <h2>Live Traffic</h2>
        <div class="chart-wrap">
          <canvas id="trafficChart"></canvas>
        </div>
      </div>

      <div class="panel">
        <h2>Controls & Form</h2>
        <form id="settingsForm" class="controls">
          <div class="field">
            <label for="region">Region</label>
            <select id="region" name="region">
              <option value="global">Global</option>
              <option value="us-east">US East</option>
              <option value="eu-west">EU West</option>
              <option value="ap-south">AP South</option>
            </select>
          </div>

          <div class="field">
            <label for="threshold">Alert Threshold</label>
            <input id="threshold" name="threshold" type="number" min="1" max="100" value="75" />
          </div>

          <div class="field">
            <label for="note">Admin Note</label>
            <textarea id="note" name="note" rows="4" placeholder="Enter a note..."></textarea>
          </div>

          <button type="submit">Save Settings</button>
        </form>

        <div class="small" style="margin-top: 12px;">
          Current filter: <span id="currentRegion">global</span> | Threshold: <span id="currentThreshold">75</span>
        </div>

        <div class="log" id="eventLog"></div>
      </div>
    </section>
  </main>

  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const responseTimeEl = document.getElementById("responseTime");

    const activeUsersTrendEl = document.getElementById("activeUsersTrend");
    const requestsTrendEl = document.getElementById("requestsTrend");
    const errorTrendEl = document.getElementById("errorTrend");
    const responseTrendEl = document.getElementById("responseTrend");

    const currentRegionEl = document.getElementById("currentRegion");
    const currentThresholdEl = document.getElementById("currentThreshold");
    const eventLogEl = document.getElementById("eventLog");

    const regionSelect = document.getElementById("region");
    const thresholdInput = document.getElementById("threshold");
    const settingsForm = document.getElementById("settingsForm");

    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
    const trafficData = labels.map(() => Math.floor(Math.random() * 100));

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointHoverRadius: 5
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          }
        }
      }
    });

    let lastActiveUsers = 0;
    let lastRequests = 0;
    let lastErrorRate = 0;
    let lastResponseTime = 0;

    function addLog(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      eventLogEl.prepend(item);
    }

    function updateDashboard() {
      const activeUsers = Math.floor(500 + Math.random() * 1500);
      const requestsPerMin = Math.floor(1000 + Math.random() * 4000);
      const errorRate = +(Math.random() * 5).toFixed(2);
      const responseTime = Math.floor(80 + Math.random() * 220);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
      errorRateEl.textContent = `${errorRate}%`;
      responseTimeEl.textContent = `${responseTime} ms`;

      const activeDelta = lastActiveUsers ? (((activeUsers - lastActiveUsers) / lastActiveUsers) * 100).toFixed(1) : 0;
      activeUsersTrendEl.textContent = `${activeDelta >= 0 ? "+" : ""}${activeDelta}% from last update`;

      const reqDelta = lastRequests ? (((requestsPerMin - lastRequests) / lastRequests) * 100).toFixed(1) : 0;
      requestsTrendEl.textContent = `${reqDelta >= 0 ? "+" : ""}${reqDelta}% from last update`;

      errorTrendEl.textContent = errorRate > 3 ? "High error rate detected" : "No incidents";
      responseTrendEl.textContent = responseTime > 220 ? "Slow response" : "Healthy";

      lastActiveUsers = activeUsers;
      lastRequests = requestsPerMin;
      lastErrorRate = errorRate;
      lastResponseTime = responseTime;

      trafficData.push(requestsPerMin / 50);
      trafficData.shift();
      trafficChart.update();

      addLog(`Live metrics updated for region: ${regionSelect.value}`);
    }

    settingsForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const region = regionSelect.value;
      const threshold = thresholdInput.value;
      const note = document.getElementById("note").value.trim();

      currentRegionEl.textContent = region;
      currentThresholdEl.textContent = threshold;

      addLog(`Settings saved: region=${region}, threshold=${threshold}${note ? `, note="${note}"` : ""}`);
      document.getElementById("note").value = "";
    });

    regionSelect.addEventListener("change", () => {
      addLog(`Region filter changed to ${regionSelect.value}`);
    });

    updateDashboard();
    setInterval(updateDashboard, 2000);
  </script>
</body>
</html>
