        <div class="metric-label">System Health</div>
        <div class="metric-value" id="systemHealth">Good</div>
        <div class="metric-sub">Status changes dynamically</div>
      </div>
    </section>

    <section class="grid">
      <div class="card chart-wrap">
        <h2 class="panel-title">Live Traffic</h2>
        <canvas id="trafficChart"></canvas>
      </div>

      <div class="card">
        <h2 class="panel-title">Controls & Form</h2>

        <div class="controls">
          <div>
            <label for="timeRange">Time Range</label>
            <select id="timeRange">
              <option value="20">Last 20 points</option>
              <option value="50" selected>Last 50 points</option>
              <option value="100">Last 100 points</option>
            </select>
          </div>

          <div>
            <label for="threshold">Alert Threshold</label>
            <input id="threshold" type="number" min="0" max="100" value="75" />
          </div>

          <div>
            <label for="note">Add Note</label>
            <textarea id="note" rows="4" placeholder="Enter a dashboard note..."></textarea>
          </div>

          <button id="submitNote">Submit Note</button>
          <div class="status" id="formStatus">No notes submitted yet.</div>
        </div>
      </div>
    </section>

    <section class="card">
      <h2 class="panel-title">Event Log</h2>
      <div class="log" id="eventLog"></div>
    </section>
  </main>

  <script>
    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = [];
    const trafficData = [];

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          fill: true,
          tension: 0.35,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const systemHealthEl = document.getElementById("systemHealth");
    const eventLogEl = document.getElementById("eventLog");
    const formStatusEl = document.getElementById("formStatus");
    const timeRangeEl = document.getElementById("timeRange");
    const thresholdEl = document.getElementById("threshold");
    const noteEl = document.getElementById("note");
    const submitNoteBtn = document.getElementById("submitNote");

    function addLog(message, type = "good") {
      const item = document.createElement("div");
      item.className = "log-item";
      const time = new Date().toLocaleTimeString();
      item.innerHTML = `
        <strong>${time}</strong>
        <span class="tag ${type}">${type.toUpperCase()}</span>
        <div style="margin-top:6px;">${message}</div>
      `;
      eventLogEl.prepend(item);
    }

    function updateMetrics() {
      const activeUsers = Math.floor(50 + Math.random() * 450);
      const requestsPerMin = Math.floor(200 + Math.random() * 1800);
      const errorRate = (Math.random() * 10).toFixed(1);
      const healthScore = 100 - parseFloat(errorRate) * 5;

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;

      let healthText = "Good";
      let healthClass = "good";

      if (healthScore < 60) {
        healthText = "Critical";
        healthClass = "bad";
      } else if (healthScore < 80) {
        healthText = "Warning";
        healthClass = "warn";
      }

      systemHealthEl.textContent = healthText;
      systemHealthEl.style.color = healthClass === "good"
        ? "#22c55e"
        : healthClass === "warn"
          ? "#f59e0b"
          : "#ef4444";

      const newPoint = Math.floor(100 + Math.random() * 900);
      const timeLabel = new Date().toLocaleTimeString();

      labels.push(timeLabel);
      trafficData.push(newPoint);

      const maxPoints = parseInt(timeRangeEl.value, 10);
      while (labels.length > maxPoints) {
        labels.shift();
        trafficData.shift();
      }

      chart.update();

      const threshold = parseInt(thresholdEl.value, 10) || 75;
      if (newPoint > threshold * 10) {
        addLog(`Traffic spike detected: ${newPoint} requests`, "warn");
      } else if (errorRate > 7) {
        addLog(`Error rate elevated: ${errorRate}%`, "bad");
      } else {
        addLog(`Traffic normal: ${newPoint} requests`, "good");
      }
    }

    submitNoteBtn.addEventListener("click", () => {
      const note = noteEl.value.trim();
      if (!note) {
        formStatusEl.textContent = "Please enter a note before submitting.";
        formStatusEl.style.color = "#f59e0b";
        return;
      }

      formStatusEl.textContent = `Note submitted at ${new Date().toLocaleTimeString()}`;
      formStatusEl.style.color = "#22c55e";
      addLog(`Note submitted: ${note}`, "good");
      noteEl.value = "";
    });

    timeRangeEl.addEventListener("change", () => {
      const maxPoints = parseInt(timeRangeEl.value, 10);
      while (labels.length > maxPoints) {
        labels.shift();
        trafficData.shift();
      }
      chart.update();
      addLog(`Time range changed to last ${maxPoints} points`, "good");
    });

    thresholdEl.addEventListener("input", () => {
      addLog(`Alert threshold set to ${thresholdEl.value}`, "good");
    });

    setInterval(updateMetrics, 1000);
    updateMetrics();
  </script>
</body>
</html>
