  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const revenueEl = document.getElementById("revenue");

    const usersTrendEl = document.getElementById("usersTrend");
    const requestsTrendEl = document.getElementById("requestsTrend");
    const errorTrendEl = document.getElementById("errorTrend");
    const revenueTrendEl = document.getElementById("revenueTrend");

    const form = document.getElementById("recordForm");
    const recordsTable = document.getElementById("recordsTable");
    const searchInput = document.getElementById("search");
    const filterCategory = document.getElementById("filterCategory");

    let trafficData = Array.from({ length: 30 }, () => Math.floor(Math.random() * 100) + 20);
    let records = [
      { name: "Alice", category: "Sales", amount: 1200, status: "ok" },
      { name: "Bob", category: "Support", amount: 340, status: "warn" },
      { name: "Charlie", category: "Engineering", amount: 2200, status: "ok" },
      { name: "Diana", category: "Marketing", amount: 890, status: "bad" }
    ];

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const padding = 40;
      const chartWidth = canvas.width - padding * 2;
      const chartHeight = canvas.height - padding * 2;

      const maxVal = Math.max(...trafficData, 100);
      const minVal = 0;
      const stepX = chartWidth / (trafficData.length - 1);

      // Background grid
      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = padding + (chartHeight / 5) * i;
        ctx.beginPath();
        ctx.moveTo(padding, y);
        ctx.lineTo(canvas.width - padding, y);
        ctx.stroke();
      }

      // Line
      ctx.beginPath();
      trafficData.forEach((val, i) => {
        const x = padding + i * stepX;
        const y = padding + chartHeight - ((val - minVal) / (maxVal - minVal)) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      const gradient = ctx.createLinearGradient(0, 0, canvas.width, 0);
      gradient.addColorStop(0, "#38bdf8");
      gradient.addColorStop(1, "#22c55e");
      ctx.strokeStyle = gradient;
      ctx.lineWidth = 3;
      ctx.stroke();

      // Points
      trafficData.forEach((val, i) => {
        const x = padding + i * stepX;
        const y = padding + chartHeight - ((val - minVal) / (maxVal - minVal)) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = "#e5e7eb";
        ctx.fill();
      });

      // Labels
      ctx.fillStyle = "#9ca3af";
      ctx.font = "12px sans-serif";
      ctx.fillText("0", 10, canvas.height - padding);
      ctx.fillText(maxVal.toString(), 10, padding + 5);
    }

    function updateStats() {
      const activeUsers = Math.floor(100 + Math.random() * 900);
      const requests = Math.floor(200 + Math.random() * 1800);
      const errorRate = (Math.random() * 5).toFixed(2);
      const revenue = Math.floor(5000 + Math.random() * 25000);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requests.toLocaleString();
      errorRateEl.textContent = `${errorRate}%`;
      revenueEl.textContent = `$${revenue.toLocaleString()}`;

      usersTrendEl.textContent = `${Math.random() > 0.5 ? "+" : "-"}${(Math.random() * 12).toFixed(1)}% vs last minute`;
      requestsTrendEl.textContent = Math.random() > 0.5 ? "Increasing" : "Stable";
      errorTrendEl.textContent = errorRate < 2 ? "Healthy" : "Monitor closely";
      revenueTrendEl.textContent = `+${(Math.random() * 8).toFixed(1)}% today`;
    }

    function updateTraffic() {
      trafficData.push(Math.floor(Math.random() * 100) + 20);
      if (trafficData.length > 30) trafficData.shift();
      drawChart();
    }

    function getBadgeClass(status) {
      return status === "ok" ? "ok" : status === "warn" ? "warn" : "bad";
    }

    function renderRecords() {
      const query = searchInput.value.toLowerCase();
      const category = filterCategory.value;

      const filtered = records.filter(record => {
        const matchesQuery =
          record.name.toLowerCase().includes(query) ||
          record.category.toLowerCase().includes(query) ||
          record.status.toLowerCase().includes(query);

        const matchesCategory = category === "All" || record.category === category;
        return matchesQuery && matchesCategory;
      });

      recordsTable.innerHTML = filtered.map(record => `
        <tr>
          <td>${record.name}</td>
          <td>${record.category}</td>
          <td>$${Number(record.amount).toFixed(2)}</td>
          <td><span class="badge ${getBadgeClass(record.status)}">${record.status.toUpperCase()}</span></td>
        </tr>
      `).join("");

      if (filtered.length === 0) {
        recordsTable.innerHTML = `
          <tr>
            <td colspan="4" class="muted">No matching records found.</td>
          </tr>
        `;
      }
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("name").value.trim();
      const category = document.getElementById("category").value;
      const amount = parseFloat(document.getElementById("amount").value);
      const status = document.getElementById("status").value;

      records.unshift({ name, category, amount, status });
      form.reset();
      renderRecords();
    });

    searchInput.addEventListener("input", renderRecords);
    filterCategory.addEventListener("change", renderRecords);

    // Initial render
    drawChart();
    updateStats();
    renderRecords();

    // Real-time updates
    setInterval(() => {
      updateStats();
      updateTraffic();
    }, 1500);
  </script>
</body>
</html>
