      return new Date().toLocaleTimeString();
    }

    function getStatusClass(type) {
      return type === "good" ? "good" : type === "warn" ? "warn" : "bad";
    }

    function addEvent(name, type, value) {
      const event = {
        time: getTimeString(),
        name,
        type,
        value: Number(value)
      };

      eventLog.unshift(event);
      if (eventLog.length > 20) eventLog.pop();

      chartLabels.push(event.time);
      chartData.push(event.value);

      if (chartLabels.length > 12) {
        chartLabels.shift();
        chartData.shift();
      }

      updateMetrics();
      renderTable();
      activityChart.update();
    }

    function updateMetrics() {
      const activeUsers = Math.floor(50 + Math.random() * 150);
      const requestsPerMin = Math.floor(200 + Math.random() * 800);
      const errorRate = Math.floor(Math.random() * 12);

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = `${errorRate}%`;

      if (errorRate < 3) {
        systemStatusEl.textContent = "OK";
        systemStatusEl.style.color = "#22c55e";
      } else if (errorRate < 8) {
        systemStatusEl.textContent = "Degraded";
        systemStatusEl.style.color = "#f59e0b";
      } else {
        systemStatusEl.textContent = "Critical";
        systemStatusEl.style.color = "#ef4444";
      }
    }

    function renderTable() {
      const typeFilter = filterType.value;
      const search = searchInput.value.toLowerCase();

      const filtered = eventLog.filter(event => {
        const matchesType = typeFilter === "all" || event.type === typeFilter;
        const matchesSearch = event.name.toLowerCase().includes(search);
        return matchesType && matchesSearch;
      });

      eventTableBody.innerHTML = filtered.map(event => `
        <tr>
          <td>${event.time}</td>
          <td>${event.name}</td>
          <td><span class="status ${getStatusClass(event.type)}">${event.type}</span></td>
          <td>${event.value}</td>
        </tr>
      `).join("");
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("eventName").value.trim();
      const type = document.getElementById("eventType").value;
      const value = document.getElementById("eventValue").value;

      if (!name) {
        formMessage.textContent = "Please enter an event name.";
        formMessage.style.color = "#fca5a5";
        return;
      }

      addEvent(name, type, value);

      formMessage.textContent = `Event "${name}" added successfully.`;
      formMessage.style.color = "#86efac";

      eventForm.reset();
      document.getElementById("eventValue").value = 1;
    });

    filterType.addEventListener("change", renderTable);
    searchInput.addEventListener("input", renderTable);

    // Seed with initial data
    [
      ["User Login", "good", 12],
      ["API Timeout", "warn", 7],
      ["Payment Failed", "bad", 3],
      ["Profile Updated", "good", 9]
    ].forEach(([name, type, value]) => addEvent(name, type, value));

    // Simulate real-time updates
    setInterval(() => {
      const sampleEvents = [
        ["Page View", "good"],
        ["Search Query", "good"],
        ["Cache Miss", "warn"],
        ["Server Error", "bad"],
        ["Checkout", "good"],
        ["Webhook Retry", "warn"]
      ];

      const [name, type] = sampleEvents[Math.floor(Math.random() * sampleEvents.length)];
      const value = Math.floor(1 + Math.random() * 100);
      addEvent(name, type, value);
    }, 3000);

    // Update metrics every second
    updateMetrics();
    setInterval(updateMetrics, 1000);
  </script>
</body>
</html>
