  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const pointCountEl = document.getElementById("pointCount");
    const intervalLabel = document.getElementById("intervalLabel");
    const statusDot = document.getElementById("statusDot");

    const toggleBtn = document.getElementById("toggleBtn");
    const resetBtn = document.getElementById("resetBtn");
    const speedSelect = document.getElementById("speedSelect");

    const metricForm = document.getElementById("metricForm");
    const metricName = document.getElementById("metricName");
    const metricValue = document.getElementById("metricValue");
    const metricType = document.getElementById("metricType");
    const metricList = document.getElementById("metricList");

    let data = [];
    let timer = null;
    let running = true;
    let intervalMs = 1000;

    const customMetrics = [];

    function resizeCanvas() {
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width * window.devicePixelRatio;
      canvas.height = rect.height * window.devicePixelRatio;
      ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
      drawChart();
    }

    function generateDataPoint() {
      const last = data.length ? data[data.length - 1] : 50;
      const next = Math.max(0, Math.min(100, last + (Math.random() * 20 - 10)));
      data.push(next);
      if (data.length > 30) data.shift();

      currentValueEl.textContent = next.toFixed(1);
      const avg = data.reduce((a, b) => a + b, 0) / data.length;
      averageValueEl.textContent = avg.toFixed(1);
      pointCountEl.textContent = data.length;

      drawChart();
    }

    function drawChart() {
      const rect = canvas.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.strokeStyle = "#1f2937";
      ctx.lineWidth = 1;
      for (let i = 0; i <= 5; i++) {
        const y = (height / 5) * i;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }

      if (data.length < 2) return;

      const padding = 20;
      const chartWidth = width - padding * 2;
      const chartHeight = height - padding * 2;

      // Line
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = padding + (index / (data.length - 1)) * chartWidth;
        const y = padding + (1 - value / 100) * chartHeight;
        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // Points
      ctx.fillStyle = "#22c55e";
      data.forEach((value, index) => {
        const x = padding + (index / (data.length - 1)) * chartWidth;
        const y = padding + (1 - value / 100) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function startUpdates() {
      stopUpdates();
      timer = setInterval(generateDataPoint, intervalMs);
      running = true;
      toggleBtn.textContent = "Pause";
      statusDot.classList.remove("paused");
    }

    function stopUpdates() {
      if (timer) clearInterval(timer);
      timer = null;
      running = false;
      toggleBtn.textContent = "Resume";
      statusDot.classList.add("paused");
    }

    toggleBtn.addEventListener("click", () => {
      running ? stopUpdates() : startUpdates();
    });

    resetBtn.addEventListener("click", () => {
      data = [];
      currentValueEl.textContent = "0";
      averageValueEl.textContent = "0";
      pointCountEl.textContent = "0";
      drawChart();
    });

    speedSelect.addEventListener("change", (e) => {
      intervalMs = Number(e.target.value);
      intervalLabel.textContent = intervalMs;
      if (running) startUpdates();
    });

    metricForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = metricName.value.trim();
      const value = Number(metricValue.value);
      const type = metricType.value;

      if (!name || Number.isNaN(value)) {
        alert("Please enter a valid metric name and value.");
        return;
      }

      customMetrics.push({ name, value, type, createdAt: new Date() });
      renderMetrics();

      metricForm.reset();
      metricName.focus();
    });

    function renderMetrics() {
      metricList.innerHTML = "";

      if (customMetrics.length === 0) {
        metricList.innerHTML = `<div class="small">No custom metrics added yet.</div>`;
        return;
      }

      customMetrics.slice().reverse().forEach((metric) => {
        const item = document.createElement("div");
        item.className = "metric-item";
        item.innerHTML = `
          <div>
            <div class="name">${metric.name}</div>
            <div class="meta">${metric.type} · ${metric.createdAt.toLocaleTimeString()}</div>
          </div>
          <div><strong>${metric.value}</strong></div>
        `;
        metricList.appendChild(item);
      });
    }

    window.addEventListener("resize", resizeCanvas);

    // Init
    resizeCanvas();
    renderMetrics();
    startUpdates();
  </script>
</body>
</html>
