        </div>
        <div class="chart-wrap">
          <canvas id="liveChart"></canvas>
        </div>
      </div>

      <div class="panel">
        <h2>Add New Item</h2>
        <form id="itemForm">
          <input type="text" id="itemName" placeholder="Item name" required />
          <div class="form-row">
            <input type="number" id="itemValue" placeholder="Value" min="0" required />
            <select id="itemStatus">
              <option value="active">Active</option>
              <option value="completed">Completed</option>
            </select>
          </div>
          <button type="submit">Add Item</button>
        </form>

        <h2 style="margin-top: 24px;">Items</h2>
        <div class="list" id="itemList"></div>
      </div>
    </section>
  </main>

  <script>
    const totalEventsEl = document.getElementById("totalEvents");
    const activeItemsEl = document.getElementById("activeItems");
    const completedItemsEl = document.getElementById("completedItems");
    const liveRateEl = document.getElementById("liveRate");
    const itemListEl = document.getElementById("itemList");
    const metricSelect = document.getElementById("metricSelect");
    const toggleLiveBtn = document.getElementById("toggleLiveBtn");
    const itemForm = document.getElementById("itemForm");

    const ctx = document.getElementById("liveChart").getContext("2d");

    let liveRunning = true;
    let eventCount = 0;
    let liveRate = 0;
    let rateWindow = [];
    let items = [
      { name: "Server A", value: 42, status: "active", time: new Date() },
      { name: "Server B", value: 78, status: "completed", time: new Date() },
      { name: "Server C", value: 31, status: "active", time: new Date() }
    ];

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels: [],
        datasets: [
          {
            label: "Active",
            data: [],
            borderColor: "#38bdf8",
            backgroundColor: "rgba(56, 189, 248, 0.15)",
            tension: 0.35,
            fill: true
          },
          {
            label: "Completed",
            data: [],
            borderColor: "#22c55e",
            backgroundColor: "rgba(34, 197, 94, 0.15)",
            tension: 0.35,
            fill: true
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    function renderItems() {
      const filter = metricSelect.value;
      const filtered = items.filter(item => filter === "all" || item.status === filter);

      itemListEl.innerHTML = filtered.map((item, index) => `
        <div class="item">
          <div>
            <strong>${item.name}</strong>
            <small>Value: ${item.value} • ${item.time.toLocaleTimeString()}</small>
          </div>
          <span class="badge ${item.status === "completed" ? "success" : ""}">
            ${item.status}
          </span>
        </div>
      `).join("");

      const activeCount = items.filter(i => i.status === "active").length;
      const completedCount = items.filter(i => i.status === "completed").length;

      totalEventsEl.textContent = items.length;
      activeItemsEl.textContent = activeCount;
      completedItemsEl.textContent = completedCount;
      liveRateEl.textContent = `${liveRate.toFixed(1)}/s`;
    }

    function updateChart() {
      const activeData = items.filter(i => i.status === "active").map(i => i.value);
      const completedData = items.filter(i => i.status === "completed").map(i => i.value);

      chart.data.labels = items.map((_, i) => `#${i + 1}`);
      chart.data.datasets[0].data = activeData;
      chart.data.datasets[1].data = completedData;
      chart.update();
    }

    function addItem(name, value, status) {
      items.unshift({
        name,
        value: Number(value),
        status,
        time: new Date()
      });
      eventCount++;
      rateWindow.push(Date.now());
      rateWindow = rateWindow.filter(ts => Date.now() - ts <= 1000);
      liveRate = rateWindow.length;
      renderItems();
      updateChart();
    }

    itemForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const name = document.getElementById("itemName").value.trim();
      const value = document.getElementById("itemValue").value;
      const status = document.getElementById("itemStatus").value;

      if (!name || value === "") return;

      addItem(name, value, status);
      itemForm.reset();
      document.getElementById("itemName").focus();
    });

    metricSelect.addEventListener("change", renderItems);

    toggleLiveBtn.addEventListener("click", () => {
      liveRunning = !liveRunning;
      toggleLiveBtn.textContent = liveRunning ? "Pause Live Updates" : "Resume Live Updates";
    });

    // Simulated real-time updates
    setInterval(() => {
      if (!liveRunning) return;

      const statuses = ["active", "completed"];
      const randomStatus = statuses[Math.floor(Math.random() * statuses.length)];
      const randomValue = Math.floor(Math.random() * 100) + 1;
      const randomName = `Auto Item ${Math.floor(Math.random() * 1000)}`;

      addItem(randomName, randomValue, randomStatus);

      // Keep list manageable
      if (items.length > 20) {
        items = items.slice(0, 20);
      }
    }, 2000);

    // Initial render
    renderItems();
    updateChart();
  </script>
</body>
</html>
