    const eventForm = document.getElementById("eventForm");
    const eventName = document.getElementById("eventName");
    const eventCategory = document.getElementById("eventCategory");
    const eventValue = document.getElementById("eventValue");

    const filterCategory = document.getElementById("filterCategory");
    const searchInput = document.getElementById("searchInput");
    const activityTable = document.getElementById("activityTable");

    const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
    const trafficData = labels.map(() => Math.floor(Math.random() * 100) + 20);

    const activityLog = [];

    const ctx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.15)" }
          }
        }
      }
    });

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function updateMetrics() {
      const activeUsers = randomInt(120, 980);
      const requestsPerMin = randomInt(300, 2400);
      const errorRate = (Math.random() * 6).toFixed(2);
      const uptime = (99.5 + Math.random() * 0.5).toFixed(2);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
      errorRateEl.textContent = `${errorRate}%`;
      uptimeEl.textContent = `${uptime}%`;

      const nextValue = randomInt(20, 180);
      trafficData.push(nextValue);
      trafficData.shift();
      trafficChart.update();
    }

    function addActivity(eventNameValue, category, value) {
      activityLog.unshift({
        time: new Date().toLocaleTimeString(),
        name: eventNameValue,
        category,
        value
      });

      if (activityLog.length > 20) {
        activityLog.pop();
      }

      renderActivityTable();
    }

    function renderActivityTable() {
      const selectedCategory = filterCategory.value;
      const searchTerm = searchInput.value.trim().toLowerCase();

      const filtered = activityLog.filter(item => {
        const matchesCategory = selectedCategory === "all" || item.category === selectedCategory;
        const matchesSearch =
          item.name.toLowerCase().includes(searchTerm) ||
          item.category.toLowerCase().includes(searchTerm) ||
          String(item.value).includes(searchTerm);
        return matchesCategory && matchesSearch;
      });

      activityTable.innerHTML = filtered.map(item => {
        const statusClass =
          item.category === "success" ? "status-ok" :
          item.category === "error" ? "status-bad" : "";

        return `
          <tr>
            <td>${item.time}</td>
            <td>${item.name}</td>
            <td class="${statusClass}">${item.category}</td>
            <td>${item.value}</td>
          </tr>
        `;
      }).join("");

      if (!filtered.length) {
        activityTable.innerHTML = `
          <tr>
            <td colspan="4" style="color:#94a3b8; text-align:center; padding:18px;">
              No matching events found.
            </td>
          </tr>
        `;
      }
    }

    eventForm.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = eventName.value.trim();
      const category = eventCategory.value;
      const value = Number(eventValue.value);

      if (!name || !value) return;

      addActivity(name, category, value);

      eventForm.reset();
      eventValue.value = 1;
      eventName.focus();
    });

    filterCategory.addEventListener("change", renderActivityTable);
    searchInput.addEventListener("input", renderActivityTable);

    // Seed initial activity
    addActivity("System Boot", "success", 1);
    addActivity("API Sync", "info", 42);
    addActivity("Cache Refresh", "warning", 7);

    updateMetrics();
    setInterval(updateMetrics, 1000);
  </script>
