          <div class="value" id="averageValue">0</div>
        </div>
        <div class="stat">
          <div class="label">Data Points</div>
          <div class="value" id="pointCount">0</div>
        </div>
      </div>

      <div class="controls">
        <button class="btn-primary" id="toggleLiveBtn">Pause Live Updates</button>
        <button class="btn-success" id="addRandomBtn">Add Random Point</button>
        <button class="btn-danger" id="resetBtn">Reset Data</button>
      </div>

      <canvas id="liveChart"></canvas>
    </section>

    <aside class="card">
      <h2>Add Data Point</h2>
      <form id="dataForm">
        <div class="field">
          <label for="labelInput">Label</label>
          <input type="text" id="labelInput" placeholder="e.g. 10:30 AM" required />
        </div>

        <div class="field">
          <label for="valueInput">Value</label>
          <input type="number" id="valueInput" placeholder="Enter a number" required />
        </div>

        <div class="field">
          <label for="categoryInput">Category</label>
          <select id="categoryInput">
            <option value="manual">Manual</option>
            <option value="sensor">Sensor</option>
            <option value="api">API</option>
          </select>
        </div>

        <div class="form-actions">
          <button type="submit" class="btn-primary">Submit</button>
          <button type="button" class="btn-danger" id="clearFormBtn">Clear</button>
        </div>
      </form>

      <h2 style="margin-top: 22px;">Activity Log</h2>
      <div class="log" id="activityLog"></div>
    </aside>
  </main>

  <script>
    const ctx = document.getElementById("liveChart").getContext("2d");

    const labels = ["T1", "T2", "T3", "T4", "T5"];
    const dataPoints = [12, 19, 8, 15, 22];

    let liveUpdates = true;
    let intervalId = null;

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const pointCountEl = document.getElementById("pointCount");
    const activityLogEl = document.getElementById("activityLog");

    function logMessage(message) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
      activityLogEl.prepend(item);
    }

    function updateStats() {
      const current = dataPoints[dataPoints.length - 1] ?? 0;
      const avg = dataPoints.length
        ? (dataPoints.reduce((sum, val) => sum + val, 0) / dataPoints.length).toFixed(2)
        : 0;

      currentValueEl.textContent = current;
      averageValueEl.textContent = avg;
      pointCountEl.textContent = dataPoints.length;
    }

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Live Metric",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          },
          y: {
            ticks: { color: "#94a3b8" },
            grid: { color: "rgba(148, 163, 184, 0.12)" }
          }
        }
      }
    });

    function addDataPoint(label, value) {
      labels.push(label);
      dataPoints.push(value);

      if (labels.length > 12) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();
      updateStats();
      logMessage(`Added data point: ${label} = ${value}`);
    }

    function addRandomPoint() {
      const nextLabel = `T${labels.length + 1}`;
      const nextValue = Math.floor(Math.random() * 100);
      addDataPoint(nextLabel, nextValue);
    }

    function startLiveUpdates() {
      intervalId = setInterval(() => {
        if (!liveUpdates) return;
        addRandomPoint();
      }, 2000);
    }

    document.getElementById("toggleLiveBtn").addEventListener("click", () => {
      liveUpdates = !liveUpdates;
      document.getElementById("toggleLiveBtn").textContent = liveUpdates
        ? "Pause Live Updates"
        : "Resume Live Updates";
      logMessage(liveUpdates ? "Live updates resumed" : "Live updates paused");
    });

    document.getElementById("addRandomBtn").addEventListener("click", addRandomPoint);

    document.getElementById("resetBtn").addEventListener("click", () => {
      labels.length = 0;
      dataPoints.length = 0;

      ["A", "B", "C", "D", "E"].forEach((label, i) => {
        labels.push(label);
        dataPoints.push([10, 20, 15, 30, 25][i]);
      });

      chart.update();
      updateStats();
      logMessage("Dashboard reset to default values");
    });

    document.getElementById("dataForm").addEventListener("submit", (e) => {
      e.preventDefault();

      const label = document.getElementById("labelInput").value.trim();
      const value = Number(document.getElementById("valueInput").value);
      const category = document.getElementById("categoryInput").value;

      if (!label || Number.isNaN(value)) {
        alert("Please enter a valid label and numeric value.");
        return;
      }

      addDataPoint(label, value);
      logMessage(`Form submitted (${category}): ${label} = ${value}`);
      e.target.reset();
    });

    document.getElementById("clearFormBtn").addEventListener("click", () => {
      document.getElementById("dataForm").reset();
      logMessage("Form cleared");
    });

    updateStats();
    logMessage("Dashboard initialized");
    startLiveUpdates();
  </script>
</body>
</html>
```

