          <button data-range="20">Last 20 points</button>
          <button data-range="30">Last 30 points</button>
          <button id="pauseBtn">Pause</button>
        </div>
        <h2 class="panel-title">Live Traffic</h2>
        <div class="chart-wrap">
          <canvas id="trafficChart"></canvas>
        </div>
      </div>

      <div class="card">
        <h2 class="panel-title">Submit Event</h2>
        <form id="eventForm">
          <label>
            Event Name
            <input type="text" id="eventName" placeholder="e.g. Signup" />
            <div class="error" id="nameError"></div>
          </label>

          <label>
            Priority
            <select id="priority">
              <option value="">Select priority</option>
              <option value="low">Low</option>
              <option value="medium">Medium</option>
              <option value="high">High</option>
            </select>
            <div class="error" id="priorityError"></div>
          </label>

          <label>
            Notes
            <textarea id="notes" placeholder="Optional notes..."></textarea>
          </label>

          <button type="submit">Add Event</button>
          <div class="success" id="formSuccess"></div>
        </form>
      </div>
    </section>

    <section class="card">
      <h2 class="panel-title">Event Log</h2>
      <div class="log" id="eventLog"></div>
    </section>
  </main>

  <script>
    const ctx = document.getElementById("trafficChart").getContext("2d");

    const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
    const dataPoints = labels.map(() => Math.floor(Math.random() * 100));

    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Traffic",
          data: dataPoints,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointBackgroundColor: "#38bdf8"
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        },
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(51, 65, 85, 0.4)" }
          }
        }
      }
    });

    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const conversionRateEl = document.getElementById("conversionRate");
    const systemLoadEl = document.getElementById("systemLoad");
    const eventLogEl = document.getElementById("eventLog");

    let paused = false;
    let rangeSize = 10;

    function updateStats() {
      activeUsersEl.textContent = Math.floor(100 + Math.random() * 900);
      requestsPerMinEl.textContent = Math.floor(50 + Math.random() * 450);
      conversionRateEl.textContent = (Math.random() * 10 + 1).toFixed(2) + "%";
      systemLoadEl.textContent = Math.floor(Math.random() * 100) + "%";
    }

    function addLogItem(title, details) {
      const item = document.createElement("div");
      item.className = "log-item";
      item.innerHTML = `
        <strong>${title}</strong>
        <small>${details}</small>
      `;
      eventLogEl.prepend(item);
    }

    function tickChart() {
      if (paused) return;

      const newValue = Math.floor(Math.random() * 100);
      trafficChart.data.labels.push(new Date().toLocaleTimeString());
      trafficChart.data.datasets[0].data.push(newValue);

      while (trafficChart.data.labels.length > rangeSize) {
        trafficChart.data.labels.shift();
        trafficChart.data.datasets[0].data.shift();
      }

      trafficChart.update();
      updateStats();
    }

    setInterval(tickChart, 1500);
    updateStats();

    document.querySelectorAll("[data-range]").forEach(btn => {
      btn.addEventListener("click", () => {
        document.querySelectorAll("[data-range]").forEach(b => b.classList.remove("active"));
        btn.classList.add("active");
        rangeSize = parseInt(btn.dataset.range, 10);
      });
    });

    document.getElementById("pauseBtn").addEventListener("click", (e) => {
      paused = !paused;
      e.target.textContent = paused ? "Resume" : "Pause";
      e.target.classList.toggle("active", paused);
    });

    const form = document.getElementById("eventForm");
    const eventName = document.getElementById("eventName");
    const priority = document.getElementById("priority");
    const notes = document.getElementById("notes");
    const nameError = document.getElementById("nameError");
    const priorityError = document.getElementById("priorityError");
    const formSuccess = document.getElementById("formSuccess");

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      nameError.textContent = "";
      priorityError.textContent = "";
      formSuccess.textContent = "";

      let valid = true;

      if (!eventName.value.trim()) {
        nameError.textContent = "Event name is required.";
        valid = false;
      }

      if (!priority.value) {
        priorityError.textContent = "Please select a priority.";
        valid = false;
      }

      if (!valid) return;

      const timestamp = new Date().toLocaleString();
      addLogItem(
        `${eventName.value.trim()} (${priority.value.toUpperCase()})`,
        `${notes.value.trim() || "No notes"} • ${timestamp}`
      );

      formSuccess.textContent = "Event submitted successfully!";
      form.reset();

      setTimeout(() => {
        formSuccess.textContent = "";
      }, 2500);
    });
  </script>
</body>
</html>
