## 4) `app.js`

```javascript
const ctx = document.getElementById("metricsChart").getContext("2d");
const latestValueEl = document.getElementById("latestValue");
const averageValueEl = document.getElementById("averageValue");
const thresholdValueEl = document.getElementById("thresholdValue");
const alertStatusEl = document.getElementById("alertStatus");
const settingsOutputEl = document.getElementById("settingsOutput");
const controlForm = document.getElementById("controlForm");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const connectionStatusEl = document.getElementById("connectionStatus");

let metricName = "CPU Usage";
let threshold = 75;
let updateInterval = 1000;
let streamRunning = true;
let intervalId = null;

const labels = [];
const dataPoints = [];

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: metricName,
        data: dataPoints,
        borderColor: "#3b82f6",
        backgroundColor: "rgba(59, 130, 246, 0.2)",
        tension: 0.35,
        fill: true,
        pointRadius: 3
      }
    ]
  },
  options: {
    responsive: true,
    animation: false,
    scales: {
      y: {
        beginAtZero: true,
        max: 100,
        ticks: {
          color: "#cbd5e1"
        },
        grid: {
          color: "rgba(148, 163, 184, 0.15)"
        }
      },
      x: {
        ticks: {
          color: "#cbd5e1"
        },
        grid: {
          color: "rgba(148, 163, 184, 0.15)"
        }
      }
    },
    plugins: {
      legend: {
        labels: {
          color: "#e2e8f0"
        }
      }
    }
  }
});

function generateRandomValue() {
  return Math.floor(Math.random() * 101);
}

function updateStats(value) {
  const values = dataPoints;
  const avg = values.length
    ? (values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(1)
    : "--";

  latestValueEl.textContent = value;
  averageValueEl.textContent = avg;
  thresholdValueEl.textContent = threshold;

  if (value > threshold) {
    alertStatusEl.textContent = "Alert";
    alertStatusEl.style.color = "#f87171";
  } else {
    alertStatusEl.textContent = "Normal";
    alertStatusEl.style.color = "#4ade80";
  }
}

function pushDataPoint() {
  const value = generateRandomValue();
  const timestamp = new Date().toLocaleTimeString();

  labels.push(timestamp);
  dataPoints.push(value);

  if (labels.length > 12) {
    labels.shift();
    dataPoints.shift();
  }

  chart.data.datasets[0].label = metricName;
  chart.update();

  updateStats(value);
}

function startStream() {
  if (intervalId) clearInterval(intervalId);

  intervalId = setInterval(() => {
    if (streamRunning) {
      pushDataPoint();
    }
  }, updateInterval);

  connectionStatusEl.textContent = "Live";
  toggleStreamBtn.textContent = "Pause Stream";
}

function stopStream() {
  streamRunning = false;
  connectionStatusEl.textContent = "Paused";
  toggleStreamBtn.textContent = "Resume Stream";
}

controlForm.addEventListener("submit", (e) => {
  e.preventDefault();

  metricName = document.getElementById("metricName").value.trim() || "Metric";
  threshold = Number(document.getElementById("threshold").value);
  updateInterval = Number(document.getElementById("interval").value);

  settingsOutputEl.textContent = JSON.stringify(
    { metricName, threshold, updateInterval },
    null,
    2
  );

  chart.data.datasets[0].label = metricName;
  chart.update();

  startStream();
});

toggleStreamBtn.addEventListener("click", () => {
  streamRunning = !streamRunning;

  if (streamRunning) {
    connectionStatusEl.textContent = "Live";
    toggleStreamBtn.textContent = "Pause Stream";
  } else {
    connectionStatusEl.textContent = "Paused";
    toggleStreamBtn.textContent = "Resume Stream";
  }
});

settingsOutputEl.textContent = JSON.stringify(
  { metricName, threshold, updateInterval },
  null,
  2
);

startStream();
```

