## 4) `app.js`

```javascript
const ctx = document.getElementById("metricChart").getContext("2d");

const requestsEl = document.getElementById("requestsPerMin");
const usersEl = document.getElementById("activeUsers");
const errorEl = document.getElementById("errorRate");
const latencyEl = document.getElementById("latency");
const lastUpdatedEl = document.getElementById("lastUpdated");
const eventLogEl = document.getElementById("eventLog");
const formFeedbackEl = document.getElementById("formFeedback");
const connectionStatusEl = document.getElementById("connectionStatus");

const controlForm = document.getElementById("controlForm");

let labels = [];
let dataPoints = [];

function getTimeLabel() {
  return new Date().toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit"
  });
}

function addLog(message, type = "info") {
  const li = document.createElement("li");
  li.innerHTML = `${message}<small>${getTimeLabel()} • ${type.toUpperCase()}</small>`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "System Load",
        data: dataPoints,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
        pointHoverRadius: 5
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" }
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" },
        suggestedMin: 0,
        suggestedMax: 100
      }
    }
  }
});

function updateMetrics() {
  const requests = Math.floor(100 + Math.random() * 900);
  const users = Math.floor(20 + Math.random() * 180);
  const errorRate = (Math.random() * 8).toFixed(1);
  const latency = Math.floor(40 + Math.random() * 260);
  const load = Math.floor(20 + Math.random() * 80);

  requestsEl.textContent = requests;
  usersEl.textContent = users;
  errorEl.textContent = `${errorRate}%`;
  latencyEl.textContent = `${latency} ms`;

  labels.push(getTimeLabel());
  dataPoints.push(load);

  if (labels.length > 12) {
    labels.shift();
    dataPoints.shift();
  }

  chart.update();

  lastUpdatedEl.textContent = `Updated at ${getTimeLabel()}`;

  if (load > 80) {
    addLog(`High load detected: ${load}%`, "warning");
  } else {
    addLog(`Metrics refreshed. Load: ${load}%`, "info");
  }
}

controlForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const threshold = document.getElementById("threshold").value;
  const mode = document.getElementById("mode").value;
  const notifications = document.getElementById("notifications").checked;

  formFeedbackEl.textContent = `Settings applied: threshold=${threshold}, mode=${mode}, notifications=${notifications ? "on" : "off"}`;
  addLog(`Control settings updated (${mode} mode)`, "success");
});

function simulateConnection() {
  connectionStatusEl.textContent = "Live";
  connectionStatusEl.style.background = "rgba(34, 197, 94, 0.15)";
  connectionStatusEl.style.color = "#86efac";
  connectionStatusEl.style.borderColor = "rgba(34, 197, 94, 0.25)";
}

simulateConnection();
updateMetrics();
setInterval(updateMetrics, 3000);
```

