## 4) `app.js`

```javascript
const usersOnlineEl = document.getElementById("usersOnline");
const requestsPerSecEl = document.getElementById("requestsPerSec");
const errorRateEl = document.getElementById("errorRate");
const avgLatencyEl = document.getElementById("avgLatency");
const eventLogEl = document.getElementById("eventLog");
const formOutputEl = document.getElementById("formOutput");
const thresholdEl = document.getElementById("threshold");
const thresholdValueEl = document.getElementById("thresholdValue");
const controlForm = document.getElementById("controlForm");
const pauseBtn = document.getElementById("pauseBtn");

let paused = false;
let tickInterval = null;

const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
const trafficData = labels.map(() => randomInt(50, 120));
const healthData = [90, 80, 70];

const trafficCtx = document.getElementById("trafficChart").getContext("2d");
const healthCtx = document.getElementById("healthChart").getContext("2d");

const trafficChart = new Chart(trafficCtx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Requests",
        data: trafficData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      y: {
        beginAtZero: true,
        grid: { color: "rgba(255,255,255,0.08)" },
        ticks: { color: "#9ca3af" },
      },
      x: {
        grid: { color: "rgba(255,255,255,0.05)" },
        ticks: { color: "#9ca3af" },
      },
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

const healthChart = new Chart(healthCtx, {
  type: "doughnut",
  data: {
    labels: ["CPU", "Memory", "Disk"],
    datasets: [
      {
        data: healthData,
        backgroundColor: ["#22c55e", "#f59e0b", "#ef4444"],
        borderColor: "#111827",
        borderWidth: 2,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: "bottom",
        labels: { color: "#e5e7eb" },
      },
    },
  },
});

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function addLog(message, type = "info") {
  const li = document.createElement("li");
  li.innerHTML = `<strong>[${type.toUpperCase()}]</strong> ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function updateMetrics() {
  const usersOnline = randomInt(120, 500);
  const requestsPerSec = randomInt(80, 300);
  const errorRate = (Math.random() * 5).toFixed(1);
  const avgLatency = randomInt(40, 220);

  usersOnlineEl.textContent = usersOnline;
  requestsPerSecEl.textContent = requestsPerSec;
  errorRateEl.textContent = `${errorRate}%`;
  avgLatencyEl.textContent = `${avgLatency} ms`;

  return { usersOnline, requestsPerSec, errorRate, avgLatency };
}

function updateCharts() {
  trafficChart.data.labels.shift();
  trafficChart.data.labels.push(`T-${Date.now() % 1000}`);
  trafficChart.data.datasets[0].data.shift();
  trafficChart.data.datasets[0].data.push(randomInt(50, 180));
  trafficChart.update();

  healthChart.data.datasets[0].data = [
    randomInt(50, 100),
    randomInt(40, 95),
    randomInt(10, 80),
  ];
  healthChart.update();
}

function tick() {
  if (paused) return;

  const metrics = updateMetrics();
  updateCharts();

  if (metrics.errorRate > 4) {
    addLog(`Error rate elevated to ${metrics.errorRate}%`, "warn");
  } else {
    addLog(`Metrics refreshed: ${metrics.usersOnline} users online`, "info");
  }
}

thresholdEl.addEventListener("input", () => {
  thresholdValueEl.textContent = thresholdEl.value;
});

controlForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const timeRange = document.getElementById("timeRange").value;
  const threshold = thresholdEl.value;
  const alertEmail = document.getElementById("alertEmail").value || "not set";

  formOutputEl.textContent = `Settings applied: time range = ${timeRange} min, threshold = ${threshold}, alert email = ${alertEmail}`;
  addLog(`Applied settings: range ${timeRange} min, threshold ${threshold}`, "info");
});

pauseBtn.addEventListener("click", () => {
  paused = !paused;
  pauseBtn.textContent = paused ? "Resume" : "Pause";
  document.getElementById("connectionStatus").textContent = paused ? "Paused" : "Live";
  addLog(paused ? "Live updates paused" : "Live updates resumed", "info");
});

updateMetrics();
tickInterval = setInterval(tick, 2000);
addLog("Dashboard initialized", "info");
```

