## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerSecEl = document.getElementById("requestsPerSec");
const errorRateEl = document.getElementById("errorRate");
const eventLogEl = document.getElementById("eventLog");
const formMessageEl = document.getElementById("formMessage");
const thresholdValueEl = document.getElementById("thresholdValue");
const pauseBtn = document.getElementById("pauseBtn");
const settingsForm = document.getElementById("settingsForm");
const refreshIntervalInput = document.getElementById("refreshInterval");
const alertThresholdInput = document.getElementById("alertThreshold");
const dashboardNameInput = document.getElementById("dashboardName");
const connectionStatusEl = document.getElementById("connectionStatus");

let isPaused = false;
let refreshInterval = 1000;
let intervalId = null;
let alertThreshold = 75;

const chartCtx = document.getElementById("trafficChart").getContext("2d");

const trafficChart = new Chart(chartCtx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Traffic",
        data: [],
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 2
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" }
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" }
      }
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" }
      }
    }
  }
});

function addLog(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function updateMetrics() {
  const activeUsers = Math.floor(Math.random() * 5000) + 500;
  const requestsPerSec = Math.floor(Math.random() * 1200) + 100;
  const errorRate = (Math.random() * 5).toFixed(2);

  activeUsersEl.textContent = activeUsers.toLocaleString();
  requestsPerSecEl.textContent = requestsPerSec.toLocaleString();
  errorRateEl.textContent = `${errorRate}%`;

  const timestamp = new Date().toLocaleTimeString();
  const trafficValue = requestsPerSec + Math.floor(Math.random() * 200) - 100;

  trafficChart.data.labels.push(timestamp);
  trafficChart.data.datasets[0].data.push(trafficValue);

  if (trafficChart.data.labels.length > 20) {
    trafficChart.data.labels.shift();
    trafficChart.data.datasets[0].data.shift();
  }

  trafficChart.update();

  if (parseFloat(errorRate) > alertThreshold / 20) {
    addLog(`Alert: error rate ${errorRate}% exceeded threshold.`);
  } else {
    addLog(`Metrics updated: ${activeUsers} users, ${requestsPerSec} req/s.`);
  }
}

function startLiveUpdates() {
  clearInterval(intervalId);
  intervalId = setInterval(() => {
    if (!isPaused) updateMetrics();
  }, refreshInterval);
}

pauseBtn.addEventListener("click", () => {
  isPaused = !isPaused;
  pauseBtn.textContent = isPaused ? "Resume" : "Pause";
  connectionStatusEl.textContent = isPaused ? "● Paused" : "● Live";
  connectionStatusEl.style.background = isPaused
    ? "rgba(239, 68, 68, 0.15)"
    : "rgba(34, 197, 94, 0.15)";
  connectionStatusEl.style.color = isPaused ? "#fca5a5" : "#86efac";
  connectionStatusEl.style.borderColor = isPaused
    ? "rgba(239, 68, 68, 0.25)"
    : "rgba(34, 197, 94, 0.25)";
  addLog(isPaused ? "Live updates paused." : "Live updates resumed.");
});

alertThresholdInput.addEventListener("input", () => {
  thresholdValueEl.textContent = alertThresholdInput.value;
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const name = dashboardNameInput.value.trim();
  const newInterval = parseInt(refreshIntervalInput.value, 10);
  const newThreshold = parseInt(alertThresholdInput.value, 10);

  if (newInterval < 500 || Number.isNaN(newInterval)) {
    formMessageEl.textContent = "Refresh interval must be at least 500 ms.";
    return;
  }

  refreshInterval = newInterval;
  alertThreshold = newThreshold;

  formMessageEl.textContent = name
    ? `Settings saved for "${name}".`
    : "Settings saved.";

  addLog(`Settings updated: interval=${refreshInterval}ms, threshold=${alertThreshold}.`);

  startLiveUpdates();
});

window.addEventListener("load", () => {
  addLog("Dashboard initialized.");
  updateMetrics();
  startLiveUpdates();
});
```

