## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const eventLogEl = document.getElementById("eventLog");
const settingsForm = document.getElementById("settingsForm");
const settingsOutput = document.getElementById("settingsOutput");
const thresholdValue = document.getElementById("thresholdValue");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const connectionStatus = document.getElementById("connectionStatus");

const ctx = document.getElementById("trafficChart").getContext("2d");

let streamRunning = true;
let refreshInterval = 1000;
let streamTimer = null;

const labels = [];
const trafficData = [];

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Traffic",
        data: trafficData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 2,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb",
        },
      },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
    },
  },
});

function addLog(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function updateMetrics() {
  const activeUsers = Math.floor(100 + Math.random() * 900);
  const requestsPerMin = Math.floor(500 + Math.random() * 2500);
  const errorRate = (Math.random() * 5).toFixed(2);

  activeUsersEl.textContent = activeUsers;
  requestsPerMinEl.textContent = requestsPerMin;
  errorRateEl.textContent = `${errorRate}%`;

  return requestsPerMin;
}

function updateChart() {
  const value = updateMetrics();
  const timeLabel = new Date().toLocaleTimeString();

  labels.push(timeLabel);
  trafficData.push(value);

  if (labels.length > 20) {
    labels.shift();
    trafficData.shift();
  }

  chart.update();
}

function startStream() {
  stopStream();
  streamTimer = setInterval(() => {
    if (streamRunning) {
      updateChart();
      addLog("Live data point received.");
    }
  }, refreshInterval);
}

function stopStream() {
  if (streamTimer) {
    clearInterval(streamTimer);
    streamTimer = null;
  }
}

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const formData = new FormData(settingsForm);
  const settings = Object.fromEntries(formData.entries());

  settings.refreshInterval = Number(settings.refreshInterval);
  settings.alertThreshold = Number(settings.alertThreshold);

  refreshInterval = settings.refreshInterval;
  thresholdValue.textContent = settings.alertThreshold;
  settingsOutput.textContent = JSON.stringify(settings, null, 2);

  addLog(`Settings saved: ${settings.dashboardName}`);
  startStream();
});

settingsForm.alertThreshold.addEventListener("input", (e) => {
  thresholdValue.textContent = e.target.value;
});

toggleStreamBtn.addEventListener("click", () => {
  streamRunning = !streamRunning;
  toggleStreamBtn.textContent = streamRunning ? "Pause Stream" : "Resume Stream";
  connectionStatus.textContent = streamRunning ? "● Live" : "● Paused";
  connectionStatus.style.background = streamRunning
    ? "rgba(34, 197, 94, 0.15)"
    : "rgba(239, 68, 68, 0.15)";
  connectionStatus.style.color = streamRunning ? "#86efac" : "#fca5a5";
  connectionStatus.style.borderColor = streamRunning
    ? "rgba(34, 197, 94, 0.3)"
    : "rgba(239, 68, 68, 0.3)";

  addLog(streamRunning ? "Stream resumed." : "Stream paused.");
});

settingsOutput.textContent = JSON.stringify(
  {
    dashboardName: "Live Analytics Dashboard",
    refreshInterval,
    alertThreshold: Number(settingsForm.alertThreshold.value),
  },
  null,
  2
);

thresholdValue.textContent = settingsForm.alertThreshold.value;
updateChart();
startStream();
addLog("Dashboard initialized.");
```

