## 4) `app.js`

```javascript
const state = {
  streamActive: true,
  refreshRate: 1000,
  threshold: 75,
  theme: "dark",
  intervalId: null,
  chart: null,
  labels: [],
  trafficData: [],
};

const els = {
  activeUsers: document.getElementById("activeUsers"),
  requestsPerSec: document.getElementById("requestsPerSec"),
  errorRate: document.getElementById("errorRate"),
  avgLatency: document.getElementById("avgLatency"),
  eventLog: document.getElementById("eventLog"),
  connectionStatus: document.getElementById("connectionStatus"),
  toggleStreamBtn: document.getElementById("toggleStreamBtn"),
  settingsForm: document.getElementById("settingsForm"),
  refreshRate: document.getElementById("refreshRate"),
  threshold: document.getElementById("threshold"),
  thresholdValue: document.getElementById("thresholdValue"),
  themeSelect: document.getElementById("themeSelect"),
};

function nowTime() {
  return new Date().toLocaleTimeString();
}

function addLog(message, type = "info") {
  const entry = document.createElement("div");
  entry.className = "log-entry";
  entry.innerHTML = `
    <strong>${type.toUpperCase()}</strong> — ${message}
    <small>${nowTime()}</small>
  `;
  els.eventLog.prepend(entry);
}

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function generateMetrics() {
  const activeUsers = randomInt(120, 1200);
  const requestsPerSec = randomInt(40, 300);
  const errorRate = (Math.random() * 8).toFixed(1);
  const avgLatency = randomInt(80, 650);

  return { activeUsers, requestsPerSec, errorRate, avgLatency };
}

function updateMetrics() {
  const metrics = generateMetrics();

  els.activeUsers.textContent = metrics.activeUsers.toLocaleString();
  els.requestsPerSec.textContent = metrics.requestsPerSec.toLocaleString();
  els.errorRate.textContent = `${metrics.errorRate}%`;
  els.avgLatency.textContent = `${metrics.avgLatency} ms`;

  if (parseFloat(metrics.errorRate) > state.threshold) {
    addLog(`Error rate exceeded threshold: ${metrics.errorRate}%`, "warning");
  }

  return metrics;
}

function updateChart(value) {
  const label = new Date().toLocaleTimeString();

  state.labels.push(label);
  state.trafficData.push(value);

  if (state.labels.length > 12) {
    state.labels.shift();
    state.trafficData.shift();
  }

  state.chart.data.labels = state.labels;
  state.chart.data.datasets[0].data = state.trafficData;
  state.chart.update();
}

function initChart() {
  const ctx = document.getElementById("trafficChart").getContext("2d");

  state.chart = new Chart(ctx, {
    type: "line",
    data: {
      labels: [],
      datasets: [
        {
          label: "Requests/sec",
          data: [],
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
        },
      ],
    },
    options: {
      responsive: true,
      plugins: {
        legend: {
          labels: {
            color: getComputedStyle(document.body).color,
          },
        },
      },
      scales: {
        x: {
          ticks: { color: getComputedStyle(document.body).color },
          grid: { color: "rgba(148, 163, 184, 0.15)" },
        },
        y: {
          ticks: { color: getComputedStyle(document.body).color },
          grid: { color: "rgba(148, 163, 184, 0.15)" },
        },
      },
    },
  });
}

function applyTheme(theme) {
  document.documentElement.setAttribute("data-theme", theme);
  state.theme = theme;

  if (state.chart) {
    state.chart.options.plugins.legend.labels.color = getComputedStyle(document.body).color;
    state.chart.options.scales.x.ticks.color = getComputedStyle(document.body).color;
    state.chart.options.scales.y.ticks.color = getComputedStyle(document.body).color;
    state.chart.update();
  }

  addLog(`Theme changed to ${theme}`, "info");
}

function startStream() {
  stopStream();

  state.intervalId = setInterval(() => {
    const metrics = updateMetrics();
    updateChart(metrics.requestsPerSec);
  }, state.refreshRate);

  state.streamActive = true;
  els.connectionStatus.textContent = "● Live";
  els.toggleStreamBtn.textContent = "Pause Stream";
  addLog("Data stream started", "success");
}

function stopStream() {
  if (state.intervalId) {
    clearInterval(state.intervalId);
    state.intervalId = null;
  }
  state.streamActive = false;
  els.connectionStatus.textContent = "● Paused";
  els.toggleStreamBtn.textContent = "Resume Stream";
  addLog("Data stream paused", "info");
}

els.toggleStreamBtn.addEventListener("click", () => {
  if (state.streamActive) stopStream();
  else startStream();
});

els.threshold.addEventListener("input", (e) => {
  els.thresholdValue.textContent = e.target.value;
});

els.settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const newRefreshRate = parseInt(els.refreshRate.value, 10);
  const newThreshold = parseInt(els.threshold.value, 10);
  const newTheme = els.themeSelect.value;

  state.refreshRate = newRefreshRate;
  state.threshold = newThreshold;

  applyTheme(newTheme);

  addLog(
    `Settings applied: refreshRate=${newRefreshRate}ms, threshold=${newThreshold}%, theme=${newTheme}`,
    "success"
  );

  if (state.streamActive) {
    startStream();
  }
});

function init() {
  els.thresholdValue.textContent = els.threshold.value;
  applyTheme(els.themeSelect.value);
  initChart();
  updateMetrics();
  startStream();
  addLog("Dashboard initialized", "success");
}

init();
```

