## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const activeUsersTrendEl = document.getElementById("activeUsersTrend");
const requestsTrendEl = document.getElementById("requestsTrend");
const errorTrendEl = document.getElementById("errorTrend");
const eventLogEl = document.getElementById("eventLog");
const settingsOutputEl = document.getElementById("settingsOutput");
const thresholdValueEl = document.getElementById("thresholdValue");
const connectionStatusEl = document.getElementById("connectionStatus");

const controlForm = document.getElementById("controlForm");
const dashboardNameInput = document.getElementById("dashboardName");
const refreshIntervalInput = document.getElementById("refreshInterval");
const alertThresholdInput = document.getElementById("alertThreshold");
const enableAlertsInput = document.getElementById("enableAlerts");

const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const clearLogBtn = document.getElementById("clearLogBtn");
const resetBtn = document.getElementById("resetBtn");

let streamRunning = true;
let refreshInterval = 1000;
let intervalId = null;

let settings = {
  dashboardName: "Operations Dashboard",
  refreshInterval: 1000,
  alertThreshold: 75,
  enableAlerts: true
};

let previousMetrics = {
  activeUsers: 0,
  requestsPerMin: 0,
  errorRate: 0
};

const chartCtx = document.getElementById("trafficChart").getContext("2d");
const trafficChart = new Chart(chartCtx, {
  type: "line",
  data: {
    labels: [],
    datasets: [
      {
        label: "Requests / Min",
        data: [],
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" }
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" }
      }
    },
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" }
      }
    }
  }
});

function logEvent(message, type = "info") {
  const item = document.createElement("div");
  item.className = "log-item";
  const time = new Date().toLocaleTimeString();
  item.innerHTML = `<span class="time">[${time}]</span> ${message}`;
  if (type === "alert") {
    item.style.borderColor = "rgba(239, 68, 68, 0.4)";
    item.style.color = "#fecaca";
  }
  eventLogEl.prepend(item);
}

function updateSettingsOutput() {
  settingsOutputEl.textContent = JSON.stringify(settings, null, 2);
  document.title = settings.dashboardName;
}

function updateThresholdLabel() {
  thresholdValueEl.textContent = alertThresholdInput.value;
}

function generateMetrics() {
  const activeUsers = Math.floor(200 + Math.random() * 800);
  const requestsPerMin = Math.floor(500 + Math.random() * 2500);
  const errorRate = +(Math.random() * 10).toFixed(2);

  return { activeUsers, requestsPerMin, errorRate };
}

function updateMetricUI(metrics) {
  activeUsersEl.textContent = metrics.activeUsers.toLocaleString();
  requestsPerMinEl.textContent = metrics.requestsPerMin.toLocaleString();
  errorRateEl.textContent = `${metrics.errorRate.toFixed(2)}%`;

  activeUsersTrendEl.textContent = `Δ ${metrics.activeUsers - previousMetrics.activeUsers >= 0 ? "+" : ""}${metrics.activeUsers - previousMetrics.activeUsers}`;
  requestsTrendEl.textContent = `Δ ${metrics.requestsPerMin - previousMetrics.requestsPerMin >= 0 ? "+" : ""}${metrics.requestsPerMin - previousMetrics.requestsPerMin}`;
  errorTrendEl.textContent = `Δ ${metrics.errorRate - previousMetrics.errorRate >= 0 ? "+" : ""}${(metrics.errorRate - previousMetrics.errorRate).toFixed(2)}%`;

  previousMetrics = metrics;
}

function updateChart(metrics) {
  const now = new Date().toLocaleTimeString();
  trafficChart.data.labels.push(now);
  trafficChart.data.datasets[0].data.push(metrics.requestsPerMin);

  if (trafficChart.data.labels.length > 12) {
    trafficChart.data.labels.shift();
    trafficChart.data.datasets[0].data.shift();
  }

  trafficChart.update();
}

function maybeTriggerAlert(metrics) {
  if (!settings.enableAlerts) return;

  if (metrics.errorRate >= settings.alertThreshold) {
    logEvent(`Alert: error rate exceeded threshold (${metrics.errorRate.toFixed(2)}% >= ${settings.alertThreshold}%)`, "alert");
  }
}

function tick() {
  if (!streamRunning) return;

  const metrics = generateMetrics();
  updateMetricUI(metrics);
  updateChart(metrics);
  maybeTriggerAlert(metrics);
}

function startStream() {
  clearInterval(intervalId);
  intervalId = setInterval(tick, refreshInterval);
  connectionStatusEl.textContent = "● Live";
  connectionStatusEl.style.background = "rgba(34, 197, 94, 0.15)";
  connectionStatusEl.style.color = "#86efac";
}

function stopStream() {
  clearInterval(intervalId);
  connectionStatusEl.textContent = "● Paused";
  connectionStatusEl.style.background = "rgba(245, 158, 11, 0.15)";
  connectionStatusEl.style.color = "#fcd34d";
}

controlForm.addEventListener("submit", (e) => {
  e.preventDefault();

  settings.dashboardName = dashboardNameInput.value.trim() || settings.dashboardName;
  settings.refreshInterval = Math.max(500, parseInt(refreshIntervalInput.value, 10) || 1000);
  settings.alertThreshold = parseInt(alertThresholdInput.value, 10);
  settings.enableAlerts = enableAlertsInput.checked;

  refreshInterval = settings.refreshInterval;
  updateSettingsOutput();
  logEvent(`Settings applied for "${settings.dashboardName}"`);
  startStream();
});

alertThresholdInput.addEventListener("input", updateThresholdLabel);

toggleStreamBtn.addEventListener("click", () => {
  streamRunning = !streamRunning;
  toggleStreamBtn.textContent = streamRunning ? "Pause Stream" : "Resume Stream";

  if (streamRunning) {
    startStream();
    logEvent("Live stream resumed");
  } else {
    stopStream();
    logEvent("Live stream paused");
  }
});

clearLogBtn.addEventListener("click", () => {
  eventLogEl.innerHTML = "";
});

resetBtn.addEventListener("click", () => {
  settings = {
    dashboardName: "Operations Dashboard",
    refreshInterval: 1000,
    alertThreshold: 75,
    enableAlerts: true
  };

  dashboardNameInput.value = "";
  refreshIntervalInput.value = 1000;
  alertThresholdInput.value = 75;
  enableAlertsInput.checked = true;
  updateThresholdLabel();
  updateSettingsOutput();
  refreshInterval = settings.refreshInterval;
  startStream();
  logEvent("Settings reset to defaults");
});

function init() {
  updateThresholdLabel();
  updateSettingsOutput();
  logEvent("Dashboard initialized");
  startStream();
  tick();
}

init();
```

