## 4) `app.js`

```javascript
const ctx = document.getElementById("metricsChart").getContext("2d");
const entriesTable = document.getElementById("entriesTable");
const dataForm = document.getElementById("dataForm");
const pauseBtn = document.getElementById("pauseBtn");

const totalEntriesEl = document.getElementById("totalEntries");
const avgValueEl = document.getElementById("avgValue");
const latestValueEl = document.getElementById("latestValue");

let isPaused = false;
let liveInterval = null;

const labels = [];
const values = [];

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Live Value",
        data: values,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
        pointBackgroundColor: "#38bdf8"
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      },
      y: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      }
    },
    plugins: {
      legend: {
        labels: { color: "#e2e8f0" }
      }
    }
  }
});

function formatTime(date = new Date()) {
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
}

function updateStats() {
  const total = values.length;
  const avg = total ? (values.reduce((a, b) => a + b, 0) / total).toFixed(1) : 0;
  const latest = total ? values[values.length - 1] : 0;

  totalEntriesEl.textContent = total;
  avgValueEl.textContent = avg;
  latestValueEl.textContent = latest;
}

function addEntryToTable({ name, category, value, time }) {
  const row = document.createElement("tr");
  row.innerHTML = `
    <td>${name}</td>
    <td>${category}</td>
    <td>${value}</td>
    <td>${time}</td>
  `;
  entriesTable.prepend(row);
}

function addDataPoint(value, label = formatTime()) {
  labels.push(label);
  values.push(value);

  if (labels.length > 12) {
    labels.shift();
    values.shift();
  }

  chart.update();
  updateStats();
}

function generateLiveData() {
  if (isPaused) return;

  const value = Math.floor(Math.random() * 100) + 1;
  addDataPoint(value);
  addEntryToTable({
    name: "Auto Feed",
    category: "Live",
    value,
    time: formatTime()
  });
}

dataForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const name = document.getElementById("name").value.trim();
  const category = document.getElementById("category").value;
  const value = Number(document.getElementById("value").value);

  if (!name || !category || Number.isNaN(value)) return;

  addDataPoint(value);
  addEntryToTable({
    name,
    category,
    value,
    time: formatTime()
  });

  dataForm.reset();
});

pauseBtn.addEventListener("click", () => {
  isPaused = !isPaused;
  pauseBtn.textContent = isPaused ? "Resume" : "Pause";
  pauseBtn.classList.toggle("secondary");
});

function init() {
  // Seed initial data
  for (let i = 0; i < 6; i++) {
    const value = Math.floor(Math.random() * 100) + 1;
    addDataPoint(value, `T-${6 - i}`);
    addEntryToTable({
      name: `Seed ${i + 1}`,
      category: ["Sales", "Marketing", "Support"][i % 3],
      value,
      time: formatTime()
    });
  }

  liveInterval = setInterval(generateLiveData, 2500);
}

init();
```

