## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const avgLatencyEl = document.getElementById("avgLatency");
const eventLogEl = document.getElementById("eventLog");
const formOutputEl = document.getElementById("formOutput");
const controlForm = document.getElementById("controlForm");

const dashboardNameInput = document.getElementById("dashboardName");
const refreshIntervalInput = document.getElementById("refreshInterval");
const alertThresholdInput = document.getElementById("alertThreshold");

let refreshIntervalMs = 3000;
let alertThreshold = 75;
let updateTimer = null;

const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);

const trafficData = Array.from({ length: 10 }, () => randomInt(50, 150));
const latencyData = Array.from({ length: 10 }, () => randomInt(80, 300));

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function addLog(message) {
  const li = document.createElement("li");
  li.textContent = `${new Date().toLocaleTimeString()} — ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

const trafficChart = new Chart(document.getElementById("trafficChart"), {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Requests/min",
        data: trafficData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  },
});

const latencyChart = new Chart(document.getElementById("latencyChart"), {
  type: "bar",
  data: {
    labels,
    datasets: [
      {
        label: "Latency (ms)",
        data: latencyData,
        borderColor: "#f59e0b",
        backgroundColor: "rgba(245, 158, 11, 0.6)",
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  },
});

function updateMetrics() {
  const activeUsers = randomInt(120, 1200);
  const requestsPerMin = randomInt(300, 1800);
  const errorRate = (Math.random() * 8).toFixed(1);
  const avgLatency = randomInt(60, 420);

  activeUsersEl.textContent = activeUsers.toLocaleString();
  requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
  errorRateEl.textContent = `${errorRate}%`;
  avgLatencyEl.textContent = `${avgLatency} ms`;

  trafficData.push(requestsPerMin);
  trafficData.shift();

  latencyData.push(avgLatency);
  latencyData.shift();

  trafficChart.update();
  latencyChart.update();

  if (Number(errorRate) > 5 || avgLatency > alertThreshold) {
    addLog(`Warning: threshold exceeded (error rate ${errorRate}%, latency ${avgLatency} ms)`);
  } else {
    addLog(`Metrics updated: ${activeUsers} users, ${requestsPerMin} req/min`);
  }
}

function startLiveUpdates() {
  if (updateTimer) clearInterval(updateTimer);
  updateTimer = setInterval(updateMetrics, refreshIntervalMs);
  addLog(`Live updates started with ${refreshIntervalMs / 1000}s interval`);
}

controlForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const dashboardName = dashboardNameInput.value.trim();
  refreshIntervalMs = Number(refreshIntervalInput.value) * 1000;
  alertThreshold = Number(alertThresholdInput.value);

  formOutputEl.textContent = `Applied settings: "${dashboardName}", refresh every ${refreshIntervalMs / 1000}s, alert threshold ${alertThreshold} ms.`;
  addLog(`Settings applied for dashboard "${dashboardName}"`);

  startLiveUpdates();
});

dashboardNameInput.value = "Operations Dashboard";
formOutputEl.textContent = "Settings not applied yet.";
startLiveUpdates();
updateMetrics();
```

