## 4) `app.js`

```javascript
const usersOnlineEl = document.getElementById("usersOnline");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const activityLogEl = document.getElementById("activityLog");
const formFeedbackEl = document.getElementById("formFeedback");
const connectionStatusEl = document.getElementById("connectionStatus");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const actionForm = document.getElementById("actionForm");

let streamRunning = true;
let trafficData = Array.from({ length: 12 }, () => Math.floor(Math.random() * 100));
let labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);

const trafficCtx = document.getElementById("trafficChart").getContext("2d");
const eventCtx = document.getElementById("eventChart").getContext("2d");

const trafficChart = new Chart(trafficCtx, {
  type: "line",
  data: {
    labels,
    datasets: [{
      label: "Requests",
      data: trafficData,
      borderColor: "#38bdf8",
      backgroundColor: "rgba(56, 189, 248, 0.15)",
      tension: 0.35,
      fill: true,
      pointRadius: 3
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" }
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" }
      }
    }
  }
});

const eventChart = new Chart(eventCtx, {
  type: "doughnut",
  data: {
    labels: ["API", "UI", "Background Jobs", "Errors"],
    datasets: [{
      data: [45, 25, 20, 10],
      backgroundColor: ["#38bdf8", "#22c55e", "#f59e0b", "#ef4444"],
      borderColor: "#111827",
      borderWidth: 2
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" }
      }
    }
  }
});

function addLog(message) {
  const li = document.createElement("li");
  const now = new Date().toLocaleTimeString();
  li.innerHTML = `${message}<small>${now}</small>`;
  activityLogEl.prepend(li);

  while (activityLogEl.children.length > 8) {
    activityLogEl.removeChild(activityLogEl.lastChild);
  }
}

function updateMetrics() {
  if (!streamRunning) return;

  const usersOnline = Math.floor(100 + Math.random() * 900);
  const requestsPerMin = Math.floor(200 + Math.random() * 1200);
  const errorRate = (Math.random() * 5).toFixed(1);

  usersOnlineEl.textContent = usersOnline;
  requestsPerMinEl.textContent = requestsPerMin;
  errorRateEl.textContent = `${errorRate}%`;

  trafficData.push(requestsPerMin);
  trafficData.shift();
  labels.push(new Date().toLocaleTimeString());
  labels.shift();

  trafficChart.data.labels = labels;
  trafficChart.data.datasets[0].data = trafficData;
  trafficChart.update();

  const eventData = [
    Math.floor(Math.random() * 60) + 20,
    Math.floor(Math.random() * 40) + 10,
    Math.floor(Math.random() * 30) + 5,
    Math.floor(Math.random() * 15) + 1
  ];
  eventChart.data.datasets[0].data = eventData;
  eventChart.update();

  addLog(`Live update received: ${requestsPerMin} req/min, ${usersOnline} users online`);
}

setInterval(updateMetrics, 2000);
updateMetrics();

toggleStreamBtn.addEventListener("click", () => {
  streamRunning = !streamRunning;
  toggleStreamBtn.textContent = streamRunning ? "Pause Stream" : "Resume Stream";
  connectionStatusEl.textContent = streamRunning ? "● Connected" : "● Paused";
  connectionStatusEl.style.background = streamRunning
    ? "rgba(34, 197, 94, 0.12)"
    : "rgba(245, 158, 11, 0.12)";
  connectionStatusEl.style.color = streamRunning ? "#86efac" : "#fcd34d";
  addLog(streamRunning ? "Stream resumed" : "Stream paused");
});

actionForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const actionName = document.getElementById("actionName").value.trim();
  const priority = document.getElementById("priority").value;
  const notes = document.getElementById("notes").value.trim();

  if (!actionName) {
    formFeedbackEl.textContent = "Action name is required.";
    formFeedbackEl.style.color = "#fca5a5";
    return;
  }

  const payload = {
    actionName,
    priority,
    notes,
    timestamp: new Date().toISOString()
  };

  formFeedbackEl.textContent = `Submitted: ${payload.actionName} (${payload.priority})`;
  formFeedbackEl.style.color = "#86efac";

  addLog(`Form submitted: ${payload.actionName} [${payload.priority}]`);

  actionForm.reset();
});
```

