  <script>
    const activeUsersEl = document.getElementById("activeUsers");
    const requestsPerMinEl = document.getElementById("requestsPerMin");
    const errorRateEl = document.getElementById("errorRate");
    const systemStatusEl = document.getElementById("systemStatus");
    const eventTable = document.getElementById("eventTable");
    const form = document.getElementById("dashboardForm");

    const labels = [];
    const trafficData = [];

    const ctx = document.getElementById("trafficChart").getContext("2d");
    const trafficChart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Requests",
          data: trafficData,
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 2
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        scales: {
          x: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          },
          y: {
            ticks: { color: "#9ca3af" },
            grid: { color: "rgba(255,255,255,0.06)" }
          }
        },
        plugins: {
          legend: {
            labels: { color: "#e5e7eb" }
          }
        }
      }
    });

    function randomInt(min, max) {
      return Math.floor(Math.random() * (max - min + 1)) + min;
    }

    function updateMetrics() {
      const activeUsers = randomInt(120, 980);
      const requests = randomInt(300, 2200);
      const errorRate = (Math.random() * 6).toFixed(1);

      activeUsersEl.textContent = activeUsers.toLocaleString();
      requestsPerMinEl.textContent = requests.toLocaleString();
      errorRateEl.textContent = `${errorRate}%`;

      if (errorRate < 2) {
        systemStatusEl.textContent = "Healthy";
        systemStatusEl.style.color = "#86efac";
      } else if (errorRate < 4) {
        systemStatusEl.textContent = "Degraded";
        systemStatusEl.style.color = "#fcd34d";
      } else {
        systemStatusEl.textContent = "Critical";
        systemStatusEl.style.color = "#fca5a5";
      }

      const now = new Date().toLocaleTimeString();
      labels.push(now);
      trafficData.push(requests);

      if (labels.length > 20) {
        labels.shift();
        trafficData.shift();
      }

      trafficChart.update();
    }

    function addEventRow({ label, value, status, notes }) {
      if (eventTable.querySelector("td[colspan]")) {
        eventTable.innerHTML = "";
      }

      const row = document.createElement("tr");
      const time = new Date().toLocaleTimeString();

      const statusClass = status === "ok" ? "ok" : status === "warn" ? "warn" : "bad";
      const statusText = status === "ok" ? "OK" : status === "warn" ? "Warning" : "Critical";

      row.innerHTML = `
        <td>${time}</td>
        <td>${label}</td>
        <td>${value}</td>
        <td><span class="status ${statusClass}">${statusText}</span></td>
        <td>${notes || "-"}</td>
      `;

      eventTable.prepend(row);
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const formData = new FormData(form);
      const data = {
        label: formData.get("label"),
        value: formData.get("value"),
        status: formData.get("status"),
        notes: formData.get("notes")
      };

      addEventRow(data);
      form.reset();
    });

    // Initial load
    updateMetrics();

    // Simulate real-time updates every 2 seconds
    setInterval(updateMetrics, 2000);
  </script>
</body>
