## 4) `app.js`

```javascript
const ctx = document.getElementById("realtimeChart").getContext("2d");

const settingsForm = document.getElementById("settingsForm");
const manualForm = document.getElementById("manualForm");
const pauseBtn = document.getElementById("pauseBtn");
const resetBtn = document.getElementById("resetBtn");

const chartTitle = document.getElementById("chartTitle");
const modeLabel = document.getElementById("modeLabel");
const connectionStatus = document.getElementById("connectionStatus");

const latestValueEl = document.getElementById("latestValue");
const averageValueEl = document.getElementById("averageValue");
const alertCountEl = document.getElementById("alertCount");
const eventLog = document.getElementById("eventLog");

const dashboardTitleInput = document.getElementById("dashboardTitle");
const dataSourceInput = document.getElementById("dataSource");
const updateIntervalInput = document.getElementById("updateInterval");
const thresholdInput = document.getElementById("threshold");

const manualLabelInput = document.getElementById("manualLabel");
const manualValueInput = document.getElementById("manualValue");

let labels = [];
let values = [];
let alerts = 0;
let paused = false;
let timer = null;
let updateInterval = 1000;
let threshold = 75;
let dataSource = "simulated";

const maxPoints = 20;

function logEvent(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLog.prepend(li);
}

function updateSummary() {
  const latest = values.length ? values[values.length - 1] : 0;
  const avg = values.length
    ? (values.reduce((sum, v) => sum + v, 0) / values.length).toFixed(1)
    : 0;

  latestValueEl.textContent = latest;
  averageValueEl.textContent = avg;
  alertCountEl.textContent = alerts;
}

function addDataPoint(label, value) {
  labels.push(label);
  values.push(value);

  if (labels.length > maxPoints) {
    labels.shift();
    values.shift();
  }

  if (value >= threshold) {
    alerts++;
    logEvent(`Alert: value ${value} exceeded threshold ${threshold}`);
  } else {
    logEvent(`Data received: ${label} = ${value}`);
  }

  chart.data.labels = labels;
  chart.data.datasets[0].data = values;
  chart.update();

  updateSummary();
}

function generateSimulatedValue() {
  return Math.floor(Math.random() * 100);
}

function tick() {
  if (paused) return;

  const value = generateSimulatedValue();
  const label = `T${labels.length + 1}`;
  addDataPoint(label, value);
}

function startStream() {
  clearInterval(timer);
  timer = setInterval(tick, updateInterval);
  logEvent(`Stream started with interval ${updateInterval}ms`);
}

const chart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Metric Value",
        data: values,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 4,
        pointHoverRadius: 6
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: {
          color: "#e5e7eb"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" }
      },
      y: {
        beginAtZero: true,
        suggestedMax: 100,
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.06)" }
      }
    }
  }
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  dataSource = dataSourceInput.value;
  updateInterval = parseInt(updateIntervalInput.value, 10) || 1000;
  threshold = parseInt(thresholdInput.value, 10) || 75;

  chartTitle.textContent = dashboardTitleInput.value || "Real-Time Dashboard";
  modeLabel.textContent = `Mode: ${dataSource === "simulated" ? "Simulated" : "Manual"}`;

  if (dataSource === "simulated") {
    connectionStatus.textContent = "Live";
    startStream();
  } else {
    connectionStatus.textContent = "Manual";
    clearInterval(timer);
    logEvent("Switched to manual mode");
  }

  logEvent("Settings applied");
});

manualForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const label = manualLabelInput.value.trim();
  const value = parseFloat(manualValueInput.value);

  if (!label || Number.isNaN(value)) {
    logEvent("Manual entry rejected: invalid label or value");
    return;
  }

  addDataPoint(label, value);
  manualLabelInput.value = "";
  manualValueInput.value = "";
});

pauseBtn.addEventListener("click", () => {
  paused = !paused;
  pauseBtn.textContent = paused ? "Resume" : "Pause";
  logEvent(paused ? "Stream paused" : "Stream resumed");
});

resetBtn.addEventListener("click", () => {
  labels = [];
  values = [];
  alerts = 0;
  eventLog.innerHTML = "";
  chart.data.labels = labels;
  chart.data.datasets[0].data = values;
  chart.update();
  updateSummary();
  logEvent("Dashboard reset");
});

startStream();
updateSummary();
logEvent("Dashboard initialized");
```

