## 4) `app.js`

```javascript
const usersOnlineEl = document.getElementById("usersOnline");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const eventLogEl = document.getElementById("eventLog");
const formMessageEl = document.getElementById("formMessage");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const settingsForm = document.getElementById("settingsForm");
const dashboardTitleInput = document.getElementById("dashboardTitle");
const refreshIntervalInput = document.getElementById("refreshInterval");
const showErrorsInput = document.getElementById("showErrors");
const connectionStatusEl = document.getElementById("connectionStatus");

let streamActive = true;
let refreshInterval = 1000;
let showErrors = true;
let timerId = null;

const labels = Array.from({ length: 20 }, (_, i) => `T-${19 - i}`);
const trafficData = Array.from({ length: 20 }, () => Math.floor(Math.random() * 100));

const ctx = document.getElementById("trafficChart").getContext("2d");
const trafficChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Traffic",
        data: trafficData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 2
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: "#e2e8f0"
        }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.15)" }
      }
    }
  }
});

function logEvent(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function updateMetrics() {
  const usersOnline = Math.max(0, 100 + Math.floor(Math.random() * 80));
  const requestsPerMin = Math.max(0, 700 + Math.floor(Math.random() * 300));
  const errorRate = showErrors
    ? (Math.random() * 3).toFixed(1)
    : (Math.random() * 0.5).toFixed(1);

  usersOnlineEl.textContent = usersOnline;
  requestsPerMinEl.textContent = requestsPerMin;
  errorRateEl.textContent = `${errorRate}%`;

  const nextValue = Math.floor(Math.random() * 100);
  trafficData.push(nextValue);
  trafficData.shift();

  trafficChart.update();

  if (showErrors && parseFloat(errorRate) > 2.2) {
    logEvent(`Warning: error rate spike detected (${errorRate}%)`);
  } else {
    logEvent(`Metrics updated: ${usersOnline} users, ${requestsPerMin} req/min`);
  }
}

function startStream() {
  clearInterval(timerId);
  timerId = setInterval(() => {
    if (streamActive) {
      updateMetrics();
    }
  }, refreshInterval);
}

toggleStreamBtn.addEventListener("click", () => {
  streamActive = !streamActive;
  toggleStreamBtn.textContent = streamActive ? "Pause Stream" : "Resume Stream";
  connectionStatusEl.textContent = streamActive ? "Live" : "Paused";
  logEvent(streamActive ? "Data stream resumed" : "Data stream paused");
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const title = dashboardTitleInput.value.trim();
  const interval = parseInt(refreshIntervalInput.value, 10);
  showErrors = showErrorsInput.checked;

  if (title) {
    document.title = title;
    document.querySelector(".topbar h1").textContent = title;
  }

  if (!Number.isNaN(interval) && interval >= 500) {
    refreshInterval = interval;
    startStream();
  }

  formMessageEl.textContent = "Settings applied successfully.";
  logEvent("Settings updated via form");
});

dashboardTitleInput.addEventListener("input", () => {
  formMessageEl.textContent = "";
});

refreshIntervalInput.addEventListener("input", () => {
  formMessageEl.textContent = "";
});

showErrorsInput.addEventListener("change", () => {
  formMessageEl.textContent = "";
});

startStream();
logEvent("Dashboard initialized");
```

