## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const activeUsersTrendEl = document.getElementById("activeUsersTrend");
const requestsTrendEl = document.getElementById("requestsTrend");
const errorTrendEl = document.getElementById("errorTrend");
const connectionStatusEl = document.getElementById("connectionStatus");
const pauseBtn = document.getElementById("pauseBtn");

const settingsForm = document.getElementById("settingsForm");
const dashboardNameInput = document.getElementById("dashboardName");
const updateIntervalInput = document.getElementById("updateInterval");
const alertThresholdInput = document.getElementById("alertThreshold");
const thresholdValueEl = document.getElementById("thresholdValue");
const enableAlertsInput = document.getElementById("enableAlerts");
const formOutput = document.getElementById("formOutput");
const eventsTable = document.getElementById("eventsTable");

let isPaused = false;
let updateInterval = 2000;
let timer = null;

let previousMetrics = {
  activeUsers: 120,
  requestsPerMin: 450,
  errorRate: 2.1
};

let metrics = { ...previousMetrics };

const ctx = document.getElementById("trafficChart").getContext("2d");
const trafficChart = new Chart(ctx, {
  type: "line",
  data: {
    labels: Array.from({ length: 10 }, (_, i) => `T-${9 - i}`),
    datasets: [
      {
        label: "Requests / Min",
        data: Array.from({ length: 10 }, () => 400 + Math.floor(Math.random() * 100)),
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true
      }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    scales: {
      x: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "#334155" }
      },
      y: {
        ticks: { color: "#cbd5e1" },
        grid: { color: "#334155" }
      }
    },
    plugins: {
      legend: {
        labels: { color: "#e2e8f0" }
      }
    }
  }
});

function randomDelta(min, max) {
  return Math.random() * (max - min) + min;
}

function updateMetrics() {
  previousMetrics = { ...metrics };

  metrics.activeUsers = Math.max(0, Math.round(metrics.activeUsers + randomDelta(-8, 15)));
  metrics.requestsPerMin = Math.max(0, Math.round(metrics.requestsPerMin + randomDelta(-30, 40)));
  metrics.errorRate = Math.max(0, +(metrics.errorRate + randomDelta(-0.4, 0.6)).toFixed(1));

  activeUsersEl.textContent = metrics.activeUsers;
  requestsPerMinEl.textContent = metrics.requestsPerMin;
  errorRateEl.textContent = `${metrics.errorRate}%`;

  const activeUsersChange = (((metrics.activeUsers - previousMetrics.activeUsers) / Math.max(previousMetrics.activeUsers, 1)) * 100).toFixed(1);
  const requestsChange = (((metrics.requestsPerMin - previousMetrics.requestsPerMin) / Math.max(previousMetrics.requestsPerMin, 1)) * 100).toFixed(1);

  activeUsersTrendEl.textContent = `${activeUsersChange >= 0 ? "+" : ""}${activeUsersChange}%`;
  requestsTrendEl.textContent = `${requestsChange >= 0 ? "+" : ""}${requestsChange}%`;
  errorTrendEl.textContent = metrics.errorRate > previousMetrics.errorRate ? "Rising" : metrics.errorRate < previousMetrics.errorRate ? "Falling" : "Stable";

  const chartData = trafficChart.data.datasets[0].data;
  chartData.push(metrics.requestsPerMin);
  if (chartData.length > 10) chartData.shift();

  trafficChart.data.labels.push(`T+${Date.now() % 1000}`);
  if (trafficChart.data.labels.length > 10) trafficChart.data.labels.shift();

  trafficChart.update();

  addEventRow("Metrics refreshed", metrics.errorRate > 5 ? "Warning" : "OK");
}

function addEventRow(eventText, statusText) {
  const now = new Date().toLocaleTimeString();

  if (eventsTable.children.length === 1 && eventsTable.children[0].children.length === 1) {
    eventsTable.innerHTML = "";
  }

  const row = document.createElement("tr");
  row.innerHTML = `
    <td>${now}</td>
    <td>${eventText}</td>
    <td>${statusText}</td>
  `;

  eventsTable.prepend(row);

  while (eventsTable.children.length > 6) {
    eventsTable.removeChild(eventsTable.lastElementChild);
  }
}

function startUpdates() {
  clearInterval(timer);
  timer = setInterval(() => {
    if (!isPaused) updateMetrics();
  }, updateInterval);
}

pauseBtn.addEventListener("click", () => {
  isPaused = !isPaused;
  pauseBtn.textContent = isPaused ? "Resume Updates" : "Pause Updates";
  connectionStatusEl.textContent = isPaused ? "Paused" : "Live";
  connectionStatusEl.style.background = isPaused ? "#f59e0b" : "#16a34a";
});

alertThresholdInput.addEventListener("input", () => {
  thresholdValueEl.textContent = alertThresholdInput.value;
});

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const dashboardName = dashboardNameInput.value.trim() || "Operations Dashboard";
  updateInterval = Math.max(500, parseInt(updateIntervalInput.value, 10) || 2000);
  const alertThreshold = parseInt(alertThresholdInput.value, 10);
  const alertsEnabled = enableAlertsInput.checked;

  formOutput.innerHTML = `
    <strong>Saved Settings</strong><br />
    Dashboard Name: ${dashboardName}<br />
    Update Interval: ${updateInterval} ms<br />
    Alert Threshold: ${alertThreshold}<br />
    Alerts Enabled: ${alertsEnabled ? "Yes" : "No"}
  `;

  document.title = dashboardName;
  startUpdates();
  addEventRow("Settings saved", "OK");
});

updateMetrics();
startUpdates();
```

