## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const eventLogEl = document.getElementById("eventLog");
const formFeedbackEl = document.getElementById("formFeedback");
const refreshBtn = document.getElementById("refreshBtn");
const controlForm = document.getElementById("controlForm");

const connectionStatus = document.getElementById("connectionStatus");

const ctx = document.getElementById("liveChart").getContext("2d");

const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
let chartData = labels.map(() => randomMetric(50, 100));

const liveChart = new Chart(ctx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Traffic",
        data: chartData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
        pointRadius: 3,
        pointBackgroundColor: "#38bdf8",
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(255,255,255,0.06)" },
      },
    },
  },
});

function randomMetric(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function addLog(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 6) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function updateMetrics() {
  const activeUsers = randomMetric(120, 980);
  const requestsPerMin = randomMetric(300, 1800);
  const errorRate = (Math.random() * 4).toFixed(1);

  activeUsersEl.textContent = activeUsers.toLocaleString();
  requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
  errorRateEl.textContent = `${errorRate}%`;

  chartData.push(requestsPerMin);
  chartData.shift();
  liveChart.data.datasets[0].data = chartData;
  liveChart.update();

  addLog(`Metrics refreshed: ${activeUsers} users, ${requestsPerMin} req/min, ${errorRate}% errors`);
}

function simulateConnectionPulse() {
  connectionStatus.textContent = "● Live";
  connectionStatus.style.background = "rgba(34, 197, 94, 0.12)";
  connectionStatus.style.color = "#86efac";
  connectionStatus.style.borderColor = "rgba(34, 197, 94, 0.25)";
}

refreshBtn.addEventListener("click", () => {
  updateMetrics();
  formFeedbackEl.textContent = "Dashboard refreshed successfully.";
});

controlForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const formData = new FormData(controlForm);
  const settings = Object.fromEntries(formData.entries());

  settings.notifications = formData.has("notifications");

  formFeedbackEl.textContent = "Settings saved successfully.";
  addLog(
    `Settings updated: mode=${settings.mode}, threshold=${settings.threshold}, notifications=${settings.notifications ? "on" : "off"}`
  );

  console.log("Saved settings:", settings);
});

controlForm.addEventListener("reset", () => {
  setTimeout(() => {
    formFeedbackEl.textContent = "Form reset.";
    addLog("Control panel reset to defaults.");
  }, 0);
});

setInterval(() => {
  updateMetrics();
  simulateConnectionPulse();
}, 3000);

updateMetrics();
addLog("Dashboard initialized.");
```

