## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const revenueEl = document.getElementById("revenue");
const ordersEl = document.getElementById("orders");
const conversionRateEl = document.getElementById("conversionRate");
const eventLogEl = document.getElementById("eventLog");
const formOutputEl = document.getElementById("formOutput");
const settingsForm = document.getElementById("settingsForm");
const dashboardNameInput = document.getElementById("dashboardName");
const refreshRateInput = document.getElementById("refreshRate");
const themeColorInput = document.getElementById("themeColor");

let refreshRate = 2000;
let updateInterval = null;
let accentColor = "#4f46e5";

const trafficCtx = document.getElementById("trafficChart").getContext("2d");
const revenueCtx = document.getElementById("revenueChart").getContext("2d");

const labels = Array.from({ length: 10 }, (_, i) => `T-${9 - i}`);
let trafficData = [12, 19, 8, 15, 22, 18, 25, 30, 28, 35];
let revenueData = [1200, 1500, 1100, 1800, 2100, 1900, 2400, 2600, 2500, 2900];

const trafficChart = new Chart(trafficCtx, {
  type: "line",
  data: {
    labels,
    datasets: [{
      label: "Visitors",
      data: trafficData,
      borderColor: accentColor,
      backgroundColor: "rgba(79, 70, 229, 0.15)",
      fill: true,
      tension: 0.35,
      pointRadius: 3
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.12)" }
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.12)" }
      }
    }
  }
});

const revenueChart = new Chart(revenueCtx, {
  type: "bar",
  data: {
    labels,
    datasets: [{
      label: "Revenue ($)",
      data: revenueData,
      backgroundColor: accentColor,
      borderRadius: 8
    }]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" }
      }
    },
    scales: {
      x: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.12)" }
      },
      y: {
        ticks: { color: "#94a3b8" },
        grid: { color: "rgba(148, 163, 184, 0.12)" }
      }
    }
  }
});

function logEvent(message) {
  const li = document.createElement("li");
  li.textContent = `[${new Date().toLocaleTimeString()}] ${message}`;
  eventLogEl.prepend(li);

  while (eventLogEl.children.length > 8) {
    eventLogEl.removeChild(eventLogEl.lastChild);
  }
}

function updateMetrics() {
  const activeUsers = Math.floor(Math.random() * 5000) + 1000;
  const revenue = Math.floor(Math.random() * 50000) + 10000;
  const orders = Math.floor(Math.random() * 300) + 50;
  const conversionRate = (Math.random() * 8 + 1).toFixed(2);

  activeUsersEl.textContent = activeUsers.toLocaleString();
  revenueEl.textContent = `$${revenue.toLocaleString()}`;
  ordersEl.textContent = orders.toLocaleString();
  conversionRateEl.textContent = `${conversionRate}%`;

  trafficData.push(Math.floor(Math.random() * 50) + 10);
  revenueData.push(Math.floor(Math.random() * 4000) + 1000);

  if (trafficData.length > 10) trafficData.shift();
  if (revenueData.length > 10) revenueData.shift();

  trafficChart.data.datasets[0].data = trafficData;
  revenueChart.data.datasets[0].data = revenueData;

  trafficChart.update();
  revenueChart.update();

  logEvent("Metrics updated in real time.");
}

function startAutoRefresh() {
  if (updateInterval) clearInterval(updateInterval);
  updateInterval = setInterval(updateMetrics, refreshRate);
  logEvent(`Auto-refresh set to ${refreshRate}ms.`);
}

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const dashboardName = dashboardNameInput.value.trim();
  refreshRate = parseInt(refreshRateInput.value, 10);
  accentColor = themeColorInput.value;

  document.documentElement.style.setProperty("--accent", accentColor);

  trafficChart.data.datasets[0].borderColor = accentColor;
  trafficChart.data.datasets[0].backgroundColor = `${accentColor}22`;
  revenueChart.data.datasets[0].backgroundColor = accentColor;

  trafficChart.update();
  revenueChart.update();

  startAutoRefresh();

  formOutputEl.textContent = `Applied settings for "${dashboardName || "Dashboard"}" with refresh rate ${refreshRate}ms.`;
  logEvent(`Settings applied: ${dashboardName || "Dashboard"} | ${refreshRate}ms | ${accentColor}`);
});

themeColorInput.addEventListener("input", () => {
  document.documentElement.style.setProperty("--accent", themeColorInput.value);
});

updateMetrics();
startAutoRefresh();
```

