function updateMetrics() {
  const visitorDelta = Math.floor(Math.random() * 20) - 5;
  const orderDelta = Math.floor(Math.random() * 4);
  const conversionDelta = (Math.random() * 1.2 - 0.4);

  visitors = Math.max(0, visitors + visitorDelta);
  orders = Math.max(0, orders + orderDelta);
  conversionRate = Math.max(0, conversionRate + conversionDelta);

  visitorsCountEl.textContent = visitors;
  ordersCountEl.textContent = orders;
  conversionRateEl.textContent = `${conversionRate.toFixed(1)}%`;

  trafficData.labels.shift();
  trafficData.labels.push("Now");
  trafficData.datasets[0].data.shift();
  trafficData.datasets[0].data.push(visitors);
  trafficChart.update();

  const categoryValues = categoryChart.data.datasets[0].data;
  categoryValues[0] = Math.max(1, categoryValues[0] + Math.floor(Math.random() * 3) - 1);
  categoryValues[1] = Math.max(1, categoryValues[1] + Math.floor(Math.random() * 2) - 1);
  categoryValues[2] = Math.max(1, categoryValues[2] + Math.floor(Math.random() * 2) - 1);
  categoryValues[3] = Math.max(1, categoryValues[3] + Math.floor(Math.random() * 2) - 1);
  categoryChart.update();

  logEvent(`Metrics updated: visitors=${visitors}, orders=${orders}, conversion=${conversionRate.toFixed(1)}%`);
}

function startLiveUpdates() {
  stopLiveUpdates();
  if (!liveUpdates) {
    connectionStatusEl.textContent = "Paused";
    return;
  }

  connectionStatusEl.textContent = "Connected";
  timer = setInterval(updateMetrics, updateInterval);
  logEvent(`Live updates started with interval ${updateInterval}ms`);
}

function stopLiveUpdates() {
  if (timer) {
    clearInterval(timer);
    timer = null;
  }
}

settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();

  dashboardTitle = dashboardTitleEl.value.trim() || "Real-Time Dashboard";
  updateInterval = Math.max(500, parseInt(updateIntervalEl.value, 10) || 2000);
  liveUpdates = liveUpdatesEl.checked;

  document.title = dashboardTitle;
  settingsOutputEl.textContent = JSON.stringify(
    {
      dashboardTitle,
      updateInterval,
      liveUpdates
    },
    null,
    2
  );

  logEvent(`Settings applied: title="${dashboardTitle}", interval=${updateInterval}, liveUpdates=${liveUpdates}`);
  startLiveUpdates();
});

liveUpdatesEl.addEventListener("change", () => {
  liveUpdates = liveUpdatesEl.checked;
  logEvent(`Live updates ${liveUpdates ? "enabled" : "disabled"}`);
  startLiveUpdates();
});

updateIntervalEl.addEventListener("change", () => {
  updateInterval = Math.max(500, parseInt(updateIntervalEl.value, 10) || 2000);
  logEvent(`Update interval changed to ${updateInterval}ms`);
  if (liveUpdates) startLiveUpdates();
});

dashboardTitleEl.value = dashboardTitle;
updateIntervalEl.value = updateInterval;
liveUpdatesEl.checked = liveUpdates;
settingsOutputEl.textContent = JSON.stringify(
  { dashboardTitle, updateInterval, liveUpdates },
  null,
  2
);

visitorsCountEl.textContent = visitors;
ordersCountEl.textContent = orders;
conversionRateEl.textContent = `${conversionRate.toFixed(1)}%`;

startLiveUpdates();
```

