## 4) `app.js`

```javascript
const activeUsersEl = document.getElementById("activeUsers");
const requestsPerMinEl = document.getElementById("requestsPerMin");
const errorRateEl = document.getElementById("errorRate");
const activityLogEl = document.getElementById("activityLog");
const formFeedbackEl = document.getElementById("formFeedback");
const connectionStatusEl = document.getElementById("connectionStatus");
const toggleStreamBtn = document.getElementById("toggleStreamBtn");
const controlForm = document.getElementById("controlForm");

const trafficCtx = document.getElementById("trafficChart").getContext("2d");
const submissionCtx = document.getElementById("submissionChart").getContext("2d");

let streamRunning = true;
let submissionCount = 0;

const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
const trafficData = labels.map(() => randomInt(40, 90));
const submissionData = labels.map(() => randomInt(5, 20));

const trafficChart = new Chart(trafficCtx, {
  type: "line",
  data: {
    labels,
    datasets: [
      {
        label: "Requests/min",
        data: trafficData,
        borderColor: "#38bdf8",
        backgroundColor: "rgba(56, 189, 248, 0.15)",
        tension: 0.35,
        fill: true,
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  },
});

const submissionChart = new Chart(submissionCtx, {
  type: "bar",
  data: {
    labels,
    datasets: [
      {
        label: "Form submissions",
        data: submissionData,
        backgroundColor: "#22c55e",
      },
    ],
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: { color: "#e5e7eb" },
      },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  },
});

function randomInt(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function addLog(message) {
  const li = document.createElement("li");
  const now = new Date().toLocaleTimeString();
  li.innerHTML = `${message}<small>${now}</small>`;
  activityLogEl.prepend(li);

  while (activityLogEl.children.length > 8) {
    activityLogEl.removeChild(activityLogEl.lastChild);
  }
}

function updateMetrics() {
  const activeUsers = randomInt(120, 980);
  const requestsPerMin = randomInt(40, 120);
  const errorRate = (Math.random() * 4).toFixed(1);

  activeUsersEl.textContent = activeUsers.toLocaleString();
  requestsPerMinEl.textContent = requestsPerMin.toLocaleString();
  errorRateEl.textContent = `${errorRate}%`;

  return { activeUsers, requestsPerMin, errorRate };
}

function updateCharts() {
  trafficChart.data.datasets[0].data.shift();
  trafficChart.data.datasets[0].data.push(randomInt(40, 120));
  trafficChart.update();

  submissionChart.data.datasets[0].data.shift();
  submissionChart.data.datasets[0].data.push(randomInt(5, 30));
  submissionChart.update();
}

function tick() {
  if (!streamRunning) return;

  const metrics = updateMetrics();
  updateCharts();

  if (metrics.errorRate > 3.0) {
    addLog(`High error rate detected: ${metrics.errorRate}%`);
  } else {
    addLog(`Metrics updated: ${metrics.activeUsers} users, ${metrics.requestsPerMin} req/min`);
  }
}

toggleStreamBtn.addEventListener("click", () => {
  streamRunning = !streamRunning;
  toggleStreamBtn.textContent = streamRunning ? "Pause Stream" : "Resume Stream";
  connectionStatusEl.textContent = streamRunning ? "Live" : "Paused";
  connectionStatusEl.style.background = streamRunning
    ? "rgba(34, 197, 94, 0.15)"
    : "rgba(245, 158, 11, 0.15)";
  connectionStatusEl.style.color = streamRunning ? "#86efac" : "#fde68a";
  addLog(streamRunning ? "Live stream resumed" : "Live stream paused");
});

controlForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const formData = new FormData(controlForm);
  const threshold = formData.get("threshold");
  const mode = formData.get("mode");
  const notifyEmail = formData.get("notifyEmail");

  if (!notifyEmail || !notifyEmail.includes("@")) {
    formFeedbackEl.textContent = "Please enter a valid notification email.";
    formFeedbackEl.style.color = "#fca5a5";
    return;
  }

  submissionCount += 1;
  submissionChart.data.datasets[0].data[submissionChart.data.datasets[0].data.length - 1] += 1;
  submissionChart.update();

  formFeedbackEl.textContent = `Settings applied: threshold=${threshold}, mode=${mode}, email=${notifyEmail}`;
  formFeedbackEl.style.color = "#86efac";

  addLog(`Settings applied: mode=${mode}, threshold=${threshold}`);
  controlForm.reset();
});

controlForm.addEventListener("reset", () => {
  formFeedbackEl.textContent = "Form reset.";
  formFeedbackEl.style.color = "#9ca3af";
});

updateMetrics();
addLog("Dashboard initialized");
setInterval(tick, 2000);
```

