## 4) `app.js`

```javascript
const state = {
  dashboardName: "Real-Time Dashboard",
  updateInterval: 1000,
  alertThreshold: 80,
  enableAlerts: true,
  streamActive: true,
  timer: null,
  chart: null,
  dataPoints: [],
  labels: []
};

const elements = {
  activeUsers: document.getElementById("activeUsers"),
  requestsPerSec: document.getElementById("requestsPerSec"),
  errorRate: document.getElementById("errorRate"),
  eventLog: document.getElementById("eventLog"),
  connectionStatus: document.getElementById("connectionStatus"),
  toggleStreamBtn: document.getElementById("toggleStreamBtn"),
  settingsForm: document.getElementById("settingsForm"),
  dashboardName: document.getElementById("dashboardName"),
  updateInterval: document.getElementById("updateInterval"),
  alertThreshold: document.getElementById("alertThreshold"),
  enableAlerts: document.getElementById("enableAlerts"),
  resetBtn: document.getElementById("resetBtn")
};

function logEvent(message, type = "info") {
  const li = document.createElement("li");
  const time = new Date().toLocaleTimeString();
  li.innerHTML = `<strong>[${time}]</strong> ${message}`;
  if (type === "alert") li.style.color = "#fca5a5";
  elements.eventLog.prepend(li);

  // Keep log manageable
  while (elements.eventLog.children.length > 20) {
    elements.eventLog.removeChild(elements.eventLog.lastChild);
  }
}

function randomBetween(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function generateDataPoint() {
  const activeUsers = randomBetween(120, 1200);
  const requestsPerSec = randomBetween(20, 300);
  const errorRate = Math.random() * 10; // 0-10%

  return { activeUsers, requestsPerSec, errorRate };
}

function updateMetrics(data) {
  elements.activeUsers.textContent = data.activeUsers.toLocaleString();
  elements.requestsPerSec.textContent = data.requestsPerSec.toLocaleString();
  elements.errorRate.textContent = `${data.errorRate.toFixed(1)}%`;

  if (state.enableAlerts && data.activeUsers > state.alertThreshold) {
    logEvent(`Alert: Active users exceeded threshold (${data.activeUsers} > ${state.alertThreshold})`, "alert");
  }
}

function updateChart(data) {
  const now = new Date().toLocaleTimeString();

  state.labels.push(now);
  state.dataPoints.push(data.requestsPerSec);

  if (state.labels.length > 12) {
    state.labels.shift();
    state.dataPoints.shift();
  }

  state.chart.data.labels = [...state.labels];
  state.chart.data.datasets[0].data = [...state.dataPoints];
  state.chart.update();
}

function setConnectionStatus(active) {
  elements.connectionStatus.textContent = active ? "● Live" : "● Paused";
  elements.connectionStatus.style.background = active
    ? "rgba(34, 197, 94, 0.15)"
    : "rgba(148, 163, 184, 0.15)";
  elements.connectionStatus.style.color = active ? "#86efac" : "#cbd5e1";
  elements.connectionStatus.style.borderColor = active
    ? "rgba(34, 197, 94, 0.3)"
    : "rgba(148, 163, 184, 0.3)";

  elements.toggleStreamBtn.textContent = active ? "Pause Stream" : "Resume Stream";
}

function startStream() {
  clearInterval(state.timer);
  state.timer = setInterval(() => {
    const data = generateDataPoint();
    updateMetrics(data);
    updateChart(data);
  }, state.updateInterval);

  state.streamActive = true;
  setConnectionStatus(true);
  logEvent("Data stream started");
}

function stopStream() {
  clearInterval(state.timer);
  state.streamActive = false;
  setConnectionStatus(false);
  logEvent("Data stream paused");
}

function initChart() {
  const ctx = document.getElementById("trafficChart").getContext("2d");

  state.chart = new Chart(ctx, {
    type: "line",
    data: {
      labels: [],
      datasets: [
        {
          label: "Requests/sec",
          data: [],
          borderColor: "#38bdf8",
          backgroundColor: "rgba(56, 189, 248, 0.15)",
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointHoverRadius: 5
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        legend: {
          labels: {
            color: "#e5e7eb"
          }
        }
      },
      scales: {
        x: {
          ticks: { color: "#94a3b8" },
          grid: { color: "rgba(255,255,255,0.06)" }
        },
        y: {
          ticks: { color: "#94a3b8" },
          grid: { color: "rgba(255,255,255,0.06)" }
        }
      }
    }
  });
}

function applySettingsFromForm() {
  state.dashboardName = elements.dashboardName.value.trim() || "Real-Time Dashboard";
  state.updateInterval = Math.max(500, parseInt(elements.updateInterval.value, 10) || 1000);
  state.alertThreshold = Math.max(0, parseInt(elements.alertThreshold.value, 10) || 80);
  state.enableAlerts = elements.enableAlerts.checked;

  document.title = state.dashboardName;
  logEvent(`Settings saved: interval=${state.updateInterval}ms, threshold=${state.alertThreshold}, alerts=${state.enableAlerts ? "on" : "off"}`);

  if (state.streamActive) {
    startStream();
  }
}

function resetSettings() {
  elements.dashboardName.value = "Real-Time Dashboard";
  elements.updateInterval.value = 1000;
  elements.alertThreshold.value = 80;
  elements.enableAlerts.checked = true;
  applySettingsFromForm();
  logEvent("Settings reset to defaults");
}

elements.settingsForm.addEventListener("submit", (e) => {
  e.preventDefault();
  applySettingsFromForm();
});

elements.toggleStreamBtn.addEventListener("click", () => {
  if (state.streamActive) stopStream();
  else startStream();
});

elements.resetBtn.addEventListener("click", resetSettings);

// Initialize
initChart();
applySettingsFromForm();
startStream();
logEvent("Dashboard initialized");
```

