<body>
  <header>
    <h1>Interactive Real-Time Dashboard</h1>
    <p>Live metrics, chart updates, and form submissions in one browser-based interface.</p>
  </header>

  <main class="container">
    <section class="card">
      <h2>Live Analytics</h2>

      <div class="stats">
        <div class="stat">
          <div class="label">Active Users</div>
          <div class="value" id="activeUsers">0</div>
          <div class="trend up" id="activeUsersTrend">+0%</div>
        </div>
        <div class="stat">
          <div class="label">Requests / Min</div>
          <div class="value" id="requestsPerMin">0</div>
          <div class="trend up" id="requestsTrend">+0%</div>
        </div>
        <div class="stat">
          <div class="label">Error Rate</div>
          <div class="value" id="errorRate">0%</div>
          <div class="trend down" id="errorTrend">0%</div>
        </div>
      </div>

      <div class="chart-wrap">
        <canvas id="realtimeChart"></canvas>
      </div>
    </section>

    <section class="card">
      <h2>Control Panel</h2>

      <form id="dashboardForm">
        <div>
          <label for="metricName">Metric Name</label>
          <input id="metricName" name="metricName" type="text" placeholder="e.g. Conversion Rate" required />
        </div>

        <div>
          <label for="metricType">Metric Type</label>
          <select id="metricType" name="metricType" required>
            <option value="line">Line</option>
            <option value="bar">Bar</option>
            <option value="gauge">Gauge (text only)</option>
          </select>
        </div>

        <div>
          <label for="metricValue">Initial Value</label>
          <input id="metricValue" name="metricValue" type="number" step="any" placeholder="e.g. 42" required />
        </div>

        <div>
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" placeholder="Add any context or configuration notes..."></textarea>
        </div>

        <button type="submit">Add Metric</button>
      </form>

      <div class="log">
        <h2 style="margin-top: 0;">Activity Log</h2>
        <div id="activityLog"></div>
      </div>
    </section>
  </main>

  <script>
    // --- Chart setup ---
    const ctx = document.getElementById('realtimeChart').getContext('2d');
    const labels = Array.from({ length: 12 }, (_, i) => `T-${11 - i}`);
    const dataPoints = labels.map(() => Math.floor(Math.random() * 100));

    const realtimeChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'System Load',
          data: dataPoints,
          borderColor: '#38bdf8',
          backgroundColor: 'rgba(56, 189, 248, 0.15)',
          tension: 0.35,
          fill: true,
          pointRadius: 3,
          pointHoverRadius: 5
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        plugins: {
          legend: {
            labels: { color: '#e5e7eb' }
          }
        },
        scales: {
          x: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' }
          },
          y: {
            ticks: { color: '#9ca3af' },
            grid: { color: 'rgba(148, 163, 184, 0.15)' },
            beginAtZero: true
          }
        }
      }
    });

    // --- DOM references ---
    const activeUsersEl = document.getElementById('activeUsers');
    const requestsPerMinEl = document.getElementById('requestsPerMin');
    const errorRateEl = document.getElementById('errorRate');
    const activeUsersTrendEl = document.getElementById('activeUsersTrend');
    const requestsTrendEl = document.getElementById('requestsTrend');
    const errorTrendEl = document.getElementById('errorTrend');
    const activityLog = document.getElementById('activityLog');
    const form = document.getElementById('dashboardForm');

    // --- State ---
    let activeUsers = 120;
    let requestsPerMin = 860;
    let errorRate = 2.4;

    function addLog(message) {
      const item = document.createElement('div');
      item.className = 'log-item';
      item.innerHTML = `
        <div>${message}</div>
        <div class="small">${new Date().toLocaleTimeString()}</div>
      `;
      activityLog.prepend(item);
    }

    function updateStats() {
      const prevUsers = activeUsers;
      const prevRequests = requestsPerMin;
      const prevError = errorRate;

      activeUsers += Math.floor(Math.random() * 11 - 5);
      requestsPerMin += Math.floor(Math.random() * 41 - 20);
      errorRate += (Math.random() * 0.8 - 0.4);

      activeUsers = Math.max(0, activeUsers);
      requestsPerMin = Math.max(0, requestsPerMin);
      errorRate = Math.max(0, Math.min(100, errorRate));

      activeUsersEl.textContent = activeUsers;
      requestsPerMinEl.textContent = requestsPerMin;
      errorRateEl.textContent = errorRate.toFixed(1) + '%';

      const userDelta = prevUsers ? (((activeUsers - prevUsers) / prevUsers) * 100).toFixed(1) : 0;
      const reqDelta = prevRequests ? (((requestsPerMin - prevRequests) / prevRequests) * 100).toFixed(1) : 0;
      const errDelta = prevError ? (((errorRate - prevError) / prevError) * 100).toFixed(1) : 0;

      activeUsersTrendEl.textContent = `${userDelta >= 0 ? '+' : ''}${userDelta}%`;
      requestsTrendEl.textContent = `${reqDelta >= 0 ? '+' : ''}${reqDelta}%`;
      errorTrendEl.textContent = `${errDelta >= 0 ? '+' : ''}${errDelta}%`;

      activeUsersTrendEl.className = `trend ${userDelta >= 0 ? 'up' : 'down'}`;
      requestsTrendEl.className = `trend ${reqDelta >= 0 ? 'up' : 'down'}`;
      errorTrendEl.className = `trend ${errDelta >= 0 ? 'up' : 'down'}`;
    }

    function updateChart() {
      const nextValue = Math.floor(Math.random() * 100);
      realtimeChart.data.labels.push(new Date().toLocaleTimeString());
      realtimeChart.data.datasets[0].data.push(nextValue);

      if (realtimeChart.data.labels.length > 12) {
        realtimeChart.data.labels.shift();
        realtimeChart.data.datasets[0].data.shift();
      }

      realtimeChart.update();
    }

    // Simulated real-time updates
    setInterval(() => {
      updateStats();
      updateChart();
    }, 2000);

    // Form handling
    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const metricName = document.getElementById('metricName').value.trim();
      const metricType = document.getElementById('metricType').value;
      const metricValue = document.getElementById('metricValue').value;
      const notes = document.getElementById('notes').value.trim();

      addLog(`
        <strong>Metric added:</strong> ${metricName}
        <br><span class="small">Type: ${metricType} | Initial Value: ${metricValue}</span>
        ${notes ? `<br><span class="small">Notes: ${notes}</span>` : ''}
      `);

      form.reset();
    });

    // Initial log entry
    addLog('Dashboard initialized and live updates started.');
  </script>
</body>
</html>
