      color: var(--muted);
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 12px;
      margin-bottom: 16px;
    }

    .stat {
      background: #0b1220;
      border-radius: 10px;
      padding: 12px;
      text-align: center;
    }

    .stat strong {
      display: block;
      font-size: 22px;
      margin-top: 6px;
      color: var(--success);
    }

    @media (max-width: 800px) {
      .dashboard {
        grid-template-columns: 1fr;
      }
      .stats {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Interactive Dashboard</h1>
  </header>

  <main class="dashboard">
    <section class="card">
      <h2>Real-Time Chart</h2>
      <canvas id="chart" width="900" height="300"></canvas>
      <div class="stats">
        <div class="stat">
          <span>Current</span>
          <strong id="currentValue">0</strong>
        </div>
        <div class="stat">
          <span>Min</span>
          <strong id="minValue">0</strong>
        </div>
        <div class="stat">
          <span>Max</span>
          <strong id="maxValue">0</strong>
        </div>
      </div>
    </section>

    <aside class="card">
      <h2>Add Entry</h2>
      <form id="entryForm">
        <input type="text" id="name" placeholder="Name" required />
        <input type="number" id="value" placeholder="Value" required />
        <button type="submit">Add</button>
      </form>

      <h2 style="margin-top: 20px;">Entries</h2>
      <ul id="entryList"></ul>
    </aside>
  </main>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");
    const currentValueEl = document.getElementById("currentValue");
    const minValueEl = document.getElementById("minValue");
    const maxValueEl = document.getElementById("maxValue");
    const entryForm = document.getElementById("entryForm");
    const entryList = document.getElementById("entryList");

    let data = Array.from({ length: 20 }, () => Math.floor(Math.random() * 100));
    let entries = [];

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const padding = 30;
      const chartWidth = canvas.width - padding * 2;
      const chartHeight = canvas.height - padding * 2;
      const max = Math.max(...data);
      const min = Math.min(...data);
      const stepX = chartWidth / (data.length - 1);

      // axes
      ctx.strokeStyle = "#334155";
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, canvas.height - padding);
      ctx.lineTo(canvas.width - padding, canvas.height - padding);
      ctx.stroke();

      // line
      ctx.strokeStyle = "#38bdf8";
      ctx.lineWidth = 3;
      ctx.beginPath();

      data.forEach((value, i) => {
        const x = padding + i * stepX;
        const y = padding + chartHeight - ((value - min) / (max - min || 1)) * chartHeight;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // points
      ctx.fillStyle = "#f8fafc";
      data.forEach((value, i) => {
        const x = padding + i * stepX;
        const y = padding + chartHeight - ((value - min) / (max - min || 1)) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });

      currentValueEl.textContent = data[data.length - 1];
      minValueEl.textContent = min;
      maxValueEl.textContent = max;
    }

    function updateData() {
      data.push(Math.floor(Math.random() * 100));
      if (data.length > 20) data.shift();
      drawChart();
    }

    entryForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const name = document.getElementById("name").value.trim();
      const value = document.getElementById("value").value.trim();

      if (!name || value === "") return;

      entries.unshift({ name, value });
      renderEntries();
      entryForm.reset();
    });

    function renderEntries() {
      entryList.innerHTML = "";
      entries.forEach((entry) => {
        const li = document.createElement("li");
        li.innerHTML = `<span>${entry.name}</span><span class="badge">${entry.value}</span>`;
        entryList.appendChild(li);
      });
    }

    drawChart();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
