      addTableRow(name, value);

      dataForm.reset();
    });

    // Simulated real-time updates
    setInterval(() => {
      const randomValue = Math.floor(Math.random() * 100);
      const timestamp = new Date().toLocaleTimeString();
      addDataPoint(timestamp, randomValue);
    }, 2000);
