      padding-left: 18px;
      margin: 0;
    }

    @media (max-width: 800px) {
      .container {
        grid-template-columns: 1fr;
      }
      .metrics {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <header>
    <h1>Real-Time Dashboard</h1>
  </header>

  <div class="container">
    <div class="card">
      <div class="metrics">
        <div class="metric">
          <h3>Current Value</h3>
          <p id="currentValue">0</p>
        </div>
        <div class="metric">
          <h3>Average</h3>
          <p id="averageValue">0</p>
        </div>
        <div class="metric">
          <h3>Points</h3>
          <p id="pointCount">0</p>
        </div>
      </div>

      <canvas id="chart" width="900" height="300"></canvas>
    </div>

    <div class="card">
      <h2>Add Data Point</h2>
      <form id="dataForm">
        <div>
          <label for="valueInput">Value</label>
          <input type="number" id="valueInput" placeholder="Enter a number" required />
        </div>
        <button type="submit">Add Point</button>
      </form>

      <h2 style="margin-top: 24px;">Recent Values</h2>
      <ul id="valueList"></ul>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const currentValueEl = document.getElementById("currentValue");
    const averageValueEl = document.getElementById("averageValue");
    const pointCountEl = document.getElementById("pointCount");
    const valueListEl = document.getElementById("valueList");
    const dataForm = document.getElementById("dataForm");
    const valueInput = document.getElementById("valueInput");

    let data = [12, 19, 8, 15, 22, 18];

    function updateMetrics() {
      const current = data[data.length - 1] ?? 0;
      const avg = data.reduce((a, b) => a + b, 0) / data.length;

      currentValueEl.textContent = current.toFixed(1);
      averageValueEl.textContent = avg.toFixed(1);
      pointCountEl.textContent = data.length;
    }

    function updateList() {
      valueListEl.innerHTML = "";
      data.slice(-5).reverse().forEach(value => {
        const li = document.createElement("li");
        li.textContent = value.toFixed(1);
        valueListEl.appendChild(li);
      });
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const padding = 40;
      const chartWidth = canvas.width - padding * 2;
      const chartHeight = canvas.height - padding * 2;

      const max = Math.max(...data, 10);
      const min = Math.min(...data, 0);
      const range = max - min || 1;

      // axes
      ctx.strokeStyle = "#999";
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, canvas.height - padding);
      ctx.lineTo(canvas.width - padding, canvas.height - padding);
      ctx.stroke();

      // line
      ctx.strokeStyle = "#2563eb";
      ctx.lineWidth = 2;
      ctx.beginPath();

      data.forEach((value, index) => {
        const x = padding + (index / (data.length - 1 || 1)) * chartWidth;
        const y = padding + (1 - (value - min) / range) * chartHeight;

        if (index === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      });

      ctx.stroke();

      // points
      ctx.fillStyle = "#ef4444";
      data.forEach((value, index) => {
        const x = padding + (index / (data.length - 1 || 1)) * chartWidth;
        const y = padding + (1 - (value - min) / range) * chartHeight;
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, Math.PI * 2);
        ctx.fill();
      });
    }

    function render() {
      updateMetrics();
      updateList();
      drawChart();
    }

    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const value = parseFloat(valueInput.value);
      if (!isNaN(value)) {
        data.push(value);
        valueInput.value = "";
        render();
      }
    });

    // Simulated real-time updates
    setInterval(() => {
      const last = data[data.length - 1];
      const next = Math.max(0, last + (Math.random() * 10 - 5));
      data.push(next);
      if (data.length > 20) data.shift();
      render();
    }, 2000);

    render();
  </script>
</body>
</html>
```

