    const ctx = document.getElementById('liveChart').getContext('2d');
    const currentValueEl = document.getElementById('currentValue');
    const itemCountEl = document.getElementById('itemCount');
    const dataTable = document.getElementById('dataTable');
    const dataForm = document.getElementById('dataForm');
    const nameInput = document.getElementById('nameInput');
    const valueInput = document.getElementById('valueInput');

    let labels = [];
    let values = [];
    let items = [];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Value',
          data: values,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.15)',
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function renderTable() {
      dataTable.innerHTML = '';
      items.forEach((item, index) => {
        const row = document.createElement('tr');
        row.innerHTML = `
          <td>${item.name}</td>
          <td>${item.value}</td>
          <td><button onclick="removeItem(${index})">Delete</button></td>
        `;
        dataTable.appendChild(row);
      });
      itemCountEl.textContent = items.length;
    }

    function updateChart() {
      chart.data.labels = labels;
      chart.data.datasets[0].data = values;
      chart.update();
      currentValueEl.textContent = values.length ? values[values.length - 1] : 0;
    }

    function addItem(name, value) {
      items.push({ name, value });
      labels.push(name);
      values.push(value);
      renderTable();
      updateChart();
    }

    function removeItem(index) {
      items.splice(index, 1);
      labels.splice(index, 1);
      values.splice(index, 1);
      renderTable();
      updateChart();
    }

    dataForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const name = nameInput.value.trim();
      const value = Number(valueInput.value);

      if (!name || Number.isNaN(value)) return;

      addItem(name, value);
      dataForm.reset();
      nameInput.focus();
    });

    // Simulate real-time incoming data every 2 seconds
    setInterval(() => {
      const randomValue = Math.floor(Math.random() * 100);
      const timestamp = new Date().toLocaleTimeString();
      addItem(timestamp, randomValue);
    }, 2000);
  </script>
