    <section class="card">
      <h2>Live Data Chart</h2>
      <div class="controls">
        <button id="startBtn">Start Stream</button>
        <button id="stopBtn" class="secondary">Stop Stream</button>
      </div>
      <canvas id="liveChart" height="100"></canvas>
      <div class="status" id="streamStatus">Stream stopped.</div>
    </section>

    <section class="card">
      <h2>Form Handling</h2>
      <form id="itemForm">
        <input type="text" id="itemInput" placeholder="Enter a new item" required />
