    const ctx = document.getElementById('liveChart').getContext('2d');
    const labels = [];
    const dataPoints = [];

    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels,
        datasets: [{
          label: 'Live Value',
          data: dataPoints,
          borderColor: '#2563eb',
          backgroundColor: 'rgba(37, 99, 235, 0.15)',
          fill: true,
          tension: 0.3
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });

    let streamInterval = null;
    let tick = 0;

    function addRandomData() {
      tick++;
      const value = Math.floor(Math.random() * 100);

      labels.push(`T${tick}`);
      dataPoints.push(value);

      if (labels.length > 12) {
        labels.shift();
        dataPoints.shift();
      }

      chart.update();
      document.getElementById('streamStatus').textContent = `Streaming... Latest value: ${value}`;
