  <header>
    <h1>Minimal Live Dashboard</h1>
  </header>

  <div class="container">
    <div class="card">
      <div class="controls">
        <button id="startBtn">Start Feed</button>
        <button id="stopBtn" class="secondary">Stop Feed</button>
        <button id="resetBtn" class="danger">Reset</button>
      </div>

      <div class="stat" id="latestValue">0</div>
      <p>Latest real-time value</p>

      <canvas id="liveChart"></canvas>
    </div>

    <div class="card">
      <h2>Form Input</h2>
      <form id="noteForm">
        <input type="text" id="noteInput" placeholder="Enter a note..." required />
        <button type="submit">Add</button>
      </form>

      <h3>Submitted Notes</h3>
      <ul id="notesList"></ul>
    </div>
  </div>

  <script>
    const latestValueEl = document.getElementById("latestValue");
    const startBtn = document.getElementById("startBtn");
    const stopBtn = document.getElementById("stopBtn");
    const resetBtn = document.getElementById("resetBtn");
    const noteForm = document.getElementById("noteForm");
    const noteInput = document.getElementById("noteInput");
    const notesList = document.getElementById("notesList");

    const labels = [];
    const dataPoints = [];
    let counter = 0;
    let feedInterval = null;

    const ctx = document.getElementById("liveChart").getContext("2d");
    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Live Data",
          data: dataPoints,
          borderColor: "#2563eb",
          backgroundColor: "rgba(37, 99, 235, 0.15)",
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });

    function addDataPoint() {
      counter++;
      const value = Math.floor(Math.random() * 100);

      labels.push(counter);
      dataPoints.push(value);

      if (labels.length > 20) {
        labels.shift();
        dataPoints.shift();
      }

      latestValueEl.textContent = value;
      chart.update();
    }

    startBtn.addEventListener("click", () => {
      if (feedInterval) return;
      addDataPoint();
      feedInterval = setInterval(addDataPoint, 1000);
    });

    stopBtn.addEventListener("click", () => {
      clearInterval(feedInterval);
      feedInterval = null;
    });

    resetBtn.addEventListener("click", () => {
      clearInterval(feedInterval);
      feedInterval = null;
      counter = 0;
      labels.length = 0;
      dataPoints.length = 0;
      latestValueEl.textContent = "0";
      chart.update();
    });

    noteForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const text = noteInput.value.trim();
      if (!text) return;

      const li = document.createElement("li");
      li.textContent = text;
      notesList.appendChild(li);

      noteInput.value = "";
      noteInput.focus();
    });
  </script>
</body>
