  </header>

  <main class="container">
    <section class="card">
      <div class="stats">
        <div class="stat">
          Live Value
          <strong id="liveValue">0</strong>
        </div>
        <div class="stat">
          Points
          <strong id="pointCount">0</strong>
        </div>
        <div class="stat">
          Average
          <strong id="avgValue">0</strong>
        </div>
      </div>

      <canvas id="chart" width="900" height="300"></canvas>
    </section>

    <aside class="card">
      <h2>Add Data</h2>
      <form id="dataForm">
        <label>
          Label
          <input type="text" id="labelInput" placeholder="e.g. Sales" required />
        </label>
        <label>
          Value
          <input type="number" id="valueInput" placeholder="e.g. 42" required />
        </label>
        <button type="submit">Add Point</button>
      </form>
    </aside>
