  <script>
    const canvas = document.getElementById("chart");
    const ctx = canvas.getContext("2d");

    const liveValueEl = document.getElementById("liveValue");
    const pointCountEl = document.getElementById("pointCount");
    const avgValueEl = document.getElementById("avgValue");

    const form = document.getElementById("dataForm");
    const labelInput = document.getElementById("labelInput");
    const valueInput = document.getElementById("valueInput");

    let data = [
      { label: "A", value: 20 },
      { label: "B", value: 35 },
      { label: "C", value: 28 }
    ];

    function updateStats() {
      const values = data.map(d => d.value);
      const sum = values.reduce((a, b) => a + b, 0);
      const avg = values.length ? (sum / values.length).toFixed(1) : 0;

      liveValueEl.textContent = values[values.length - 1] ?? 0;
      pointCountEl.textContent = data.length;
      avgValueEl.textContent = avg;
    }

    function drawChart() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const padding = 40;
      const chartWidth = canvas.width - padding * 2;
      const chartHeight = canvas.height - padding * 2;

      const values = data.map(d => d.value);
      const maxValue = Math.max(...values, 1);
      const barWidth = chartWidth / data.length - 10;

      // axes
      ctx.strokeStyle = "#999";
      ctx.beginPath();
      ctx.moveTo(padding, padding);
      ctx.lineTo(padding, padding + chartHeight);
      ctx.lineTo(padding + chartWidth, padding + chartHeight);
      ctx.stroke();

      data.forEach((item, index) => {
        const barHeight = (item.value / maxValue) * (chartHeight - 20);
        const x = padding + index * (barWidth + 10) + 5;
        const y = padding + chartHeight - barHeight;

        ctx.fillStyle = "#2563eb";
        ctx.fillRect(x, y, barWidth, barHeight);

        ctx.fillStyle = "#111";
        ctx.font = "12px Arial";
        ctx.textAlign = "center";
        ctx.fillText(item.label, x + barWidth / 2, canvas.height - 10);
        ctx.fillText(item.value, x + barWidth / 2, y - 6);
      });
    }

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const label = labelInput.value.trim();
      const value = Number(valueInput.value);

      if (!label || Number.isNaN(value)) return;

      data.push({ label, value });

      labelInput.value = "";
      valueInput.value = "";

      updateStats();
      drawChart();
    });

    // Simulate real-time updates
    setInterval(() => {
      const randomValue = Math.floor(Math.random() * 100);
      data.push({
        label: `T${data.length + 1}`,
        value: randomValue
      });

      // keep last 10 points
      if (data.length > 10) data.shift();

      updateStats();
      drawChart();
    }, 2000);

    updateStats();
    drawChart();
  </script>
</body>
