    </div>

    <div class="grid">
      <div class="card">
        <h2>Real-time Metric</h2>
        <div class="stat" id="currentValue">0</div>
        <canvas id="chart" height="120"></canvas>
      </div>

      <div class="card">
        <h2>Add Data Item</h2>
        <form id="itemForm">
          <input type="text" id="itemName" placeholder="Item name" required />
          <input type="number" id="itemValue" placeholder="Value" required />
          <button type="submit">Add</button>
        </form>

        <ul id="itemList"></ul>
      </div>
    </div>
  </div>

  <script>
    // Clock
    function updateClock() {
      document.getElementById("clock").textContent = new Date().toLocaleTimeString();
    }
    setInterval(updateClock, 1000);
    updateClock();

    // Chart setup
    const ctx = document.getElementById("chart").getContext("2d");
    const labels = [];
    const data = [];

    const chart = new Chart(ctx, {
      type: "line",
      data: {
        labels,
        datasets: [{
          label: "Live Value",
          data,
          borderColor: "#2563eb",
          backgroundColor: "rgba(37, 99, 235, 0.15)",
          tension: 0.3,
          fill: true
        }]
      },
      options: {
        responsive: true,
        animation: false,
        scales: {
          y: { beginAtZero: true }
        }
      }
    });

    // Simulated real-time updates
    const currentValueEl = document.getElementById("currentValue");
    setInterval(() => {
      const value = Math.floor(Math.random() * 100);

      labels.push(new Date().toLocaleTimeString());
      data.push(value);

      if (labels.length > 10) {
        labels.shift();
        data.shift();
      }

      currentValueEl.textContent = value;
      chart.update();
    }, 2000);

    // Form handling
    const form = document.getElementById("itemForm");
    const itemList = document.getElementById("itemList");

    form.addEventListener("submit", (e) => {
      e.preventDefault();

      const name = document.getElementById("itemName").value.trim();
      const value = document.getElementById("itemValue").value.trim();

      if (!name || value === "") return;

      const li = document.createElement("li");
      li.innerHTML = `<span>${name}</span><strong>${value}</strong>`;
      itemList.prepend(li);

      form.reset();
    });
  </script>
</body>
