        responsive: true,
        animation: false,
        scales: {
          y: {
            beginAtZero: true
          }
        }
      }
    });

    function updateMetric() {
      const latest = data[data.length - 1] ?? 0;
      liveMetric.textContent = latest;
    }

    function addDataPoint(value) {
      const nextLabel = `T${labels.length + 1}`;
      labels.push(nextLabel);
      data.push(value);

      // Keep only last 20 points
      if (data.length > 20) {
        labels.shift();
        data.shift();
      }

      chart.update();
      updateMetric();
    }

    // Form handling
    dataForm.addEventListener("submit", (e) => {
      e.preventDefault();
      const value = Number(valueInput.value);
      if (!Number.isNaN(value)) {
        addDataPoint(value);
        valueInput.value = "";
      }
    });

    // Simulate real-time updates every second
    setInterval(() => {
      const randomValue = Math.floor(Math.random() * 100);
      addDataPoint(randomValue);
    }, 1000);

    updateMetric();
  </script>
