## `background.js`

This keeps the extension enabled state in sync with storage and can be expanded later for logging or per-site controls.

```js
const DEFAULT_ENABLED = true;

chrome.runtime.onInstalled.addListener(async () => {
  const { enabled } = await chrome.storage.sync.get({ enabled: DEFAULT_ENABLED });
  await setBlockingEnabled(enabled);
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes.enabled) {
    await setBlockingEnabled(changes.enabled.newValue);
  }
});

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }
}
```

