## `background.js`

This keeps the extension state in sync with the popup toggle.

```js
const DEFAULT_ENABLED = true;

chrome.runtime.onInstalled.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.sync.get("blockingEnabled");
  if (blockingEnabled === undefined) {
    await chrome.storage.sync.set({ blockingEnabled: DEFAULT_ENABLED });
  }
  await updateRules();
});

chrome.runtime.onStartup.addListener(updateRules);

chrome.storage.onChanged.addListener((changes, areaName) => {
  if (areaName === "sync" && changes.blockingEnabled) {
    updateRules();
  }
});

async function updateRules() {
  const { blockingEnabled } = await chrome.storage.sync.get("blockingEnabled");
  const enabled = blockingEnabled !== false;

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }
}
```

