## `popup.js`

This example stores an enabled/disabled state in `chrome.storage` and updates the rules accordingly.

```js
const RULESET_ID = "tracker_rules";

async function getEnabled() {
  const result = await chrome.storage.local.get({ enabled: true });
  return result.enabled;
}

async function setEnabled(enabled) {
  await chrome.storage.local.set({ enabled });
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [RULESET_ID]
    });
  }
}

async function refreshUI() {
  const enabled = await getEnabled();
  const status = document.getElementById("status");
  const btn = document.getElementById("toggleBtn");

  if (enabled) {
    status.textContent = "Protection is ON";
    btn.textContent = "Disable protection";
    btn.classList.remove("off");
  } else {
    status.textContent = "Protection is OFF";
    btn.textContent = "Enable protection";
    btn.classList.add("off");
  }
}

document.getElementById("toggleBtn").addEventListener("click", async () => {
  const enabled = await getEnabled();
  await setEnabled(!enabled);
  await refreshUI();
});

refreshUI();
```

