## `background.js`

This stores the enabled/disabled state and updates the rules accordingly.

```js
const DEFAULT_ENABLED = true;

async function setBlockingEnabled(enabled) {
  const ruleIds = [1, 2, 3, 4, 5, 6, 7, 8];

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["default_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["default_rules"]
    });
  }

  await chrome.storage.local.set({ blockingEnabled: enabled });
}

async function init() {
  const { blockingEnabled } = await chrome.storage.local.get("blockingEnabled");
  const enabled = typeof blockingEnabled === "boolean" ? blockingEnabled : DEFAULT_ENABLED;
  await setBlockingEnabled(enabled);
}

chrome.runtime.onInstalled.addListener(() => {
  init();
});

chrome.runtime.onStartup.addListener(() => {
  init();
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "SET_BLOCKING_ENABLED") {
    setBlockingEnabled(Boolean(message.enabled))
      .then(() => sendResponse({ ok: true }))
      .catch((error) => sendResponse({ ok: false, error: String(error) }));
    return true;
  }

  if (message?.type === "GET_BLOCKING_ENABLED") {
    chrome.storage.local.get("blockingEnabled").then((result) => {
      sendResponse({
        ok: true,
        enabled: typeof result.blockingEnabled === "boolean" ? result.blockingEnabled : DEFAULT_ENABLED
      });
    });
    return true;
  }
});
```

