async function getEnabled() {
  const res = await chrome.runtime.sendMessage({ type: "GET_BLOCKING_ENABLED" });
  return res.enabled;
}

async function setEnabled(enabled) {
  await chrome.runtime.sendMessage({
    type: "SET_BLOCKING_ENABLED",
    enabled
  });
}

function render(enabled) {
  stateEl.textContent = enabled ? "On" : "Off";
  toggleBtn.textContent = enabled ? "Disable blocking" : "Enable blocking";
  toggleBtn.className = enabled ? "off" : "on";
  statusTextEl.textContent = enabled
    ? "Tracking script blocking is enabled."
    : "Tracking script blocking is disabled.";
}

(async () => {
  const enabled = await getEnabled();
  render(enabled);

  toggleBtn.addEventListener("click", async () => {
    const current = await getEnabled();
    const next = !current;
    await setEnabled(next);
    render(next);
  });
})();
