## `background.js`

This keeps track of whether blocking is enabled and updates the dynamic rules accordingly.

```js
const STORAGE_KEY = "privacyBlockerEnabled";

async function setBlockingEnabled(enabled) {
  await chrome.storage.local.set({ [STORAGE_KEY]: enabled });

  // Enable/disable the static ruleset
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }
}

async function getBlockingEnabled() {
  const result = await chrome.storage.local.get(STORAGE_KEY);
  return result[STORAGE_KEY] ?? true;
}

chrome.runtime.onInstalled.addListener(async () => {
  const enabled = await getBlockingEnabled();
  await setBlockingEnabled(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const enabled = await getBlockingEnabled();
  await setBlockingEnabled(enabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "SET_BLOCKING_ENABLED") {
    setBlockingEnabled(Boolean(message.enabled))
      .then(() => sendResponse({ ok: true }))
      .catch((error) => sendResponse({ ok: false, error: String(error) }));
    return true; // async response
  }

  if (message?.type === "GET_BLOCKING_ENABLED") {
    getBlockingEnabled()
      .then((enabled) => sendResponse({ ok: true, enabled }))
      .catch((error) => sendResponse({ ok: false, error: String(error) }));
    return true;
  }
});
```

