function refreshUI() {
  chrome.runtime.sendMessage({ type: "getStatus" }, (response) => {
    const enabled = response?.enabled ?? true;
    const blockedCount = response?.blockedCount ?? 0;

    statusEl.textContent = enabled ? "Enabled" : "Disabled";
    statusEl.style.color = enabled ? "#2ecc71" : "#e74c3c";
    blockedCountEl.textContent = String(blockedCount);

    toggleBtn.textContent = enabled ? "Disable" : "Enable";
    toggleBtn.className = enabled ? "off" : "on";
  });
}

toggleBtn.addEventListener("click", () => {
  chrome.runtime.sendMessage({ type: "getStatus" }, (response) => {
    const enabled = response?.enabled ?? true;
    chrome.runtime.sendMessage({ type: "setEnabled", enabled: !enabled }, () => {
      refreshUI();
    });
  });
});

refreshUI();
