## `content.js`

This script removes common tracking-related DOM elements and blocks some inline tracking patterns.

```js
(() => {
  const TRACKING_SELECTORS = [
    'script[src*="google-analytics"]',
    'script[src*="googletagmanager"]',
    'script[src*="doubleclick"]',
    'script[src*="facebook.net"]',
    'iframe[src*="doubleclick"]',
    'iframe[src*="facebook.com"]',
    'img[src*="doubleclick"]',
    'img[src*="google-analytics"]',
    'link[href*="google-analytics"]'
  ];

  function removeTrackingElements(root = document) {
    for (const selector of TRACKING_SELECTORS) {
      root.querySelectorAll(selector).forEach((el) => el.remove());
    }
  }

  // Remove existing trackers ASAP
  removeTrackingElements();

  // Watch for dynamically inserted trackers
  const observer = new MutationObserver((mutations) => {
    for (const mutation of mutations) {
      for (const node of mutation.addedNodes) {
        if (!(node instanceof Element)) continue;

        // Remove if the node itself matches
        for (const selector of TRACKING_SELECTORS) {
          if (node.matches(selector)) {
            node.remove();
            break;
          }
        }

        // Remove descendants
        removeTrackingElements(node);
      }
    }
  });

  observer.observe(document.documentElement, {
    childList: true,
    subtree: true
  });

  // Optional: reduce fingerprinting via navigator properties (limited effectiveness)
  try {
    Object.defineProperty(navigator, "webdriver", {
      get: () => undefined
    });
  } catch (_) {}
})();
```

