## `popup.js`

This version stores an enabled/disabled state in `chrome.storage` and toggles rules dynamically.

```js
const statusEl = document.getElementById("status");
const toggleBtn = document.getElementById("toggleBtn");

const RULE_IDS = [1, 2, 3, 4, 5, 6, 7, 8];

async function getEnabled() {
  const result = await chrome.storage.local.get({ enabled: true });
  return result.enabled;
}

async function setEnabled(enabled) {
  await chrome.storage.local.set({ enabled });

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }

  render(enabled);
}

function render(enabled) {
  statusEl.textContent = enabled ? "Protection is ON" : "Protection is OFF";
  toggleBtn.textContent = enabled ? "Disable protection" : "Enable protection";
  toggleBtn.classList.toggle("off", enabled);
}

toggleBtn.addEventListener("click", async () => {
  const enabled = await getEnabled();
  await setEnabled(!enabled);
});

(async function init() {
  const enabled = await getEnabled();
  render(enabled);
})();
```

