## `popup.js`

This toggles the extension’s enabled state and updates the active rules.

```js
const stateEl = document.getElementById("state");
const messageEl = document.getElementById("message");
const toggleBtn = document.getElementById("toggle");

async function getEnabled() {
  const { enabled = true } = await chrome.storage.sync.get({ enabled: true });
  return enabled;
}

async function setEnabled(enabled) {
  await chrome.storage.sync.set({ enabled });

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracker_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracker_rules"]
    });
  }

  render();
}

async function render() {
  const enabled = await getEnabled();
  stateEl.textContent = enabled ? "ON" : "OFF";
  toggleBtn.textContent = enabled ? "Disable" : "Enable";
  messageEl.textContent = enabled
    ? "Tracking protection is active."
    : "Tracking protection is disabled.";
}

toggleBtn.addEventListener("click", async () => {
  const enabled = await getEnabled();
  await setEnabled(!enabled);
});

render();
```

