## `background.js`

This service worker keeps track of whether blocking is enabled and updates the rules accordingly.

```javascript
const RULESET_ID = "tracking_rules";

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [RULESET_ID]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.sync.get({ blockingEnabled: true });
  await setBlockingEnabled(blockingEnabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const { blockingEnabled } = await chrome.storage.sync.get({ blockingEnabled: true });
  await setBlockingEnabled(blockingEnabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "SET_BLOCKING_ENABLED") {
    chrome.storage.sync.set({ blockingEnabled: message.enabled }).then(async () => {
      await setBlockingEnabled(message.enabled);
      sendResponse({ ok: true, enabled: message.enabled });
    });
    return true;
  }

  if (message?.type === "GET_BLOCKING_ENABLED") {
    chrome.storage.sync.get({ blockingEnabled: true }).then((result) => {
      sendResponse({ ok: true, enabled: result.blockingEnabled });
    });
    return true;
  }
});
```

