This lets the user enable/disable blocking from the popup.

```js
const STORAGE_KEY = "privacyBlockerEnabled";

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["default_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["default_rules"]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const stored = await chrome.storage.sync.get(STORAGE_KEY);
  const enabled = stored[STORAGE_KEY] ?? true;
  await chrome.storage.sync.set({ [STORAGE_KEY]: enabled });
  await setBlockingEnabled(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const stored = await chrome.storage.sync.get(STORAGE_KEY);
  const enabled = stored[STORAGE_KEY] ?? true;
  await setBlockingEnabled(enabled);
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "SET_BLOCKING_ENABLED") {
    (async () => {
      const enabled = !!message.enabled;
      await chrome.storage.sync.set({ [STORAGE_KEY]: enabled });
      await setBlockingEnabled(enabled);
      sendResponse({ ok: true, enabled });
    })();
    return true;
  }

  if (message?.type === "GET_BLOCKING_ENABLED") {
    (async () => {
      const stored = await chrome.storage.sync.get(STORAGE_KEY);
      sendResponse({ enabled: stored[STORAGE_KEY] ?? true });
    })();
    return true;
  }
});
