## `popup.js`

```js
const statusText = document.getElementById("statusText");
const toggleBtn = document.getElementById("toggleBtn");

async function refreshUI() {
  const { blockingEnabled } = await chrome.storage.sync.get({ blockingEnabled: true });
  statusText.textContent = blockingEnabled ? "Enabled" : "Disabled";
  toggleBtn.textContent = blockingEnabled ? "Disable blocking" : "Enable blocking";
  toggleBtn.className = blockingEnabled ? "disabled" : "enabled";
}

toggleBtn.addEventListener("click", async () => {
  const { blockingEnabled } = await chrome.storage.sync.get({ blockingEnabled: true });
  const next = !blockingEnabled;

  await chrome.runtime.sendMessage({
    type: "setBlockingEnabled",
    enabled: next
  });

  await refreshUI();
});

refreshUI();
```

