## `background.js`

This script removes tracking parameters from URLs before navigation.

```javascript
const TRACKING_PARAMS = [
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "utm_id",
  "gclid",
  "dclid",
  "fbclid",
  "msclkid",
  "igshid",
  "mc_cid",
  "mc_eid",
  "ref"
];

function cleanUrl(urlString) {
  try {
    const url = new URL(urlString);
    let changed = false;

    for (const param of TRACKING_PARAMS) {
      if (url.searchParams.has(param)) {
        url.searchParams.delete(param);
        changed = true;
      }
    }

    // Remove empty query string if no params remain
    if (changed) {
      return url.toString();
    }
  } catch (e) {
    // Ignore invalid URLs
  }

  return null;
}

chrome.webNavigation.onBeforeNavigate.addListener((details) => {
  if (details.frameId !== 0) return;

  const cleaned = cleanUrl(details.url);
  if (cleaned && cleaned !== details.url) {
    chrome.tabs.update(details.tabId, { url: cleaned });
  }
});
```

