## `options.js`

This stores custom domains and adds/removes dynamic blocking rules.

```js
const domainInput = document.getElementById("domainInput");
const addBtn = document.getElementById("addBtn");
const domainList = document.getElementById("domainList");

const CUSTOM_RULE_ID_BASE = 1000;

async function getCustomDomains() {
  const { customDomains = [] } = await chrome.storage.sync.get("customDomains");
  return customDomains;
}

async function saveCustomDomains(domains) {
  await chrome.storage.sync.set({ customDomains: domains });
}

function normalizeDomain(input) {
  return input.trim().toLowerCase().replace(/^https?:\/\//, "").replace(/^www\./, "");
}

async function syncCustomRules(domains) {
  const existingRules = await chrome.declarativeNetRequest.getDynamicRules();
  const customRuleIds = existingRules
    .filter(rule => rule.id >= CUSTOM_RULE_ID_BASE)
    .map(rule => rule.id);

  const addRules = domains.map((domain, index) => ({
    id: CUSTOM_RULE_ID_BASE + index,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: domain,
      resourceTypes: ["script", "xmlhttprequest", "sub_frame", "image", "other"]
    }
  }));

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: customRuleIds,
    addRules
  });
}

async function render() {
  const domains = await getCustomDomains();
  domainList.innerHTML = "";

  domains.forEach((domain, index) => {
    const li = document.createElement("li");
    li.innerHTML = `
      <span class="domain">${domain}</span>
      <button data-index="${index}">Remove</button>
    `;
    domainList.appendChild(li);
  });

  domainList.querySelectorAll("button").forEach(btn => {
    btn.addEventListener("click", async () => {
      const index = Number(btn.dataset.index);
      const domains = await getCustomDomains();
      domains.splice(index, 1);
      await saveCustomDomains(domains);
      await syncCustomRules(domains);
      render();
    });
  });
}

addBtn.addEventListener("click", async () => {
  const domain = normalizeDomain(domainInput.value);
  if (!domain) return;

  const domains = await getCustomDomains();
  if (!domains.includes(domain)) {
    domains.push(domain);
    await saveCustomDomains(domains);
    await syncCustomRules(domains);
    render();
  }

  domainInput.value = "";
});

render();
```

