## 3) `background.js`

This service worker loads settings and can be extended later to manage dynamic rules.

```js
const DEFAULT_SETTINGS = {
  enabled: true,
  customBlockedDomains: []
};

async function getSettings() {
  const result = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  return result;
}

async function setBadge(enabled) {
  await chrome.action.setBadgeText({
    text: enabled ? "ON" : "OFF"
  });

  await chrome.action.setBadgeBackgroundColor({
    color: enabled ? "#2e7d32" : "#b71c1c"
  });
}

async function updateProtectionState() {
  const settings = await getSettings();
  await setBadge(settings.enabled);
}

chrome.runtime.onInstalled.addListener(async () => {
  await updateProtectionState();
});

chrome.runtime.onStartup.addListener(async () => {
  await updateProtectionState();
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes.enabled) {
    await setBadge(changes.enabled.newValue);
  }
});
```

