const DEFAULT_SETTINGS = {
  enabled: true
};

async function loadState() {
  const { enabled } = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  document.getElementById("enabledToggle").checked = enabled;
  document.getElementById("status").textContent = enabled
    ? "Protection is enabled."
    : "Protection is disabled.";
}

async function saveState(enabled) {
  await chrome.storage.sync.set({ enabled });
  document.getElementById("status").textContent = enabled
    ? "Protection is enabled."
    : "Protection is disabled.";
}

document.addEventListener("DOMContentLoaded", async () => {
  await loadState();

  document.getElementById("enabledToggle").addEventListener("change", async (e) => {
    await saveState(e.target.checked);
  });

  document.getElementById("openOptions").addEventListener("click", () => {
    chrome.runtime.openOptionsPage();
  });
});
