## 7) `options.js`

```js
const DEFAULT_SETTINGS = {
  customBlockedDomains: []
};

async function loadDomains() {
  const { customBlockedDomains } = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  document.getElementById("domains").value = customBlockedDomains.join("\n");
}

async function saveDomains() {
  const raw = document.getElementById("domains").value;
  const domains = raw
    .split("\n")
    .map(d => d.trim())
    .filter(Boolean);

  await chrome.storage.sync.set({ customBlockedDomains: domains });
  document.getElementById("message").textContent = "Saved.";
}

document.addEventListener("DOMContentLoaded", async () => {
  await loadDomains();

  document.getElementById("save").addEventListener("click", saveDomains);
});
```

