## 5) `popup.js`

This toggles the enabled state in storage.  
Note: this initial version stores the setting, but the ruleset itself is always enabled. A more complete version would dynamically enable/disable rules using `declarativeNetRequest.updateEnabledRulesets()` or dynamic rules.

```js
const toggleBtn = document.getElementById("toggleBtn");
const statusText = document.getElementById("statusText");

function render(enabled) {
  toggleBtn.textContent = enabled ? "Disable Blocking" : "Enable Blocking";
  statusText.textContent = enabled ? "Blocking is ON" : "Blocking is OFF";
}

chrome.storage.sync.get({ blockingEnabled: true }, ({ blockingEnabled }) => {
  render(blockingEnabled);
});

toggleBtn.addEventListener("click", async () => {
  const { blockingEnabled } = await chrome.storage.sync.get({ blockingEnabled: true });
  const next = !blockingEnabled;

  await chrome.storage.sync.set({ blockingEnabled: next });
  render(next);
});
```

