## 3) `background.js`

This keeps track of whether blocking is enabled and updates the extension badge.

```js
const DEFAULT_STATE = {
  enabled: true
};

async function getState() {
  const result = await chrome.storage.local.get(DEFAULT_STATE);
  return result;
}

async function setBadge(enabled) {
  await chrome.action.setBadgeText({ text: enabled ? "ON" : "OFF" });
  await chrome.action.setBadgeBackgroundColor({
    color: enabled ? "#2e7d32" : "#b71c1c"
  });
}

async function applyRules(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["tracking_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["tracking_rules"]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const state = await getState();
  await applyRules(state.enabled);
  await setBadge(state.enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const state = await getState();
  await applyRules(state.enabled);
  await setBadge(state.enabled);
});

chrome.storage.onChanged.addListener(async (changes, area) => {
  if (area === "local" && changes.enabled) {
    const enabled = changes.enabled.newValue;
    await applyRules(enabled);
    await setBadge(enabled);
  }
});
```

