## 5) `popup.js`

```js
const DEFAULT_STATE = { enabled: true };

async function loadState() {
  const { enabled } = await chrome.storage.local.get(DEFAULT_STATE);
  const toggle = document.getElementById("enabledToggle");
  const status = document.getElementById("status");

  toggle.checked = enabled;
  status.textContent = enabled ? "Blocking is enabled." : "Blocking is disabled.";
}

async function saveState(enabled) {
  await chrome.storage.local.set({ enabled });
}

document.addEventListener("DOMContentLoaded", async () => {
  const toggle = document.getElementById("enabledToggle");
  const status = document.getElementById("status");

  await loadState();

  toggle.addEventListener("change", async () => {
    const enabled = toggle.checked;
    await saveState(enabled);
    status.textContent = enabled ? "Blocking is enabled." : "Blocking is disabled.";
  });
});
```

