## 5) Add enable/disable support for rules

Right now the ruleset is always enabled. To make the toggle actually control blocking, update `background.js` to enable/disable the ruleset dynamically.

Replace `background.js` with:

```js
const RULESET_ID = "tracker_rules";

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: [RULESET_ID]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const result = await chrome.storage.local.get(["enabled"]);
  const enabled = result.enabled !== false;
  await chrome.storage.local.set({ enabled });
  await setBlockingEnabled(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const result = await chrome.storage.local.get(["enabled"]);
  const enabled = result.enabled !== false;
  await setBlockingEnabled(enabled);
});

chrome.storage.onChanged.addListener((changes, areaName) => {
  if (areaName === "local" && changes.enabled) {
    setBlockingEnabled(changes.enabled.newValue !== false);
  }
});
```

