## 7) `options.js`

```js
const customRulesEl = document.getElementById("customRules");
const statusEl = document.getElementById("status");

async function loadSettings() {
  const { customRules = "[]" } = await chrome.storage.local.get("customRules");
  customRulesEl.value = customRules;
}

document.getElementById("saveBtn").addEventListener("click", async () => {
  try {
    const parsed = JSON.parse(customRulesEl.value);

    if (!Array.isArray(parsed)) {
      throw new Error("Custom rules must be a JSON array.");
    }

    await chrome.storage.local.set({
      customRules: JSON.stringify(parsed, null, 2)
    });

    statusEl.textContent = "Saved successfully.";
  } catch (err) {
    statusEl.textContent = `Error: ${err.message}`;
  }
});

loadSettings();
```

