## 3) `background.js`

This registers dynamic blocking rules and updates the badge count.

```js
import { TRACKER_DOMAINS } from "./blocklist.js";

const STORAGE_KEY = "privacy_blocker_enabled";

async function getEnabled() {
  const result = await chrome.storage.local.get(STORAGE_KEY);
  return result[STORAGE_KEY] ?? true;
}

async function setBadge(text) {
  await chrome.action.setBadgeText({ text });
  await chrome.action.setBadgeBackgroundColor({ color: "#2e7d32" });
}

function domainToRule(domain, id) {
  return {
    id,
    priority: 1,
    action: {
      type: "block"
    },
    condition: {
      urlFilter: domain,
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame", "fetch", "ping"]
    }
  };
}

async function updateRules(enabled) {
  const ruleIds = TRACKER_DOMAINS.map((_, index) => index + 1);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: ruleIds,
    addRules: enabled
      ? TRACKER_DOMAINS.map((domain, index) => domainToRule(domain, index + 1))
      : []
  });

  await setBadge(enabled ? "ON" : "OFF");
}

chrome.runtime.onInstalled.addListener(async () => {
  const enabled = await getEnabled();
  await updateRules(enabled);
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "local" && changes[STORAGE_KEY]) {
    await updateRules(changes[STORAGE_KEY].newValue);
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "getStatus") {
    getEnabled().then((enabled) => sendResponse({ enabled }));
    return true;
  }

  if (message?.type === "setStatus") {
    chrome.storage.local.set({ [STORAGE_KEY]: message.enabled }).then(() => {
      sendResponse({ ok: true });
    });
    return true;
  }
});
```

