## 3) `background.js`

This service worker manages custom user block rules and basic state.

```js
const CUSTOM_RULES_START_ID = 1000;

async function getCustomBlockedDomains() {
  const result = await chrome.storage.sync.get({ blockedDomains: [] });
  return result.blockedDomains;
}

function buildRulesFromDomains(domains) {
  return domains.map((domain, index) => ({
    id: CUSTOM_RULES_START_ID + index,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: domain,
      resourceTypes: ["script", "xmlhttprequest", "image", "sub_frame", "ping", "font", "media"]
    }
  }));
}

async function updateCustomRules() {
  const domains = await getCustomBlockedDomains();
  const rules = buildRulesFromDomains(domains);

  const existing = await chrome.declarativeNetRequest.getDynamicRules();
  const removeRuleIds = existing.map(rule => rule.id);

  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds,
    addRules: rules
  });
}

chrome.runtime.onInstalled.addListener(async () => {
  await updateCustomRules();
});

chrome.runtime.onStartup.addListener(async () => {
  await updateCustomRules();
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes.blockedDomains) {
    await updateCustomRules();
  }
});

// Optional: expose a simple message API for popup/options pages
chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_STATUS") {
    chrome.storage.sync.get({ blockedDomains: [] }).then(({ blockedDomains }) => {
      sendResponse({
        blockedDomainsCount: blockedDomains.length
      });
    });
    return true;
  }
});
```

