```js
async function getBlockedDomains() {
  const result = await chrome.storage.sync.get({ blockedDomains: [] });
  return result.blockedDomains;
}

async function saveBlockedDomains(domains) {
  await chrome.storage.sync.set({ blockedDomains: domains });
}

function renderList(domains) {
  const list = document.getElementById("domainList");
  list.innerHTML = "";

  if (domains.length === 0) {
    const li = document.createElement("li");
    li.textContent = "No custom blocked domains yet.";
    list.appendChild(li);
    return;
  }

  domains.forEach((domain, index) => {
    const li = document.createElement("li");
    li.textContent = domain;

    const removeBtn = document.createElement("button");
    removeBtn.textContent = "Remove";
    removeBtn.style.marginLeft = "12px";
    removeBtn.addEventListener("click", async () => {
      const updated = domains.filter((_, i) => i !== index);
      await saveBlockedDomains(updated);
      renderList(updated);
    });

    li.appendChild(removeBtn);
    list.appendChild(li);
  });
}

async function refresh() {
  const domains = await getBlockedDomains();
  renderList(domains);
}

document.getElementById("addBtn").addEventListener("click", async () => {
  const input = document.getElementById("domainInput");
  const value = input.value.trim();

  if (!value) return;

  const domains = await getBlockedDomains();
  if (!domains.includes(value)) {
    domains.push(value);
    await saveBlockedDomains(domains);
    renderList(domains);
  }

  input.value = "";
});

refresh();
