## 3) `background.js`

This service worker manages extension state and can later be expanded to dynamically enable/disable rules.

```js
const DEFAULT_SETTINGS = {
  blockingEnabled: true
};

chrome.runtime.onInstalled.addListener(async () => {
  const current = await chrome.storage.sync.get(DEFAULT_SETTINGS);
  if (typeof current.blockingEnabled === "undefined") {
    await chrome.storage.sync.set(DEFAULT_SETTINGS);
  }
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message?.type === "GET_SETTINGS") {
    chrome.storage.sync.get(DEFAULT_SETTINGS).then((settings) => {
      sendResponse(settings);
    });
    return true;
  }

  if (message?.type === "SET_BLOCKING_ENABLED") {
    const enabled = Boolean(message.enabled);

    chrome.storage.sync.set({ blockingEnabled: enabled }).then(() => {
      // In a more advanced version, you could dynamically enable/disable rules here.
      sendResponse({ ok: true, blockingEnabled: enabled });
    });

    return true;
  }
});
```

