## 3) `background.js`

This service worker handles enabling/disabling the extension’s blocking behavior.

```js
const STORAGE_KEY = "privacyGuardEnabled";

async function setBlockingEnabled(enabled) {
  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: ["static_rules"],
      disableRulesetIds: []
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [],
      disableRulesetIds: ["static_rules"]
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const result = await chrome.storage.sync.get(STORAGE_KEY);
  const enabled = result[STORAGE_KEY] ?? true;
  await chrome.storage.sync.set({ [STORAGE_KEY]: enabled });
  await setBlockingEnabled(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const result = await chrome.storage.sync.get(STORAGE_KEY);
  const enabled = result[STORAGE_KEY] ?? true;
  await setBlockingEnabled(enabled);
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes[STORAGE_KEY]) {
    await setBlockingEnabled(changes[STORAGE_KEY].newValue);
  }
});
```

