## `background.js`

This keeps the extension enabled by default and stores the user’s toggle state.

```js
const RULESET_ID = "tracker_rules";

chrome.runtime.onInstalled.addListener(async () => {
  const { enabled } = await chrome.storage.local.get({ enabled: true });

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });
});

chrome.runtime.onStartup.addListener(async () => {
  const { enabled } = await chrome.storage.local.get({ enabled: true });

  await chrome.declarativeNetRequest.updateEnabledRulesets({
    enableRulesetIds: enabled ? [RULESET_ID] : [],
    disableRulesetIds: enabled ? [] : [RULESET_ID]
  });
});

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.type === "setEnabled") {
    chrome.storage.local.set({ enabled: message.enabled }).then(async () => {
      await chrome.declarativeNetRequest.updateEnabledRulesets({
        enableRulesetIds: message.enabled ? [RULESET_ID] : [],
        disableRulesetIds: message.enabled ? [] : [RULESET_ID]
      });
      sendResponse({ ok: true });
    });

    return true;
  }

  if (message.type === "getEnabled") {
    chrome.storage.local.get({ enabled: true }).then(({ enabled }) => {
      sendResponse({ enabled });
    });

    return true;
  }
});
```

