  const response = await chrome.runtime.sendMessage({ type: "getEnabled" });
  toggle.checked = response.enabled;
  status.textContent = response.enabled ? "Tracker blocking is on." : "Tracker blocking is off.";
}

toggle.addEventListener("change", async () => {
  const enabled = toggle.checked;
  await chrome.runtime.sendMessage({ type: "setEnabled", enabled });
