## 3) `service_worker.js`

This installs a dynamic ruleset that blocks a few common tracker domains.

```js
const TRACKER_DOMAINS = [
  "googletagmanager.com",
  "google-analytics.com",
  "doubleclick.net",
  "facebook.net",
  "connect.facebook.net",
  "hotjar.com",
  "segment.com",
  "mixpanel.com"
];

const RULES = TRACKER_DOMAINS.map((domain, index) => ({
  id: index + 1,
  priority: 1,
  action: {
    type: "block"
  },
  condition: {
    urlFilter: domain,
    resourceTypes: ["script"]
  }
}));

async function updateRules(enabled) {
  const existing = await chrome.declarativeNetRequest.getDynamicRules();
  const existingIds = existing.map(rule => rule.id);

  if (existingIds.length) {
    await chrome.declarativeNetRequest.updateDynamicRules({
      removeRuleIds: existingIds,
      addRules: enabled ? RULES : []
    });
  } else if (enabled) {
    await chrome.declarativeNetRequest.updateDynamicRules({
      addRules: RULES
    });
  }
}

chrome.runtime.onInstalled.addListener(async () => {
  const { enabled = true } = await chrome.storage.sync.get("enabled");
  await updateRules(enabled);
});

chrome.runtime.onStartup.addListener(async () => {
  const { enabled = true } = await chrome.storage.sync.get("enabled");
  await updateRules(enabled);
});

chrome.storage.onChanged.addListener(async (changes, areaName) => {
  if (areaName === "sync" && changes.enabled) {
    await updateRules(changes.enabled.newValue);
  }
});
```

