## 2) `background.js`

```js
const DEFAULT_ENABLED = true;

// Very small starter blocklist
const TRACKER_DOMAINS = [
  "google-analytics.com",
  "www.google-analytics.com",
  "googletagmanager.com",
  "connect.facebook.net",
  "facebook.com/tr",
  "static.hotjar.com",
  "script.hotjar.com",
  "mixpanel.com",
  "cdn.segment.com",
  "api.segment.io",
  "doubleclick.net",
  "adservice.google.com"
];

// Common tracking script/path patterns
const TRACKER_PATHS = [
  "/gtag/js",
  "/analytics.js",
  "/fbevents.js",
  "/hotjar-",
  "/mixpanel.js"
];

async function getEnabled() {
  const result = await chrome.storage.local.get({ enabled: DEFAULT_ENABLED });
  return result.enabled;
}

function isTrackerUrl(url) {
  try {
    const u = new URL(url);
    const host = u.hostname.toLowerCase();
    const full = url.toLowerCase();
    return (
      TRACKER_DOMAINS.some(domain => host === domain || host.endsWith("." + domain) || full.includes(domain)) ||
      TRACKER_PATHS.some(path => full.includes(path))
    );
  } catch {
    return false;
  }
}

chrome.webRequest.onBeforeRequest.addListener(
  async (details) => {
    const enabled = await getEnabled();
    if (!enabled) return;

    if (details.type === "script" || details.type === "xmlhttprequest" || details.type === "ping" || details.type === "beacon") {
      if (isTrackerUrl(details.url)) {
        return { cancel: true };
      }
    }
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);
```

