## 2) `background.js`

This registers a dynamic ruleset to block a few common tracker domains.

```js
const RULE_IDS = [1, 2, 3, 4, 5];

const RULES = [
  {
    id: 1,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||google-analytics.com^",
      resourceTypes: ["script", "xmlhttprequest", "image", "ping", "other"]
    }
  },
  {
    id: 2,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||googletagmanager.com^",
      resourceTypes: ["script", "xmlhttprequest", "image", "ping", "other"]
    }
  },
  {
    id: 3,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||facebook.net^",
      resourceTypes: ["script", "xmlhttprequest", "image", "ping", "other"]
    }
  },
  {
    id: 4,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||doubleclick.net^",
      resourceTypes: ["script", "xmlhttprequest", "image", "ping", "other"]
    }
  },
  {
    id: 5,
    priority: 1,
    action: { type: "block" },
    condition: {
      urlFilter: "||segment.com^",
      resourceTypes: ["script", "xmlhttprequest", "image", "ping", "other"]
    }
  }
];

async function enableBlocking() {
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: RULE_IDS,
    addRules: RULES
  });
}

async function disableBlocking() {
  await chrome.declarativeNetRequest.updateDynamicRules({
    removeRuleIds: RULE_IDS
  });
}

async function syncState() {
  const { enabled = true } = await chrome.storage.sync.get("enabled");
  if (enabled) {
    await enableBlocking();
  } else {
    await disableBlocking();
  }
}

chrome.runtime.onInstalled.addListener(syncState);
chrome.runtime.onStartup.addListener(syncState);

chrome.storage.onChanged.addListener((changes, area) => {
  if (area === "sync" && changes.enabled) {
    if (changes.enabled.newValue) {
      enableBlocking();
    } else {
      disableBlocking();
    }
  }
});
```

