## 4) `popup.js`

This lets the user enable/disable the ruleset.

```javascript
const RULESET_ID = "default_rules";

async function updateStatus() {
  const enabledRulesets = await chrome.declarativeNetRequest.getEnabledRulesets();
  const enabled = enabledRulesets.includes(RULESET_ID);

  document.getElementById("status").textContent = enabled
    ? "Blocking is ON"
    : "Blocking is OFF";

  document.getElementById("toggle").textContent = enabled
    ? "Disable blocking"
    : "Enable blocking";
}

document.getElementById("toggle").addEventListener("click", async () => {
  const enabledRulesets = await chrome.declarativeNetRequest.getEnabledRulesets();
  const enabled = enabledRulesets.includes(RULESET_ID);

  if (enabled) {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      disableRulesetIds: [RULESET_ID]
    });
  } else {
    await chrome.declarativeNetRequest.updateEnabledRulesets({
      enableRulesetIds: [RULESET_ID]
    });
  }

  updateStatus();
});

updateStatus();
```

