## Full example

Save as `index.html` and open in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Stock Price Heatmap</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #0b1020;
      color: #e5e7eb;
      font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
    }

    #app {
      position: relative;
      width: 100vw;
      height: 100vh;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .hud {
      position: absolute;
      top: 12px;
      left: 12px;
      background: rgba(15, 23, 42, 0.85);
      border: 1px solid rgba(148, 163, 184, 0.2);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 13px;
      line-height: 1.4;
      backdrop-filter: blur(8px);
      max-width: 320px;
      pointer-events: none;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      border: 1px solid rgba(148, 163, 184, 0.25);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      color: #f8fafc;
      transform: translate(12px, 12px);
      display: none;
      white-space: nowrap;
      box-shadow: 0 8px 24px rgba(0,0,0,0.25);
    }

    .legend {
      margin-top: 8px;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .bar {
      width: 140px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, #dc2626, #f59e0b, #16a34a);
      border: 1px solid rgba(255,255,255,0.12);
    }

    .hint {
      color: #94a3b8;
      margin-top: 6px;
      font-size: 12px;
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="heatmap"></canvas>

    <div class="hud">
      <div><strong>Stock Heatmap</strong></div>
      <div>Drag to pan • Wheel to zoom • Hover for details</div>
      <div class="legend">
        <span>↓</span>
        <div class="bar"></div>
        <span>↑</span>
      </div>
      <div class="hint">Real-time updates simulated every second</div>
    </div>

    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const tooltip = document.getElementById("tooltip");

    // ---------- Utilities ----------
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function hexToRgb(hex) {
      const m = hex.replace("#", "");
      return {
        r: parseInt(m.slice(0, 2), 16),
        g: parseInt(m.slice(2, 4), 16),
        b: parseInt(m.slice(4, 6), 16)
      };
    }

    function rgbToCss({ r, g, b }) {
      return `rgb(${r|0}, ${g|0}, ${b|0})`;
    }

    function mixColor(c1, c2, t) {
      return {
        r: lerp(c1.r, c2.r, t),
        g: lerp(c1.g, c2.g, t),
        b: lerp(c1.b, c2.b, t)
      };
    }

    // Red -> Yellow -> Green
    const red = hexToRgb("#dc2626");
    const yellow = hexToRgb("#f59e0b");
    const green = hexToRgb("#16a34a");

    function priceChangeToColor(changePct) {
      // changePct in range roughly [-10, 10]
      const t = clamp((changePct + 10) / 20, 0, 1);
      if (t < 0.5) {
        return rgbToCss(mixColor(red, yellow, t / 0.5));
      }
      return rgbToCss(mixColor(yellow, green, (t - 0.5) / 0.5));
    }

    function formatPct(v) {
      return `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`;
    }

    function formatPrice(v) {
      return `$${v.toFixed(2)}`;
    }

    // ---------- Data ----------
    const rows = 12;
    const cols = 12;
    const stocks = [];
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX","AMD","INTC",
      "ORCL","CRM","UBER","SHOP","SQ","PYPL","ADBE","QCOM","AVGO","CSCO",
      "BABA","SONY","IBM","SAP","NOW","SNOW","PLTR","PANW","NET","DDOG",
      "COST","WMT","TGT","HD","LOW","MCD","SBUX","NKE","DIS","BA",
      "JPM","BAC","WFC","GS","MS","V","MA","AXP","BLK","SCHW",
      "XOM","CVX","COP","SLB","OXY","PFE","MRK","JNJ","UNH","LLY",
      "KO","PEP","PG","CL","KMB","GE","CAT","DE","RTX","LMT",
      "T","VZ","TMUS","CMCSA","ATVI","EA","TTD","RBLX","ZS","CRWD",
      "F","GM","RIVN","LCID","SNAP","TWLO","DOCU","OKTA","HPE","HPQ",
      "SPOT","BIDU","JD","PDD","NTES","SHOP","ETSY","ABNB","LYFT","DASH",
      "MELI","SE","ASML","TSM","ARM","SMCI","MU","KLAC","LRCX","AMAT",
      "BMY","GILD","AMGN","VRTX","REGN","BIIB","ISRG","MDT","SYK","ZTS"
    ];

    function randomBetween(a, b) {
      return a + Math.random() * (b - a);
    }

    for (let i = 0; i < rows * cols; i++) {
      const base = randomBetween(20, 500);
      const change = randomBetween(-8, 8);
      stocks.push({
        symbol: symbols[i % symbols.length] + (i >= symbols.length ? i : ""),
        price: base,
        prevPrice: base,
        changePct: change,
        volume: Math.floor(randomBetween(100000, 50000000))
      });
    }

    // ---------- View transform ----------
    const view = {
      x: 20,
      y: 20,
      scale: 1
    };

    // ---------- Canvas sizing ----------
    let dpr = window.devicePixelRatio || 1;
    function resize() {
      dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(canvas.clientWidth * dpr);
      canvas.height = Math.floor(canvas.clientHeight * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }
    window.addEventListener("resize", resize);

    // ---------- Interaction ----------
    let isPanning = false;
    let panStart = { x: 0, y: 0 };
    let viewStart = { x: 0, y: 0 };

    function screenToWorld(sx, sy) {
      return {
        x: (sx - view.x) / view.scale,
        y: (sy - view.y) / view.scale
      };
    }

    function worldToScreen(wx, wy) {
      return {
        x: wx * view.scale + view.x,
        y: wy * view.scale + view.y
      };
    }

    canvas.addEventListener("mousedown", (e) => {
      isPanning = true;
      panStart = { x: e.clientX, y: e.clientY };
      viewStart = { x: view.x, y: view.y };
    });

    window.addEventListener("mousemove", (e) => {
      if (isPanning) {
        view.x = viewStart.x + (e.clientX - panStart.x);
        view.y = viewStart.y + (e.clientY - panStart.y);
        draw();
      }
      updateTooltip(e.clientX, e.clientY);
    });

    window.addEventListener("mouseup", () => {
      isPanning = false;
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const mouseX = e.clientX;
      const mouseY = e.clientY;
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(view.scale * zoomFactor, 0.4, 4);

      // Zoom around cursor
      const before = screenToWorld(mouseX, mouseY);
      view.scale = newScale;
      const after = screenToWorld(mouseX, mouseY);

      view.x += (after.x - before.x) * view.scale;
      view.y += (after.y - before.y) * view.scale;

      draw();
    }, { passive: false });

    canvas.addEventListener("mouseleave", () => {
      tooltip.style.display = "none";
    });

    // ---------- Real-time updates ----------
    function updateData() {
      for (const stock of stocks) {
        stock.prevPrice = stock.price;

        // Simulate small random walk
        const drift = randomBetween(-1.2, 1.2);
        const shock = randomBetween(-0.8, 0.8);
        const delta = drift + shock;

        stock.price = Math.max(1, stock.price + delta);
        stock.changePct = ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;

        // Occasionally simulate a larger move
        if (Math.random() < 0.03) {
          stock.price = Math.max(1, stock.price * randomBetween(0.96, 1.04));
          stock.changePct = ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;
        }

        stock.volume = Math.max(1000, stock.volume + Math.floor(randomBetween(-500000, 500000)));
      }
      draw();
    }

    setInterval(updateData, 1000);

    // ---------- Rendering ----------
    function drawGridBackground() {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;

      ctx.save();
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, w, h);

      // subtle grid
      ctx.strokeStyle = "rgba(148, 163, 184, 0.08)";
      ctx.lineWidth = 1;
      const step = 40;
      for (let x = 0; x < w; x += step) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, h);
        ctx.stroke();
      }
      for (let y = 0; y < h; y += step) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(w, y);
        ctx.stroke();
      }
      ctx.restore();
    }

    function draw() {
      const w = canvas.clientWidth;
      const h = canvas.clientHeight;
      drawGridBackground();

      const cellW = 110;
      const cellH = 70;
      const gap = 8;

      ctx.save();
      ctx.translate(view.x, view.y);
      ctx.scale(view.scale, view.scale);

      for (let i = 0; i < stocks.length; i++) {
        const stock = stocks[i];
        const row = Math.floor(i / cols);
        const col = i % cols;

        const x = col * (cellW + gap);
        const y = row * (cellH + gap);

        const color = priceChangeToColor(stock.changePct);

        // cell shadow
        ctx.fillStyle = "rgba(0,0,0,0.25)";
        roundRect(ctx, x + 3, y + 4, cellW, cellH, 10);
        ctx.fill();

        // cell body
        ctx.fillStyle = color;
        roundRect(ctx, x, y, cellW, cellH, 10);
        ctx.fill();

        // overlay for readability
        ctx.fillStyle = "rgba(15, 23, 42, 0.18)";
        roundRect(ctx, x, y, cellW, cellH, 10);
        ctx.fill();

        // text
        ctx.fillStyle = "#fff";
        ctx.font = "bold 14px system-ui, sans-serif";
        ctx.fillText(stock.symbol, x + 10, y + 22);

        ctx.font = "12px system-ui, sans-serif";
        ctx.fillText(formatPrice(stock.price), x + 10, y + 41);

        ctx.fillStyle = stock.changePct >= 0 ? "#dcfce7" : "#fee2e2";
        ctx.fillText(formatPct(stock.changePct), x + 10, y + 58);
      }

      ctx.restore();
    }

    function roundRect(ctx, x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    function updateTooltip(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const sx = clientX - rect.left;
      const sy = clientY - rect.top;

      const world = screenToWorld(sx, sy);

      const cellW = 110;
      const cellH = 70;
      const gap = 8;

      let found = null;

      for (let i = 0; i < stocks.length; i++) {
        const row = Math.floor(i / cols);
        const col = i % cols;
        const x = col * (cellW + gap);
        const y = row * (cellH + gap);

        if (
          world.x >= x && world.x <= x + cellW &&
          world.y >= y && world.y <= y + cellH
        ) {
          found = stocks[i];
          break;
        }
      }

      if (found) {
        tooltip.style.display = "block";
        tooltip.style.left = `${clientX}px`;
        tooltip.style.top = `${clientY}px`;
        tooltip.innerHTML = `
          <div><strong>${found.symbol}</strong></div>
          <div>Price: ${formatPrice(found.price)}</div>
          <div>Change: ${formatPct(found.changePct)}</div>
          <div>Volume: ${found.volume.toLocaleString()}</div>
        `;
      } else {
        tooltip.style.display = "none";
      }
    }

    // Initial render
    resize();
    draw();
  </script>
</body>
</html>
```

