      text-anchor: middle;
      dominant-baseline: middle;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(10, 15, 30, 0.95);
      color: white;
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 12px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.35);
      opacity: 0;
      transform: translate(10px, 10px);
      transition: opacity 0.12s ease;
      white-space: nowrap;
    }

    .hint {
      color: var(--muted);
      font-size: 12px;
    }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Interactive Stock Price Heatmap</h1>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
      <div class="spacer"></div>
      <div class="hint">Scroll to zoom • Drag to pan • Hover for details</div>
      <button id="resetBtn">Reset View</button>
    </div>

    <div class="chart-wrap" id="chartWrap">
      <svg id="chart"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = d3.select("#chart");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");

    const margin = { top: 20, right: 20, bottom: 20, left: 20 };
    let width = 0;
    let height = 0;

    // Sample stock universe
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","AMD","NFLX","INTC",
      "ORCL","CRM","ADBE","QCOM","AVGO","CSCO","IBM","UBER","SHOP","SNOW",
      "BABA","PDD","SQ","PYPL","SPOT","DIS","BA","JPM","V","MA"
    ];

    // Create initial data
    let data = symbols.map((symbol, i) => ({
      symbol,
      price: 50 + Math.random() * 450,
      prevPrice: null,
      changePct: 0,
      volume: Math.floor(1e6 + Math.random() * 9e6),
      sector: ["Tech", "Finance", "Consumer", "Industrial"][i % 4]
    }));

    // Layout: grid of cells
    const cols = 6;
    const rows = Math.ceil(data.length / cols);

    const zoomLayer = svg.append("g").attr("class", "zoom-layer");
    const cellsLayer = zoomLayer.append("g").attr("class", "cells-layer");

    const color = d3.scaleLinear()
      .domain([-5, -1, 0, 1, 5])
      .range(["#b91c1c", "#f59e0b", "#111827", "#22c55e", "#166534"])
      .clamp(true);

    const formatPrice = d3.format("$.2f");
    const formatPct = d3.format("+.2f%");
    const formatNum = d3.format(",");

    let transform = d3.zoomIdentity;

    function resize() {
      const rect = wrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      svg.attr("viewBox", `0 0 ${width} ${height}`);
      render();
    }

    function cellSize() {
      const usableW = width - margin.left - margin.right;
      const usableH = height - margin.top - margin.bottom;
      return {
        w: usableW / cols,
        h: usableH / rows
      };
    }

    function render() {
      const { w, h } = cellSize();

      const cells = cellsLayer.selectAll("g.cell-group")
        .data(data, d => d.symbol);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "cell-group");

      cellsEnter.append("rect")
        .attr("class", "cell");

      cellsEnter.append("text")
        .attr("class", "label")
        .attr("dy", "-0.2em");

      cellsEnter.append("text")
        .attr("class", "subtext")
        .attr("dy", "1.1em");

      const merged = cellsEnter.merge(cells);

      merged.each(function(d, i) {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = margin.left + col * w;
        const y = margin.top + row * h;

        const group = d3.select(this);

        group.attr("transform", `translate(${x},${y})`);

        group.select("rect")
          .transition()
          .duration(250)
          .attr("width", w - 4)
          .attr("height", h - 4)
          .attr("rx", 14)
          .attr("ry", 14)
          .attr("fill", color(d.changePct * 100));

        group.select("text.label")
          .attr("x", (w - 4) / 2)
          .attr("y", (h - 4) / 2 - 8)
          .text(d.symbol);

        group.select("text.subtext")
          .attr("x", (w - 4) / 2)
          .attr("y", (h - 4) / 2 + 10)
          .text(`${formatPrice(d.price)}  ${formatPct(d.changePct)}`);

        group.on("mousemove", (event) => {
          tooltip.style.opacity = 1;
          tooltip.innerHTML = `
            <div><strong>${d.symbol}</strong> <span style="color:#9aa7c7">(${d.sector})</span></div>
            <div>Price: ${formatPrice(d.price)}</div>
            <div>Change: ${formatPct(d.changePct)}</div>
            <div>Volume: ${formatNum(d.volume)}</div>
          `;
          const [mx, my] = d3.pointer(event, wrap);
          tooltip.style.left = `${mx + 14}px`;
          tooltip.style.top = `${my + 14}px`;
        });

        group.on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });
      });

      cells.exit().remove();

      // Apply current zoom transform
      zoomLayer.attr("transform", transform);
    }

    // Zoom behavior
    const zoom = d3.zoom()
      .scaleExtent([0.7, 4])
      .on("zoom", (event) => {
        transform = event.transform;
        zoomLayer.attr("transform", transform);
      });

    svg.call(zoom);

    resetBtn.addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    // Simulated real-time updates
    function updatePrices() {
      data = data.map(d => {
        const prev = d.price;
        const drift = (Math.random() - 0.5) * 0.03; // +/- 1.5%
        const next = Math.max(1, prev * (1 + drift));
        const changePct = (next - prev) / prev;

        return {
          ...d,
          prevPrice: prev,
          price: next,
          changePct,
          volume: Math.max(1000, d.volume + Math.floor((Math.random() - 0.5) * 50000))
        };
      });

      render();
    }

    // Initial render
    resize();
    render();

    // Resize handling
    window.addEventListener("resize", resize);

    // Update every second
    setInterval(updatePrices, 1000);

    // Optional: pause updates when tab is hidden
    document.addEventListener("visibilitychange", () => {
      // You could pause/resume your real feed here
    });
  </script>
</body>
</html>
```

