</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <span class="chip" id="status">Live: connected</span>
      <span class="chip" id="lastUpdate">Last update: --</span>
      <button id="resetZoom">Reset Zoom</button>
      <button id="toggleLive">Pause Live</button>
    </div>

    <div class="main" id="chartWrap">
      <svg id="chart"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <div class="details" id="details">
      Hover a tile to inspect. Click a tile to pin its details.
    </div>
  </div>

  <script>
    const svg = d3.select("#chart");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const details = document.getElementById("details");
    const statusEl = document.getElementById("status");
    const lastUpdateEl = document.getElementById("lastUpdate");
    const resetZoomBtn = document.getElementById("resetZoom");
    const toggleLiveBtn = document.getElementById("toggleLive");

    const margin = { top: 20, right: 20, bottom: 20, left: 20 };
    let width = 0, height = 0;

    const sectors = [
      "Technology", "Finance", "Healthcare", "Energy",
      "Consumer", "Industrials", "Utilities", "Materials"
    ];

    const symbols = [
      "AAPL","MSFT","NVDA","GOOGL","AMZN","META","TSLA","JPM",
      "BAC","WFC","JNJ","PFE","XOM","CVX","KO","PEP",
      "CAT","GE","DUK","NEM","AMD","INTC","ORCL","CRM"
    ];

    const data = symbols.map((symbol, i) => ({
      symbol,
      sector: sectors[i % sectors.length],
      price: 50 + Math.random() * 450,
      changePct: (Math.random() - 0.5) * 8,
      volume: Math.floor(1e6 + Math.random() * 20e6),
      pinned: false
    }));

    const color = d3.scaleLinear()
      .domain([-8, 0, 8])
      .range(["#d73027", "#1f2937", "#1a9850"])
      .clamp(true);

    const root = svg.append("g").attr("class", "root");
    const grid = root.append("g").attr("class", "grid");
    const legend = root.append("g").attr("class", "legend");

    let transform = d3.zoomIdentity;
    let live = true;
    let pinnedItem = null;

    const zoom = d3.zoom()
      .scaleExtent([0.7, 8])
      .on("zoom", (event) => {
        transform = event.transform;
        root.attr("transform", transform);
      });

    svg.call(zoom);

    function resize() {
      const rect = wrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;
      svg.attr("viewBox", `0 0 ${width} ${height}`);
      render();
    }

    function layout() {
      const cols = Math.max(1, Math.floor(Math.sqrt(data.length * (width / height))));
      const rows = Math.ceil(data.length / cols);
      const cellW = (width - margin.left - margin.right) / cols;
      const cellH = (height - margin.top - margin.bottom) / rows;
      return { cols, rows, cellW, cellH };
    }

    function render() {
      const { cols, cellW, cellH } = layout();

      const cells = grid.selectAll("g.cell-group")
        .data(data, d => d.symbol);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "cell-group")
        .style("cursor", "pointer")
        .on("mousemove", (event, d) => showTooltip(event, d))
        .on("mouseleave", hideTooltip)
        .on("click", (event, d) => {
          d.pinned = !d.pinned;
          pinnedItem = d.pinned ? d : (pinnedItem === d ? null : pinnedItem);
          updateDetails(d, true);
          render();
        });

      cellsEnter.append("rect").attr("class", "cell");
      cellsEnter.append("text").attr("class", "label");
      cellsEnter.append("text").attr("class", "subtext");

      const merged = cellsEnter.merge(cells);

      merged.transition().duration(250)
        .attr("transform", (d, i) => {
          const col = i % cols;
          const row = Math.floor(i / cols);
          const x = margin.left + col * cellW;
          const y = margin.top + row * cellH;
          return `translate(${x},${y})`;
        });

      merged.select("rect")
        .transition().duration(250)
        .attr("width", Math.max(0, cellW - 8))
        .attr("height", Math.max(0, cellH - 8))
        .attr("fill", d => color(d.changePct))
        .attr("opacity", d => d.pinned ? 1 : 0.92)
        .attr("stroke", d => d.pinned ? "#ffffff" : "rgba(255,255,255,0.08)")
        .attr("stroke-width", d => d.pinned ? 2 : 1);

      merged.select("text.label")
        .attr("x", (cellW - 8) / 2)
        .attr("y", Math.max(18, (cellH - 8) / 2 - 4))
        .text(d => d.symbol);

      merged.select("text.subtext")
        .attr("x", (cellW - 8) / 2)
        .attr("y", Math.max(34, (cellH - 8) / 2 + 12))
        .text(d => `${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%`);

      cells.exit().remove();

      renderLegend();
    }

    function renderLegend() {
      const legendData = [
        { label: "Down", color: color(-8) },
        { label: "Flat", color: color(0) },
        { label: "Up", color: color(8) }
      ];

      const g = legend.attr("transform", `translate(${width - 220}, ${height - 50})`);
      const items = g.selectAll("g.legend-item").data(legendData);

      const enter = items.enter().append("g").attr("class", "legend-item");
      enter.append("rect").attr("width", 18).attr("height", 18).attr("rx", 4);
      enter.append("text").attr("x", 24).attr("y", 13);

      const merged = enter.merge(items);
      merged.attr("transform", (d, i) => `translate(${i * 70}, 0)`);
      merged.select("rect").attr("fill", d => d.color);
      merged.select("text").text(d => d.label);

      items.exit().remove();
    }

    function showTooltip(event, d) {
      if (d.pinned) return;
      const [x, y] = d3.pointer(event, wrap);
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
      tooltip.style.opacity = 1;
      tooltip.innerHTML = `
        <strong>${d.symbol}</strong><br/>
        Sector: ${d.sector}<br/>
        Price: $${d.price.toFixed(2)}<br/>
        Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}%<br/>
        Volume: ${d.volume.toLocaleString()}
      `;
      updateDetails(d, false);
    }

    function hideTooltip() {
      tooltip.style.opacity = 0;
      if (pinnedItem) updateDetails(pinnedItem, true);
    }

    function updateDetails(d, pinned) {
      details.innerHTML = `
        ${pinned ? "<strong>Pinned:</strong> " : ""}
        <strong>${d.symbol}</strong> — ${d.sector} |
        Price: $${d.price.toFixed(2)} |
        Change: ${d.changePct >= 0 ? "+" : ""}${d.changePct.toFixed(2)}% |
        Volume: ${d.volume.toLocaleString()}
      `;
    }

    function tick() {
      if (!live) return;

      data.forEach(d => {
        const drift = (Math.random() - 0.5) * 0.8;
        d.changePct = Math.max(-12, Math.min(12, d.changePct + drift * 0.35));
        d.price = Math.max(1, d.price * (1 + drift / 100));
        d.volume = Math.max(0, d.volume + Math.floor((Math.random() - 0.5) * 200000));
      });

      lastUpdateEl.textContent = `Last update: ${new Date().toLocaleTimeString()}`;
      render();
    }

    resetZoomBtn.addEventListener("click", () => {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    });

    toggleLiveBtn.addEventListener("click", () => {
      live = !live;
      toggleLiveBtn.textContent = live ? "Pause Live" : "Resume Live";
      statusEl.textContent = live ? "Live: connected" : "Live: paused";
    });

    window.addEventListener("resize", resize);

    resize();
    render();
    setInterval(tick, 1000);
  </script>
</body>
</html>
