    <div class="overlay">
      <div><strong>Stock Heatmap</strong></div>
      <div>Wheel: zoom • Drag: pan • Hover: inspect</div>
      <div class="legend"></div>
      <div class="hint">Real-time updates simulated every 500ms</div>
    </div>

    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const tooltip = document.getElementById("tooltip");

    const state = {
      dpr: Math.max(1, window.devicePixelRatio || 1),
      width: 0,
      height: 0,
      cols: 30,
      rows: 18,
      cellGap: 4,
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startPanX: 0,
      startPanY: 0,
      hoverCell: null,
      lastMouseX: 0,
      lastMouseY: 0,
      cells: []
    };

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function initData() {
      state.cells = [];
      const symbols = [];
      for (let i = 0; i < state.cols * state.rows; i++) {
        symbols.push(`STK${String(i + 1).padStart(3, "0")}`);
      }

      for (let r = 0; r < state.rows; r++) {
        for (let c = 0; c < state.cols; c++) {
          const idx = r * state.cols + c;
          const base = rand(20, 500);
          state.cells.push({
            symbol: symbols[idx],
            price: base,
            prevPrice: base,
            changePct: 0,
            volume: Math.floor(rand(10000, 500000)),
            row: r,
            col: c
          });
        }
      }
    }

    function resize() {
      state.width = window.innerWidth;
      state.height = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      canvas.style.width = state.width + "px";
      canvas.style.height = state.height + "px";
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      draw();
    }

    function priceToColor(changePct) {
      // Negative -> red, neutral -> dark, positive -> green
      const t = clamp((changePct + 5) / 10, 0, 1); // map [-5, +5] to [0,1]
      const r = Math.round(220 * (1 - t) + 17 * t);
      const g = Math.round(38 * (1 - t) + 163 * t);
      const b = Math.round(38 * (1 - t) + 74 * t);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function getGridMetrics() {
      const baseCellW = 120;
      const baseCellH = 72;
      const cellW = baseCellW * state.zoom;
      const cellH = baseCellH * state.zoom;
      const gap = state.cellGap * state.zoom;

      const totalW = state.cols * cellW + (state.cols - 1) * gap;
      const totalH = state.rows * cellH + (state.rows - 1) * gap;

      const originX = (state.width - totalW) / 2 + state.panX;
      const originY = (state.height - totalH) / 2 + state.panY;

      return { cellW, cellH, gap, originX, originY, totalW, totalH };
    }

    function draw() {
      ctx.clearRect(0, 0, state.width, state.height);

      // background
      const bg = ctx.createLinearGradient(0, 0, 0, state.height);
      bg.addColorStop(0, "#0b1020");
      bg.addColorStop(1, "#050816");
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, state.width, state.height);

      const { cellW, cellH, gap, originX, originY } = getGridMetrics();

      // draw cells
      for (const cell of state.cells) {
        const x = originX + cell.col * (cellW + gap);
        const y = originY + cell.row * (cellH + gap);

        // skip offscreen for performance
        if (x + cellW < -50 || y + cellH < -50 || x > state.width + 50 || y > state.height + 50) continue;

        const isHover = state.hoverCell === cell;
        const fill = priceToColor(cell.changePct);

        ctx.save();
        ctx.shadowColor = isHover ? "rgba(255,255,255,0.25)" : "rgba(0,0,0,0.25)";
        ctx.shadowBlur = isHover ? 18 : 8;
        ctx.fillStyle = fill;
        roundRect(ctx, x, y, cellW, cellH, 12 * state.zoom);
        ctx.fill();

        // border
        ctx.shadowBlur = 0;
        ctx.lineWidth = isHover ? 2 : 1;
        ctx.strokeStyle = isHover ? "rgba(255,255,255,0.85)" : "rgba(255,255,255,0.08)";
        ctx.stroke();

        // text
        ctx.fillStyle = "rgba(255,255,255,0.95)";
        ctx.font = `${Math.max(10, 14 * state.zoom)}px system-ui, sans-serif`;
        ctx.textBaseline = "top";
        ctx.fillText(cell.symbol, x + 10 * state.zoom, y + 10 * state.zoom);

        ctx.font = `600 ${Math.max(12, 18 * state.zoom)}px system-ui, sans-serif`;
        ctx.fillText(`$${cell.price.toFixed(2)}`, x + 10 * state.zoom, y + 28 * state.zoom);

        ctx.font = `${Math.max(9, 12 * state.zoom)}px system-ui, sans-serif`;
        const changeText = `${cell.changePct >= 0 ? "+" : ""}${cell.changePct.toFixed(2)}%`;
        ctx.fillStyle = cell.changePct >= 0 ? "#bbf7d0" : "#fecaca";
        ctx.fillText(changeText, x + 10 * state.zoom, y + 50 * state.zoom);

        ctx.restore();
      }
    }

    function roundRect(ctx, x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    function screenToCell(mx, my) {
      const { cellW, cellH, gap, originX, originY } = getGridMetrics();

      for (const cell of state.cells) {
        const x = originX + cell.col * (cellW + gap);
        const y = originY + cell.row * (cellH + gap);
        if (mx >= x && mx <= x + cellW && my >= y && my <= y + cellH) {
          return { cell, x, y, w: cellW, h: cellH };
        }
      }
      return null;
    }

    function updateTooltip(mx, my, hit) {
      if (!hit) {
        tooltip.style.display = "none";
        return;
      }

      const c = hit.cell;
      tooltip.style.display = "block";
      tooltip.style.left = mx + "px";
      tooltip.style.top = my + "px";
      tooltip.innerHTML = `
        <div><strong>${c.symbol}</strong></div>
        <div>Price: $${c.price.toFixed(2)}</div>
        <div>Change: ${c.changePct >= 0 ? "+" : ""}${c.changePct.toFixed(2)}%</div>
        <div>Volume: ${c.volume.toLocaleString()}</div>
      `;
    }

    canvas.addEventListener("mousedown", (e) => {
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      state.lastMouseX = e.clientX;
      state.lastMouseY = e.clientY;

      if (state.dragging) {
        state.panX = state.startPanX + (e.clientX - state.dragStartX);
        state.panY = state.startPanY + (e.clientY - state.dragStartY);
        draw();
        return;
      }

      const hit = screenToCell(e.clientX, e.clientY);
      state.hoverCell = hit ? hit.cell : null;
      updateTooltip(e.clientX, e.clientY, hit);
      draw();
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const oldZoom = state.zoom;
      const newZoom = clamp(state.zoom * zoomFactor, 0.45, 2.5);

      // zoom around mouse position
      const mx = e.clientX;
      const my = e.clientY;
      const before = screenToWorld(mx, my, oldZoom);
      state.zoom = newZoom;
      const after = screenToWorld(mx, my, newZoom);

      state.panX += (after.x - before.x) * newZoom;
      state.panY += (after.y - before.y) * newZoom;

      draw();
    }, { passive: false });

    function screenToWorld(mx, my, zoom) {
      const { cellW, cellH, gap, originX, originY } = getGridMetricsForZoom(zoom);
      return {
        x: (mx - originX) / (cellW + gap),
        y: (my - originY) / (cellH + gap)
      };
    }

    function getGridMetricsForZoom(zoom) {
      const baseCellW = 120;
      const baseCellH = 72;
      const cellW = baseCellW * zoom;
      const cellH = baseCellH * zoom;
      const gap = state.cellGap * zoom;
      const totalW = state.cols * cellW + (state.cols - 1) * gap;
      const totalH = state.rows * cellH + (state.rows - 1) * gap;
      const originX = (state.width - totalW) / 2 + state.panX;
      const originY = (state.height - totalH) / 2 + state.panY;
      return { cellW, cellH, gap, originX, originY, totalW, totalH };
    }

    // Simulated real-time updates
    function tick() {
      for (const cell of state.cells) {
        cell.prevPrice = cell.price;

        // random walk with occasional spikes
        const drift = rand(-0.8, 0.8);
        const spike = Math.random() < 0.03 ? rand(-4, 4) : 0;
        const delta = drift + spike;

        cell.price = Math.max(1, cell.price + delta);
        cell.changePct = ((cell.price - cell.prevPrice) / cell.prevPrice) * 100;

        // volume changes too
        cell.volume = Math.max(0, cell.volume + Math.floor(rand(-5000, 5000)));
      }

      draw();
    }

    // Optional: replace with WebSocket feed
    // const ws = new WebSocket("wss://your-feed.example.com");
    // ws.onmessage = (event) => {
    //   const updates = JSON.parse(event.data);
    //   // apply updates to state.cells
    //   draw();
    // };

    window.addEventListener("resize", resize);

    initData();
    resize();
    setInterval(tick, 500);
  </script>
</body>
</html>
```

---

## How it works

- **Canvas rendering**: fast drawing for many cells.
- **Zoom/pan**:
  - Mouse wheel changes `state.zoom`
  - Dragging changes `state.panX/panY`
- **Real-time updates**:
  - `setInterval(tick, 500)` simulates live price changes
- **Hover detection**:
  - Converts mouse coordinates to a cell hit test
- **Color mapping**:
  - Negative change = red
  - Positive change = green
  - Neutral = dark

---

## If you want live market data

Replace the simulated `tick()` with a WebSocket or SSE feed. For example:

```js
const ws = new WebSocket("wss://your-data-provider.example.com/stream");

ws.onmessage = (event) => {
  const msg = JSON.parse(event.data);
  // Example msg:
  // { symbol: "AAPL", price: 189.23, volume: 123456 }

  const cell = state.cells.find(c => c.symbol === msg.symbol);
  if (cell) {
    cell.prevPrice = cell.price;
    cell.price = msg.price;
    cell.changePct = ((cell.price - cell.prevPrice) / cell.prevPrice) * 100;
    cell.volume = msg.volume ?? cell.volume;
    draw();
  }
};
```

