  <script>
    const viewport = document.getElementById('viewport');
    const canvas = document.getElementById('canvas');
    const heatmap = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const zoomLabel = document.getElementById('zoomLabel');
    const updateLabel = document.getElementById('updateLabel');
    const resetBtn = document.getElementById('resetBtn');
    const toggleBtn = document.getElementById('toggleBtn');

    const tickers = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','AMD','NFLX','INTC','ORCL','CRM',
      'UBER','SNOW','SHOP','ADBE','QCOM','AVGO','PYPL','BABA','BA','JPM','V','MA',
      'DIS','KO','PEP','XOM','CVX','WMT','COST','NKE','PFE','MRNA','LLY','UNH'
    ];

    const state = {
      scale: 1,
      tx: 0,
      ty: 0,
      dragging: false,
      lastX: 0,
      lastY: 0,
      paused: false,
      updatesPerSec: 0
    };

    const stocks = tickers.map((ticker, i) => ({
      ticker,
      price: +(50 + Math.random() * 450).toFixed(2),
      prev: null,
      change: 0,
      volume: Math.floor(1e6 + Math.random() * 9e6),
      sector: ['Tech','Finance','Retail','Energy','Health'][i % 5]
    }));

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // change in percent
      const maxAbs = 5;
      const t = clamp((change + maxAbs) / (2 * maxAbs), 0, 1);
      // red -> yellow -> green
      const red = [217, 75, 75];
      const yellow = [240, 196, 25];
      const green = [46, 204, 113];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = yellow; localT = t / 0.5;
      } else {
        c1 = yellow; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = c1.map((v, idx) => Math.round(v + (c2[idx] - v) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function textColorForBg(change) {
      return Math.abs(change) > 2.5 ? '#ffffff' : '#0b1020';
    }

    function render() {
      heatmap.innerHTML = '';
      stocks.forEach((s, idx) => {
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.index = idx;

        const bg = colorForChange(s.change);
        const fg = textColorForBg(s.change);

        cell.style.background = `linear-gradient(135deg, ${bg}, rgba(255,255,255,0.08))`;
        cell.style.color = fg;

        cell.innerHTML = `
          <div class="ticker">${s.ticker}</div>
