        cell.addEventListener('mouseenter', (e) => {
          showTooltip(e, s);
        });
        cell.addEventListener('mousemove', (e) => {
          moveTooltip(e);
        });
        cell.addEventListener('mouseleave', hideTooltip);

        heatmap.appendChild(cell);
      });
      applyTransform();
    }

    function updateRandomPrices() {
      if (state.paused) return;

      let updates = 0;
      stocks.forEach(s => {
        s.prev = s.price;
        const deltaPct = (Math.random() - 0.5) * 1.8; // -0.9% to +0.9%
        s.price = Math.max(1, +(s.price * (1 + deltaPct / 100)).toFixed(2));
        s.change = +(((s.price - s.prev) / s.prev) * 100).toFixed(2);
        s.volume += Math.floor((Math.random() - 0.4) * 50000);
        updates++;
      });

      updateLabel.textContent = updates;
      render();
    }

    function applyTransform() {
      canvas.style.transform = `translate(${state.tx}px, ${state.ty}px) scale(${state.scale})`;
      zoomLabel.textContent = `${Math.round(state.scale * 100)}%`;
    }

    function resetView() {
      state.scale = 1;
      state.tx = 0;
      state.ty = 0;
      applyTransform();
    }

    function showTooltip(e, s) {
      tooltip.classList.add('visible');
      tooltip.innerHTML = `
        <strong>${s.ticker}</strong><br/>
        Price: $${s.price.toFixed(2)}<br/>
