    function moveTooltip(e) {
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
    }

    function hideTooltip() {
      tooltip.classList.remove('visible');
    }

    viewport.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      viewport.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      viewport.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (!state.dragging) return;
      const dx = e.clientX - state.lastX;
      const dy = e.clientY - state.lastY;
      state.tx += dx;
      state.ty += dy;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      applyTransform();
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const nextScale = clamp(state.scale * zoomFactor, 0.5, 3);

      // Zoom around cursor
      const worldX = (mouseX - state.tx) / state.scale;
      const worldY = (mouseY - state.ty) / state.scale;

      state.scale = nextScale;
      state.tx = mouseX - worldX * state.scale;
      state.ty = mouseY - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    resetBtn.addEventListener('click', resetView);

    toggleBtn.addEventListener('click', () => {
      state.paused = !state.paused;
      toggleBtn.textContent = state.paused ? 'Resume Updates' : 'Pause Updates';
    });

    // Initial render
    render();

    // Simulated real-time updates
    setInterval(updateRandomPrices, 1000);

    // Optional: smoother continuous updates label
    setInterval(() => {
      if (!state.paused) updateLabel.textContent = stocks.length;
    }, 1000);
  </script>
