    let offsetStart = { x: 0, y: 0 };
    let hoverCell = null;

    function screenToWorld(x, y) {
      return {
        x: (x - view.offsetX) / view.scale,
        y: (y - view.offsetY) / view.scale
      };
    }

    function worldToScreen(x, y) {
      return {
        x: x * view.scale + view.offsetX,
        y: y * view.scale + view.offsetY
      };
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    // --- Color scale ---
    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function hexToRgb(hex) {
      const m = hex.replace('#', '');
      const n = parseInt(m, 16);
      return {
        r: (n >> 16) & 255,
        g: (n >> 8) & 255,
        b: n & 255
      };
    }

    function rgbToHex(r, g, b) {
      return '#' + [r, g, b].map(v => v.toString(16).padStart(2, '0')).join('');
    }

    function mix(c1, c2, t) {
      const a = hexToRgb(c1), b = hexToRgb(c2);
      return rgbToHex(
        Math.round(lerp(a.r, b.r, t)),
        Math.round(lerp(a.g, b.g, t)),
        Math.round(lerp(a.b, b.b, t))
      );
    }

    function colorForChange(pct) {
      const min = -8;
      const max = 8;
      const t = clamp((pct - min) / (max - min), 0, 1);

      // Red -> white -> green
      if (t < 0.5) return mix('#b91c1c', '#f8fafc', t / 0.5);
      return mix('#f8fafc', '#15803d', (t - 0.5) / 0.5);
    }

    function textColorForBg(pct) {
      return Math.abs(pct) > 3.5 ? '#ffffff' : '#0f172a';
    }

    // --- Layout ---
    function getGridMetrics() {
      const margin = 24;
      const gap = 10;
      const cellW = 150;
      const cellH = 92;
      const gridW = cols * cellW + (cols - 1) * gap;
      const gridH = rows * cellH + (rows - 1) * gap;
      const startX = (width - gridW) / 2;
      const startY = (height - gridH) / 2;
      return { margin, gap, cellW, cellH, gridW, gridH, startX, startY };
    }

    function cellBounds(index) {
      const { gap, cellW, cellH, startX, startY } = getGridMetrics();
      const col = index % cols;
      const row = Math.floor(index / cols);
      const x = startX + col * (cellW + gap);
      const y = startY + row * (cellH + gap);
      return { x, y, w: cellW, h: cellH };
    }

    function findCellAtScreen(x, y) {
      const p = screenToWorld(x, y);
      for (let i = 0; i < cells.length; i++) {
        const b = cellBounds(i);
        if (p.x >= b.x && p.x <= b.x + b.w && p.y >= b.y && p.y <= b.y + b.h) {
          return { cell: cells[i], index: i, bounds: b };
        }
      }
      return null;
    }

    // --- Drawing ---
    function drawRoundedRect(ctx, x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function draw() {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, width, height);

      // Apply view transform
      ctx.save();
      ctx.translate(view.offsetX, view.offsetY);
      ctx.scale(view.scale, view.scale);

      const { gap, cellW, cellH } = getGridMetrics();

      // Background subtle grid
      ctx.fillStyle = 'rgba(255,255,255,0.02)';
      for (let i = 0; i < cells.length; i++) {
        const b = cellBounds(i);
        drawRoundedRect(ctx, b.x, b.y, b.w, b.h, 14);
        ctx.fillStyle = colorForChange(cells[i].changePct);
        ctx.fill();

        // Border
        ctx.strokeStyle = 'rgba(15, 23, 42, 0.35)';
        ctx.lineWidth = 1;
        ctx.stroke();

        // Highlight hover
        if (hoverCell && hoverCell.index === i) {
          ctx.strokeStyle = 'rgba(255,255,255,0.9)';
          ctx.lineWidth = 2;
          ctx.stroke();
        }

        // Text
        const c = cells[i];
        const fg = textColorForBg(c.changePct);
        ctx.fillStyle = fg;
        ctx.font = '600 16px Inter, system-ui, sans-serif';
        ctx.fillText(c.symbol, b.x + 12, b.y + 24);

        ctx.font = '12px Inter, system-ui, sans-serif';
        ctx.fillText(`$${c.price.toFixed(2)}`, b.x + 12, b.y + 46);

        const sign = c.changePct >= 0 ? '+' : '';
        ctx.fillText(`${sign}${c.changePct.toFixed(2)}%`, b.x + 12, b.y + 66);

        ctx.fillStyle = 'rgba(255,255,255,0.75)';
        ctx.font = '11px Inter, system-ui, sans-serif';
        ctx.fillText(c.sector, b.x + 12, b.y + 82);
      }

      ctx.restore();
    }

    // --- Tooltip ---
    function showTooltip(x, y, cell) {
      tooltip.classList.add('visible');
      tooltip.style.left = x + 'px';
      tooltip.style.top = y + 'px';

      const sign = cell.changePct >= 0 ? '+' : '';
      tooltip.innerHTML = `
        <div><strong>${cell.symbol}</strong> <span style="color:#94a3b8">(${cell.sector})</span></div>
        <div>Price: $${cell.price.toFixed(2)}</div>
        <div>Change: ${sign}${cell.changePct.toFixed(2)}%</div>
        <div>Volume: ${cell.volume.toLocaleString()}</div>
      `;
    }

    function hideTooltip() {
      tooltip.classList.remove('visible');
    }

    // --- Events ---
    wrap.addEventListener('mousedown', (e) => {
      isDragging = true;
      wrap.classList.add('dragging');
      dragStart = { x: e.clientX, y: e.clientY };
      offsetStart = { x: view.offsetX, y: view.offsetY };
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      wrap.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (isDragging) {
        view.offsetX = offsetStart.x + (e.clientX - dragStart.x);
        view.offsetY = offsetStart.y + (e.clientY - dragStart.y);
        draw();
        return;
      }

      const hit = findCellAtScreen(e.clientX - wrap.getBoundingClientRect().left, e.clientY - wrap.getBoundingClientRect().top);
      hoverCell = hit;
      if (hit) {
        showTooltip(e.clientX - wrap.getBoundingClientRect().left, e.clientY - wrap.getBoundingClientRect().top, hit.cell);
      } else {
        hideTooltip();
      }
      draw();
    });

    wrap.addEventListener('mouseleave', () => {
      hoverCell = null;
      hideTooltip();
      draw();
    });

    wrap.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = wrap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const newScale = clamp(view.scale * zoomFactor, 0.5, 4);

      // Zoom around cursor
      const worldBefore = screenToWorld(mouseX, mouseY);
      view.scale = newScale;
      view.offsetX = mouseX - worldBefore.x * view.scale;
      view.offsetY = mouseY - worldBefore.y * view.scale;

      draw();
    }, { passive: false });

    // --- Real-time updates (simulated) ---
    function updatePrices() {
      for (const c of cells) {
        c.prevClose = c.prevClose || c.price;

        // Random walk with slight mean reversion
        const drift = (Math.random() - 0.5) * 0.02;
        const shock = (Math.random() - 0.5) * 0.8;
        c.price = Math.max(1, c.price * (1 + drift / 100) + shock);

        // Occasionally update volume
        if (Math.random() < 0.2) {
          c.volume = Math.max(1000, Math.floor(c.volume * (0.9 + Math.random() * 0.2)));
        }
      }
      recalcChanges();
      draw();
    }

    // If you have a real feed, replace this with WebSocket updates.
    const updateTimer = setInterval(updatePrices, 1000);

    // --- Optional: pause updates when tab hidden ---
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) {
        statusEl.textContent = 'Live updates: paused';
      } else {
        statusEl.textContent = 'Live updates: on';
      }
    });

    // Initial fit
    resize();

    // Center view on first load
    const initial = getGridMetrics();
    view.offsetX = 0;
    view.offsetY = 0;
    draw();
  </script>
</body>
</html>
```

