    // Initialize stock data
    for (let i = 0; i < rows * cols; i++) {
      const base = rand(20, 500);
      const changePct = rand(-5, 5);
      stocks.push({
        ticker: tickers[i % tickers.length],
        price: base,
        prevClose: base / (1 + changePct / 100),
