    // --- Rendering ---
    grid.style.gridTemplateColumns = `repeat(${cols}, 120px)`;

    function colorForChange(changePct) {
      // Map changePct to color from red -> dark -> green
      const t = clamp((changePct + 5) / 10, 0, 1); // -5..+5 => 0..1
      const hue = 0 + t * 140; // red to green
      const sat = 70;
      const light = 28 + t * 18;
      return `hsl(${hue}, ${sat}%, ${light}%)`;
    }

    function render() {
      grid.innerHTML = '';
      stocks.forEach((s, idx) => {
        const cell = document.createElement('div');
        cell.className = 'cell';
