    window.addEventListener('mousemove', (e) => {
      if (!isDragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      applyTransform();
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      viewport.classList.remove('dragging');
    });

    resetBtn.addEventListener('click', resetView);

    // --- Real-time updates (simulated) ---
    let live = true;

    function updatePrices() {
      if (!live) return;

      stocks.forEach(s => {
        // random walk
        const drift = rand(-0.6, 0.6);
        const shock = rand(-1.2, 1.2);
        const pctMove = (drift + shock) / 100;

        s.price = Math.max(1, s.price * (1 + pctMove));
        s.changePct = ((s.price - s.prevClose) / s.prevClose) * 100;
      });

      render();
      statusEl.textContent = `Live updates: on • ${new Date().toLocaleTimeString()}`;
    }

    const interval = setInterval(updatePrices, 1000);

    toggleLiveBtn.addEventListener('click', () => {
      live = !live;
      toggleLiveBtn.textContent = live ? 'Pause Live' : 'Resume Live';
      statusEl.textContent = live ? 'Live updates: on' : 'Live updates: paused';
    });

    // Initial render
    render();
    applyTransform();

    // Optional: keep tooltip inside viewport edges
    document.addEventListener('mousemove', (e) => {
      const pad = 16;
      const rect = tooltip.getBoundingClientRect();
      let x = e.clientX + 12;
      let y = e.clientY + 12;

      if (x + rect.width > window.innerWidth - pad) {
        x = e.clientX - rect.width - 12;
      }
      if (y + rect.height > window.innerHeight - pad) {
        y = e.clientY - rect.height - 12;
      }

      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    });
  </script>
