          Reset view
        </button>
      </div>
    </header>

    <div id="canvasWrap">
      <canvas id="heatmap"></canvas>
      <div id="tooltip"></div>
    </div>

    <footer>
      <div>Mouse wheel: zoom • Drag: pan • Hover: details • Click: pin tooltip</div>
      <div id="status">Ready</div>
    </footer>
  </div>

  <script>
    (() => {
      const canvas = document.getElementById('heatmap');
      const wrap = document.getElementById('canvasWrap');
      const tooltip = document.getElementById('tooltip');
      const status = document.getElementById('status');
      const speedInput = document.getElementById('speed');
      const speedLabel = document.getElementById('speedLabel');
      const volInput = document.getElementById('volatility');
      const volLabel = document.getElementById('volLabel');
      const resetBtn = document.getElementById('resetBtn');

      const ctx = canvas.getContext('2d', { alpha: true });

      // Heatmap data
      const rows = 18;
      const cols = 28;
      const stocks = Array.from({ length: rows }, (_, i) => `STK${String(i + 1).padStart(2, '0')}`);
      const data = Array.from({ length: rows }, (_, r) =>
        Array.from({ length: cols }, (_, c) => ({
          symbol: stocks[r],
          time: c,
          price: 100 + Math.random() * 50,
          change: (Math.random() - 0.5) * 4,
          volume: Math.floor(1000 + Math.random() * 9000)
        }))
      );

      // View transform
      const view = {
        scale: 1,
        offsetX: 0,
        offsetY: 0
      };

      let dpr = Math.max(1, window.devicePixelRatio || 1);
      let width = 0;
      let height = 0;

      let dragging = false;
      let dragStart = { x: 0, y: 0 };
      let viewStart = { x: 0, y: 0 };

      let pinned = null;
      let hoverCell = null;

      function resize() {
        const rect = wrap.getBoundingClientRect();
        width = rect.width;
        height = rect.height;
        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        canvas.style.width = width + 'px';
        canvas.style.height = height + 'px';
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        draw();
      }

      function clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      function lerp(a, b, t) {
        return a + (b - a) * t;
      }

      function colorForChange(change) {
        // Map change to red-white-green
        const maxAbs = 20;
        const t = clamp((change + maxAbs) / (2 * maxAbs), 0, 1);
        const r = Math.round(lerp(220, 34, t));
        const g = Math.round(lerp(38, 197, t));
        const b = Math.round(lerp(38, 94, t));
        return `rgb(${r}, ${g}, ${b})`;
      }

      function cellMetrics() {
        const baseCellW = 90;
        const baseCellH = 42;
        return {
          cellW: baseCellW * view.scale,
          cellH: baseCellH * view.scale,
          gap: 4 * view.scale
        };
      }

      function worldToScreen(x, y) {
        return {
          x: x * view.scale + view.offsetX,
          y: y * view.scale + view.offsetY
        };
      }

      function screenToWorld(x, y) {
        return {
          x: (x - view.offsetX) / view.scale,
          y: (y - view.offsetY) / view.scale
        };
      }

      function getCellAtPointer(px, py) {
        const { cellW, cellH, gap } = cellMetrics();
        const world = screenToWorld(px, py);
        const totalW = cellW + gap;
        const totalH = cellH + gap;

        const col = Math.floor(world.x / totalW);
        const row = Math.floor(world.y / totalH);

        if (row < 0 || row >= rows || col < 0 || col >= cols) return null;

        const localX = world.x - col * totalW;
        const localY = world.y - row * totalH;

        if (localX > cellW || localY > cellH) return null;

        return { row, col };
      }

      function drawGridBackground() {
        ctx.clearRect(0, 0, width, height);

        // subtle grid backdrop
        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, width, height);

        const gridSize = 40;
        ctx.strokeStyle = 'rgba(255,255,255,0.03)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        for (let x = 0; x < width; x += gridSize) {
          ctx.moveTo(x, 0);
          ctx.lineTo(x, height);
        }
        for (let y = 0; y < height; y += gridSize) {
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
        }
        ctx.stroke();
      }

      function draw() {
        drawGridBackground();

        const { cellW, cellH, gap } = cellMetrics();
        const totalW = cellW + gap;
        const totalH = cellH + gap;

        ctx.save();
        ctx.translate(view.offsetX, view.offsetY);
        ctx.scale(view.scale, view.scale);

        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const cell = data[r][c];
            const x = c * totalW;
            const y = r * totalH;

            const isHover = hoverCell && hoverCell.row === r && hoverCell.col === c;
            const isPinned = pinned && pinned.row === r && pinned.col === c;

            ctx.fillStyle = colorForChange(cell.change);
            ctx.globalAlpha = 0.95;
            roundRect(ctx, x, y, cellW, cellH, 8);
            ctx.fill();

            if (isHover || isPinned) {
              ctx.strokeStyle = isPinned ? '#ffffff' : '#4cc9f0';
              ctx.lineWidth = 2 / view.scale;
              roundRect(ctx, x, y, cellW, cellH, 8);
              ctx.stroke();
            }

            // text
            ctx.globalAlpha = 1;
            ctx.fillStyle = 'rgba(255,255,255,0.95)';
            ctx.font = `${12 / view.scale}px Inter, sans-serif`;
            ctx.fillText(cell.symbol, x + 10, y + 16);

            ctx.fillStyle = 'rgba(255,255,255,0.88)';
            ctx.font = `${11 / view.scale}px Inter, sans-serif`;
            ctx.fillText(`$${cell.price.toFixed(2)}`, x + 10, y + 31);

            const changeText = `${cell.change >= 0 ? '+' : ''}${cell.change.toFixed(2)}%`;
            ctx.fillStyle = cell.change >= 0 ? '#d1fae5' : '#fee2e2';
            ctx.fillText(changeText, x + cellW - ctx.measureText(changeText).width - 10, y + 31);
          }
        }

        ctx.restore();
      }

      function roundRect(ctx, x, y, w, h, r) {
        const radius = Math.min(r, w / 2, h / 2);
        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.arcTo(x + w, y, x + w, y + h, radius);
        ctx.arcTo(x + w, y + h, x, y + h, radius);
        ctx.arcTo(x, y + h, x, y, radius);
        ctx.arcTo(x, y, x + w, y, radius);
        ctx.closePath();
      }

      function showTooltip(cell, px, py) {
        if (!cell) {
          tooltip.style.display = 'none';
          return;
        }
        const d = data[cell.row][cell.col];
        tooltip.style.display = 'block';
        tooltip.style.left = px + 'px';
        tooltip.style.top = py + 'px';
        tooltip.innerHTML = `
          <div><strong>${d.symbol}</strong></div>
          <div>Price: $${d.price.toFixed(2)}</div>
          <div>Change: <span style="color:${d.change >= 0 ? '#86efac' : '#fca5a5'}">${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}%</span></div>
          <div>Volume: ${d.volume.toLocaleString()}</div>
          <div style="color:#94a3b8;margin-top:4px;">Cell ${cell.row + 1}, ${cell.col + 1}</div>
        `;
      }

      function updateStatus() {
        const live = `Scale ${view.scale.toFixed(2)} | Offset (${Math.round(view.offsetX)}, ${Math.round(view.offsetY)})`;
        status.textContent = pinned ? `${live} | Pinned ${data[pinned.row][pinned.col].symbol}` : live;
      }

      function animateUpdate() {
        const volatility = Number(volInput.value);
        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const cell = data[r][c];
            const delta = (Math.random() - 0.5) * volatility;
            cell.change = clamp(cell.change + delta * 0.15, -20, 20);
            cell.price = Math.max(1, cell.price * (1 + delta / 1000));
            cell.volume = Math.max(0, Math.floor(cell.volume + (Math.random() - 0.5) * 500));
          }
        }
        draw();
      }

      let updateTimer = null;
      function restartUpdates() {
        if (updateTimer) clearInterval(updateTimer);
        updateTimer = setInterval(animateUpdate, Number(speedInput.value));
      }

      canvas.addEventListener('pointerdown', (e) => {
        dragging = true;
        canvas.setPointerCapture(e.pointerId);
        dragStart = { x: e.clientX, y: e.clientY };
        viewStart = { x: view.offsetX, y: view.offsetY };
      });

      canvas.addEventListener('pointermove', (e) => {
        const rect = canvas.getBoundingClientRect();
        const px = e.clientX - rect.left;
        const py = e.clientY - rect.top;

        if (dragging) {
          view.offsetX = viewStart.x + (e.clientX - dragStart.x);
          view.offsetY = viewStart.y + (e.clientY - dragStart.y);
          draw();
          updateStatus();
          return;
        }

        hoverCell = getCellAtPointer(px, py);
        if (hoverCell) {
          showTooltip(hoverCell, px, py);
        } else if (!pinned) {
          tooltip.style.display = 'none';
        }

        if (pinned) {
          const d = data[pinned.row][pinned.col];
          tooltip.style.display = 'block';
          tooltip.style.left = px + 'px';
          tooltip.style.top = py + 'px';
          tooltip.innerHTML = `
            <div><strong>${d.symbol}</strong> <span style="color:#93c5fd">(pinned)</span></div>
            <div>Price: $${d.price.toFixed(2)}</div>
            <div>Change: <span style="color:${d.change >= 0 ? '#86efac' : '#fca5a5'}">${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}%</span></div>
            <div>Volume: ${d.volume.toLocaleString()}</div>
          `;
        }

        draw();
      });

      canvas.addEventListener('pointerup', (e) => {
        dragging = false;
        try { canvas.releasePointerCapture(e.pointerId); } catch {}
      });

      canvas.addEventListener('pointerleave', () => {
        if (!pinned) {
          hoverCell = null;
          tooltip.style.display = 'none';
          draw();
        }
      });

      canvas.addEventListener('click', (e) => {
        const rect = canvas.getBoundingClientRect();
        const px = e.clientX - rect.left;
        const py = e.clientY - rect.top;
        const cell = getCellAtPointer(px, py);
        pinned = cell ? { ...cell } : null;
        if (!pinned) tooltip.style.display = 'none';
        draw();
        updateStatus();
      });

      canvas.addEventListener('wheel', (e) => {
        e.preventDefault();

        const rect = canvas.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;

        const zoomFactor = Math.exp(-e.deltaY * 0.001);
        const newScale = clamp(view.scale * zoomFactor, 0.5, 4);

        // Zoom around mouse position
        const worldBefore = screenToWorld(mx, my);
        view.scale = newScale;
        view.offsetX = mx - worldBefore.x * view.scale;
        view.offsetY = my - worldBefore.y * view.scale;

        draw();
        updateStatus();
      }, { passive: false });

      speedInput.addEventListener('input', () => {
        speedLabel.textContent = `${speedInput.value}ms`;
        restartUpdates();
      });

      volInput.addEventListener('input', () => {
        volLabel.textContent = volInput.value;
      });

      resetBtn.addEventListener('click', () => {
        view.scale = 1;
        view.offsetX = 20;
        view.offsetY = 20;
        pinned = null;
        hoverCell = null;
        tooltip.style.display = 'none';
        draw();
        updateStatus();
      });

      window.addEventListener('resize', resize);

      // Initial view
      view.offsetX = 20;
      view.offsetY = 20;

      speedLabel.textContent = `${speedInput.value}ms`;
      volLabel.textContent = volInput.value;

      resize();
      restartUpdates();
      updateStatus();

      // Optional: simulate a websocket feed hook
      // Replace this with real data updates from your backend.
      window.simulateStockUpdate = function(symbol, price, change, volume) {
        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            if (data[r][c].symbol === symbol) {
              data[r][c].price = price;
              data[r][c].change = change;
              data[r][c].volume = volume;
            }
          }
        }
        draw();
      };
    })();
  </script>
</body>
</html>
```

### How it works
- **Canvas rendering** keeps it fast for many cells.
- **Real-time updates** are simulated with `setInterval`; you can swap this for WebSocket data.
- **Zoom/pan** are handled by a simple transform (`scale`, `offsetX`, `offsetY`).
- **Hover/click** uses pointer coordinates mapped back into heatmap cell coordinates.

### To connect real stock data
Replace `animateUpdate()` with a WebSocket/SSE handler that updates the `data` array, e.g.:

```js
socket.onmessage = (event) => {
  const update = JSON.parse(event.data);
  // update symbol, price, change, volume
  window.simulateStockUpdate(update.symbol, update.price, update.change, update.volume);
};
```

