        const mid = { r: 43, g: 53, b: 87 };
        const green = { r: 61, g: 220, b: 132 };

        let c;
        if (t < 0.5) {
          const u = t / 0.5;
          c = {
            r: Math.round(lerp(red.r, mid.r, u)),
            g: Math.round(lerp(red.g, mid.g, u)),
            b: Math.round(lerp(red.b, mid.b, u))
          };
        } else {
          const u = (t - 0.5) / 0.5;
          c = {
            r: Math.round(lerp(mid.r, green.r, u)),
            g: Math.round(lerp(mid.g, green.g, u)),
            b: Math.round(lerp(mid.b, green.b, u))
          };
        }
        return `rgb(${c.r},${c.g},${c.b})`;
      }

      function drawGridBackground(w, h, cellW, cellH) {
        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, w, h);

        ctx.strokeStyle = 'rgba(255,255,255,0.05)';
        ctx.lineWidth = 1;

        for (let r = 0; r <= rows; r++) {
          const y = r * cellH;
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(cols * cellW, y);
          ctx.stroke();
        }

        for (let c = 0; c <= cols; c++) {
          const x = c * cellW;
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, rows * cellH);
          ctx.stroke();
        }
      }

      function draw() {
        const rect = wrap.getBoundingClientRect();
        const w = rect.width;
        const h = rect.height;

        ctx.save();
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.restore();

        // Apply pan/zoom in CSS pixel space
        ctx.save();
        ctx.translate(offsetX, offsetY);
        ctx.scale(scale, scale);

        const cellW = 120;
        const cellH = 28;
        const totalW = cols * cellW;
        const totalH = rows * cellH;

        // Background and grid
        drawGridBackground(w, h, cellW, cellH);

        // Draw cells
        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const cell = data[r][c];
            const x = c * cellW;
            const y = r * cellH;

            ctx.fillStyle = colorForChange(cell.changePct);
            ctx.fillRect(x + 1, y + 1, cellW - 2, cellH - 2);

            // Text
            ctx.fillStyle = '#ffffff';
            ctx.font = '12px system-ui, sans-serif';
            ctx.textBaseline = 'middle';

            const label = `${symbols[r]}`;
            const priceText = cell.price.toFixed(2);
            const pctText = `${cell.changePct >= 0 ? '+' : ''}${cell.changePct.toFixed(2)}%`;

            ctx.fillText(label, x + 8, y + cellH / 2);
            ctx.textAlign = 'right';
            ctx.fillText(priceText, x + cellW - 8, y + cellH / 2 - 6);
            ctx.fillStyle = cell.changePct >= 0 ? '#d8ffe8' : '#ffe0e0';
            ctx.fillText(pctText, x + cellW - 8, y + cellH / 2 + 6);
            ctx.textAlign = 'left';
          }
        }

        // Border around data area
        ctx.strokeStyle = 'rgba(255,255,255,0.15)';
        ctx.lineWidth = 1;
        ctx.strokeRect(0.5, 0.5, totalW - 1, totalH - 1);

        ctx.restore();
      }

      function screenToWorld(clientX, clientY) {
        const rect = canvas.getBoundingClientRect();
        return {
          x: (clientX - rect.left - offsetX) / scale,
          y: (clientY - rect.top - offsetY) / scale
        };
      }

      function updateTooltip(e) {
        const cellW = 120;
        const cellH = 28;
        const p = screenToWorld(e.clientX, e.clientY);
        const c = Math.floor(p.x / cellW);
        const r = Math.floor(p.y / cellH);

        if (r >= 0 && r < rows && c >= 0 && c < cols) {
          const cell = data[r][c];
          tooltip.style.display = 'block';
          tooltip.style.left = `${e.clientX - wrap.getBoundingClientRect().left}px`;
          tooltip.style.top = `${e.clientY - wrap.getBoundingClientRect().top}px`;
          tooltip.innerHTML = `
            <div><strong>${symbols[r]}</strong> @ T${String(c + 1).padStart(2, '0')}</div>
            <div>Price: <strong>${cell.price.toFixed(2)}</strong></div>
            <div>Change: <strong style="color:${cell.changePct >= 0 ? '#3ddc84' : '#ff7b7b'}">
              ${cell.changePct >= 0 ? '+' : ''}${cell.changePct.toFixed(2)}%
            </strong></div>
            <div>Volume: <strong>${cell.volume.toLocaleString()}</strong></div>
          `;
        } else {
          tooltip.style.display = 'none';
        }
      }

      // --- Real-time updates (simulated) ---
      function tick() {
        if (!live) return;

        for (let r = 0; r < rows; r++) {
          for (let c = 0; c < cols; c++) {
            const cell = data[r][c];
            cell.prev = cell.price;

            // Random walk with slight mean reversion
            const drift = (Math.random() - 0.5) * 1.2;
            const shock = (Math.random() - 0.5) * 0.8;
            cell.price = Math.max(1, cell.price + drift + shock);

            cell.changePct = ((cell.price - cell.prev) / cell.prev) * 100;

            // Occasionally spike volume
            if (Math.random() < 0.03) {
              cell.volume = Math.floor(cell.volume * (1 + Math.random() * 2));
            } else {
              cell.volume = Math.max(100, Math.floor(cell.volume * (0.98 + Math.random() * 0.04)));
            }
          }
        }

        draw();
      }

      // --- Interaction: pan / zoom ---
      canvas.addEventListener('mousedown', (e) => {
        isPanning = true;
        panStart = { x: e.clientX, y: e.clientY };
        offsetStart = { x: offsetX, y: offsetY };
      });

      window.addEventListener('mousemove', (e) => {
        if (isPanning) {
          offsetX = offsetStart.x + (e.clientX - panStart.x);
          offsetY = offsetStart.y + (e.clientY - panStart.y);
          draw();
        }
        updateTooltip(e);
      });

      window.addEventListener('mouseup', () => {
        isPanning = false;
      });

      canvas.addEventListener('wheel', (e) => {
        e.preventDefault();

        const zoomIntensity = 0.0015;
        const delta = -e.deltaY;
        const zoom = Math.exp(delta * zoomIntensity);

        const rect = canvas.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        // Zoom around cursor
        const worldX = (mouseX - offsetX) / scale;
        const worldY = (mouseY - offsetY) / scale;

        scale = clamp(scale * zoom, 0.5, 4);

        offsetX = mouseX - worldX * scale;
        offsetY = mouseY - worldY * scale;

        draw();
      }, { passive: false });

      canvas.addEventListener('mouseleave', () => {
        tooltip.style.display = 'none';
      });

      // Touch support: basic pinch/drag could be added here if needed.

      // --- Controls ---
      resetViewBtn.addEventListener('click', () => {
        scale = 1;
        offsetX = 0;
        offsetY = 0;
        draw();
      });

      toggleLiveBtn.addEventListener('click', () => {
        live = !live;
        toggleLiveBtn.textContent = live ? 'Pause' : 'Resume';
        status.textContent = `Live updates: ${live ? 'ON' : 'OFF'}`;
        status.style.background = live ? 'rgba(77,163,255,0.12)' : 'rgba(255,255,255,0.08)';
      });

      // --- Init ---
      window.addEventListener('resize', resizeCanvas);
      resizeCanvas();
      draw();

      setInterval(tick, 1000);
    })();
  </script>
</body>
</html>
```

