  <script>
    // -----------------------------
    // Data setup
    // -----------------------------
    const symbols = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","AMD","NFLX","ORCL",
      "INTC","IBM","CRM","ADBE","QCOM","AVGO","CSCO","UBER","SHOP","SNOW",
      "PYPL","PLTR","SQ","BA","JPM","BAC","XOM","CVX","KO","PEP"
    ];

    const sectors = ["Tech", "Finance", "Energy", "Consumer", "Industrial"];
    const sectorBySymbol = new Map(symbols.map((s, i) => [s, sectors[i % sectors.length]]));

    const rows = 6; // time buckets visible
    const cols = symbols.length;

    // Each cell: {symbol, row, price, prevPrice, changePct, sector, ts}
    let data = [];
    let live = true;

    function rand(min, max) {
      return min + Math.random() * (max - min);
    }

    function initData() {
      const basePrices = new Map(symbols.map(s => [s, rand(20, 500)]));
      data = [];
      for (let r = 0; r < rows; r++) {
        symbols.forEach((symbol, c) => {
          const base = basePrices.get(symbol);
          const noise = rand(-0.03, 0.03);
          const price = base * (1 + noise);
          const prev = base;
          data.push({
            symbol,
            row: r,
            col: c,
            price,
            prevPrice: prev,
            changePct: ((price - prev) / prev) * 100,
            sector: sectorBySymbol.get(symbol),
            ts: new Date(Date.now() - (rows - 1 - r) * 1000)
          });
        });
      }
    }

    initData();

    // -----------------------------
    // Dimensions / SVG
    // -----------------------------
    const svg = d3.select("#chart");
    const wrap = document.getElementById("chartWrap");
    const tooltip = document.getElementById("tooltip");
    const status = document.getElementById("status");
    const toggleBtn = document.getElementById("toggleStream");
    const resetBtn = document.getElementById("resetView");

    const margin = { top: 30, right: 20, bottom: 40, left: 70 };
    let width = 0, height = 0;
    let cellW = 0, cellH = 0;

    const gRoot = svg.append("g").attr("class", "root");
    const gGrid = gRoot.append("g").attr("class", "grid");
    const gCells = gRoot.append("g").attr("class", "cells");
    const gXAxis = gRoot.append("g").attr("class", "axis x-axis");
    const gYAxis = gRoot.append("g").attr("class", "axis y-axis");

    const color = d3.scaleLinear()
      .domain([-5, 0, 5])
      .range(["#b91c1c", "#f8fafc", "#15803d"])
      .clamp(true);

    const formatPct = d3.format("+.2f");
    const formatPrice = d3.format("$.2f");

    let transform = d3.zoomIdentity;

    function resize() {
      const rect = wrap.getBoundingClientRect();
      width = rect.width;
      height = rect.height;

      svg.attr("viewBox", `0 0 ${width} ${height}`);

      cellW = Math.max(60, (width - margin.left - margin.right) / cols);
      cellH = Math.max(28, (height - margin.top - margin.bottom) / rows);

      render();
    }

    window.addEventListener("resize", resize);

    // -----------------------------
    // Render
    // -----------------------------
    function render() {
      const innerW = cols * cellW;
      const innerH = rows * cellH;

      gRoot.attr("transform", `translate(${margin.left},${margin.top})`);

      // Background grid lines
      const vLines = d3.range(cols + 1);
      const hLines = d3.range(rows + 1);

      gGrid.selectAll("line.v")
        .data(vLines)
        .join("line")
        .attr("class", "grid-line v")
        .attr("x1", d => d * cellW)
        .attr("x2", d => d * cellW)
        .attr("y1", 0)
        .attr("y2", innerH);

      gGrid.selectAll("line.h")
        .data(hLines)
        .join("line")
        .attr("class", "grid-line h")
        .attr("x1", 0)
        .attr("x2", innerW)
        .attr("y1", d => d * cellH)
        .attr("y2", d => d * cellH);

      // Cells
      const cells = gCells.selectAll("g.cell-group")
        .data(data, d => `${d.symbol}-${d.row}`);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "cell-group")
        .on("mousemove", (event, d) => {
          const [mx, my] = d3.pointer(event, wrap);
          tooltip.style.left = `${mx}px`;
          tooltip.style.top = `${my}px`;
          tooltip.style.opacity = 1;
          tooltip.innerHTML = `
            <strong>${d.symbol}</strong> (${d.sector})<br/>
            Price: ${formatPrice(d.price)}<br/>
            Change: ${formatPct(d.changePct)}%<br/>
            Time: ${d.ts.toLocaleTimeString()}
          `;
        })
        .on("mouseleave", () => {
          tooltip.style.opacity = 0;
        });

      cellsEnter.append("rect")
        .attr("class", "cell");

      cellsEnter.append("text")
        .attr("class", "cell-label")
        .attr("text-anchor", "middle")
        .attr("dominant-baseline", "middle")
        .style("fill", "#0f172a")
        .style("font-size", "11px")
        .style("font-weight", "700")
        .style("pointer-events", "none");

      const merged = cellsEnter.merge(cells);

      merged.attr("transform", d => `translate(${d.col * cellW},${d.row * cellH})`);

      merged.select("rect")
        .attr("width", cellW)
        .attr("height", cellH)
        .attr("rx", 6)
        .attr("ry", 6)
        .attr("fill", d => color(d.changePct));

      merged.select("text")
        .attr("x", cellW / 2)
        .attr("y", cellH / 2)
        .text(d => d.symbol);

      cells.exit().remove();

      // Axes labels
      const xLabels = symbols.map((s, i) => ({ label: s, x: i * cellW + cellW / 2 }));
      const yLabels = d3.range(rows).map(r => ({ label: `T-${rows - 1 - r}`, y: r * cellH + cellH / 2 }));

      gXAxis.attr("transform", `translate(0,${innerH + 8})`)
        .call(d3.axisBottom(d3.scalePoint()
          .domain(symbols)
          .range([cellW / 2, innerW - cellW / 2]))
          .tickSize(0))
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

      gYAxis.call(d3.axisLeft(d3.scalePoint()
        .domain(d3.range(rows).map(r => `T-${rows - 1 - r}`))
        .range([cellH / 2, innerH - cellH / 2]))
        .tickSize(0));

      // Apply zoom transform
      gRoot.attr("transform", `translate(${margin.left},${margin.top}) ${transform}`);
    }

    // -----------------------------
    // Zoom / Pan
    // -----------------------------
    const zoom = d3.zoom()
      .scaleExtent([0.7, 6])
      .translateExtent([[0, 0], [5000, 5000]])
      .on("zoom", (event) => {
        transform = event.transform;
        gRoot.attr("transform", `translate(${margin.left},${margin.top}) ${transform}`);
      });

    svg.call(zoom);

    resetBtn.addEventListener("click", () => {
      transform = d3.zoomIdentity;
      svg.transition().duration(250).call(zoom.transform, d3.zoomIdentity);
    });

    // -----------------------------
    // Real-time updates (simulated)
    // -----------------------------
    function updateStream() {
      if (!live) return;

      // Shift rows up and append a new row at bottom
      const nextRow = rows - 1;
      const newTimestamp = new Date();

      // Move existing rows up
      data = data
        .filter(d => d.row < rows - 1)
        .map(d => ({ ...d, row: d.row + 1 }));

      // Generate new bottom row
      symbols.forEach((symbol, c) => {
        const prevCell = data.find(d => d.symbol === symbol && d.row === rows - 2);
        const prevPrice = prevCell ? prevCell.price : rand(20, 500);
        const delta = rand(-0.02, 0.02);
        const price = Math.max(1, prevPrice * (1 + delta));
        data.push({
          symbol,
          row: nextRow,
          col: c,
          price,
          prevPrice,
          changePct: ((price - prevPrice) / prevPrice) * 100,
          sector: sectorBySymbol.get(symbol),
          ts: newTimestamp
        });
      });

      // Recompute colors and rerender
      render();
      status.textContent = `Live updates: on • ${newTimestamp.toLocaleTimeString()}`;
    }

    let interval = setInterval(updateStream, 1200);

    toggleBtn.addEventListener("click", () => {
      live = !live;
      toggleBtn.textContent = live ? "Pause Stream" : "Resume Stream";
      status.textContent = `Live updates: ${live ? "on" : "paused"}`;
    });

    // -----------------------------
    // Initial render
    // -----------------------------
    resize();
  </script>
</body>
</html>
