<script>
(() => {
  const canvas = document.getElementById('heatmap');
  const wrap = document.getElementById('canvasWrap');
  const tooltip = document.getElementById('tooltip');
  const statusEl = document.getElementById('status');
  const resetBtn = document.getElementById('resetBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const sortSelect = document.getElementById('sortSelect');

  const ctx = canvas.getContext('2d');

  // ----- Data -----
  const symbols = [
    'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','NFLX','INTC',
    'ORCL','CRM','ADBE','QCOM','AVGO','IBM','UBER','SHOP','SNOW','PLTR',
    'BABA','BA','JPM','BAC','GS','XOM','CVX','KO','PEP','WMT',
    'COST','TMO','LLY','UNH','PFE','MRNA','DIS','NKE','MCD','SBUX'
  ];

  let stocks = symbols.map((sym, i) => {
    const base = 50 + Math.random() * 450;
    return {
      symbol: sym,
      price: base,
      prevClose: base * (0.98 + Math.random() * 0.04),
      volume: Math.floor(1e6 + Math.random() * 9e6),
      sector: ['Tech','Finance','Energy','Retail','Health'][i % 5],
      lastUpdate: Date.now()
    };
  });

  let paused = false;
  let sortMode = 'symbol';

  // ----- View transform -----
  const view = {
    scale: 1,
    offsetX: 20,
    offsetY: 20
  };

  function resetView() {
    view.scale = 1;
    view.offsetX = 20;
    view.offsetY = 20;
    render();
  }

  // ----- Canvas sizing -----
  let dpr = Math.max(1, window.devicePixelRatio || 1);
  function resize() {
    const rect = wrap.getBoundingClientRect();
    dpr = Math.max(1, window.devicePixelRatio || 1);
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    render();
  }
  window.addEventListener('resize', resize);

  // ----- Helpers -----
  function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
  }

  function pctChange(s) {
    return ((s.price - s.prevClose) / s.prevClose) * 100;
  }

  function colorForChange(change) {
    // Map change to a red-yellow-green gradient.
    const maxAbs = 6; // percent
    const t = clamp((change + maxAbs) / (2 * maxAbs), 0, 1); // 0..1
    // Interpolate red -> yellow -> green
    const stops = [
      { p: 0.0, c: [239, 68, 68] },   // red
      { p: 0.5, c: [250, 204, 21] },   // yellow
      { p: 1.0, c: [34, 197, 94] }     // green
    ];

    let a = stops[0], b = stops[2];
    if (t <= 0.5) { a = stops[0]; b = stops[1]; }
    else { a = stops[1]; b = stops[2]; }

    const localT = (t - a.p) / (b.p - a.p);
    const rgb = a.c.map((v, i) => Math.round(v + (b.c[i] - v) * localT));
    return `rgb(${rgb[0]},${rgb[1]},${rgb[2]})`;
  }

  function textColorForBg(change) {
    return Math.abs(change) > 2.5 ? '#08111f' : '#ffffff';
  }

  function sortStocks() {
    const arr = [...stocks];
    if (sortMode === 'change') arr.sort((a, b) => pctChange(b) - pctChange(a));
    else if (sortMode === 'price') arr.sort((a, b) => b.price - a.price);
    else arr.sort((a, b) => a.symbol.localeCompare(b.symbol));
    return arr;
  }

  // ----- Layout -----
  function getGridLayout(count) {
    const cols = Math.ceil(Math.sqrt(count));
    const rows = Math.ceil(count / cols);
    return { cols, rows };
  }

  function worldToScreen(x, y) {
    return {
      x: x * view.scale + view.offsetX,
      y: y * view.scale + view.offsetY
    };
  }

  function screenToWorld(x, y) {
    return {
      x: (x - view.offsetX) / view.scale,
      y: (y - view.offsetY) / view.scale
    };
  }

  // ----- Rendering -----
  function render() {
    const w = canvas.width;
    const h = canvas.height;
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, w, h);

    // Background
    ctx.fillStyle = '#0b1020';
    ctx.fillRect(0, 0, w, h);

    const data = sortStocks();
    const { cols, rows } = getGridLayout(data.length);

    const cellW = 150;
    const cellH = 92;
    const gap = 10;
    const totalW = cols * cellW + (cols - 1) * gap;
    const totalH = rows * cellH + (rows - 1) * gap;

    // Apply view transform
    ctx.save();
    ctx.scale(dpr * view.scale, dpr * view.scale);
    ctx.translate(view.offsetX / view.scale, view.offsetY / view.scale);

    // Grid background
    ctx.strokeStyle = 'rgba(255,255,255,0.06)';
    ctx.lineWidth = 1 / view.scale;

    for (let i = 0; i < data.length; i++) {
      const r = Math.floor(i / cols);
      const c = i % cols;
      const x = c * (cellW + gap);
      const y = r * (cellH + gap);
      const s = data[i];
      const change = pctChange(s);
      const bg = colorForChange(change);

      // Cell
      roundRect(ctx, x, y, cellW, cellH, 12 / view.scale);
      ctx.fillStyle = bg;
      ctx.fill();

      // subtle overlay
      ctx.fillStyle = 'rgba(255,255,255,0.06)';
      ctx.fillRect(x, y, cellW, 18 / view.scale);

      // Text
      ctx.fillStyle = textColorForBg(change);
      ctx.font = `${12 / view.scale}px Inter, system-ui, sans-serif`;
      ctx.fillText(s.symbol, x + 10 / view.scale, y + 13 / view.scale);

      ctx.font = `bold ${18 / view.scale}px Inter, system-ui, sans-serif`;
      ctx.fillText(`$${s.price.toFixed(2)}`, x + 10 / view.scale, y + 44 / view.scale);

      ctx.font = `${12 / view.scale}px Inter, system-ui, sans-serif`;
      const ch = change >= 0 ? `+${change.toFixed(2)}%` : `${change.toFixed(2)}%`;
      ctx.fillText(ch, x + 10 / view.scale, y + 66 / view.scale);

      // volume
      ctx.fillStyle = 'rgba(255,255,255,0.75)';
      ctx.font = `${10 / view.scale}px Inter, system-ui, sans-serif`;
      ctx.fillText(`Vol ${formatCompact(s.volume)}`, x + 10 / view.scale, y + 82 / view.scale);

      // border
      ctx.strokeStyle = 'rgba(255,255,255,0.12)';
      ctx.stroke();
    }

    // Grid labels
    ctx.restore();

    // Draw viewport info
    statusEl.textContent = `${paused ? 'Paused' : 'Live'} • ${data.length} symbols • Zoom ${view.scale.toFixed(2)}x`;
  }

  function roundRect(ctx, x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);
    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  function formatCompact(n) {
    if (n >= 1e9) return (n / 1e9).toFixed(1) + 'B';
    if (n >= 1e6) return (n / 1e6).toFixed(1) + 'M';
    if (n >= 1e3) return (n / 1e3).toFixed(1) + 'K';
    return String(n);
  }

  // ----- Hit testing -----
  function hitTest(clientX, clientY) {
    const rect = canvas.getBoundingClientRect();
    const x = (clientX - rect.left) * dpr;
    const y = (clientY - rect.top) * dpr;

    const world = screenToWorld(x / dpr, y / dpr);
    const data = sortStocks();
    const { cols } = getGridLayout(data.length);

    const cellW = 150;
    const cellH = 92;
    const gap = 10;

    for (let i = 0; i < data.length; i++) {
      const r = Math.floor(i / cols);
      const c = i % cols;
      const cx = c * (cellW + gap);
      const cy = r * (cellH + gap);
      if (world.x >= cx && world.x <= cx + cellW && world.y >= cy && world.y <= cy + cellH) {
        return { stock: data[i], x: clientX, y: clientY };
      }
    }
    return null;
  }

  // ----- Tooltip -----
  function showTooltip(hit) {
    const s = hit.stock;
    const ch = pctChange(s);
    const cls = ch > 0 ? 'up' : ch < 0 ? 'down' : 'flat';
    tooltip.innerHTML = `
      <div class="sym">${s.symbol}</div>
      <div>Price: <strong>$${s.price.toFixed(2)}</strong></div>
      <div>Change: <span class="${cls}">${ch >= 0 ? '+' : ''}${ch.toFixed(2)}%</span></div>
      <div>Prev Close: $${s.prevClose.toFixed(2)}</div>
      <div>Volume: ${formatCompact(s.volume)}</div>
      <div>Sector: ${s.sector}</div>
    `;
    tooltip.style.left = hit.x + 'px';
    tooltip.style.top = hit.y + 'px';
    tooltip.style.display = 'block';
  }

  function hideTooltip() {
    tooltip.style.display = 'none';
  }

  // ----- Interaction: pan/zoom -----
  let dragging = false;
  let dragStart = null;

  wrap.addEventListener('pointerdown', (e) => {
    dragging = true;
    dragStart = {
      x: e.clientX,
      y: e.clientY,
      ox: view.offsetX,
      oy: view.offsetY
    };
    wrap.setPointerCapture(e.pointerId);
  });

  wrap.addEventListener('pointermove', (e) => {
    if (dragging && dragStart) {
      view.offsetX = dragStart.ox + (e.clientX - dragStart.x);
      view.offsetY = dragStart.oy + (e.clientY - dragStart.y);
      render();
      return;
    }

    const hit = hitTest(e.clientX, e.clientY);
    if (hit) showTooltip(hit);
    else hideTooltip();
  });

  wrap.addEventListener('pointerup', (e) => {
    dragging = false;
    dragStart = null;
    try { wrap.releasePointerCapture(e.pointerId); } catch {}
  });

  wrap.addEventListener('pointerleave', hideTooltip);

  wrap.addEventListener('wheel', (e) => {
    e.preventDefault();

    const rect = canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const zoomFactor = Math.exp(-e.deltaY * 0.001);
    const nextScale = clamp(view.scale * zoomFactor, 0.5, 3.5);

    // Zoom around cursor
    const worldX = (mouseX - view.offsetX) / view.scale;
    const worldY = (mouseY - view.offsetY) / view.scale;

    view.scale = nextScale;
    view.offsetX = mouseX - worldX * view.scale;
    view.offsetY = mouseY - worldY * view.scale;

    render();
  }, { passive: false });

  // ----- Live updates -----
  function tick() {
    if (!paused) {
      // Update a subset of stocks each tick
      const updates = Math.max(1, Math.floor(stocks.length * 0.25));
      for (let i = 0; i < updates; i++) {
        const idx = Math.floor(Math.random() * stocks.length);
        const s = stocks[idx];
        const drift = (Math.random() - 0.5) * 0.02; // +/- 1%
        const shock = (Math.random() < 0.08 ? (Math.random() - 0.5) * 0.06 : 0);
        const next = Math.max(1, s.price * (1 + drift + shock));
        s.price = next;
        s.volume += Math.floor(Math.random() * 5000);
        s.lastUpdate = Date.now();
      }
      render();
    }
    requestAnimationFrame(() => {});
  }

  setInterval(tick, 900);

  // ----- Controls -----
  resetBtn.addEventListener('click', resetView);

  pauseBtn.addEventListener('click', () => {
    paused = !paused;
    pauseBtn.textContent = paused ? 'Resume Updates' : 'Pause Updates';
    render();
  });

  sortSelect.addEventListener('change', () => {
    sortMode = sortSelect.value;
    render();
  });

  // ----- Initial render -----
  resize();
  render();

})();
</script>
</body>
</html>
```

## How it works

- **Canvas-based rendering**: Efficient for many cells and frequent updates.
- **Real-time updates**: A timer simulates changing stock prices and volumes.
- **Zoom/pan**:
  - Drag to pan
  - Mouse wheel to zoom around cursor
- **Hover tooltips**: Shows symbol, price, change, volume, sector.
- **Sorting**: By symbol, price, or percent change.

## To connect to real data

Replace the simulated `tick()` logic with a WebSocket message handler, e.g.:

```js
const ws = new WebSocket("wss://your-feed.example.com");
ws.onmessage = (event) => {
  const updates = JSON.parse(event.data);
  for (const u of updates) {
    const s = stocks.find(x => x.symbol === u.symbol);
    if (s) {
      s.price = u.price;
      s.volume = u.volume ?? s.volume;
      s.lastUpdate = Date.now();
    }
  }
  render();
};
```

