      font-weight: 600;
      margin-bottom: 4px;
    }

    .tooltip .up { color: #4dff9a; }
    .tooltip .down { color: #ff6b6b; }
  </style>
</head>
<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <span class="badge" id="status">Live</span>
      <span class="hint">Wheel = zoom • Drag = pan • Hover = details</span>
      <div class="spacer"></div>
      <span class="hint" id="stats">0 symbols</span>
    </div>

    <div class="stage" id="stage">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    (() => {
      const canvas = document.getElementById('heatmap');
      const stage = document.getElementById('stage');
      const tooltip = document.getElementById('tooltip');
      const stats = document.getElementById('stats');

      const ctx = canvas.getContext('2d');

      // --- Data model ---
      const symbols = [
        'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','NFLX','INTC',
        'ORCL','CRM','ADBE','QCOM','AVGO','IBM','CSCO','UBER','SHOP','SNOW',
        'BA','JPM','BAC','WMT','COST','DIS','XOM','CVX','PFE','MRNA',
        'KO','PEP','NKE','MCD','V','MA','PYPL','SQ','SPOT','PANW'
      ];

      const rows = 8;
      const cols = Math.ceil(symbols.length / rows);

      const cells = symbols.map((symbol, i) => ({
        symbol,
        price: 50 + Math.random() * 450,
        prevPrice: null,
        changePct: 0,
        row: Math.floor(i / cols),
        col: i % cols
      }));

      // --- View transform ---
      const view = {
        scale: 1,
        offsetX: 0,
        offsetY: 0
      };

      // --- Interaction state ---
      let dpr = Math.max(1, window.devicePixelRatio || 1);
      let width = 0;
      let height = 0;
      let dragging = false;
      let dragStart = { x: 0, y: 0 };
      let offsetStart = { x: 0, y: 0 };
      let hoverCell = null;
      let needsRender = true;

      function resize() {
        const rect = stage.getBoundingClientRect();
        width = rect.width;
        height = rect.height;
        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        canvas.style.width = width + 'px';
        canvas.style.height = height + 'px';
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        needsRender = true;
      }

      window.addEventListener('resize', () => {
        dpr = Math.max(1, window.devicePixelRatio || 1);
        resize();
      });

      resize();

      // --- Simulated real-time updates ---
      function tickPrices() {
        for (const cell of cells) {
          cell.prevPrice = cell.price;
          const drift = (Math.random() - 0.5) * 2.2;
          const shock = Math.random() < 0.03 ? (Math.random() - 0.5) * 12 : 0;
          cell.price = Math.max(1, cell.price + drift + shock);
          cell.changePct = cell.prevPrice ? ((cell.price - cell.prevPrice) / cell.prevPrice) * 100 : 0;
        }
        needsRender = true;
      }

      setInterval(tickPrices, 700);

      // --- Color scale ---
      function lerp(a, b, t) {
        return a + (b - a) * t;
      }

      function clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      function colorForChange(pct) {
        // Map negative -> red, positive -> green, near zero -> dark neutral
        const maxAbs = 5;
        const t = clamp(Math.abs(pct) / maxAbs, 0, 1);

        if (pct >= 0) {
          const r = Math.round(lerp(20, 40, t));
          const g = Math.round(lerp(40, 220, t));
          const b = Math.round(lerp(30, 90, t));
          return `rgb(${r},${g},${b})`;
        } else {
          const r = Math.round(lerp(40, 220, t));
          const g = Math.round(lerp(40, 70, t));
          const b = Math.round(lerp(30, 60, t));
          return `rgb(${r},${g},${b})`;
        }
      }

      function textColorForBg(pct) {
        return Math.abs(pct) > 2.5 ? '#ffffff' : '#d7def7';
      }

      // --- Coordinate helpers ---
      function screenToWorld(x, y) {
        return {
          x: (x - view.offsetX) / view.scale,
          y: (y - view.offsetY) / view.scale
        };
      }

      function worldToScreen(x, y) {
        return {
          x: x * view.scale + view.offsetX,
          y: y * view.scale + view.offsetY
        };
      }

      function getGridMetrics() {
        const margin = 24;
        const headerH = 18;
        const usableW = width - margin * 2;
        const usableH = height - margin * 2 - headerH;
        const cellW = usableW / cols;
        const cellH = usableH / rows;
        return { margin, headerH, cellW, cellH };
      }

      function cellBounds(cell) {
        const { margin, headerH, cellW, cellH } = getGridMetrics();
        const x = margin + cell.col * cellW;
        const y = margin + headerH + cell.row * cellH;
        return { x, y, w: cellW, h: cellH };
      }

      function hitTest(screenX, screenY) {
        const world = screenToWorld(screenX, screenY);
        for (const cell of cells) {
          const b = cellBounds(cell);
          if (world.x >= b.x && world.x <= b.x + b.w && world.y >= b.y && world.y <= b.y + b.h) {
            return cell;
          }
        }
        return null;
      }

      // --- Rendering ---
      function draw() {
        if (!needsRender) return;
        needsRender = false;

        ctx.clearRect(0, 0, width, height);

        // Background
        const bg = ctx.createLinearGradient(0, 0, 0, height);
        bg.addColorStop(0, '#0b1020');
        bg.addColorStop(1, '#090d18');
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, width, height);

        // Apply view transform
        ctx.save();
        ctx.translate(view.offsetX, view.offsetY);
        ctx.scale(view.scale, view.scale);

        const { margin, headerH, cellW, cellH } = getGridMetrics();

        // Grid labels
        ctx.fillStyle = 'rgba(255,255,255,0.7)';
        ctx.font = '12px Inter, system-ui, sans-serif';
        ctx.fillText('Market movers', margin, margin + 12);

        // Cells
        for (const cell of cells) {
          const x = margin + cell.col * cellW;
          const y = margin + headerH + cell.row * cellH;
          const pad = 4;

          ctx.fillStyle = colorForChange(cell.changePct);
          ctx.fillRect(x + pad, y + pad, cellW - pad * 2, cellH - pad * 2);

          // Border
          ctx.strokeStyle = 'rgba(255,255,255,0.08)';
          ctx.strokeRect(x + pad, y + pad, cellW - pad * 2, cellH - pad * 2);

          // Highlight hover
          if (hoverCell === cell) {
            ctx.strokeStyle = 'rgba(255,255,255,0.95)';
            ctx.lineWidth = 2;
            ctx.strokeRect(x + pad + 1, y + pad + 1, cellW - pad * 2 - 2, cellH - pad * 2 - 2);
            ctx.lineWidth = 1;
          }

          // Text
          ctx.fillStyle = textColorForBg(cell.changePct);
          ctx.font = '600 14px Inter, system-ui, sans-serif';
          ctx.fillText(cell.symbol, x + 12, y + 22);

          ctx.font = '12px Inter, system-ui, sans-serif';
          ctx.fillText(`$${cell.price.toFixed(2)}`, x + 12, y + 42);

          const pct = cell.changePct >= 0 ? `+${cell.changePct.toFixed(2)}%` : `${cell.changePct.toFixed(2)}%`;
          ctx.fillText(pct, x + 12, y + 60);
        }

        // Grid lines
        ctx.strokeStyle = 'rgba(255,255,255,0.06)';
        for (let r = 0; r <= rows; r++) {
          const y = margin + headerH + r * cellH;
          ctx.beginPath();
          ctx.moveTo(margin, y);
          ctx.lineTo(margin + cols * cellW, y);
          ctx.stroke();
        }
        for (let c = 0; c <= cols; c++) {
          const x = margin + c * cellW;
          ctx.beginPath();
          ctx.moveTo(x, margin + headerH);
          ctx.lineTo(x, margin + headerH + rows * cellH);
          ctx.stroke();
        }

        ctx.restore();

        stats.textContent = `${cells.length} symbols`;

        requestAnimationFrame(draw);
      }

      requestAnimationFrame(draw);

      // --- Zoom / pan interactions ---
      canvas.addEventListener('mousedown', (e) => {
        dragging = true;
        canvas.classList.add('dragging');
        dragStart = { x: e.clientX, y: e.clientY };
        offsetStart = { x: view.offsetX, y: view.offsetY };
      });

      window.addEventListener('mousemove', (e) => {
        if (dragging) {
          view.offsetX = offsetStart.x + (e.clientX - dragStart.x);
          view.offsetY = offsetStart.y + (e.clientY - dragStart.y);
          needsRender = true;
        }

        const cell = hitTest(e.clientX, e.clientY);
        hoverCell = cell;

        if (cell) {
          const pct = cell.changePct >= 0 ? `+${cell.changePct.toFixed(2)}%` : `${cell.changePct.toFixed(2)}%`;
          tooltip.style.display = 'block';
          tooltip.innerHTML = `
            <div class="name">${cell.symbol}</div>
            <div>Price: <strong>$${cell.price.toFixed(2)}</strong></div>
            <div class="${cell.changePct >= 0 ? 'up' : 'down'}">Change: ${pct}</div>
          `;
          tooltip.style.left = e.clientX + 'px';
          tooltip.style.top = e.clientY + 'px';
        } else {
          tooltip.style.display = 'none';
        }

        needsRender = true;
      });

      window.addEventListener('mouseup', () => {
        dragging = false;
        canvas.classList.remove('dragging');
      });

      canvas.addEventListener('wheel', (e) => {
        e.preventDefault();

        const zoomFactor = Math.exp(-e.deltaY * 0.0015);
        const oldScale = view.scale;
        const newScale = clamp(oldScale * zoomFactor, 0.6, 3.5);

        const rect = canvas.getBoundingClientRect();
        const mouseX = e.clientX - rect.left;
        const mouseY = e.clientY - rect.top;

        // Zoom around cursor
        const worldBefore = {
          x: (mouseX - view.offsetX) / oldScale,
          y: (mouseY - view.offsetY) / oldScale
        };

        view.scale = newScale;
        view.offsetX = mouseX - worldBefore.x * newScale;
        view.offsetY = mouseY - worldBefore.y * newScale;

        needsRender = true;
      }, { passive: false });

      // Optional: double-click to reset view
      canvas.addEventListener('dblclick', () => {
        view.scale = 1;
        view.offsetX = 0;
        view.offsetY = 0;
        needsRender = true;
      });

      // Initial render
      needsRender = true;
    })();
  </script>
</body>
