      "KO","PEP","WMT","COST","TGT","HD","LOW","NKE",
      "DIS","CMCSA","T","VZ","UBER","LYFT","SNAP","SHOP"
    ];

    const data = tickers.slice(0, cols * rows).map((t, i) => ({
      ticker: t,
      price: 50 + Math.random() * 450,
      prevPrice: null,
      changePct: 0,
      x: i % cols,
      y: Math.floor(i / cols)
    }));

    const margin = { top: 20, right: 20, bottom: 20, left: 20 };
    let cellW = 100;
    let cellH = 80;

    const g = svg.append("g").attr("class", "viewport");

    const zoom = d3.zoom()
      .scaleExtent([0.7, 8])
      .on("zoom", (event) => {
        g.attr("transform", event.transform);
      });

    svg.call(zoom);

    function colorForChange(pct) {
      const scale = d3.scaleLinear()
        .domain([-5, -1, 0, 1, 5])
        .range(["#d73027", "#f46d43", "#f7f7f7", "#66bd63", "#1a9850"])
        .clamp(true);
      return scale(pct);
