        .attr("class", "ticker-label")
        .attr("text-anchor", "middle");

      cellsEnter.append("text")
        .attr("class", "price-label")
        .attr("text-anchor", "middle");

      cells.merge(cellsEnter).each(function(d) {
        const x = d.x * cellW + margin.left;
        const y = d.y * cellH + margin.top;

        d3.select(this).select("rect")
          .transition()
          .duration(250)
          .attr("x", x + 4)
          .attr("y", y + 4)
          .attr("width", cellW - 8)
          .attr("height", cellH - 8)
          .attr("fill", colorForChange(d.changePct));

        d3.select(this).select(".ticker-label")
          .attr("x", x + cellW / 2)
          .attr("y", y + cellH / 2 - 4)
          .text(d.ticker);

        d3.select(this).select(".price-label")
          .attr("x", x + cellW / 2)
          .attr("y", y + cellH / 2 + 14)
          .text(`$${d.price.toFixed(2)}`);
      });

      cells.exit().remove();
