    function updatePrices() {
      data.forEach(d => {
        d.prevPrice = d.price;
        const drift = (Math.random() - 0.5) * 4;
        d.price = Math.max(1, d.price + drift);
        d.changePct = d.prevPrice ? ((d.price - d.prevPrice) / d.prevPrice) * 100 : 0;
      });
      layout();
