      const base = 50 + Math.random() * 450;
      return {
        symbol,
        price: base,
        prevPrice: base,
        changePct: 0,
        volume: Math.floor(1e6 + Math.random() * 9e6),
        sector: ["Tech", "Finance", "Consumer", "Energy", "Media"][i % 5],
        pinned: false
      };
    });

    // Layout: grid of tiles
    const cols = 8;
    const tileGap = 10;
    const tileW = 140;
    const tileH = 90;

    const gRoot = svg.append("g").attr("class", "root");
    const gGrid = gRoot.append("g").attr("class", "grid");

    // Zoom behavior
    const zoom = d3.zoom()
      .scaleExtent([0.5, 6])
      .on("zoom", (event) => {
        gRoot.attr("transform", event.transform);
      });

    svg.call(zoom);

    function resetZoom() {
      svg.transition().duration(300).call(zoom.transform, d3.zoomIdentity);
    }

    document.getElementById("resetZoom").addEventListener("click", resetZoom);

    let live = true;
    document.getElementById("toggleLive").addEventListener("click", () => {
      live = !live;
      document.getElementById("toggleLive").textContent = live ? "Pause Live Updates" : "Resume Live Updates";
      statusEl.textContent = `Live updates: ${live ? "on" : "off"}`;
    });

    // Color scale: red -> green based on percent change
    const color = d3.scaleLinear()
      .domain([-5, -2, 0, 2, 5])
      .range(["#d73027", "#f46d43", "#fee08b", "#66bd63", "#1a9850"])
      .clamp(true);

    function formatPrice(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatPct(v) {
      return `${v >= 0 ? "+" : ""}${v.toFixed(2)}%`;
    }

    function layout() {
      const w = width();
      const h = height();
      svg.attr("viewBox", `0 0 ${w} ${h}`);

      const totalW = cols * tileW + (cols - 1) * tileGap;
      const rows = Math.ceil(data.length / cols);
      const totalH = rows * tileH + (rows - 1) * tileGap;

      const offsetX = Math.max(20, (w - totalW) / 2);
      const offsetY = Math.max(20, (h - totalH) / 2);

      const cells = gGrid.selectAll(".cell-group")
        .data(data, d => d.symbol);

      const cellsEnter = cells.enter()
        .append("g")
        .attr("class", "cell-group")
        .style("cursor", "pointer")
