        .on("mousemove", (event, d) => {
          if (!d.pinned) moveTooltip(event);
        })
        .on("mouseleave", (event, d) => {
          if (!d.pinned) hideTooltip();
        })
        .on("click", (event, d) => {
          d.pinned = !d.pinned;
          updatePinnedStyles();
          if (d.pinned) {
            showTooltip(event, d, true);
          } else {
            hideTooltip();
          }
          event.stopPropagation();
        });

      cellsEnter.append("rect")
        .attr("class", "cell")
        .attr("width", tileW)
        .attr("height", tileH)
        .attr("rx", 8)
        .attr("ry", 8);

      cellsEnter.append("text")
        .attr("class", "cell-label")
        .attr("y", 34);

      cellsEnter.append("text")
        .attr("class", "cell-sub")
        .attr("y", 58);

      cells.merge(cellsEnter)
        .attr("transform", (d, i) => {
          const col = i % cols;
          const row = Math.floor(i / cols);
          const x = offsetX + col * (tileW + tileGap);
          const y = offsetY + row * (tileH + tileGap);
          return `translate(${x},${y})`;
        })
        .each(function(d) {
          const g = d3.select(this);
          g.select("rect")
            .attr("fill", color(d.changePct))
            .classed("pinned", d.pinned);

          g.select(".cell-label")
            .text(d.symbol)
            .attr("x", tileW / 2);

          g.select(".cell-sub")
            .text(`${formatPrice(d.price)}  ${formatPct(d.changePct)}`)
            .attr("x", tileW / 2);
        });

      cells.exit().remove();
      updatePinnedStyles();
    }

    function updatePinnedStyles() {
      gGrid.selectAll(".cell-group rect")
        .classed("pinned", d => d.pinned);
    }

    function showTooltip(event, d, pinned = false) {
      tooltip.innerHTML = `
        <strong>${d.symbol}</strong>
        Price: ${formatPrice(d.price)}<br/>
        Change: ${formatPct(d.changePct)}<br/>
        Volume: ${d.volume.toLocaleString()}<br/>
        Sector: ${d.sector}<br/>
        ${pinned ? "<em>Pinned</em>" : ""}
      `;
      tooltip.style.opacity = 1;
      moveTooltip(event);
    }

    function moveTooltip(event) {
      const rect = main.getBoundingClientRect();
      const x = event.clientX - rect.left;
      const y = event.clientY - rect.top;
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.style.opacity = 0;
    }

    // Simulated real-time updates
    function updatePrices() {
      if (!live) return;

      data.forEach(d => {
        d.prevPrice = d.price;
        const drift = (Math.random() - 0.5) * 2.2; // random walk
        d.price = Math.max(1, d.price + drift);
        d.changePct = ((d.price - d.prevPrice) / d.prevPrice) * 100;

        // occasional larger move
        if (Math.random() < 0.08) {
          d.price = Math.max(1, d.price + (Math.random() - 0.5) * 10);
          d.changePct = ((d.price - d.prevPrice) / d.prevPrice) * 100;
        }

        d.volume = Math.max(1000, d.volume + Math.floor((Math.random() - 0.5) * 50000));
      });

      layout();
    }

    // Click background to unpin all
    svg.on("click", () => {
      data.forEach(d => d.pinned = false);
      hideTooltip();
      updatePinnedStyles();
    });

    // Resize handling
    window.addEventListener("resize", () => layout());

    // Initial render
    layout();

    // Update every second
    setInterval(updatePrices, 1000);

    // Optional: smooth hover highlight
    gGrid.selectAll(".cell-group").on("mouseenter.highlight", function() {
      d3.select(this).raise();
    });
  </script>
</body>
</html>
