  const updates = JSON.parse(event.data); // [{symbol, price, volume}, ...]
  updates.forEach(u => {
    const d = data.find(x => x.symbol === u.symbol);
    if (d) {
      d.prevPrice = d.price;
      d.price = u.price;
      d.changePct = ((d.price - d.prevPrice) / d.prevPrice) * 100;
      d.volume = u.volume ?? d.volume;
    }
  });
  layout();
};
```

