      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    // -----------------------------
    // Data setup
    // -----------------------------
    const tickers = [
      "AAPL","MSFT","NVDA","AMZN","GOOGL","META","TSLA","AMD","NFLX","INTC",
      "ORCL","CRM","ADBE","QCOM","AVGO","IBM","CSCO","UBER","SHOP","SNOW",
      "PLTR","SQ","PYPL","BABA","DIS","PEP","KO","MCD","NKE","BA",
      "XOM","CVX","JPM","BAC","WMT","COST","T","V","MA","UNH"
    ];

    const state = {
      items: [],
      scale: 1,
      panX: 20,
      panY: 20,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startPanX: 0,
      startPanY: 0,
      cellSize: 120,
      gap: 10,
      cols: 5,
      lastUpdate: Date.now()
    };

    const viewport = document.getElementById("viewport");
    const heatmap = document.getElementById("heatmap");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");
    const resetBtn = document.getElementById("resetBtn");

    // Generate initial mock data
    function initData() {
      state.items = tickers.map((ticker, i) => {
        const base = 50 + Math.random() * 450;
        const changePct = (Math.random() - 0.5) * 10;
        return {
          ticker,
          price: base,
          prevPrice: base,
          changePct,
          volume: Math.floor(1e6 + Math.random() * 2e7),
          sector: ["Tech", "Finance", "Consumer", "Energy", "Health"][i % 5]
        };
      });
    }

    // -----------------------------
    // Layout
    // -----------------------------
    function layoutHeatmap() {
      const width = viewport.clientWidth;
      const height = viewport.clientHeight;

      // Responsive columns based on viewport width
      const targetCell = 140;
      const cols = Math.max(2, Math.floor(width / targetCell));
      state.cols = cols;

      const cellW = Math.max(90, Math.min(160, Math.floor((width - 40 - (cols - 1) * state.gap) / cols)));
      const cellH = Math.max(80, Math.floor(cellW * 0.78));
      state.cellSize = Math.min(cellW, cellH + 20);

      const rows = Math.ceil(state.items.length / cols);
      const totalW = cols * cellW + (cols - 1) * state.gap;
      const totalH = rows * cellH + (rows - 1) * state.gap;

      heatmap.style.width = totalW + "px";
      heatmap.style.height = totalH + "px";

      state.items.forEach((item, idx) => {
        const col = idx % cols;
        const row = Math.floor(idx / cols);
        const x = col * (cellW + state.gap);
        const y = row * (cellH + state.gap);

        item.x = x;
        item.y = y;
        item.w = cellW;
        item.h = cellH;
      });

      render();
    }

    // -----------------------------
    // Color mapping
    // -----------------------------
    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(changePct) {
      // Map -10%..+10% to red -> neutral -> green
      const t = clamp((changePct + 10) / 20, 0, 1);

      // Interpolate from red (#d90429) to neutral (#2b2d42) to green (#2a9d8f)
      const red = [217, 4, 41];
      const neutral = [43, 45, 66];
      const green = [42, 157, 143];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = neutral; localT = t / 0.5;
      } else {
        c1 = neutral; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = c1.map((v, i) => Math.round(v + (c2[i] - v) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function textColorForBg(changePct) {
      return Math.abs(changePct) > 4 ? "#ffffff" : "#f3f6ff";
    }

    // -----------------------------
    // Rendering
    // -----------------------------
    function render() {
      heatmap.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.scale})`;

      // Build cells once, then update styles
      if (!heatmap.children.length) {
        const frag = document.createDocumentFragment();

        state.items.forEach((item, idx) => {
          const cell = document.createElement("div");
          cell.className = "cell";
          cell.dataset.index = idx;

          cell.innerHTML = `
            <div class="ticker"></div>
            <div class="price"></div>
            <div class="change"></div>
          `;

          cell.addEventListener("mouseenter", (e) => showTooltip(e, item));
          cell.addEventListener("mousemove", (e) => moveTooltip(e));
          cell.addEventListener("mouseleave", hideTooltip);

          frag.appendChild(cell);
        });

        heatmap.appendChild(frag);
      }

      [...heatmap.children].forEach((cell, idx) => {
        const item = state.items[idx];
        cell.style.left = item.x + "px";
        cell.style.top = item.y + "px";
        cell.style.width = item.w + "px";
        cell.style.height = item.h + "px";
        cell.style.background = colorForChange(item.changePct);
        cell.style.color = textColorForBg(item.changePct);

        cell.querySelector(".ticker").textContent = item.ticker;
        cell.querySelector(".price").textContent = `$${item.price.toFixed(2)}`;
        cell.querySelector(".change").textContent =
          `${item.changePct >= 0 ? "+" : ""}${item.changePct.toFixed(2)}%`;
      });
    }

    // -----------------------------
    // Real-time updates (simulated)
    // -----------------------------
    function updatePrices() {
      state.items.forEach(item => {
        const drift = (Math.random() - 0.5) * 2.2; // random walk
        const next = Math.max(1, item.price + drift);
        item.prevPrice = item.price;
        item.price = next;
        item.changePct = ((item.price - item.prevPrice) / item.prevPrice) * 100 + item.changePct * 0.92;
        item.volume += Math.floor(Math.random() * 5000);
      });

      render();
      statusEl.textContent = `Streaming: connected • Updated ${new Date().toLocaleTimeString()}`;
    }

    // -----------------------------
    // Tooltip
    // -----------------------------
    function showTooltip(e, item) {
      tooltip.classList.add("visible");
      tooltip.innerHTML = `
        <strong>${item.ticker}</strong><br/>
        Sector: ${item.sector}<br/>
        Price: $${item.price.toFixed(2)}<br/>
        Change: ${item.changePct >= 0 ? "+" : ""}${item.changePct.toFixed(2)}%<br/>
        Volume: ${item.volume.toLocaleString()}
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      const pad = 16;
      const x = Math.min(window.innerWidth - 220, e.clientX + pad);
      const y = Math.min(window.innerHeight - 120, e.clientY + pad);
      tooltip.style.left = x + "px";
      tooltip.style.top = y + "px";
    }

    function hideTooltip() {
      tooltip.classList.remove("visible");
    }

    // -----------------------------
    // Zoom / Pan
    // -----------------------------
    function applyTransform() {
      render();
    }

    viewport.addEventListener("mousedown", (e) => {
      state.dragging = true;
      viewport.classList.add("dragging");
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.dragging) return;
      const dx = e.clientX - state.dragStartX;
      const dy = e.clientY - state.dragStartY;
      state.panX = state.startPanX + dx;
      state.panY = state.startPanY + dy;
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const newScale = clamp(state.scale * zoomFactor, 0.5, 3);

      // Zoom around cursor
      const worldX = (mouseX - state.panX) / state.scale;
      const worldY = (mouseY - state.panY) / state.scale;

      state.scale = newScale;
      state.panX = mouseX - worldX * state.scale;
      state.panY = mouseY - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      state.scale = 1;
      state.panX = 20;
      state.panY = 20;
      applyTransform();
    });

    // -----------------------------
    // Resize handling
    // -----------------------------
    window.addEventListener("resize", () => {
      layoutHeatmap();
    });

    // -----------------------------
    // Boot
    // -----------------------------
    initData();
    layoutHeatmap();

    // Simulate real-time updates
    setInterval(updatePrices, 1000);

    // Optional: smoother animation loop for future extensions
    // requestAnimationFrame(function tick() { render(); requestAnimationFrame(tick); });
  </script>
</body>
</html>
