      'KO','PEP','MCD','NKE','DIS','BA','CAT','GE','T','VZ',
      'SPY','QQQ','IWM','DIA','XLK','XLF','XLE','XLV','XLY','XLP',
      'SNOW','PLTR','CRWD','PANW','NET','DDOG','ZS','OKTA','TEAM','MDB',
      'BABA','TSM','ASML','SAP','SONY','SHOP','RBLX','PYPL','F','GM'
    ];

    function randomBetween(min, max) {
      return min + Math.random() * (max - min);
    }

    function initCells() {
      const total = state.gridCols * state.gridRows;
      state.cells = Array.from({ length: total }, (_, i) => {
        const symbol = symbols[i % symbols.length] + (i >= symbols.length ? `.${Math.floor(i / symbols.length)}` : '');
        const price = randomBetween(10, 500);
        const change = randomBetween(-5, 5);
        return {
          symbol,
          price,
          change,
          volume: Math.floor(randomBetween(100000, 50000000)),
          x: 0,
          y: 0,
          w: 0,
          h: 0
        };
      });
    }

    function resize() {
      state.dpr = Math.max(1, window.devicePixelRatio || 1);
      state.width = window.innerWidth;
      state.height = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      canvas.style.width = state.width + 'px';
      canvas.style.height = state.height + 'px';
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      render();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // Map -10%..+10% to red->dark->green
      const t = clamp((change + 10) / 20, 0, 1);
      if (t < 0.5) {
        const k = t / 0.5;
        return lerpColor([185, 28, 28], [17, 24, 39], k);
      } else {
        const k = (t - 0.5) / 0.5;
        return lerpColor([17, 24, 39], [34, 197, 94], k);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const bl = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r},${g},${bl})`;
    }

    function layoutCells() {
      const padding = 20;
      const gap = state.cellGap;
      const cols = state.gridCols;
      const rows = state.gridRows;

      const baseCellW = (state.width - padding * 2 - gap * (cols - 1)) / cols;
      const baseCellH = (state.height - padding * 2 - gap * (rows - 1)) / rows;

      const cellW = baseCellW * state.zoom;
      const cellH = baseCellH * state.zoom;

      const totalW = cols * cellW + (cols - 1) * gap * state.zoom;
      const totalH = rows * cellH + (rows - 1) * gap * state.zoom;

      const startX = (state.width - totalW) / 2 + state.panX;
      const startY = (state.height - totalH) / 2 + state.panY;

      state.cells.forEach((cell, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        cell.x = startX + col * (cellW + gap * state.zoom);
        cell.y = startY + row * (cellH + gap * state.zoom);
        cell.w = cellW;
        cell.h = cellH;
      });
    }

    function drawRoundedRect(x, y, w, h, r) {
      const radius = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    function render() {
      layoutCells();

      ctx.clearRect(0, 0, state.width, state.height);

      // Background
      const bg = ctx.createLinearGradient(0, 0, 0, state.height);
      bg.addColorStop(0, '#0b1020');
      bg.addColorStop(1, '#050816');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, state.width, state.height);

      // Cells
      for (const cell of state.cells) {
        const visible = cell.x + cell.w > 0 && cell.y + cell.h > 0 && cell.x < state.width && cell.y < state.height;
        if (!visible) continue;

        const isHover = state.hoverCell === cell;
        const fill = colorForChange(cell.change);

        ctx.save();
        ctx.shadowColor = 'rgba(0,0,0,0.25)';
        ctx.shadowBlur = isHover ? 18 : 8;
        ctx.shadowOffsetY = 2;

        drawRoundedRect(cell.x, cell.y, cell.w, cell.h, 12);
        ctx.fillStyle = fill;
        ctx.fill();

        ctx.lineWidth = isHover ? 2 : 1;
        ctx.strokeStyle = isHover ? 'rgba(255,255,255,0.9)' : 'rgba(255,255,255,0.08)';
        ctx.stroke();
        ctx.restore();

        // Text
        const minDim = Math.min(cell.w, cell.h);
        if (minDim > 42) {
          const pad = 10;
          ctx.fillStyle = 'rgba(255,255,255,0.95)';
          ctx.font = `600 ${Math.max(11, Math.min(18, minDim * 0.18))}px system-ui, sans-serif`;
          ctx.fillText(cell.symbol, cell.x + pad, cell.y + pad + 14);

          ctx.font = `500 ${Math.max(10, Math.min(14, minDim * 0.14))}px system-ui, sans-serif`;
          ctx.fillStyle = 'rgba(255,255,255,0.85)';
          ctx.fillText(`$${cell.price.toFixed(2)}`, cell.x + pad, cell.y + pad + 34);

          const changeText = `${cell.change >= 0 ? '+' : ''}${cell.change.toFixed(2)}%`;
          ctx.fillStyle = cell.change >= 0 ? '#bbf7d0' : '#fecaca';
          ctx.fillText(changeText, cell.x + pad, cell.y + pad + 52);
        }
      }

      // Hover tooltip
      if (state.hoverCell) {
        tooltip.style.display = 'block';
        tooltip.innerHTML = `
          <div><strong>${state.hoverCell.symbol}</strong></div>
          <div>Price: $${state.hoverCell.price.toFixed(2)}</div>
          <div>Change: ${state.hoverCell.change >= 0 ? '+' : ''}${state.hoverCell.change.toFixed(2)}%</div>
          <div>Volume: ${state.hoverCell.volume.toLocaleString()}</div>
        `;
      } else {
        tooltip.style.display = 'none';
      }
    }

    function hitTest(x, y) {
      for (const cell of state.cells) {
        if (x >= cell.x && x <= cell.x + cell.w && y >= cell.y && y <= cell.y + cell.h) {
          return cell;
        }
      }
      return null;
    }

    function screenToCanvas(e) {
      const rect = canvas.getBoundingClientRect();
      return {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
      };
    }

    canvas.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastMouseX = e.clientX;
      state.lastMouseY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
    });

    window.addEventListener('mousemove', (e) => {
      const pos = screenToCanvas(e);

      if (state.dragging) {
        const dx = e.clientX - state.lastMouseX;
        const dy = e.clientY - state.lastMouseY;
        state.panX += dx;
        state.panY += dy;
        state.lastMouseX = e.clientX;
        state.lastMouseY = e.clientY;
        render();
      }

      state.hoverCell = hitTest(pos.x, pos.y);
      if (state.hoverCell) {
        tooltip.style.left = `${e.clientX}px`;
        tooltip.style.top = `${e.clientY}px`;
      }
      render();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const oldZoom = state.zoom;
      const newZoom = clamp(state.zoom * zoomFactor, state.minZoom, state.maxZoom);

      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Zoom around cursor
      const worldX = (mouseX - state.width / 2 - state.panX) / oldZoom;
      const worldY = (mouseY - state.height / 2 - state.panY) / oldZoom;

      state.zoom = newZoom;
      state.panX = mouseX - state.width / 2 - worldX * newZoom;
      state.panY = mouseY - state.height / 2 - worldY * newZoom;

      render();
    }, { passive: false });

    // Simulated real-time updates
    function updateData() {
      for (const cell of state.cells) {
        const drift = randomBetween(-0.35, 0.35);
        const shock = Math.random() < 0.08 ? randomBetween(-1.5, 1.5) : 0;
        cell.change = clamp(cell.change + drift + shock, -12, 12);

        // Price follows change loosely
        cell.price = Math.max(0.5, cell.price * (1 + (drift + shock) / 100));

        // Volume changes too
        cell.volume = Math.max(1000, Math.floor(cell.volume * randomBetween(0.95, 1.05)));
      }

      render();
    }

    // Optional: replace with real WebSocket feed
    // const ws = new WebSocket('wss://your-feed.example.com');
    // ws.onmessage = (event) => {
    //   const updates = JSON.parse(event.data);
    //   // update matching cells here
    //   render();
    // };

    initCells();
    resize();
    render();

    window.addEventListener('resize', resize);
    setInterval(updateData, 1000);
  </script>
</body>
</html>
```

