</head>
<body>
  <div class="app">
    <header>
      <div class="toolbar">
        <h1>Stock Price Heatmap</h1>
        <div class="legend">
          <span>Loss</span>
          <div class="legend-bar"></div>
          <span>Gain</span>
        </div>
        <div class="spacer"></div>
        <button class="btn" id="resetBtn">Reset View</button>
        <button class="btn" id="toggleFeedBtn">Pause Feed</button>
        <div class="status" id="status">Connected: simulated feed</div>
      </div>
    </header>

    <div class="canvas-wrap" id="wrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>

    <footer>
      Mouse wheel to zoom, drag to pan, hover for details. Real-time updates are simulated client-side.
    </footer>
  </div>

  <script>
    (() => {
      const canvas = document.getElementById('heatmap');
      const wrap = document.getElementById('wrap');
      const tooltip = document.getElementById('tooltip');
      const status = document.getElementById('status');
      const resetBtn = document.getElementById('resetBtn');
      const toggleFeedBtn = document.getElementById('toggleFeedBtn');

      const ctx = canvas.getContext('2d');

      // --- Data model ---
      const rows = 18;
      const cols = 28;
      const symbols = Array.from({ length: rows * cols }, (_, i) => ({
        symbol: `STK${String(i + 1).padStart(3, '0')}`,
        price: 50 + Math.random() * 150,
        prev: null,
        changePct: 0,
        volume: Math.floor(100000 + Math.random() * 900000),
      }));

      // --- View transform ---
      const view = {
        scale: 1,
        offsetX: 20,
        offsetY: 20,
        minScale: 0.5,
        maxScale: 4,
      };

      const cell = {
        w: 90,
        h: 52,
        gap: 8,
      };

      let dpr = Math.max(1, window.devicePixelRatio || 1);
      let width = 0;
      let height = 0;

      let isDragging = false;
      let dragStart = { x: 0, y: 0 };
      let dragOrigin = { x: 0, y: 0 };
      let feedRunning = true;
      let hoveredIndex = -1;

      function resize() {
        dpr = Math.max(1, window.devicePixelRatio || 1);
        width = wrap.clientWidth;
        height = wrap.clientHeight;
        canvas.width = Math.floor(width * dpr);
        canvas.height = Math.floor(height * dpr);
        canvas.style.width = width + 'px';
        canvas.style.height = height + 'px';
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
        draw();
      }

      function resetView() {
        view.scale = 1;
        view.offsetX = 20;
        view.offsetY = 20;
        draw();
      }

      function clamp(v, min, max) {
        return Math.max(min, Math.min(max, v));
      }

      function priceToColor(changePct) {
        // Map -10%..+10% to red->green
        const t = clamp((changePct + 10) / 20, 0, 1);
        const r = Math.round(215 * (1 - t) + 26 * t);
        const g = Math.round(48 * (1 - t) + 152 * t);
        const b = Math.round(39 * (1 - t) + 80 * t);
        return `rgb(${r}, ${g}, ${b})`;
      }

      function textColorForBg(changePct) {
        return Math.abs(changePct) > 4 ? '#ffffff' : '#0b1020';
      }

      function getGridSize() {
        return {
          totalW: cols * (cell.w + cell.gap) - cell.gap,
          totalH: rows * (cell.h + cell.gap) - cell.gap,
        };
      }

      function screenToWorld(x, y) {
        return {
          x: (x - view.offsetX) / view.scale,
          y: (y - view.offsetY) / view.scale,
        };
      }

      function worldToScreen(x, y) {
        return {
          x: x * view.scale + view.offsetX,
          y: y * view.scale + view.offsetY,
        };
      }

      function getCellAt(mx, my) {
        const p = screenToWorld(mx, my);
        const stepX = cell.w + cell.gap;
        const stepY = cell.h + cell.gap;

        const col = Math.floor(p.x / stepX);
        const row = Math.floor(p.y / stepY);

        if (col < 0 || col >= cols || row < 0 || row >= rows) return -1;

        const localX = p.x - col * stepX;
        const localY = p.y - row * stepY;

        if (localX > cell.w || localY > cell.h) return -1;

        return row * cols + col;
      }

      function drawGridBackground() {
        ctx.save();
        ctx.fillStyle = '#0b1020';
        ctx.fillRect(0, 0, width, height);

        // subtle grid
        ctx.strokeStyle = 'rgba(255,255,255,0.04)';
        ctx.lineWidth = 1;
        const spacing = 40 * view.scale;
        for (let x = view.offsetX % spacing; x < width; x += spacing) {
          ctx.beginPath();
          ctx.moveTo(x, 0);
          ctx.lineTo(x, height);
          ctx.stroke();
        }
        for (let y = view.offsetY % spacing; y < height; y += spacing) {
          ctx.beginPath();
          ctx.moveTo(0, y);
          ctx.lineTo(width, y);
          ctx.stroke();
        }
        ctx.restore();
      }

      function draw() {
        drawGridBackground();

        const stepX = (cell.w + cell.gap) * view.scale;
        const stepY = (cell.h + cell.gap) * view.scale;
        const cw = cell.w * view.scale;
        const ch = cell.h * view.scale;

        hoveredIndex = -1;

        for (let row = 0; row < rows; row++) {
          for (let col = 0; col < cols; col++) {
            const i = row * cols + col;
            const item = symbols[i];

            const x = view.offsetX + col * stepX;
            const y = view.offsetY + row * stepY;

            if (x + cw < 0 || y + ch < 0 || x > width || y > height) continue;

            const isHover = i === hoveredIndex;
            ctx.save();
            ctx.fillStyle = priceToColor(item.changePct);
            ctx.strokeStyle = isHover ? 'rgba(255,255,255,0.9)' : 'rgba(255,255,255,0.08)';
            ctx.lineWidth = isHover ? 2 : 1;

            roundRect(ctx, x, y, cw, ch, 10 * view.scale);
            ctx.fill();
            ctx.stroke();

            // label
            ctx.fillStyle = textColorForBg(item.changePct);
            ctx.font = `${Math.max(10, 12 * view.scale)}px Inter, sans-serif`;
            ctx.textAlign = 'left';
            ctx.textBaseline = 'top';

            const pad = 8 * view.scale;
            ctx.fillText(item.symbol, x + pad, y + pad);

            ctx.font = `${Math.max(9, 11 * view.scale)}px Inter, sans-serif`;
            const priceText = `$${item.price.toFixed(2)}`;
            const pctText = `${item.changePct >= 0 ? '+' : ''}${item.changePct.toFixed(2)}%`;

            ctx.fillText(priceText, x + pad, y + pad + 16 * view.scale);
            ctx.fillText(pctText, x + pad, y + pad + 32 * view.scale);

            ctx.restore();
          }
        }
      }

      function roundRect(ctx, x, y, w, h, r) {
        const radius = Math.min(r, w / 2, h / 2);
        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.arcTo(x + w, y, x + w, y + h, radius);
        ctx.arcTo(x + w, y + h, x, y + h, radius);
        ctx.arcTo(x, y + h, x, y, radius);
        ctx.arcTo(x, y, x + w, y, radius);
        ctx.closePath();
      }

      function updateTooltip(mx, my, index) {
        if (index < 0) {
          tooltip.style.display = 'none';
          return;
        }

        const item = symbols[index];
        tooltip.style.display = 'block';
        tooltip.style.left = mx + 'px';
        tooltip.style.top = my + 'px';
        tooltip.innerHTML = `
          <div class="symbol">${item.symbol}</div>
          <div>Price: <strong>$${item.price.toFixed(2)}</strong></div>
          <div>Change: <strong style="color:${item.changePct >= 0 ? '#7CFC98' : '#ff7b7b'}">
            ${item.changePct >= 0 ? '+' : ''}${item.changePct.toFixed(2)}%
          </strong></div>
          <div>Volume: ${item.volume.toLocaleString()}</div>
        `;
      }

      function onPointerMove(e) {
        const rect = canvas.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;

        if (isDragging) {
          view.offsetX = dragOrigin.x + (mx - dragStart.x);
          view.offsetY = dragOrigin.y + (my - dragStart.y);
          draw();
          return;
        }

        const idx = getCellAt(mx, my);
        hoveredIndex = idx;
        draw();
        updateTooltip(mx, my, idx);
      }

      function onPointerDown(e) {
        isDragging = true;
        canvas.classList.add('dragging');
        const rect = canvas.getBoundingClientRect();
        dragStart = { x: e.clientX - rect.left, y: e.clientY - rect.top };
        dragOrigin = { x: view.offsetX, y: view.offsetY };
      }

      function onPointerUp() {
        isDragging = false;
        canvas.classList.remove('dragging');
      }

      function onWheel(e) {
        e.preventDefault();

        const rect = canvas.getBoundingClientRect();
        const mx = e.clientX - rect.left;
        const my = e.clientY - rect.top;

        const zoomFactor = Math.exp(-e.deltaY * 0.0015);
        const newScale = clamp(view.scale * zoomFactor, view.minScale, view.maxScale);

        // Zoom around cursor
        const world = screenToWorld(mx, my);
        view.scale = newScale;
        view.offsetX = mx - world.x * view.scale;
        view.offsetY = my - world.y * view.scale;

        draw();
      }

      function simulateFeedTick() {
        if (!feedRunning) return;

        // Update a subset of cells each tick
        const updates = 8 + Math.floor(Math.random() * 10);
        for (let k = 0; k < updates; k++) {
          const i = Math.floor(Math.random() * symbols.length);
          const item = symbols[i];

          item.prev = item.price;
          const drift = (Math.random() - 0.5) * 2.2;
          item.price = Math.max(1, item.price + drift);
          item.changePct = ((item.price - 100) / 100) * 10 + (Math.random() - 0.5) * 1.5;
          item.volume = Math.max(0, item.volume + Math.floor((Math.random() - 0.5) * 5000));
        }

        status.textContent = `Connected: simulated feed | ${new Date().toLocaleTimeString()}`;
        draw();
      }

      resetBtn.addEventListener('click', resetView);

      toggleFeedBtn.addEventListener('click', () => {
        feedRunning = !feedRunning;
        toggleFeedBtn.textContent = feedRunning ? 'Pause Feed' : 'Resume Feed';
        status.textContent = feedRunning ? 'Connected: simulated feed' : 'Feed paused';
      });

      canvas.addEventListener('pointermove', onPointerMove);
      canvas.addEventListener('pointerdown', onPointerDown);
      window.addEventListener('pointerup', onPointerUp);
      canvas.addEventListener('wheel', onWheel, { passive: false });

      window.addEventListener('resize', resize);

      // Initial render
      resize();

      // Simulated real-time updates
      setInterval(simulateFeedTick, 500);

      // Optional: replace with real WebSocket feed
      // const ws = new WebSocket('wss://your-feed.example.com');
      // ws.onmessage = (event) => {
      //   const data = JSON.parse(event.data);
      //   // Update symbols based on incoming data
      //   draw();
      // };
    })();
  </script>
</body>
</html>
