      user-select: none;
      pointer-events: none;
    }

    .tooltip {
      position: absolute;
      display: none;
      background: rgba(15, 23, 42, 0.95);
      border: 1px solid rgba(148, 163, 184, 0.25);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      color: #fff;
      pointer-events: none;
      transform: translate(12px, 12px);
      white-space: nowrap;
      box-shadow: 0 10px 30px rgba(0,0,0,0.3);
    }

    .legend {
      position: absolute;
      bottom: 12px;
      left: 12px;
      background: rgba(15, 23, 42, 0.85);
      border: 1px solid rgba(148, 163, 184, 0.2);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 12px;
      backdrop-filter: blur(8px);
      user-select: none;
    }

    .legend-bar {
      width: 220px;
      height: 12px;
      border-radius: 999px;
      margin-top: 6px;
      background: linear-gradient(90deg, #b91c1c 0%, #ef4444 25%, #111827 50%, #22c55e 75%, #15803d 100%);
      border: 1px solid rgba(255,255,255,0.12);
    }

    .controls {
      position: absolute;
      top: 12px;
      right: 12px;
      background: rgba(15, 23, 42, 0.85);
      border: 1px solid rgba(148, 163, 184, 0.2);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 13px;
      line-height: 1.5;
      backdrop-filter: blur(8px);
      user-select: none;
    }

    .controls button {
      margin-right: 6px;
      margin-top: 6px;
      background: #1f2937;
      color: #e5e7eb;
      border: 1px solid #374151;
      border-radius: 8px;
      padding: 6px 10px;
      cursor: pointer;
    }

    .controls button:hover {
      background: #374151;
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="heatmap"></canvas>

    <div class="hud">
      <strong>Stock Heatmap</strong><br />
      Wheel: zoom<br />
      Drag: pan<br />
      Hover: details
    </div>

    <div class="controls">
      <div><strong>View</strong></div>
      <button id="resetBtn">Reset</button>
      <button id="zoomInBtn">Zoom +</button>
      <button id="zoomOutBtn">Zoom -</button>
      <div id="status" style="margin-top:8px; opacity:0.85;">Connecting...</div>
    </div>

    <div class="legend">
      <div><strong>Change %</strong></div>
      <div class="legend-bar"></div>
      <div style="display:flex; justify-content:space-between; margin-top:4px;">
        <span>-5%</span><span>0%</span><span>+5%</span>
      </div>
    </div>

    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');

    const state = {
      dpr: window.devicePixelRatio || 1,
      width: 0,
      height: 0,
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      lastMouseX: 0,
      lastMouseY: 0,
      hoverCell: null,
      cells: [],
      rows: 0,
      cols: 0
    };

    // Sample stock universe
    const tickers = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AVGO','AMD','NFLX',
      'ORCL','CRM','INTC','QCOM','IBM','ADBE','CSCO','TXN','MU','AMAT',
      'JPM','BAC','WFC','C','GS','MS','AXP','BLK','V','MA',
      'XOM','CVX','COP','SLB','EOG','OXY','PXD','PSX','KMI','HAL',
      'LLY','JNJ','PFE','MRK','ABBV','TMO','UNH','BMY','GILD','AMGN',
      'KO','PEP','MCD','SBUX','COST','WMT','TGT','HD','LOW','NKE'
    ];

    function resize() {
      state.dpr = window.devicePixelRatio || 1;
      state.width = window.innerWidth;
      state.height = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      canvas.style.width = state.width + 'px';
      canvas.style.height = state.height + 'px';
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      layoutCells();
      draw();
    }

    function layoutCells() {
      const padding = 20;
      const availableW = state.width - padding * 2;
      const availableH = state.height - padding * 2;

      // Choose a grid close to square
      state.cols = Math.ceil(Math.sqrt(tickers.length));
      state.rows = Math.ceil(tickers.length / state.cols);

      const cellW = availableW / state.cols;
      const cellH = availableH / state.rows;

      state.cells = tickers.map((ticker, i) => {
        const row = Math.floor(i / state.cols);
        const col = i % state.cols;
        return {
          ticker,
          row,
          col,
          x: padding + col * cellW,
          y: padding + row * cellH,
          w: cellW - 4,
          h: cellH - 4,
          price: 100 + Math.random() * 200,
          prevPrice: 100 + Math.random() * 200,
          change: 0
        };
      });
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // change is in percent, roughly -5 to +5
      const c = clamp(change, -5, 5);
      if (c < 0) {
        const t = (c + 5) / 5; // 0..1
        // red -> dark
        return `rgb(${Math.round(185 * t + 60 * (1 - t))}, ${Math.round(28 * t + 20 * (1 - t))}, ${Math.round(28 * t + 40 * (1 - t))})`;
      } else {
        const t = c / 5; // 0..1
        // dark -> green
        return `rgb(${Math.round(17 * (1 - t) + 34 * t)}, ${Math.round(24 * (1 - t) + 197 * t)}, ${Math.round(39 * (1 - t) + 94 * t)})`;
      }
    }

    function drawRoundedRect(x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function draw() {
      ctx.clearRect(0, 0, state.width, state.height);

      // Background
      const bg = ctx.createLinearGradient(0, 0, 0, state.height);
      bg.addColorStop(0, '#0b1020');
      bg.addColorStop(1, '#050816');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, state.width, state.height);

      ctx.save();
      ctx.translate(state.panX, state.panY);
      ctx.scale(state.zoom, state.zoom);

      for (const cell of state.cells) {
        const isHover = state.hoverCell && state.hoverCell.ticker === cell.ticker;

        // Cell background
        ctx.fillStyle = colorForChange(cell.change);
        drawRoundedRect(cell.x, cell.y, cell.w, cell.h, 10);
        ctx.fill();

        // Border
        ctx.lineWidth = isHover ? 3 : 1;
        ctx.strokeStyle = isHover ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.12)';
        ctx.stroke();

        // Text
        ctx.fillStyle = '#fff';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        const nameSize = Math.max(10, Math.min(18, cell.h * 0.22));
        const priceSize = Math.max(9, Math.min(14, cell.h * 0.16));
        const changeSize = Math.max(9, Math.min(13, cell.h * 0.14));

        ctx.font = `700 ${nameSize}px system-ui, sans-serif`;
        ctx.fillText(cell.ticker, cell.x + cell.w / 2, cell.y + cell.h * 0.35);

        ctx.font = `600 ${priceSize}px system-ui, sans-serif`;
        ctx.fillText(`$${cell.price.toFixed(2)}`, cell.x + cell.w / 2, cell.y + cell.h * 0.56);

        const sign = cell.change >= 0 ? '+' : '';
        ctx.font = `600 ${changeSize}px system-ui, sans-serif`;
        ctx.fillText(`${sign}${cell.change.toFixed(2)}%`, cell.x + cell.w / 2, cell.y + cell.h * 0.75);
      }

      ctx.restore();
    }

    function screenToWorld(x, y) {
      return {
        x: (x - state.panX) / state.zoom,
        y: (y - state.panY) / state.zoom
      };
    }

    function hitTest(mx, my) {
      const p = screenToWorld(mx, my);
      return state.cells.find(cell =>
        p.x >= cell.x && p.x <= cell.x + cell.w &&
        p.y >= cell.y && p.y <= cell.y + cell.h
      ) || null;
    }

    function updateTooltip(cell, mx, my) {
      if (!cell) {
        tooltip.style.display = 'none';
        return;
      }
      tooltip.style.display = 'block';
      tooltip.style.left = mx + 'px';
      tooltip.style.top = my + 'px';
      const sign = cell.change >= 0 ? '+' : '';
      tooltip.innerHTML = `
        <strong>${cell.ticker}</strong><br/>
        Price: $${cell.price.toFixed(2)}<br/>
        Change: ${sign}${cell.change.toFixed(2)}%
      `;
    }

    function simulateRealtimeUpdate() {
      for (const cell of state.cells) {
        cell.prevPrice = cell.price;
        const drift = (Math.random() - 0.5) * 1.2;
        cell.price = Math.max(1, cell.price + drift);
        cell.change = ((cell.price - cell.prevPrice) / cell.prevPrice) * 100;
      }
      statusEl.textContent = `Live updates: ${new Date().toLocaleTimeString()}`;
      draw();
    }

    // Mouse interactions
    canvas.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastMouseX = e.clientX;
      state.lastMouseY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
    });

    window.addEventListener('mousemove', (e) => {
      if (state.dragging) {
        const dx = e.clientX - state.lastMouseX;
        const dy = e.clientY - state.lastMouseY;
        state.panX += dx;
        state.panY += dy;
        state.lastMouseX = e.clientX;
        state.lastMouseY = e.clientY;
        draw();
      }

      const cell = hitTest(e.clientX, e.clientY);
      state.hoverCell = cell;
      updateTooltip(cell, e.clientX, e.clientY);
      draw();
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newZoom = clamp(state.zoom * zoomFactor, 0.5, 4);

      // Zoom around mouse position
      const mx = e.clientX;
      const my = e.clientY;
      const worldBefore = screenToWorld(mx, my);

      state.zoom = newZoom;

      state.panX = mx - worldBefore.x * state.zoom;
      state.panY = my - worldBefore.y * state.zoom;

      draw();
    }, { passive: false });

    // Touch support: basic pan
    let touchStartDist = 0;
    let touchStartZoom = 1;
    let touchStartPan = { x: 0, y: 0 };
    let touchStartMid = { x: 0, y: 0 };

    canvas.addEventListener('touchstart', (e) => {
      if (e.touches.length === 1) {
        state.dragging = true;
        state.lastMouseX = e.touches[0].clientX;
        state.lastMouseY = e.touches[0].clientY;
      } else if (e.touches.length === 2) {
        state.dragging = false;
        const [a, b] = e.touches;
        touchStartDist = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
        touchStartZoom = state.zoom;
        touchStartPan = { x: state.panX, y: state.panY };
        touchStartMid = {
          x: (a.clientX + b.clientX) / 2,
          y: (a.clientY + b.clientY) / 2
        };
      }
    }, { passive: true });

    canvas.addEventListener('touchmove', (e) => {
      if (e.touches.length === 1 && state.dragging) {
        const t = e.touches[0];
        const dx = t.clientX - state.lastMouseX;
        const dy = t.clientY - state.lastMouseY;
        state.panX += dx;
        state.panY += dy;
        state.lastMouseX = t.clientX;
        state.lastMouseY = t.clientY;
        draw();
      } else if (e.touches.length === 2) {
        const [a, b] = e.touches;
        const dist = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
        const scale = dist / touchStartDist;
        const newZoom = clamp(touchStartZoom * scale, 0.5, 4);

        const mid = {
          x: (a.clientX + b.clientX) / 2,
          y: (a.clientY + b.clientY) / 2
        };

        const worldBefore = {
          x: (touchStartMid.x - touchStartPan.x) / touchStartZoom,
          y: (touchStartMid.y - touchStartPan.y) / touchStartZoom
        };

        state.zoom = newZoom;
        state.panX = mid.x - worldBefore.x * state.zoom;
        state.panY = mid.y - worldBefore.y * state.zoom;
        draw();
      }
    }, { passive: true });

    // Buttons
    document.getElementById('resetBtn').addEventListener('click', () => {
      state.zoom = 1;
      state.panX = 0;
      state.panY = 0;
      draw();
    });

    document.getElementById('zoomInBtn').addEventListener('click', () => {
      state.zoom = clamp(state.zoom * 1.2, 0.5, 4);
      draw();
    });

    document.getElementById('zoomOutBtn').addEventListener('click', () => {
      state.zoom = clamp(state.zoom / 1.2, 0.5, 4);
      draw();
    });

    // Simulated "real-time" feed
    statusEl.textContent = 'Live updates: connected';
    setInterval(simulateRealtimeUpdate, 1000);

    window.addEventListener('resize', resize);
    resize();
  </script>
</body>
</html>
```

