  <script>
    const svg = document.getElementById("svg");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const zoomInBtn = document.getElementById("zoomIn");
    const zoomOutBtn = document.getElementById("zoomOut");
    const resetViewBtn = document.getElementById("resetView");

    // --- Data setup ---
    const stocks = [
      "AAPL", "MSFT", "NVDA", "AMZN", "GOOGL",
      "META", "TSLA", "AMD", "NFLX", "INTC",
      "ORCL", "CRM", "UBER", "SHOP", "ADBE"
    ];

    const timeBuckets = 40;
    const cellSize = 28;
    const labelWidth = 70;
    const labelHeight = 28;

    // Each row = stock, each column = time bucket
    // value = percent return for that bucket
    const data = stocks.map(() =>
      Array.from({ length: timeBuckets }, () => randomReturn())
    );

    function randomReturn() {
      // Simulated price change in percent
      return (Math.random() - 0.5) * 0.12; // roughly -6% to +6%
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatPct(v) {
      return `${(v * 100).toFixed(2)}%`;
    }

    // --- View transform state ---
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    let isDragging = false;
    let dragStart = { x: 0, y: 0 };
    let offsetStart = { x: 0, y: 0 };

    function resetView() {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      render();
    }

    function applyTransform() {
      const g = document.getElementById("heatmapGroup");
      if (!g) return;
      g.setAttribute(
        "transform",
        `translate(${offsetX}, ${offsetY}) scale(${scale})`
      );
    }

    // --- Color scale ---
    function colorForValue(v) {
      // v is return in decimal, e.g. 0.02 = +2%
      // Map around 0 with red-white-green
      const maxAbs = 0.06; // 6%
      const t = clamp((v + maxAbs) / (2 * maxAbs), 0, 1);

      // Interpolate red -> white -> green
      const red = [215, 48, 39];
      const white = [247, 247, 247];
      const green = [26, 152, 80];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = white; localT = t / 0.5;
      } else {
        c1 = white; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = c1.map((a, i) => Math.round(a + (c2[i] - a) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    // --- Rendering ---
    function render() {
      const width = labelWidth + timeBuckets * cellSize + 40;
      const height = labelHeight + stocks.length * cellSize + 40;

      svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
      svg.innerHTML = "";

      const ns = "http://www.w3.org/2000/svg";

      // Background
      const bg = document.createElementNS(ns, "rect");
      bg.setAttribute("x", 0);
      bg.setAttribute("y", 0);
      bg.setAttribute("width", width);
      bg.setAttribute("height", height);
      bg.setAttribute("fill", "transparent");
      svg.appendChild(bg);

      const g = document.createElementNS(ns, "g");
      g.setAttribute("id", "heatmapGroup");
      svg.appendChild(g);

      // Axis labels
      stocks.forEach((stock, row) => {
        const text = document.createElementNS(ns, "text");
        text.setAttribute("x", 10);
        text.setAttribute("y", labelHeight + row * cellSize + cellSize * 0.7);
        text.setAttribute("class", "axis-label");
        text.textContent = stock;
        g.appendChild(text);
      });

      for (let col = 0; col < timeBuckets; col++) {
        const text = document.createElementNS(ns, "text");
        text.setAttribute("x", labelWidth + col * cellSize + cellSize * 0.15);
        text.setAttribute("y", 18);
        text.setAttribute("class", "axis-label");
        text.textContent = col;
        g.appendChild(text);
      }

      // Cells
      stocks.forEach((stock, row) => {
        data[row].forEach((value, col) => {
          const rect = document.createElementNS(ns, "rect");
          rect.setAttribute("x", labelWidth + col * cellSize);
          rect.setAttribute("y", labelHeight + row * cellSize);
          rect.setAttribute("width", cellSize);
          rect.setAttribute("height", cellSize);
          rect.setAttribute("rx", 3);
          rect.setAttribute("ry", 3);
          rect.setAttribute("class", "cell");
          rect.setAttribute("fill", colorForValue(value));

          rect.dataset.stock = stock;
          rect.dataset.row = row;
          rect.dataset.col = col;
          rect.dataset.value = value;

          rect.addEventListener("mousemove", onCellHover);
          rect.addEventListener("mouseleave", hideTooltip);

          g.appendChild(rect);
        });
      });

      applyTransform();
    }

    function onCellHover(e) {
      const rect = e.target;
      const stock = rect.dataset.stock;
      const row = rect.dataset.row;
      const col = rect.dataset.col;
      const value = parseFloat(rect.dataset.value);

      tooltip.innerHTML = `
        <strong>${stock}</strong><br/>
        Bucket: ${col}<br/>
        Return: ${formatPct(value)}<br/>
        Row: ${row}
      `;

      tooltip.classList.add("visible");
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
    }

    function hideTooltip() {
      tooltip.classList.remove("visible");
    }

    // --- Zoom / pan interactions ---
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const delta = -e.deltaY;
      const zoomFactor = delta > 0 ? 1.08 : 0.92;

      const rect = svg.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const oldScale = scale;
      scale = clamp(scale * zoomFactor, 0.6, 4);

      // Zoom around mouse position
      const worldX = (mouseX - offsetX) / oldScale;
      const worldY = (mouseY - offsetY) / oldScale;

      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      render();
    }, { passive: false });

    viewport.addEventListener("mousedown", (e) => {
      isDragging = true;
      viewport.classList.add("dragging");
      dragStart = { x: e.clientX, y: e.clientY };
      offsetStart = { x: offsetX, y: offsetY };
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      offsetX = offsetStart.x + (e.clientX - dragStart.x);
      offsetY = offsetStart.y + (e.clientY - dragStart.y);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      viewport.classList.remove("dragging");
    });

    zoomInBtn.addEventListener("click", () => {
      scale = clamp(scale * 1.2, 0.6, 4);
      render();
    });

    zoomOutBtn.addEventListener("click", () => {
      scale = clamp(scale / 1.2, 0.6, 4);
      render();
    });

    resetViewBtn.addEventListener("click", resetView);

    // --- Simulated real-time updates ---
    function updateLiveData() {
      // Shift left and append new values
      for (let row = 0; row < stocks.length; row++) {
        data[row].shift();
        data[row].push(randomReturn());
      }

      statusEl.textContent = `Live updates: on • ${new Date().toLocaleTimeString()}`;
      render();
    }

    // Initial render
    render();

    // Update every second
    setInterval(updateLiveData, 1000);

    // Hide tooltip on scroll/resize
    window.addEventListener("resize", () => {
      render();
    });
  </script>
</body>
</html>
```

