      border-radius: 8px;
      font-size: 12px;
      line-height: 1.4;
      transform: translate(10px, 10px);
      display: none;
      white-space: nowrap;
      z-index: 3;
    }
  </style>
</head>
<body>
  <div id="app">
    <div id="toolbar">
      <button id="resetBtn">Reset View</button>
      <button id="pauseBtn">Pause</button>
      <span>Wheel: zoom | Drag: pan | Hover: inspect</span>
      <div id="status">Connecting...</div>
    </div>
    <div id="viewport">
      <canvas id="heatmap"></canvas>
      <div id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const viewport = document.getElementById('viewport');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');
    const pauseBtn = document.getElementById('pauseBtn');

    // ----- Demo data -----
    const stocks = [
      'AAPL', 'MSFT', 'NVDA', 'AMZN', 'GOOGL',
      'META', 'TSLA', 'AMD', 'NFLX', 'INTC',
      'ORCL', 'CRM', 'UBER', 'SHOP', 'ADBE'
    ];

    const timeBuckets = 60; // columns
    const rows = stocks.length;

    // Each cell stores a price change percentage
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: timeBuckets }, () => (Math.random() - 0.5) * 4)
    );

    // ----- View state -----
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;
    let isDragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let dragOffsetX = 0;
    let dragOffsetY = 0;
    let paused = false;

    // ----- Canvas sizing -----
    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = viewport.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      render();
    }

    window.addEventListener('resize', resizeCanvas);

    // ----- Color mapping -----
    function valueToColor(v) {
      // v in percent change, roughly [-5, 5]
      const clamped = Math.max(-5, Math.min(5, v));
      const t = (clamped + 5) / 10; // 0..1
      // red -> neutral -> green
      const r = Math.round(255 * (1 - t));
      const g = Math.round(255 * t);
      const b = 80;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function valueToTextColor(v) {
      return Math.abs(v) > 2.5 ? '#ffffff' : '#0f172a';
    }

    // ----- Rendering -----
    function render() {
      const rect = viewport.getBoundingClientRect();
      ctx.clearRect(0, 0, rect.width, rect.height);

      const cellW = 18 * scale;
      const cellH = 18 * scale;
      const gap = 2 * scale;

      const startX = offsetX;
      const startY = offsetY;

      // background
      ctx.fillStyle = '#0f172a';
      ctx.fillRect(0, 0, rect.width, rect.height);

      // draw cells
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < timeBuckets; c++) {
          const x = startX + c * (cellW + gap);
          const y = startY + r * (cellH + gap);

          // cull offscreen
          if (x + cellW < 0 || y + cellH < 0 || x > rect.width || y > rect.height) continue;

          const v = data[r][c];
          ctx.fillStyle = valueToColor(v);
          ctx.fillRect(x, y, cellW, cellH);

          // label if large enough
          if (cellW >= 28 && cellH >= 16) {
            ctx.fillStyle = valueToTextColor(v);
            ctx.font = `${Math.max(10, 11 * scale)}px Arial`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText(v.toFixed(1), x + cellW / 2, y + cellH / 2);
          }
        }
      }

      // row labels
      ctx.fillStyle = '#cbd5e1';
      ctx.font = '12px Arial';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (let r = 0; r < rows; r++) {
        const y = startY + r * (cellH + gap) + cellH / 2;
        if (y < 0 || y > rect.height) continue;
        ctx.fillText(stocks[r], 50, y);
      }
    }

    // ----- Interaction: pan -----
    viewport.addEventListener('mousedown', (e) => {
      isDragging = true;
      viewport.classList.add('dragging');
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      dragOffsetX = offsetX;
      dragOffsetY = offsetY;
    });

    window.addEventListener('mousemove', (e) => {
      if (isDragging) {
        offsetX = dragOffsetX + (e.clientX - dragStartX);
        offsetY = dragOffsetY + (e.clientY - dragStartY);
        render();
      }

      updateTooltip(e);
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      viewport.classList.remove('dragging');
    });

    // ----- Interaction: zoom -----
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.max(0.5, Math.min(4, scale * zoomFactor));

      // zoom around cursor
      const worldX = (mouseX - offsetX) / scale;
      const worldY = (mouseY - offsetY) / scale;

      scale = newScale;
      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      render();
    }, { passive: false });

    // ----- Tooltip -----
    function updateTooltip(e) {
      const rect = viewport.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      const cellW = 18 * scale;
      const cellH = 18 * scale;
      const gap = 2 * scale;

      const col = Math.floor((x - offsetX) / (cellW + gap));
      const row = Math.floor((y - offsetY) / (cellH + gap));

      if (row >= 0 && row < rows && col >= 0 && col < timeBuckets) {
        const cellX = offsetX + col * (cellW + gap);
        const cellY = offsetY + row * (cellH + gap);

        if (x >= cellX && x <= cellX + cellW && y >= cellY && y <= cellY + cellH) {
          const v = data[row][col];
          tooltip.style.display = 'block';
          tooltip.style.left = `${e.clientX - rect.left}px`;
          tooltip.style.top = `${e.clientY - rect.top}px`;
          tooltip.innerHTML = `
            <strong>${stocks[row]}</strong><br/>
            Bucket: ${col}<br/>
            Change: ${v.toFixed(2)}%
          `;
          return;
        }
      }

      tooltip.style.display = 'none';
    }

    // ----- Real-time updates (simulated) -----
    function pushUpdate() {
      if (paused) return;

      for (let r = 0; r < rows; r++) {
        // shift left and append new value
        data[r].shift();
        const prev = data[r][data[r].length - 1] ?? 0;
        const next = prev + (Math.random() - 0.5) * 1.2;
        data[r].push(Math.max(-5, Math.min(5, next)));
      }

      statusEl.textContent = `Live • ${new Date().toLocaleTimeString()}`;
      render();
    }

    // ----- Controls -----
    resetBtn.addEventListener('click', () => {
      scale = 1;
      offsetX = 70;
      offsetY = 20;
      render();
    });

    pauseBtn.addEventListener('click', () => {
      paused = !paused;
      pauseBtn.textContent = paused ? 'Resume' : 'Pause';
      statusEl.textContent = paused ? 'Paused' : 'Live';
    });

    // ----- Init -----
    offsetX = 70;
    offsetY = 20;
    resizeCanvas();
    render();
    statusEl.textContent = 'Live';

    setInterval(pushUpdate, 1000);
  </script>
</body>
</html>
