      <span>-5% or less</span>
      <span>0%</span>
      <span>+5% or more</span>
    </div>
  </div>

  <div class="tooltip" id="tooltip"></div>

  <script>
    const viewport = document.getElementById('viewport');
    const canvas = document.getElementById('canvas');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');

    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','AMD','NFLX','INTC',
      'ORCL','CRM','ADBE','QCOM','AVGO','IBM','CSCO','SAP','UBER','SHOP',
      'BA','GE','JPM','BAC','WFC','GS','MS','V','MA','PYPL'
    ];

    const state = {
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startPanX: 0,
      startPanY: 0,
      cells: new Map(),
      lastUpdate: Date.now()
    };

    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatPct(v) {
      return `${v >= 0 ? '+' : ''}${v.toFixed(2)}%`;
    }

    function colorForChange(change) {
      // Clamp to [-5, 5] for visual scaling
      const c = clamp(change, -5, 5);

      if (c < 0) {
        // red -> neutral
        const t = (c + 5) / 5; // 0..1
        const r = Math.round(185 + (31 - 185) * t);
        const g = Math.round(28 + (41 - 28) * t);
        const b = Math.round(28 + (55 - 28) * t);
        return `rgb(${r}, ${g}, ${b})`;
      } else {
        // neutral -> green
        const t = c / 5; // 0..1
        const r = Math.round(31 + (34 - 31) * t);
        const g = Math.round(41 + (197 - 41) * t);
        const b = Math.round(55 + (94 - 55) * t);
        return `rgb(${r}, ${g}, ${b})`;
      }
    }

    function createInitialData() {
      return symbols.map(symbol => {
        const price = randomBetween(20, 1200);
        const change = randomBetween(-5, 5);
        return {
          symbol,
          price,
          change,
          volume: Math.floor(randomBetween(100000, 50000000))
        };
      });
    }

    function renderGrid(data) {
      grid.innerHTML = '';
      state.cells.clear();

      data.forEach(item => {
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.symbol = item.symbol;

        cell.innerHTML = `
          <div class="symbol">${item.symbol}</div>
          <div class="price">$${item.price.toFixed(2)}</div>
          <div class="change">${formatPct(item.change)}</div>
        `;

        cell.style.background = colorForChange(item.change);

        cell.addEventListener('mouseenter', (e) => showTooltip(e, item));
        cell.addEventListener('mousemove', (e) => moveTooltip(e));
        cell.addEventListener('mouseleave', hideTooltip);

        grid.appendChild(cell);
        state.cells.set(item.symbol, { el: cell, data: item });
      });
    }

    function updateGrid(data) {
      data.forEach(item => {
        const entry = state.cells.get(item.symbol);
        if (!entry) return;

        entry.data = item;
        const el = entry.el;
        el.style.background = colorForChange(item.change);
        el.querySelector('.price').textContent = `$${item.price.toFixed(2)}`;
        el.querySelector('.change').textContent = formatPct(item.change);
      });
    }

    function showTooltip(event, item) {
      tooltip.style.display = 'block';
      tooltip.innerHTML = `
        <div><strong>${item.symbol}</strong></div>
        <div class="muted">Price: <span style="color: white">$${item.price.toFixed(2)}</span></div>
        <div class="muted">Change: <span style="color: white">${formatPct(item.change)}</span></div>
        <div class="muted">Volume: <span style="color: white">${item.volume.toLocaleString()}</span></div>
      `;
      moveTooltip(event);
    }

    function moveTooltip(event) {
      const pad = 16;
      const x = clamp(event.clientX + 12, pad, window.innerWidth - 220);
      const y = clamp(event.clientY + 12, pad, window.innerHeight - 120);
      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    function applyTransform() {
      canvas.style.transform = `translate(${state.panX}px, ${state.panY}px) scale(${state.zoom})`;
    }

    function resetView() {
      state.zoom = 1;
      state.panX = 0;
      state.panY = 0;
      applyTransform();
    }

    // Zoom around cursor
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const newZoom = clamp(state.zoom * zoomFactor, 0.5, 3);

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Keep cursor point stable
      const worldX = (mouseX - state.panX) / state.zoom;
      const worldY = (mouseY - state.panY) / state.zoom;

      state.zoom = newZoom;
      state.panX = mouseX - worldX * state.zoom;
      state.panY = mouseY - worldY * state.zoom;

      applyTransform();
    }, { passive: false });

    // Pan
    viewport.addEventListener('pointerdown', (e) => {
      state.dragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startPanX = state.panX;
      state.startPanY = state.panY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener('pointermove', (e) => {
      if (!state.dragging) return;
      state.panX = state.startPanX + (e.clientX - state.dragStartX);
      state.panY = state.startPanY + (e.clientY - state.dragStartY);
      applyTransform();
    });

    viewport.addEventListener('pointerup', () => {
      state.dragging = false;
    });

    viewport.addEventListener('pointercancel', () => {
      state.dragging = false;
    });

    resetBtn.addEventListener('click', resetView);

    // Simulated real-time updates
    let data = createInitialData();
    renderGrid(data);
    applyTransform();

    statusEl.textContent = 'Live updates active';

    function tick() {
      data = data.map(item => {
        // Simulate price movement
        const drift = randomBetween(-2.2, 2.2);
        const newPrice = Math.max(0.5, item.price + drift);
        const change = ((newPrice - item.price) / item.price) * 100;

        return {
          ...item,
          price: newPrice,
          change: change,
          volume: Math.max(1, Math.floor(item.volume + randomBetween(-50000, 50000)))
        };
      });

      updateGrid(data);
      state.lastUpdate = Date.now();
      statusEl.textContent = `Updated ${new Date(state.lastUpdate).toLocaleTimeString()}`;
    }

    setInterval(tick, 1000);
  </script>
</body>
</html>
```

