## Example implementation

```jsx
import React, { useEffect, useMemo, useRef, useState } from "react";

const INITIAL_STOCKS = [
  { symbol: "AAPL", price: 189.12, change: 0.8 },
  { symbol: "MSFT", price: 412.55, change: -0.4 },
  { symbol: "GOOGL", price: 176.21, change: 1.2 },
  { symbol: "AMZN", price: 184.77, change: -1.1 },
  { symbol: "NVDA", price: 122.34, change: 2.4 },
  { symbol: "TSLA", price: 238.91, change: -3.2 },
  { symbol: "META", price: 512.44, change: 0.6 },
  { symbol: "NFLX", price: 654.18, change: 1.1 },
  { symbol: "AMD", price: 156.33, change: -0.9 },
  { symbol: "INTC", price: 31.44, change: 0.2 },
  { symbol: "ORCL", price: 141.77, change: -0.3 },
  { symbol: "CRM", price: 267.88, change: 0.9 },
];

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function getColor(change) {
  // change is percent
  const maxAbs = 5;
  const normalized = clamp(change / maxAbs, -1, 1);

  if (normalized > 0) {
    const intensity = Math.round(255 - normalized * 140);
    return `rgb(${intensity}, 255, ${intensity})`;
  } else if (normalized < 0) {
    const intensity = Math.round(255 - Math.abs(normalized) * 140);
    return `rgb(255, ${intensity}, ${intensity})`;
  }
  return "rgb(245,245,245)";
}

function generateGrid(stocks, cols = 4) {
  return stocks.map((stock, index) => ({
    ...stock,
    x: index % cols,
    y: Math.floor(index / cols),
  }));
}

export default function StockHeatmap() {
  const svgRef = useRef(null);
  const [stocks, setStocks] = useState(INITIAL_STOCKS);
  const [hovered, setHovered] = useState(null);

  const [view, setView] = useState({
    scale: 1,
    offsetX: 0,
    offsetY: 0,
  });

  const [dragState, setDragState] = useState({
    dragging: false,
    startX: 0,
    startY: 0,
    originX: 0,
    originY: 0,
  });

  // Simulated real-time updates
  useEffect(() => {
    const interval = setInterval(() => {
      setStocks((prev) =>
        prev.map((s) => {
          const delta = (Math.random() - 0.5) * 1.2;
          const newChange = clamp(s.change + delta, -10, 10);
          const newPrice = Math.max(0.01, s.price * (1 + delta / 100));
          return {
            ...s,
            price: Number(newPrice.toFixed(2)),
            change: Number(newChange.toFixed(2)),
          };
        })
      );
    }, 1000);

    return () => clearInterval(interval);
  }, []);

  const grid = useMemo(() => generateGrid(stocks, 4), [stocks]);

  const cellSize = 120;
  const gap = 10;
  const cols = 4;
  const rows = Math.ceil(grid.length / cols);
  const width = cols * cellSize + (cols - 1) * gap;
  const height = rows * cellSize + (rows - 1) * gap;

  const handleWheel = (e) => {
    e.preventDefault();
    const svg = svgRef.current;
    if (!svg) return;

    const rect = svg.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
    setView((prev) => {
      const nextScale = clamp(prev.scale * zoomFactor, 0.5, 4);

      // Zoom around cursor
      const worldX = (mouseX - prev.offsetX) / prev.scale;
      const worldY = (mouseY - prev.offsetY) / prev.scale;

      const nextOffsetX = mouseX - worldX * nextScale;
      const nextOffsetY = mouseY - worldY * nextScale;

      return {
        scale: nextScale,
        offsetX: nextOffsetX,
        offsetY: nextOffsetY,
      };
    });
  };

  const handleMouseDown = (e) => {
    setDragState({
      dragging: true,
      startX: e.clientX,
      startY: e.clientY,
      originX: view.offsetX,
      originY: view.offsetY,
    });
  };

  const handleMouseMove = (e) => {
    if (dragState.dragging) {
      const dx = e.clientX - dragState.startX;
      const dy = e.clientY - dragState.startY;
      setView((prev) => ({
        ...prev,
        offsetX: dragState.originX + dx,
        offsetY: dragState.originY + dy,
      }));
      return;
    }

    const svg = svgRef.current;
    if (!svg) return;

    const rect = svg.getBoundingClientRect();
    const x = (e.clientX - rect.left - view.offsetX) / view.scale;
    const y = (e.clientY - rect.top - view.offsetY) / view.scale;

    const hit = grid.find((cell) => {
      const cx = cell.x * (cellSize + gap);
      const cy = cell.y * (cellSize + gap);
      return x >= cx && x <= cx + cellSize && y >= cy && y <= cy + cellSize;
    });

    setHovered(hit || null);
  };

  const handleMouseUp = () => {
    setDragState((prev) => ({ ...prev, dragging: false }));
  };

  const handleMouseLeave = () => {
    setHovered(null);
    setDragState((prev) => ({ ...prev, dragging: false }));
  };

  return (
    <div style={{ fontFamily: "sans-serif", width: "100%", height: "100%" }}>
      <div style={{ marginBottom: 12 }}>
        <strong>Stock Heatmap</strong>
        <div style={{ fontSize: 12, color: "#666" }}>
          Scroll to zoom • Drag to pan • Hover for details
        </div>
      </div>

      {hovered && (
        <div
          style={{
            position: "absolute",
            left: 20,
            top: 60,
            background: "white",
            border: "1px solid #ddd",
            borderRadius: 8,
            padding: "8px 10px",
            boxShadow: "0 4px 16px rgba(0,0,0,0.12)",
            pointerEvents: "none",
            zIndex: 10,
          }}
        >
          <div><strong>{hovered.symbol}</strong></div>
          <div>Price: ${hovered.price.toFixed(2)}</div>
          <div>Change: {hovered.change.toFixed(2)}%</div>
        </div>
      )}

      <svg
        ref={svgRef}
        width="100%"
        height="600"
        viewBox={`0 0 1000 600`}
        style={{
          border: "1px solid #e5e5e5",
          background: "#fafafa",
          cursor: dragState.dragging ? "grabbing" : "grab",
          userSelect: "none",
          touchAction: "none",
        }}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseLeave}
      >
        <g transform={`translate(${view.offsetX}, ${view.offsetY}) scale(${view.scale})`}>
          {grid.map((cell) => {
            const x = cell.x * (cellSize + gap);
            const y = cell.y * (cellSize + gap);
            const fill = getColor(cell.change);

            return (
              <g key={cell.symbol}>
                <rect
                  x={x}
                  y={y}
                  width={cellSize}
                  height={cellSize}
                  rx={12}
                  ry={12}
                  fill={fill}
                  stroke="#ddd"
                  strokeWidth={1}
                />
                <text
                  x={x + cellSize / 2}
                  y={y + 42}
                  textAnchor="middle"
                  fontSize="18"
                  fontWeight="700"
                  fill="#111"
                >
                  {cell.symbol}
                </text>
                <text
                  x={x + cellSize / 2}
                  y={y + 68}
                  textAnchor="middle"
                  fontSize="14"
                  fill="#333"
                >
                  ${cell.price.toFixed(2)}
                </text>
                <text
                  x={x + cellSize / 2}
                  y={y + 88}
                  textAnchor="middle"
                  fontSize="13"
                  fill={cell.change >= 0 ? "#0a7a2f" : "#b00020"}
                >
                  {cell.change >= 0 ? "+" : ""}
                  {cell.change.toFixed(2)}%
                </text>
              </g>
            );
          })}
        </g>
      </svg>
    </div>
  );
}
```

