<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="legend">
        <span class="swatch" style="background:#16a34a"></span> Up
        <span class="swatch" style="background:#64748b"></span> Flat
        <span class="swatch" style="background:#dc2626"></span> Down
      </div>
      <div class="meta">Wheel = zoom · Drag = pan · Hover = details</div>
    </div>

    <div id="viewport" class="viewport">
      <div id="heatmap" class="heatmap">
        <div id="grid" class="grid"></div>
      </div>
      <div id="tooltip" class="tooltip"></div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');

    // Sample stock universe
    const symbols = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','NFLX',
      'AMD','INTC','ORCL','CRM','UBER','SHOP','ADBE','QCOM',
      'JPM','BAC','GS','MS','V','MA','PYPL','COST',
      'XOM','CVX','COP','SLB','BA','CAT','GE','HON'
    ];

    const stocks = symbols.map((symbol, i) => {
      const base = 50 + Math.random() * 450;
      return {
        symbol,
        price: base,
        prevClose: base * (1 - (Math.random() - 0.5) * 0.04),
        volume: Math.floor(1e6 + Math.random() * 9e6),
        sector: ['Tech','Finance','Energy','Industrials','Consumer'][i % 5]
      };
    });

    // Layout
    const cols = 8;
    grid.style.gridTemplateColumns = `repeat(${cols}, 120px)`;

    function pctChange(stock) {
      return ((stock.price - stock.prevClose) / stock.prevClose) * 100;
    }

    function colorForChange(change) {
      // Map change to red/gray/green
      const maxAbs = 5; // +/- 5% saturates
      const t = Math.max(-1, Math.min(1, change / maxAbs));

      if (Math.abs(t) < 0.05) return 'rgb(100, 116, 139)'; // flat

      if (t > 0) {
        const g = Math.floor(80 + 120 * t);
        const r = Math.floor(20 + 20 * (1 - t));
        const b = Math.floor(40 + 20 * (1 - t));
        return `rgb(${r}, ${g}, ${b})`;
      } else {
        const a = Math.abs(t);
        const r = Math.floor(80 + 140 * a);
        const g = Math.floor(30 + 30 * (1 - a));
        const b = Math.floor(40 + 20 * (1 - a));
        return `rgb(${r}, ${g}, ${b})`;
      }
    }

    function render() {
      grid.innerHTML = '';
      stocks.forEach((stock, idx) => {
        const change = pctChange(stock);
        const tile = document.createElement('div');
        tile.className = 'tile';
        tile.style.background = colorForChange(change);

        tile.innerHTML = `
          <div class="symbol">${stock.symbol}</div>
          <div class="price">$${stock.price.toFixed(2)}</div>
          <div class="change">${change >= 0 ? '+' : ''}${change.toFixed(2)}%</div>
        `;

        tile.addEventListener('mouseenter', (e) => {
          tooltip.style.display = 'block';
          tooltip.innerHTML = `
            <strong>${stock.symbol}</strong><br/>
            Price: $${stock.price.toFixed(2)}<br/>
            Prev Close: $${stock.prevClose.toFixed(2)}<br/>
            Change: ${change >= 0 ? '+' : ''}${change.toFixed(2)}%<br/>
            Volume: ${stock.volume.toLocaleString()}<br/>
            Sector: ${stock.sector}
          `;
        });

        tile.addEventListener('mousemove', (e) => {
          tooltip.style.left = `${e.clientX}px`;
          tooltip.style.top = `${e.clientY}px`;
        });

        tile.addEventListener('mouseleave', () => {
          tooltip.style.display = 'none';
        });

        grid.appendChild(tile);
      });
    }

    // Real-time updates (simulated)
    function updatePrices() {
      stocks.forEach(stock => {
        const drift = (Math.random() - 0.5) * 0.8; // random walk
        stock.price = Math.max(1, stock.price * (1 + drift / 100));
        stock.volume = Math.max(0, stock.volume + Math.floor((Math.random() - 0.5) * 50000));
      });
      render();
    }

    // Zoom/pan state
    let scale = 1;
    let panX = 0;
    let panY = 0;
    let isDragging = false;
    let startX = 0;
    let startY = 0;
    let startPanX = 0;
    let startPanY = 0;

    function applyTransform() {
      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = Math.min(4, Math.max(0.5, scale * zoomFactor));

      // Zoom around cursor
      panX = mouseX - (mouseX - panX) * (nextScale / scale);
      panY = mouseY - (mouseY - panY) * (nextScale / scale);
      scale = nextScale;

      applyTransform();
    }, { passive: false });

    viewport.addEventListener('mousedown', (e) => {
      isDragging = true;
      viewport.classList.add('dragging');
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (isDragging) {
        panX = startPanX + (e.clientX - startX);
        panY = startPanY + (e.clientY - startY);
        applyTransform();
      }

      // Keep tooltip following cursor even when not over tile
      if (tooltip.style.display === 'block') {
        tooltip.style.left = `${e.clientX}px`;
        tooltip.style.top = `${e.clientY}px`;
      }
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
      viewport.classList.remove('dragging');
    });

    // Initial render
    render();
    applyTransform();

    // Update every second
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
```

