<body>
  <div class="app">
    <div class="toolbar">
      <button id="resetView">Reset View</button>
      <button id="toggleLive">Pause Live Updates</button>
      <div class="legend">
        <span>Change:</span>
        <div class="legend-bar"></div>
        <span>-5% to +5%</span>
      </div>
      <div class="hint">Wheel = zoom · Drag = pan · Hover = details</div>
    </div>
    <div class="container" id="container">
      <canvas id="heatmap"></canvas>
      <div id="tooltip" class="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");
    const container = document.getElementById("container");
    const tooltip = document.getElementById("tooltip");
    const resetViewBtn = document.getElementById("resetView");
    const toggleLiveBtn = document.getElementById("toggleLive");

    // Demo stock universe
    const stocks = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","AMD","NFLX","INTC",
      "ORCL","CRM","UBER","SNOW","SHOP","QCOM","IBM","ADBE","PYPL","BABA"
    ];

    const timeBuckets = 60; // columns
    const rows = stocks.length;

    // Heatmap data: each cell is a percentage change
    let data = Array.from({ length: rows }, () =>
      Array.from({ length: timeBuckets }, () => randomChange())
    );

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    let isDragging = false;
    let dragStart = { x: 0, y: 0 };
    let panStart = { x: 0, y: 0 };

    let liveUpdates = true;
    let animationFrame = null;

    function randomChange() {
      // Simulated price change between -5% and +5%
      return (Math.random() - 0.5) * 10;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function resizeCanvas() {
      const dpr = window.devicePixelRatio || 1;
      const rect = container.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function colorForChange(change) {
      // Map -5..0..+5 to red/black/green
      const t = clamp((change + 5) / 10, 0, 1);
      const r = t < 0.5 ? 239 : Math.round(17 + (34 - 17) * ((t - 0.5) / 0.5));
      const g = t < 0.5 ? Math.round(68 + (17 - 68) * (t / 0.5)) : Math.round(17 + (197 - 17) * ((t - 0.5) / 0.5));
      const b = t < 0.5 ? Math.round(68 + (17 - 68) * (t / 0.5)) : Math.round(17 + (34 - 17) * ((t - 0.5) / 0.5));
      return `rgb(${r},${g},${b})`;
    }

    function draw() {
      const rect = container.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, width, height);

      const cellW = 80 * scale;
      const cellH = 28 * scale;
      const startX = offsetX;
      const startY = offsetY;

      // Draw cells
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < timeBuckets; c++) {
          const x = startX + c * cellW;
          const y = startY + r * cellH;

          if (x + cellW < 0 || y + cellH < 0 || x > width || y > height) continue;

          const change = data[r][c];
          ctx.fillStyle = colorForChange(change);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // subtle text for larger zoom levels
          if (scale > 0.8) {
            ctx.fillStyle = "rgba(255,255,255,0.9)";
            ctx.font = `${Math.max(10, 12 * scale)}px system-ui`;
            ctx.fillText(change.toFixed(2) + "%", x + 6, y + cellH / 2 + 4);
          }
        }
      }

      // Row labels
      ctx.fillStyle = "#e5e7eb";
      ctx.font = "12px system-ui";
      for (let r = 0; r < rows; r++) {
        const y = startY + r * cellH + cellH / 2 + 4;
        if (y < 0 || y > height) continue;
        ctx.fillText(stocks[r], 8, y);
      }

      // Grid lines
      ctx.strokeStyle = "rgba(255,255,255,0.06)";
      ctx.lineWidth = 1;
      for (let r = 0; r <= rows; r++) {
        const y = startY + r * cellH;
        if (y < 0 || y > height) continue;
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
      }
    }

    function screenToCell(mx, my) {
      const cellW = 80 * scale;
      const cellH = 28 * scale;
      const c = Math.floor((mx - offsetX) / cellW);
      const r = Math.floor((my - offsetY) / cellH);
      if (r < 0 || r >= rows || c < 0 || c >= timeBuckets) return null;
      return { r, c, cellW, cellH };
    }

    canvas.addEventListener("mousedown", (e) => {
      isDragging = true;
      dragStart = { x: e.clientX, y: e.clientY };
      panStart = { x: offsetX, y: offsetY };
    });

    window.addEventListener("mousemove", (e) => {
      const rect = container.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      if (isDragging) {
        offsetX = panStart.x + (e.clientX - dragStart.x);
        offsetY = panStart.y + (e.clientY - dragStart.y);
        draw();
      }

      const cell = screenToCell(mx, my);
      if (cell) {
        const value = data[cell.r][cell.c];
        tooltip.style.display = "block";
        tooltip.style.left = `${mx}px`;
        tooltip.style.top = `${my}px`;
        tooltip.innerHTML = `
          <strong>${stocks[cell.r]}</strong><br/>
          Bucket: ${cell.c}<br/>
          Change: ${value.toFixed(2)}%
        `;
      } else {
        tooltip.style.display = "none";
      }
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = container.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.4, 4);

      // Zoom around cursor
      const worldX = (mx - offsetX) / scale;
      const worldY = (my - offsetY) / scale;

      scale = newScale;
      offsetX = mx - worldX * scale;
      offsetY = my - worldY * scale;

      draw();
    }, { passive: false });

    resetViewBtn.addEventListener("click", () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    toggleLiveBtn.addEventListener("click", () => {
      liveUpdates = !liveUpdates;
      toggleLiveBtn.textContent = liveUpdates ? "Pause Live Updates" : "Resume Live Updates";
    });

    // Simulated real-time updates
    function updateLiveData() {
      if (liveUpdates) {
        for (let r = 0; r < rows; r++) {
          data[r].shift();
          data[r].push(randomChange());
        }
        draw();
      }
      animationFrame = setTimeout(updateLiveData, 1000);
    }

    window.addEventListener("resize", resizeCanvas);

    // Initial render
    resizeCanvas();
    updateLiveData();
  </script>
</body>
</html>
