  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="hint">Wheel = zoom · Drag = pan · Hover = details</div>
      <div class="spacer"></div>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
      <button id="resetBtn">Reset View</button>
    </div>

    <div id="viewport" class="viewport">
      <div id="heatmap" class="heatmap"></div>
      <div id="tooltip" class="tooltip"></div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');

    // Sample stock universe
    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','AMD','NFLX','INTC',
      'ORCL','CRM','ADBE','QCOM','AVGO','COST','PEP','KO','MCD','DIS',
      'JPM','BAC','WFC','GS','MS','V','MA','PYPL','UBER','SNOW',
      'SHOP','SQ','PLTR','PANW','ZS','NOW','INTU','TXN','IBM','CSCO'
    ];

    // Layout config
    const cols = 5;
    heatmap.style.gridTemplateColumns = `repeat(${cols}, 120px)`;

    // State
    const state = {
      scale: 1,
      translateX: 0,
      translateY: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startTranslateX: 0,
      startTranslateY: 0,
      stocks: []
    };

    function randomBetween(min, max) {
      return min + Math.random() * (max - min);
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function formatPrice(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatChange(v) {
      const sign = v >= 0 ? '+' : '';
      return `${sign}${v.toFixed(2)}%`;
    }

    function generateInitialStocks() {
      state.stocks = symbols.map(symbol => {
        const price = randomBetween(20, 1000);
        const change = randomBetween(-4, 4);
        return {
          symbol,
          price,
          prevPrice: price,
          changePct: change,
          volume: Math.floor(randomBetween(100000, 50000000))
        };
      });
    }

    function getColor(changePct) {
      // Map -5%..+5% to red->dark->green
      const c = clamp(changePct, -5, 5);
      const t = (c + 5) / 10; // 0..1
      // Interpolate between red, neutral, green
      const red = [185, 28, 28];
      const neutral = [31, 41, 55];
      const green = [34, 197, 94];

      let a, b, localT;
      if (t < 0.5) {
        a = red; b = neutral; localT = t / 0.5;
      } else {
        a = neutral; b = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = a.map((v, i) => Math.round(v + (b[i] - v) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function renderHeatmap() {
      heatmap.innerHTML = '';

      state.stocks.forEach(stock => {
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.style.background = getColor(stock.changePct);

        cell.innerHTML = `
          <div class="symbol">${stock.symbol}</div>
          <div class="price">${formatPrice(stock.price)}</div>
          <div class="change">${formatChange(stock.changePct)}</div>
        `;

        cell.addEventListener('mouseenter', (e) => showTooltip(e, stock));
        cell.addEventListener('mousemove', (e) => moveTooltip(e));
        cell.addEventListener('mouseleave', hideTooltip);

        heatmap.appendChild(cell);
      });

      applyTransform();
    }

    function applyTransform() {
      heatmap.style.transform = `translate(${state.translateX}px, ${state.translateY}px) scale(${state.scale})`;
    }

    function resetView() {
      state.scale = 1;
      state.translateX = 0;
      state.translateY = 0;
      applyTransform();
    }

    function updateStockData() {
      // Simulate real-time updates
      state.stocks = state.stocks.map(stock => {
        const drift = randomBetween(-1.2, 1.2);
        const newChange = clamp(stock.changePct + drift * 0.15, -10, 10);
        const newPrice = Math.max(0.01, stock.price * (1 + drift / 100));

        return {
          ...stock,
          prevPrice: stock.price,
          price: newPrice,
          changePct: newChange
        };
      });

      // Re-render only the cells for simplicity in this initial version
      renderHeatmap();
    }

    function showTooltip(event, stock) {
      tooltip.style.display = 'block';
      tooltip.innerHTML = `
        <div class="name">${stock.symbol}</div>
        <div>Price: ${formatPrice(stock.price)}</div>
        <div>Change: ${formatChange(stock.changePct)}</div>
        <div>Volume: ${stock.volume.toLocaleString()}</div>
      `;
      moveTooltip(event);
    }

    function moveTooltip(event) {
      const padding = 16;
      const rect = tooltip.getBoundingClientRect();
      let x = event.clientX + 12;
      let y = event.clientY + 12;

      if (x + rect.width + padding > window.innerWidth) {
        x = event.clientX - rect.width - 12;
      }
      if (y + rect.height + padding > window.innerHeight) {
        y = event.clientY - rect.height - 12;
      }

      tooltip.style.left = `${x}px`;
      tooltip.style.top = `${y}px`;
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    // Zoom with mouse wheel
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomIntensity = 0.0015;
      const delta = -e.deltaY * zoomIntensity;
      const newScale = clamp(state.scale * (1 + delta), 0.5, 3);

      // Zoom around cursor
      const rect = viewport.getBoundingClientRect();
      const cursorX = e.clientX - rect.left;
      const cursorY = e.clientY - rect.top;

      const worldX = (cursorX - state.translateX) / state.scale;
      const worldY = (cursorY - state.translateY) / state.scale;

      state.scale = newScale;
      state.translateX = cursorX - worldX * state.scale;
      state.translateY = cursorY - worldY * state.scale;

      applyTransform();
    }, { passive: false });

    // Pan with drag
    viewport.addEventListener('pointerdown', (e) => {
      state.dragging = true;
      viewport.classList.add('dragging');
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startTranslateX = state.translateX;
      state.startTranslateY = state.translateY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener('pointermove', (e) => {
      if (!state.dragging) return;

      const dx = e.clientX - state.dragStartX;
      const dy = e.clientY - state.dragStartY;
      state.translateX = state.startTranslateX + dx;
      state.translateY = state.startTranslateY + dy;
      applyTransform();
    });

    viewport.addEventListener('pointerup', () => {
      state.dragging = false;
      viewport.classList.remove('dragging');
    });

    viewport.addEventListener('pointercancel', () => {
      state.dragging = false;
      viewport.classList.remove('dragging');
    });

    resetBtn.addEventListener('click', resetView);

    // Init
    generateInitialStocks();
    renderHeatmap();

    // Real-time update simulation
    setInterval(updateStockData, 1500);
  </script>
</body>
</html>
```

