<body>
  <div class="app">
    <div class="toolbar">
      <div>
        <h1>Stock Price Heatmap</h1>
        <div class="meta">Drag to pan • Scroll to zoom • Hover for details</div>
      </div>
      <div class="controls">
        <div class="legend">
          <span>-5%</span>
          <div class="legend-bar"></div>
          <span>+5%</span>
        </div>
        <button id="resetBtn">Reset View</button>
      </div>
    </div>

    <div class="canvas-wrap" id="wrap">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById("heatmap");
    const wrap = document.getElementById("wrap");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");
    const ctx = canvas.getContext("2d");

    // ----- Data model -----
    const stocks = [
      "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
      "TSLA", "META", "AMD", "NFLX", "INTC",
      "ORCL", "CRM", "UBER", "SHOP", "ADBE"
    ];

    const timeBuckets = 60;
    const cellW = 70;
    const cellH = 28;
    const labelW = 80;
    const labelH = 28;

    // Each stock has an array of percent changes over time
    const data = stocks.map(() =>
      Array.from({ length: timeBuckets }, () => randomChange())
    );

    function randomChange() {
      return (Math.random() - 0.5) * 10; // -5% to +5%
    }

    // ----- View transform -----
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    let dragging = false;
    let dragStart = { x: 0, y: 0 };
    let offsetStart = { x: 0, y: 0 };

    // ----- Canvas sizing -----
    function resize() {
      const dpr = window.devicePixelRatio || 1;
      const rect = wrap.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + "px";
      canvas.style.height = rect.height + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    window.addEventListener("resize", resize);

    // ----- Color mapping -----
    function colorForChange(change) {
      // clamp to [-5, 5]
      const v = Math.max(-5, Math.min(5, change));
      if (v < 0) {
        const t = (v + 5) / 5; // 0..1
        return lerpColor([185, 28, 28], [248, 250, 252], t);
      } else {
        const t = v / 5; // 0..1
        return lerpColor([248, 250, 252], [21, 128, 61], t);
      }
    }

    function lerpColor(a, b, t) {
      const r = Math.round(a[0] + (b[0] - a[0]) * t);
      const g = Math.round(a[1] + (b[1] - a[1]) * t);
      const b2 = Math.round(a[2] + (b[2] - a[2]) * t);
      return `rgb(${r}, ${g}, ${b2})`;
    }

    // ----- Drawing -----
    function draw() {
      const rect = wrap.getBoundingClientRect();
      ctx.clearRect(0, 0, rect.width, rect.height);

      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      // Background grid
      const totalW = labelW + timeBuckets * cellW;
      const totalH = labelH + stocks.length * cellH;

      // Draw cells
      for (let row = 0; row < stocks.length; row++) {
        for (let col = 0; col < timeBuckets; col++) {
          const x = labelW + col * cellW;
          const y = labelH + row * cellH;
          const change = data[row][col];

          ctx.fillStyle = colorForChange(change);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // subtle border
          ctx.strokeStyle = "rgba(15, 23, 42, 0.25)";
          ctx.strokeRect(x, y, cellW - 1, cellH - 1);

          // text
          ctx.fillStyle = Math.abs(change) > 2.5 ? "#ffffff" : "#0f172a";
          ctx.font = "11px sans-serif";
          ctx.textAlign = "center";
          ctx.textBaseline = "middle";
          ctx.fillText(change.toFixed(1) + "%", x + cellW / 2, y + cellH / 2);
        }
      }

      // Row labels
      ctx.fillStyle = "#e5e7eb";
      ctx.font = "12px sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      for (let row = 0; row < stocks.length; row++) {
        const y = labelH + row * cellH + cellH / 2;
        ctx.fillText(stocks[row], labelW - 10, y);
      }

      // Column labels
      ctx.textAlign = "center";
      ctx.textBaseline = "bottom";
      for (let col = 0; col < timeBuckets; col += 5) {
        const x = labelW + col * cellW + cellW / 2;
        ctx.fillStyle = "#94a3b8";
        ctx.fillText(`T${col}`, x, labelH - 4);
      }

      // Grid lines
      ctx.strokeStyle = "rgba(148, 163, 184, 0.15)";
      for (let row = 0; row <= stocks.length; row++) {
        const y = labelH + row * cellH;
        ctx.beginPath();
        ctx.moveTo(labelW, y);
        ctx.lineTo(labelW + timeBuckets * cellW, y);
        ctx.stroke();
      }
      for (let col = 0; col <= timeBuckets; col++) {
        const x = labelW + col * cellW;
        ctx.beginPath();
        ctx.moveTo(x, labelH);
        ctx.lineTo(x, labelH + stocks.length * cellH);
        ctx.stroke();
      }

      ctx.restore();
    }

    // ----- Interaction helpers -----
    function screenToWorld(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = (clientX - rect.left - offsetX) / scale;
      const y = (clientY - rect.top - offsetY) / scale;
      return { x, y };
    }

    function getCellAt(clientX, clientY) {
      const p = screenToWorld(clientX, clientY);
      const col = Math.floor((p.x - labelW) / cellW);
      const row = Math.floor((p.y - labelH) / cellH);

      if (
        row >= 0 && row < stocks.length &&
        col >= 0 && col < timeBuckets
      ) {
        return { row, col };
      }
      return null;
    }

    // ----- Mouse events -----
    canvas.addEventListener("mousedown", (e) => {
      dragging = true;
      dragStart = { x: e.clientX, y: e.clientY };
      offsetStart = { x: offsetX, y: offsetY };
    });

    window.addEventListener("mousemove", (e) => {
      if (dragging) {
        offsetX = offsetStart.x + (e.clientX - dragStart.x);
        offsetY = offsetStart.y + (e.clientY - dragStart.y);
        draw();
      }

      const cell = getCellAt(e.clientX, e.clientY);
      if (cell) {
        const change = data[cell.row][cell.col];
        tooltip.style.display = "block";
        tooltip.style.left = (e.clientX - wrap.getBoundingClientRect().left + 12) + "px";
        tooltip.style.top = (e.clientY - wrap.getBoundingClientRect().top + 12) + "px";
        tooltip.innerHTML = `
          <strong>${stocks[cell.row]}</strong><br/>
          Bucket: ${cell.col}<br/>
          Change: ${change.toFixed(2)}%<br/>
          Price: $${(100 + change).toFixed(2)}
        `;
      } else {
        tooltip.style.display = "none";
      }
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - offsetX) / scale;
      const worldY = (mouseY - offsetY) / scale;

      scale *= zoomFactor;
      scale = Math.max(0.5, Math.min(3, scale));

      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      draw();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      draw();
    });

    // ----- Real-time updates -----
    function updateData() {
      for (let row = 0; row < stocks.length; row++) {
        // shift left and append new value
        data[row].shift();
        const prev = data[row][data[row].length - 1] ?? 0;
        const next = Math.max(-5, Math.min(5, prev + (Math.random() - 0.5) * 1.2));
        data[row].push(next);
      }
      draw();
    }

    // ----- Initialize -----
    resize();
    setInterval(updateData, 1000);
  </script>
</body>
</html>
