      // Neutral dark gray
      const neutral = [31, 41, 55];
      const green = [34, 197, 94];
      const red = [239, 68, 68];

      const target = changePct >= 0 ? green : red;
      const rgb = neutral.map((n, i) => Math.round(n + (target[i] - n) * t));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function updateHeatmapTransform() {
      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    function renderTiles() {
      heatmap.innerHTML = "";
      stocks.forEach(stock => {
        const tile = document.createElement("div");
        tile.className = "tile";
        tile.dataset.ticker = stock.ticker;

        tile.style.background = colorForChange(stock.changePct);

        tile.innerHTML = `
          <div class="ticker">${stock.ticker}</div>
          <div class="price">${formatPrice(stock.price)}</div>
          <div class="change">${formatPct(stock.changePct)}</div>
        `;

        tile.addEventListener("mouseenter", (e) => {
          tooltip.classList.add("visible");
          tooltip.innerHTML = `
            <strong>${stock.ticker}</strong><br/>
            Price: ${formatPrice(stock.price)}<br/>
            Change: ${formatPct(stock.changePct)}
          `;
        });

        tile.addEventListener("mousemove", (e) => {
          tooltip.style.left = `${e.clientX}px`;
          tooltip.style.top = `${e.clientY}px`;
        });

        tile.addEventListener("mouseleave", () => {
          tooltip.classList.remove("visible");
        });

        heatmap.appendChild(tile);
      });
    }

    function updatePrices() {
      stocks.forEach(stock => {
        stock.prevPrice = stock.price;

        // Random walk with slight drift
        const volatility = stock.price * 0.01;
        const delta = (Math.random() - 0.5) * volatility * 2;
        stock.price = Math.max(1, stock.price + delta);
        stock.changePct = ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;
      });

      // Update tile contents and colors
      [...heatmap.children].forEach((tile, i) => {
        const stock = stocks[i];
        tile.style.background = colorForChange(stock.changePct);
        tile.querySelector(".price").textContent = formatPrice(stock.price);
        tile.querySelector(".change").textContent = formatPct(stock.changePct);
      });

      statusEl.textContent = `Live updates: on | ${new Date().toLocaleTimeString()}`;
    }

    // --- Pan / zoom interactions ---
    viewport.addEventListener("mousedown", (e) => {
      isDragging = true;
      viewport.classList.add("dragging");
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      panX = startPanX + (e.clientX - dragStartX);
      panY = startPanY + (e.clientY - dragStartY);
      updateHeatmapTransform();
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = 1.08;
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const prevScale = scale;
      const nextScale = e.deltaY < 0 ? scale * zoomFactor : scale / zoomFactor;
      scale = clamp(nextScale, 0.5, 3);

      // Zoom around cursor
      const worldX = (mouseX - panX) / prevScale;
      const worldY = (mouseY - panY) / prevScale;

      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      updateHeatmapTransform();
    }, { passive: false });

    // Touch support for basic pan
    let touchStartDist = 0;
    let touchStartScale = 1;
    let touchStartPanX = 0;
    let touchStartPanY = 0;
    let touchStartCenter = null;

    viewport.addEventListener("touchstart", (e) => {
      if (e.touches.length === 1) {
        isDragging = true;
        const t = e.touches[0];
        dragStartX = t.clientX;
        dragStartY = t.clientY;
        startPanX = panX;
        startPanY = panY;
      } else if (e.touches.length === 2) {
        isDragging = false;
        const [a, b] = e.touches;
        touchStartDist = Math.hypot(b.clientX - a.clientX, b.clientY - a.clientY);
        touchStartScale = scale;
        touchStartPanX = panX;
        touchStartPanY = panY;
        touchStartCenter = {
          x: (a.clientX + b.clientX) / 2,
          y: (a.clientY + b.clientY) / 2
        };
      }
    }, { passive: true });

    viewport.addEventListener("touchmove", (e) => {
      if (e.touches.length === 1 && isDragging) {
        const t = e.touches[0];
        panX = startPanX + (t.clientX - dragStartX);
        panY = startPanY + (t.clientY - dragStartY);
        updateHeatmapTransform();
      } else if (e.touches.length === 2) {
        e.preventDefault();
        const [a, b] = e.touches;
        const dist = Math.hypot(b.clientX - a.clientX, b.clientY - a.clientY);
        const center = {
          x: (a.clientX + b.clientX) / 2,
          y: (a.clientY + b.clientY) / 2
        };

        const prevScale = touchStartScale;
        scale = clamp(touchStartScale * (dist / touchStartDist), 0.5, 3);

        const dx = center.x - touchStartCenter.x;
        const dy = center.y - touchStartCenter.y;

        panX = touchStartPanX + dx;
        panY = touchStartPanY + dy;

        // Keep zoom centered around pinch center
        const worldX = (touchStartCenter.x - touchStartPanX) / prevScale;
        const worldY = (touchStartCenter.y - touchStartPanY) / prevScale;
        panX = center.x - worldX * scale;
        panY = center.y - worldY * scale;

        updateHeatmapTransform();
      }
    }, { passive: false });

    viewport.addEventListener("touchend", () => {
      if (viewport.touches?.length === 0) isDragging = false;
    });

    // --- Init ---
    renderTiles();
    updateHeatmapTransform();
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
```

