    </div>
  </div>

  <script>
    const viewport = document.getElementById('viewport');
    const canvas = document.getElementById('canvas');
    const tooltip = document.getElementById('tooltip');
    const resetBtn = document.getElementById('resetBtn');
    const toggleLiveBtn = document.getElementById('toggleLiveBtn');

    // Demo data
    const stocks = [
      'AAPL', 'MSFT', 'NVDA', 'AMZN', 'GOOGL', 'META', 'TSLA', 'AMD',
      'NFLX', 'INTC', 'ORCL', 'CRM', 'UBER', 'SHOP', 'ADBE', 'QCOM'
    ];

    const timeBuckets = 40;
    const cellW = 90;
    const cellH = 34;
    const labelW = 70;
    const labelH = 24;

    let live = true;

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    // Drag state
    let dragging = false;
    let dragStartX = 0;
    let dragStartY = 0;
    let startOffsetX = 0;
    let startOffsetY = 0;

    // Data: each stock has an array of % changes over time
    const data = new Map();
    const basePrices = new Map();

    function initData() {
      stocks.forEach(sym => {
        basePrices.set(sym, 100 + Math.random() * 900);
        const arr = [];
        for (let i = 0; i < timeBuckets; i++) {
          arr.push((Math.random() - 0.5) * 4);
        }
        data.set(sym, arr);
      });
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // change in percent, roughly -5 to +5
      const maxAbs = 5;
      const t = clamp((change + maxAbs) / (2 * maxAbs), 0, 1);

      // interpolate red -> neutral -> green
      const red = [217, 75, 75];
      const mid = [43, 58, 102];
      const green = [60, 207, 122];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = mid; localT = t / 0.5;
      } else {
        c1 = mid; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = c1.map((v, i) => Math.round(v + (c2[i] - v) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function render() {
      const width = labelW + timeBuckets * cellW;
      const height = labelH + stocks.length * cellH;

      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';
      canvas.style.transform = `translate(${offsetX}px, ${offsetY}px) scale(${scale})`;

      canvas.innerHTML = '';

      // Labels
      stocks.forEach((sym, row) => {
        const label = document.createElement('div');
        label.className = 'label';
        label.style.left = '8px';
        label.style.top = `${labelH + row * cellH + 8}px`;
        label.textContent = sym;
        canvas.appendChild(label);
      });

      for (let col = 0; col < timeBuckets; col++) {
        const label = document.createElement('div');
        label.className = 'label';
        label.style.left = `${labelW + col * cellW + 8}px`;
        label.style.top = '4px';
        label.textContent = `T-${timeBuckets - col - 1}`;
        canvas.appendChild(label);
      }

      // Cells
      stocks.forEach((sym, row) => {
        const arr = data.get(sym);
        arr.forEach((change, col) => {
          const cell = document.createElement('div');
          cell.className = 'cell';
          cell.style.left = `${labelW + col * cellW}px`;
          cell.style.top = `${labelH + row * cellH}px`;
          cell.style.width = `${cellW}px`;
          cell.style.height = `${cellH}px`;
          cell.style.background = colorForChange(change);
          cell.dataset.symbol = sym;
          cell.dataset.row = row;
          cell.dataset.col = col;
          cell.dataset.change = change.toFixed(2);
          cell.dataset.price = (basePrices.get(sym) * (1 + change / 100)).toFixed(2);

          cell.addEventListener('mousemove', onCellHover);
          cell.addEventListener('mouseleave', hideTooltip);

          canvas.appendChild(cell);
        });
      });
    }

    function onCellHover(e) {
      const cell = e.currentTarget;
      const symbol = cell.dataset.symbol;
      const change = parseFloat(cell.dataset.change);
      const price = parseFloat(cell.dataset.price);
      const base = basePrices.get(symbol);

      tooltip.innerHTML = `
        <div><strong>${symbol}</strong></div>
        <div class="muted">Current: $${price.toFixed(2)}</div>
        <div class="muted">Base: $${base.toFixed(2)}</div>
        <div class="muted">Change: ${change >= 0 ? '+' : ''}${change.toFixed(2)}%</div>
      `;
      tooltip.style.display = 'block';
      tooltip.style.left = (e.clientX + 14) + 'px';
      tooltip.style.top = (e.clientY + 14) + 'px';
    }

    function hideTooltip() {
      tooltip.style.display = 'none';
    }

    function updateLiveData() {
      if (!live) return;

      // Shift left and append new values
      stocks.forEach(sym => {
        const arr = data.get(sym);
        arr.shift();

        const prev = arr[arr.length - 1] ?? 0;
        const next = clamp(prev + (Math.random() - 0.5) * 1.2, -5, 5);
        arr.push(next);

        // Update base price slightly for realism
        const currentBase = basePrices.get(sym);
        basePrices.set(sym, currentBase * (1 + (Math.random() - 0.5) * 0.002));
      });

      render();
    }

    function resetView() {
      scale = 1;
      offsetX = 0;
      offsetY = 0;
      render();
    }

    // Zoom around cursor
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 3);

      // Keep point under cursor stable
      const worldX = (mouseX - offsetX) / scale;
      const worldY = (mouseY - offsetY) / scale;

      scale = newScale;
      offsetX = mouseX - worldX * scale;
      offsetY = mouseY - worldY * scale;

      render();
    }, { passive: false });

    // Pan
    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      startOffsetX = offsetX;
      startOffsetY = offsetY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      offsetX = startOffsetX + (e.clientX - dragStartX);
      offsetY = startOffsetY + (e.clientY - dragStartY);
      render();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    resetBtn.addEventListener('click', resetView);

    toggleLiveBtn.addEventListener('click', () => {
      live = !live;
      toggleLiveBtn.textContent = live ? 'Pause Live' : 'Resume Live';
    });

    // Keep tooltip positioned on scroll/resize if needed
    window.addEventListener('resize', () => render());

    initData();
    render();
    setInterval(updateLiveData, 1000);
  </script>
</body>
