### `StockHeatmap.jsx`
```jsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import { scaleLinear } from "d3-scale";
import { extent } from "d3-array";

const STOCKS = [
  "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
  "META", "TSLA", "AMD", "NFLX", "INTC",
  "ORCL", "CRM", "ADBE", "QCOM", "AVGO"
];

const TIME_BUCKETS = 40;
const CELL_W = 48;
const CELL_H = 28;

function generateInitialData() {
  const now = Date.now();
  return STOCKS.map((symbol, row) => ({
    symbol,
    values: Array.from({ length: TIME_BUCKETS }, (_, i) => ({
      t: now - (TIME_BUCKETS - i) * 1000,
      price: 100 + Math.random() * 50,
      change: (Math.random() - 0.5) * 4
    }))
  }));
}

function updateData(prev) {
  return prev.map((stock) => {
    const last = stock.values[stock.values.length - 1];
    const nextPrice = Math.max(1, last.price * (1 + (Math.random() - 0.5) * 0.01));
    const nextChange = ((nextPrice - last.price) / last.price) * 100;

    return {
      ...stock,
      values: [
        ...stock.values.slice(1),
        {
          t: Date.now(),
          price: nextPrice,
          change: nextChange
        }
      ]
    };
  });
}

export default function StockHeatmap() {
  const containerRef = useRef(null);
  const svgRef = useRef(null);

  const [data, setData] = useState(generateInitialData);
  const [hovered, setHovered] = useState(null);
  const [transform, setTransform] = useState({
    x: 0,
    y: 0,
    k: 1
  });

  // Simulated real-time updates
  useEffect(() => {
    const id = setInterval(() => {
      setData((prev) => updateData(prev));
    }, 1000);
    return () => clearInterval(id);
  }, []);

  const allChanges = useMemo(() => {
    return data.flatMap((s) => s.values.map((v) => v.change));
  }, [data]);

  const colorScale = useMemo(() => {
    const [min, max] = extent(allChanges);
    return scaleLinear()
      .domain([min ?? -5, 0, max ?? 5])
      .range(["#d73027", "#f7f7f7", "#1a9850"]);
  }, [allChanges]);

  const handleWheel = (e) => {
    e.preventDefault();
    const delta = -e.deltaY;
    const zoomFactor = delta > 0 ? 1.1 : 0.9;

    setTransform((t) => ({
      ...t,
      k: Math.min(4, Math.max(0.5, t.k * zoomFactor))
    }));
  };

  const dragState = useRef({ dragging: false, startX: 0, startY: 0, origX: 0, origY: 0 });

  const onMouseDown = (e) => {
    dragState.current = {
      dragging: true,
      startX: e.clientX,
      startY: e.clientY,
      origX: transform.x,
      origY: transform.y
    };
  };

  const onMouseMove = (e) => {
    if (!dragState.current.dragging) return;
    const dx = e.clientX - dragState.current.startX;
    const dy = e.clientY - dragState.current.startY;
    setTransform((t) => ({
      ...t,
      x: dragState.current.origX + dx,
      y: dragState.current.origY + dy
    }));
  };

  const onMouseUp = () => {
    dragState.current.dragging = false;
  };

  const width = TIME_BUCKETS * CELL_W;
  const height = STOCKS.length * CELL_H;

  return (
    <div
      ref={containerRef}
      style={{
        width: "100%",
        height: "100%",
        overflow: "hidden",
        position: "relative",
        background: "#111"
      }}
      onWheel={handleWheel}
      onMouseMove={onMouseMove}
      onMouseUp={onMouseUp}
      onMouseLeave={onMouseUp}
    >
      <svg
        ref={svgRef}
        width="100%"
        height="100%"
        style={{ cursor: dragState.current.dragging ? "grabbing" : "grab" }}
        onMouseDown={onMouseDown}
      >
        <g transform={`translate(${transform.x}, ${transform.y}) scale(${transform.k})`}>
          {data.map((stock, row) =>
            stock.values.map((cell, col) => {
              const x = col * CELL_W;
              const y = row * CELL_H;
              return (
                <rect
                  key={`${stock.symbol}-${cell.t}`}
                  x={x}
                  y={y}
                  width={CELL_W - 1}
                  height={CELL_H - 1}
                  fill={colorScale(cell.change)}
                  stroke="#222"
                  onMouseEnter={() =>
                    setHovered({
                      symbol: stock.symbol,
                      ...cell,
                      row,
                      col
                    })
                  }
                  onMouseLeave={() => setHovered(null)}
                />
              );
            })
          )}

          {/* Row labels */}
          {data.map((stock, row) => (
            <text
              key={stock.symbol}
              x={-8}
              y={row * CELL_H + CELL_H * 0.7}
              textAnchor="end"
              fill="#fff"
              fontSize="12"
            >
              {stock.symbol}
            </text>
          ))}
        </g>
      </svg>

      {/* Tooltip */}
      {hovered && (
        <div
          style={{
            position: "absolute",
            left: 16,
            top: 16,
            padding: "8px 10px",
            background: "rgba(0,0,0,0.8)",
            color: "#fff",
            border: "1px solid #444",
            borderRadius: 6,
            fontSize: 12,
            pointerEvents: "none"
          }}
        >
          <div><strong>{hovered.symbol}</strong></div>
          <div>Price: {hovered.price.toFixed(2)}</div>
          <div>Change: {hovered.change.toFixed(2)}%</div>
          <div>Time: {new Date(hovered.t).toLocaleTimeString()}</div>
        </div>
      )}
    </div>
  );
}
