## Example implementation

### `StockHeatmap.jsx`

```jsx
import React, { useEffect, useMemo, useRef, useState } from "react";

const INITIAL_STOCKS = [
  { symbol: "AAPL", name: "Apple", price: 189.12, change: 0.8 },
  { symbol: "MSFT", name: "Microsoft", price: 412.55, change: -0.4 },
  { symbol: "GOOGL", name: "Alphabet", price: 173.21, change: 1.2 },
  { symbol: "AMZN", name: "Amazon", price: 178.44, change: -1.1 },
  { symbol: "TSLA", name: "Tesla", price: 242.88, change: 2.4 },
  { symbol: "NVDA", name: "NVIDIA", price: 124.77, change: 3.1 },
  { symbol: "META", name: "Meta", price: 498.33, change: -0.7 },
  { symbol: "NFLX", name: "Netflix", price: 645.19, change: 0.5 },
  { symbol: "AMD", name: "AMD", price: 156.02, change: -2.2 },
  { symbol: "INTC", name: "Intel", price: 34.88, change: 0.1 },
  { symbol: "ORCL", name: "Oracle", price: 141.66, change: 0.9 },
  { symbol: "CRM", name: "Salesforce", price: 267.44, change: -0.3 },
];

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function getColor(change) {
  // change is percent, map to red/green intensity
  const maxAbs = 5;
  const normalized = clamp(change / maxAbs, -1, 1);

  if (normalized >= 0) {
    const intensity = Math.floor(255 - normalized * 140);
    return `rgb(${intensity}, 255, ${intensity})`;
  } else {
    const intensity = Math.floor(255 + normalized * 140);
    return `rgb(255, ${intensity}, ${intensity})`;
  }
}

function simulateUpdate(stock) {
  const delta = (Math.random() - 0.5) * 2.5;
  const newChange = clamp(stock.change + delta * 0.15, -10, 10);
  const newPrice = Math.max(0.01, stock.price * (1 + delta / 100));
  return {
    ...stock,
    price: Number(newPrice.toFixed(2)),
    change: Number(newChange.toFixed(2)),
  };
}

export default function StockHeatmap() {
  const [stocks, setStocks] = useState(INITIAL_STOCKS);
  const [hovered, setHovered] = useState(null);
  const [view, setView] = useState({ scale: 1, x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const dragStartRef = useRef(null);
  const containerRef = useRef(null);

  // Real-time updates
  useEffect(() => {
    const id = setInterval(() => {
      setStocks((prev) => prev.map(simulateUpdate));
    }, 1000);

    return () => clearInterval(id);
  }, []);

  const layout = useMemo(() => {
    const cols = 4;
    const cellW = 180;
    const cellH = 110;
    const gap = 12;

    return stocks.map((stock, index) => {
      const row = Math.floor(index / cols);
      const col = index % cols;
      return {
        ...stock,
        x: col * (cellW + gap),
        y: row * (cellH + gap),
        w: cellW,
        h: cellH,
      };
    });
  }, [stocks]);

  const onWheel = (e) => {
    e.preventDefault();
    const zoomFactor = e.deltaY > 0 ? 0.92 : 1.08;

    setView((prev) => ({
      ...prev,
      scale: clamp(prev.scale * zoomFactor, 0.5, 3),
    }));
  };

  const onMouseDown = (e) => {
    setDragging(true);
    dragStartRef.current = { x: e.clientX, y: e.clientY, vx: view.x, vy: view.y };
  };

  const onMouseMove = (e) => {
    if (dragging && dragStartRef.current) {
      const dx = e.clientX - dragStartRef.current.x;
      const dy = e.clientY - dragStartRef.current.y;
      setView((prev) => ({
        ...prev,
        x: dragStartRef.current.vx + dx,
        y: dragStartRef.current.vy + dy,
      }));
    }
  };

  const onMouseUp = () => {
    setDragging(false);
    dragStartRef.current = null;
  };

  return (
    <div
      ref={containerRef}
      style={{
        width: "100%",
        height: "100vh",
        background: "#0b1020",
        color: "#fff",
        overflow: "hidden",
        position: "relative",
        fontFamily: "system-ui, sans-serif",
      }}
      onWheel={onWheel}
      onMouseMove={onMouseMove}
      onMouseUp={onMouseUp}
      onMouseLeave={onMouseUp}
    >
      <div style={{ padding: "12px 16px", position: "absolute", zIndex: 2 }}>
        <h2 style={{ margin: 0 }}>Stock Price Heatmap</h2>
        <div style={{ fontSize: 13, opacity: 0.8 }}>
          Scroll to zoom • Drag to pan • Live updates every second
        </div>
      </div>

      {hovered && (
        <div
          style={{
            position: "absolute",
            left: hovered.mouseX + 12,
            top: hovered.mouseY + 12,
            background: "rgba(20, 25, 40, 0.95)",
            border: "1px solid rgba(255,255,255,0.15)",
            borderRadius: 8,
            padding: "10px 12px",
            pointerEvents: "none",
            zIndex: 3,
            minWidth: 180,
            boxShadow: "0 8px 24px rgba(0,0,0,0.35)",
          }}
        >
          <div style={{ fontWeight: 700 }}>{hovered.symbol}</div>
          <div style={{ fontSize: 13, opacity: 0.85 }}>{hovered.name}</div>
          <div style={{ marginTop: 8, fontSize: 13 }}>
            Price: <b>${hovered.price}</b>
          </div>
          <div style={{ fontSize: 13 }}>
            Change:{" "}
            <b style={{ color: hovered.change >= 0 ? "#7CFF7C" : "#FF7C7C" }}>
              {hovered.change >= 0 ? "+" : ""}
              {hovered.change}%
            </b>
          </div>
        </div>
      )}

      <svg
        width="100%"
        height="100%"
        style={{ display: "block", cursor: dragging ? "grabbing" : "grab" }}
      >
        <g transform={`translate(${view.x}, ${view.y}) scale(${view.scale})`}>
          {layout.map((stock) => (
            <g
              key={stock.symbol}
              transform={`translate(${stock.x}, ${stock.y})`}
              onMouseEnter={(e) =>
                setHovered({
                  ...stock,
                  mouseX: e.clientX,
                  mouseY: e.clientY,
                })
              }
              onMouseMove={(e) =>
                setHovered((prev) =>
                  prev
                    ? {
                        ...prev,
                        mouseX: e.clientX,
                        mouseY: e.clientY,
                      }
                    : prev
                )
              }
              onMouseLeave={() => setHovered(null)}
            >
              <rect
                width={stock.w}
                height={stock.h}
                rx={12}
                ry={12}
                fill={getColor(stock.change)}
                stroke="rgba(255,255,255,0.12)"
                strokeWidth="1"
              />
              <text
                x={14}
                y={28}
                fill="#111"
                fontSize="18"
                fontWeight="700"
              >
                {stock.symbol}
              </text>
              <text x={14} y={52} fill="#111" fontSize="12" opacity="0.9">
                {stock.name}
              </text>
              <text x={14} y={78} fill="#111" fontSize="14" fontWeight="600">
                ${stock.price}
              </text>
              <text
                x={stock.w - 14}
                y={78}
                fill="#111"
                fontSize="14"
                fontWeight="700"
                textAnchor="end"
              >
                {stock.change >= 0 ? "+" : ""}
                {stock.change}%
              </text>
            </g>
          ))}
        </g>
      </svg>

      <div
        style={{
          position: "absolute",
          right: 16,
          bottom: 16,
          background: "rgba(20,25,40,0.9)",
          border: "1px solid rgba(255,255,255,0.12)",
          borderRadius: 10,
          padding: "10px 12px",
          fontSize: 12,
          zIndex: 2,
        }}
      >
        <div>Green = positive change</div>
        <div>Red = negative change</div>
      </div>
    </div>
  );
}
