  { symbol: "MSFT", name: "Microsoft", price: 412.44, change: -0.3 },
  { symbol: "GOOGL", name: "Alphabet", price: 173.21, change: 1.2 },
  { symbol: "AMZN", name: "Amazon", price: 184.55, change: -1.1 },
  { symbol: "NVDA", name: "NVIDIA", price: 124.88, change: 2.4 },
  { symbol: "META", name: "Meta", price: 498.33, change: 0.2 },
  { symbol: "TSLA", name: "Tesla", price: 221.77, change: -2.8 },
  { symbol: "NFLX", name: "Netflix", price: 642.19, change: 1.6 },
  { symbol: "AMD", name: "AMD", price: 156.02, change: 0.9 },
  { symbol: "INTC", name: "Intel", price: 32.15, change: -0.6 },
  { symbol: "ORCL", name: "Oracle", price: 141.22, change: 0.4 },
  { symbol: "CRM", name: "Salesforce", price: 267.89, change: -0.2 },
  { symbol: "UBER", name: "Uber", price: 72.44, change: 1.1 },
  { symbol: "DIS", name: "Disney", price: 98.31, change: -0.9 },
  { symbol: "BA", name: "Boeing", price: 184.67, change: 0.5 },
  { symbol: "JPM", name: "JPMorgan", price: 204.12, change: -0.4 },
];

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function getHeatColor(change) {
  // change is percent-ish; clamp to [-5, 5]
  const c = clamp(change, -5, 5);
  const t = Math.abs(c) / 5;

  if (c > 0) {
    // green scale
    const g = Math.round(80 + 140 * t);
    const r = Math.round(20 + 30 * (1 - t));
    const b = Math.round(20 + 30 * (1 - t));
    return `rgb(${r}, ${g}, ${b})`;
  } else if (c < 0) {
    // red scale
    const r = Math.round(80 + 140 * t);
    const g = Math.round(20 + 30 * (1 - t));
    const b = Math.round(20 + 30 * (1 - t));
    return `rgb(${r}, ${g}, ${b})`;
  }
  return "rgb(60, 60, 60)";
}

function generateGridLayout(items, cols = 4, cellW = 180, cellH = 120, gap = 12) {
  return items.map((item, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    return {
      ...item,
      x: col * (cellW + gap),
      y: row * (cellH + gap),
      width: cellW,
      height: cellH,
    };
  });
}

export default function StockHeatmap() {
  const [stocks, setStocks] = useState(INITIAL_STOCKS);
  const [hovered, setHovered] = useState(null);
  const [view, setView] = useState({ scale: 1, tx: 20, ty: 20 });
  const [dragging, setDragging] = useState(false);
  const dragRef = useRef({ startX: 0, startY: 0, startTx: 0, startTy: 0 });
  const svgRef = useRef(null);

  // Simulate real-time updates
  useEffect(() => {
    const id = setInterval(() => {
      setStocks((prev) =>
        prev.map((s) => {
          const delta = (Math.random() - 0.5) * 1.2; // random price movement
          const newPrice = Math.max(0.01, s.price + delta);
          const pctChange = ((newPrice - s.price) / s.price) * 100;

          return {
            ...s,
            price: Number(newPrice.toFixed(2)),
            change: Number((s.change + pctChange * 0.2).toFixed(2)),
          };
        })
      );
    }, 1000);

    return () => clearInterval(id);
  }, []);

  const layout = useMemo(() => generateGridLayout(stocks, 4), [stocks]);

  const handleWheel = (e) => {
    e.preventDefault();
    const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
    setView((v) => ({
      ...v,
      scale: clamp(v.scale * zoomFactor, 0.5, 3),
    }));
  };

  const handleMouseDown = (e) => {
    setDragging(true);
    dragRef.current = {
      startX: e.clientX,
      startY: e.clientY,
      startTx: view.tx,
      startTy: view.ty,
    };
  };

  const handleMouseMove = (e) => {
    if (!dragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    setView((v) => ({
      ...v,
      tx: dragRef.current.startTx + dx,
      ty: dragRef.current.startTy + dy,
    }));
  };

  const handleMouseUp = () => setDragging(false);
  const handleMouseLeave = () => {
    setDragging(false);
    setHovered(null);
  };

  return (
    <div style={styles.container}>
      <div style={styles.header}>
        <div>
          <h2 style={styles.title}>Stock Price Heatmap</h2>
          <div style={styles.subtitle}>Real-time updates • Zoom with wheel • Pan by dragging</div>
        </div>
        <div style={styles.legend}>
          <span style={{ ...styles.legendItem, background: getHeatColor(-5) }}>Down</span>
          <span style={{ ...styles.legendItem, background: getHeatColor(0) }}>Flat</span>
          <span style={{ ...styles.legendItem, background: getHeatColor(5) }}>Up</span>
        </div>
      </div>

      <div
        style={styles.viewport}
        onWheel={handleWheel}
        onMouseDown={handleMouseDown}
        onMouseMove={handleMouseMove}
        onMouseUp={handleMouseUp}
        onMouseLeave={handleMouseLeave}
      >
        <svg
          ref={svgRef}
          width="100%"
          height="100%"
          viewBox="0 0 900 700"
          style={{ cursor: dragging ? "grabbing" : "grab" }}
        >
          <g transform={`translate(${view.tx}, ${view.ty}) scale(${view.scale})`}>
            {layout.map((stock) => (
              <g
                key={stock.symbol}
                transform={`translate(${stock.x}, ${stock.y})`}
                onMouseEnter={() => setHovered(stock)}
                onMouseLeave={() => setHovered(null)}
              >
                <rect
                  width={stock.width}
                  height={stock.height}
                  rx="14"
                  ry="14"
                  fill={getHeatColor(stock.change)}
                  stroke="rgba(255,255,255,0.12)"
                  strokeWidth="1"
                />
                <text x="14" y="28" fill="#fff" fontSize="18" fontWeight="700">
                  {stock.symbol}
                </text>
                <text x="14" y="52" fill="rgba(255,255,255,0.85)" fontSize="12">
                  {stock.name}
                </text>
                <text x="14" y="82" fill="#fff" fontSize="16" fontWeight="600">
                  ${stock.price.toFixed(2)}
                </text>
                <text x="14" y="102" fill="rgba(255,255,255,0.9)" fontSize="12">
                  {stock.change >= 0 ? "+" : ""}
                  {stock.change.toFixed(2)}%
                </text>
              </g>
            ))}
          </g>
        </svg>

        {hovered && (
          <div
            style={{
              ...styles.tooltip,
              left: 20,
              top: 20,
            }}
          >
            <div style={{ fontWeight: 700, marginBottom: 4 }}>
              {hovered.symbol} — {hovered.name}
            </div>
            <div>Price: ${hovered.price.toFixed(2)}</div>
            <div>
              Change:{" "}
              <span style={{ color: hovered.change >= 0 ? "#7CFC98" : "#FF7B7B" }}>
                {hovered.change >= 0 ? "+" : ""}
                {hovered.change.toFixed(2)}%
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

