<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="status" id="status">Live updates: connected</div>
      <div class="spacer"></div>
      <div class="legend">
        <span>Down</span>
        <div class="legend-bar"></div>
        <span>Up</span>
      </div>
      <button id="resetBtn">Reset View</button>
    </div>

    <div class="viewport" id="viewport">
      <div class="heatmap" id="heatmap"></div>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const viewport = document.getElementById("viewport");
    const heatmap = document.getElementById("heatmap");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");
    const statusEl = document.getElementById("status");

    // Sample stock universe
    const stocks = [
      { symbol: "AAPL", name: "Apple Inc." },
      { symbol: "MSFT", name: "Microsoft Corp." },
      { symbol: "GOOGL", name: "Alphabet Inc." },
      { symbol: "AMZN", name: "Amazon.com Inc." },
      { symbol: "NVDA", name: "NVIDIA Corp." },
      { symbol: "META", name: "Meta Platforms" },
      { symbol: "TSLA", name: "Tesla Inc." },
      { symbol: "JPM", name: "JPMorgan Chase" },
      { symbol: "V", name: "Visa Inc." },
      { symbol: "UNH", name: "UnitedHealth Group" },
      { symbol: "XOM", name: "Exxon Mobil" },
      { symbol: "LLY", name: "Eli Lilly" },
      { symbol: "AVGO", name: "Broadcom Inc." },
      { symbol: "COST", name: "Costco Wholesale" },
      { symbol: "MA", name: "Mastercard Inc." },
      { symbol: "HD", name: "Home Depot" },
      { symbol: "PG", name: "Procter & Gamble" },
      { symbol: "BAC", name: "Bank of America" },
      { symbol: "ADBE", name: "Adobe Inc." },
      { symbol: "CRM", name: "Salesforce Inc." },
      { symbol: "NFLX", name: "Netflix Inc." },
      { symbol: "KO", name: "Coca-Cola Co." },
      { symbol: "PEP", name: "PepsiCo Inc." },
      { symbol: "INTC", name: "Intel Corp." }
    ];

    // State
    const state = {
      scale: 1,
      translateX: 0,
      translateY: 0,
      isDragging: false,
      dragStartX: 0,
      dragStartY: 0,
      startTranslateX: 0,
      startTranslateY: 0,
      cells: new Map()
    };

    // Initialize stock data
    function randomBetween(min, max) {
      return Math.random() * (max - min) + min;
    }

    function initData() {
      return stocks.map((s) => {
        const base = randomBetween(50, 500);
        const changePct = randomBetween(-4, 4);
        const price = base * (1 + changePct / 100);
        return {
          ...s,
          basePrice: base,
          price,
          prevPrice: price,
          changePct
        };
      });
    }

    let data = initData();

    function formatPrice(v) {
      return `$${v.toFixed(2)}`;
    }

    function formatPct(v) {
      const sign = v >= 0 ? "+" : "";
      return `${sign}${v.toFixed(2)}%`;
    }

    // Color scale: red -> dark -> green
    function getColor(changePct) {
      const clamped = Math.max(-5, Math.min(5, changePct));
      const t = (clamped + 5) / 10; // 0..1
      // interpolate between red, neutral, green
      const red = [185, 28, 28];
      const neutral = [31, 41, 55];
      const green = [21, 128, 61];

      let a, b, localT;
      if (t < 0.5) {
        a = red; b = neutral; localT = t / 0.5;
      } else {
        a = neutral; b = green; localT = (t - 0.5) / 0.5;
      }

      const rgb = a.map((av, i) => Math.round(av + (b[i] - av) * localT));
      return `rgb(${rgb[0]}, ${rgb[1]}, ${rgb[2]})`;
    }

    function textColorForBg(changePct) {
      return Math.abs(changePct) < 1.2 ? "#e8eefc" : "#ffffff";
    }

    function render() {
      heatmap.innerHTML = "";
      heatmap.style.gridTemplateColumns = "repeat(6, 120px)";
      heatmap.style.transform = `translate(${state.translateX}px, ${state.translateY}px) scale(${state.scale})`;

      data.forEach((stock) => {
        const cell = document.createElement("div");
        cell.className = "cell";
        cell.style.background = getColor(stock.changePct);
        cell.style.color = textColorForBg(stock.changePct);

        cell.innerHTML = `
          <div>
            <div class="symbol">${stock.symbol}</div>
            <div class="name">${stock.name}</div>
          </div>
          <div class="price-row">
            <div class="price">${formatPrice(stock.price)}</div>
            <div class="change">${formatPct(stock.changePct)}</div>
          </div>
        `;

        cell.addEventListener("mouseenter", (e) => showTooltip(e, stock));
        cell.addEventListener("mousemove", (e) => moveTooltip(e));
        cell.addEventListener("mouseleave", hideTooltip);

        heatmap.appendChild(cell);
        state.cells.set(stock.symbol, cell);
      });
    }

    function updateCells() {
      data.forEach((stock) => {
        const cell = state.cells.get(stock.symbol);
        if (!cell) return;

        cell.style.background = getColor(stock.changePct);
        cell.style.color = textColorForBg(stock.changePct);
        cell.querySelector(".price").textContent = formatPrice(stock.price);
        cell.querySelector(".change").textContent = formatPct(stock.changePct);
      });
    }

    function simulateRealTimeUpdate() {
      data = data.map((stock) => {
        const drift = randomBetween(-0.8, 0.8);
        const volatility = randomBetween(-1.2, 1.2);
        const newChange = Math.max(-10, Math.min(10, stock.changePct + drift + volatility * 0.2));
        const newPrice = Math.max(1, stock.basePrice * (1 + newChange / 100));
        return {
          ...stock,
          prevPrice: stock.price,
          price: newPrice,
          changePct: newChange
        };
      });

      updateCells();
      statusEl.textContent = `Live updates: ${new Date().toLocaleTimeString()}`;
    }

    // Tooltip
    function showTooltip(e, stock) {
      tooltip.classList.add("visible");
      tooltip.innerHTML = `
        <strong>${stock.symbol}</strong> — ${stock.name}<br/>
        Price: ${formatPrice(stock.price)}<br/>
        Change: ${formatPct(stock.changePct)}<br/>
        Base: ${formatPrice(stock.basePrice)}
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
    }

    function hideTooltip() {
      tooltip.classList.remove("visible");
    }

    // Zoom and pan
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = 1.08;
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const prevScale = state.scale;
      const nextScale = e.deltaY < 0 ? prevScale * zoomFactor : prevScale / zoomFactor;
      const clampedScale = Math.max(0.5, Math.min(3, nextScale));

      // Zoom around cursor
      const worldX = (mouseX - state.translateX) / prevScale;
      const worldY = (mouseY - state.translateY) / prevScale;

      state.translateX = mouseX - worldX * clampedScale;
      state.translateY = mouseY - worldY * clampedScale;
      state.scale = clampedScale;

      applyTransform();
    }, { passive: false });

    viewport.addEventListener("mousedown", (e) => {
      state.isDragging = true;
      viewport.classList.add("dragging");
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.startTranslateX = state.translateX;
      state.startTranslateY = state.translateY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.isDragging) return;
      state.translateX = state.startTranslateX + (e.clientX - state.dragStartX);
      state.translateY = state.startTranslateY + (e.clientY - state.dragStartY);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      state.isDragging = false;
      viewport.classList.remove("dragging");
    });

    function applyTransform() {
      heatmap.style.transform = `translate(${state.translateX}px, ${state.translateY}px) scale(${state.scale})`;
    }

    resetBtn.addEventListener("click", () => {
      state.scale = 1;
      state.translateX = 0;
      state.translateY = 0;
      applyTransform();
    });

    // Initial render
    render();

    // Simulated real-time updates
    setInterval(simulateRealTimeUpdate, 1000);

    // Resize handling
    window.addEventListener("resize", () => {
      // no-op for now, but useful for future layout logic
    });
  </script>
</body>
</html>
