<body>
  <div class="app">
    <div class="toolbar">
      <h1>Stock Price Heatmap</h1>
      <div class="status" id="status">Connecting…</div>
      <button id="resetBtn">Reset View</button>
      <div class="legend">
        <span>Loss</span>
        <div class="legend-bar"></div>
        <span>Gain</span>
      </div>
    </div>

    <div class="viewport" id="viewport">
      <canvas id="heatmap"></canvas>
      <div class="tooltip" id="tooltip"></div>
      <div class="hint">Wheel = zoom · Drag = pan · Hover = inspect</div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const viewport = document.getElementById('viewport');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');

    // ----- Data model -----
    const symbols = [
      'AAPL', 'MSFT', 'GOOGL', 'AMZN', 'NVDA',
      'TSLA', 'META', 'NFLX', 'AMD', 'INTC',
      'ORCL', 'CRM', 'UBER', 'SHOP', 'SQ'
    ];

    const timeBuckets = 60; // columns
    const rows = symbols.length;

    // Each cell stores a price change percentage, e.g. -3.2 to +3.2
    const data = Array.from({ length: rows }, () =>
      Array.from({ length: timeBuckets }, () => randomChange())
    );

    function randomChange() {
      return (Math.random() - 0.5) * 6; // -3% to +3%
    }

    // ----- View transform -----
    const view = {
      scale: 1,
      offsetX: 0,
      offsetY: 0
    };

    function resetView() {
      view.scale = 1;
      view.offsetX = 0;
      view.offsetY = 0;
      render();
    }

    // ----- Canvas sizing -----
    let dpr = window.devicePixelRatio || 1;
    function resizeCanvas() {
      const rect = viewport.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * dpr);
      canvas.height = Math.floor(rect.height * dpr);
      canvas.style.width = rect.width + 'px';
      canvas.style.height = rect.height + 'px';
      render();
    }

    window.addEventListener('resize', resizeCanvas);

    // ----- Real-time updates (simulated) -----
    let connected = false;
    function startFeed() {
      connected = true;
      statusEl.textContent = 'Live updates active';
      setInterval(() => {
        // Shift left and append new values
        for (let r = 0; r < rows; r++) {
          data[r].shift();
          // Slightly correlated random walk for realism
          const prev = data[r][data[r].length - 1] || 0;
          const next = clamp(prev + (Math.random() - 0.5) * 1.2, -8, 8);
          data[r].push(next);
        }
        render();
      }, 1000);
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    // ----- Color mapping -----
    function getColor(value) {
      // value in [-8, 8]
      const maxAbs = 8;
      const t = clamp(value / maxAbs, -1, 1);

      // Neutral around 0
      if (Math.abs(t) < 0.08) return 'rgba(148, 163, 184, 0.35)';

      if (t > 0) {
        // Green scale
        const alpha = 0.25 + 0.75 * t;
        return `rgba(34, 197, 94, ${alpha})`;
      } else {
        // Red scale
        const alpha = 0.25 + 0.75 * Math.abs(t);
        return `rgba(239, 68, 68, ${alpha})`;
      }
    }

    // ----- Rendering -----
    function render() {
      const rect = viewport.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, width, height);

      // Background
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);

      const cellW = 80 * view.scale;
      const cellH = 34 * view.scale;
      const labelW = 90 * view.scale;
      const labelH = 24 * view.scale;

      const startX = view.offsetX + labelW;
      const startY = view.offsetY + labelH;

      // Draw grid cells
      for (let r = 0; r < rows; r++) {
        const y = startY + r * cellH;

        // Row label
        ctx.fillStyle = '#e5e7eb';
        ctx.font = `${12 * view.scale}px Inter, sans-serif`;
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText(symbols[r], startX - 10, y + cellH / 2);

        for (let c = 0; c < timeBuckets; c++) {
          const x = startX + c * cellW;
          const val = data[r][c];

          ctx.fillStyle = getColor(val);
          ctx.fillRect(x, y, cellW - 1, cellH - 1);

          // Cell border
          ctx.strokeStyle = 'rgba(255,255,255,0.06)';
          ctx.strokeRect(x, y, cellW - 1, cellH - 1);
        }
      }

      // Column labels
      ctx.fillStyle = '#94a3b8';
      ctx.font = `${11 * view.scale}px Inter, sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';

      for (let c = 0; c < timeBuckets; c += 5) {
        const x = startX + c * cellW + cellW / 2;
        ctx.fillText(`T-${timeBuckets - c}`, x, startY - 10);
      }

      // Top-left corner label
      ctx.fillStyle = '#94a3b8';
      ctx.textAlign = 'left';
      ctx.fillText('Symbol', 12, 16);
      ctx.textAlign = 'center';
      ctx.fillText('Time', startX + (timeBuckets * cellW) / 2, 16);
    }

    // ----- Hit testing for hover -----
    function getCellAt(clientX, clientY) {
      const rect = viewport.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const cellW = 80 * view.scale;
      const cellH = 34 * view.scale;
      const labelW = 90 * view.scale;
      const labelH = 24 * view.scale;
      const startX = view.offsetX + labelW;
      const startY = view.offsetY + labelH;

      const col = Math.floor((x - startX) / cellW);
      const row = Math.floor((y - startY) / cellH);

      if (row < 0 || row >= rows || col < 0 || col >= timeBuckets) return null;

      const cellX = startX + col * cellW;
      const cellY = startY + row * cellH;

      if (x < cellX || x > cellX + cellW || y < cellY || y > cellY + cellH) return null;

      return { row, col, x: cellX, y: cellY };
    }

    viewport.addEventListener('mousemove', (e) => {
      if (dragging) {
        const dx = e.clientX - lastX;
        const dy = e.clientY - lastY;
        view.offsetX += dx;
        view.offsetY += dy;
        lastX = e.clientX;
        lastY = e.clientY;
        render();
        return;
      }

      const hit = getCellAt(e.clientX, e.clientY);
      if (!hit) {
        tooltip.style.display = 'none';
        return;
      }

      const value = data[hit.row][hit.col];
      tooltip.style.display = 'block';
      tooltip.style.left = `${e.clientX - viewport.getBoundingClientRect().left}px`;
      tooltip.style.top = `${e.clientY - viewport.getBoundingClientRect().top}px`;
      tooltip.innerHTML = `
        <strong>${symbols[hit.row]}</strong><br/>
        Bucket: ${timeBuckets - hit.col}<br/>
        Change: <span style="color:${value >= 0 ? '#4ade80' : '#f87171'}">${value.toFixed(2)}%</span>
      `;
    });

    viewport.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
    });

    // ----- Pan interaction -----
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      lastX = e.clientX;
      lastY = e.clientY;
      viewport.classList.add('dragging');
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    // ----- Zoom interaction -----
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      // Zoom around cursor
      const prevScale = view.scale;
      const nextScale = clamp(view.scale * zoomFactor, 0.6, 3);

      const scaleRatio = nextScale / prevScale;
      view.offsetX = mouseX - (mouseX - view.offsetX) * scaleRatio;
      view.offsetY = mouseY - (mouseY - view.offsetY) * scaleRatio;
      view.scale = nextScale;

      render();
    }, { passive: false });

    resetBtn.addEventListener('click', resetView);

    // ----- Initialize -----
    resizeCanvas();
    resetView();
    startFeed();
  </script>
</body>
</html>
```

