</head>
<body>
  <div class="app">
    <div class="toolbar">
      <button id="zoomIn">Zoom In</button>
      <button id="zoomOut">Zoom Out</button>
      <button id="resetView">Reset</button>
      <div class="legend">
        <span>Change</span>
        <div class="legend-bar"></div>
        <span>Negative → Positive</span>
      </div>
      <div class="status" id="status">Initializing...</div>
    </div>

    <div class="viewport" id="viewport">
      <svg id="svg"></svg>
      <div class="tooltip" id="tooltip"></div>
    </div>
  </div>

  <script>
    const svg = document.getElementById("svg");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const statusEl = document.getElementById("status");

    const zoomInBtn = document.getElementById("zoomIn");
    const zoomOutBtn = document.getElementById("zoomOut");
    const resetViewBtn = document.getElementById("resetView");

    const NS = "http://www.w3.org/2000/svg";

    // --- Data setup ---
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX",
      "AMD","INTC","ORCL","CRM","ADBE","IBM","QCOM","AVGO",
      "JPM","BAC","WFC","C","GS","MS","AXP","V",
      "MA","PYPL","SQ","SHOP","UBER","LYFT","SNAP","PINS"
    ];

    const stocks = symbols.map((symbol, i) => ({
      symbol,
      price: 100 + Math.random() * 900,
      prevPrice: null,
      changePct: 0,
      volume: Math.floor(1e6 + Math.random() * 9e6),
      sector: ["Tech","Finance","Payments","Consumer"][i % 4]
    }));

    // --- Layout ---
    const cols = 8;
    const cellW = 140;
    const cellH = 90;
    const gap = 12;
    const padding = 20;

    const rows = Math.ceil(stocks.length / cols);
    const contentW = cols * (cellW + gap) - gap + padding * 2;
    const contentH = rows * (cellH + gap) - gap + padding * 2;

    svg.setAttribute("viewBox", `0 0 ${contentW} ${contentH}`);

    // --- View transform state ---
    let scale = 1;
    let translateX = 0;
    let translateY = 0;
    let isDragging = false;
    let dragStart = { x: 0, y: 0 };
    let dragOrigin = { x: 0, y: 0 };

    function applyTransform() {
      svg.style.transformOrigin = "0 0";
      svg.style.transform = `translate(${translateX}px, ${translateY}px) scale(${scale})`;
    }

    function resetView() {
      scale = 1;
      translateX = 0;
      translateY = 0;
      applyTransform();
    }

    function zoomAt(factor, clientX, clientY) {
      const rect = viewport.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const beforeX = (x - translateX) / scale;
      const beforeY = (y - translateY) / scale;

      scale = Math.min(4, Math.max(0.5, scale * factor));

      translateX = x - beforeX * scale;
      translateY = y - beforeY * scale;

      applyTransform();
    }

    // --- Color scale ---
    function lerp(a, b, t) {
      return a + (b - a) * t;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function changeToColor(changePct) {
      // Map [-5, 5] to red -> neutral -> green
      const maxAbs = 5;
      const t = clamp(changePct / maxAbs, -1, 1);

      if (t < 0) {
        const p = Math.abs(t);
        const r = Math.round(lerp(17, 220, p));
        const g = Math.round(lerp(24, 38, p));
        const b = Math.round(lerp(39, 38, p));
        return `rgb(${r},${g},${b})`;
      } else {
        const p = t;
        const r = Math.round(lerp(17, 22, p));
        const g = Math.round(lerp(24, 163, p));
        const b = Math.round(lerp(39, 74, p));
        return `rgb(${r},${g},${b})`;
      }
    }

    // --- Rendering ---
    const cellMap = new Map();

    function createCell(stock, index) {
      const g = document.createElementNS(NS, "g");
      g.classList.add("cell");

      const col = index % cols;
      const row = Math.floor(index / cols);

      const x = padding + col * (cellW + gap);
      const y = padding + row * (cellH + gap);

      g.setAttribute("transform", `translate(${x}, ${y})`);

      const rect = document.createElementNS(NS, "rect");
      rect.setAttribute("width", cellW);
      rect.setAttribute("height", cellH);
      rect.setAttribute("fill", changeToColor(stock.changePct));

      const symbolText = document.createElementNS(NS, "text");
      symbolText.setAttribute("x", cellW / 2);
      symbolText.setAttribute("y", 28);
      symbolText.textContent = stock.symbol;
      symbolText.style.fontSize = "16px";

      const priceText = document.createElementNS(NS, "text");
      priceText.setAttribute("x", cellW / 2);
      priceText.setAttribute("y", 52);
      priceText.textContent = `$${stock.price.toFixed(2)}`;

      const changeText = document.createElementNS(NS, "text");
      changeText.setAttribute("x", cellW / 2);
      changeText.setAttribute("y", 72);
      changeText.textContent = `${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%`;
      changeText.style.fontSize = "11px";
      changeText.style.fill = "rgba(255,255,255,0.85)";

      g.appendChild(rect);
      g.appendChild(symbolText);
      g.appendChild(priceText);
      g.appendChild(changeText);

      g.addEventListener("mouseenter", (e) => {
        tooltip.classList.add("visible");
        tooltip.innerHTML = `
          <strong>${stock.symbol}</strong><br/>
          Price: $${stock.price.toFixed(2)}<br/>
          Change: ${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%<br/>
          Volume: ${stock.volume.toLocaleString()}<br/>
          Sector: ${stock.sector}
        `;
      });

      g.addEventListener("mousemove", (e) => {
        const vpRect = viewport.getBoundingClientRect();
        tooltip.style.left = `${e.clientX - vpRect.left}px`;
        tooltip.style.top = `${e.clientY - vpRect.top}px`;
      });

      g.addEventListener("mouseleave", () => {
        tooltip.classList.remove("visible");
      });

      cellMap.set(stock.symbol, { g, rect, priceText, changeText, stock });
      return g;
    }

    function render() {
      svg.innerHTML = "";
      stocks.forEach((stock, i) => {
        svg.appendChild(createCell(stock, i));
      });
    }

    function updateCells() {
      stocks.forEach((stock) => {
        const cell = cellMap.get(stock.symbol);
        if (!cell) return;

        cell.rect.setAttribute("fill", changeToColor(stock.changePct));
        cell.priceText.textContent = `$${stock.price.toFixed(2)}`;
        cell.changeText.textContent = `${stock.changePct >= 0 ? "+" : ""}${stock.changePct.toFixed(2)}%`;
      });
    }

    // --- Simulated real-time updates ---
    function tickMarket() {
      stocks.forEach((stock) => {
        stock.prevPrice = stock.price;

        const drift = (Math.random() - 0.5) * 2.5;
        const shock = (Math.random() - 0.5) * 1.2;
        const deltaPct = (drift + shock) / 100;

        stock.price = Math.max(1, stock.price * (1 + deltaPct));
        stock.changePct = ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;
        stock.volume = Math.max(1000, stock.volume + Math.floor((Math.random() - 0.5) * 50000));
      });

      updateCells();
      statusEl.textContent = `Last updated: ${new Date().toLocaleTimeString()}`;
    }

    // --- Interaction handlers ---
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.1 : 0.9;
      zoomAt(factor, e.clientX, e.clientY);
    }, { passive: false });

    viewport.addEventListener("mousedown", (e) => {
      isDragging = true;
      dragStart = { x: e.clientX, y: e.clientY };
      dragOrigin = { x: translateX, y: translateY };
      svg.classList.add("dragging");
    });

    window.addEventListener("mousemove", (e) => {
      if (!isDragging) return;
      translateX = dragOrigin.x + (e.clientX - dragStart.x);
      translateY = dragOrigin.y + (e.clientY - dragStart.y);
      applyTransform();
    });

    window.addEventListener("mouseup", () => {
      isDragging = false;
      svg.classList.remove("dragging");
    });

    zoomInBtn.addEventListener("click", () => zoomAt(1.2, window.innerWidth / 2, window.innerHeight / 2));
    zoomOutBtn.addEventListener("click", () => zoomAt(0.8, window.innerWidth / 2, window.innerHeight / 2));
    resetViewBtn.addEventListener("click", resetView);

    // --- Init ---
    render();
    resetView();
    tickMarket();
    setInterval(tickMarket, 1000);
  </script>
</body>
</html>
```

