    const cellWidth = 90;
    const cellHeight = 42;

    let scale = 1;
    let panX = 20;
    let panY = 20;
    let dragging = false;
    let dragStart = { x: 0, y: 0 };
    let panStart = { x: 0, y: 0 };

    // Data model: rows x timeBuckets
    const data = Array.from({ length: rows }, (_, r) =>
      Array.from({ length: timeBuckets }, (_, c) => ({
        symbol: symbols[r],
        bucket: c,
        price: 100 + Math.random() * 100,
        change: (Math.random() - 0.5) * 6
      }))
    );

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function changeToColor(change) {
      // Clamp to [-5, 5] and map to red -> neutral -> green
      const c = clamp(change, -5, 5);
      const t = (c + 5) / 10; // 0..1
      const red = { r: 217, g: 75, b: 75 };
      const mid = { r: 43, g: 58, b: 103 };
      const green = { r: 63, g: 209, b: 127 };

      let a, b, u;
      if (t < 0.5) {
        a = red; b = mid; u = t / 0.5;
      } else {
        a = mid; b = green; u = (t - 0.5) / 0.5;
      }

      const r = Math.round(a.r + (b.r - a.r) * u);
      const g = Math.round(a.g + (b.g - a.g) * u);
      const bl = Math.round(a.b + (b.b - a.b) * u);
      return `rgb(${r}, ${g}, ${bl})`;
    }

    function renderGrid() {
      grid.style.gridTemplateColumns = `repeat(${timeBuckets}, ${cellWidth}px)`;
      grid.innerHTML = "";

      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < timeBuckets; c++) {
          const cellData = data[r][c];
          const cell = document.createElement("div");
          cell.className = "cell";
          cell.dataset.row = r;
          cell.dataset.col = c;
          cell.style.background = changeToColor(cellData.change);

          cell.innerHTML = `
            <div class="symbol">${cellData.symbol}</div>
            <div class="value">${cellData.price.toFixed(2)} (${cellData.change >= 0 ? "+" : ""}${cellData.change.toFixed(2)}%)</div>
          `;

          cell.addEventListener("mouseenter", (e) => {
            showTooltip(e, cellData);
          });

          cell.addEventListener("mousemove", (e) => {
            moveTooltip(e);
          });

          cell.addEventListener("mouseleave", hideTooltip);

          grid.appendChild(cell);
        }
      }

      updateTransform();
    }

    function updateTransform() {
      canvas.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    function showTooltip(e, d) {
      tooltip.classList.add("visible");
      tooltip.innerHTML = `
        <div><strong>${d.symbol}</strong></div>
        <div>Price: $${d.price.toFixed(2)}</div>
        <div>Change: ${d.change >= 0 ? "+" : ""}${d.change.toFixed(2)}%</div>
        <div>Bucket: ${d.bucket}</div>
      `;
      moveTooltip(e);
    }

    function moveTooltip(e) {
      tooltip.style.left = `${e.clientX}px`;
      tooltip.style.top = `${e.clientY}px`;
    }

    function hideTooltip() {
      tooltip.classList.remove("visible");
    }

    function randomWalk(value, volatility = 1.2) {
      return value + (Math.random() - 0.5) * volatility;
    }

    function updateLiveData() {
      // Shift each row left and append a new bucket on the right
      for (let r = 0; r < rows; r++) {
        data[r].shift();

        const last = data[r][data[r].length - 1];
        const prevPrice = last ? last.price : 100;
        const newPrice = Math.max(1, randomWalk(prevPrice, 2.5));
        const change = ((newPrice - prevPrice) / prevPrice) * 100;

        data[r].push({
          symbol: symbols[r],
          bucket: Date.now(),
          price: newPrice,
          change: change
        });
      }

      renderGrid();
      statusEl.textContent = `Live updates: ${new Date().toLocaleTimeString()}`;
    }

    // Zoom around mouse pointer
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = clamp(scale * zoomFactor, 0.5, 3);

      // Keep mouse point stable during zoom
      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      scale = nextScale;
      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      updateTransform();
    }, { passive: false });

    viewport.addEventListener("mousedown", (e) => {
      dragging = true;
      viewport.classList.add("dragging");
      dragStart = { x: e.clientX, y: e.clientY };
      panStart = { x: panX, y: panY };
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      panX = panStart.x + (e.clientX - dragStart.x);
      panY = panStart.y + (e.clientY - dragStart.y);
      updateTransform();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    resetBtn.addEventListener("click", () => {
      scale = 1;
      panX = 20;
      panY = 20;
      updateTransform();
    });

    // Initial render
    renderGrid();

    // Simulated real-time updates
    setInterval(updateLiveData, 1000);
  </script>
</body>
</html>
```

