      color: #cbd5e1;
      backdrop-filter: blur(8px);
    }

    .hud strong {
      color: white;
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="heatmap"></canvas>
    <div id="tooltip" class="tooltip"></div>
    <div class="hud">
      <div><strong>Stock Heatmap</strong></div>
      <div>Wheel: zoom</div>
      <div>Drag: pan</div>
      <div>Hover: details</div>
    </div>
  </div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');
    const app = document.getElementById('app');

    let dpr = window.devicePixelRatio || 1;
    let width = 0;
    let height = 0;

    // View transform
    const view = {
      scale: 1,
      offsetX: 40,
      offsetY: 40
    };

    // Grid settings
    const cellSize = 90;
    const cellGap = 8;
    const cols = 10;

    // Mock stock data
    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','META','TSLA','NFLX','AMD','INTC',
      'ORCL','CRM','ADBE','QCOM','AVGO','CSCO','IBM','TXN','MU','NOW',
      'UBER','SHOP','SNOW','PANW','PLTR','SQ','PYPL','BIDU','BABA','SONY',
      'DIS','V','MA','JPM','BAC','WFC','GS','C','AXP','BLK'
    ];

    const stocks = symbols.map((symbol, i) => {
      const base = 50 + Math.random() * 450;
      return {
        symbol,
        name: symbol,
        price: base,
        prevPrice: base,
        changePct: 0,
        x: (i % cols) * (cellSize + cellGap),
        y: Math.floor(i / cols) * (cellSize + cellGap),
      };
    });

    function resize() {
      dpr = window.devicePixelRatio || 1;
      width = canvas.clientWidth;
      height = canvas.clientHeight;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    window.addEventListener('resize', resize);

    function worldToScreen(x, y) {
      return {
        x: x * view.scale + view.offsetX,
        y: y * view.scale + view.offsetY
      };
    }

    function screenToWorld(x, y) {
      return {
        x: (x - view.offsetX) / view.scale,
        y: (y - view.offsetY) / view.scale
      };
    }

    function getColor(changePct) {
      // Clamp to [-5, 5] for color intensity
      const v = Math.max(-5, Math.min(5, changePct));
      const t = Math.abs(v) / 5;

      if (v > 0) {
        // Green
        const g = Math.floor(80 + 150 * t);
        const r = Math.floor(20 + 30 * (1 - t));
        return `rgb(${r}, ${g}, ${40})`;
      } else if (v < 0) {
        // Red
        const r = Math.floor(80 + 150 * t);
        const g = Math.floor(20 + 30 * (1 - t));
        return `rgb(${r}, ${g}, ${40})`;
      }
      return 'rgb(70, 80, 95)';
    }

    function drawGridBackground() {
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);
    }

    function draw() {
      drawGridBackground();

      // Visible bounds in world space
      const invScale = 1 / view.scale;
      const left = (-view.offsetX) * invScale;
      const top = (-view.offsetY) * invScale;
      const right = left + width * invScale;
      const bottom = top + height * invScale;

      for (const stock of stocks) {
        const sx = stock.x;
        const sy = stock.y;
        const sw = cellSize;
        const sh = cellSize;

        if (sx + sw < left || sy + sh < top || sx > right || sy > bottom) continue;

        const p = worldToScreen(sx, sy);
        const size = cellSize * view.scale;
        const gap = cellGap * view.scale;

        const x = p.x;
        const y = p.y;
        const w = size;
        const h = size;

        // Cell
        ctx.fillStyle = getColor(stock.changePct);
        roundRect(ctx, x, y, w, h, 10 * view.scale);
        ctx.fill();

        // Border
        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.lineWidth = 1;
        ctx.stroke();

        // Text
        if (w > 45 && h > 45) {
          ctx.fillStyle = '#ffffff';
          ctx.font = `${Math.max(10, 14 * view.scale)}px system-ui, sans-serif`;
          ctx.textAlign = 'center';
          ctx.textBaseline = 'middle';

          ctx.fillText(stock.symbol, x + w / 2, y + h / 2 - 10 * view.scale);
          ctx.fillStyle = 'rgba(255,255,255,0.85)';
          ctx.font = `${Math.max(9, 12 * view.scale)}px system-ui, sans-serif`;
          ctx.fillText(stock.price.toFixed(2), x + w / 2, y + h / 2 + 10 * view.scale);
        }
      }

      requestAnimationFrame(draw);
    }

    function roundRect(ctx, x, y, w, h, r) {
      const radius = Math.max(0, Math.min(r, Math.min(w, h) / 2));
      ctx.beginPath();
      ctx.moveTo(x + radius, y);
      ctx.arcTo(x + w, y, x + w, y + h, radius);
      ctx.arcTo(x + w, y + h, x, y + h, radius);
      ctx.arcTo(x, y + h, x, y, radius);
      ctx.arcTo(x, y, x + w, y, radius);
      ctx.closePath();
    }

    // Real-time updates (mock stream)
    setInterval(() => {
      for (const stock of stocks) {
        stock.prevPrice = stock.price;

        // Random walk
        const delta = (Math.random() - 0.5) * stock.price * 0.01;
        stock.price = Math.max(1, stock.price + delta);
        stock.changePct = ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;
      }
    }, 500);

    // Interaction state
    let isDragging = false;
    let dragStart = { x: 0, y: 0 };
    let viewStart = { x: 0, y: 0 };

    canvas.addEventListener('mousedown', (e) => {
      isDragging = true;
      dragStart = { x: e.clientX, y: e.clientY };
      viewStart = { x: view.offsetX, y: view.offsetY };
    });

    window.addEventListener('mouseup', () => {
      isDragging = false;
    });

    window.addEventListener('mousemove', (e) => {
      if (isDragging) {
        view.offsetX = viewStart.x + (e.clientX - dragStart.x);
        view.offsetY = viewStart.y + (e.clientY - dragStart.y);
      }

      updateHover(e.clientX, e.clientY);
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = Math.exp(-e.deltaY * 0.001);
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const before = screenToWorld(mouseX, mouseY);

      view.scale = Math.max(0.3, Math.min(4, view.scale * zoomFactor));

      const after = screenToWorld(mouseX, mouseY);

      view.offsetX += (after.x - before.x) * view.scale;
      view.offsetY += (after.y - before.y) * view.scale;
    }, { passive: false });

    function updateHover(clientX, clientY) {
      const rect = canvas.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const world = screenToWorld(x, y);

      const found = stocks.find(stock => {
        return (
          world.x >= stock.x &&
          world.x <= stock.x + cellSize &&
          world.y >= stock.y &&
          world.y <= stock.y + cellSize
        );
      });

      if (found) {
        tooltip.style.display = 'block';
        tooltip.style.left = `${x}px`;
        tooltip.style.top = `${y}px`;
        tooltip.innerHTML = `
          <div><strong>${found.symbol}</strong></div>
          <div>Price: $${found.price.toFixed(2)}</div>
          <div>Change: ${found.changePct >= 0 ? '+' : ''}${found.changePct.toFixed(2)}%</div>
        `;
      } else {
        tooltip.style.display = 'none';
      }
    }

    // Touch support
    let touchStartDist = 0;
    let touchStartScale = 1;
    let touchStartCenter = null;
    let touchStartView = null;

    canvas.addEventListener('touchstart', (e) => {
      if (e.touches.length === 1) {
        const t = e.touches[0];
        isDragging = true;
        dragStart = { x: t.clientX, y: t.clientY };
        viewStart = { x: view.offsetX, y: view.offsetY };
      } else if (e.touches.length === 2) {
        isDragging = false;
        const [t1, t2] = e.touches;
        touchStartDist = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
        touchStartScale = view.scale;
        touchStartCenter = {
          x: (t1.clientX + t2.clientX) / 2,
          y: (t1.clientY + t2.clientY) / 2
        };
        touchStartView = { x: view.offsetX, y: view.offsetY };
      }
    }, { passive: true });

    canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      if (e.touches.length === 1 && isDragging) {
        const t = e.touches[0];
        view.offsetX = viewStart.x + (t.clientX - dragStart.x);
        view.offsetY = viewStart.y + (t.clientY - dragStart.y);
      } else if (e.touches.length === 2) {
        const [t1, t2] = e.touches;
        const dist = Math.hypot(t2.clientX - t1.clientX, t2.clientY - t1.clientY);
        const center = {
          x: (t1.clientX + t2.clientX) / 2,
          y: (t1.clientY + t2.clientY) / 2
        };

        const zoomFactor = dist / touchStartDist;
        const newScale = Math.max(0.3, Math.min(4, touchStartScale * zoomFactor));

        const before = screenToWorld(touchStartCenter.x, touchStartCenter.y);
        view.scale = newScale;
        const after = screenToWorld(touchStartCenter.x, touchStartCenter.y);

        view.offsetX = touchStartView.x + (center.x - touchStartCenter.x) + (after.x - before.x) * view.scale;
        view.offsetY = touchStartView.y + (center.y - touchStartCenter.y) + (after.y - before.y) * view.scale;
      }
    }, { passive: false });

    canvas.addEventListener('touchend', () => {
      isDragging = false;
    });

    // Init
    resize();
    draw();
  </script>
</body>
</html>
