      dragStartY: 0,
      dragPanX: 0,
      dragPanY: 0,
      hoveredIndex: -1,
      needsRender: true,
      lastUpdate: performance.now()
    };

    const symbols = [
      'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','BRK.B',
      'JPM','V','UNH','XOM','LLY','AVGO','COST','MA',
      'HD','PG','MRK','PEP','KO','ADBE','NFLX','CRM',
      'AMD','INTC','CSCO','QCOM','TMO','WMT','DIS','BAC'
    ];

    function initStocks() {
      state.stocks = symbols.map(symbol => {
        const price = 50 + Math.random() * 450;
        return {
          symbol,
          price,
          prevPrice: price,
          changePct: 0,
          volume: Math.floor(100000 + Math.random() * 900000)
        };
      });
      state.rows = Math.ceil(state.stocks.length / state.cols);
    }

    function resize() {
      state.dpr = Math.max(1, window.devicePixelRatio || 1);
      state.width = window.innerWidth;
      state.height = window.innerHeight;
      canvas.width = Math.floor(state.width * state.dpr);
      canvas.height = Math.floor(state.height * state.dpr);
      canvas.style.width = state.width + 'px';
      canvas.style.height = state.height + 'px';
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
      state.needsRender = true;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function priceToColor(changePct) {
      // Range roughly [-5%, +5%]
      const t = clamp((changePct + 5) / 10, 0, 1);
      const red = [185, 28, 28];
      const mid = [17, 24, 39];
      const green = [21, 128, 61];

      let c1, c2, localT;
      if (t < 0.5) {
        c1 = red; c2 = mid; localT = t / 0.5;
      } else {
        c1 = mid; c2 = green; localT = (t - 0.5) / 0.5;
      }

      const r = Math.round(c1[0] + (c2[0] - c1[0]) * localT);
      const g = Math.round(c1[1] + (c2[1] - c1[1]) * localT);
      const b = Math.round(c1[2] + (c2[2] - c1[2]) * localT);
      return `rgb(${r},${g},${b})`;
    }

    function updatePrices() {
      for (const stock of state.stocks) {
        stock.prevPrice = stock.price;
        const drift = (Math.random() - 0.5) * 2.5;
        stock.price = Math.max(1, stock.price + drift);
        stock.changePct = ((stock.price - stock.prevPrice) / stock.prevPrice) * 100;
        stock.volume = Math.max(1000, stock.volume + Math.floor((Math.random() - 0.5) * 50000));
      }
      state.lastUpdate = performance.now();
      state.needsRender = true;
    }

    function worldToScreen(x, y) {
      return {
        x: x * state.zoom + state.panX,
        y: y * state.zoom + state.panY
      };
    }

    function screenToWorld(x, y) {
      return {
        x: (x - state.panX) / state.zoom,
        y: (y - state.panY) / state.zoom
      };
    }

    function getCellRect(index) {
      const col = index % state.cols;
      const row = Math.floor(index / state.cols);
      const x = col * state.cellW;
      const y = row * state.cellH;
      return { x, y, w: state.cellW, h: state.cellH };
    }

    function findHoveredIndex(mx, my) {
      const world = screenToWorld(mx, my);
      const col = Math.floor(world.x / state.cellW);
      const row = Math.floor(world.y / state.cellH);
      if (col < 0 || col >= state.cols || row < 0 || row >= state.rows) return -1;
      const index = row * state.cols + col;
      return index >= 0 && index < state.stocks.length ? index : -1;
    }

    function draw() {
      if (!state.needsRender) return;
      state.needsRender = false;

      ctx.clearRect(0, 0, state.width, state.height);
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, state.width, state.height);

      // Center content if smaller than viewport
      const contentW = state.cols * state.cellW;
      const contentH = state.rows * state.cellH;

      ctx.save();
      ctx.translate(state.panX, state.panY);
      ctx.scale(state.zoom, state.zoom);

      // Background grid
      for (let i = 0; i < state.stocks.length; i++) {
        const stock = state.stocks[i];
        const { x, y, w, h } = getCellRect(i);

        ctx.fillStyle = priceToColor(stock.changePct);
        ctx.fillRect(x + 4, y + 4, w - 8, h - 8);

        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.lineWidth = 1 / state.zoom;
        ctx.strokeRect(x + 4, y + 4, w - 8, h - 8);

        if (i === state.hoveredIndex) {
          ctx.strokeStyle = 'rgba(255,255,255,0.9)';
          ctx.lineWidth = 2 / state.zoom;
          ctx.strokeRect(x + 4, y + 4, w - 8, h - 8);
        }

        ctx.fillStyle = 'white';
        ctx.font = `bold ${14 / state.zoom}px system-ui, sans-serif`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(stock.symbol, x + w / 2, y + h / 2 - 10 / state.zoom);

        ctx.font = `${12 / state.zoom}px system-ui, sans-serif`;
        const sign = stock.changePct >= 0 ? '+' : '';
        ctx.fillText(`${sign}${stock.changePct.toFixed(2)}%`, x + w / 2, y + h / 2 + 10 / state.zoom);
      }

      // Subtle border around content
      ctx.strokeStyle = 'rgba(255,255,255,0.06)';
      ctx.lineWidth = 1 / state.zoom;
      ctx.strokeRect(0, 0, contentW, contentH);

      ctx.restore();

      // Footer status
      ctx.fillStyle = 'rgba(255,255,255,0.7)';
      ctx.font = '12px system-ui, sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText(`Updated: ${new Date().toLocaleTimeString()}`, state.width - 12, state.height - 12);
    }

    function renderLoop() {
      draw();
      requestAnimationFrame(renderLoop);
    }

    function updateTooltip(mx, my) {
      const index = findHoveredIndex(mx, my);
      state.hoveredIndex = index;

      if (index === -1) {
        tooltip.style.display = 'none';
        state.needsRender = true;
        return;
      }

      const stock = state.stocks[index];
      const sign = stock.changePct >= 0 ? '+' : '';
      tooltip.innerHTML = `
        <div><strong>${stock.symbol}</strong></div>
        <div>Price: $${stock.price.toFixed(2)}</div>
        <div>Change: ${sign}${stock.changePct.toFixed(2)}%</div>
        <div>Volume: ${stock.volume.toLocaleString()}</div>
      `;
      tooltip.style.left = mx + 'px';
      tooltip.style.top = my + 'px';
      tooltip.style.display = 'block';
      state.needsRender = true;
    }

    canvas.addEventListener('mousedown', (e) => {
      state.isDragging = true;
      state.dragStartX = e.clientX;
      state.dragStartY = e.clientY;
      state.dragPanX = state.panX;
      state.dragPanY = state.panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (state.isDragging) {
        state.panX = state.dragPanX + (e.clientX - state.dragStartX);
        state.panY = state.dragPanY + (e.clientY - state.dragStartY);
        state.needsRender = true;
      }
      updateTooltip(e.clientX, e.clientY);
    });

    window.addEventListener('mouseup', () => {
      state.isDragging = false;
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const oldZoom = state.zoom;
      const newZoom = clamp(state.zoom * zoomFactor, 0.5, 3);

      const mx = e.clientX;
      const my = e.clientY;

      // Zoom around cursor
      const worldBefore = screenToWorld(mx, my);
      state.zoom = newZoom;
      state.panX = mx - worldBefore.x * state.zoom;
      state.panY = my - worldBefore.y * state.zoom;

      state.needsRender = true;
    }, { passive: false });

    window.addEventListener('resize', resize);

    // Simulated real-time updates
    setInterval(updatePrices, 1000);

    // Initialize
    initStocks();
    resize();
    renderLoop();

    // Optional: initial centering
    state.panX = 20;
    state.panY = 60;
    state.needsRender = true;
  </script>
</body>
</html>
```

