## React implementation

```jsx
import React, { useEffect, useMemo, useRef, useState } from "react";

const STOCKS = [
  "AAPL", "MSFT", "GOOGL", "AMZN", "NVDA",
  "TSLA", "META", "AMD", "NFLX", "INTC",
  "ORCL", "CRM", "ADBE", "QCOM", "AVGO"
];

const TIME_BUCKETS = 30;
const CELL_W = 70;
const CELL_H = 28;

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function priceToColor(changePct) {
  // changePct in [-5, 5] roughly
  const maxAbs = 5;
  const t = clamp(Math.abs(changePct) / maxAbs, 0, 1);

  if (Math.abs(changePct) < 0.15) return "#d1d5db"; // neutral gray

  if (changePct > 0) {
    // gray -> green
    const r = Math.round(lerp(209, 34, t));
    const g = Math.round(lerp(213, 197, t));
    const b = Math.round(lerp(219, 94, t));
    return `rgb(${r},${g},${b})`;
  } else {
    // gray -> red
    const r = Math.round(lerp(209, 239, t));
    const g = Math.round(lerp(213, 68, t));
    const b = Math.round(lerp(219, 68, t));
    return `rgb(${r},${g},${b})`;
  }
}

function generateInitialData() {
  return STOCKS.map((symbol) => {
    const base = 100 + Math.random() * 300;
    const series = Array.from({ length: TIME_BUCKETS }, (_, i) => {
      const noise = (Math.random() - 0.5) * 2;
      const trend = Math.sin(i / 4) * 0.8;
      const changePct = noise + trend;
      return {
        time: Date.now() - (TIME_BUCKETS - i) * 1000,
        price: base * (1 + changePct / 100),
        changePct,
      };
    });
    return { symbol, base, series };
  });
}

export default function StockHeatmap() {
  const [data, setData] = useState(generateInitialData);
  const [hovered, setHovered] = useState(null);
  const [view, setView] = useState({
    scale: 1,
    offsetX: 0,
    offsetY: 0,
  });

  const containerRef = useRef(null);
  const dragRef = useRef({
    dragging: false,
    startX: 0,
    startY: 0,
    startOffsetX: 0,
    startOffsetY: 0,
  });

  // Simulated real-time updates
  useEffect(() => {
    const id = setInterval(() => {
      setData((prev) =>
        prev.map((stock) => {
          const last = stock.series[stock.series.length - 1];
          const delta = (Math.random() - 0.5) * 1.2;
          const changePct = clamp(last.changePct + delta, -8, 8);
          const price = Math.max(1, last.price * (1 + delta / 100));

          const nextSeries = [...stock.series.slice(1), {
            time: Date.now(),
            price,
            changePct,
          }];

          return { ...stock, series: nextSeries };
        })
      );
    }, 1000);

    return () => clearInterval(id);
  }, []);

  const width = STOCKS.length * CELL_W;
  const height = TIME_BUCKETS * CELL_H;

  const cells = useMemo(() => {
    const out = [];
    data.forEach((stock, row) => {
      stock.series.forEach((point, col) => {
        out.push({
          symbol: stock.symbol,
          row,
          col,
          ...point,
        });
      });
    });
    return out;
  }, [data]);

  const onWheel = (e) => {
    e.preventDefault();
    const delta = -e.deltaY * 0.001;
    setView((v) => {
      const nextScale = clamp(v.scale * (1 + delta), 0.5, 4);
      return { ...v, scale: nextScale };
    });
  };

  const onMouseDown = (e) => {
    dragRef.current = {
      dragging: true,
      startX: e.clientX,
      startY: e.clientY,
      startOffsetX: view.offsetX,
      startOffsetY: view.offsetY,
    };
  };

  const onMouseMove = (e) => {
    if (dragRef.current.dragging) {
      const dx = e.clientX - dragRef.current.startX;
      const dy = e.clientY - dragRef.current.startY;
      setView((v) => ({
        ...v,
        offsetX: dragRef.current.startOffsetX + dx,
        offsetY: dragRef.current.startOffsetY + dy,
      }));
      return;
    }

    const target = e.target.closest("[data-cell]");
    if (target) {
      const symbol = target.getAttribute("data-symbol");
      const price = parseFloat(target.getAttribute("data-price"));
      const changePct = parseFloat(target.getAttribute("data-change"));
      const time = parseInt(target.getAttribute("data-time"), 10);
      setHovered({ symbol, price, changePct, time });
    } else {
      setHovered(null);
    }
  };

  const onMouseUp = () => {
    dragRef.current.dragging = false;
  };

  const resetView = () => setView({ scale: 1, offsetX: 0, offsetY: 0 });

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", padding: 16 }}>
      <div style={{ display: "flex", gap: 12, alignItems: "center", marginBottom: 12 }}>
        <h2 style={{ margin: 0 }}>Stock Price Heatmap</h2>
        <button onClick={resetView}>Reset View</button>
        <div style={{ color: "#6b7280" }}>
          Wheel to zoom · Drag to pan · Hover cells
        </div>
      </div>

      {hovered && (
        <div
          style={{
            marginBottom: 12,
            padding: 10,
            border: "1px solid #e5e7eb",
            borderRadius: 8,
            background: "#fff",
            display: "inline-block",
          }}
        >
          <strong>{hovered.symbol}</strong>{" "}
          <span style={{ color: hovered.changePct >= 0 ? "#16a34a" : "#dc2626" }}>
            {hovered.changePct.toFixed(2)}%
          </span>
          <div>Price: ${hovered.price.toFixed(2)}</div>
          <div>Time: {new Date(hovered.time).toLocaleTimeString()}</div>
        </div>
      )}

      <div
        ref={containerRef}
        onWheel={onWheel}
        onMouseDown={onMouseDown}
        onMouseMove={onMouseMove}
        onMouseUp={onMouseUp}
        onMouseLeave={onMouseUp}
        style={{
          width: "100%",
          height: 600,
          overflow: "hidden",
          border: "1px solid #e5e7eb",
          borderRadius: 12,
          background: "#f9fafb",
          position: "relative",
          cursor: dragRef.current.dragging ? "grabbing" : "grab",
          userSelect: "none",
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox={`0 0 ${width} ${height}`}
          preserveAspectRatio="none"
          style={{
            transform: `translate(${view.offsetX}px, ${view.offsetY}px) scale(${view.scale})`,
            transformOrigin: "0 0",
          }}
        >
          {/* Grid cells */}
          {cells.map((cell) => {
            const x = cell.row * CELL_W;
            const y = cell.col * CELL_H;
            const fill = priceToColor(cell.changePct);

            return (
              <g key={`${cell.symbol}-${cell.col}`}>
                <rect
                  data-cell="true"
                  data-symbol={cell.symbol}
                  data-price={cell.price}
                  data-change={cell.changePct}
                  data-time={cell.time}
                  x={x}
                  y={y}
                  width={CELL_W - 2}
                  height={CELL_H - 2}
                  rx={4}
                  fill={fill}
                  stroke="#ffffff"
                  strokeWidth="1"
                />
                <text
                  x={x + 8}
                  y={y + 18}
                  fontSize="10"
                  fill="#111827"
                  pointerEvents="none"
                >
                  {cell.symbol}
                </text>
              </g>
            );
          })}

          {/* Row labels */}
          {STOCKS.map((symbol, i) => (
            <text
              key={symbol}
              x={i * CELL_W + 8}
              y={height - 6}
              fontSize="11"
              fill="#374151"
            >
              {symbol}
            </text>
          ))}
        </svg>
      </div>
    </div>
  );
}
```

