  </div>

  <div id="tooltip"></div>

  <script>
    const heatmap = document.getElementById('heatmap');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');

    const cols = 8;
    const rows = 6;
    const cellW = 90;
    const cellH = 60;
    const gap = 8;

    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","META","TSLA","NFLX",
      "AMD","INTC","ORCL","CRM","ADBE","IBM","QCOM","AVGO",
      "UBER","SNOW","SHOP","PLTR","PYPL","SQ","BABA","DIS",
      "BA","GE","JPM","BAC","WMT","COST","KO","PEP",
      "XOM","CVX","NKE","MCD","T","V","MA","AXP",
      "CSCO","TMUS","SBUX","PFE","MRNA","LLY","UNH","HD"
    ];

    const stocks = symbols.slice(0, cols * rows).map((symbol, i) => ({
      symbol,
      price: 50 + Math.random() * 450,
      change: (Math.random() - 0.5) * 6
    }));

    let scale = 1;
    let panX = 40;
    let panY = 80;
    let dragging = false;
    let startX = 0;
    let startY = 0;
    let startPanX = 0;
    let startPanY = 0;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // Red for negative, green for positive
      const maxAbs = 5;
      const t = clamp(Math.abs(change) / maxAbs, 0, 1);
      const base = change >= 0 ? [34, 197, 94] : [239, 68, 68];
      const dark = [25, 28, 35];
      const r = Math.round(dark[0] + (base[0] - dark[0]) * t);
      const g = Math.round(dark[1] + (base[1] - dark[1]) * t);
      const b = Math.round(dark[2] + (base[2] - dark[2]) * t);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function render() {
      grid.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;

      let html = '';
      stocks.forEach((s, i) => {
        const x = (i % cols) * (cellW + gap);
        const y = Math.floor(i / cols) * (cellH + gap);
        html += `
          <div class="cell" data-symbol="${s.symbol}"
               style="left:${x}px; top:${y}px; background:${colorForChange(s.change)};">
            <div class="ticker">${s.symbol}</div>
            <div class="price">$${s.price.toFixed(2)}</div>
            <div class="change">${s.change >= 0 ? '+' : ''}${s.change.toFixed(2)}%</div>
          </div>
        `;
      });
      grid.innerHTML = html;
    }

    // Simulated real-time updates
    setInterval(() => {
      stocks.forEach(s => {
        const delta = (Math.random() - 0.5) * 2.5;
        s.price = Math.max(1, s.price + delta);
        s.change = clamp(s.change + (Math.random() - 0.5) * 0.6, -5, 5);
      });
      render();
    }, 1000);

    // Zoom with mouse wheel centered on cursor
    heatmap.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = heatmap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 3);

      // Keep cursor point stable while zooming
      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      scale = newScale;
      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      render();
    }, { passive: false });

    // Pan with drag
    heatmap.addEventListener('mousedown', (e) => {
      dragging = true;
      heatmap.classList.add('dragging');
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      render();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      heatmap.classList.remove('dragging');
    });

    // Tooltip
    heatmap.addEventListener('mousemove', (e) => {
      const cell = e.target.closest('.cell');
      if (!cell) {
        tooltip.style.display = 'none';
        return;
      }

      const symbol = cell.dataset.symbol;
      const stock = stocks.find(s => s.symbol === symbol);

      tooltip.style.display = 'block';
      tooltip.style.left = (e.clientX + 12) + 'px';
      tooltip.style.top = (e.clientY + 12) + 'px';
      tooltip.innerHTML = `
        <strong>${stock.symbol}</strong><br>
        Price: $${stock.price.toFixed(2)}<br>
        Change: ${stock.change >= 0 ? '+' : ''}${stock.change.toFixed(2)}%
      `;
    });

    heatmap.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
    });

    render();
  </script>
</body>
</html>
