  <div id="tooltip"></div>

  <script>
    const viewport = document.getElementById('viewport');
    const heatmap = document.getElementById('heatmap');
    const tooltip = document.getElementById('tooltip');
    const statusEl = document.getElementById('status');
    const resetBtn = document.getElementById('resetBtn');
    const toggleBtn = document.getElementById('toggleBtn');

    // Minimal stock universe
    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','TSLA','META','NFLX',
      'AMD','INTC','ORCL','IBM','CRM','ADBE','QCOM','AVGO'
    ];

    const cols = 4;
    const cellW = 180;
    const cellH = 110;
    const gap = 10;

    let live = true;
    let scale = 1;
    let panX = 20;
    let panY = 20;
    let dragging = false;
    let dragStart = { x: 0, y: 0, panX: 0, panY: 0 };

    // Simulated prices and daily changes
    const data = symbols.map((sym, i) => ({
      symbol: sym,
      price: 100 + Math.random() * 400,
      change: (Math.random() - 0.5) * 6,
      row: Math.floor(i / cols),
      col: i % cols
    }));

    function colorForChange(change) {
      // red -> gray -> green
      const maxAbs = 6;
      const t = Math.max(-1, Math.min(1, change / maxAbs));
      if (t >= 0) {
        const g = Math.floor(120 + 120 * t);
        return `rgb(${40}, ${g}, ${60})`;
      } else {
        const r = Math.floor(120 + 120 * (-t));
        return `rgb(${r}, ${50}, ${50})`;
      }
    }

    function render() {
      heatmap.innerHTML = '';
      const width = cols * cellW + (cols - 1) * gap;
      const rows = Math.ceil(symbols.length / cols);
      const height = rows * cellH + (rows - 1) * gap;
      heatmap.style.width = width + 'px';
      heatmap.style.height = height + 'px';

      data.forEach(item => {
        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.style.left = (item.col * (cellW + gap)) + 'px';
        cell.style.top = (item.row * (cellH + gap)) + 'px';
        cell.style.width = cellW + 'px';
        cell.style.height = cellH + 'px';
        cell.style.background = colorForChange(item.change);

        cell.innerHTML = `
          <div class="symbol">${item.symbol}</div>
          <div class="price">$${item.price.toFixed(2)}</div>
          <div class="price">${item.change >= 0 ? '+' : ''}${item.change.toFixed(2)}%</div>
        `;

        cell.addEventListener('mousemove', (e) => {
          tooltip.style.display = 'block';
          tooltip.style.left = (e.clientX + 12) + 'px';
          tooltip.style.top = (e.clientY + 12) + 'px';
          tooltip.innerHTML = `
            <strong>${item.symbol}</strong><br/>
            Price: $${item.price.toFixed(2)}<br/>
            Change: ${item.change >= 0 ? '+' : ''}${item.change.toFixed(2)}%
          `;
        });

        cell.addEventListener('mouseleave', () => {
          tooltip.style.display = 'none';
        });

        heatmap.appendChild(cell);
      });

      applyTransform();
    }

    function applyTransform() {
      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    function updateLiveData() {
      if (!live) return;

      data.forEach(item => {
        const delta = (Math.random() - 0.5) * 2.5;
        item.price = Math.max(1, item.price + delta);
        item.change = Math.max(-8, Math.min(8, item.change + (Math.random() - 0.5) * 0.4));
      });

      // Update only cell contents/colors
      [...heatmap.children].forEach((cell, i) => {
        const item = data[i];
        cell.style.background = colorForChange(item.change);
        cell.innerHTML = `
          <div class="symbol">${item.symbol}</div>
          <div class="price">$${item.price.toFixed(2)}</div>
          <div class="price">${item.change >= 0 ? '+' : ''}${item.change.toFixed(2)}%</div>
        `;
      });
    }

    // Zoom with mouse wheel
    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.min(4, Math.max(0.4, scale * zoomFactor));

      // Zoom around mouse position
      panX = mouseX - (mouseX - panX) * (newScale / scale);
      panY = mouseY - (mouseY - panY) * (newScale / scale);
      scale = newScale;

      applyTransform();
    }, { passive: false });

    // Pan with drag
    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      dragStart = { x: e.clientX, y: e.clientY, panX, panY };
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      panX = dragStart.panX + (e.clientX - dragStart.x);
      panY = dragStart.panY + (e.clientY - dragStart.y);
      applyTransform();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    resetBtn.addEventListener('click', () => {
      scale = 1;
      panX = 20;
      panY = 20;
      applyTransform();
    });

    toggleBtn.addEventListener('click', () => {
      live = !live;
      toggleBtn.textContent = live ? 'Pause Updates' : 'Resume Updates';
      statusEl.textContent = `Live updates: ${live ? 'on' : 'off'}`;
    });

    // Initial render
    render();

    // Real-time updates
    setInterval(updateLiveData, 1000);
  </script>
</body>
