    const cellW = 140;
    const cellH = 90;
    const gap = 4;

    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','TSLA','META','NFLX','AMD','INTC',
      'ORCL','CRM','ADBE','QCOM','AVGO','IBM','UBER','SNOW','SHOP','PYPL',
      'BA','JPM','BAC','WMT','COST','KO','PEP','DIS','NKE','XOM',
      'CVX','PFE','MRNA','T','VZ','CSCO','SAP','SONY','BABA','TSM',
      'ASML','MU','LULU','SBUX','MCD','HD','LOW','GS','MS','AXP'
    ];

    const stocks = symbols.slice(0, rows * cols).map((sym, i) => ({
      sym,
      price: 50 + Math.random() * 450,
      prev: 0,
      chg: 0,
      x: (i % cols) * (cellW + gap),
      y: Math.floor(i / cols) * (cellH + gap)
    }));

    function colorForChange(chg) {
      // chg is percent
      const max = 5;
      const t = Math.max(-1, Math.min(1, chg / max));
      if (t >= 0) {
        const g = Math.round(60 + 160 * t);
        return `rgb(20, ${g}, 70)`;
