        div.addEventListener('mousemove', onCellHover);
        div.addEventListener('mouseleave', hideTooltip);
        content.appendChild(div);
      });
    }

    function updatePrices() {
      stocks.forEach(s => {
        s.prev = s.price;
        const delta = (Math.random() - 0.5) * (s.price * 0.02); // +/-1%
        s.price = Math.max(1, s.price + delta);
        s.chg = ((s.price - s.prev) / s.prev) * 100;
