<body>
  <div class="toolbar">
    <strong>Stock Heatmap</strong>
    <span>Wheel = zoom, drag = pan, hover = details</span>
    <span id="status"></span>
  </div>

  <div id="viewport">
    <div id="heatmap"></div>

    <div class="legend">
      Price change
      <div class="bar"></div>
      <div>-5% &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 0% &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; +5%</div>
    </div>
  </div>

  <script>
    const stocks = ["AAPL","MSFT","NVDA","AMZN","GOOG","META","TSLA","AMD","NFLX","INTC"];
    const cols = 40;

    const heatmap = document.getElementById("heatmap");
    const viewport = document.getElementById("viewport");
    const status = document.getElementById("status");

    // Data: percent change values
    const data = stocks.map(() =>
      Array.from({ length: cols }, () => (Math.random() - 0.5) * 10)
    );

    let scale = 1;
    let panX = 0;
    let panY = 0;

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(v) {
      // v in [-5, 5]
      const x = clamp((v + 5) / 10, 0, 1);
      const r = x < 0.5 ? 185 + (245 - 185) * (x / 0.5) : 245 + (20 - 245) * ((x - 0.5) / 0.5);
      const g = x < 0.5 ? 28 + (158 - 28) * (x / 0.5) : 158 + (83 - 158) * ((x - 0.5) / 0.5);
      const b = x < 0.5 ? 28 + (11 - 28) * (x / 0.5) : 11 + (45 - 11) * ((x - 0.5) / 0.5);
      return `rgb(${Math.round(r)},${Math.round(g)},${Math.round(b)})`;
    }

    function render() {
      heatmap.innerHTML = "";
      stocks.forEach((stock, row) => {
        const rowEl = document.createElement("div");
        rowEl.className = "row";

        const label = document.createElement("div");
        label.className = "label";
        label.textContent = stock;
        rowEl.appendChild(label);

        data[row].forEach((v, col) => {
          const cell = document.createElement("div");
          cell.className = "cell";
          cell.style.background = colorForChange(v);
          cell.dataset.tip = `${stock} | T${col + 1} | ${v.toFixed(2)}%`;
          rowEl.appendChild(cell);
        });

        heatmap.appendChild(rowEl);
      });

      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
      status.textContent = `Scale: ${scale.toFixed(2)}`;
    }

    // Real-time updates
    setInterval(() => {
      for (let r = 0; r < data.length; r++) {
        for (let c = 0; c < data[r].length; c++) {
          // small random walk
          data[r][c] = clamp(data[r][c] + (Math.random() - 0.5) * 0.8, -5, 5);
        }
      }
      render();
    }, 1000);

    // Zoom with mouse wheel
    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = clamp(scale * zoomFactor, 0.5, 3);

      // Zoom around cursor
      panX = mouseX - (mouseX - panX) * (newScale / scale);
      panY = mouseY - (mouseY - panY) * (newScale / scale);
      scale = newScale;

      render();
    }, { passive: false });

    // Pan with drag
    let dragging = false;
    let startX = 0, startY = 0, startPanX = 0, startPanY = 0;

    viewport.addEventListener("pointerdown", (e) => {
      dragging = true;
      viewport.classList.add("dragging");
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener("pointermove", (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      render();
    });

    viewport.addEventListener("pointerup", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("pointercancel", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    render();
  </script>
</body>
</html>
