<body>
  <div id="toolbar">
    <div><strong>Stock Heatmap</strong></div>
    <div>Wheel: zoom · Drag: pan</div>
    <div>Live updates: simulated every 1s</div>
  </div>

  <canvas id="heatmap"></canvas>
  <div id="tooltip" class="tooltip"></div>

  <script>
    const canvas = document.getElementById('heatmap');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');

    let dpr = window.devicePixelRatio || 1;
    let width = 0, height = 0;

    // View transform
    let scale = 1;
    let offsetX = 0;
    let offsetY = 0;

    // Interaction state
    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    // Generate sample stocks
    const stocks = Array.from({ length: 120 }, (_, i) => ({
      symbol: `STK${String(i + 1).padStart(3, '0')}`,
      price: 50 + Math.random() * 150,
      change: (Math.random() - 0.5) * 10
    }));

    function resize() {
      dpr = window.devicePixelRatio || 1;
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function colorForChange(change) {
      // Red for negative, green for positive
      const max = 10;
      const t = Math.max(-1, Math.min(1, change / max));
      if (t >= 0) {
        const g = Math.floor(80 + t * 175);
        return `rgb(20, ${g}, 80)`;
      } else {
        const r = Math.floor(80 + (-t) * 175);
        return `rgb(${r}, 40, 40)`;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, width, height);

      // Background grid
      ctx.fillStyle = '#0b1020';
      ctx.fillRect(0, 0, width, height);

      const cols = Math.max(1, Math.floor(Math.sqrt(stocks.length)));
      const rows = Math.ceil(stocks.length / cols);

      const cellW = 120;
      const cellH = 70;
      const gap = 8;

      // Apply pan/zoom
      ctx.save();
      ctx.translate(offsetX, offsetY);
      ctx.scale(scale, scale);

      stocks.forEach((s, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = col * (cellW + gap);
        const y = row * (cellH + gap);

        ctx.fillStyle = colorForChange(s.change);
        roundRect(ctx, x, y, cellW, cellH, 10);
        ctx.fill();

        ctx.strokeStyle = 'rgba(255,255,255,0.08)';
        ctx.stroke();

        ctx.fillStyle = 'white';
        ctx.font = 'bold 14px system-ui, sans-serif';
        ctx.fillText(s.symbol, x + 10, y + 24);

        ctx.font = '12px system-ui, sans-serif';
        ctx.fillStyle = 'rgba(255,255,255,0.9)';
        ctx.fillText(`$${s.price.toFixed(2)}`, x + 10, y + 44);

        ctx.fillStyle = s.change >= 0 ? '#bbf7d0' : '#fecaca';
        ctx.fillText(`${s.change >= 0 ? '+' : ''}${s.change.toFixed(2)}%`, x + 10, y + 60);
      });

      ctx.restore();
    }

    function roundRect(ctx, x, y, w, h, r) {
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + w, y, x + w, y + h, r);
      ctx.arcTo(x + w, y + h, x, y + h, r);
      ctx.arcTo(x, y + h, x, y, r);
      ctx.arcTo(x, y, x + w, y, r);
      ctx.closePath();
    }

    function screenToWorld(px, py) {
      return {
        x: (px - offsetX) / scale,
        y: (py - offsetY) / scale
      };
    }

    function getCellAt(px, py) {
      const cols = Math.max(1, Math.floor(Math.sqrt(stocks.length)));
      const cellW = 120;
      const cellH = 70;
      const gap = 8;

      const p = screenToWorld(px, py);
      for (let i = 0; i < stocks.length; i++) {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = col * (cellW + gap);
        const y = row * (cellH + gap);
        if (p.x >= x && p.x <= x + cellW && p.y >= y && p.y <= y + cellH) {
          return { stock: stocks[i], x, y, w: cellW, h: cellH };
        }
      }
      return null;
    }

    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      canvas.classList.add('dragging');
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      canvas.classList.remove('dragging');
    });

    window.addEventListener('mousemove', (e) => {
      if (dragging) {
        offsetX += e.clientX - lastX;
        offsetY += e.clientY - lastY;
        lastX = e.clientX;
        lastY = e.clientY;
        draw();
      }

      const hit = getCellAt(e.clientX, e.clientY);
      if (hit) {
        tooltip.style.display = 'block';
        tooltip.style.left = e.clientX + 'px';
        tooltip.style.top = e.clientY + 'px';
        tooltip.innerHTML = `
          <strong>${hit.stock.symbol}</strong><br>
          Price: $${hit.stock.price.toFixed(2)}<br>
          Change: ${hit.stock.change >= 0 ? '+' : ''}${hit.stock.change.toFixed(2)}%
        `;
      } else {
        tooltip.style.display = 'none';
      }
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      const before = screenToWorld(mouseX, mouseY);
      scale *= zoomFactor;
      scale = Math.max(0.5, Math.min(4, scale));
      const after = screenToWorld(mouseX, mouseY);

      offsetX += (after.x - before.x) * scale;
      offsetY += (after.y - before.y) * scale;

      draw();
    }, { passive: false });

    // Simulated real-time updates
    setInterval(() => {
      stocks.forEach(s => {
        s.change += (Math.random() - 0.5) * 1.2;
        s.change = Math.max(-10, Math.min(10, s.change));
        s.price *= 1 + (s.change / 1000) * (Math.random() * 0.3);
      });
      draw();
    }, 1000);

    window.addEventListener('resize', resize);

    resize();
  </script>
