<body>
  <div id="toolbar">
    Wheel = zoom · Drag = pan
  </div>

  <div id="viewport">
    <div id="grid"></div>
  </div>

  <div id="tooltip"></div>

  <script>
    const viewport = document.getElementById('viewport');
    const grid = document.getElementById('grid');
    const tooltip = document.getElementById('tooltip');

    const rows = 8;
    const cols = 10;
    const tickers = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','TSLA','META','NFLX','AMD','INTC',
      'ORCL','IBM','CRM','UBER','SNOW','SHOP','ADBE','QCOM','AVGO','BABA',
      'JPM','BAC','WMT','COST','KO','PEP','XOM','CVX','DIS','NKE',
      'PFE','MRNA','LLY','UNH','V','MA','PYPL','SQ','SPOT','PLTR',
      'BA','GE','CAT','HON','T','VZ','TMUS','CSCO','TXN','MU'
    ];

    const cells = [];
    const state = {
      scale: 1,
      x: 0,
      y: 0,
      dragging: false,
      startX: 0,
      startY: 0,
      originX: 0,
      originY: 0
    };

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function priceToColor(changePct) {
      // red for negative, green for positive
      const clamped = Math.max(-5, Math.min(5, changePct));
      const t = (clamped + 5) / 10; // 0..1
      const r = Math.round(220 * (1 - t) + 30);
      const g = Math.round(40 * (1 - t) + 200 * t);
      const b = Math.round(50 * (1 - t) + 40 * t);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function createGrid() {
      grid.style.gridTemplateColumns = `repeat(${cols}, 90px)`;

      for (let i = 0; i < rows * cols; i++) {
        const ticker = tickers[i % tickers.length];
        const base = rand(20, 500);
        const changePct = rand(-5, 5);

        const cell = document.createElement('div');
        cell.className = 'cell';
        cell.dataset.ticker = ticker;
        cell.dataset.base = base.toFixed(2);
        cell.dataset.change = changePct.toFixed(2);

        const color = priceToColor(changePct);
        cell.style.background = color;

        cell.innerHTML = `
          <div class="ticker">${ticker}</div>
          <div class="price">$${base.toFixed(2)}</div>
        `;

        cell.addEventListener('mouseenter', (e) => {
          tooltip.style.display = 'block';
          updateTooltip(e, cell);
        });

        cell.addEventListener('mousemove', (e) => updateTooltip(e, cell));

        cell.addEventListener('mouseleave', () => {
          tooltip.style.display = 'none';
        });

        grid.appendChild(cell);
        cells.push(cell);
      }
    }

    function updateTooltip(e, cell) {
      const ticker = cell.dataset.ticker;
      const base = parseFloat(cell.dataset.base);
      const change = parseFloat(cell.dataset.change);
      const price = base * (1 + change / 100);

      tooltip.style.left = e.clientX + 'px';
      tooltip.style.top = e.clientY + 'px';
      tooltip.innerHTML = `
        <strong>${ticker}</strong><br>
        Price: $${price.toFixed(2)}<br>
        Change: ${change >= 0 ? '+' : ''}${change.toFixed(2)}%
      `;
    }

    function applyTransform() {
      grid.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
    }

    viewport.addEventListener('mousedown', (e) => {
      state.dragging = true;
      viewport.classList.add('dragging');
      state.startX = e.clientX;
      state.startY = e.clientY;
      state.originX = state.x;
      state.originY = state.y;
    });

    window.addEventListener('mousemove', (e) => {
      if (!state.dragging) return;
      state.x = state.originX + (e.clientX - state.startX);
      state.y = state.originY + (e.clientY - state.startY);
      applyTransform();
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
      viewport.classList.remove('dragging');
    });

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.min(3, Math.max(0.5, state.scale * zoomFactor));

      // Zoom around mouse position
      const rect = viewport.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      state.x = mx - (mx - state.x) * (newScale / state.scale);
      state.y = my - (my - state.y) * (newScale / state.scale);
      state.scale = newScale;

      applyTransform();
    }, { passive: false });

    // Simulated real-time updates
    function updatePrices() {
      cells.forEach(cell => {
        let change = parseFloat(cell.dataset.change);
        let base = parseFloat(cell.dataset.base);

        // random walk
        change += rand(-0.3, 0.3);
        change = Math.max(-5, Math.min(5, change));

        // update base price slightly too
        base *= (1 + rand(-0.002, 0.002));

        cell.dataset.change = change.toFixed(2);
        cell.dataset.base = base.toFixed(2);

        const color = priceToColor(change);
        cell.style.background = color;

        const price = base * (1 + change / 100);
        cell.querySelector('.price').textContent = `$${price.toFixed(2)}`;
      });
    }

    createGrid();
    applyTransform();
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
```

