<script>
(() => {
  const svg = document.getElementById('svg');
  const viewport = document.getElementById('viewport');
  const tooltip = document.getElementById('tooltip');
  const status = document.getElementById('status');
  const resetBtn = document.getElementById('resetBtn');
  const pauseBtn = document.getElementById('pauseBtn');

  const cols = 10;
  const rows = 6;
  const cellW = 92;
  const cellH = 92;
  const gap = 10;
  const startX = 40;
  const startY = 40;

  let paused = false;
  let scale = 1;
  let tx = 0;
  let ty = 0;
  let dragging = false;
  let dragStart = null;

  const symbols = [
    'AAPL','MSFT','NVDA','AMZN','GOOGL','META','TSLA','AMD','NFLX','INTC',
    'ORCL','CRM','ADBE','QCOM','AVGO','IBM','UBER','SHOP','SNOW','PLTR',
    'BA','JPM','BAC','XOM','CVX','KO','PEP','WMT','COST','DIS',
    'NKE','MCD','T','VZ','CSCO','PYPL','SQ','SPOT','BIDU','BABA',
    'LLY','PFE','MRNA','UNH','HD','LOW','GS','MS','CAT','GE',
    'TM','SONY','SBUX','ABNB','RIVN','F','GM','DE','HON','RTX'
  ];

  const data = symbols.slice(0, cols * rows).map((symbol, i) => ({
    symbol,
    price: 50 + Math.random() * 450,
    change: (Math.random() - 0.5) * 8,
    volume: Math.floor(1e6 + Math.random() * 9e6),
    x: startX + (i % cols) * (cellW + gap),
    y: startY + Math.floor(i / cols) * (cellH + gap)
  }));

  function clamp(v, min, max) {
    return Math.max(min, Math.min(max, v));
  }

  function colorForChange(change) {
    const t = clamp((change + 10) / 20, 0, 1);
    const stops = [
      [215, 48, 39],   // red
      [253, 174, 97],  // orange
      [255, 255, 191], // yellow
      [166, 217, 106], // light green
      [26, 152, 80]    // green
    ];
    const idx = t * (stops.length - 1);
    const i = Math.floor(idx);
    const f = idx - i;
    const a = stops[i];
    const b = stops[Math.min(i + 1, stops.length - 1)];
    const r = Math.round(a[0] + (b[0] - a[0]) * f);
    const g = Math.round(a[1] + (b[1] - a[1]) * f);
    const bl = Math.round(a[2] + (b[2] - a[2]) * f);
    return `rgb(${r},${g},${bl})`;
  }

  function render() {
    svg.innerHTML = '';
    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.setAttribute('transform', `translate(${tx},${ty}) scale(${scale})`);
    svg.appendChild(g);

    data.forEach(d => {
      const group = document.createElementNS('http://www.w3.org/2000/svg', 'g');

      const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
      rect.setAttribute('class', 'cell');
      rect.setAttribute('x', d.x);
      rect.setAttribute('y', d.y);
      rect.setAttribute('width', cellW);
      rect.setAttribute('height', cellH);
      rect.setAttribute('fill', colorForChange(d.change));

      const label = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      label.setAttribute('class', 'label');
      label.setAttribute('x', d.x + cellW / 2);
      label.setAttribute('y', d.y + cellH / 2 - 8);
      label.textContent = d.symbol;

      const sub = document.createElementNS('http://www.w3.org/2000/svg', 'text');
      sub.setAttribute('class', 'label');
      sub.setAttribute('x', d.x + cellW / 2);
      sub.setAttribute('y', d.y + cellH / 2 + 12);
      sub.textContent = `${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}%`;

      group.appendChild(rect);
      group.appendChild(label);
      group.appendChild(sub);

      group.addEventListener('mouseenter', (e) => showTooltip(e, d));
      group.addEventListener('mousemove', (e) => moveTooltip(e));
      group.addEventListener('mouseleave', hideTooltip);

      g.appendChild(group);
    });
  }

  function showTooltip(e, d) {
    tooltip.style.display = 'block';
    tooltip.innerHTML = `
      <strong>${d.symbol}</strong><br>
      Price: $${d.price.toFixed(2)}<br>
      Change: ${d.change >= 0 ? '+' : ''}${d.change.toFixed(2)}%<br>
      Volume: ${d.volume.toLocaleString()}
    `;
    moveTooltip(e);
  }

  function moveTooltip(e) {
    const rect = viewport.getBoundingClientRect();
    tooltip.style.left = `${e.clientX - rect.left}px`;
    tooltip.style.top = `${e.clientY - rect.top}px`;
  }

  function hideTooltip() {
    tooltip.style.display = 'none';
  }

  function updatePrices() {
    if (paused) return;

    data.forEach(d => {
      const delta = (Math.random() - 0.5) * 1.2;
      d.price = Math.max(1, d.price + delta);
      d.change = clamp(d.change + (Math.random() - 0.5) * 0.8, -10, 10);
      d.volume = Math.max(0, d.volume + Math.floor((Math.random() - 0.5) * 200000));
    });

    render();
    status.textContent = `Live • ${new Date().toLocaleTimeString()}`;
  }

  function applyTransform() {
    svg.querySelector('g')?.setAttribute('transform', `translate(${tx},${ty}) scale(${scale})`);
  }

  viewport.addEventListener('wheel', (e) => {
    e.preventDefault();
    const rect = svg.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    const zoom = Math.exp(-e.deltaY * 0.001);
    const nextScale = clamp(scale * zoom, 0.5, 4);

    tx = mx - (mx - tx) * (nextScale / scale);
    ty = my - (my - ty) * (nextScale / scale);
    scale = nextScale;
    applyTransform();
  }, { passive: false });

  viewport.addEventListener('pointerdown', (e) => {
    dragging = true;
    viewport.classList.add('dragging');
    dragStart = { x: e.clientX, y: e.clientY, tx, ty };
    viewport.setPointerCapture(e.pointerId);
  });

  viewport.addEventListener('pointermove', (e) => {
    if (dragging && dragStart) {
      tx = dragStart.tx + (e.clientX - dragStart.x);
      ty = dragStart.ty + (e.clientY - dragStart.y);
      applyTransform();
    }
  });

  viewport.addEventListener('pointerup', () => {
    dragging = false;
    dragStart = null;
    viewport.classList.remove('dragging');
  });

  viewport.addEventListener('pointercancel', () => {
    dragging = false;
    dragStart = null;
    viewport.classList.remove('dragging');
  });

  resetBtn.addEventListener('click', () => {
    scale = 1;
    tx = 0;
    ty = 0;
    applyTransform();
  });

  pauseBtn.addEventListener('click', () => {
    paused = !paused;
    pauseBtn.textContent = paused ? 'Resume Updates' : 'Pause Updates';
    status.textContent = paused ? 'Paused' : 'Live';
  });

  render();
  setInterval(updatePrices, 1000);
})();
</script>
