        const delta = (Math.random() - 0.5) * 2;
        s.price = Math.max(1, s.price + delta);
        s.change = Math.max(-5, Math.min(5, s.change + (Math.random() - 0.5) * 0.6));
      });
      render();
    }

    viewport.addEventListener("mousedown", (e) => {
      dragging = true;
      viewport.classList.add("dragging");
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener("mousemove", (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      render();
    });

    window.addEventListener("mouseup", () => {
      dragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const rect = viewport.getBoundingClientRect();

      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - panX) / scale;
      const worldY = (mouseY - panY) / scale;

      scale = Math.min(3, Math.max(0.5, scale * zoomFactor));

      panX = mouseX - worldX * scale;
      panY = mouseY - worldY * scale;

      render();
    }, { passive: false });

    resetBtn.addEventListener("click", () => {
      scale = 1;
      panX = 0;
      panY = 0;
      render();
    });

    // Initial render + live updates
    render();
    setInterval(updatePrices, 1000);
  </script>
</body>
