      "NFLX","INTC","ORCL","CRM","UBER","SHOP","ADBE","QCOM",
      "AVGO","COST","JPM","BAC","XOM","CVX","PFE","KO"
    ];

    const rows = 4;
    const cols = 6;

    const state = symbols.map(sym => ({
      sym,
      price: 50 + Math.random() * 450,
      chg: (Math.random() - 0.5) * 8
    }));

    // --- DOM ---
    const wrap = document.getElementById("wrap");
    const heatmap = document.getElementById("heatmap");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");
    const toggleBtn = document.getElementById("toggleBtn");

    // --- View transform ---
    let scale = 1;
    let panX = 20;
    let panY = 20;

    function applyTransform() {
      heatmap.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    // --- Build grid ---
    heatmap.style.gridTemplateColumns = `repeat(${cols}, 88px)`;
