      const cell = document.createElement("div");
      cell.className = "cell";
      cell.dataset.index = i;
      cell.innerHTML = `
        <div class="sym">${d.sym}</div>
        <div class="price"></div>
        <div class="chg"></div>
      `;
      heatmap.appendChild(cell);
    });

    function colorForChange(chg) {
      // red for negative, green for positive
      const max = 8;
      const t = Math.max(-1, Math.min(1, chg / max));
      if (t >= 0) {
        const g = Math.round(90 + 140 * t);
        const r = Math.round(20 + 30 * (1 - t));
        return `rgb(${r}, ${g}, 60)`;
      } else {
        const a = Math.abs(t);
        const r = Math.round(90 + 140 * a);
        const g = Math.round(30 + 30 * (1 - a));
        return `rgb(${r}, ${g}, 60)`;
      }
    }

    function render() {
      const cells = heatmap.children;
      state.forEach((d, i) => {
        const cell = cells[i];
        const priceEl = cell.querySelector(".price");
        const chgEl = cell.querySelector(".chg");

        priceEl.textContent = `$${d.price.toFixed(2)}`;
        chgEl.textContent = `${d.chg >= 0 ? "+" : ""}${d.chg.toFixed(2)}%`;
        cell.style.background = colorForChange(d.chg);
      });
    }

    // --- Real-time updates (simulated) ---
    let running = true;
    setInterval(() => {
      if (!running) return;

      state.forEach(d => {
        const delta = (Math.random() - 0.5) * 1.2;
        d.chg = Math.max(-8, Math.min(8, d.chg + delta));
        d.price = Math.max(1, d.price * (1 + delta / 100));
      });

      render();
    }, 800);

    // --- Zoom / pan ---
    let dragging = false;
    let startX = 0, startY = 0;
    let startPanX = 0, startPanY = 0;

    wrap.addEventListener("pointerdown", (e) => {
      dragging = true;
      wrap.classList.add("dragging");
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
      wrap.setPointerCapture(e.pointerId);
    });

    wrap.addEventListener("pointermove", (e) => {
      if (dragging) {
        panX = startPanX + (e.clientX - startX);
        panY = startPanY + (e.clientY - startY);
        applyTransform();
      }
    });

    wrap.addEventListener("pointerup", () => {
      dragging = false;
      wrap.classList.remove("dragging");
    });

    wrap.addEventListener("wheel", (e) => {
      e.preventDefault();

      const rect = wrap.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const nextScale = Math.min(4, Math.max(0.5, scale * zoomFactor));

      // zoom around mouse position
      panX = mouseX - (mouseX - panX) * (nextScale / scale);
      panY = mouseY - (mouseY - panY) * (nextScale / scale);
      scale = nextScale;

      applyTransform();
    }, { passive: false });

