    ];

    const world = document.getElementById("world");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");
    const resetBtn = document.getElementById("resetBtn");

    const state = {
      scale: 1,
      x: 0,
      y: 0,
      dragging: false,
      startX: 0,
      startY: 0,
      originX: 0,
      originY: 0,
      data: []
    };

    function priceToColor(changePct) {
      // Red for negative, green for positive
      const clamped = Math.max(-5, Math.min(5, changePct));
      const t = (clamped + 5) / 10; // 0..1
      const r = Math.round(220 * (1 - t) + 40 * t);
      const g = Math.round(50 * (1 - t) + 200 * t);
      const b = Math.round(60 * (1 - t) + 70 * t);
      return `rgb(${r}, ${g}, ${b})`;
    }

    function createCells() {
      world.innerHTML = "";
      state.data = symbols.map((symbol, i) => {
        const base = 50 + Math.random() * 450;
        const changePct = (Math.random() * 10) - 5;
        return { symbol, price: base, changePct };
      });

      state.data.forEach((item, i) => {
        const cell = document.createElement("div");
        cell.className = "cell";
        cell.dataset.index = i;

        const symbol = document.createElement("div");
        symbol.className = "symbol";
        symbol.textContent = item.symbol;

        const price = document.createElement("div");
        price.className = "price";
        price.textContent = `$${item.price.toFixed(2)}`;

        cell.appendChild(symbol);
        cell.appendChild(price);
        cell.style.background = priceToColor(item.changePct);

        cell.addEventListener("mouseenter", (e) => {
          tooltip.style.display = "block";
          updateTooltip(e, item);
        });

        cell.addEventListener("mousemove", (e) => {
          updateTooltip(e, item);
        });

        cell.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        world.appendChild(cell);
      });
    }

    function updateTooltip(e, item) {
      tooltip.innerHTML = `
        <strong>${item.symbol}</strong><br>
        Price: $${item.price.toFixed(2)}<br>
        Change: ${item.changePct.toFixed(2)}%
      `;
      tooltip.style.left = (e.clientX + 12) + "px";
      tooltip.style.top = (e.clientY + 12) + "px";
    }

    function renderTransform() {
      world.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
    }

    function resetView() {
      state.scale = 1;
      state.x = 0;
      state.y = 0;
      renderTransform();
    }

    viewport.addEventListener("mousedown", (e) => {
      state.dragging = true;
      viewport.classList.add("dragging");
      state.startX = e.clientX;
      state.startY = e.clientY;
      state.originX = state.x;
      state.originY = state.y;
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.dragging) return;
      state.x = state.originX + (e.clientX - state.startX);
      state.y = state.originY + (e.clientY - state.startY);
      renderTransform();
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      viewport.classList.remove("dragging");
    });

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const newScale = Math.min(3, Math.max(0.5, state.scale * zoomFactor));

      // Zoom around cursor
      const rect = viewport.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const worldX = (mouseX - state.x) / state.scale;
      const worldY = (mouseY - state.y) / state.scale;

      state.scale = newScale;
      state.x = mouseX - worldX * state.scale;
      state.y = mouseY - worldY * state.scale;

      renderTransform();
    }, { passive: false });

    resetBtn.addEventListener("click", resetView);

    // Simulated real-time updates
    function tick() {
      state.data.forEach((item, i) => {
        // small random walk
        item.changePct += (Math.random() - 0.5) * 0.4;
        item.changePct = Math.max(-8, Math.min(8, item.changePct));

        item.price *= (1 + (Math.random() - 0.5) * 0.01);
        item.price = Math.max(1, item.price);

        const cell = world.children[i];
        if (cell) {
          cell.style.background = priceToColor(item.changePct);
          cell.querySelector(".price").textContent = `$${item.price.toFixed(2)}`;
        }
      });
    }

    createCells();
    renderTransform();
    setInterval(tick, 1000);
  </script>
</body>
</html>
