      cursor: grabbing;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    Drag to pan • Mouse wheel to zoom • Real-time updates
  </div>
  <canvas id="heatmap"></canvas>

  <script>
    const canvas = document.getElementById("heatmap");
    const ctx = canvas.getContext("2d");

    const state = {
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      lastX: 0,
      lastY: 0,
      stocks: [],
      cols: 10,
      cellSize: 90,
      gap: 8
    };

    function resize() {
      canvas.width = window.innerWidth * devicePixelRatio;
      canvas.height = window.innerHeight * devicePixelRatio;
      canvas.style.width = window.innerWidth + "px";
      canvas.style.height = window.innerHeight + "px";
      ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
      draw();
    }

    function randomStockSymbol(i) {
      return "STK" + String(i).padStart(3, "0");
    }

    function initStocks(count = 120) {
      state.stocks = Array.from({ length: count }, (_, i) => ({
        symbol: randomStockSymbol(i + 1),
        price: 50 + Math.random() * 150,
        change: (Math.random() - 0.5) * 4
      }));
    }

    function updateStocks() {
      for (const s of state.stocks) {
        const delta = (Math.random() - 0.5) * 2;
        s.change = delta;
        s.price = Math.max(1, s.price + delta);
      }
      draw();
    }

    function colorForChange(change) {
      // red for negative, green for positive
      const intensity = Math.min(255, Math.floor(Math.abs(change) * 60) + 40);
      if (change >= 0) return `rgb(0, ${intensity}, 80)`;
      return `rgb(${intensity}, 40, 40)`;
    }

    function draw() {
      const w = window.innerWidth;
      const h = window.innerHeight;

      ctx.clearRect(0, 0, w, h);
      ctx.fillStyle = "#111";
      ctx.fillRect(0, 0, w, h);

      ctx.save();
      ctx.translate(state.panX, state.panY);
      ctx.scale(state.zoom, state.zoom);

      const cellW = state.cellSize;
      const cellH = state.cellSize;
      const gap = state.gap;

      state.stocks.forEach((s, i) => {
        const row = Math.floor(i / state.cols);
        const col = i % state.cols;

        const x = col * (cellW + gap);
        const y = row * (cellH + gap);

        ctx.fillStyle = colorForChange(s.change);
        ctx.fillRect(x, y, cellW, cellH);

        ctx.strokeStyle = "rgba(255,255,255,0.15)";
        ctx.strokeRect(x, y, cellW, cellH);

        ctx.fillStyle = "#fff";
        ctx.font = "bold 14px system-ui, sans-serif";
        ctx.fillText(s.symbol, x + 10, y + 22);

        ctx.font = "12px system-ui, sans-serif";
        ctx.fillText(`$${s.price.toFixed(2)}`, x + 10, y + 42);

        ctx.fillStyle = s.change >= 0 ? "#b6ffcf" : "#ffb6b6";
        ctx.fillText(`${s.change >= 0 ? "+" : ""}${s.change.toFixed(2)}`, x + 10, y + 62);
      });

      ctx.restore();
    }

    canvas.addEventListener("mousedown", (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.dragging) return;
      state.panX += e.clientX - state.lastX;
      state.panY += e.clientY - state.lastY;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      draw();
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const oldZoom = state.zoom;
      const newZoom = Math.min(4, Math.max(0.4, oldZoom * zoomFactor));

      // zoom around mouse position
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      state.panX = mouseX - ((mouseX - state.panX) * (newZoom / oldZoom));
      state.panY = mouseY - ((mouseY - state.panY) * (newZoom / oldZoom));
      state.zoom = newZoom;

      draw();
    }, { passive: false });

    window.addEventListener("resize", resize);

    initStocks();
    resize();
    draw();

    // Simulated real-time updates
    setInterval(updateStocks, 1000);
  </script>
</body>
</html>
