```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      overflow: hidden;
      font-family: system-ui, sans-serif;
      background: #0b1020;
      color: #e5e7eb;
    }

    #app {
      position: relative;
      width: 100vw;
      height: 100vh;
      user-select: none;
    }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      cursor: grab;
    }

    canvas:active {
      cursor: grabbing;
    }

    .hud {
      position: absolute;
      top: 12px;
      left: 12px;
      background: rgba(15, 23, 42, 0.85);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 13px;
      line-height: 1.4;
      backdrop-filter: blur(8px);
      pointer-events: none;
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      color: #fff;
      transform: translate(12px, 12px);
      display: none;
      white-space: nowrap;
    }

    .legend {
      margin-top: 6px;
      display: flex;
      gap: 8px;
      align-items: center;
    }

    .bar {
      width: 120px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, #dc2626, #111827, #16a34a);
      border: 1px solid rgba(255,255,255,0.12);
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="c"></canvas>
    <div class="hud">
      <div><strong>Stock Heatmap</strong></div>
      <div>Drag to pan • Wheel to zoom • Hover for details</div>
      <div class="legend">
        <span>Loss</span>
        <div class="bar"></div>
        <span>Gain</span>
      </div>
    </div>
    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById('c');
    const ctx = canvas.getContext('2d');
    const tooltip = document.getElementById('tooltip');

    const state = {
      dpr: Math.max(1, window.devicePixelRatio || 1),
      w: 0,
      h: 0,
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      lastX: 0,
      lastY: 0,
      mouseX: 0,
      mouseY: 0,
      hover: null,
      stocks: []
    };

    // Generate sample stocks
    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','TSLA','META','NFLX','AMD','INTC',
      'ORCL','CRM','ADBE','UBER','SHOP','SQ','PYPL','BABA','DIS','PEP',
      'KO','XOM','CVX','JPM','BAC','WMT','COST','T','V','MA',
      'NKE','PFE','MRNA','BA','GE','IBM','QCOM','AVGO','CSCO','TXN'
    ];

    function initStocks() {
      state.stocks = symbols.map((sym, i) => ({
        symbol: sym,
        price: 50 + Math.random() * 450,
        prev: 50 + Math.random() * 450,
        change: 0,
        x: 0,
        y: 0,
        w: 0,
        h: 0
      }));
    }

    function resize() {
      state.dpr = Math.max(1, window.devicePixelRatio || 1);
      state.w = canvas.clientWidth;
      state.h = canvas.clientHeight;
      canvas.width = Math.floor(state.w * state.dpr);
      canvas.height = Math.floor(state.h * state.dpr);
      ctx.setTransform(state.dpr, 0, 0, state.dpr, 0, 0);
    }

    function colorForChange(change) {
      // change in percent
      const t = Math.max(-1, Math.min(1, change / 5));
      if (t < 0) {
        const a = Math.abs(t);
        return `rgb(${Math.round(220 * a + 17 * (1-a))}, ${Math.round(38 * (1-a) + 24 * a)}, ${Math.round(38 * (1-a) + 39 * a)})`;
      } else {
        const a = t;
        return `rgb(${Math.round(22 * a + 17 * (1-a))}, ${Math.round(163 * a + 24 * (1-a))}, ${Math.round(74 * a + 39 * (1-a))})`;
      }
    }

    function layout() {
      const padding = 20;
      const cellMin = 90;
      const cols = Math.max(1, Math.floor((state.w - padding * 2) / cellMin));
      const cellW = Math.floor((state.w - padding * 2) / cols);
      const cellH = 70;

      state.stocks.forEach((s, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        s.x = padding + col * cellW;
        s.y = padding + row * cellH;
        s.w = cellW - 6;
        s.h = cellH - 6;
      });
    }

    function updatePrices() {
      for (const s of state.stocks) {
        s.prev = s.price;
        const drift = (Math.random() - 0.5) * 2.5;
        s.price = Math.max(1, s.price + drift);
        s.change = ((s.price - s.prev) / s.prev) * 100;
      }
    }

    function worldToScreen(x, y) {
      return {
        x: (x + state.panX) * state.zoom,
        y: (y + state.panY) * state.zoom
      };
    }

    function screenToWorld(x, y) {
      return {
        x: x / state.zoom - state.panX,
        y: y / state.zoom - state.panY
      };
    }

    function draw() {
      ctx.clearRect(0, 0, state.w, state.h);

      // background
      const g = ctx.createLinearGradient(0, 0, 0, state.h);
      g.addColorStop(0, '#0b1020');
      g.addColorStop(1, '#111827');
      ctx.fillStyle = g;
      ctx.fillRect(0, 0, state.w, state.h);

      ctx.save();
      ctx.scale(state.zoom, state.zoom);
      ctx.translate(state.panX, state.panY);

      for (const s of state.stocks) {
        const fill = colorForChange(s.change);
        const isHover = state.hover === s;

        ctx.fillStyle = fill;
        roundRect(ctx, s.x, s.y, s.w, s.h, 12);
        ctx.fill();

        ctx.strokeStyle = isHover ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.10)';
        ctx.lineWidth = isHover ? 2 : 1;
        ctx.stroke();

        ctx.fillStyle = '#fff';
        ctx.font = 'bold 16px system-ui, sans-serif';
        ctx.fillText(s.symbol, s.x + 12, s.y + 24);

        ctx.font = '12px system-ui, sans-serif';
        ctx.fillStyle = 'rgba(255,255,255,0.9)';
        ctx.fillText(`$${s.price.toFixed(2)}`, s.x + 12, s.y + 44);

        const ch = s.change >= 0 ? `+${s.change.toFixed(2)}%` : `${s.change.toFixed(2)}%`;
        ctx.fillStyle = 'rgba(255,255,255,0.85)';
        ctx.fillText(ch, s.x + s.w - 62, s.y + 24);
      }

      ctx.restore();
    }

    function roundRect(ctx, x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function hitTest(mx, my) {
      const p = screenToWorld(mx, my);
      for (const s of state.stocks) {
        if (p.x >= s.x && p.x <= s.x + s.w && p.y >= s.y && p.y <= s.y + s.h) {
          return s;
        }
      }
      return null;
    }

    canvas.addEventListener('mousedown', (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
    });

    window.addEventListener('mouseup', () => {
      state.dragging = false;
    });

    window.addEventListener('mousemove', (e) => {
      state.mouseX = e.clientX;
      state.mouseY = e.clientY;

      if (state.dragging) {
        const dx = (e.clientX - state.lastX) / state.zoom;
        const dy = (e.clientY - state.lastY) / state.zoom;
        state.panX += dx;
        state.panY += dy;
        state.lastX = e.clientX;
        state.lastY = e.clientY;
      }

      state.hover = hitTest(e.clientX, e.clientY);
      if (state.hover) {
        tooltip.style.display = 'block';
        tooltip.style.left = e.clientX + 'px';
        tooltip.style.top = e.clientY + 'px';
        const ch = state.hover.change >= 0 ? `+${state.hover.change.toFixed(2)}%` : `${state.hover.change.toFixed(2)}%`;
        tooltip.innerHTML = `
          <strong>${state.hover.symbol}</strong><br>
          Price: $${state.hover.price.toFixed(2)}<br>
          Change: ${ch}
        `;
      } else {
        tooltip.style.display = 'none';
      }
    });

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const before = screenToWorld(e.clientX, e.clientY);

      state.zoom = Math.max(0.5, Math.min(3, state.zoom * zoomFactor));

      const after = screenToWorld(e.clientX, e.clientY);
      state.panX += before.x - after.x;
      state.panY += before.y - after.y;
    }, { passive: false });

    window.addEventListener('resize', () => {
      resize();
      layout();
    });

    initStocks();
    resize();
    layout();

    // Initial centering
    state.panX = 0;
    state.panY = 0;

    setInterval(() => {
      updatePrices();
    }, 1000);

    function loop() {
      draw();
      requestAnimationFrame(loop);
    }
    loop();
  </script>
</body>
</html>
