      left: 0;
      top: 0;
      transform-origin: 0 0;
      will-change: transform;
    }

    .cell {
      position: absolute;
      width: 70px;
      height: 48px;
      border-radius: 8px;
      display: flex;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      font-size: 12px;
      font-weight: 600;
      color: white;
      box-shadow: inset 0 0 0 1px rgba(255,255,255,0.08);
      transition: background-color 0.2s linear, transform 0.1s;
    }

    .cell:hover {
      transform: scale(1.05);
      z-index: 2;
    }

    #tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(0,0,0,0.85);
      color: white;
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 12px;
      display: none;
      z-index: 20;
      white-space: nowrap;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="zoomIn">Zoom +</button>
    <button id="zoomOut">Zoom -</button>
    <button id="reset">Reset</button>
    <span id="status">Live</span>
  </div>

  <div id="viewport">
    <div id="world"></div>
  </div>

  <div id="tooltip"></div>

  <script>
    const viewport = document.getElementById('viewport');
    const world = document.getElementById('world');
    const tooltip = document.getElementById('tooltip');
    const status = document.getElementById('status');

    const rows = 8;
    const cols = 12;
    const cellW = 80;
    const cellH = 58;
    const gap = 10;

    let scale = 1;
    let panX = 40;
    let panY = 80;

    const stocks = [];
    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','TSLA','META','AMD',
      'NFLX','INTC','ORCL','CRM','UBER','SHOP','BABA','JPM',
      'BAC','XOM','CVX','KO','PEP','DIS','WMT','COST',
      'ADBE','QCOM','AVGO','PYPL','SNOW','PLTR','SQ','BA',
      'GE','F','GM','NKE','MCD','T','V','MA'
    ];

    function rand(min, max) {
      return Math.random() * (max - min) + min;
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function priceToColor(change) {
      // change in percent
      const t = clamp((change + 5) / 10, 0, 1); // map -5..+5 to 0..1
      const r = Math.round(220 * (1 - t));
      const g = Math.round(220 * t);
      const b = 60;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function buildGrid() {
      world.innerHTML = '';
      stocks.length = 0;

      let idx = 0;
      for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
          const symbol = symbols[idx % symbols.length];
          const price = rand(20, 500);
          const change = rand(-5, 5);

          const stock = {
            symbol,
            price,
            change,
            el: document.createElement('div')
          };

          stock.el.className = 'cell';
          stock.el.style.left = `${c * (cellW + gap)}px`;
          stock.el.style.top = `${r * (cellH + gap)}px`;
          stock.el.style.width = `${cellW}px`;
          stock.el.style.height = `${cellH}px`;

          stock.el.addEventListener('mousemove', (e) => {
            tooltip.style.display = 'block';
            tooltip.style.left = `${e.clientX + 12}px`;
            tooltip.style.top = `${e.clientY + 12}px`;
            tooltip.textContent = `${stock.symbol}  $${stock.price.toFixed(2)}  (${stock.change >= 0 ? '+' : ''}${stock.change.toFixed(2)}%)`;
          });

          stock.el.addEventListener('mouseleave', () => {
            tooltip.style.display = 'none';
          });

          world.appendChild(stock.el);
          stocks.push(stock);
          idx++;
        }
      }
      updateCells();
      updateTransform();
    }

    function updateCells() {
      for (const s of stocks) {
        s.el.style.background = priceToColor(s.change);
        s.el.innerHTML = `
          <div>${s.symbol}</div>
          <div style="opacity:.9">$${s.price.toFixed(0)}</div>
        `;
      }
    }

    function updateTransform() {
      world.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`;
    }

    function zoomAt(factor, cx, cy) {
      const rect = viewport.getBoundingClientRect();
      const x = cx - rect.left;
      const y = cy - rect.top;

      const worldX = (x - panX) / scale;
      const worldY = (y - panY) / scale;

      scale = clamp(scale * factor, 0.4, 3);

      panX = x - worldX * scale;
      panY = y - worldY * scale;

      updateTransform();
    }

    document.getElementById('zoomIn').onclick = () => zoomAt(1.2, window.innerWidth / 2, window.innerHeight / 2);
    document.getElementById('zoomOut').onclick = () => zoomAt(1 / 1.2, window.innerWidth / 2, window.innerHeight / 2);
    document.getElementById('reset').onclick = () => {
      scale = 1;
      panX = 40;
      panY = 80;
      updateTransform();
    };

    viewport.addEventListener('wheel', (e) => {
      e.preventDefault();
      const factor = e.deltaY < 0 ? 1.1 : 1 / 1.1;
      zoomAt(factor, e.clientX, e.clientY);
    }, { passive: false });

    let dragging = false;
    let startX = 0, startY = 0;
    let startPanX = 0, startPanY = 0;

    viewport.addEventListener('mousedown', (e) => {
      dragging = true;
      viewport.classList.add('dragging');
      startX = e.clientX;
      startY = e.clientY;
      startPanX = panX;
      startPanY = panY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      panX = startPanX + (e.clientX - startX);
      panY = startPanY + (e.clientY - startY);
      updateTransform();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      viewport.classList.remove('dragging');
    });

    // Simulated real-time updates
    setInterval(() => {
      for (const s of stocks) {
        const delta = rand(-1.2, 1.2);
        s.change = clamp(s.change + delta * 0.15, -6, 6);
        s.price = Math.max(1, s.price * (1 + delta / 100));
      }
      updateCells();
      status.textContent = `Live • ${new Date().toLocaleTimeString()}`;
    }, 1000);

    buildGrid();
    window.addEventListener('resize', updateTransform);
  </script>
</body>
</html>
