Below is a minimal working client-side stock price heatmap that:

- renders a heatmap in the browser
- updates in real time with simulated stock prices
- supports zoom via mouse wheel
- supports pan by dragging
- uses only HTML/CSS/JS and Canvas

You can save this as `index.html` and open it directly in a browser.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      overflow: hidden;
      background: #0b1020;
      color: #e5e7eb;
      font-family: system-ui, sans-serif;
    }
    #toolbar {
      position: fixed;
      top: 12px;
      left: 12px;
      z-index: 10;
      background: rgba(17, 24, 39, 0.85);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 10px;
      padding: 10px 12px;
      backdrop-filter: blur(8px);
      box-shadow: 0 8px 24px rgba(0,0,0,0.25);
      font-size: 14px;
      line-height: 1.4;
    }
    #toolbar b { color: #fff; }
    canvas {
      display: block;
      width: 100vw;
      height: 100vh;
      cursor: grab;
    }
    canvas.dragging {
      cursor: grabbing;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <b>Stock Heatmap</b><br>
    Wheel: zoom<br>
    Drag: pan<br>
    Real-time simulated updates
  </div>
  <canvas id="c"></canvas>

  <script>
    const canvas = document.getElementById('c');
    const ctx = canvas.getContext('2d');

    const symbols = [
      'AAPL','MSFT','GOOGL','AMZN','NVDA','TSLA','META','NFLX',
      'AMD','INTC','ORCL','CRM','UBER','SHOP','ADBE','PYPL'
    ];

    const data = symbols.map((s, i) => ({
      symbol: s,
      price: 100 + Math.random() * 200,
      prev: 100 + Math.random() * 200,
      x: i % 4,
      y: Math.floor(i / 4)
    }));

    let dpr = window.devicePixelRatio || 1;
    let width = 0, height = 0;

    let view = {
      scale: 1,
      offsetX: 0,
      offsetY: 0
    };

    let dragging = false;
    let lastX = 0;
    let lastY = 0;

    function resize() {
      dpr = window.devicePixelRatio || 1;
      width = window.innerWidth;
      height = window.innerHeight;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';
      draw();
    }

    function priceToColor(change) {
      // change in percent
      const t = Math.max(-1, Math.min(1, change / 5)); // clamp around +/-5%
      if (t >= 0) {
        const g = Math.floor(80 + 175 * t);
        const r = Math.floor(40 + 40 * (1 - t));
        return `rgb(${r},${g},70)`;
      } else {
        const a = Math.abs(t);
        const r = Math.floor(80 + 175 * a);
        const g = Math.floor(40 + 40 * (1 - a));
        return `rgb(${r},${g},70)`;
      }
    }

    function drawRoundedRect(x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    function draw() {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, width, height);

      // background
      const bg = ctx.createLinearGradient(0, 0, 0, height);
      bg.addColorStop(0, '#0b1020');
      bg.addColorStop(1, '#111827');
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, width, height);

      const cols = 4;
      const rows = Math.ceil(data.length / cols);
      const cellW = 180;
      const cellH = 110;
      const gap = 12;

      const gridW = cols * cellW + (cols - 1) * gap;
      const gridH = rows * cellH + (rows - 1) * gap;

      const originX = (width - gridW * view.scale) / 2 + view.offsetX;
      const originY = (height - gridH * view.scale) / 2 + view.offsetY;

      ctx.save();
      ctx.translate(originX, originY);
      ctx.scale(view.scale, view.scale);

      data.forEach((d, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const x = col * (cellW + gap);
        const y = row * (cellH + gap);

        const changePct = ((d.price - d.prev) / d.prev) * 100;
        const color = priceToColor(changePct);

        // tile
        ctx.fillStyle = color;
        drawRoundedRect(x, y, cellW, cellH, 14);
        ctx.fill();

        // subtle border
        ctx.strokeStyle = 'rgba(255,255,255,0.12)';
        ctx.lineWidth = 1;
        ctx.stroke();

        // text
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 18px system-ui, sans-serif';
        ctx.fillText(d.symbol, x + 14, y + 28);

        ctx.font = '14px system-ui, sans-serif';
        ctx.fillText(`$${d.price.toFixed(2)}`, x + 14, y + 54);

        const sign = changePct >= 0 ? '+' : '';
        ctx.fillText(`${sign}${changePct.toFixed(2)}%`, x + 14, y + 78);
      });

      ctx.restore();

      // HUD
      ctx.fillStyle = 'rgba(255,255,255,0.75)';
      ctx.font = '12px system-ui, sans-serif';
      ctx.fillText(`Zoom: ${view.scale.toFixed(2)}x`, 16, height - 18);
    }

    function updatePrices() {
      data.forEach(d => {
        d.prev = d.price;
        const drift = (Math.random() - 0.5) * 2.5;
        d.price = Math.max(1, d.price + drift);
      });
      draw();
    }

    canvas.addEventListener('wheel', (e) => {
      e.preventDefault();

      const zoomFactor = e.deltaY < 0 ? 1.08 : 0.92;
      const oldScale = view.scale;
      const newScale = Math.min(4, Math.max(0.5, oldScale * zoomFactor));

      // zoom around mouse position
      const rect = canvas.getBoundingClientRect();
      const mx = e.clientX - rect.left;
      const my = e.clientY - rect.top;

      const worldX = (mx - (width - 0) / 2 - view.offsetX) / oldScale;
      const worldY = (my - (height - 0) / 2 - view.offsetY) / oldScale;

      view.scale = newScale;
      view.offsetX = mx - (width - 0) / 2 - worldX * newScale;
      view.offsetY = my - (height - 0) / 2 - worldY * newScale;

      draw();
    }, { passive: false });

    canvas.addEventListener('mousedown', (e) => {
      dragging = true;
      canvas.classList.add('dragging');
      lastX = e.clientX;
      lastY = e.clientY;
    });

    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      view.offsetX += e.clientX - lastX;
      view.offsetY += e.clientY - lastY;
      lastX = e.clientX;
      lastY = e.clientY;
      draw();
    });

    window.addEventListener('mouseup', () => {
      dragging = false;
      canvas.classList.remove('dragging');
    });

    window.addEventListener('resize', resize);

    resize();
    draw();
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
