      width: 100vw;
      height: calc(100vh - 58px);
      overflow: hidden;
      cursor: grab;
      user-select: none;
      touch-action: none;
    }

    #viewport.dragging {
      cursor: grabbing;
    }

    #heatmap {
      position: absolute;
      left: 0;
      top: 0;
      display: grid;
      gap: var(--grid-gap);
      padding: 12px;
      transform-origin: 0 0;
      will-change: transform;
    }

    .cell {
      width: 110px;
      height: 72px;
      border-radius: 10px;
      padding: 8px;
      box-sizing: border-box;
      color: white;
      display: flex;
      flex-direction: column;
      justify-content: space-between;
      box-shadow: 0 0 0 1px rgba(255,255,255,0.08) inset;
      transition: background 0.15s linear;
    }

    .symbol {
      font-weight: 700;
      font-size: 14px;
    }

    .price {
      font-size: 18px;
      font-weight: 600;
    }

    .change {
      font-size: 12px;
      opacity: 0.9;
    }

    #tooltip {
      position: fixed;
      pointer-events: none;
      background: rgba(10, 14, 28, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      color: white;
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 13px;
      display: none;
      z-index: 20;
      white-space: nowrap;
    }
  </style>
</head>
<body>
  <div class="toolbar">
    <button id="zoomIn">Zoom In</button>
    <button id="zoomOut">Zoom Out</button>
    <button id="reset">Reset</button>
    <div class="info">Wheel to zoom, drag to pan, hover for details</div>
  </div>

  <div id="viewport">
    <div id="heatmap"></div>
  </div>

  <div id="tooltip"></div>

  <script>
    const symbols = [
      "AAPL","MSFT","GOOGL","AMZN","NVDA","TSLA","META","NFLX",
      "AMD","INTC","ORCL","IBM","CRM","ADBE","QCOM","AVGO",
      "JPM","BAC","WFC","GS","MS","C","V","MA"
    ];

    const heatmap = document.getElementById("heatmap");
    const viewport = document.getElementById("viewport");
    const tooltip = document.getElementById("tooltip");

    const cols = 4;
    heatmap.style.gridTemplateColumns = `repeat(${cols}, 110px)`;

    const state = {
      scale: 1,
      x: 0,
      y: 0,
      dragging: false,
      startX: 0,
      startY: 0,
      panX: 0,
      panY: 0,
      prices: {}
    };

    function randomPrice(base) {
      return base + (Math.random() - 0.5) * base * 0.02;
    }

    function initData() {
      symbols.forEach(sym => {
        const base = 50 + Math.random() * 450;
        state.prices[sym] = {
          price: base,
          prev: base
        };
      });
    }

    function changeColor(changePct) {
      // red for negative, green for positive
      const intensity = Math.min(Math.abs(changePct) * 10, 1);
      if (changePct >= 0) {
        const g = Math.floor(70 + intensity * 160);
        return `rgb(20, ${g}, 60)`;
      } else {
        const r = Math.floor(70 + intensity * 160);
        return `rgb(${r}, 35, 45)`;
      }
    }

    function render() {
      heatmap.innerHTML = "";
      symbols.forEach(sym => {
        const { price, prev } = state.prices[sym];
        const changePct = ((price - prev) / prev) * 100;

        const cell = document.createElement("div");
        cell.className = "cell";
        cell.style.background = changeColor(changePct);
        cell.innerHTML = `
          <div class="symbol">${sym}</div>
          <div class="price">$${price.toFixed(2)}</div>
          <div class="change">${changePct >= 0 ? "+" : ""}${changePct.toFixed(2)}%</div>
        `;

        cell.addEventListener("mouseenter", (e) => {
          tooltip.style.display = "block";
          tooltip.innerHTML = `
            <strong>${sym}</strong><br>
            Price: $${price.toFixed(2)}<br>
            Change: ${changePct >= 0 ? "+" : ""}${changePct.toFixed(2)}%
          `;
        });

        cell.addEventListener("mousemove", (e) => {
          tooltip.style.left = (e.clientX + 12) + "px";
          tooltip.style.top = (e.clientY + 12) + "px";
        });

        cell.addEventListener("mouseleave", () => {
          tooltip.style.display = "none";
        });

        heatmap.appendChild(cell);
      });

      heatmap.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
    }

    function updatePrices() {
      symbols.forEach(sym => {
        const item = state.prices[sym];
        item.prev = item.price;
        item.price = randomPrice(item.price);
      });
      render();
    }

    function setTransform() {
      heatmap.style.transform = `translate(${state.x}px, ${state.y}px) scale(${state.scale})`;
    }

    viewport.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      state.scale = Math.min(3, Math.max(0.5, state.scale * zoomFactor));
      setTransform();
    }, { passive: false });

    viewport.addEventListener("pointerdown", (e) => {
      state.dragging = true;
      viewport.classList.add("dragging");
      state.startX = e.clientX;
      state.startY = e.clientY;
      state.panX = state.x;
      state.panY = state.y;
      viewport.setPointerCapture(e.pointerId);
    });

    viewport.addEventListener("pointermove", (e) => {
      if (!state.dragging) return;
      state.x = state.panX + (e.clientX - state.startX);
      state.y = state.panY + (e.clientY - state.startY);
      setTransform();
    });

    viewport.addEventListener("pointerup", (e) => {
      state.dragging = false;
      viewport.classList.remove("dragging");
      viewport.releasePointerCapture(e.pointerId);
    });

    document.getElementById("zoomIn").addEventListener("click", () => {
      state.scale = Math.min(3, state.scale * 1.15);
      setTransform();
    });

    document.getElementById("zoomOut").addEventListener("click", () => {
      state.scale = Math.max(0.5, state.scale / 1.15);
      setTransform();
    });

    document.getElementById("reset").addEventListener("click", () => {
      state.scale = 1;
      state.x = 0;
      state.y = 0;
      setTransform();
    });

    initData();
    render();
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
```

