## Minimal working example

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      overflow: hidden;
      font-family: system-ui, sans-serif;
      background: #0b1020;
      color: #e5e7eb;
    }

    #app {
      position: relative;
      width: 100vw;
      height: 100vh;
      user-select: none;
      cursor: grab;
    }
    #app.dragging { cursor: grabbing; }

    canvas {
      display: block;
      width: 100%;
      height: 100%;
      background: #0b1020;
    }

    .hud {
      position: absolute;
      top: 12px;
      left: 12px;
      background: rgba(15, 23, 42, 0.85);
      border: 1px solid rgba(255,255,255,0.08);
      border-radius: 10px;
      padding: 10px 12px;
      font-size: 13px;
      line-height: 1.4;
      backdrop-filter: blur(6px);
    }

    .tooltip {
      position: absolute;
      pointer-events: none;
      background: rgba(15, 23, 42, 0.95);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: 8px;
      padding: 8px 10px;
      font-size: 12px;
      transform: translate(12px, 12px);
      display: none;
      white-space: nowrap;
    }

    .legend {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 8px;
    }

    .bar {
      width: 140px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(90deg, #dc2626, #111827, #16a34a);
      border: 1px solid rgba(255,255,255,0.12);
    }
  </style>
</head>
<body>
  <div id="app">
    <canvas id="c"></canvas>

    <div class="hud">
      <div><strong>Stock Heatmap</strong></div>
      <div>Wheel: zoom</div>
      <div>Drag: pan</div>
      <div>Hover: inspect</div>
      <div class="legend">
        <span>Loss</span>
        <div class="bar"></div>
        <span>Gain</span>
      </div>
    </div>

    <div id="tooltip" class="tooltip"></div>
  </div>

  <script>
    const canvas = document.getElementById('c');
    const ctx = canvas.getContext('2d');
    const app = document.getElementById('app');
    const tooltip = document.getElementById('tooltip');

    const state = {
      dpr: Math.max(1, window.devicePixelRatio || 1),
      cols: 20,
      rows: 12,
      cellSize: 70,
      gap: 6,
      panX: 0,
      panY: 0,
      zoom: 1,
      dragging: false,
      lastX: 0,
      lastY: 0,
      hover: null,
      stocks: []
    };

    // Create mock stock data
    const symbols = Array.from({ length: state.cols * state.rows }, (_, i) => {
      const prefixes = ["A", "B", "C", "D", "E", "F", "G", "H", "I", "J"];
      return prefixes[i % prefixes.length] + String(i).padStart(3, "0");
    });

    state.stocks = symbols.map((symbol, i) => ({
      symbol,
      price: 50 + Math.random() * 250,
      change: (Math.random() - 0.5) * 8,
      volume: Math.floor(1e5 + Math.random() * 9e5),
      row: Math.floor(i / state.cols),
      col: i % state.cols
    }));

    function resize() {
      const rect = canvas.getBoundingClientRect();
      canvas.width = Math.floor(rect.width * state.dpr);
      canvas.height = Math.floor(rect.height * state.dpr);
      draw();
    }

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    function colorForChange(change) {
      // Map change roughly from -10..10 to red->dark->green
      const t = clamp((change + 10) / 20, 0, 1);
      const r = Math.round(220 * (1 - t));
      const g = Math.round(220 * t);
      const b = 60;
      const mid = 0.5;
      if (Math.abs(t - mid) < 0.08) return `rgb(17,24,39)`;
      return `rgb(${r}, ${g}, ${b})`;
    }

    function draw() {
      const w = canvas.width;
      const h = canvas.height;
      ctx.clearRect(0, 0, w, h);

      // Background
      ctx.fillStyle = "#0b1020";
      ctx.fillRect(0, 0, w, h);

      const baseCell = state.cellSize * state.zoom * state.dpr;
      const gap = state.gap * state.zoom * state.dpr;
      const totalW = state.cols * (baseCell + gap);
      const totalH = state.rows * (baseCell + gap);

      const startX = state.panX * state.dpr + w / 2 - totalW / 2;
      const startY = state.panY * state.dpr + h / 2 - totalH / 2;

      // Draw cells
      for (const s of state.stocks) {
        const x = startX + s.col * (baseCell + gap);
        const y = startY + s.row * (baseCell + gap);

        if (x > w || y > h || x + baseCell < 0 || y + baseCell < 0) continue;

        const isHover = state.hover && state.hover.symbol === s.symbol;

        ctx.fillStyle = colorForChange(s.change);
        roundRect(ctx, x, y, baseCell, baseCell, 10 * state.zoom * state.dpr);
        ctx.fill();

        if (isHover) {
          ctx.strokeStyle = "#ffffff";
          ctx.lineWidth = 3 * state.dpr;
          ctx.stroke();
        } else {
          ctx.strokeStyle = "rgba(255,255,255,0.08)";
          ctx.lineWidth = 1 * state.dpr;
          ctx.stroke();
        }

        // Text
        ctx.fillStyle = "#fff";
        ctx.font = `${12 * state.zoom * state.dpr}px system-ui, sans-serif`;
        ctx.textAlign = "center";
        ctx.textBaseline = "middle";
        ctx.fillText(s.symbol, x + baseCell / 2, y + baseCell / 2 - 8 * state.zoom * state.dpr);

        ctx.font = `${11 * state.zoom * state.dpr}px system-ui, sans-serif`;
        const changeText = `${s.change >= 0 ? "+" : ""}${s.change.toFixed(2)}%`;
        ctx.fillText(changeText, x + baseCell / 2, y + baseCell / 2 + 10 * state.zoom * state.dpr);
      }
    }

    function roundRect(ctx, x, y, w, h, r) {
      r = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.arcTo(x + w, y, x + w, y + h, r);
      ctx.arcTo(x + w, y + h, x, y + h, r);
      ctx.arcTo(x, y + h, x, y, r);
      ctx.arcTo(x, y, x + w, y, r);
      ctx.closePath();
    }

    function screenToCell(mx, my) {
      const rect = canvas.getBoundingClientRect();
      const x = (mx - rect.left) * state.dpr;
      const y = (my - rect.top) * state.dpr;

      const baseCell = state.cellSize * state.zoom * state.dpr;
      const gap = state.gap * state.zoom * state.dpr;
      const totalW = state.cols * (baseCell + gap);
      const totalH = state.rows * (baseCell + gap);

      const startX = state.panX * state.dpr + canvas.width / 2 - totalW / 2;
      const startY = state.panY * state.dpr + canvas.height / 2 - totalH / 2;

      for (const s of state.stocks) {
        const sx = startX + s.col * (baseCell + gap);
        const sy = startY + s.row * (baseCell + gap);
        if (x >= sx && x <= sx + baseCell && y >= sy && y <= sy + baseCell) return s;
      }
      return null;
    }

    function updateTooltip(mx, my, stock) {
      if (!stock) {
        tooltip.style.display = "none";
        return;
      }
      tooltip.style.display = "block";
      tooltip.style.left = `${mx}px`;
      tooltip.style.top = `${my}px`;
      tooltip.innerHTML = `
        <strong>${stock.symbol}</strong><br>
        Price: $${stock.price.toFixed(2)}<br>
        Change: ${stock.change >= 0 ? "+" : ""}${stock.change.toFixed(2)}%<br>
        Volume: ${stock.volume.toLocaleString()}
      `;
    }

    canvas.addEventListener("mousemove", (e) => {
      if (state.dragging) {
        const dx = e.clientX - state.lastX;
        const dy = e.clientY - state.lastY;
        state.panX += dx;
        state.panY += dy;
        state.lastX = e.clientX;
        state.lastY = e.clientY;
        draw();
        return;
      }

      const stock = screenToCell(e.clientX, e.clientY);
      state.hover = stock;
      updateTooltip(e.clientX, e.clientY, stock);
      draw();
    });

    canvas.addEventListener("mousedown", (e) => {
      state.dragging = true;
      app.classList.add("dragging");
      state.lastX = e.clientX;
      state.lastY = e.clientY;
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      app.classList.remove("dragging");
    });

    canvas.addEventListener("mouseleave", () => {
      if (!state.dragging) {
        state.hover = null;
        tooltip.style.display = "none";
        draw();
      }
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();
      const delta = -e.deltaY * 0.001;
      state.zoom = clamp(state.zoom * (1 + delta), 0.5, 3);
      draw();
    }, { passive: false });

    // Simulated real-time updates
    setInterval(() => {
      for (const s of state.stocks) {
        s.change += (Math.random() - 0.5) * 0.8;
        s.change = clamp(s.change, -12, 12);
        s.price *= 1 + (Math.random() - 0.5) * 0.01;
        s.volume = Math.max(1000, s.volume + Math.floor((Math.random() - 0.5) * 5000));
      }
      draw();
    }, 1000);

    window.addEventListener("resize", resize);

    resize();
  </script>
</body>
</html>
```

