Save as `index.html` and open it in a browser.

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Stock Heatmap</title>
  <style>
    html, body {
      margin: 0;
      height: 100%;
      overflow: hidden;
      font-family: system-ui, sans-serif;
      background: #0b1020;
      color: #e5e7eb;
    }
    #toolbar {
      position: fixed;
      top: 10px;
      left: 10px;
      z-index: 10;
      background: rgba(17, 24, 39, 0.85);
      padding: 10px 12px;
      border-radius: 10px;
      backdrop-filter: blur(6px);
      box-shadow: 0 4px 20px rgba(0,0,0,0.25);
      font-size: 14px;
    }
    #canvas {
      display: block;
      width: 100vw;
      height: 100vh;
      cursor: grab;
    }
    #canvas.dragging {
      cursor: grabbing;
    }
    .hint {
      opacity: 0.8;
      font-size: 12px;
      margin-top: 4px;
    }
  </style>
</head>
<body>
  <div id="toolbar">
    <div><strong>Stock Heatmap</strong></div>
    <div id="status">Loading...</div>
    <div class="hint">Wheel = zoom, drag = pan</div>
  </div>
  <canvas id="canvas"></canvas>

  <script>
    const canvas = document.getElementById("canvas");
    const ctx = canvas.getContext("2d");
    const statusEl = document.getElementById("status");

    const state = {
      zoom: 1,
      panX: 0,
      panY: 0,
      dragging: false,
      lastX: 0,
      lastY: 0,
      cols: 12,
      rows: 8,
      cellW: 90,
      cellH: 70,
      stocks: []
    };

    const symbols = [
      "AAPL","MSFT","GOOG","AMZN","META","NVDA","TSLA","NFLX",
      "AMD","INTC","ORCL","IBM","CRM","ADBE","UBER","SHOP",
      "BABA","QCOM","PYPL","SNOW","COST","PEP","KO","DIS",
      "BAC","JPM","WMT","T","V","MA","XOM","CVX",
      "PFE","MRNA","NKE","SBUX","BA","GE","CAT","HON",
      "LLY","UNH","HD","LOW","SPOT","SQ","PLTR","RIVN"
    ];

    function resize() {
      const dpr = window.devicePixelRatio || 1;
      canvas.width = Math.floor(window.innerWidth * dpr);
      canvas.height = Math.floor(window.innerHeight * dpr);
      canvas.style.width = window.innerWidth + "px";
      canvas.style.height = window.innerHeight + "px";
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      draw();
    }

    function initStocks() {
      const count = state.cols * state.rows;
      state.stocks = Array.from({ length: count }, (_, i) => {
        const base = 50 + Math.random() * 450;
        return {
          symbol: symbols[i % symbols.length] + (i >= symbols.length ? i : ""),
          price: base,
          prev: base,
          change: 0
        };
      });
    }

    function priceToColor(changePct) {
      // red for negative, green for positive
      const t = Math.max(-1, Math.min(1, changePct / 5));
      const r = t < 0 ? 220 : Math.round(40 + 40 * (1 - t));
      const g = t > 0 ? 220 : Math.round(40 + 40 * (1 + t));
      const b = 60;
      return `rgb(${r},${g},${b})`;
    }

    function updatePrices() {
      for (const s of state.stocks) {
        s.prev = s.price;
        const drift = (Math.random() - 0.5) * 2.5;
        s.price = Math.max(1, s.price + drift);
        s.change = ((s.price - s.prev) / s.prev) * 100;
      }
      const avg = state.stocks.reduce((a, s) => a + s.change, 0) / state.stocks.length;
      statusEl.textContent = `Live updates | Avg change: ${avg.toFixed(2)}%`;
      draw();
    }

    function draw() {
      const w = window.innerWidth;
      const h = window.innerHeight;
      ctx.clearRect(0, 0, w, h);

      // background
      const bg = ctx.createLinearGradient(0, 0, 0, h);
      bg.addColorStop(0, "#0b1020");
      bg.addColorStop(1, "#111827");
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);

      ctx.save();
      ctx.translate(state.panX, state.panY);
      ctx.scale(state.zoom, state.zoom);

      const margin = 12;
      const totalW = state.cols * (state.cellW + margin);
      const totalH = state.rows * (state.cellH + margin);

      const startX = (w / state.zoom - totalW) / 2;
      const startY = (h / state.zoom - totalH) / 2;

      state.stocks.forEach((s, i) => {
        const col = i % state.cols;
        const row = Math.floor(i / state.cols);
        const x = startX + col * (state.cellW + margin);
        const y = startY + row * (state.cellH + margin);

        ctx.fillStyle = priceToColor(s.change);
        roundRect(ctx, x, y, state.cellW, state.cellH, 12);
        ctx.fill();

        ctx.strokeStyle = "rgba(255,255,255,0.08)";
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.fillStyle = "white";
        ctx.font = "bold 14px system-ui, sans-serif";
        ctx.fillText(s.symbol, x + 10, y + 22);

        ctx.font = "12px system-ui, sans-serif";
        ctx.fillText(`$${s.price.toFixed(2)}`, x + 10, y + 42);

        ctx.fillStyle = s.change >= 0 ? "#d1fae5" : "#fee2e2";
        ctx.fillText(`${s.change >= 0 ? "+" : ""}${s.change.toFixed(2)}%`, x + 10, y + 60);
      });

      ctx.restore();
    }

    function roundRect(ctx, x, y, w, h, r) {
      const rr = Math.min(r, w / 2, h / 2);
      ctx.beginPath();
      ctx.moveTo(x + rr, y);
      ctx.arcTo(x + w, y, x + w, y + h, rr);
      ctx.arcTo(x + w, y + h, x, y + h, rr);
      ctx.arcTo(x, y + h, x, y, rr);
      ctx.arcTo(x, y, x + w, y, rr);
      ctx.closePath();
    }

    canvas.addEventListener("mousedown", (e) => {
      state.dragging = true;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      canvas.classList.add("dragging");
    });

    window.addEventListener("mouseup", () => {
      state.dragging = false;
      canvas.classList.remove("dragging");
    });

    window.addEventListener("mousemove", (e) => {
      if (!state.dragging) return;
      state.panX += e.clientX - state.lastX;
      state.panY += e.clientY - state.lastY;
      state.lastX = e.clientX;
      state.lastY = e.clientY;
      draw();
    });

    canvas.addEventListener("wheel", (e) => {
      e.preventDefault();
      const zoomFactor = e.deltaY < 0 ? 1.1 : 0.9;
      const mouseX = e.clientX;
      const mouseY = e.clientY;

      // zoom around cursor
      const beforeX = (mouseX - state.panX) / state.zoom;
      const beforeY = (mouseY - state.panY) / state.zoom;

      state.zoom = Math.max(0.5, Math.min(3, state.zoom * zoomFactor));

      state.panX = mouseX - beforeX * state.zoom;
      state.panY = mouseY - beforeY * state.zoom;

      draw();
    }, { passive: false });

    window.addEventListener("resize", resize);

    initStocks();
    resize();
    updatePrices();
    setInterval(updatePrices, 1000);
  </script>
</body>
</html>
```

