## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

/**
 * In-memory board state
 * Replace with a database for production use.
 */
let board = {
  todo: [
    { id: "task-1", title: "Design homepage", description: "Create wireframe and layout" },
    { id: "task-2", title: "Set up auth", description: "Implement login flow" }
  ],
  doing: [
    { id: "task-3", title: "Build API", description: "Create task endpoints" }
  ],
  done: []
};

function findTask(taskId) {
  for (const column of Object.keys(board)) {
    const index = board[column].findIndex(task => task.id === taskId);
    if (index !== -1) {
      return { column, index, task: board[column][index] };
    }
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current board state to newly connected client
  socket.emit("board:update", board);

  // Handle task movement
  socket.on("task:move", ({ taskId, fromColumn, toColumn, toIndex }) => {
    if (!board[fromColumn] || !board[toColumn]) return;

    const taskIndex = board[fromColumn].findIndex(task => task.id === taskId);
    if (taskIndex === -1) return;

    const [task] = board[fromColumn].splice(taskIndex, 1);

    const insertIndex = Math.max(0, Math.min(toIndex, board[toColumn].length));
    board[toColumn].splice(insertIndex, 0, task);

    io.emit("board:update", board);
  });

  // Handle task creation
  socket.on("task:create", ({ title, description }) => {
    const newTask = {
      id: `task-${Date.now()}`,
      title: title || "Untitled Task",
      description: description || ""
    };

    board.todo.unshift(newTask);
    io.emit("board:update", board);
  });

  // Handle task deletion
  socket.on("task:delete", ({ taskId }) => {
    for (const column of Object.keys(board)) {
      const index = board[column].findIndex(task => task.id === taskId);
      if (index !== -1) {
        board[column].splice(index, 1);
        io.emit("board:update", board);
        break;
      }
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
