## 5) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const taskTemplate = document.getElementById("taskTemplate");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescInput = document.getElementById("taskDesc");

let currentBoard = {};
let draggedTaskId = null;
let draggedFromColumn = null;

function renderBoard(board) {
  currentBoard = board;

  for (const columnName of ["todo", "doing", "done"]) {
    const listEl = document.getElementById(columnName);
    listEl.innerHTML = "";

    board[columnName].forEach((task, index) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.column = columnName;
      taskEl.dataset.index = index;

      taskNode.querySelector(".task-title").textContent = task.title;
      taskNode.querySelector(".task-desc").textContent = task.description;

      taskEl.addEventListener("dragstart", (e) => {
        draggedTaskId = task.id;
        draggedFromColumn = columnName;
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("text/plain", task.id);
      });

      taskEl.addEventListener("dragend", () => {
        draggedTaskId = null;
        draggedFromColumn = null;
        document.querySelectorAll(".task-list").forEach(el => el.classList.remove("drag-over"));
      });

      taskNode.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      listEl.appendChild(taskNode);
    });
  }
}

function getDropIndex(listEl, clientY) {
  const tasks = [...listEl.querySelectorAll(".task:not(.dragging)")];
  if (tasks.length === 0) return 0;

  let closest = { offset: Number.NEGATIVE_INFINITY, index: 0 };

  tasks.forEach((task, index) => {
    const rect = task.getBoundingClientRect();
    const offset = clientY - rect.top - rect.height / 2;

    if (offset < 0 && offset > closest.offset) {
      closest = { offset, index };
    }
  });

  return closest.index;
}

document.querySelectorAll(".task-list").forEach((listEl) => {
  listEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    listEl.classList.add("drag-over");
  });

  listEl.addEventListener("dragleave", () => {
    listEl.classList.remove("drag-over");
  });

  listEl.addEventListener("drop", (e) => {
    e.preventDefault();
    listEl.classList.remove("drag-over");

    if (!draggedTaskId || !draggedFromColumn) return;

    const toColumn = listEl.id;
    const toIndex = getDropIndex(listEl, e.clientY);

    socket.emit("task:move", {
      taskId: draggedTaskId,
      fromColumn: draggedFromColumn,
      toColumn,
      toIndex
    });
  });
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  const description = taskDescInput.value.trim();

  socket.emit("task:create", { title, description });

  taskTitleInput.value = "";
  taskDescInput.value = "";
  taskTitleInput.focus();
});

taskDescInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

socket.on("board:update", (board) => {
  renderBoard(board);
});

// Initial empty render until server sends board
renderBoard({
  todo: [],
  doing: [],
  done: []
});
```

