## 3) Backend — `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory data store
let boards = [
  {
    id: "todo",
    title: "To Do",
    tasks: [
      { id: "1", title: "Design app layout", description: "Create initial wireframes", assignee: "Alex" },
      { id: "2", title: "Set up auth", description: "Implement login flow", assignee: "Sam" }
    ]
  },
  {
    id: "doing",
    title: "In Progress",
    tasks: [
      { id: "3", title: "Build task board", description: "Implement drag and drop", assignee: "Jordan" }
    ]
  },
  {
    id: "done",
    title: "Done",
    tasks: [
      { id: "4", title: "Initialize project", description: "Set up repo and tooling", assignee: "Taylor" }
    ]
  }
];

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.post("/api/tasks", (req, res) => {
  const { boardId, task } = req.body;
  const board = boards.find((b) => b.id === boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  const newTask = {
    id: crypto.randomUUID(),
    title: task.title || "Untitled Task",
    description: task.description || "",
    assignee: task.assignee || ""
  };

  board.tasks.push(newTask);
  io.emit("boards:update", boards);
  res.status(201).json(newTask);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const updatedTask = req.body;

  for (const board of boards) {
    const taskIndex = board.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex !== -1) {
      board.tasks[taskIndex] = { ...board.tasks[taskIndex], ...updatedTask };
      io.emit("boards:update", boards);
      return res.json(board.tasks[taskIndex]);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const board of boards) {
    const taskIndex = board.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex !== -1) {
      const deleted = board.tasks.splice(taskIndex, 1)[0];
      io.emit("boards:update", boards);
      return res.json(deleted);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.post("/api/move-task", (req, res) => {
  const { taskId, sourceBoardId, destinationBoardId, destinationIndex } = req.body;

  const sourceBoard = boards.find((b) => b.id === sourceBoardId);
  const destinationBoard = boards.find((b) => b.id === destinationBoardId);

  if (!sourceBoard || !destinationBoard) {
    return res.status(404).json({ error: "Board not found" });
  }

  const taskIndex = sourceBoard.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return res.status(404).json({ error: "Task not found" });

  const [task] = sourceBoard.tasks.splice(taskIndex, 1);
  destinationBoard.tasks.splice(destinationIndex, 0, task);

  io.emit("boards:update", boards);
  res.json({ success: true, boards });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("boards:update", boards);

  socket.on("boards:request", () => {
    socket.emit("boards:update", boards);
  });

  socket.on("boards:sync", (updatedBoards) => {
    boards = updatedBoards;
    io.emit("boards:update", boards);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

