import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:3001");

export default function App() {
  const [boards, setBoards] = useState([]);
  const [draggedTask, setDraggedTask] = useState(null);
  const [newTask, setNewTask] = useState({
    title: "",
    description: "",
    assignee: "",
    boardId: "todo"
  });

  useEffect(() => {
    socket.on("boards:update", (updatedBoards) => {
      setBoards(updatedBoards);
    });

    socket.emit("boards:request");

    return () => {
      socket.off("boards:update");
    };
  }, []);

  const taskCount = useMemo(
    () => boards.reduce((sum, board) => sum + board.tasks.length, 0),
    [boards]
  );

  const handleDragStart = (task, sourceBoardId) => {
    setDraggedTask({ taskId: task.id, sourceBoardId });
  };

  const handleDrop = (destinationBoardId, destinationIndex) => {
    if (!draggedTask) return;

    const payload = {
      taskId: draggedTask.taskId,
      sourceBoardId: draggedTask.sourceBoardId,
      destinationBoardId,
      destinationIndex
    };

    fetch("http://localhost:3001/api/move-task", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });

    setDraggedTask(null);
  };

  const handleAddTask = async (e) => {
    e.preventDefault();

    await fetch("http://localhost:3001/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        boardId: newTask.boardId,
        task: {
          title: newTask.title,
          description: newTask.description,
          assignee: newTask.assignee
        }
      })
    });

    setNewTask({
      title: "",
      description: "",
      assignee: "",
      boardId: "todo"
    });
  };

  const handleDeleteTask = async (taskId) => {
    await fetch(`http://localhost:3001/api/tasks/${taskId}`, {
      method: "DELETE"
    });
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>{taskCount} tasks total</p>
      </header>

      <section className="new-task-panel">
        <h2>Create Task</h2>
        <form onSubmit={handleAddTask} className="task-form">
          <input
            type="text"
            placeholder="Title"
            value={newTask.title}
            onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
            required
          />
          <input
            type="text"
            placeholder="Description"
            value={newTask.description}
            onChange={(e) => setNewTask({ ...newTask, description: e.target.value })}
          />
          <input
            type="text"
            placeholder="Assignee"
            value={newTask.assignee}
            onChange={(e) => setNewTask({ ...newTask, assignee: e.target.value })}
          />
          <select
            value={newTask.boardId}
            onChange={(e) => setNewTask({ ...newTask, boardId: e.target.value })}
          >
            {boards.map((board) => (
              <option key={board.id} value={board.id}>
                {board.title}
              </option>
            ))}
          </select>
          <button type="submit">Add Task</button>
        </form>
      </section>

      <main className="board-container">
        {boards.map((board) => (
          <div
            key={board.id}
            className="board"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(board.id, board.tasks.length)}
          >
            <h2>{board.title}</h2>

            <div className="task-list">
              {board.tasks.map((task, index) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={() => handleDragStart(task, board.id)}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={() => handleDrop(board.id, index)}
                >
                  <div className="task-card-header">
                    <strong>{task.title}</strong>
                    <button onClick={() => handleDeleteTask(task.id)}>×</button>
                  </div>
                  <p>{task.description}</p>
                  <small>Assignee: {task.assignee || "Unassigned"}</small>
                </div>
              ))}
            </div>
          </div>
        ))}
      </main>
    </div>
  );
}
