## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Design homepage", description: "Create initial wireframes", assignee: "Alex" },
        { id: "t2", title: "Set up auth", description: "Implement login flow", assignee: "Sam" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Build API", description: "Create task endpoints", assignee: "Jordan" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "t4", title: "Project scaffold", description: "Initialize app structure", assignee: "Taylor" }
      ]
    }
  ]
};

function findTask(taskId) {
  for (const board of state.boards) {
    const task = board.tasks.find(t => t.id === taskId);
    if (task) return { board, task };
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("state:init", state);

  socket.on("task:create", (payload) => {
    const { boardId, task } = payload;
    const board = state.boards.find(b => b.id === boardId);
    if (!board) return;

    board.tasks.unshift(task);
    io.emit("state:update", state);
  });

  socket.on("task:update", (payload) => {
    const { taskId, updates } = payload;
    const found = findTask(taskId);
    if (!found) return;

    Object.assign(found.task, updates);
    io.emit("state:update", state);
  });

  socket.on("task:move", (payload) => {
    const { taskId, fromBoardId, toBoardId, toIndex } = payload;

    const fromBoard = state.boards.find(b => b.id === fromBoardId);
    const toBoard = state.boards.find(b => b.id === toBoardId);
    if (!fromBoard || !toBoard) return;

    const taskIndex = fromBoard.tasks.findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromBoard.tasks.splice(taskIndex, 1);
    toBoard.tasks.splice(toIndex, 0, task);

    io.emit("state:update", state);
  });

  socket.on("task:delete", (payload) => {
    const { taskId } = payload;
    for (const board of state.boards) {
      const idx = board.tasks.findIndex(t => t.id === taskId);
      if (idx !== -1) {
        board.tasks.splice(idx, 1);
        io.emit("state:update", state);
        return;
      }
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

