## 6) `public/app.js`

```js
const socket = io();

const boardsEl = document.getElementById("boards");
const taskTemplate = document.getElementById("taskTemplate");
const addTaskBtn = document.getElementById("addTaskBtn");
const newTaskTitle = document.getElementById("newTaskTitle");
const newTaskBoard = document.getElementById("newTaskBoard");

let appState = null;
let draggedTaskId = null;
let draggedFromBoardId = null;

function saveLocalState(state) {
  localStorage.setItem("project-manager-state", JSON.stringify(state));
}

function loadLocalState() {
  try {
    return JSON.parse(localStorage.getItem("project-manager-state"));
  } catch {
    return null;
  }
}

function render() {
  if (!appState) return;

  boardsEl.innerHTML = "";

  appState.boards.forEach(board => {
    const boardEl = document.createElement("section");
    boardEl.className = "board";
    boardEl.innerHTML = `
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}"></div>
    `;

    const taskList = boardEl.querySelector(".task-list");

    board.tasks.forEach(task => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.boardId = board.id;

      taskNode.querySelector(".task-title").textContent = task.title;
      taskNode.querySelector(".task-desc").textContent = task.description || "";
      taskNode.querySelector(".task-assignee").textContent = task.assignee ? `Assignee: ${task.assignee}` : "";

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromBoardId = board.id;
      });

      taskEl.addEventListener("dragend", () => {
        draggedTaskId = null;
        draggedFromBoardId = null;
        document.querySelectorAll(".task-list").forEach(el => el.classList.remove("drag-over"));
      });

      taskNode.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      taskList.appendChild(taskNode);
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromBoardId) return;

      const toBoardId = taskList.dataset.boardId;
      const toIndex = appState.boards.find(b => b.id === toBoardId).tasks.length;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        fromBoardId: draggedFromBoardId,
        toBoardId,
        toIndex
      });
    });

    boardsEl.appendChild(boardEl);
  });

  saveLocalState(appState);
}

addTaskBtn.addEventListener("click", () => {
  const title = newTaskTitle.value.trim();
  const boardId = newTaskBoard.value;

  if (!title) return;

  const task = {
    id: crypto.randomUUID(),
    title,
    description: "",
    assignee: ""
  };

  socket.emit("task:create", { boardId, task });
  newTaskTitle.value = "";
});

newTaskTitle.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

socket.on("state:init", (state) => {
  const local = loadLocalState();
  appState = local || state;
  render();
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});
```

