## 2) Backend — `server/index.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const cors = require("cors");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST"],
  },
});

// In-memory data store
let boards = {
  todo: [
    { id: "task-1", title: "Design homepage", description: "Create wireframes", assignee: "Ava" },
    { id: "task-2", title: "Set up auth", description: "Implement login flow", assignee: "Noah" },
  ],
  inProgress: [
    { id: "task-3", title: "Build API", description: "Create task endpoints", assignee: "Mia" },
  ],
  done: [
    { id: "task-4", title: "Project kickoff", description: "Initial planning meeting", assignee: "Liam" },
  ],
};

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, task } = req.body;
  if (!boards[columnId]) return res.status(400).json({ error: "Invalid column" });

  boards[columnId].push(task);
  io.emit("boards:update", boards);
  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { updatedTask } = req.body;

  for (const columnId of Object.keys(boards)) {
    const idx = boards[columnId].findIndex((t) => t.id === taskId);
    if (idx !== -1) {
      boards[columnId][idx] = { ...boards[columnId][idx], ...updatedTask };
      io.emit("boards:update", boards);
      return res.json(boards[columnId][idx]);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const columnId of Object.keys(boards)) {
    const idx = boards[columnId].findIndex((t) => t.id === taskId);
    if (idx !== -1) {
      const [removed] = boards[columnId].splice(idx, 1);
      io.emit("boards:update", boards);
      return res.json(removed);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

// Socket.IO real-time sync
io.on("connection", (socket) => {
  console.log("User connected:", socket.id);

  socket.emit("boards:update", boards);

  socket.on("boards:moveTask", ({ sourceColumn, destinationColumn, taskId, destinationIndex }) => {
    const sourceTasks = boards[sourceColumn];
    const destTasks = boards[destinationColumn];
    if (!sourceTasks || !destTasks) return;

    const sourceIndex = sourceTasks.findIndex((t) => t.id === taskId);
    if (sourceIndex === -1) return;

    const [movedTask] = sourceTasks.splice(sourceIndex, 1);
    destTasks.splice(destinationIndex, 0, movedTask);

    io.emit("boards:update", boards);
  });

  socket.on("boards:createTask", ({ columnId, task }) => {
    if (!boards[columnId]) return;
    boards[columnId].push(task);
    io.emit("boards:update", boards);
  });

  socket.on("boards:updateTask", ({ taskId, updatedTask }) => {
    for (const columnId of Object.keys(boards)) {
      const idx = boards[columnId].findIndex((t) => t.id === taskId);
      if (idx !== -1) {
        boards[columnId][idx] = { ...boards[columnId][idx], ...updatedTask };
        io.emit("boards:update", boards);
        return;
      }
    }
  });

  socket.on("boards:deleteTask", ({ taskId }) => {
    for (const columnId of Object.keys(boards)) {
      const idx = boards[columnId].findIndex((t) => t.id === taskId);
      if (idx !== -1) {
        boards[columnId].splice(idx, 1);
        io.emit("boards:update", boards);
        return;
      }
    }
  });

  socket.on("disconnect", () => {
    console.log("User disconnected:", socket.id);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
