import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay,
  useDroppable,
  useDraggable,
} from "@dnd-kit/core";
import { arrayMove, SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";

const socket = io("http://localhost:3001");

const initialColumns = {
  todo: { id: "todo", title: "To Do" },
  inProgress: { id: "inProgress", title: "In Progress" },
  done: { id: "done", title: "Done" },
};

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task.id,
    data: { task },
  });

  const style = {
    transform: transform
      ? `translate3d(${transform.x}px, ${transform.y}px, 0)`
      : undefined,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...listeners} {...attributes}>
      <div className="task-title">{task.title}</div>
      <div className="task-desc">{task.description}</div>
      <div className="task-meta">Assignee: {task.assignee}</div>
    </div>
  );
}

function Column({ column, tasks }) {
  const { setNodeRef, isOver } = useDroppable({
    id: column.id,
  });

  return (
    <div ref={setNodeRef} className={`column ${isOver ? "column-over" : ""}`}>
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [boards, setBoards] = useState({ todo: [], inProgress: [], done: [] });
  const [activeTask, setActiveTask] = useState(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 },
    })
  );

  useEffect(() => {
    fetch("http://localhost:3001/api/boards")
      .then((res) => res.json())
      .then(setBoards);

    socket.on("boards:update", (updatedBoards) => {
      setBoards(updatedBoards);
    });

    return () => {
      socket.off("boards:update");
    };
  }, []);

  const allTasksById = useMemo(() => {
    const map = {};
    Object.values(boards).forEach((tasks) => {
      tasks.forEach((task) => {
        map[task.id] = task;
      });
    });
    return map;
  }, [boards]);

  function findTaskColumn(taskId) {
    return Object.keys(boards).find((columnId) =>
      boards[columnId].some((task) => task.id === taskId)
    );
  }

  function handleDragStart(event) {
    const { active } = event;
    setActiveTask(allTasksById[active.id] || null);
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    setActiveTask(null);

    if (!over) return;

    const taskId = active.id;
    const sourceColumn = findTaskColumn(taskId);
    const destinationColumn = over.id in initialColumns ? over.id : findTaskColumn(over.id);

    if (!sourceColumn || !destinationColumn) return;

    const sourceTasks = [...boards[sourceColumn]];
    const destinationTasks = sourceColumn === destinationColumn ? sourceTasks : [...boards[destinationColumn]];

    const sourceIndex = sourceTasks.findIndex((t) => t.id === taskId);
    if (sourceIndex === -1) return;

    const [movedTask] = sourceTasks.splice(sourceIndex, 1);

    let destinationIndex = destinationTasks.length;
    if (over.id !== destinationColumn) {
      const overIndex = destinationTasks.findIndex((t) => t.id === over.id);
      if (overIndex !== -1) destinationIndex = overIndex;
    }

    destinationTasks.splice(destinationIndex, 0, movedTask);

    const updatedBoards = {
      ...boards,
      [sourceColumn]: sourceTasks,
      [destinationColumn]: destinationTasks,
    };

    setBoards(updatedBoards);

    socket.emit("boards:moveTask", {
      sourceColumn,
      destinationColumn,
      taskId,
      destinationIndex,
    });
  }

  function addTask(columnId) {
    const title = prompt("Task title?");
    if (!title) return;

    const description = prompt("Task description?") || "";
    const assignee = prompt("Assignee?") || "Unassigned";

    const task = {
      id: `task-${Date.now()}`,
      title,
      description,
      assignee,
    };

    socket.emit("boards:createTask", { columnId, task });
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {Object.values(initialColumns).map((column) => (
            <div key={column.id} className="column-wrapper">
              <button className="add-btn" onClick={() => addTask(column.id)}>
                + Add Task
              </button>
              <Column column={column} tasks={boards[column.id] || []} />
            </div>
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
