import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory store for demo purposes
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Design app layout", description: "Create initial wireframes", assignee: "Alice" },
    "task-2": { id: "task-2", title: "Set up auth", description: "Implement login flow", assignee: "Bob" },
    "task-3": { id: "task-3", title: "Build drag-and-drop", description: "Use HTML5 drag events", assignee: "Charlie" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", assignee = "" } = req.body;
  const id = `task-${Date.now()}`;

  const newTask = { id, title, description, assignee };
  board.tasks[id] = newTask;
  board.columns[0].taskIds.unshift(id);

  io.emit("boardUpdated", board);
  res.status(201).json(newTask);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  if (!board.tasks[id]) return res.status(404).json({ error: "Task not found" });

  board.tasks[id] = { ...board.tasks[id], ...req.body };
  io.emit("boardUpdated", board);
  res.json(board.tasks[id]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  if (!board.tasks[id]) return res.status(404).json({ error: "Task not found" });

  delete board.tasks[id];
  for (const column of board.columns) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  io.emit("boardUpdated", board);
  res.json({ success: true });
});

app.post("/api/move-task", (req, res) => {
  const { taskId, sourceColumnId, destinationColumnId, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid column" });
  }

  sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  io.emit("boardUpdated", board);
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("boardUpdated", board);

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(4000, () => {
  console.log("Server running on http://localhost:4000");
});
