import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

export default function App() {
  const [board, setBoard] = useState(null);
  const [draggedTask, setDraggedTask] = useState(null);
  const [newTask, setNewTask] = useState({
    title: "",
    description: "",
    assignee: ""
  });

  useEffect(() => {
    socket.on("boardUpdated", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("boardUpdated");
    };
  }, []);

  const columnsById = useMemo(() => {
    if (!board) return {};
    return Object.fromEntries(board.columns.map((c) => [c.id, c]));
  }, [board]);

  async function createTask(e) {
    e.preventDefault();
    if (!newTask.title.trim()) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(newTask)
    });

    setNewTask({ title: "", description: "", assignee: "" });
  }

  function onDragStart(taskId, sourceColumnId) {
    setDraggedTask({ taskId, sourceColumnId });
  }

  async function onDrop(destinationColumnId, destinationIndex) {
    if (!draggedTask) return;

    await fetch(`${API_URL}/api/move-task`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        taskId: draggedTask.taskId,
        sourceColumnId: draggedTask.sourceColumnId,
        destinationColumnId,
        destinationIndex
      })
    });

    setDraggedTask(null);
  }

  function allowDrop(e) {
    e.preventDefault();
  }

  if (!board) {
    return <div className="loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <form className="task-form" onSubmit={createTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTask.title}
            onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
          />
          <input
            type="text"
            placeholder="Description"
            value={newTask.description}
            onChange={(e) => setNewTask({ ...newTask, description: e.target.value })}
          />
          <input
            type="text"
            placeholder="Assignee"
            value={newTask.assignee}
            onChange={(e) => setNewTask({ ...newTask, assignee: e.target.value })}
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {board.columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={allowDrop}
            onDrop={() => onDrop(column.id, column.taskIds.length)}
          >
            <h2>{column.title}</h2>

            <div className="task-list">
              {column.taskIds.map((taskId, index) => {
                const task = board.tasks[taskId];
                if (!task) return null;

                return (
                  <div
                    key={task.id}
                    className="task-card"
                    draggable
                    onDragStart={() => onDragStart(task.id, column.id)}
                    onDragOver={allowDrop}
                    onDrop={(e) => {
                      e.preventDefault();
                      onDrop(column.id, index);
                    }}
                  >
                    <h3>{task.title}</h3>
                    <p>{task.description}</p>
                    <small>Assignee: {task.assignee || "Unassigned"}</small>
                  </div>
                );
              })}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
