### `server/index.js`
```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { randomUUID } from "crypto";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory data store
let board = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
    { id: "doing", title: "In Progress", taskIds: ["task-3"] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Set up project", description: "Initialize repo and tooling", status: "todo" },
    "task-2": { id: "task-2", title: "Design UI", description: "Create wireframes", status: "todo" },
    "task-3": { id: "task-3", title: "Implement auth", description: "Add login flow", status: "doing" }
  }
};

function broadcastBoard() {
  io.emit("board:update", board);
}

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;
  if (!title) return res.status(400).json({ error: "Title is required" });

  const id = randomUUID();
  const task = { id, title, description, status: columnId };
  board.tasks[id] = task;

  const column = board.columns.find(c => c.id === columnId);
  if (column) column.taskIds.push(id);

  broadcastBoard();
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, status } = req.body;
  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;

  if (status && status !== task.status) {
    const oldColumn = board.columns.find(c => c.id === task.status);
    const newColumn = board.columns.find(c => c.id === status);

    if (oldColumn) oldColumn.taskIds = oldColumn.taskIds.filter(tid => tid !== id);
    if (newColumn) newColumn.taskIds.push(id);

    task.status = status;
  }

  broadcastBoard();
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const column = board.columns.find(c => c.id === task.status);
  if (column) column.taskIds = column.taskIds.filter(tid => tid !== id);

  delete board.tasks[id];
  broadcastBoard();
  res.json({ success: true });
});

// Reorder tasks within/between columns
app.post("/api/reorder", (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid columns" });
  }

  const [movedTaskId] = sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, movedTaskId);

  if (board.tasks[movedTaskId]) {
    board.tasks[movedTaskId].status = destinationColumnId;
  }

  broadcastBoard();
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", (payload) => {
    const { title, description = "", columnId = "todo" } = payload;
    const id = randomUUID();
    const task = { id, title, description, status: columnId };
    board.tasks[id] = task;

    const column = board.columns.find(c => c.id === columnId);
    if (column) column.taskIds.push(id);

    broadcastBoard();
  });

  socket.on("task:update", (payload) => {
    const { id, updates } = payload;
    const task = board.tasks[id];
    if (!task) return;

    const prevStatus = task.status;
    Object.assign(task, updates);

    if (updates.status && updates.status !== prevStatus) {
      const oldColumn = board.columns.find(c => c.id === prevStatus);
      const newColumn = board.columns.find(c => c.id === updates.status);

      if (oldColumn) oldColumn.taskIds = oldColumn.taskIds.filter(tid => tid !== id);
      if (newColumn) newColumn.taskIds.push(id);
    }

    broadcastBoard();
  });

  socket.on("task:delete", (id) => {
    const task = board.tasks[id];
    if (!task) return;

    const column = board.columns.find(c => c.id === task.status);
    if (column) column.taskIds = column.taskIds.filter(tid => tid !== id);

    delete board.tasks[id];
    broadcastBoard();
  });

  socket.on("board:reorder", (payload) => {
    const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = payload;

    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    const [movedTaskId] = sourceColumn.taskIds.splice(sourceIndex, 1);
    destinationColumn.taskIds.splice(destinationIndex, 0, movedTaskId);

    if (board.tasks[movedTaskId]) {
      board.tasks[movedTaskId].status = destinationColumnId;
    }

    broadcastBoard();
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

