import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function TaskCard({ task, onEdit, onDelete }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <div className="task-header">
        <strong>{task.title}</strong>
      </div>
      <p>{task.description}</p>
      <div className="task-actions">
        <button onClick={(e) => { e.stopPropagation(); onEdit(task); }}>Edit</button>
        <button onClick={(e) => { e.stopPropagation(); onDelete(task.id); }}>Delete</button>
      </div>
    </div>
  );
}

function Column({ column, tasks, onEdit, onDelete }) {
  return (
    <div className="column">
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map(task => (
            <TaskCard key={task.id} task={task} onEdit={onEdit} onDelete={onDelete} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingTask, setEditingTask] = useState(null);
  const [form, setForm] = useState({ title: "", description: "", columnId: "todo" });

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    socket.on("board:update", (data) => setBoard(data));
    return () => socket.off("board:update");
  }, []);

  const columns = board?.columns || [];
  const tasks = board?.tasks || {};

  const tasksByColumn = useMemo(() => {
    const result = {};
    for (const col of columns) {
      result[col.id] = col.taskIds.map(id => tasks[id]).filter(Boolean);
    }
    return result;
  }, [columns, tasks]);

  function openCreateModal(columnId = "todo") {
    setEditingTask(null);
    setForm({ title: "", description: "", columnId });
    setModalOpen(true);
  }

  function openEditModal(task) {
    setEditingTask(task);
    setForm({
      title: task.title,
      description: task.description || "",
      columnId: task.status
    });
    setModalOpen(true);
  }

  function saveTask() {
    if (!form.title.trim()) return;

    if (editingTask) {
      socket.emit("task:update", {
        id: editingTask.id,
        updates: {
          title: form.title,
          description: form.description,
          status: form.columnId
        }
      });
    } else {
      socket.emit("task:create", form);
    }

    setModalOpen(false);
  }

  function deleteTask(id) {
    socket.emit("task:delete", id);
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over) return;

    const activeId = active.id;
    const overId = over.id;

    let sourceColumnId = null;
    let destinationColumnId = null;
    let sourceIndex = -1;
    let destinationIndex = -1;

    for (const col of columns) {
      const idx = col.taskIds.indexOf(activeId);
      if (idx !== -1) {
        sourceColumnId = col.id;
        sourceIndex = idx;
      }
      const overIdx = col.taskIds.indexOf(overId);
      if (overIdx !== -1) {
        destinationColumnId = col.id;
        destinationIndex = overIdx;
      }
    }

    if (sourceColumnId && destinationColumnId) {
      socket.emit("board:reorder", {
        sourceColumnId,
        destinationColumnId,
        sourceIndex,
        destinationIndex
      });
    }
  }

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <button onClick={() => openCreateModal("todo")}>+ New Task</button>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <div key={column.id} className="column-wrapper">
              <div className="column-toolbar">
                <h2>{column.title}</h2>
                <button onClick={() => openCreateModal(column.id)}>+ Add</button>
              </div>

              <Column
                column={column}
                tasks={tasksByColumn[column.id] || []}
                onEdit={openEditModal}
                onDelete={deleteTask}
              />
            </div>
          ))}
        </div>
      </DndContext>

      {modalOpen && (
        <div className="modal-backdrop" onClick={() => setModalOpen(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <h3>{editingTask ? "Edit Task" : "Create Task"}</h3>

            <label>
              Title
              <input
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
              />
            </label>

            <label>
              Description
              <textarea
                value={form.description}
                onChange={(e) => setForm({ ...form, description: e.target.value })}
              />
            </label>

            <label>
              Column
              <select
                value={form.columnId}
                onChange={(e) => setForm({ ...form, columnId: e.target.value })}
              >
                {columns.map((col) => (
                  <option key={col.id} value={col.id}>
                    {col.title}
                  </option>
                ))}
              </select>
            </label>

            <div className="modal-actions">
              <button onClick={() => setModalOpen(false)}>Cancel</button>
              <button onClick={saveTask}>Save</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
