## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Design app layout", description: "Create initial UI", assignee: "Alex" },
        { id: "t2", title: "Set up backend", description: "Express + Socket.IO", assignee: "Sam" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Implement drag and drop", description: "Kanban interactions", assignee: "Priya" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

function findTask(taskId) {
  for (const board of state.boards) {
    const task = board.tasks.find(t => t.id === taskId);
    if (task) return { board, task };
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("state:init", state);

  socket.on("task:create", (payload) => {
    const board = state.boards.find(b => b.id === payload.boardId);
    if (!board) return;

    const task = {
      id: `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      title: payload.title || "Untitled Task",
      description: payload.description || "",
      assignee: payload.assignee || ""
    };

    board.tasks.unshift(task);
    io.emit("state:update", state);
  });

  socket.on("task:update", (payload) => {
    const found = findTask(payload.taskId);
    if (!found) return;

    found.task.title = payload.title ?? found.task.title;
    found.task.description = payload.description ?? found.task.description;
    found.task.assignee = payload.assignee ?? found.task.assignee;

    io.emit("state:update", state);
  });

  socket.on("task:move", (payload) => {
    const found = findTask(payload.taskId);
    const targetBoard = state.boards.find(b => b.id === payload.toBoardId);
    if (!found || !targetBoard) return;

    found.board.tasks = found.board.tasks.filter(t => t.id !== payload.taskId);
    targetBoard.tasks.splice(payload.toIndex ?? targetBoard.tasks.length, 0, found.task);

    io.emit("state:update", state);
  });

  socket.on("task:delete", (payload) => {
    const found = findTask(payload.taskId);
    if (!found) return;

    found.board.tasks = found.board.tasks.filter(t => t.id !== payload.taskId);
    io.emit("state:update", state);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

