## 5) `public/app.js`

```js
const socket = io();

let appState = { boards: [] };
let dragTaskId = null;

const boardsEl = document.getElementById("boards");
const modal = document.getElementById("modal");
const taskForm = document.getElementById("taskForm");
const addTaskBtn = document.getElementById("addTaskBtn");
const cancelBtn = document.getElementById("cancelBtn");
const modalTitle = document.getElementById("modalTitle");

const taskIdInput = document.getElementById("taskId");
const titleInput = document.getElementById("title");
const descriptionInput = document.getElementById("description");
const assigneeInput = document.getElementById("assignee");
const boardIdSelect = document.getElementById("boardId");

function openModal(task = null, boardId = "") {
  modal.classList.remove("hidden");
  boardIdSelect.innerHTML = appState.boards
    .map(board => `<option value="${board.id}">${board.title}</option>`)
    .join("");

  if (task) {
    modalTitle.textContent = "Edit Task";
    taskIdInput.value = task.id;
    titleInput.value = task.title;
    descriptionInput.value = task.description || "";
    assigneeInput.value = task.assignee || "";
    boardIdSelect.value = boardId;
  } else {
    modalTitle.textContent = "New Task";
    taskIdInput.value = "";
    titleInput.value = "";
    descriptionInput.value = "";
    assigneeInput.value = "";
    boardIdSelect.value = boardId || appState.boards[0]?.id || "";
  }
}

function closeModal() {
  modal.classList.add("hidden");
  taskForm.reset();
}

function render() {
  boardsEl.innerHTML = appState.boards.map(board => `
    <section class="board" data-board-id="${board.id}">
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}">
        ${board.tasks.map(task => `
          <article class="task" draggable="true" data-task-id="${task.id}">
            <h3>${task.title}</h3>
            <p>${task.description || ""}</p>
            <p class="meta">Assignee: ${task.assignee || "Unassigned"}</p>
            <div class="task-actions">
              <button class="edit-btn" data-action="edit" data-task-id="${task.id}" data-board-id="${board.id}">Edit</button>
              <button class="delete-btn" data-action="delete" data-task-id="${task.id}">Delete</button>
            </div>
          </article>
        `).join("")}
      </div>
    </section>
  `).join("");

  document.querySelectorAll(".task").forEach(taskEl => {
    taskEl.addEventListener("dragstart", (e) => {
      dragTaskId = taskEl.dataset.taskId;
      e.dataTransfer.setData("text/plain", dragTaskId);
    });
  });

  document.querySelectorAll(".task-list").forEach(listEl => {
    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      listEl.classList.add("dropzone");
    });

    listEl.addEventListener("dragleave", () => {
      listEl.classList.remove("dropzone");
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      listEl.classList.remove("dropzone");

      const taskId = e.dataTransfer.getData("text/plain") || dragTaskId;
      const toBoardId = listEl.dataset.boardId;

      socket.emit("task:move", {
        taskId,
        toBoardId
      });
    });
  });

  document.querySelectorAll("[data-action='edit']").forEach(btn => {
    btn.addEventListener("click", () => {
      const taskId = btn.dataset.taskId;
      const boardId = btn.dataset.boardId;
      const board = appState.boards.find(b => b.id === boardId);
      const task = board?.tasks.find(t => t.id === taskId);
      if (task) openModal(task, boardId);
    });
  });

  document.querySelectorAll("[data-action='delete']").forEach(btn => {
    btn.addEventListener("click", () => {
      socket.emit("task:delete", { taskId: btn.dataset.taskId });
    });
  });
}

socket.on("state:init", (state) => {
  appState = state;
  render();
});

socket.on("state:update", (state) => {
  appState = state;
  render();
});

addTaskBtn.addEventListener("click", () => openModal());

cancelBtn.addEventListener("click", closeModal);

modal.addEventListener("click", (e) => {
  if (e.target === modal) closeModal();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const taskId = taskIdInput.value.trim();
  const payload = {
    title: titleInput.value.trim(),
    description: descriptionInput.value.trim(),
    assignee: assigneeInput.value.trim(),
    boardId: boardIdSelect.value
  };

  if (taskId) {
    socket.emit("task:update", { taskId, ...payload });
  } else {
    socket.emit("task:create", payload);
  }

  closeModal();
});
