## 2) Backend — `server/index.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");
const { v4: uuidv4 } = require("uuid");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"],
  },
});

// In-memory board state
let board = {
  columns: [
    { id: "todo", title: "To Do", taskIds: [] },
    { id: "inprogress", title: "In Progress", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] },
  ],
  tasks: {},
};

// Seed data
const task1 = { id: uuidv4(), title: "Design homepage", description: "Create wireframes", status: "todo" };
const task2 = { id: uuidv4(), title: "Set up auth", description: "Implement login flow", status: "inprogress" };
const task3 = { id: uuidv4(), title: "Deploy app", description: "Deploy to production", status: "done" };

board.tasks[task1.id] = task1;
board.tasks[task2.id] = task2;
board.tasks[task3.id] = task3;
board.columns[0].taskIds.push(task1.id);
board.columns[1].taskIds.push(task2.id);
board.columns[2].taskIds.push(task3.id);

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", columnId = "todo" } = req.body;
  if (!title) return res.status(400).json({ error: "Title is required" });

  const task = {
    id: uuidv4(),
    title,
    description,
    status: columnId,
  };

  board.tasks[task.id] = task;
  const column = board.columns.find((c) => c.id === columnId);
  if (column) column.taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description } = req.body;
  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;

  io.emit("board:update", board);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const column = board.columns.find((c) => c.id === task.status);
  if (column) column.taskIds = column.taskIds.filter((taskId) => taskId !== id);

  delete board.tasks[id];

  io.emit("board:update", board);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const task = board.tasks[taskId];
    if (!task) return;

    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);
    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);
    task.status = destinationColumnId;

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

