## 5) Frontend — `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
} from "@dnd-kit/sortable";

const socket = io("http://localhost:4000");

function TaskCard({ task }) {
  return (
    <div className="task-card">
      <div className="task-title">{task.title}</div>
      {task.description && <div className="task-desc">{task.description}</div>}
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <h2>{column.title}</h2>
      <SortableContext items={column.taskIds} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDesc, setNewTaskDesc] = useState("");

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 },
    })
  );

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:update", setBoard);
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    for (const column of board.columns) {
      result[column.id] = column.taskIds.map((id) => board.tasks[id]).filter(Boolean);
    }
    return result;
  }, [board]);

  const handleAddTask = async (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    await fetch("http://localhost:4000/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: newTaskTitle,
        description: newTaskDesc,
        columnId: "todo",
      }),
    });

    setNewTaskTitle("");
    setNewTaskDesc("");
  };

  const handleDragEnd = (event) => {
    const { active, over } = event;
    if (!active || !over || !board) return;

    const taskId = active.id;
    const sourceColumnId = findTaskColumn(board, taskId);
    const destinationColumnId = findTaskColumn(board, over.id) || over.id;

    if (!sourceColumnId || !destinationColumnId) return;

    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
    let destinationIndex = destinationColumn.taskIds.indexOf(over.id);

    if (destinationIndex === -1) destinationIndex = destinationColumn.taskIds.length;

    if (sourceColumnId === destinationColumnId) {
      const newTaskIds = arrayMove(sourceColumn.taskIds, sourceIndex, destinationIndex);
      const updatedBoard = {
        ...board,
        columns: board.columns.map((col) =>
          col.id === sourceColumnId ? { ...col, taskIds: newTaskIds } : col
        ),
      };
      setBoard(updatedBoard);
      socket.emit("task:move", {
        taskId,
        sourceColumnId,
        destinationColumnId,
        destinationIndex,
      });
    } else {
      const updatedSourceIds = sourceColumn.taskIds.filter((id) => id !== taskId);
      const updatedDestinationIds = [...destinationColumn.taskIds];
      updatedDestinationIds.splice(destinationIndex, 0, taskId);

      const updatedBoard = {
        ...board,
        columns: board.columns.map((col) => {
          if (col.id === sourceColumnId) return { ...col, taskIds: updatedSourceIds };
          if (col.id === destinationColumnId) return { ...col, taskIds: updatedDestinationIds };
          return col;
        }),
      };

      setBoard(updatedBoard);
      socket.emit("task:move", {
        taskId,
        sourceColumnId,
        destinationColumnId,
        destinationIndex,
      });
    }
  };

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <form className="new-task-form" onSubmit={handleAddTask}>
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <input
            value={newTaskDesc}
            onChange={(e) => setNewTaskDesc(e.target.value)}
            placeholder="Description"
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {board.columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={tasksByColumn[column.id] || []}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}

function findTaskColumn(board, id) {
  for (const column of board.columns) {
    if (column.id === id) return column.id;
    if (column.taskIds.includes(id)) return column.id;
  }
  return null;
}
