## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static(path.join(__dirname, "public")));

let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Design app layout", description: "Create initial wireframe" },
        { id: "task-2", title: "Set up backend", description: "Initialize Node/Express server" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Build drag-and-drop", description: "Implement task movement" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

function findTask(taskId) {
  for (const column of boardState.columns) {
    const index = column.tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      return { column, index, task: column.tasks[index] };
    }
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", (task) => {
    const todoColumn = boardState.columns.find((c) => c.id === "todo");
    if (!todoColumn) return;

    const newTask = {
      id: `task-${Date.now()}`,
      title: task.title || "Untitled Task",
      description: task.description || ""
    };

    todoColumn.tasks.unshift(newTask);
    io.emit("board:update", boardState);
  });

  socket.on("task:update", ({ taskId, updates }) => {
    const found = findTask(taskId);
    if (!found) return;

    Object.assign(found.task, updates);
    io.emit("board:update", boardState);
  });

  socket.on("task:move", ({ taskId, toColumnId, toIndex }) => {
    const found = findTask(taskId);
    if (!found) return;

    found.column.tasks.splice(found.index, 1);

    const targetColumn = boardState.columns.find((c) => c.id === toColumnId);
    if (!targetColumn) return;

    const insertIndex = Math.max(0, Math.min(toIndex ?? targetColumn.tasks.length, targetColumn.tasks.length));
    targetColumn.tasks.splice(insertIndex, 0, found.task);

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", ({ taskId }) => {
    const found = findTask(taskId);
    if (!found) return;

    found.column.tasks.splice(found.index, 1);
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

