## 6) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const taskTemplate = document.getElementById("taskTemplate");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescInput = document.getElementById("taskDesc");

let boardState = null;
let draggedTaskId = null;

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard();
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  const description = taskDescInput.value.trim();

  if (!title) return;

  socket.emit("task:create", { title, description });

  taskTitleInput.value = "";
  taskDescInput.value = "";
});

function renderBoard() {
  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";

    const titleEl = document.createElement("h2");
    titleEl.textContent = `${column.title} (${column.tasks.length})`;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list drop-zone";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTaskId) return;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        toColumnId: column.id,
        toIndex: column.tasks.length
      });

      draggedTaskId = null;
    });

    column.tasks.forEach((task) => {
      const taskEl = createTaskElement(task);
      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

function createTaskElement(task) {
  const taskEl = taskTemplate.content.firstElementChild.cloneNode(true);
  taskEl.dataset.taskId = task.id;

  taskEl.querySelector(".task-title").textContent = task.title;
  taskEl.querySelector(".task-desc").textContent = task.description;

  taskEl.addEventListener("dragstart", () => {
    draggedTaskId = task.id;
    taskEl.classList.add("dragging");
  });

  taskEl.addEventListener("dragend", () => {
    taskEl.classList.remove("dragging");
    draggedTaskId = null;
  });

  taskEl.querySelector(".delete-btn").addEventListener("click", () => {
    socket.emit("task:delete", { taskId: task.id });
  });

  taskEl.querySelector(".edit-btn").addEventListener("click", () => {
    const newTitle = prompt("Edit task title:", task.title);
    if (newTitle === null) return;

    const newDesc = prompt("Edit task description:", task.description);
    if (newDesc === null) return;

    socket.emit("task:update", {
      taskId: task.id,
      updates: {
        title: newTitle.trim() || task.title,
        description: newDesc.trim()
      }
    });
  });

  return taskEl;
}
```

