```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const SERVER_URL = "http://localhost:4000";

function createTaskId() {
  return `task-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

export default function App() {
  const socket = useMemo(() => io(SERVER_URL), []);
  const [board, setBoard] = useState(null);
  const [draggedTask, setDraggedTask] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskColumn, setNewTaskColumn] = useState("todo");

  useEffect(() => {
    fetch(`${SERVER_URL}/api/board`)
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.disconnect();
    };
  }, [socket]);

  function syncBoard(updatedBoard) {
    setBoard(updatedBoard);
    socket.emit("board:update", updatedBoard);
    fetch(`${SERVER_URL}/api/board`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(updatedBoard)
    }).catch(() => {});
  }

  function handleAddTask(e) {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    const updatedBoard = structuredClone(board);
    const column = updatedBoard.columns.find((c) => c.id === newTaskColumn);
    column.tasks.push({
      id: createTaskId(),
      title: newTaskTitle.trim(),
      description: ""
    });

    setNewTaskTitle("");
    syncBoard(updatedBoard);
  }

  function handleDragStart(task, fromColumnId) {
    setDraggedTask({ task, fromColumnId });
  }

  function handleDrop(toColumnId) {
    if (!draggedTask || !board) return;

    const updatedBoard = structuredClone(board);
    const fromColumn = updatedBoard.columns.find((c) => c.id === draggedTask.fromColumnId);
    const toColumn = updatedBoard.columns.find((c) => c.id === toColumnId);

    const taskIndex = fromColumn.tasks.findIndex((t) => t.id === draggedTask.task.id);
    if (taskIndex === -1) return;

    const [movedTask] = fromColumn.tasks.splice(taskIndex, 1);
    toColumn.tasks.push(movedTask);

    setDraggedTask(null);
    syncBoard(updatedBoard);
  }

  function handleTaskEdit(columnId, taskId, field, value) {
    const updatedBoard = structuredClone(board);
    const column = updatedBoard.columns.find((c) => c.id === columnId);
    const task = column.tasks.find((t) => t.id === taskId);
    task[field] = value;
    syncBoard(updatedBoard);
  }

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>

        <form className="add-task-form" onSubmit={handleAddTask}>
          <input
            type="text"
            placeholder="New task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <select value={newTaskColumn} onChange={(e) => setNewTaskColumn(e.target.value)}>
            {board.columns.map((col) => (
              <option key={col.id} value={col.id}>
                {col.title}
              </option>
            ))}
          </select>
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {board.columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(column.id)}
          >
            <h2>{column.title}</h2>

            <div className="task-list">
              {column.tasks.map((task) => (
                <article
                  key={task.id}
                  className="task"
                  draggable
                  onDragStart={() => handleDragStart(task, column.id)}
                >
                  <input
                    className="task-title"
                    value={task.title}
                    onChange={(e) =>
                      handleTaskEdit(column.id, task.id, "title", e.target.value)
                    }
                  />
                  <textarea
                    className="task-desc"
                    value={task.description}
                    placeholder="Description..."
                    onChange={(e) =>
                      handleTaskEdit(column.id, task.id, "description", e.target.value)
                    }
                  />
                </article>
              ))}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

