```js
import express from "express";
import cors from "cors";
import { createServer } from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const httpServer = createServer(app);
const io = new Server(httpServer, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory board state
let board = {
  columns: [
    { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
    { id: "doing", title: "In Progress", taskIds: ["task-3"] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Design app layout", description: "Create initial wireframes" },
    "task-2": { id: "task-2", title: "Set up auth", description: "Implement login flow" },
    "task-3": { id: "task-3", title: "Build drag-and-drop", description: "Kanban interactions" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId } = req.body;
  const id = `task-${Date.now()}`;

  board.tasks[id] = { id, title, description };
  const column = board.columns.find(c => c.id === columnId || c.id === "todo");
  column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(board.tasks[id]);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const { title, description } = req.body;

  if (!board.tasks[id]) return res.status(404).json({ error: "Task not found" });

  board.tasks[id] = { ...board.tasks[id], title, description };
  io.emit("board:update", board);
  res.json(board.tasks[id]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;

  if (!board.tasks[id]) return res.status(404).json({ error: "Task not found" });

  // Remove from column
  for (const column of board.columns) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  delete board.tasks[id];
  io.emit("board:update", board);
  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter(id => id !== taskId);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
httpServer.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

