import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove
} from "@dnd-kit/sortable";

const socket = io("http://localhost:4000");

function TaskCard({ task }) {
  return (
    <div className="task-card">
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
      </div>

      <SortableContext items={column.taskIds} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map(task => (
            <div key={task.id} className="task-wrapper">
              <TaskCard task={task} />
            </div>
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [activeTask, setActiveTask] = useState(null);
  const [newTitle, setNewTitle] = useState("");
  const [newDescription, setNewDescription] = useState("");

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then(res => res.json())
      .then(setBoard);

    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:update");
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    for (const column of board.columns) {
      result[column.id] = column.taskIds.map(id => board.tasks[id]).filter(Boolean);
    }
    return result;
  }, [board]);

  function handleDragStart(event) {
    const { active } = event;
    if (!board) return;
    setActiveTask(board.tasks[active.id]);
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    setActiveTask(null);
    if (!board || !over) return;

    const taskId = active.id;
    const sourceColumn = board.columns.find(col => col.taskIds.includes(taskId));
    const destinationColumn = board.columns.find(col =>
      col.taskIds.includes(over.id) || col.id === over.id
    );

    if (!sourceColumn || !destinationColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(taskId);
    const destinationIndex = destinationColumn.taskIds.indexOf(over.id);

    const updated = structuredClone(board);

    // Remove from source
    updated.columns.find(c => c.id === sourceColumn.id).taskIds.splice(sourceIndex, 1);

    // Insert into destination
    const destCol = updated.columns.find(c => c.id === destinationColumn.id);
    const insertIndex = destinationIndex >= 0 ? destinationIndex : destCol.taskIds.length;
    destCol.taskIds.splice(insertIndex, 0, taskId);

    setBoard(updated);

    socket.emit("task:move", {
      taskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId: destinationColumn.id,
      destinationIndex: insertIndex
    });
  }

  async function addTask(e) {
    e.preventDefault();
    if (!newTitle.trim()) return;

    await fetch("http://localhost:4000/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: newTitle,
        description: newDescription,
        columnId: "todo"
      })
    });

    setNewTitle("");
    setNewDescription("");
  }

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <form className="new-task-form" onSubmit={addTask}>
          <input
            value={newTitle}
            onChange={e => setNewTitle(e.target.value)}
            placeholder="Task title"
          />
          <input
            value={newDescription}
            onChange={e => setNewDescription(e.target.value)}
            placeholder="Task description"
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columns.map(column => (
            <div key={column.id} className="column-dropzone" id={column.id}>
              <Column column={column} tasks={tasksByColumn[column.id]} />
            </div>
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
