## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

/**
 * In-memory board state.
 * In production, store this in a database.
 */
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Design app layout" },
        { id: "task-2", title: "Set up authentication" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Build drag-and-drop board" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", title: "Create project scaffold" }
      ]
    }
  ]
};

function findTaskAndRemove(taskId) {
  for (const column of board.columns) {
    const index = column.tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      const [task] = column.tasks.splice(index, 1);
      return task;
    }
  }
  return null;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current board state to new client
  socket.emit("board:init", board);

  // Handle task move
  socket.on("task:move", ({ taskId, toColumnId, toIndex }) => {
    const task = findTaskAndRemove(taskId);
    if (!task) return;

    const targetColumn = board.columns.find((c) => c.id === toColumnId);
    if (!targetColumn) return;

    const safeIndex = Math.max(0, Math.min(toIndex, targetColumn.tasks.length));
    targetColumn.tasks.splice(safeIndex, 0, task);

    // Broadcast updated board to all clients
    io.emit("board:update", board);
  });

  // Handle task creation
  socket.on("task:create", ({ columnId, title }) => {
    const column = board.columns.find((c) => c.id === columnId);
    if (!column || !title?.trim()) return;

    const newTask = {
      id: `task-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      title: title.trim()
    };

    column.tasks.unshift(newTask);
    io.emit("board:update", board);
  });

  // Handle task deletion
  socket.on("task:delete", ({ taskId }) => {
    const task = findTaskAndRemove(taskId);
    if (!task) return;
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

