## 5) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const connectionStatusEl = document.getElementById("connectionStatus");
const taskTitleInput = document.getElementById("taskTitleInput");
const columnSelect = document.getElementById("columnSelect");
const addTaskBtn = document.getElementById("addTaskBtn");

let currentBoard = null;
let draggedTaskId = null;

socket.on("connect", () => {
  connectionStatusEl.textContent = "Connected";
  connectionStatusEl.style.color = "#10b981";
});

socket.on("disconnect", () => {
  connectionStatusEl.textContent = "Disconnected";
  connectionStatusEl.style.color = "#ef4444";
});

socket.on("board:init", (board) => {
  currentBoard = board;
  renderBoard();
});

socket.on("board:update", (board) => {
  currentBoard = board;
  renderBoard();
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  const columnId = columnSelect.value;

  if (!title) return;

  socket.emit("task:create", { columnId, title });
  taskTitleInput.value = "";
  taskTitleInput.focus();
});

taskTitleInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

function renderBoard() {
  if (!currentBoard) return;

  boardEl.innerHTML = "";

  currentBoard.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTaskId) return;

      const toColumnId = taskListEl.dataset.columnId;
      const toIndex = column.tasks.length;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        toColumnId,
        toIndex
      });

      draggedTaskId = null;
    });

    column.tasks.forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
      });

      taskEl.addEventListener("dragend", () => {
        draggedTaskId = null;
      });

      // Drop before this task
      taskEl.addEventListener("dragover", (e) => {
        e.preventDefault();
      });

      taskEl.addEventListener("drop", (e) => {
        e.preventDefault();
        if (!draggedTaskId) return;

        const toColumnId = column.id;
        const toIndex = index;

        socket.emit("task:move", {
          taskId: draggedTaskId,
          toColumnId,
          toIndex
        });

        draggedTaskId = null;
      });

      const titleSpan = document.createElement("div");
      titleSpan.className = "task-title";
      titleSpan.textContent = task.title;

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const deleteBtn = document.createElement("button");
      deleteBtn.className = "icon-btn";
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      actions.appendChild(deleteBtn);
      taskEl.appendChild(titleSpan);
      taskEl.appendChild(actions);
      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}
```

