```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory demo data
let boards = [
  {
    id: "todo",
    title: "To Do",
    taskIds: ["task-1", "task-2"]
  },
  {
    id: "doing",
    title: "In Progress",
    taskIds: ["task-3"]
  },
  {
    id: "done",
    title: "Done",
    taskIds: []
  }
];

let tasks = {
  "task-1": {
    id: "task-1",
    title: "Design app layout",
    description: "Create the initial UI wireframe and layout.",
    boardId: "todo",
    updatedAt: Date.now()
  },
  "task-2": {
    id: "task-2",
    title: "Set up authentication",
    description: "Add login and session handling.",
    boardId: "todo",
    updatedAt: Date.now()
  },
  "task-3": {
    id: "task-3",
    title: "Implement drag and drop",
    description: "Use dnd-kit for task movement.",
    boardId: "doing",
    updatedAt: Date.now()
  }
};

app.get("/api/state", (req, res) => {
  res.json({ boards, tasks });
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", boardId = "todo" } = req.body;

  const id = `task-${Date.now()}`;
  const task = {
    id,
    title,
    description,
    boardId,
    updatedAt: Date.now()
  };

  tasks[id] = task;
  const board = boards.find((b) => b.id === boardId);
  if (board) board.taskIds.push(id);

  io.emit("state:update", { boards, tasks });
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const existing = tasks[id];

  if (!existing) {
    return res.status(404).json({ error: "Task not found" });
  }

  const prevBoardId = existing.boardId;
  const nextBoardId = req.body.boardId ?? prevBoardId;

  tasks[id] = {
    ...existing,
    ...req.body,
    boardId: nextBoardId,
    updatedAt: Date.now()
  };

  if (prevBoardId !== nextBoardId) {
    const prevBoard = boards.find((b) => b.id === prevBoardId);
    const nextBoard = boards.find((b) => b.id === nextBoardId);

    if (prevBoard) {
      prevBoard.taskIds = prevBoard.taskIds.filter((taskId) => taskId !== id);
    }
    if (nextBoard && !nextBoard.taskIds.includes(id)) {
      nextBoard.taskIds.push(id);
    }
  }

  io.emit("state:update", { boards, tasks });
  res.json(tasks[id]);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = tasks[id];

  if (!task) {
    return res.status(404).json({ error: "Task not found" });
  }

  const board = boards.find((b) => b.id === task.boardId);
  if (board) {
    board.taskIds = board.taskIds.filter((taskId) => taskId !== id);
  }

  delete tasks[id];

  io.emit("state:update", { boards, tasks });
  res.json({ success: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("state:update", { boards, tasks });

  socket.on("task:move", ({ taskId, fromBoardId, toBoardId, toIndex }) => {
    const task = tasks[taskId];
    if (!task) return;

    const fromBoard = boards.find((b) => b.id === fromBoardId);
    const toBoard = boards.find((b) => b.id === toBoardId);
    if (!fromBoard || !toBoard) return;

    fromBoard.taskIds = fromBoard.taskIds.filter((id) => id !== taskId);

    const insertIndex =
      typeof toIndex === "number" ? toIndex : toBoard.taskIds.length;

    toBoard.taskIds.splice(insertIndex, 0, taskId);

    tasks[taskId] = {
      ...task,
      boardId: toBoardId,
      updatedAt: Date.now()
    };

    io.emit("state:update", { boards, tasks });
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

