import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay,
  useDroppable
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function TaskCard({ task, onEdit, onDelete, isDragging = false }) {
  const { attributes, listeners, setNodeRef, transform, transition } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes}>
      <div className="task-card-header" {...listeners}>
        <strong>{task.title}</strong>
      </div>
      <p>{task.description}</p>
      <div className="task-actions">
        <button onClick={() => onEdit(task)}>Edit</button>
        <button onClick={() => onDelete(task.id)}>Delete</button>
      </div>
    </div>
  );
}

function BoardColumn({ board, tasks, onEdit, onDelete }) {
  const { setNodeRef, isOver } = useDroppable({ id: board.id });

  return (
    <div ref={setNodeRef} className={`board-column ${isOver ? "over" : ""}`}>
      <h2>{board.title}</h2>
      <SortableContext
        items={tasks.map((t) => t.id)}
        strategy={verticalListSortingStrategy}
      >
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard
              key={task.id}
              task={task}
              onEdit={onEdit}
              onDelete={onDelete}
            />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [boards, setBoards] = useState([]);
  const [tasks, setTasks] = useState({});
  const [activeTask, setActiveTask] = useState(null);
  const [editingTask, setEditingTask] = useState(null);
  const [form, setForm] = useState({ title: "", description: "", boardId: "todo" });

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    fetch("http://localhost:4000/api/state")
      .then((res) => res.json())
      .then((data) => {
        setBoards(data.boards);
        setTasks(data.tasks);
      });

    socket.on("state:update", (data) => {
      setBoards(data.boards);
      setTasks(data.tasks);
    });

    return () => {
      socket.off("state:update");
    };
  }, []);

  const tasksByBoard = useMemo(() => {
    const grouped = {};
    for (const board of boards) {
      grouped[board.id] = board.taskIds.map((id) => tasks[id]).filter(Boolean);
    }
    return grouped;
  }, [boards, tasks]);

  function handleDragStart(event) {
    const task = tasks[event.active.id];
    setActiveTask(task);
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    setActiveTask(null);

    if (!over) return;

    const taskId = active.id;
    const task = tasks[taskId];
    if (!task) return;

    const fromBoardId = task.boardId;
    const toBoardId = boards.some((b) => b.id === over.id) ? over.id : task.boardId;

    if (fromBoardId === toBoardId) return;

    socket.emit("task:move", {
      taskId,
      fromBoardId,
      toBoardId
    });
  }

  async function handleSubmit(e) {
    e.preventDefault();

    if (!form.title.trim()) return;

    if (editingTask) {
      await fetch(`http://localhost:4000/api/tasks/${editingTask.id}`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form)
      });
      setEditingTask(null);
    } else {
      await fetch("http://localhost:4000/api/tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form)
      });
    }

    setForm({ title: "", description: "", boardId: "todo" });
  }

  function handleEdit(task) {
    setEditingTask(task);
    setForm({
      title: task.title,
      description: task.description,
      boardId: task.boardId
    });
  }

  async function handleDelete(id) {
    await fetch(`http://localhost:4000/api/tasks/${id}`, {
      method: "DELETE"
    });
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between boards. Updates sync in real time.</p>
      </header>

      <section className="task-form">
        <h2>{editingTask ? "Edit Task" : "New Task"}</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="Task title"
            value={form.title}
            onChange={(e) => setForm({ ...form, title: e.target.value })}
          />
          <textarea
            placeholder="Task description"
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
          />
          <select
            value={form.boardId}
            onChange={(e) => setForm({ ...form, boardId: e.target.value })}
          >
            {boards.map((board) => (
              <option key={board.id} value={board.id}>
                {board.title}
              </option>
            ))}
          </select>
          <button type="submit">{editingTask ? "Save" : "Add Task"}</button>
        </form>
      </section>

      <main className="boards">
        <DndContext
          sensors={sensors}
          collisionDetection={closestCenter}
          onDragStart={handleDragStart}
          onDragEnd={handleDragEnd}
        >
          {boards.map((board) => (
            <BoardColumn
              key={board.id}
              board={board}
              tasks={tasksByBoard[board.id] || []}
              onEdit={handleEdit}
              onDelete={handleDelete}
            />
          ))}

          <DragOverlay>
            {activeTask ? (
              <div className="task-card dragging">
                <strong>{activeTask.title}</strong>
                <p>{activeTask.description}</p>
              </div>
            ) : null}
          </DragOverlay>
        </DndContext>
      </main>
    </div>
  );
}
```

