## 2) Backend — `server/index.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "http://localhost:5173",
    methods: ["GET", "POST", "PUT", "DELETE"],
  },
});

// In-memory data store
let board = {
  todo: [
    { id: "task-1", title: "Design app layout", description: "Create wireframes" },
    { id: "task-2", title: "Set up auth", description: "Login and registration" },
  ],
  inProgress: [
    { id: "task-3", title: "Build drag-and-drop", description: "Kanban interactions" },
  ],
  done: [],
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, task } = req.body;
  if (!board[columnId]) return res.status(400).json({ error: "Invalid column" });

  board[columnId].push(task);
  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;
  const { title, description } = req.body;

  for (const columnId of Object.keys(board)) {
    const task = board[columnId].find((t) => t.id === taskId);
    if (task) {
      task.title = title ?? task.title;
      task.description = description ?? task.description;
      io.emit("board:update", board);
      return res.json(task);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

app.delete("/api/tasks/:taskId", (req, res) => {
  const { taskId } = req.params;

  for (const columnId of Object.keys(board)) {
    const index = board[columnId].findIndex((t) => t.id === taskId);
    if (index !== -1) {
      const [removed] = board[columnId].splice(index, 1);
      io.emit("board:update", board);
      return res.json(removed);
    }
  }

  res.status(404).json({ error: "Task not found" });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:moved", ({ taskId, fromColumn, toColumn, toIndex }) => {
    if (!board[fromColumn] || !board[toColumn]) return;

    const fromTasks = board[fromColumn];
    const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromTasks.splice(taskIndex, 1);
    board[toColumn].splice(toIndex, 0, task);

    io.emit("board:update", board);
  });

  socket.on("task:created", ({ columnId, task }) => {
    if (!board[columnId]) return;
    board[columnId].push(task);
    io.emit("board:update", board);
  });

  socket.on("task:updated", ({ taskId, updates }) => {
    for (const columnId of Object.keys(board)) {
      const task = board[columnId].find((t) => t.id === taskId);
      if (task) {
        Object.assign(task, updates);
        io.emit("board:update", board);
        return;
      }
    }
  });

  socket.on("task:deleted", ({ taskId }) => {
    for (const columnId of Object.keys(board)) {
      const index = board[columnId].findIndex((t) => t.id === taskId);
      if (index !== -1) {
        board[columnId].splice(index, 1);
        io.emit("board:update", board);
        return;
      }
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

