## 5) Frontend — `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors,
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
} from "@dnd-kit/sortable";
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

const columnTitles = {
  todo: "To Do",
  inProgress: "In Progress",
  done: "Done",
};

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1,
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function Column({ id, tasks }) {
  return (
    <div className="column">
      <h3>{columnTitles[id]}</h3>
      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState({ todo: [], inProgress: [], done: [] });
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");
  const [selectedColumn, setSelectedColumn] = useState("todo");

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 },
    })
  );

  useEffect(() => {
    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const allTaskIds = useMemo(
    () => Object.values(board).flat().map((task) => task.id),
    [board]
  );

  function findTask(taskId) {
    for (const columnId of Object.keys(board)) {
      const task = board[columnId].find((t) => t.id === taskId);
      if (task) return { task, columnId };
    }
    return null;
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    if (!over) return;

    const activeInfo = findTask(active.id);
    const overInfo = findTask(over.id);

    if (!activeInfo || !overInfo) return;

    const fromColumn = activeInfo.columnId;
    const toColumn = overInfo.columnId;

    const fromTasks = [...board[fromColumn]];
    const toTasks = fromColumn === toColumn ? fromTasks : [...board[toColumn]];

    const oldIndex = fromTasks.findIndex((t) => t.id === active.id);
    const newIndex = toTasks.findIndex((t) => t.id === over.id);

    const movedTask = fromTasks[oldIndex];
    fromTasks.splice(oldIndex, 1);

    if (fromColumn === toColumn) {
      const reordered = arrayMove(board[fromColumn], oldIndex, newIndex);
      const updatedBoard = { ...board, [fromColumn]: reordered };
      setBoard(updatedBoard);
      socket.emit("task:moved", {
        taskId: active.id,
        fromColumn,
        toColumn,
        toIndex: newIndex,
      });
    } else {
      toTasks.splice(newIndex, 0, movedTask);
      const updatedBoard = {
        ...board,
        [fromColumn]: fromTasks,
        [toColumn]: toTasks,
      };
      setBoard(updatedBoard);
      socket.emit("task:moved", {
        taskId: active.id,
        fromColumn,
        toColumn,
        toIndex: newIndex,
      });
    }
  }

  function createTask() {
    if (!newTaskTitle.trim()) return;

    const task = {
      id: `task-${Date.now()}`,
      title: newTaskTitle,
      description: newTaskDescription,
    };

    socket.emit("task:created", {
      columnId: selectedColumn,
      task,
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>

        <div className="task-form">
          <select value={selectedColumn} onChange={(e) => setSelectedColumn(e.target.value)}>
            <option value="todo">To Do</option>
            <option value="inProgress">In Progress</option>
            <option value="done">Done</option>
          </select>

          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />

          <input
            type="text"
            placeholder="Task description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />

          <button onClick={createTask}>Add Task</button>
        </div>
      </header>

      <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
        <div className="board">
          {Object.keys(board).map((columnId) => (
            <Column key={columnId} id={columnId} tasks={board[columnId]} />
          ))}
        </div>
      </DndContext>
    </div>
  );
}
```

