let boards = [
  {
    id: "todo",
    title: "To Do",
    tasks: [
      { id: "task-1", title: "Design app layout", description: "Create wireframes" },
      { id: "task-2", title: "Set up backend", description: "Express + Socket.IO" },
    ],
  },
  {
    id: "doing",
    title: "In Progress",
    tasks: [{ id: "task-3", title: "Build drag-and-drop", description: "Use HTML5 DnD" }],
  },
  {
    id: "done",
    title: "Done",
    tasks: [{ id: "task-4", title: "Initialize repo", description: "Create project structure" }],
  },
];

app.get("/api/boards", (req, res) => {
  res.json(boards);
});

app.post("/api/tasks", (req, res) => {
  const { boardId, title, description } = req.body;
  const newTask = {
    id: `task-${Date.now()}`,
    title,
    description: description || "",
  };

  const board = boards.find((b) => b.id === boardId);
  if (!board) return res.status(404).json({ error: "Board not found" });

  board.tasks.push(newTask);
  io.emit("boards:update", boards);
  res.status(201).json(newTask);
});

app.put("/api/tasks/move", (req, res) => {
  const { taskId, sourceBoardId, destinationBoardId, destinationIndex } = req.body;

  const sourceBoard = boards.find((b) => b.id === sourceBoardId);
  const destinationBoard = boards.find((b) => b.id === destinationBoardId);

  if (!sourceBoard || !destinationBoard) {
    return res.status(404).json({ error: "Board not found" });
  }

  const taskIndex = sourceBoard.tasks.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return res.status(404).json({ error: "Task not found" });

  const [task] = sourceBoard.tasks.splice(taskIndex, 1);
  destinationBoard.tasks.splice(destinationIndex, 0, task);

  io.emit("boards:update", boards);
  res.json({ success: true, boards });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("boards:update", boards);

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
