```jsx
import { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

export default function App() {
  const [boards, setBoards] = useState([]);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [selectedBoardId, setSelectedBoardId] = useState("todo");

  useEffect(() => {
    fetch(`${API_URL}/api/boards`)
      .then((res) => res.json())
      .then(setBoards)
      .catch(console.error);

    socket.on("boards:update", (updatedBoards) => {
      setBoards(updatedBoards);
    });

    return () => {
      socket.off("boards:update");
    };
  }, []);

  const handleDragStart = (e, taskId, sourceBoardId) => {
    e.dataTransfer.setData(
      "application/json",
      JSON.stringify({ taskId, sourceBoardId })
    );
  };

  const handleDrop = async (e, destinationBoardId, destinationIndex) => {
    e.preventDefault();
    const data = JSON.parse(e.dataTransfer.getData("application/json"));
    if (!data) return;

    await fetch(`${API_URL}/api/tasks/move`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        taskId: data.taskId,
        sourceBoardId: data.sourceBoardId,
        destinationBoardId,
        destinationIndex,
      }),
    });
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const addTask = async (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        boardId: selectedBoardId,
        title: newTaskTitle,
        description: "",
      }),
    });

    setNewTaskTitle("");
  };

  const boardMap = useMemo(() => {
    const map = {};
    boards.forEach((b) => (map[b.id] = b));
    return map;
  }, [boards]);

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag and drop tasks. Updates sync in real time.</p>

        <form className="task-form" onSubmit={addTask}>
          <input
            type="text"
            placeholder="New task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <select
            value={selectedBoardId}
            onChange={(e) => setSelectedBoardId(e.target.value)}
          >
            {boards.map((board) => (
              <option key={board.id} value={board.id}>
                {board.title}
              </option>
            ))}
          </select>
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board-container">
        {boards.map((board) => (
          <section
            key={board.id}
            className="board"
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, board.id, board.tasks.length)}
          >
            <h2>{board.title}</h2>

            <div className="task-list">
              {board.tasks.map((task, index) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={(e) => handleDragStart(e, task.id, board.id)}
                  onDragOver={handleDragOver}
                  onDrop={(e) => handleDrop(e, board.id, index)}
                >
                  <strong>{task.title}</strong>
                  {task.description && <p>{task.description}</p>}
                </div>
              ))}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
