## 2) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

/**
 * In-memory board state.
 * Replace with a database for production use.
 */
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", title: "Set up project", description: "Initialize repo and tooling" },
        { id: "t2", title: "Design UI", description: "Create board layout" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "t3", title: "Build drag-and-drop", description: "Implement task movement" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "t4", title: "Requirements gathering", description: "Collect project needs" }
      ]
    }
  ]
};

function findTask(boardState, taskId) {
  for (const column of boardState.columns) {
    const index = column.tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      return { column, index, task: column.tasks[index] };
    }
  }
  return null;
}

function moveTask(boardState, taskId, targetColumnId, targetIndex) {
  const found = findTask(boardState, taskId);
  if (!found) return false;

  const { column: sourceColumn, index: sourceIndex, task } = found;
  sourceColumn.tasks.splice(sourceIndex, 1);

  const targetColumn = boardState.columns.find((c) => c.id === targetColumnId);
  if (!targetColumn) return false;

  const insertIndex = Math.max(0, Math.min(targetIndex, targetColumn.tasks.length));
  targetColumn.tasks.splice(insertIndex, 0, task);

  return true;
}

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  // Send current board state to newly connected client
  socket.emit("board:init", board);

  // Handle task movement
  socket.on("task:move", ({ taskId, targetColumnId, targetIndex }) => {
    const ok = moveTask(board, taskId, targetColumnId, targetIndex);
    if (ok) {
      io.emit("board:update", board);
    }
  });

  // Handle task creation
  socket.on("task:create", ({ columnId, title, description }) => {
    const column = board.columns.find((c) => c.id === columnId);
    if (!column) return;

    const newTask = {
      id: `task_${Date.now()}_${Math.random().toString(16).slice(2)}`,
      title: title || "Untitled Task",
      description: description || ""
    };

    column.tasks.unshift(newTask);
    io.emit("board:update", board);
  });

  // Handle task deletion
  socket.on("task:delete", ({ taskId }) => {
    const found = findTask(board, taskId);
    if (!found) return;

    found.column.tasks.splice(found.index, 1);
    io.emit("board:update", board);
  });

  // Handle task editing
  socket.on("task:update", ({ taskId, title, description }) => {
    const found = findTask(board, taskId);
    if (!found) return;

    if (typeof title === "string") found.task.title = title;
    if (typeof description === "string") found.task.description = description;

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

