## 5) `public/app.js`

```js
const socket = io();

const boardEl = document.getElementById("board");
const statusEl = document.getElementById("status");

const addTaskBtn = document.getElementById("addTaskBtn");
const modalBackdrop = document.getElementById("modalBackdrop");
const cancelTaskBtn = document.getElementById("cancelTaskBtn");
const saveTaskBtn = document.getElementById("saveTaskBtn");
const taskColumn = document.getElementById("taskColumn");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");

const editBackdrop = document.getElementById("editBackdrop");
const editTaskId = document.getElementById("editTaskId");
const editTaskTitle = document.getElementById("editTaskTitle");
const editTaskDescription = document.getElementById("editTaskDescription");
const cancelEditBtn = document.getElementById("cancelEditBtn");
const saveEditBtn = document.getElementById("saveEditBtn");
const deleteTaskBtn = document.getElementById("deleteTaskBtn");

let boardState = null;
let draggedTaskId = null;

function openModal() {
  modalBackdrop.classList.remove("hidden");
}

function closeModal() {
  modalBackdrop.classList.add("hidden");
  taskTitle.value = "";
  taskDescription.value = "";
}

function openEditModal(task) {
  editTaskId.value = task.id;
  editTaskTitle.value = task.title;
  editTaskDescription.value = task.description || "";
  editBackdrop.classList.remove("hidden");
}

function closeEditModal() {
  editBackdrop.classList.add("hidden");
}

function renderBoard(board) {
  boardState = board;
  boardEl.innerHTML = "";
  taskColumn.innerHTML = "";

  board.columns.forEach((column) => {
    const option = document.createElement("option");
    option.value = column.id;
    option.textContent = column.title;
    taskColumn.appendChild(option);

    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="task-list" data-column-id="${column.id}"></div>
    `;

    const taskList = columnEl.querySelector(".task-list");

    column.tasks.forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        draggedTaskId = null;
        taskEl.classList.remove("dragging");
      });

      taskEl.addEventListener("dblclick", () => openEditModal(task));

      taskList.appendChild(taskEl);
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drop-zone");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drop-zone");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drop-zone");

      if (!draggedTaskId) return;

      const targetColumnId = taskList.dataset.columnId;
      const tasks = Array.from(taskList.querySelectorAll(".task"));
      const targetIndex = tasks.length;

      socket.emit("task:move", {
        taskId: draggedTaskId,
        targetColumnId,
        targetIndex
      });
    });

    boardEl.appendChild(columnEl);
  });
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

addTaskBtn.addEventListener("click", openModal);
cancelTaskBtn.addEventListener("click", closeModal);

saveTaskBtn.addEventListener("click", () => {
  const columnId = taskColumn.value;
  const title = taskTitle.value.trim();
  const description = taskDescription.value.trim();

  if (!title) return;

  socket.emit("task:create", { columnId, title, description });
  closeModal();
});

cancelEditBtn.addEventListener("click", closeEditModal);

saveEditBtn.addEventListener("click", () => {
  const taskId = editTaskId.value;
  const title = editTaskTitle.value.trim();
  const description = editTaskDescription.value.trim();

  socket.emit("task:update", { taskId, title, description });
  closeEditModal();
});

deleteTaskBtn.addEventListener("click", () => {
  const taskId = editTaskId.value;
  socket.emit("task:delete", { taskId });
  closeEditModal();
});

modalBackdrop.addEventListener("click", (e) => {
  if (e.target === modalBackdrop) closeModal();
});

editBackdrop.addEventListener("click", (e) => {
  if (e.target === editBackdrop) closeEditModal();
});

socket.on("connect", () => {
  statusEl.textContent = "Connected";
});

socket.on("disconnect", () => {
  statusEl.textContent = "Disconnected";
});

socket.on("board:init", (board) => {
  renderBoard(board);
});

socket.on("board:update", (board) => {
  renderBoard(board);
});
