## 3) Backend: `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { v4 as uuidv4 } from "uuid";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST", "PUT", "DELETE"]
  }
});

// In-memory store for demo purposes
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: []
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: []
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {}
};

// Seed tasks
const seedTask1 = {
  id: uuidv4(),
  title: "Design project layout",
  description: "Create initial wireframes and layout structure.",
  status: "todo",
  updatedAt: Date.now()
};
const seedTask2 = {
  id: uuidv4(),
  title: "Set up authentication",
  description: "Implement login and session handling.",
  status: "inprogress",
  updatedAt: Date.now()
};

board.tasks[seedTask1.id] = seedTask1;
board.tasks[seedTask2.id] = seedTask2;
board.columns[0].taskIds.push(seedTask1.id);
board.columns[1].taskIds.push(seedTask2.id);

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description = "", status = "todo" } = req.body;
  if (!title) return res.status(400).json({ error: "Title is required" });

  const task = {
    id: uuidv4(),
    title,
    description,
    status,
    updatedAt: Date.now()
  };

  board.tasks[task.id] = task;
  const column = board.columns.find(c => c.id === status);
  if (column) column.taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description, status } = req.body;

  if (title !== undefined) task.title = title;
  if (description !== undefined) task.description = description;

  if (status && status !== task.status) {
    const oldColumn = board.columns.find(c => c.id === task.status);
    const newColumn = board.columns.find(c => c.id === status);

    if (oldColumn) oldColumn.taskIds = oldColumn.taskIds.filter(tid => tid !== id);
    if (newColumn) newColumn.taskIds.push(id);

    task.status = status;
  }

  task.updatedAt = Date.now();
  io.emit("board:update", board);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const column = board.columns.find(c => c.id === task.status);
  if (column) column.taskIds = column.taskIds.filter(tid => tid !== id);

  delete board.tasks[id];
  io.emit("board:update", board);
  res.json({ success: true });
});

app.post("/api/tasks/reorder", (req, res) => {
  const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex, taskId } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const destinationColumn = board.columns.find(c => c.id === destinationColumnId);

  if (!sourceColumn || !destinationColumn) {
    return res.status(400).json({ error: "Invalid columns" });
  }

  sourceColumn.taskIds.splice(sourceIndex, 1);
  destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

  const task = board.tasks[taskId];
  if (task) {
    task.status = destinationColumnId;
    task.updatedAt = Date.now();
  }

  io.emit("board:update", board);
  res.json(board);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", (data) => {
    const task = {
      id: uuidv4(),
      title: data.title,
      description: data.description || "",
      status: data.status || "todo",
      updatedAt: Date.now()
    };

    board.tasks[task.id] = task;
    const column = board.columns.find(c => c.id === task.status);
    if (column) column.taskIds.push(task.id);

    io.emit("board:update", board);
  });

  socket.on("task:update", (data) => {
    const task = board.tasks[data.id];
    if (!task) return;

    if (data.title !== undefined) task.title = data.title;
    if (data.description !== undefined) task.description = data.description;

    if (data.status && data.status !== task.status) {
      const oldColumn = board.columns.find(c => c.id === task.status);
      const newColumn = board.columns.find(c => c.id === data.status);

      if (oldColumn) oldColumn.taskIds = oldColumn.taskIds.filter(tid => tid !== task.id);
      if (newColumn) newColumn.taskIds.push(task.id);

      task.status = data.status;
    }

    task.updatedAt = Date.now();
    io.emit("board:update", board);
  });

  socket.on("task:delete", (id) => {
    const task = board.tasks[id];
    if (!task) return;

    const column = board.columns.find(c => c.id === task.status);
    if (column) column.taskIds = column.taskIds.filter(tid => tid !== id);

    delete board.tasks[id];
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

