## 7) Frontend: `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove
} from "@dnd-kit/sortable";

const socket = io("http://localhost:4000");

function TaskCard({ task, onDelete }) {
  return (
    <div className="task-card">
      <div className="task-card-header">
        <strong>{task.title}</strong>
        <button className="delete-btn" onClick={() => onDelete(task.id)}>
          ×
        </button>
      </div>
      <p>{task.description}</p>
      <small>Updated: {new Date(task.updatedAt).toLocaleTimeString()}</small>
    </div>
  );
}

function Column({ column, tasks, onDeleteTask }) {
  return (
    <div className="column">
      <h2>{column.title}</h2>
      <SortableContext items={tasks.map(t => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map(task => (
            <TaskCard key={task.id} task={task} onDelete={onDeleteTask} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    fetch("http://localhost:4000/api/board")
      .then(res => res.json())
      .then(setBoard);

    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:update");
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    for (const column of board.columns) {
      result[column.id] = column.taskIds.map(id => board.tasks[id]).filter(Boolean);
    }
    return result;
  }, [board]);

  const handleCreateTask = (e) => {
    e.preventDefault();
    if (!title.trim()) return;

    socket.emit("task:create", {
      title,
      description,
      status: "todo"
    });

    setTitle("");
    setDescription("");
  };

  const handleDeleteTask = (id) => {
    socket.emit("task:delete", id);
  };

  const findColumnByTaskId = (taskId) => {
    if (!board) return null;
    return board.columns.find(col => col.taskIds.includes(taskId));
  };

  const handleDragEnd = async (event) => {
    const { active, over } = event;
    if (!active || !over || active.id === over.id || !board) return;

    const sourceColumn = findColumnByTaskId(active.id);
    const destinationColumn = findColumnByTaskId(over.id) || board.columns.find(c => c.id === over.id);

    if (!sourceColumn || !destinationColumn) return;

    const sourceTasks = [...sourceColumn.taskIds];
    const destinationTasks =
      sourceColumn.id === destinationColumn.id
        ? sourceTasks
        : [...destinationColumn.taskIds];

    const sourceIndex = sourceTasks.indexOf(active.id);
    const destinationIndex = destinationTasks.indexOf(over.id);

    if (sourceColumn.id === destinationColumn.id) {
      const reordered = arrayMove(sourceTasks, sourceIndex, destinationIndex);
      const updatedBoard = {
        ...board,
        columns: board.columns.map(col =>
          col.id === sourceColumn.id ? { ...col, taskIds: reordered } : col
        )
      };
      setBoard(updatedBoard);
    } else {
      sourceTasks.splice(sourceIndex, 1);
      destinationTasks.splice(destinationIndex < 0 ? destinationTasks.length : destinationIndex, 0, active.id);

      const updatedBoard = {
        ...board,
        columns: board.columns.map(col => {
          if (col.id === sourceColumn.id) return { ...col, taskIds: sourceTasks };
          if (col.id === destinationColumn.id) return { ...col, taskIds: destinationTasks };
          return col;
        })
      };
      setBoard(updatedBoard);
    }

    socket.emit("task:update", {
      id: active.id,
      status: destinationColumn.id
    });
  };

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <form className="task-form" onSubmit={handleCreateTask}>
          <input
            type="text"
            placeholder="Task title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columns.map(column => (
            <Column
              key={column.id}
              column={column}
              tasks={tasksByColumn[column.id] || []}
              onDeleteTask={handleDeleteTask}
            />
          ))}
        </div>
      </DndContext>
    </div>
  );
}
```

