  function updateBoard(newBoard) {
    setBoard(newBoard);
    socket.emit("board:update", newBoard);
  }

  function findColumnByTaskId(taskId, currentBoard) {
    return currentBoard.columnOrder.find((colId) =>
      currentBoard.columns[colId].taskIds.includes(taskId)
    );
  }

  function handleDragStart(event) {
    setActiveTaskId(event.active.id);
  }

  function handleDragEnd(event) {
    setActiveTaskId(null);

    const { active, over } = event;
    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    const sourceColumnId = findColumnByTaskId(activeId, board);
    const targetColumnId = board.columns[overId]
      ? overId
      : findColumnByTaskId(overId, board);

    if (!sourceColumnId || !targetColumnId) return;

    const sourceColumn = board.columns[sourceColumnId];
    const targetColumn = board.columns[targetColumnId];

    const sourceIndex = sourceColumn.taskIds.indexOf(activeId);

    // Moving within same column
    if (sourceColumnId === targetColumnId) {
      const targetIndex = targetColumn.taskIds.indexOf(overId);
      if (sourceIndex !== targetIndex) {
        const newTaskIds = arrayMove(sourceColumn.taskIds, sourceIndex, targetIndex);
        const newBoard = {
          ...board,
          columns: {
            ...board.columns,
            [sourceColumnId]: {
              ...sourceColumn,
              taskIds: newTaskIds
            }
          }
        };
        updateBoard(newBoard);
      }
      return;
    }

    // Moving across columns
    const newSourceTaskIds = sourceColumn.taskIds.filter((id) => id !== activeId);
    const overTaskIndex = targetColumn.taskIds.indexOf(overId);
    const insertIndex = overTaskIndex >= 0 ? overTaskIndex : targetColumn.taskIds.length;

    const newTargetTaskIds = [...targetColumn.taskIds];
    newTargetTaskIds.splice(insertIndex, 0, activeId);

    const newBoard = {
      ...board,
      columns: {
        ...board.columns,
        [sourceColumnId]: {
          ...sourceColumn,
          taskIds: newSourceTaskIds
        },
        [targetColumnId]: {
          ...targetColumn,
          taskIds: newTargetTaskIds
        }
      }
    };

    updateBoard(newBoard);
  }

  if (!board) {
    return <div className="app-loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columnOrder.map((columnId) => {
            const column = board.columns[columnId];
            const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);

            return (
              <div key={column.id} className="column">
                <h2>{column.title}</h2>

                <SortableContext
                  items={column.taskIds}
                  strategy={verticalListSortingStrategy}
                >
                  <div className="task-list" id={column.id}>
                    {tasks.map((task) => (
                      <SortableTask key={task.id} task={task} />
                    ))}
                  </div>
                </SortableContext>
              </div>
            );
          })}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

