```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory board state
let board = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    doing: {
      id: "doing",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", content: "Design app layout" },
    "task-2": { id: "task-2", content: "Set up authentication" },
    "task-3": { id: "task-3", content: "Implement drag and drop" }
  },
  columnOrder: ["todo", "doing", "done"]
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/board/reset", (req, res) => {
  board = {
    columns: {
      todo: {
        id: "todo",
        title: "To Do",
        taskIds: ["task-1", "task-2"]
      },
      doing: {
        id: "doing",
        title: "In Progress",
        taskIds: ["task-3"]
      },
      done: {
        id: "done",
        title: "Done",
        taskIds: []
      }
    },
    tasks: {
      "task-1": { id: "task-1", content: "Design app layout" },
      "task-2": { id: "task-2", content: "Set up authentication" },
      "task-3": { id: "task-3", content: "Implement drag and drop" }
    },
    columnOrder: ["todo", "doing", "done"]
  };

  io.emit("board:update", board);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:move", (payload) => {
    const { sourceColumnId, destinationColumnId, sourceIndex, destinationIndex } = payload;

    if (
      !board.columns[sourceColumnId] ||
      !board.columns[destinationColumnId] ||
      sourceIndex == null ||
      destinationIndex == null
    ) {
      return;
    }

    const sourceTasks = [...board.columns[sourceColumnId].taskIds];
    const destinationTasks =
      sourceColumnId === destinationColumnId
        ? sourceTasks
        : [...board.columns[destinationColumnId].taskIds];

    const [movedTaskId] = sourceTasks.splice(sourceIndex, 1);
    destinationTasks.splice(destinationIndex, 0, movedTaskId);

    board.columns[sourceColumnId].taskIds = sourceTasks;
    board.columns[destinationColumnId].taskIds = destinationTasks;

    io.emit("board:update", board);
  });

  socket.on("task:add", (payload) => {
    const { columnId, content } = payload;
    if (!board.columns[columnId] || !content?.trim()) return;

    const id = `task-${Date.now()}`;
    board.tasks[id] = { id, content: content.trim() };
    board.columns[columnId].taskIds.unshift(id);

    io.emit("board:update", board);
  });

  socket.on("task:delete", (payload) => {
    const { taskId } = payload;
    if (!board.tasks[taskId]) return;

    for (const column of Object.values(board.columns)) {
      column.taskIds = column.taskIds.filter((id) => id !== taskId);
    }

    delete board.tasks[taskId];
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
