import React, { useEffect, useMemo, useState } from "react";
import { socket } from "./socket";

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskText, setNewTaskText] = useState("");
  const [newTaskColumn, setNewTaskColumn] = useState("todo");
  const [dragging, setDragging] = useState(null);

  useEffect(() => {
    const handleBoardUpdate = (updatedBoard) => setBoard(updatedBoard);

    socket.on("board:update", handleBoardUpdate);

    return () => {
      socket.off("board:update", handleBoardUpdate);
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((columnId) => board.columns[columnId]);
  }, [board]);

  const handleAddTask = (e) => {
    e.preventDefault();
    socket.emit("task:add", {
      columnId: newTaskColumn,
      content: newTaskText
    });
    setNewTaskText("");
  };

  const handleDragStart = (taskId, sourceColumnId, sourceIndex) => {
    setDragging({ taskId, sourceColumnId, sourceIndex });
  };

  const handleDrop = (destinationColumnId, destinationIndex) => {
    if (!dragging) return;

    socket.emit("task:move", {
      sourceColumnId: dragging.sourceColumnId,
      destinationColumnId,
      sourceIndex: dragging.sourceIndex,
      destinationIndex
    });

    setDragging(null);
  };

  const handleDelete = (taskId) => {
    socket.emit("task:delete", { taskId });
  };

  if (!board) {
    return <div className="app loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <div>
          <h1>Project Manager</h1>
          <p>Drag-and-drop boards with real-time collaboration</p>
        </div>

        <form className="add-task-form" onSubmit={handleAddTask}>
          <select
            value={newTaskColumn}
            onChange={(e) => setNewTaskColumn(e.target.value)}
          >
            {columns.map((col) => (
              <option key={col.id} value={col.id}>
                {col.title}
              </option>
            ))}
          </select>

          <input
            type="text"
            placeholder="New task..."
            value={newTaskText}
            onChange={(e) => setNewTaskText(e.target.value)}
          />

          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(column.id, column.taskIds.length)}
          >
            <div className="column-header">
              <h2>{column.title}</h2>
              <span>{column.taskIds.length}</span>
            </div>

            <div className="task-list">
              {column.taskIds.map((taskId, index) => {
                const task = board.tasks[taskId];
                return (
                  <article
                    key={task.id}
                    className={`task ${dragging?.taskId === task.id ? "dragging" : ""}`}
                    draggable
                    onDragStart={() => handleDragStart(task.id, column.id, index)}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={() => handleDrop(column.id, index)}
                  >
                    <span>{task.content}</span>
                    <button
                      className="delete-btn"
                      onClick={() => handleDelete(task.id)}
                      aria-label="Delete task"
                    >
                      ×
                    </button>
                  </article>
                );
              })}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

