## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");
const path = require("path");
const crypto = require("crypto");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.json());
app.use(express.static(path.join(__dirname, "public")));

// In-memory data store
let board = {
  columns: [
    { id: "todo", title: "To Do", taskIds: [] },
    { id: "doing", title: "In Progress", taskIds: [] },
    { id: "done", title: "Done", taskIds: [] }
  ],
  tasks: {}
};

function createTask({ title, description = "" }) {
  const id = crypto.randomUUID();
  return {
    id,
    title,
    description,
    createdAt: new Date().toISOString()
  };
}

// Seed with sample tasks
const t1 = createTask({ title: "Design UI mockups", description: "Create initial wireframes" });
const t2 = createTask({ title: "Set up auth", description: "Add login and registration" });
board.tasks[t1.id] = t1;
board.tasks[t2.id] = t2;
board.columns[0].taskIds.push(t1.id);
board.columns[1].taskIds.push(t2.id);

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/tasks", (req, res) => {
  const { title, description, columnId = "todo" } = req.body;
  if (!title || !title.trim()) {
    return res.status(400).json({ error: "Title is required" });
  }

  const task = createTask({ title: title.trim(), description: description?.trim() || "" });
  board.tasks[task.id] = task;

  const column = board.columns.find(c => c.id === columnId);
  if (!column) return res.status(400).json({ error: "Invalid column" });

  column.taskIds.push(task.id);

  io.emit("board:update", board);
  res.status(201).json(task);
});

app.put("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  const task = board.tasks[id];
  if (!task) return res.status(404).json({ error: "Task not found" });

  const { title, description } = req.body;
  if (typeof title === "string") task.title = title;
  if (typeof description === "string") task.description = description;

  io.emit("board:update", board);
  res.json(task);
});

app.delete("/api/tasks/:id", (req, res) => {
  const { id } = req.params;
  if (!board.tasks[id]) return res.status(404).json({ error: "Task not found" });

  // Remove from columns
  for (const column of board.columns) {
    column.taskIds = column.taskIds.filter(taskId => taskId !== id);
  }

  delete board.tasks[id];
  io.emit("board:update", board);
  res.json({ ok: true });
});

app.post("/api/move-task", (req, res) => {
  const { taskId, fromColumnId, toColumnId, toIndex } = req.body;

  const fromColumn = board.columns.find(c => c.id === fromColumnId);
  const toColumn = board.columns.find(c => c.id === toColumnId);

  if (!fromColumn || !toColumn) {
    return res.status(400).json({ error: "Invalid column" });
  }

  fromColumn.taskIds = fromColumn.taskIds.filter(id => id !== taskId);

  const insertIndex = typeof toIndex === "number" ? toIndex : toColumn.taskIds.length;
  toColumn.taskIds.splice(insertIndex, 0, taskId);

  io.emit("board:update", board);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:create", (payload) => {
    const { title, description, columnId } = payload;
    if (!title || !title.trim()) return;

    const task = createTask({ title: title.trim(), description: description?.trim() || "" });
    board.tasks[task.id] = task;

    const column = board.columns.find(c => c.id === (columnId || "todo"));
    if (column) column.taskIds.push(task.id);

    io.emit("board:update", board);
  });

  socket.on("task:update", ({ id, title, description }) => {
    const task = board.tasks[id];
    if (!task) return;

    if (typeof title === "string") task.title = title;
    if (typeof description === "string") task.description = description;

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ id }) => {
    if (!board.tasks[id]) return;

    for (const column of board.columns) {
      column.taskIds = column.taskIds.filter(taskId => taskId !== id);
    }
    delete board.tasks[id];

    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = board.columns.find(c => c.id === fromColumnId);
    const toColumn = board.columns.find(c => c.id === toColumnId);

    if (!fromColumn || !toColumn) return;

    fromColumn.taskIds = fromColumn.taskIds.filter(id => id !== taskId);
    const insertIndex = typeof toIndex === "number" ? toIndex : toColumn.taskIds.length;
    toColumn.taskIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
