## 6) `public/app.js`

```js
const socket = io();

let boardState = null;
let draggedTask = null;

const boardEl = document.getElementById("board");
const newTaskBtn = document.getElementById("newTaskBtn");

const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");
const taskColumn = document.getElementById("taskColumn");
const cancelTaskBtn = document.getElementById("cancelTaskBtn");

const editDialog = document.getElementById("editDialog");
const editForm = document.getElementById("editForm");
const editTaskId = document.getElementById("editTaskId");
const editTaskTitle = document.getElementById("editTaskTitle");
const editTaskDescription = document.getElementById("editTaskDescription");
const cancelEditBtn = document.getElementById("cancelEditBtn");
const deleteTaskBtn = document.getElementById("deleteTaskBtn");

newTaskBtn.addEventListener("click", () => {
  taskForm.reset();
  taskDialog.showModal();
});

cancelTaskBtn.addEventListener("click", () => taskDialog.close());
cancelEditBtn.addEventListener("click", () => editDialog.close());

taskForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  socket.emit("task:create", {
    title: taskTitle.value,
    description: taskDescription.value,
    columnId: taskColumn.value
  });

  taskDialog.close();
});

editForm.addEventListener("submit", (e) => {
  e.preventDefault();

  socket.emit("task:update", {
    id: editTaskId.value,
    title: editTaskTitle.value,
    description: editTaskDescription.value
  });

  editDialog.close();
});

deleteTaskBtn.addEventListener("click", () => {
  const id = editTaskId.value;
  if (!id) return;

  socket.emit("task:delete", { id });
  editDialog.close();
});

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard();
});

function renderBoard() {
  if (!boardState) return;

  boardEl.innerHTML = "";

  boardState.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    columnEl.innerHTML = `
      <h2>${column.title}</h2>
      <div class="task-list" data-column-id="${column.id}"></div>
    `;

    const taskListEl = columnEl.querySelector(".task-list");

    columnEl.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    columnEl.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTask) return;

      const toColumnId = column.id;
      const fromColumnId = draggedTask.fromColumnId;

      if (fromColumnId === toColumnId) {
        // Reorder within same column
        const tasks = [...boardState.columns.find(c => c.id === toColumnId).taskIds];
        const fromIndex = tasks.indexOf(draggedTask.taskId);
        const toIndex = tasks.length;

        socket.emit("task:move", {
          taskId: draggedTask.taskId,
          fromColumnId,
          toColumnId,
          toIndex
        });
      } else {
        socket.emit("task:move", {
          taskId: draggedTask.taskId,
          fromColumnId,
          toColumnId,
          toIndex: boardState.columns.find(c => c.id === toColumnId).taskIds.length
        });
      }

      draggedTask = null;
    });

    column.taskIds.forEach((taskId) => {
      const task = boardState.tasks[taskId];
      if (!task) return;

      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="meta">ID: ${task.id.slice(0, 8)}</div>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = { taskId: task.id, fromColumnId: column.id };
      });

      taskEl.addEventListener("dblclick", () => {
        editTaskId.value = task.id;
        editTaskTitle.value = task.title;
        editTaskDescription.value = task.description || "";
        editDialog.showModal();
      });

      taskListEl.appendChild(taskEl);
    });

    boardEl.appendChild(columnEl);
  });
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
