### `client/src/App.jsx`

```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const API_URL = "http://localhost:4000";
const socket = io(API_URL);

function App() {
  const [board, setBoard] = useState(null);
  const [draggingTaskId, setDraggingTaskId] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then((res) => res.json())
      .then(setBoard);

    socket.on("board:update", setBoard);

    return () => {
      socket.off("board:update", setBoard);
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    board.columns.forEach((column) => {
      result[column.id] = column.taskIds.map((taskId) => board.tasks[taskId]);
    });
    return result;
  }, [board]);

  const handleDragStart = (taskId) => {
    setDraggingTaskId(taskId);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleDrop = async (destinationColumnId, destinationIndex) => {
    if (!draggingTaskId || !board) return;

    let sourceColumnId = null;
    for (const column of board.columns) {
      if (column.taskIds.includes(draggingTaskId)) {
        sourceColumnId = column.id;
        break;
      }
    }

    if (!sourceColumnId) return;

    await fetch(`${API_URL}/api/move-task`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        taskId: draggingTaskId,
        sourceColumnId,
        destinationColumnId,
        destinationIndex
      })
    });

    setDraggingTaskId(null);
  };

  const handleAddTask = async (columnId = "todo") => {
    if (!newTaskTitle.trim()) return;

    await fetch(`${API_URL}/api/tasks`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        title: newTaskTitle,
        description: newTaskDescription,
        columnId
      })
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <div className="new-task-form">
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <button onClick={() => handleAddTask("todo")}>Add Task</button>
        </div>
      </header>

      <main className="board">
        {board.columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={handleDragOver}
            onDrop={() => handleDrop(column.id, column.taskIds.length)}
          >
            <h2>{column.title}</h2>

            <div className="task-list">
              {tasksByColumn[column.id].map((task, index) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={() => handleDragStart(task.id)}
                  onDragOver={handleDragOver}
                  onDrop={(e) => {
                    e.stopPropagation();
                    handleDrop(column.id, index);
                  }}
                >
                  <strong>{task.title}</strong>
                  <p>{task.description}</p>
                </div>
              ))}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}

export default App;
```

