### `server/index.js`

```js
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for initial implementation
let boards = {
  default: {
    id: "default",
    name: "Main Board",
    columns: [
      {
        id: "todo",
        title: "To Do",
        taskIds: ["task-1", "task-2"]
      },
      {
        id: "doing",
        title: "In Progress",
        taskIds: ["task-3"]
      },
      {
        id: "done",
        title: "Done",
        taskIds: []
      }
    ],
    tasks: {
      "task-1": { id: "task-1", title: "Set up project", description: "Initialize repo and tooling" },
      "task-2": { id: "task-2", title: "Design UI", description: "Create wireframes and layout" },
      "task-3": { id: "task-3", title: "Implement drag-and-drop", description: "Use HTML5 drag events" }
    }
  }
};

app.get("/api/boards/:boardId", (req, res) => {
  const board = boards[req.params.boardId];
  if (!board) return res.status(404).json({ error: "Board not found" });
  res.json(board);
});

app.post("/api/boards/:boardId/tasks", (req, res) => {
  const board = boards[req.params.boardId];
  if (!board) return res.status(404).json({ error: "Board not found" });

  const { title, description, columnId } = req.body;
  const id = `task-${Date.now()}`;

  board.tasks[id] = {
    id,
    title,
    description: description || ""
  };

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) return res.status(400).json({ error: "Invalid column" });

  column.taskIds.push(id);

  io.emit("board:update", board);
  res.status(201).json(board.tasks[id]);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.on("board:join", (boardId) => {
    socket.join(boardId);
    const board = boards[boardId];
    if (board) socket.emit("board:update", board);
  });

  socket.on("task:move", ({ boardId, taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const board = boards[boardId];
    if (!board) return;

    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);
    if (!sourceColumn || !destinationColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);
    destinationColumn.taskIds.splice(destinationIndex, 0, taskId);

    io.to(boardId).emit("board:update", board);
  });

  socket.on("task:create", ({ boardId, title, description, columnId }) => {
    const board = boards[boardId];
    if (!board) return;

    const id = `task-${Date.now()}`;
    board.tasks[id] = { id, title, description: description || "" };

    const column = board.columns.find((c) => c.id === columnId);
    if (!column) return;

    column.taskIds.push(id);

    io.to(boardId).emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

server.listen(3001, () => {
  console.log("Server running on http://localhost:3001");
});
```

