```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:3001");

export default function App() {
  const boardId = "default";
  const [board, setBoard] = useState(null);
  const [draggingTaskId, setDraggingTaskId] = useState(null);

  useEffect(() => {
    socket.emit("board:join", boardId);

    socket.on("board:update", (updatedBoard) => {
      setBoard({ ...updatedBoard });
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    board.columns.forEach((column) => {
      result[column.id] = column.taskIds.map((taskId) => board.tasks[taskId]);
    });
    return result;
  }, [board]);

  const handleDragStart = (taskId) => {
    setDraggingTaskId(taskId);
  };

  const handleDrop = (destinationColumnId, destinationIndex) => {
    if (!board || !draggingTaskId) return;

    let sourceColumnId = null;
    for (const column of board.columns) {
      if (column.taskIds.includes(draggingTaskId)) {
        sourceColumnId = column.id;
        break;
      }
    }

    if (!sourceColumnId) return;

    socket.emit("task:move", {
      boardId,
      taskId: draggingTaskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    });

    setDraggingTaskId(null);
  };

  const addTask = (columnId) => {
    const title = prompt("Task title?");
    if (!title) return;

    const description = prompt("Task description?") || "";

    socket.emit("task:create", {
      boardId,
      title,
      description,
      columnId
    });
  };

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>{board.name}</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <div className="board">
        {board.columns.map((column) => (
          <div
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(column.id, column.taskIds.length)}
          >
            <div className="column-header">
              <h2>{column.title}</h2>
              <button onClick={() => addTask(column.id)}>+ Task</button>
            </div>

            <div className="task-list">
              {tasksByColumn[column.id].map((task, index) => (
                <div
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={() => handleDragStart(task.id)}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => {
                    e.stopPropagation();
                    handleDrop(column.id, index);
                  }}
                >
                  <strong>{task.title}</strong>
                  <p>{task.description}</p>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
```

