## `server/index.js`

```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory board state for initial implementation
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Set up project", description: "Initialize app structure" },
        { id: "task-2", title: "Design UI", description: "Create board layout" }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Build drag and drop", description: "Implement task movement" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/board/task", (req, res) => {
  const { columnId, task } = req.body;

  if (!columnId || !task || !task.id || !task.title) {
    return res.status(400).json({ error: "Invalid task payload" });
  }

  const column = board.columns.find((c) => c.id === columnId);
  if (!column) {
    return res.status(404).json({ error: "Column not found" });
  }

  column.tasks.push(task);
  io.emit("board:update", board);

  res.status(201).json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:moved", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = board.columns.find((c) => c.id === fromColumnId);
    const toColumn = board.columns.find((c) => c.id === toColumnId);

    if (!fromColumn || !toColumn) return;

    const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromColumn.tasks.splice(taskIndex, 1);

    const insertIndex =
      typeof toIndex === "number" && toIndex >= 0 && toIndex <= toColumn.tasks.length
        ? toIndex
        : toColumn.tasks.length;

    toColumn.tasks.splice(insertIndex, 0, task);

    io.emit("board:update", board);
  });

  socket.on("task:created", ({ columnId, task }) => {
    const column = board.columns.find((c) => c.id === columnId);
    if (!column || !task?.id || !task?.title) return;

    column.tasks.push(task);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

