## `client/app.js`

```js
const socket = io("http://localhost:3001");

const boardEl = document.getElementById("board");
const columnTemplate = document.getElementById("columnTemplate");
const taskTemplate = document.getElementById("taskTemplate");
const addTaskBtn = document.getElementById("addTaskBtn");
const newTaskTitleInput = document.getElementById("newTaskTitle");

let boardState = null;
let draggedTaskId = null;
let draggedFromColumnId = null;

function renderBoard(board) {
  boardEl.innerHTML = "";

  board.columns.forEach((column) => {
    const columnNode = columnTemplate.content.cloneNode(true);
    const section = columnNode.querySelector(".column");
    const title = columnNode.querySelector(".column-title");
    const taskList = columnNode.querySelector(".task-list");

    title.textContent = `${column.title} (${column.tasks.length})`;
    taskList.dataset.columnId = column.id;

    column.tasks.forEach((task) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      const taskTitle = taskNode.querySelector(".task-title");
      const taskDesc = taskNode.querySelector(".task-desc");

      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;
      taskTitle.textContent = task.title;
      taskDesc.textContent = task.description || "";

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFromColumnId = column.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskList.appendChild(taskNode);
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFromColumnId) return;

      const toColumnId = taskList.dataset.columnId;
      const tasks = Array.from(taskList.querySelectorAll(".task"));
      const toIndex = tasks.length;

      socket.emit("task:moved", {
        taskId: draggedTaskId,
        fromColumnId: draggedFromColumnId,
        toColumnId,
        toIndex
      });

      draggedTaskId = null;
      draggedFromColumnId = null;
    });

    boardEl.appendChild(columnNode);
  });
}

socket.on("board:update", (board) => {
  boardState = board;
  renderBoard(boardState);
});

addTaskBtn.addEventListener("click", () => {
  const title = newTaskTitleInput.value.trim();
  if (!title || !boardState) return;

  const task = {
    id: `task-${Date.now()}`,
    title,
    description: "New task"
  };

  socket.emit("task:created", {
    columnId: "todo",
    task
  });

  newTaskTitleInput.value = "";
});

newTaskTitleInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});
