### `server/index.js`

```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory board state for initial implementation
let board = {
  todo: [
    { id: "task-1", title: "Design app layout" },
    { id: "task-2", title: "Set up authentication" }
  ],
  doing: [
    { id: "task-3", title: "Implement drag and drop" }
  ],
  done: [
    { id: "task-4", title: "Create project scaffold" }
  ]
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/board", (req, res) => {
  board = req.body;
  io.emit("board:update", board);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:add", ({ columnId, task }) => {
    if (!board[columnId]) return;
    board[columnId].push(task);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ sourceColumnId, destColumnId, sourceIndex, destIndex }) => {
    if (!board[sourceColumnId] || !board[destColumnId]) return;

    const [movedTask] = board[sourceColumnId].splice(sourceIndex, 1);
    if (!movedTask) return;

    board[destColumnId].splice(destIndex, 0, movedTask);
    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ columnId, taskId }) => {
    if (!board[columnId]) return;
    board[columnId] = board[columnId].filter((task) => task.id !== taskId);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

