## 5) Frontend: JavaScript with drag-and-drop + realtime sync

### `client/app.js`

```js
const socket = io("http://localhost:3000");

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const newTaskInput = document.getElementById("newTaskInput");
const newTaskColumn = document.getElementById("newTaskColumn");

let boardState = {
  todo: [],
  doing: [],
  done: []
};

let draggedTask = null;
let draggedFromColumn = null;
let draggedFromIndex = null;

function renderBoard(board) {
  boardState = board;

  ["todo", "doing", "done"].forEach((columnId) => {
    const columnEl = document.getElementById(columnId);
    columnEl.innerHTML = "";

    board[columnId].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <span>${escapeHtml(task.title)}</span>
        <button title="Delete task">×</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = task;
        draggedFromColumn = columnId;
        draggedFromIndex = index;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
        draggedTask = null;
        draggedFromColumn = null;
        draggedFromIndex = null;
      });

      taskEl.querySelector("button").addEventListener("click", () => {
        socket.emit("task:delete", { columnId, taskId: task.id });
      });

      columnEl.appendChild(taskEl);
    });

    setupDropZone(columnEl, columnId);
  });
}

function setupDropZone(columnEl, columnId) {
  columnEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    columnEl.classList.add("drag-over");
  });

  columnEl.addEventListener("dragleave", () => {
    columnEl.classList.remove("drag-over");
  });

  columnEl.addEventListener("drop", (e) => {
    e.preventDefault();
    columnEl.classList.remove("drag-over");

    if (!draggedTask) return;

    const targetIndex = boardState[columnId].length;

    socket.emit("task:move", {
      sourceColumnId: draggedFromColumn,
      destColumnId: columnId,
      sourceIndex: draggedFromIndex,
      destIndex: targetIndex
    });
  });
}

addTaskBtn.addEventListener("click", () => {
  const title = newTaskInput.value.trim();
  const columnId = newTaskColumn.value;

  if (!title) return;

  const task = {
    id: `task-${Date.now()}`,
    title
  };

  socket.emit("task:add", { columnId, task });

  newTaskInput.value = "";
  newTaskInput.focus();
});

newTaskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

socket.on("board:update", (board) => {
  renderBoard(board);
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

