### `client/src/App.jsx`
```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const SERVER_URL = "http://localhost:4000";

const initialBoard = {
  columns: [],
  tasks: {}
};

export default function App() {
  const [board, setBoard] = useState(initialBoard);
  const [draggedTaskId, setDraggedTaskId] = useState(null);
  const socket = useMemo(() => io(SERVER_URL), []);

  useEffect(() => {
    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.disconnect();
    };
  }, [socket]);

  const moveTask = (taskId, sourceColumnId, targetColumnId, targetIndex) => {
    if (!taskId || sourceColumnId === targetColumnId && targetIndex == null) return;

    const nextBoard = structuredClone(board);

    const sourceColumn = nextBoard.columns.find((c) => c.id === sourceColumnId);
    const targetColumn = nextBoard.columns.find((c) => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn) return;

    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    const insertIndex = targetIndex ?? targetColumn.taskIds.length;
    targetColumn.taskIds.splice(insertIndex, 0, taskId);

    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
  };

  const handleDragStart = (taskId) => {
    setDraggedTaskId(taskId);
  };

  const handleDrop = (columnId, targetIndex = null) => {
    if (!draggedTaskId) return;

    const sourceColumn = board.columns.find((col) =>
      col.taskIds.includes(draggedTaskId)
    );

    if (!sourceColumn) return;

    moveTask(draggedTaskId, sourceColumn.id, columnId, targetIndex);
    setDraggedTaskId(null);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const addTask = (columnId) => {
    const id = `task-${Date.now()}`;
    const nextBoard = structuredClone(board);

    nextBoard.tasks[id] = {
      id,
      title: "New Task",
      description: "Click to edit"
    };

    const column = nextBoard.columns.find((c) => c.id === columnId);
    column.taskIds.push(id);

    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
  };

  const updateTaskTitle = (taskId, title) => {
    const nextBoard = structuredClone(board);
    nextBoard.tasks[taskId].title = title;
    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
  };

  const updateTaskDescription = (taskId, description) => {
    const nextBoard = structuredClone(board);
    nextBoard.tasks[taskId].description = description;
    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <main className="board">
        {board.columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={handleDragOver}
            onDrop={() => handleDrop(column.id)}
          >
            <div className="column-header">
              <h2>{column.title}</h2>
              <button onClick={() => addTask(column.id)}>+ Add</button>
            </div>

            <div className="task-list">
              {column.taskIds.map((taskId) => {
                const task = board.tasks[taskId];
                if (!task) return null;

                return (
                  <article
                    key={task.id}
                    className="task-card"
                    draggable
                    onDragStart={() => handleDragStart(task.id)}
                    onDragOver={handleDragOver}
                    onDrop={(e) => {
                      e.preventDefault();
                      handleDrop(column.id, column.taskIds.indexOf(task.id));
                    }}
                  >
                    <input
                      className="task-title"
                      value={task.title}
                      onChange={(e) => updateTaskTitle(task.id, e.target.value)}
                    />
                    <textarea
                      className="task-desc"
                      value={task.description}
                      onChange={(e) => updateTaskDescription(task.id, e.target.value)}
                    />
                  </article>
                );
              })}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

