```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCenter,
  PointerSensor,
  useSensor,
  useSensors,
  DragOverlay
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  arrayMove,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:3001");

function TaskCard({ task, isDragging = false }) {
  return (
    <div className={`task-card ${isDragging ? "dragging" : ""}`}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function SortableTask({ task }) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging
  } = useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition
  };

  return (
    <div ref={setNodeRef} style={style} {...attributes} {...listeners}>
      <TaskCard task={task} isDragging={isDragging} />
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{tasks.length}</span>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <SortableTask key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [activeTaskId, setActiveTaskId] = useState(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    socket.on("board:update", (nextBoard) => {
      setBoard(nextBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const activeTask = useMemo(() => {
    if (!board || !activeTaskId) return null;
    return board.tasks[activeTaskId];
  }, [board, activeTaskId]);

  function findColumnByTaskId(taskId, currentBoard) {
    return Object.values(currentBoard.columns).find((column) =>
      column.taskIds.includes(taskId)
    );
  }

  function handleDragStart(event) {
    setActiveTaskId(event.active.id);
  }

  function handleDragEnd(event) {
    const { active, over } = event;
    setActiveTaskId(null);

    if (!board || !over || active.id === over.id) return;

    const nextBoard = structuredClone(board);

    const sourceColumn = findColumnByTaskId(active.id, nextBoard);
    const targetColumn = Object.values(nextBoard.columns).find((column) =>
      column.taskIds.includes(over.id)
    );

    if (!sourceColumn || !targetColumn) return;

    const sourceIndex = sourceColumn.taskIds.indexOf(active.id);
    const targetIndex = targetColumn.taskIds.indexOf(over.id);

    // Same column reorder
    if (sourceColumn.id === targetColumn.id) {
      sourceColumn.taskIds = arrayMove(sourceColumn.taskIds, sourceIndex, targetIndex);
    } else {
      sourceColumn.taskIds.splice(sourceIndex, 1);
      targetColumn.taskIds.splice(targetIndex, 0, active.id);
    }

    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
  }

  if (!board) {
    return <div className="app loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="topbar">
        <div>
          <h1>Project Manager</h1>
          <p>Drag tasks across columns. Updates sync in real time.</p>
        </div>
        <div className="status">Live collaboration enabled</div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        onDragStart={handleDragStart}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {board.columnOrder.map((columnId) => {
            const column = board.columns[columnId];
            const tasks = column.taskIds.map((taskId) => board.tasks[taskId]);

            return (
              <Column key={column.id} column={column} tasks={tasks} />
            );
          })}
        </div>

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} isDragging /> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

> Note: This is an initial implementation. For more robust drag behavior across columns, you may later want to add droppable column containers and handle empty-column drops explicitly.

