export type Task = {
  id: string;
  title: string;
  description?: string;
};

export type ColumnId = "todo" | "inprogress" | "done";

export type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

export const initialState: BoardState = {
  columns: {
    todo: [
      { id: "task-1", title: "Set up project" },
      { id: "task-2", title: "Design board layout" }
