### `server/src/index.ts`
```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";
import { BoardState, initialState, ColumnId, Task } from "./state";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let boardState: BoardState = structuredClone(initialState);

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

app.post("/api/tasks", (req, res) => {
  const { columnId, task } = req.body as { columnId: ColumnId; task: Task };
  if (!boardState.columns[columnId]) {
    return res.status(400).json({ error: "Invalid column" });
  }

  boardState.columns[columnId].push(task);
  io.emit("board:update", boardState);
  res.status(201).json(boardState);
});

io.on("connection", (socket) => {
  socket.emit("board:update", boardState);

  socket.on("task:move", (payload: { taskId: string; from: ColumnId; to: ColumnId; index: number }) => {
    const { taskId, from, to, index } = payload;

    const fromTasks = boardState.columns[from];
    const toTasks = boardState.columns[to];

    const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromTasks.splice(taskIndex, 1);
    toTasks.splice(index, 0, task);

    io.emit("board:update", boardState);
  });

  socket.on("task:create", (payload: { columnId: ColumnId; task: Task }) => {
    const { columnId, task } = payload;
    if (!boardState.columns[columnId]) return;

    boardState.columns[columnId].push(task);
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected");
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

