```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";

type ColumnId = "todo" | "inprogress" | "done";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

const API_URL = "http://localhost:4000";
const SOCKET_URL = "http://localhost:4000";

function TaskCard({ task }: { task: Task }) {
  return (
    <div className="task-card">
      <strong>{task.title}</strong>
      {task.description ? <p>{task.description}</p> : null}
    </div>
  );
}

function Column({
  id,
  title,
  tasks,
  onTaskClick
}: {
  id: ColumnId;
  title: string;
  tasks: Task[];
  onTaskClick?: (task: Task) => void;
}) {
  return (
    <div className="column" data-column-id={id}>
      <h2>{title}</h2>
      <div className="task-list">
        {tasks.map((task) => (
          <div key={task.id} data-task-id={task.id} onClick={() => onTaskClick?.(task)}>
            <TaskCard task={task} />
          </div>
        ))}
      </div>
    </div>
  );
}

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [board, setBoard] = useState<BoardState | null>(null);
  const [activeTask, setActiveTask] = useState<Task | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    fetch(`${API_URL}/api/board`)
      .then((res) => res.json())
      .then(setBoard);

    const s = io(SOCKET_URL);
    s.on("board:update", (nextBoard: BoardState) => setBoard(nextBoard));
    setSocket(s);

    return () => {
      s.disconnect();
    };
  }, []);

  const columns = useMemo(
    () => [
      { id: "todo" as const, title: "To Do" },
      { id: "inprogress" as const, title: "In Progress" },
      { id: "done" as const, title: "Done" }
    ],
    []
  );

  function findTaskLocation(taskId: string) {
    if (!board) return null;
    for (const columnId of Object.keys(board.columns) as ColumnId[]) {
      const index = board.columns[columnId].findIndex((t) => t.id === taskId);
      if (index !== -1) return { columnId, index };
    }
    return null;
  }

  function handleDragEnd(event: DragEndEvent) {
    const taskId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!socket || !board || !overId) return;

    const from = findTaskLocation(taskId);
    if (!from) return;

    const targetColumn = (["todo", "inprogress", "done"] as const).includes(overId as ColumnId)
      ? (overId as ColumnId)
      : findTaskLocation(overId)?.columnId;

    if (!targetColumn) return;

    const toIndex =
      (["todo", "inprogress", "done"] as const).includes(overId as ColumnId)
        ? board.columns[targetColumn].length
        : findTaskLocation(overId)?.index ?? board.columns[targetColumn].length;

    socket.emit("task:move", {
      taskId,
      from: from.columnId,
      to: targetColumn,
      index: toIndex
    });

    setActiveTask(null);
  }

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Real-time collaborative task boards</p>
      </header>

      <DndContext
        sensors={sensors}
        onDragStart={(event) => {
          const taskId = String(event.active.id);
          const loc = findTaskLocation(taskId);
          if (!loc) return;
          setActiveTask(board.columns[loc.columnId][loc.index]);
        }}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          {columns.map((col) => (
            <Column
              key={col.id}
              id={col.id}
              title={col.title}
              tasks={board.columns[col.id]}
            />
          ))}
        </div>

        <DragOverlay>{activeTask ? <TaskCard task={activeTask} /> : null}</DragOverlay>
      </DndContext>
    </div>
  );
}
```

