### `server/src/types.ts`
```ts
export type Task = {
  id: string;
  title: string;
  description?: string;
};

export type Column = {
  id: string;
  title: string;
  taskIds: string[];
};

export type BoardState = {
  tasks: Record<string, Task>;
  columns: Record<string, Column>;
  columnOrder: string[];
};

export type ClientMessage =
  | { type: "join"; boardId: string; userId: string }
  | { type: "update-board"; boardId: string; state: BoardState };

export type ServerMessage =
  | { type: "board-state"; boardId: string; state: BoardState }
  | { type: "presence"; boardId: string; users: string[] };
