### `server/src/index.ts`
```ts
import { WebSocketServer } from "ws";
import { BoardState, ClientMessage, ServerMessage } from "./types";

const wss = new WebSocketServer({ port: 8080 });

const boards = new Map<string, BoardState>();
const boardUsers = new Map<string, Set<string>>();
const sockets = new Map<any, { boardId?: string; userId?: string }>();

function createInitialBoard(): BoardState {
  const task1 = { id: "task-1", title: "Design app layout" };
  const task2 = { id: "task-2", title: "Set up WebSocket sync" };
  const task3 = { id: "task-3", title: "Implement drag and drop" };

  return {
    tasks: {
      [task1.id]: task1,
      [task2.id]: task2,
      [task3.id]: task3
    },
    columns: {
      "todo": { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
      "in-progress": { id: "in-progress", title: "In Progress", taskIds: ["task-3"] },
      "done": { id: "done", title: "Done", taskIds: [] }
    },
    columnOrder: ["todo", "in-progress", "done"]
  };
}

function broadcast(boardId: string, message: ServerMessage) {
  for (const client of wss.clients) {
    const meta = sockets.get(client);
    if (client.readyState === client.OPEN && meta?.boardId === boardId) {
      client.send(JSON.stringify(message));
    }
  }
}

wss.on("connection", (ws) => {
  sockets.set(ws, {});

  ws.on("message", (data) => {
    const msg = JSON.parse(data.toString()) as ClientMessage;

    if (msg.type === "join") {
      sockets.set(ws, { boardId: msg.boardId, userId: msg.userId });

      if (!boards.has(msg.boardId)) {
        boards.set(msg.boardId, createInitialBoard());
      }

      if (!boardUsers.has(msg.boardId)) {
        boardUsers.set(msg.boardId, new Set());
      }
      boardUsers.get(msg.boardId)!.add(msg.userId);

      ws.send(JSON.stringify({
        type: "board-state",
        boardId: msg.boardId,
        state: boards.get(msg.boardId)!
      } satisfies ServerMessage));

      broadcast(msg.boardId, {
        type: "presence",
        boardId: msg.boardId,
        users: Array.from(boardUsers.get(msg.boardId)!)
      });
    }

    if (msg.type === "update-board") {
      boards.set(msg.boardId, msg.state);
      broadcast(msg.boardId, {
        type: "board-state",
        boardId: msg.boardId,
        state: msg.state
      });
    }
  });

  ws.on("close", () => {
    const meta = sockets.get(ws);
    if (meta?.boardId && meta?.userId) {
      const users = boardUsers.get(meta.boardId);
      users?.delete(meta.userId);
      broadcast(meta.boardId, {
        type: "presence",
        boardId: meta.boardId,
        users: Array.from(users ?? [])
      });
    }
    sockets.delete(ws);
  });
});

console.log("WebSocket server running on ws://localhost:8080");
```

