### `client/src/App.tsx`
```tsx
import { useCallback, useMemo, useState } from "react";
import { DragEndEvent } from "@dnd-kit/core";
import { Board } from "./components/Board";
import { BoardState, ServerMessage } from "./types";
import { useSocket } from "./hooks/useSocket";

function moveTask(state: BoardState, taskId: string, fromColumnId: string, toColumnId: string) {
  if (fromColumnId === toColumnId) return state;

  const fromColumn = state.columns[fromColumnId];
  const toColumn = state.columns[toColumnId];

  return {
    ...state,
    columns: {
      ...state.columns,
      [fromColumnId]: {
        ...fromColumn,
        taskIds: fromColumn.taskIds.filter((id) => id !== taskId)
      },
      [toColumnId]: {
        ...toColumn,
        taskIds: [...toColumn.taskIds, taskId]
      }
    }
  };
}

export default function App() {
  const boardId = "demo-board";
  const userId = useMemo(() => `user-${Math.random().toString(36).slice(2, 8)}`, []);
  const [state, setState] = useState<BoardState | null>(null);
  const [users, setUsers] = useState<string[]>([]);

  const onMessage = useCallback((msg: ServerMessage) => {
    if (msg.type === "board-state") setState(msg.state);
    if (msg.type === "presence") setUsers(msg.users);
  }, []);

  const { connected, send } = useSocket(boardId, userId, onMessage);

  const handleDragEnd = (event: DragEndEvent) => {
    if (!state) return;

    const taskId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!overId) return;

    const fromColumnId = Object.values(state.columns).find((col) => col.taskIds.includes(taskId))?.id;
    if (!fromColumnId) return;

    const nextState = moveTask(state, taskId, fromColumnId, overId);
    setState(nextState);
    send({ type: "update-board", boardId, state: nextState });
  };

  return (
    <div className="app">
      <header className="header">
        <div>
          <h1>Project Manager</h1>
          <p>{connected ? "Connected" : "Connecting..."}</p>
        </div>
        <div>
          <strong>Users online:</strong> {users.length}
        </div>
      </header>

      {state ? (
        <Board state={state} onDragEnd={handleDragEnd} />
      ) : (
        <p>Loading board...</p>
      )}
    </div>
  );
}
```

