import { arrayMove } from "@dnd-kit/sortable";
import { io, Socket } from "socket.io-client";
import { Board } from "./components/Board";
import "./styles.css";

type Task = {
  id: string;
  title: string;
};

type BoardType = {
  id: string;
  title: string;
  taskIds: string[];
};

type AppState = {
  tasks: Record<string, Task>;
  boards: Record<string, BoardType>;
  boardOrder: string[];
};

const SERVER_URL = "http://localhost:4000";

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [state, setState] = useState<AppState | null>(null);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    const s = io(SERVER_URL);
    setSocket(s);

    s.on("state:update", (nextState: AppState) => {
      setState(nextState);
    });

    return () => {
      s.disconnect();
    };
  }, []);

  const boardList = useMemo(() => {
    if (!state) return [];
    return state.boardOrder.map((boardId) => state.boards[boardId]);
  }, [state]);

  function emitState(nextState: AppState) {
    setState(nextState);
    socket?.emit("state:update", nextState);
  }

  function findBoardByTaskId(taskId: string) {
    if (!state) return null;
    return Object.values(state.boards).find((board) => board.taskIds.includes(taskId)) || null;
  }

  function handleDragStart(event: DragStartEvent) {
    setActiveTaskId(String(event.active.id));
  }

  function handleDragOver(event: DragOverEvent) {
    if (!state) return;

    const activeId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!overId || activeId === overId) return;

    const activeBoard = findBoardByTaskId(activeId);
    const overBoard = state.boards[overId] || findBoardByTaskId(overId);
    if (!activeBoard || !overBoard) return;

    if (activeBoard.id === overBoard.id) return;

    const nextState: AppState = structuredClone(state);
    nextState.boards[activeBoard.id].taskIds = nextState.boards[activeBoard.id].taskIds.filter(
      (id) => id !== activeId
    );
    nextState.boards[overBoard.id].taskIds.push(activeId);

    emitState(nextState);
  }

  function handleDragEnd(event: DragEndEvent) {
    if (!state) return;
    setActiveTaskId(null);

    const activeId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!overId || activeId === overId) return;

    const activeBoard = findBoardByTaskId(activeId);
    const overBoard = state.boards[overId] || findBoardByTaskId(overId);
    if (!activeBoard || !overBoard) return;

    const nextState: AppState = structuredClone(state);

    if (activeBoard.id === overBoard.id) {
      const oldIndex = nextState.boards[activeBoard.id].taskIds.indexOf(activeId);
      const newIndex = nextState.boards[overBoard.id].taskIds.indexOf(overId);
      nextState.boards[activeBoard.id].taskIds = arrayMove(
        nextState.boards[activeBoard.id].taskIds,
        oldIndex,
        newIndex
      );
      emitState(nextState);
    }
  }

  function addTask(boardId: string) {
    if (!state) return;
    const title = prompt("Task title?");
    if (!title) return;

    const id = `task-${crypto.randomUUID()}`;
    const nextState: AppState = structuredClone(state);
    nextState.tasks[id] = { id, title };
    nextState.boards[boardId].taskIds.push(id);
    emitState(nextState);
  }

  if (!state) return <div className="app-shell">Loading...</div>;

  return (
    <div className="app-shell">
      <header className="topbar">
        <h1>Project Manager</h1>
        <p>Drag tasks between boards. Updates sync in real time.</p>
      </header>

      <DndContext sensors={sensors} onDragStart={handleDragStart} onDragOver={handleDragOver} onDragEnd={handleDragEnd}>
        <div className="board-row">
          {boardList.map((board) => (
            <div key={board.id} className="board-wrap">
              <Board
                id={board.id}
                title={board.title}
                tasks={board.taskIds.map((taskId) => state.tasks[taskId])}
              />
              <button className="add-btn" onClick={() => addTask(board.id)}>
                + Add task
              </button>
            </div>
          ))}
        </div>
      </DndContext>

      {activeTaskId && <div className="dragging-indicator">Dragging: {state.tasks[activeTaskId]?.title}</div>}
    </div>
  );
}
```

