### `server/index.js`
```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for initial implementation
let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "in-progress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Set up project", description: "Initialize repo and tooling" },
    "task-2": { id: "task-2", title: "Design UI", description: "Create board layout" },
    "task-3": { id: "task-3", title: "Implement drag and drop", description: "Enable task movement" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body;
  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", (task) => {
    const id = `task-${Date.now()}`;
    const newTask = {
      id,
      title: task.title || "Untitled Task",
      description: task.description || ""
    };

    boardState.tasks[id] = newTask;
    boardState.columns[0].taskIds.unshift(id);

    io.emit("board:update", boardState);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = boardState.columns.find(c => c.id === fromColumnId);
    const toColumn = boardState.columns.find(c => c.id === toColumnId);

    if (!fromColumn || !toColumn) return;

    fromColumn.taskIds = fromColumn.taskIds.filter(id => id !== taskId);

    const insertIndex = typeof toIndex === "number" ? toIndex : toColumn.taskIds.length;
    toColumn.taskIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

