```ts
import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

type Task = {
  id: string;
  title: string;
  description?: string;
  status: "todo" | "inprogress" | "done";
};

type BoardState = {
  tasks: Task[];
};

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

let boardState: BoardState = {
  tasks: [
    { id: "1", title: "Design app layout", status: "todo" },
    { id: "2", title: "Set up authentication", status: "inprogress" },
    { id: "3", title: "Deploy initial version", status: "done" }
  ]
};

app.get("/api/board", (_req, res) => {
  res.json(boardState);
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:create", (task: Omit<Task, "id">) => {
    const newTask: Task = {
      id: crypto.randomUUID(),
      ...task
    };
    boardState.tasks.push(newTask);
    io.emit("board:update", boardState);
  });

  socket.on("task:update", (updatedTask: Task) => {
    boardState.tasks = boardState.tasks.map((task) =>
      task.id === updatedTask.id ? updatedTask : task
    );
    io.emit("board:update", boardState);
  });

  socket.on("task:move", (payload: { taskId: string; status: Task["status"] }) => {
    boardState.tasks = boardState.tasks.map((task) =>
      task.id === payload.taskId ? { ...task, status: payload.status } : task
    );
    io.emit("board:update", boardState);
  });

  socket.on("task:delete", (taskId: string) => {
    boardState.tasks = boardState.tasks.filter((task) => task.id !== taskId);
    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

