```tsx
import { useEffect, useMemo, useState } from "react";
import { io, Socket } from "socket.io-client";

type TaskStatus = "todo" | "inprogress" | "done";

type Task = {
  id: string;
  title: string;
  description?: string;
  status: TaskStatus;
};

type BoardState = {
  tasks: Task[];
};

const SOCKET_URL = "http://localhost:4000";

export default function App() {
  const [socket, setSocket] = useState<Socket | null>(null);
  const [board, setBoard] = useState<BoardState>({ tasks: [] });
  const [newTaskTitle, setNewTaskTitle] = useState("");

  useEffect(() => {
    const s = io(SOCKET_URL);
    setSocket(s);

    s.on("board:update", (state: BoardState) => {
      setBoard(state);
    });

    return () => {
      s.disconnect();
    };
  }, []);

  const columns = useMemo(
    () => [
      { key: "todo" as const, label: "To Do" },
      { key: "inprogress" as const, label: "In Progress" },
      { key: "done" as const, label: "Done" }
    ],
    []
  );

  const tasksByStatus = (status: TaskStatus) =>
    board.tasks.filter((task) => task.status === status);

  const handleDragStart = (e: React.DragEvent, taskId: string) => {
    e.dataTransfer.setData("taskId", taskId);
  };

  const handleDrop = (e: React.DragEvent, status: TaskStatus) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData("taskId");
    if (socket && taskId) {
      socket.emit("task:move", { taskId, status });
    }
  };

  const handleCreateTask = () => {
    if (!socket || !newTaskTitle.trim()) return;

    socket.emit("task:create", {
      title: newTaskTitle.trim(),
      status: "todo"
    });

    setNewTaskTitle("");
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>

        <div className="create-task">
          <input
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            placeholder="New task title"
          />
          <button onClick={handleCreateTask}>Add Task</button>
        </div>
      </header>

      <main className="board">
        {columns.map((column) => (
          <section
            key={column.key}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={(e) => handleDrop(e, column.key)}
          >
            <h2>{column.label}</h2>
            <div className="task-list">
              {tasksByStatus(column.key).map((task) => (
                <article
                  key={task.id}
                  className="task-card"
                  draggable
                  onDragStart={(e) => handleDragStart(e, task.id)}
                >
                  <h3>{task.title}</h3>
                  <small>ID: {task.id}</small>
                </article>
              ))}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

