### `server/index.js`
```js
import express from "express";
import http from "http";
import cors from "cors";
import { Server } from "socket.io";

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for initial implementation
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Design app layout", description: "Create initial UI mockup" },
        { id: "task-2", title: "Set up backend", description: "Initialize Express server" }
      ]
    },
    {
      id: "in-progress",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Implement drag-and-drop", description: "Enable task movement" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", title: "Project scaffold", description: "Create folder structure" }
      ]
    }
  ]
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/board/task", (req, res) => {
  const { columnId, task } = req.body;
  const column = board.columns.find(c => c.id === columnId);
  if (!column) return res.status(404).json({ error: "Column not found" });

  column.tasks.push(task);
  io.emit("board:update", board);
  res.json({ ok: true, board });
});

app.post("/api/board/move", (req, res) => {
  const { sourceColumnId, targetColumnId, taskId, targetIndex } = req.body;

  const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
  const targetColumn = board.columns.find(c => c.id === targetColumnId);

  if (!sourceColumn || !targetColumn) {
    return res.status(404).json({ error: "Column not found" });
  }

  const taskIndex = sourceColumn.tasks.findIndex(t => t.id === taskId);
  if (taskIndex === -1) return res.status(404).json({ error: "Task not found" });

  const [task] = sourceColumn.tasks.splice(taskIndex, 1);
  targetColumn.tasks.splice(targetIndex ?? targetColumn.tasks.length, 0, task);

  io.emit("board:update", board);
  res.json({ ok: true, board });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:create", ({ columnId, task }) => {
    const column = board.columns.find(c => c.id === columnId);
    if (!column) return;

    column.tasks.push(task);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ sourceColumnId, targetColumnId, taskId, targetIndex }) => {
    const sourceColumn = board.columns.find(c => c.id === sourceColumnId);
    const targetColumn = board.columns.find(c => c.id === targetColumnId);

    if (!sourceColumn || !targetColumn) return;

    const taskIndex = sourceColumn.tasks.findIndex(t => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = sourceColumn.tasks.splice(taskIndex, 1);
    targetColumn.tasks.splice(targetIndex ?? targetColumn.tasks.length, 0, task);

    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
