### `client/app.js`
```js
const socket = io("http://localhost:3001");
const boardEl = document.getElementById("board");
const statusEl = document.getElementById("connectionStatus");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskTitleEl = document.getElementById("taskTitle");
const taskDescriptionEl = document.getElementById("taskDescription");
const taskColumnEl = document.getElementById("taskColumn");

let boardData = null;
let draggedTask = null;

socket.on("connect", () => {
  statusEl.textContent = "Connected";
  statusEl.style.background = "#065f46";
});

socket.on("disconnect", () => {
  statusEl.textContent = "Disconnected";
  statusEl.style.background = "#7f1d1d";
});

socket.on("board:update", (board) => {
  boardData = board;
  renderBoard();
});

function renderBoard() {
  if (!boardData) return;

  boardEl.innerHTML = "";

  boardData.columns.forEach((column) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const titleEl = document.createElement("h2");
    titleEl.textContent = column.title;

    const taskListEl = document.createElement("div");
    taskListEl.className = "task-list";
    taskListEl.dataset.columnId = column.id;

    taskListEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskListEl.classList.add("drag-over");
    });

    taskListEl.addEventListener("dragleave", () => {
      taskListEl.classList.remove("drag-over");
    });

    taskListEl.addEventListener("drop", (e) => {
      e.preventDefault();
      taskListEl.classList.remove("drag-over");

      if (!draggedTask) return;

      socket.emit("task:move", {
        sourceColumnId: draggedTask.sourceColumnId,
        targetColumnId: column.id,
        taskId: draggedTask.taskId,
        targetIndex: column.tasks.length
      });

      draggedTask = null;
    });

    column.tasks.forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          sourceColumnId: column.id
        };
      });

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
      `;

      taskListEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(taskListEl);
    boardEl.appendChild(columnEl);
  });
}

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleEl.value.trim();
  const description = taskDescriptionEl.value.trim();
  const columnId = taskColumnEl.value;

  if (!title) return;

  const task = {
    id: `task-${Date.now()}`,
    title,
    description
  };

  socket.emit("task:create", { columnId, task });

  taskTitleEl.value = "";
  taskDescriptionEl.value = "";
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

