## `server/src/index.ts`

```ts
import express from "express";
import cors from "cors";
import http from "http";
import { WebSocketServer, WebSocket } from "ws";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type ColumnId = "todo" | "inprogress" | "done";

type BoardState = {
  columns: Record<ColumnId, Task[]>;
};

type ClientMessage =
  | { type: "move-task"; taskId: string; from: ColumnId; to: ColumnId; index?: number }
  | { type: "add-task"; columnId: ColumnId; task: Task }
  | { type: "delete-task"; taskId: string; columnId: ColumnId };

type ServerMessage =
  | { type: "board-state"; state: BoardState }
  | { type: "board-updated"; state: BoardState };

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

let boardState: BoardState = {
  columns: {
    todo: [
      { id: "task-1", title: "Design project layout" },
      { id: "task-2", title: "Set up auth flow" }
    ],
    inprogress: [{ id: "task-3", title: "Build drag-and-drop board" }],
    done: [{ id: "task-4", title: "Initialize repo" }]
  }
};

function broadcast(message: ServerMessage) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

function moveTask(taskId: string, from: ColumnId, to: ColumnId, index?: number) {
  const source = boardState.columns[from];
  const target = boardState.columns[to];

  const taskIndex = source.findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return;

  const [task] = source.splice(taskIndex, 1);

  if (typeof index === "number" && index >= 0 && index <= target.length) {
    target.splice(index, 0, task);
  } else {
    target.push(task);
  }
}

function addTask(columnId: ColumnId, task: Task) {
  boardState.columns[columnId].push(task);
}

function deleteTask(taskId: string, columnId: ColumnId) {
  boardState.columns[columnId] = boardState.columns[columnId].filter((t) => t.id !== taskId);
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "board-state", state: boardState } satisfies ServerMessage));

  ws.on("message", (raw) => {
    try {
      const msg = JSON.parse(raw.toString()) as ClientMessage;

      switch (msg.type) {
        case "move-task":
          moveTask(msg.taskId, msg.from, msg.to, msg.index);
          break;
        case "add-task":
          addTask(msg.columnId, msg.task);
          break;
        case "delete-task":
          deleteTask(msg.taskId, msg.columnId);
          break;
      }

      broadcast({ type: "board-updated", state: boardState });
    } catch (err) {
      console.error("Invalid message", err);
    }
  });
});

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

