  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <div className="task-title">{task.title}</div>
      {task.description && <div className="task-desc">{task.description}</div>}
    </div>
  );
}

function Column({
  id,
  title,
  tasks
}: {
  id: ColumnId;
  title: string;
  tasks: Task[];
}) {
  return (
    <div className="column">
      <div className="column-header">
        <h2>{title}</h2>
        <span>{tasks.length}</span>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list" data-column-id={id}>
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState<BoardState>({
    columns: { todo: [], inprogress: [], done: [] }
  });
  const [socket, setSocket] = useState<WebSocket | null>(null);
  const [activeTaskId, setActiveTaskId] = useState<string | null>(null);

  const sensors = useSensors(useSensor(PointerSensor));

  useEffect(() => {
    const ws = new WebSocket(WS_URL);

    ws.onopen = () => console.log("Connected to server");
    ws.onmessage = (event) => {
      const msg = JSON.parse(event.data) as ServerMessage;
      if (msg.type === "board-state" || msg.type === "board-updated") {
        setBoard(msg.state);
      }
    };
    ws.onclose = () => console.log("Disconnected");

    setSocket(ws);
    return () => ws.close();
  }, []);

  const taskIndex = useMemo(() => {
    const map = new Map<string, { columnId: ColumnId; index: number }>();
    (Object.keys(board.columns) as ColumnId[]).forEach((columnId) => {
      board.columns[columnId].forEach((task, index) => {
        map.set(task.id, { columnId, index });
      });
    });
    return map;
  }, [board]);

  function send(message: unknown) {
    if (socket?.readyState === WebSocket.OPEN) {
      socket.send(JSON.stringify(message));
    }
  }

  function handleDragStart(event: DragStartEvent) {
    setActiveTaskId(String(event.active.id));
  }

  function handleDragOver(event: DragOverEvent) {
    const activeId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!overId) return;

    const activeInfo = taskIndex.get(activeId);
    const overInfo = taskIndex.get(overId);

    if (!activeInfo || !overInfo || activeInfo.columnId === overInfo.columnId) return;

    send({
      type: "move-task",
      taskId: activeId,
      from: activeInfo.columnId,
      to: overInfo.columnId,
      index: overInfo.index
    });
  }

  function handleDragEnd(event: DragEndEvent) {
    setActiveTaskId(null);
    const activeId = String(event.active.id);
    const overId = event.over?.id ? String(event.over.id) : null;
    if (!overId || activeId === overId) return;

    const activeInfo = taskIndex.get(activeId);
    const overInfo = taskIndex.get(overId);
    if (!activeInfo || !overInfo) return;

    send({
      type: "move-task",
      taskId: activeId,
      from: activeInfo.columnId,
      to: overInfo.columnId,
      index: overInfo.index
    });
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Board</h1>
        <div className="status">{socket?.readyState === WebSocket.OPEN ? "Live" : "Connecting..."}</div>
      </header>

      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
      >
        <div className="board">
          <Column id="todo" title="To Do" tasks={board.columns.todo} />
          <Column id="inprogress" title="In Progress" tasks={board.columns.inprogress} />
          <Column id="done" title="Done" tasks={board.columns.done} />
        </div>
      </DndContext>

      {activeTaskId && <div className="dragging-indicator">Dragging: {activeTaskId}</div>}
    </div>
  );
}
```

