import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for initial implementation
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "inprogress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Set up project", description: "Initialize app structure" },
    "task-2": { id: "task-2", title: "Design UI", description: "Create board layout" },
    "task-3": { id: "task-3", title: "Implement drag and drop", description: "Enable task movement" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/board", (req, res) => {
  board = req.body;
  io.emit("board:update", board);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("board:update", (updatedBoard) => {
    board = updatedBoard;
    socket.broadcast.emit("board:update", board);
  });

  socket.on("task:add", (task) => {
    const id = `task-${Date.now()}`;
    board.tasks[id] = { id, ...task };
    board.columns[0].taskIds.push(id);
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
