import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:4000");

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");
  const [draggedTaskId, setDraggedTaskId] = useState(null);

  useEffect(() => {
    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const columns = useMemo(() => board?.columns || [], [board]);
  const tasks = useMemo(() => board?.tasks || {}, [board]);

  const handleDragStart = (taskId) => {
    setDraggedTaskId(taskId);
  };

  const handleDrop = (columnId) => {
    if (!board || !draggedTaskId) return;

    const nextBoard = structuredClone(board);

    // Remove task from current column
    for (const column of nextBoard.columns) {
      column.taskIds = column.taskIds.filter((id) => id !== draggedTaskId);
    }

    // Add task to target column
    const targetColumn = nextBoard.columns.find((c) => c.id === columnId);
    if (targetColumn) {
      targetColumn.taskIds.push(draggedTaskId);
    }

    setBoard(nextBoard);
    socket.emit("board:update", nextBoard);
    setDraggedTaskId(null);
  };

  const handleAddTask = (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    socket.emit("task:add", {
      title: newTaskTitle.trim(),
      description: newTaskDescription.trim()
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  if (!board) {
    return <div className="loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="header">
        <h1>Project Manager</h1>
        <form className="new-task-form" onSubmit={handleAddTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Task description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(column.id)}
          >
            <h2>{column.title}</h2>
            <div className="task-list">
              {column.taskIds.map((taskId) => {
                const task = tasks[taskId];
                if (!task) return null;

                return (
                  <article
                    key={task.id}
                    className="task"
                    draggable
                    onDragStart={() => handleDragStart(task.id)}
                  >
                    <h3>{task.title}</h3>
                    <p>{task.description}</p>
                  </article>
                );
              })}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

