import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory state for initial implementation
let boardState = {
  columns: {
    todo: {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    inprogress: {
      id: "inprogress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    done: {
      id: "done",
      title: "Done",
      taskIds: []
    }
  },
  tasks: {
    "task-1": { id: "task-1", title: "Design app layout", description: "Create initial wireframes" },
    "task-2": { id: "task-2", title: "Set up auth", description: "Implement login flow" },
    "task-3": { id: "task-3", title: "Build task board", description: "Kanban board with drag-and-drop" }
  },
  columnOrder: ["todo", "inprogress", "done"]
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body;
  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("board:update", (newState) => {
    boardState = newState;
    socket.broadcast.emit("board:update", boardState);
  });

  socket.on("task:create", (task) => {
    const id = `task-${Date.now()}`;
    const newTask = { id, ...task };

    boardState.tasks[id] = newTask;
    boardState.columns.todo.taskIds.unshift(id);

    io.emit("board:update", boardState);
  });

  socket.on("task:delete", (taskId) => {
    delete boardState.tasks[taskId];
    Object.values(boardState.columns).forEach((col) => {
      col.taskIds = col.taskIds.filter((id) => id !== taskId);
    });

    io.emit("board:update", boardState);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

app.get("/", (req, res) => {
  res.send("Project Manager API running");
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

