### `client/src/App.jsx`
```jsx
import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";
import {
  DndContext,
  closestCorners,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import {
  SortableContext,
  verticalListSortingStrategy,
  useSortable
} from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

const socket = io("http://localhost:4000");

function TaskCard({ task }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } =
    useSortable({ id: task.id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.5 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <h4>{task.title}</h4>
      <p>{task.description}</p>
    </div>
  );
}

function Column({ column, tasks }) {
  return (
    <div className="column">
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{tasks.length}</span>
      </div>

      <SortableContext items={tasks.map((t) => t.id)} strategy={verticalListSortingStrategy}>
        <div className="task-list">
          {tasks.map((task) => (
            <TaskCard key={task.id} task={task} />
          ))}
        </div>
      </SortableContext>
    </div>
  );
}

function moveTask(board, activeId, overId) {
  const newBoard = structuredClone(board);

  let sourceColumnId = null;
  let targetColumnId = null;

  for (const colId of newBoard.columnOrder) {
    if (newBoard.columns[colId].taskIds.includes(activeId)) sourceColumnId = colId;
    if (newBoard.columns[colId].taskIds.includes(overId)) targetColumnId = colId;
  }

  if (!sourceColumnId || !targetColumnId) return board;

  const sourceIds = newBoard.columns[sourceColumnId].taskIds;
  const targetIds = newBoard.columns[targetColumnId].taskIds;

  const sourceIndex = sourceIds.indexOf(activeId);
  sourceIds.splice(sourceIndex, 1);

  const overIndex = targetIds.indexOf(overId);
  if (sourceColumnId === targetColumnId) {
    targetIds.splice(overIndex, 0, activeId);
  } else {
    targetIds.splice(overIndex, 0, activeId);
  }

  return newBoard;
}

export default function App() {
  const [board, setBoard] = useState(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 5 }
    })
  );

  useEffect(() => {
    socket.on("board:update", (state) => {
      setBoard(state);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const columns = useMemo(() => {
    if (!board) return [];
    return board.columnOrder.map((colId) => ({
      ...board.columns[colId],
      tasks: board.columns[colId].taskIds.map((taskId) => board.tasks[taskId]).filter(Boolean)
    }));
  }, [board]);

  const handleDragEnd = ({ active, over }) => {
    if (!over || !board) return;

    const activeId = active.id;
    const overId = over.id;

    if (activeId === overId) return;

    const updated = moveTask(board, activeId, overId);
    setBoard(updated);
    socket.emit("board:update", updated);
  };

  const addTask = () => {
    socket.emit("task:create", {
      title: "New Task",
      description: "Describe the task here"
    });
  };

  const deleteTask = (taskId) => {
    socket.emit("task:delete", taskId);
  };

  if (!board) return <div className="app">Loading board...</div>;

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <button onClick={addTask}>Add Task</button>
      </header>

      <div className="board">
        <DndContext sensors={sensors} collisionDetection={closestCorners} onDragEnd={handleDragEnd}>
          {columns.map((column) => (
            <div key={column.id} className="column-wrap">
              <Column column={column} tasks={column.tasks} />
              <div className="column-actions">
                {column.tasks.map((task) => (
                  <button key={task.id} className="delete-btn" onClick={() => deleteTask(task.id)}>
                    Delete {task.title}
                  </button>
                ))}
              </div>
            </div>
          ))}
        </DndContext>
      </div>
    </div>
  );
}
```

