```js
const express = require("express");
const http = require("http");
const cors = require("cors");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);

app.use(cors());
app.use(express.json());

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory store for initial implementation
let boardState = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "task-1", title: "Design project layout", description: "Create initial wireframe and structure." },
        { id: "task-2", title: "Set up auth", description: "Add login and session handling." }
      ]
    },
    {
      id: "doing",
      title: "In Progress",
      tasks: [
        { id: "task-3", title: "Build drag-and-drop", description: "Implement board interactions." }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: [
        { id: "task-4", title: "Initialize repo", description: "Create project scaffold." }
      ]
    }
  ]
};

app.get("/api/board", (req, res) => {
  res.json(boardState);
});

app.post("/api/board", (req, res) => {
  boardState = req.body;
  io.emit("board:update", boardState);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", boardState);

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = boardState.columns.find((c) => c.id === fromColumnId);
    const toColumn = boardState.columns.find((c) => c.id === toColumnId);
    if (!fromColumn || !toColumn) return;

    const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromColumn.tasks.splice(taskIndex, 1);
    const insertIndex = typeof toIndex === "number" ? toIndex : toColumn.tasks.length;
    toColumn.tasks.splice(insertIndex, 0, task);

    io.emit("board:update", boardState);
  });

  socket.on("task:create", ({ columnId, title, description }) => {
    const column = boardState.columns.find((c) => c.id === columnId);
    if (!column) return;

    const newTask = {
      id: `task-${Date.now()}`,
      title,
      description: description || ""
    };

    column.tasks.unshift(newTask);
    io.emit("board:update", boardState);
  });

  socket.on("task:delete", ({ taskId }) => {
    for (const column of boardState.columns) {
      const idx = column.tasks.findIndex((t) => t.id === taskId);
      if (idx !== -1) {
        column.tasks.splice(idx, 1);
        io.emit("board:update", boardState);
        return;
      }
    }
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
