### `client/app.js`
```js
const socket = io("http://localhost:3001");

const boardEl = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskTitleInput = document.getElementById("taskTitle");
const taskDescriptionInput = document.getElementById("taskDescription");
const taskColumnSelect = document.getElementById("taskColumn");

let boardState = null;
let draggedTask = null;

function renderBoard(state) {
  boardEl.innerHTML = "";

  state.columns.forEach((column) => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.dataset.columnId = column.id;

    const title = document.createElement("h2");
    title.textContent = `${column.title} (${column.tasks.length})`;

    const taskList = document.createElement("div");
    taskList.className = "task-list";
    taskList.dataset.columnId = column.id;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumnId = column.id;
      const toIndex = column.tasks.length;

      socket.emit("task:move", {
        taskId: draggedTask.taskId,
        fromColumnId: draggedTask.fromColumnId,
        toColumnId,
        toIndex
      });

      draggedTask = null;
    });

    column.tasks.forEach((task) => {
      const taskEl = document.createElement("article");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumnId: column.id
        };
      });

      const h3 = document.createElement("h3");
      h3.textContent = task.title;

      const p = document.createElement("p");
      p.textContent = task.description || "";

      const actions = document.createElement("div");
      actions.className = "task-actions";

      const deleteBtn = document.createElement("button");
      deleteBtn.className = "delete-btn";
      deleteBtn.textContent = "Delete";
      deleteBtn.addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id });
      });

      actions.appendChild(deleteBtn);
      taskEl.appendChild(h3);
      taskEl.appendChild(p);
      taskEl.appendChild(actions);
      taskList.appendChild(taskEl);
    });

    columnEl.appendChild(title);
    columnEl.appendChild(taskList);
    boardEl.appendChild(columnEl);
  });
}

socket.on("board:update", (state) => {
  boardState = state;
  renderBoard(state);
});

addTaskBtn.addEventListener("click", () => {
  const title = taskTitleInput.value.trim();
  const description = taskDescriptionInput.value.trim();
  const columnId = taskColumnSelect.value;

  if (!title) return;

  socket.emit("task:create", { columnId, title, description });

  taskTitleInput.value = "";
  taskDescriptionInput.value = "";
});

taskTitleInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});
```

