```ts
import express from "express";
import cors from "cors";
import http from "http";
import { WebSocketServer } from "ws";

type Task = {
  id: string;
  title: string;
  description?: string;
};

type Board = {
  [columnId: string]: Task[];
};

type Message =
  | { type: "board:update"; board: Board }
  | { type: "board:request" };

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);
const wss = new WebSocketServer({ server });

let board: Board = {
  todo: [
    { id: "task-1", title: "Design app layout" },
    { id: "task-2", title: "Set up auth flow" }
  ],
  inProgress: [{ id: "task-3", title: "Implement drag and drop" }],
  done: [{ id: "task-4", title: "Create project scaffold" }]
};

function broadcastBoard() {
  const message: Message = { type: "board:update", board };
  const payload = JSON.stringify(message);

  wss.clients.forEach((client) => {
    if (client.readyState === 1) {
      client.send(payload);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "board:update", board }));

  ws.on("message", (data) => {
    try {
      const message = JSON.parse(data.toString()) as Message;

      if (message.type === "board:update") {
        board = message.board;
        broadcastBoard();
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

app.get("/health", (_req, res) => {
  res.json({ ok: true });
});

const PORT = process.env.PORT || 4000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

