## `client/src/App.tsx`

```tsx
import { useEffect, useMemo, useRef, useState } from "react";
import {
  DndContext,
  DragEndEvent,
  DragOverlay,
  PointerSensor,
  useSensor,
  useSensors
} from "@dnd-kit/core";
import { arrayMove, SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { Board, Task, WsMessage } from "./types";
import { SortableTaskCard } from "./SortableTaskCard";

const initialBoard: Board = {
  todo: [],
  inProgress: [],
  done: []
};

const columns = [
  { id: "todo", title: "To Do" },
  { id: "inProgress", title: "In Progress" },
  { id: "done", title: "Done" }
] as const;

type ColumnId = (typeof columns)[number]["id"];

function findTask(board: Board, taskId: string): { task: Task; columnId: ColumnId; index: number } | null {
  for (const columnId of Object.keys(board) as ColumnId[]) {
    const index = board[columnId].findIndex((t) => t.id === taskId);
    if (index !== -1) return { task: board[columnId][index], columnId, index };
  }
  return null;
}

export default function App() {
  const [board, setBoard] = useState<Board>(initialBoard);
  const [activeTask, setActiveTask] = useState<Task | null>(null);
  const wsRef = useRef<WebSocket | null>(null);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 6 }
    })
  );

  useEffect(() => {
    const ws = new WebSocket("ws://localhost:4000");
    wsRef.current = ws;

    ws.onopen = () => {
      ws.send(JSON.stringify({ type: "board:request" }));
    };

    ws.onmessage = (event) => {
      const message = JSON.parse(event.data) as WsMessage;
      if (message.type === "board:update") {
        setBoard(message.board);
      }
    };

    return () => {
      ws.close();
    };
  }, []);

  const taskIds = useMemo(
    () => ({
      todo: board.todo.map((t) => t.id),
      inProgress: board.inProgress.map((t) => t.id),
      done: board.done.map((t) => t.id)
    }),
    [board]
  );

  function syncBoard(nextBoard: Board) {
    setBoard(nextBoard);
    wsRef.current?.send(JSON.stringify({ type: "board:update", board: nextBoard }));
  }

  function onDragStart(event: any) {
    const id = event.active.id as string;
    const found = findTask(board, id);
    setActiveTask(found?.task ?? null);
  }

  function onDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    setActiveTask(null);

    if (!over) return;

    const activeId = active.id as string;
    const overId = over.id as string;

    const activeLocation = findTask(board, activeId);
    if (!activeLocation) return;

    const nextBoard: Board = {
      todo: [...board.todo],
      inProgress: [...board.inProgress],
      done: [...board.done]
    };

    const sourceColumn = nextBoard[activeLocation.columnId];
    const [movedTask] = sourceColumn.splice(activeLocation.index, 1);

    const overLocation = findTask(board, overId);

    if (!overLocation) {
      nextBoard[overId as ColumnId].push(movedTask);
      syncBoard(nextBoard);
      return;
    }

    if (activeLocation.columnId === overLocation.columnId) {
      const column = nextBoard[activeLocation.columnId];
      const oldIndex = activeLocation.index;
      const newIndex = overLocation.index;
      nextBoard[activeLocation.columnId] = arrayMove(column, oldIndex, newIndex);
    } else {
      nextBoard[overLocation.columnId].splice(overLocation.index, 0, movedTask);
    }

    syncBoard(nextBoard);
  }

  return (
    <div className="app">
      <header className="header">
        <div>
          <h1>Project Manager</h1>
          <p>Drag tasks across boards. Updates sync in real time.</p>
        </div>
        <div className="status">Connected to WebSocket</div>
      </header>

      <DndContext sensors={sensors} onDragStart={onDragStart} onDragEnd={onDragEnd}>
        <div className="board">
          {columns.map((column) => (
            <section className="column" key={column.id}>
              <div className="column-header">
                <h2>{column.title}</h2>
                <span>{board[column.id].length}</span>
              </div>

              <div className="task-list">
                <SortableContext items={taskIds[column.id]} strategy={verticalListSortingStrategy}>
                  {board[column.id].map((task) => (
                    <SortableTaskCard key={task.id} task={task} />
                  ))}
                </SortableContext>
              </div>
            </section>
          ))}
        </div>

        <DragOverlay>
          {activeTask ? <div className="task-card dragging">{activeTask.title}</div> : null}
        </DragOverlay>
      </DndContext>
    </div>
  );
}
```

## `client/src/SortableTaskCard.tsx`

```tsx
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Task } from "./types";

export function SortableTaskCard({ task }: { task: Task }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: task.id
  });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
    opacity: isDragging ? 0.4 : 1
  };

  return (
    <div ref={setNodeRef} style={style} className="task-card" {...attributes} {...listeners}>
      <div className="task-title">{task.title}</div>
      {task.description ? <div className="task-desc">{task.description}</div> : null}
    </div>
  );
}
```

