import express from "express";
import cors from "cors";
import http from "http";
import { Server } from "socket.io";

const app = express();
app.use(cors());
app.use(express.json());

const server = http.createServer(app);

const io = new Server(server, {
  cors: {
    origin: "*",
    methods: ["GET", "POST"]
  }
});

// In-memory board state for initial implementation
let board = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      taskIds: ["task-1", "task-2"]
    },
    {
      id: "in-progress",
      title: "In Progress",
      taskIds: ["task-3"]
    },
    {
      id: "done",
      title: "Done",
      taskIds: []
    }
  ],
  tasks: {
    "task-1": { id: "task-1", title: "Set up project", description: "Initialize repo and tooling" },
    "task-2": { id: "task-2", title: "Design UI", description: "Create board layout" },
    "task-3": { id: "task-3", title: "Implement drag and drop", description: "Enable task movement" }
  }
};

app.get("/api/board", (req, res) => {
  res.json(board);
});

app.post("/api/board/reset", (req, res) => {
  board = {
    columns: [
      { id: "todo", title: "To Do", taskIds: ["task-1", "task-2"] },
      { id: "in-progress", title: "In Progress", taskIds: ["task-3"] },
      { id: "done", title: "Done", taskIds: [] }
    ],
    tasks: {
      "task-1": { id: "task-1", title: "Set up project", description: "Initialize repo and tooling" },
      "task-2": { id: "task-2", title: "Design UI", description: "Create board layout" },
      "task-3": { id: "task-3", title: "Implement drag and drop", description: "Enable task movement" }
    }
  };

  io.emit("board:update", board);
  res.json({ ok: true });
});

io.on("connection", (socket) => {
  console.log("Client connected:", socket.id);

  socket.emit("board:update", board);

  socket.on("task:move", ({ taskId, sourceColumnId, destinationColumnId, destinationIndex }) => {
    const sourceColumn = board.columns.find((c) => c.id === sourceColumnId);
    const destinationColumn = board.columns.find((c) => c.id === destinationColumnId);

    if (!sourceColumn || !destinationColumn) return;
    if (!board.tasks[taskId]) return;

    // Remove from source
    sourceColumn.taskIds = sourceColumn.taskIds.filter((id) => id !== taskId);

    // Insert into destination
    const insertIndex = Math.max(0, Math.min(destinationIndex, destinationColumn.taskIds.length));
    destinationColumn.taskIds.splice(insertIndex, 0, taskId);

    io.emit("board:update", board);
  });

  socket.on("task:create", ({ title, description, columnId }) => {
    const id = `task-${Date.now()}`;
    board.tasks[id] = { id, title, description: description || "" };

    const column = board.columns.find((c) => c.id === columnId);
    if (column) {
      column.taskIds.unshift(id);
      io.emit("board:update", board);
    }
  });

  socket.on("task:delete", ({ taskId }) => {
    delete board.tasks[taskId];
    board.columns.forEach((col) => {
      col.taskIds = col.taskIds.filter((id) => id !== taskId);
    });
    io.emit("board:update", board);
  });

  socket.on("disconnect", () => {
    console.log("Client disconnected:", socket.id);
  });
});

const PORT = process.env.PORT || 3001;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
