import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const SOCKET_URL = "http://localhost:3001";

export default function App() {
  const socket = useMemo(() => io(SOCKET_URL), []);
  const [board, setBoard] = useState(null);
  const [draggingTaskId, setDraggingTaskId] = useState(null);

  useEffect(() => {
    socket.on("board:update", (newBoard) => {
      setBoard(newBoard);
    });

    return () => {
      socket.disconnect();
    };
  }, [socket]);

  const handleDragStart = (taskId) => {
    setDraggingTaskId(taskId);
  };

  const handleDrop = (destinationColumnId, destinationIndex) => {
    if (!draggingTaskId || !board) return;

    let sourceColumnId = null;
    for (const column of board.columns) {
      if (column.taskIds.includes(draggingTaskId)) {
        sourceColumnId = column.id;
        break;
      }
    }

    if (!sourceColumnId) return;

    socket.emit("task:move", {
      taskId: draggingTaskId,
      sourceColumnId,
      destinationColumnId,
      destinationIndex
    });

    setDraggingTaskId(null);
  };

  const handleCreateTask = (columnId) => {
    const title = prompt("Task title?");
    if (!title) return;

    const description = prompt("Task description?") || "";
    socket.emit("task:create", { title, description, columnId });
  };

  const handleDeleteTask = (taskId) => {
    socket.emit("task:delete", { taskId });
  };

  if (!board) {
    return <div className="app loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <p>Drag tasks between columns. Updates sync in real time.</p>
      </header>

      <main className="board">
        {board.columns.map((column) => (
          <section
            key={column.id}
            className="column"
            onDragOver={(e) => e.preventDefault()}
            onDrop={() => handleDrop(column.id, column.taskIds.length)}
          >
            <div className="column-header">
              <h2>{column.title}</h2>
              <button onClick={() => handleCreateTask(column.id)}>+ Task</button>
            </div>

            <div className="task-list">
              {column.taskIds.map((taskId, index) => {
                const task = board.tasks[taskId];
                if (!task) return null;

                return (
                  <div
                    key={task.id}
                    className="task-card"
                    draggable
                    onDragStart={() => handleDragStart(task.id)}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={(e) => {
                      e.preventDefault();
                      handleDrop(column.id, index);
                    }}
                  >
                    <div className="task-card-top">
                      <strong>{task.title}</strong>
                      <button
                        className="delete-btn"
                        onClick={() => handleDeleteTask(task.id)}
                        title="Delete task"
                      >
                        ×
                      </button>
                    </div>
                    {task.description && <p>{task.description}</p>}
                  </div>
                );
              })}
            </div>
          </section>
        ))}
      </main>
    </div>
  );
}
```

