import React, { useEffect, useMemo, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:4000");

function TaskCard({ task, onDragStart }) {
  return (
    <div
      className="task-card"
      draggable
      onDragStart={(e) => onDragStart(e, task.id)}
    >
      <h4>{task.title}</h4>
      {task.description && <p>{task.description}</p>}
    </div>
  );
}

function Column({ column, tasks, onDrop, onDragOver, onDragStart }) {
  return (
    <div
      className="column"
      onDrop={(e) => onDrop(e, column.id)}
      onDragOver={onDragOver}
    >
      <div className="column-header">
        <h3>{column.title}</h3>
        <span>{tasks.length}</span>
      </div>
      <div className="column-body">
        {tasks.map((task) => (
          <TaskCard key={task.id} task={task} onDragStart={onDragStart} />
        ))}
      </div>
    </div>
  );
}

export default function App() {
  const [board, setBoard] = useState(null);
  const [newTaskTitle, setNewTaskTitle] = useState("");
  const [newTaskDescription, setNewTaskDescription] = useState("");

  useEffect(() => {
    socket.on("board:update", (updatedBoard) => {
      setBoard(updatedBoard);
    });

    return () => {
      socket.off("board:update");
    };
  }, []);

  const tasksByColumn = useMemo(() => {
    if (!board) return {};
    const result = {};
    board.columns.forEach((column) => {
      result[column.id] = column.taskIds.map((id) => board.tasks[id]).filter(Boolean);
    });
    return result;
  }, [board]);

  const handleDragStart = (e, taskId) => {
    e.dataTransfer.setData("taskId", taskId);
  };

  const handleDrop = (e, destinationColumnId) => {
    e.preventDefault();
    if (!board) return;

    const taskId = e.dataTransfer.getData("taskId");
    if (!taskId) return;

    const sourceColumn = board.columns.find((column) =>
      column.taskIds.includes(taskId)
    );

    if (!sourceColumn) return;

    socket.emit("task:move", {
      taskId,
      sourceColumnId: sourceColumn.id,
      destinationColumnId,
      destinationIndex: board.columns.find((c) => c.id === destinationColumnId).taskIds.length
    });
  };

  const handleDragOver = (e) => {
    e.preventDefault();
  };

  const handleCreateTask = (e) => {
    e.preventDefault();
    if (!newTaskTitle.trim()) return;

    socket.emit("task:create", {
      title: newTaskTitle.trim(),
      description: newTaskDescription.trim(),
      columnId: "todo"
    });

    setNewTaskTitle("");
    setNewTaskDescription("");
  };

  if (!board) {
    return <div className="app loading">Loading board...</div>;
  }

  return (
    <div className="app">
      <header className="topbar">
        <h1>Project Manager</h1>
        <form className="task-form" onSubmit={handleCreateTask}>
          <input
            type="text"
            placeholder="Task title"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
          />
          <input
            type="text"
            placeholder="Description"
            value={newTaskDescription}
            onChange={(e) => setNewTaskDescription(e.target.value)}
          />
          <button type="submit">Add Task</button>
        </form>
      </header>

      <main className="board">
        {board.columns.map((column) => (
          <Column
            key={column.id}
            column={column}
            tasks={tasksByColumn[column.id] || []}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragStart={handleDragStart}
          />
        ))}
      </main>
    </div>
  );
}
