    ],
    done: []
  }
};

io.on("connection", (socket) => {
  socket.emit("state", state);

  socket.on("addTask", (task) => {
    const newTask = {
      id: String(Date.now()),
      title: task.title || "Untitled Task",
      description: task.description || ""
    };
    state.columns[task.column].push(newTask);
    io.emit("state", state);
  });

  socket.on("moveTask", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const fromList = state.columns[fromColumn];
    const toList = state.columns[toColumn];

    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    toList.splice(toIndex, 0, task);

    io.emit("state", state);
  });

  socket.on("deleteTask", ({ taskId, column }) => {
    state.columns[column] = state.columns[column].filter((t) => t.id !== taskId);
    io.emit("state", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
