## 6) `public/app.js`

```js
const socket = io();

let currentState = null;
let draggedTask = null;

const taskForm = document.getElementById("taskForm");
const titleInput = document.getElementById("title");
const descriptionInput = document.getElementById("description");
const columnSelect = document.getElementById("column");

const columns = ["todo", "doing", "done"];

socket.on("state", (state) => {
  currentState = state;
  renderBoard();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  socket.emit("addTask", {
    title: titleInput.value,
    description: descriptionInput.value,
    column: columnSelect.value
  });

  titleInput.value = "";
  descriptionInput.value = "";
});

function renderBoard() {
  columns.forEach((column) => {
    const list = document.getElementById(column);
    list.innerHTML = "";

    currentState.columns[column].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;
      taskEl.dataset.column = column;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="actions">
          <button class="delete">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: column,
          fromIndex: index
        };
      });

      taskEl.querySelector(".delete").addEventListener("click", () => {
        socket.emit("deleteTask", { taskId: task.id, column });
      });

      list.appendChild(taskEl);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumn = column;
      const toIndex = currentState.columns[toColumn].length;

      socket.emit("moveTask", {
        taskId: draggedTask.taskId,
        fromColumn: draggedTask.fromColumn,
        toColumn,
        toIndex
      });

      draggedTask = null;
    });
  });
}

function escapeHtml(str) {
  return String(str)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
