const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Set up project" },
      { id: "t2", title: "Design UI" }
    ],
    doing: [
      { id: "t3", title: "Build drag-and-drop" }
    ],
    done: []
  }
};

io.on("connection", (socket) => {
  socket.emit("state:init", state);

  socket.on("task:add", (task) => {
    state.columns[task.columnId].push(task);
    io.emit("state:update", state);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromCol = state.columns[fromColumnId];
    const toCol = state.columns[toColumnId];

    const taskIndex = fromCol.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromCol.splice(taskIndex, 1);
    toCol.splice(toIndex, 0, task);

    io.emit("state:update", state);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    state.columns[columnId] = state.columns[columnId].filter((t) => t.id !== taskId);
    io.emit("state:update", state);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
