```js
const socket = io();

let state = null;
let draggedTask = null;

const board = document.getElementById("board");
const taskInput = document.getElementById("taskInput");
const columnSelect = document.getElementById("columnSelect");
const addTaskBtn = document.getElementById("addTaskBtn");

function render() {
  if (!state) return;

  ["todo", "doing", "done"].forEach((columnId) => {
    const container = document.getElementById(columnId);
    container.innerHTML = "";

    state.columns[columnId].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;

      taskEl.innerHTML = `
        <span>${task.title}</span>
        <button data-delete="${task.id}">×</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = { ...task, columnId };
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
        draggedTask = null;
      });

      taskEl.querySelector("button").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId });
      });

      container.appendChild(taskEl);
    });
  });
}

addTaskBtn.addEventListener("click", () => {
  const title = taskInput.value.trim();
  const columnId = columnSelect.value;

  if (!title) return;

  socket.emit("task:add", {
    id: `task-${Date.now()}`,
    title,
    columnId
  });

  taskInput.value = "";
});

document.querySelectorAll(".column").forEach((column) => {
  column.addEventListener("dragover", (e) => {
    e.preventDefault();
    column.classList.add("drag-over");
  });

  column.addEventListener("dragleave", () => {
    column.classList.remove("drag-over");
  });

  column.addEventListener("drop", (e) => {
    e.preventDefault();
    column.classList.remove("drag-over");

    if (!draggedTask) return;

    const toColumnId = column.dataset.column;
    const toList = state.columns[toColumnId];
    const toIndex = toList.length;

    socket.emit("task:move", {
      taskId: draggedTask.id,
      fromColumnId: draggedTask.columnId,
      toColumnId,
      toIndex
    });
  });
});

socket.on("state:init", (serverState) => {
  state = serverState;
  render();
});

socket.on("state:update", (serverState) => {
  state = serverState;
  render();
});
