## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let board = {
  todo: [
    { id: "1", title: "Design UI" },
    { id: "2", title: "Set up backend" }
  ],
  doing: [
    { id: "3", title: "Build drag-and-drop" }
  ],
  done: [
    { id: "4", title: "Create project repo" }
  ]
};

function findTask(taskId) {
  for (const column of Object.keys(board)) {
    const task = board[column].find(t => t.id === taskId);
    if (task) return { column, task };
  }
  return null;
}

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:add", (title) => {
    const task = {
      id: String(Date.now()) + Math.random().toString(36).slice(2),
      title: title.trim()
    };
    if (!task.title) return;
    board.todo.push(task);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, toColumn, toIndex }) => {
    const found = findTask(taskId);
    if (!found || !board[toColumn]) return;

    const { column: fromColumn, task } = found;
    board[fromColumn] = board[fromColumn].filter(t => t.id !== taskId);

    const insertIndex = Math.max(0, Math.min(toIndex, board[toColumn].length));
    board[toColumn].splice(insertIndex, 0, task);

    io.emit("board:update", board);
  });

  socket.on("task:delete", (taskId) => {
    for (const column of Object.keys(board)) {
      board[column] = board[column].filter(t => t.id !== taskId);
    }
    io.emit("board:update", board);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

