const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let board = {
  todo: [
    { id: "1", title: "Set up project" },
    { id: "2", title: "Design UI" }
  ],
  doing: [
    { id: "3", title: "Build drag and drop" }
  ],
  done: [
    { id: "4", title: "Create repo" }
  ]
};

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("board:move", ({ taskId, from, to, toIndex }) => {
    const fromList = board[from];
    const toList = board[to];
    if (!fromList || !toList) return;

    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    toList.splice(toIndex, 0, task);

    io.emit("board:update", board);
  });

  socket.on("task:add", ({ title }) => {
    const newTask = {
      id: Date.now().toString(),
      title: title.trim()
    };
    if (!newTask.title) return;

    board.todo.unshift(newTask);
    io.emit("board:update", board);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
