## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  tasks: [
    { id: "1", title: "Design homepage", status: "todo" },
    { id: "2", title: "Set up auth", status: "todo" },
    { id: "3", title: "Build API", status: "doing" },
    { id: "4", title: "Deploy app", status: "done" }
  ]
};

function broadcast() {
  const message = JSON.stringify({ type: "state", payload: state });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", payload: state }));

  ws.on("message", (data) => {
    try {
      const msg = JSON.parse(data.toString());

      if (msg.type === "add-task") {
        const newTask = {
          id: String(Date.now()),
          title: msg.payload.title,
          status: "todo"
        };
        state.tasks.push(newTask);
        broadcast();
      }

      if (msg.type === "move-task") {
        const { id, status } = msg.payload;
        const task = state.tasks.find((t) => t.id === id);
        if (task) {
          task.status = status;
          broadcast();
        }
      }

      if (msg.type === "delete-task") {
        const { id } = msg.payload;
        state.tasks = state.tasks.filter((t) => t.id !== id);
        broadcast();
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

