```js
const statusEl = document.getElementById("status");
const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");

const columns = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

let currentState = { tasks: [] };
let draggedTaskId = null;

const wsProtocol = location.protocol === "https:" ? "wss" : "ws";
const ws = new WebSocket(`${wsProtocol}://${location.host}`);

ws.addEventListener("open", () => {
  statusEl.textContent = "Connected";
});

ws.addEventListener("close", () => {
  statusEl.textContent = "Disconnected";
});

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.type === "state") {
    currentState = msg.payload;
    render();
  }
});

function sendMessage(type, payload) {
  ws.send(JSON.stringify({ type, payload }));
}

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;

  sendMessage("add-task", { title });
  taskInput.value = "";
});

function render() {
  Object.values(columns).forEach((col) => (col.innerHTML = ""));

  currentState.tasks.forEach((task) => {
    const el = document.createElement("div");
    el.className = "task";
    el.draggable = true;
    el.dataset.id = task.id;

    el.innerHTML = `
      <span>${escapeHtml(task.title)}</span>
      <button data-delete="${task.id}">Delete</button>
    `;

    el.addEventListener("dragstart", () => {
      draggedTaskId = task.id;
    });

    el.querySelector("button").addEventListener("click", () => {
      sendMessage("delete-task", { id: task.id });
    });

    columns[task.status].appendChild(el);
  });
}

Object.entries(columns).forEach(([status, col]) => {
  col.addEventListener("dragover", (e) => {
    e.preventDefault();
    col.parentElement.classList.add("drag-over");
  });

  col.addEventListener("dragleave", () => {
    col.parentElement.classList.remove("drag-over");
  });

  col.addEventListener("drop", (e) => {
    e.preventDefault();
    col.parentElement.classList.remove("drag-over");

    if (draggedTaskId) {
      sendMessage("move-task", { id: draggedTaskId, status });
      draggedTaskId = null;
    }
  });
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
