```js
const socket = io();
const board = document.getElementById("board");

let state = null;
let draggedTask = null;

const columnsMeta = [
  { id: "todo", title: "To Do" },
  { id: "doing", title: "Doing" },
  { id: "done", title: "Done" }
];

socket.on("state", (newState) => {
  state = newState;
  renderBoard();
});

function renderBoard() {
  board.innerHTML = "";

  columnsMeta.forEach((col) => {
    const columnEl = document.createElement("section");
    columnEl.className = "column";
    columnEl.innerHTML = `
      <h2>${col.title}</h2>
      <div class="task-list" data-column="${col.id}"></div>
      <form class="add-form" data-column="${col.id}">
        <input type="text" placeholder="New task..." />
        <button class="add-btn" type="submit">Add</button>
      </form>
    `;

    const taskList = columnEl.querySelector(".task-list");
    const tasks = state.columns[col.id] || [];

    tasks.forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.column = col.id;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <div>${task.title}</div>
        <div class="task-actions">
          <small>#${task.id}</small>
          <button class="delete-btn" data-delete="${task.id}">Delete</button>
        </div>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: col.id
        };
      });

      taskList.appendChild(taskEl);
    });

    columnEl.querySelector(".add-form").addEventListener("submit", (e) => {
      e.preventDefault();
      const input = e.target.querySelector("input");
      const title = input.value;
      socket.emit("add-task", { columnId: col.id, title });
      input.value = "";
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumn = col.id;
      const toIndex = state.columns[toColumn].length;

      socket.emit("move-task", {
        taskId: draggedTask.taskId,
        fromColumn: draggedTask.fromColumn,
        toColumn,
        toIndex
      });

      draggedTask = null;
    });

    columnEl.addEventListener("click", (e) => {
      const deleteId = e.target.getAttribute("data-delete");
      if (deleteId) {
        socket.emit("delete-task", { columnId: col.id, taskId: deleteId });
      }
    });

    board.appendChild(columnEl);
  });
}
