const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Set up project" },
      { id: "t2", title: "Design UI" }
    ],
    doing: [
      { id: "t3", title: "Build backend" }
    ],
    done: [
      { id: "t4", title: "Create repo" }
    ]
  }
};

io.on("connection", (socket) => {
  socket.emit("state", state);

  socket.on("move-task", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const fromTasks = state.columns[fromColumn];
    const toTasks = state.columns[toColumn];

    const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromTasks.splice(taskIndex, 1);
    toTasks.splice(toIndex, 0, task);

    io.emit("state", state);
  });

  socket.on("add-task", ({ columnId, title }) => {
    const newTask = {
      id: `t${Date.now()}`,
      title: title.trim()
    };

    if (!newTask.title) return;

    state.columns[columnId].push(newTask);
    io.emit("state", state);
  });

  socket.on("delete-task", ({ taskId, columnId }) => {
    state.columns[columnId] = state.columns[columnId].filter((t) => t.id !== taskId);
    io.emit("state", state);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

