## 6) `public/app.js`

```js
const socket = io();

let state = {
  columns: {
    todo: [],
    doing: [],
    done: []
  }
};

socket.on("state", (newState) => {
  state = newState;
  render();
});

function render() {
  ["todo", "doing", "done"].forEach((columnId) => {
    const list = document.getElementById(columnId);
    list.innerHTML = "";

    state.columns[columnId].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <span>${escapeHtml(task.title)}</span>
        <button class="delete-btn" title="Delete">×</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      taskEl.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("delete-task", { taskId: task.id, columnId });
      });

      list.appendChild(taskEl);
    });
  });
}

document.querySelectorAll(".add-task-form").forEach((form) => {
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const input = form.querySelector("input");
    const title = input.value;
    const columnId = form.dataset.column;

    socket.emit("add-task", { columnId, title });
    input.value = "";
  });
});

document.querySelectorAll(".task-list").forEach((list) => {
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();

    const dragging = document.querySelector(".task.dragging");
    if (!dragging) return;

    const taskId = dragging.dataset.taskId;
    const fromColumn = dragging.dataset.columnId;
    const toColumn = list.id;

    const tasksInTarget = [...list.querySelectorAll(".task")];
    const toIndex = tasksInTarget.length;

    socket.emit("move-task", {
      taskId,
      fromColumn,
      toColumn,
      toIndex
    });
  });
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
