      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: column,
          fromIndex: index
        };
      });

      taskEl.querySelector("button").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, column });
      });

      boardEls[column].appendChild(taskEl);
    });
  });
}

socket.on("board:init", renderBoard);
socket.on("board:update", renderBoard);

addTaskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskTitle.value.trim();
  const column = taskColumn.value;

  if (!title) return;

  socket.emit("task:add", { title, column });
  taskTitle.value = "";
});

