```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  boards: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", text: "Set up project", boardId: "todo" },
        { id: "t2", text: "Design UI", boardId: "todo" }
      ]
    },
    {
      id: "doing",
      title: "Doing",
      tasks: [
        { id: "t3", text: "Build drag-and-drop", boardId: "doing" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

function findTask(taskId) {
  for (const board of state.boards) {
    const task = board.tasks.find(t => t.id === taskId);
    if (task) return { task, board };
  }
  return null;
}

io.on("connection", (socket) => {
  socket.emit("state", state);

  socket.on("addTask", ({ boardId, text }) => {
    const board = state.boards.find(b => b.id === boardId);
    if (!board || !text.trim()) return;

    const task = {
      id: `task_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      text: text.trim(),
      boardId
    };

    board.tasks.push(task);
    io.emit("state", state);
  });

  socket.on("moveTask", ({ taskId, toBoardId, toIndex }) => {
    const found = findTask(taskId);
    const targetBoard = state.boards.find(b => b.id === toBoardId);
    if (!found || !targetBoard) return;

    const { task, board: fromBoard } = found;
    fromBoard.tasks = fromBoard.tasks.filter(t => t.id !== taskId);

    task.boardId = toBoardId;

    if (typeof toIndex !== "number" || toIndex < 0 || toIndex > targetBoard.tasks.length) {
      targetBoard.tasks.push(task);
    } else {
      targetBoard.tasks.splice(toIndex, 0, task);
    }

    io.emit("state", state);
  });

  socket.on("deleteTask", ({ taskId }) => {
    for (const board of state.boards) {
      const before = board.tasks.length;
      board.tasks = board.tasks.filter(t => t.id !== taskId);
      if (board.tasks.length !== before) break;
    }
    io.emit("state", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

