## 6) `public/app.js`

```js
const socket = io();

let state = null;
let draggedTaskId = null;

const boardsEl = document.getElementById("boards");
const boardSelect = document.getElementById("boardSelect");
const taskInput = document.getElementById("taskInput");
const addTaskBtn = document.getElementById("addTaskBtn");

socket.on("state", (newState) => {
  state = newState;
  render();
});

function render() {
  if (!state) return;

  boardSelect.innerHTML = state.boards
    .map(board => `<option value="${board.id}">${board.title}</option>`)
    .join("");

  boardsEl.innerHTML = state.boards.map(board => `
    <section class="board">
      <h2>${board.title}</h2>
      <div class="task-list" data-board-id="${board.id}">
        ${board.tasks.map(task => `
          <div class="task" draggable="true" data-task-id="${task.id}">
            <span>${escapeHtml(task.text)}</span>
            <button data-delete-id="${task.id}">×</button>
          </div>
        `).join("")}
      </div>
    </section>
  `).join("");

  attachTaskEvents();
  attachBoardDropEvents();
}

function attachTaskEvents() {
  document.querySelectorAll(".task").forEach(taskEl => {
    taskEl.addEventListener("dragstart", () => {
      draggedTaskId = taskEl.dataset.taskId;
    });

    taskEl.querySelector("button").addEventListener("click", (e) => {
      e.stopPropagation();
      socket.emit("deleteTask", { taskId: taskEl.dataset.taskId });
    });
  });
}

function attachBoardDropEvents() {
  document.querySelectorAll(".task-list").forEach(list => {
    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      if (!draggedTaskId) return;

      const toBoardId = list.dataset.boardId;
      const tasks = Array.from(list.querySelectorAll(".task"));
      const toIndex = tasks.findIndex(t => t.dataset.taskId === draggedTaskId);

      socket.emit("moveTask", {
        taskId: draggedTaskId,
        toBoardId,
        toIndex: toIndex === -1 ? undefined : toIndex
      });

      draggedTaskId = null;
    });
  });
}

addTaskBtn.addEventListener("click", () => {
  const text = taskInput.value.trim();
  const boardId = boardSelect.value;
  if (!text) return;

  socket.emit("addTask", { boardId, text });
  taskInput.value = "";
});

taskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
