## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Set up project" },
      { id: "t2", title: "Design UI" }
    ],
    doing: [
      { id: "t3", title: "Build drag-and-drop" }
    ],
    done: []
  }
};

io.on("connection", (socket) => {
  socket.emit("state", state);

  socket.on("addTask", ({ columnId, title }) => {
    const task = {
      id: `t_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      title
    };
    state.columns[columnId].push(task);
    io.emit("state", state);
  });

  socket.on("moveTask", ({ taskId, fromColumn, toColumn, toIndex }) => {
    const fromList = state.columns[fromColumn];
    const toList = state.columns[toColumn];

    const idx = fromList.findIndex((t) => t.id === taskId);
    if (idx === -1) return;

    const [task] = fromList.splice(idx, 1);
    toList.splice(toIndex, 0, task);

    io.emit("state", state);
  });

  socket.on("deleteTask", ({ taskId, columnId }) => {
    state.columns[columnId] = state.columns[columnId].filter((t) => t.id !== taskId);
    io.emit("state", state);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

