## 6) `public/app.js`

```js
const socket = io();

let state = null;
let draggedTask = null;

const board = document.getElementById("board");
const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");
const columnSelect = document.getElementById("columnSelect");

socket.on("state", (newState) => {
  state = newState;
  render();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  const columnId = columnSelect.value;
  if (!title) return;

  socket.emit("addTask", { columnId, title });
  taskInput.value = "";
});

function render() {
  document.querySelectorAll(".task-list").forEach((list) => (list.innerHTML = ""));

  Object.entries(state.columns).forEach(([columnId, tasks]) => {
    const list = document.querySelector(`.column[data-column="${columnId}"] .task-list`);

    tasks.forEach((task, index) => {
      const el = document.createElement("div");
      el.className = "task";
      el.draggable = true;
      el.dataset.taskId = task.id;
      el.dataset.columnId = columnId;
      el.dataset.index = index;

      el.innerHTML = `
        <span>${task.title}</span>
        <button class="delete-btn" title="Delete">×</button>
      `;

      el.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumn: columnId
        };
        el.classList.add("dragging");
      });

      el.addEventListener("dragend", () => {
        el.classList.remove("dragging");
        draggedTask = null;
      });

      el.querySelector(".delete-btn").addEventListener("click", () => {
        socket.emit("deleteTask", { taskId: task.id, columnId });
      });

      list.appendChild(el);
    });
  });
}

document.querySelectorAll(".task-list").forEach((list) => {
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    if (!draggedTask) return;

    const toColumn = list.closest(".column").dataset.column;
    const tasks = Array.from(list.querySelectorAll(".task"));
    const afterElement = getDragAfterElement(list, e.clientY);
    const toIndex = afterElement
      ? tasks.indexOf(afterElement)
      : tasks.length;

    socket.emit("moveTask", {
      taskId: draggedTask.taskId,
      fromColumn: draggedTask.fromColumn,
      toColumn,
      toIndex
    });
  });
});

function getDragAfterElement(container, y) {
  const draggableElements = [...container.querySelectorAll(".task:not(.dragging)")];

  return draggableElements.reduce(
    (closest, child) => {
      const box = child.getBoundingClientRect();
      const offset = y - box.top - box.height / 2;
      if (offset < 0 && offset > closest.offset) {
        return { offset, element: child };
      } else {
        return closest;
      }
    },
    { offset: Number.NEGATIVE_INFINITY }
  ).element;
}
