const socket = io();

let state = {
  boards: {
    todo: [],
    doing: [],
    done: []
  }
};

const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");

const boardEls = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

let draggedTaskId = null;
let draggedFrom = null;

socket.on("state:init", (serverState) => {
  state = serverState;
  render();
});

socket.on("state:update", (serverState) => {
  state = serverState;
  render();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;

  socket.emit("task:add", { title });
  taskInput.value = "";
});

function render() {
  Object.keys(boardEls).forEach((boardName) => {
    const el = boardEls[boardName];
    el.innerHTML = "";

    state.boards[boardName].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.board = boardName;
      taskEl.dataset.index = index;
      taskEl.textContent = task.title;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        draggedFrom = boardName;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        taskEl.classList.remove("dragging");
      });

      el.appendChild(taskEl);
    });
  });

  setupDropZones();
}

function setupDropZones() {
  document.querySelectorAll(".column").forEach((column) => {
    column.addEventListener("dragover", (e) => {
      e.preventDefault();
      column.classList.add("drag-over");
    });

    column.addEventListener("dragleave", () => {
      column.classList.remove("drag-over");
    });

    column.addEventListener("drop", (e) => {
      e.preventDefault();
      column.classList.remove("drag-over");

      if (!draggedTaskId || !draggedFrom) return;

      const toBoard = column.dataset.board;
      const toList = state.boards[toBoard];

      socket.emit("task:move", {
        taskId: draggedTaskId,
        from: draggedFrom,
        to: toBoard,
        index: toList.length
      });

      draggedTaskId = null;
      draggedFrom = null;
    });
  });
}
