## 6) `public/app.js`

```js
const socket = io();

const board = document.getElementById("board");
const addTaskBtn = document.getElementById("addTaskBtn");
const taskDialog = document.getElementById("taskDialog");
const taskForm = document.getElementById("taskForm");
const taskTitle = document.getElementById("taskTitle");
const taskDescription = document.getElementById("taskDescription");
const cancelBtn = document.getElementById("cancelBtn");

let state = null;
let draggedTaskId = null;

function renderBoard() {
  ["todo", "doing", "done"].forEach((columnId) => {
    const list = document.getElementById(columnId);
    list.innerHTML = "";

    state.columns[columnId].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.id = task.id;

      taskEl.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTaskId = task.id;
        taskEl.classList.add("dragging");
      });

      taskEl.addEventListener("dragend", () => {
        draggedTaskId = null;
        taskEl.classList.remove("dragging");
      });

      list.appendChild(taskEl);
    });
  });
}

function findTaskById(id) {
  for (const columnId of Object.keys(state.columns)) {
    const index = state.columns[columnId].findIndex((t) => t.id === id);
    if (index !== -1) {
      return { columnId, index, task: state.columns[columnId][index] };
    }
  }
  return null;
}

function moveTask(taskId, targetColumnId) {
  const found = findTaskById(taskId);
  if (!found || found.columnId === targetColumnId) return;

  state.columns[found.columnId].splice(found.index, 1);
  state.columns[targetColumnId].push(found.task);

  socket.emit("updateState", state);
}

board.querySelectorAll(".task-list").forEach((list) => {
  list.addEventListener("dragover", (e) => {
    e.preventDefault();
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    const targetColumnId = list.id;
    if (draggedTaskId) {
      moveTask(draggedTaskId, targetColumnId);
    }
  });
});

addTaskBtn.addEventListener("click", () => {
  taskForm.reset();
  taskDialog.showModal();
});

cancelBtn.addEventListener("click", () => {
  taskDialog.close();
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();

  const newTask = {
    id: crypto.randomUUID(),
    title: taskTitle.value.trim(),
    description: taskDescription.value.trim()
  };

  state.columns.todo.push(newTask);
  socket.emit("updateState", state);
  taskDialog.close();
});

socket.on("state", (serverState) => {
  state = serverState;
  renderBoard();
});

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

