const socket = io();

const boardEl = document.getElementById("board");
const taskForm = document.getElementById("taskForm");
const taskInput = document.getElementById("taskInput");

let currentBoard = {};

function renderBoard(board) {
  currentBoard = board;

  ["todo", "doing", "done"].forEach((column) => {
    const list = document.getElementById(column);
    list.innerHTML = "";

    board[column].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.textContent = task.title;
      taskEl.dataset.id = task.id;
      taskEl.dataset.column = column;
      taskEl.dataset.index = index;

      taskEl.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData(
          "text/plain",
          JSON.stringify({
            taskId: task.id,
            fromColumn: column
          })
        );
      });

      list.appendChild(taskEl);
    });
  });
}

socket.on("board:update", (board) => {
  renderBoard(board);
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskInput.value.trim();
  if (!title) return;

  socket.emit("task:add", { title });
  taskInput.value = "";
});

document.querySelectorAll(".column").forEach((columnEl) => {
  columnEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    columnEl.classList.add("drag-over");
  });

  columnEl.addEventListener("dragleave", () => {
    columnEl.classList.remove("drag-over");
  });

  columnEl.addEventListener("drop", (e) => {
    e.preventDefault();
    columnEl.classList.remove("drag-over");

    const data = JSON.parse(e.dataTransfer.getData("text/plain"));
    const toColumn = columnEl.dataset.column;

    if (!data || !toColumn) return;
    if (data.fromColumn === toColumn) return;

    socket.emit("task:move", {
      taskId: data.taskId,
      fromColumn: data.fromColumn,
      toColumn,
      toIndex: currentBoard[toColumn].length
    });
  });
});
