## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: {
    todo: [
      { id: "1", title: "Set up project", description: "Initialize app structure" },
      { id: "2", title: "Design UI", description: "Create basic board layout" }
    ],
    doing: [
      { id: "3", title: "Implement drag-and-drop", description: "Move cards between columns" }
    ],
    done: []
  }
};

function broadcast() {
  const payload = JSON.stringify({ type: "state", state });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) client.send(payload);
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", state }));

  ws.on("message", (message) => {
    try {
      const data = JSON.parse(message.toString());

      if (data.type === "move-task") {
        const { taskId, fromColumn, toColumn, toIndex } = data;

        const fromTasks = state.columns[fromColumn];
        const toTasks = state.columns[toColumn];

        const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromTasks.splice(taskIndex, 1);
        toTasks.splice(toIndex, 0, task);

        broadcast();
      }

      if (data.type === "add-task") {
        const { column, title } = data;
        const newTask = {
          id: String(Date.now()),
          title,
          description: ""
        };
        state.columns[column].push(newTask);
        broadcast();
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

