    const columnNode = columnTemplate.content.cloneNode(true);
    const section = columnNode.querySelector(".column");
    const title = columnNode.querySelector("h2");
    const taskList = columnNode.querySelector(".task-list");
    const form = columnNode.querySelector(".add-task-form");
    const input = form.querySelector("input");

    title.textContent = label;
    section.dataset.column = key;

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      if (!draggedTask) return;

      const toColumn = key;
      const toIndex = taskList.children.length;

      ws.send(JSON.stringify({
        type: "move-task",
        taskId: draggedTask.id,
        fromColumn: draggedTask.column,
        toColumn,
        toIndex
      }));

      draggedTask = null;
    });

    appState.columns[key].forEach((task) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const article = taskNode.querySelector(".task");
      const titleEl = taskNode.querySelector(".task-title");
      const descEl = taskNode.querySelector(".task-desc");

      article.dataset.id = task.id;
      article.dataset.column = key;
      titleEl.textContent = task.title;
      descEl.textContent = task.description || "";

      article.addEventListener("dragstart", () => {
        draggedTask = { id: task.id, column: key };
        article.classList.add("dragging");
      });

      article.addEventListener("dragend", () => {
        article.classList.remove("dragging");
      });

      taskList.appendChild(taskNode);
    });

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const title = input.value.trim();
      if (!title) return;

      ws.send(JSON.stringify({
        type: "add-task",
        column: key,
        title
      }));

      input.value = "";
    });

    board.appendChild(columnNode);
  });
}
