const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let board = {
  todo: [
    { id: "1", title: "Set up project" },
    { id: "2", title: "Design UI" }
  ],
  doing: [
    { id: "3", title: "Build drag-and-drop" }
  ],
  done: [
    { id: "4", title: "Create repo" }
  ]
};

io.on("connection", (socket) => {
  socket.emit("board:update", board);

  socket.on("task:add", (task) => {
    const newTask = {
      id: Date.now().toString(),
      title: task.title
    };
    board.todo.push(newTask);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, from, to, index }) => {
    const taskIndex = board[from].findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = board[from].splice(taskIndex, 1);
    board[to].splice(index, 0, task);

    io.emit("board:update", board);
  });

  socket.on("board:reset", () => {
    board = {
      todo: [],
      doing: [],
      done: []
    };
    io.emit("board:update", board);
  });
});

server.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
