```js
const socket = io();

const taskInput = document.getElementById("taskInput");
const addTaskBtn = document.getElementById("addTaskBtn");
const resetBtn = document.getElementById("resetBtn");

const columns = ["todo", "doing", "done"];
let boardState = {};

let draggedTask = null;

function renderBoard(board) {
  boardState = board;

  columns.forEach((col) => {
    const list = document.getElementById(col);
    list.innerHTML = "";

    board[col].forEach((task, index) => {
      const div = document.createElement("div");
      div.className = "task";
      div.draggable = true;
      div.textContent = task.title;
      div.dataset.taskId = task.id;
      div.dataset.column = col;
      div.dataset.index = index;

      div.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          from: col
        };
      });

      list.appendChild(div);
    });
  });
}

addTaskBtn.addEventListener("click", () => {
  const title = taskInput.value.trim();
  if (!title) return;

  socket.emit("task:add", { title });
  taskInput.value = "";
});

resetBtn.addEventListener("click", () => {
  socket.emit("board:reset");
});

columns.forEach((col) => {
  const list = document.getElementById(col);

  list.addEventListener("dragover", (e) => {
    e.preventDefault();
    list.classList.add("drag-over");
  });

  list.addEventListener("dragleave", () => {
    list.classList.remove("drag-over");
  });

  list.addEventListener("drop", (e) => {
    e.preventDefault();
    list.classList.remove("drag-over");

    if (!draggedTask) return;

    const targetIndex = boardState[col].length;
    socket.emit("task:move", {
      taskId: draggedTask.taskId,
      from: draggedTask.from,
      to: col,
      index: targetIndex
    });

    draggedTask = null;
  });
});

socket.on("board:update", (board) => {
  renderBoard(board);
});
