## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const WebSocket = require("ws");
const path = require("path");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: [
    {
      id: "todo",
      title: "To Do",
      tasks: [
        { id: "t1", text: "Set up project", columnId: "todo" },
        { id: "t2", text: "Design UI", columnId: "todo" }
      ]
    },
    {
      id: "doing",
      title: "Doing",
      tasks: [
        { id: "t3", text: "Build drag-and-drop", columnId: "doing" }
      ]
    },
    {
      id: "done",
      title: "Done",
      tasks: []
    }
  ]
};

function broadcast() {
  const data = JSON.stringify({ type: "state", payload: state });
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) client.send(data);
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "state", payload: state }));

  ws.on("message", (message) => {
    try {
      const msg = JSON.parse(message);

      if (msg.type === "add-task") {
        const { columnId, text } = msg.payload;
        const column = state.columns.find((c) => c.id === columnId);
        if (!column || !text.trim()) return;

        const task = {
          id: `t_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
          text: text.trim(),
          columnId
        };

        column.tasks.push(task);
        broadcast();
      }

      if (msg.type === "move-task") {
        const { taskId, fromColumnId, toColumnId, toIndex } = msg.payload;
        const fromColumn = state.columns.find((c) => c.id === fromColumnId);
        const toColumn = state.columns.find((c) => c.id === toColumnId);
        if (!fromColumn || !toColumn) return;

        const taskIndex = fromColumn.tasks.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromColumn.tasks.splice(taskIndex, 1);
        task.columnId = toColumnId;

        const insertIndex = Math.max(0, Math.min(toIndex, toColumn.tasks.length));
        toColumn.tasks.splice(insertIndex, 0, task);

        broadcast();
      }
    } catch (err) {
      console.error("Invalid message:", err);
    }
  });
});

app.get("/health", (req, res) => res.json({ ok: true }));

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

