## 6) `public/app.js`

```js
const board = document.getElementById("board");
const columnTemplate = document.getElementById("column-template");
const taskTemplate = document.getElementById("task-template");

let state = null;
let draggedTask = null;

const ws = new WebSocket(`ws://${location.host}`);

ws.addEventListener("open", () => {
  console.log("Connected to server");
});

ws.addEventListener("message", (event) => {
  const msg = JSON.parse(event.data);
  if (msg.type === "state") {
    state = msg.payload;
    renderBoard();
  }
});

function renderBoard() {
  board.innerHTML = "";

  state.columns.forEach((column) => {
    const columnNode = columnTemplate.content.cloneNode(true);
    const section = columnNode.querySelector(".column");
    const title = columnNode.querySelector("h2");
    const taskList = columnNode.querySelector(".task-list");
    const form = columnNode.querySelector(".add-task-form");
    const input = form.querySelector("input");

    title.textContent = column.title;

    column.tasks.forEach((task) => {
      const taskNode = taskTemplate.content.cloneNode(true);
      const taskEl = taskNode.querySelector(".task");
      taskEl.textContent = task.text;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = column.id;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumnId: column.id
        };
      });

      taskList.appendChild(taskNode);
    });

    taskList.addEventListener("dragover", (e) => {
      e.preventDefault();
      taskList.classList.add("drag-over");
    });

    taskList.addEventListener("dragleave", () => {
      taskList.classList.remove("drag-over");
    });

    taskList.addEventListener("drop", (e) => {
      e.preventDefault();
      taskList.classList.remove("drag-over");

      if (!draggedTask) return;

      const targetTask = e.target.closest(".task");
      let toIndex = column.tasks.length;

      if (targetTask) {
        const targetTaskId = targetTask.dataset.taskId;
        toIndex = column.tasks.findIndex((t) => t.id === targetTaskId);
        if (toIndex < 0) toIndex = column.tasks.length;
      }

      ws.send(JSON.stringify({
        type: "move-task",
        payload: {
          taskId: draggedTask.taskId,
          fromColumnId: draggedTask.fromColumnId,
          toColumnId: column.id,
          toIndex
        }
      }));

      draggedTask = null;
    });

    form.addEventListener("submit", (e) => {
      e.preventDefault();
      const text = input.value.trim();
      if (!text) return;

      ws.send(JSON.stringify({
        type: "add-task",
        payload: {
          columnId: column.id,
          text
        }
      }));

      input.value = "";
    });

    section.querySelector(".column-header").appendChild(title);
    section.querySelector(".task-list").replaceWith(taskList);
    section.querySelector(".add-task-form").replaceWith(form);
    board.appendChild(columnNode);
  });
}
