```js
const socket = io();

let boardState = {
  todo: [],
  doing: [],
  done: []
};

const boardEl = document.getElementById("board");

function renderBoard() {
  document.querySelectorAll(".column").forEach((columnEl) => {
    const columnName = columnEl.dataset.column;
    const cardsContainer = columnEl.querySelector(".cards");
    cardsContainer.innerHTML = "";

    boardState[columnName].forEach((task) => {
      const card = document.createElement("div");
      card.className = "card";
      card.draggable = true;
      card.dataset.id = task.id;
      card.dataset.column = columnName;

      card.innerHTML = `
        <h3>${task.title}</h3>
        <p>${task.description}</p>
      `;

      card.addEventListener("dragstart", onDragStart);
      cardsContainer.appendChild(card);
    });
  });
}

let draggedTask = null;

function onDragStart(e) {
  const taskId = e.currentTarget.dataset.id;
  const column = e.currentTarget.dataset.column;

  draggedTask = { taskId, fromColumn: column };
  e.dataTransfer.effectAllowed = "move";
}

document.querySelectorAll(".column").forEach((columnEl) => {
  columnEl.addEventListener("dragover", (e) => {
    e.preventDefault();
    columnEl.classList.add("drag-over");
  });

  columnEl.addEventListener("dragleave", () => {
    columnEl.classList.remove("drag-over");
  });

  columnEl.addEventListener("drop", (e) => {
    e.preventDefault();
    columnEl.classList.remove("drag-over");

    if (!draggedTask) return;

    const toColumn = columnEl.dataset.column;
    if (draggedTask.fromColumn === toColumn) return;

    moveTask(draggedTask.taskId, draggedTask.fromColumn, toColumn);
    draggedTask = null;
  });
});

function moveTask(taskId, fromColumn, toColumn) {
  const taskIndex = boardState[fromColumn].findIndex((t) => t.id === taskId);
  if (taskIndex === -1) return;

  const [task] = boardState[fromColumn].splice(taskIndex, 1);
  boardState[toColumn].push(task);

  renderBoard();
  socket.emit("board:update", boardState);
}

socket.on("board:init", (initialState) => {
  boardState = initialState;
  renderBoard();
});

socket.on("board:update", (newState) => {
  boardState = newState;
  renderBoard();
});
