const express = require("express");
const http = require("http");
const { Server } = require("socket.io");

const app = express();
const server = http.createServer(app);
const io = new Server(server);

app.use(express.static("public"));

let state = {
  columns: {
    todo: [
      { id: "1", title: "Set up project" },
      { id: "2", title: "Design UI" }
    ],
    doing: [
      { id: "3", title: "Build drag-and-drop" }
    ],
    done: [
      { id: "4", title: "Create repo" }
    ]
  }
};

io.on("connection", (socket) => {
  socket.emit("state:init", state);

  socket.on("task:add", ({ columnId, title }) => {
    const task = { id: Date.now().toString(), title };
    state.columns[columnId].push(task);
    io.emit("state:update", state);
  });

  socket.on("task:move", ({ taskId, fromColumnId, toColumnId, toIndex }) => {
    const fromColumn = state.columns[fromColumnId];
    const toColumn = state.columns[toColumnId];

    const taskIndex = fromColumn.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromColumn.splice(taskIndex, 1);
    toColumn.splice(toIndex, 0, task);

    io.emit("state:update", state);
  });

  socket.on("task:delete", ({ taskId, columnId }) => {
    state.columns[columnId] = state.columns[columnId].filter((t) => t.id !== taskId);
    io.emit("state:update", state);
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
