```js
const socket = io();

const state = {
  columns: {
    todo: [],
    doing: [],
    done: []
  }
};

const taskLists = {
  todo: document.getElementById("todo"),
  doing: document.getElementById("doing"),
  done: document.getElementById("done")
};

const addTaskForm = document.getElementById("addTaskForm");
const taskTitleInput = document.getElementById("taskTitle");
const columnSelect = document.getElementById("columnSelect");

let draggedTask = null;

socket.on("state:init", (serverState) => {
  state.columns = serverState.columns;
  render();
});

socket.on("state:update", (serverState) => {
  state.columns = serverState.columns;
  render();
});

addTaskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  const title = taskTitleInput.value.trim();
  const columnId = columnSelect.value;

  if (!title) return;

  socket.emit("task:add", { columnId, title });
  taskTitleInput.value = "";
});

function render() {
  Object.keys(taskLists).forEach((columnId) => {
    const list = taskLists[columnId];
    list.innerHTML = "";

    state.columns[columnId].forEach((task, index) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.dataset.taskId = task.id;
      taskEl.dataset.columnId = columnId;
      taskEl.dataset.index = index;

      taskEl.innerHTML = `
        <span>${escapeHtml(task.title)}</span>
        <button title="Delete">×</button>
      `;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = {
          taskId: task.id,
          fromColumnId: columnId,
          fromIndex: index
        };
      });

      taskEl.querySelector("button").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, columnId });
      });

      list.appendChild(taskEl);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumnId = columnId;
      const toIndex = state.columns[toColumnId].length;

      socket.emit("task:move", {
        taskId: draggedTask.taskId,
        fromColumnId: draggedTask.fromColumnId,
        toColumnId,
        toIndex
      });

      draggedTask = null;
    });
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
