## 3) `server.js`

```js
const express = require("express");
const http = require("http");
const path = require("path");
const WebSocket = require("ws");

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });

app.use(express.static(path.join(__dirname, "public")));

let state = {
  columns: {
    todo: [
      { id: "t1", title: "Set up project" },
      { id: "t2", title: "Design UI" }
    ],
    doing: [
      { id: "t3", title: "Build drag and drop" }
    ],
    done: []
  }
};

function broadcast(message) {
  const data = JSON.stringify(message);
  wss.clients.forEach((client) => {
    if (client.readyState === WebSocket.OPEN) {
      client.send(data);
    }
  });
}

wss.on("connection", (ws) => {
  ws.send(JSON.stringify({ type: "init", state }));

  ws.on("message", (msg) => {
    try {
      const message = JSON.parse(msg);

      if (message.type === "move-task") {
        const { taskId, fromColumn, toColumn, toIndex } = message;

        const fromTasks = state.columns[fromColumn];
        const toTasks = state.columns[toColumn];
        if (!fromTasks || !toTasks) return;

        const taskIndex = fromTasks.findIndex((t) => t.id === taskId);
        if (taskIndex === -1) return;

        const [task] = fromTasks.splice(taskIndex, 1);
        toTasks.splice(toIndex, 0, task);

        broadcast({ type: "state", state });
      }

      if (message.type === "add-task") {
        const { columnId, title } = message;
        if (!state.columns[columnId]) return;

        const task = {
          id: "t" + Date.now(),
          title: title.trim()
        };

        if (!task.title) return;

        state.columns[columnId].push(task);
        broadcast({ type: "state", state });
      }
    } catch (e) {
      console.error("Invalid message:", e);
    }
  });
});

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Server running at http://localhost:${PORT}`);
});
```

