const boardEl = document.getElementById("board");
const taskInput = document.getElementById("taskInput");
const columnSelect = document.getElementById("columnSelect");
const addTaskBtn = document.getElementById("addTaskBtn");

let state = null;
let draggedTask = null;

const ws = new WebSocket(`ws://${location.host}`);

ws.addEventListener("message", (event) => {
  const message = JSON.parse(event.data);

  if (message.type === "init" || message.type === "state") {
    state = message.state;
    renderBoard();
  }
});

function send(message) {
  ws.send(JSON.stringify(message));
}

function renderBoard() {
  if (!state) return;

  const columns = [
    { id: "todo", title: "To Do" },
    { id: "doing", title: "Doing" },
    { id: "done", title: "Done" }
  ];

  boardEl.innerHTML = "";

  columns.forEach((col) => {
    const columnEl = document.createElement("div");
    columnEl.className = "column";

    const titleEl = document.createElement("h2");
    titleEl.textContent = col.title;

    const listEl = document.createElement("div");
    listEl.className = "task-list";
    listEl.dataset.columnId = col.id;

    listEl.addEventListener("dragover", (e) => {
      e.preventDefault();
      listEl.classList.add("drag-over");
    });

    listEl.addEventListener("dragleave", () => {
      listEl.classList.remove("drag-over");
    });

    listEl.addEventListener("drop", (e) => {
      e.preventDefault();
      listEl.classList.remove("drag-over");

      if (!draggedTask) return;

      const toColumn = col.id;
      const toIndex = state.columns[toColumn].length;

      send({
        type: "move-task",
        taskId: draggedTask.id,
        fromColumn: draggedTask.fromColumn,
        toColumn,
        toIndex
      });

      draggedTask = null;
    });

    state.columns[col.id].forEach((task) => {
      const taskEl = document.createElement("div");
      taskEl.className = "task";
      taskEl.draggable = true;
      taskEl.textContent = task.title;

      taskEl.addEventListener("dragstart", () => {
        draggedTask = { id: task.id, fromColumn: col.id };
      });

      listEl.appendChild(taskEl);
    });

    columnEl.appendChild(titleEl);
    columnEl.appendChild(listEl);
    boardEl.appendChild(columnEl);
  });
}

addTaskBtn.addEventListener("click", () => {
  const title = taskInput.value.trim();
  const columnId = columnSelect.value;

  if (!title) return;

  send({
    type: "add-task",
    columnId,
    title
  });

  taskInput.value = "";
});

taskInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") addTaskBtn.click();
});
