    };
    board.todo.unshift(newTask);
    io.emit("board:update", board);
  });

  socket.on("task:move", ({ taskId, from, to, index }) => {
    const fromList = board[from];
    const toList = board[to];
    if (!fromList || !toList) return;

    const taskIndex = fromList.findIndex((t) => t.id === taskId);
    if (taskIndex === -1) return;

    const [task] = fromList.splice(taskIndex, 1);
    toList.splice(index, 0, task);

    io.emit("board:update", board);
  });

  socket.on("task:delete", ({ taskId, column }) => {
    const list = board[column];
    if (!list) return;

    board[column] = list.filter((t) => t.id !== taskId);
    io.emit("board:update", board);
  });
});

