## 6) `public/app.js`

```js
const socket = io();

const taskForm = document.getElementById("taskForm");
const titleInput = document.getElementById("titleInput");
const descInput = document.getElementById("descInput");

const columns = ["todo", "doing", "done"];
let currentBoard = {};

socket.on("board:update", (board) => {
  currentBoard = board;
  renderBoard(board);
});

taskForm.addEventListener("submit", (e) => {
  e.preventDefault();
  socket.emit("task:add", {
    title: titleInput.value.trim(),
    description: descInput.value.trim()
  });
  titleInput.value = "";
  descInput.value = "";
});

function renderBoard(board) {
  columns.forEach((column) => {
    const list = document.getElementById(column);
    list.innerHTML = "";

    board[column].forEach((task, index) => {
      const card = document.createElement("div");
      card.className = "task";
      card.draggable = true;
      card.dataset.id = task.id;
      card.dataset.column = column;
      card.dataset.index = index;

      card.innerHTML = `
        <h3>${escapeHtml(task.title)}</h3>
        <p>${escapeHtml(task.description || "")}</p>
        <div class="actions">
          <button data-delete="${task.id}">Delete</button>
        </div>
      `;

      card.addEventListener("dragstart", (e) => {
        e.dataTransfer.setData(
          "text/plain",
          JSON.stringify({ taskId: task.id, from: column, index })
        );
      });

      card.querySelector("[data-delete]").addEventListener("click", () => {
        socket.emit("task:delete", { taskId: task.id, column });
      });

      list.appendChild(card);
    });

    list.addEventListener("dragover", (e) => {
      e.preventDefault();
      list.classList.add("drag-over");
    });

    list.addEventListener("dragleave", () => {
      list.classList.remove("drag-over");
    });

    list.addEventListener("drop", (e) => {
      e.preventDefault();
      list.classList.remove("drag-over");

      const data = JSON.parse(e.dataTransfer.getData("text/plain"));
      socket.emit("task:move", {
        taskId: data.taskId,
        from: data.from,
        to: column,
        index: board[column].length
      });
    });
  });
}

function escapeHtml(str) {
  return str
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}
```

