## `src/risk.rs`

```rust
use crate::types::{NewOrder, Qty};

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: Qty,
    pub max_notional: i64,
}

#[derive(Debug)]
pub enum RiskError {
    QtyTooLarge,
    InvalidPrice,
}

pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn validate_new_order(&self, order: &NewOrder) -> Result<(), RiskError> {
        if order.qty <= 0 || order.qty > self.limits.max_order_qty {
            return Err(RiskError::QtyTooLarge);
        }

        if let Some(price) = order.price {
            let notional = price.saturating_mul(order.qty);
            if notional.abs() > self.limits.max_notional {
                return Err(RiskError::InvalidPrice);
            }
        }

        Ok(())
    }
}
```

