## `src/oms.rs`

```rust
use std::collections::HashMap;

use crate::types::{ClientOrderId, OrderId, OrderCommand, ExecutionReport, NewOrder};

#[derive(Debug, Clone)]
pub enum OrderState {
    PendingNew,
    Acked,
    Filled,
    Rejected,
    Cancelled,
}

#[derive(Debug, Clone)]
pub struct OrderRecord {
    pub order_id: Option<OrderId>,
    pub client_order_id: ClientOrderId,
    pub state: OrderState,
    pub order: NewOrder,
}

pub struct OrderManager {
    next_order_id: OrderId,
    orders: HashMap<ClientOrderId, OrderRecord>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            next_order_id: 1,
            orders: HashMap::new(),
        }
    }

    pub fn on_new_order(&mut self, order: NewOrder) -> OrderId {
        let order_id = self.next_order_id;
        self.next_order_id += 1;

        let record = OrderRecord {
            order_id: Some(order_id),
            client_order_id: order.client_order_id,
            state: OrderState::PendingNew,
            order,
        };

        self.orders.insert(record.client_order_id, record);
        order_id
    }

    pub fn on_execution_report(&mut self, report: &ExecutionReport) {
        match report {
            ExecutionReport::Ack { order_id, client_order_id } => {
                if let Some(rec) = self.orders.get_mut(client_order_id) {
                    rec.order_id = Some(*order_id);
                    rec.state = OrderState::Acked;
                }
            }
            ExecutionReport::Fill { order_id: _, filled_qty: _, fill_price: _ } => {
                // In a real OMS, track partial fills and remaining qty.
            }
            ExecutionReport::Reject { client_order_id, .. } => {
                if let Some(rec) = self.orders.get_mut(client_order_id) {
                    rec.state = OrderState::Rejected;
                }
            }
        }
    }

    pub fn build_command(&mut self, cmd: OrderCommand) -> OrderCommand {
        cmd
    }
}
