## `src/strategy.rs`

A simple example strategy: if bid/ask spread is wide enough, place a limit order.

```rust
use crate::types::{MarketDataTick, NewOrder, OrderCommand, OrderType, Side, TimeInForce};

pub struct Strategy {
    pub spread_threshold: i64,
    next_client_order_id: u64,
}

impl Strategy {
    pub fn new(spread_threshold: i64) -> Self {
        Self {
            spread_threshold,
            next_client_order_id: 1,
        }
    }

    pub fn on_market_data(&mut self, tick: &MarketDataTick) -> Option<OrderCommand> {
        let spread = tick.ask - tick.bid;
        if spread >= self.spread_threshold {
            let client_order_id = self.next_client_order_id;
            self.next_client_order_id += 1;

            let order = NewOrder {
                client_order_id,
                instrument_id: tick.instrument_id,
                side: Side::Buy,
                order_type: OrderType::Limit,
                price: Some(tick.bid),
                qty: 1,
                tif: TimeInForce::IOC,
            };

            return Some(OrderCommand::New(order));
        }

        None
    }
}
