use crate::types::MarketDataTick;
use tokio::time::{sleep, Duration};

pub async fn run_mock_feed<F>(mut on_tick: F)
where
    F: FnMut(MarketDataTick) + Send + 'static,
{
    let mut price: i64 = 1000;

    loop {
        price += 1;

        let tick = MarketDataTick {
            instrument_id: 1,
            bid: price,
            ask: price + 2,
            bid_qty: 10,
            ask_qty: 10,
            ts_nanos: current_time_nanos(),
        };

        on_tick(tick);

        sleep(Duration::from_millis(10)).await;
    }
}

fn current_time_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64
}
```

