use std::sync::atomic::{AtomicU64, Ordering};

pub struct Metrics {
    pub market_data_count: AtomicU64,
    pub orders_sent: AtomicU64,
    pub rejects: AtomicU64,
}

impl Metrics {
    pub fn new() -> Self {
        Self {
            market_data_count: AtomicU64::new(0),
            orders_sent: AtomicU64::new(0),
            rejects: AtomicU64::new(0),
        }
    }

    pub fn inc_market_data(&self) {
        self.market_data_count.fetch_add(1, Ordering::Relaxed);
    }

    pub fn inc_orders_sent(&self) {
        self.orders_sent.fetch_add(1, Ordering::Relaxed);
    }

    pub fn inc_rejects(&self) {
        self.rejects.fetch_add(1, Ordering::Relaxed);
    }
}
