use crate::config::AppConfig;
use crate::execution::ExecutionGateway;
use crate::metrics::Metrics;
use crate::risk::{RiskEngine, RiskLimits};
use crate::strategy::Strategy;
use crate::types::{OrderCommand, StrategyEvent};
use std::sync::Arc;
use tracing::{info, warn};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = AppConfig::default();
    let metrics = Arc::new(Metrics::new());

    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: config.max_order_qty,
        max_notional: config.max_notional,
    });

    let mut strategy = Strategy::new(config.spread_threshold);
    let mut execution = ExecutionGateway::new();
    let mut oms = oms::OrderManager::new();

    info!("Starting trading platform");

    market_data::run_mock_feed(move |tick| {
        metrics.inc_market_data();

        let event = StrategyEvent::MarketData(tick.clone());
        info!("Market event: {:?}", event);

        if let Some(cmd) = strategy.on_market_data(&tick) {
            match cmd {
                OrderCommand::New(order) => {
                    if let Err(err) = risk.validate_new_order(&order) {
                        metrics.inc_rejects();
                        warn!("Risk reject for order {:?}: {:?}", order.client_order_id, err);
                        return;
                    }

                    let _internal_order_id = oms.on_new_order(order.clone());
                    metrics.inc_orders_sent();

                    let report = execution.send_new_order(&order);
                    oms.on_execution_report(&report);

                    info!("Execution report: {:?}", report);
                }
                OrderCommand::Cancel(_) => {
                    // handle cancel path
                }
            }
        }
    })
    .await;

    Ok(())
}
