Pre-trade risk checks. Keep this fast and deterministic.

```rust
use crate::types::{Order, OrderType, Side};
use dashmap::DashMap;
use std::sync::Arc;
use uuid::Uuid;

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
    pub max_position_per_symbol: f64,
}

#[derive(Debug, Clone)]
pub struct Position {
    pub qty: f64,
    pub avg_price: f64,
}

#[derive(Clone)]
pub struct RiskEngine {
    limits: RiskLimits,
    positions: Arc<DashMap<String, Position>>,
}

#[derive(Debug, thiserror::Error)]
pub enum RiskError {
    #[error("order quantity exceeds limit")]
    QtyLimit,
    #[error("notional exceeds limit")]
    NotionalLimit,
    #[error("position limit exceeded")]
    PositionLimit,
    #[error("missing price for limit order")]
    MissingPrice,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn check_order(&self, order: &Order, market_price: Option<f64>) -> Result<(), RiskError> {
        if order.qty > self.limits.max_order_qty {
            return Err(RiskError::QtyLimit);
        }

        let px = match order.order_type {
            OrderType::Market => market_price.ok_or(RiskError::MissingPrice)?,
            OrderType::Limit => order.price.ok_or(RiskError::MissingPrice)?,
        };

        let notional = order.qty * px;
        if notional > self.limits.max_notional {
            return Err(RiskError::NotionalLimit);
        }

        let pos = self.positions.get(&order.symbol).map(|p| p.qty).unwrap_or(0.0);
        let projected = match order.side {
            Side::Buy => pos + order.qty,
            Side::Sell => pos - order.qty,
        };

        if projected.abs() > self.limits.max_position_per_symbol {
            return Err(RiskError::PositionLimit);
        }

        Ok(())
    }

    pub fn apply_fill(&self, symbol: &str, qty: f64, price: f64, side: Side) {
        let signed_qty = match side {
            Side::Buy => qty,
            Side::Sell => -qty,
        };

        self.positions
            .entry(symbol.to_string())
            .and_modify(|p| {
                let new_qty = p.qty + signed_qty;
                p.avg_price = if new_qty.abs() < f64::EPSILON {
                    0.0
                } else {
                    price
                };
                p.qty = new_qty;
            })
            .or_insert(Position {
                qty: signed_qty,
                avg_price: price,
            });
    }
}
