# `src/engine.rs`

The core event loop. This is where market data, strategy, risk, and execution connect.

```rust
use crate::{
    exchange::{Exchange, ExchangeError},
    risk::{RiskEngine, RiskError},
    strategy::Strategy,
    types::{Event, MarketTick, Order, OrderStatus},
};
use std::sync::Arc;
use tracing::{error, info};

pub struct Engine<E: Exchange> {
    pub risk: RiskEngine,
    pub exchange: Arc<E>,
    pub strategy: Box<dyn Strategy>,
}

impl<E: Exchange + 'static> Engine<E> {
    pub fn new(risk: RiskEngine, exchange: Arc<E>, strategy: Box<dyn Strategy>) -> Self {
        Self { risk, exchange, strategy }
    }

    pub async fn handle_event(&mut self, event: Event) {
        match event {
            Event::MarketTick(tick) => self.on_tick(tick).await,
            Event::NewOrder(order) => self.on_new_order(order).await,
            Event::Fill(fill) => {
                info!("fill received: {:?}", fill);
            }
            Event::CancelOrder(order_id) => {
                if let Err(e) = self.exchange.cancel_order(order_id).await {
                    error!("cancel failed: {e}");
                }
            }
            Event::OrderAccepted(_) | Event::OrderRejected { .. } => {}
        }
    }

    async fn on_tick(&mut self, tick: MarketTick) {
        let orders = self.strategy.on_tick(&tick);
        for order in orders {
            self.on_new_order(order).await;
        }
    }

    async fn on_new_order(&mut self, mut order: Order) {
        let market_price = Some((order.price.unwrap_or(0.0)).max(0.0));

        if let Err(reason) = self.risk.check_order(&order, market_price) {
            error!("risk reject order {}: {:?}", order.id, reason);
            order.status = OrderStatus::Rejected;
            return;
        }

        match self.exchange.send_order(&order).await {
            Ok(_) => {
                order.status = OrderStatus::Accepted;
                info!("order accepted: {}", order.id);
            }
            Err(e) => {
                error!("exchange error for {}: {e}", order.id);
            }
        }
    }
}
