```rust
use crate::types::{Price, Qty, Side};
use std::cmp::Reverse;
use std::collections::{BTreeMap, VecDeque};

#[derive(Debug, Clone)]
pub struct BookOrder {
    pub order_id: u64,
    pub qty: Qty,
}

#[derive(Debug, Default)]
pub struct OrderBook {
    bids: BTreeMap<Reverse<Price>, VecDeque<BookOrder>>,
    asks: BTreeMap<Price, VecDeque<BookOrder>>,
}

impl OrderBook {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_limit_order(
        &mut self,
        order_id: u64,
        side: Side,
        price: Price,
        qty: Qty,
    ) -> Vec<(u64, Qty, Price)> {
        let mut fills = Vec::new();
        let mut remaining = qty;

        match side {
            Side::Buy => {
                while remaining > 0 {
                    let best_ask_price = match self.asks.keys().next().copied() {
                        Some(p) => p,
                        None => break,
                    };

                    if best_ask_price > price {
                        break;
                    }

                    let mut remove_level = false;
                    if let Some(level) = self.asks.get_mut(&best_ask_price) {
                        while remaining > 0 {
                            let front = match level.front_mut() {
                                Some(o) => o,
                                None => break,
                            };

                            let traded = remaining.min(front.qty);
                            front.qty -= traded;
                            remaining -= traded;
                            fills.push((front.order_id, traded, best_ask_price));

                            if front.qty == 0 {
                                level.pop_front();
                            } else {
                                break;
                            }
                        }

                        if level.is_empty() {
                            remove_level = true;
                        }
                    }

                    if remove_level {
                        self.asks.remove(&best_ask_price);
                    }
                }

                if remaining > 0 {
                    self.bids
                        .entry(Reverse(price))
                        .or_default()
                        .push_back(BookOrder { order_id, qty: remaining });
                }
            }
            Side::Sell => {
                while remaining > 0 {
                    let best_bid_price = match self.bids.keys().next().copied() {
                        Some(Reverse(p)) => p,
                        None => break,
                    };

                    if best_bid_price < price {
                        break;
                    }

                    let mut remove_level = false;
                    if let Some(level) = self.bids.get_mut(&Reverse(best_bid_price)) {
                        while remaining > 0 {
                            let front = match level.front_mut() {
                                Some(o) => o,
                                None => break,
                            };

                            let traded = remaining.min(front.qty);
                            front.qty -= traded;
                            remaining -= traded;
                            fills.push((front.order_id, traded, best_bid_price));

                            if front.qty == 0 {
                                level.pop_front();
                            } else {
                                break;
                            }
                        }

                        if level.is_empty() {
                            remove_level = true;
                        }
                    }

                    if remove_level {
                        self.bids.remove(&Reverse(best_bid_price));
                    }
                }

                if remaining > 0 {
                    self.asks
                        .entry(price)
                        .or_default()
                        .push_back(BookOrder { order_id, qty: remaining });
                }
            }
        }

        fills
    }

    pub fn add_market_order(
        &mut self,
        order_id: u64,
        side: Side,
        qty: Qty,
    ) -> Vec<(u64, Qty, Price)> {
        let mut fills = Vec::new();
        let mut remaining = qty;

        match side {
            Side::Buy => {
                while remaining > 0 {
                    let best_ask_price = match self.asks.keys().next().copied() {
                        Some(p) => p,
                        None => break,
                    };

                    let mut remove_level = false;
                    if let Some(level) = self.asks.get_mut(&best_ask_price) {
                        while remaining > 0 {
                            let front = match level.front_mut() {
                                Some(o) => o,
                                None => break,
                            };

                            let traded = remaining.min(front.qty);
                            front.qty -= traded;
                            remaining -= traded;
                            fills.push((front.order_id, traded, best_ask_price));

                            if front.qty == 0 {
                                level.pop_front();
                            } else {
                                break;
                            }
                        }

                        if level.is_empty() {
                            remove_level = true;
                        }
                    }

                    if remove_level {
                        self.asks.remove(&best_ask_price);
                    }
                }
            }
            Side::Sell => {
                while remaining > 0 {
                    let best_bid_price = match self.bids.keys().next().copied() {
                        Some(Reverse(p)) => p,
                        None => break,
                    };

                    let mut remove_level = false;
                    if let Some(level) = self.bids.get_mut(&Reverse(best_bid_price)) {
                        while remaining > 0 {
                            let front = match level.front_mut() {
                                Some(o) => o,
                                None => break,
                            };

                            let traded = remaining.min(front.qty);
                            front.qty -= traded;
                            remaining -= traded;
                            fills.push((front.order_id, traded, best_bid_price));

                            if front.qty == 0 {
                                level.pop_front();
                            } else {
                                break;
