## `src/engine/risk.rs`

```rust
use crate::types::{NewOrder, Qty, Side};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: Qty,
    pub max_notional: i64,
}

#[derive(Debug, Default)]
pub struct RiskState {
    pub positions: HashMap<String, Qty>,
}

#[derive(Debug)]
pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn check_order(&self, order: &NewOrder) -> Result<(), String> {
        if order.qty <= 0 {
            return Err("qty must be positive".into());
        }

        if order.qty > self.limits.max_order_qty {
            return Err(format!("qty exceeds max_order_qty {}", self.limits.max_order_qty));
        }

        if let Some(price) = order.price {
            let notional = price.saturating_mul(order.qty);
            if notional > self.limits.max_notional {
                return Err("notional exceeds limit".into());
            }
        }

        Ok(())
    }

    pub fn apply_fill(&self, state: &mut RiskState, symbol: &str, side: Side, qty: Qty) {
        let pos = state.positions.entry(symbol.to_string()).or_insert(0);
        match side {
            Side::Buy => *pos += qty,
            Side::Sell => *pos -= qty,
        }
    }
}
