use crate::types::{NewOrder, OrderEvent, OrderAck};
use dashmap::DashMap;
use uuid::Uuid;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OrderStatus {
    New,
    Accepted,
    Rejected,
    Filled,
    PartiallyFilled,
    Cancelled,
}

#[derive(Debug, Clone)]
pub struct OrderRecord {
    pub order: NewOrder,
    pub status: OrderStatus,
}

#[derive(Debug, Default)]
pub struct Oms {
    orders: DashMap<Uuid, OrderRecord>,
}

impl Oms {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn on_new_order(&self, order: NewOrder) -> OrderEvent {
        let id = order.client_order_id;
        self.orders.insert(
            id,
            OrderRecord {
                order: order.clone(),
                status: OrderStatus::Accepted,
            },
        );

        OrderEvent::Ack(OrderAck {
            client_order_id: id,
            accepted: true,
            reason: None,
        })
    }

    pub fn reject(&self, order: NewOrder, reason: String) -> OrderEvent {
        self.orders.insert(
            order.client_order_id,
            OrderRecord {
                order: order.clone(),
                status: OrderStatus::Rejected,
            },
        );

        OrderEvent::Reject {
            client_order_id: order.client_order_id,
            reason,
        }
    }
}
