## `src/net/order_api.rs`

A simple TCP JSON order API.

```rust
use crate::types::NewOrder;
use serde_json::json;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tracing::{error, info};

pub async fn run_order_api(addr: &str, tx: tokio::sync::mpsc::Sender<NewOrder>) -> std::io::Result<()> {
    let listener = TcpListener::bind(addr).await?;
    info!("order api listening on {}", addr);

    loop {
        let (socket, peer) = listener.accept().await?;
        let tx = tx.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(socket, tx).await {
                error!("client {} error: {}", peer, e);
            }
        });
    }
}

async fn handle_client(socket: TcpStream, tx: tokio::sync::mpsc::Sender<NewOrder>) -> std::io::Result<()> {
    let (read_half, mut write_half) = socket.into_split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let parsed: Result<NewOrder, _> = serde_json::from_str(line.trim());
        match parsed {
            Ok(order) => {
                if tx.send(order).await.is_ok() {
                    write_half.write_all(b"{\"status\":\"ok\"}\n").await?;
                } else {
                    write_half.write_all(b"{\"status\":\"error\",\"reason\":\"engine unavailable\"}\n").await?;
                }
            }
            Err(e) => {
                let msg = json!({"status":"error","reason": e.to_string()}).to_string() + "\n";
                write_half.write_all(msg.as_bytes()).await?;
            }
        }
    }

    Ok(())
}
```

