            .create(true)
            .append(true)
            .open(&self.path)
            .await?;

        let line = serde_json::to_string(event).unwrap_or_else(|_| "{\"error\":\"serialize\"}".into());
        file.write_all(line.as_bytes()).await?;
        file.write_all(b"\n").await?;
        Ok(())
    }
}
