use crate::config::Config;
use crate::engine::oms::Oms;
use crate::engine::risk::{RiskEngine, RiskLimits, RiskState};
use crate::infra::audit::AuditLogger;
use crate::infra::metrics::Metrics;
use crate::types::{NewOrder, OrderEvent, OrderType, Side, TimeInForce};
use std::sync::Arc;
use tokio::sync::mpsc;
use tracing::{error, info};
use uuid::Uuid;

#[tokio::main]
async fn main() -> std::io::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = Config::default();
    let metrics = Arc::new(Metrics::default());
    let audit = AuditLogger::new(config.audit_path.clone());

    let oms = Arc::new(Oms::new());
    let risk = Arc::new(RiskEngine::new(RiskLimits {
        max_order_qty: 100_000,
        max_notional: 1_000_000_000,
    }));

    let (tx, mut rx) = mpsc::channel::<NewOrder>(10_000);

    let api_tx = tx.clone();
    tokio::spawn(async move {
        if let Err(e) = net::order_api::run_order_api(&config.order_api_addr, api_tx).await {
            error!("order api failed: {}", e);
        }
    });

    let engine_metrics = metrics.clone();
    let engine_oms = oms.clone();
    let engine_risk = risk.clone();

    tokio::spawn(async move {
        let mut risk_state = RiskState::default();

        while let Some(order) = rx.recv().await {
            engine_metrics.inc_received();

            match engine_risk.check_order(&order) {
                Ok(_) => {
                    let ack = engine_oms.on_new_order(order.clone());
                    engine_metrics.inc_accepted();
                    let _ = audit.log_event(&ack).await;

                    info!("accepted order {}", order.client_order_id);

                    let simulated_fill = OrderEvent::Fill(crate::types::Fill {
                        client_order_id: order.client_order_id,
                        symbol: order.symbol.clone(),
                        qty: order.qty,
                        price: order.price.unwrap_or(0),
                    });

                    if let OrderEvent::Fill(fill) = simulated_fill {
                        engine_risk.apply_fill(&mut risk_state, &fill.symbol, order.side, fill.qty);
                        engine_metrics.inc_fills();
                        let _ = audit.log_event(&OrderEvent::Fill(fill)).await;
                    }
                }
                Err(reason) => {
                    engine_metrics.inc_rejected();
                    let rej = engine_oms.reject(order.clone(), reason);
                    let _ = audit.log_event(&rej).await;
                }
            }
        }
    });

    info!("trading platform started");

    loop {
        tokio::time::sleep(std::time::Duration::from_secs(60)).await;
    }
}
