# `src/risk.rs`

```rust
use crate::{
    config::Config,
    types::{OrderRequest, OrderType, Side},
};

#[derive(Clone)]
pub struct RiskEngine {
    config: Config,
}

impl RiskEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn validate_order(&self, order: &OrderRequest, market_price: Option<f64>) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }

        if order.qty > self.config.risk_max_order_qty {
            return Err(format!("qty exceeds max order qty {}", self.config.risk_max_order_qty));
        }

        let px = match (&order.order_type, market_price) {
            (OrderType::Market, Some(p)) => p,
            (OrderType::Limit { price }, _) => *price,
            (OrderType::Market, None) => return Err("no market price available for market order".into()),
        };

        let notional = px * order.qty;
        if notional > self.config.risk_max_notional {
            return Err(format!("notional exceeds max notional {}", self.config.risk_max_notional));
        }

        match order.side {
            Side::Buy | Side::Sell => Ok(()),
        }
    }
}
```

