                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: 1.0,
                order_type: OrderType::Market,
                ts_nanos: tick.ts_nanos,
            };

            self.bus.publish(Event::OrderRequest(order)).await;
        }
    }
}
