# `src/engine.rs`

This is the event loop that wires everything together.

```rust
use std::sync::Arc;

use tracing::{info, warn};

use crate::{
    config::Config,
    execution::ExecutionGateway,
    oms::OrderManagementSystem,
    risk::RiskEngine,
    strategy::StrategyEngine,
    types::{Event, MarketTick},
};

pub struct TradingEngine {
    config: Config,
    risk: RiskEngine,
    strategy: StrategyEngine,
    oms: Arc<OrderManagementSystem>,
    execution: ExecutionGateway,
}

impl TradingEngine {
    pub fn new(
        config: Config,
        strategy: StrategyEngine,
        risk: RiskEngine,
        oms: Arc<OrderManagementSystem>,
        execution: ExecutionGateway,
    ) -> Self {
        Self {
            config,
            risk,
            strategy,
            oms,
            execution,
        }
    }

    pub async fn run(mut rx: tokio::sync::mpsc::Receiver<Event>, engine: Arc<Self>) {
        info!("trading engine started");

        while let Some(event) = rx.recv().await {
            match event {
                Event::Tick(tick) => {
                    engine.strategy.on_tick(tick).await;
                }
                Event::OrderRequest(order) => {
                    engine.oms.submit(&order);

                    let market_price = Some(100.0);
                    match engine.risk.validate_order(&order, market_price) {
                        Ok(_) => {
                            let exec = engine.execution.execute(order);
                            tokio::spawn(exec);
                        }
                        Err(reason) => {
                            warn!("order rejected: {}", reason);
                        }
                    }
                }
                Event::OrderUpdate(update) => {
                    engine.oms.update(update);
                }
                Event::Shutdown => {
                    info!("shutdown received");
                    break;
                }
            }
        }

        info!("trading engine stopped");
    }
}
```

