## `src/risk.rs`

```rust
use crate::types::{NewOrder, OrderType, Side};
use anyhow::Result;
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

#[derive(Debug)]
pub struct RiskEngine {
    limits: RiskLimits,
    positions: HashMap<String, f64>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: HashMap::new(),
        }
    }

    pub fn check_order(&self, order: &NewOrder, reference_price: f64) -> Result<()> {
        if order.qty <= 0.0 {
            anyhow::bail!("qty must be positive");
        }

        if order.qty > self.limits.max_order_qty {
            anyhow::bail!("order qty exceeds limit");
        }

        let notional = match order.order_type {
            OrderType::Market => order.qty * reference_price,
            OrderType::Limit { price } => order.qty * price,
        };

        if notional > self.limits.max_notional {
            anyhow::bail!("order notional exceeds limit");
        }

        Ok(())
    }

    pub fn on_fill(&mut self, symbol: &str, side: &Side, qty: f64) {
        let pos = self.positions.entry(symbol.to_string()).or_insert(0.0);
        match side {
            Side::Buy => *pos += qty,
            Side::Sell => *pos -= qty,
        }
    }
}
```

