## `src/oms.rs`

```rust
use crate::types::{NewOrder, OrderId, OrderStatus, OrderUpdate};
use dashmap::DashMap;
use uuid::Uuid;

#[derive(Debug, Clone)]
pub struct OrderRecord {
    pub order_id: OrderId,
    pub order: NewOrder,
    pub status: OrderStatus,
}

pub struct OrderManager {
    orders: DashMap<OrderId, OrderRecord>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            orders: DashMap::new(),
        }
    }

    pub fn submit(&self, order: NewOrder) -> OrderId {
        let order_id = Uuid::new_v4();
        let record = OrderRecord {
            order_id,
            order,
            status: OrderStatus::New,
        };
        self.orders.insert(order_id, record);
        order_id
    }

    pub fn update(&self, update: OrderUpdate) {
        if let Some(mut rec) = self.orders.get_mut(&update.order_id) {
            rec.status = update.status;
        }
    }

    pub fn get(&self, order_id: &OrderId) -> Option<OrderRecord> {
        self.orders.get(order_id).map(|r| r.clone())
    }
}
