use crate::types::{MarketTick, NewOrder, OrderType, Side};
use uuid::Uuid;

pub struct StrategyEngine {
    pub spread_threshold: f64,
    pub order_qty: f64,
}

impl StrategyEngine {
    pub fn new(spread_threshold: f64, order_qty: f64) -> Self {
        Self {
            spread_threshold,
            order_qty,
        }
    }

    pub fn on_tick(&self, tick: &MarketTick) -> Option<NewOrder> {
        let spread = tick.ask - tick.bid;
        if spread <= self.spread_threshold {
            Some(NewOrder {
                client_order_id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                order_type: OrderType::Limit {
                    price: tick.bid,
                },
            })
        } else {
            None
        }
    }
}
