## `src/gateway/market_data.rs`

```rust
use crate::types::MarketTick;
use anyhow::Result;
use tokio::net::TcpListener;
use tokio::io::AsyncReadExt;
use tracing::info;

pub async fn run_market_data_listener(addr: &str) -> Result<()> {
    let listener = TcpListener::bind(addr).await?;
    info!("market data listener on {}", addr);

    loop {
        let (mut socket, peer) = listener.accept().await?;
        info!("market data connection from {}", peer);

        tokio::spawn(async move {
            let mut buf = vec![0u8; 4096];
            loop {
                match socket.read(&mut buf).await {
                    Ok(0) => break,
                    Ok(n) => {
                        let payload = &buf[..n];
                        if let Ok(tick) = serde_json::from_slice::<MarketTick>(payload) {
                            tracing::debug!("tick {:?}", tick);
                        }
                    }
                    Err(e) => {
                        tracing::warn!("market data read error: {}", e);
                        break;
                    }
                }
            }
        });
    }
}
