use anyhow::Result;
use std::fs::OpenOptions;
use std::io::Write;
use std::sync::Mutex;

pub struct EventLog {
    file: Mutex<std::fs::File>,
}

impl EventLog {
    pub fn new(path: &str) -> Result<Self> {
        let file = OpenOptions::new()
            .create(true)
            .append(true)
            .open(path)?;
        Ok(Self {
            file: Mutex::new(file),
        })
    }

    pub fn append_json<T: serde::Serialize>(&self, event: &T) -> Result<()> {
        let mut file = self.file.lock().unwrap();
        let line = serde_json::to_string(event)?;
        writeln!(file, "{}", line)?;
        Ok(())
    }
}
