This wires the components together.

```rust
mod bus;
mod config;
mod gateway;
mod metrics;
mod oms;
mod persistence;
mod risk;
mod strategy;
mod types;

use anyhow::Result;
use bus::EventBus;
use metrics::Metrics;
use oms::OrderManager;
use persistence::EventLog;
use risk::{RiskEngine, RiskLimits};
use strategy::StrategyEngine;
use tracing::{info, Level};
use tracing_subscriber::EnvFilter;
use types::{Event, MarketTick};

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive(Level::INFO.into()))
        .init();

    let metrics = Metrics::new();
    let event_log = EventLog::new("events.log")?;
    let order_manager = OrderManager::new();
    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 1000.0,
        max_notional: 1_000_000.0,
    });
    let strategy = StrategyEngine::new(0.02, 10.0);

    let (bus, rx) = EventBus::<Event>::new();

    let bus_clone = bus.clone();
    tokio::spawn(async move {
        // Demo tick generator
        loop {
            let tick = MarketTick {
                symbol: "AAPL".to_string(),
                bid: 189.99,
                ask: 190.00,
                last: 189.995,
                ts_nanos: current_ts_nanos(),
            };
            let _ = bus_clone.publish(Event::Tick(tick));
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
    });

    let order_gateway = gateway::order::OrderGateway::new();

    info!("starting event loop");

    loop {
        let event = rx.recv()?;

        event_log.append_json(&event)?;

        match event {
            Event::Tick(tick) => {
                metrics.inc_ticks();

                if let Some(order) = strategy.on_tick(&tick) {
                    if let Err(e) = risk.check_order(&order, tick.last) {
                        metrics.inc_rejects();
                        tracing::warn!("risk reject: {}", e);
                        continue;
                    }

                    metrics.inc_orders();
                    let order_id = order_manager.submit(order.clone());
                    let update = order_gateway.send_order(&order).await?;
                    order_manager.update(update);
                    tracing::info!("order submitted {:?} -> {:?}", order_id, order.client_order_id);
                }
            }
            Event::NewOrder(order) => {
                if let Err(e) = risk.check_order(&order, 0.0) {
                    metrics.inc_rejects();
                    tracing::warn!("risk reject: {}", e);
                } else {
                    metrics.inc_orders();
                    let order_id = order_manager.submit(order.clone());
                    let update = order_gateway.send_order(&order).await?;
                    order_manager.update(update);
                    tracing::info!("order submitted {:?}", order_id);
                }
            }
            Event::OrderUpdate(update) => {
                order_manager.update(update);
            }
        }
    }
}

fn current_ts_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64
}
```

