```rust
use std::sync::Arc;

use dashmap::DashMap;

use crate::types::{OrderRequest, Side};

#[derive(Clone)]
pub struct RiskEngine {
    max_order_qty: f64,
    max_notional: f64,
    positions: Arc<DashMap<String, f64>>,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn validate(&self, order: &OrderRequest) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }
        if order.qty > self.max_order_qty {
            return Err(format!("qty exceeds max_order_qty: {}", self.max_order_qty));
        }

        let notional = order.qty * order.price;
        if notional > self.max_notional {
            return Err(format!("notional exceeds max_notional: {}", self.max_notional));
        }

        // Example position check
        let current_pos = self.positions.get(&order.symbol).map(|v| *v).unwrap_or(0.0);
        let projected = match order.side {
            Side::Buy => current_pos + order.qty,
            Side::Sell => current_pos - order.qty,
        };

        if projected.abs() > 1000.0 {
            return Err("position limit exceeded".into());
        }

        Ok(())
    }

    pub fn apply_fill(&self, symbol: &str, side: &Side, qty: f64) {
        let mut entry = self.positions.entry(symbol.to_string()).or_insert(0.0);
        match side {
            Side::Buy => *entry += qty,
            Side::Sell => *entry -= qty,
        }
    }
}
