#[derive(Clone)]
pub struct OrderManager {
    orders: Arc<DashMap<Uuid, OrderStatus>>,
}

impl OrderManager {
    pub fn new() -> Self {
        Self {
            orders: Arc::new(DashMap::new()),
        }
    }

    pub fn register(&self, order: &OrderRequest) {
        self.orders.insert(order.id, OrderStatus::New);
    }

    pub fn update(&self, update: OrderUpdate) {
        self.orders.insert(update.order_id, update.status);
    }

    pub fn get_status(&self, id: &Uuid) -> Option<OrderStatus> {
        self.orders.get(id).map(|s| s.clone())
    }
}
