async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (bus, mut rx) = EventBus::new(1024);

    let strategy = SimpleMeanReversionStrategy {
        symbol: "AAPL".to_string(),
        threshold: 100.0,
    };

    let risk = RiskEngine::new(100.0, 50_000.0);
    let oms = OrderManager::new();
    let exec = ExecutionGateway::new();

    // Simulated market data producer
    let producer = bus.clone();
    tokio::spawn(async move {
        let ticks = vec![
            MarketTick { symbol: "AAPL".into(), bid: 99.5, ask: 99.6, ts_nanos: now_nanos() },
            MarketTick { symbol: "AAPL".into(), bid: 101.2, ask: 101.3, ts_nanos: now_nanos() },
            MarketTick { symbol: "AAPL".into(), bid: 100.1, ask: 100.2, ts_nanos: now_nanos() },
        ];

        for tick in ticks {
            producer.publish(Event::Tick(tick)).await;
        }
    });

    while let Some(event) = rx.recv().await {
        if let Some(order) = strategy.on_event(&event) {
            oms.register(&order);

            match risk.validate(&order) {
                Ok(_) => {
                    let update = exec.send_order(&order).await;
                    oms.update(update.clone());
                    info!("order accepted: {:?}", update);
                }
                Err(reason) => {
                    warn!("risk rejected order {}: {}", order.id, reason);
                }
            }
        }
    }
}

