use tokio::sync::mpsc;

use crate::types::{MarketTick, Order, Fill, Signal};

#[derive(Debug)]
pub struct EventBus {
    pub market_tx: mpsc::Sender<MarketTick>,
    pub signal_tx: mpsc::Sender<Signal>,
    pub order_tx: mpsc::Sender<Order>,
    pub fill_tx: mpsc::Sender<Fill>,
}

#[derive(Debug)]
pub struct EventBusReceivers {
    pub market_rx: mpsc::Receiver<MarketTick>,
    pub signal_rx: mpsc::Receiver<Signal>,
    pub order_rx: mpsc::Receiver<Order>,
    pub fill_rx: mpsc::Receiver<Fill>,
}

pub fn new_bus(buffer: usize) -> (EventBus, EventBusReceivers) {
    let (market_tx, market_rx) = mpsc::channel(buffer);
    let (signal_tx, signal_rx) = mpsc::channel(buffer);
    let (order_tx, order_rx) = mpsc::channel(buffer);
    let (fill_tx, fill_rx) = mpsc::channel(buffer);

    (
        EventBus {
            market_tx,
            signal_tx,
            order_tx,
            fill_tx,
        },
        EventBusReceivers {
            market_rx,
            signal_rx,
            order_rx,
            fill_rx,
        },
    )
}
