use crate::types::{MarketTick, Signal};

pub struct SimpleStrategy {
    pub symbol: String,
    pub threshold: f64,
}

impl SimpleStrategy {
    pub fn on_tick(&self, tick: &MarketTick) -> Option<Signal> {
        if tick.symbol != self.symbol {
            return None;
        }

        let mid = (tick.bid + tick.ask) / 2.0;

        if tick.last > mid + self.threshold {
            Some(Signal::Sell {
                symbol: tick.symbol.clone(),
                qty: 10,
            })
        } else if tick.last < mid - self.threshold {
            Some(Signal::Buy {
                symbol: tick.symbol.clone(),
                qty: 10,
            })
        } else {
            None
        }
    }
}
