```rust
use std::collections::HashMap;

use crate::types::{Order, Side};

pub struct RiskEngine {
    pub max_position: i64,
    pub positions: HashMap<String, i64>,
}

impl RiskEngine {
    pub fn new(max_position: i64) -> Self {
        Self {
            max_position,
            positions: HashMap::new(),
        }
    }

    pub fn check_order(&self, order: &Order) -> bool {
        let current = *self.positions.get(&order.symbol).unwrap_or(&0);
        let delta = match order.side {
            Side::Buy => order.qty as i64,
            Side::Sell => -(order.qty as i64),
        };

        let projected = current + delta;
        projected.abs() <= self.max_position
    }

    pub fn on_fill(&mut self, symbol: &str, side: &Side, qty: u64) {
        let entry = self.positions.entry(symbol.to_string()).or_insert(0);
        match side {
            Side::Buy => *entry += qty as i64,
            Side::Sell => *entry -= qty as i64,
        }
    }
}
