```rust
mod bus;
mod execution;
mod oms;
mod risk;
mod strategy;
mod types;

use bus::new_bus;
use execution::ExecutionGateway;
use oms::OrderManager;
use risk::RiskEngine;
use strategy::SimpleStrategy;
use types::{MarketTick, Signal};

use tracing::{info, warn};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let (bus, mut rx) = new_bus(1024);

    let strategy = SimpleStrategy {
        symbol: "AAPL".to_string(),
        threshold: 0.05,
    };

    let mut risk = RiskEngine::new(1000);

    let market_tx = bus.market_tx.clone();
    let signal_tx = bus.signal_tx.clone();
    let order_tx = bus.order_tx.clone();
    let fill_tx = bus.fill_tx.clone();

    // Market data producer
    tokio::spawn(async move {
        let mut price = 100.0;
        loop {
            price += 0.01;
            let tick = MarketTick {
                symbol: "AAPL".to_string(),
                bid: price - 0.01,
                ask: price + 0.01,
                last: price,
                ts_nanos: now_nanos(),
            };

            if market_tx.send(tick).await.is_err() {
                break;
            }

            tokio::time::sleep(tokio::time::Duration::from_millis(10)).await;
        }
    });

    // Strategy engine
    let strategy_task = {
        let mut market_rx = rx.market_rx;
        let signal_tx = signal_tx.clone();

        tokio::spawn(async move {
            while let Some(tick) = market_rx.recv().await {
                if let Some(signal) = strategy.on_tick(&tick) {
                    if signal_tx.send(signal).await.is_err() {
                        break;
                    }
                }
            }
        })
    };

    // OMS + risk + execution
    let oms_task = {
        let mut signal_rx = rx.signal_rx;
        let order_tx = order_tx.clone();

        tokio::spawn(async move {
            while let Some(signal) = signal_rx.recv().await {
                let order = OrderManager::from_signal(signal);
                if order_tx.send(order).await.is_err() {
                    break;
                }
            }
        })
    };

    let exec_task = {
        let mut order_rx = rx.order_rx;
        let fill_tx = fill_tx.clone();

        tokio::spawn(async move {
            while let Some(order) = order_rx.recv().await {
                if risk.check_order(&order) {
                    let fill = ExecutionGateway::send_order(&order).await;
                    if fill_tx.send(fill).await.is_err() {
                        break;
                    }
                } else {
                    warn!("Risk rejected order: {:?}", order);
                }
            }
        })
    };

    // Fill handler
    let fill_task = tokio::spawn(async move {
        while let Some(fill) = rx.fill_rx.recv().await {
            info!("Fill received: {:?}", fill);
        }
    });

    let _ = tokio::join!(strategy_task, oms_task, exec_task, fill_task);
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64
}
```

