# `src/strategy.rs`

A basic strategy: if spread is tight and price is rising, buy; if falling, sell.

```rust
use crate::bus::Bus;
use crate::domain::{MarketTick, Order, OrderType, Signal, Side};
use uuid::Uuid;
use tracing::info;

pub async fn run_strategy(
    mut md_rx: tokio::sync::broadcast::Receiver<MarketTick>,
    signal_bus: Bus<Signal>,
) {
    let mut last_mid: Option<f64> = None;

    loop {
        match md_rx.recv().await {
            Ok(tick) => {
                let mid = (tick.bid + tick.ask) / 2.0;
                let spread = tick.ask - tick.bid;

                let signal = if spread <= 0.05 {
                    if let Some(prev) = last_mid {
                        if mid > prev {
                            Signal::Buy {
                                instrument: tick.instrument.clone(),
                                qty: 10.0,
                            }
                        } else if mid < prev {
                            Signal::Sell {
                                instrument: tick.instrument.clone(),
                                qty: 10.0,
                            }
                        } else {
                            Signal::Hold
                        }
                    } else {
                        Signal::Hold
                    }
                } else {
                    Signal::Hold
                };

                last_mid = Some(mid);

                info!("strategy signal: {:?}", signal);
                signal_bus.publish(signal);
            }
            Err(_) => break,
        }
    }
}
