use crate::domain::{Order, Signal, Side, OrderType};
use uuid::Uuid;

#[derive(Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

pub fn check_signal(signal: Signal, limits: &RiskLimits, last_price: f64) -> Option<Order> {
    match signal {
        Signal::Buy { instrument, qty } => {
            if qty <= limits.max_order_qty && qty * last_price <= limits.max_notional {
                Some(Order {
                    id: Uuid::new_v4(),
                    instrument,
                    side: Side::Buy,
                    qty,
                    order_type: OrderType::Market,
                    ts_nanos: now_nanos(),
                })
            } else {
                None
            }
        }
        Signal::Sell { instrument, qty } => {
            if qty <= limits.max_order_qty && qty * last_price <= limits.max_notional {
                Some(Order {
                    id: Uuid::new_v4(),
                    instrument,
                    side: Side::Sell,
                    qty,
                    order_type: OrderType::Market,
                    ts_nanos: now_nanos(),
                })
            } else {
                None
            }
        }
        Signal::Hold => None,
    }
}

