use crate::domain::{Fill, Order, OrderType, Side};
use tracing::info;

pub async fn execute_order(order: Order) -> Fill {
    let price = match order.order_type {
        OrderType::Market => 100.0, // placeholder
        OrderType::Limit { price } => price,
    };

    info!("executing order: {:?}", order);

    Fill {
        order_id: order.id,
        instrument: order.instrument,
        side: order.side,
        qty: order.qty,
        price,
        ts_nanos: now_nanos(),
    }
}

fn now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
