This wires everything together.

```rust
use crate::bus::Bus;
use crate::domain::{MarketTick, Signal};
use crate::risk::{check_signal, RiskLimits};
use crate::execution::execute_order;
use tracing::{info, warn};

pub async fn run_engine(
    mut signal_rx: tokio::sync::broadcast::Receiver<Signal>,
    md_bus: Bus<MarketTick>,
) {
    let limits = RiskLimits {
        max_order_qty: 100.0,
        max_notional: 50_000.0,
    };

    let mut last_price: f64 = 100.0;

    let mut md_rx = md_bus.subscribe();
    tokio::spawn(async move {
        while let Ok(tick) = md_rx.recv().await {
            last_price = (tick.bid + tick.ask) / 2.0;
        }
    });

    loop {
        match signal_rx.recv().await {
            Ok(signal) => {
                if let Some(order) = check_signal(signal, &limits, last_price) {
                    let fill = execute_order(order).await;
                    info!("fill: {:?}", fill);
                } else {
                    warn!("signal rejected by risk or hold");
                }
            }
            Err(_) => break,
        }
    }
}
