## 7) Risk engine

### `src/risk.rs`

```rust
use crate::types::{Order, Side};
use dashmap::DashMap;
use std::sync::Arc;

#[derive(Clone)]
pub struct RiskEngine {
    max_order_qty: f64,
    max_notional: f64,
    positions: Arc<DashMap<String, f64>>,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn validate_order(&self, order: &Order, market_price: f64) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }

        if order.qty > self.max_order_qty {
            return Err(format!("qty exceeds max_order_qty: {}", self.max_order_qty));
        }

        let notional = order.qty * market_price;
        if notional > self.max_notional {
            return Err(format!("notional exceeds max_notional: {}", self.max_notional));
        }

        // Example position check
        let current_pos = self.positions.get(&order.symbol).map(|v| *v).unwrap_or(0.0);
        match order.side {
            Side::Buy => {
                let projected = current_pos + order.qty;
                if projected.abs() > self.max_order_qty * 10.0 {
                    return Err("projected position too large".into());
                }
            }
            Side::Sell => {
                let projected = current_pos - order.qty;
                if projected.abs() > self.max_order_qty * 10.0 {
                    return Err("projected position too large".into());
                }
            }
        }

        Ok(())
    }

    pub fn update_position(&self, symbol: &str, delta_qty: f64) {
        self.positions
            .entry(symbol.to_string())
            .and_modify(|v| *v += delta_qty)
            .or_insert(delta_qty);
    }
}
```

