## 8) Strategy engine

This example strategy is a simple spread-based mean reversion placeholder.

### `src/strategy.rs`

```rust
use crate::types::{MarketTick, Order, OrderType, Side};
use uuid::Uuid;

pub struct StrategyEngine {
    pub strategy_id: String,
    pub threshold: f64,
    pub order_qty: f64,
}

impl StrategyEngine {
    pub fn new(strategy_id: impl Into<String>, threshold: f64, order_qty: f64) -> Self {
        Self {
            strategy_id: strategy_id.into(),
            threshold,
            order_qty,
        }
    }

    pub fn on_tick(&self, tick: &MarketTick) -> Option<Order> {
        let mid = (tick.bid + tick.ask) / 2.0;
        let spread = tick.ask - tick.bid;

        if spread > self.threshold {
            // Example: buy if spread is wide and price is near bid
            return Some(Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                price: Some(tick.bid),
                order_type: OrderType::Limit,
                strategy_id: self.strategy_id.clone(),
                ts_nanos: tick.ts_nanos,
            });
        }

        if tick.last > mid + self.threshold {
            return Some(Order {
                id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: self.order_qty,
                price: Some(tick.ask),
                order_type: OrderType::Limit,
                strategy_id: self.strategy_id.clone(),
                ts_nanos: tick.ts_nanos,
            });
        }

        None
    }
}
```

