use crate::types::MarketTick;
use tokio::time::{interval, Duration};
use uuid::Uuid;

pub async fn run_market_data_feed(symbol: String, mut publish: impl FnMut(MarketTick) + Send + 'static) {
    let mut timer = interval(Duration::from_millis(10));
    let mut px = 100.0;

    loop {
        timer.tick().await;

        px += 0.01;
        let tick = MarketTick {
            symbol: symbol.clone(),
            bid: px - 0.01,
            ask: px + 0.01,
            last: px,
            ts_nanos: current_ts_nanos(),
        };

        publish(tick);
    }
}

fn current_ts_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
