```rust
mod bus;
mod execution;
mod market_data;
mod oms;
mod risk;
mod strategy;
mod types;

use execution::ExecutionGateway;
use oms::OrderManager;
use risk::RiskEngine;
use strategy::StrategyEngine;
use tokio::sync::mpsc;
use tracing::{info, warn};
use types::{MarketTick, OrderEvent};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let strategy = StrategyEngine::new("mean_reversion_1", 0.03, 10.0);
    let risk = RiskEngine::new(1000.0, 100_000.0);
    let oms = OrderManager::new();
    let exec = ExecutionGateway::new();

    let (tick_bus, mut tick_rx) = bus::Bus::<MarketTick>::new(1024);
    let (order_bus, mut order_rx) = bus::Bus::<types::Order>::new(1024);
    let (event_bus, mut event_rx) = bus::Bus::<OrderEvent>::new(1024);

    let tick_bus_clone = tick_bus.clone();
    tokio::spawn(async move {
        market_data::run_market_data_feed("AAPL".to_string(), move |tick| {
            let tick_bus = tick_bus_clone.clone();
            tokio::spawn(async move {
                let _ = tick_bus.publish(tick).await;
            });
        })
        .await;
    });

    let strategy_task = {
        let order_bus = order_bus.clone();
        tokio::spawn(async move {
            while let Some(tick) = tick_rx.recv().await {
                if let Some(order) = strategy.on_tick(&tick) {
                    let _ = order_bus.publish(order).await;
                }
            }
        })
    };

    let risk_task = {
        let event_bus = event_bus.clone();
        let oms = oms.clone();
        tokio::spawn(async move {
            while let Some(order) = order_rx.recv().await {
                let market_price = order.price.unwrap_or(100.0);

                match risk.validate_order(&order, market_price) {
                    Ok(_) => {
                        oms.submit(&order);
                        let event = exec.send_order(&order).await;
                        let _ = event_bus.publish(event).await;
                    }
                    Err(reason) => {
                        warn!("order rejected: {} {:?}", reason, order);
                    }
                }
            }
        })
    };

    let event_task = {
        let oms = oms.clone();
        tokio::spawn(async move {
            while let Some(event) = event_rx.recv().await {
                oms.on_event(&event);
                info!("order event: {:?}", event);
            }
        })
    };

    let _ = tokio::join!(strategy_task, risk_task, event_task);
}
```

