```rust
use std::sync::Arc;

use dashmap::DashMap;
use uuid::Uuid;

use crate::types::{OrderIntent, Side};

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: f64,
    pub max_notional: f64,
    pub max_position_abs: f64,
}

#[derive(Debug)]
pub enum RiskError {
    OrderQtyTooLarge,
    NotionalTooLarge,
    PositionLimitExceeded,
}

#[derive(Clone)]
pub struct RiskEngine {
    limits: RiskLimits,
    positions: Arc<DashMap<String, f64>>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn check_order(&self, order: &OrderIntent, market_price: f64) -> Result<(), RiskError> {
        if order.qty > self.limits.max_order_qty {
            return Err(RiskError::OrderQtyTooLarge);
        }

        let notional = order.qty * market_price;
        if notional > self.limits.max_notional {
            return Err(RiskError::NotionalTooLarge);
        }

        let current_pos = self.positions.get(&order.symbol).map(|v| *v).unwrap_or(0.0);
        let projected = match order.side {
            Side::Buy => current_pos + order.qty,
            Side::Sell => current_pos - order.qty,
        };

        if projected.abs() > self.limits.max_position_abs {
            return Err(RiskError::PositionLimitExceeded);
        }

        Ok(())
    }

    pub fn apply_fill(&self, symbol: &str, side: &Side, filled_qty: f64) {
        let mut entry = self.positions.entry(symbol.to_string()).or_insert(0.0);
        match side {
            Side::Buy => *entry += filled_qty,
            Side::Sell => *entry -= filled_qty,
        }
    }

    pub fn position(&self, symbol: &str) -> f64 {
        self.positions.get(symbol).map(|v| *v).unwrap_or(0.0)
    }
}
