## `src/strategy.rs`

A simple example strategy: if spread is tight and price moves, generate a limit order.

```rust
use uuid::Uuid;

use crate::types::{OrderIntent, OrderType, Side, Tick};

pub trait Strategy: Send + Sync {
    fn on_tick(&self, tick: &Tick) -> Option<OrderIntent>;
}

#[derive(Clone)]
pub struct MeanReversionStrategy {
    pub symbol: String,
    pub threshold: f64,
    pub qty: f64,
}

impl Strategy for MeanReversionStrategy {
    fn on_tick(&self, tick: &Tick) -> Option<OrderIntent> {
        if tick.symbol != self.symbol {
            return None;
        }

        let mid = (tick.bid + tick.ask) / 2.0;
        let spread = tick.ask - tick.bid;

        if spread <= self.threshold {
            let side = if tick.last < mid { Side::Buy } else { Side::Sell };

            return Some(OrderIntent {
                client_order_id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side,
                qty: self.qty,
                order_type: OrderType::Limit,
                limit_price: Some(mid),
            });
        }

        None
    }
}
