use std::sync::Arc;

use dashmap::DashMap;
use uuid::Uuid;

use crate::{
    execution::ExecutionGateway,
    risk::RiskEngine,
    types::{Order, OrderIntent, OrderStatus, OrderUpdate, Tick},
};

#[derive(Clone)]
pub struct Oms {
    orders: Arc<DashMap<Uuid, OrderStatus>>,
    risk: RiskEngine,
    exec: ExecutionGateway,
}

impl Oms {
    pub fn new(risk: RiskEngine, exec: ExecutionGateway) -> Self {
        Self {
            orders: Arc::new(DashMap::new()),
            risk,
            exec,
        }
    }

    pub async fn submit(&self, intent: OrderIntent, market_price: f64) -> Result<OrderUpdate, String> {
        self.risk
            .check_order(&intent, market_price)
            .map_err(|e| format!("risk rejected: {:?}", e))?;

        let order = Order {
            order_id: Uuid::new_v4(),
            client_order_id: intent.client_order_id,
            symbol: intent.symbol.clone(),
            side: intent.side.clone(),
            qty: intent.qty,
            order_type: intent.order_type.clone(),
            limit_price: intent.limit_price,
        };

        self.orders.insert(order.order_id, OrderStatus::New);

        let ack = self.exec.send_order(order.clone()).await;
        self.orders.insert(order.order_id, ack.status.clone());

        Ok(ack)
    }

    pub fn on_update(&self, update: &OrderUpdate) {
        self.orders.insert(update.order_id, update.status.clone());
    }
}
