pub async fn run_market_data(bus: EventBus, symbol: String) {
    let mut px = 100.0;
    let mut iv = interval(Duration::from_millis(10));

    loop {
        iv.tick().await;

        px += 0.01;
        let tick = Tick {
            symbol: symbol.clone(),
            bid: px - 0.01,
            ask: px + 0.01,
            last: px,
            ts_nanos: now_nanos(),
        };

        bus.publish(Event::Tick(tick));
    }
}
