use std::sync::Arc;

use tracing::{error, info};

use bus::{Event, EventBus};
use execution::ExecutionGateway;
use market_data::run_market_data;
use metrics::Metrics;
use oms::Oms;
use risk::{RiskEngine, RiskLimits};
use strategy::{MeanReversionStrategy, Strategy};

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let bus = EventBus::new(1024);
    let metrics = Arc::new(Metrics::default());

    let risk = RiskEngine::new(RiskLimits {
        max_order_qty: 100.0,
        max_notional: 50_000.0,
        max_position_abs: 500.0,
    });

    let exec = ExecutionGateway::new();
    let oms = Oms::new(risk.clone(), exec.clone());

    let strategy = MeanReversionStrategy {
        symbol: "AAPL".to_string(),
        threshold: 0.05,
        qty: 10.0,
    };

    let bus_md = bus.clone();
    tokio::spawn(async move {
        run_market_data(bus_md, "AAPL".to_string()).await;
    });

    let mut rx = bus.subscribe();
    let oms_clone = oms.clone();
    let metrics_clone = metrics.clone();

    tokio::spawn(async move {
        loop {
            match rx.recv().await {
                Ok(Event::Tick(tick)) => {
                    metrics_clone.inc_ticks();

                    if let Some(intent) = strategy.on_tick(&tick) {
                        metrics_clone.inc_orders();

                        match oms_clone.submit(intent, tick.last).await {
                            Ok(update) => {
                                info!("order ack: {:?}", update);
                            }
                            Err(e) => {
                                metrics_clone.inc_rejects();
                                error!("order rejected: {}", e);
                            }
                        }
                    }
                }
                Ok(Event::OrderUpdate(update)) => {
                    oms_clone.on_update(&update);
                }
                Ok(Event::OrderIntent(_)) => {}
                Err(_) => break,
            }
        }
    });

    loop {
        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
        info!(
            "metrics: ticks={}, orders={}, rejects={}, fills={}",
            metrics.ticks.load(std::sync::atomic::Ordering::Relaxed),
            metrics.orders.load(std::sync::atomic::Ordering::Relaxed),
            metrics.rejects.load(std::sync::atomic::Ordering::Relaxed),
            metrics.fills.load(std::sync::atomic::Ordering::Relaxed),
        );
    }
}
