type Service struct {
	mu      sync.RWMutex
	limits  Limits
	// in-memory example; replace with distributed state later
	userExposure map[string]int64
}

func NewService(l Limits) *Service {
	return &Service{
		limits:       l,
		userExposure: make(map[string]int64),
	}
}

func (s *Service) Check(order *common.Order) error {
	if order.Quantity > s.limits.MaxOrderQty {
		return ErrRiskLimitExceeded
	}
	notional := order.Quantity * order.Price
	if order.Type == common.Market {
		// market orders need reference price in real implementation
		notional = order.Quantity
	}
	if notional > s.limits.MaxNotional {
		return ErrRiskLimitExceeded
	}
	return nil
}

func (s *Service) ApplyFill(userID string, deltaNotional int64) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.userExposure[userID] += deltaNotional
}
