## `internal/matching/orderbook.go`
```go
package matching

import (
	"container/heap"
	"trading-platform/internal/common"
)

type OrderBook struct {
	Bids *BidHeap
	Asks *AskHeap
}

func NewOrderBook() *OrderBook {
	b := &BidHeap{}
	a := &AskHeap{}
	heap.Init(b)
	heap.Init(a)
	return &OrderBook{Bids: b, Asks: a}
}

type BidHeap []*common.Order
type AskHeap []*common.Order

func (h BidHeap) Len() int { return len(h) }
func (h BidHeap) Less(i, j int) bool {
	if h[i].Price == h[j].Price {
		return h[i].CreatedAt.Before(h[j].CreatedAt)
	}
	return h[i].Price > h[j].Price
}
func (h BidHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *BidHeap) Push(x any) { *h = append(*h, x.(*common.Order)) }
func (h *BidHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}

func (h AskHeap) Len() int { return len(h) }
func (h AskHeap) Less(i, j int) bool {
	if h[i].Price == h[j].Price {
		return h[i].CreatedAt.Before(h[j].CreatedAt)
	}
	return h[i].Price < h[j].Price
}
func (h AskHeap) Swap(i, j int) { h[i], h[j] = h[j], h[i] }
func (h *AskHeap) Push(x any) { *h = append(*h, x.(*common.Order)) }
func (h *AskHeap) Pop() any {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[:n-1]
	return x
}
```

## `internal/matching/engine.go`
```go
package matching

import (
	"container/heap"
	"time"

	"trading-platform/internal/common"
)

type Engine struct {
	symbol string
	book   *OrderBook
	trades chan common.Trade
}

func NewEngine(symbol string, trades chan common.Trade) *Engine {
	return &Engine{
		symbol: symbol,
		book:   NewOrderBook(),
		trades: trades,
	}
}

func (e *Engine) Process(order *common.Order) []common.Trade {
	var executed []common.Trade

	if order.Symbol != e.symbol {
		return executed
	}

	switch order.Side {
	case common.Buy:
		executed = append(executed, e.matchBuy(order)...)
		if order.Quantity > order.FilledQty {
			heap.Push(e.book.Bids, order)
		}
	case common.Sell:
		executed = append(executed, e.matchSell(order)...)
		if order.Quantity > order.FilledQty {
			heap.Push(e.book.Asks, order)
		}
	}

	for _, t := range executed {
		select {
		case e.trades <- t:
		default:
			// drop or buffer depending on policy; better to use bounded queue + backpressure
		}
	}

	return executed
}

func (e *Engine) matchBuy(order *common.Order) []common.Trade {
	var trades []common.Trade
	for e.book.Asks.Len() > 0 && order.FilledQty < order.Quantity {
		bestAsk := (*(e.book.Asks))[0]
		if order.Type == common.Limit && bestAsk.Price > order.Price {
			break
		}
		heap.Pop(e.book.Asks)

		remainingBuy := order.Quantity - order.FilledQty
		remainingSell := bestAsk.Quantity - bestAsk.FilledQty
		qty := min(remainingBuy, remainingSell)

		order.FilledQty += qty
		bestAsk.FilledQty += qty

		trades = append(trades, common.Trade{
			TradeID:    newID(),
			Symbol:     order.Symbol,
			BuyOrderID: order.ID,
			SellOrderID: bestAsk.ID,
			Price:      bestAsk.Price,
			Quantity:   qty,
			ExecutedAt: time.Now().UTC(),
		})

		if bestAsk.FilledQty < bestAsk.Quantity {
			heap.Push(e.book.Asks, bestAsk)
		}
	}
	return trades
}

func (e *Engine) matchSell(order *common.Order) []common.Trade {
	var trades []common.Trade
	for e.book.Bids.Len() > 0 && order.FilledQty < order.Quantity {
		bestBid := (*(e.book.Bids))[0]
		if order.Type == common.Limit && bestBid.Price < order.Price {
			break
		}
		heap.Pop(e.book.Bids)

		remainingSell := order.Quantity - order.FilledQty
		remainingBuy := bestBid.Quantity - bestBid.FilledQty
		qty := min(remainingSell, remainingBuy)

		order.FilledQty += qty
		bestBid.FilledQty += qty

		trades = append(trades, common.Trade{
			TradeID:    newID(),
			Symbol:     order.Symbol,
			BuyOrderID: bestBid.ID,
			SellOrderID: order.ID,
			Price:      bestBid.Price,
			Quantity:   qty,
			ExecutedAt: time.Now().UTC(),
		})

		if bestBid.FilledQty < bestBid.Quantity {
			heap.Push(e.book.Bids, bestBid)
		}
	}
	return trades
}

func min(a, b int64) int64 {
	if a < b {
		return a
	}
	return b
}

func newID() string {
	return time.Now().UTC().Format("20060102150405.000000000")
}
