func NewService(repo Repository, pub EventPublisher, riskSvc *risk.Service) *Service {
	return &Service{
		validator: &Validator{},
		risk:      riskSvc,
		repo:      repo,
		pub:       pub,
	}
}

func (s *Service) PlaceOrder(o *common.Order) error {
	o.CreatedAt = time.Now().UTC()
	o.Status = common.New

	if err := s.validator.Validate(o); err != nil {
		o.Status = common.Rejected
		return err
	}
	if err := s.risk.Check(o); err != nil {
		o.Status = common.Rejected
		return err
	}
	o.Status = common.Accepted

	if err := s.repo.SaveOrder(o); err != nil {
		return err
	}

	// publish event for matching engine
	// in production, use outbox pattern for atomicity
	return s.pub.Publish(common.Event{
		ID:        o.ID,
		Type:      common.OrderPlacedEvent,
		Key:       o.Symbol,
		Timestamp: time.Now().UTC(),
	})
}
