```go
package bus

import (
	"sync"

	"trading-platform/internal/common"
)

type Bus struct {
	mu   sync.RWMutex
	subs map[string][]chan common.Event
}

func NewBus() *Bus {
	return &Bus{subs: make(map[string][]chan common.Event)}
}

func (b *Bus) Subscribe(topic string) <-chan common.Event {
	ch := make(chan common.Event, 1024)
	b.mu.Lock()
	b.subs[topic] = append(b.subs[topic], ch)
	b.mu.Unlock()
	return ch
}

func (b *Bus) Publish(topic string, e common.Event) {
	b.mu.RLock()
	subs := append([]chan common.Event(nil), b.subs[topic]...)
	b.mu.RUnlock()

	for _, ch := range subs {
		select {
		case ch <- e:
		default:
			// backpressure policy needed
		}
	}
}
