use crate::types::{Order, Side};

#[derive(Debug, Clone)]
pub struct RiskLimits {
    pub max_order_qty: u64,
    pub max_notional: f64,
}

#[derive(Debug)]
pub struct RiskEngine {
    limits: RiskLimits,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self { limits }
    }

    pub fn check_order(&self, order: &Order, last_price: Option<f64>) -> Result<(), String> {
        if order.qty == 0 {
            return Err("qty must be > 0".to_string());
        }

        if order.qty > self.limits.max_order_qty {
            return Err(format!(
                "qty {} exceeds max_order_qty {}",
                order.qty, self.limits.max_order_qty
            ));
        }

        let px = match order.order_type {
            crate::types::OrderType::Market => last_price.ok_or("missing last price for market order")?,
            crate::types::OrderType::Limit => order.limit_price.ok_or("missing limit price")?,
        };

        let notional = px * order.qty as f64;
        if notional > self.limits.max_notional {
            return Err(format!(
                "notional {} exceeds max_notional {}",
                notional, self.limits.max_notional
            ));
        }

        match order.side {
            Side::Buy | Side::Sell => Ok(()),
        }
    }
}
