## `src/oms.rs`

```rust
use crate::{
    execution::ExecutionGateway,
    risk::RiskEngine,
    types::{Event, MarketTick, Order},
};
use std::collections::HashMap;
use tokio::sync::mpsc::{Receiver, Sender};
use tracing::{info, warn};

pub struct OrderManagementSystem {
    rx: Receiver<Event>,
    tx: Sender<Event>,
    risk: RiskEngine,
    exec: ExecutionGateway,
    last_prices: HashMap<String, f64>,
}

impl OrderManagementSystem {
    pub fn new(
        rx: Receiver<Event>,
        tx: Sender<Event>,
        risk: RiskEngine,
        exec: ExecutionGateway,
    ) -> Self {
        Self {
            rx,
            tx,
            risk,
            exec,
            last_prices: HashMap::new(),
        }
    }

    pub async fn run(mut self) {
        while let Some(event) = self.rx.recv().await {
            match event {
                Event::MarketTick(tick) => self.handle_tick(tick).await,
                Event::NewOrder(order) => self.handle_new_order(order).await,
                Event::Fill(fill) => {
                    info!("fill received: {:?}", fill);
                }
                _ => {}
            }
        }
    }

    async fn handle_tick(&mut self, tick: MarketTick) {
        self.last_prices.insert(tick.symbol.clone(), (tick.bid + tick.ask) / 2.0);
    }

    async fn handle_new_order(&mut self, order: Order) {
        let last_price = self.last_prices.get(&order.symbol).copied();

        match self.risk.check_order(&order, last_price) {
            Ok(_) => {
                let _ = self.tx.send(Event::RiskApproved(order.clone())).await;
                let fill = self.exec.send_order(order.clone()).await;
                let _ = self.tx.send(Event::OrderSent(order)).await;
                let _ = self.tx.send(Event::Fill(fill)).await;
            }
            Err(reason) => {
                warn!("risk rejected order: {}", reason);
                let _ = self
                    .tx
                    .send(Event::RiskRejected {
                        order_id: order.id,
                        reason,
                    })
                    .await;
            }
        }
    }
}
