impl MarketDataFeed {
    pub fn new(tx: Sender<Event>) -> Self {
        Self { tx }
    }

    pub async fn run(self) {
        let mut timer = interval(Duration::from_millis(100));
        let mut px = 100.0;

        loop {
            timer.tick().await;
            px += 0.01;

            let tick = MarketTick {
                symbol: "AAPL".to_string(),
                bid: px - 0.02,
                ask: px + 0.03,
                ts_nanos: chrono_like_now_nanos(),
            };

            info!("tick: {:?}", tick);
            let _ = self.tx.send(Event::MarketTick(tick)).await;
        }
    }
}

fn chrono_like_now_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
