use crate::events::{MarketEvent, OrderRequest, Side};

pub trait Strategy: Send {
    fn on_market_event(&mut self, event: &MarketEvent) -> Vec<OrderRequest>;
}

pub struct MeanReversionStrategy {
    fair_value: f64,
    threshold: f64,
}

impl MeanReversionStrategy {
    pub fn new(fair_value: f64, threshold: f64) -> Self {
        Self { fair_value, threshold }
    }
}

impl Strategy for MeanReversionStrategy {
    fn on_market_event(&mut self, event: &MarketEvent) -> Vec<OrderRequest> {
        match event {
            MarketEvent::Tick(tick) => {
                let mut orders = Vec::new();

                if tick.price < self.fair_value - self.threshold {
                    orders.push(OrderRequest {
                        symbol: tick.symbol.clone(),
                        side: Side::Buy,
                        quantity: 10,
                        price: Some(tick.price),
                    });
                } else if tick.price > self.fair_value + self.threshold {
                    orders.push(OrderRequest {
                        symbol: tick.symbol.clone(),
                        side: Side::Sell,
                        quantity: 10,
                        price: Some(tick.price),
                    });
                }

                orders
            }
        }
    }
}
