pub trait RiskManager: Send {
    fn validate(&mut self, order: &OrderRequest) -> Result<(), String>;
}

pub struct BasicRiskManager {
    max_notional: f64,
    max_qty: u64,
    current_position: i64,
}

impl BasicRiskManager {
    pub fn new(max_notional: f64, max_qty: u64) -> Self {
        Self {
            max_notional,
            max_qty,
            current_position: 0,
        }
    }
}

impl RiskManager for BasicRiskManager {
    fn validate(&mut self, order: &OrderRequest) -> Result<(), String> {
        if order.quantity > self.max_qty {
            return Err(format!("Quantity exceeds max_qty: {}", order.quantity));
        }

        if let Some(price) = order.price {
            let notional = price * order.quantity as f64;
            if notional > self.max_notional {
                return Err(format!("Notional exceeds limit: {}", notional));
            }
        }

        match order.side {
            Side::Buy => self.current_position += order.quantity as i64,
            Side::Sell => self.current_position -= order.quantity as i64,
        }

        Ok(())
    }
}
