use crate::events::{OrderRequest, OrderStatus, OrderUpdate};
use std::sync::atomic::{AtomicU64, Ordering};

pub trait ExecutionGateway: Send {
    fn send_order(&mut self, order: &OrderRequest) -> OrderUpdate;
}

pub struct SimulatedExecutionGateway {
    next_order_id: AtomicU64,
}

impl SimulatedExecutionGateway {
    pub fn new() -> Self {
        Self {
            next_order_id: AtomicU64::new(1),
        }
    }
}

impl ExecutionGateway for SimulatedExecutionGateway {
    fn send_order(&mut self, _order: &OrderRequest) -> OrderUpdate {
        let order_id = self.next_order_id.fetch_add(1, Ordering::Relaxed);
        OrderUpdate {
            order_id,
            status: OrderStatus::Accepted,
        }
    }
}
