```java
package com.example.trading.strategy;

import com.example.trading.core.MarketEvent;
import com.example.trading.core.OrderEvent;

import java.util.concurrent.atomic.AtomicLong;

public final class MeanReversionStrategy implements Strategy {
    private final String symbol;
    private final double fairValue;
    private final double threshold;
    private final AtomicLong orderSeq = new AtomicLong(1);

    public MeanReversionStrategy(String symbol, double fairValue, double threshold) {
        this.symbol = symbol;
        this.fairValue = fairValue;
        this.threshold = threshold;
    }

    @Override
    public OrderEvent onMarketData(MarketEvent event) {
        if (!symbol.equals(event.symbol())) {
            return null;
        }

        double mid = (event.bid() + event.ask()) / 2.0;
        double diff = mid - fairValue;

        if (diff > threshold) {
            return new OrderEvent(
                    System.nanoTime(),
                    "ORD-" + orderSeq.getAndIncrement(),
                    symbol,
                    OrderEvent.Side.SELL,
                    100,
                    event.bid()
            );
        } else if (diff < -threshold) {
            return new OrderEvent(
                    System.nanoTime(),
                    "ORD-" + orderSeq.getAndIncrement(),
                    symbol,
                    OrderEvent.Side.BUY,
                    100,
                    event.ask()
            );
        }

        return null;
    }
}
```

