package com.example.trading.risk;

import com.example.trading.core.OrderEvent;

import java.util.concurrent.atomic.AtomicLong;

public final class BasicRiskEngine implements RiskEngine {
    private final long maxOrderSize;
    private final AtomicLong netPosition = new AtomicLong(0);

    public BasicRiskEngine(long maxOrderSize) {
        this.maxOrderSize = maxOrderSize;
    }

    @Override
    public boolean approve(OrderEvent order) {
        if (order.quantity() <= 0 || order.quantity() > maxOrderSize) {
            return false;
        }

        // Simplified position check
        long delta = order.side() == OrderEvent.Side.BUY ? order.quantity() : -order.quantity();
        long newPos = netPosition.addAndGet(delta);

        // Example hard limit
        if (Math.abs(newPos) > 10_000) {
            netPosition.addAndGet(-delta);
            return false;
        }

        return true;
    }
}
```

