package com.example.trading.marketdata;

import com.example.trading.core.MarketEvent;

import java.util.Random;

public final class SimulatedMarketDataFeed implements Runnable {
    private final MarketDataHandler handler;
    private final String symbol;
    private final Random random = new Random();
    private volatile boolean running = true;

    public SimulatedMarketDataFeed(MarketDataHandler handler, String symbol) {
        this.handler = handler;
        this.symbol = symbol;
    }

    public void stop() {
        running = false;
    }

    @Override
    public void run() {
        double price = 100.0;

        while (running) {
            price += (random.nextDouble() - 0.5) * 0.1;
            double bid = price - 0.01;
            double ask = price + 0.01;

            MarketEvent event = new MarketEvent(
                    System.nanoTime(),
                    symbol,
                    bid,
                    ask,
                    1000,
                    1000
            );

            handler.onMarketData(event);

            try {
                Thread.sleep(1); // simulation only
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }
}
