package com.example.trading;

import com.example.trading.bus.EventBus;
import com.example.trading.bus.InMemoryEventBus;
import com.example.trading.core.Event;
import com.example.trading.core.MarketEvent;
import com.example.trading.core.OrderEvent;
import com.example.trading.execution.SimulatedExecutionGateway;
import com.example.trading.marketdata.SimulatedMarketDataFeed;
import com.example.trading.oms.SimpleOrderManager;
import com.example.trading.risk.BasicRiskEngine;
import com.example.trading.strategy.MeanReversionStrategy;

public final class App {
    public static void main(String[] args) {
        EventBus bus = new InMemoryEventBus();

        BasicRiskEngine riskEngine = new BasicRiskEngine(1000);
        SimulatedExecutionGateway executionGateway = new SimulatedExecutionGateway(bus);
        SimpleOrderManager orderManager = new SimpleOrderManager(riskEngine, executionGateway);
        MeanReversionStrategy strategy = new MeanReversionStrategy("AAPL", 100.0, 0.05);

        bus.subscribe(event -> {
            if (event instanceof OrderEvent order) {
                orderManager.onOrder(order);
            } else if (event instanceof com.example.trading.core.TradeEvent trade) {
                System.out.println("Trade fill: " + trade.orderId() + " " + trade.symbol() + " " + trade.quantity() + " @ " + trade.price());
            }
        });

        SimulatedMarketDataFeed feed = new SimulatedMarketDataFeed(event -> {
            if (event instanceof MarketEvent md) {
                OrderEvent order = strategy.onMarketData(md);
                if (order != null) {
                    bus.publish(order);
                }
            }
        }, "AAPL");

        Thread feedThread = new Thread(feed, "md-feed");
        feedThread.start();

        Runtime.getRuntime().addShutdownHook(new Thread(feed::stop));
    }
}
