use crate::types::{OrderNew, Side};
use thiserror::Error;

#[derive(Debug, Error)]
pub enum RiskError {
    #[error("order quantity exceeds limit")]
    QtyLimitExceeded,
    #[error("order notional exceeds limit")]
    NotionalLimitExceeded,
}

#[derive(Clone)]
pub struct RiskEngine {
    pub max_qty: f64,
    pub max_notional: f64,
}

impl RiskEngine {
    pub fn new(max_qty: f64, max_notional: f64) -> Self {
        Self { max_qty, max_notional }
    }

    pub fn validate(&self, order: &OrderNew) -> Result<(), RiskError> {
        if order.qty > self.max_qty {
            return Err(RiskError::QtyLimitExceeded);
        }

        if let Some(price) = order.price {
            let notional = order.qty * price;
            if notional > self.max_notional {
                return Err(RiskError::NotionalLimitExceeded);
            }
        }

        Ok(())
    }
}
```

