use tracing::{info, warn};
use uuid::Uuid;

#[tokio::main]
async fn main() {
    init_tracing();

    let market_bus: EventBus<EventEnvelope<MarketDataTick>> = EventBus::new(1024);

    let strategy = SimpleStrategy::new(0.05);
    let risk = RiskEngine::new(10.0, 100_000.0);
    let execution = ExecutionGateway::new();
    let mut positions = PositionService::default();

    let mut rx = market_bus.subscribe();

    // Simulated market data producer
    let producer_bus = market_bus.clone();
    tokio::spawn(async move {
        let tick = MarketDataTick {
            symbol: "BTC-USD".to_string(),
            bid: 65000.10,
            ask: 65000.20,
            bid_size: 1.2,
            ask_size: 0.8,
        };

        let event = EventEnvelope {
            event_id: Uuid::new_v4(),
            timestamp: Utc::now(),
            source: "simulator".to_string(),
            event_type: "MarketDataTick".to_string(),
            payload: tick,
        };

        producer_bus.publish(event);
    });

    while let Ok(event) = rx.recv().await {
        let tick = event.payload;
        info!("received tick: {:?}", tick);

        if let Some(order) = strategy.on_tick(&tick) {
            match risk.validate(&order) {
                Ok(_) => {
                    let (ack, fill) = execution.send_order(&order).await;
                    info!("order ack: {:?}", ack);

                    if let Some(fill) = fill {
                        positions.apply_fill(&fill);
                        info!("fill applied: {:?}", fill);
                        info!("position {} = {}", fill.symbol, positions.get_position(&fill.symbol));
                    }
