## `risk/engine.rs`

```rust
use std::collections::HashMap;
use crate::common::types::{Order, OrderStatus, Side};

pub struct RiskEngine {
    max_order_qty: f64,
    max_notional: f64,
    positions: HashMap<u64, f64>,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
            positions: HashMap::new(),
        }
    }

    pub fn pre_trade_check(&self, order: &Order, market_price: Option<f64>) -> Result<(), String> {
        if order.quantity <= 0.0 {
            return Err("Quantity must be positive".into());
        }

        if order.quantity > self.max_order_qty {
            return Err(format!("Order quantity exceeds limit: {}", self.max_order_qty));
        }

        let px = match (order.price, market_price) {
            (Some(p), _) => p,
            (None, Some(m)) => m,
            (None, None) => return Err("No price available for notional check".into()),
        };

        let notional = px * order.quantity;
        if notional > self.max_notional {
            return Err(format!("Order notional exceeds limit: {}", self.max_notional));
        }

        Ok(())
    }

    pub fn on_fill(&mut self, instrument_id: u64, side: &Side, qty: f64) {
        let pos = self.positions.entry(instrument_id).or_insert(0.0);
        match side {
            Side::Buy => *pos += qty,
            Side::Sell => *pos -= qty,
        }
    }

    pub fn position(&self, instrument_id: u64) -> f64 {
        *self.positions.get(&instrument_id).unwrap_or(&0.0)
    }
}
```

