## `src/risk.rs`

```rust
use std::sync::Arc;
use dashmap::DashMap;
use uuid::Uuid;

use crate::types::{NewOrderRequest, OrderEvent, OrderStatus, Position, Side};

#[derive(Clone)]
pub struct RiskEngine {
    max_order_qty: f64,
    max_notional: f64,
    positions: Arc<DashMap<String, Position>>,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
            positions: Arc::new(DashMap::new()),
        }
    }

    pub fn check_order(&self, order: &NewOrderRequest) -> Result<(), String> {
        if order.qty <= 0.0 {
            return Err("qty must be positive".into());
        }
        if order.qty > self.max_order_qty {
            return Err(format!("qty exceeds max_order_qty: {}", self.max_order_qty));
        }
        let notional = order.qty * order.price;
        if notional > self.max_notional {
            return Err(format!("notional exceeds max_notional: {}", self.max_notional));
        }
        Ok(())
    }

    pub fn on_fill(&self, symbol: &str, side: &Side, qty: f64, price: f64) {
        let mut entry = self.positions.entry(symbol.to_string()).or_insert(Position {
            symbol: symbol.to_string(),
            net_qty: 0.0,
            avg_price: 0.0,
        });

        let signed_qty = match side {
            Side::Buy => qty,
            Side::Sell => -qty,
        };

        let new_net = entry.net_qty + signed_qty;
        entry.avg_price = if new_net.abs() < f64::EPSILON {
            0.0
        } else {
            price
        };
        entry.net_qty = new_net;
    }

    pub fn position(&self, symbol: &str) -> Option<Position> {
        self.positions.get(symbol).map(|p| p.clone())
    }
}
```

