## `src/strategy.rs`

A simple example strategy: buy when ask is below a threshold, sell when bid is above a threshold.

```rust
use uuid::Uuid;

use crate::{
    bus::{Event, EventBus},
    types::{NewOrderRequest, Side, Tick},
};

#[derive(Clone)]
pub struct StrategyEngine {
    bus: EventBus,
    symbol: String,
    buy_below: f64,
    sell_above: f64,
    order_qty: f64,
}

impl StrategyEngine {
    pub fn new(bus: EventBus, symbol: &str, buy_below: f64, sell_above: f64, order_qty: f64) -> Self {
        Self {
            bus,
            symbol: symbol.to_string(),
            buy_below,
            sell_above,
            order_qty,
        }
    }

    pub fn on_tick(&self, tick: Tick) {
        if tick.symbol != self.symbol {
            return;
        }

        if tick.ask < self.buy_below {
            let order = NewOrderRequest {
                order_id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Buy,
                qty: self.order_qty,
                price: tick.ask,
                ts_nanos: tick.ts_nanos,
            };
            self.bus.publish(Event::NewOrder(order));
        } else if tick.bid > self.sell_above {
            let order = NewOrderRequest {
                order_id: Uuid::new_v4(),
                symbol: tick.symbol.clone(),
                side: Side::Sell,
                qty: self.order_qty,
                price: tick.bid,
                ts_nanos: tick.ts_nanos,
            };
            self.bus.publish(Event::NewOrder(order));
        }
    }
}
```

