## `src/oms.rs`

```rust
use std::sync::Arc;
use dashmap::DashMap;

use crate::{
    bus::{Event, EventBus},
    risk::RiskEngine,
    types::{NewOrderRequest, OrderEvent, OrderStatus},
};

#[derive(Clone)]
pub struct OrderManagementSystem {
    bus: EventBus,
    risk: RiskEngine,
    orders: Arc<DashMap<uuid::Uuid, OrderStatus>>,
}

impl OrderManagementSystem {
    pub fn new(bus: EventBus, risk: RiskEngine) -> Self {
        Self {
            bus,
            risk,
            orders: Arc::new(DashMap::new()),
        }
    }

    pub fn on_new_order(&self, order: NewOrderRequest) {
        self.orders.insert(order.order_id, OrderStatus::New);

        if let Err(reason) = self.risk.check_order(&order) {
            let evt = OrderEvent {
                order_id: order.order_id,
                status: OrderStatus::Rejected,
                reason: Some(reason),
                filled_qty: 0.0,
                remaining_qty: order.qty,
                ts_nanos: order.ts_nanos,
            };
            self.orders.insert(order.order_id, OrderStatus::Rejected);
            self.bus.publish(Event::OrderEvent(evt));
            return;
        }

        let evt = OrderEvent {
            order_id: order.order_id,
            status: OrderStatus::Accepted,
            reason: None,
            filled_qty: 0.0,
            remaining_qty: order.qty,
            ts_nanos: order.ts_nanos,
        };
        self.orders.insert(order.order_id, OrderStatus::Accepted);
        self.bus.publish(Event::OrderEvent(evt));

        // In a real system, forward to execution gateway here.
        // For initial implementation, simulate immediate fill.
        let fill_evt = OrderEvent {
            order_id: order.order_id,
            status: OrderStatus::Filled,
            reason: None,
            filled_qty: order.qty,
            remaining_qty: 0.0,
            ts_nanos: order.ts_nanos + 1,
        };
        self.orders.insert(order.order_id, OrderStatus::Filled);
        self.bus.publish(Event::OrderEvent(fill_evt));
    }
}
```

