use tokio::time::{sleep, Duration};

use crate::{
    bus::{Event, EventBus},
    types::Tick,
};

pub async fn run_md_gateway(bus: EventBus) {
    let mut price = 100.0;
    loop {
        price += 0.1;
        let tick = Tick {
            symbol: "AAPL".to_string(),
            bid: price - 0.01,
            ask: price + 0.01,
            ts_nanos: current_ts_nanos(),
        };
        bus.publish(Event::Tick(tick));
        sleep(Duration::from_millis(10)).await;
    }
}

fn current_ts_nanos() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos() as u64
}
```

