```rust
mod bus;
mod exec_gateway;
mod md_gateway;
mod oms;
mod risk;
mod strategy;
mod types;

use bus::{Event, EventBus};
use oms::OrderManagementSystem;
use risk::RiskEngine;
use strategy::StrategyEngine;
use tracing::{info, warn};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let bus = EventBus::new(1024);
    let risk = RiskEngine::new(1000.0, 100_000.0);
    let oms = OrderManagementSystem::new(bus.clone(), risk.clone());
    let strategy = StrategyEngine::new(bus.clone(), "AAPL", 100.5, 101.5, 10.0);

    let mut rx = bus.subscribe();

    tokio::spawn(md_gateway::run_md_gateway(bus.clone()));

    let strategy_clone = strategy.clone();
    let oms_clone = oms.clone();

    tokio::spawn(async move {
        loop {
            match rx.recv().await {
                Ok(Event::Tick(tick)) => {
                    strategy_clone.on_tick(tick);
                }
                Ok(Event::NewOrder(order)) => {
                    oms_clone.on_new_order(order);
                }
                Ok(Event::OrderEvent(evt)) => {
                    info!("Order event: {:?}", evt);
                }
                Err(e) => {
                    warn!("event bus recv error: {}", e);
                }
            }
        }
    });

    tokio::signal::ctrl_c().await?;
    Ok(())
}
