# 10) Risk engine

## `src/risk/risk_engine.rs`
```rust
use std::collections::HashMap;

use crate::domain::{
    order::{Order, Side},
    risk::RiskLimits,
};

pub struct RiskEngine {
    pub limits: RiskLimits,
    pub positions: HashMap<String, f64>,
}

impl RiskEngine {
    pub fn new(limits: RiskLimits) -> Self {
        Self {
            limits,
            positions: HashMap::new(),
        }
    }

    pub fn validate_order(&self, order: &Order) -> Result<(), String> {
        if order.qty > self.limits.max_order_qty {
            return Err("order qty exceeds limit".into());
        }

        let current_pos = *self.positions.get(&order.instrument_id).unwrap_or(&0.0);
        let projected_pos = match order.side {
            Side::Buy => current_pos + order.qty,
            Side::Sell => current_pos - order.qty,
        };

        if projected_pos.abs() > self.limits.max_position {
            return Err("projected position exceeds limit".into());
        }

        Ok(())
    }
}
```

