use tokio::sync::broadcast;

use crate::types::{MarketTick, OrderRequest};

#[derive(Clone)]
pub struct EventBus {
    tick_tx: broadcast::Sender<MarketTick>,
    order_tx: broadcast::Sender<OrderRequest>,
}

impl EventBus {
    pub fn new(buffer: usize) -> Self {
        let (tick_tx, _) = broadcast::channel(buffer);
        let (order_tx, _) = broadcast::channel(buffer);
        Self { tick_tx, order_tx }
    }

    pub fn publish_tick(&self, tick: MarketTick) {
        let _ = self.tick_tx.send(tick);
    }

    pub fn publish_order(&self, order: OrderRequest) {
        let _ = self.order_tx.send(order);
    }

    pub fn subscribe_ticks(&self) -> broadcast::Receiver<MarketTick> {
        self.tick_tx.subscribe()
    }

    pub fn subscribe_orders(&self) -> broadcast::Receiver<OrderRequest> {
        self.order_tx.subscribe()
    }
}
