## `src/risk.rs`

```rust
use crate::types::{OrderRequest, RiskDecision};

pub struct RiskEngine {
    pub max_order_qty: f64,
    pub max_order_notional: f64,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_order_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_order_notional,
        }
    }

    pub fn check(&self, order: &OrderRequest, market_price: f64) -> RiskDecision {
        if order.qty <= 0.0 {
            return RiskDecision {
                approved: false,
                reason: Some("qty must be positive".into()),
            };
        }

        if order.qty > self.max_order_qty {
            return RiskDecision {
                approved: false,
                reason: Some("qty exceeds limit".into()),
            };
        }

        let px = order.price.unwrap_or(market_price);
        let notional = px * order.qty;

        if notional > self.max_order_notional {
            return RiskDecision {
                approved: false,
                reason: Some("notional exceeds limit".into()),
            };
        }

        RiskDecision {
            approved: true,
            reason: None,
        }
    }
}
```

