use crate::types::{MarketTick, OrderRequest, Side, TradeSignal};

pub struct StrategyEngine;

impl StrategyEngine {
    pub fn new() -> Self {
        Self
    }

    pub fn on_tick(&self, tick: &MarketTick) -> Option<TradeSignal> {
        let mid = (tick.bid + tick.ask) / 2.0;
        let spread = tick.ask - tick.bid;

        if spread <= 0.01 {
            if tick.last >= mid {
                Some(TradeSignal {
                    symbol: tick.symbol.clone(),
                    side: Side::Buy,
                    qty: 1.0,
                })
            } else {
                Some(TradeSignal {
                    symbol: tick.symbol.clone(),
                    side: Side::Sell,
                    qty: 1.0,
                })
            }
        } else {
            None
        }
    }

