use observability::init_tracing;
use risk::RiskEngine;
use strategy::StrategyEngine;
use types::{OrderAck, OrderFill};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    init_tracing();

    let bus = EventBus::new(1024);
    let strategy = StrategyEngine::new();
    let risk = RiskEngine::new(100.0, 100_000.0);
    let execution = ExecutionGateway::new();
    let logger = persistence::EventLogger::new("events.log");

    let md_bus = bus.clone();
    tokio::spawn(async move {
        MarketDataHandler::new().run(md_bus).await;
    });

    let mut tick_rx = bus.subscribe_ticks();

    loop {
        let tick = tick_rx.recv().await?;

        logger.append(&tick)?;

        if let Some(signal) = strategy.on_tick(&tick) {
            let order = strategy.signal_to_order(signal, format!("COID-{}", tick.ts_nanos));

            let decision = risk.check(&order, tick.last);
            if !decision.approved {
                tracing::warn!("risk rejected order: {:?}", decision.reason);
                continue;
