use crate::types::OrderIntent;

pub struct RiskEngine {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
        }
    }

    pub fn check(&self, intent: &OrderIntent) -> Result<(), String> {
        if intent.quantity <= 0.0 {
            return Err("quantity must be positive".into());
        }
        if intent.quantity > self.max_order_qty {
            return Err(format!("order qty exceeds limit: {}", intent.quantity));
        }

        if let Some(price) = intent.price {
            let notional = price * intent.quantity;
            if notional > self.max_notional {
                return Err(format!("notional exceeds limit: {}", notional));
            }
        }

        Ok(())
    }
}
```

