use tokio::sync::broadcast;

use crate::types::{MarketEvent, OrderIntent, OrderType, Side};

pub struct StrategyEngine {
    pub strategy_id: u64,
}

impl StrategyEngine {
    pub fn new(strategy_id: u64) -> Self {
        Self { strategy_id }
    }

    pub async fn run(
        self,
        mut market_rx: broadcast::Receiver<MarketEvent>,
        intent_tx: broadcast::Sender<OrderIntent>,
    ) {
        let mut intent_id = 1u64;

        while let Ok(event) = market_rx.recv().await {
            // Example strategy: if spread is small, buy a tiny amount
            let spread = event.ask - event.bid;
            if spread > 0.0 && spread < 0.05 {
                let intent = OrderIntent {
                    intent_id,
                    strategy_id: self.strategy_id,
                    instrument_id: event.instrument_id,
                    side: Side::Buy,
                    quantity: 1.0,
                    price: Some(event.ask),
                    order_type: OrderType::Limit,
                };

                let _ = intent_tx.send(intent);
                intent_id += 1;
            }
        }
    }
}
