```rust
use crate::types::{Event, Order, OrderStatus};

pub struct RiskEngine {
    pub max_order_qty: f64,
    pub max_notional: f64,
}

impl RiskEngine {
    pub fn new(max_order_qty: f64, max_notional: f64) -> Self {
        Self {
            max_order_qty,
            max_notional,
        }
    }

    pub fn validate(&self, order: &Order) -> Result<(), String> {
        if order.quantity <= 0.0 {
            return Err("quantity must be positive".into());
        }

        if order.quantity > self.max_order_qty {
            return Err(format!(
                "quantity {} exceeds max_order_qty {}",
                order.quantity, self.max_order_qty
            ));
        }

        if let Some(price) = order.price {
            let notional = price * order.quantity;
            if notional > self.max_notional {
                return Err(format!(
                    "notional {} exceeds max_notional {}",
                    notional, self.max_notional
                ));
            }
        }

        Ok(())
    }

    pub fn apply(&self, event: Event) -> Event {
        match event {
            Event::OrderIntentCreated(mut order) => {
                match self.validate(&order) {
                    Ok(_) => {
                        order.status = OrderStatus::Validated;
                        Event::OrderValidated(order)
                    }
                    Err(reason) => Event::OrderRejected {
                        order_id: order.order_id,
                        reason,
                    },
                }
            }
            other => other,
        }
    }
}
```

