use bus::EventBus;
use execution::ExecutionGateway;
use market_data::MarketDataGateway;
use persistence::Persistence;
use risk::RiskEngine;
use strategy::StrategyEngine;
use types::{Event, MarketData};

use tracing::{info, error};
use tracing_subscriber::EnvFilter;

#[tokio::main]
async fn main() {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let bus = EventBus::new(1024);
    let persistence = Persistence::new("events.log");
    let risk = RiskEngine::new(1000.0, 100000.0);
    let strategy = StrategyEngine::new();
    let execution = ExecutionGateway::new();
    let md_gateway = MarketDataGateway::new();

    let mut rx = bus.subscribe();
    let bus_clone = bus.clone();

    tokio::spawn(async move {
        while let Ok(event) = rx.recv().await {
            persistence.append(&event);

            match event {
                Event::MarketDataUpdated(md) => {
                    if let Some(order) = strategy.on_market_data(&md) {
                        bus_clone.publish(Event::OrderIntentCreated(order));
                    }
                }
                Event::OrderIntentCreated(order) => {
                    let validated = risk.apply(Event::OrderIntentCreated(order));
                    bus_clone.publish(validated);
                }
                Event::OrderValidated(order) => {
                    match execution.submit(&order).await {
                        Ok(exec_event) => bus_clone.publish(exec_event),
                        Err(reason) => bus_clone.publish(Event::OrderRejected {
                            order_id: order.order_id,
                            reason,
                        }),
                    }
                }
                Event::OrderFilled { order_id, fill } => {
                    info!("Order filled: {:?}, fill: {:?}", order_id, fill);
                }
                Event::OrderRejected { order_id, reason } => {
                    error!("Order rejected: {:?}, reason: {}", order_id, reason);
                }
                _ => {}
            }
        }
    });

    // Simulated market data input
    let md = MarketData {
        instrument_id: "BTC-USD".to_string(),
        bid: 65000.0,
        ask: 65001.0,
        last: 65000.5,
        bid_size: 10.0,
        ask_size: 12.0,
        timestamp_ms: current_time_ms(),
    };

    let event = md_gateway.ingest(md);
    bus.publish(event);

    tokio::time::sleep(std::time::Duration::from_secs(1)).await;
}

fn current_time_ms() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}
