## Go implementation

```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a routed unit of work.
type Message struct {
	Key       string
	Payload   []byte
	CreatedAt time.Time
}

// Metrics holds high-frequency counters.
type Metrics struct {
	Received    atomic.Uint64
	Routed      atomic.Uint64
	Processed   atomic.Uint64
	Dropped    atomic.Uint64
	Errors      atomic.Uint64
	TotalNanos  atomic.Uint64
	MaxNanos    atomic.Uint64
}

// ObserveLatency records latency in nanoseconds.
func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	m.TotalNanos.Add(ns)

	for {
		old := m.MaxNanos.Load()
		if ns <= old {
			break
		}
		if m.MaxNanos.CompareAndSwap(old, ns) {
			break
		}
	}
}

// Snapshot returns a human-readable metrics view.
func (m *Metrics) Snapshot() string {
	processed := m.Processed.Load()
	avg := time.Duration(0)
	if processed > 0 {
		avg = time.Duration(m.TotalNanos.Load() / processed)
	}
	return fmt.Sprintf(
		"received=%d routed=%d processed=%d dropped=%d errors=%d avg_latency=%s max_latency=%s",
		m.Received.Load(),
		m.Routed.Load(),
		processed,
		m.Dropped.Load(),
		m.Errors.Load(),
		avg,
		time.Duration(m.MaxNanos.Load()),
	)
}

// Shard processes messages for a subset of keys.
type Shard struct {
	id      int
	ch      chan Message
	metrics *Metrics
	handler func(Message) error
}

// NewShard creates a shard with a bounded queue.
func NewShard(id int, queueSize int, metrics *Metrics, handler func(Message) error) *Shard {
	return &Shard{
		id:      id,
		ch:      make(chan Message, queueSize),
		metrics: metrics,
		handler: handler,
	}
}

// Start begins shard processing.
func (s *Shard) Start(ctx context.Context, wg *sync.WaitGroup) {
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-ctx.Done():
				return
			case msg := <-s.ch:
				start := time.Now()
				if err := s.handler(msg); err != nil {
					s.metrics.Errors.Add(1)
				}
				latency := time.Since(msg.CreatedAt)
				s.metrics.ObserveLatency(latency)
				s.metrics.Processed.Add(1)

				_ = start // reserved for handler timing if needed
			}
		}
	}()
}

// Router routes messages to shards.
type Router struct {
	shards  []*Shard
	metrics *Metrics
}

// NewRouter creates a router with N shards.
func NewRouter(numShards int, queueSize int, handler func(Message) error) *Router {
	metrics := &Metrics{}
	shards := make([]*Shard, numShards)
	for i := 0; i < numShards; i++ {
		shards[i] = NewShard(i, queueSize, metrics, handler)
	}
	return &Router{
		shards:  shards,
		metrics: metrics,
	}
}

// Start all shards.
func (r *Router) Start(ctx context.Context) *sync.WaitGroup {
	var wg sync.WaitGroup
	for _, shard := range r.shards {
		shard.Start(ctx, &wg)
	}
	return &wg
}

// hashKey maps a key to a shard.
func hashKey(key string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return h.Sum32()
}

// Route sends a message to the appropriate shard.
func (r *Router) Route(msg Message) bool {
	r.metrics.Received.Add(1)

	idx := int(hashKey(msg.Key) % uint32(len(r.shards)))
	shard := r.shards[idx]

	select {
	case shard.ch <- msg:
		r.metrics.Routed.Add(1)
		return true
	default:
		// Backpressure/drop policy: drop if shard queue is full
		r.metrics.Dropped.Add(1)
		return false
	}
}

// Metrics returns current metrics.
func (r *Router) Metrics() *Metrics {
	return r.metrics
}

// Example handler simulates fast processing.
func fastHandler(msg Message) error {
	// Replace with real business logic.
	_ = msg.Payload
	return nil
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	numShards := runtime.NumCPU() * 4
	queueSize := 8192

	router := NewRouter(numShards, queueSize, fastHandler)
	wg := router.Start(ctx)

	// Simulate high-rate producers.
	producerCount := runtime.NumCPU() * 2
	var prodWG sync.WaitGroup

	for p := 0; p < producerCount; p++ {
		prodWG.Add(1)
		go func(id int) {
			defer prodWG.Done()
			for i := 0; i < 1_000_000; i++ {
				msg := Message{
					Key:       fmt.Sprintf("user-%d", i%100_000),
					Payload:   []byte("hello"),
					CreatedAt: time.Now(),
				}
				router.Route(msg)
			}
		}(p)
	}

	// Metrics reporter
	go func() {
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()
		for range ticker.C {
			log.Println(router.Metrics().Snapshot())
		}
	}()

	prodWG.Wait()

	// Allow draining
	time.Sleep(2 * time.Second)
	cancel()
	wg.Wait()

	log.Println("final:", router.Metrics().Snapshot())
}
