## Go implementation

```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a routed unit of work.
type Message struct {
	ID        uint64
	Key       string
	Payload   []byte
	CreatedAt  time.Time
	TraceID    string
	Partition  int
	Attributes map[string]string
}

// Handler processes a message.
type Handler func(ctx context.Context, msg Message) error

// Metrics collects high-level counters and latency stats.
type Metrics struct {
	Received uint64
	Routed   uint64
	Processed uint64
	Dropped  uint64
	Errors   uint64

	// Latency in nanoseconds
	TotalLatencyNanos uint64
	MaxLatencyNanos   uint64
}

func (m *Metrics) IncReceived()  { atomic.AddUint64(&m.Received, 1) }
func (m *Metrics) IncRouted()    { atomic.AddUint64(&m.Routed, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.Processed, 1) }
func (m *Metrics) IncDropped()   { atomic.AddUint64(&m.Dropped, 1) }
func (m *Metrics) IncErrors()    { atomic.AddUint64(&m.Errors, 1) }

func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.TotalLatencyNanos, ns)

	for {
		old := atomic.LoadUint64(&m.MaxLatencyNanos)
		if ns <= old {
			return
		}
		if atomic.CompareAndSwapUint64(&m.MaxLatencyNanos, old, ns) {
			return
		}
	}
}

func (m *Metrics) Snapshot() map[string]any {
	received := atomic.LoadUint64(&m.Received)
	routed := atomic.LoadUint64(&m.Routed)
	processed := atomic.LoadUint64(&m.Processed)
	dropped := atomic.LoadUint64(&m.Dropped)
	errors := atomic.LoadUint64(&m.Errors)
	totalLatency := atomic.LoadUint64(&m.TotalLatencyNanos)
	maxLatency := atomic.LoadUint64(&m.MaxLatencyNanos)

	avgLatency := uint64(0)
	if processed > 0 {
		avgLatency = totalLatency / processed
	}

	return map[string]any{
		"received":          received,
		"routed":            routed,
		"processed":         processed,
		"dropped":           dropped,
		"errors":            errors,
		"avg_latency_ns":    avgLatency,
		"max_latency_ns":    maxLatency,
		"goroutines":        runtime.NumGoroutine(),
		"queue_depth_total": 0, // filled by router if desired
	}
}

// Shard is a single processing lane.
type Shard struct {
	id       int
	queue    chan Message
	handler  Handler
	metrics  *Metrics
	stopOnce sync.Once
}

func NewShard(id int, queueSize int, handler Handler, metrics *Metrics) *Shard {
	return &Shard{
		id:      id,
		queue:   make(chan Message, queueSize),
		handler: handler,
		metrics: metrics,
	}
}

func (s *Shard) Start(ctx context.Context, wg *sync.WaitGroup) {
	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-ctx.Done():
				return
			case msg := <-s.queue:
				start := time.Now()
				err := s.handler(ctx, msg)
				if err != nil {
					s.metrics.IncErrors()
				}
				s.metrics.IncProcessed()
				s.metrics.ObserveLatency(time.Since(msg.CreatedAt))
				_ = start
			}
		}
	}()
}

func (s *Shard) TryEnqueue(msg Message) bool {
	select {
	case s.queue <- msg:
		return true
	default:
		return false
	}
}

func (s *Shard) Depth() int {
	return len(s.queue)
}

// Router routes messages to shards.
type Router struct {
	shards  []*Shard
	metrics *Metrics
}

func NewRouter(numShards int, queueSize int, handler Handler, metrics *Metrics) *Router {
	shards := make([]*Shard, numShards)
	for i := 0; i < numShards; i++ {
		shards[i] = NewShard(i, queueSize, handler, metrics)
	}
	return &Router{
		shards:  shards,
		metrics: metrics,
	}
}

func (r *Router) Start(ctx context.Context) *sync.WaitGroup {
	var wg sync.WaitGroup
	for _, shard := range r.shards {
		shard.Start(ctx, &wg)
	}
	return &wg
}

func (r *Router) Route(msg Message) bool {
	r.metrics.IncReceived()

	idx := r.shardIndex(msg.Key)
	msg.Partition = idx

	if r.shards[idx].TryEnqueue(msg) {
		r.metrics.IncRouted()
		return true
	}

	r.metrics.IncDropped()
	return false
}

func (r *Router) shardIndex(key string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return int(h.Sum32()) % len(r.shards)
}

func (r *Router) QueueDepthTotal() int {
	total := 0
	for _, s := range r.shards {
		total += s.Depth()
	}
	return total
}

// Example handler simulates fast processing.
func fastHandler(ctx context.Context, msg Message) error {
	// Replace with real business logic.
	_ = ctx
	_ = msg
	return nil
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	metrics := &Metrics{}
	numShards := runtime.NumCPU() * 2
	queueSize := 8192

	router := NewRouter(numShards, queueSize, fastHandler, metrics)
	wg := router.Start(ctx)

	// Latency/throughput reporter
	go func() {
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()

		var lastProcessed uint64
		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				snap := metrics.Snapshot()
				processed := atomic.LoadUint64(&metrics.Processed)
				delta := processed - lastProcessed
				lastProcessed = processed

				snap["queue_depth_total"] = router.QueueDepthTotal()
				fmt.Printf(
					"throughput=%d msg/s received=%d routed=%d processed=%d dropped=%d errors=%d avg_lat=%dns max_lat=%dns queue=%d\n",
					delta,
					snap["received"],
					snap["routed"],
					snap["processed"],
					snap["dropped"],
					snap["errors"],
					snap["avg_latency_ns"],
					snap["max_latency_ns"],
					snap["queue_depth_total"],
				)
			}
		}
	}()

	// Simulated high-rate producer
	go func() {
		var id uint64
		ticker := time.NewTicker(0)
		defer ticker.Stop()

		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				msg := Message{
					ID:       atomic.AddUint64(&id, 1),
					Key:      fmt.Sprintf("user-%d", id%100000),
					Payload:  []byte("hello"),
					CreatedAt: time.Now(),
					TraceID:  fmt.Sprintf("trace-%d", id),
				}
				_ = router.Route(msg)
			}
		}
	}()

	// Run for demo purposes
	time.Sleep(5 * time.Second)
	cancel()
	wg.Wait()
	log.Println("shutdown complete")
}
