	ID        uint64
	Key       string
	Payload   []byte
	CreatedAt time.Time
}

type RoutedMessage struct {
	Msg       Message
	ShardID   int
	EnqueuedAt time.Time
}

type Metrics struct {
	Received       atomic.Uint64
	Routed         atomic.Uint64
	Processed      atomic.Uint64
	Dropped        atomic.Uint64
	QueueFullDrops atomic.Uint64

	TotalLatencyNs atomic.Uint64
	MaxLatencyNs   atomic.Uint64
}

func (m *Metrics) RecordLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	m.TotalLatencyNs.Add(ns)

	for {
		old := m.MaxLatencyNs.Load()
		if ns <= old {
			break
		}
		if m.MaxLatencyNs.CompareAndSwap(old, ns) {
			break
		}
	}
}

func (m *Metrics) Snapshot() string {
	processed := m.Processed.Load()
	avg := time.Duration(0)
	if processed > 0 {
		avg = time.Duration(m.TotalLatencyNs.Load() / processed)
	}
	return fmt.Sprintf(
		"received=%d routed=%d processed=%d dropped=%d queue_full_drops=%d avg_latency=%s max_latency=%s",
		m.Received.Load(),
		m.Routed.Load(),
		processed,
		m.Dropped.Load(),
		m.QueueFullDrops.Load(),
		avg,
		time.Duration(m.MaxLatencyNs.Load()),
	)
}

type Shard struct {
	ID       int
	In       chan RoutedMessage
	StopOnce sync.Once
}

type Router struct {
	shards  []*Shard
	metrics *Metrics
}

func NewRouter(numShards int, queueSize int, metrics *Metrics) *Router {
	r := &Router{
		shards:  make([]*Shard, numShards),
		metrics: metrics,
	}
	for i := 0; i < numShards; i++ {
		r.shards[i] = &Shard{
			ID: i,
			In: make(chan RoutedMessage, queueSize),
		}
	}
	return r
}

func (r *Router) shardForKey(key string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return int(h.Sum32() % uint32(len(r.shards)))
}

func (r *Router) Route(msg Message) bool {
	r.metrics.Received.Add(1)

	shardID := r.shardForKey(msg.Key)
	rm := RoutedMessage{
		Msg:       msg,
		ShardID:   shardID,
		EnqueuedAt: time.Now(),
	}

	select {
	case r.shards[shardID].In <- rm:
		r.metrics.Routed.Add(1)
		return true
	default:
		r.metrics.QueueFullDrops.Add(1)
		r.metrics.Dropped.Add(1)
		return false
	}
}

func (r *Router) Start(ctx context.Context, wg *sync.WaitGroup, handler func(context.Context, RoutedMessage)) {
	for _, shard := range r.shards {
		wg.Add(1)
		go func(s *Shard) {
			defer wg.Done()
			for {
				select {
				case <-ctx.Done():
					return
				case rm := <-s.In:
					handler(ctx, rm)
				}
			}
		}(shard)
	}
}

func (r *Router) ShardChannels() []chan RoutedMessage {
	out := make([]chan RoutedMessage, len(r.shards))
	for i, s := range r.shards {
		out[i] = s.In
	}
	return out
}

type LatencyMonitor struct {
	metrics *Metrics
}

func NewLatencyMonitor(metrics *Metrics) *LatencyMonitor {
	return &LatencyMonitor{metrics: metrics}
}

func (lm *LatencyMonitor) Observe(msg Message) {
	lm.metrics.Processed.Add(1)
	lm.metrics.RecordLatency(time.Since(msg.CreatedAt))
}

func main() {
	const (
		numShards = 8
		queueSize  = 10000
	)

	metrics := &Metrics{}
	router := NewRouter(numShards, queueSize, metrics)
	monitor := NewLatencyMonitor(metrics)

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	var wg sync.WaitGroup

	// Start shard workers
	router.Start(ctx, &wg, func(ctx context.Context, rm RoutedMessage) {
		// Simulate processing
		// In real systems, this would be your business logic / fanout / persistence.
		monitor.Observe(rm.Msg)
	})

	// Metrics reporter
	wg.Add(1)
	go func() {
		defer wg.Done()
		ticker := time.NewTicker(1 * time.Second)
		defer ticker.Stop()

		for {
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
				log.Println(metrics.Snapshot())
			}
		}
	}()

	// Producer simulation
	producerCount := 4
	messagesPerProducer := 250000

	var prodWG sync.WaitGroup
	prodWG.Add(producerCount)

	for p := 0; p < producerCount; p++ {
		go func(pid int) {
			defer prodWG.Done()
			rng := rand.New(rand.NewSource(time.Now().UnixNano() + int64(pid)))

			for i := 0; i < messagesPerProducer; i++ {
				msg := Message{
					ID:        uint64(pid)<<32 | uint64(i),
					Key:       fmt.Sprintf("user-%d", rng.Intn(100000)),
					Payload:   []byte("hello world"),
					CreatedAt: time.Now(),
				}
				router.Route(msg)
			}
		}(p)
	}

	prodWG.Wait()

	// Let workers drain
	time.Sleep(2 * time.Second)
	cancel()
	wg.Wait()

	log.Println("final:", metrics.Snapshot())
}
