package main

import (
	"fmt"
	"hash/fnv"
	"log"
	"math"
	"sort"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt time.Time
}

type Handler func(msg Message)

// -------------------- Metrics --------------------

type Metrics struct {
	received   uint64
	routed     uint64
	dropped    uint64
	processed  uint64
	totalNanos uint64

	latMu    sync.Mutex
	latency  []int64 // nanoseconds samples
	maxSamps int
}

func NewMetrics(maxSamples int) *Metrics {
	return &Metrics{
		latency:  make([]int64, 0, maxSamples),
		maxSamps: maxSamples,
	}
}

func (m *Metrics) IncReceived()  { atomic.AddUint64(&m.received, 1) }
func (m *Metrics) IncRouted()    { atomic.AddUint64(&m.routed, 1) }
func (m *Metrics) IncDropped()   { atomic.AddUint64(&m.dropped, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.processed, 1) }

func (m *Metrics) ObserveLatency(d time.Duration) {
	nanos := d.Nanoseconds()
	atomic.AddUint64(&m.totalNanos, uint64(nanos))

	m.latMu.Lock()
	if len(m.latency) < m.maxSamps {
		m.latency = append(m.latency, nanos)
	} else {
		// Reservoir-style replacement for bounded memory
		idx := int(atomic.AddUint64(&m.processed, 1)) % m.maxSamps
		m.latency[idx] = nanos
	}
	m.latMu.Unlock()
}

func (m *Metrics) Snapshot() string {
	received := atomic.LoadUint64(&m.received)
	routed := atomic.LoadUint64(&m.routed)
	dropped := atomic.LoadUint64(&m.dropped)
	processed := atomic.LoadUint64(&m.processed)
	totalNanos := atomic.LoadUint64(&m.totalNanos)

	avg := time.Duration(0)
	if processed > 0 {
		avg = time.Duration(totalNanos / processed)
	}

	p50, p95, p99 := m.Percentiles()

	return fmt.Sprintf(
		"received=%d routed=%d processed=%d dropped=%d avg=%s p50=%s p95=%s p99=%s",
		received, routed, processed, dropped, avg, p50, p95, p99,
	)
}

func (m *Metrics) Percentiles() (time.Duration, time.Duration, time.Duration) {
	m.latMu.Lock()
	defer m.latMu.Unlock()

	if len(m.latency) == 0 {
		return 0, 0, 0
	}

	samples := make([]int64, len(m.latency))
	copy(samples, m.latency)
	sort.Slice(samples, func(i, j int) bool { return samples[i] < samples[j] })

	get := func(p float64) time.Duration {
		if len(samples) == 0 {
			return 0
		}
		idx := int(math.Ceil(p*float64(len(samples)))) - 1
		if idx < 0 {
			idx = 0
		}
		if idx >= len(samples) {
			idx = len(samples) - 1
		}
		return time.Duration(samples[idx])
	}

	return get(0.50), get(0.95), get(0.99)
}

// -------------------- Router --------------------

type shard struct {
	mu       sync.RWMutex
	handlers map[string]Handler
}

type Router struct {
	shards  []shard
	metrics *Metrics
}

func NewRouter(numShards int, metrics *Metrics) *Router {
	r := &Router{
		shards:  make([]shard, numShards),
		metrics: metrics,
	}
	for i := range r.shards {
		r.shards[i].handlers = make(map[string]Handler)
	}
	return r
}

func (r *Router) shardFor(topic string) *shard {
	h := fnv.New32a()
	_, _ = h.Write([]byte(topic))
	idx := int(h.Sum32()) % len(r.shards)
	return &r.shards[idx]
}

func (r *Router) Register(topic string, h Handler) {
	s := r.shardFor(topic)
	s.mu.Lock()
	s.handlers[topic] = h
	s.mu.Unlock()
}

func (r *Router) Route(msg Message) bool {
	s := r.shardFor(msg.Topic)
	s.mu.RLock()
	h, ok := s.handlers[msg.Topic]
	s.mu.RUnlock()

	if !ok {
		r.metrics.IncDropped()
		return false
	}

	r.metrics.IncRouted()
	h(msg)
	return true
}

// -------------------- Broker / Ingest Pipeline --------------------

type Broker struct {
	router      *Router
	metrics     *Metrics
	in          chan Message
	workers     int
	stopCh      chan struct{}
	wg          sync.WaitGroup
	batchSize   int
	nonBlocking bool
}

func NewBroker(router *Router, metrics *Metrics, queueSize, workers, batchSize int, nonBlocking bool) *Broker {
	return &Broker{
		router:      router,
		metrics:     metrics,
		in:          make(chan Message, queueSize),
		workers:     workers,
		stopCh:      make(chan struct{}),
		batchSize:   batchSize,
		nonBlocking: nonBlocking,
	}
}

func (b *Broker) Start() {
	for i := 0; i < b.workers; i++ {
		b.wg.Add(1)
		go b.workerLoop(i)
	}
}

func (b *Broker) Stop() {
	close(b.stopCh)
	b.wg.Wait()
}

func (b *Broker) Publish(msg Message) bool {
	b.metrics.IncReceived()

	if msg.CreatedAt.IsZero() {
		msg.CreatedAt = time.Now()
	}

	if b.nonBlocking {
		select {
		case b.in <- msg:
			return true
		default:
			b.metrics.IncDropped()
			return false
		}
	}

	select {
	case b.in <- msg:
		return true
	case <-b.stopCh:
		return false
	}
}

func (b *Broker) workerLoop(id int) {
	defer b.wg.Done()

	batch := make([]Message, 0, b.batchSize)

	flush := func() {
		for _, msg := range batch {
			start := time.Now()
			b.router.Route(msg)
			b.metrics.IncProcessed()
			b.metrics.ObserveLatency(time.Since(msg.CreatedAt))
			_ = start
		}
		batch = batch[:0]
	}

	for {
		select {
		case <-b.stopCh:
			flush()
			return
		case msg := <-b.in:
			batch = append(batch, msg)
			if len(batch) >= b.batchSize {
				flush()
			}
		default:
			if len(batch) > 0 {
				flush()
			} else {
				// Avoid busy spin; tune for your workload
				time.Sleep(10 * time.Microsecond)
			}
		}
	}
}

// -------------------- Example Handlers --------------------

func fastHandler(msg Message) {
	// Keep handlers extremely lightweight for high throughput.
	// Avoid allocations, logging, blocking I/O, and locks.
	_ = msg.Payload
}

func main() {
	metrics := NewMetrics(100_000)
	router := NewRouter(64, metrics)

	router.Register("orders", fastHandler)
	router.Register("quotes", fastHandler)
	router.Register("alerts", fastHandler)

	broker := NewBroker(router, metrics, 1_000_000, 8, 256, true)
	broker.Start()
	defer broker.Stop()

	// Simulate high-rate publishing
	go func() {
		var id uint64
		topics := []string{"orders", "quotes", "alerts"}
		for {
			id++
			msg := Message{
				ID:        id,
				Topic:     topics[id%uint64(len(topics))],
				Payload:   []byte("hello"),
				CreatedAt: time.Now(),
			}
			_ = broker.Publish(msg)
		}
	}()

	// Metrics reporter
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		log.Println(metrics.Snapshot())
	}
}
