## Go code

```go
package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a high-throughput message.
type Message struct {
	Key       string
	Payload   []byte
	CreatedAt time.Time
}

// Handler processes messages.
type Handler func(ctx context.Context, msg *Message) error

// Router routes messages to shards based on key.
type Router struct {
	shards []*shard
	mask   uint32
	pool   sync.Pool
	closed atomic.Bool
}

// shard is a single-threaded hot path worker to minimize contention.
type shard struct {
	in       chan *Message
	handler  Handler
	metrics  *Metrics
	stopCh   chan struct{}
	stopped  chan struct{}
}

// Metrics tracks throughput and latency.
type Metrics struct {
	received uint64
	processed uint64
	dropped   uint64
	errors    uint64

	// latency buckets in nanoseconds:
	// <1us, <5us, <10us, <50us, <100us, <500us, <1ms, <5ms, >=5ms
	latencyBuckets [9]uint64
}

// NewRouter creates a router with shardCount power-of-two shards.
func NewRouter(shardCount int, queueSize int, handler Handler) *Router {
	if shardCount <= 0 || (shardCount&(shardCount-1)) != 0 {
		panic("shardCount must be a power of two and > 0")
	}

	r := &Router{
		shards: make([]*shard, shardCount),
		mask:   uint32(shardCount - 1),
		pool: sync.Pool{
			New: func() any {
				return &Message{}
			},
		},
	}

	for i := 0; i < shardCount; i++ {
		s := &shard{
			in:      make(chan *Message, queueSize),
			handler: handler,
			metrics: &Metrics{},
			stopCh:  make(chan struct{}),
			stopped: make(chan struct{}),
		}
		r.shards[i] = s
		go s.run()
	}

	return r
}

// hashKey maps a key to a shard.
func hashKey(key string) uint32 {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return h.Sum32()
}

// shardFor returns the shard for a key.
func (r *Router) shardFor(key string) *shard {
	idx := hashKey(key) & r.mask
	return r.shards[idx]
}

// Publish sends a message into the system.
// Returns false if the router is closed or the shard queue is full.
func (r *Router) Publish(key string, payload []byte) bool {
	if r.closed.Load() {
		return false
	}

	s := r.shardFor(key)

	msg := r.pool.Get().(*Message)
	msg.Key = key
	msg.Payload = payload
	msg.CreatedAt = time.Now()

	atomic.AddUint64(&s.metrics.received, 1)

	select {
	case s.in <- msg:
		return true
	default:
		atomic.AddUint64(&s.metrics.dropped, 1)
		r.recycle(msg)
		return false
	}
}

// recycle returns a message to the pool.
func (r *Router) recycle(msg *Message) {
	msg.Key = ""
	msg.Payload = nil
	msg.CreatedAt = time.Time{}
	r.pool.Put(msg)
}

// Close stops all shards.
func (r *Router) Close() {
	if !r.closed.CompareAndSwap(false, true) {
		return
	}

	for _, s := range r.shards {
		close(s.stopCh)
	}

	for _, s := range r.shards {
		<-s.stopped
	}
}

// MetricsSnapshot returns aggregated metrics.
func (r *Router) MetricsSnapshot() Metrics {
	var out Metrics
	for _, s := range r.shards {
		out.received += atomic.LoadUint64(&s.metrics.received)
		out.processed += atomic.LoadUint64(&s.metrics.processed)
		out.dropped += atomic.LoadUint64(&s.metrics.dropped)
		out.errors += atomic.LoadUint64(&s.metrics.errors)

		for i := range out.latencyBuckets {
			out.latencyBuckets[i] += atomic.LoadUint64(&s.metrics.latencyBuckets[i])
		}
	}
	return out
}

// run processes messages for a shard.
func (s *shard) run() {
	defer close(s.stopped)

	ctx := context.Background()

	for {
		select {
		case <-s.stopCh:
			return
		case msg := <-s.in:
			if msg == nil {
				continue
			}

			start := time.Now()
			err := s.handler(ctx, msg)
			latency := time.Since(msg.CreatedAt)

			atomic.AddUint64(&s.metrics.processed, 1)
			if err != nil {
				atomic.AddUint64(&s.metrics.errors, 1)
			}
			recordLatency(&s.metrics.latencyBuckets, latency)

			_ = start // reserved if you want handler-only timing
			// NOTE: recycle handled by caller if needed; here we assume handler does not retain msg.
			// In a real system, define ownership clearly.
		}
	}
}

// recordLatency places latency into a bucket.
func recordLatency(buckets *[9]uint64, d time.Duration) {
	ns := d.Nanoseconds()
	var idx int
	switch {
	case ns < 1_000:
		idx = 0
	case ns < 5_000:
		idx = 1
	case ns < 10_000:
		idx = 2
	case ns < 50_000:
		idx = 3
	case ns < 100_000:
		idx = 4
	case ns < 500_000:
		idx = 5
	case ns < 1_000_000:
		idx = 6
	case ns < 5_000_000:
		idx = 7
	default:
		idx = 8
	}
	atomic.AddUint64(&buckets[idx], 1)
}

// Example handler.
func exampleHandler(ctx context.Context, msg *Message) error {
	// Simulate work
	_ = ctx
	_ = msg
	return nil
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	router := NewRouter(
		64,    // shards
		4096,  // queue size per shard
		exampleHandler,
	)

	defer router.Close()

	// Simulate high-rate publishing
	for i := 0; i < 1_000_000; i++ {
		key := fmt.Sprintf("user-%d", i%1000)
		ok := router.Publish(key, []byte("hello world"))
		if !ok {
			// backpressure / drop handling
		}
	}

	time.Sleep(2 * time.Second)

	m := router.MetricsSnapshot()
	log.Printf("received=%d processed=%d dropped=%d errors=%d latencyBuckets=%v",
		m.received, m.processed, m.dropped, m.errors, m.latencyBuckets)
}
```

