package main

import (
	"context"
	"fmt"
	"hash/fnv"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a routed message.
type Message struct {
	ID        uint64
	Key       string
	Payload   []byte
	CreatedAt  int64 // unix nano
	ReceivedAt int64 // unix nano
}

// RouteResult is used for latency tracking and delivery stats.
type RouteResult struct {
	MessageID    uint64
	QueueLatency time.Duration
	ProcLatency  time.Duration
	TotalLatency time.Duration
	Success      bool
}

// Metrics collects high-level system stats.
type Metrics struct {
	ingested      uint64
	routed        uint64
	processed     uint64
	dropped       uint64
	totalLatencyN uint64
	maxLatencyN   uint64
}

func (m *Metrics) IncIngested()  { atomic.AddUint64(&m.ingested, 1) }
func (m *Metrics) IncRouted()    { atomic.AddUint64(&m.routed, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.processed, 1) }
func (m *Metrics) IncDropped()   { atomic.AddUint64(&m.dropped, 1) }

func (m *Metrics) ObserveLatency(d time.Duration) {
	n := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.totalLatencyN, n)

	for {
		old := atomic.LoadUint64(&m.maxLatencyN)
		if n <= old {
			return
		}
		if atomic.CompareAndSwapUint64(&m.maxLatencyN, old, n) {
			return
		}
	}
}

func (m *Metrics) Snapshot() (ingested, routed, processed, dropped uint64, avgLatency, maxLatency time.Duration) {
	ingested = atomic.LoadUint64(&m.ingested)
	routed = atomic.LoadUint64(&m.routed)
	processed = atomic.LoadUint64(&m.processed)
	dropped = atomic.LoadUint64(&m.dropped)

	totalLatency := atomic.LoadUint64(&m.totalLatencyN)
	maxLatencyN := atomic.LoadUint64(&m.maxLatencyN)

	if processed > 0 {
		avgLatency = time.Duration(totalLatency / processed)
	}
	maxLatency = time.Duration(maxLatencyN)
	return
}

// Router routes messages to one of N shards.
type Router struct {
	shards  []chan *Message
	metrics *Metrics
}

func NewRouter(numShards int, shardQueueSize int, metrics *Metrics) *Router {
	r := &Router{
		shards:  make([]chan *Message, numShards),
		metrics: metrics,
	}
	for i := range r.shards {
		r.shards[i] = make(chan *Message, shardQueueSize)
	}
	return r
}

func (r *Router) shardForKey(key string) int {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	return int(h.Sum32()) % len(r.shards)
}

func (r *Router) Submit(msg *Message) bool {
	msg.ReceivedAt = time.Now().UnixNano()
	r.metrics.IncIngested()

	idx := r.shardForKey(msg.Key)

	select {
	case r.shards[idx] <- msg:
		r.metrics.IncRouted()
		return true
	default:
		// Backpressure: drop if shard queue is full.
		r.metrics.IncDropped()
		return false
	}
}

func (r *Router) Shard(i int) <-chan *Message {
	return r.shards[i]
}

// Processor simulates message handling.
type Processor struct {
	id      int
	metrics *Metrics
}

func NewProcessor(id int, metrics *Metrics) *Processor {
	return &Processor{id: id, metrics: metrics}
}

func (p *Processor) Handle(msg *Message) {
	start := time.Now()

	// Simulate work. Replace with real business logic.
	_ = len(msg.Payload)

	procLatency := time.Since(start)
	totalLatency := time.Duration(time.Now().UnixNano() - msg.CreatedAt)

	p.metrics.IncProcessed()
	p.metrics.ObserveLatency(totalLatency)

	_ = RouteResult{
		MessageID:    msg.ID,
		QueueLatency: time.Duration(msg.ReceivedAt - msg.CreatedAt),
		ProcLatency:  procLatency,
		TotalLatency: totalLatency,
		Success:      true,
	}
}

// Worker consumes messages from a shard.
func Worker(ctx context.Context, shardID int, in <-chan *Message, metrics *Metrics, wg *sync.WaitGroup) {
	defer wg.Done()
	processor := NewProcessor(shardID, metrics)

	for {
		select {
		case <-ctx.Done():
			return
		case msg := <-in:
			if msg == nil {
				continue
			}
			processor.Handle(msg)
		}
	}
}

// Generator simulates high-rate message production.
func Generator(ctx context.Context, router *Router, ratePerSec int, keySpace int) {
	ticker := time.NewTicker(time.Second / time.Duration(ratePerSec))
	defer ticker.Stop()

	var id uint64
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			id++
			key := fmt.Sprintf("user-%d", id%uint64(keySpace))
			msg := &Message{
				ID:       id,
				Key:      key,
				Payload:  []byte("hello"),
				CreatedAt: time.Now().UnixNano(),
			}
			router.Submit(msg)
		}
	}
}

