```go
package main

import (
	"fmt"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	CreatedAt  int64 // unix nano
	Payload    []byte
	ShardKey   uint64
}

type LatencyStats struct {
	Count       uint64
	TotalNanos  uint64
	MinNanos    uint64
	MaxNanos    uint64
}

func NewLatencyStats() *LatencyStats {
	return &LatencyStats{
		MinNanos: ^uint64(0),
	}
}

func (s *LatencyStats) Record(latency time.Duration) {
	n := uint64(latency.Nanoseconds())
	atomic.AddUint64(&s.Count, 1)
	atomic.AddUint64(&s.TotalNanos, n)

	for {
		oldMin := atomic.LoadUint64(&s.MinNanos)
		if n >= oldMin {
			break
		}
		if atomic.CompareAndSwapUint64(&s.MinNanos, oldMin, n) {
			break
		}
	}

	for {
		oldMax := atomic.LoadUint64(&s.MaxNanos)
		if n <= oldMax {
			break
		}
		if atomic.CompareAndSwapUint64(&s.MaxNanos, oldMax, n) {
			break
		}
	}
}

func (s *LatencyStats) Snapshot() (count, avg, min, max time.Duration) {
	count = atomic.LoadUint64(&s.Count)
	total := atomic.LoadUint64(&s.TotalNanos)
	minN := atomic.LoadUint64(&s.MinNanos)
	maxN := atomic.LoadUint64(&s.MaxNanos)

	if count > 0 {
		avg = time.Duration(total / count)
		min = time.Duration(minN)
		max = time.Duration(maxN)
	}
	return
}

type Worker struct {
	id      int
	ch      chan *Message
	stats   *LatencyStats
	wg      *sync.WaitGroup
	stop    chan struct{}
}

func NewWorker(id int, buffer int, stats *LatencyStats, wg *sync.WaitGroup) *Worker {
	return &Worker{
		id:    id,
		ch:    make(chan *Message, buffer),
		stats: stats,
		wg:    wg,
		stop:  make(chan struct{}),
	}
}

func (w *Worker) Start() {
	w.wg.Add(1)
	go func() {
		defer w.wg.Done()
		for {
			select {
			case msg := <-w.ch:
				if msg == nil {
					continue
				}
				// Simulate processing
				// In a real system, do actual work here.
				latency := time.Since(time.Unix(0, msg.CreatedAt))
				w.stats.Record(latency)

			case <-w.stop:
				return
			}
		}
	}()
}

func (w *Worker) Stop() {
	close(w.stop)
}

type Router struct {
	workers []*Worker
	n       uint64
}

func NewRouter(workers []*Worker) *Router {
	return &Router{
		workers: workers,
		n:       uint64(len(workers)),
	}
}

func (r *Router) Route(msg *Message) {
	idx := msg.ShardKey % r.n
	r.workers[idx].ch <- msg
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	const (
		numWorkers   = 8
		bufferSize    = 65536
		numMessages   = 1000000
		producerBurst = 1024
	)

	stats := NewLatencyStats()
	var wg sync.WaitGroup

	workers := make([]*Worker, 0, numWorkers)
	for i := 0; i < numWorkers; i++ {
		w := NewWorker(i, bufferSize, stats, &wg)
		workers = append(workers, w)
		w.Start()
	}

	router := NewRouter(workers)

	start := time.Now()

	// Producer loop
	for i := 0; i < numMessages; i++ {
		msg := &Message{
			ID:       uint64(i),
			CreatedAt: time.Now().UnixNano(),
			Payload:   make([]byte, 128),
			ShardKey:  uint64(i),
		}
		router.Route(msg)

		// Optional burst pacing
		if i%producerBurst == 0 {
			runtime.Gosched()
		}
	}

	// Wait for queues to drain
	for {
		count, _, _, _ := stats.Snapshot()
		if count >= numMessages {
			break
		}
		time.Sleep(10 * time.Millisecond)
	}

	elapsed := time.Since(start)
	count, avg, min, max := stats.Snapshot()

	for _, w := range workers {
		w.Stop()
	}

	fmt.Printf("Messages: %d\n", count)
	fmt.Printf("Elapsed: %s\n", elapsed)
	fmt.Printf("Throughput: %.2f msg/s\n", float64(count)/elapsed.Seconds())
	fmt.Printf("Latency avg: %s min: %s max: %s\n", avg, min, max)
}
