### Latency tracker
This version uses a lock-free-ish histogram approach for approximate percentiles.

```java
import java.util.concurrent.atomic.LongAdder;
import java.util.concurrent.atomic.AtomicLongArray;

public final class LatencyTracker {
    private final LongAdder count = new LongAdder();
    private final LongAdder totalNanos = new LongAdder();
    private final AtomicLongArray buckets;

    // Buckets represent latency ranges in microseconds.
    // Example: bucket 0 = 0-1us, 1 = 1-2us, 2 = 2-4us, etc.
    public LatencyTracker(int bucketCount) {
        this.buckets = new AtomicLongArray(bucketCount);
    }

    public void record(long latencyNanos) {
        count.increment();
        totalNanos.add(latencyNanos);

        long micros = latencyNanos / 1_000;
        int bucket = bucketFor(micros);
        if (bucket >= buckets.length()) {
            bucket = buckets.length() - 1;
        }
        buckets.incrementAndGet(bucket);
    }

    private int bucketFor(long micros) {
        if (micros <= 0) return 0;
        int bucket = 0;
        long v = micros;
        while (v > 1 && bucket < 62) {
            v >>= 1;
            bucket++;
        }
        return bucket;
    }

    public long count() {
        return count.sum();
    }

    public double averageMicros() {
        long c = count.sum();
        if (c == 0) return 0.0;
        return (totalNanos.sum() / 1_000.0) / c;
    }

    public long percentileBucket(long percentile) {
        long target = (count.sum() * percentile) / 100;
        long running = 0;
        for (int i = 0; i < buckets.length(); i++) {
            running += buckets.get(i);
            if (running >= target) return i;
        }
        return buckets.length() - 1;
    }
}
