        while (running || !queue.isEmpty()) {
            try {
                Message msg = queue.poll();
                if (msg == null) {
                    Thread.onSpinWait();
                    continue;
                }

                process(msg);
                long latency = System.nanoTime() - msg.createdNanos;
                latencyTracker.record(latency);
            } catch (Exception e) {
