### Router
Routes messages to a shard based on routing key.

```java
import java.util.concurrent.atomic.AtomicInteger;

public final class Router {
    private final ShardWorker[] shards;
    private final AtomicInteger rr = new AtomicInteger(0);

    public Router(ShardWorker[] shards) {
        this.shards = shards;
    }

    public boolean route(Message msg) {
        int idx = Math.floorMod(msg.routingKey, shards.length);
        return shards[idx].submit(msg);
    }

    public boolean routeRoundRobin(Message msg) {
        int idx = Math.floorMod(rr.getAndIncrement(), shards.length);
        return shards[idx].submit(msg);
    }
}
