Below is an initial implementation sketch for a high-frequency messaging system designed to route very large volumes of messages with built-in latency monitoring. It focuses on a low-overhead in-memory pipeline, batching, and simple observability hooks.

## Design goals
- Very high throughput
- Low latency
- Minimal allocations
- Backpressure support
- Per-message latency tracking
- Easy to extend into a distributed system later

---

## Architecture

**Core components**
1. **Message**: lightweight envelope with timestamp and payload
2. **Ingress**: accepts messages from producers
3. **Router**: dispatches messages to destination handlers
4. **Workers**: process messages in batches
5. **Latency monitor**: records end-to-end and routing latency
6. **Backpressure**: bounded queues to avoid overload

---

## Initial implementation in Go

Go is a good fit for an initial version because of its concurrency model and relatively low runtime overhead.

### `main.go`
```go
package main

import (
	"fmt"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	CreatedAt time.Time
	Topic     uint32
	Payload   []byte
}

type RoutedMessage struct {
	Msg      Message
	RoutedAt time.Time
}

type LatencyStats struct {
	Count       uint64
	TotalNanos   uint64
	MaxNanos     uint64
	MinNanos     uint64
}

func (s *LatencyStats) Record(d time.Duration) {
	n := uint64(d.Nanoseconds())
	atomic.AddUint64(&s.Count, 1)
	atomic.AddUint64(&s.TotalNanos, n)

	for {
		oldMax := atomic.LoadUint64(&s.MaxNanos)
		if n <= oldMax || atomic.CompareAndSwapUint64(&s.MaxNanos, oldMax, n) {
			break
		}
	}

	for {
		oldMin := atomic.LoadUint64(&s.MinNanos)
		if oldMin != 0 && n >= oldMin || atomic.CompareAndSwapUint64(&s.MinNanos, oldMin, n) {
			break
		}
	}
}

func (s *LatencyStats) Snapshot() (count, avg, min, max time.Duration) {
	count = atomic.LoadUint64(&s.Count)
	total := atomic.LoadUint64(&s.TotalNanos)
	minN := atomic.LoadUint64(&s.MinNanos)
	maxN := atomic.LoadUint64(&s.MaxNanos)

	if count > 0 {
		avg = time.Duration(total / count)
	}
	if minN > 0 {
		min = time.Duration(minN)
	}
	max = time.Duration(maxN)
	return
}

type Router struct {
	workers   int
	inbound   chan Message
	handlers  map[uint32]func(Message)
	stats     *LatencyStats
	stopCh    chan struct{}
	wg        sync.WaitGroup
	processed uint64
}

func NewRouter(workers int, queueSize int) *Router {
	return &Router{
		workers:  workers,
		inbound:  make(chan Message, queueSize),
		handlers: make(map[uint32]func(Message)),
		stats:    &LatencyStats{},
		stopCh:   make(chan struct{}),
	}
}

func (r *Router) Register(topic uint32, handler func(Message)) {
	r.handlers[topic] = handler
}

func (r *Router) Start() {
	for i := 0; i < r.workers; i++ {
		r.wg.Add(1)
		go func() {
			defer r.wg.Done()
			batch := make([]Message, 0, 256)

			for {
				select {
				case <-r.stopCh:
					return
				case msg := <-r.inbound:
					batch = append(batch, msg)
					if len(batch) >= cap(batch) {
						r.processBatch(batch)
						batch = batch[:0]
					}
				default:
					if len(batch) > 0 {
						r.processBatch(batch)
						batch = batch[:0]
					} else {
						runtime.Gosched()
					}
				}
			}
		}()
	}
}

func (r *Router) processBatch(batch []Message) {
	for _, msg := range batch {
		handler, ok := r.handlers[msg.Topic]
		if ok {
			handler(msg)
		}
		latency := time.Since(msg.CreatedAt)
		r.stats.Record(latency)
		atomic.AddUint64(&r.processed, 1)
	}
}

func (r *Router) Submit(msg Message) bool {
	select {
	case r.inbound <- msg:
		return true
	default:
		return false
	}
}

func (r *Router) Stop() {
	close(r.stopCh)
	r.wg.Wait()
}

func (r *Router) Processed() uint64 {
	return atomic.LoadUint64(&r.processed)
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	router := NewRouter(8, 1_000_000)

	router.Register(1, func(msg Message) {
		_ = msg.Payload
	})

	router.Register(2, func(msg Message) {
		_ = msg.Payload
	})

	router.Start()

	// Producer simulation
	go func() {
		var id uint64
		ticker := time.NewTicker(1 * time.Microsecond)
		defer ticker.Stop()

		for range ticker.C {
			msg := Message{
				ID:        atomic.AddUint64(&id, 1),
				CreatedAt: time.Now(),
				Topic:     uint32(id%2 + 1),
				Payload:   []byte("hello"),
			}
			if !router.Submit(msg) {
				// Backpressure: drop or count rejected messages
			}
		}
	}()

	// Metrics reporter
	go func() {
		ticker := time.NewTicker(2 * time.Second)
		defer ticker.Stop()

		for range ticker.C {
			count, avg, min, max := router.stats.Snapshot()
			fmt.Printf("processed=%d avg=%s min=%s max=%s\n", count, avg, min, max)
		}
	}()

	log.Println("running...")
	select {}
}
```

