```go
package main

import (
	"fmt"
	"log"
	"math/rand"
	"sync"
	"sync/atomic"
	"time"
)

type Message struct {
	Topic     string
	Payload   []byte
	CreatedAt  int64 // unix nano
	SequenceID uint64
}

type Subscriber struct {
	ID   string
	ch   chan *Message
	done chan struct{}
}

func NewSubscriber(id string, buffer int) *Subscriber {
	return &Subscriber{
		ID:   id,
		ch:   make(chan *Message, buffer),
		done: make(chan struct{}),
	}
}

func (s *Subscriber) Start(process func(msg *Message, latency time.Duration)) {
	go func() {
		for {
			select {
			case msg := <-s.ch:
				if msg == nil {
					continue
				}
				latency := time.Since(time.Unix(0, msg.CreatedAt))
				process(msg, latency)
			case <-s.done:
				return
			}
		}
	}()
}

func (s *Subscriber) Stop() {
	close(s.done)
}

type Topic struct {
	name        string
	subscribers map[string]*Subscriber
	mu          sync.RWMutex
}

func NewTopic(name string) *Topic {
	return &Topic{
		name:        name,
		subscribers: make(map[string]*Subscriber),
	}
}

func (t *Topic) AddSubscriber(sub *Subscriber) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.subscribers[sub.ID] = sub
}

func (t *Topic) RemoveSubscriber(id string) {
	t.mu.Lock()
	defer t.mu.Unlock()
	delete(t.subscribers, id)
}

func (t *Topic) Publish(msg *Message, metrics *Metrics) {
	t.mu.RLock()
	defer t.mu.RUnlock()

	for _, sub := range t.subscribers {
		select {
		case sub.ch <- msg:
			metrics.IncDelivered()
		default:
			metrics.IncDropped()
		}
	}
}

type Router struct {
	topics map[string]*Topic
	mu     sync.RWMutex
}

func NewRouter() *Router {
	return &Router{
		topics: make(map[string]*Topic),
	}
}

func (r *Router) GetOrCreateTopic(name string) *Topic {
	r.mu.RLock()
	t, ok := r.topics[name]
	r.mu.RUnlock()
	if ok {
		return t
	}

	r.mu.Lock()
	defer r.mu.Unlock()

	if t, ok = r.topics[name]; ok {
		return t
	}

	t = NewTopic(name)
	r.topics[name] = t
	return t
}

func (r *Router) Publish(topic string, msg *Message, metrics *Metrics) {
	t := r.GetOrCreateTopic(topic)
	t.Publish(msg, metrics)
}

type Metrics struct {
	delivered uint64
	dropped   uint64
	latencyNs uint64
	count     uint64
}

func (m *Metrics) IncDelivered() {
	atomic.AddUint64(&m.delivered, 1)
}

func (m *Metrics) IncDropped() {
	atomic.AddUint64(&m.dropped, 1)
}

func (m *Metrics) ObserveLatency(d time.Duration) {
	atomic.AddUint64(&m.latencyNs, uint64(d.Nanoseconds()))
	atomic.AddUint64(&m.count, 1)
}

func (m *Metrics) Snapshot() (delivered, dropped, avgLatency time.Duration) {
	delivered = time.Duration(atomic.LoadUint64(&m.delivered))
	dropped = time.Duration(atomic.LoadUint64(&m.dropped))
	count := atomic.LoadUint64(&m.count)
	totalLatency := atomic.LoadUint64(&m.latencyNs)

	if count > 0 {
		avgLatency = time.Duration(totalLatency / count)
	}
	return
}

func main() {
	router := NewRouter()
	metrics := &Metrics{}

	// Create topic and subscribers
	topic := router.GetOrCreateTopic("orders")

	for i := 0; i < 4; i++ {
		sub := NewSubscriber(fmt.Sprintf("sub-%d", i), 1024)
		sub.Start(func(msg *Message, latency time.Duration) {
			metrics.ObserveLatency(latency)

			// Simulate lightweight processing
			_ = msg.Payload
		})
		topic.AddSubscriber(sub)
	}

	// Publisher loop
	var seq uint64
	stop := time.After(5 * time.Second)
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	go func() {
		for {
			msg := &Message{
				Topic:     "orders",
				Payload:   []byte("hello"),
				CreatedAt: time.Now().UnixNano(),
				SequenceID: atomic.AddUint64(&seq, 1),
			}
			router.Publish("orders", msg, metrics)
		}
	}()

	for {
		select {
		case <-ticker.C:
			delivered, dropped, avgLatency := metrics.Snapshot()
			log.Printf("delivered=%d dropped=%d avg_latency=%s", delivered, dropped, avgLatency)
		case <-stop:
			delivered, dropped, avgLatency := metrics.Snapshot()
			log.Printf("FINAL delivered=%d dropped=%d avg_latency=%s", delivered, dropped, avgLatency)
			return
		}
	}
}
