## Go implementation

```go
package main

import (
	"fmt"
	"log"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

// Message represents a single routed event.
type Message struct {
	ID        uint64
	Topic     string
	Payload   []byte
	CreatedAt time.Time
}

// Metrics tracks throughput and latency.
type Metrics struct {
	Published      uint64
	Routed         uint64
	Consumed       uint64
	Dropped        uint64
	TotalLatencyNs  uint64
	MaxLatencyNs    uint64
	MinLatencyNs    uint64
}

func (m *Metrics) Init() {
	atomic.StoreUint64(&m.MinLatencyNs, ^uint64(0))
}

func (m *Metrics) RecordLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.TotalLatencyNs, ns)

	for {
		old := atomic.LoadUint64(&m.MaxLatencyNs)
		if ns <= old || atomic.CompareAndSwapUint64(&m.MaxLatencyNs, old, ns) {
			break
		}
	}

	for {
		old := atomic.LoadUint64(&m.MinLatencyNs)
		if ns >= old || atomic.CompareAndSwapUint64(&m.MinLatencyNs, old, ns) {
			break
		}
	}
}

func (m *Metrics) AvgLatency() time.Duration {
	consumed := atomic.LoadUint64(&m.Consumed)
	if consumed == 0 {
		return 0
	}
	total := atomic.LoadUint64(&m.TotalLatencyNs)
	return time.Duration(total / consumed)
}

// Subscriber consumes messages from a dedicated queue.
type Subscriber struct {
	ID      string
	Queue   chan Message
	Handler func(Message)
	stop    chan struct{}
	wg      sync.WaitGroup
}

func NewSubscriber(id string, queueSize int, handler func(Message)) *Subscriber {
	return &Subscriber{
		ID:      id,
		Queue:   make(chan Message, queueSize),
		Handler: handler,
		stop:    make(chan struct{}),
	}
}

func (s *Subscriber) Start(metrics *Metrics) {
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()
		for {
			select {
			case msg := <-s.Queue:
				start := time.Now()
				s.Handler(msg)
				latency := time.Since(msg.CreatedAt)
				metrics.RecordLatency(latency)
				atomic.AddUint64(&metrics.Consumed, 1)

				_ = start // reserved for handler timing if needed
			case <-s.stop:
				return
			}
		}
	}()
}

func (s *Subscriber) Stop() {
	close(s.stop)
	s.wg.Wait()
}

// Broker routes messages to subscribers by topic.
type Broker struct {
	mu          sync.RWMutex
	subscribers map[string][]*Subscriber
	inbox       chan Message
	metrics     *Metrics
	stop        chan struct{}
	wg          sync.WaitGroup
}

func NewBroker(buffer int, metrics *Metrics) *Broker {
	return &Broker{
		subscribers: make(map[string][]*Subscriber),
		inbox:       make(chan Message, buffer),
		metrics:     metrics,
		stop:        make(chan struct{}),
	}
}

func (b *Broker) Subscribe(topic string, sub *Subscriber) {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.subscribers[topic] = append(b.subscribers[topic], sub)
}

func (b *Broker) Publish(msg Message) bool {
	select {
	case b.inbox <- msg:
		atomic.AddUint64(&b.metrics.Published, 1)
		return true
	default:
		atomic.AddUint64(&b.metrics.Dropped, 1)
		return false
	}
}

func (b *Broker) Start() {
	b.wg.Add(1)
	go func() {
		defer b.wg.Done()
		for {
			select {
			case msg := <-b.inbox:
				b.route(msg)
				atomic.AddUint64(&b.metrics.Routed, 1)
			case <-b.stop:
				return
			}
		}
	}()
}

func (b *Broker) route(msg Message) {
	b.mu.RLock()
	subs := b.subscribers[msg.Topic]
	b.mu.RUnlock()

	for _, sub := range subs {
		select {
		case sub.Queue <- msg:
		default:
			atomic.AddUint64(&b.metrics.Dropped, 1)
		}
	}
}

func (b *Broker) Stop() {
	close(b.stop)
	b.wg.Wait()
}

// ID generator
var globalID uint64

func nextID() uint64 {
	return atomic.AddUint64(&globalID, 1)
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	metrics := &Metrics{}
	metrics.Init()

	broker := NewBroker(1_000_000, metrics)
	broker.Start()

	// Example subscriber
	sub := NewSubscriber("sub-1", 100_000, func(msg Message) {
		// Simulate lightweight processing
		_ = msg.Payload
	})
	sub.Start(metrics)
	broker.Subscribe("orders", sub)

	// Publisher loop
	go func() {
		payload := []byte("hello world")
		for i := 0; i < 10_000_000; i++ {
			msg := Message{
				ID:        nextID(),
				Topic:     "orders",
				Payload:   payload,
				CreatedAt: time.Now(),
			}
			broker.Publish(msg)
		}
	}()

	// Metrics reporter
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()

	start := time.Now()
	for range ticker.C {
		published := atomic.LoadUint64(&metrics.Published)
		routed := atomic.LoadUint64(&metrics.Routed)
		consumed := atomic.LoadUint64(&metrics.Consumed)
		dropped := atomic.LoadUint64(&metrics.Dropped)

		elapsed := time.Since(start).Seconds()
		throughput := float64(consumed) / elapsed

		fmt.Printf(
			"published=%d routed=%d consumed=%d dropped=%d throughput=%.0f msg/s avg-latency=%s max-latency=%s min-latency=%s\n",
			published,
			routed,
			consumed,
			dropped,
			throughput,
			metrics.AvgLatency(),
			time.Duration(atomic.LoadUint64(&metrics.MaxLatencyNs)),
			time.Duration(atomic.LoadUint64(&metrics.MinLatencyNs)),
		)

		if consumed >= 10_000_000 {
			break
		}
	}

	sub.Stop()
	broker.Stop()

	log.Println("shutdown complete")
}
```

