### `main.go`

```go
package main

import (
	"fmt"
	"hash/fnv"
	"runtime"
	"sync"
	"sync/atomic"
	"time"
)

const (
	NumProducers   = 4
	NumConsumers   = 8
	QueueSize      = 1 << 16
	BatchSize      = 256
	RunSeconds     = 10
	MonitorEveryNs  = int64(time.Second)
	LatencyBuckets = 64
)

type Message struct {
	ID        uint64
	Key       uint64
	CreatedNs  int64
	Payload   [32]byte // fixed-size payload to avoid allocations
}

type Metrics struct {
	Count       uint64
	TotalLatencyNs uint64
	MaxLatencyNs uint64
	Buckets     [LatencyBuckets]uint64
}

func (m *Metrics) Record(latencyNs uint64) {
	atomic.AddUint64(&m.Count, 1)
	atomic.AddUint64(&m.TotalLatencyNs, latencyNs)

	for {
		old := atomic.LoadUint64(&m.MaxLatencyNs)
		if latencyNs <= old || atomic.CompareAndSwapUint64(&m.MaxLatencyNs, old, latencyNs) {
			break
		}
	}

	b := bucket(latencyNs)
	atomic.AddUint64(&m.Buckets[b], 1)
}

func bucket(ns uint64) int {
	// log2-ish buckets
	b := 0
	for ns > 0 && b < LatencyBuckets-1 {
		ns >>= 1
		b++
	}
	return b
}

type Router struct {
	consumers []chan Message
}

func NewRouter(n int) *Router {
	r := &Router{
		consumers: make([]chan Message, n),
	}
	for i := range r.consumers {
		r.consumers[i] = make(chan Message, QueueSize)
	}
	return r
}

func (r *Router) Route(msg Message) {
	idx := int(hashKey(msg.Key) % uint64(len(r.consumers)))
	r.consumers[idx] <- msg
}

func hashKey(k uint64) uint64 {
	h := fnv.New64a()
	var b [8]byte
	for i := 0; i < 8; i++ {
		b[i] = byte(k >> (8 * i))
	}
	_, _ = h.Write(b[:])
	return h.Sum64()
}

func producer(id int, out chan<- Message, stop <-chan struct{}, seq *uint64) {
	var payload [32]byte
	for i := range payload {
		payload[i] = byte(id)
	}

	for {
		select {
		case <-stop:
			return
		default:
			n := atomic.AddUint64(seq, 1)
			msg := Message{
				ID:       n,
				Key:      n % 1024,
				CreatedNs: time.Now().UnixNano(),
				Payload:  payload,
			}
			out <- msg
		}
	}
}

func routerLoop(in <-chan Message, r *Router, stop <-chan struct{}) {
	batch := make([]Message, 0, BatchSize)

	for {
		select {
		case <-stop:
			return
		case msg := <-in:
			batch = append(batch, msg)
			if len(batch) >= BatchSize {
				for _, m := range batch {
					r.Route(m)
				}
				batch = batch[:0]
			}
		default:
			if len(batch) > 0 {
				for _, m := range batch {
					r.Route(m)
				}
				batch = batch[:0]
			}
			runtime.Gosched()
		}
	}
}

func consumer(id int, in <-chan Message, metrics *Metrics, stop <-chan struct{}) {
	for {
		select {
		case <-stop:
			return
		case msg := <-in:
			latency := uint64(time.Now().UnixNano() - msg.CreatedNs)
			metrics.Record(latency)
		}
	}
}

func main() {
	runtime.GOMAXPROCS(runtime.NumCPU())

	stop := make(chan struct{})
	producerOut := make(chan Message, QueueSize)
	router := NewRouter(NumConsumers)

	var seq uint64
	var metrics Metrics

	// Start consumers
	var wg sync.WaitGroup
	for i := 0; i < NumConsumers; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			consumer(i, router.consumers[i], &metrics, stop)
		}(i)
	}

	// Start producers
	for i := 0; i < NumProducers; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			producer(i, producerOut, stop, &seq)
		}(i)
	}

	// Start router
	wg.Add(1)
	go func() {
		defer wg.Done()
		routerLoop(producerOut, router, stop)
	}()

	// Monitor
	start := time.Now()
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	go func() {
		<-time.After(RunSeconds * time.Second)
		close(stop)
	}()

	for {
		select {
		case <-stop:
			wg.Wait()
			elapsed := time.Since(start).Seconds()
			count := atomic.LoadUint64(&metrics.Count)
			total := atomic.LoadUint64(&metrics.TotalLatencyNs)
			max := atomic.LoadUint64(&metrics.MaxLatencyNs)

			avg := float64(0)
			if count > 0 {
				avg = float64(total) / float64(count)
			}

			fmt.Printf("messages=%d throughput=%.2f msg/s avg_latency=%.2f us max_latency=%.2f us\n",
				count, float64(count)/elapsed, avg/1000.0, float64(max)/1000.0)

			fmt.Println("latency buckets (log2 ns):")
			for i, v := range metrics.Buckets {
				if v > 0 {
					fmt.Printf("bucket[%d]=%d\n", i, v)
				}
			}
			return

		case <-ticker.C:
			count := atomic.LoadUint64(&metrics.Count)
			elapsed := time.Since(start).Seconds()
			fmt.Printf("live throughput=%.2f msg/s\n", float64(count)/elapsed)
		}
	}
}
