## File: `main.go`
```go
package main

import (
	"bufio"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync/atomic"
	"time"
)

type Message struct {
	ID        uint64
	Key       string
	Payload   string
	CreatedAt time.Time
}

type Metrics struct {
	received uint64
	routed   uint64
	processed uint64
	dropped  uint64

	latencySumNs uint64
	latencyMaxNs uint64
}

func (m *Metrics) IncReceived()  { atomic.AddUint64(&m.received, 1) }
func (m *Metrics) IncRouted()    { atomic.AddUint64(&m.routed, 1) }
func (m *Metrics) IncProcessed() { atomic.AddUint64(&m.processed, 1) }
func (m *Metrics) IncDropped()   { atomic.AddUint64(&m.dropped, 1) }

func (m *Metrics) ObserveLatency(d time.Duration) {
	ns := uint64(d.Nanoseconds())
	atomic.AddUint64(&m.latencySumNs, ns)
	for {
		old := atomic.LoadUint64(&m.latencyMaxNs)
		if ns <= old {
			return
		}
		if atomic.CompareAndSwapUint64(&m.latencyMaxNs, old, ns) {
			return
		}
	}
}

func (m *Metrics) Snapshot() string {
	received := atomic.LoadUint64(&m.received)
	routed := atomic.LoadUint64(&m.routed)
	processed := atomic.LoadUint64(&m.processed)
	dropped := atomic.LoadUint64(&m.dropped)
	sum := atomic.LoadUint64(&m.latencySumNs)
	max := atomic.LoadUint64(&m.latencyMaxNs)

	avg := uint64(0)
	if processed > 0 {
		avg = sum / processed
	}

	return fmt.Sprintf(
		"received %d\nrouted %d\nprocessed %d\ndropped %d\nlatency_avg_ns %d\nlatency_max_ns %d\n",
		received, routed, processed, dropped, avg, max,
	)
}

type Router struct {
	workers []chan Message
	metrics *Metrics
}

func NewRouter(workerCount int, queueSize int, metrics *Metrics) *Router {
	workers := make([]chan Message, workerCount)
	for i := range workers {
		workers[i] = make(chan Message, queueSize)
	}
	return &Router{workers: workers, metrics: metrics}
}

func (r *Router) Route(msg Message) {
	idx := int(hash(msg.Key) % uint64(len(r.workers)))
	select {
	case r.workers[idx] <- msg:
		r.metrics.IncRouted()
	default:
		r.metrics.IncDropped()
	}
}

func hash(s string) uint64 {
	var h uint64 = 1469598103934665603
	for i := 0; i < len(s); i++ {
		h ^= uint64(s[i])
		h *= 1099511628211
	}
	return h
}

func worker(id int, ch <-chan Message, metrics *Metrics) {
	for msg := range ch {
		// Simulate processing / forwarding
		_ = msg.Payload

		lat := time.Since(msg.CreatedAt)
		metrics.IncProcessed()
		metrics.ObserveLatency(lat)
	}
}

func startMetricsHTTP(metrics *Metrics) {
	http.HandleFunc("/metrics", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "text/plain; version=0.0.4")
		_, _ = w.Write([]byte(metrics.Snapshot()))
	})
	go func() {
		log.Println("metrics listening on :8080")
		log.Fatal(http.ListenAndServe(":8080", nil))
	}()
}

func handleConn(conn net.Conn, router *Router, metrics *Metrics) {
	defer conn.Close()

	scanner := bufio.NewScanner(conn)
	// Increase scanner buffer for larger messages
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)

	var id uint64
	for scanner.Scan() {
		line := scanner.Text()
		parts := strings.SplitN(line, "|", 2)
		if len(parts) != 2 {
			metrics.IncDropped()
			continue
		}

		key := parts[0]
		payload := parts[1]

		msg := Message{
			ID:        id,
			Key:       key,
			Payload:   payload,
			CreatedAt: time.Now(),
		}
		id++
		metrics.IncReceived()
		router.Route(msg)
	}
}

func startTCPServer(addr string, router *Router, metrics *Metrics) {
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		log.Fatal(err)
	}
	log.Println("tcp listening on", addr)

	for {
		conn, err := ln.Accept()
		if err != nil {
			continue
		}
		go handleConn(conn, router, metrics)
	}
}

func main() {
	workerCount := 8
	queueSize := 4096

	if v := os.Getenv("WORKERS"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			workerCount = n
		}
	}
	if v := os.Getenv("QUEUE_SIZE"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 {
			queueSize = n
		}
	}

	metrics := &Metrics{}
	router := NewRouter(workerCount, queueSize, metrics)

	for i := 0; i < workerCount; i++ {
		go worker(i, router.workers[i], metrics)
	}

	startMetricsHTTP(metrics)
	startTCPServer(":9000", router, metrics)
}
