```rust
use std::io;
use std::mem;
use std::os::unix::io::RawFd;
use std::ptr;
use std::time::Instant;

const ETH_P_ALL: u16 = 0x0003;

#[repr(C)]
#[derive(Clone, Copy)]
struct SockAddrLl {
    sll_family: u16,
    sll_protocol: u16,
    sll_ifindex: i32,
    sll_hatype: u16,
    sll_pkttype: u8,
    sll_halen: u8,
    sll_addr: [u8; 8],
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn open_packet_socket() -> io::Result<RawFd> {
    let fd = unsafe {
        libc::socket(
            libc::AF_PACKET,
            libc::SOCK_RAW,
            i32::from(htons(ETH_P_ALL)),
        )
    };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(fd)
}

fn bind_to_interface(fd: RawFd, ifindex: i32) -> io::Result<()> {
    let addr = SockAddrLl {
        sll_family: libc::AF_PACKET as u16,
        sll_protocol: htons(ETH_P_ALL),
        sll_ifindex: ifindex,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            fd,
            &addr as *const SockAddrLl as *const libc::sockaddr,
            mem::size_of::<SockAddrLl>() as libc::socklen_t,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn set_nonblocking(fd: RawFd) -> io::Result<()> {
    let flags = unsafe { libc::fcntl(fd, libc::F_GETFL) };
    if flags < 0 {
        return Err(io::Error::last_os_error());
    }
    let ret = unsafe { libc::fcntl(fd, libc::F_SETFL, flags | libc::O_NONBLOCK) };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

// Example filter:
// - drop empty frames
// - allow only IPv4 Ethernet frames (0x0800)
// - optionally inspect payload further
fn allow_packet(frame: &[u8]) -> bool {
    if frame.len() < 14 {
        return false;
    }
    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    ethertype == 0x0800
}

fn forward_packet(fd_out: RawFd, frame: &[u8]) -> io::Result<usize> {
    let sent = unsafe {
        libc::send(
            fd_out,
            frame.as_ptr() as *const libc::c_void,
            frame.len(),
            0,
        )
    };
    if sent < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(sent as usize)
}

fn main() -> io::Result<()> {
    // Replace with real interface indices
    let in_ifindex = 2;
    let out_ifindex = 3;

    let rx = open_packet_socket()?;
    let tx = open_packet_socket()?;

    bind_to_interface(rx, in_ifindex)?;
    bind_to_interface(tx, out_ifindex)?;

    set_nonblocking(rx)?;
    set_nonblocking(tx)?;

    // Optional: increase socket buffers
    let rcvbuf: i32 = 4 * 1024 * 1024;
    unsafe {
        libc::setsockopt(
            rx,
            libc::SOL_SOCKET,
            libc::SO_RCVBUF,
            &rcvbuf as *const i32 as *const libc::c_void,
            mem::size_of::<i32>() as libc::socklen_t,
        );
    }

    let mut buf = vec![0u8; 2048];
    let mut forwarded: u64 = 0;
    let mut dropped: u64 = 0;
    let start = Instant::now();

    loop {
        let n = unsafe {
            libc::recv(
                rx,
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::WouldBlock {
                continue;
            }
            eprintln!("recv error: {err}");
            continue;
        }

        let frame = &buf[..n as usize];

        if allow_packet(frame) {
            match forward_packet(tx, frame) {
                Ok(_) => forwarded += 1,
                Err(e) => eprintln!("send error: {e}"),
            }
        } else {
            dropped += 1;
        }

        if (forwarded + dropped) % 100_000 == 0 {
            let elapsed = start.elapsed().as_secs_f64();
            eprintln!(
                "stats: forwarded={}, dropped={}, pps={:.0}",
                forwarded,
                dropped,
                (forwarded + dropped) as f64 / elapsed.max(0.001)
            );
        }
    }
}
```

