struct Rule {
    allow_dst_port: Option<u16>,
    allow_src_ip: Option<Ipv4Addr>,
}

impl Rule {
    fn matches(&self, pkt: &Packet) -> bool {
        if let Some(port) = self.allow_dst_port {
            if pkt.dst_port != port {
                return false;
            }
        }
        if let Some(ip) = self.allow_src_ip {
            if pkt.src_ip != ip {
                return false;
            }
        }
        true
    }
}

struct FilterEngine {
    rules: Vec<Rule>,
}

impl FilterEngine {
    fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    fn decide(&self, pkt: &Packet) -> Action {
        if self.rules.iter().any(|r| r.matches(pkt)) {
            Action::Forward
        } else {
            Action::Drop
        }
    }
}

