use bytes::BytesMut;
use crossbeam_channel::{bounded, Receiver, Sender};
use parking_lot::RwLock;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

const MAX_PACKET_SIZE: usize = 2048;
const BATCH_SIZE: usize = 64;

#[derive(Clone, Debug)]
struct Packet {
    data: BytesMut,
}

#[derive(Clone, Debug)]
enum Action {
    Drop,
    Forward { out_port: u16 },
    Mirror { out_port: u16 },
}

#[derive(Clone, Debug)]
struct Rule {
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    proto: Option<u8>, // 6 TCP, 17 UDP, etc.
    action: Action,
}

#[derive(Default)]
struct RuleTable {
    rules: Vec<Rule>,
}

impl RuleTable {
    fn evaluate(&self, pkt: &Packet) -> Action {
        if let Some(hdr) = parse_ipv4_l4(&pkt.data) {
            for rule in &self.rules {
                if rule_matches(rule, &hdr) {
                    return rule.action.clone();
                }
            }
        }
        Action::Drop
    }
}

#[derive(Debug)]
struct ParsedHdr {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    proto: u8,
}

fn rule_matches(rule: &Rule, hdr: &ParsedHdr) -> bool {
    if let Some(ip) = rule.src_ip {
        if ip != hdr.src_ip {
            return false;
        }
    }
    if let Some(ip) = rule.dst_ip {
        if ip != hdr.dst_ip {
            return false;
        }
    }
    if let Some(p) = rule.src_port {
        if Some(p) != hdr.src_port {
            return false;
        }
    }
    if let Some(p) = rule.dst_port {
        if Some(p) != hdr.dst_port {
            return false;
        }
    }
    if let Some(proto) = rule.proto {
        if proto != hdr.proto {
            return false;
        }
    }
    true
}

fn parse_ipv4_l4(data: &[u8]) -> Option<ParsedHdr> {
    if data.len() < 34 {
        return None;
    }

    // Ethernet header: 14 bytes
    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    if ethertype != 0x0800 {
        return None; // IPv4 only
    }

    let ip_start = 14;
    let version_ihl = data[ip_start];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || data.len() < ip_start + ihl {
        return None;
    }

    let proto = data[ip_start + 9];
    let src_ip = Ipv4Addr::new(
        data[ip_start + 12],
        data[ip_start + 13],
        data[ip_start + 14],
        data[ip_start + 15],
    );
    let dst_ip = Ipv4Addr::new(
        data[ip_start + 16],
        data[ip_start + 17],
        data[ip_start + 18],
        data[ip_start + 19],
    );

    let l4_start = ip_start + ihl;
    let (src_port, dst_port) = match proto {
        6 | 17 => {
            if data.len() < l4_start + 4 {
                return None;
            }
            let sp = u16::from_be_bytes([data[l4_start], data[l4_start + 1]]);
            let dp = u16::from_be_bytes([data[l4_start + 2], data[l4_start + 3]]);
            (Some(sp), Some(dp))
        }
        _ => (None, None),
    };

    Some(ParsedHdr {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    })
}

struct Engine {
    rules: Arc<RwLock<RuleTable>>,
    ingress_rx: Receiver<Packet>,
    egress_tx: Sender<(u16, Packet)>,
}

impl Engine {
    fn run(self) {
        loop {
            let mut batch = Vec::with_capacity(BATCH_SIZE);

            for _ in 0..BATCH_SIZE {
                match self.ingress_rx.try_recv() {
                    Ok(pkt) => batch.push(pkt),
                    Err(_) => break,
                }
            }

            if batch.is_empty() {
                thread::sleep(Duration::from_micros(50));
                continue;
            }

            let rules = self.rules.read().clone();
            for pkt in batch {
                match rules.evaluate(&pkt) {
                    Action::Drop => {
                        // drop
                    }
                    Action::Forward { out_port } => {
                        let _ = self.egress_tx.send((out_port, pkt));
                    }
                    Action::Mirror { out_port } => {
                        let _ = self.egress_tx.send((out_port, pkt.clone()));
                        // original continues elsewhere if desired
                    }
                }
            }
        }
    }
}

fn main() {
    let rules = Arc::new(RwLock::new(RuleTable {
        rules: vec![
            Rule {
                src_ip: Some(Ipv4Addr::new(10, 0, 0, 10)),
                dst_ip: None,
                src_port: None,
                dst_port: Some(443),
                proto: Some(6),
                action: Action::Forward { out_port: 2 },
            },
            Rule {
                src_ip: None,
                dst_ip: Some(Ipv4Addr::new(192, 168, 1, 100)),
                src_port: None,
                dst_port: None,
                proto: None,
                action: Action::Drop,
            },
        ],
    }));

    let (ingress_tx, ingress_rx) = bounded::<Packet>(8192);
    let (egress_tx, egress_rx) = bounded::<(u16, Packet)>(8192);

    let engine = Engine {
        rules: rules.clone(),
        ingress_rx,
        egress_tx,
    };

    thread::spawn(move || engine.run());

    // Simulated packet producer
    let producer = thread::spawn(move || {
        loop {
            let mut pkt = BytesMut::with_capacity(MAX_PACKET_SIZE);
            pkt.resize(64, 0);

            // Minimal fake Ethernet+IPv4+TCP packet for demo purposes
            pkt[12] = 0x08;
            pkt[13] = 0x00; // IPv4
            pkt[14] = 0x45; // IPv4, IHL=5
            pkt[23] = 6;    // TCP
            pkt[26] = 10;
            pkt[27] = 0;
            pkt[28] = 0;
            pkt[29] = 10;
            pkt[30] = 93;
            pkt[31] = 184;
            pkt[32] = 216;
            pkt[33] = 34;
            pkt[34] = 1;
            pkt[35] = 187; // src port 443
            pkt[36] = 1;
            pkt[37] = 0;   // dst port 256

            let _ = ingress_tx.send(Packet { data: pkt });
            thread::sleep(Duration::from_micros(10));
        }
    });

    // Simulated egress consumer
    thread::spawn(move || {
        while let Ok((port, _pkt)) = egress_rx.recv() {
            println!("Forwarded packet to port {}", port);
        }
