/// Mock source for demonstration.
struct MockSource {
    frames: Vec<Vec<u8>>,
    idx: usize,
}

impl MockSource {
    fn new(frames: Vec<Vec<u8>>) -> Self {
        Self { frames, idx: 0 }
    }
}

impl PacketSource for MockSource {
    fn recv_batch<'a>(&'a mut self, out: &mut Vec<Packet<'a>>) -> usize {
        out.clear();
        let batch_size = 32;
        let mut count = 0;

        while self.idx < self.frames.len() && count < batch_size {
            let frame = &self.frames[self.idx];
            out.push(Packet { data: frame });
            self.idx += 1;
            count += 1;
        }

        count
    }
}

/// Mock sink for demonstration.
struct MockSink;

impl PacketSink for MockSink {
    fn send_batch(&mut self, packets: &[Packet<'_>]) {
        println!("Forwarding {} packets", packets.len());
    }
}

fn run_forwarder<S: PacketSource, T: PacketSink>(
    mut source: S,
    mut sink: T,
    engine: FilterEngine,
) {
    let mut batch: Vec<Packet<'_>> = Vec::with_capacity(64);
    let mut forward_buf: Vec<Packet<'_>> = Vec::with_capacity(64);

    loop {
        let n = source.recv_batch(&mut batch);
        if n == 0 {
            break;
        }

        forward_buf.clear();

        for pkt in &batch {
            match engine.classify(pkt) {
                Action::Allow => {
                    forward_buf.push(*pkt);
                }
                Action::Forward(_egress) => {
                    forward_buf.push(*pkt);
                }
                Action::Drop => {
                    // drop
                }
            }
        }

        if !forward_buf.is_empty() {
            sink.send_batch(&forward_buf);
        }
    }
}

