use anyhow::{Context, Result};
use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum L4Proto {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
struct PacketMeta {
    src_mac: [u8; 6],
    dst_mac: [u8; 6],
    ethertype: u16,
    vlan_id: Option<u16>,

    src_v4: Option<Ipv4Addr>,
    dst_v4: Option<Ipv4Addr>,
    src_v6: Option<Ipv6Addr>,
    dst_v6: Option<Ipv6Addr>,

    l4_proto: Option<L4Proto>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
}

#[derive(Debug, Clone)]
enum Action {
    Allow,
    Drop,
    Forward { out_port: usize },
}

#[derive(Debug, Clone)]
struct Rule {
    // Simple example rule fields
    src_v4: Option<Ipv4Addr>,
    dst_v4: Option<Ipv4Addr>,
    l4_proto: Option<L4Proto>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    action: Action,
}

#[derive(Default)]
struct Counters {
    rx_pkts: AtomicU64,
    rx_bytes: AtomicU64,
    tx_pkts: AtomicU64,
    tx_bytes: AtomicU64,
    dropped: AtomicU64,
    parse_errors: AtomicU64,
}

struct Engine {
    rules: Vec<Rule>,
    counters: Arc<Counters>,
}

impl Engine {
    fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules,
            counters: Arc::new(Counters::default()),
        }
    }

    fn classify(&self, meta: &PacketMeta) -> Action {
        for r in &self.rules {
            if let Some(ip) = r.src_v4 {
                if meta.src_v4 != Some(ip) { continue; }
            }
            if let Some(ip) = r.dst_v4 {
                if meta.dst_v4 != Some(ip) { continue; }
            }
            if let Some(p) = r.l4_proto {
                if meta.l4_proto != Some(p) { continue; }
            }
            if let Some(p) = r.src_port {
                if meta.src_port != Some(p) { continue; }
            }
            if let Some(p) = r.dst_port {
                if meta.dst_port != Some(p) { continue; }
            }
            return r.action.clone();
        }
        Action::Drop
    }
}

// -------------------- Packet parsing --------------------

fn parse_packet(buf: &[u8]) -> Result<PacketMeta> {
    if buf.len() < 14 {
        anyhow::bail!("short ethernet frame");
    }

    let mut meta = PacketMeta {
        src_mac: buf[6..12].try_into().unwrap(),
        dst_mac: buf[0..6].try_into().unwrap(),
        ethertype: u16::from_be_bytes([buf[12], buf[13]]),
        vlan_id: None,
        src_v4: None,
        dst_v4: None,
        src_v6: None,
        dst_v6: None,
        l4_proto: None,
        src_port: None,
        dst_port: None,
    };

    let mut offset = 14;
    let mut ethertype = meta.ethertype;

    // VLAN tag
    if ethertype == 0x8100 && buf.len() >= 18 {
        meta.vlan_id = Some(u16::from_be_bytes([buf[14], buf[15]]) & 0x0fff);
        ethertype = u16::from_be_bytes([buf[16], buf[17]]);
        offset = 18;
    }

    match ethertype {
        0x0800 => parse_ipv4(buf, offset, &mut meta)?,
        0x86DD => parse_ipv6(buf, offset, &mut meta)?,
        _ => {}
    }

    Ok(meta)
}

fn parse_ipv4(buf: &[u8], offset: usize, meta: &mut PacketMeta) -> Result<()> {
    if buf.len() < offset + 20 {
        anyhow::bail!("short ipv4 header");
    }
    let ihl = (buf[offset] & 0x0f) as usize * 4;
    if ihl < 20 || buf.len() < offset + ihl {
        anyhow::bail!("invalid ipv4 ihl");
    }

    let proto = buf[offset + 9];
    meta.src_v4 = Some(Ipv4Addr::new(
        buf[offset + 12],
        buf[offset + 13],
        buf[offset + 14],
        buf[offset + 15],
    ));
    meta.dst_v4 = Some(Ipv4Addr::new(
        buf[offset + 16],
        buf[offset + 17],
        buf[offset + 18],
        buf[offset + 19],
    ));
    meta.l4_proto = Some(match proto {
        6 => L4Proto::Tcp,
        17 => L4Proto::Udp,
        1 => L4Proto::Icmp,
        x => L4Proto::Other(x),
    });

    let l4_off = offset + ihl;
    parse_l4(buf, l4_off, meta)?;
    Ok(())
}

fn parse_ipv6(buf: &[u8], offset: usize, meta: &mut PacketMeta) -> Result<()> {
    if buf.len() < offset + 40 {
        anyhow::bail!("short ipv6 header");
    }

    let next_header = buf[offset + 6];
    meta.src_v6 = Some(Ipv6Addr::from(buf[offset + 8..offset + 24].try_into().unwrap()));
    meta.dst_v6 = Some(Ipv6Addr::from(buf[offset + 24..offset + 40].try_into().unwrap()));
    meta.l4_proto = Some(match next_header {
        6 => L4Proto::Tcp,
        17 => L4Proto::Udp,
        58 => L4Proto::Icmp,
        x => L4Proto::Other(x),
    });

    let l4_off = offset + 40;
    parse_l4(buf, l4_off, meta)?;
    Ok(())
}

fn parse_l4(buf: &[u8], offset: usize, meta: &mut PacketMeta) -> Result<()> {
    match meta.l4_proto {
        Some(L4Proto::Tcp) => {
            if buf.len() < offset + 20 {
                anyhow::bail!("short tcp header");
            }
            meta.src_port = Some(u16::from_be_bytes([buf[offset], buf[offset + 1]]));
            meta.dst_port = Some(u16::from_be_bytes([buf[offset + 2], buf[offset + 3]]));
        }
        Some(L4Proto::Udp) => {
            if buf.len() < offset + 8 {
                anyhow::bail!("short udp header");
            }
            meta.src_port = Some(u16::from_be_bytes([buf[offset], buf[offset + 1]]));
            meta.dst_port = Some(u16::from_be_bytes([buf[offset + 2], buf[offset + 3]]));
        }
        _ => {}
    }
    Ok(())
}

// -------------------- Forwarding hook --------------------

trait Forwarder {
    fn send(&self, out_port: usize, frame: &[u8]) -> Result<()>;
}

struct DummyForwarder;

impl Forwarder for DummyForwarder {
    fn send(&self, out_port: usize, frame: &[u8]) -> Result<()> {
        // Replace with AF_XDP TX ring, DPDK, io_uring+veth, or NIC-specific TX path.
        let _ = (out_port, frame);
        Ok(())
    }
}

// -------------------- Main dataplane loop --------------------

fn process_frame<F: Forwarder>(
    engine: &Engine,
    fwd: &F,
    frame: &[u8],
) -> Result<()> {
    engine.counters.rx_pkts.fetch_add(1, Ordering::Relaxed);
    engine.counters.rx_bytes.fetch_add(frame.len() as u64, Ordering::Relaxed);

    let meta = match parse_packet(frame) {
        Ok(m) => m,
        Err(_) => {
            engine.counters.parse_errors.fetch_add(1, Ordering::Relaxed);
            engine.counters.dropped.fetch_add(1, Ordering::Relaxed);
            return Ok(());
        }
    };

    match engine.classify(&meta) {
        Action::Allow => {
            // In a real implementation, you might forward based on routing table.
            engine.counters.dropped.fetch_add(1, Ordering::Relaxed);
        }
        Action::Drop => {
            engine.counters.dropped.fetch_add(1, Ordering::Relaxed);
        }
        Action::Forward { out_port } => {
            fwd.send(out_port, frame)?;
            engine.counters.tx_pkts.fetch_add(1, Ordering::Relaxed);
            engine.counters.tx_bytes.fetch_add(frame.len() as u64, Ordering::Relaxed);
        }
    }

    Ok(())
}

