```rust
use pnet::datalink::{self, Channel::Ethernet};
use pnet::packet::ethernet::{EtherTypes, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::env;
use std::net::Ipv4Addr;
use std::time::Instant;

fn allow_packet(buf: &[u8]) -> bool {
    if let Some(eth) = pnet::packet::ethernet::EthernetPacket::new(buf) {
        match eth.get_ethertype() {
            EtherTypes::Ipv4 => {
                if let Some(ipv4) = Ipv4Packet::new(eth.payload()) {
                    let src = ipv4.get_source();
                    let dst = ipv4.get_destination();

                    // Example policy:
                    // - drop traffic from a blocked source
                    // - allow only specific destination subnet
                    let blocked_src = Ipv4Addr::new(10, 0, 0, 66);
                    let allowed_prefix = Ipv4Addr::new(192, 168, 1, 0);
                    let mask = Ipv4Addr::new(255, 255, 255, 0);

                    let src_u32 = u32::from(src);
                    let blocked_u32 = u32::from(blocked_src);
                    if src_u32 == blocked_u32 {
                        return false;
                    }

                    let dst_u32 = u32::from(dst);
                    let prefix_u32 = u32::from(allowed_prefix);
                    let mask_u32 = u32::from(mask);

                    if (dst_u32 & mask_u32) != (prefix_u32 & mask_u32) {
                        return false;
                    }

                    // Example: optionally inspect transport protocol
                    match ipv4.get_next_level_protocol() {
                        IpNextHeaderProtocols::Tcp => {
                            if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                                let dport = tcp.get_destination();
                                // Allow only HTTP/HTTPS
                                return dport == 80 || dport == 443;
                            }
                            false
                        }
                        IpNextHeaderProtocols::Udp => {
                            if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                                let dport = udp.get_destination();
                                // Allow DNS
                                return dport == 53;
                            }
                            false
                        }
                        _ => false,
                    }
                } else {
                    false
                }
            }
            _ => false,
        }
    } else {
        false
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <input_iface> <output_iface>", args[0]);
        std::process::exit(1);
    }

    let in_name = &args[1];
    let out_name = &args[2];

    let interfaces = datalink::interfaces();
    let in_iface = interfaces
        .iter()
        .find(|iface| &iface.name == in_name)
        .expect("input interface not found")
        .clone();
    let out_iface = interfaces
        .iter()
        .find(|iface| &iface.name == out_name)
        .expect("output interface not found")
        .clone();

    let config = datalink::Config {
        read_timeout: None,
        write_buffer_size: 1 << 20,
        read_buffer_size: 1 << 20,
        ..Default::default()
    };

    let (_, mut rx) = match datalink::channel(&in_iface, config.clone()) {
        Ok(Ethernet(tx, rx)) => (tx, rx),
        Ok(_) => panic!("unhandled channel type"),
        Err(e) => panic!("failed to open input channel: {}", e),
    };

    let mut tx = match datalink::channel(&out_iface, config) {
        Ok(Ethernet(tx, _rx)) => tx,
        Ok(_) => panic!("unhandled channel type"),
        Err(e) => panic!("failed to open output channel: {}", e),
    };

    let mut forwarded = 0u64;
    let mut dropped = 0u64;
    let start = Instant::now();

    loop {
        match rx.next() {
            Ok(packet) => {
                if allow_packet(packet) {
                    if let Some(eth) = MutableEthernetPacket::owned(packet.to_vec()) {
                        let bytes = eth.packet();
                        match tx.send_to(bytes, None) {
                            Some(Ok(())) => forwarded += 1,
                            Some(Err(_)) | None => dropped += 1,
                        }
                    } else {
                        dropped += 1;
                    }
                } else {
                    dropped += 1;
                }

                if (forwarded + dropped) % 10000 == 0 {
                    let elapsed = start.elapsed().as_secs_f64();
                    eprintln!(
                        "pkts={} fwd={} drop={} rate={:.0} pkt/s",
                        forwarded + dropped,
                        forwarded,
                        dropped,
                        (forwarded + dropped) as f64 / elapsed.max(0.001)
                    );
                }
            }
            Err(_) => {
                dropped += 1;
            }
        }
    }
}
