use libc::{c_void, sockaddr_ll, AF_PACKET, ETH_P_ALL, PACKET_ADD_MEMBERSHIP, PACKET_MR_PROMISC};
use nix::errno::Errno;
use nix::sys::socket::{
    bind, recv, sendto, socket, AddressFamily, MsgFlags, SockFlag, SockProtocol, SockType,
};
use nix::unistd::close;
use std::env;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::fd::RawFd;
use std::str::FromStr;

const ETH_HDR_LEN: usize = 14;
const ARP_ETHERTYPE: u16 = 0x0806;
const IPV4_ETHERTYPE: u16 = 0x0800;
const TCP_PROTO: u8 = 6;
const UDP_PROTO: u8 = 17;

#[derive(Clone, Debug)]
struct FilterConfig {
    allowed_tcp_ports: Vec<u16>,
    allowed_udp_ports: Vec<u16>,
    allow_arp: bool,
}

impl FilterConfig {
    fn default() -> Self {
        Self {
            allowed_tcp_ports: vec![80, 443],
            allowed_udp_ports: vec![53],
            allow_arp: true,
        }
    }
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn parse_ethertype(frame: &[u8]) -> Option<u16> {
    if frame.len() < ETH_HDR_LEN {
        return None;
    }
    Some(u16::from_be_bytes([frame[12], frame[13]]))
}

fn parse_ipv4_proto(frame: &[u8]) -> Option<u8> {
    if frame.len() < ETH_HDR_LEN + 20 {
        return None;
    }
    let ethertype = parse_ethertype(frame)?;
    if ethertype != IPV4_ETHERTYPE {
        return None;
    }
    let ihl = (frame[14] & 0x0f) as usize * 4;
    if frame.len() < ETH_HDR_LEN + ihl {
        return None;
    }
    Some(frame[23])
}

fn parse_l4_dst_port(frame: &[u8]) -> Option<u16> {
    let ethertype = parse_ethertype(frame)?;
    if ethertype != IPV4_ETHERTYPE {
        return None;
    }

    let ihl = (frame[14] & 0x0f) as usize * 4;
    if frame.len() < ETH_HDR_LEN + ihl + 4 {
        return None;
    }

    let proto = frame[23];
    let l4 = ETH_HDR_LEN + ihl;

    match proto {
        TCP_PROTO | UDP_PROTO => {
            let dst = u16::from_be_bytes([frame[l4 + 2], frame[l4 + 3]]);
            Some(dst)
        }
        _ => None,
    }
}

fn should_forward(frame: &[u8], cfg: &FilterConfig) -> bool {
    match parse_ethertype(frame) {
        Some(ARP_ETHERTYPE) => cfg.allow_arp,
        Some(IPV4_ETHERTYPE) => {
            match parse_ipv4_proto(frame) {
                Some(TCP_PROTO) => {
                    if let Some(port) = parse_l4_dst_port(frame) {
                        cfg.allowed_tcp_ports.contains(&port)
                    } else {
                        false
                    }
                }
                Some(UDP_PROTO) => {
                    if let Some(port) = parse_l4_dst_port(frame) {
                        cfg.allowed_udp_ports.contains(&port)
                    } else {
                        false
                    }
                }
                _ => false,
            }
        }
        _ => false,
    }
}

fn open_packet_socket(ifindex: i32) -> io::Result<RawFd> {
    let fd = socket(
        AddressFamily::Packet,
        SockType::Raw,
        SockFlag::empty(),
        SockProtocol::from((ETH_P_ALL as u16).to_be() as i32),
    )
    .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    let sll = sockaddr_ll {
        sll_family: AF_PACKET as u16,
        sll_protocol: htons(ETH_P_ALL as u16),
        sll_ifindex: ifindex,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            fd,
            &sll as *const sockaddr_ll as *const libc::sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        let e = Errno::last();
        let _ = close(fd);
        return Err(io::Error::from_raw_os_error(e as i32));
    }

    Ok(fd)
}

fn ifindex_from_name(name: &str) -> io::Result<i32> {
    let c_name = std::ffi::CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(c_name.as_ptr()) };
    if idx == 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(idx as i32)
    }
}

fn forward_loop(in_fd: RawFd, out_fd: RawFd, cfg: FilterConfig) -> io::Result<()> {
    let mut buf = vec![0u8; 65536];

    loop {
        let n = recv(in_fd, &mut buf, MsgFlags::empty())
            .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

        if n == 0 {
            continue;
        }

        let frame = &buf[..n];

        if should_forward(frame, &cfg) {
            // Forward raw frame as-is.
            // In a real deployment, you may want to rewrite L2 headers,
            // enforce VLAN policy, or apply egress ACLs.
            let sent = sendto(
                out_fd,
                frame,
                MsgFlags::empty(),
                None::<&nix::sys::socket::SockaddrStorage>,
            )
            .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

            if sent != n {
                eprintln!("short send: {} of {}", sent, n);
            }
        }
    }
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} <in_if> <out_if>", args[0]);
        std::process::exit(1);
    }

    let in_if = &args[1];
    let out_if = &args[2];

    let in_idx = ifindex_from_name(in_if)?;
    let out_idx = ifindex_from_name(out_if)?;

    let in_fd = open_packet_socket(in_idx)?;
    let out_fd = open_packet_socket(out_idx)?;

    let cfg = FilterConfig::default();

    eprintln!(
        "Forwarding from {} -> {} with config: {:?}",
        in_if, out_if, cfg
    );

    let res = forward_loop(in_fd, out_fd, cfg);

    let _ = close(in_fd);
    let _ = close(out_fd);

    res
}
