const BUF_SIZE: usize = 2048;

fn should_forward(packet: &[u8]) -> bool {
    // Example filter:
    // - forward only packets with at least 4 bytes
    // - and first byte not equal to 0x13
    packet.len() >= 4 && packet[0] != 0x13
