    let listen_addr: SocketAddr = "0.0.0.0:9000".parse().unwrap();
    let target_addr: SocketAddr = "127.0.0.1:9001".parse().unwrap();

    let recv_sock = UdpSocket::bind(listen_addr)?;
    recv_sock.set_nonblocking(false)?;

    let send_sock = UdpSocket::bind("0.0.0.0:0")?;
    send_sock.connect(target_addr)?;

    let mut buf = [0u8; BUF_SIZE];

    eprintln!("listening on {}, forwarding to {}", listen_addr, target_addr);

    loop {
        let start = Instant::now();
        let (len, src) = recv_sock.recv_from(&mut buf)?;

        let packet = &buf[..len];
        if should_forward(packet) {
            let sent = send_sock.send(packet)?;
            eprintln!(
                "forwarded {} bytes from {} in {:?}",
                sent,
                src,
                start.elapsed()
            );
        } else {
            eprintln!("dropped {} bytes from {} in {:?}", len, src, start.elapsed());
        }
    }
}
