```rust
use std::net::{SocketAddr, UdpSocket};
use std::sync::mpsc::{sync_channel, SyncSender};
use std::thread;
use std::time::Duration;

use pcap::{Capture, Device};

#[derive(Clone, Debug)]
struct Packet {
    data: Vec<u8>,
}

fn is_allowed_packet(pkt: &[u8]) -> bool {
    // Example filter:
    // - allow IPv4 UDP packets
    // - drop everything else
    if pkt.len() < 34 {
        return false;
    }

    // Ethernet type IPv4
    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    if ethertype != 0x0800 {
        return false;
    }

    // IPv4 protocol field
    let ip_header_start = 14;
    let ihl = (pkt[ip_header_start] & 0x0f) as usize * 4;
    if pkt.len() < ip_header_start + ihl + 8 {
        return false;
    }

    let protocol = pkt[ip_header_start + 9];
    protocol == 17 // UDP
}

fn forward_packet(sock: &UdpSocket, dst: SocketAddr, pkt: &[u8]) -> std::io::Result<usize> {
    // In a real forwarder, you would rewrite headers and checksum as needed.
    // Here we just send the raw bytes to a UDP endpoint for demonstration.
    sock.send_to(pkt, dst)
}

fn capture_loop(tx: SyncSender<Packet>, iface: &str) -> anyhow::Result<()> {
    let mut cap = Capture::from_device(iface)?
        .promisc(true)
        .immediate_mode(true)
        .timeout(1)
        .open()?;

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                if is_allowed_packet(packet.data) {
                    let _ = tx.try_send(Packet {
                        data: packet.data.to_vec(),
                    });
                }
            }
            Err(_) => {
                // Avoid busy spinning on transient errors
                thread::sleep(Duration::from_micros(50));
            }
        }
    }
}

fn worker_loop(rx: std::sync::mpsc::Receiver<Packet>, dst: SocketAddr) -> anyhow::Result<()> {
    let sock = UdpSocket::bind("0.0.0.0:0")?;
    sock.set_nonblocking(true)?;

    while let Ok(pkt) = rx.recv() {
        let _ = forward_packet(&sock, dst, &pkt.data);
    }

    Ok(())
}

fn main() -> anyhow::Result<()> {
    let iface = std::env::args().nth(1).unwrap_or_else(|| "eth0".to_string());
    let dst: SocketAddr = std::env::args()
        .nth(2)
        .unwrap_or_else(|| "127.0.0.1:9000".to_string())
        .parse()?;

    let (tx, rx) = sync_channel::<Packet>(4096);

    let cap_iface = iface.clone();
    let cap_tx = tx.clone();

    let capture_thread = thread::spawn(move || {
        if let Err(e) = capture_loop(cap_tx, &cap_iface) {
            eprintln!("capture error: {e:?}");
        }
    });

    let worker_thread = thread::spawn(move || {
        if let Err(e) = worker_loop(rx, dst) {
            eprintln!("worker error: {e:?}");
        }
    });

    let _ = capture_thread.join();
    let _ = worker_thread.join();

    Ok(())
}
```

