use anyhow::{Context, Result};
use libc::*;
use std::ffi::CString;
use std::io;
use std::mem;
use std::os::fd::RawFd;
use std::ptr;
use std::thread;
use std::time::Duration;

const ETH_P_ALL: u16 = 0x0003;

fn htons(u: u16) -> u16 {
    u.to_be()
}

fn open_packet_socket(iface: &str) -> Result<RawFd> {
    unsafe {
        let fd = socket(AF_PACKET, SOCK_RAW, i32::from(htons(ETH_P_ALL)));
        if fd < 0 {
            return Err(io::Error::last_os_error()).context("socket(AF_PACKET) failed");
        }

        let ifname = CString::new(iface)?;
        let ifindex = if_nametoindex(ifname.as_ptr());
        if ifindex == 0 {
            return Err(io::Error::last_os_error()).context("if_nametoindex failed");
        }

        let mut sll: sockaddr_ll = mem::zeroed();
        sll.sll_family = AF_PACKET as u16;
        sll.sll_protocol = htons(ETH_P_ALL);
        sll.sll_ifindex = ifindex as i32;

        let ret = bind(
            fd,
            &sll as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        );
        if ret < 0 {
            return Err(io::Error::last_os_error()).context("bind(AF_PACKET) failed");
        }

        Ok(fd)
    }
}

fn set_promiscuous(fd: RawFd, iface: &str) -> Result<()> {
    unsafe {
        let ifname = CString::new(iface)?;
        let ifindex = if_nametoindex(ifname.as_ptr());
        if ifindex == 0 {
            return Err(io::Error::last_os_error()).context("if_nametoindex failed");
        }

        let mut mreq: packet_mreq = mem::zeroed();
        mreq.mr_ifindex = ifindex as i32;
        mreq.mr_type = PACKET_MR_PROMISC as u16;

        let ret = setsockopt(
            fd,
            SOL_PACKET,
            PACKET_ADD_MEMBERSHIP,
            &mreq as *const packet_mreq as *const c_void,
            mem::size_of::<packet_mreq>() as u32,
        );
        if ret < 0 {
            return Err(io::Error::last_os_error()).context("setsockopt(PACKET_ADD_MEMBERSHIP) failed");
        }
        Ok(())
    }
}

fn should_forward(frame: &[u8]) -> bool {
    // Very simple example filter:
    // - require Ethernet header
    // - drop broadcast/multicast
    // - allow only IPv4 frames
    if frame.len() < 14 {
        return false;
    }

    let dst = &frame[0..6];
    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);

    let is_broadcast = dst.iter().all(|&b| b == 0xff);
    let is_multicast = (dst[0] & 0x01) == 0x01;

    if is_broadcast || is_multicast {
        return false;
    }

    ethertype == 0x0800 // IPv4
}

fn forward_frame(tx_fd: RawFd, frame: &[u8]) -> Result<()> {
    unsafe {
        let ret = send(tx_fd, frame.as_ptr() as *const c_void, frame.len(), 0);
        if ret < 0 {
            return Err(io::Error::last_os_error()).context("send failed");
        }
    }
    Ok(())
}

fn main() -> Result<()> {
    let rx_iface = "eth0";
    let tx_iface = "eth1";

    let rx_fd = open_packet_socket(rx_iface)?;
    let tx_fd = open_packet_socket(tx_iface)?;

    // Optional: enable promiscuous mode on receive interface
    let _ = set_promiscuous(rx_fd, rx_iface);

    // Increase socket buffers for burst handling
    unsafe {
        let rcvbuf: c_int = 8 * 1024 * 1024;
        setsockopt(
            rx_fd,
            SOL_SOCKET,
            SO_RCVBUF,
            &rcvbuf as *const c_int as *const c_void,
            mem::size_of::<c_int>() as u32,
        );
        let sndbuf: c_int = 8 * 1024 * 1024;
        setsockopt(
            tx_fd,
            SOL_SOCKET,
            SO_SNDBUF,
            &sndbuf as *const c_int as *const c_void,
            mem::size_of::<c_int>() as u32,
        );
    }

    let mut buf = vec![0u8; 65536];

    loop {
        let n = unsafe {
            recv(
                rx_fd,
                buf.as_mut_ptr() as *mut c_void,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            eprintln!("recv error: {err}");
            thread::sleep(Duration::from_millis(1));
            continue;
        }

        let n = n as usize;
        let frame = &buf[..n];

        if should_forward(frame) {
            if let Err(e) = forward_frame(tx_fd, frame) {
                eprintln!("forward error: {e}");
            }
        }
    }
}
