// Cargo.toml dependencies:
// [dependencies]
// libc = "0.2"
// nix = { version = "0.29", features = ["net", "socket"] }

use libc::{c_void, sockaddr_ll, AF_PACKET, ETH_P_ALL, PACKET_ADD_MEMBERSHIP, PACKET_MR_PROMISC};
use nix::errno::Errno;
use nix::sys::socket::{
    bind, recv, sendto, socket, AddressFamily, MsgFlags, SockFlag, SockProtocol, SockType,
    SockaddrLike,
};
use nix::unistd::close;
use std::collections::HashSet;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::fd::RawFd;
use std::str::FromStr;

#[derive(Clone, Debug)]
struct RuleSet {
    blocked_ips: HashSet<Ipv4Addr>,
    allowed_ports: HashSet<u16>,
}

impl RuleSet {
    fn new() -> Self {
        Self {
            blocked_ips: HashSet::new(),
            allowed_ports: HashSet::new(),
        }
    }

    fn allow_port(mut self, port: u16) -> Self {
        self.allowed_ports.insert(port);
        self
    }

    fn block_ip(mut self, ip: Ipv4Addr) -> Self {
        self.blocked_ips.insert(ip);
        self
    }

    fn should_drop(&self, pkt: &[u8]) -> bool {
        // Minimal Ethernet + IPv4 + TCP/UDP parsing.
        // Returns true if packet should be dropped.
        if pkt.len() < 14 {
            return true;
        }

        let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
        if ethertype != 0x0800 {
            // Non-IPv4: forward by default or drop depending on policy.
            return false;
        }

        if pkt.len() < 14 + 20 {
            return true;
        }

        let ip = &pkt[14..];
        let ihl = ((ip[0] & 0x0f) as usize) * 4;
        if ihl < 20 || ip.len() < ihl {
            return true;
        }

        let proto = ip[9];
        let src = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
        let dst = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

        if self.blocked_ips.contains(&src) || self.blocked_ips.contains(&dst) {
            return true;
        }

        // If port allowlist is configured, enforce it for TCP/UDP.
        if !self.allowed_ports.is_empty() && (proto == 6 || proto == 17) {
            if ip.len() < ihl + 4 {
                return true;
            }
            let l4 = &ip[ihl..];
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            if !self.allowed_ports.contains(&src_port) && !self.allowed_ports.contains(&dst_port) {
                return true;
            }
        }

        false
    }
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn open_packet_socket(ifindex: i32) -> io::Result<RawFd> {
    let fd = socket(
        AddressFamily::Packet,
        SockType::Raw,
        SockFlag::empty(),
        SockProtocol::EthAll,
    )
    .map_err(to_io)?;

    let sll = sockaddr_ll {
        sll_family: AF_PACKET as u16,
        sll_protocol: htons(ETH_P_ALL as u16),
        sll_ifindex: ifindex,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    bind(fd, &sll).map_err(to_io)?;
    Ok(fd)
}

fn ifindex_from_name(name: &str) -> io::Result<i32> {
    let c_name = std::ffi::CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(c_name.as_ptr()) };
    if idx == 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(idx as i32)
    }
}

fn forward_packet(tx_fd: RawFd, out_ifindex: i32, pkt: &[u8]) -> io::Result<usize> {
    let sll = sockaddr_ll {
        sll_family: AF_PACKET as u16,
        sll_protocol: htons(ETH_P_ALL as u16),
        sll_ifindex: out_ifindex,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    sendto(tx_fd, pkt, &sll, MsgFlags::empty()).map_err(to_io)
}

fn to_io(err: nix::Error) -> io::Error {
    match err {
        nix::Error::Sys(errno) => io::Error::from_raw_os_error(errno as i32),
        other => io::Error::new(io::ErrorKind::Other, other.to_string()),
    }
}

fn main() -> io::Result<()> {
    // Example: receive on eth0, forward to eth1.
    let in_if = "eth0";
    let out_if = "eth1";

    let in_ifindex = ifindex_from_name(in_if)?;
    let out_ifindex = ifindex_from_name(out_if)?;

    let rx_fd = open_packet_socket(in_ifindex)?;
    let tx_fd = open_packet_socket(out_ifindex)?;

    let rules = RuleSet::new()
        .block_ip(Ipv4Addr::from_str("10.0.0.66").unwrap())
        .allow_port(80)
        .allow_port(443);

    let mut buf = vec![0u8; 65536];

    loop {
        let n = match recv(rx_fd, &mut buf, MsgFlags::empty()) {
            Ok(n) => n,
            Err(nix::Error::Sys(Errno::EINTR)) => continue,
            Err(e) => {
                eprintln!("recv error: {}", e);
                continue;
            }
        };

        let pkt = &buf[..n];

        if rules.should_drop(pkt) {
            continue;
        }

        if let Err(e) = forward_packet(tx_fd, out_ifindex, pkt) {
            eprintln!("forward error: {}", e);
        }
    }

    // unreachable
