use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, Ordering},
    Arc,
};
use std::thread;
use std::time::Instant;

const MAX_BATCH: usize = 64;
const ETH_P_IPV4: u16 = 0x0800;
const ETH_P_ARP: u16 = 0x0806;

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct EthernetHeader {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct Ipv4Header {
    version_ihl: u8,
    dscp_ecn: u8,
    total_length: u16,
    identification: u16,
    flags_fragment: u16,
    ttl: u8,
    protocol: u8,
    checksum: u16,
    src: u32,
    dst: u32,
}

#[derive(Clone, Copy, Debug)]
enum Action {
    Drop,
    Forward(u16), // output port
    Pass,
}

struct Packet<'a> {
    data: &'a [u8],
}

impl<'a> Packet<'a> {
    fn eth(&self) -> Option<EthernetHeader> {
        if self.data.len() < std::mem::size_of::<EthernetHeader>() {
            return None;
        }
        let mut hdr = EthernetHeader {
            dst: [0; 6],
            src: [0; 6],
            ethertype: 0,
        };
        unsafe {
            std::ptr::copy_nonoverlapping(
                self.data.as_ptr(),
                &mut hdr as *mut EthernetHeader as *mut u8,
                std::mem::size_of::<EthernetHeader>(),
            );
        }
        hdr.ethertype = u16::from_be(hdr.ethertype);
        Some(hdr)
    }

    fn ipv4(&self) -> Option<Ipv4Header> {
        let off = std::mem::size_of::<EthernetHeader>();
        if self.data.len() < off + std::mem::size_of::<Ipv4Header>() {
            return None;
        }
        let mut hdr = Ipv4Header {
            version_ihl: 0,
            dscp_ecn: 0,
            total_length: 0,
            identification: 0,
            flags_fragment: 0,
            ttl: 0,
            protocol: 0,
            checksum: 0,
            src: 0,
            dst: 0,
        };
        unsafe {
            std::ptr::copy_nonoverlapping(
                self.data[off..].as_ptr(),
                &mut hdr as *mut Ipv4Header as *mut u8,
                std::mem::size_of::<Ipv4Header>(),
            );
        }
        hdr.total_length = u16::from_be(hdr.total_length);
        hdr.identification = u16::from_be(hdr.identification);
        hdr.flags_fragment = u16::from_be(hdr.flags_fragment);
        hdr.checksum = u16::from_be(hdr.checksum);
        hdr.src = u32::from_be(hdr.src);
        hdr.dst = u32::from_be(hdr.dst);
        Some(hdr)
    }
}

struct FilterConfig {
    allowed_src: Option<Ipv4Addr>,
    allowed_dst: Option<Ipv4Addr>,
    drop_arp: bool,
    min_ttl: u8,
}

impl Default for FilterConfig {
    fn default() -> Self {
        Self {
            allowed_src: None,
            allowed_dst: None,
            drop_arp: false,
            min_ttl: 1,
        }
    }
}

struct ForwardingTable {
    // In a real implementation this would be a lock-free table or precomputed trie.
    default_port: u16,
}

impl ForwardingTable {
    fn lookup(&self, _pkt: &Packet) -> Action {
        Action::Forward(self.default_port)
    }
}

struct Metrics {
    rx_packets: u64,
    tx_packets: u64,
    dropped_packets: u64,
    forwarded_packets: u64,
}

impl Metrics {
    fn new() -> Self {
        Self {
            rx_packets: 0,
            tx_packets: 0,
            dropped_packets: 0,
            forwarded_packets: 0,
        }
    }
}

fn ipv4_addr_from_u32(v: u32) -> Ipv4Addr {
    Ipv4Addr::from(v)
}

fn filter_packet(pkt: &Packet, cfg: &FilterConfig) -> Action {
    let eth = match pkt.eth() {
        Some(h) => h,
        None => return Action::Drop,
    };

    match eth.ethertype {
        ETH_P_ARP if cfg.drop_arp => return Action::Drop,
        ETH_P_IPV4 => {}
        _ => return Action::Pass,
    }

    let ip = match pkt.ipv4() {
        Some(h) => h,
        None => return Action::Drop,
    };

    let ttl = ip.ttl;
    if ttl < cfg.min_ttl {
        return Action::Drop;
    }

    if let Some(src) = cfg.allowed_src {
        if ipv4_addr_from_u32(ip.src) != src {
            return Action::Drop;
        }
    }

    if let Some(dst) = cfg.allowed_dst {
        if ipv4_addr_from_u32(ip.dst) != dst {
            return Action::Drop;
        }
    }

    Action::Pass
}

struct PacketSource;
struct PacketSink;

impl PacketSource {
    fn recv_batch<'a>(&'a self, _buf: &'a mut [Vec<u8>]) -> usize {
        0
    }
}

impl PacketSink {
    fn send_batch(&self, _pkts: &[Vec<u8>]) -> usize {
        0
    }
}

fn process_batch(
    rx: &PacketSource,
    tx: &PacketSink,
    filter_cfg: &FilterConfig,
    fwd: &ForwardingTable,
    metrics: &mut Metrics,
) {
    let mut batch: Vec<Vec<u8>> = (0..MAX_BATCH).map(|_| Vec::with_capacity(2048)).collect();
    let n = rx.recv_batch(&mut batch);

    if n == 0 {
        return;
    }

    metrics.rx_packets += n as u64;

    let mut out: Vec<Vec<u8>> = Vec::with_capacity(n);

    for i in 0..n {
        let pkt = Packet { data: &batch[i] };

        match filter_packet(&pkt, filter_cfg) {
            Action::Drop => {
                metrics.dropped_packets += 1;
            }
            Action::Pass => match fwd.lookup(&pkt) {
                Action::Drop => {
                    metrics.dropped_packets += 1;
                }
                Action::Forward(_port) => {
                    // In a real implementation, enqueue to the selected output ring/queue.
                    out.push(batch[i].clone());
                    metrics.forwarded_packets += 1;
                }
                Action::Pass => {
                    out.push(batch[i].clone());
                    metrics.forwarded_packets += 1;
                }
            },
            Action::Forward(_port) => {
                out.push(batch[i].clone());
                metrics.forwarded_packets += 1;
            }
        }
    }

    let sent = tx.send_batch(&out);
    metrics.tx_packets += sent as u64;
}

fn main() {
    let running = Arc::new(AtomicBool::new(true));
    let r = running.clone();

    let filter_cfg = FilterConfig {
        allowed_src: None,
        allowed_dst: None,
        drop_arp: true,
        min_ttl: 1,
    };

    let fwd = ForwardingTable { default_port: 0 };
    let rx = PacketSource;
    let tx = PacketSink;

    let worker = thread::spawn(move || {
        let mut metrics = Metrics::new();
        let mut last_report = Instant::now();

        while r.load(Ordering::Relaxed) {
            process_batch(&rx, &tx, &filter_cfg, &fwd, &mut metrics);

            if last_report.elapsed().as_secs() >= 1 {
                println!(
                    "rx={} tx={} fwd={} drop={}",
                    metrics.rx_packets,
                    metrics.tx_packets,
                    metrics.forwarded_packets,
                    metrics.dropped_packets
                );
                last_report = Instant::now();
            }
        }
    });

    // In a real service, install signal handlers and set running=false on SIGINT/SIGTERM.
    worker.join().unwrap();
}
