    protocol: Option<u8>,
    action: Action,
}

impl Rule {
    fn matches(&self, p: &Packet) -> bool {
        self.src_ip.map_or(true, |ip| ip == p.src_ip)
            && self.dst_ip.map_or(true, |ip| ip == p.dst_ip)
            && self.src_port.map_or(true, |port| port == p.src_port)
            && self.dst_port.map_or(true, |port| port == p.dst_port)
            && self.protocol.map_or(true, |proto| proto == p.protocol)
    }
