use bytes::BytesMut;
use crossbeam::queue::ArrayQueue;
use hashbrown::HashMap;
use std::net::Ipv4Addr;
use std::sync::{
    atomic::{AtomicBool, AtomicU64, Ordering},
    Arc, Mutex,
};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src: Ipv4Addr,
    dst: Ipv4Addr,
    proto: u8,
    src_port: u16,
    dst_port: u16,
}

#[derive(Debug)]
enum Decision {
    Allow,
    Drop,
    Forward(u16), // output port
}

struct Packet {
    data: BytesMut,
    ingress_port: u16,
}

struct Stats {
    rx: AtomicU64,
    tx: AtomicU64,
    dropped: AtomicU64,
}

impl Stats {
    fn new() -> Self {
        Self {
            rx: AtomicU64::new(0),
            tx: AtomicU64::new(0),
            dropped: AtomicU64::new(0),
        }
    }
}

struct Engine {
    running: AtomicBool,
    stats: Arc<Stats>,
    flow_counters: Mutex<HashMap<FlowKey, u64>>,
    rxq: Arc<ArrayQueue<Packet>>,
    txq: Arc<ArrayQueue<Packet>>,
}

impl Engine {
    fn new(queue_size: usize) -> Self {
        Self {
            running: AtomicBool::new(true),
            stats: Arc::new(Stats::new()),
            flow_counters: Mutex::new(HashMap::new()),
            rxq: Arc::new(ArrayQueue::new(queue_size)),
            txq: Arc::new(ArrayQueue::new(queue_size)),
        }
    }

    fn classify(&self, pkt: &Packet) -> Decision {
        // Minimal parser for IPv4 + TCP/UDP.
        // In production, validate lengths carefully and use a robust parser.
        if pkt.data.len() < 34 {
            return Decision::Drop;
        }

        let ethertype = u16::from_be_bytes([pkt.data[12], pkt.data[13]]);
        if ethertype != 0x0800 {
            return Decision::Drop; // only IPv4 in this example
        }

        let ihl = (pkt.data[14] & 0x0f) as usize * 4;
        let proto = pkt.data[23];
        let src = Ipv4Addr::new(pkt.data[26], pkt.data[27], pkt.data[28], pkt.data[29]);
        let dst = Ipv4Addr::new(pkt.data[30], pkt.data[31], pkt.data[32], pkt.data[33]);

        let l4_off = 14 + ihl;
        if pkt.data.len() < l4_off + 4 {
            return Decision::Drop;
        }

        let src_port = u16::from_be_bytes([pkt.data[l4_off], pkt.data[l4_off + 1]]);
        let dst_port = u16::from_be_bytes([pkt.data[l4_off + 2], pkt.data[l4_off + 3]]);

        let key = FlowKey {
            src,
            dst,
            proto,
            src_port,
            dst_port,
        };

        {
            let mut flows = self.flow_counters.lock().unwrap();
            *flows.entry(key).or_insert(0) += 1;
        }

        // Example policy:
        // - drop RFC1918-to-RFC1918 traffic on port 25
        // - forward everything else to port 1
        if dst_port == 25 {
            return Decision::Drop;
        }

        Decision::Forward(1)
    }

    fn process_packet(&self, pkt: Packet) {
        self.stats.rx.fetch_add(1, Ordering::Relaxed);

        match self.classify(&pkt) {
            Decision::Allow => {
                // In a real implementation, send to local consumer or stack.
                self.stats.tx.fetch_add(1, Ordering::Relaxed);
            }
            Decision::Drop => {
                self.stats.dropped.fetch_add(1, Ordering::Relaxed);
            }
            Decision::Forward(_port) => {
                // In a real implementation, enqueue to TX ring for that port.
                let _ = self.txq.push(pkt);
                self.stats.tx.fetch_add(1, Ordering::Relaxed);
            }
        }
    }

    fn run(self: Arc<Self>) {
        let rx_engine = self.clone();
        let worker = thread::spawn(move || {
            while rx_engine.running.load(Ordering::Relaxed) {
                if let Some(pkt) = rx_engine.rxq.pop() {
                    rx_engine.process_packet(pkt);
                } else {
                    std::hint::spin_loop();
                }
            }
        });

        let tx_engine = self.clone();
        let tx_thread = thread::spawn(move || {
            while tx_engine.running.load(Ordering::Relaxed) {
                if let Some(_pkt) = tx_engine.txq.pop() {
                    // Replace with actual NIC transmit path.
                    // This is intentionally a stub.
                } else {
                    std::hint::spin_loop();
                }
            }
        });

        let stats = self.stats.clone();
        let monitor = thread::spawn(move || {
            let start = Instant::now();
            while start.elapsed() < Duration::from_secs(5) {
                thread::sleep(Duration::from_secs(1));
                println!(
                    "rx={} tx={} dropped={}",
                    stats.rx.load(Ordering::Relaxed),
                    stats.tx.load(Ordering::Relaxed),
                    stats.dropped.load(Ordering::Relaxed)
                );
            }
        });

        let _ = monitor.join();
        self.running.store(false, Ordering::Relaxed);
        let _ = worker.join();
        let _ = tx_thread.join();
    }
}

fn main() {
