use crate::packet::{Packet, Protocol};
use dashmap::DashMap;
use std::net::IpAddr;
use std::sync::Arc;

#[derive(Clone, Debug)]
pub enum FilterAction {
    Allow,
    Drop,
    ForwardTo(String),
}

#[derive(Clone, Debug)]
pub struct FilterRule {
    pub src_ip: Option<IpAddr>,
    pub dst_ip: Option<IpAddr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub protocol: Option<Protocol>,
    pub action: FilterAction,
}

impl FilterRule {
    pub fn matches(&self, pkt: &Packet) -> bool {
        if let Some(ip) = self.src_ip {
            if pkt.src_ip != ip {
                return false;
            }
        }
        if let Some(ip) = self.dst_ip {
            if pkt.dst_ip != ip {
                return false;
            }
        }
        if let Some(port) = self.src_port {
            if pkt.src_port != port {
                return false;
            }
        }
        if let Some(port) = self.dst_port {
            if pkt.dst_port != port {
                return false;
            }
        }
        if let Some(proto) = self.protocol {
            if pkt.protocol != proto {
                return false;
            }
        }
        true
    }
}

#[derive(Clone)]
pub struct PacketFilter {
    rules: Arc<DashMap<u64, FilterRule>>,
}

impl PacketFilter {
    pub fn new() -> Self {
        Self {
            rules: Arc::new(DashMap::new()),
        }
    }

    pub fn add_rule(&self, id: u64, rule: FilterRule) {
        self.rules.insert(id, rule);
    }

    pub fn remove_rule(&self, id: u64) {
        self.rules.remove(&id);
    }

    pub fn evaluate(&self, pkt: &Packet) -> FilterAction {
        for entry in self.rules.iter() {
            let rule = entry.value();
            if rule.matches(pkt) {
                return rule.action.clone();
            }
        }
        FilterAction::Drop
    }
}
