fn worker_loop(
    rx: Receiver<Packet>,
    filter: PacketFilter,
    forwarder: Forwarder,
    metrics: Arc<Metrics>,
) {
    while let Ok(pkt) = rx.recv() {
        metrics.inc_received();

        match filter.evaluate(&pkt) {
            FilterAction::Allow => {
                metrics.inc_allowed();
            }
            FilterAction::Drop => {
                metrics.inc_dropped();
            }
            FilterAction::ForwardTo(target) => {
                if forwarder.forward(&target, &pkt).is_ok() {
                    metrics.inc_forwarded();
                } else {
                    metrics.inc_errors();
                }
            }
        }
    }
}

