            dst_port: Some(443),
            protocol: Some(Protocol::Tcp),
            action: FilterAction::ForwardTo("edge-a".to_string()),
        },
    );

    let (tx, rx) = bounded::<Packet>(65_536);

    let worker_filter = filter.clone();
    let worker_forwarder = forwarder.clone();
    let worker_metrics = metrics.clone();

    thread::spawn(move || worker_loop(rx, worker_filter, worker_forwarder, worker_metrics));
    thread::spawn(move || packet_source(tx));

    loop {
        thread::sleep(Duration::from_secs(5));
        let (received, allowed, dropped, forwarded, errors) = metrics.snapshot();
        println!(
            "metrics: received={received} allowed={allowed} dropped={dropped} forwarded={forwarded} errors={errors}"
        );
    }
}
