```rust
use anyhow::{Context, Result};
use clap::Parser;
use libc::{c_void, sockaddr_ll, AF_PACKET, ETH_P_ALL, PACKET_ADD_MEMBERSHIP, PACKET_MR_PROMISC, SOL_PACKET};
use std::ffi::CString;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};
use std::ptr;
use std::time::Instant;

const MAX_FRAME_SIZE: usize = 2048;
const POOL_SIZE: usize = 4096;

#[derive(Parser, Debug)]
struct Args {
    /// Input interface
    #[arg(long)]
    ingress: String,

    /// Output interface
    #[arg(long)]
    egress: String,

    /// Optional IPv4 source allowlist (comma-separated)
    #[arg(long, default_value = "")]
    allow_src: String,

    /// Optional IPv4 destination allowlist (comma-separated)
    #[arg(long, default_value = "")]
    allow_dst: String,
}

#[derive(Clone, Debug)]
struct RuleSet {
    allow_src: Vec<Ipv4Addr>,
    allow_dst: Vec<Ipv4Addr>,
}

impl RuleSet {
    fn from_args(args: &Args) -> Self {
        let allow_src = parse_ip_list(&args.allow_src);
        let allow_dst = parse_ip_list(&args.allow_dst);
        Self { allow_src, allow_dst }
    }

    fn allow_packet(&self, pkt: &[u8]) -> bool {
        // Minimal Ethernet + IPv4 parsing
        if pkt.len() < 14 {
            return false;
        }

        let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
        if ethertype != 0x0800 {
            // Only IPv4 allowed in this initial implementation
            return false;
        }

        if pkt.len() < 14 + 20 {
            return false;
        }

        let ip = &pkt[14..];
        let version_ihl = ip[0];
        let version = version_ihl >> 4;
        let ihl = (version_ihl & 0x0f) as usize * 4;
        if version != 4 || ihl < 20 || ip.len() < ihl {
            return false;
        }

        let src = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
        let dst = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

        if !self.allow_src.is_empty() && !self.allow_src.contains(&src) {
            return false;
        }
        if !self.allow_dst.is_empty() && !self.allow_dst.contains(&dst) {
            return false;
        }

        true
    }
}

fn parse_ip_list(s: &str) -> Vec<Ipv4Addr> {
    if s.trim().is_empty() {
        return Vec::new();
    }
    s.split(',')
        .filter_map(|x| x.trim().parse::<Ipv4Addr>().ok())
        .collect()
}

struct PacketSocket {
    fd: OwnedFd,
}

impl PacketSocket {
    fn open(interface: &str, promisc: bool) -> Result<Self> {
        unsafe {
            let fd = libc::socket(AF_PACKET, libc::SOCK_RAW, (ETH_P_ALL as u16).to_be() as i32);
            if fd < 0 {
                return Err(io::Error::last_os_error()).context("socket(AF_PACKET) failed");
            }
            let fd = OwnedFd::from_raw_fd(fd);

            let ifname = CString::new(interface)?;
            let ifindex = libc::if_nametoindex(ifname.as_ptr());
            if ifindex == 0 {
                return Err(io::Error::last_os_error()).context("if_nametoindex failed");
            }

            let mut sll: sockaddr_ll = mem::zeroed();
            sll.sll_family = AF_PACKET as u16;
            sll.sll_protocol = (ETH_P_ALL as u16).to_be();
            sll.sll_ifindex = ifindex as i32;

            let bind_ret = libc::bind(
                fd.as_raw_fd(),
                &sll as *const sockaddr_ll as *const libc::sockaddr,
                mem::size_of::<sockaddr_ll>() as u32,
            );
            if bind_ret < 0 {
                return Err(io::Error::last_os_error()).context("bind(AF_PACKET) failed");
            }

            if promisc {
                let mut mreq: libc::packet_mreq = mem::zeroed();
                mreq.mr_ifindex = ifindex as i32;
                mreq.mr_type = PACKET_MR_PROMISC as u16;
                let ret = libc::setsockopt(
                    fd.as_raw_fd(),
                    SOL_PACKET,
                    PACKET_ADD_MEMBERSHIP,
                    &mreq as *const libc::packet_mreq as *const c_void,
                    mem::size_of::<libc::packet_mreq>() as u32,
                );
                if ret < 0 {
                    return Err(io::Error::last_os_error()).context("setsockopt(PACKET_MR_PROMISC) failed");
                }
            }

            Ok(Self { fd })
        }
    }

    fn recv_into(&self, buf: &mut [u8]) -> Result<usize> {
        let ret = unsafe {
            libc::recv(
                self.fd.as_raw_fd(),
                buf.as_mut_ptr() as *mut c_void,
                buf.len(),
                0,
            )
        };
        if ret < 0 {
            Err(io::Error::last_os_error()).context("recv failed")
        } else {
            Ok(ret as usize)
        }
    }

    fn send(&self, buf: &[u8]) -> Result<usize> {
        let ret = unsafe {
            libc::send(
                self.fd.as_raw_fd(),
                buf.as_ptr() as *const c_void,
                buf.len(),
                0,
            )
        };
        if ret < 0 {
            Err(io::Error::last_os_error()).context("send failed")
        } else {
            Ok(ret as usize)
        }
    }
}

struct PacketPool {
    bufs: Vec<Vec<u8>>,
    idx: usize,
}

impl PacketPool {
    fn new() -> Self {
        let mut bufs = Vec::with_capacity(POOL_SIZE);
        for _ in 0..POOL_SIZE {
            bufs.push(vec![0u8; MAX_FRAME_SIZE]);
        }
        Self { bufs, idx: 0 }
    }

    fn next(&mut self) -> &mut [u8] {
        let i = self.idx;
        self.idx = (self.idx + 1) % self.bufs.len();
        &mut self.bufs[i]
    }
}

#[derive(Default)]
struct Stats {
    rx: u64,
    forwarded: u64,
    dropped: u64,
    errors: u64,
}

fn main() -> Result<()> {
    let args = Args::parse();
    let rules = RuleSet::from_args(&args);

    let ingress = PacketSocket::open(&args.ingress, true)
        .with_context(|| format!("opening ingress {}", args.ingress))?;
    let egress = PacketSocket::open(&args.egress, false)
        .with_context(|| format!("opening egress {}", args.egress))?;

    let mut pool = PacketPool::new();
    let mut stats = Stats::default();
    let mut last_report = Instant::now();

    loop {
        let buf = pool.next();
        match ingress.recv_into(buf) {
            Ok(n) => {
                stats.rx += 1;
                let pkt = &buf[..n];

                if rules.allow_packet(pkt) {
                    match egress.send(pkt) {
                        Ok(_) => stats.forwarded += 1,
                        Err(_) => stats.errors += 1,
                    }
                } else {
                    stats.dropped += 1;
                }
            }
            Err(_) => {
                stats.errors += 1;
            }
        }

        if last_report.elapsed().as_secs() >= 1 {
            eprintln!(
                "rx={} forwarded={} dropped={} errors={}",
                stats.rx, stats.forwarded, stats.dropped, stats.errors
            );
            last_report = Instant::now();
        }
    }
}
```

