## 1) `src/packet_filter.hpp`

```cpp
#pragma once
#include <cstdint>
#include <vector>
#include <optional>

enum class Action : uint8_t {
    Drop,
    Forward,
    Pass
};

struct PacketView {
    const uint8_t* data{};
    size_t len{};
};

struct Rule {
    // Very simple L3/L4 filter fields
    std::optional<uint32_t> src_ip;   // IPv4 host order
    std::optional<uint32_t> dst_ip;   // IPv4 host order
    std::optional<uint16_t> src_port;
    std::optional<uint16_t> dst_port;
    std::optional<uint8_t>  proto;    // e.g. 6 TCP, 17 UDP
    Action action{Action::Drop};
};

class PacketFilter {
public:
    void add_rule(Rule r) { rules_.push_back(r); }

    Action evaluate(const PacketView& pkt) const {
        // Minimal IPv4 parser
        if (pkt.len < 14 + 20) return Action::Drop;

        const uint8_t* eth = pkt.data;
        uint16_t ethertype = (uint16_t(eth[12]) << 8) | eth[13];
        if (ethertype != 0x0800) return Action::Drop; // IPv4 only

        const uint8_t* ip = pkt.data + 14;
        uint8_t ihl = ip[0] & 0x0F;
        if (ihl < 5) return Action::Drop;
        size_t ip_hdr_len = ihl * 4;
        if (pkt.len < 14 + ip_hdr_len) return Action::Drop;

        uint8_t proto = ip[9];
        uint32_t src_ip = (uint32_t(ip[12]) << 24) | (uint32_t(ip[13]) << 16) |
                          (uint32_t(ip[14]) << 8)  | uint32_t(ip[15]);
        uint32_t dst_ip = (uint32_t(ip[16]) << 24) | (uint32_t(ip[17]) << 16) |
                          (uint32_t(ip[18]) << 8)  | uint32_t(ip[19]);

        const uint8_t* l4 = pkt.data + 14 + ip_hdr_len;
        uint16_t src_port = 0, dst_port = 0;
        if (proto == 6 || proto == 17) {
            if (pkt.len < 14 + ip_hdr_len + 4) return Action::Drop;
            src_port = (uint16_t(l4[0]) << 8) | l4[1];
            dst_port = (uint16_t(l4[2]) << 8) | l4[3];
        }

        for (const auto& r : rules_) {
            if (r.proto && *r.proto != proto) continue;
            if (r.src_ip && *r.src_ip != src_ip) continue;
            if (r.dst_ip && *r.dst_ip != dst_ip) continue;
            if (r.src_port && *r.src_port != src_port) continue;
            if (r.dst_port && *r.dst_port != dst_port) continue;
            return r.action;
        }

        return Action::Drop;
    }

private:
    std::vector<Rule> rules_;
};
```

