## 2) `src/umem.hpp`

```cpp
#pragma once
#include <cstdint>
#include <vector>
#include <memory>
#include <stdexcept>

class UMEM {
public:
    static constexpr uint32_t FRAME_SIZE = 2048;
    static constexpr uint32_t NUM_FRAMES  = 4096;

    UMEM() {
        buffer_.resize(size_t(FRAME_SIZE) * NUM_FRAMES);
        free_.reserve(NUM_FRAMES);
        for (uint32_t i = 0; i < NUM_FRAMES; ++i) free_.push_back(i);
    }

    uint8_t* frame_ptr(uint32_t idx) {
        return buffer_.data() + size_t(idx) * FRAME_SIZE;
    }

    uint32_t alloc_frame() {
        if (free_.empty()) throw std::runtime_error("UMEM exhausted");
        uint32_t idx = free_.back();
        free_.pop_back();
        return idx;
    }

    void free_frame(uint32_t idx) {
        free_.push_back(idx);
    }

private:
    std::vector<uint8_t> buffer_;
    std::vector<uint32_t> free_;
};
```

