## 4) `src/xdp_kern.c`

This is a minimal XDP program that can be extended to do early drops or redirect to an AF_XDP socket.

```c
#include <linux/bpf.h>
#include <bpf/bpf_helpers.h>
#include <linux/if_ether.h>
#include <linux/ip.h>

SEC("xdp")
int xdp_prog(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_DROP;

    if (eth->h_proto != __constant_htons(ETH_P_IP))
        return XDP_DROP;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_DROP;

    // Example early filter: drop private RFC1918 traffic
    __u32 saddr = __builtin_bswap32(ip->saddr);
    if ((saddr & 0xFF000000) == 0x0A000000) return XDP_DROP;       // 10.0.0.0/8
    if ((saddr & 0xFFF00000) == 0xAC100000) return XDP_DROP;       // 172.16.0.0/12
    if ((saddr & 0xFFFF0000) == 0xC0A80000) return XDP_DROP;       // 192.168.0.0/16

    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";
