use anyhow::{Context, Result};
use clap::Parser;
use log::{debug, info, warn};
use serde::{Deserialize, Serialize};
use std::fs;
use std::net::Ipv4Addr;
use std::path::PathBuf;
use std::sync::Arc;

#[derive(Parser, Debug)]
#[command(author, version, about)]
struct Args {
    /// Path to JSON config file
    #[arg(short, long)]
    config: PathBuf,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct Config {
    input_iface: String,
    output_iface: String,
    rules: Vec<Rule>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type")]
enum Rule {
    AllowTcpPort { port: u16 },
    AllowUdpPort { port: u16 },
    AllowSrcIp { ip: String },
    AllowDstIp { ip: String },
    DropAll,
}

#[derive(Debug, Clone)]
struct Packet<'a> {
    data: &'a [u8],
}

#[derive(Debug, Clone)]
struct ParsedPacket {
    ethertype: u16,
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    protocol: Option<u8>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Action {
    Allow,
    Drop,
}

trait PacketSource {
    fn recv(&mut self) -> Option<Vec<u8>>;
}

trait PacketSink {
    fn send(&mut self, packet: &[u8]) -> Result<()>;
}

/// Placeholder source for initial implementation.
/// Replace with AF_XDP/DPDK RX queue later.
struct MockSource {
    packets: Vec<Vec<u8>>,
    idx: usize,
}

impl MockSource {
    fn new() -> Self {
        Self {
            packets: vec![],
            idx: 0,
        }
    }
}

impl PacketSource for MockSource {
    fn recv(&mut self) -> Option<Vec<u8>> {
        if self.idx < self.packets.len() {
            let pkt = self.packets[self.idx].clone();
            self.idx += 1;
            Some(pkt)
        } else {
            None
        }
    }
}

/// Placeholder sink for initial implementation.
/// Replace with AF_XDP/DPDK TX queue later.
struct MockSink;

impl PacketSink for MockSink {
    fn send(&mut self, packet: &[u8]) -> Result<()> {
        debug!("Forwarded packet len={}", packet.len());
        Ok(())
    }
}

struct FilterEngine {
    rules: Arc<Vec<Rule>>,
}

impl FilterEngine {
    fn new(rules: Vec<Rule>) -> Self {
        Self {
            rules: Arc::new(rules),
        }
    }

    fn evaluate(&self, pkt: &ParsedPacket) -> Action {
        for rule in self.rules.iter() {
            match rule {
                Rule::AllowTcpPort { port } => {
                    if pkt.protocol == Some(6) && (pkt.src_port == Some(*port) || pkt.dst_port == Some(*port)) {
                        return Action::Allow;
                    }
                }
                Rule::AllowUdpPort { port } => {
                    if pkt.protocol == Some(17) && (pkt.src_port == Some(*port) || pkt.dst_port == Some(*port)) {
                        return Action::Allow;
                    }
                }
                Rule::AllowSrcIp { ip } => {
                    if let Ok(ipv4) = ip.parse::<Ipv4Addr>() {
                        if pkt.src_ip == Some(ipv4) {
                            return Action::Allow;
                        }
                    }
                }
                Rule::AllowDstIp { ip } => {
                    if let Ok(ipv4) = ip.parse::<Ipv4Addr>() {
                        if pkt.dst_ip == Some(ipv4) {
                            return Action::Allow;
                        }
                    }
                }
                Rule::DropAll => return Action::Drop,
            }
        }

        Action::Drop
    }
}

fn parse_packet(data: &[u8]) -> Option<ParsedPacket> {
    if data.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([data[12], data[13]]);
    let mut parsed = ParsedPacket {
        ethertype,
        src_ip: None,
        dst_ip: None,
        protocol: None,
        src_port: None,
        dst_port: None,
    };

    // IPv4 only for initial implementation
    if ethertype != 0x0800 || data.len() < 34 {
        return Some(parsed);
    }

    let ihl = (data[14] & 0x0f) as usize * 4;
    if data.len() < 14 + ihl {
        return Some(parsed);
    }

    let proto = data[23];
    let src_ip = Ipv4Addr::new(data[26], data[27], data[28], data[29]);
    let dst_ip = Ipv4Addr::new(data[30], data[31], data[32], data[33]);

    parsed.src_ip = Some(src_ip);
    parsed.dst_ip = Some(dst_ip);
    parsed.protocol = Some(proto);

    let l4_offset = 14 + ihl;
    if (proto == 6 || proto == 17) && data.len() >= l4_offset + 4 {
        parsed.src_port = Some(u16::from_be_bytes([data[l4_offset], data[l4_offset + 1]]));
        parsed.dst_port = Some(u16::from_be_bytes([data[l4_offset + 2], data[l4_offset + 3]]));
    }

    Some(parsed)
}

struct ForwardingService<S: PacketSource, T: PacketSink> {
    source: S,
    sink: T,
    filter: FilterEngine,
}

impl<S: PacketSource, T: PacketSink> ForwardingService<S, T> {
    fn run(&mut self) -> Result<()> {
        info!("Starting packet processing loop");

        while let Some(pkt) = self.source.recv() {
            let packet = Packet { data: &pkt };

            if let Some(parsed) = parse_packet(packet.data) {
                match self.filter.evaluate(&parsed) {
                    Action::Allow => {
                        self.sink.send(packet.data)?;
                    }
                    Action::Drop => {
                        debug!("Dropped packet");
                    }
                }
            } else {
                warn!("Malformed packet dropped");
            }
        }

        info!("Packet source exhausted; exiting");
        Ok(())
    }
}

fn load_config(path: &PathBuf) -> Result<Config> {
    let raw = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {}", path.display()))?;
    let cfg: Config = serde_json::from_str(&raw)
        .context("failed to parse config JSON")?;
    Ok(cfg)
}

fn main() -> Result<()> {
    env_logger::init();

    let args = Args::parse();
    let config = load_config(&args.config)?;

    info!(
        "Loaded config: input={} output={} rules={}",
        config.input_iface,
        config.output_iface,
        config.rules.len()
    );

    let filter = FilterEngine::new(config.rules);

    // Replace these with real AF_XDP/DPDK implementations later.
    let source = MockSource::new();
    let sink = MockSink;

    let mut service = ForwardingService {
        source,
        sink,
        filter,
    };

    service.run()
}
