use std::net::{Ipv4Addr, Ipv6Addr};

#[derive(Debug, Clone, Copy)]
pub enum Action {
    Drop,
    Pass,
    Forward(u16), // target queue/interface id
}

#[derive(Debug, Clone, Copy)]
pub struct PacketView<'a> {
    pub data: &'a [u8],
}

impl<'a> PacketView<'a> {
    pub fn new(data: &'a [u8]) -> Self {
        Self { data }
    }

    pub fn ethertype(&self) -> Option<u16> {
        if self.data.len() < 14 {
            return None;
        }
        Some(u16::from_be_bytes([self.data[12], self.data[13]]))
    }

    pub fn ipv4_src(&self) -> Option<Ipv4Addr> {
        if self.data.len() < 34 {
            return None;
        }
        if self.ethertype()? != 0x0800 {
            return None;
        }
        Some(Ipv4Addr::new(
            self.data[26],
            self.data[27],
            self.data[28],
            self.data[29],
        ))
    }

    pub fn ipv4_dst(&self) -> Option<Ipv4Addr> {
        if self.data.len() < 34 {
            return None;
        }
        if self.ethertype()? != 0x0800 {
            return None;
        }
        Some(Ipv4Addr::new(
            self.data[30],
            self.data[31],
            self.data[32],
            self.data[33],
        ))
    }

    pub fn ipv6_src(&self) -> Option<Ipv6Addr> {
        if self.data.len() < 54 {
            return None;
        }
        if self.ethertype()? != 0x86DD {
            return None;
        }
        let mut b = [0u8; 16];
        b.copy_from_slice(&self.data[22..38]);
        Some(Ipv6Addr::from(b))
    }

    pub fn ipv6_dst(&self) -> Option<Ipv6Addr> {
        if self.data.len() < 54 {
            return None;
        }
        if self.ethertype()? != 0x86DD {
            return None;
        }
        let mut b = [0u8; 16];
        b.copy_from_slice(&self.data[38..54]);
        Some(Ipv6Addr::from(b))
    }

    pub fn l4_proto(&self) -> Option<u8> {
        match self.ethertype()? {
            0x0800 => {
                if self.data.len() < 24 {
                    return None;
                }
                Some(self.data[23])
            }
            0x86DD => {
                if self.data.len() < 54 {
                    return None;
                }
                Some(self.data[20])
            }
            _ => None,
        }
    }

    pub fn tcp_dst_port(&self) -> Option<u16> {
        let proto = self.l4_proto()?;
        if proto != 6 {
            return None;
        }
        let offset = match self.ethertype()? {
            0x0800 => {
                let ihl = (self.data[14] & 0x0f) as usize * 4;
                14 + ihl
            }
            0x86DD => 54,
            _ => return None,
        };
        if self.data.len() < offset + 4 {
            return None;
        }
        Some(u16::from_be_bytes([self.data[offset + 2], self.data[offset + 3]]))
    }

    pub fn udp_dst_port(&self) -> Option<u16> {
        let proto = self.l4_proto()?;
        if proto != 17 {
            return None;
        }
        let offset = match self.ethertype()? {
            0x0800 => {
                let ihl = (self.data[14] & 0x0f) as usize * 4;
                14 + ihl
            }
            0x86DD => 54,
            _ => return None,
        };
        if self.data.len() < offset + 4 {
            return None;
        }
        Some(u16::from_be_bytes([self.data[offset + 2], self.data[offset + 3]]))
    }
}
