## `src/filter.rs`

```rust
use crate::packet::{Action, PacketView};
use std::net::Ipv4Addr;

#[derive(Debug, Clone)]
pub struct FilterConfig {
    pub drop_ipv4_src: Vec<Ipv4Addr>,
    pub drop_tcp_dst_ports: Vec<u16>,
    pub forward_udp_dst_port: Option<(u16, u16)>, // (port, target_id)
}

impl Default for FilterConfig {
    fn default() -> Self {
        Self {
            drop_ipv4_src: Vec::new(),
            drop_tcp_dst_ports: Vec::new(),
            forward_udp_dst_port: None,
        }
    }
}

#[inline(always)]
pub fn classify(pkt: &PacketView<'_>, cfg: &FilterConfig) -> Action {
    if let Some(src) = pkt.ipv4_src() {
        if cfg.drop_ipv4_src.iter().any(|x| *x == src) {
            return Action::Drop;
        }
    }

    if let Some(port) = pkt.tcp_dst_port() {
        if cfg.drop_tcp_dst_ports.iter().any(|p| *p == port) {
            return Action::Drop;
        }
    }

    if let Some((match_port, target)) = cfg.forward_udp_dst_port {
        if let Some(port) = pkt.udp_dst_port() {
            if port == match_port {
                return Action::Forward(target);
            }
        }
    }

    Action::Pass
}
