pub fn spawn_stats_thread(stats: Arc<TxStats>) -> thread::JoinHandle<()> {
    thread::spawn(move || loop {
        let f = stats.forwarded.load(Ordering::Relaxed);
        let d = stats.dropped.load(Ordering::Relaxed);
        let p = stats.passed.load(Ordering::Relaxed);

        eprintln!(
            "stats: forwarded={} dropped={} passed={}",
            f, d, p
        );

        thread::sleep(Duration::from_secs(1));
