```rust
#[derive(Debug, Clone, Copy)]
pub struct EthernetHeader {
    pub ethertype: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct Ipv4Header {
    pub protocol: u8,
    pub src: [u8; 4],
    pub dst: [u8; 4],
}

#[derive(Debug, Clone, Copy)]
pub struct TcpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct UdpHeader {
    pub src_port: u16,
    pub dst_port: u16,
}

pub fn parse_ethernet(frame: &[u8]) -> Option<EthernetHeader> {
    if frame.len() < 14 {
        return None;
    }
    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    Some(EthernetHeader { ethertype })
}

pub fn parse_ipv4(frame: &[u8]) -> Option<Ipv4Header> {
    if frame.len() < 34 {
        return None;
    }
    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return None;
    }

    let ihl = (frame[14] & 0x0f) as usize * 4;
    if frame.len() < 14 + ihl + 8 {
        return None;
    }

    let protocol = frame[23];
    let src = [frame[26], frame[27], frame[28], frame[29]];
    let dst = [frame[30], frame[31], frame[32], frame[33]];

    Some(Ipv4Header { protocol, src, dst })
}

pub fn parse_tcp(frame: &[u8]) -> Option<TcpHeader> {
    let ihl = (frame.get(14).copied()? & 0x0f) as usize * 4;
    let l4 = 14 + ihl;
    if frame.len() < l4 + 4 {
        return None;
    }
    let src_port = u16::from_be_bytes([frame[l4], frame[l4 + 1]]);
    let dst_port = u16::from_be_bytes([frame[l4 + 2], frame[l4 + 3]]);
    Some(TcpHeader { src_port, dst_port })
}

pub fn parse_udp(frame: &[u8]) -> Option<UdpHeader> {
    let ihl = (frame.get(14).copied()? & 0x0f) as usize * 4;
    let l4 = 14 + ihl;
    if frame.len() < l4 + 4 {
        return None;
    }
    let src_port = u16::from_be_bytes([frame[l4], frame[l4 + 1]]);
    let dst_port = u16::from_be_bytes([frame[l4 + 2], frame[l4 + 3]]);
    Some(UdpHeader { src_port, dst_port })
}
