    Tcp,
    Udp,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub action: Action,
    pub protocol: Protocol,
    pub src_ip: Option<[u8; 4]>,
    pub dst_ip: Option<[u8; 4]>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

impl Rule {
    pub fn matches(&self, frame: &[u8]) -> bool {
        let ip = match parse_ipv4(frame) {
            Some(ip) => ip,
            None => return false,
        };

        if let Some(src_ip) = self.src_ip {
            if ip.src != src_ip {
                return false;
            }
        }
        if let Some(dst_ip) = self.dst_ip {
            if ip.dst != dst_ip {
                return false;
            }
        }

        match self.protocol {
            Protocol::Any => {}
            Protocol::Tcp => {
                if ip.protocol != 6 {
                    return false;
                }
            }
            Protocol::Udp => {
                if ip.protocol != 17 {
                    return false;
                }
            }
        }

        if let Some(port) = self.src_port {
            let ok = match ip.protocol {
                6 => parse_tcp(frame).map(|h| h.src_port == port).unwrap_or(false),
                17 => parse_udp(frame).map(|h| h.src_port == port).unwrap_or(false),
                _ => false,
            };
            if !ok {
                return false;
            }
        }

        if let Some(port) = self.dst_port {
            let ok = match ip.protocol {
                6 => parse_tcp(frame).map(|h| h.dst_port == port).unwrap_or(false),
                17 => parse_udp(frame).map(|h| h.dst_port == port).unwrap_or(false),
                _ => false,
            };
            if !ok {
                return false;
            }
        }

        true
    }
}

#[derive(Debug, Clone)]
pub struct FilterEngine {
    pub rules: Vec<Rule>,
    pub default_action: Action,
}

impl FilterEngine {
    pub fn should_allow(&self, frame: &[u8]) -> bool {
        for rule in &self.rules {
            if rule.matches(frame) {
                return matches!(rule.action, Action::Allow);
            }
        }
        matches!(self.default_action, Action::Allow)
    }
}
