## 8) src/main.rs

This is a basic Linux raw socket receiver/forwarder. For a real ultra-low-latency deployment, you’d likely replace this with AF_XDP or DPDK, but this is a good initial implementation.

```rust
mod filter;
mod forward;
mod metrics;
mod packet;

use anyhow::{Context, Result};
use filter::{Action, FilterEngine, Protocol, Rule};
use forward::Forwarder;
use metrics::Metrics;
use nix::sys::socket::{
    bind, recv, socket, AddressFamily, MsgFlags, SockFlag, SockProtocol, SockType,
};
use nix::unistd::close;
use std::net::Ipv4Addr;
use std::os::fd::RawFd;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

fn open_raw_socket(_iface: &str) -> Result<RawFd> {
    // Initial implementation: AF_PACKET raw socket.
    // In practice, you would bind to interface index and set PACKET_RX_RING / TX_RING or AF_XDP.
    let fd = socket(
        AddressFamily::Packet,
        SockType::Raw,
        SockFlag::SOCK_NONBLOCK,
        Some(SockProtocol::EthAll),
    )?;
    Ok(fd)
}

fn main() -> Result<()> {
    let rx_iface = "eth0";
    let tx_iface = "eth1";

    let rx_fd = open_raw_socket(rx_iface).context("open rx socket")?;
    let tx_fd = open_raw_socket(tx_iface).context("open tx socket")?;

    let forwarder = Forwarder::new(tx_fd);
    let metrics = Arc::new(Metrics::new());

    let engine = FilterEngine {
        rules: vec![
            Rule {
                action: Action::Drop,
                protocol: Protocol::Tcp,
                src_ip: Some([10, 0, 0, 1]),
                dst_ip: None,
                src_port: None,
                dst_port: Some(22),
            },
            Rule {
                action: Action::Allow,
                protocol: Protocol::Any,
                src_ip: None,
                dst_ip: None,
                src_port: None,
                dst_port: None,
            },
        ],
        default_action: Action::Drop,
    };

    let metrics_clone = metrics.clone();
    thread::spawn(move || loop {
        let (rx, fwd, drop, err) = metrics_clone.snapshot();
        eprintln!(
            "metrics rx={} forwarded={} dropped={} errors={}",
            rx, fwd, drop, err
        );
        thread::sleep(Duration::from_secs(1));
    });

    let mut buf = vec![0u8; 2048];

    loop {
        match recv(rx_fd, &mut buf, MsgFlags::MSG_DONTWAIT) {
            Ok(0) => continue,
            Ok(n) => {
                metrics.rx_packets.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                let frame = &buf[..n];

                if engine.should_allow(frame) {
                    match forwarder.forward(frame) {
                        Ok(_) => {
                            metrics.forwarded_packets.fetch_add(
                                1,
                                std::sync::atomic::Ordering::Relaxed,
                            );
                        }
                        Err(_) => {
                            metrics.errors.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                        }
                    }
                } else {
                    metrics.dropped_packets.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
                }
            }
            Err(_) => {
                // Non-blocking socket: no packet available.
                // In a real low-latency loop, you might use busy-polling or kernel bypass.
                std::hint::spin_loop();
            }
        }
    }

    #[allow(unreachable_code)]
    {
        close(rx_fd).ok();
        close(tx_fd).ok();
        Ok(())
    }
}
