use anyhow::{Context, Result};
use libc::*;
use log::{info, warn};
use std::ffi::CString;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::fd::{AsRawFd, FromRawFd, OwnedFd};
use std::ptr;
use std::slice;

#[derive(Clone, Debug)]
struct Config {
    ingress_if: String,
    egress_if: String,
    // Example filter: drop packets from this source IP if present
    drop_src_ip: Option<Ipv4Addr>,
}

fn main() -> Result<()> {
    env_logger::init();

    let cfg = Config {
        ingress_if: std::env::var("INGRESS_IF").unwrap_or_else(|_| "eth0".to_string()),
        egress_if: std::env::var("EGRESS_IF").unwrap_or_else(|_| "eth1".to_string()),
        drop_src_ip: std::env::var("DROP_SRC_IP")
            .ok()
            .and_then(|s| s.parse().ok()),
    };

    info!("Starting forwarder: {:?}", cfg);

    let ingress = PacketSocket::bind(&cfg.ingress_if)
        .with_context(|| format!("binding ingress interface {}", cfg.ingress_if))?;
    let egress = PacketSocket::bind(&cfg.egress_if)
        .with_context(|| format!("binding egress interface {}", cfg.egress_if))?;

    run_forwarder(cfg, ingress, egress)
}

fn run_forwarder(cfg: Config, ingress: PacketSocket, egress: PacketSocket) -> Result<()> {
    let mut buf = vec![0u8; 2048];

    loop {
        let n = match ingress.recv(&mut buf) {
            Ok(n) => n,
            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e).context("recv failed"),
        };

        if n == 0 {
            continue;
        }

        let pkt = &buf[..n];

        if !packet_allowed(pkt, cfg.drop_src_ip) {
            continue;
        }

        if let Err(e) = egress.send(pkt) {
            warn!("send failed: {}", e);
        }
    }
}

fn packet_allowed(pkt: &[u8], drop_src_ip: Option<Ipv4Addr>) -> bool {
    // Minimal Ethernet + IPv4 parsing
    if pkt.len() < 14 {
        return false;
    }

    let ethertype = u16::from_be_bytes([pkt[12], pkt[13]]);
    if ethertype != 0x0800 {
        // Allow non-IPv4 by default
        return true;
    }

    if pkt.len() < 14 + 20 {
        return false;
    }

    let ihl = (pkt[14] & 0x0f) as usize * 4;
    if ihl < 20 || pkt.len() < 14 + ihl {
        return false;
    }

    let src = Ipv4Addr::new(pkt[26], pkt[27], pkt[28], pkt[29]);

    if let Some(drop_ip) = drop_src_ip {
        if src == drop_ip {
            return false;
        }
    }

    true
}

struct PacketSocket {
    fd: OwnedFd,
    if_index: i32,
}

impl PacketSocket {
    fn bind(if_name: &str) -> Result<Self> {
        let c_if = CString::new(if_name).context("invalid interface name")?;

        let if_index = unsafe { if_nametoindex(c_if.as_ptr()) } as i32;
        if if_index == 0 {
            return Err(anyhow::anyhow!(
                "interface {} not found: {}",
                if_name,
                io::Error::last_os_error()
            ));
        }

        let fd = unsafe {
            socket(
                AF_PACKET,
                SOCK_RAW,
                (ETH_P_ALL as u16).to_be() as i32,
            )
        };

        if fd < 0 {
            return Err(anyhow::anyhow!("socket failed: {}", io::Error::last_os_error()));
        }

        let fd = unsafe { OwnedFd::from_raw_fd(fd) };

        // Bind to interface
        let mut sll: sockaddr_ll = unsafe { mem::zeroed() };
        sll.sll_family = AF_PACKET as u16;
        sll.sll_protocol = (ETH_P_ALL as u16).to_be();
        sll.sll_ifindex = if_index;

        let ret = unsafe {
            bind(
                fd.as_raw_fd(),
                &sll as *const sockaddr_ll as *const sockaddr,
                mem::size_of::<sockaddr_ll>() as u32,
            )
        };

        if ret < 0 {
            return Err(anyhow::anyhow!("bind failed: {}", io::Error::last_os_error()));
        }

        Ok(Self { fd, if_index })
    }

    fn recv(&self, buf: &mut [u8]) -> io::Result<usize> {
        let ret = unsafe {
            recv(
                self.fd.as_raw_fd(),
                buf.as_mut_ptr() as *mut c_void,
                buf.len(),
                0,
            )
        };

        if ret < 0 {
            Err(io::Error::last_os_error())
        } else {
            Ok(ret as usize)
        }
    }

    fn send(&self, pkt: &[u8]) -> io::Result<usize> {
        let ret = unsafe {
            send(
                self.fd.as_raw_fd(),
                pkt.as_ptr() as *const c_void,
                pkt.len(),
                0,
            )
        };

        if ret < 0 {
            Err(io::Error::last_os_error())
        } else {
            Ok(ret as usize)
        }
    }
}
```

