use std::net::{Ipv4Addr, Ipv6Addr};

#[derive(Debug, Clone, Copy)]
pub enum PacketAction {
    Drop,
    Forward,
}

#[derive(Debug, Clone, Copy)]
pub struct EthernetHeader {
    pub ethertype: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct Ipv4Header {
    pub src: Ipv4Addr,
    pub dst: Ipv4Addr,
    pub protocol: u8,
}

#[derive(Debug, Clone, Copy)]
pub struct Ipv6Header {
    pub src: Ipv6Addr,
    pub dst: Ipv6Addr,
    pub next_header: u8,
}

pub fn parse_ethernet(frame: &[u8]) -> Option<EthernetHeader> {
    if frame.len() < 14 {
        return None;
    }
    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    Some(EthernetHeader { ethertype })
}

pub fn parse_ipv4(frame: &[u8]) -> Option<Ipv4Header> {
    if frame.len() < 34 {
        return None;
    }
    let ihl = (frame[14] & 0x0f) as usize * 4;
    if frame.len() < 14 + ihl || ihl < 20 {
        return None;
    }

    let protocol = frame[23];
    let src = Ipv4Addr::new(frame[26], frame[27], frame[28], frame[29]);
    let dst = Ipv4Addr::new(frame[30], frame[31], frame[32], frame[33]);

    Some(Ipv4Header { src, dst, protocol })
}

pub fn parse_ipv6(frame: &[u8]) -> Option<Ipv6Header> {
    if frame.len() < 14 + 40 {
        return None;
    }

    let next_header = frame[20];
    let src = Ipv6Addr::from([
        frame[22], frame[23], frame[24], frame[25],
        frame[26], frame[27], frame[28], frame[29],
        frame[30], frame[31], frame[32], frame[33],
        frame[34], frame[35], frame[36], frame[37],
    ]);
    let dst = Ipv6Addr::from([
        frame[38], frame[39], frame[40], frame[41],
        frame[42], frame[43], frame[44], frame[45],
        frame[46], frame[47], frame[48], frame[49],
        frame[50], frame[51], frame[52], frame[53],
    ]);

    Some(Ipv6Header { src, dst, next_header })
}
