## `src/filter.rs`

```rust
use std::net::{Ipv4Addr, Ipv6Addr};

use crate::packet::{parse_ethernet, parse_ipv4, parse_ipv6, PacketAction};

#[derive(Debug, Clone)]
pub enum FilterRule {
    AllowIpv4Src(Ipv4Addr),
    AllowIpv4Dst(Ipv4Addr),
    AllowIpv6Src(Ipv6Addr),
    AllowIpv6Dst(Ipv6Addr),
    AllowTcp,
    AllowUdp,
    DropAll,
}

#[derive(Debug)]
pub struct FilterEngine {
    rules: Vec<FilterRule>,
}

impl FilterEngine {
    pub fn new(rules: Vec<FilterRule>) -> Self {
        Self { rules }
    }

    pub fn evaluate(&self, frame: &[u8]) -> PacketAction {
        let eth = match parse_ethernet(frame) {
            Some(h) => h,
            None => return PacketAction::Drop,
        };

        match eth.ethertype {
            0x0800 => self.eval_ipv4(frame),
            0x86DD => self.eval_ipv6(frame),
            _ => PacketAction::Drop,
        }
    }

    fn eval_ipv4(&self, frame: &[u8]) -> PacketAction {
        let ip = match parse_ipv4(frame) {
            Some(h) => h,
            None => return PacketAction::Drop,
        };

        for rule in &self.rules {
            match rule {
                FilterRule::DropAll => return PacketAction::Drop,
                FilterRule::AllowIpv4Src(addr) if *addr == ip.src => return PacketAction::Forward,
                FilterRule::AllowIpv4Dst(addr) if *addr == ip.dst => return PacketAction::Forward,
                FilterRule::AllowTcp if ip.protocol == 6 => return PacketAction::Forward,
                FilterRule::AllowUdp if ip.protocol == 17 => return PacketAction::Forward,
                _ => {}
            }
        }

        PacketAction::Drop
    }

    fn eval_ipv6(&self, frame: &[u8]) -> PacketAction {
        let ip = match parse_ipv6(frame) {
            Some(h) => h,
            None => return PacketAction::Drop,
        };

        for rule in &self.rules {
            match rule {
                FilterRule::DropAll => return PacketAction::Drop,
                FilterRule::AllowIpv6Src(addr) if *addr == ip.src => return PacketAction::Forward,
                FilterRule::AllowIpv6Dst(addr) if *addr == ip.dst => return PacketAction::Forward,
                FilterRule::AllowTcp if ip.next_header == 6 => return PacketAction::Forward,
                FilterRule::AllowUdp if ip.next_header == 17 => return PacketAction::Forward,
                _ => {}
            }
        }

        PacketAction::Drop
    }
}
