    ]);

    let mut forwarder = Forwarder::default();

    let mut last_report = Instant::now();
    let mut packets_seen: u64 = 0;

    loop {
        let batch = xdp.receive_batch()?;

        if batch.is_empty() {
            std::thread::sleep(Duration::from_micros(10));
            continue;
        }

        let mut tx_batch = Vec::with_capacity(batch.len());

        for frame in batch {
            packets_seen += 1;
            let action = filter.evaluate(&frame);

            if let Some(out) = forwarder.process_packet(&frame, action) {
                tx_batch.push(out);
            }
        }

        if !tx_batch.is_empty() {
            xdp.transmit_batch(tx_batch)?;
        }

        if last_report.elapsed() >= Duration::from_secs(1) {
            info!(
                "pps={} forwarded={} dropped={}",
                packets_seen,
                forwarder.forwarded,
                forwarder.dropped
            );
            packets_seen = 0;
            forwarder.forwarded = 0;
            forwarder.dropped = 0;
            last_report = Instant::now();
        }
    }
}
```

