use anyhow::Result;
use clap::Parser;
use config::Config;
use policy::{Action, PolicyEngine};
use stats::Stats;
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;
use std::time::Duration;

#[derive(Parser, Debug)]
struct Args {
    #[arg(long, default_value = "eth0")]
    iface: String,

    #[arg(long, default_value_t = 0)]
    rx_queue: u32,

    #[arg(long, default_value_t = 0)]
    tx_queue: u32,
}

fn main() -> Result<()> {
    let args = Args::parse();
    let config = Config::from_args(&args);

    let running = Arc::new(AtomicBool::new(true));
    let stats = Arc::new(Stats::default());
    let policy = Arc::new(PolicyEngine::new());

    // Example rules
    policy.add_rule("allow_dns", |pkt| {
        if pkt.is_udp() && (pkt.dst_port() == Some(53) || pkt.src_port() == Some(53)) {
            Action::Forward(0)
        } else {
            Action::Pass
        }
    });

    policy.add_rule("drop_icmp", |pkt| {
        if pkt.is_icmp() {
            Action::Drop
        } else {
            Action::Pass
        }
    });

    let xdp = xdp::XdpInterface::open(&config)?;

    let rx_running = running.clone();
    let rx_stats = stats.clone();
    let rx_policy = policy.clone();
    let rx_xdp = xdp.clone();

    let worker = thread::spawn(move || {
        let mut buf = vec![0u8; 2048];

        while rx_running.load(Ordering::Relaxed) {
            match rx_xdp.recv(&mut buf) {
                Ok(Some(pkt_len)) => {
                    rx_stats.rx_packets.fetch_add(1, Ordering::Relaxed);
                    rx_stats.rx_bytes.fetch_add(pkt_len as u64, Ordering::Relaxed);

                    if let Some(pkt) = packet::PacketView::parse(&buf[..pkt_len]) {
                        match rx_policy.classify(&pkt) {
                            Action::Drop => {
                                rx_stats.dropped.fetch_add(1, Ordering::Relaxed);
                            }
                            Action::Pass => {
                                rx_stats.passed.fetch_add(1, Ordering::Relaxed);
                                // In a real deployment, pass may mean deliver to host stack.
                            }
                            Action::Forward(port) => {
                                rx_stats.forwarded.fetch_add(1, Ordering::Relaxed);
                                let _ = rx_xdp.send(port, &buf[..pkt_len]);
                            }
                        }
                    } else {
                        rx_stats.parse_errors.fetch_add(1, Ordering::Relaxed);
                    }
                }
                Ok(None) => {
                    // Busy poll: no packet available
                    std::hint::spin_loop();
                }
                Err(e) => {
                    eprintln!("RX error: {e:?}");
                    thread::sleep(Duration::from_millis(1));
                }
            }
        }
    });

    let stats_running = running.clone();
    let stats_clone = stats.clone();
    let stats_thread = thread::spawn(move || {
        while stats_running.load(Ordering::Relaxed) {
            thread::sleep(Duration::from_secs(1));
            eprintln!(
                "rx={} tx={} fwd={} drop={} pass={} parse_err={}",
                stats_clone.rx_packets.load(Ordering::Relaxed),
                stats_clone.tx_packets.load(Ordering::Relaxed),
                stats_clone.forwarded.load(Ordering::Relaxed),
                stats_clone.dropped.load(Ordering::Relaxed),
                stats_clone.passed.load(Ordering::Relaxed),
                stats_clone.parse_errors.load(Ordering::Relaxed),
            );
        }
    });

    // Run until interrupted in a real implementation.
    // For now, just wait.
    worker.join().unwrap();
    stats_thread.join().unwrap();

    Ok(())
}
