## `src/packet.rs`

```rust
#[derive(Debug, Clone, Copy)]
pub struct PacketView<'a> {
    data: &'a [u8],
}

impl<'a> PacketView<'a> {
    pub fn parse(data: &'a [u8]) -> Option<Self> {
        if data.len() < 14 {
            return None;
        }
        Some(Self { data })
    }

    pub fn ethertype(&self) -> Option<u16> {
        if self.data.len() < 14 {
            return None;
        }
        Some(u16::from_be_bytes([self.data[12], self.data[13]]))
    }

    pub fn is_ipv4(&self) -> bool {
        self.ethertype() == Some(0x0800)
    }

    pub fn is_ipv6(&self) -> bool {
        self.ethertype() == Some(0x86DD)
    }

    pub fn is_icmp(&self) -> bool {
        if !self.is_ipv4() || self.data.len() < 34 {
            return false;
        }
        self.data[23] == 1
    }

    pub fn is_udp(&self) -> bool {
        if !self.is_ipv4() || self.data.len() < 34 {
            return false;
        }
        self.data[23] == 17
    }

    pub fn src_port(&self) -> Option<u16> {
        self.l4_ports().map(|(src, _)| src)
    }

    pub fn dst_port(&self) -> Option<u16> {
        self.l4_ports().map(|(_, dst)| dst)
    }

    fn l4_ports(&self) -> Option<(u16, u16)> {
        if !self.is_ipv4() || self.data.len() < 38 {
            return None;
        }
        let ihl = (self.data[14] & 0x0f) as usize * 4;
        let l4 = 14 + ihl;
        if self.data.len() < l4 + 4 {
            return None;
        }
        let src = u16::from_be_bytes([self.data[l4], self.data[l4 + 1]]);
        let dst = u16::from_be_bytes([self.data[l4 + 2], self.data[l4 + 3]]);
        Some((src, dst))
    }
}
