## `src/policy.rs`

```rust
use crate::packet::PacketView;
use parking_lot::RwLock;
use std::sync::Arc;

#[derive(Debug, Clone, Copy)]
pub enum Action {
    Drop,
    Pass,
    Forward(u16),
}

type RuleFn = dyn for<'a> Fn(&PacketView<'a>) -> Action + Send + Sync + 'static;

pub struct PolicyEngine {
    rules: RwLock<Vec<(String, Arc<RuleFn>)>>,
}

impl PolicyEngine {
    pub fn new() -> Self {
        Self {
            rules: RwLock::new(Vec::new()),
        }
    }

    pub fn add_rule<F>(&self, name: impl Into<String>, rule: F)
    where
        F: for<'a> Fn(&PacketView<'a>) -> Action + Send + Sync + 'static,
    {
        self.rules.write().push((name.into(), Arc::new(rule)));
    }

    pub fn classify<'a>(&self, pkt: &PacketView<'a>) -> Action {
        for (_, rule) in self.rules.read().iter() {
            match rule(pkt) {
                Action::Pass => continue,
                action => return action,
            }
        }
        Action::Pass
    }
}
