## `src/packet.rs`

This is a lightweight packet parser for IPv4 + TCP/UDP. It assumes Ethernet frames are already stripped or that you are feeding it L3 packets. If you want raw NIC capture, you’d typically add AF_PACKET/DPDK/AF_XDP later.

```rust
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum L4Protocol {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct PacketView<'a> {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub protocol: L4Protocol,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub payload: &'a [u8],
}

pub fn parse_ipv4_packet(buf: &[u8]) -> Option<PacketView<'_>> {
    if buf.len() < 20 {
        return None;
    }

    let version_ihl = buf[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 || ihl < 20 || buf.len() < ihl {
        return None;
    }

    let total_len = u16::from_be_bytes([buf[2], buf[3]]) as usize;
    if total_len < ihl || buf.len() < total_len {
        return None;
    }

    let protocol = match buf[9] {
        6 => L4Protocol::Tcp,
        17 => L4Protocol::Udp,
        x => L4Protocol::Other(x),
    };

    let src_ip = Ipv4Addr::new(buf[12], buf[13], buf[14], buf[15]);
    let dst_ip = Ipv4Addr::new(buf[16], buf[17], buf[18], buf[19]);

    let l4 = &buf[ihl..total_len];

    let (src_port, dst_port, payload) = match protocol {
        L4Protocol::Tcp => {
            if l4.len() < 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            let data_offset = ((l4[12] >> 4) as usize) * 4;
            if l4.len() < data_offset {
                return None;
            }
            (Some(src_port), Some(dst_port), &l4[data_offset..])
        }
        L4Protocol::Udp => {
            if l4.len() < 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            (Some(src_port), Some(dst_port), &l4[8..])
        }
        L4Protocol::Other(_) => (None, None, l4),
    };

    Some(PacketView {
        src_ip,
        dst_ip,
        protocol,
        src_port,
        dst_port,
        payload,
    })
}
```

