## `src/rules.rs`

A simple rule engine for filtering and forwarding decisions.

```rust
use crate::packet::{L4Protocol, PacketView};
use std::net::Ipv4Addr;

#[derive(Debug, Clone)]
pub enum Action {
    Drop,
    Pass,
    Forward,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub protocol: Option<L4Protocol>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub action: Action,
}

impl Rule {
    pub fn matches(&self, pkt: &PacketView<'_>) -> bool {
        if let Some(ip) = self.src_ip {
            if pkt.src_ip != ip {
                return false;
            }
        }
        if let Some(ip) = self.dst_ip {
            if pkt.dst_ip != ip {
                return false;
            }
        }
        if let Some(proto) = self.protocol {
            if pkt.protocol != proto {
                return false;
            }
        }
        if let Some(port) = self.src_port {
            if pkt.src_port != Some(port) {
                return false;
            }
        }
        if let Some(port) = self.dst_port {
            if pkt.dst_port != Some(port) {
                return false;
            }
        }
        true
    }
}

#[derive(Default)]
pub struct RuleSet {
    pub rules: Vec<Rule>,
}

impl RuleSet {
    pub fn decide(&self, pkt: &PacketView<'_>) -> Action {
        for rule in &self.rules {
            if rule.matches(pkt) {
                return rule.action.clone();
            }
        }
        Action::Forward
    }
}
```

