## `src/engine.rs`

This is the main packet-processing loop. It receives packets, parses them, applies rules, and forwards or drops them.

For the initial implementation, forwarding is simulated using a UDP socket. In a real ultra-low-latency environment, you’d replace this with raw sockets, AF_XDP, DPDK, or kernel-bypass networking.

```rust
use crate::config::ServiceConfig;
use crate::packet::parse_ipv4_packet;
use crate::rules::{Action, RuleSet};
use anyhow::Result;
use mio::net::{UdpSocket};
use mio::{Events, Interest, Poll, Token};
use std::net::SocketAddr;
use std::time::Duration;

const LISTENER: Token = Token(0);

pub struct Engine {
    config: ServiceConfig,
    rules: RuleSet,
    poll: Poll,
    listener: UdpSocket,
    forward_socket: UdpSocket,
}

impl Engine {
    pub fn new(config: ServiceConfig, rules: RuleSet) -> Result<Self> {
        let poll = Poll::new()?;

        let listener = UdpSocket::bind(config.listen_addr)?;
        let forward_socket = UdpSocket::bind("0.0.0.0:0".parse::<SocketAddr>()?)?;

        Ok(Self {
            config,
            rules,
            poll,
            listener,
            forward_socket,
        })
    }

    pub fn run(mut self) -> Result<()> {
        self.poll
            .registry()
            .register(&mut self.listener, LISTENER, Interest::READABLE)?;

        let mut events = Events::with_capacity(1024);
        let mut buf = [0u8; 2048];

        loop {
            self.poll
                .poll(&mut events, Some(Duration::from_millis(1)))?;

            for event in events.iter() {
                if event.token() == LISTENER && event.is_readable() {
                    loop {
                        match self.listener.recv_from(&mut buf) {
                            Ok((n, _peer)) => {
                                if let Some(pkt) = parse_ipv4_packet(&buf[..n]) {
                                    match self.rules.decide(&pkt) {
                                        Action::Drop => {
                                            // intentionally drop
                                        }
                                        Action::Pass | Action::Forward => {
                                            let _ = self.forward_socket.send_to(
                                                &buf[..n],
                                                self.config.forward_target.addr,
                                            );
                                        }
                                    }
                                }
                            }
                            Err(ref e) if e.kind() == std::io::ErrorKind::WouldBlock => break,
                            Err(e) => return Err(e.into()),
                        }
                    }
                }
            }
        }
    }
}
```

