```rust
use anyhow::{Context, Result};
use clap::Parser;
use crossbeam_channel::{bounded, Receiver, Sender};
use log::{debug, error, info, warn};
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

#[derive(Parser, Debug, Clone)]
#[command(name = "ultra_net")]
struct Args {
    /// Interface to receive packets on
    #[arg(long)]
    input_iface: String,

    /// Interface to forward packets out of
    #[arg(long)]
    output_iface: String,

    /// Optional source IP filter
    #[arg(long)]
    allow_src: Option<Ipv4Addr>,

    /// Optional destination IP filter
    #[arg(long)]
    allow_dst: Option<Ipv4Addr>,

    /// Optional TCP/UDP port filter
    #[arg(long)]
    allow_port: Option<u16>,

    /// Drop all packets unless they match filters
    #[arg(long, default_value_t = true)]
    strict: bool,

    /// Queue size between RX and TX workers
    #[arg(long, default_value_t = 4096)]
    queue_size: usize,
}

#[derive(Debug, Clone)]
struct FilterRules {
    allow_src: Option<Ipv4Addr>,
    allow_dst: Option<Ipv4Addr>,
    allow_port: Option<u16>,
    strict: bool,
}

impl FilterRules {
    fn matches(&self, pkt: &ParsedPacket) -> bool {
        if let Some(src) = self.allow_src {
            if pkt.src_ip != Some(src) {
                return false;
            }
        }

        if let Some(dst) = self.allow_dst {
            if pkt.dst_ip != Some(dst) {
                return false;
            }
        }

        if let Some(port) = self.allow_port {
            if pkt.src_port != Some(port) && pkt.dst_port != Some(port) {
                return false;
            }
        }

        true
    }
}

#[derive(Debug, Clone)]
struct ParsedPacket {
    raw: Vec<u8>,
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    protocol: Option<u8>,
}

#[derive(Debug)]
enum Action {
    Drop,
    Forward(Vec<u8>),
}

fn main() -> Result<()> {
    env_logger::init();
    let args = Args::parse();

    let rules = Arc::new(FilterRules {
        allow_src: args.allow_src,
        allow_dst: args.allow_dst,
        allow_port: args.allow_port,
        strict: args.strict,
    });

    let input_iface = find_interface(&args.input_iface)
        .with_context(|| format!("input interface '{}' not found", args.input_iface))?;
    let output_iface = find_interface(&args.output_iface)
        .with_context(|| format!("output interface '{}' not found", args.output_iface))?;

    info!("input iface: {}", input_iface.name);
    info!("output iface: {}", output_iface.name);
    info!("rules: {:?}", rules);

    let (tx_queue_s, tx_queue_r) = bounded::<Vec<u8>>(args.queue_size);

    let rx_handle = {
        let rules = rules.clone();
        let tx_queue_s = tx_queue_s.clone();
        thread::spawn(move || {
            if let Err(e) = rx_worker(input_iface, rules, tx_queue_s) {
                error!("rx worker error: {:#}", e);
            }
        })
    };

    let tx_handle = thread::spawn(move || {
        if let Err(e) = tx_worker(output_iface, tx_queue_r) {
            error!("tx worker error: {:#}", e);
        }
    });

    rx_handle.join().expect("rx thread panicked");
    tx_handle.join().expect("tx thread panicked");

    Ok(())
}

fn find_interface(name: &str) -> Option<NetworkInterface> {
    datalink::interfaces().into_iter().find(|iface| iface.name == name)
}

fn rx_worker(
    iface: NetworkInterface,
    rules: Arc<FilterRules>,
    tx_queue: Sender<Vec<u8>>,
) -> Result<()> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(1));
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;

    let (_, mut rx) = match datalink::channel(&iface, config)? {
        Channel::Ethernet(tx, rx) => (tx, rx),
        _ => anyhow::bail!("unsupported channel type"),
    };

    loop {
        match rx.next() {
            Ok(packet) => {
                if let Some(parsed) = parse_packet(packet) {
                    let action = decide_action(&rules, &parsed);
                    match action {
                        Action::Drop => {
                            debug!("dropped packet: {:?}", parsed);
                        }
                        Action::Forward(bytes) => {
                            if let Err(_) = tx_queue.try_send(bytes) {
                                warn!("tx queue full, dropping packet");
                            }
                        }
                    }
                }
            }
            Err(_) => {
                // timeout or transient read error
                continue;
            }
        }
    }
}

fn tx_worker(iface: NetworkInterface, rx_queue: Receiver<Vec<u8>>) -> Result<()> {
    let mut config = Config::default();
    config.write_buffer_size = 1 << 20;
    config.read_timeout = Some(Duration::from_millis(1));

    let (mut tx, _) = match datalink::channel(&iface, config)? {
        Channel::Ethernet(tx, rx) => (tx, rx),
        _ => anyhow::bail!("unsupported channel type"),
    };

    loop {
        match rx_queue.recv() {
            Ok(frame) => {
                if let Err(e) = send_frame(&mut tx, &frame) {
                    warn!("failed to send frame: {:#}", e);
                }
            }
            Err(_) => break,
        }
    }

    Ok(())
}

fn parse_packet(raw: &[u8]) -> Option<ParsedPacket> {
    let eth = EthernetPacket::new(raw)?;
    let mut pkt = ParsedPacket {
        raw: raw.to_vec(),
        src_ip: None,
        dst_ip: None,
        src_port: None,
        dst_port: None,
        protocol: None,
    };

    match eth.get_ethertype() {
        EtherTypes::Ipv4 => {
            let ip = Ipv4Packet::new(eth.payload())?;
            pkt.src_ip = Some(ip.get_source());
            pkt.dst_ip = Some(ip.get_destination());
            pkt.protocol = Some(ip.get_next_level_protocol().0);

            match ip.get_next_level_protocol() {
                IpNextHeaderProtocols::Tcp => {
                    if let Some(tcp) = TcpPacket::new(ip.payload()) {
                        pkt.src_port = Some(tcp.get_source());
                        pkt.dst_port = Some(tcp.get_destination());
                    }
                }
                IpNextHeaderProtocols::Udp => {
                    if let Some(udp) = UdpPacket::new(ip.payload()) {
                        pkt.src_port = Some(udp.get_source());
                        pkt.dst_port = Some(udp.get_destination());
                    }
                }
                _ => {}
            }
        }
        _ => {}
    }

    Some(pkt)
}

fn decide_action(rules: &FilterRules, pkt: &ParsedPacket) -> Action {
    if rules.strict && !rules.matches(pkt) {
        return Action::Drop;
    }

    if !rules.strict && rules.allow_src.is_some() || rules.allow_dst.is_some() || rules.allow_port.is_some() {
        if !rules.matches(pkt) {
            return Action::Drop;
        }
    }

    Action::Forward(pkt.raw.clone())
}

fn send_frame(tx: &mut Box<dyn DataLinkSender>, frame: &[u8]) -> Result<()> {
    match tx.send_to(frame, None) {
        Some(Ok(())) => Ok(()),
        Some(Err(e)) => Err(e.into()),
        None => anyhow::bail!("send_to returned None"),
    }
}
```

