## `src/packet.rs`

```rust
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};

#[derive(Debug, Clone, Copy)]
pub enum L4Proto {
    Tcp,
    Udp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct PacketMeta {
    pub ethertype: u16,
    pub src_ip: Option<IpAddr>,
    pub dst_ip: Option<IpAddr>,
    pub l4_proto: Option<L4Proto>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
}

impl PacketMeta {
    pub fn empty(ethertype: u16) -> Self {
        Self {
            ethertype,
            src_ip: None,
            dst_ip: None,
            l4_proto: None,
            src_port: None,
            dst_port: None,
        }
    }
}

pub fn parse_packet(buf: &[u8]) -> Option<PacketMeta> {
    if buf.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([buf[12], buf[13]]);
    let mut meta = PacketMeta::empty(ethertype);

    match ethertype {
        0x0800 => parse_ipv4(&buf[14..], &mut meta),
        0x86DD => parse_ipv6(&buf[14..], &mut meta),
        _ => Some(meta),
    }
}

fn parse_ipv4(buf: &[u8], meta: &mut PacketMeta) -> Option<PacketMeta> {
    if buf.len() < 20 {
        return None;
    }

    let ihl = (buf[0] & 0x0f) as usize * 4;
    if buf.len() < ihl || ihl < 20 {
        return None;
    }

    let proto = buf[9];
    let src = Ipv4Addr::new(buf[12], buf[13], buf[14], buf[15]);
    let dst = Ipv4Addr::new(buf[16], buf[17], buf[18], buf[19]);

    meta.src_ip = Some(IpAddr::V4(src));
    meta.dst_ip = Some(IpAddr::V4(dst));

    let l4 = &buf[ihl..];
    match proto {
        6 => {
            meta.l4_proto = Some(L4Proto::Tcp);
            parse_tcp_udp(l4, meta)
        }
        17 => {
            meta.l4_proto = Some(L4Proto::Udp);
            parse_tcp_udp(l4, meta)
        }
        other => {
            meta.l4_proto = Some(L4Proto::Other(other));
            Some(*meta)
        }
    }
}

fn parse_ipv6(buf: &[u8], meta: &mut PacketMeta) -> Option<PacketMeta> {
    if buf.len() < 40 {
        return None;
    }

    let next_header = buf[6];
    let src = Ipv6Addr::from(<[u8; 16]>::try_from(&buf[8..24]).ok()?);
    let dst = Ipv6Addr::from(<[u8; 16]>::try_from(&buf[24..40]).ok()?);

    meta.src_ip = Some(IpAddr::V6(src));
    meta.dst_ip = Some(IpAddr::V6(dst));

    let l4 = &buf[40..];
    match next_header {
        6 => {
            meta.l4_proto = Some(L4Proto::Tcp);
            parse_tcp_udp(l4, meta)
        }
        17 => {
            meta.l4_proto = Some(L4Proto::Udp);
            parse_tcp_udp(l4, meta)
        }
        other => {
            meta.l4_proto = Some(L4Proto::Other(other));
            Some(*meta)
        }
    }
}

fn parse_tcp_udp(buf: &[u8], meta: &mut PacketMeta) -> Option<PacketMeta> {
    if buf.len() < 4 {
        return None;
    }

    meta.src_port = Some(u16::from_be_bytes([buf[0], buf[1]]));
    meta.dst_port = Some(u16::from_be_bytes([buf[2], buf[3]]));
    Some(*meta)
}
