## `src/filter.rs`

```rust
use crate::config::Config;
use crate::packet::{L4Proto, PacketMeta};

#[derive(Debug, Default)]
pub struct Counters {
    pub received: u64,
    pub forwarded: u64,
    pub dropped: u64,
    pub parse_failed: u64,
}

pub fn should_forward(meta: &PacketMeta, cfg: &Config) -> bool {
    if let Some(deny_src) = cfg.deny_src {
        if meta.src_ip == Some(deny_src) {
            return false;
        }
    }

    if let Some(deny_dst) = cfg.deny_dst {
        if meta.dst_ip == Some(deny_dst) {
            return false;
        }
    }

    if let Some(allow_src) = cfg.allow_src {
        if meta.src_ip != Some(allow_src) {
            return false;
        }
    }

    if let Some(allow_dst) = cfg.allow_dst {
        if meta.dst_ip != Some(allow_dst) {
            return false;
        }
    }

    if let Some(port) = cfg.allow_port {
        let src_ok = meta.src_port == Some(port);
        let dst_ok = meta.dst_port == Some(port);
        if !(src_ok || dst_ok) {
            return false;
        }
    }

    match meta.l4_proto {
        Some(L4Proto::Tcp) | Some(L4Proto::Udp) | Some(L4Proto::Other(_)) => true,
        None => true,
    }
}
