## `src/forward.rs`

```rust
use anyhow::{Context, Result};
use nix::net::if_::if_nametoindex;
use socket2::{Domain, Protocol, Socket, Type};
use std::os::fd::AsRawFd;

pub struct Forwarder {
    sock: Socket,
}

impl Forwarder {
    pub fn new(output_if: &str) -> Result<Self> {
        let ifindex = if_nametoindex(output_if)
            .with_context(|| format!("failed to resolve interface {}", output_if))?;

        let sock = Socket::new(Domain::PACKET, Type::RAW, Some(Protocol::from(libc::ETH_P_ALL as i32)))
            .context("failed to create raw packet socket")?;

        let sll = libc::sockaddr_ll {
            sll_family: libc::AF_PACKET as u16,
            sll_protocol: (libc::ETH_P_ALL as u16).to_be(),
            sll_ifindex: ifindex as i32,
            sll_hatype: 0,
            sll_pkttype: 0,
            sll_halen: 0,
            sll_addr: [0; 8],
        };

        let ret = unsafe {
            libc::bind(
                sock.as_raw_fd(),
                &sll as *const _ as *const libc::sockaddr,
                std::mem::size_of::<libc::sockaddr_ll>() as libc::socklen_t,
            )
        };

        if ret != 0 {
            return Err(std::io::Error::last_os_error()).context("failed to bind forward socket");
        }

        Ok(Self { sock })
    }

    pub fn send(&self, frame: &[u8]) -> Result<usize> {
        let n = unsafe {
            libc::send(
                self.sock.as_raw_fd(),
                frame.as_ptr() as *const libc::c_void,
                frame.len(),
                0,
            )
        };

        if n < 0 {
            return Err(std::io::Error::last_os_error()).context("send failed");
        }

        Ok(n as usize)
    }
}
