## `src/main.rs`

```rust
mod config;
mod filter;
mod forward;
mod packet;

use anyhow::{Context, Result};
use clap::Parser;
use config::Config;
use filter::{should_forward, Counters};
use forward::Forwarder;
use packet::parse_packet;
use socket2::{Domain, Protocol, Socket, Type};
use std::os::fd::AsRawFd;

fn main() -> Result<()> {
    let cfg = Config::parse();
    run(cfg)
}

fn run(cfg: Config) -> Result<()> {
    let rx = create_rx_socket(&cfg.input_if, cfg.promiscuous)?;
    let forwarder = Forwarder::new(&cfg.output_if)?;

    let mut counters = Counters::default();
    let mut buf = vec![0u8; 65536];

    loop {
        let n = unsafe {
            libc::recv(
                rx.as_raw_fd(),
                buf.as_mut_ptr() as *mut libc::c_void,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            let err = std::io::Error::last_os_error();
            eprintln!("recv error: {err}");
            continue;
        }

        let n = n as usize;
        counters.received += 1;

        let frame = &buf[..n];
        let meta = match parse_packet(frame) {
            Some(m) => m,
            None => {
                counters.parse_failed += 1;
                continue;
            }
        };

        if should_forward(&meta, &cfg) {
            if let Err(e) = forwarder.send(frame) {
                eprintln!("forward error: {e:?}");
                counters.dropped += 1;
            } else {
                counters.forwarded += 1;
            }
        } else {
            counters.dropped += 1;
        }

        if counters.received % 100_000 == 0 {
            eprintln!(
                "rx={} fwd={} drop={} parse_fail={}",
                counters.received, counters.forwarded, counters.dropped, counters.parse_failed
            );
        }
    }
}

fn create_rx_socket(ifname: &str, promiscuous: bool) -> Result<Socket> {
    let ifindex = nix::net::if_::if_nametoindex(ifname)
        .with_context(|| format!("failed to resolve interface {}", ifname))?;

    let sock = Socket::new(Domain::PACKET, Type::RAW, Some(Protocol::from(libc::ETH_P_ALL as i32)))
        .context("failed to create raw packet socket")?;

    let sll = libc::sockaddr_ll {
        sll_family: libc::AF_PACKET as u16,
        sll_protocol: (libc::ETH_P_ALL as u16).to_be(),
        sll_ifindex: ifindex as i32,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            sock.as_raw_fd(),
            &sll as *const _ as *const libc::sockaddr,
            std::mem::size_of::<libc::sockaddr_ll>() as libc::socklen_t,
        )
    };

    if ret != 0 {
        return Err(std::io::Error::last_os_error()).context("failed to bind rx socket");
    }

    if promiscuous {
        let mreq = libc::packet_mreq {
            mr_ifindex: ifindex as i32,
            mr_type: libc::PACKET_MR_PROMISC as u16,
            mr_alen: 0,
            mr_address: [0; 8],
        };

        let ret = unsafe {
            libc::setsockopt(
                sock.as_raw_fd(),
                libc::SOL_PACKET,
                libc::PACKET_ADD_MEMBERSHIP,
                &mreq as *const _ as *const libc::c_void,
                std::mem::size_of::<libc::packet_mreq>() as libc::socklen_t,
            )
        };

        if ret != 0 {
            return Err(std::io::Error::last_os_error()).context("failed to enable promiscuous mode");
        }
    }

    Ok(sock)
}
