use anyhow::{Context, Result};
use pnet::datalink::{self, Channel, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::Ipv4Addr;
use std::time::Duration;

#[derive(Clone, Debug)]
enum Action {
    Drop,
    Forward { out_iface: String },
    Accept,
}

#[derive(Clone, Debug)]
enum Protocol {
    Any,
    Ipv4,
    Tcp,
    Udp,
}

#[derive(Clone, Debug)]
struct Rule {
    protocol: Protocol,
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
    action: Action,
}

impl Rule {
    fn matches(&self, frame: &[u8]) -> bool {
        let eth = match EthernetPacket::new(frame) {
            Some(pkt) => pkt,
            None => return false,
        };

        match eth.get_ethertype() {
            EtherTypes::Ipv4 => {
                let ipv4 = match Ipv4Packet::new(eth.payload()) {
                    Some(pkt) => pkt,
                    None => return false,
                };

                if !matches!(self.protocol, Protocol::Any | Protocol::Ipv4) {
                    if !matches!(self.protocol, Protocol::Tcp) && !matches!(self.protocol, Protocol::Udp) {
                        return false;
                    }
                }

                if let Some(src) = self.src_ip {
                    if ipv4.get_source() != src {
                        return false;
                    }
                }

                if let Some(dst) = self.dst_ip {
                    if ipv4.get_destination() != dst {
                        return false;
                    }
                }

                match ipv4.get_next_level_protocol() {
                    IpNextHeaderProtocols::Tcp => {
                        if !matches!(self.protocol, Protocol::Any | Protocol::Ipv4 | Protocol::Tcp) {
                            return false;
                        }
                        let tcp = match TcpPacket::new(ipv4.payload()) {
                            Some(pkt) => pkt,
                            None => return false,
                        };

                        if let Some(src_port) = self.src_port {
                            if tcp.get_source() != src_port {
                                return false;
                            }
                        }
                        if let Some(dst_port) = self.dst_port {
                            if tcp.get_destination() != dst_port {
                                return false;
                            }
                        }
                        true
                    }
                    IpNextHeaderProtocols::Udp => {
                        if !matches!(self.protocol, Protocol::Any | Protocol::Ipv4 | Protocol::Udp) {
                            return false;
                        }
                        let udp = match UdpPacket::new(ipv4.payload()) {
                            Some(pkt) => pkt,
                            None => return false,
                        };

                        if let Some(src_port) = self.src_port {
                            if udp.get_source() != src_port {
                                return false;
                            }
                        }
                        if let Some(dst_port) = self.dst_port {
                            if udp.get_destination() != dst_port {
                                return false;
                            }
                        }
                        true
                    }
                    _ => matches!(self.protocol, Protocol::Any | Protocol::Ipv4),
                }
            }
            _ => false,
        }
    }
}

struct Forwarder {
    rules: Vec<Rule>,
    default_action: Action,
}

impl Forwarder {
    fn new(rules: Vec<Rule>, default_action: Action) -> Self {
        Self {
            rules,
            default_action,
        }
    }

    fn decide(&self, frame: &[u8]) -> Action {
        for rule in &self.rules {
            if rule.matches(frame) {
                return rule.action.clone();
            }
        }
        self.default_action.clone()
    }
}

fn find_interface(name: &str) -> Result<NetworkInterface> {
    datalink::interfaces()
        .into_iter()
        .find(|iface| iface.name == name)
        .with_context(|| format!("interface '{}' not found", name))
}

fn open_channel(iface: &NetworkInterface) -> Result<(Box<dyn DataLinkSender>, Box<dyn DataLinkReceiver>)> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_micros(0));
    config.write_buffer_size = 4096;
    config.read_buffer_size = 4096;
    config.promiscuous = true;

    match datalink::channel(iface, config)? {
        Channel::Ethernet(tx, rx) => Ok((tx, rx)),
        _ => anyhow::bail!("unsupported channel type"),
    }
}

fn forward_loop(
    in_iface: NetworkInterface,
    out_iface: NetworkInterface,
    forwarder: Forwarder,
) -> Result<()> {
    let (_in_tx, mut in_rx) = open_channel(&in_iface)?;
    let (mut out_tx, _out_rx) = open_channel(&out_iface)?;

    let mut buffer = vec![0u8; 65536];

    loop {
        match in_rx.next() {
            Ok(packet) => {
                let len = packet.len();
                buffer[..len].copy_from_slice(packet);

                match forwarder.decide(&buffer[..len]) {
                    Action::Drop => {
                        // intentionally do nothing
                    }
                    Action::Accept => {
                        // For now, accept means forward unchanged
                        if let Some(result) = out_tx.send_to(&buffer[..len], None) {
                            if let Err(e) = result {
                                eprintln!("send error: {e}");
                            }
                        }
                    }
                    Action::Forward { .. } => {
                        if let Some(result) = out_tx.send_to(&buffer[..len], None) {
                            if let Err(e) = result {
                                eprintln!("send error: {e}");
                            }
                        }
                    }
                }
            }
            Err(_) => {
                // Non-blocking / timeout path; continue polling
                continue;
            }
        }
    }
}

fn main() -> Result<()> {
    // Example rules:
    // - Drop all UDP traffic to port 53
    // - Forward TCP traffic to port 443
    let rules = vec![
        Rule {
            protocol: Protocol::Udp,
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: Some(53),
            action: Action::Drop,
        },
        Rule {
            protocol: Protocol::Tcp,
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: Some(443),
            action: Action::Forward {
                out_iface: "eth1".to_string(),
            },
        },
    ];

    let forwarder = Forwarder::new(rules, Action::Accept);

    let in_iface = find_interface("eth0")?;
    let out_iface = find_interface("eth1")?;

    println!("Starting forwarding from {} -> {}", in_iface.name, out_iface.name);
    forward_loop(in_iface, out_iface, forwarder)
}
```

