```rust
use anyhow::{Context, Result};
use clap::Parser;
use pnet::datalink::{self, Channel::Ethernet, Config, DataLinkReceiver, DataLinkSender, NetworkInterface};
use pnet::packet::ethernet::{EtherTypes, EthernetPacket, MutableEthernetPacket};
use pnet::packet::ip::IpNextHeaderProtocols;
use pnet::packet::ipv4::Ipv4Packet;
use pnet::packet::ipv6::Ipv6Packet;
use pnet::packet::tcp::TcpPacket;
use pnet::packet::udp::UdpPacket;
use pnet::packet::Packet;
use std::net::{IpAddr, Ipv4Addr};
use std::sync::Arc;
use std::time::Duration;

#[derive(Parser, Debug)]
#[command(name = "ultra-low-latency-forwarder")]
struct Args {
    /// Input interface
    #[arg(long)]
    input: String,

    /// Output interface
    #[arg(long)]
    output: String,

    /// Enable verbose logging
    #[arg(long, default_value_t = false)]
    verbose: bool,
}

#[derive(Clone, Debug)]
enum Action {
    Allow,
    Drop,
}

#[derive(Clone, Debug)]
enum Rule {
    AllowTcpDstPort(u16),
    AllowUdpDstPort(u16),
    DropIcmp,
    AllowSrcIp(IpAddr),
}

#[derive(Clone)]
struct FilterEngine {
    rules: Arc<Vec<Rule>>,
    default_action: Action,
}

impl FilterEngine {
    fn new(rules: Vec<Rule>, default_action: Action) -> Self {
        Self {
            rules: Arc::new(rules),
            default_action,
        }
    }

    fn evaluate(&self, packet: &[u8]) -> Action {
        let eth = match EthernetPacket::new(packet) {
            Some(p) => p,
            None => return Action::Drop,
        };

        match eth.get_ethertype() {
            EtherTypes::Ipv4 => {
                let ipv4 = match Ipv4Packet::new(eth.payload()) {
                    Some(p) => p,
                    None => return Action::Drop,
                };

                let src_ip = IpAddr::V4(ipv4.get_source());

                for rule in self.rules.iter() {
                    match rule {
                        Rule::AllowSrcIp(ip) if *ip == src_ip => return Action::Allow,
                        Rule::DropIcmp if ipv4.get_next_level_protocol() == IpNextHeaderProtocols::Icmp => {
                            return Action::Drop
                        }
                        Rule::AllowTcpDstPort(port)
                            if ipv4.get_next_level_protocol() == IpNextHeaderProtocols::Tcp =>
                        {
                            if let Some(tcp) = TcpPacket::new(ipv4.payload()) {
                                if tcp.get_destination() == *port {
                                    return Action::Allow;
                                }
                            }
                        }
                        Rule::AllowUdpDstPort(port)
                            if ipv4.get_next_level_protocol() == IpNextHeaderProtocols::Udp =>
                        {
                            if let Some(udp) = UdpPacket::new(ipv4.payload()) {
                                if udp.get_destination() == *port {
                                    return Action::Allow;
                                }
                            }
                        }
                        _ => {}
                    }
                }

                self.default_action.clone()
            }

            EtherTypes::Ipv6 => {
                let ipv6 = match Ipv6Packet::new(eth.payload()) {
                    Some(p) => p,
                    None => return Action::Drop,
                };

                let src_ip = IpAddr::V6(ipv6.get_source());

                for rule in self.rules.iter() {
                    match rule {
                        Rule::AllowSrcIp(ip) if *ip == src_ip => return Action::Allow,
                        Rule::DropIcmp if ipv6.get_next_header() == IpNextHeaderProtocols::Icmpv6 => {
                            return Action::Drop
                        }
                        Rule::AllowTcpDstPort(port)
                            if ipv6.get_next_header() == IpNextHeaderProtocols::Tcp =>
                        {
                            if let Some(tcp) = TcpPacket::new(ipv6.payload()) {
                                if tcp.get_destination() == *port {
                                    return Action::Allow;
                                }
                            }
                        }
                        Rule::AllowUdpDstPort(port)
                            if ipv6.get_next_header() == IpNextHeaderProtocols::Udp =>
                        {
                            if let Some(udp) = UdpPacket::new(ipv6.payload()) {
                                if udp.get_destination() == *port {
                                    return Action::Allow;
                                }
                            }
                        }
                        _ => {}
                    }
                }

                self.default_action.clone()
            }

            _ => self.default_action.clone(),
        }
    }
}

fn get_interface(name: &str) -> Result<NetworkInterface> {
    let interfaces = datalink::interfaces();
    interfaces
        .into_iter()
        .find(|iface| iface.name == name)
        .with_context(|| format!("interface '{}' not found", name))
}

fn build_sender_receiver(
    iface: &NetworkInterface,
) -> Result<(Box<dyn DataLinkSender>, Box<dyn DataLinkReceiver>)> {
    let mut config = Config::default();
    config.read_timeout = Some(Duration::from_millis(1));
    config.write_buffer_size = 1 << 20;
    config.read_buffer_size = 1 << 20;

    match datalink::channel(iface, config)? {
        Ethernet(tx, rx) => Ok((tx, rx)),
        _ => anyhow::bail!("unsupported channel type"),
    }
}

fn forward_packet(tx: &mut Box<dyn DataLinkSender>, packet: &[u8]) {
    let _ = tx.send_to(packet, None);
}

fn main() -> Result<()> {
    let args = Args::parse();

    let input_iface = get_interface(&args.input)?;
    let output_iface = get_interface(&args.output)?;

    let (_tx_in, mut rx) = build_sender_receiver(&input_iface)?;
    let (mut tx, _rx_out) = build_sender_receiver(&output_iface)?;

    let rules = vec![
        Rule::AllowTcpDstPort(443),
        Rule::AllowUdpDstPort(53),
        Rule::DropIcmp,
    ];

    let filter = FilterEngine::new(rules, Action::Drop);

    if args.verbose {
        eprintln!("Starting forwarder: {} -> {}", args.input, args.output);
    }

    loop {
        match rx.next() {
            Ok(packet) => {
                match filter.evaluate(packet) {
                    Action::Allow => {
                        forward_packet(&mut tx, packet);
                        if args.verbose {
                            eprintln!("forwarded {} bytes", packet.len());
                        }
                    }
                    Action::Drop => {
                        if args.verbose {
                            eprintln!("dropped {} bytes", packet.len());
                        }
                    }
                }
            }
            Err(_) => {
                // Keep spinning for low-latency behavior.
                // In production, consider backoff or metrics here.
                continue;
            }
        }
    }
}
```

