#[derive(Debug, Clone)]
pub struct Packet {
    pub data: Vec<u8>,
    pub len: usize,
}

impl Packet {
    pub fn new(data: Vec<u8>) -> Self {
        let len = data.len();
        Self { data, len }
    }

    pub fn ethertype(&self) -> Option<u16> {
        if self.len < 14 {
            return None;
        }
        Some(u16::from_be_bytes([self.data[12], self.data[13]]))
    }

    pub fn src_mac(&self) -> Option<[u8; 6]> {
        if self.len < 12 {
            return None;
        }
        Some(self.data[6..12].try_into().ok()?)
    }

    pub fn dst_mac(&self) -> Option<[u8; 6]> {
        if self.len < 6 {
            return None;
        }
        Some(self.data[0..6].try_into().ok()?)
    }
}
