    min_len: usize,
    max_len: usize,
    allow_ethertypes: Vec<u16>,
}

impl Filter {
    pub fn new(cfg: &Config) -> Self {
        let allow_ethertypes = cfg
            .allow_ethertypes
            .iter()
            .filter_map(|s| {
                let s = s.trim();
                let s = s.strip_prefix("0x").unwrap_or(s);
                u16::from_str_radix(s, 16).ok()
            })
            .collect();

        Self {
            min_len: cfg.min_len,
            max_len: cfg.max_len,
            allow_ethertypes,
        }
    }

    pub fn allow(&self, pkt: &Packet) -> bool {
        if pkt.len < self.min_len || pkt.len > self.max_len {
            return false;
        }

        if self.allow_ethertypes.is_empty() {
            return true;
        }

        match pkt.ethertype() {
            Some(et) => self.allow_ethertypes.contains(&et),
            None => false,
        }
    }
}
