```rust
use anyhow::{Context, Result};
use nix::sys::socket::{
    bind, recv, send, socket, AddressFamily, MsgFlags, SockFlag, SockProtocol, SockType,
};
use nix::unistd::close;
use std::os::fd::RawFd;

pub struct RawSocket {
    fd: RawFd,
}

impl RawSocket {
    pub fn open_packet_socket(ifindex: i32) -> Result<Self> {
        let fd = socket(
            AddressFamily::Packet,
            SockType::Raw,
            SockFlag::empty(),
            SockProtocol::EthAll,
        )
        .context("socket(AF_PACKET) failed")?;

        // Bind to interface
        let sll = libc::sockaddr_ll {
            sll_family: libc::AF_PACKET as u16,
            sll_protocol: u16::to_be(libc::ETH_P_ALL as u16),
            sll_ifindex: ifindex,
            sll_hatype: 0,
            sll_pkttype: 0,
            sll_halen: 0,
            sll_addr: [0; 8],
        };

        let ret = unsafe {
            bind(
                fd,
                &sll as *const libc::sockaddr_ll as *const libc::sockaddr,
                std::mem::size_of::<libc::sockaddr_ll>() as u32,
            )
        };

        if let Err(e) = ret {
            let _ = close(fd);
            return Err(anyhow::anyhow!("bind(AF_PACKET) failed: {e}"));
        }

        Ok(Self { fd })
    }

    pub fn recv_packet(&self, buf: &mut [u8]) -> Result<usize> {
        let n = recv(self.fd, buf, MsgFlags::empty()).context("recv failed")?;
        Ok(n)
    }

    pub fn send_packet(&self, buf: &[u8]) -> Result<usize> {
        let n = send(self.fd, buf, MsgFlags::empty()).context("send failed")?;
        Ok(n)
    }
}

impl Drop for RawSocket {
    fn drop(&mut self) {
        let _ = close(self.fd);
    }
}
