```rust
mod config;
mod filter;
mod forward;
mod packet;
mod stats;

use anyhow::Result;
use clap::Parser;
use config::Config;
use crossbeam_channel::{bounded, Receiver, Sender};
use filter::Filter;
use forward::RawSocket;
use packet::Packet;
use stats::Stats;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

fn ifindex_from_name(name: &str) -> Result<i32> {
    let c_name = std::ffi::CString::new(name)?;
    let idx = unsafe { libc::if_nametoindex(c_name.as_ptr()) };
    if idx == 0 {
        Err(anyhow::anyhow!("interface not found: {name}"))
    } else {
        Ok(idx as i32)
    }
}

fn rx_loop(sock: Arc<RawSocket>, tx: Sender<Packet>, stats: Arc<Stats>) -> Result<()> {
    let mut buf = vec![0u8; 2048];

    loop {
        let n = sock.recv_packet(&mut buf)?;
        if n == 0 {
            continue;
        }

        stats.inc_rx(n as u64);

        let pkt = Packet::new(buf[..n].to_vec());
        if tx.send(pkt).is_err() {
            break;
        }
    }

    Ok(())
}

fn worker_loop(
    rx: Receiver<Packet>,
    tx_sock: Arc<RawSocket>,
    filter: Arc<Filter>,
    stats: Arc<Stats>,
) -> Result<()> {
    while let Ok(pkt) = rx.recv() {
        if filter.allow(&pkt) {
            let sent = tx_sock.send_packet(&pkt.data)?;
            stats.inc_tx(sent as u64);
        } else {
            stats.inc_filtered();
            stats.inc_drop();
        }
    }
    Ok(())
}

fn main() -> Result<()> {
    let cfg = Config::parse();

    let in_if = ifindex_from_name(&cfg.input_if)?;
    let out_if = ifindex_from_name(&cfg.output_if)?;

    let rx_sock = Arc::new(RawSocket::open_packet_socket(in_if)?);
    let tx_sock = Arc::new(RawSocket::open_packet_socket(out_if)?);

    let filter = Arc::new(Filter::new(&cfg));
    let stats = Arc::new(Stats::default());

    let (tx, rx) = bounded::<Packet>(65_536);

    // RX thread
    {
        let rx_sock = rx_sock.clone();
        let tx = tx.clone();
        let stats = stats.clone();
        thread::spawn(move || {
            if let Err(e) = rx_loop(rx_sock, tx, stats) {
                eprintln!("rx loop error: {e:?}");
            }
        });
    }

    // Worker threads
    for _ in 0..cfg.workers {
        let rx = rx.clone();
        let tx_sock = tx_sock.clone();
        let filter = filter.clone();
        let stats = stats.clone();

        thread::spawn(move || {
            if let Err(e) = worker_loop(rx, tx_sock, filter, stats) {
                eprintln!("worker loop error: {e:?}");
            }
        });
    }

    // Stats printer
    {
        let stats = stats.clone();
        thread::spawn(move || loop {
            thread::sleep(Duration::from_secs(1));
            println!(
                "rx={} tx={} drop={} filtered={} rx_bytes={} tx_bytes={}",
                stats.rx_packets.load(std::sync::atomic::Ordering::Relaxed),
                stats.tx_packets.load(std::sync::atomic::Ordering::Relaxed),
                stats.dropped_packets.load(std::sync::atomic::Ordering::Relaxed),
                stats.filtered_packets.load(std::sync::atomic::Ordering::Relaxed),
                stats.rx_bytes.load(std::sync::atomic::Ordering::Relaxed),
                stats.tx_bytes.load(std::sync::atomic::Ordering::Relaxed),
            );
        });
    }

    // Keep main alive
    loop {
        thread::park();
    }
}
