use anyhow::{Context, Result};
use bytes::BytesMut;
use socket2::{Domain, Protocol, Socket, Type};
use std::{
    net::{Ipv4Addr, SocketAddr, SocketAddrV4},
    sync::Arc,
    time::Instant,
};
use tokio::net::UdpSocket;
use tracing::{debug, info, warn};

const MAX_PACKET_SIZE: usize = 2048;
const BATCH_SIZE: usize = 64;

#[derive(Clone, Debug)]
struct FilterConfig {
    allow_src: Option<Ipv4Addr>,
    allow_dst: Option<Ipv4Addr>,
    allow_src_port: Option<u16>,
    allow_dst_port: Option<u16>,
}

impl FilterConfig {
    fn matches(&self, pkt: &PacketView<'_>) -> bool {
        if let Some(ip) = self.allow_src {
            if pkt.src_ip != Some(ip) {
                return false;
            }
        }
        if let Some(ip) = self.allow_dst {
            if pkt.dst_ip != Some(ip) {
                return false;
            }
        }
        if let Some(port) = self.allow_src_port {
            if pkt.src_port != Some(port) {
                return false;
            }
        }
        if let Some(port) = self.allow_dst_port {
            if pkt.dst_port != Some(port) {
                return false;
            }
        }
        true
    }
}

#[derive(Debug, Clone, Copy)]
struct PacketView<'a> {
    data: &'a [u8],
    src_ip: Option<Ipv4Addr>,
    dst_ip: Option<Ipv4Addr>,
    src_port: Option<u16>,
    dst_port: Option<u16>,
}

impl<'a> PacketView<'a> {
    fn parse_udp_ipv4(data: &'a [u8]) -> Self {
        // Minimal parser for IPv4 + UDP.
        // Assumes Ethernet header is stripped or packet is already UDP payload.
        // For a real NIC dataplane, parse L2/L3/L4 headers explicitly.
        let mut pkt = PacketView {
            data,
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: None,
        };

        // Very lightweight heuristic parser:
        // If packet looks like IPv4, try to extract addresses and UDP ports.
        if data.len() >= 28 && (data[0] >> 4) == 4 {
            let ihl = ((data[0] & 0x0f) as usize) * 4;
            if data.len() >= ihl + 8 {
                let proto = data[9];
                if proto == 17 {
                    let src_ip = Ipv4Addr::new(data[12], data[13], data[14], data[15]);
                    let dst_ip = Ipv4Addr::new(data[16], data[17], data[18], data[19]);
                    let udp_off = ihl;
                    let src_port = u16::from_be_bytes([data[udp_off], data[udp_off + 1]]);
                    let dst_port = u16::from_be_bytes([data[udp_off + 2], data[udp_off + 3]]);
                    pkt.src_ip = Some(src_ip);
                    pkt.dst_ip = Some(dst_ip);
                    pkt.src_port = Some(src_port);
                    pkt.dst_port = Some(dst_port);
                }
            }
        }

        pkt
    }
}

struct Forwarder {
    out_socket: Arc<UdpSocket>,
    out_addr: SocketAddr,
}

impl Forwarder {
    async fn forward(&self, packet: &[u8]) -> Result<()> {
        self.out_socket
            .send_to(packet, self.out_addr)
            .await
            .context("forward send_to failed")?;
        Ok(())
    }
}

fn create_udp_socket(bind_addr: SocketAddr) -> Result<std::net::UdpSocket> {
    let domain = match bind_addr {
        SocketAddr::V4(_) => Domain::IPV4,
        SocketAddr::V6(_) => Domain::IPV6,
    };

    let socket = Socket::new(domain, Type::DGRAM, Some(Protocol::UDP))
        .context("failed to create socket")?;
    socket
        .set_reuse_address(true)
        .context("failed to set reuse_address")?;
    socket
        .bind(&bind_addr.into())
        .context("failed to bind socket")?;

    Ok(socket.into())
}

#[tokio::main(flavor = "current_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    // Example config:
    // Listen on 0.0.0.0:9000 and forward matching packets to 127.0.0.1:9001
    let listen_addr: SocketAddr = "0.0.0.0:9000".parse()?;
    let forward_addr: SocketAddr = "127.0.0.1:9001".parse()?;

    let filter = FilterConfig {
        allow_src: None,
        allow_dst: None,
        allow_src_port: None,
        allow_dst_port: Some(9000),
    };

    let raw_sock = create_udp_socket(listen_addr)?;
    raw_sock
        .set_nonblocking(true)
        .context("failed to set nonblocking")?;
    let in_socket = UdpSocket::from_std(raw_sock).context("tokio from_std failed")?;

    let out_raw = create_udp_socket("0.0.0.0:0".parse()?)?;
    out_raw
        .set_nonblocking(true)
        .context("failed to set nonblocking")?;
    let out_socket = Arc::new(UdpSocket::from_std(out_raw).context("tokio from_std failed")?);

    let forwarder = Forwarder {
        out_socket,
        out_addr: forward_addr,
    };

    info!("listening on {}", listen_addr);
    info!("forwarding to {}", forward_addr);

    let mut buf = vec![0u8; MAX_PACKET_SIZE];
    let mut processed: u64 = 0;
    let mut forwarded: u64 = 0;
    let mut dropped: u64 = 0;
    let mut last_stats = Instant::now();

    loop {
        let n = match in_socket.recv(&mut buf).await {
            Ok(n) => n,
            Err(e) => {
                warn!("recv error: {e}");
                continue;
            }
        };

        processed += 1;

        let pkt = PacketView::parse_udp_ipv4(&buf[..n]);

        if filter.matches(&pkt) {
            if let Err(e) = forwarder.forward(pkt.data).await {
                warn!("forward error: {e}");
                dropped += 1;
            } else {
                forwarded += 1;
            }
        } else {
            dropped += 1;
        }

        if last_stats.elapsed().as_secs_f32() >= 1.0 {
            info!(
                processed,
                forwarded,
                dropped,
                "packet stats"
            );
            last_stats = Instant::now();
        }
    }
}
