use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum L4Protocol {
    Tcp,
    Udp,
    Icmp,
    Other(u8),
}

#[derive(Debug, Clone, Copy)]
pub struct PacketMeta {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: L4Protocol,
    pub len: usize,
}

impl PacketMeta {
    pub fn parse_ipv4(packet: &[u8]) -> Option<Self> {
        if packet.len() < 34 {
            return None;
        }

        // Ethernet header: 14 bytes
        let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
        if ethertype != 0x0800 {
            return None;
        }

        let ihl = (packet[14] & 0x0f) as usize * 4;
        if packet.len() < 14 + ihl + 8 {
            return None;
        }

        let proto = packet[23];
        let src_ip = Ipv4Addr::new(packet[26], packet[27], packet[28], packet[29]);
        let dst_ip = Ipv4Addr::new(packet[30], packet[31], packet[32], packet[33]);

        let l4_offset = 14 + ihl;
        let src_port = u16::from_be_bytes([packet[l4_offset], packet[l4_offset + 1]]);
        let dst_port = u16::from_be_bytes([packet[l4_offset + 2], packet[l4_offset + 3]]);

        let proto = match proto {
            6 => L4Protocol::Tcp,
            17 => L4Protocol::Udp,
            1 => L4Protocol::Icmp,
            x => L4Protocol::Other(x),
        };

        Some(PacketMeta {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
            len: packet.len(),
        })
    }
}
