use crate::packet::{L4Protocol, PacketMeta};
use std::net::Ipv4Addr;

#[derive(Debug, Clone)]
pub enum Action {
    Drop,
    Forward { out_port: u16 },
    Pass,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub src_ip: Option<Ipv4Addr>,
    pub dst_ip: Option<Ipv4Addr>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub proto: Option<L4Protocol>,
    pub action: Action,
}

impl Rule {
    pub fn matches(&self, pkt: &PacketMeta) -> bool {
        if let Some(ip) = self.src_ip {
            if pkt.src_ip != ip {
                return false;
            }
        }
        if let Some(ip) = self.dst_ip {
            if pkt.dst_ip != ip {
                return false;
            }
        }
        if let Some(port) = self.src_port {
            if pkt.src_port != port {
                return false;
            }
        }
        if let Some(port) = self.dst_port {
            if pkt.dst_port != port {
                return false;
            }
        }
        if let Some(proto) = self.proto {
            if pkt.proto != proto {
                return false;
            }
        }
        true
    }
}

#[derive(Debug, Default)]
pub struct RuleEngine {
    rules: Vec<Rule>,
}

impl RuleEngine {
    pub fn new(rules: Vec<Rule>) -> Self {
        Self { rules }
    }

    pub fn decide(&self, pkt: &PacketMeta) -> Action {
        for rule in &self.rules {
            if rule.matches(pkt) {
                return rule.action.clone();
            }
        }
        Action::Pass
    }
}
