}

pub trait PacketSink {
    fn send(&mut self, packet: &[u8], out_port: u16) -> Result<()>;
}

pub struct Dataplane<S: PacketSource, K: PacketSink> {
    source: S,
    sink: K,
    rules: Arc<RuleEngine>,
    batch: Vec<Vec<u8>>,
}

impl<S: PacketSource, K: PacketSink> Dataplane<S, K> {
    pub fn new(source: S, sink: K, rules: Arc<RuleEngine>) -> Self {
        Self {
            source,
            sink,
            rules,
            batch: Vec::with_capacity(1024),
        }
    }

    pub fn run(&mut self) -> Result<()> {
        loop {
            self.batch.clear();
            let n = self.source.recv_batch(&mut self.batch)?;
            if n == 0 {
                continue;
            }

            let start = Instant::now();

            for packet in &self.batch {
                if let Some(meta) = PacketMeta::parse_ipv4(packet) {
                    match self.rules.decide(&meta) {
                        Action::Drop => {
                            // drop fast path
                        }
                        Action::Forward { out_port } => {
                            self.sink.send(packet, out_port)?;
                        }
                        Action::Pass => {
                            // default forward path, e.g. port 0
                            self.sink.send(packet, 0)?;
                        }
                    }
                }
            }

            let elapsed = start.elapsed();
            if elapsed.as_micros() > 100 {
                log::debug!("processed {} packets in {:?}", n, elapsed);
            }
        }
    }
}
