```rust
use etherparse::{Ethernet2HeaderSlice, Ipv4HeaderSlice, Ipv6HeaderSlice, TcpHeaderSlice, UdpHeaderSlice};

#[derive(Debug, Clone, Copy)]
pub enum L3Protocol {
    Ipv4,
    Ipv6,
    Other,
}

#[derive(Debug, Clone, Copy)]
pub enum L4Protocol {
    Tcp,
    Udp,
    Other,
}

#[derive(Debug, Clone)]
pub struct PacketMeta {
    pub l3: L3Protocol,
    pub l4: L4Protocol,
    pub src_ip: Option<[u8; 16]>,
    pub dst_ip: Option<[u8; 16]>,
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub ethertype: Option<u16>,
}

impl Default for PacketMeta {
    fn default() -> Self {
        Self {
            l3: L3Protocol::Other,
            l4: L4Protocol::Other,
            src_ip: None,
            dst_ip: None,
            src_port: None,
            dst_port: None,
            ethertype: None,
        }
    }
}

pub fn parse_packet(packet: &[u8]) -> Option<PacketMeta> {
    let eth = Ethernet2HeaderSlice::from_slice(packet).ok()?;
    let ethertype = eth.ether_type().0;

    let mut meta = PacketMeta {
        ethertype: Some(ethertype),
        ..Default::default()
    };

    let payload = eth.payload();

    match ethertype {
        0x0800 => {
            // IPv4
            let ip = Ipv4HeaderSlice::from_slice(payload).ok()?;
            meta.l3 = L3Protocol::Ipv4;

            let src = ip.source_addr().octets();
            let dst = ip.destination_addr().octets();
            let mut src16 = [0u8; 16];
            let mut dst16 = [0u8; 16];
            src16[..4].copy_from_slice(&src);
            dst16[..4].copy_from_slice(&dst);
            meta.src_ip = Some(src16);
            meta.dst_ip = Some(dst16);

            let l4_payload = ip.payload();

            match ip.protocol() {
                6 => {
                    let tcp = TcpHeaderSlice::from_slice(l4_payload).ok()?;
                    meta.l4 = L4Protocol::Tcp;
                    meta.src_port = Some(tcp.source_port());
                    meta.dst_port = Some(tcp.destination_port());
                }
                17 => {
                    let udp = UdpHeaderSlice::from_slice(l4_payload).ok()?;
                    meta.l4 = L4Protocol::Udp;
                    meta.src_port = Some(udp.source_port());
                    meta.dst_port = Some(udp.destination_port());
                }
                _ => {}
            }
        }
        0x86DD => {
            // IPv6
            let ip = Ipv6HeaderSlice::from_slice(payload).ok()?;
            meta.l3 = L3Protocol::Ipv6;

            meta.src_ip = Some(ip.source_addr().octets());
            meta.dst_ip = Some(ip.destination_addr().octets());

            let l4_payload = ip.payload();

            match ip.next_header() {
                6 => {
                    let tcp = TcpHeaderSlice::from_slice(l4_payload).ok()?;
                    meta.l4 = L4Protocol::Tcp;
                    meta.src_port = Some(tcp.source_port());
                    meta.dst_port = Some(tcp.destination_port());
                }
                17 => {
                    let udp = UdpHeaderSlice::from_slice(l4_payload).ok()?;
                    meta.l4 = L4Protocol::Udp;
                    meta.src_port = Some(udp.source_port());
                    meta.dst_port = Some(udp.destination_port());
                }
                _ => {}
            }
        }
        _ => {}
    }

    Some(meta)
}
