```rust
use crate::packet::{L3Protocol, L4Protocol, PacketMeta};

#[derive(Debug, Clone)]
pub enum Action {
    Allow,
    Drop,
    Forward(u16), // output interface id
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub src_port: Option<u16>,
    pub dst_port: Option<u16>,
    pub l3: Option<L3Protocol>,
    pub l4: Option<L4Protocol>,
    pub action: Action,
}

#[derive(Debug, Default)]
pub struct FilterEngine {
    rules: Vec<Rule>,
    default_action: Action,
}

impl FilterEngine {
    pub fn new(default_action: Action) -> Self {
        Self {
            rules: Vec::new(),
            default_action,
        }
    }

    pub fn add_rule(&mut self, rule: Rule) {
        self.rules.push(rule);
    }

    pub fn evaluate(&self, meta: &PacketMeta) -> Action {
        for rule in &self.rules {
            if let Some(l3) = rule.l3 {
                if meta.l3 as u8 != l3 as u8 {
                    continue;
                }
            }

            if let Some(l4) = rule.l4 {
                if meta.l4 as u8 != l4 as u8 {
                    continue;
                }
            }

            if let Some(src_port) = rule.src_port {
                if meta.src_port != Some(src_port) {
                    continue;
                }
            }

            if let Some(dst_port) = rule.dst_port {
                if meta.dst_port != Some(dst_port) {
                    continue;
                }
            }

            return rule.action.clone();
        }

        self.default_action.clone()
    }
}
