# `src/engine.rs`

```rust
use anyhow::Result;
use crossbeam_channel::{Receiver, Sender};
use log::{debug, info};

use crate::filter::{Action, FilterEngine};
use crate::forward::ForwardingTable;
use crate::packet::parse_packet;

pub struct PacketEngine {
    filter: FilterEngine,
    forwarding: ForwardingTable,
    tx: Sender<(u16, Vec<u8>)>,
}

impl PacketEngine {
    pub fn new(filter: FilterEngine, forwarding: ForwardingTable, tx: Sender<(u16, Vec<u8>)>) -> Self {
        Self {
            filter,
            forwarding,
            tx,
        }
    }

    pub fn run(&self, rx: Receiver<Vec<u8>>) -> Result<()> {
        info!("packet engine started");

        while let Ok(packet) = rx.recv() {
            if let Some(meta) = parse_packet(&packet) {
                let action = self.filter.evaluate(&meta);

                match action {
                    Action::Drop => {
                        debug!("packet dropped");
                    }
                    Action::Allow => {
                        let decision = self.forwarding.lookup(&packet);
                        self.tx.send((decision.out_if, packet))?;
                    }
                    Action::Forward(out_if) => {
                        self.tx.send((out_if, packet))?;
                    }
                }
            } else {
                debug!("failed to parse packet; dropping");
            }
        }

        Ok(())
    }
}
