```rust
use std::net::Ipv4Addr;

#[derive(Debug, Clone, Copy)]
pub struct EthernetHeader {
    pub dst: [u8; 6],
    pub src: [u8; 6],
    pub ethertype: u16,
}

#[derive(Debug, Clone, Copy)]
pub struct Ipv4Header {
    pub src: Ipv4Addr,
    pub dst: Ipv4Addr,
    pub protocol: u8,
}

#[derive(Debug, Clone, Copy)]
pub struct ParsedPacket<'a> {
    pub eth: EthernetHeader,
    pub ipv4: Option<Ipv4Header>,
    pub payload: &'a [u8],
}

pub fn parse_ethernet(frame: &[u8]) -> Option<ParsedPacket<'_>> {
    if frame.len() < 14 {
        return None;
    }

    let eth = EthernetHeader {
        dst: frame[0..6].try_into().ok()?,
        src: frame[6..12].try_into().ok()?,
        ethertype: u16::from_be_bytes([frame[12], frame[13]]),
    };

    let mut ipv4 = None;
    let payload = if eth.ethertype == 0x0800 && frame.len() >= 34 {
        let ihl = (frame[14] & 0x0f) as usize * 4;
        if frame.len() < 14 + ihl || ihl < 20 {
            return Some(ParsedPacket {
                eth,
                ipv4: None,
                payload: &frame[14..],
            });
        }

        let src = Ipv4Addr::new(frame[26], frame[27], frame[28], frame[29]);
        let dst = Ipv4Addr::new(frame[30], frame[31], frame[32], frame[33]);
        let protocol = frame[23];

        ipv4 = Some(Ipv4Header { src, dst, protocol });

        &frame[14 + ihl..]
    } else {
        &frame[14..]
    };

    Some(ParsedPacket { eth, ipv4, payload })
}
```

