## `src/dataplane.rs`

```rust
use crate::packet::parse_ethernet;
use crate::rules::{Action, RuleEngine};
use crossbeam_channel::{Receiver, Sender};
use parking_lot::RwLock;
use std::sync::Arc;

#[derive(Debug, Clone)]
pub struct Packet {
    pub data: Vec<u8>,
    pub ingress_port: u16,
}

#[derive(Debug, Clone)]
pub struct TxPacket {
    pub data: Vec<u8>,
    pub egress_port: u16,
}

pub struct DataPlane {
    rules: Arc<RwLock<RuleEngine>>,
    rx: Receiver<Packet>,
    tx: Sender<TxPacket>,
}

impl DataPlane {
    pub fn new(
        rules: Arc<RwLock<RuleEngine>>,
        rx: Receiver<Packet>,
        tx: Sender<TxPacket>,
    ) -> Self {
        Self { rules, rx, tx }
    }

    pub fn run(&self) {
        while let Ok(pkt) = self.rx.recv() {
            self.process_packet(pkt);
        }
    }

    fn process_packet(&self, pkt: Packet) {
        let parsed = match parse_ethernet(&pkt.data) {
            Some(p) => p,
            None => return,
        };

        let ipv4 = parsed.ipv4;
        let action = {
            let rules = self.rules.read();
            rules.evaluate(
                parsed.eth.ethertype,
                ipv4.map(|h| h.src),
                ipv4.map(|h| h.dst),
            )
        };

        match action {
            Action::Allow => {
                // In a real implementation, this would forward to a default egress.
                let _ = self.tx.send(TxPacket {
                    data: pkt.data,
                    egress_port: pkt.ingress_port,
                });
            }
            Action::Drop => {
                // drop silently
            }
            Action::Forward { port } => {
                let _ = self.tx.send(TxPacket {
                    data: pkt.data,
                    egress_port: port,
                });
            }
        }
    }
}
