use parking_lot::RwLock;
use rules::{Action, Rule, RuleEngine};
use std::net::Ipv4Addr;
use std::sync::Arc;
use std::thread;

fn main() -> Result<()> {
    let (rx_tx, rx_rx) = unbounded::<Packet>();
    let (tx_tx, tx_rx) = unbounded::<dataplane::TxPacket>();

    let mut engine = RuleEngine::new(Action::Drop);
    engine.set_rules(vec![
        Rule {
            src_ip: Some(Ipv4Addr::new(10, 0, 0, 1)),
            dst_ip: None,
            ethertype: Some(0x0800),
            action: Action::Forward { port: 2 },
        },
        Rule {
            src_ip: None,
            dst_ip: Some(Ipv4Addr::new(10, 0, 0, 99)),
            ethertype: Some(0x0800),
            action: Action::Drop,
        },
    ]);

    let rules = Arc::new(RwLock::new(engine));
    let dataplane = DataPlane::new(rules.clone(), rx_rx, tx_tx);

    let dp_thread = thread::spawn(move || {
        dataplane.run();
    });

    // Simulated packet injection
    rx_tx.send(Packet {
        data: vec![
            0, 1, 2, 3, 4, 5, // dst mac
            6, 7, 8, 9, 10, 11, // src mac
            0x08, 0x00, // ethertype IPv4
            0x45, 0x00, 0x00, 0x28, 0, 0, 0, 0, 64, 6, 0, 0,
            10, 0, 0, 1, // src ip
            10, 0, 0, 2, // dst ip
        ],
        ingress_port: 1,
    })?;

    drop(rx_tx);

    while let Ok(pkt) = tx_rx.recv() {
        println!("TX packet on port {} ({} bytes)", pkt.egress_port, pkt.data.len());
    }

    dp_thread.join().unwrap();
    Ok(())
}
```

