```rust
use libc::{c_int, c_void};
use std::ffi::CString;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::ptr;
use std::slice;

const ETH_P_ALL: u16 = 0x0003;
const ETH_P_IP: u16 = 0x0800;
const IPPROTO_TCP: u8 = 6;

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct Ipv4Hdr {
    ver_ihl: u8,
    dscp_ecn: u8,
    total_len: u16,
    id: u16,
    flags_frag: u16,
    ttl: u8,
    proto: u8,
    checksum: u16,
    src: u32,
    dst: u32,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct TcpHdr {
    src_port: u16,
    dst_port: u16,
    seq: u32,
    ack: u32,
    data_offset_reserved_flags: u16,
    window: u16,
    checksum: u16,
    urgent_ptr: u16,
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn ntohs(v: u16) -> u16 {
    u16::from_be(v)
}

fn ntohl(v: u32) -> u32 {
    u32::from_be(v)
}

fn open_raw_socket(iface: &str) -> io::Result<c_int> {
    unsafe {
        let fd = libc::socket(libc::AF_PACKET, libc::SOCK_RAW, i32::from(htons(ETH_P_ALL)) as c_int);
        if fd < 0 {
            return Err(io::Error::last_os_error());
        }

        let c_iface = CString::new(iface).unwrap();
        let ifindex = libc::if_nametoindex(c_iface.as_ptr());
        if ifindex == 0 {
            return Err(io::Error::last_os_error());
        }

        let mut sll: libc::sockaddr_ll = mem::zeroed();
        sll.sll_family = libc::AF_PACKET as u16;
        sll.sll_protocol = htons(ETH_P_ALL);
        sll.sll_ifindex = ifindex as i32;

        let ret = libc::bind(
            fd,
            &sll as *const _ as *const libc::sockaddr,
            mem::size_of::<libc::sockaddr_ll>() as u32,
        );
        if ret < 0 {
            return Err(io::Error::last_os_error());
        }

        Ok(fd)
    }
}

fn parse_eth(frame: &[u8]) -> Option<EthHdr> {
    if frame.len() < mem::size_of::<EthHdr>() {
        return None;
    }
    Some(unsafe { ptr::read_unaligned(frame.as_ptr() as *const EthHdr) })
}

fn parse_ipv4(pkt: &[u8]) -> Option<(Ipv4Hdr, usize)> {
    if pkt.len() < mem::size_of::<Ipv4Hdr>() {
        return None;
    }
    let hdr = unsafe { ptr::read_unaligned(pkt.as_ptr() as *const Ipv4Hdr) };
    let ihl = (hdr.ver_ihl & 0x0f) as usize * 4;
    if ihl < 20 || pkt.len() < ihl {
        return None;
    }
    Some((hdr, ihl))
}

fn parse_tcp(pkt: &[u8]) -> Option<(TcpHdr, usize)> {
    if pkt.len() < mem::size_of::<TcpHdr>() {
        return None;
    }
    let hdr = unsafe { ptr::read_unaligned(pkt.as_ptr() as *const TcpHdr) };
    let off = ((u16::from_be(hdr.data_offset_reserved_flags) >> 12) as usize) * 4;
    if off < 20 || pkt.len() < off {
        return None;
    }
    Some((hdr, off))
}

fn main() -> io::Result<()> {
    let iface = std::env::args().nth(1).unwrap_or_else(|| "eth0".to_string());
    let allow_dst_ip: Ipv4Addr = "192.0.2.10".parse().unwrap(); // fixed allowed destination
    let allow_dst_port: u16 = 443;

    let fd = open_raw_socket(&iface)?;
    let mut buf = vec![0u8; 65536];

    loop {
        let n = unsafe {
            libc::recv(fd, buf.as_mut_ptr() as *mut c_void, buf.len(), 0)
        };
        if n < 0 {
            eprintln!("recv error: {}", io::Error::last_os_error());
            continue;
        }
        let frame = &buf[..n as usize];

        let eth = match parse_eth(frame) {
            Some(h) => h,
            None => continue,
        };

        if ntohs(eth.ethertype) != ETH_P_IP {
            continue;
        }

        let ip_off = mem::size_of::<EthHdr>();
        let ip_pkt = &frame[ip_off..];
        let (ip, ip_hlen) = match parse_ipv4(ip_pkt) {
            Some(v) => v,
            None => continue,
        };

        if ip.proto != IPPROTO_TCP {
            continue;
        }

        let dst_ip = Ipv4Addr::from(ntohl(ip.dst));
        if dst_ip != allow_dst_ip {
            continue;
        }

        let tcp_pkt = &ip_pkt[ip_hlen..];
        let (tcp, _tcp_hlen) = match parse_tcp(tcp_pkt) {
            Some(v) => v,
            None => continue,
        };

        let dst_port = ntohs(tcp.dst_port);
        if dst_port != allow_dst_port {
            continue;
        }

        // Minimal forwarding action:
        // In a real appliance, you would rewrite L2/L3 headers and transmit via a
        // dedicated egress socket/interface. Here we just log the accepted packet.
        let src_ip = Ipv4Addr::from(ntohl(ip.src));
        let src_port = ntohs(tcp.src_port);
        println!("ACCEPT {}:{} -> {}:{}", src_ip, src_port, dst_ip, dst_port);
    }
}
