```rust
use libc::{
    c_int, c_void, if_nametoindex, recv, sendto, socket, sockaddr, sockaddr_ll, AF_PACKET,
    ETH_P_ALL, PACKET_OUTGOING, SOCK_RAW,
};
use std::env;
use std::ffi::CString;
use std::io;
use std::mem;
use std::net::Ipv4Addr;
use std::os::unix::io::RawFd;
use std::ptr;

const ETH_HDR_LEN: usize = 14;
const BUF_SIZE: usize = 2048;

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct EthHdr {
    dst: [u8; 6],
    src: [u8; 6],
    ethertype: u16,
}

#[repr(C, packed)]
#[derive(Clone, Copy)]
struct Ipv4Hdr {
    ver_ihl: u8,
    dscp_ecn: u8,
    total_len: u16,
    id: u16,
    flags_frag: u16,
    ttl: u8,
    proto: u8,
    checksum: u16,
    src: u32,
    dst: u32,
}

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn parse_mac(s: &str) -> Option<[u8; 6]> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() != 6 {
        return None;
    }
    let mut mac = [0u8; 6];
    for (i, p) in parts.iter().enumerate() {
        mac[i] = u8::from_str_radix(p, 16).ok()?;
    }
    Some(mac)
}

fn open_raw_socket() -> io::Result<RawFd> {
    let fd = unsafe { socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL as u16) as c_int) };
    if fd < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(fd)
    }
}

fn ifindex(name: &str) -> io::Result<i32> {
    let c = CString::new(name).unwrap();
    let idx = unsafe { if_nametoindex(c.as_ptr()) };
    if idx == 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(idx as i32)
    }
}

fn bind_socket(fd: RawFd, ifname: &str) -> io::Result<()> {
    let idx = ifindex(ifname)?;
    let sll = sockaddr_ll {
        sll_family: AF_PACKET as u16,
        sll_protocol: htons(ETH_P_ALL as u16),
        sll_ifindex: idx,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        libc::bind(
            fd,
            &sll as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(())
    }
}

fn send_packet(fd: RawFd, ifname: &str, data: &[u8]) -> io::Result<usize> {
    let idx = ifindex(ifname)?;
    let sll = sockaddr_ll {
        sll_family: AF_PACKET as u16,
        sll_protocol: htons(ETH_P_ALL as u16),
        sll_ifindex: idx,
        sll_hatype: 0,
        sll_pkttype: 0,
        sll_halen: 0,
        sll_addr: [0; 8],
    };

    let ret = unsafe {
        sendto(
            fd,
            data.as_ptr() as *const c_void,
            data.len(),
            0,
            &sll as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };

    if ret < 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(ret as usize)
    }
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!(
            "Usage: {} <ingress_if> <egress_if> [--ethertype 0x0800] [--ipv4-proto 17] [--dst-mac aa:bb:cc:dd:ee:ff]",
            args[0]
        );
        std::process::exit(1);
    }

    let ingress = &args[1];
    let egress = &args[2];

    let mut ethertype_filter: Option<u16> = None;
    let mut ipv4_proto_filter: Option<u8> = None;
    let mut dst_mac_filter: Option<[u8; 6]> = None;

    let mut i = 3;
    while i < args.len() {
        match args[i].as_str() {
            "--ethertype" if i + 1 < args.len() => {
                let s = args[i + 1].trim_start_matches("0x");
                ethertype_filter = u16::from_str_radix(s, 16).ok();
                i += 2;
            }
            "--ipv4-proto" if i + 1 < args.len() => {
                ipv4_proto_filter = args[i + 1].parse::<u8>().ok();
                i += 2;
            }
            "--dst-mac" if i + 1 < args.len() => {
                dst_mac_filter = parse_mac(&args[i + 1]);
                i += 2;
            }
            _ => {
                eprintln!("Unknown or incomplete argument: {}", args[i]);
                std::process::exit(1);
            }
        }
    }

    let rx_fd = open_raw_socket()?;
    let tx_fd = open_raw_socket()?;

    bind_socket(rx_fd, ingress)?;

    let mut buf = [0u8; BUF_SIZE];

    eprintln!("Forwarding from {} -> {}", ingress, egress);
    eprintln!(
        "Filters: ethertype={:?}, ipv4_proto={:?}, dst_mac={:?}",
        ethertype_filter, ipv4_proto_filter, dst_mac_filter
    );

    loop {
        let n = unsafe {
            recv(
                rx_fd,
                buf.as_mut_ptr() as *mut c_void,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            let err = io::Error::last_os_error();
            if err.kind() == io::ErrorKind::Interrupted {
                continue;
            }
            return Err(err);
        }

        let n = n as usize;
        if n < ETH_HDR_LEN {
            continue;
        }

        let eth = unsafe { ptr::read_unaligned(buf.as_ptr() as *const EthHdr) };
        let ethertype = u16::from_be(eth.ethertype);

        if let Some(f) = ethertype_filter {
            if ethertype != f {
                continue;
            }
        }

        if let Some(mac) = dst_mac_filter {
            if eth.dst != mac {
                continue;
            }
        }

        if ethertype == 0x0800 && n >= ETH_HDR_LEN + mem::size_of::<Ipv4Hdr>() {
            let ip = unsafe { ptr::read_unaligned(buf[ETH_HDR_LEN..].as_ptr() as *const Ipv4Hdr) };
            if let Some(proto) = ipv4_proto_filter {
                if ip.proto != proto {
                    continue;
                }
            }
        } else if ipv4_proto_filter.is_some() {
            continue;
        }

        let _ = send_packet(tx_fd, egress, &buf[..n])?;
    }
}
