```rust
use libc::{
    bind, close, if_nametoindex, recv, sendto, socket, sockaddr, sockaddr_ll, AF_PACKET,
    ETH_P_ALL, SOCK_RAW,
};
use std::env;
use std::ffi::CString;
use std::io;
use std::mem;
use std::os::unix::io::RawFd;

const ETH_P_IP: u16 = 0x0800;
const IPPROTO_UDP: u8 = 17;

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn open_packet_socket(ifname: &str) -> io::Result<(RawFd, sockaddr_ll)> {
    let c_ifname = CString::new(ifname).unwrap();
    let ifindex = unsafe { if_nametoindex(c_ifname.as_ptr()) };
    if ifindex == 0 {
        return Err(io::Error::last_os_error());
    }

    let fd = unsafe { socket(AF_PACKET, SOCK_RAW, i32::from(htons(ETH_P_ALL))) };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }

    let mut sll: sockaddr_ll = unsafe { mem::zeroed() };
    sll.sll_family = AF_PACKET as u16;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex as i32;

    let ret = unsafe {
        bind(
            fd,
            &sll as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        unsafe { close(fd) };
        return Err(io::Error::last_os_error());
    }

    Ok((fd, sll))
}

fn parse_udp_dst_port(frame: &[u8]) -> Option<u16> {
    if frame.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != ETH_P_IP {
        return None;
    }

    let ip_start = 14;
    if frame.len() < ip_start + 20 {
        return None;
    }

    let version_ihl = frame[ip_start];
    let ihl = ((version_ihl & 0x0f) as usize) * 4;
    if ihl < 20 || frame.len() < ip_start + ihl {
        return None;
    }

    let proto = frame[ip_start + 9];
    if proto != IPPROTO_UDP {
        return None;
    }

    let udp_start = ip_start + ihl;
    if frame.len() < udp_start + 8 {
        return None;
    }

    Some(u16::from_be_bytes([frame[udp_start + 2], frame[udp_start + 3]]))
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <in_if> <out_if>", args[0]);
        std::process::exit(1);
    }

    let in_if = &args[1];
    let out_if = &args[2];

    let (in_fd, _) = open_packet_socket(in_if)?;
    let (out_fd, out_sll) = open_packet_socket(out_if)?;

    let mut buf = [0u8; 2048];

    loop {
        let n = unsafe { recv(in_fd, buf.as_mut_ptr() as *mut _, buf.len(), 0) };
        if n < 0 {
            eprintln!("recv error: {}", io::Error::last_os_error());
            continue;
        }

        let frame = &buf[..n as usize];

        // Minimal filter: forward only UDP packets to port 9000
        if let Some(dst_port) = parse_udp_dst_port(frame) {
            if dst_port == 9000 {
                let sent = unsafe {
                    sendto(
                        out_fd,
                        frame.as_ptr() as *const _,
                        frame.len(),
                        0,
                        &out_sll as *const sockaddr_ll as *const sockaddr,
                        mem::size_of::<sockaddr_ll>() as u32,
                    )
                };

                if sent < 0 {
                    eprintln!("sendto error: {}", io::Error::last_os_error());
                }
            }
        }
    }
}
