use libc::{
    bind, close, if_nametoindex, recv, sendto, socket, sockaddr, sockaddr_ll, AF_PACKET, ETH_P_ALL,
    SOCK_RAW,
};
use std::env;
use std::ffi::CString;
use std::io;
use std::mem::{size_of, zeroed};
use std::os::fd::RawFd;
use std::ptr;

const ETH_HDR_LEN: usize = 14;

fn htons(u: u16) -> u16 {
    u.to_be()
}

fn open_raw_socket() -> io::Result<RawFd> {
    let fd = unsafe { socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL as u16) as i32) };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(fd)
}

fn bind_to_iface(fd: RawFd, iface: &str) -> io::Result<()> {
    let c_iface = CString::new(iface).unwrap();
    let ifindex = unsafe { if_nametoindex(c_iface.as_ptr()) };
    if ifindex == 0 {
        return Err(io::Error::last_os_error());
    }

    let mut addr: sockaddr_ll = unsafe { zeroed() };
    addr.sll_family = AF_PACKET as u16;
    addr.sll_protocol = htons(ETH_P_ALL as u16);
    addr.sll_ifindex = ifindex as i32;

    let ret = unsafe {
        bind(
            fd,
            &addr as *const sockaddr_ll as *const sockaddr,
            size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn should_forward(frame: &[u8]) -> bool {
    // Minimal packet-level filter:
    // - require Ethernet frame
    // - drop broadcast frames
    // - allow only IPv4 frames (0x0800)
    if frame.len() < ETH_HDR_LEN {
        return false;
    }

    let dst = &frame[0..6];
    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);

    let is_broadcast = dst.iter().all(|&b| b == 0xff);
    if is_broadcast {
        return false;
    }

    ethertype == 0x0800
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <input-iface> <output-iface>", args[0]);
        std::process::exit(1);
    }

    let in_iface = &args[1];
    let out_iface = &args[2];

    let rx = open_raw_socket()?;
    let tx = open_raw_socket()?;

    bind_to_iface(rx, in_iface)?;
    bind_to_iface(tx, out_iface)?;

    let mut buf = [0u8; 2048];

    loop {
        let n = unsafe { recv(rx, buf.as_mut_ptr() as *mut _, buf.len(), 0) };
        if n < 0 {
            eprintln!("recv error: {}", io::Error::last_os_error());
            continue;
        }

        let n = n as usize;
        let frame = &buf[..n];

        if !should_forward(frame) {
            continue;
        }

        let sent = unsafe {
            sendto(
                tx,
                frame.as_ptr() as *const _,
                frame.len(),
                0,
                ptr::null(),
                0,
            )
        };

        if sent < 0 {
            eprintln!("sendto error: {}", io::Error::last_os_error());
        }
    }
}
