use libc::{
    bind, close, if_nametoindex, recv, sendto, socket, sockaddr, sockaddr_ll, AF_PACKET, ETH_P_ALL,
    SOCK_RAW,
};
use std::env;
use std::ffi::CString;
use std::io;
use std::mem;
use std::os::unix::io::RawFd;
use std::ptr;

const ETH_P_IP: u16 = 0x0800;
const ETH_HDR_LEN: usize = 14;
const IPV4_MIN_HDR_LEN: usize = 20;

fn htons(v: u16) -> u16 {
    v.to_be()
}

fn open_packet_socket() -> io::Result<RawFd> {
    let fd = unsafe { socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL) as i32) };
    if fd < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(fd)
}

fn bind_to_iface(fd: RawFd, ifname: &str) -> io::Result<()> {
    let c_ifname = CString::new(ifname).unwrap();
    let ifindex = unsafe { if_nametoindex(c_ifname.as_ptr()) };
    if ifindex == 0 {
        return Err(io::Error::last_os_error());
    }

    let mut addr: sockaddr_ll = unsafe { mem::zeroed() };
    addr.sll_family = AF_PACKET as u16;
    addr.sll_protocol = htons(ETH_P_ALL);
    addr.sll_ifindex = ifindex as i32;

    let ret = unsafe {
        bind(
            fd,
            &addr as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };
    if ret < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn send_frame(fd: RawFd, ifname: &str, frame: &[u8]) -> io::Result<()> {
    let c_ifname = CString::new(ifname).unwrap();
    let ifindex = unsafe { if_nametoindex(c_ifname.as_ptr()) };
    if ifindex == 0 {
        return Err(io::Error::last_os_error());
    }

    let mut addr: sockaddr_ll = unsafe { mem::zeroed() };
    addr.sll_family = AF_PACKET as u16;
    addr.sll_protocol = htons(ETH_P_ALL);
    addr.sll_ifindex = ifindex as i32;
    addr.sll_halen = 6;

    let ret = unsafe {
        sendto(
            fd,
            frame.as_ptr() as *const _,
            frame.len(),
            0,
            &addr as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        )
    };

    if ret < 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(())
}

fn parse_ipv4_dst_port(frame: &[u8]) -> Option<u16> {
    if frame.len() < ETH_HDR_LEN + IPV4_MIN_HDR_LEN {
        return None;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != ETH_P_IP {
        return None;
    }

    let ihl = (frame[14] & 0x0f) as usize * 4;
    if ihl < IPV4_MIN_HDR_LEN || frame.len() < ETH_HDR_LEN + ihl + 4 {
        return None;
    }

    let proto = frame[23];
    if proto != 6 && proto != 17 {
        return None;
    }

    let l4_offset = ETH_HDR_LEN + ihl;
    let dst_port = u16::from_be_bytes([frame[l4_offset + 2], frame[l4_offset + 3]]);
    Some(dst_port)
}

fn main() -> io::Result<()> {
    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("Usage: {} <rx_iface> <tx_iface> <dst_port>", args[0]);
        std::process::exit(1);
    }

    let rx_iface = &args[1];
    let tx_iface = &args[2];
    let dst_port: u16 = args[3].parse().expect("invalid port");

    let rx_fd = open_packet_socket()?;
    let tx_fd = open_packet_socket()?;

    bind_to_iface(rx_fd, rx_iface)?;

    let mut buf = vec![0u8; 2048];

    loop {
        let n = unsafe { recv(rx_fd, buf.as_mut_ptr() as *mut _, buf.len(), 0) };
        if n < 0 {
            return Err(io::Error::last_os_error());
        }
        let n = n as usize;
        let frame = &buf[..n];

        if let Some(port) = parse_ipv4_dst_port(frame) {
            if port == dst_port {
                send_frame(tx_fd, tx_iface, frame)?;
            }
        }
    }

    #[allow(unreachable_code)]
    {
        unsafe {
            close(rx_fd);
            close(tx_fd);
        }
        Ok(())
    }
}
