### `pktfw.c`
```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if.h>
#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <net/if_arp.h>
#include <net/if.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

static volatile sig_atomic_t running = 1;

static void on_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int get_ifindex(int sock, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);
    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) return -1;
    return ifr.ifr_ifindex;
}

static int get_hwaddr(int sock, const char *ifname, unsigned char mac[6]) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);
    if (ioctl(sock, SIOCGIFHWADDR, &ifr) < 0) return -1;
    memcpy(mac, ifr.ifr_hwaddr.sa_data, 6);
    return 0;
}

static int is_allowed(const unsigned char *pkt, ssize_t len) {
    if (len < (ssize_t)(sizeof(struct ethhdr) + sizeof(struct iphdr)))
        return 0;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP)
        return 1; // allow non-IPv4 in this minimal example

    const struct iphdr *ip = (const struct iphdr *)(pkt + sizeof(struct ethhdr));

    // Example filter:
    // Drop TCP traffic to port 22, allow everything else.
    if (ip->protocol == IPPROTO_TCP) {
        size_t iphdr_len = ip->ihl * 4;
        if (len < (ssize_t)(sizeof(struct ethhdr) + iphdr_len + sizeof(struct tcphdr)))
            return 0;

        const struct tcphdr *tcp = (const struct tcphdr *)(pkt + sizeof(struct ethhdr) + iphdr_len);
        if (ntohs(tcp->dest) == 22)
            return 0;
    }

    return 1;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <in_if> <out_if>\n", argv[0]);
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];

    signal(SIGINT, on_sigint);
    signal(SIGTERM, on_sigint);

    int rx = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (rx < 0) {
        perror("socket(rx)");
        return 1;
    }

    int tx = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (tx < 0) {
        perror("socket(tx)");
        close(rx);
        return 1;
    }

    int in_idx = get_ifindex(rx, in_if);
    int out_idx = get_ifindex(tx, out_if);
    if (in_idx < 0 || out_idx < 0) {
        perror("get_ifindex");
        close(rx);
        close(tx);
        return 1;
    }

    unsigned char out_mac[6];
    if (get_hwaddr(tx, out_if, out_mac) < 0) {
        perror("get_hwaddr");
        close(rx);
        close(tx);
        return 1;
    }

    struct sockaddr_ll sll_rx;
    memset(&sll_rx, 0, sizeof(sll_rx));
    sll_rx.sll_family = AF_PACKET;
    sll_rx.sll_protocol = htons(ETH_P_ALL);
    sll_rx.sll_ifindex = in_idx;

    if (bind(rx, (struct sockaddr *)&sll_rx, sizeof(sll_rx)) < 0) {
        perror("bind(rx)");
        close(rx);
        close(tx);
        return 1;
    }

    struct sockaddr_ll sll_tx;
    memset(&sll_tx, 0, sizeof(sll_tx));
    sll_tx.sll_family = AF_PACKET;
    sll_tx.sll_protocol = htons(ETH_P_ALL);
    sll_tx.sll_ifindex = out_idx;

    unsigned char buf[2048];

    while (running) {
        ssize_t n = recv(rx, buf, sizeof(buf), 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            break;
        }

        if (!is_allowed(buf, n))
            continue;

        if (n >= (ssize_t)sizeof(struct ethhdr)) {
            struct ethhdr *eth = (struct ethhdr *)buf;

            // Rewrite L2 for outgoing interface
            memcpy(eth->h_source, out_mac, 6);

            // In a real router, you'd resolve next-hop MAC.
            // For a minimal lab forwarder, send to the interface's own MAC.
            memcpy(eth->h_dest, out_mac, 6);
        }

        ssize_t sent = sendto(tx, buf, n, 0, (struct sockaddr *)&sll_tx, sizeof(sll_tx));
        if (sent < 0) {
            perror("sendto");
        }
    }

    close(rx);
    close(tx);
    return 0;
}
```

