use libc::*;
use std::ffi::CString;
use std::io;
use std::mem;
use std::os::fd::RawFd;
use std::ptr;

const ETH_P_ALL: u16 = 0x0003;
const BUFFER_SIZE: usize = 2048;

fn htons(u: u16) -> u16 {
    u.to_be()
}

fn open_raw_socket(iface: &str) -> io::Result<RawFd> {
    unsafe {
        let fd = socket(AF_PACKET, SOCK_RAW, i32::from(htons(ETH_P_ALL)));
        if fd < 0 {
            return Err(io::Error::last_os_error());
        }

        let ifname = CString::new(iface).unwrap();
        let ifindex = if_nametoindex(ifname.as_ptr());
        if ifindex == 0 {
            close(fd);
            return Err(io::Error::last_os_error());
        }

        let mut sll: sockaddr_ll = mem::zeroed();
        sll.sll_family = AF_PACKET as u16;
        sll.sll_protocol = htons(ETH_P_ALL);
        sll.sll_ifindex = ifindex as i32;

        let ret = bind(
            fd,
            &sll as *const sockaddr_ll as *const sockaddr,
            mem::size_of::<sockaddr_ll>() as u32,
        );
        if ret < 0 {
            close(fd);
            return Err(io::Error::last_os_error());
        }

        // Enable promiscuous mode
        let mut mreq: packet_mreq = mem::zeroed();
        mreq.mr_ifindex = ifindex as i32;
        mreq.mr_type = PACKET_MR_PROMISC as u16;

        let ret = setsockopt(
            fd,
            SOL_PACKET,
            PACKET_ADD_MEMBERSHIP,
            &mreq as *const packet_mreq as *const _,
            mem::size_of::<packet_mreq>() as u32,
        );
        if ret < 0 {
            close(fd);
            return Err(io::Error::last_os_error());
        }

        Ok(fd)
    }
}

fn packet_filter(frame: &[u8]) -> bool {
    // Minimal filter:
    // - must be Ethernet
    // - allow only IPv4 packets
    // - optionally drop broadcast frames
    if frame.len() < 14 {
        return false;
    }

    let ethertype = u16::from_be_bytes([frame[12], frame[13]]);
    if ethertype != 0x0800 {
        return false;
    }

    // Example: drop broadcast destination MAC
    let dst = &frame[0..6];
    if dst == [0xff; 6] {
        return false;
    }

    true
}

fn forward_loop(rx_fd: RawFd, tx_fd: RawFd) -> io::Result<()> {
    let mut buf = [0u8; BUFFER_SIZE];

    loop {
        let n = unsafe {
            recv(
                rx_fd,
                buf.as_mut_ptr() as *mut _,
                buf.len(),
                0,
            )
        };

        if n < 0 {
            return Err(io::Error::last_os_error());
        }

        let n = n as usize;
        let frame = &buf[..n];

        if !packet_filter(frame) {
            continue;
        }

        let sent = unsafe {
            send(
                tx_fd,
                frame.as_ptr() as *const _,
                frame.len(),
                0,
            )
        };

        if sent < 0 {
            return Err(io::Error::last_os_error());
        }
    }
}

fn main() -> io::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <rx_iface> <tx_iface>", args[0]);
        std::process::exit(1);
    }

    let rx_iface = &args[1];
    let tx_iface = &args[2];

    let rx_fd = open_raw_socket(rx_iface)?;
    let tx_fd = open_raw_socket(tx_iface)?;

    println!("Forwarding from {} -> {}", rx_iface, tx_iface);
    forward_loop(rx_fd, tx_fd)
}
