## Code: `fast_forward.c`

```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#ifndef ETH_P_ALL
#define ETH_P_ALL 0x0003
#endif

typedef struct {
    int out_sock;
    int ifindex;
    unsigned short allow_dport; // 0 = allow all
} ctx_t;

static int get_ifindex(int sock, const char *ifname) {
    struct ifreq ifr;
    memset(&ifr, 0, sizeof(ifr));
    strncpy(ifr.ifr_name, ifname, IFNAMSIZ - 1);
    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) return -1;
    return ifr.ifr_ifindex;
}

static int bind_promisc_pcap(pcap_t **handle, const char *ifname, char *errbuf) {
    *handle = pcap_open_live(ifname, 65535, 1, 1, errbuf); // 1 ms timeout
    if (!*handle) return -1;

    // Capture only IPv4 packets; keep it simple.
    struct bpf_program fp;
    if (pcap_compile(*handle, &fp, "ip", 1, PCAP_NETMASK_UNKNOWN) < 0) {
        snprintf(errbuf, PCAP_ERRBUF_SIZE, "pcap_compile failed: %s", pcap_geterr(*handle));
        pcap_close(*handle);
        return -1;
    }
    if (pcap_setfilter(*handle, &fp) < 0) {
        snprintf(errbuf, PCAP_ERRBUF_SIZE, "pcap_setfilter failed: %s", pcap_geterr(*handle));
        pcap_freecode(&fp);
        pcap_close(*handle);
        return -1;
    }
    pcap_freecode(&fp);
    return 0;
}

static int should_forward(const unsigned char *pkt, size_t len, unsigned short allow_dport) {
    if (len < sizeof(struct ether_header) + sizeof(struct ip)) return 0;

    const struct ether_header *eth = (const struct ether_header *)pkt;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return 0;

    const struct ip *iph = (const struct ip *)(pkt + sizeof(struct ether_header));
    size_t ip_hlen = iph->ip_hl * 4;
    if (ip_hlen < sizeof(struct ip)) return 0;
    if (len < sizeof(struct ether_header) + ip_hlen) return 0;

    if (allow_dport == 0) return 1;

    if (iph->ip_p == IPPROTO_TCP) {
        if (len < sizeof(struct ether_header) + ip_hlen + sizeof(struct tcphdr)) return 0;
        const struct tcphdr *th = (const struct tcphdr *)(pkt + sizeof(struct ether_header) + ip_hlen);
        return ntohs(th->th_dport) == allow_dport;
    } else if (iph->ip_p == IPPROTO_UDP) {
        if (len < sizeof(struct ether_header) + ip_hlen + sizeof(struct udphdr)) return 0;
        const struct udphdr *uh = (const struct udphdr *)(pkt + sizeof(struct ether_header) + ip_hlen);
        return ntohs(uh->uh_dport) == allow_dport;
    }

    return 0;
}

static int forward_packet(ctx_t *ctx, const unsigned char *pkt, size_t len) {
    struct sockaddr_ll addr;
    memset(&addr, 0, sizeof(addr));
    addr.sll_family   = AF_PACKET;
    addr.sll_ifindex  = ctx->ifindex;
    addr.sll_halen    = ETH_ALEN;

    // Broadcast MAC as a minimal placeholder.
    // For real forwarding, you would resolve the next-hop MAC via ARP.
    memset(addr.sll_addr, 0xff, ETH_ALEN);

    ssize_t sent = sendto(ctx->out_sock, pkt, len, 0, (struct sockaddr *)&addr, sizeof(addr));
    return (sent == (ssize_t)len) ? 0 : -1;
}

static void on_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    ctx_t *ctx = (ctx_t *)user;
    if (!should_forward(bytes, h->caplen, ctx->allow_dport)) return;

    if (forward_packet(ctx, bytes, h->caplen) < 0) {
        perror("sendto");
    }
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <in_if> <out_if> [allow_dport]\n", argv[0]);
        fprintf(stderr, "  allow_dport=0 means allow all IPv4 TCP/UDP packets\n");
        return 1;
    }

    const char *in_if = argv[1];
    const char *out_if = argv[2];
    unsigned short allow_dport = 0;
    if (argc >= 4) allow_dport = (unsigned short)atoi(argv[3]);

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = NULL;
    if (bind_promisc_pcap(&handle, in_if, errbuf) < 0) {
        fprintf(stderr, "pcap init failed: %s\n", errbuf);
        return 1;
    }

    int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("socket(AF_PACKET)");
        pcap_close(handle);
        return 1;
    }

    int ifindex = get_ifindex(sock, out_if);
    if (ifindex < 0) {
        perror("get_ifindex");
        close(sock);
        pcap_close(handle);
        return 1;
    }

    ctx_t ctx = {
        .out_sock = sock,
        .ifindex = ifindex,
        .allow_dport = allow_dport
    };

    fprintf(stderr, "Forwarding from %s -> %s, allow_dport=%u\n", in_if, out_if, allow_dport);
    fprintf(stderr, "Note: this minimal example uses broadcast MAC and is for lab use only.\n");

    if (pcap_loop(handle, -1, on_packet, (u_char *)&ctx) < 0) {
        fprintf(stderr, "pcap_loop error: %s\n", pcap_geterr(handle));
    }

    close(sock);
    pcap_close(handle);
    return 0;
}
```

