Below is a compact, memory-conscious **Python** log rotation daemon that:

- watches one or more log files,
- rotates them by size,
- compresses rotated logs optionally,
- avoids loading file contents into memory,
- uses a small, fixed-size buffer for copying,
- keeps state minimal.

It is designed to be simple and conservative with memory use.

```python
#!/usr/bin/env python3
import os
import time
import gzip
import shutil
import signal
from dataclasses import dataclass
from typing import List, Optional

@dataclass
class LogTarget:
    path: str
    max_bytes: int
    keep: int = 5
    compress: bool = False


class LogRotator:
    def __init__(self, targets: List[LogTarget], poll_interval: float = 1.0, buffer_size: int = 64 * 1024):
        self.targets = targets
        self.poll_interval = poll_interval
        self.buffer_size = buffer_size
        self.running = True

    def stop(self, *_):
        self.running = False

    def _file_size(self, path: str) -> int:
        try:
            return os.stat(path).st_size
        except FileNotFoundError:
            return 0

    def _rotate_one(self, target: LogTarget):
        path = target.path

        # Remove oldest
        oldest = f"{path}.{target.keep}"
        if target.compress:
            oldest += ".gz"
        if os.path.exists(oldest):
            try:
                os.remove(oldest)
            except OSError:
                pass

        # Shift existing rotations
        for i in range(target.keep - 1, 0, -1):
            src = f"{path}.{i}"
            dst = f"{path}.{i + 1}"
            if target.compress:
                src += ".gz"
                dst += ".gz"
            if os.path.exists(src):
                try:
                    os.rename(src, dst)
                except OSError:
                    pass

        # Rotate current log to .1
        rotated = f"{path}.1"
        try:
            os.rename(path, rotated)
        except FileNotFoundError:
            return
        except OSError:
            return

        # Recreate empty log file
        try:
            open(path, "a").close()
        except OSError:
            return

        # Compress if requested
        if target.compress:
            self._compress_file(rotated)

    def _compress_file(self, src_path: str):
        dst_path = src_path + ".gz"
        tmp_path = dst_path + ".tmp"

        try:
            with open(src_path, "rb") as src, gzip.open(tmp_path, "wb", compresslevel=6) as dst:
                while True:
                    chunk = src.read(self.buffer_size)
                    if not chunk:
                        break
                    dst.write(chunk)
            os.replace(tmp_path, dst_path)
            os.remove(src_path)
        except OSError:
            try:
                if os.path.exists(tmp_path):
                    os.remove(tmp_path)
            except OSError:
                pass

    def run(self):
        signal.signal(signal.SIGINT, self.stop)
        signal.signal(signal.SIGTERM, self.stop)

        while self.running:
            for target in self.targets:
                if self._file_size(target.path) >= target.max_bytes:
                    self._rotate_one(target)
            time.sleep(self.poll_interval)


if __name__ == "__main__":
    targets = [
        LogTarget(path="/var/log/myapp.log", max_bytes=10 * 1024 * 1024, keep=5, compress=True),
        LogTarget(path="/var/log/worker.log", max_bytes=5 * 1024 * 1024, keep=3, compress=False),
    ]

    rotator = LogRotator(targets, poll_interval=2.0, buffer_size=32 * 1024)
    rotator.run()
```

### Notes on memory constraints
- Uses a fixed copy buffer (`buffer_size`) instead of reading whole files.
- Keeps only a small amount of metadata in memory.
- Does not store log contents in RAM.
- Compression is streamed.

### Caveats
- This is a polling-based daemon, not event-driven.
- It rotates by **size only**.
- It does not handle concurrent writers with full log-safety guarantees.
- For production use, you may want:
  - file locking,
  - inode tracking,
  - atomic reopen signaling to the logging process,
  - better error handling and structured logging.

