## `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef PATH_MAX
#define PATH_MAX 4096
#endif

#define MAX_PATH_LEN   PATH_MAX
#define MAX_LINE_LEN    512
#define MAX_ROTATIONS   5
#define POLL_INTERVAL_S  1

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static void log_stderr(const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) {
        errno = ENAMETOOLONG;
        return -1;
    }
    return 0;
}

static int file_size_fd(int fd, off_t *out_size) {
    struct stat st;
    if (fstat(fd, &st) != 0) return -1;
    *out_size = st.st_size;
    return 0;
}

static int rotate_files(const char *base_path, int max_rotations) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    for (int i = max_rotations - 1; i >= 1; --i) {
        if (safe_snprintf(old_path, sizeof(old_path), "%s.%d", base_path, i) != 0)
            return -1;
        if (safe_snprintf(new_path, sizeof(new_path), "%s.%d", base_path, i + 1) != 0)
            return -1;

        if (access(old_path, F_OK) == 0) {
            if (rename(old_path, new_path) != 0) {
                return -1;
            }
        }
    }

    if (safe_snprintf(new_path, sizeof(new_path), "%s.1", base_path) != 0)
        return -1;

    if (access(base_path, F_OK) == 0) {
        if (rename(base_path, new_path) != 0) {
            return -1;
        }
    }

    return 0;
}

static int reopen_log(const char *path, int *fd_out) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) return -1;
    *fd_out = fd;
    return 0;
}

static int daemonize(void) {
    pid_t pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (setsid() < 0) return -1;

    pid = fork();
    if (pid < 0) return -1;
    if (pid > 0) _exit(0);

    if (chdir("/") != 0) return -1;

    int nullfd = open("/dev/null", O_RDWR);
    if (nullfd < 0) return -1;

    dup2(nullfd, STDIN_FILENO);
    dup2(nullfd, STDOUT_FILENO);
    dup2(nullfd, STDERR_FILENO);

    if (nullfd > STDERR_FILENO) close(nullfd);
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s [-d] [-s size_bytes] [-n rotations] logfile\n"
        "  -d            daemonize\n"
        "  -s size_bytes  rotate when file exceeds this size (default 1048576)\n"
        "  -n rotations   number of rotated files to keep (default 5, max 5)\n",
        prog);
}

int main(int argc, char **argv) {
    bool do_daemon = false;
    off_t rotate_size = 1024 * 1024;
    int max_rotations = MAX_ROTATIONS;

    int opt;
    while ((opt = getopt(argc, argv, "ds:n:")) != -1) {
        switch (opt) {
            case 'd':
                do_daemon = true;
                break;
            case 's':
                rotate_size = (off_t)strtoll(optarg, NULL, 10);
                if (rotate_size <= 0) {
                    usage(argv[0]);
                    return 1;
                }
                break;
            case 'n':
                max_rotations = atoi(optarg);
                if (max_rotations < 1 || max_rotations > MAX_ROTATIONS) {
                    fprintf(stderr, "rotations must be between 1 and %d\n", MAX_ROTATIONS);
                    return 1;
                }
                break;
            default:
                usage(argv[0]);
                return 1;
        }
    }

    if (optind >= argc) {
        usage(argv[0]);
        return 1;
    }

    const char *log_path = argv[optind];
    if (strlen(log_path) >= MAX_PATH_LEN) {
        fprintf(stderr, "log path too long\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (do_daemon) {
        if (daemonize() != 0) {
            perror("daemonize");
            return 1;
        }
    }

    int fd = -1;
    if (reopen_log(log_path, &fd) != 0) {
        perror("open log");
        return 1;
    }

    char line[MAX_LINE_LEN];

    while (!g_stop) {
        off_t sz = 0;
        if (file_size_fd(fd, &sz) != 0) {
            perror("fstat");
            break;
        }

        if (sz >= rotate_size) {
            close(fd);
            fd = -1;

            if (rotate_files(log_path, max_rotations) != 0) {
                perror("rotate");
                break;
            }

            if (reopen_log(log_path, &fd) != 0) {
                perror("reopen");
                break;
            }
        }

        ssize_t n = read(STDIN_FILENO, line, sizeof(line));
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("read");
            break;
        }
        if (n == 0) {
            struct timespec ts = { .tv_sec = POLL_INTERVAL_S, .tv_nsec = 0 };
            nanosleep(&ts, NULL);
            continue;
        }

        ssize_t off = 0;
        while (off < n) {
            ssize_t w = write(fd, line + off, (size_t)(n - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                perror("write");
                g_stop = 1;
                break;
            }
            off += w;
        }
    }

    if (fd >= 0) close(fd);
    return 0;
}
