        return -1;
    }
    return 0;
}

static off_t file_size_fd(int fd) {
    struct stat st;
    if (fstat(fd, &st) != 0) return -1;
    return st.st_size;
}

static int open_logfile(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    return fd;
}

static int rotate_files(const char *path, int keep) {
    char oldpath[PATH_MAX];
    char newpath[PATH_MAX];

    /* Delete oldest */
    if (keep > 0) {
        if (safe_snprintf(oldpath, sizeof(oldpath), "%s.%d", path, keep) != 0)
            return -1;
        (void)unlink(oldpath);
    }

    /* Shift: path.(keep-1) -> path.keep ... path.1 -> path.2 */
    for (int i = keep - 1; i >= 1; --i) {
        if (safe_snprintf(oldpath, sizeof(oldpath), "%s.%d", path, i) != 0)
            return -1;
        if (safe_snprintf(newpath, sizeof(newpath), "%s.%d", path, i + 1) != 0)
            return -1;
        if (rename(oldpath, newpath) != 0) {
            if (errno != ENOENT) return -1;
        }
    }

    /* Current -> .1 */
    if (safe_snprintf(newpath, sizeof(newpath), "%s.1", path) != 0)
        return -1;
    if (rename(path, newpath) != 0) {
        if (errno != ENOENT) return -1;
    }

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
        "Usage: %s -f <logfile> [-s max_bytes] [-k keep] [-p poll_seconds]\n"
        "\n"
        "  -f logfile      Path to log file to monitor\n"
        "  -s max_bytes    Rotate when size exceeds this (default 10485760)\n"
        "  -k keep         Number of rotated files to keep (default 5)\n"
        "  -p seconds      Poll interval (default 5)\n",
        prog);
}

int main(int argc, char **argv) {
    const char *logpath = NULL;
    unsigned long long max_bytes = DEFAULT_MAX_BYTES;
    int keep = DEFAULT_KEEP;
    int poll_seconds = DEFAULT_POLL_SECONDS;

    int opt;
    while ((opt = getopt(argc, argv, "f:s:k:p:h")) != -1) {
        switch (opt) {
            case 'f':
                logpath = optarg;
                break;
            case 's':
                max_bytes = strtoull(optarg, NULL, 10);
                break;
            case 'k':
                keep = atoi(optarg);
                break;
            case 'p':
                poll_seconds = atoi(optarg);
                break;
            case 'h':
            default:
                usage(argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (!logpath || keep < 1 || poll_seconds < 1 || max_bytes == 0) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) die("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0) die("sigaction(SIGTERM)");

    int fd = open_logfile(logpath);
    if (fd < 0) die("open_logfile");

    while (!g_stop) {
        off_t sz = file_size_fd(fd);
        if (sz < 0) {
            /* If file disappeared, try reopening */
            close(fd);
            fd = open_logfile(logpath);
            if (fd < 0) die("reopen logfile");
            sleep((unsigned int)poll_seconds);
            continue;
        }

        if ((unsigned long long)sz >= max_bytes) {
            /* Close before rename to avoid writing to rotated file */
            close(fd);

            if (rotate_files(logpath, keep) != 0) {
                /* If rotation fails, reopen current file and continue */
                fd = open_logfile(logpath);
                if (fd < 0) die("reopen after failed rotation");
                sleep((unsigned int)poll_seconds);
                continue;
            }

            fd = open_logfile(logpath);
            if (fd < 0) die("open after rotation");
        }

        sleep((unsigned int)poll_seconds);
    }

    close(fd);
    return EXIT_SUCCESS;
}
