## Code

```python
#!/usr/bin/env python3
import os
import time
import gzip
import shutil
import signal
import argparse
from pathlib import Path

STOP = False


def handle_signal(signum, frame):
    global STOP
    STOP = True


def file_size(path: Path) -> int:
    try:
        return path.stat().st_size
    except FileNotFoundError:
        return 0


def should_rotate(path: Path, max_bytes: int, interval_sec: int, last_rotate_ts: float) -> bool:
    if not path.exists():
        return False
    if max_bytes > 0 and file_size(path) >= max_bytes:
        return True
    if interval_sec > 0 and (time.time() - last_rotate_ts) >= interval_sec:
        return True
    return False


def rotate_file(path: Path, keep: int, compress: bool) -> None:
    if not path.exists():
        return

    base = str(path)

    # Shift old files: logfile.4 -> logfile.5, etc.
    for i in range(keep - 1, 0, -1):
        src = Path(f"{base}.{i}")
        if compress:
            src_gz = Path(f"{base}.{i}.gz")
            if src_gz.exists():
                dst_gz = Path(f"{base}.{i+1}.gz")
                try:
                    os.replace(src_gz, dst_gz)
                except OSError:
                    pass
            elif src.exists():
                dst = Path(f"{base}.{i+1}")
                try:
                    os.replace(src, dst)
                except OSError:
                    pass
        else:
            if src.exists():
                dst = Path(f"{base}.{i+1}")
                try:
                    os.replace(src, dst)
                except OSError:
                    pass

    rotated = Path(f"{base}.1")
    try:
        os.replace(path, rotated)
    except OSError:
        return

    if compress:
        gz_path = Path(f"{base}.1.gz")
        try:
            with open(rotated, "rb") as f_in, gzip.open(gz_path, "wb", compresslevel=6) as f_out:
                shutil.copyfileobj(f_in, f_out, length=64 * 1024)
            rotated.unlink(missing_ok=True)
        except OSError:
            pass

    # Remove excess old logs
    excess = Path(f"{base}.{keep + 1}")
    if compress:
        excess_gz = Path(f"{base}.{keep + 1}.gz")
        if excess_gz.exists():
            try:
                excess_gz.unlink()
            except OSError:
                pass
    else:
        if excess.exists():
            try:
                excess.unlink()
            except OSError:
                pass


def reopen_log(path: Path):
    # Reopen by returning a new file handle; caller should use this after rotation.
    return open(path, "a", buffering=1)


def daemon_loop(log_path: Path, max_bytes: int, interval_sec: int, keep: int, compress: bool, poll_sec: float):
    last_rotate_ts = time.time()
    current_inode = None
    log_fh = None

    def open_if_needed():
        nonlocal log_fh, current_inode
        if log_fh is None:
            log_fh = reopen_log(log_path)
            try:
                current_inode = os.fstat(log_fh.fileno()).st_ino
            except OSError:
                current_inode = None

    open_if_needed()

    while not STOP:
        try:
            # Detect external rotation/truncation
            try:
                st = log_path.stat()
                if current_inode is not None and st.st_ino != current_inode:
                    log_fh.close()
                    log_fh = reopen_log(log_path)
                    current_inode = os.fstat(log_fh.fileno()).st_ino
            except FileNotFoundError:
                # Recreate if missing
                if log_fh:
                    log_fh.close()
                log_fh = reopen_log(log_path)
                current_inode = os.fstat(log_fh.fileno()).st_ino

            if should_rotate(log_path, max_bytes, interval_sec, last_rotate_ts):
                if log_fh:
                    log_fh.close()
                    log_fh = None
                rotate_file(log_path, keep=keep, compress=compress)
                log_fh = reopen_log(log_path)
                current_inode = os.fstat(log_fh.fileno()).st_ino
                last_rotate_ts = time.time()

            # Example daemon action: append a heartbeat line
            # Replace this with your actual logging source.
            log_fh.write(f"{time.strftime('%Y-%m-%d %H:%M:%S')} heartbeat\n")
            log_fh.flush()

        except (OSError, IOError):
            # Keep daemon alive on transient errors
            pass

        time.sleep(poll_sec)

    if log_fh:
        try:
            log_fh.close()
        except OSError:
            pass


def main():
    parser = argparse.ArgumentParser(description="Memory-constrained log rotation daemon")
    parser.add_argument("--log-file", required=True, help="Path to log file")
    parser.add_argument("--max-bytes", type=int, default=10 * 1024 * 1024, help="Rotate after this many bytes")
    parser.add_argument("--interval-sec", type=int, default=0, help="Rotate after this many seconds (0 disables)")
    parser.add_argument("--keep", type=int, default=5, help="Number of rotated logs to keep")
    parser.add_argument("--compress", action="store_true", help="Compress rotated logs with gzip")
    parser.add_argument("--poll-sec", type=float, default=1.0, help="Polling interval")
    args = parser.parse_args()

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    log_path = Path(args.log_file)
    log_path.parent.mkdir(parents=True, exist_ok=True)

    daemon_loop(
        log_path=log_path,
        max_bytes=args.max_bytes,
        interval_sec=args.interval_sec,
        keep=args.keep,
        compress=args.compress,
        poll_sec=args.poll_sec,
    )


if __name__ == "__main__":
    main()
```

