## 1) Minimal C log rotation daemon

### Features
- Watches one file
- Checks size periodically
- Rotates when size exceeds limit
- Keeps a fixed number of backups
- Uses fixed-size buffers only
- No dynamic allocation in the hot path

### `logrotate_daemon.c`
```c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define MAX_PATH 512
#define BUF_SIZE  4096

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static int rename_if_exists(const char *oldp, const char *newp) {
    if (!file_exists(oldp)) return 0;
    if (rename(oldp, newp) != 0) {
        fprintf(stderr, "rename(%s -> %s) failed: %s\n", oldp, newp, strerror(errno));
        return -1;
    }
    return 0;
}

static int rotate_logs(const char *logfile, int keep) {
    char src[MAX_PATH];
    char dst[MAX_PATH];

    // Delete oldest
    snprintf(src, sizeof(src), "%s.%d", logfile, keep);
    unlink(src);

    // Shift backups: logfile.(n-1) -> logfile.n
    for (int i = keep - 1; i >= 1; --i) {
        snprintf(src, sizeof(src), "%s.%d", logfile, i);
        snprintf(dst, sizeof(dst), "%s.%d", logfile, i + 1);
        if (rename_if_exists(src, dst) != 0) return -1;
    }

    // Current logfile -> logfile.1
    snprintf(dst, sizeof(dst), "%s.1", logfile);
    if (rename_if_exists(logfile, dst) != 0) return -1;

    // Recreate empty logfile
    int fd = open(logfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", logfile, strerror(errno));
        return -1;
    }
    close(fd);

    return 0;
}

static off_t get_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

int main(int argc, char **argv) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <logfile> <max_bytes> <keep_backups> [interval_sec]\n", argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    off_t max_bytes = (off_t)atoll(argv[2]);
    int keep = atoi(argv[3]);
    int interval = (argc >= 5) ? atoi(argv[4]) : 5;

    if (max_bytes <= 0 || keep < 1 || interval < 1) {
        fprintf(stderr, "Invalid arguments\n");
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Ensure logfile exists
    int fd = open(logfile, O_WRONLY | O_CREAT, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", logfile, strerror(errno));
        return 1;
    }
    close(fd);

    while (running) {
        off_t sz = get_size(logfile);
        if (sz < 0) {
            fprintf(stderr, "stat(%s) failed: %s\n", logfile, strerror(errno));
        } else if (sz >= max_bytes) {
            if (rotate_logs(logfile, keep) != 0) {
                fprintf(stderr, "rotation failed\n");
            }
        }

        sleep(interval);
    }

    return 0;
}
