## C implementation

```c
// logrotate_min.c
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>

#define COPY_BUF_SIZE 4096
#define POLL_INTERVAL_SEC 1

typedef struct {
    const char *path;
    off_t max_size;
    int keep;
} Config;

static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int copy_file_streaming(const char *src, const char *dst) {
    int in_fd = -1, out_fd = -1;
    char buf[COPY_BUF_SIZE];
    ssize_t r;

    in_fd = open(src, O_RDONLY);
    if (in_fd < 0) return -1;

    out_fd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (out_fd < 0) {
        close(in_fd);
        return -1;
    }

    while ((r = read(in_fd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(out_fd, buf + off, (size_t)(r - off));
            if (w < 0) {
                if (errno == EINTR) continue;
                close(in_fd);
                close(out_fd);
                return -1;
            }
            off += w;
        }
    }

    close(in_fd);
    close(out_fd);
    return (r < 0) ? -1 : 0;
}

static int rotate_logs(const Config *cfg) {
    char old_name[512];
    char new_name[512];

    // Delete oldest
    snprintf(old_name, sizeof(old_name), "%s.%d", cfg->path, cfg->keep);
    unlink(old_name);

    // Shift existing archives
    for (int i = cfg->keep - 1; i >= 1; --i) {
        snprintf(old_name, sizeof(old_name), "%s.%d", cfg->path, i);
        snprintf(new_name, sizeof(new_name), "%s.%d", cfg->path, i + 1);
        if (file_exists(old_name)) {
            rename(old_name, new_name);
        }
    }

    // Move current log to .1
    snprintf(new_name, sizeof(new_name), "%s.1", cfg->path);
    if (file_exists(cfg->path)) {
        if (rename(cfg->path, new_name) != 0) {
            return -1;
        }
    }

    // Recreate empty log file
    int fd = open(cfg->path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr, "Usage: %s <logfile> <max_size_bytes> <keep>\n", prog);
}

int main(int argc, char **argv) {
    if (argc != 4) {
        usage(argv[0]);
        return 1;
    }

    Config cfg;
    cfg.path = argv[1];
    cfg.max_size = (off_t)atoll(argv[2]);
    cfg.keep = atoi(argv[3]);

    if (cfg.max_size <= 0 || cfg.keep < 1) {
        fprintf(stderr, "Invalid arguments\n");
        return 1;
    }

    while (1) {
        off_t sz = file_size(cfg.path);
        if (sz < 0) {
            // If file doesn't exist yet, create it
            int fd = open(cfg.path, O_WRONLY | O_CREAT, 0644);
            if (fd >= 0) close(fd);
        } else if (sz >= cfg.max_size) {
            if (rotate_logs(&cfg) != 0) {
                fprintf(stderr, "Rotation failed: %s\n", strerror(errno));
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    return 0;
}
