## Minimal implementation: `logd.c`

```c
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/resource.h>
#include <string.h>
#include <errno.h>
#include <time.h>

#define BUF_SIZE 4096
#define POLL_INTERVAL_SEC 1

static const char *log_path = "/tmp/app.log";
static const char *base_name = "/tmp/app.log";
static size_t max_size = 1024 * 1024;   // 1 MiB
static int max_backups = 3;

static int set_memory_limit(size_t bytes) {
    struct rlimit rl;
    rl.rlim_cur = bytes;
    rl.rlim_max = bytes;
    return setrlimit(RLIMIT_AS, &rl);
}

static off_t file_size(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    return st.st_size;
}

static int safe_rename(const char *oldp, const char *newp) {
    if (rename(oldp, newp) != 0) {
        return -1;
    }
    return 0;
}

static int rotate_logs(void) {
    char oldname[512];
    char newname[512];

    // Shift backups: .2 -> .3, .1 -> .2, etc.
    for (int i = max_backups - 1; i >= 1; --i) {
        snprintf(oldname, sizeof(oldname), "%s.%d", base_name, i);
        snprintf(newname, sizeof(newname), "%s.%d", base_name, i + 1);
        unlink(newname); // ignore errors
        if (access(oldname, F_OK) == 0) {
            if (rename(oldname, newname) != 0) {
                fprintf(stderr, "rename(%s -> %s) failed: %s\n",
                        oldname, newname, strerror(errno));
                return -1;
            }
        }
    }

    // Current log -> .1
    snprintf(newname, sizeof(newname), "%s.1", base_name);
    unlink(newname); // ignore errors
    if (rename(base_name, newname) != 0) {
        fprintf(stderr, "rename(%s -> %s) failed: %s\n",
                base_name, newname, strerror(errno));
        return -1;
    }

    return 0;
}

static int reopen_log(int *fd) {
    int newfd = open(log_path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (newfd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", log_path, strerror(errno));
        return -1;
    }

    if (*fd >= 0) close(*fd);
    *fd = newfd;
    return 0;
}

static int copy_file(const char *src, const char *dst) {
    int sfd = open(src, O_RDONLY);
    if (sfd < 0) return -1;

    int dfd = open(dst, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (dfd < 0) {
        close(sfd);
        return -1;
    }

    char buf[BUF_SIZE];
    ssize_t r;
    while ((r = read(sfd, buf, sizeof(buf))) > 0) {
        ssize_t off = 0;
        while (off < r) {
            ssize_t w = write(dfd, buf + off, (size_t)(r - off));
            if (w < 0) {
                close(sfd);
                close(dfd);
                return -1;
            }
            off += w;
        }
    }

    close(sfd);
    close(dfd);
    return (r < 0) ? -1 : 0;
}

int main(int argc, char **argv) {
    if (argc > 1) log_path = argv[1];
    base_name = log_path;

    if (argc > 2) max_size = (size_t)strtoull(argv[2], NULL, 10);
    if (argc > 3) max_backups = atoi(argv[3]);
    if (max_backups < 1) max_backups = 1;

    // Strict memory limit: 8 MiB address space
    if (set_memory_limit(8 * 1024 * 1024) != 0) {
        fprintf(stderr, "setrlimit failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = -1;
    if (reopen_log(&fd) != 0) return 1;

    while (1) {
        off_t sz = file_size(log_path);
        if (sz < 0) {
            // If file disappears, recreate it
            if (reopen_log(&fd) != 0) break;
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if ((size_t)sz >= max_size) {
            if (fd >= 0) close(fd);
            fd = -1;

            if (rotate_logs() != 0) {
                sleep(POLL_INTERVAL_SEC);
                continue;
            }

            if (reopen_log(&fd) != 0) break;
        }

        // Minimal daemon loop: no log ingestion here.
        // In a real deployment, another process writes to log_path.
        sleep(POLL_INTERVAL_SEC);
    }

    if (fd >= 0) close(fd);
    return 0;
}
