#define _POSIX_C_SOURCE 200809L
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <stdlib.h>

#define LOG_PATH        "/var/log/myapp.log"
#define MAX_BACKUPS     3
#define ROTATE_SIZE     (10 * 1024 * 1024)   /* 10 MB */
#define POLL_INTERVAL_S 5

static int rotate_logs(void) {
    char oldpath[256];
    char newpath[256];

    /* Remove oldest backup */
    snprintf(oldpath, sizeof(oldpath), "%s.%d", LOG_PATH, MAX_BACKUPS);
    unlink(oldpath);

    /* Shift backups */
    for (int i = MAX_BACKUPS - 1; i >= 1; --i) {
        snprintf(oldpath, sizeof(oldpath), "%s.%d", LOG_PATH, i);
        snprintf(newpath, sizeof(newpath), "%s.%d", LOG_PATH, i + 1);
        rename(oldpath, newpath);
    }

    /* Rotate current log */
    snprintf(oldpath, sizeof(oldpath), "%s", LOG_PATH);
    snprintf(newpath, sizeof(newpath), "%s.1", LOG_PATH);
    if (rename(oldpath, newpath) != 0) {
        return -1;
    }

    /* Recreate empty log file */
    int fd = open(LOG_PATH, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static off_t get_log_size(void) {
    struct stat st;
    if (stat(LOG_PATH, &st) != 0) return -1;
    return st.st_size;
}

int main(void) {
    while (1) {
        off_t size = get_log_size();
        if (size >= 0 && size >= ROTATE_SIZE) {
            if (rotate_logs() != 0) {
                fprintf(stderr, "rotation failed: %s\n", strerror(errno));
            }
        }
        sleep(POLL_INTERVAL_S);
    }
    return 0;
}
