        if (errno != ENOENT) perror("stat");
        return -1;
    }
    return st.st_size;
}

int main(void) {
    int fd;
    off_t sz;

    /* Ensure log file exists */
    fd = open(LOG_PATH, O_CREAT | O_APPEND | O_WRONLY, 0644);
    if (fd < 0) {
        perror("open");
        return 1;
    }
    close(fd);

    for (;;) {
        sz = file_size(LOG_PATH);
        if (sz < 0) {
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (sz >= ROTATE_SIZE_BYTES) {
            if (rotate_logs() == 0) {
                /* Recreate empty current log */
                fd = open(LOG_PATH, O_CREAT | O_TRUNC | O_WRONLY, 0644);
                if (fd < 0) {
                    perror("recreate log");
                    return 1;
                }
