## `logrotated.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <limits.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#ifndef MAX_PATH_LEN
#define MAX_PATH_LEN 512
#endif

#ifndef MAX_BACKUPS
#define MAX_BACKUPS 9
#endif

#ifndef BUF_SIZE
#define BUF_SIZE 4096
#endif

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int safe_snprintf(char *dst, size_t dstsz, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    int n = vsnprintf(dst, dstsz, fmt, ap);
    va_end(ap);
    if (n < 0 || (size_t)n >= dstsz) return -1;
    return 0;
}

static int file_size(const char *path, off_t *out_size) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    if (!S_ISREG(st.st_mode)) {
        errno = EINVAL;
        return -1;
    }
    *out_size = st.st_size;
    return 0;
}

static int rename_chain(const char *base, int backups) {
    char src[MAX_PATH_LEN];
    char dst[MAX_PATH_LEN];

    for (int i = backups - 1; i >= 1; --i) {
        if (safe_snprintf(src, sizeof(src), "%s.%d", base, i) != 0) return -1;
        if (safe_snprintf(dst, sizeof(dst), "%s.%d", base, i + 1) != 0) return -1;
        if (access(src, F_OK) == 0) {
            if (rename(src, dst) != 0) return -1;
        }
    }

    if (safe_snprintf(dst, sizeof(dst), "%s.1", base) != 0) return -1;
    if (rename(base, dst) != 0) return -1;

    return 0;
}

static int reopen_truncate(const char *path) {
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

static int rotate_log(const char *path, int backups) {
    if (rename_chain(path, backups) != 0) return -1;
    if (reopen_truncate(path) != 0) return -1;
    return 0;
}

static void usage(const char *prog) {
    fprintf(stderr,
            "Usage: %s <logfile> <max_bytes> [backups] [poll_ms]\n"
            "  logfile   Path to active log file\n"
            "  max_bytes Threshold for rotation\n"
            "  backups   Number of rotated files to keep (default %d)\n"
            "  poll_ms   Poll interval in milliseconds (default 1000)\n",
            prog, MAX_BACKUPS);
}

int main(int argc, char **argv) {
    if (argc < 3) {
        usage(argv[0]);
        return 2;
    }

    const char *logfile = argv[1];
    off_t max_bytes = (off_t)strtoll(argv[2], NULL, 10);
    int backups = (argc >= 4) ? atoi(argv[3]) : MAX_BACKUPS;
    int poll_ms = (argc >= 5) ? atoi(argv[4]) : 1000;

    if (max_bytes <= 0 || backups < 1 || backups > 99 || poll_ms < 1) {
        fprintf(stderr, "Invalid arguments\n");
        return 2;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Ensure log file exists.
    if (reopen_truncate(logfile) != 0) {
        perror("create log file");
        return 1;
    }

    while (!g_stop) {
        off_t sz = 0;
        if (file_size(logfile, &sz) == 0 && sz >= max_bytes) {
            if (rotate_log(logfile, backups) != 0) {
                perror("rotate");
                // Keep running; try again next cycle.
            }
        }

        struct timespec ts;
        ts.tv_sec = poll_ms / 1000;
        ts.tv_nsec = (long)(poll_ms % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    return 0;
}
