        "Usage: %s <logfile> <max_bytes> [backups]\n"
        "  logfile    path to log file\n"
        "  max_bytes  rotate when file size >= this value\n"
        "  backups   number of rotated files to keep (1-%d, default 3)\n",
        prog, MAX_BACKUPS);
}

int main(int argc, char **argv) {
    if (argc < 3 || argc > 4) {
        usage(argv[0]);
        return 1;
    }

    const char *logfile = argv[1];
    off_t max_bytes = (off_t)strtoll(argv[2], NULL, 10);
    int backups = (argc == 4) ? atoi(argv[3]) : 3;

    if (max_bytes <= 0 || backups < 1 || backups > MAX_BACKUPS) {
        usage(argv[0]);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Ensure log exists
    if (reopen_truncate(logfile) != 0) {
        perror("initial create");
        return 1;
    }

    while (!g_stop) {
        if (rotate_if_needed(logfile, max_bytes, backups) != 0) {
            perror("rotate");
        }
        sleep(CHECK_INTERVAL_SEC);
    }

    return 0;
}
