## `logrotate_min.c`

```c
#define _POSIX_C_SOURCE 200809L

#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PATH_LEN   256
#define MAX_BACKUPS    5
#define POLL_SECONDS   5

static volatile sig_atomic_t g_stop = 0;

static void on_signal(int sig) {
    (void)sig;
    g_stop = 1;
}

static int file_size(const char *path, off_t *size_out) {
    struct stat st;
    if (stat(path, &st) != 0) return -1;
    *size_out = st.st_size;
    return 0;
}

static int rotate_logs(const char *log_path) {
    char old_path[MAX_PATH_LEN];
    char new_path[MAX_PATH_LEN];

    // Remove oldest backup
    snprintf(old_path, sizeof(old_path), "%s.%d", log_path, MAX_BACKUPS);
    unlink(old_path);

    // Shift backups: .4 -> .5, .3 -> .4, ...
    for (int i = MAX_BACKUPS - 1; i >= 1; --i) {
        snprintf(old_path, sizeof(old_path), "%s.%d", log_path, i);
        snprintf(new_path, sizeof(new_path), "%s.%d", log_path, i + 1);
        rename(old_path, new_path);
    }

    // Current log -> .1
    snprintf(new_path, sizeof(new_path), "%s.1", log_path);
    if (rename(log_path, new_path) != 0) {
        return -1;
    }

    // Recreate empty log file
    int fd = open(log_path, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) return -1;
    close(fd);

    return 0;
}

static int ensure_log_exists(const char *log_path) {
    int fd = open(log_path, O_CREAT | O_WRONLY | O_APPEND, 0644);
    if (fd < 0) return -1;
    close(fd);
    return 0;
}

int main(int argc, char **argv) {
    const char *log_path;
    off_t max_size;
    struct sigaction sa;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <logfile> <max_size_bytes>\n", argv[0]);
        return 1;
    }

    log_path = argv[1];
    max_size = (off_t)strtoll(argv[2], NULL, 10);
    if (max_size <= 0) {
        fprintf(stderr, "Invalid max_size_bytes\n");
        return 1;
    }

    if (strlen(log_path) >= MAX_PATH_LEN) {
        fprintf(stderr, "Path too long (max %d)\n", MAX_PATH_LEN - 1);
        return 1;
    }

    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = on_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (ensure_log_exists(log_path) != 0) {
        perror("ensure_log_exists");
        return 1;
    }

    while (!g_stop) {
        off_t sz = 0;
        if (file_size(log_path, &sz) == 0 && sz >= max_size) {
            if (rotate_logs(log_path) != 0) {
                perror("rotate_logs");
            }
        }

        sleep(POLL_SECONDS);
    }

    return 0;
}
```

