use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs,
    net::SocketAddr,
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{TcpListener, TcpStream},
    signal,
    sync::{Mutex, RwLock},
    time,
};
use tracing::{debug, error, info, warn};

#[derive(Clone, Debug)]
struct Config {
    sample_interval: Duration,
    control_addr: SocketAddr,
    cpu_warn_pct: f32,
    mem_warn_pct: f32,
    disk_warn_pct: f32,
    top_processes: usize,
    state_file: PathBuf,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval: Duration::from_secs(2),
            control_addr: "127.0.0.1:7878".parse().unwrap(),
            cpu_warn_pct: 85.0,
            mem_warn_pct: 90.0,
            disk_warn_pct: 90.0,
            top_processes: 5,
            state_file: "/var/run/sysguardd.state.json".into(),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage_pct: f32,
    mem_total_kib: u64,
    mem_used_kib: u64,
    swap_total_kib: u64,
    swap_used_kib: u64,
    disk_total_bytes: u64,
    disk_used_bytes: u64,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: i32,
    name: String,
    cpu_usage_pct: f32,
    memory_kib: u64,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonState {
    last_snapshot: Option<ResourceSnapshot>,
    alerts: Vec<String>,
    actions_taken: Vec<String>,
}

impl Default for DaemonState {
    fn default() -> Self {
        Self {
            last_snapshot: None,
            alerts: Vec::new(),
            actions_taken: Vec::new(),
        }
    }
}

#[derive(Clone)]
struct SharedState {
    inner: Arc<RwLock<DaemonState>>,
}

impl SharedState {
    fn new() -> Self {
        Self {
            inner: Arc::new(RwLock::new(DaemonState::default())),
        }
    }

    async fn update_snapshot(&self, snapshot: ResourceSnapshot) {
        let mut state = self.inner.write().await;
        state.last_snapshot = Some(snapshot);
    }

    async fn push_alert(&self, msg: String) {
        let mut state = self.inner.write().await;
        state.alerts.push(msg);
        if state.alerts.len() > 1000 {
            state.alerts.drain(0..500);
        }
    }

    async fn push_action(&self, msg: String) {
        let mut state = self.inner.write().await;
        state.actions_taken.push(msg);
        if state.actions_taken.len() > 1000 {
            state.actions_taken.drain(0..500);
        }
    }

    async fn snapshot_state(&self) -> DaemonState {
        self.inner.read().await.clone()
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    let config = Config::default();
    info!("starting sysguardd");

    let shared = SharedState::new();
    let sys = Arc::new(Mutex::new(System::new_all()));

    let monitor_task = {
        let shared = shared.clone();
        let sys = sys.clone();
        let config = config.clone();
        tokio::spawn(async move {
            if let Err(e) = monitor_loop(shared, sys, config).await {
                error!("monitor loop failed: {e:#}");
            }
        })
    };

    let control_task = {
        let shared = shared.clone();
        let config = config.clone();
        tokio::spawn(async move {
            if let Err(e) = control_server(shared, config).await {
                error!("control server failed: {e:#}");
            }
        })
    };

    let shutdown = async {
        signal::ctrl_c().await.context("failed to listen for ctrl-c")?;
        Ok::<_, anyhow::Error>(())
    };

    shutdown.await?;
    info!("shutdown requested");

    monitor_task.abort();
    control_task.abort();

    persist_state(&shared, &config).await?;
    info!("sysguardd stopped");
    Ok(())
}

async fn monitor_loop(shared: SharedState, sys: Arc<Mutex<System>>, config: Config) -> Result<()> {
    let mut interval = time::interval(config.sample_interval);
    interval.set_missed_tick_behavior(time::MissedTickBehavior::Skip);

    loop {
        interval.tick().await;
        let start = Instant::now();

        let snapshot = collect_snapshot(&sys, config.top_processes).await?;
        evaluate_snapshot(&shared, &config, &snapshot).await;
        shared.update_snapshot(snapshot.clone()).await;

        debug!(
            "sampled resources in {:?}: cpu={:.1}% mem={:.1}%",
            start.elapsed(),
            snapshot.cpu_usage_pct,
            (snapshot.mem_used_kib as f32 / snapshot.mem_total_kib.max(1) as f32) * 100.0
        );
    }
}

async fn collect_snapshot(sys: &Arc<Mutex<System>>, top_n: usize) -> Result<ResourceSnapshot> {
    let mut sys = sys.lock().await;
    sys.refresh_all();

    let cpu_usage_pct = sys.global_cpu_info().cpu_usage();
    let mem_total_kib = sys.total_memory();
    let mem_used_kib = sys.used_memory();
    let swap_total_kib = sys.total_swap();
    let swap_used_kib = sys.used_swap();

    let mut disk_total_bytes = 0u64;
    let mut disk_used_bytes = 0u64;
    for disk in sys.disks() {
        let total = disk.total_space();
        let avail = disk.available_space();
        disk_total_bytes += total;
        disk_used_bytes += total.saturating_sub(avail);
    }

    let mut processes: Vec<ProcessInfo> = sys
        .processes()
        .iter()
        .map(|(pid, p)| ProcessInfo {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_usage_pct: p.cpu_usage(),
            memory_kib: p.memory(),
        })
        .collect();

    processes.sort_by(|a, b| {
        b.cpu_usage_pct
            .partial_cmp(&a.cpu_usage_pct)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    processes.truncate(top_n);

    Ok(ResourceSnapshot {
        timestamp_ms: Instant::now().elapsed().as_millis(),
        cpu_usage_pct,
        mem_total_kib,
        mem_used_kib,
        swap_total_kib,
        swap_used_kib,
        disk_total_bytes,
        disk_used_bytes,
        top_processes: processes,
    })
}

async fn evaluate_snapshot(shared: &SharedState, config: &Config, snap: &ResourceSnapshot) {
    let mem_pct = (snap.mem_used_kib as f32 / snap.mem_total_kib.max(1) as f32) * 100.0;
    let disk_pct = (snap.disk_used_bytes as f32 / snap.disk_total_bytes.max(1) as f32) * 100.0;

    if snap.cpu_usage_pct >= config.cpu_warn_pct {
        let msg = format!("high CPU usage: {:.1}%", snap.cpu_usage_pct);
        warn!("{msg}");
        shared.push_alert(msg).await;
    }

    if mem_pct >= config.mem_warn_pct {
        let msg = format!("high memory usage: {:.1}%", mem_pct);
        warn!("{msg}");
        shared.push_alert(msg).await;
    }

    if disk_pct >= config.disk_warn_pct {
        let msg = format!("high disk usage: {:.1}%", disk_pct);
        warn!("{msg}");
        shared.push_alert(msg).await;
    }

    // Example management action stub:
    // In a real daemon, this could trigger cgroup adjustments, service restarts,
    // process throttling, or alerting. Here we only log a placeholder.
    if snap.cpu_usage_pct > 95.0 {
        let action = "would throttle or inspect top CPU consumers".to_string();
        info!("{action}");
        shared.push_action(action).await;
    }
}

async fn control_server(shared: SharedState, config: Config) -> Result<()> {
    let listener = TcpListener::bind(config.control_addr)
        .await
        .with_context(|| format!("bind {}", config.control_addr))?;

    info!("control server listening on {}", config.control_addr);

    loop {
        let (stream, addr) = listener.accept().await?;
        let shared = shared.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, addr, shared).await {
                error!("client {addr} error: {e:#}");
            }
        });
    }
}

async fn handle_client(stream: TcpStream, addr: SocketAddr, shared: SharedState) -> Result<()> {
    info!("client connected: {addr}");
    let (reader, mut writer) = stream.into_split();
    let mut lines = BufReader::new(reader).lines();

    writer.write_all(b"sysguardd ready\ncommands: status, alerts, actions, quit\n").await?;

    while let Some(line) = lines.next_line().await? {
        let cmd = line.trim().to_lowercase();
        match cmd.as_str() {
            "status" => {
                let state = shared.snapshot_state().await;
                let json = serde_json::to_string_pretty(&state)?;
                writer.write_all(json.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "alerts" => {
                let state = shared.snapshot_state().await;
                for a in state.alerts.iter().rev().take(20) {
                    writer.write_all(a.as_bytes()).await?;
                    writer.write_all(b"\n").await?;
                }
            }
            "actions" => {
                let state = shared.snapshot_state().await;
                for a in state.actions_taken.iter().rev().take(20) {
                    writer.write_all(a.as_bytes()).await?;
                    writer.write_all(b"\n").await?;
                }
            }
            "quit" | "exit" => {
                writer.write_all(b"bye\n").await?;
                break;
            }
            _ => {
                writer.write_all(b"unknown command\n").await?;
            }
        }
    }

    info!("client disconnected: {addr}");
    Ok(())
}

async fn persist_state(shared: &SharedState, config: &Config) -> Result<()> {
    let state = shared.snapshot_state().await;
    let json = serde_json::to_vec_pretty(&state)?;
    if let Some(parent) = config.state_file.parent() {
        fs::create_dir_all(parent).ok();
    }
    fs::write(&config.state_file, json)
        .with_context(|| format!("write state file {}", config.state_file.display()))?;
    Ok(())
}
