#[derive(Debug, Clone, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    disk_warn_threshold: f32,
    top_n_processes: usize,
    enable_process_kill: bool,
    kill_cpu_threshold: f32,
    kill_mem_threshold_mb: u64,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_warn_threshold: 85.0,
            mem_warn_threshold: 90.0,
            disk_warn_threshold: 90.0,
            top_n_processes: 5,
            enable_process_kill: false,
            kill_cpu_threshold: 95.0,
            kill_mem_threshold_mb: 1024,
        }
    }
}

impl Config {
    fn load(path: Option<PathBuf>) -> Self {
        if let Some(path) = path {
            if let Ok(data) = fs::read_to_string(path) {
                if let Ok(cfg) = serde_json::from_str::<Config>(&data) {
                    return cfg;
                }
            }
        }
        Self::default()
    }
}

#[derive(Debug)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu: f32,
    memory_mb: u64,
}

struct ResourceDaemon {
    system: System,
    config: Config,
    last_process_scan: HashMap<i32, Instant>,
}

impl ResourceDaemon {
    fn new(config: Config) -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        Self {
            system,
            config,
            last_process_scan: HashMap::new(),
        }
    }

    fn refresh_metrics(&mut self) {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.system.refresh_processes();
    }

    fn cpu_usage(&self) -> f32 {
        let cpus = self.system.cpus();
        if cpus.is_empty() {
            return 0.0;
        }
        cpus.iter().map(|c| c.cpu_usage()).sum::<f32>() / cpus.len() as f32
    }

    fn memory_usage(&self) -> f32 {
        let total = self.system.total_memory() as f32;
        let used = self.system.used_memory() as f32;
        if total <= 0.0 {
            0.0
        } else {
            (used / total) * 100.0
        }
    }

    fn disk_usage(&self) -> f32 {
        let mut total = 0u64;
        let mut used = 0u64;

        for disk in self.system.disks() {
            let t = disk.total_space();
            let a = disk.available_space();
            total += t;
            used += t.saturating_sub(a);
        }

        if total == 0 {
            0.0
        } else {
            (used as f32 / total as f32) * 100.0
        }
    }

    fn top_processes(&self, n: usize) -> Vec<ProcessSnapshot> {
        let mut procs: Vec<_> = self
            .system
            .processes()
            .iter()
            .map(|(pid, p)| ProcessSnapshot {
                pid: pid.as_u32() as i32,
                name: p.name().to_string(),
                cpu: p.cpu_usage(),
                memory_mb: p.memory() / 1024,
            })
            .collect();

        procs.sort_by(|a, b| {
            b.cpu
                .partial_cmp(&a.cpu)
                .unwrap_or(std::cmp::Ordering::Equal)
                .then_with(|| b.memory_mb.cmp(&a.memory_mb))
        });

        procs.truncate(n);
        procs
    }

    fn maybe_take_action(&mut self) {
        if !self.config.enable_process_kill {
            return;
        }

        for (pid, process) in self.system.processes() {
            let cpu = process.cpu_usage();
            let mem_mb = process.memory() / 1024;

            if cpu >= self.config.kill_cpu_threshold || mem_mb >= self.config.kill_mem_threshold_mb {
                warn!(
                    pid = pid.as_u32(),
                    name = %process.name(),
                    cpu = cpu,
                    mem_mb = mem_mb,
                    "Process exceeds kill thresholds"
                );

                // Example policy: terminate only if process has been above threshold
                // for at least 3 consecutive scans. This avoids killing transient spikes.
                let now = Instant::now();
                let pid_i32 = pid.as_u32() as i32;

                let should_kill = match self.last_process_scan.get(&pid_i32) {
                    Some(first_seen) => now.duration_since(*first_seen) >= Duration::from_secs(3),
                    None => {
                        self.last_process_scan.insert(pid_i32, now);
                        false
                    }
                };

                if should_kill {
                    #[cfg(unix)]
                    {
                        use nix::sys::signal::{kill, Signal};
                        use nix::unistd::Pid;

                        let _ = kill(Pid::from_raw(pid.as_u32() as i32), Signal::SIGTERM);
                        warn!(pid = pid.as_u32(), "Sent SIGTERM to process");
                    }
                }
            } else {
                self.last_process_scan.remove(&pid.as_u32() as i32);
            }
        }
    }

    fn report(&self) {
        let cpu = self.cpu_usage();
        let mem = self.memory_usage();
        let disk = self.disk_usage();

        info!(
            cpu = cpu,
            memory = mem,
            disk = disk,
            "Resource snapshot"
        );

        if cpu >= self.config.cpu_warn_threshold {
            warn!(cpu = cpu, "CPU usage above threshold");
        }
        if mem >= self.config.mem_warn_threshold {
            warn!(memory = mem, "Memory usage above threshold");
        }
        if disk >= self.config.disk_warn_threshold {
            warn!(disk = disk, "Disk usage above threshold");
        }

        for p in self.top_processes(self.config.top_n_processes) {
            debug!(
                pid = p.pid,
                name = %p.name,
                cpu = p.cpu,
                mem_mb = p.memory_mb,
                "Top process"
            );
        }
    }

    async fn run(mut self) -> Result<()> {
        let mut ticker = interval(Duration::from_millis(self.config.sample_interval_ms));

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    self.refresh_metrics();
                    self.report();
                    self.maybe_take_action();
                }
                _ = signal::ctrl_c() => {
                    info!("Shutdown signal received");
                    break;
                }
            }
        }

        Ok(())
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    let config_path = std::env::args().nth(1).map(PathBuf::from);
    let config = Config::load(config_path);

    info!(?config, "Starting resource daemon");

    let daemon = ResourceDaemon::new(config);
    if let Err(e) = daemon.run().await {
        error!(error = %e, "Daemon exited with error");
        return Err(e);
    }

    info!("Daemon stopped cleanly");
    Ok(())
}
