use anyhow::Result;
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::signal;
use tokio::time::interval;
use tracing::{info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Debug, Clone)]
struct Thresholds {
    cpu_warn: f32,
    mem_warn: f32,
    disk_warn: f32,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_warn: 85.0,
            mem_warn: 85.0,
            disk_warn: 90.0,
        }
    }
}

#[derive(Debug)]
struct Snapshot {
    cpu_usage: f32,
    mem_used_pct: f32,
    disk_used_pct: f32,
    total_memory_mb: u64,
    used_memory_mb: u64,
    total_swap_mb: u64,
    used_swap_mb: u64,
}

fn collect_snapshot(sys: &mut System) -> Snapshot {
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_disks_list();
    sys.refresh_disks();

    let cpu_usage = sys.global_cpu_info().cpu_usage();

    let total_memory = sys.total_memory();
    let used_memory = sys.used_memory();
    let total_swap = sys.total_swap();
    let used_swap = sys.used_swap();

    let mem_used_pct = if total_memory > 0 {
        (used_memory as f32 / total_memory as f32) * 100.0
    } else {
        0.0
    };

    // Aggregate disk usage across mounted disks
    let mut total_disk = 0u64;
    let mut used_disk = 0u64;
    for disk in sys.disks() {
        let total = disk.total_space();
        let avail = disk.available_space();
        total_disk += total;
        used_disk += total.saturating_sub(avail);
    }

    let disk_used_pct = if total_disk > 0 {
        (used_disk as f32 / total_disk as f32) * 100.0
    } else {
        0.0
    };

    Snapshot {
        cpu_usage,
        mem_used_pct,
        disk_used_pct,
        total_memory_mb: total_memory / 1024,
        used_memory_mb: used_memory / 1024,
        total_swap_mb: total_swap / 1024,
        used_swap_mb: used_swap / 1024,
    }
}

fn evaluate(snapshot: &Snapshot, thresholds: &Thresholds) {
    info!(
        cpu = format!("{:.1}", snapshot.cpu_usage),
        mem = format!("{:.1}", snapshot.mem_used_pct),
        disk = format!("{:.1}", snapshot.disk_used_pct),
        total_mem_mb = snapshot.total_memory_mb,
        used_mem_mb = snapshot.used_memory_mb,
        total_swap_mb = snapshot.total_swap_mb,
        used_swap_mb = snapshot.used_swap_mb,
        "resource snapshot"
    );

    if snapshot.cpu_usage >= thresholds.cpu_warn {
        warn!(cpu = format!("{:.1}", snapshot.cpu_usage), "high CPU usage");
    }
    if snapshot.mem_used_pct >= thresholds.mem_warn {
        warn!(mem = format!("{:.1}", snapshot.mem_used_pct), "high memory usage");
    }
    if snapshot.disk_used_pct >= thresholds.disk_warn {
        warn!(disk = format!("{:.1}", snapshot.disk_used_pct), "high disk usage");
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse()?))
        .init();

    let thresholds = Thresholds::default();
    let mut sys = System::new_all();

    // Warm-up refresh so CPU readings stabilize
    sys.refresh_cpu();
    tokio::time::sleep(Duration::from_millis(500)).await;

    let mut ticker = interval(Duration::from_secs(5));

    info!("resource daemon started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let snapshot = collect_snapshot(&mut sys);
                evaluate(&snapshot, &thresholds);
            }
            _ = signal::ctrl_c() => {
                info!("shutdown requested");
                break;
            }
        }
    }

    info!("resource daemon stopped");
    Ok(())
}
