## `src/main.rs`

```rust
use anyhow::{Context, Result};
use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Method, Request, Response, StatusCode};
use hyper_util::rt::TokioIo;
use serde::Serialize;
use std::convert::Infallible;
use std::net::SocketAddr;
use std::sync::Arc;
use tokio::net::TcpListener;
use tokio::sync::RwLock;
use tokio::time::{interval, Duration};
use tracing::{error, info, warn};

use sysinfo::{
    CpuExt, DiskExt, PidExt, ProcessExt, System, SystemExt,
};

#[derive(Clone)]
struct Config {
    poll_interval: Duration,
    http_bind: SocketAddr,
    cpu_kill_threshold: f32,
    memory_warn_threshold: f32,
    disk_warn_threshold: f32,
    enable_pid_kill: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval: Duration::from_secs(2),
            http_bind: "127.0.0.1:8080".parse().unwrap(),
            cpu_kill_threshold: 90.0,
            memory_warn_threshold: 85.0,
            disk_warn_threshold: 90.0,
            enable_pid_kill: false,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_unix: u64,
    cpu_usage_percent: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    memory_usage_percent: f32,
    total_swap_kib: u64,
    used_swap_kib: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disk_usage_percent: f32,
    process_count: usize,
    top_processes: Vec<ProcessInfo>,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessInfo {
    pid: u32,
    name: String,
    cpu_usage_percent: f32,
    memory_kib: u64,
}

struct SharedState {
    snapshot: Option<ResourceSnapshot>,
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let config = Config::default();
    let state = Arc::new(RwLock::new(SharedState { snapshot: None }));

    let monitor_state = state.clone();
    let monitor_config = config.clone();
    tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_config).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let http_state = state.clone();
    let http_config = config.clone();
    tokio::spawn(async move {
        if let Err(e) = run_http_server(http_state, http_config).await {
            error!("http server failed: {e:#}");
        }
    });

    info!("daemon started");

    tokio::signal::ctrl_c()
        .await
        .context("failed to listen for ctrl-c")?;

    info!("shutdown requested");
    Ok(())
}

async fn monitor_loop(state: Arc<RwLock<SharedState>>, config: Config) -> Result<()> {
    let mut system = System::new_all();
    let mut ticker = interval(config.poll_interval);

    loop {
        ticker.tick().await;

        system.refresh_all();

        let snapshot = build_snapshot(&system);
        evaluate_policy(&system, &snapshot, &config);

        {
            let mut guard = state.write().await;
            guard.snapshot = Some(snapshot);
        }
    }
}

fn build_snapshot(system: &System) -> ResourceSnapshot {
    let cpu_usage_percent = system.global_cpu_info().cpu_usage();
    let total_memory_kib = system.total_memory();
    let used_memory_kib = system.used_memory();
    let memory_usage_percent = if total_memory_kib > 0 {
        (used_memory_kib as f32 / total_memory_kib as f32) * 100.0
    } else {
        0.0
    };

    let total_swap_kib = system.total_swap();
    let used_swap_kib = system.used_swap();

    let load = System::load_average();

    let disk_usage_percent = disk_usage_percent(system);

    let mut processes: Vec<ProcessInfo> = system
        .processes()
        .iter()
        .map(|(pid, proc_)| ProcessInfo {
            pid: pid.as_u32(),
            name: proc_.name().to_string(),
            cpu_usage_percent: proc_.cpu_usage(),
            memory_kib: proc_.memory(),
        })
        .collect();

    processes.sort_by(|a, b| {
        b.cpu_usage_percent
            .partial_cmp(&a.cpu_usage_percent)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    let top_processes = processes.into_iter().take(10).collect::<Vec<_>>();

    ResourceSnapshot {
        timestamp_unix: chrono_like_unix_time(),
        cpu_usage_percent,
        total_memory_kib,
        used_memory_kib,
        memory_usage_percent,
        total_swap_kib,
        used_swap_kib,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        disk_usage_percent,
        process_count: system.processes().len(),
        top_processes,
    }
}

fn disk_usage_percent(system: &System) -> f32 {
    let mut total = 0u64;
    let mut used = 0u64;

    for disk in system.disks() {
        let t = disk.total_space();
        let a = disk.available_space();
        total += t;
        used += t.saturating_sub(a);
    }

    if total > 0 {
        (used as f32 / total as f32) * 100.0
    } else {
        0.0
    }
}

fn evaluate_policy(system: &System, snapshot: &ResourceSnapshot, config: &Config) {
    if snapshot.memory_usage_percent >= config.memory_warn_threshold {
        warn!(
            "high memory usage: {:.1}% (used {} KiB / total {} KiB)",
            snapshot.memory_usage_percent,
            snapshot.used_memory_kib,
            snapshot.total_memory_kib
        );
    }

    if snapshot.disk_usage_percent >= config.disk_warn_threshold {
        warn!(
            "high disk usage: {:.1}% (process count {})",
            snapshot.disk_usage_percent,
            snapshot.process_count
        );
    }

    if snapshot.cpu_usage_percent >= config.cpu_kill_threshold {
        warn!(
            "high CPU usage: {:.1}% (top process: {:?})",
            snapshot.cpu_usage_percent,
            snapshot.top_processes.first()
        );

        if config.enable_pid_kill {
            if let Some(proc_) = snapshot.top_processes.first() {
                let pid = sysinfo::Pid::from_u32(proc_.pid);
                if let Some(target) = system.process(pid) {
                    warn!("killing process pid={} name={}", proc_.pid, proc_.name);
                    let _ = target.kill();
                }
            }
        }
    }
}

async fn run_http_server(state: Arc<RwLock<SharedState>>, config: Config) -> Result<()> {
    let listener = TcpListener::bind(config.http_bind)
        .await
        .with_context(|| format!("failed to bind {}", config.http_bind))?;

    info!("http server listening on {}", config.http_bind);

    loop {
        let (stream, _) = listener.accept().await?;
        let io = TokioIo::new(stream);
        let state = state.clone();

        tokio::spawn(async move {
            let service = service_fn(move |req| {
                let state = state.clone();
                async move { handle_request(req, state).await }
            });

            if let Err(err) = hyper::server::conn::http1::Builder::new()
                .serve_connection(io, service)
                .await
            {
                error!("http connection error: {err}");
            }
        });
    }
}

async fn handle_request(
    req: Request<Incoming>,
    state: Arc<RwLock<SharedState>>,
) -> Result<Response<Full<Bytes>>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/health") => text_response(StatusCode::OK, "ok\n"),
        (&Method::GET, "/metrics") => {
            let guard = state.read().await;
            if let Some(snapshot) = &guard.snapshot {
                match serde_json::to_string_pretty(snapshot) {
                    Ok(body) => json_response(StatusCode::OK, body),
                    Err(_) => text_response(StatusCode::INTERNAL_SERVER_ERROR, "serialization error\n"),
                }
            } else {
                text_response(StatusCode::SERVICE_UNAVAILABLE, "no snapshot yet\n")
            }
        }
        (&Method::GET, "/") => text_response(
            StatusCode::OK,
            "resmon-daemon\nGET /health\nGET /metrics\n",
        ),
        _ => text_response(StatusCode::NOT_FOUND, "not found\n"),
    };

    Ok(response)
}

fn text_response(status: StatusCode, body: &str) -> Response<Full<Bytes>> {
    Response::builder()
        .status(status)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from(body.to_owned())))
        .unwrap()
}

fn json_response(status: StatusCode, body: String) -> Response<Full<Bytes>> {
    Response::builder()
        .status(status)
        .header("content-type", "application/json")
        .body(Full::new(Bytes::from(body)))
        .unwrap()
}

fn chrono_like_unix_time() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
```

