```rust
use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::Path,
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Networks, RefreshKind, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Debug, Deserialize, Clone)]
struct Thresholds {
    warn_threshold: f64,
    critical_threshold: f64,
}

#[derive(Debug, Deserialize, Clone)]
struct NetworkThresholds {
    warn_threshold: u64,
    critical_threshold: u64,
}

#[derive(Debug, Deserialize, Clone)]
struct Config {
    poll_interval_ms: u64,
    cpu: Thresholds,
    memory: Thresholds,
    disk: Thresholds,
    network: NetworkThresholds,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: 1000,
            cpu: Thresholds {
                warn_threshold: 80.0,
                critical_threshold: 95.0,
            },
            memory: Thresholds {
                warn_threshold: 80.0,
                critical_threshold: 95.0,
            },
            disk: Thresholds {
                warn_threshold: 80.0,
                critical_threshold: 95.0,
            },
            network: NetworkThresholds {
                warn_threshold: 10_000_000,
                critical_threshold: 50_000_000,
            },
        }
    }
}

#[derive(Debug)]
struct Sample {
    cpu_usage: f32,
    memory_usage: f32,
    disk_usage: f32,
    net_rx_bps: u64,
    net_tx_bps: u64,
}

fn load_config(path: impl AsRef<Path>) -> Result<Config> {
    let path = path.as_ref();
    if !path.exists() {
        return Ok(Config::default());
    }
    let content = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {}", path.display()))?;
    let cfg: Config = toml::from_str(&content)
        .with_context(|| format!("failed to parse config file: {}", path.display()))?;
    Ok(cfg)
}

fn init_logging() {
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));
    tracing_subscriber::fmt()
        .with_env_filter(filter)
        .with_target(false)
        .compact()
        .init();
}

fn percent(used: u64, total: u64) -> f64 {
    if total == 0 {
        0.0
    } else {
        (used as f64 * 100.0) / total as f64
    }
}

fn collect_sample(
    system: &mut System,
    networks: &mut Networks,
    prev_net: &mut Option<(Instant, u64, u64)>,
) -> Sample {
    system.refresh_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything()),
    );
    networks.refresh();

    let cpu_usage = system.global_cpu_usage();
    let total_memory = system.total_memory();
    let used_memory = system.used_memory();
    let memory_usage = percent(used_memory, total_memory) as f32;

    let mut total_disk_used = 0u64;
    let mut total_disk_total = 0u64;
    for disk in system.disks() {
        let total = disk.total_space();
        let available = disk.available_space();
        total_disk_total += total;
        total_disk_used += total.saturating_sub(available);
    }
    let disk_usage = percent(total_disk_used, total_disk_total) as f32;

    let now = Instant::now();
    let mut rx_total = 0u64;
    let mut tx_total = 0u64;
    for (_name, data) in networks.iter() {
        rx_total += data.received();
        tx_total += data.transmitted();
    }

    let (net_rx_bps, net_tx_bps) = if let Some((prev_t, prev_rx, prev_tx)) = prev_net {
        let dt = now.duration_since(*prev_t).as_secs_f64().max(0.001);
        let rx_bps = ((rx_total.saturating_sub(*prev_rx)) as f64 / dt) as u64;
        let tx_bps = ((tx_total.saturating_sub(*prev_tx)) as f64 / dt) as u64;
        (rx_bps, tx_bps)
    } else {
        (0, 0)
    };

    *prev_net = Some((now, rx_total, tx_total));

    Sample {
        cpu_usage,
        memory_usage,
        disk_usage,
        net_rx_bps,
        net_tx_bps,
    }
}

fn evaluate_and_act(sample: &Sample, cfg: &Config) {
    if sample.cpu_usage as f64 >= cfg.cpu.critical_threshold {
        error!("CRITICAL CPU usage: {:.1}%", sample.cpu_usage);
    } else if sample.cpu_usage as f64 >= cfg.cpu.warn_threshold {
        warn!("High CPU usage: {:.1}%", sample.cpu_usage);
    }

    if sample.memory_usage as f64 >= cfg.memory.critical_threshold {
        error!("CRITICAL memory usage: {:.1}%", sample.memory_usage);
    } else if sample.memory_usage as f64 >= cfg.memory.warn_threshold {
        warn!("High memory usage: {:.1}%", sample.memory_usage);
    }

    if sample.disk_usage as f64 >= cfg.disk.critical_threshold {
        error!("CRITICAL disk usage: {:.1}%", sample.disk_usage);
    } else if sample.disk_usage as f64 >= cfg.disk.warn_threshold {
        warn!("High disk usage: {:.1}%", sample.disk_usage);
    }

    let net_total = sample.net_rx_bps.saturating_add(sample.net_tx_bps);
    if net_total >= cfg.network.critical_threshold {
        error!(
            "CRITICAL network throughput: rx={} B/s tx={} B/s",
            sample.net_rx_bps, sample.net_tx_bps
        );
    } else if net_total >= cfg.network.warn_threshold {
        warn!(
            "High network throughput: rx={} B/s tx={} B/s",
            sample.net_rx_bps, sample.net_tx_bps
        );
    }

    debug!(
        "sample: cpu={:.1}% mem={:.1}% disk={:.1}% rx={} tx={}",
        sample.cpu_usage,
        sample.memory_usage,
        sample.disk_usage,
        sample.net_rx_bps,
        sample.net_tx_bps
    );
}

#[tokio::main]
async fn main() -> Result<()> {
    init_logging();

    let cfg = load_config("config.toml")?;
    info!("starting sysd with config: {:?}", cfg);

    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything()),
    );
    let mut networks = Networks::new_with_refreshed_list();
    let mut prev_net: Option<(Instant, u64, u64)> = None;

    let mut ticker = interval(Duration::from_millis(cfg.poll_interval_ms));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let sample = collect_sample(&mut system, &mut networks, &mut prev_net);
                evaluate_and_act(&sample, &cfg);
            }
            _ = signal::ctrl_c() => {
                info!("shutdown requested");
                break;
            }
        }
    }

    info!("sysd stopped");
    Ok(())
}
