## `src/main.rs`

```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    fs,
    path::PathBuf,
    sync::Arc,
    time::Duration,
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::{signal, sync::RwLock, time};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    poll_interval_ms: u64,
    cpu_warn_pct: f32,
    mem_warn_pct: f32,
    disk_warn_pct: f32,
    max_processes_to_report: usize,
    enable_process_throttling: bool,
    process_cpu_kill_pct: f32,
    process_mem_kill_mb: u64,
    report_path: Option<PathBuf>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: 1000,
            cpu_warn_pct: 85.0,
            mem_warn_pct: 90.0,
            disk_warn_pct: 90.0,
            max_processes_to_report: 10,
            enable_process_throttling: false,
            process_cpu_kill_pct: 80.0,
            process_mem_kill_mb: 1024,
            report_path: Some(PathBuf::from("/tmp/resource_daemon_report.json")),
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ProcessSnapshot {
    pid: i32,
    name: String,
    cpu_usage: f32,
    memory_kb: u64,
}

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    cpu_usage_pct: f32,
    total_memory_kb: u64,
    used_memory_kb: u64,
    total_swap_kb: u64,
    used_swap_kb: u64,
    disk_usage_pct: f32,
    top_processes: Vec<ProcessSnapshot>,
}

#[derive(Clone)]
struct DaemonState {
    config: Arc<RwLock<Config>>,
}

fn load_config(path: &str) -> Config {
    match fs::read_to_string(path) {
        Ok(contents) => serde_json::from_str(&contents).unwrap_or_else(|_| Config::default()),
        Err(_) => Config::default(),
    }
}

fn disk_usage_pct(system: &System) -> f32 {
    let mut total: u64 = 0;
    let mut used: u64 = 0;

    for disk in system.disks() {
        let t = disk.total_space();
        let a = disk.available_space();
        total += t;
        used += t.saturating_sub(a);
    }

    if total == 0 {
        0.0
    } else {
        (used as f32 / total as f32) * 100.0
    }
}

fn top_processes(system: &System, limit: usize) -> Vec<ProcessSnapshot> {
    let mut procs: Vec<_> = system
        .processes()
        .iter()
        .map(|(pid, p)| ProcessSnapshot {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_usage: p.cpu_usage(),
            memory_kb: p.memory(),
        })
        .collect();

    procs.sort_by(|a, b| {
        b.cpu_usage
            .partial_cmp(&a.cpu_usage)
            .unwrap_or(std::cmp::Ordering::Equal)
    });

    procs.truncate(limit);
    procs
}

fn build_snapshot(system: &System, cfg: &Config) -> ResourceSnapshot {
    ResourceSnapshot {
        cpu_usage_pct: system.global_cpu_info().cpu_usage(),
        total_memory_kb: system.total_memory(),
        used_memory_kb: system.used_memory(),
        total_swap_kb: system.total_swap(),
        used_swap_kb: system.used_swap(),
        disk_usage_pct: disk_usage_pct(system),
        top_processes: top_processes(system, cfg.max_processes_to_report),
    }
}

fn maybe_take_action(system: &mut System, snapshot: &ResourceSnapshot, cfg: &Config) {
    if snapshot.cpu_usage_pct >= cfg.cpu_warn_pct {
        warn!("High CPU usage: {:.2}%", snapshot.cpu_usage_pct);
    }

    let mem_pct = if snapshot.total_memory_kb == 0 {
        0.0
    } else {
        (snapshot.used_memory_kb as f32 / snapshot.total_memory_kb as f32) * 100.0
    };

    if mem_pct >= cfg.mem_warn_pct {
        warn!("High memory usage: {:.2}%", mem_pct);
    }

    if snapshot.disk_usage_pct >= cfg.disk_warn_pct {
        warn!("High disk usage: {:.2}%", snapshot.disk_usage_pct);
    }

    if !cfg.enable_process_throttling {
        return;
    }

    for proc in &snapshot.top_processes {
        let mem_mb = proc.memory_kb / 1024;
        if proc.cpu_usage >= cfg.process_cpu_kill_pct || mem_mb >= cfg.process_mem_kill_mb {
            warn!(
                "Process {} (pid={}) exceeds policy: cpu={:.2}% mem={} MB",
                proc.name, proc.pid, proc.cpu_usage, mem_mb
            );

            // Example action: terminate offending process.
            // In production, consider graceful signaling, allowlists, and escalation policy.
            if let Some(p) = system.process(sysinfo::Pid::from_u32(proc.pid as u32)) {
                if let Err(e) = p.kill() {
                    error!("Failed to kill pid {}: {}", proc.pid, e);
                } else {
                    info!("Killed pid {} ({})", proc.pid, proc.name);
                }
            }
        }
    }
}

fn write_report(path: &PathBuf, snapshot: &ResourceSnapshot) -> Result<()> {
    let json = serde_json::to_string_pretty(snapshot)?;
    fs::write(path, json).with_context(|| format!("writing report to {}", path.display()))?;
    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config_path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "config.json".to_string());

    let config = load_config(&config_path);
    info!("Loaded config from {}", config_path);

    let state = DaemonState {
        config: Arc::new(RwLock::new(config)),
    };

    let mut system = System::new_all();
    system.refresh_all();

    let mut interval = time::interval(Duration::from_millis(
        state.config.read().await.poll_interval_ms,
    ));

    loop {
        tokio::select! {
            _ = interval.tick() => {
                system.refresh_all();

                let cfg = state.config.read().await.clone();
                let snapshot = build_snapshot(&system, &cfg);

                info!(
                    "CPU={:.2}% MEM={}/{} KB DISK={:.2}%",
                    snapshot.cpu_usage_pct,
                    snapshot.used_memory_kb,
                    snapshot.total_memory_kb,
                    snapshot.disk_usage_pct
                );

                if let Some(path) = &cfg.report_path {
                    if let Err(e) = write_report(path, &snapshot) {
                        error!("Failed to write report: {}", e);
                    }
                }

                maybe_take_action(&mut system, &snapshot, &cfg);
            }

            _ = signal::ctrl_c() => {
                info!("Shutdown signal received, exiting.");
                break;
            }
        }
    }

    Ok(())
}
