```rust
use anyhow::{Context, Result};
use serde::Deserialize;
use std::{fs, path::Path, time::Duration};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::signal;
use tokio::time::interval;
use tracing::{error, info, warn};

#[derive(Debug, Deserialize, Clone)]
struct Config {
    daemon: DaemonConfig,
    thresholds: Thresholds,
    actions: Actions,
}

#[derive(Debug, Deserialize, Clone)]
struct DaemonConfig {
    interval_ms: u64,
}

#[derive(Debug, Deserialize, Clone)]
struct Thresholds {
    cpu_percent: f32,
    memory_percent: f32,
    disk_percent: f32,
}

#[derive(Debug, Deserialize, Clone)]
struct Actions {
    kill_process_name: String,
    enable_kill: bool,
}

#[derive(Debug)]
struct Metrics {
    cpu_percent: f32,
    memory_percent: f32,
    disk_percent: f32,
    process_count: usize,
}

fn load_config<P: AsRef<Path>>(path: P) -> Result<Config> {
    let content = fs::read_to_string(&path)
        .with_context(|| format!("failed to read config: {:?}", path.as_ref()))?;
    let cfg: Config = toml::from_str(&content).context("failed to parse config")?;
    Ok(cfg)
}

fn collect_metrics(system: &mut System) -> Metrics {
    system.refresh_cpu();
    system.refresh_memory();
    system.refresh_disks_list();
    system.refresh_disks();
    system.refresh_processes();

    let cpu_percent = system.global_cpu_info().cpu_usage();
    let total_memory = system.total_memory() as f32;
    let used_memory = system.used_memory() as f32;
    let memory_percent = if total_memory > 0.0 {
        (used_memory / total_memory) * 100.0
    } else {
        0.0
    };

    let mut disk_percent = 0.0;
    for disk in system.disks() {
        let total = disk.total_space() as f32;
        let available = disk.available_space() as f32;
        if total > 0.0 {
            let used = ((total - available) / total) * 100.0;
            if used > disk_percent {
                disk_percent = used;
            }
        }
    }

    Metrics {
        cpu_percent,
        memory_percent,
        disk_percent,
        process_count: system.processes().len(),
    }
}

fn maybe_kill_process(system: &mut System, process_name: &str) -> Result<()> {
    for (pid, process) in system.processes() {
        if process.name() == process_name {
            warn!("killing process {} (pid={})", process_name, pid);
            let killed = process.kill();
            if !killed {
                warn!("failed to kill process {} (pid={})", process_name, pid);
            }
        }
    }
    Ok(())
}

fn evaluate_policy(cfg: &Config, system: &mut System, metrics: &Metrics) -> Result<()> {
    if metrics.cpu_percent > cfg.thresholds.cpu_percent {
        warn!(
            "CPU threshold exceeded: {:.2}% > {:.2}%",
            metrics.cpu_percent, cfg.thresholds.cpu_percent
        );
    }

    if metrics.memory_percent > cfg.thresholds.memory_percent {
        warn!(
            "Memory threshold exceeded: {:.2}% > {:.2}%",
            metrics.memory_percent, cfg.thresholds.memory_percent
        );
    }

    if metrics.disk_percent > cfg.thresholds.disk_percent {
        warn!(
            "Disk threshold exceeded: {:.2}% > {:.2}%",
            metrics.disk_percent, cfg.thresholds.disk_percent
        );
    }

    if cfg.actions.enable_kill && metrics.cpu_percent > cfg.thresholds.cpu_percent {
        maybe_kill_process(system, &cfg.actions.kill_process_name)?;
    }

    Ok(())
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let cfg = load_config("config.toml")?;
    info!("loaded config: {:?}", cfg);

    let mut system = System::new_all();
    let mut ticker = interval(Duration::from_millis(cfg.daemon.interval_ms));

    info!("resource daemon started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let metrics = collect_metrics(&mut system);
                info!(
                    "metrics cpu={:.2}% mem={:.2}% disk={:.2}% procs={}",
                    metrics.cpu_percent,
                    metrics.memory_percent,
                    metrics.disk_percent,
                    metrics.process_count
                );

                if let Err(e) = evaluate_policy(&cfg, &mut system, &metrics) {
                    error!("policy evaluation error: {:?}", e);
                }
            }

            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("resource daemon stopped");
    Ok(())
}
```

