```rust
use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    net::SocketAddr,
    path::Path,
    sync::Arc,
    time::Duration,
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{TcpListener, TcpStream},
    signal,
    sync::RwLock,
    time::interval,
};
use tracing::{error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    sample_interval_ms: u64,
    cpu_warn_pct: f32,
    mem_warn_pct: f32,
    disk_warn_pct: f32,
    load_warn: f32,
    control_bind: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval_ms: 1000,
            cpu_warn_pct: 85.0,
            mem_warn_pct: 90.0,
            disk_warn_pct: 90.0,
            load_warn: 8.0,
            control_bind: "127.0.0.1:7878".to_string(),
        }
    }
}

#[derive(Debug, Clone)]
struct Metrics {
    cpu_usage: f32,
    mem_usage: f32,
    disk_usage: f32,
    load_avg: f32,
}

impl Default for Metrics {
    fn default() -> Self {
        Self {
            cpu_usage: 0.0,
            mem_usage: 0.0,
            disk_usage: 0.0,
            load_avg: 0.0,
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let config = load_config("daemon.toml").unwrap_or_else(|_| Config::default());
    info!("Loaded config: {:?}", config);

    let metrics = Arc::new(RwLock::new(Metrics::default()));
    let config = Arc::new(config);

    let monitor_metrics = metrics.clone();
    let monitor_config = config.clone();
    let monitor_task = tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_metrics, monitor_config).await {
            error!("monitor loop failed: {:#}", e);
        }
    });

    let control_metrics = metrics.clone();
    let control_config = config.clone();
    let control_task = tokio::spawn(async move {
        if let Err(e) = control_server(control_metrics, control_config).await {
            error!("control server failed: {:#}", e);
        }
    });

    info!("Daemon started. Press Ctrl+C to stop.");
    signal::ctrl_c().await.context("failed to listen for Ctrl+C")?;
    info!("Shutdown signal received.");

    monitor_task.abort();
    control_task.abort();

    Ok(())
}

fn load_config<P: AsRef<Path>>(path: P) -> Result<Config> {
    let content = fs::read_to_string(path)?;
    let cfg: Config = toml::from_str(&content)?;
    Ok(cfg)
}

async fn monitor_loop(metrics: Arc<RwLock<Metrics>>, config: Arc<Config>) -> Result<()> {
    let mut sys = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_disks(DiskRefreshKind::everything()),
    );

    let mut ticker = interval(Duration::from_millis(config.sample_interval_ms));

    loop {
        ticker.tick().await;

        sys.refresh_cpu();
        sys.refresh_memory();
        sys.refresh_disks_list();
        sys.refresh_disks();

        let cpu_usage = sys.global_cpu_info().cpu_usage();
        let total_mem = sys.total_memory() as f32;
        let used_mem = sys.used_memory() as f32;
        let mem_usage = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let disk_usage = compute_disk_usage(&sys);
        let load_avg = sysinfo::System::load_average().one as f32;

        {
            let mut m = metrics.write().await;
            m.cpu_usage = cpu_usage;
            m.mem_usage = mem_usage;
            m.disk_usage = disk_usage;
            m.load_avg = load_avg;
        }

        if cpu_usage > config.cpu_warn_pct {
            warn!("High CPU usage: {:.2}%", cpu_usage);
            trigger_action("cpu", cpu_usage).await;
        }
        if mem_usage > config.mem_warn_pct {
            warn!("High memory usage: {:.2}%", mem_usage);
            trigger_action("memory", mem_usage).await;
        }
        if disk_usage > config.disk_warn_pct {
            warn!("High disk usage: {:.2}%", disk_usage);
            trigger_action("disk", disk_usage).await;
        }
        if load_avg > config.load_warn {
            warn!("High load average: {:.2}", load_avg);
            trigger_action("load", load_avg).await;
        }
    }
}

fn compute_disk_usage(sys: &System) -> f32 {
    let mut total = 0u64;
    let mut used = 0u64;

    for disk in sys.disks() {
        let t = disk.total_space();
        let a = disk.available_space();
        total += t;
        used += t.saturating_sub(a);
    }

    if total > 0 {
        (used as f32 / total as f32) * 100.0
    } else {
        0.0
    }
}

async fn trigger_action(resource: &str, value: f32) {
    // Placeholder for real management actions:
    // - cgroup throttling
    // - process priority adjustment
    // - service restart
    // - alerting
    info!("Triggering action for {} at value {:.2}", resource, value);
}

async fn control_server(metrics: Arc<RwLock<Metrics>>, config: Arc<Config>) -> Result<()> {
    let addr: SocketAddr = config.control_bind.parse()?;
    let listener = TcpListener::bind(addr).await?;
    info!("Control server listening on {}", addr);

    loop {
        let (stream, peer) = listener.accept().await?;
        let metrics = metrics.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, metrics).await {
                error!("client {} error: {:#}", peer, e);
            }
        });
    }
}

async fn handle_client(stream: TcpStream, metrics: Arc<RwLock<Metrics>>) -> Result<()> {
    let (read_half, mut write_half) = stream.into_split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    write_half
        .write_all(b"Resource daemon control interface\nCommands: stats, quit\n")
        .await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim().to_lowercase();
        match cmd.as_str() {
            "stats" => {
                let m = metrics.read().await;
                let resp = format!(
                    "cpu={:.2}% mem={:.2}% disk={:.2}% load={:.2}\n",
                    m.cpu_usage, m.mem_usage, m.disk_usage, m.load_avg
                );
                write_half.write_all(resp.as_bytes()).await?;
            }
            "quit" => {
                write_half.write_all(b"bye\n").await?;
                break;
            }
            _ => {
                write_half.write_all(b"unknown command\n").await?;
            }
        }
    }

    Ok(())
}
