use std::time::Duration;
use tokio::time::interval;
use sysinfo::{System, SystemExt, CpuExt};
use warp::Filter;

#[derive(serde::Serialize, Clone)]
struct Metrics {
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
}

#[tokio::main]
async fn main() {
    let metrics = std::sync::Arc::new(tokio::sync::RwLock::new(Metrics {
        cpu_usage: 0.0,
        total_memory: 0,
        used_memory: 0,
        total_swap: 0,
        used_swap: 0,
    }));

    let metrics_clone = metrics.clone();
    tokio::spawn(async move {
        let mut sys = System::new_all();
        let mut tick = interval(Duration::from_secs(1));

        loop {
            tick.tick().await;
            sys.refresh_cpu();
            sys.refresh_memory();

            let cpu = sys.global_cpu_info().cpu_usage();
            let total_memory = sys.total_memory();
            let used_memory = sys.used_memory();
            let total_swap = sys.total_swap();
            let used_swap = sys.used_swap();

            let mut guard = metrics_clone.write().await;
            *guard = Metrics {
                cpu_usage: cpu,
                total_memory,
                used_memory,
                total_swap,
                used_swap,
            };
        }
    });

    let metrics_route = {
        let metrics = metrics.clone();
        warp::path("metrics").and(warp::get()).and_then(move || {
            let metrics = metrics.clone();
            async move {
                let guard = metrics.read().await;
                Ok::<_, warp::Rejection>(warp::reply::json(&*guard))
            }
        })
    };

    println!("Monitoring daemon listening on http://127.0.0.1:3030/metrics");
    warp::serve(metrics_route).run(([127, 0, 0, 1], 3030)).await;
}
