## `src/main.rs`

```rust
use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::Path,
    sync::Arc,
    time::Duration,
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::{signal, sync::RwLock, time};
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    poll_interval_ms: PollInterval,
    cpu: Threshold,
    memory: Threshold,
    disk: Threshold,
    actions: Actions,
}

#[derive(Debug, Clone, Deserialize)]
struct PollInterval {
    value: u64,
}

#[derive(Debug, Clone, Deserialize)]
struct Threshold {
    warn_percent: f32,
    critical_percent: f32,
}

#[derive(Debug, Clone, Deserialize)]
struct Actions {
    log_only: bool,
    kill_top_cpu_process: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: PollInterval { value: 1000 },
            cpu: Threshold {
                warn_percent: 80.0,
                critical_percent: 95.0,
            },
            memory: Threshold {
                warn_percent: 80.0,
                critical_percent: 95.0,
            },
            disk: Threshold {
                warn_percent: 85.0,
                critical_percent: 95.0,
            },
            actions: Actions {
                log_only: true,
                kill_top_cpu_process: false,
            },
        }
    }
}

#[derive(Debug, Clone)]
struct ResourceSnapshot {
    cpu_usage: f32,
    memory_usage: f32,
    disk_usage: f32,
    top_process: Option<(i32, String, f32)>, // pid, name, cpu
}

struct Daemon {
    system: System,
    config: Arc<RwLock<Config>>,
}

impl Daemon {
    fn new(config: Config) -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        Self {
            system,
            config: Arc::new(RwLock::new(config)),
        }
    }

    fn collect_snapshot(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.system.refresh_processes();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory() as f32;
        let used_memory = self.system.used_memory() as f32;
        let memory_usage = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut disk_usage = 0.0;
        for disk in self.system.disks() {
            let total = disk.total_space() as f32;
            let avail = disk.available_space() as f32;
            if total > 0.0 {
                let used = ((total - avail) / total) * 100.0;
                if used > disk_usage {
                    disk_usage = used;
                }
            }
        }

        let top_process = self
            .system
            .processes()
            .iter()
            .max_by(|a, b| a.1.cpu_usage().partial_cmp(&b.1.cpu_usage()).unwrap())
            .map(|(pid, p)| {
                (
                    pid.as_u32() as i32,
                    p.name().to_string(),
                    p.cpu_usage(),
                )
            });

        ResourceSnapshot {
            cpu_usage,
            memory_usage,
            disk_usage,
            top_process,
        }
    }

    async fn handle_snapshot(&mut self, snapshot: ResourceSnapshot) {
        let cfg = self.config.read().await.clone();

        self.check_threshold("CPU", snapshot.cpu_usage, &cfg.cpu, &snapshot).await;
        self.check_threshold("Memory", snapshot.memory_usage, &cfg.memory, &snapshot).await;
        self.check_threshold("Disk", snapshot.disk_usage, &cfg.disk, &snapshot).await;

        if cfg.actions.kill_top_cpu_process {
            if let Some((pid, name, cpu)) = snapshot.top_process.clone() {
                if snapshot.cpu_usage >= cfg.cpu.critical_percent {
                    warn!(
                        pid = pid,
                        process = %name,
                        cpu = cpu,
                        "Critical CPU usage detected; would consider terminating top CPU process"
                    );
                    // Production: implement safe policy checks before killing.
                }
            }
        }
    }

    async fn check_threshold(
        &self,
        label: &str,
        value: f32,
        threshold: &Threshold,
        snapshot: &ResourceSnapshot,
    ) {
        if value >= threshold.critical_percent {
            error!(
                resource = label,
                usage = value,
                warn = threshold.warn_percent,
                critical = threshold.critical_percent,
                top_process = ?snapshot.top_process,
                "Critical resource usage"
            );
        } else if value >= threshold.warn_percent {
            warn!(
                resource = label,
                usage = value,
                warn = threshold.warn_percent,
                critical = threshold.critical_percent,
                "High resource usage"
            );
        } else {
            debug!(resource = label, usage = value, "Resource usage normal");
        }
    }

    async fn run(&mut self) -> Result<()> {
        let interval_ms = {
            let cfg = self.config.read().await;
            cfg.poll_interval_ms.value
        };

        let mut ticker = time::interval(Duration::from_millis(interval_ms));
        info!("Daemon started");

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snapshot = self.collect_snapshot();
                    self.handle_snapshot(snapshot).await;
                }
                _ = signal::ctrl_c() => {
                    info!("Shutdown signal received");
                    break;
                }
            }
        }

        Ok(())
    }
}

fn load_config(path: impl AsRef<Path>) -> Result<Config> {
    let path = path.as_ref();
    if !path.exists() {
        return Ok(Config::default());
    }

    let content = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {}", path.display()))?;
    let cfg: Config = toml::from_str(&content)
        .with_context(|| format!("failed to parse config file: {}", path.display()))?;
    Ok(cfg)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
        .init();

    let config = load_config("config.toml")?;
    info!(?config, "Loaded configuration");

    let mut daemon = Daemon::new(config);
    daemon.run().await
}
```

