```rust
use anyhow::Result;
use serde::Serialize;
use std::{
    collections::HashMap,
    sync::{Arc, RwLock},
    time::Duration,
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::time::interval;
use tracing::{error, info, warn};
use warp::Filter;

#[derive(Clone)]
struct Config {
    sample_interval: Duration,
    cpu_warn_pct: f32,
    mem_warn_pct: f32,
    disk_warn_pct: f32,
    max_processes: usize,
    metrics_port: u16,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval: Duration::from_secs(2),
            cpu_warn_pct: 85.0,
            mem_warn_pct: 90.0,
            disk_warn_pct: 90.0,
            max_processes: 1024,
            metrics_port: 9090,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disk_usage_pct: f32,
    process_count: usize,
}

impl Default for ResourceSnapshot {
    fn default() -> Self {
        Self {
            cpu_usage: 0.0,
            total_memory: 0,
            used_memory: 0,
            total_swap: 0,
            used_swap: 0,
            load_avg_one: 0.0,
            load_avg_five: 0.0,
            load_avg_fifteen: 0.0,
            disk_usage_pct: 0.0,
            process_count: 0,
        }
    }
}

struct DaemonState {
    snapshot: RwLock<ResourceSnapshot>,
}

impl DaemonState {
    fn new() -> Self {
        Self {
            snapshot: RwLock::new(ResourceSnapshot::default()),
        }
    }

    fn update(&self, snap: ResourceSnapshot) {
        if let Ok(mut guard) = self.snapshot.write() {
            *guard = snap;
        }
    }

    fn get(&self) -> ResourceSnapshot {
        self.snapshot
            .read()
            .map(|g| g.clone())
            .unwrap_or_default()
    }
}

fn collect_snapshot(sys: &mut System) -> ResourceSnapshot {
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_processes();
    sys.refresh_disks_list();
    sys.refresh_disks();

    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let total_memory = sys.total_memory();
    let used_memory = sys.used_memory();
    let total_swap = sys.total_swap();
    let used_swap = sys.used_swap();
    let load = System::load_average();

    let mut disk_usage_pct = 0.0;
    let mut total_disk = 0u64;
    let mut used_disk = 0u64;

    for disk in sys.disks() {
        let total = disk.total_space();
        let avail = disk.available_space();
        total_disk += total;
        used_disk += total.saturating_sub(avail);
    }

    if total_disk > 0 {
        disk_usage_pct = (used_disk as f32 / total_disk as f32) * 100.0;
    }

    let process_count = sys.processes().len();

    ResourceSnapshot {
        cpu_usage,
        total_memory,
        used_memory,
        total_swap,
        used_swap,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        disk_usage_pct,
        process_count,
    }
}

fn evaluate_and_manage(cfg: &Config, snap: &ResourceSnapshot, sys: &System) {
    if snap.cpu_usage > cfg.cpu_warn_pct {
        warn!("High CPU usage detected: {:.2}%", snap.cpu_usage);
    }

    let mem_pct = if snap.total_memory > 0 {
        (snap.used_memory as f32 / snap.total_memory as f32) * 100.0
    } else {
        0.0
    };

    if mem_pct > cfg.mem_warn_pct {
        warn!("High memory usage detected: {:.2}%", mem_pct);
    }

    if snap.disk_usage_pct > cfg.disk_warn_pct {
        warn!("High disk usage detected: {:.2}%", snap.disk_usage_pct);
    }

    if snap.process_count > cfg.max_processes {
        warn!(
            "Process count exceeded limit: {} > {}",
            snap.process_count, cfg.max_processes
        );
    }

    // Example management action:
    // Identify top CPU-consuming processes and log them.
    let mut top: Vec<_> = sys.processes().values().collect();
    top.sort_by(|a, b| b.cpu_usage().partial_cmp(&a.cpu_usage()).unwrap_or(std::cmp::Ordering::Equal));

    for proc_ in top.into_iter().take(5) {
        if proc_.cpu_usage() > 50.0 {
            warn!(
                "High CPU process: pid={} name={} cpu={:.2}%",
                proc_.pid(),
                proc_.name(),
                proc_.cpu_usage()
            );
        }
    }
}

async fn run_monitor(cfg: Config, state: Arc<DaemonState>) -> Result<()> {
    let mut sys = System::new_all();
    let mut ticker = interval(cfg.sample_interval);

    loop {
        ticker.tick().await;

        let snap = collect_snapshot(&mut sys);
        state.update(snap.clone());

        info!(
            "cpu={:.2}% mem={}/{} disk={:.2}% procs={}",
            snap.cpu_usage,
            snap.used_memory,
            snap.total_memory,
            snap.disk_usage_pct,
            snap.process_count
        );

        evaluate_and_manage(&cfg, &snap, &sys);
    }
}

fn with_state(
    state: Arc<DaemonState>,
) -> impl Filter<Extract = (Arc<DaemonState>,), Error = std::convert::Infallible> + Clone {
    warp::any().map(move || state.clone())
}

async fn run_http_server(state: Arc<DaemonState>, port: u16) {
    let metrics = warp::path("metrics")
        .and(warp::get())
        .and(with_state(state.clone()))
        .map(|state: Arc<DaemonState>| {
            let snap = state.get();
            let mem_pct = if snap.total_memory > 0 {
                (snap.used_memory as f32 / snap.total_memory as f32) * 100.0
            } else {
                0.0
            };

            let body = format!(
                concat!(
                    "# TYPE daemon_cpu_usage gauge\n",
                    "daemon_cpu_usage {}\n",
                    "# TYPE daemon_memory_usage_percent gauge\n",
                    "daemon_memory_usage_percent {}\n",
                    "# TYPE daemon_disk_usage_percent gauge\n",
                    "daemon_disk_usage_percent {}\n",
                    "# TYPE daemon_process_count gauge\n",
                    "daemon_process_count {}\n",
                    "# TYPE daemon_load_one gauge\n",
                    "daemon_load_one {}\n",
                    "# TYPE daemon_load_five gauge\n",
                    "daemon_load_five {}\n",
                    "# TYPE daemon_load_fifteen gauge\n",
                    "daemon_load_fifteen {}\n"
                ),
                snap.cpu_usage,
                mem_pct,
                snap.disk_usage_pct,
                snap.process_count,
                snap.load_avg_one,
                snap.load_avg_five,
                snap.load_avg_fifteen
            );

            warp::reply::with_header(body, "Content-Type", "text/plain; version=0.0.4")
        });

    let health = warp::path("health")
        .and(warp::get())
        .map(|| warp::reply::json(&serde_json::json!({"status": "ok"})));

    let routes = metrics.or(health);

    info!("HTTP server listening on 0.0.0.0:{}", port);
    warp::serve(routes).run(([0, 0, 0, 0], port)).await;
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg = Config::default();
    let state = Arc::new(DaemonState::new());

    let monitor_state = state.clone();
    let http_state = state.clone();

    let monitor_cfg = cfg.clone();
    let http_port = cfg.metrics_port;

    let monitor_task = tokio::spawn(async move {
        if let Err(e) = run_monitor(monitor_cfg, monitor_state).await {
            error!("monitor task failed: {:?}", e);
        }
    });

    let http_task = tokio::spawn(async move {
        run_http_server(http_state, http_port).await;
    });

    tokio::select! {
        _ = monitor_task => {},
        _ = http_task => {},
        _ = tokio::signal::ctrl_c() => {
            info!("shutdown signal received");
        }
    }

    Ok(())
}
