## `src/metrics.rs`

```rust
use serde::Serialize;
use sysinfo::{Disks, Networks, System};

#[derive(Debug, Clone, Serialize)]
pub struct Metrics {
    pub cpu_usage_pct: f32,
    pub memory_usage_pct: f32,
    pub total_memory_kb: u64,
    pub used_memory_kb: u64,
    pub disk_usage_pct: f32,
    pub network_rx_bytes: u64,
    pub network_tx_bytes: u64,
}

pub struct MetricsCollector {
    system: System,
    disks: Disks,
    networks: Networks,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let mut disks = Disks::new_with_refreshed_list();
        disks.refresh(true);

        let mut networks = Networks::new_with_refreshed_list();
        networks.refresh(true);

        Self {
            system,
            disks,
            networks,
        }
    }

    pub fn collect(&mut self) -> Metrics {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.disks.refresh(true);
        self.networks.refresh(true);

        let cpu_usage_pct = self.system.global_cpu_usage();
        let total_memory_kb = self.system.total_memory();
        let used_memory_kb = self.system.used_memory();
        let memory_usage_pct = if total_memory_kb > 0 {
            (used_memory_kb as f32 / total_memory_kb as f32) * 100.0
        } else {
            0.0
        };

        let mut disk_total = 0u64;
        let mut disk_used = 0u64;
        for disk in self.disks.list() {
            let total = disk.total_space();
            let avail = disk.available_space();
            disk_total += total;
            disk_used += total.saturating_sub(avail);
        }

        let disk_usage_pct = if disk_total > 0 {
            (disk_used as f32 / disk_total as f32) * 100.0
        } else {
            0.0
        };

        let mut rx = 0u64;
        let mut tx = 0u64;
        for (_, data) in self.networks.iter() {
            rx += data.received();
            tx += data.transmitted();
        }

        Metrics {
            cpu_usage_pct,
            memory_usage_pct,
            total_memory_kb,
            used_memory_kb,
            disk_usage_pct,
            network_rx_bytes: rx,
            network_tx_bytes: tx,
        }
    }
}
