## `src/control.rs`

```rust
use crate::metrics::Metrics;
use anyhow::Result;
use serde::{Deserialize, Serialize};
use tokio::{
    io::{AsyncReadExt, AsyncWriteExt},
    net::{UnixListener, UnixStream},
};

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
pub enum Command {
    GetMetrics,
    Ping,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct Response {
    pub ok: bool,
    pub message: String,
    pub metrics: Option<Metrics>,
}

pub async fn serve(socket_path: String, metrics: tokio::sync::watch::Receiver<Metrics>) -> Result<()> {
    let _ = std::fs::remove_file(&socket_path);
    let listener = UnixListener::bind(&socket_path)?;

    loop {
        let (stream, _) = listener.accept().await?;
        let rx = metrics.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, rx).await {
                tracing::warn!("control client error: {e}");
            }
        });
    }
}

async fn handle_client(mut stream: UnixStream, metrics: tokio::sync::watch::Receiver<Metrics>) -> Result<()> {
    let mut buf = vec![0u8; 4096];
    let n = stream.read(&mut buf).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: Command = serde_json::from_slice(&buf[..n])?;
    let resp = match cmd {
        Command::Ping => Response {
            ok: true,
            message: "pong".into(),
            metrics: None,
        },
        Command::GetMetrics => {
            let m = metrics.borrow().clone();
            Response {
                ok: true,
                message: "ok".into(),
                metrics: Some(m),
            }
        }
    };

    let out = serde_json::to_vec(&resp)?;
    stream.write_all(&out).await?;
    Ok(())
}
