## `src/daemon.rs`

```rust
use crate::{
    config::Config,
    control,
    metrics::{Metrics, MetricsCollector},
};
use anyhow::Result;
use tokio::{
    sync::watch,
    time::{self, Duration},
};
use tracing::{info, warn};

pub struct Daemon {
    cfg: Config,
    foreground: bool,
}

impl Daemon {
    pub fn new(cfg: Config, foreground: bool) -> Self {
        Self { cfg, foreground }
    }

    pub async fn run(self) -> Result<()> {
        if !self.foreground {
            info!("daemon mode requested; initial implementation stays in foreground");
        }

        let mut collector = MetricsCollector::new();
        let initial = collector.collect();
        let (tx, rx) = watch::channel(initial);

        let socket_path = self.cfg.socket_path.clone();
        tokio::spawn(async move {
            if let Err(e) = control::serve(socket_path, rx).await {
                tracing::error!("control server failed: {e}");
            }
        });

        let mut interval = time::interval(Duration::from_millis(self.cfg.interval_ms));

        loop {
            interval.tick().await;
            let m = collector.collect();

            if m.cpu_usage_pct > self.cfg.cpu_warn_pct {
                warn!("high CPU usage: {:.1}%", m.cpu_usage_pct);
            }
            if m.memory_usage_pct > self.cfg.mem_warn_pct {
                warn!("high memory usage: {:.1}%", m.memory_usage_pct);
            }
            if m.disk_usage_pct > self.cfg.disk_warn_pct {
                warn!("high disk usage: {:.1}%", m.disk_usage_pct);
            }

            let _ = tx.send(m);
        }
    }
}
