```rust
use crate::metrics::Metrics;
use anyhow::Result;
use sysinfo::{CpuExt, DiskExt, LoadAvg, System, SystemExt};

pub struct Monitor {
    system: System,
}

impl Monitor {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn collect(&mut self) -> Result<Metrics> {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_percent = self.system.global_cpu_info().cpu_usage();

        let total_mem = self.system.total_memory() as f32;
        let used_mem = self.system.used_memory() as f32;
        let memory_percent = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let disk_percent = self
            .system
            .disks()
            .iter()
            .map(|d| {
                let total = d.total_space() as f32;
                let avail = d.available_space() as f32;
                if total > 0.0 {
                    ((total - avail) / total) * 100.0
                } else {
                    0.0
                }
            })
            .fold(0.0, f32::max);

        let LoadAvg { one, .. } = System::load_average();
        let cores = self.system.cpus().len().max(1) as f32;
        let load_per_core = one as f32 / cores;

        Ok(Metrics {
            cpu_percent,
            memory_percent,
            disk_percent,
            load_per_core,
        })
    }
}
