## `src/daemon.rs`

```rust
use crate::{
    actions::ActionManager,
    config::Config,
    monitor::Monitor,
};
use anyhow::Result;
use tokio::time::{interval, Duration};
use tracing::{info, warn};

pub struct Daemon {
    config: Config,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub async fn run(self) -> Result<()> {
        let mut monitor = Monitor::new();
        let mut actions = ActionManager::new(self.config.action_cooldown_ms);
        let mut ticker = interval(Duration::from_millis(self.config.poll_interval_ms));

        info!("daemon started");

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    match monitor.collect() {
                        Ok(metrics) => {
                            info!(
                                "metrics cpu={:.2}% mem={:.2}% disk={:.2}% load/core={:.2}",
                                metrics.cpu_percent,
                                metrics.memory_percent,
                                metrics.disk_percent,
                                metrics.load_per_core
                            );

                            if metrics.is_cpu_high(self.config.cpu_warn_percent) {
                                warn!("CPU above threshold: {:.2}%", metrics.cpu_percent);
                            }
                            if metrics.is_memory_high(self.config.mem_warn_percent) {
                                warn!("Memory above threshold: {:.2}%", metrics.memory_percent);
                            }
                            if metrics.is_disk_high(self.config.disk_warn_percent) {
                                warn!("Disk above threshold: {:.2}%", metrics.disk_percent);
                            }
                            if metrics.is_load_high(self.config.load_warn_per_core) {
                                warn!("Load above threshold: {:.2}", metrics.load_per_core);
                            }

                            if self.config.enable_actions {
                                actions.evaluate_and_act(&metrics)?;
                            }
                        }
                        Err(e) => warn!("failed to collect metrics: {e:?}"),
                    }
                }
                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        info!("daemon stopped");
        Ok(())
    }
}
```

