```rust
use crate::metrics::{ProcessMetric, SystemMetrics};
use sysinfo::{DiskExt, ProcessExt, System, SystemExt};

pub struct Monitor {
    system: System,
}

impl Monitor {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn sample(&mut self) -> (SystemMetrics, Vec<ProcessMetric>) {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.system.refresh_processes();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();

        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let memory_usage = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let total_disk: u64 = self.system.disks().iter().map(|d| d.total_space()).sum();
        let used_disk: u64 = self
            .system
            .disks()
            .iter()
            .map(|d| d.total_space().saturating_sub(d.available_space()))
            .sum();

        let disk_usage = if total_disk > 0 {
            (used_disk as f32 / total_disk as f32) * 100.0
        } else {
            0.0
        };

        let metrics = SystemMetrics {
            cpu_usage,
            memory_usage,
            disk_usage,
            total_memory,
            used_memory,
            total_swap: self.system.total_swap(),
            used_swap: self.system.used_swap(),
        };

        let mut processes: Vec<ProcessMetric> = self
            .system
            .processes()
            .iter()
            .map(|(pid, proc_)| ProcessMetric {
                pid: pid.as_u32() as i32,
                name: proc_.name().to_string(),
                cpu_usage: proc_.cpu_usage(),
                memory: proc_.memory(),
            })
            .collect();

        processes.sort_by(|a, b| {
            b.cpu_usage
                .partial_cmp(&a.cpu_usage)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        (metrics, processes)
    }
}
