## `src/policy.rs`

```rust
use crate::{config::Config, metrics::{ProcessMetric, SystemMetrics}};

#[derive(Debug, Clone)]
pub enum Action {
    LogWarning(String),
    SuggestProcessThrottle { pid: i32, name: String, cpu_usage: f32 },
    SuggestMemoryPressureMitigation,
    SuggestDiskCleanup,
}

pub struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, sys: &SystemMetrics, procs: &[ProcessMetric]) -> Vec<Action> {
        let mut actions = Vec::new();

        if sys.cpu_usage >= self.config.cpu_warn_threshold {
            actions.push(Action::LogWarning(format!(
                "High CPU usage detected: {:.2}%",
                sys.cpu_usage
            )));

            for p in procs.iter().take(self.config.top_processes) {
                if p.cpu_usage > 20.0 {
                    actions.push(Action::SuggestProcessThrottle {
                        pid: p.pid,
                        name: p.name.clone(),
                        cpu_usage: p.cpu_usage,
                    });
                }
            }
        }

        if sys.memory_usage >= self.config.mem_warn_threshold {
            actions.push(Action::LogWarning(format!(
                "High memory usage detected: {:.2}%",
                sys.memory_usage
            )));
            actions.push(Action::SuggestMemoryPressureMitigation);
        }

        if sys.disk_usage >= self.config.disk_warn_threshold {
            actions.push(Action::LogWarning(format!(
                "High disk usage detected: {:.2}%",
                sys.disk_usage
            )));
            actions.push(Action::SuggestDiskCleanup);
        }

        actions
    }
}
