use crate::{
    actions::ActionExecutor,
    config::Config,
    monitor::Monitor,
    policy::PolicyEngine,
};
use tokio::time::{interval, Duration};
use tracing::info;

pub struct Daemon {
    config: Config,
    monitor: Monitor,
    policy: PolicyEngine,
    executor: ActionExecutor,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self {
            policy: PolicyEngine::new(config.clone()),
            monitor: Monitor::new(),
            executor: ActionExecutor::new(),
            config,
        }
    }

    pub async fn run(&mut self) {
        let mut ticker = interval(Duration::from_millis(self.config.sample_interval_ms));

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let (sys_metrics, processes) = self.monitor.sample();

                    info!(
                        cpu = sys_metrics.cpu_usage,
                        memory = sys_metrics.memory_usage,
                        disk = sys_metrics.disk_usage,
                        "sampled system metrics"
                    );

                    let actions = self.policy.evaluate(&sys_metrics, &processes);
                    self.executor.execute(&actions);
                }

                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }
    }
}
