use anyhow::{Context, Result};
use serde::Deserialize;
use std::{
    fs,
    path::Path,
    time::Duration,
};
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::time::interval;
use tracing::{debug, error, info, warn};

#[derive(Debug, Clone, Deserialize)]
struct Config {
    /// Polling interval in milliseconds
    poll_interval_ms: u64,

    /// CPU usage threshold percentage
    cpu_threshold: f32,

    /// Memory usage threshold percentage
    memory_threshold: f32,

    /// Disk usage threshold percentage
    disk_threshold: f32,

    /// Optional process name to watch
    watch_process: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: 1000,
            cpu_threshold: 85.0,
            memory_threshold: 90.0,
            disk_threshold: 90.0,
            watch_process: None,
        }
    }
}

impl Config {
    fn load(path: Option<&str>) -> Result<Self> {
        if let Some(path) = path {
            let content = fs::read_to_string(path)
                .with_context(|| format!("failed to read config file: {}", path))?;
            let cfg: Config = toml::from_str(&content)
                .with_context(|| format!("failed to parse config file: {}", path))?;
            Ok(cfg)
        } else {
            Ok(Self::default())
        }
    }
}

#[derive(Debug)]
struct ResourceSnapshot {
    cpu_usage: f32,
    memory_usage: f32,
    disk_usage: f32,
    total_memory: u64,
    used_memory: u64,
}

struct ResourceMonitor {
    system: System,
}

impl ResourceMonitor {
    fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    fn snapshot(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory();
        let used_memory = self.system.used_memory();
        let memory_usage = if total_memory > 0 {
            (used_memory as f32 / total_memory as f32) * 100.0
        } else {
            0.0
        };

        let mut total_disk = 0u64;
        let mut used_disk = 0u64;

        for disk in self.system.disks() {
            let total = disk.total_space();
            let available = disk.available_space();
            total_disk += total;
            used_disk += total.saturating_sub(available);
        }

        let disk_usage = if total_disk > 0 {
            (used_disk as f32 / total_disk as f32) * 100.0
        } else {
            0.0
        };

        ResourceSnapshot {
            cpu_usage,
            memory_usage,
            disk_usage,
            total_memory,
            used_memory,
        }
    }

    fn process_count_by_name(&mut self, name: &str) -> usize {
        self.system.refresh_processes();
        self.system
            .processes()
            .values()
            .filter(|p| p.name().eq_ignore_ascii_case(name))
            .count()
    }
}

async fn handle_thresholds(cfg: &Config, snap: &ResourceSnapshot, monitor: &mut ResourceMonitor) {
    if snap.cpu_usage >= cfg.cpu_threshold {
        warn!("CPU threshold exceeded: {:.2}%", snap.cpu_usage);
    }

    if snap.memory_usage >= cfg.memory_threshold {
        warn!(
            "Memory threshold exceeded: {:.2}% (used {} / total {})",
            snap.memory_usage, snap.used_memory, snap.total_memory
        );
    }

    if snap.disk_usage >= cfg.disk_threshold {
        warn!("Disk threshold exceeded: {:.2}%", snap.disk_usage);
    }

    if let Some(proc_name) = &cfg.watch_process {
        let count = monitor.process_count_by_name(proc_name);
        debug!("Process '{}' count: {}", proc_name, count);
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    let config_path = std::env::args().nth(1);
    let cfg = Config::load(config_path.as_deref())?;

    info!("Starting sysd with config: {:?}", cfg);

    let mut monitor = ResourceMonitor::new();
    let mut ticker = interval(Duration::from_millis(cfg.poll_interval_ms));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let snap = monitor.snapshot();

                info!(
                    "cpu={:.2}% memory={:.2}% disk={:.2}%",
                    snap.cpu_usage, snap.memory_usage, snap.disk_usage
                );

                handle_thresholds(&cfg, &snap, &mut monitor).await;
            }

            _ = tokio::signal::ctrl_c() => {
                info!("Shutdown signal received, exiting.");
                break;
            }
        }
    }

    Ok(())
}
