## `src/policy.rs`

```rust
use crate::{config::Config, metrics::Metrics};

#[derive(Debug)]
pub enum Action {
    LogWarning(String),
    ReclaimMemory,
    ReapProcesses,
    None,
}

pub struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, metrics: &Metrics) -> Vec<Action> {
        let mut actions = Vec::new();

        if metrics.cpu_usage > self.config.cpu_high_threshold {
            actions.push(Action::LogWarning(format!(
                "High CPU usage detected: {:.2}%",
                metrics.cpu_usage
            )));
        }

        if metrics.memory_usage > self.config.mem_high_threshold {
            actions.push(Action::LogWarning(format!(
                "High memory usage detected: {:.2}%",
                metrics.memory_usage
            )));
            actions.push(Action::ReclaimMemory);
        }

        if metrics.disk_usage > self.config.disk_high_threshold {
            actions.push(Action::LogWarning(format!(
                "High disk usage detected: {:.2}%",
                metrics.disk_usage
            )));
        }

        if self.config.enable_process_reaper && metrics.load_avg_1m > 10.0 {
            actions.push(Action::ReapProcesses);
        }

        if actions.is_empty() {
            actions.push(Action::None);
        }

        actions
    }
}
```

