use crate::{
    actions::ActionExecutor, config::Config, monitor::Monitor, policy::PolicyEngine,
};
use anyhow::Result;
use tokio::time::{sleep, Duration};
use tracing::info;

pub struct Daemon {
    config: Config,
    monitor: Monitor,
    policy: PolicyEngine,
    executor: ActionExecutor,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self {
            policy: PolicyEngine::new(config.clone()),
            monitor: Monitor::new(),
            executor: ActionExecutor::new(),
            config,
        }
    }

    pub async fn run(&mut self) -> Result<()> {
        let interval = Duration::from_millis(self.config.sample_interval_ms);

        loop {
            let metrics = self.monitor.sample();

            info!(
                cpu = metrics.cpu_usage,
                memory = metrics.memory_usage,
                disk = metrics.disk_usage,
                load1 = metrics.load_avg_1m,
                load5 = metrics.load_avg_5m,
                load15 = metrics.load_avg_15m,
                "sampled system metrics"
            );

            let actions = self.policy.evaluate(&metrics);
            for action in &actions {
                self.executor.execute(action)?;
            }

            tokio::select! {
                _ = sleep(interval) => {},
                _ = tokio::signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        Ok(())
    }
}
