use anyhow::Result;
use clap::Parser;
use serde::Serialize;
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};
use tokio::signal;
use tokio::time::interval;
use tracing::{error, info, warn};
use tracing_subscriber::{fmt, EnvFilter};

#[derive(Parser, Debug)]
#[command(name = "sysd", about = "High-performance OS resource monitoring daemon")]
struct Args {
    /// Polling interval in seconds
    #[arg(short, long, default_value_t = 5)]
    interval_secs: u64,

    /// CPU usage threshold percentage
    #[arg(long, default_value_t = 80.0)]
    cpu_threshold: f32,

    /// Memory usage threshold percentage
    #[arg(long, default_value_t = 80.0)]
    memory_threshold: f32,

    /// Disk usage threshold percentage
    #[arg(long, default_value_t = 90.0)]
    disk_threshold: f32,

    /// Enable JSON logs
    #[arg(long, default_value_t = true)]
    json_logs: bool,
}

#[derive(Debug, Serialize)]
struct ResourceSnapshot {
    timestamp: u64,
    cpu_usage: f32,
    memory_used_mb: u64,
    memory_total_mb: u64,
    memory_usage_pct: f32,
    disk_used_gb: u64,
    disk_total_gb: u64,
    disk_usage_pct: f32,
    process_count: usize,
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    let args = Args::parse();

    init_logging(args.json_logs);

    info!("starting sysd daemon");

    let mut system = System::new_all();
    system.refresh_all();

    let mut ticker = interval(Duration::from_secs(args.interval_secs));

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                if let Err(e) = collect_and_manage(&mut system, &args).await {
                    error!("monitoring cycle failed: {e:?}");
                }
            }
            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("sysd daemon stopped");
    Ok(())
}

fn init_logging(json_logs: bool) {
    let filter = EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info"));

    if json_logs {
        tracing_subscriber::registry()
            .with(filter)
            .with(fmt::layer().json())
            .init();
    } else {
        tracing_subscriber::registry()
            .with(filter)
            .with(fmt::layer())
            .init();
    }
}

async fn collect_and_manage(system: &mut System, args: &Args) -> Result<()> {
    // Refresh only what we need for lower overhead
    system.refresh_cpu();
    system.refresh_memory();
    system.refresh_disks_list();
    system.refresh_disks();
    system.refresh_processes();

    let cpu_usage = system.global_cpu_info().cpu_usage();
    let memory_total = system.total_memory() / 1024;
    let memory_used = system.used_memory() / 1024;
    let memory_usage_pct = if memory_total > 0 {
        (memory_used as f32 / memory_total as f32) * 100.0
    } else {
        0.0
    };

    let (disk_total, disk_used) = collect_disk_usage(system);
    let disk_usage_pct = if disk_total > 0 {
        (disk_used as f32 / disk_total as f32) * 100.0
    } else {
        0.0
    };

    let snapshot = ResourceSnapshot {
        timestamp: current_unix_ts(),
        cpu_usage,
        memory_used_mb: memory_used,
        memory_total_mb: memory_total,
        memory_usage_pct,
        disk_used_gb: disk_used / 1024,
        disk_total_gb: disk_total / 1024,
        disk_usage_pct,
        process_count: system.processes().len(),
    };

    log_snapshot(&snapshot);

    if snapshot.cpu_usage >= args.cpu_threshold {
        warn!(
            cpu = snapshot.cpu_usage,
            threshold = args.cpu_threshold,
            "cpu threshold exceeded"
        );
        // Placeholder for action hook:
        // e.g. throttle workloads, notify supervisor, spawn remediation task
    }

    if snapshot.memory_usage_pct >= args.memory_threshold {
        warn!(
            memory = snapshot.memory_usage_pct,
            threshold = args.memory_threshold,
            "memory threshold exceeded"
        );
        // Placeholder for action hook:
        // e.g. reclaim caches, kill runaway processes, notify orchestrator
    }

    if snapshot.disk_usage_pct >= args.disk_threshold {
        warn!(
            disk = snapshot.disk_usage_pct,
            threshold = args.disk_threshold,
            "disk threshold exceeded"
        );
        // Placeholder for action hook:
        // e.g. rotate logs, clean temp files, alert operator
    }

    Ok(())
}

fn collect_disk_usage(system: &System) -> (u64, u64) {
    let mut total = 0u64;
    let mut used = 0u64;

    for disk in system.disks() {
        let disk_total = disk.total_space() / (1024 * 1024 * 1024);
        let disk_available = disk.available_space() / (1024 * 1024 * 1024);
        let disk_used = disk_total.saturating_sub(disk_available);

        total += disk_total;
        used += disk_used;
    }

    (total, used)
}

fn log_snapshot(snapshot: &ResourceSnapshot) {
    info!(
        timestamp = snapshot.timestamp,
        cpu_usage = snapshot.cpu_usage,
        memory_used_mb = snapshot.memory_used_mb,
        memory_total_mb = snapshot.memory_total_mb,
        memory_usage_pct = snapshot.memory_usage_pct,
        disk_used_gb = snapshot.disk_used_gb,
        disk_total_gb = snapshot.disk_total_gb,
        disk_usage_pct = snapshot.disk_usage_pct,
        process_count = snapshot.process_count,
        "resource snapshot"
    );
}

fn current_unix_ts() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}
