```rust
use serde::Serialize;
use sysinfo::{CpuExt, DiskExt, ProcessExt, System, SystemExt};

#[derive(Debug, Clone, Serialize)]
pub struct ResourceSnapshot {
    pub cpu_usage_pct: f32,
    pub memory_usage_pct: f32,
    pub disk_usage_pct: f32,
    pub process_count: usize,
}

pub struct Monitor {
    system: System,
}

impl Monitor {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn sample(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage_pct = self.system.global_cpu_info().cpu_usage();

        let total_mem = self.system.total_memory() as f32;
        let used_mem = self.system.used_memory() as f32;
        let memory_usage_pct = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let mut disk_total = 0u64;
        let mut disk_used = 0u64;
        for disk in self.system.disks() {
            let total = disk.total_space();
            let avail = disk.available_space();
            disk_total += total;
            disk_used += total.saturating_sub(avail);
        }

        let disk_usage_pct = if disk_total > 0 {
            (disk_used as f32 / disk_total as f32) * 100.0
        } else {
            0.0
        };

        let process_count = self.system.processes().len();

        ResourceSnapshot {
            cpu_usage_pct,
            memory_usage_pct,
            disk_usage_pct,
            process_count,
        }
    }
}
