## `src/control.rs`

```rust
use crate::actions::Actions;
use crate::monitor::ResourceSnapshot;
use anyhow::Result;
use serde::{Deserialize, Serialize};
use std::path::Path;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{UnixListener, UnixStream};
use tokio::sync::watch;

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
pub enum Command {
    Status,
    Top { limit: usize },
    Kill { pid: i32 },
}

#[derive(Debug, Serialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Response {
    Status { snapshot: ResourceSnapshot },
    Top { processes: Vec<(i32, String, f32)> },
    Ok,
    Error { message: String },
}

pub async fn run_control_server(
    socket_path: &Path,
    snapshot_rx: watch::Receiver<ResourceSnapshot>,
    actions: Actions,
) -> Result<()> {
    if socket_path.exists() {
        std::fs::remove_file(socket_path)?;
    }

    let listener = UnixListener::bind(socket_path)?;
    tracing::info!("control socket listening at {:?}", socket_path);

    loop {
        let (stream, _) = listener.accept().await?;
        let rx = snapshot_rx.clone();
        let actions = Actions::new();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, rx, actions).await {
                tracing::error!("client error: {e:?}");
            }
        });
    }
}

async fn handle_client(
    stream: UnixStream,
    snapshot_rx: watch::Receiver<ResourceSnapshot>,
    actions: Actions,
) -> Result<()> {
    let (read_half, mut write_half) = stream.into_split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    reader.read_line(&mut line).await?;
    let cmd: Command = serde_json::from_str(&line)?;

    let resp = match cmd {
        Command::Status => Response::Status {
            snapshot: snapshot_rx.borrow().clone(),
        },
        Command::Top { limit } => Response::Top {
            processes: actions.list_top_processes(limit),
        },
        Command::Kill { pid } => match actions.kill_process_by_pid(pid) {
            Ok(_) => Response::Ok,
            Err(e) => Response::Error {
                message: e.to_string(),
            },
        },
    };

    let out = serde_json::to_string(&resp)? + "\n";
    write_half.write_all(out.as_bytes()).await?;
    Ok(())
}
```

