## `src/daemon.rs`

```rust
use crate::actions::Actions;
use crate::config::Config;
use crate::control::run_control_server;
use crate::monitor::{Monitor, ResourceSnapshot};
use anyhow::Result;
use tokio::sync::watch;
use tokio::time::{interval, Duration};

pub async fn run_daemon(config: Config) -> Result<()> {
    let mut monitor = Monitor::new();
    let actions = Actions::new();

    let initial = monitor.sample();
    let (snapshot_tx, snapshot_rx) = watch::channel::<ResourceSnapshot>(initial);

    let poll_interval = Duration::from_millis(config.poll_interval_ms);
    let mut ticker = interval(poll_interval);

    let socket_path = config.control_socket.clone();
    let control_task = tokio::spawn(async move {
        if let Err(e) = run_control_server(&socket_path, snapshot_rx, actions).await {
            tracing::error!("control server failed: {e:?}");
        }
    });

    tracing::info!("daemon started");

    loop {
        ticker.tick().await;

        let snapshot = monitor.sample();
        let _ = snapshot_tx.send(snapshot.clone());

        tracing::info!(
            cpu = snapshot.cpu_usage_pct,
            memory = snapshot.memory_usage_pct,
            disk = snapshot.disk_usage_pct,
            processes = snapshot.process_count,
            "resource snapshot"
        );

        if snapshot.cpu_usage_pct > config.cpu_warn_pct {
            tracing::warn!("cpu usage above threshold: {}", snapshot.cpu_usage_pct);
        }
        if snapshot.memory_usage_pct > config.mem_warn_pct {
            tracing::warn!("memory usage above threshold: {}", snapshot.memory_usage_pct);
        }
        if snapshot.disk_usage_pct > config.disk_warn_pct {
            tracing::warn!("disk usage above threshold: {}", snapshot.disk_usage_pct);
        }

        if control_task.is_finished() {
            tracing::error!("control server exited unexpectedly");
            break;
        }
    }

    Ok(())
}
