```rust
use crate::actions;
use crate::config::Config;
use crate::monitor::Monitor;
use anyhow::Result;
use tokio::time::{interval, Duration};
use tracing::{info, warn};

pub struct Daemon {
    config: Config,
    monitor: Monitor,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self {
            config,
            monitor: Monitor::new(),
        }
    }

    pub async fn run(&mut self) -> Result<()> {
        let mut ticker = interval(Duration::from_millis(self.config.interval_ms));

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snapshot = self.monitor.sample();

                    info!(
                        cpu = snapshot.cpu_usage,
                        memory = snapshot.memory_usage_percent,
                        load = snapshot.load_average,
                        "resource snapshot"
                    );

                    if snapshot.cpu_usage > self.config.cpu_threshold_percent {
                        warn!(
                            cpu = snapshot.cpu_usage,
                            threshold = self.config.cpu_threshold_percent,
                            "CPU usage above threshold"
                        );
                    }

                    if snapshot.memory_usage_percent > self.config.memory_threshold_percent {
                        warn!(
                            memory = snapshot.memory_usage_percent,
                            threshold = self.config.memory_threshold_percent,
                            "Memory usage above threshold"
                        );
                    }

                    if snapshot.load_average > self.config.load_threshold {
                        warn!(
                            load = snapshot.load_average,
                            threshold = self.config.load_threshold,
                            "Load average above threshold"
                        );
                    }

                    if self.config.enable_kill_heavy_processes {
                        for (pid, name, cpu) in &snapshot.top_processes {
                            if *cpu > self.config.max_process_cpu_percent {
                                let _ = actions::kill_process(*pid, name);
                            }
                        }
                    }
                }

                _ = tokio::signal::ctrl_c() => {
                    info!("Shutdown signal received");
                    break;
                }
            }
        }

        Ok(())
    }
}
