pub struct Monitor {
    cfg: Config,
    shared_metrics: Arc<RwLock<Metrics>>,
}

impl Monitor {
    pub fn new(cfg: Config, shared_metrics: Arc<RwLock<Metrics>>) -> Self {
        Self { cfg, shared_metrics }
    }

    pub async fn run(self) {
        let mut sys = System::new_all();

        loop {
            sys.refresh_all();

            let cpu_usage = sys.global_cpu_info().cpu_usage();
            let mem_total = sys.total_memory();
            let mem_used = sys.used_memory();
            let swap_total = sys.total_swap();
            let swap_used = sys.used_swap();

            let mut disk_total = 0u64;
            let mut disk_used = 0u64;
            for d in sys.disks() {
                disk_total += d.total_space();
                disk_used += d.total_space().saturating_sub(d.available_space());
            }

            let load = sys.load_average();
            let process_count = sys.processes().len();

            let metrics = Metrics {
                cpu_usage_pct: cpu_usage,
                mem_total_kb: mem_total,
                mem_used_kb: mem_used,
                swap_total_kb: swap_total,
                swap_used_kb: swap_used,
                disk_total_bytes: disk_total,
                disk_used_bytes: disk_used,
                load_avg_1: load.one,
                load_avg_5: load.five,
                load_avg_15: load.fifteen,
                process_count,
                timestamp_unix_ms: SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_millis(),
            };

            {
                let mut guard = self.shared_metrics.write();
                *guard = metrics.clone();
            }

            alerts::evaluate_alerts(&self.cfg, &metrics);
            info!("Metrics updated");

            sleep(Duration::from_millis(self.cfg.poll_interval_ms)).await;
        }
    }
}
