```rust
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::HashMap,
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};
use sysinfo::{CpuRefreshKind, DiskRefreshKind, Disks, ProcessRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::{mpsc, RwLock},
    time,
};
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Debug, Clone)]
struct Config {
    sample_interval: Duration,
    control_socket: PathBuf,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    disk_warn_threshold: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval: Duration::from_secs(2),
            control_socket: "/tmp/sysd.sock".into(),
            cpu_warn_threshold: 85.0,
            mem_warn_threshold: 90.0,
            disk_warn_threshold: 90.0,
        }
    }
}

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    timestamp_ms: u128,
    cpu_usage: f32,
    memory_used: u64,
    memory_total: u64,
    memory_percent: f32,
    swap_used: u64,
    swap_total: u64,
    disk_used: u64,
    disk_total: u64,
    disk_percent: f32,
    top_processes: Vec<ProcessStat>,
}

#[derive(Debug, Clone, Serialize)]
struct ProcessStat {
    pid: i32,
    name: String,
    cpu_usage: f32,
    memory: u64,
}

#[derive(Debug, Clone, Serialize)]
struct DaemonStatus {
    running: bool,
    last_snapshot: Option<ResourceSnapshot>,
    alerts: Vec<String>,
}

#[derive(Debug, Deserialize)]
#[serde(tag = "cmd", rename_all = "snake_case")]
enum ControlCommand {
    Status,
    SetThresholds {
        cpu_warn_threshold: Option<f32>,
        mem_warn_threshold: Option<f32>,
        disk_warn_threshold: Option<f32>,
    },
    Shutdown,
}

struct SharedState {
    config: RwLock<Config>,
    last_snapshot: RwLock<Option<ResourceSnapshot>>,
    alerts: RwLock<Vec<String>>,
    running: RwLock<bool>,
}

impl SharedState {
    fn new(config: Config) -> Self {
        Self {
            config: RwLock::new(config),
            last_snapshot: RwLock::new(None),
            alerts: RwLock::new(Vec::new()),
            running: RwLock::new(true),
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env())
        .init();

    let config = Config::default();
    let state = Arc::new(SharedState::new(config.clone()));

    cleanup_socket(&config.control_socket)?;
    let listener = UnixListener::bind(&config.control_socket)
        .with_context(|| format!("failed to bind control socket at {:?}", config.control_socket))?;

    info!("sysd starting");
    info!("control socket: {:?}", config.control_socket);

    let (shutdown_tx, mut shutdown_rx) = mpsc::channel::<()>(1);

    let monitor_state = state.clone();
    let monitor_shutdown_tx = shutdown_tx.clone();
    tokio::spawn(async move {
        if let Err(e) = monitor_loop(monitor_state, monitor_shutdown_tx).await {
            error!("monitor loop failed: {e:#}");
        }
    });

    let control_state = state.clone();
    let control_shutdown_tx = shutdown_tx.clone();
    tokio::spawn(async move {
        if let Err(e) = control_loop(listener, control_state, control_shutdown_tx).await {
            error!("control loop failed: {e:#}");
        }
    });

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("received Ctrl-C");
        }
        _ = shutdown_rx.recv() => {
            info!("shutdown requested");
        }
    }

    {
        let mut running = state.running.write().await;
        *running = false;
    }

    cleanup_socket(&config.control_socket)?;
    info!("sysd stopped");
    Ok(())
}

async fn monitor_loop(state: Arc<SharedState>, shutdown_tx: mpsc::Sender<()>) -> Result<()> {
    let cfg = { state.config.read().await.clone() };

    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory()
            .with_processes(ProcessRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    );

    let mut disks = Disks::new_with_refreshed_list();

    let mut interval = time::interval(cfg.sample_interval);
    interval.set_missed_tick_behavior(time::MissedTickBehavior::Delay);

    loop {
        interval.tick().await;

        if !*state.running.read().await {
            break;
        }

        let start = Instant::now();

        system.refresh_cpu();
        system.refresh_memory();
        system.refresh_processes();
        disks.refresh(true);

        let snapshot = build_snapshot(&system, &disks);
        let alerts = evaluate_policies(&snapshot, &cfg);

        {
            let mut last = state.last_snapshot.write().await;
            *last = Some(snapshot.clone());
        }
        {
            let mut a = state.alerts.write().await;
            *a = alerts.clone();
        }

        if !alerts.is_empty() {
            for alert in &alerts {
                warn!("{alert}");
            }
        }

        debug!(
            "sampled in {:?}, cpu={:.1}%, mem={:.1}%, disk={:.1}%",
            start.elapsed(),
            snapshot.cpu_usage,
            snapshot.memory_percent,
            snapshot.disk_percent
        );

        if snapshot.cpu_usage > 99.0 {
            let _ = shutdown_tx.send(()).await;
        }
    }

    Ok(())
}

fn build_snapshot(system: &System, disks: &Disks) -> ResourceSnapshot {
    let timestamp_ms = Instant::now().elapsed().as_millis();

    let cpu_usage = system.global_cpu_info().cpu_usage();

    let memory_total = system.total_memory();
    let memory_used = system.used_memory();
    let memory_percent = if memory_total > 0 {
        (memory_used as f32 / memory_total as f32) * 100.0
    } else {
        0.0
    };

    let swap_total = system.total_swap();
    let swap_used = system.used_swap();

    let mut disk_total = 0u64;
    let mut disk_used = 0u64;
    for disk in disks.list() {
        let total = disk.total_space();
        let avail = disk.available_space();
        disk_total += total;
        disk_used += total.saturating_sub(avail);
    }

    let disk_percent = if disk_total > 0 {
        (disk_used as f32 / disk_total as f32) * 100.0
    } else {
        0.0
    };

    let mut processes: Vec<ProcessStat> = system
        .processes()
        .iter()
        .map(|(pid, p)| ProcessStat {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_usage: p.cpu_usage(),
            memory: p.memory(),
        })
        .collect();

    processes.sort_by(|a, b| {
        b.cpu_usage
            .partial_cmp(&a.cpu_usage)
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    processes.truncate(5);

    ResourceSnapshot {
        timestamp_ms,
        cpu_usage,
        memory_used,
        memory_total,
        memory_percent,
        swap_used,
        swap_total,
        disk_used,
        disk_total,
        disk_percent,
        top_processes: processes,
    }
}

fn evaluate_policies(snapshot: &ResourceSnapshot, cfg: &Config) -> Vec<String> {
    let mut alerts = Vec::new();

    if snapshot.cpu_usage >= cfg.cpu_warn_threshold {
        alerts.push(format!(
            "high cpu usage: {:.1}% >= {:.1}%",
            snapshot.cpu_usage, cfg.cpu_warn_threshold
        ));
    }

    if snapshot.memory_percent >= cfg.mem_warn_threshold {
        alerts.push(format!(
            "high memory usage: {:.1}% >= {:.1}%",
            snapshot.memory_percent, cfg.mem_warn_threshold
        ));
    }

    if snapshot.disk_percent >= cfg.disk_warn_threshold {
        alerts.push(format!(
            "high disk usage: {:.1}% >= {:.1}%",
            snapshot.disk_percent, cfg.disk_warn_threshold
        ));
    }

    alerts
}

async fn control_loop(
    listener: UnixListener,
    state: Arc<SharedState>,
    shutdown_tx: mpsc::Sender<()>,
) -> Result<()> {
    loop {
        let (stream, _) = listener.accept().await?;
        let state = state.clone();
        let shutdown_tx = shutdown_tx.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, state, shutdown_tx).await {
                error!("control client error: {e:#}");
            }
        });

        if !*state.running.read().await {
            break;
        }
    }

    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    state: Arc<SharedState>,
    shutdown_tx: mpsc::Sender<()>,
) -> Result<()> {
    let (read_half, mut write_half) = stream.into_split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd: ControlCommand = serde_json::from_str(line.trim())?;

    match cmd {
        ControlCommand::Status => {
            let status = DaemonStatus {
                running: *state.running.read().await,
                last_snapshot: state.last_snapshot.read().await.clone(),
                alerts: state.alerts.read().await.clone(),
            };
            let payload = serde_json::to_string(&status)?;
            write_half.write_all(payload.as_bytes()).await?;
            write_half.write_all(b"\n").await?;
        }
        ControlCommand::SetThresholds {
            cpu_warn_threshold,
            mem_warn_threshold,
            disk_warn_threshold,
        } => {
            let mut cfg = state.config.write().await;
            if let Some(v) = cpu_warn_threshold {
                cfg.cpu_warn_threshold = v;
            }
            if let Some(v) = mem_warn_threshold {
                cfg.mem_warn_threshold = v;
            }
            if let Some(v) = disk_warn_threshold {
                cfg.disk_warn_threshold = v;
            }
            write_half.write_all(b"{\"ok\":true}\n").await?;
        }
        ControlCommand::Shutdown => {
            {
                let mut running = state.running.write().await;
                *running = false;
            }
            let _ = shutdown_tx.send(()).await;
            write_half.write_all(b"{\"ok\":true,\"shutdown\":true}\n").await?;
        }
    }

    Ok(())
}

fn cleanup_socket(path: &PathBuf) -> Result<()> {
    if path.exists() {
        std::fs::remove_file(path)
            .with_context(|| format!("failed to remove existing socket {:?}", path))?;
    }
    Ok(())
}
