```rust
use crate::metrics::Metrics;
use sysinfo::{Disks, Networks, System};

pub struct Monitor {
    system: System,
    disks: Disks,
    networks: Networks,
}

impl Monitor {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();

        let mut disks = Disks::new_with_refreshed_list();
        disks.refresh(true);

        let mut networks = Networks::new_with_refreshed_list();
        networks.refresh(true);

        Self {
            system,
            disks,
            networks,
        }
    }

    pub fn sample(&mut self) -> Metrics {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.disks.refresh(true);
        self.networks.refresh(true);

        let cpu_usage = self.system.global_cpu_usage();
        let total_memory = self.system.total_memory() as f32;
        let used_memory = self.system.used_memory() as f32;
        let memory_usage = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut disk_usage = 0.0;
        let mut disk_count = 0.0;
        for disk in self.disks.list() {
            let total = disk.total_space() as f32;
            let avail = disk.available_space() as f32;
            if total > 0.0 {
                disk_usage += ((total - avail) / total) * 100.0;
                disk_count += 1.0;
            }
        }
        if disk_count > 0.0 {
            disk_usage /= disk_count;
        }

        let mut rx = 0u64;
        let mut tx = 0u64;
        for (_, data) in self.networks.iter() {
            rx += data.received();
            tx += data.transmitted();
        }

        Metrics::new(cpu_usage, memory_usage, disk_usage, rx, tx)
    }
}
