use crate::{config::Config, metrics::Metrics};
use tracing::{info, warn};

pub struct ActionEngine {
    config: Config,
}

impl ActionEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, metrics: &Metrics) {
        if metrics.cpu_usage >= self.config.cpu_usage_threshold {
            warn!(
                cpu = metrics.cpu_usage,
                threshold = self.config.cpu_usage_threshold,
                "CPU usage threshold exceeded"
            );
            self.handle_high_cpu(metrics);
        }

        if metrics.memory_usage >= self.config.memory_usage_threshold {
            warn!(
                memory = metrics.memory_usage,
                threshold = self.config.memory_usage_threshold,
                "Memory usage threshold exceeded"
            );
            self.handle_high_memory(metrics);
        }

        if metrics.disk_usage >= self.config.disk_usage_threshold {
            warn!(
                disk = metrics.disk_usage,
                threshold = self.config.disk_usage_threshold,
                "Disk usage threshold exceeded"
            );
            self.handle_high_disk(metrics);
        }

        if metrics.network_rx_bytes >= self.config.network_rx_threshold_bytes {
            info!(
                rx = metrics.network_rx_bytes,
                threshold = self.config.network_rx_threshold_bytes,
                "Network RX threshold exceeded"
            );
        }

        if metrics.network_tx_bytes >= self.config.network_tx_threshold_bytes {
            info!(
                tx = metrics.network_tx_bytes,
                threshold = self.config.network_tx_threshold_bytes,
                "Network TX threshold exceeded"
            );
        }
    }

    fn handle_high_cpu(&self, _metrics: &Metrics) {
        // Placeholder for future policy:
        // - identify top CPU processes
        // - lower priority
