```rust
use crate::{actions::ActionEngine, config::Config, monitor::Monitor};
use anyhow::Result;
use tokio::time::{interval, Duration};
use tracing::info;

pub struct Daemon {
    monitor: Monitor,
    actions: ActionEngine,
    config: Config,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        let monitor = Monitor::new();
        let actions = ActionEngine::new(config.clone());

        Self {
            monitor,
            actions,
            config,
        }
    }

    pub async fn run(mut self) -> Result<()> {
        let mut ticker = interval(Duration::from_millis(self.config.sample_interval_ms));

        info!(
            interval_ms = self.config.sample_interval_ms,
            "System daemon started"
        );

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let metrics = self.monitor.sample();
                    info!(
                        cpu = metrics.cpu_usage,
                        memory = metrics.memory_usage,
                        disk = metrics.disk_usage,
                        rx = metrics.network_rx_bytes,
                        tx = metrics.network_tx_bytes,
                        "Sampled system metrics"
                    );
                    self.actions.evaluate(&metrics);
                }
                _ = tokio::signal::ctrl_c() => {
                    info!("Shutdown signal received");
                    break;
                }
            }
        }

        info!("System daemon stopped");
        Ok(())
    }
}
