```rust
use crate::metrics::Metrics;
use tracing::{info, warn};

#[derive(Debug, Clone)]
pub enum Action {
    LogWarning(String),
    SuggestCleanup,
    SuggestProcessReview,
}

pub fn evaluate(metrics: &Metrics) -> Vec<Action> {
    let mut actions = Vec::new();

    if metrics.cpu_usage > 85.0 {
        actions.push(Action::LogWarning(format!(
            "High CPU usage detected: {:.2}%",
            metrics.cpu_usage
        )));
        actions.push(Action::SuggestProcessReview);
    }

    if metrics.memory_usage > 85.0 {
        actions.push(Action::LogWarning(format!(
            "High memory usage detected: {:.2}%",
            metrics.memory_usage
        )));
        actions.push(Action::SuggestProcessReview);
    }

    if metrics.disk_usage > 90.0 {
        actions.push(Action::LogWarning(format!(
            "High disk usage detected: {:.2}%",
            metrics.disk_usage
        )));
        actions.push(Action::SuggestCleanup);
    }

    actions
}

pub fn execute(actions: &[Action]) {
    for action in actions {
        match action {
            Action::LogWarning(msg) => warn!("{msg}"),
            Action::SuggestCleanup => info!("Suggested action: cleanup disk space"),
            Action::SuggestProcessReview => info!("Suggested action: review top CPU/memory processes"),
        }
    }
}
