## `src/monitor.rs`

```rust
use crate::metrics::Metrics;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};

pub struct Monitor {
    system: System,
}

impl Monitor {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn sample(&mut self) -> Metrics {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory() as f32;
        let used_memory = self.system.used_memory() as f32;
        let memory_usage = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut disk_total = 0u64;
        let mut disk_used = 0u64;
        for disk in self.system.disks() {
            let total = disk.total_space();
            let available = disk.available_space();
            disk_total += total;
            disk_used += total.saturating_sub(available);
        }

        let disk_usage = if disk_total > 0 {
            (disk_used as f64 / disk_total as f64 * 100.0) as f32
        } else {
            0.0
        };

        let load_average = sysinfo::System::load_average().one;

        Metrics::new(cpu_usage, memory_usage, disk_usage, load_average)
    }
}
