## `src/main.rs`

```rust
use anyhow::{Context, Result};
use clap::Parser;
use serde::{Deserialize, Serialize};
use std::{
    path::PathBuf,
    sync::Arc,
    time::{Duration, Instant},
};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    sync::{RwLock, watch},
    task,
};
use tracing::{error, info, warn};
use tracing_subscriber::EnvFilter;

use sysinfo::{CpuRefreshKind, DiskRefreshKind, MemoryRefreshKind, RefreshKind, System};

#[derive(Parser, Debug)]
#[command(name = "sysmon-daemon")]
struct Args {
    /// Path to the Unix domain socket used for control/status requests
    #[arg(long, default_value = "/run/sysmon-daemon.sock")]
    socket: PathBuf,

    /// Sampling interval in seconds
    #[arg(long, default_value_t = 2)]
    interval_secs: u64,

    /// Log level filter, e.g. info, debug, trace
    #[arg(long, default_value = "info")]
    log_level: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    uptime_secs: u64,

    cpu_usage_percent: f32,
    memory_total_bytes: u64,
    memory_used_bytes: u64,
    memory_used_percent: f32,

    swap_total_bytes: u64,
    swap_used_bytes: u64,

    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,

    disk_total_bytes: u64,
    disk_available_bytes: u64,
    disk_used_percent: f32,

    process_count: usize,
}

impl Default for ResourceSnapshot {
    fn default() -> Self {
        Self {
            timestamp_unix_ms: 0,
            uptime_secs: 0,
            cpu_usage_percent: 0.0,
            memory_total_bytes: 0,
            memory_used_bytes: 0,
            memory_used_percent: 0.0,
            swap_total_bytes: 0,
            swap_used_bytes: 0,
            load_avg_one: 0.0,
            load_avg_five: 0.0,
            load_avg_fifteen: 0.0,
            disk_total_bytes: 0,
            disk_available_bytes: 0,
            disk_used_percent: 0.0,
            process_count: 0,
        }
    }
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(tag = "command", rename_all = "snake_case")]
enum ControlRequest {
    Status,
    Reload,
    Shutdown,
}

#[derive(Debug, Serialize, Deserialize)]
struct ControlResponse {
    ok: bool,
    message: String,
    snapshot: Option<ResourceSnapshot>,
}

#[derive(Clone)]
struct SharedState {
    snapshot: Arc<RwLock<ResourceSnapshot>>,
}

#[tokio::main]
async fn main() -> Result<()> {
    let args = Args::parse();

    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::new(args.log_level))
        .init();

    let socket_path = args.socket;
    if socket_path.exists() {
        std::fs::remove_file(&socket_path)
            .with_context(|| format!("failed to remove existing socket {:?}", socket_path))?;
    }

    let system = Arc::new(RwLock::new(System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything())
            .with_disks(DiskRefreshKind::everything()),
    )));

    let shared = SharedState {
        snapshot: Arc::new(RwLock::new(ResourceSnapshot::default())),
    };

    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    let sampler_handle = {
        let system = system.clone();
        let shared = shared.clone();
        let mut shutdown_rx = shutdown_rx.clone();
        let interval = Duration::from_secs(args.interval_secs.max(1));

        task::spawn(async move {
            let mut ticker = tokio::time::interval(interval);
            loop {
                tokio::select! {
                    _ = ticker.tick() => {
                        if let Err(e) = sample_resources(&system, &shared).await {
                            error!("sampling failed: {e:#}");
                        }
                    }
                    changed = shutdown_rx.changed() => {
                        if changed.is_ok() && *shutdown_rx.borrow() {
                            info!("sampler shutting down");
                            break;
                        }
                    }
                }
            }
        })
    };

    let listener = UnixListener::bind(&socket_path)
        .with_context(|| format!("failed to bind socket {:?}", socket_path))?;

    info!("sysmon-daemon started");
    info!("control socket: {:?}", socket_path);

    let server_handle = {
        let shared = shared.clone();
        let mut shutdown_rx = shutdown_rx.clone();
        let shutdown_tx = shutdown_tx.clone();

        task::spawn(async move {
            loop {
                tokio::select! {
                    accept_res = listener.accept() => {
                        match accept_res {
                            Ok((stream, _addr)) => {
                                let shared = shared.clone();
                                let shutdown_tx = shutdown_tx.clone();
                                task::spawn(async move {
                                    if let Err(e) = handle_client(stream, shared, shutdown_tx).await {
                                        warn!("client handling failed: {e:#}");
                                    }
                                });
                            }
                            Err(e) => {
                                error!("accept failed: {e:#}");
                                break;
                            }
                        }
                    }
                    changed = shutdown_rx.changed() => {
                        if changed.is_ok() && *shutdown_rx.borrow() {
                            info!("server shutting down");
                            break;
                        }
                    }
                }
            }
        })
    };

    tokio::signal::ctrl_c().await?;
    info!("received termination signal");

    let _ = shutdown_tx.send(true);

    let _ = sampler_handle.await;
    let _ = server_handle.await;

    if socket_path.exists() {
        let _ = std::fs::remove_file(&socket_path);
    }

    info!("sysmon-daemon exited cleanly");
    Ok(())
}

async fn sample_resources(system: &Arc<RwLock<System>>, shared: &SharedState) -> Result<()> {
    let mut sys = system.write().await;

    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_disks_list();
    sys.refresh_disks();

    let timestamp_unix_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)?
        .as_millis();

    let uptime_secs = System::uptime();
    let cpu_usage_percent = sys.global_cpu_info().cpu_usage();

    let memory_total_bytes = sys.total_memory() * 1024;
    let memory_used_bytes = sys.used_memory() * 1024;
    let memory_used_percent = if memory_total_bytes > 0 {
        (memory_used_bytes as f32 / memory_total_bytes as f32) * 100.0
    } else {
        0.0
    };

    let swap_total_bytes = sys.total_swap() * 1024;
    let swap_used_bytes = sys.used_swap() * 1024;

    let load = System::load_average();

    let mut disk_total_bytes = 0u64;
    let mut disk_available_bytes = 0u64;
    for disk in sys.disks() {
        disk_total_bytes += disk.total_space();
        disk_available_bytes += disk.available_space();
    }
    let disk_used_bytes = disk_total_bytes.saturating_sub(disk_available_bytes);
    let disk_used_percent = if disk_total_bytes > 0 {
        (disk_used_bytes as f32 / disk_total_bytes as f32) * 100.0
    } else {
        0.0
    };

    let process_count = sys.processes().len();

    let snapshot = ResourceSnapshot {
        timestamp_unix_ms,
        uptime_secs,
        cpu_usage_percent,
        memory_total_bytes,
        memory_used_bytes,
        memory_used_percent,
        swap_total_bytes,
        swap_used_bytes,
        load_avg_one: load.one,
        load_avg_five: load.five,
        load_avg_fifteen: load.fifteen,
        disk_total_bytes,
        disk_available_bytes,
        disk_used_percent,
        process_count,
    };

    *shared.snapshot.write().await = snapshot;
    Ok(())
}

async fn handle_client(
    stream: UnixStream,
    shared: SharedState,
    shutdown_tx: watch::Sender<bool>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let req: ControlRequest = serde_json::from_str(line.trim())
        .context("failed to parse control request")?;

    match req {
        ControlRequest::Status => {
            let snapshot = shared.snapshot.read().await.clone();
            let resp = ControlResponse {
                ok: true,
                message: "ok".to_string(),
                snapshot: Some(snapshot),
            };
            let json = serde_json::to_string(&resp)?;
            writer.write_all(json.as_bytes()).await?;
            writer.write_all(b"\n").await?;
        }
        ControlRequest::Reload => {
            let resp = ControlResponse {
                ok: true,
                message: "reload requested".to_string(),
                snapshot: None,
            };
            let json = serde_json::to_string(&resp)?;
            writer.write_all(json.as_bytes()).await?;
            writer.write_all(b"\n").await?;
        }
        ControlRequest::Shutdown => {
            let _ = shutdown_tx.send(true);
            let resp = ControlResponse {
                ok: true,
                message: "shutdown requested".to_string(),
                snapshot: None,
            };
            let json = serde_json::to_string(&resp)?;
            writer.write_all(json.as_bytes()).await?;
            writer.write_all(b"\n").await?;
        }
    }

    Ok(())
}
