use anyhow::Result;
use clap::Parser;
use serde::Serialize;
use std::time::Duration;
use sysinfo::{CpuRefreshKind, DiskRefreshKind, MemoryRefreshKind, RefreshKind, System};
use tokio::signal;
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Parser, Debug)]
#[command(name = "sysd", about = "High-performance OS resource monitoring daemon")]
struct Args {
    /// Sampling interval in seconds
    #[arg(short, long, default_value_t = 2)]
    interval_secs: u64,

    /// CPU usage threshold percentage for warning
    #[arg(long, default_value_t = 85.0)]
    cpu_warn: f32,

    /// Memory usage threshold percentage for warning
    #[arg(long, default_value_t = 85.0)]
    mem_warn: f32,

    /// Disk usage threshold percentage for warning
    #[arg(long, default_value_t = 90.0)]
    disk_warn: f32,

    /// Emit JSON instead of human-readable logs
    #[arg(long, default_value_t = false)]
    json: bool,
}

#[derive(Debug, Serialize)]
struct ResourceSnapshot {
    timestamp_unix_ms: u128,
    cpu_usage_percent: f32,
    memory_total_bytes: u64,
    memory_used_bytes: u64,
    memory_usage_percent: f32,
    swap_total_bytes: u64,
    swap_used_bytes: u64,
    load_avg_one: f64,
    load_avg_five: f64,
    load_avg_fifteen: f64,
    disks: Vec<DiskSnapshot>,
}

#[derive(Debug, Serialize)]
struct DiskSnapshot {
    name: String,
    mount_point: String,
    total_space: u64,
    available_space: u64,
    used_space: u64,
    usage_percent: f32,
}

struct Daemon {
    system: System,
    args: Args,
}

impl Daemon {
    fn new(args: Args) -> Self {
        let refresh = RefreshKind::new()
            .with_cpu(CpuRefreshKind::new())
            .with_memory(MemoryRefreshKind::new())
            .with_disks(DiskRefreshKind::new());

        let system = System::new_with_specifics(refresh);

        Self { system, args }
    }

    fn snapshot(&mut self) -> ResourceSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage_percent = self.system.global_cpu_info().cpu_usage();
        let memory_total_bytes = self.system.total_memory() * 1024;
        let memory_used_bytes = self.system.used_memory() * 1024;
        let memory_usage_percent = if memory_total_bytes > 0 {
            (memory_used_bytes as f32 / memory_total_bytes as f32) * 100.0
        } else {
            0.0
        };

        let swap_total_bytes = self.system.total_swap() * 1024;
        let swap_used_bytes = self.system.used_swap() * 1024;

        let load_avg = System::load_average();

        let disks = self
            .system
            .disks()
            .iter()
            .map(|disk| {
                let total_space = disk.total_space();
                let available_space = disk.available_space();
                let used_space = total_space.saturating_sub(available_space);
                let usage_percent = if total_space > 0 {
                    (used_space as f32 / total_space as f32) * 100.0
                } else {
                    0.0
                };

                DiskSnapshot {
                    name: disk.name().to_string_lossy().to_string(),
                    mount_point: disk.mount_point().to_string_lossy().to_string(),
                    total_space,
                    available_space,
                    used_space,
                    usage_percent,
                }
            })
            .collect();

        ResourceSnapshot {
            timestamp_unix_ms: std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis(),
            cpu_usage_percent,
            memory_total_bytes,
            memory_used_bytes,
            memory_usage_percent,
            swap_total_bytes,
            swap_used_bytes,
            load_avg_one: load_avg.one,
            load_avg_five: load_avg.five,
            load_avg_fifteen: load_avg.fifteen,
            disks,
        }
    }

    fn evaluate_thresholds(&self, snap: &ResourceSnapshot) {
        if snap.cpu_usage_percent >= self.args.cpu_warn {
            warn!(
                cpu = snap.cpu_usage_percent,
                threshold = self.args.cpu_warn,
                "CPU usage above threshold"
            );
        }

        if snap.memory_usage_percent >= self.args.mem_warn {
            warn!(
                memory = snap.memory_usage_percent,
                threshold = self.args.mem_warn,
                "Memory usage above threshold"
            );
        }

        for disk in &snap.disks {
            if disk.usage_percent >= self.args.disk_warn {
                warn!(
                    disk = %disk.name,
                    mount = %disk.mount_point,
                    usage = disk.usage_percent,
                    threshold = self.args.disk_warn,
                    "Disk usage above threshold"
                );
            }
        }
    }

    async fn run(&mut self) -> Result<()> {
        let mut ticker = interval(Duration::from_secs(self.args.interval_secs));

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snap = self.snapshot();
                    self.evaluate_thresholds(&snap);

                    if self.args.json {
                        println!("{}", serde_json::to_string(&snap)?);
                    } else {
                        info!(
                            cpu = snap.cpu_usage_percent,
                            mem = snap.memory_usage_percent,
                            load1 = snap.load_avg_one,
                            load5 = snap.load_avg_five,
                            load15 = snap.load_avg_fifteen,
                            "resource snapshot"
                        );
                    }
                }
                _ = signal::ctrl_c() => {
                    info!("shutdown signal received");
                    break;
                }
            }
        }

        Ok(())
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "info".into()),
        )
        .init();

    let args = Args::parse();
    let mut daemon = Daemon::new(args);

    info!("starting sysd");
    daemon.run().await?;
    info!("sysd stopped");

    Ok(())
}
```

