```rust
use serde::Serialize;
use sysinfo::{CpuExt, DiskExt, NetworkExt, NetworksExt, System, SystemExt};

#[derive(Debug, Clone, Serialize)]
pub struct MetricsSnapshot {
    pub cpu_usage: f32,
    pub memory_used: u64,
    pub memory_total: u64,
    pub memory_usage_percent: f32,
    pub disk_used: u64,
    pub disk_total: u64,
    pub disk_usage_percent: f32,
    pub network_received: u64,
    pub network_transmitted: u64,
}

pub struct MetricsCollector {
    system: System,
}

impl MetricsCollector {
    pub fn new() -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system }
    }

    pub fn collect(&mut self) -> MetricsSnapshot {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
        self.system.refresh_networks_list();
        self.system.refresh_networks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();

        let memory_total = self.system.total_memory();
        let memory_used = self.system.used_memory();
        let memory_usage_percent = if memory_total > 0 {
            (memory_used as f32 / memory_total as f32) * 100.0
        } else {
            0.0
        };

        let mut disk_total = 0u64;
        let mut disk_used = 0u64;
        for disk in self.system.disks() {
            let total = disk.total_space();
            let available = disk.available_space();
            disk_total += total;
            disk_used += total.saturating_sub(available);
        }

        let disk_usage_percent = if disk_total > 0 {
            (disk_used as f32 / disk_total as f32) * 100.0
        } else {
            0.0
        };

        let mut network_received = 0u64;
        let mut network_transmitted = 0u64;
        for (_name, data) in self.system.networks() {
            network_received += data.received();
            network_transmitted += data.transmitted();
        }

        MetricsSnapshot {
            cpu_usage,
            memory_used,
            memory_total,
            memory_usage_percent,
            disk_used,
            disk_total,
            disk_usage_percent,
            network_received,
            network_transmitted,
        }
    }
}
