## `src/daemon.rs`

```rust
use crate::config::Config;
use crate::metrics::MetricsCollector;
use crate::policy::PolicyEngine;
use anyhow::Result;
use tokio::time::{interval, Duration};
use tracing::info;

pub struct Daemon {
    config: Config,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub async fn run(self) -> Result<()> {
        let mut collector = MetricsCollector::new();
        let policy = PolicyEngine::new(self.config.clone());
        let mut ticker = interval(Duration::from_millis(self.config.interval_ms));

        info!(
            interval_ms = self.config.interval_ms,
            "Daemon started"
        );

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let snapshot = collector.collect();
                    tracing::info!(
                        cpu_usage = snapshot.cpu_usage,
                        memory_used = snapshot.memory_used,
                        memory_total = snapshot.memory_total,
                        memory_usage_percent = snapshot.memory_usage_percent,
                        disk_used = snapshot.disk_used,
                        disk_total = snapshot.disk_total,
                        disk_usage_percent = snapshot.disk_usage_percent,
                        network_received = snapshot.network_received,
                        network_transmitted = snapshot.network_transmitted,
                        "Collected metrics"
                    );

                    policy.evaluate(&snapshot);
                }

                _ = tokio::signal::ctrl_c() => {
                    info!("Shutdown signal received");
                    break;
                }
            }
        }

        info!("Daemon stopped");
        Ok(())
    }
}
```

