use anyhow::{Context, Result};
use serde::Deserialize;
use std::{fs, path::Path};

#[derive(Debug, Clone, Deserialize)]
pub struct Config {
    pub poll_interval_ms: u64,
    pub cpu_high_watermark: f32,
    pub mem_high_watermark: f32,
    pub load_high_watermark: f32,
    pub enable_actions: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            poll_interval_ms: 1000,
            cpu_high_watermark: 90.0,
            mem_high_watermark: 90.0,
            load_high_watermark: 8.0,
            enable_actions: false,
        }
    }
}

impl Config {
    pub fn load_default() -> Result<Self> {
        let path = Path::new("/etc/sysd.toml");
        if path.exists() {
            let raw = fs::read_to_string(path)
                .with_context(|| format!("failed to read config: {}", path.display()))?;
            let cfg: Self = toml::from_str(&raw)
                .with_context(|| format!("failed to parse config: {}", path.display()))?;
            Ok(cfg)
        } else {
            Ok(Self::default())
        }
    }
}
