use crate::metrics::SystemMetrics;
use anyhow::Result;
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, RefreshKind, System};

pub struct Monitor {
    system: System,
}

impl Monitor {
    pub fn new() -> Self {
        let refresh = RefreshKind::nothing()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything());

        let system = System::new_with_specifics(refresh);
        Self { system }
    }

    pub fn collect(&mut self) -> Result<SystemMetrics> {
        self.system.refresh_cpu_usage();
        self.system.refresh_memory();
        self.system.refresh_processes();

        let cpu_usage_percent = self.system.global_cpu_usage();
        let memory_usage_percent = if self.system.total_memory() > 0 {
            (self.system.used_memory() as f32 / self.system.total_memory() as f32) * 100.0
        } else {
            0.0
        };

        let load = System::load_average();

        Ok(SystemMetrics {
            cpu_usage_percent,
            memory_usage_percent,
            load_avg_1m: load.one,
            load_avg_5m: load.five,
            load_avg_15m: load.fifteen,
            total_memory_kb: self.system.total_memory(),
            used_memory_kb: self.system.used_memory(),
            total_swap_kb: self.system.total_swap(),
            used_swap_kb: self.system.used_swap(),
            process_count: self.system.processes().len(),
        })
    }
}
