```rust
use crate::{config::Config, metrics::SystemMetrics};
use tracing::{info, warn};

#[derive(Debug, Clone)]
pub enum Action {
    LogOnly,
    SuggestThrottle,
    SuggestMemoryPressureMitigation,
}

pub struct PolicyEngine {
    cfg: Config,
}

impl PolicyEngine {
    pub fn new(cfg: Config) -> Self {
        Self { cfg }
    }

    pub fn evaluate(&self, m: &SystemMetrics) -> Vec<Action> {
        let mut actions = Vec::new();

        if m.cpu_usage_percent >= self.cfg.cpu_high_watermark {
            actions.push(Action::SuggestThrottle);
        }

        if m.memory_usage_percent >= self.cfg.mem_high_watermark {
            actions.push(Action::SuggestMemoryPressureMitigation);
        }

        if m.load_avg_1m >= self.cfg.load_high_watermark {
            actions.push(Action::LogOnly);
        }

        actions
    }

    pub fn apply(&self, metrics: &SystemMetrics, actions: &[Action]) {
        if actions.is_empty() {
            return;
        }

        for action in actions {
            match action {
                Action::LogOnly => {
                    info!(
                        cpu = metrics.cpu_usage_percent,
                        mem = metrics.memory_usage_percent,
                        load1 = metrics.load_avg_1m,
                        "system load elevated"
                    );
                }
                Action::SuggestThrottle => {
                    warn!(
                        cpu = metrics.cpu_usage_percent,
                        "cpu usage above threshold; throttling policy may be needed"
                    );
                }
                Action::SuggestMemoryPressureMitigation => {
                    warn!(
                        mem = metrics.memory_usage_percent,
                        "memory usage above threshold; reclaim/oom policy may be needed"
                    );
                }
            }
        }
    }
}
