## `src/daemon.rs`

```rust
use crate::{config::Config, monitor::Monitor, policy::PolicyEngine, util::sleep_ms};
use anyhow::Result;
use tracing::{error, info};

pub async fn run(cfg: Config) -> Result<()> {
    info!(?cfg, "starting sysd");

    let mut monitor = Monitor::new();
    let policy = PolicyEngine::new(cfg.clone());

    let mut ticker = tokio::time::interval(std::time::Duration::from_millis(cfg.poll_interval_ms));
    ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);

    loop {
        tokio::select! {
            _ = tokio::signal::ctrl_c() => {
                info!("shutdown requested");
                break;
            }
            _ = ticker.tick() => {
                match monitor.collect() {
                    Ok(metrics) => {
                        info!(
                            cpu = metrics.cpu_usage_percent,
                            mem = metrics.memory_usage_percent,
                            load1 = metrics.load_avg_1m,
                            procs = metrics.process_count,
                            "collected metrics"
                        );

                        let actions = policy.evaluate(&metrics);
                        if cfg.enable_actions {
                            policy.apply(&metrics, &actions);
                        }
                    }
                    Err(e) => {
                        error!(error = %e, "failed to collect metrics");
                    }
                }
            }
        }
    }

    sleep_ms(100).await;
    info!("sysd stopped");
    Ok(())
}
```

