## `src/monitor.rs`

```rust
use crate::config::Config;
use crate::actions::{Action, execute};
use anyhow::Result;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::time::{interval, Duration};
use tracing::{info, warn};

#[derive(Debug, Clone)]
pub struct Metrics {
    pub cpu_pct: f32,
    pub mem_pct: f32,
    pub disk_pct: f32,
}

pub struct Monitor {
    system: System,
    config: Config,
}

impl Monitor {
    pub fn new(config: Config) -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system, config }
    }

    fn collect(&mut self) -> Metrics {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_pct = self.system.global_cpu_info().cpu_usage();
        let mem_total = self.system.total_memory() as f32;
        let mem_used = self.system.used_memory() as f32;
        let mem_pct = if mem_total > 0.0 { (mem_used / mem_total) * 100.0 } else { 0.0 };

        let mut disk_used_pct = 0.0f32;
        for disk in self.system.disks() {
            let total = disk.total_space() as f32;
            let avail = disk.available_space() as f32;
            if total > 0.0 {
                let used = ((total - avail) / total) * 100.0;
                if used > disk_used_pct {
                    disk_used_pct = used;
                }
            }
        }

        Metrics {
            cpu_pct,
            mem_pct,
            disk_pct: disk_used_pct,
        }
    }

    pub async fn run(mut self) -> Result<()> {
        let mut tick = interval(Duration::from_millis(self.config.sample_interval_ms));

        loop {
            tick.tick().await;
            let m = self.collect();

            info!(
                cpu = m.cpu_pct,
                mem = m.mem_pct,
                disk = m.disk_pct,
                "resource sample"
            );

            if m.cpu_pct >= self.config.cpu_warn_pct {
                warn!(cpu = m.cpu_pct, "cpu threshold exceeded");
                execute(Action::Notify(format!("CPU high: {:.1}%", m.cpu_pct))).await?;
            }

            if m.mem_pct >= self.config.mem_warn_pct {
                warn!(mem = m.mem_pct, "memory threshold exceeded");
                execute(Action::Notify(format!("Memory high: {:.1}%", m.mem_pct))).await?;
            }

            if m.disk_pct >= self.config.disk_warn_pct {
                warn!(disk = m.disk_pct, "disk threshold exceeded");
                execute(Action::Notify(format!("Disk high: {:.1}%", m.disk_pct))).await?;
            }
        }
    }
}
```

