## `src/control.rs`

```rust
use crate::config::Config;
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::fs;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{UnixListener, UnixStream};
use tracing::info;

#[derive(Debug, Serialize, Deserialize)]
pub enum Command {
    Status,
    Reload,
    Shutdown,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct Response {
    pub ok: bool,
    pub message: String,
}

async fn handle_client(mut stream: UnixStream) -> Result<()> {
    let mut buf = Vec::new();
    stream.read_to_end(&mut buf).await?;
    let cmd: Command = serde_json::from_slice(&buf).context("invalid command")?;

    let resp = match cmd {
        Command::Status => Response {
            ok: true,
            message: "daemon running".to_string(),
        },
        Command::Reload => Response {
            ok: true,
            message: "reload requested".to_string(),
        },
        Command::Shutdown => Response {
            ok: true,
            message: "shutdown requested".to_string(),
        },
    };

    let data = serde_json::to_vec(&resp)?;
    stream.write_all(&data).await?;
    Ok(())
}

pub async fn run_control_socket(config: Config) -> Result<()> {
    let _ = fs::remove_file(&config.socket_path);
    let listener = UnixListener::bind(&config.socket_path)
        .with_context(|| format!("failed to bind socket: {}", config.socket_path))?;

    info!(path = %config.socket_path, "control socket listening");

    loop {
        let (stream, _) = listener.accept().await?;
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream).await {
                tracing::error!(error = %e, "control client error");
            }
        });
    }
}
```

