use crate::config::Config;
use crate::control::run_control_socket;
use crate::monitor::Monitor;
use crate::util::{remove_file_if_exists, write_pid_file};
use anyhow::Result;
use tokio::signal;
use tracing::info;

pub async fn run_daemon(config: Config) -> Result<()> {
    write_pid_file(&config.pid_file)?;

    let monitor_task = tokio::spawn(Monitor::new(config.clone()).run());
    let control_task = tokio::spawn(run_control_socket(config.clone()));

    info!("daemon started");

    tokio::select! {
        _ = signal::ctrl_c() => {
            info!("shutdown requested via signal");
        }
        res = monitor_task => {
            if let Err(e) = res {
                tracing::error!(error = %e, "monitor task join error");
            }
        }
        res = control_task => {
            if let Err(e) = res {
                tracing::error!(error = %e, "control task join error");
            }
        }
    }

    remove_file_if_exists(&config.pid_file)?;
    remove_file_if_exists(&config.socket_path)?;
    info!("daemon stopped");
    Ok(())
}
