enum Cmd {
    Daemon,
    Status,
    Reload,
    Shutdown,
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse()?))
        .init();

    let cli = Cli::parse();
    let config = Config::default();

    match cli.command.unwrap_or(Cmd::Daemon) {
        Cmd::Daemon => {
            daemon::run_daemon(config).await?;
        }
        Cmd::Status | Cmd::Reload | Cmd::Shutdown => {
            let cmd = match cli.command.unwrap() {
                Cmd::Status => Command::Status,
                Cmd::Reload => Command::Reload,
                Cmd::Shutdown => Command::Shutdown,
                Cmd::Daemon => unreachable!(),
            };

            let mut stream = UnixStream::connect(&config.socket_path).await?;
            let data = serde_json::to_vec(&cmd)?;
            stream.write_all(&data).await?;
            stream.shutdown().await?;

            let mut buf = Vec::new();
            stream.read_to_end(&mut buf).await?;
            let resp: Response = serde_json::from_slice(&buf)?;
            println!("{}", resp.message);

            if matches!(cmd, Command::Shutdown) {
                let _ = fs::remove_file(&config.pid_file);
            }
        }
    }

    Ok(())
}
