pub enum PolicyAction {
    LogWarning(String),
    ThrottleCpu,
    ReclaimMemory,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PolicyDecision {
    pub actions: Vec<PolicyAction>,
}

pub struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, metrics: &SystemMetrics) -> PolicyDecision {
        let mut actions = Vec::new();

        if metrics.cpu_usage >= self.config.cpu_warn_threshold {
            actions.push(PolicyAction::LogWarning(format!(
                "CPU usage high: {:.2}%",
                metrics.cpu_usage
            )));
            actions.push(PolicyAction::ThrottleCpu);
        }

        if metrics.memory_used_percent >= self.config.memory_warn_threshold {
            actions.push(PolicyAction::LogWarning(format!(
                "Memory usage high: {:.2}%",
                metrics.memory_used_percent
            )));
            actions.push(PolicyAction::ReclaimMemory);
        }

        PolicyDecision { actions }
    }
}
