use crate::metrics::{ProcessMetric, SystemMetrics};
use sysinfo::{LoadAvg, System};

pub fn collect_system_metrics(sys: &mut System) -> SystemMetrics {
    sys.refresh_cpu();
    sys.refresh_memory();

    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let total_memory = sys.total_memory();
    let used_memory = sys.used_memory();
    let total_swap = sys.total_swap();
    let used_swap = sys.used_swap();

    let memory_used_percent = if total_memory > 0 {
        (used_memory as f32 / total_memory as f32) * 100.0
    } else {
        0.0
    };

    let LoadAvg {
        one,
        five,
        fifteen,
    } = System::load_average();

    SystemMetrics {
        cpu_usage,
        memory_used_percent,
        total_memory,
        used_memory,
        total_swap,
        used_swap,
        load_avg_one: one,
        load_avg_five: five,
        load_avg_fifteen: fifteen,
    }
}

pub fn collect_top_processes(sys: &mut System, limit: usize) -> Vec<ProcessMetric> {
    sys.refresh_processes();

    let mut procs: Vec<_> = sys
        .processes()
        .iter()
        .map(|(pid, p)| ProcessMetric {
            pid: pid.as_u32() as i32,
            name: p.name().to_string(),
            cpu_usage: p.cpu_usage(),
            memory_kb: p.memory(),
        })
        .collect();

    procs.sort_by(|a, b| b.cpu_usage.partial_cmp(&a.cpu_usage).unwrap_or(std::cmp::Ordering::Equal));
    procs.truncate(limit);
    procs
}
