## `src/daemon.rs`

```rust
use crate::config::Config;
use crate::manager::ResourceManager;
use crate::policy::PolicyEngine;
use crate::util::{collect_system_metrics, collect_top_processes};
use anyhow::Result;
use serde_json::json;
use sysinfo::System;
use tokio::signal;
use tokio::time::{interval, MissedTickBehavior};
use tracing::{info, warn};

pub struct Daemon {
    config: Config,
    policy: PolicyEngine,
    manager: ResourceManager,
}

impl Daemon {
    pub fn new(config: Config) -> Self {
        Self {
            policy: PolicyEngine::new(config.clone()),
            manager: ResourceManager::new(),
            config,
        }
    }

    pub async fn run(self) -> Result<()> {
        let mut sys = System::new_all();
        let mut ticker = interval(self.config.poll_interval());
        ticker.set_missed_tick_behavior(MissedTickBehavior::Delay);

        info!("daemon started");

        loop {
            tokio::select! {
                _ = ticker.tick() => {
                    let metrics = collect_system_metrics(&mut sys);
                    let top_processes = collect_top_processes(&mut sys, self.config.max_processes_to_track);
                    let decision = self.policy.evaluate(&metrics);

                    self.manager.apply_actions(&decision.actions).await?;

                    let snapshot = json!({
                        "system": metrics,
                        "top_processes": top_processes,
                        "decision": decision,
                    });

                    println!("{}", serde_json::to_string_pretty(&snapshot)?);
                }
                _ = signal::ctrl_c() => {
                    warn!("shutdown requested");
                    break;
                }
            }
        }

        info!("daemon stopped");
        Ok(())
    }
}
```

