```rust
use anyhow::{Context, Result};
use clap::Parser;
use serde::Deserialize;
use std::{
    fs,
    path::PathBuf,
    sync::Arc,
    time::Duration,
};
use sysinfo::{Pid, ProcessExt, System, SystemExt};
use tokio::{
    signal,
    sync::RwLock,
    time::interval,
};
use tracing::{debug, error, info, warn};
use tracing_subscriber::EnvFilter;

#[derive(Parser, Debug)]
#[command(name = "sysd", version, about = "High-performance OS resource daemon")]
struct Args {
    /// Path to configuration file
    #[arg(short, long, default_value = "/etc/sysd.toml")]
    config: PathBuf,
}

#[derive(Debug, Clone, Deserialize)]
struct Config {
    /// Monitoring interval in seconds
    #[serde(default = "default_interval_secs")]
    interval_secs: u64,

    /// CPU usage threshold percentage
    #[serde(default = "default_cpu_threshold")]
    cpu_threshold: f32,

    /// Memory usage threshold percentage
    #[serde(default = "default_mem_threshold")]
    memory_threshold: f32,

    /// Disk usage threshold percentage
    #[serde(default = "default_disk_threshold")]
    disk_threshold: f32,

    /// Enable automatic process termination on threshold breach
    #[serde(default)]
    enable_enforcement: bool,

    /// PID of a process to protect from termination
    #[serde(default)]
    protected_pids: Vec<i32>,
}

fn default_interval_secs() -> u64 {
    5
}
fn default_cpu_threshold() -> f32 {
    85.0
}
fn default_mem_threshold() -> f32 {
    85.0
}
fn default_disk_threshold() -> f32 {
    90.0
}

impl Default for Config {
    fn default() -> Self {
        Self {
            interval_secs: default_interval_secs(),
            cpu_threshold: default_cpu_threshold(),
            memory_threshold: default_mem_threshold(),
            disk_threshold: default_disk_threshold(),
            enable_enforcement: false,
            protected_pids: vec![],
        }
    }
}

#[derive(Debug, Clone)]
struct Metrics {
    cpu_usage: f32,
    memory_usage: f32,
    disk_usage: f32,
    top_processes: Vec<ProcessMetric>,
}

#[derive(Debug, Clone)]
struct ProcessMetric {
    pid: i32,
    name: String,
    cpu: f32,
    memory: u64,
}

#[derive(Debug)]
struct DaemonState {
    config: Config,
    system: System,
}

impl DaemonState {
    fn new(config: Config) -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { config, system }
    }

    fn refresh_metrics(&mut self) -> Metrics {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_processes();
        self.system.refresh_disks_list();
        self.system.refresh_disks();

        let cpu_usage = self.system.global_cpu_info().cpu_usage();
        let total_memory = self.system.total_memory() as f32;
        let used_memory = self.system.used_memory() as f32;
        let memory_usage = if total_memory > 0.0 {
            (used_memory / total_memory) * 100.0
        } else {
            0.0
        };

        let mut disk_usage = 0.0;
        for disk in self.system.disks() {
            let total = disk.total_space() as f32;
            let avail = disk.available_space() as f32;
            if total > 0.0 {
                let used = total - avail;
                let usage = (used / total) * 100.0;
                if usage > disk_usage {
                    disk_usage = usage;
                }
            }
        }

        let mut processes: Vec<ProcessMetric> = self
            .system
            .processes()
            .iter()
            .map(|(pid, proc_)| ProcessMetric {
                pid: pid.as_u32() as i32,
                name: proc_.name().to_string(),
                cpu: proc_.cpu_usage(),
                memory: proc_.memory(),
            })
            .collect();

        processes.sort_by(|a, b| b.cpu.partial_cmp(&a.cpu).unwrap_or(std::cmp::Ordering::Equal));
        processes.truncate(5);

        Metrics {
            cpu_usage,
            memory_usage,
            disk_usage,
            top_processes: processes,
        }
    }

    fn enforce_policies(&mut self, metrics: &Metrics) {
        if metrics.cpu_usage > self.config.cpu_threshold {
            warn!(
                cpu = metrics.cpu_usage,
                threshold = self.config.cpu_threshold,
                "CPU usage threshold exceeded"
            );
        }

        if metrics.memory_usage > self.config.memory_threshold {
            warn!(
                memory = metrics.memory_usage,
                threshold = self.config.memory_threshold,
                "Memory usage threshold exceeded"
            );
        }

        if metrics.disk_usage > self.config.disk_threshold {
            warn!(
                disk = metrics.disk_usage,
                threshold = self.config.disk_threshold,
                "Disk usage threshold exceeded"
            );
        }

        for p in &metrics.top_processes {
            debug!(
                pid = p.pid,
                name = %p.name,
                cpu = p.cpu,
                memory = p.memory,
                "Top process"
            );
        }

        if !self.config.enable_enforcement {
            return;
        }

        // Simple enforcement example:
        // terminate the highest CPU process if CPU threshold is exceeded
        if metrics.cpu_usage > self.config.cpu_threshold {
            if let Some(proc_) = self
                .system
                .processes()
                .values()
                .max_by(|a, b| a.cpu_usage().partial_cmp(&b.cpu_usage()).unwrap_or(std::cmp::Ordering::Equal))
            {
                let pid = proc_.pid().as_u32() as i32;
                if self.config.protected_pids.contains(&pid) {
                    info!(pid, "Skipping protected process");
                } else {
                    warn!(pid, name = %proc_.name(), "Terminating process due to CPU policy");
                    let _ = proc_.kill();
                }
            }
        }

        // Simple enforcement example:
        // terminate the highest memory process if memory threshold is exceeded
        if metrics.memory_usage > self.config.memory_threshold {
            if let Some(proc_) = self
                .system
                .processes()
                .values()
                .max_by_key(|p| p.memory())
            {
                let pid = proc_.pid().as_u32() as i32;
                if self.config.protected_pids.contains(&pid) {
                    info!(pid, "Skipping protected process");
                } else {
                    warn!(pid, name = %proc_.name(), "Terminating process due to memory policy");
                    let _ = proc_.kill();
                }
            }
        }
    }
}

fn load_config(path: &PathBuf) -> Result<Config> {
    if !path.exists() {
        return Ok(Config::default());
    }

    let content = fs::read_to_string(path)
        .with_context(|| format!("failed to read config file: {}", path.display()))?;
    let cfg: Config = toml::from_str(&content)
        .with_context(|| format!("failed to parse config file: {}", path.display()))?;
    Ok(cfg)
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(EnvFilter::from_default_env().add_directive("info".parse()?))
        .init();

    let args = Args::parse();
    let config = load_config(&args.config)?;
    info!(?config, "Loaded configuration");

    let state = Arc::new(RwLock::new(DaemonState::new(config.clone())));
    let mut ticker = interval(Duration::from_secs(config.interval_secs));

    info!("sysd started");

    loop {
        tokio::select! {
            _ = ticker.tick() => {
                let mut guard = state.write().await;
                let metrics = guard.refresh_metrics();
                info!(
                    cpu = metrics.cpu_usage,
                    memory = metrics.memory_usage,
                    disk = metrics.disk_usage,
                    "Resource snapshot"
                );
                guard.enforce_policies(&metrics);
            }

            _ = signal::ctrl_c() => {
                info!("Shutdown signal received");
                break;
            }
        }
    }

    info!("sysd stopped");
    Ok(())
}
```

