use crate::{config::Config, metrics::Metrics};
use tracing::{info, warn};

#[derive(Debug, Clone)]
pub enum Action {
    None,
    LogOnly,
    ThrottleCpu,
    PressureMemory,
}

pub struct PolicyEngine {
    config: Config,
}

impl PolicyEngine {
    pub fn new(config: Config) -> Self {
        Self { config }
    }

    pub fn evaluate(&self, metrics: &Metrics) -> Action {
        if metrics.cpu_usage >= self.config.cpu_high_watermark {
            return Action::ThrottleCpu;
        }

        if metrics.memory_usage >= self.config.memory_high_watermark {
            return Action::PressureMemory;
        }

        Action::None
    }

    pub fn apply(&self, action: Action, metrics: &Metrics) {
        match action {
            Action::None => {
                info!(
                    cpu = metrics.cpu_usage,
                    memory = metrics.memory_usage,
                    "resource usage within thresholds"
                );
            }
            Action::LogOnly => {
                warn!(
                    cpu = metrics.cpu_usage,
                    memory = metrics.memory_usage,
                    "policy triggered: log only"
                );
            }
            Action::ThrottleCpu => {
                warn!(
                    cpu = metrics.cpu_usage,
                    memory = metrics.memory_usage,
                    "policy triggered: cpu threshold exceeded"
                );

                if self.config.enable_actions {
                    // Placeholder for future cgroup/systemd slice throttling.
                    info!("action enabled: cpu throttling would be applied here");
                }
            }
            Action::PressureMemory => {
                warn!(
                    cpu = metrics.cpu_usage,
                    memory = metrics.memory_usage,
                    "policy triggered: memory threshold exceeded"
                );

                if self.config.enable_actions {
                    // Placeholder for future reclaim / oomd integration / cgroup memory pressure handling.
                    info!("action enabled: memory mitigation would be applied here");
                }
            }
        }
    }
}
