use anyhow::Result;
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::time::interval;
use tracing::{info, warn};

#[derive(Debug, Clone)]
struct Config {
    sample_interval: Duration,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    disk_warn_threshold: f32,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            sample_interval: Duration::from_secs(5),
            cpu_warn_threshold: 80.0,
            mem_warn_threshold: 80.0,
            disk_warn_threshold: 90.0,
        }
    }
}

struct Daemon {
    sys: System,
    cfg: Config,
}

impl Daemon {
    fn new(cfg: Config) -> Self {
        let mut sys = System::new_all();
        sys.refresh_all();
        Self { sys, cfg }
    }

    fn sample_and_manage(&mut self) {
        self.sys.refresh_cpu();
        self.sys.refresh_memory();
        self.sys.refresh_disks_list();
        self.sys.refresh_disks();

        let cpu_usage = self.sys.global_cpu_info().cpu_usage();
        let total_mem = self.sys.total_memory() as f32;
        let used_mem = self.sys.used_memory() as f32;
        let mem_usage = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        let mut max_disk_usage = 0.0f32;
        for disk in self.sys.disks() {
            let total = disk.total_space() as f32;
            let avail = disk.available_space() as f32;
            if total > 0.0 {
                let used_pct = ((total - avail) / total) * 100.0;
                if used_pct > max_disk_usage {
                    max_disk_usage = used_pct;
                }
            }
        }

        info!(
            cpu = cpu_usage,
            memory = mem_usage,
            disk = max_disk_usage,
            "resource sample"
        );

        if cpu_usage > self.cfg.cpu_warn_threshold {
            warn!("CPU usage high: {:.1}%", cpu_usage);
            self.take_action("cpu");
        }

        if mem_usage > self.cfg.mem_warn_threshold {
            warn!("Memory usage high: {:.1}%", mem_usage);
            self.take_action("memory");
        }

        if max_disk_usage > self.cfg.disk_warn_threshold {
            warn!("Disk usage high: {:.1}%", max_disk_usage);
            self.take_action("disk");
        }
    }

    fn take_action(&self, resource: &str) {
        // Minimal placeholder actions.
        // In a real daemon, this could:
        // - log to journald/syslog
        // - notify a controller
        // - adjust cgroups / priorities
        // - trigger cleanup tasks
        // - restart services
        info!("taking management action for {}", resource);
    }

    async fn run(mut self) -> Result<()> {
        let mut ticker = interval(self.cfg.sample_interval);

        loop {
            ticker.tick().await;
            self.sample_and_manage();
        }
    }
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let cfg = Config::default();
    info!("starting sysd");

    let daemon = Daemon::new(cfg);
    daemon.run().await
}
```

