```rust
use anyhow::Result;
use serde::Serialize;
use std::sync::{Arc, RwLock};
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::signal;
use tokio::time::interval;

#[derive(Debug, Clone, Serialize)]
struct ResourceSnapshot {
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    disks: Vec<DiskSnapshot>,
}

#[derive(Debug, Clone, Serialize)]
struct DiskSnapshot {
    name: String,
    total_space: u64,
    available_space: u64,
    used_space: u64,
}

#[derive(Debug, Clone, Serialize)]
struct SharedState {
    snapshot: ResourceSnapshot,
}

impl SharedState {
    fn new() -> Self {
        Self {
            snapshot: ResourceSnapshot {
                cpu_usage: 0.0,
                total_memory: 0,
                used_memory: 0,
                total_swap: 0,
                used_swap: 0,
                disks: vec![],
            },
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let state = Arc::new(RwLock::new(SharedState::new()));
    let monitor_state = state.clone();
    let control_state = state.clone();

    let monitor_task = tokio::spawn(async move {
        let mut sys = System::new_all();
        let mut tick = interval(Duration::from_secs(1));

        loop {
            tick.tick().await;
            sys.refresh_all();

            let cpu_usage = sys.global_cpu_info().cpu_usage();
            let total_memory = sys.total_memory();
            let used_memory = sys.used_memory();
            let total_swap = sys.total_swap();
            let used_swap = sys.used_swap();

            let disks = sys
                .disks()
                .iter()
                .map(|d| DiskSnapshot {
                    name: d.name().to_string_lossy().to_string(),
                    total_space: d.total_space(),
                    available_space: d.available_space(),
                    used_space: d.total_space().saturating_sub(d.available_space()),
                })
                .collect::<Vec<_>>();

            let snapshot = ResourceSnapshot {
                cpu_usage,
                total_memory,
                used_memory,
                total_swap,
                used_swap,
                disks,
            };

            if let Ok(mut guard) = monitor_state.write() {
                guard.snapshot = snapshot;
            }
        }
    });

    let control_task = tokio::spawn(async move {
        let listener = TcpListener::bind("127.0.0.1:7878").await?;
        loop {
            let (stream, _) = listener.accept().await?;
            let state = control_state.clone();
            tokio::spawn(async move {
                if let Err(e) = handle_client(stream, state).await {
                    eprintln!("client error: {e}");
                }
            });
        }
        #[allow(unreachable_code)]
        Ok::<(), anyhow::Error>(())
    });

    println!("sysd started on 127.0.0.1:7878");
    println!("commands: status | quit");

    tokio::select! {
        _ = signal::ctrl_c() => {
            println!("shutdown requested");
        }
        _ = monitor_task => {}
        _ = control_task => {}
    }

    Ok(())
}

async fn handle_client(stream: TcpStream, state: Arc<RwLock<SharedState>>) -> Result<()> {
    let (read_half, mut write_half) = stream.into_split();
    let mut reader = BufReader::new(read_half);
    let mut line = String::new();

    write_half.write_all(b"sysd ready\n").await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        match cmd {
            "status" => {
                let snapshot = {
                    let guard = state.read().unwrap();
                    guard.snapshot.clone()
                };
                let json = serde_json::to_string_pretty(&snapshot)?;
                write_half.write_all(json.as_bytes()).await?;
                write_half.write_all(b"\n").await?;
            }
            "quit" => {
                write_half.write_all(b"bye\n").await?;
                std::process::exit(0);
            }
            _ => {
                write_half.write_all(b"unknown command\n").await?;
            }
        }
    }

    Ok(())
}
