```rust
use anyhow::Result;
use serde::Serialize;
use std::{
    fs,
    path::Path,
    sync::{Arc, RwLock},
    time::Duration,
};
use sysinfo::{CpuRefreshKind, RefreshKind, System};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{UnixListener, UnixStream},
    signal,
    sync::watch,
    time,
};

const SOCKET_PATH: &str = "/tmp/sysd.sock";
const POLL_INTERVAL_SECS: u64 = 1;

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    cpu_usage: f32,
    total_memory_kib: u64,
    used_memory_kib: u64,
    load_avg_1: f64,
    load_avg_5: f64,
    load_avg_15: f64,
    process_count: usize,
}

#[tokio::main]
async fn main() -> Result<()> {
    // Remove stale socket if present
    if Path::new(SOCKET_PATH).exists() {
        let _ = fs::remove_file(SOCKET_PATH);
    }

    let metrics = Arc::new(RwLock::new(Metrics::default()));
    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    // Spawn metrics collector
    {
        let metrics = metrics.clone();
        let mut shutdown_rx = shutdown_rx.clone();
        tokio::spawn(async move {
            let mut sys = System::new_with_specifics(
                RefreshKind::new()
                    .with_cpu(CpuRefreshKind::new().with_cpu_usage())
                    .with_memory()
                    .with_processes(),
            );

            let mut interval = time::interval(Duration::from_secs(POLL_INTERVAL_SECS));

            loop {
                tokio::select! {
                    _ = interval.tick() => {
                        sys.refresh_cpu();
                        sys.refresh_memory();
                        sys.refresh_processes();

                        let load = System::load_average();
                        let cpu = sys.global_cpu_info().cpu_usage();
                        let total_mem = sys.total_memory();
                        let used_mem = sys.used_memory();
                        let proc_count = sys.processes().len();

                        let mut guard = metrics.write().unwrap();
                        *guard = Metrics {
                            cpu_usage: cpu,
                            total_memory_kib: total_mem,
                            used_memory_kib: used_mem,
                            load_avg_1: load.one,
                            load_avg_5: load.five,
                            load_avg_15: load.fifteen,
                            process_count: proc_count,
                        };
                    }
                    _ = shutdown_rx.changed() => {
                        if *shutdown_rx.borrow() {
                            break;
                        }
                    }
                }
            }
        });
    }

    // Spawn control socket server
    {
        let metrics = metrics.clone();
        let shutdown_tx = shutdown_tx.clone();
        tokio::spawn(async move {
            if let Err(e) = run_socket_server(metrics, shutdown_tx).await {
                eprintln!("socket server error: {e}");
            }
        });
    }

    println!("sysd started");
    println!("control socket: {SOCKET_PATH}");

    // Handle SIGINT/SIGTERM
    tokio::select! {
        _ = signal::ctrl_c() => {
            println!("received ctrl-c");
        }
    }

    let _ = shutdown_tx.send(true);
    let _ = fs::remove_file(SOCKET_PATH);
    println!("sysd stopped");
    Ok(())
}

async fn run_socket_server(
    metrics: Arc<RwLock<Metrics>>,
    shutdown_tx: watch::Sender<bool>,
) -> Result<()> {
    let listener = UnixListener::bind(SOCKET_PATH)?;

    loop {
        let (stream, _) = listener.accept().await?;
        let metrics = metrics.clone();
        let shutdown_tx = shutdown_tx.clone();

        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, metrics, shutdown_tx).await {
                eprintln!("client error: {e}");
            }
        });
    }
}

async fn handle_client(
    stream: UnixStream,
    metrics: Arc<RwLock<Metrics>>,
    shutdown_tx: watch::Sender<bool>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    let n = reader.read_line(&mut line).await?;
    if n == 0 {
        return Ok(());
    }

    let cmd = line.trim();

    match cmd {
        "status" => {
            let snapshot = metrics.read().unwrap().clone();
            let json = serde_json::to_string(&snapshot)?;
            writer.write_all(json.as_bytes()).await?;
            writer.write_all(b"\n").await?;
        }
        "quit" => {
            let _ = shutdown_tx.send(true);
            writer.write_all(b"ok\n").await?;
        }
        _ => {
            writer.write_all(b"unknown command\n").await?;
        }
    }

    Ok(())
}
