use anyhow::Result;
use std::time::Duration;
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::signal;
use tokio::time::interval;
use tracing::{info, warn, error};

#[derive(Debug, Clone)]
struct Thresholds {
    cpu_percent: f32,
    mem_percent: f32,
    disk_percent: f32,
}

impl Default for Thresholds {
    fn default() -> Self {
        Self {
            cpu_percent: 85.0,
            mem_percent: 90.0,
            disk_percent: 90.0,
        }
    }
}

struct ResourceMonitor {
    system: System,
    thresholds: Thresholds,
}

impl ResourceMonitor {
    fn new(thresholds: Thresholds) -> Self {
        let mut system = System::new_all();
        system.refresh_all();
        Self { system, thresholds }
    }

    fn refresh(&mut self) {
        self.system.refresh_cpu();
        self.system.refresh_memory();
        self.system.refresh_disks_list();
        self.system.refresh_disks();
    }

    fn cpu_usage(&self) -> f32 {
        let cpus = self.system.cpus();
        if cpus.is_empty() {
            0.0
        } else {
            cpus.iter().map(|c| c.cpu_usage()).sum::<f32>() / cpus.len() as f32
        }
    }

    fn memory_usage_percent(&self) -> f32 {
        let total = self.system.total_memory() as f32;
        let used = self.system.used_memory() as f32;
        if total == 0.0 { 0.0 } else { (used / total) * 100.0 }
    }

    fn disk_usage_percent(&self) -> f32 {
        let mut total = 0u64;
        let mut used = 0u64;

        for disk in self.system.disks() {
            let t = disk.total_space();
            let a = disk.available_space();
            total += t;
            used += t.saturating_sub(a);
        }

        if total == 0 {
            0.0
        } else {
            (used as f32 / total as f32) * 100.0
        }
    }

    fn check_and_manage(&self) {
        let cpu = self.cpu_usage();
        let mem = self.memory_usage_percent();
        let disk = self.disk_usage_percent();

        info!(
            cpu = cpu,
            memory = mem,
            disk = disk,
            "resource snapshot"
        );

        if cpu > self.thresholds.cpu_percent {
            warn!("CPU usage high: {:.2}% > {:.2}%", cpu, self.thresholds.cpu_percent);
            self.manage_cpu_pressure();
        }

        if mem > self.thresholds.mem_percent {
            warn!("Memory usage high: {:.2}% > {:.2}%", mem, self.thresholds.mem_percent);
            self.manage_memory_pressure();
        }

        if disk > self.thresholds.disk_percent {
            warn!("Disk usage high: {:.2}% > {:.2}%", disk, self.thresholds.disk_percent);
            self.manage_disk_pressure();
        }
    }

    fn manage_cpu_pressure(&self) {
        // Minimal placeholder:
        // In a real daemon, you might:
        // - lower priority of non-critical processes
        // - notify a supervisor
        // - trigger autoscaling
        info!("CPU management action: placeholder");
    }

    fn manage_memory_pressure(&self) {
        // Minimal placeholder:
        // - log top memory consumers
        // - request cache drop (Linux-specific, privileged)
        // - restart non-critical services
        info!("Memory management action: placeholder");
    }

    fn manage_disk_pressure(&self) {
        // Minimal placeholder:
        // - clean temp files
        // - rotate logs
        // - alert admin
        info!("Disk management action: placeholder");
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    info!("starting sysmon daemon");

    let thresholds = Thresholds::default();
    let mut monitor = ResourceMonitor::new(thresholds);

    let mut tick = interval(Duration::from_secs(5));

    loop {
        tokio::select! {
            _ = tick.tick() => {
                monitor.refresh();
                monitor.check_and_manage();
            }
            _ = signal::ctrl_c() => {
                info!("shutdown signal received");
                break;
            }
        }
    }

    info!("sysmon daemon stopped");
    Ok(())
}
