```rust
use serde::Serialize;
use std::sync::{Arc, RwLock};
use std::time::{Duration, SystemTime, UNIX_EPOCH};
use sysinfo::{CpuExt, DiskExt, System, SystemExt};
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::net::{TcpListener, TcpStream};
use tokio::time::interval;

#[derive(Debug, Clone, Serialize, Default)]
struct Metrics {
    timestamp: u64,
    cpu_usage: f32,
    total_memory: u64,
    used_memory: u64,
    total_swap: u64,
    used_swap: u64,
    disks_total: u64,
    disks_available: u64,
}

#[derive(Clone)]
struct SharedState {
    metrics: Arc<RwLock<Metrics>>,
}

impl SharedState {
    fn new() -> Self {
        Self {
            metrics: Arc::new(RwLock::new(Metrics::default())),
        }
    }

    fn update(&self, m: Metrics) {
        if let Ok(mut guard) = self.metrics.write() {
            *guard = m;
        }
    }

    fn get(&self) -> Metrics {
        self.metrics
            .read()
            .map(|g| g.clone())
            .unwrap_or_default()
    }
}

fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs()
}

fn collect_metrics(sys: &mut System) -> Metrics {
    sys.refresh_cpu();
    sys.refresh_memory();
    sys.refresh_disks_list();
    sys.refresh_disks();

    let cpu_usage = sys.global_cpu_info().cpu_usage();
    let total_memory = sys.total_memory();
    let used_memory = sys.used_memory();
    let total_swap = sys.total_swap();
    let used_swap = sys.used_swap();

    let mut disks_total = 0;
    let mut disks_available = 0;
    for disk in sys.disks() {
        disks_total += disk.total_space();
        disks_available += disk.available_space();
    }

    Metrics {
        timestamp: now_unix(),
        cpu_usage,
        total_memory,
        used_memory,
        total_swap,
        used_swap,
        disks_total,
        disks_available,
    }
}

async fn metrics_collector(state: SharedState) {
    let mut sys = System::new_all();
    let mut tick = interval(Duration::from_secs(2));

    loop {
        tick.tick().await;
        let m = collect_metrics(&mut sys);
        state.update(m.clone());

        println!(
            "[{}] cpu={:.1}% mem={}/{} swap={}/{} disk_avail={}/{}",
            m.timestamp,
            m.cpu_usage,
            m.used_memory,
            m.total_memory,
            m.used_swap,
            m.total_swap,
            m.disks_available,
            m.disks_total
        );
    }
}

async fn handle_client(stream: TcpStream, state: SharedState) -> std::io::Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer
        .write_all(b"OSD daemon ready. Commands: status, trim, quit\n")
        .await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim().to_lowercase();

        match cmd.as_str() {
            "status" => {
                let m = state.get();
                let json = serde_json::to_string(&m).unwrap_or_else(|_| "{}".into());
                writer.write_all(json.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "trim" => {
                // Placeholder for a safe management action.
                // In a real daemon, this could trigger cache cleanup or memory pressure handling.
                writer.write_all(b"trim requested: ok\n").await?;
            }
            "quit" | "exit" => {
                writer.write_all(b"bye\n").await?;
                break;
            }
            _ => {
                writer.write_all(b"unknown command\n").await?;
            }
        }
    }

    Ok(())
}

async fn control_server(state: SharedState) -> std::io::Result<()> {
    let listener = TcpListener::bind("127.0.0.1:7878").await?;
    println!("control server listening on 127.0.0.1:7878");

    loop {
        let (stream, _) = listener.accept().await?;
        let s = state.clone();
        tokio::spawn(async move {
            if let Err(e) = handle_client(stream, s).await {
                eprintln!("client error: {e}");
            }
        });
    }
}

#[tokio::main]
async fn main() -> std::io::Result<()> {
    let state = SharedState::new();

    let collector_state = state.clone();
    tokio::spawn(async move {
        metrics_collector(collector_state).await;
    });

    control_server(state).await
}
