```rust
use anyhow::Result;
use serde::Serialize;
use std::{
    sync::{Arc, Mutex},
    time::Duration,
};
use sysinfo::{CpuExt, DiskExt, NetworkExt, NetworksExt, System, SystemExt};
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    net::{TcpListener, TcpStream},
    signal,
    sync::watch,
    time,
};
use tracing::{info, warn};

#[derive(Clone, Debug, Serialize)]
struct Metrics {
    cpu_usage: f32,
    memory_used: u64,
    memory_total: u64,
    disk_used: u64,
    disk_total: u64,
    net_rx: u64,
    net_tx: u64,
}

impl Default for Metrics {
    fn default() -> Self {
        Self {
            cpu_usage: 0.0,
            memory_used: 0,
            memory_total: 0,
            disk_used: 0,
            disk_total: 0,
            net_rx: 0,
            net_tx: 0,
        }
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter("info")
        .init();

    let metrics = Arc::new(Mutex::new(Metrics::default()));
    let (shutdown_tx, shutdown_rx) = watch::channel(false);

    // Metrics collector
    {
        let metrics = metrics.clone();
        let shutdown_rx = shutdown_rx.clone();
        tokio::spawn(async move {
            collect_metrics(metrics, shutdown_rx).await;
        });
    }

    // Control server
    {
        let metrics = metrics.clone();
        let shutdown_tx = shutdown_tx.clone();
        let shutdown_rx = shutdown_rx.clone();
        tokio::spawn(async move {
            if let Err(e) = control_server(metrics, shutdown_tx, shutdown_rx).await {
                warn!("control server error: {e}");
            }
        });
    }

    info!("sysd started");

    // Graceful shutdown on SIGINT/SIGTERM
    signal::ctrl_c().await?;
    info!("shutdown signal received");
    let _ = shutdown_tx.send(true);

    // Give tasks a moment to exit cleanly
    time::sleep(Duration::from_millis(300)).await;
    info!("sysd stopped");

    Ok(())
}

async fn collect_metrics(metrics: Arc<Mutex<Metrics>>, mut shutdown_rx: watch::Receiver<bool>) {
    let mut sys = System::new_all();
    let mut interval = time::interval(Duration::from_secs(1));

    loop {
        tokio::select! {
            _ = interval.tick() => {
                sys.refresh_cpu();
                sys.refresh_memory();
                sys.refresh_disks_list();
                sys.refresh_disks();
                sys.refresh_networks();
                sys.refresh_networks_list();

                let cpu = sys.global_cpu_info().cpu_usage();
                let mem_used = sys.used_memory();
                let mem_total = sys.total_memory();

                let mut disk_used = 0;
                let mut disk_total = 0;
                for d in sys.disks() {
                    let total = d.total_space();
                    let avail = d.available_space();
                    disk_total += total;
                    disk_used += total.saturating_sub(avail);
                }

                let mut net_rx = 0;
                let mut net_tx = 0;
                for (_name, data) in sys.networks() {
                    net_rx += data.received();
                    net_tx += data.transmitted();
                }

                let mut m = metrics.lock().unwrap();
                m.cpu_usage = cpu;
                m.memory_used = mem_used;
                m.memory_total = mem_total;
                m.disk_used = disk_used;
                m.disk_total = disk_total;
                m.net_rx = net_rx;
                m.net_tx = net_tx;

                info!(
                    "cpu={:.1}% mem={}/{} KB disk={}/{} B net_rx={} net_tx={}",
                    m.cpu_usage, m.memory_used, m.memory_total, m.disk_used, m.disk_total, m.net_rx, m.net_tx
                );
            }
            _ = shutdown_rx.changed() => {
                if *shutdown_rx.borrow() {
                    break;
                }
            }
        }
    }
}

async fn control_server(
    metrics: Arc<Mutex<Metrics>>,
    shutdown_tx: watch::Sender<bool>,
    mut shutdown_rx: watch::Receiver<bool>,
) -> Result<()> {
    let listener = TcpListener::bind("127.0.0.1:7878").await?;
    info!("control server listening on 127.0.0.1:7878");

    loop {
        tokio::select! {
            accept_res = listener.accept() => {
                let (stream, addr) = accept_res?;
                info!("client connected: {addr}");
                let metrics = metrics.clone();
                let shutdown_tx = shutdown_tx.clone();
                tokio::spawn(async move {
                    if let Err(e) = handle_client(stream, metrics, shutdown_tx).await {
                        warn!("client error: {e}");
                    }
                });
            }
            _ = shutdown_rx.changed() => {
                if *shutdown_rx.borrow() {
                    break;
                }
            }
        }
    }

    Ok(())
}

async fn handle_client(
    stream: TcpStream,
    metrics: Arc<Mutex<Metrics>>,
    shutdown_tx: watch::Sender<bool>,
) -> Result<()> {
    let (reader, mut writer) = stream.into_split();
    let mut reader = BufReader::new(reader);
    let mut line = String::new();

    writer.write_all(b"sysd control ready\ncommands: status | shutdown\n").await?;

    loop {
        line.clear();
        let n = reader.read_line(&mut line).await?;
        if n == 0 {
            break;
        }

        let cmd = line.trim();
        match cmd {
            "status" => {
                let m = metrics.lock().unwrap().clone();
                let json = serde_json::to_string(&m)?;
                writer.write_all(json.as_bytes()).await?;
                writer.write_all(b"\n").await?;
            }
            "shutdown" => {
                writer.write_all(b"shutting down\n").await?;
                let _ = shutdown_tx.send(true);
                break;
            }
            _ => {
                writer.write_all(b"unknown command\n").await?;
            }
        }
    }

    Ok(())
}
