use anyhow::Result;
use daemonize::Daemonize;
use log::{info, warn};
use serde::Deserialize;
use simplelog::{Config as LogConfig, LevelFilter, WriteLogger};
use std::{
    fs::File,
    thread,
    time::Duration,
};
use sysinfo::{CpuRefreshKind, MemoryRefreshKind, RefreshKind, System};

#[derive(Debug, Deserialize)]
struct Config {
    interval_secs: u64,
    cpu_warn_threshold: f32,
    mem_warn_threshold: f32,
    log_file: String,
    pid_file: String,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            interval_secs: 5,
            cpu_warn_threshold: 80.0,
            mem_warn_threshold: 80.0,
            log_file: "/tmp/sysd.log".to_string(),
            pid_file: "/tmp/sysd.pid".to_string(),
        }
    }
}

fn load_config() -> Config {
    let path = "sysd.toml";
    match std::fs::read_to_string(path) {
        Ok(contents) => toml::from_str(&contents).unwrap_or_default(),
        Err(_) => Config::default(),
    }
}

fn main() -> Result<()> {
    let config = load_config();

    let log_file = File::create(&config.log_file)?;
    WriteLogger::init(LevelFilter::Info, LogConfig::default(), log_file)?;

    let stdout = File::create("/tmp/sysd.out")?;
    let stderr = File::create("/tmp/sysd.err")?;

    let daemonize = Daemonize::new()
        .pid_file(&config.pid_file)
        .working_directory("/")
        .stdout(stdout)
        .stderr(stderr);

    match daemonize.start() {
        Ok(_) => info!("sysd started"),
        Err(e) => {
            eprintln!("Failed to daemonize: {}", e);
            return Ok(());
        }
    }

    let mut system = System::new_with_specifics(
        RefreshKind::new()
            .with_cpu(CpuRefreshKind::everything())
            .with_memory(MemoryRefreshKind::everything()),
    );

    loop {
        system.refresh_cpu();
        system.refresh_memory();

        let cpu_usage = system.global_cpu_info().cpu_usage();
        let total_mem = system.total_memory() as f32;
        let used_mem = system.used_memory() as f32;
        let mem_usage = if total_mem > 0.0 {
            (used_mem / total_mem) * 100.0
        } else {
            0.0
        };

        info!(
            "cpu_usage={:.2}% mem_usage={:.2}% used_mem={} total_mem={}",
            cpu_usage, mem_usage, used_mem as u64, total_mem as u64
        );

        if cpu_usage > config.cpu_warn_threshold {
            warn!("CPU usage high: {:.2}%", cpu_usage);
        }

        if mem_usage > config.mem_warn_threshold {
            warn!("Memory usage high: {:.2}%", mem_usage);
        }

        thread::sleep(Duration::from_secs(config.interval_secs));
    }
}
```

