    uint16_t urgent;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

// =========================
// Flow key / value
// =========================

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
    uint8_t  pad[3]; // align to 16 bytes

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t hash = 0;
    bool occupied = false;
};

// =========================
// Fixed-size open-addressing table
// =========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowStats* find_or_insert(const FlowKey& key, uint64_t now_ns) noexcept {
        const uint64_t h = hash_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < table_.size(); ++probe) {
            FlowEntry& e = table_[idx];
            if (!e.occupied) {
                e.occupied = true;
                e.key = key;
                e.hash = h;
                e.stats.first_seen_ns = now_ns;
                e.stats.last_seen_ns = now_ns;
                return &e.stats;
            }
            if (e.hash == h && e.key == key) {
                e.stats.last_seen_ns = now_ns;
                return &e.stats;
            }
            idx = (idx + 1) & mask_;
        }
        return nullptr; // table full
    }

    template <typename Fn>
    void expire_older_than(uint64_t cutoff_ns, Fn&& fn) {
        for (auto& e : table_) {
            if (e.occupied && e.stats.last_seen_ns < cutoff_ns) {
                fn(e.key, e.stats);
                e.occupied = false;
            }
        }
    }

    size_t size() const noexcept {
        size_t n = 0;
        for (const auto& e : table_) n += e.occupied ? 1 : 0;
        return n;
    }

private:
    static uint64_t hash_key(const FlowKey& k) noexcept {
        // Compact hash over the 5-tuple
        uint64_t a = (static_cast<uint64_t>(k.src_ip) << 32) ^ k.dst_ip;
        uint64_t b = (static_cast<uint64_t>(k.src_port) << 48) ^
                     (static_cast<uint64_t>(k.dst_port) << 32) ^
                     (static_cast<uint64_t>(k.proto) << 24);
        return hash64(a ^ hash64(b));
    }

    size_t mask_;
    std::vector<FlowEntry> table_;
};

// =========================
// Packet parsing
// =========================

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
};

static inline std::optional<ParsedPacket> parse_packet(std::span<const uint8_t> pkt) noexcept {
    if (pkt.size() < sizeof(EthHdr)) return std::nullopt;

    const auto* eth = reinterpret_cast<const EthHdr*>(pkt.data());
    uint16_t ethertype = bswap16(eth->ethertype);
    size_t offset = sizeof(EthHdr);

    // VLAN support (single tag)
    if (ethertype == 0x8100 || ethertype == 0x88A8) {
        if (pkt.size() < offset + sizeof(VlanHdr)) return std::nullopt;
        const auto* vlan = reinterpret_cast<const VlanHdr*>(pkt.data() + offset);
        ethertype = bswap16(vlan->ethertype);
        offset += sizeof(VlanHdr);
    }

    if (ethertype != 0x0800) return std::nullopt; // IPv4 only

    if (pkt.size() < offset + sizeof(Ipv4Hdr)) return std::nullopt;
    const auto* ip = reinterpret_cast<const Ipv4Hdr*>(pkt.data() + offset);

    const uint8_t version = ip->ver_ihl >> 4;
    const uint8_t ihl = ip->ver_ihl & 0x0F;
    if (version != 4 || ihl < 5) return std::nullopt;

    const size_t ip_hdr_len = static_cast<size_t>(ihl) * 4;
    if (pkt.size() < offset + ip_hdr_len) return std::nullopt;

    const uint16_t total_len = bswap16(ip->total_len);
    if (total_len < ip_hdr_len) return std::nullopt;

    const uint8_t proto = ip->protocol;
    const uint8_t* l4 = pkt.data() + offset + ip_hdr_len;

    ParsedPacket out;
    out.key.src_ip = ip->src;
    out.key.dst_ip = ip->dst;
    out.key.proto = proto;

    if (proto == 6) { // TCP
        if (pkt.size() < offset + ip_hdr_len + sizeof(TcpHdr)) return std::nullopt;
        const auto* tcp = reinterpret_cast<const TcpHdr*>(l4);
        const uint8_t data_offset = (tcp->data_offset_reserved >> 4) & 0x0F;
        if (data_offset < 5) return std::nullopt;

        out.key.src_port = bswap16(tcp->src_port);
        out.key.dst_port = bswap16(tcp->dst_port);
        out.payload_len = total_len - ip_hdr_len - static_cast<uint32_t>(data_offset) * 4;
    } else if (proto == 17) { // UDP
        if (pkt.size() < offset + ip_hdr_len + sizeof(UdpHdr)) return std::nullopt;
        const auto* udp = reinterpret_cast<const UdpHdr*>(l4);
        out.key.src_port = bswap16(udp->src_port);
        out.key.dst_port = bswap16(udp->dst_port);
        out.payload_len = total_len - ip_hdr_len - sizeof(UdpHdr);
    } else {
        return std::nullopt;
    }

    return out;
}

// =========================
// Analyzer
// =========================

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2, uint64_t flow_timeout_ns)
        : table_(table_capacity_pow2), flow_timeout_ns_(flow_timeout_ns) {}

    void process_packet(std::span<const uint8_t> pkt, uint64_t now_ns) noexcept {
        auto parsed = parse_packet(pkt);
        if (!parsed) return;

        FlowStats* stats = table_.find_or_insert(parsed->key, now_ns);
        if (!stats) return;

        stats->packets += 1;
        stats->bytes += pkt.size();
    }

    template <typename Fn>
    void expire(Fn&& fn, uint64_t now_ns) {
        const uint64_t cutoff = now_ns > flow_timeout_ns_ ? now_ns - flow_timeout_ns_ : 0;
        table_.expire_older_than(cutoff, std::forward<Fn>(fn));
    }

    size_t active_flows() const noexcept {
        return table_.size();
    }

private:
    FlowTable table_;
    uint64_t flow_timeout_ns_;
};

// =========================
// Example driver
// =========================

int main() {
    constexpr size_t TABLE_SIZE = 1u << 20; // 1,048,576 entries
    constexpr uint64_t FLOW_TIMEOUT_NS = 30ULL * 1000ULL * 1000ULL * 1000ULL; // 30s

    FlowAnalyzer analyzer(TABLE_SIZE, FLOW_TIMEOUT_NS);

    // Example packet buffer would come from NIC capture ring.
    std::vector<uint8_t> packet(64, 0);

    // Fake Ethernet + IPv4 + UDP packet setup for demo
    auto* eth = reinterpret_cast<EthHdr*>(packet.data());
    eth->ethertype = bswap16(0x0800);

    auto* ip = reinterpret_cast<Ipv4Hdr*>(packet.data() + sizeof(EthHdr));
    ip->ver_ihl = (4 << 4) | 5;
    ip->protocol = 17;
    ip->total_len = bswap16(20 + 8 + 12);
    ip->src = 0x0A000001; // 10.0.0.1
    ip->dst = 0x0A000002; // 10.0.0.2

    auto* udp = reinterpret_cast<UdpHdr*>(packet.data() + sizeof(EthHdr) + 20);
    udp->src_port = bswap16(12345);
    udp->dst_port = bswap16(53);

    const uint64_t now_ns = rdtsc_fallback_ns();
    analyzer.process_packet(packet, now_ns);

    analyzer.expire([](const FlowKey& key, const FlowStats& stats) {
        std::cout << "Expired flow: "
                  << key.src_ip << ":" << key.src_port
                  << " -> " << key.dst_ip << ":" << key.dst_port
                  << " proto=" << static_cast<int>(key.proto)
                  << " packets=" << stats.packets
                  << " bytes=" << stats.bytes << "\n";
    }, now_ns + 31ULL * 1000ULL * 1000ULL * 1000ULL);

    std::cout << "Active flows: " << analyzer.active_flows() << "\n";
    return 0;
}
