// =========================
// Packet header definitions
// =========================

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

// =========================
// Utility
// =========================

static inline uint16_t bswap16(uint16_t x) {
    return (x >> 8) | (x << 8);
}

static inline uint32_t bswap32(uint32_t x) {
    return ((x & 0x000000FFu) << 24) |
           ((x & 0x0000FF00u) << 8)  |
           ((x & 0x00FF0000u) >> 8)  |
           ((x & 0xFF000000u) >> 24);
}

#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
static inline uint16_t ntoh16(uint16_t x) { return bswap16(x); }
static inline uint32_t ntoh32(uint32_t x) { return bswap32(x); }
#else
static inline uint16_t ntoh16(uint16_t x) { return x; }
static inline uint32_t ntoh32(uint32_t x) { return x; }
#endif

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

// =========================
// Flow key and state
// =========================

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    OTHER = 255
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    // Fast 64-bit mix
    static inline uint64_t mix64(uint64_t x) {
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return x;
    }

    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t x = 0;
        x ^= uint64_t(k.src_ip) << 32;
        x ^= uint64_t(k.dst_ip);
        x ^= uint64_t(k.src_port) << 16;
        x ^= uint64_t(k.dst_port);
        x ^= uint64_t(k.proto) << 56;
        return static_cast<size_t>(mix64(x));
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;

    // TCP-specific optional counters
    uint64_t syn = 0;
    uint64_t fin = 0;
    uint64_t rst = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    bool occupied = false;
    bool tombstone = false;
};

// =========================
// Fixed-size open-addressing hash table
// =========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowStats* find_or_insert(const FlowKey& key, uint64_t ts_ns) {
        size_t idx = hasher_(key) & mask_;
        size_t first_tombstone = npos;

        for (;;) {
            FlowEntry& e = table_[idx];

            if (!e.occupied) {
                if (first_tombstone != npos) idx = first_tombstone;
                FlowEntry& target = table_[idx];
                target.key = key;
                target.stats = {};
                target.stats.first_seen_ns = ts_ns;
                target.stats.last_seen_ns = ts_ns;
                target.occupied = true;
                target.tombstone = false;
                ++size_;
                return &target.stats;
            }

            if (e.key == key) {
                e.stats.last_seen_ns = ts_ns;
                return &e.stats;
            }

            if (e.tombstone && first_tombstone == npos) {
                first_tombstone = idx;
            }

            idx = (idx + 1) & mask_;
        }
    }

    template <typename Fn>
    void expire(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& fn) {
        for (auto& e : table_) {
            if (!e.occupied) continue;
            if (now_ns - e.stats.last_seen_ns >= idle_timeout_ns) {
                fn(e.key, e.stats);
                e.occupied = false;
                e.tombstone = true;
                --size_;
            }
        }
    }

    size_t size() const noexcept { return size_; }
    size_t capacity() const noexcept { return table_.size(); }

private:
    static constexpr size_t npos = static_cast<size_t>(-1);

    size_t mask_;
    std::vector<FlowEntry> table_;
    size_t size_ = 0;
    FlowKeyHash hasher_;
};

// =========================
// Packet parsing
// =========================

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    uint8_t tcp_flags = 0;
    bool valid = false;
};

static inline ParsedPacket parse_packet(const uint8_t* data, size_t len) {
    ParsedPacket out{};

    if (len < sizeof(EthernetHeader)) return out;

    const auto* eth = reinterpret_cast<const EthernetHeader*>(data);
    uint16_t ethertype = ntoh16(eth->ethertype);

    if (ethertype != 0x0800) { // IPv4 only
        return out;
    }

    size_t offset = sizeof(EthernetHeader);
    if (len < offset + sizeof(IPv4Header)) return out;

    const auto* ip = reinterpret_cast<const IPv4Header*>(data + offset);
    uint8_t version = ip->ver_ihl >> 4;
    uint8_t ihl = ip->ver_ihl & 0x0F;
    if (version != 4 || ihl < 5) return out;

    size_t ip_hdr_len = ihl * 4;
    if (len < offset + ip_hdr_len) return out;

    uint16_t total_len = ntoh16(ip->total_length);
    if (total_len < ip_hdr_len) return out;

    uint32_t src_ip = ntoh32(ip->src_ip);
    uint32_t dst_ip = ntoh32(ip->dst_ip);
    uint8_t proto = ip->protocol;

    offset += ip_hdr_len;

    if (proto == 6) { // TCP
        if (len < offset + sizeof(TCPHeader)) return out;
        const auto* tcp = reinterpret_cast<const TCPHeader*>(data + offset);
        uint8_t data_offset = (tcp->data_offset_reserved >> 4) & 0x0F;
        if (data_offset < 5) return out;

        size_t tcp_hdr_len = data_offset * 4;
        if (len < offset + tcp_hdr_len) return out;

        uint16_t src_port = ntoh16(tcp->src_port);
        uint16_t dst_port = ntoh16(tcp->dst_port);

        out.key = {src_ip, dst_ip, src_port, dst_port, proto};
        out.payload_len = (total_len > ip_hdr_len + tcp_hdr_len) ? (total_len - ip_hdr_len - tcp_hdr_len) : 0;
        out.tcp_flags = tcp->flags;
        out.valid = true;
        return out;
    }

    if (proto == 17) { // UDP
        if (len < offset + sizeof(UDPHeader)) return out;
        const auto* udp = reinterpret_cast<const UDPHeader*>(data + offset);

        uint16_t src_port = ntoh16(udp->src_port);
        uint16_t dst_port = ntoh16(udp->dst_port);

        out.key = {src_ip, dst_ip, src_port, dst_port, proto};
        out.payload_len = (total_len > ip_hdr_len + sizeof(UDPHeader)) ? (total_len - ip_hdr_len - sizeof(UDPHeader)) : 0;
        out.valid = true;
        return out;
    }

    return out;
}

// =========================
// Analyzer
// =========================

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2, uint64_t idle_timeout_ns)
        : table_(table_capacity_pow2), idle_timeout_ns_(idle_timeout_ns) {}

    void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
        ParsedPacket pkt = parse_packet(data, len);
        if (!pkt.valid) return;

        FlowStats* stats = table_.find_or_insert(pkt.key, ts_ns);
        stats->packets++;
        stats->bytes += pkt.payload_len;

        if (pkt.key.proto == 6) {
            if (pkt.tcp_flags & 0x02) stats->syn++;
            if (pkt.tcp_flags & 0x01) stats->fin++;
            if (pkt.tcp_flags & 0x04) stats->rst++;
        }
    }

    template <typename Fn>
    void expire(Fn&& fn) {
        uint64_t ts = now_ns();
        table_.expire(ts, idle_timeout_ns_, std::forward<Fn>(fn));
    }

    size_t active_flows() const noexcept {
        return table_.size();
    }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
};

// =========================
// Example usage
// =========================

static void export_flow(const FlowKey& k, const FlowStats& s) {
    std::cout << "flow "
              << k.src_ip << ":" << k.src_port
              << " -> " << k.dst_ip << ":" << k.dst_port
              << " proto=" << int(k.proto)
              << " packets=" << s.packets
              << " bytes=" << s.bytes
              << " syn=" << s.syn
              << " fin=" << s.fin
              << " rst=" << s.rst
              << "\n";
}

int main() {
    // 1M entries table; must be power of two
    FlowAnalyzer analyzer(1 << 20, 30ULL * 1000000000ULL); // 30s idle timeout

    // Example packet buffer would come from AF_PACKET, DPDK, PF_RING, libpcap, etc.
    std::vector<uint8_t> packet(64, 0);

    // Simulate processing loop
    for (int i = 0; i < 1000000; ++i) {
        analyzer.process_packet(packet.data(), packet.size(), now_ns());

        if ((i & 0xFFFF) == 0) {
            analyzer.expire(export_flow);
        }
    }

    std::cout << "active flows: " << analyzer.active_flows() << "\n";
    return 0;
}
