    uint8_t hop_limit;
    uint8_t src[16];
    uint8_t dst[16];
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static constexpr uint16_t ETH_P_IPV4 = 0x0800;
static constexpr uint16_t ETH_P_IPV6 = 0x86DD;
static constexpr uint8_t IPPROTO_TCP = 6;
static constexpr uint8_t IPPROTO_UDP = 17;

// =========================
// Flow key / value
// =========================

enum class L3Type : uint8_t { IPv4, IPv6 };

struct FlowKey {
    L3Type l3;
    uint8_t proto; // TCP/UDP/other
    uint16_t src_port;
    uint16_t dst_port;

    // IPv4: use first 4 bytes, IPv6: full 16 bytes
    std::array<uint8_t, 16> src_ip{};
    std::array<uint8_t, 16> dst_ip{};

    bool operator==(const FlowKey& other) const noexcept {
        return l3 == other.l3 &&
               proto == other.proto &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               src_ip == other.src_ip &&
               dst_ip == other.dst_ip;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t hash = 0;
    bool occupied = false;
};

// =========================
// Fast hash
// =========================

static inline uint64_t fnv1a64(const void* data, size_t len) noexcept {
    const uint8_t* p = static_cast<const uint8_t*>(data);
    uint64_t h = 1469598103934665603ULL;
    for (size_t i = 0; i < len; ++i) {
        h ^= p[i];
        h *= 1099511628211ULL;
    }
    return h;
}

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t h = 0;
    h ^= static_cast<uint64_t>(k.l3) * 0x9e3779b185ebca87ULL;
    h ^= static_cast<uint64_t>(k.proto) * 0xc2b2ae3d27d4eb4fULL;
    h ^= static_cast<uint64_t>(k.src_port) << 16;
    h ^= static_cast<uint64_t>(k.dst_port);

    h ^= fnv1a64(k.src_ip.data(), k.l3 == L3Type::IPv4 ? 4 : 16);
    h ^= fnv1a64(k.dst_ip.data(), k.l3 == L3Type::IPv4 ? 4 : 16) << 1;
    return h;
}

// =========================
// Flow table: open addressing
// =========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowStats& update(const FlowKey& key, uint64_t bytes, uint64_t now_ns) noexcept {
        const uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (;;) {
            FlowEntry& e = table_[idx];
            if (!e.occupied) {
                e.occupied = true;
                e.hash = h;
                e.key = key;
                e.stats.packets = 1;
                e.stats.bytes = bytes;
                e.stats.first_seen_ns = now_ns;
                e.stats.last_seen_ns = now_ns;
                ++size_;
                return e.stats;
            }

            if (e.hash == h && e.key == key) {
                e.stats.packets++;
                e.stats.bytes += bytes;
                e.stats.last_seen_ns = now_ns;
                return e.stats;
            }

            idx = (idx + 1) & mask_;
        }
    }

    template <typename Fn>
    void expire(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& fn) {
        for (auto& e : table_) {
            if (!e.occupied) continue;
            if (now_ns - e.stats.last_seen_ns >= idle_timeout_ns) {
                fn(e.key, e.stats);
                e.occupied = false;
                e.stats = {};
                e.hash = 0;
                --size_;
            }
        }
    }

    size_t size() const noexcept { return size_; }

private:
    size_t mask_;
    std::vector<FlowEntry> table_;
    size_t size_ = 0;
};

// =========================
// Packet parsing
// =========================

static inline uint16_t bswap16(uint16_t x) noexcept { return __builtin_bswap16(x); }
static inline uint32_t bswap32(uint32_t x) noexcept { return __builtin_bswap32(x); }

struct ParsedPacket {
    FlowKey key;
    uint32_t l4_len = 0;
};

static inline std::optional<ParsedPacket> parse_packet(std::span<const uint8_t> pkt) noexcept {
    if (pkt.size() < sizeof(EthHdr)) return std::nullopt;

    const auto* eth = reinterpret_cast<const EthHdr*>(pkt.data());
    uint16_t ethertype = bswap16(eth->ethertype);

    size_t off = sizeof(EthHdr);
    ParsedPacket out{};

    if (ethertype == ETH_P_IPV4) {
        if (pkt.size() < off + sizeof(Ipv4Hdr)) return std::nullopt;
        const auto* ip = reinterpret_cast<const Ipv4Hdr*>(pkt.data() + off);

        uint8_t ihl = ip->ver_ihl & 0x0F;
        uint8_t ver = ip->ver_ihl >> 4;
        if (ver != 4 || ihl < 5) return std::nullopt;

        size_t ip_hdr_len = ihl * 4;
        if (pkt.size() < off + ip_hdr_len) return std::nullopt;

        out.key.l3 = L3Type::IPv4;
        out.key.proto = ip->protocol;
        std::memcpy(out.key.src_ip.data(), &ip->src, 4);
        std::memcpy(out.key.dst_ip.data(), &ip->dst, 4);

        off += ip_hdr_len;

        if (ip->protocol == IPPROTO_TCP) {
            if (pkt.size() < off + sizeof(TcpHdr)) return std::nullopt;
            const auto* tcp = reinterpret_cast<const TcpHdr*>(pkt.data() + off);
            out.key.src_port = bswap16(tcp->src_port);
            out.key.dst_port = bswap16(tcp->dst_port);
        } else if (ip->protocol == IPPROTO_UDP) {
            if (pkt.size() < off + sizeof(UdpHdr)) return std::nullopt;
            const auto* udp = reinterpret_cast<const UdpHdr*>(pkt.data() + off);
            out.key.src_port = bswap16(udp->src_port);
            out.key.dst_port = bswap16(udp->dst_port);
        } else {
            out.key.src_port = 0;
            out.key.dst_port = 0;
        }

        out.l4_len = static_cast<uint32_t>(pkt.size() - off);
        return out;
    }

    if (ethertype == ETH_P_IPV6) {
        if (pkt.size() < off + sizeof(Ipv6Hdr)) return std::nullopt;
        const auto* ip6 = reinterpret_cast<const Ipv6Hdr*>(pkt.data() + off);

        uint32_t ver = bswap32(ip6->ver_tc_fl) >> 28;
        if (ver != 6) return std::nullopt;

        out.key.l3 = L3Type::IPv6;
        out.key.proto = ip6->next_header;
        std::memcpy(out.key.src_ip.data(), ip6->src, 16);
        std::memcpy(out.key.dst_ip.data(), ip6->dst, 16);

        off += sizeof(Ipv6Hdr);

        if (ip6->next_header == IPPROTO_TCP) {
            if (pkt.size() < off + sizeof(TcpHdr)) return std::nullopt;
            const auto* tcp = reinterpret_cast<const TcpHdr*>(pkt.data() + off);
            out.key.src_port = bswap16(tcp->src_port);
            out.key.dst_port = bswap16(tcp->dst_port);
        } else if (ip6->next_header == IPPROTO_UDP) {
            if (pkt.size() < off + sizeof(UdpHdr)) return std::nullopt;
            const auto* udp = reinterpret_cast<const UdpHdr*>(pkt.data() + off);
            out.key.src_port = bswap16(udp->src_port);
            out.key.dst_port = bswap16(udp->dst_port);
        } else {
            out.key.src_port = 0;
            out.key.dst_port = 0;
        }

        out.l4_len = static_cast<uint32_t>(pkt.size() - off);
        return out;
    }

    return std::nullopt;
}

// =========================
// Analyzer
// =========================

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2, uint64_t idle_timeout_ns)
        : table_(table_capacity_pow2), idle_timeout_ns_(idle_timeout_ns) {}

    void ingest_packet(std::span<const uint8_t> pkt, uint64_t now_ns) noexcept {
        auto parsed = parse_packet(pkt);
        if (!parsed) return;

        table_.update(parsed->key, pkt.size(), now_ns);
    }

    template <typename Fn>
    void expire(uint64_t now_ns, Fn&& fn) {
        table_.expire(now_ns, idle_timeout_ns_, std::forward<Fn>(fn));
    }

    size_t flow_count() const noexcept { return table_.size(); }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
};

// =========================
// Example usage
// =========================

static uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

int main() {
    // Example: 1M entries, idle timeout 60s
    FlowAnalyzer analyzer(1u << 20, 60ULL * 1'000'000'000ULL);

    // Replace this with real packet capture loop
    std::vector<uint8_t> fake_packet(64, 0);

    // Fake Ethernet + IPv4 + TCP
    auto* eth = reinterpret_cast<EthHdr*>(fake_packet.data());
    eth->ethertype = bswap16(ETH_P_IPV4);

    auto* ip = reinterpret_cast<Ipv4Hdr*>(fake_packet.data() + sizeof(EthHdr));
    ip->ver_ihl = (4 << 4) | 5;
    ip->protocol = IPPROTO_TCP;
    ip->src = 0x0A000001; // 10.0.0.1
    ip->dst = 0x0A000002; // 10.0.0.2

    auto* tcp = reinterpret_cast<TcpHdr*>(fake_packet.data() + sizeof(EthHdr) + sizeof(Ipv4Hdr));
    tcp->src_port = bswap16(12345);
    tcp->dst_port = bswap16(80);

    const uint64_t t = now_ns();
    for (int i = 0; i < 100000; ++i) {
        analyzer.ingest_packet(fake_packet, t + i);
    }

    analyzer.expire(now_ns(), [](const FlowKey&, const FlowStats& s) {
        std::cout << "Expired flow: packets=" << s.packets
                  << " bytes=" << s.bytes << "\n";
    });

    std::cout << "Active flows: " << analyzer.flow_count() << "\n";
    return 0;
}
