};
#pragma pack(pop)

static inline uint16_t bswap16(uint16_t x) {
    return (uint16_t)((x << 8) | (x >> 8));
}

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

static inline uint16_t ntoh16(uint16_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap16(x);
#else
    return x;
#endif
}

static inline uint32_t ntoh32(uint32_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap32(x);
#else
    return x;
#endif
}

// -----------------------------
// Flow key and stats
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t hash = 0;
    bool occupied = false;
};

// -----------------------------
// Fast hash
// -----------------------------
static inline uint64_t mix64(uint64_t x) noexcept {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t x = 0;
    x ^= (uint64_t)k.src_ip * 0x9e3779b185ebca87ULL;
    x ^= (uint64_t)k.dst_ip * 0xc2b2ae3d27d4eb4fULL;
    x ^= (uint64_t)k.src_port << 16;
    x ^= (uint64_t)k.dst_port;
    x ^= (uint64_t)k.proto << 48;
    return mix64(x);
}

// -----------------------------
// Open-addressing flow table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          entries_(capacity_) {}

    FlowStats* update(const FlowKey& key, uint64_t bytes, uint64_t now_ns) {
        uint64_t h = hash_flow_key(key);
        size_t idx = (size_t)h & mask_;

        for (;;) {
            FlowEntry& e = entries_[idx];
            if (!e.occupied) {
                e.occupied = true;
                e.key = key;
                e.hash = h;
                e.stats.packets = 1;
                e.stats.bytes = bytes;
                e.stats.first_seen_ns = now_ns;
                e.stats.last_seen_ns = now_ns;
                ++size_;
                return &e.stats;
            }

            if (e.hash == h && e.key == key) {
                e.stats.packets++;
                e.stats.bytes += bytes;
                e.stats.last_seen_ns = now_ns;
                return &e.stats;
            }

            idx = (idx + 1) & mask_;
        }
    }

    template <typename Fn>
    void expire_inactive(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_expire) {
        for (auto& e : entries_) {
            if (!e.occupied) continue;
            if (now_ns - e.stats.last_seen_ns > idle_timeout_ns) {
                on_expire(e.key, e.stats);
                e.occupied = false;
                --size_;
            }
        }
    }

    size_t size() const noexcept { return size_; }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
    size_t size_ = 0;
};

// -----------------------------
// Packet parsing
// -----------------------------
struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    bool valid = false;
};

static inline ParsedPacket parse_ipv4_packet(const uint8_t* data, size_t len) {
    ParsedPacket out{};
    if (len < sizeof(EthHdr) + sizeof(Ipv4Hdr)) return out;

    const EthHdr* eth = reinterpret_cast<const EthHdr*>(data);
    uint16_t ethertype = ntoh16(eth->ethertype);
    if (ethertype != 0x0800) return out; // IPv4 only

    const Ipv4Hdr* ip = reinterpret_cast<const Ipv4Hdr*>(data + sizeof(EthHdr));
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20) return out;
    if (len < sizeof(EthHdr) + ihl) return out;

    uint16_t total_len = ntoh16(ip->total_len);
    if (total_len < ihl) return out;

    uint32_t src_ip = ntoh32(ip->src);
    uint32_t dst_ip = ntoh32(ip->dst);
    uint8_t proto = ip->protocol;

    const uint8_t* l4 = data + sizeof(EthHdr) + ihl;
    size_t l4_len = len - sizeof(EthHdr) - ihl;

    FlowKey key{};
    key.src_ip = src_ip;
    key.dst_ip = dst_ip;
    key.proto = proto;

    if (proto == 6) { // TCP
        if (l4_len < sizeof(TcpHdr)) return out;
        const TcpHdr* tcp = reinterpret_cast<const TcpHdr*>(l4);
        key.src_port = ntoh16(tcp->src_port);
        key.dst_port = ntoh16(tcp->dst_port);
    } else if (proto == 17) { // UDP
        if (l4_len < sizeof(UdpHdr)) return out;
        const UdpHdr* udp = reinterpret_cast<const UdpHdr*>(l4);
        key.src_port = ntoh16(udp->src_port);
        key.dst_port = ntoh16(udp->dst_port);
    } else {
        return out; // ignore non-TCP/UDP
    }

    out.key = key;
    out.payload_len = total_len - ihl;
    out.valid = true;
    return out;
}

// -----------------------------
// Analyzer
// -----------------------------
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_pow2 = 20)
        : table_(table_pow2) {}

    void process_packet(const uint8_t* data, size_t len, uint64_t now_ns) {
        auto pkt = parse_ipv4_packet(data, len);
        if (unlikely(!pkt.valid)) return;

        // Approximate bytes as captured length; adjust if you want wire length.
        table_.update(pkt.key, len, now_ns);
    }

    template <typename Fn>
    void expire(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_expire) {
        table_.expire_inactive(now_ns, idle_timeout_ns, std::forward<Fn>(on_expire));
    }

    size_t flow_count() const noexcept {
        return table_.size();
    }

private:
    FlowTable table_;
};

