// =====================
// Utility: fast hash
// =====================
static inline uint64_t splitmix64(uint64_t x) noexcept {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

// =====================
// Packet representation
// =====================
struct PacketView {
    const uint8_t* data;
    uint32_t len;
    uint64_t ts_ns;
};

// =====================
// Flow key
// =====================
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t x = 0;
    x ^= splitmix64(static_cast<uint64_t>(k.src_ip));
    x ^= splitmix64(static_cast<uint64_t>(k.dst_ip) << 1);
    x ^= splitmix64(static_cast<uint64_t>(k.src_port) << 16);
    x ^= splitmix64(static_cast<uint64_t>(k.dst_port) << 32);
    x ^= splitmix64(static_cast<uint64_t>(k.proto) << 48);
    return x;
}

// =====================
// Flow record
// =====================
struct FlowRecord {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    bool used = false;
};

// =====================
// Open-addressing flow table
// =====================
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t now_ns) noexcept {
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < table_.size(); ++probe) {
            FlowRecord& r = table_[idx];
            if (!r.used) {
                r.used = true;
                r.key = key;
                r.packets = 0;
                r.bytes = 0;
                r.first_seen_ns = now_ns;
                r.last_seen_ns = now_ns;
                return &r;
            }
            if (r.key == key) {
                return &r;
            }
            idx = (idx + 1) & mask_;
        }
        return nullptr; // table full
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (auto& r : table_) {
            if (r.used) fn(r);
        }
    }

    void age_out(uint64_t now_ns, uint64_t idle_timeout_ns) noexcept {
        for (auto& r : table_) {
            if (r.used && (now_ns - r.last_seen_ns) > idle_timeout_ns) {
                r.used = false;
            }
        }
    }

private:
    size_t mask_;
    std::vector<FlowRecord> table_;
};

// =====================
// Minimal IPv4/TCP/UDP parser
// Assumes Ethernet + IPv4
// =====================
struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    bool valid = false;
};

static inline uint16_t read_be16(const uint8_t* p) noexcept {
    return (uint16_t(p[0]) << 8) | uint16_t(p[1]);
}

static inline uint32_t read_be32(const uint8_t* p) noexcept {
    return (uint32_t(p[0]) << 24) |
           (uint32_t(p[1]) << 16) |
           (uint32_t(p[2]) << 8)  |
           uint32_t(p[3]);
}

static inline ParsedPacket parse_packet(const PacketView& pkt) noexcept {
    ParsedPacket out{};
    if (pkt.len < 14 + 20) return out;

    const uint8_t* p = pkt.data;

    // Ethernet type
    uint16_t ethertype = read_be16(p + 12);
    if (ethertype != 0x0800) return out; // IPv4 only

    const uint8_t* ip = p + 14;
    uint8_t ver_ihl = ip[0];
    uint8_t version = ver_ihl >> 4;
    uint8_t ihl = ver_ihl & 0x0F;
    if (version != 4 || ihl < 5) return out;

    uint32_t ip_hlen = uint32_t(ihl) * 4;
    if (pkt.len < 14 + ip_hlen) return out;

    uint8_t proto = ip[9];
    uint32_t src_ip = read_be32(ip + 12);
    uint32_t dst_ip = read_be32(ip + 16);

    const uint8_t* l4 = ip + ip_hlen;
    uint16_t src_port = 0, dst_port = 0;

    if (proto == 6 || proto == 17) { // TCP/UDP
        if (pkt.len < size_t(l4 - p) + 4) return out;
        src_port = read_be16(l4);
        dst_port = read_be16(l4 + 2);
    } else {
        // For non-TCP/UDP, still track by protocol
        src_port = 0;
        dst_port = 0;
    }

    out.key = FlowKey{src_ip, dst_ip, src_port, dst_port, proto};
    out.payload_len = pkt.len - (14 + ip_hlen);
    out.valid = true;
    return out;
}

// =====================
// Analyzer
// =====================
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2)
        : table_(table_capacity_pow2) {}

    void process_packet(const PacketView& pkt) noexcept {
        ParsedPacket pp = parse_packet(pkt);
        if (!pp.valid) return;

        FlowRecord* rec = table_.find_or_insert(pp.key, pkt.ts_ns);
        if (!rec) {
            dropped_++;
            return;
        }

        rec->packets++;
        rec->bytes += pkt.len;
        rec->last_seen_ns = pkt.ts_ns;
    }

    void age(uint64_t now_ns, uint64_t idle_timeout_ns) noexcept {
        table_.age_out(now_ns, idle_timeout_ns);
    }

    void report_top_flows(size_t n = 10) {
        std::vector<FlowRecord> flows;
        flows.reserve(1024);

        table_.for_each([&](const FlowRecord& r) {
            flows.push_back(r);
        });

        std::sort(flows.begin(), flows.end(), [](const auto& a, const auto& b) {
            return a.bytes > b.bytes;
        });

        std::cout << "Top flows:\n";
        for (size_t i = 0; i < std::min(n, flows.size()); ++i) {
            const auto& f = flows[i];
            std::cout << i + 1
                      << " packets=" << f.packets
                      << " bytes=" << f.bytes
                      << " proto=" << unsigned(f.key.proto)
                      << " sport=" << f.key.src_port
                      << " dport=" << f.key.dst_port
                      << "\n";
        }
        std::cout << "Dropped inserts: " << dropped_.load() << "\n";
    }

private:
    FlowTable table_;
    std::atomic<uint64_t> dropped_{0};
};

// =====================
// Example driver
// =====================
int main() {
    constexpr size_t TABLE_SIZE = 1u << 20; // ~1M entries
    FlowAnalyzer analyzer(TABLE_SIZE);

    // Example packet buffer placeholder
    std::array<uint8_t, 64> dummy{};
    dummy[12] = 0x08; dummy[13] = 0x00; // IPv4 ethertype
    dummy[14] = 0x45; // IPv4, IHL=5
    dummy[23] = 6;    // TCP
    dummy[26] = 192; dummy[27] = 168; dummy[28] = 1; dummy[29] = 10;
    dummy[30] = 192; dummy[31] = 168; dummy[32] = 1; dummy[33] = 20;
    dummy[34] = 0x1F; dummy[35] = 0x90; // src port 8080
    dummy[36] = 0x00; dummy[37] = 0x50; // dst port 80

    PacketView pkt{dummy.data(), static_cast<uint32_t>(dummy.size()), 1000};

    for (int i = 0; i < 100000; ++i) {
        analyzer.process_packet(pkt);
    }

    analyzer.age(10'000'000, 5'000'000);
    analyzer.report_top_flows(5);

    return 0;
}
