```cpp
#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <chrono>
#include <iostream>
#include <optional>
#include <vector>
#include <algorithm>

// -----------------------------
// Packet metadata
// -----------------------------
struct PacketMeta {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;   // e.g. TCP=6, UDP=17
    uint32_t length;     // packet length in bytes
    uint64_t timestamp_ns;
};

// -----------------------------
// Flow key
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Fast hash for FlowKey
static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    // 64-bit mix; good enough for flow hashing
    uint64_t x = 0xcbf29ce484222325ULL;
    auto mix = [&](uint64_t v) {
        x ^= v;
        x *= 0x100000001b3ULL;
    };
    mix(k.src_ip);
    mix(k.dst_ip);
    mix((uint64_t(k.src_port) << 16) | k.dst_port);
    mix(k.protocol);
    return x;
}

// -----------------------------
// Flow entry
// -----------------------------
struct FlowEntry {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    bool occupied = false;
};

// -----------------------------
// Fixed-size open addressing table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          entries_(capacity_) {
        if ((capacity_ & (capacity_ - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    // Insert/update a flow
    FlowEntry* update(const PacketMeta& pkt) noexcept {
        FlowKey key{pkt.src_ip, pkt.dst_ip, pkt.src_port, pkt.dst_port, pkt.protocol};
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        // Linear probing
        for (size_t probe = 0; probe < capacity_; ++probe) {
            FlowEntry& e = entries_[idx];

            if (!e.occupied) {
                // New entry
                e.occupied = true;
                e.key = key;
                e.packets = 1;
                e.bytes = pkt.length;
                e.first_seen_ns = pkt.timestamp_ns;
                e.last_seen_ns = pkt.timestamp_ns;
                return &e;
            }

            if (e.key == key) {
                // Existing flow
                ++e.packets;
                e.bytes += pkt.length;
                e.last_seen_ns = pkt.timestamp_ns;
                return &e;
            }

            idx = (idx + 1) & mask_;
        }

        // Table full
        return nullptr;
    }

    // Expire flows inactive for timeout_ns
    template <typename Callback>
    void expire(uint64_t now_ns, uint64_t timeout_ns, Callback cb) {
        for (auto& e : entries_) {
            if (e.occupied && (now_ns - e.last_seen_ns > timeout_ns)) {
                cb(e);
                e = FlowEntry{};
            }
        }
    }

    size_t size() const noexcept {
        size_t n = 0;
        for (const auto& e : entries_) {
            if (e.occupied) ++n;
        }
        return n;
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
};

// -----------------------------
// Analyzer
// -----------------------------
class NetworkFlowAnalyzer {
public:
    explicit NetworkFlowAnalyzer(size_t table_pow2 = 20) // ~1M slots
        : table_(table_pow2) {}

    void ingest(const PacketMeta& pkt) noexcept {
        auto* entry = table_.update(pkt);
        if (!entry) {
            dropped_.fetch_add(1, std::memory_order_relaxed);
        } else {
            processed_.fetch_add(1, std::memory_order_relaxed);
            bytes_.fetch_add(pkt.length, std::memory_order_relaxed);
        }
    }

    void expire_old(uint64_t now_ns, uint64_t timeout_ns) {
        table_.expire(now_ns, timeout_ns, [&](const FlowEntry& e) {
            // Replace with logging / export / metrics sink
            expired_.fetch_add(1, std::memory_order_relaxed);
            // Example output (avoid in hot path)
            // std::cout << "Expired flow: packets=" << e.packets
            //           << " bytes=" << e.bytes << "\n";
        });
    }

    void print_stats() const {
        std::cout << "processed=" << processed_.load()
                  << " bytes=" << bytes_.load()
                  << " dropped=" << dropped_.load()
                  << " expired=" << expired_.load()
                  << " active_flows=" << table_.size()
                  << "\n";
    }

private:
    FlowTable table_;
    std::atomic<uint64_t> processed_{0};
    std::atomic<uint64_t> bytes_{0};
    std::atomic<uint64_t> dropped_{0};
    std::atomic<uint64_t> expired_{0};
};

// -----------------------------
// Example usage
// -----------------------------
int main() {
    NetworkFlowAnalyzer analyzer(20); // 2^20 entries

    // Simulated packets
    const uint64_t t0 = 1'000'000'000ULL;
    for (uint32_t i = 0; i < 1'000'000; ++i) {
        PacketMeta pkt{
            .src_ip = 0x0A000001 + (i % 1024),
            .dst_ip = 0x0A000100 + (i % 256),
            .src_port = static_cast<uint16_t>(10000 + (i % 1000)),
            .dst_port = 443,
            .protocol = 6,
            .length = 64 + (i % 1400),
            .timestamp_ns = t0 + i * 1000
        };
        analyzer.ingest(pkt);

        if ((i % 100000) == 0) {
            analyzer.expire_old(pkt.timestamp_ns, 5'000'000'000ULL); // 5s timeout
        }
    }

    analyzer.print_stats();
    return 0;
}
