// =========================
// SPSC ring buffer
// =========================

template <typename T, size_t CapacityPow2>
class SpscRing {
    static_assert((CapacityPow2 & (CapacityPow2 - 1)) == 0, "Capacity must be power of two");
public:
    bool push(const T& item) noexcept {
        const size_t h = head_.load(std::memory_order_relaxed);
        const size_t next = (h + 1) & mask_;
        if (next == tail_.load(std::memory_order_acquire)) return false;
        buffer_[h] = item;
        head_.store(next, std::memory_order_release);
        return true;
    }

    bool pop(T& out) noexcept {
        const size_t t = tail_.load(std::memory_order_relaxed);
        if (t == head_.load(std::memory_order_acquire)) return false;
        out = buffer_[t];
        tail_.store((t + 1) & mask_, std::memory_order_release);
        return true;
    }

private:
    static constexpr size_t mask_ = CapacityPow2 - 1;
    std::array<T, CapacityPow2> buffer_{};
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
};

// =========================
// Flow table: open addressing
// =========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(capacity_pow2), mask_(capacity_pow2 - 1), table_(capacity_pow2) {}

    FlowEntry* find_or_insert(const FlowKey& key) noexcept {
        size_t idx = hasher_(key) & mask_;
        size_t first_tombstone = capacity_; // sentinel

        for (;;) {
            FlowEntry& e = table_[idx];
            if (!e.occupied) {
                if (!e.tombstone) {
                    // Empty slot
                    if (first_tombstone != capacity_) idx = first_tombstone;
                    FlowEntry& target = table_[idx];
                    target.key = key;
                    target.stats = {};
                    target.occupied = true;
                    target.tombstone = false;
                    return &target;
                } else if (first_tombstone == capacity_) {
                    first_tombstone = idx;
                }
            } else if (e.key == key) {
                return &e;
            }
            idx = (idx + 1) & mask_;
        }
    }

    template <typename Fn>
    void expire(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_expire) {
        for (auto& e : table_) {
            if (e.occupied && (now_ns - e.stats.last_seen_ns >= idle_timeout_ns)) {
                on_expire(e.key, e.stats);
                e.occupied = false;
                e.tombstone = true;
            }
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> table_;
    FlowKeyHash hasher_;
};

// =========================
// Packet parsing helpers
// =========================

static inline uint16_t bswap16(uint16_t x) {
    return (uint16_t)((x >> 8) | (x << 8));
}

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

static inline uint16_t ntoh16(uint16_t x) { return bswap16(x); }
static inline uint32_t ntoh32(uint32_t x) { return bswap32(x); }

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    bool valid = false;
};

ParsedPacket parse_packet(const PacketView& p) {
    ParsedPacket out{};
    if (p.len < sizeof(EthernetHeader)) return out;

    const auto* eth = reinterpret_cast<const EthernetHeader*>(p.data);
    uint16_t ethertype = ntoh16(eth->ethertype);
    if (ethertype != 0x0800) return out; // IPv4 only

    size_t off = sizeof(EthernetHeader);
    if (p.len < off + sizeof(IPv4Header)) return out;

    const auto* ip = reinterpret_cast<const IPv4Header*>(p.data + off);
    uint8_t ihl = ip->ver_ihl & 0x0F;
    uint8_t version = ip->ver_ihl >> 4;
    if (version != 4 || ihl < 5) return out;

    size_t ip_hdr_len = ihl * 4;
    if (p.len < off + ip_hdr_len) return out;

    uint8_t proto = ip->protocol;
    uint32_t src_ip = ntoh32(ip->src_ip);
    uint32_t dst_ip = ntoh32(ip->dst_ip);

    off += ip_hdr_len;

    uint16_t src_port = 0, dst_port = 0;
    if (proto == 6) { // TCP
        if (p.len < off + sizeof(TCPHeader)) return out;
        const auto* tcp = reinterpret_cast<const TCPHeader*>(p.data + off);
        src_port = ntoh16(tcp->src_port);
        dst_port = ntoh16(tcp->dst_port);
        uint8_t doff = (tcp->data_offset_reserved >> 4) & 0x0F;
        size_t tcp_hdr_len = doff * 4;
        if (doff < 5 || p.len < off + tcp_hdr_len) return out;
        off += tcp_hdr_len;
    } else if (proto == 17) { // UDP
        if (p.len < off + sizeof(UDPHeader)) return out;
        const auto* udp = reinterpret_cast<const UDPHeader*>(p.data + off);
        src_port = ntoh16(udp->src_port);
        dst_port = ntoh16(udp->dst_port);
        off += sizeof(UDPHeader);
    } else {
        // Non-TCP/UDP flows can still be tracked with ports = 0
    }

    out.key = FlowKey{src_ip, dst_ip, src_port, dst_port, proto};
    out.payload_len = (p.len > off) ? static_cast<uint32_t>(p.len - off) : 0;
    out.valid = true;
    return out;
}

// =========================
// Flow analyser
// =========================

class FlowAnalyzer {
public:
    FlowAnalyzer(size_t flow_table_pow2, uint64_t idle_timeout_ns)
        : flows_(flow_table_pow2), idle_timeout_ns_(idle_timeout_ns) {}

    void process_packet(const PacketView& pkt) noexcept {
        ParsedPacket parsed = parse_packet(pkt);
        if (!parsed.valid) return;

        FlowEntry* e = flows_.find_or_insert(parsed.key);
        if (e->stats.packets == 0) {
            e->stats.first_seen_ns = pkt.ts_ns;
        }
        e->stats.packets++;
        e->stats.bytes += parsed.payload_len;
        e->stats.last_seen_ns = pkt.ts_ns;
    }

    template <typename Fn>
    void expire(uint64_t now_ns, Fn&& on_expire) {
        flows_.expire(now_ns, idle_timeout_ns_, std::forward<Fn>(on_expire));
    }

private:
    FlowTable flows_;
    uint64_t idle_timeout_ns_;
};

// =========================
// Example ingestion loop
// =========================

int main() {
    constexpr size_t RingSize = 1 << 16;
    constexpr size_t FlowTableSize = 1 << 20;

    SpscRing<PacketView, RingSize> ring;
    FlowAnalyzer analyzer(FlowTableSize, 30ULL * 1000 * 1000 * 1000); // 30s idle timeout

    std::atomic<bool> running{true};

    // Producer thread placeholder: replace with real capture backend
    std::thread producer([&] {
        while (running.load(std::memory_order_relaxed)) {
            // In real code, fill from NIC/capture backend.
            // Here we just sleep.
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    });

    // Consumer thread
    std::thread consumer([&] {
        PacketView pkt{};
        while (running.load(std::memory_order_relaxed)) {
            while (ring.pop(pkt)) {
                analyzer.process_packet(pkt);
            }

            auto now_ns = (uint64_t)std::chrono::duration_cast<std::chrono::nanoseconds>(
                std::chrono::steady_clock::now().time_since_epoch()).count();

            analyzer.expire(now_ns, [](const FlowKey& key, const FlowStats& stats) {
                std::cout << "Expired flow: "
                          << key.src_ip << ":" << key.src_port
