                          << " proto=" << (int)key.protocol
                          << " packets=" << stats.packets
                          << " bytes=" << stats.bytes
                          << "\n";
            });

            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    });

    std::this_thread::sleep_for(std::chrono::seconds(2));
    running.store(false);

    producer.join();
    consumer.join();
    return 0;
}
