#include <chrono>
#include <algorithm>

// -----------------------------
// Packet / protocol definitions
// -----------------------------

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t header_checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct IPv6Header {
    uint32_t ver_tc_fl;
    uint16_t payload_length;
    uint8_t next_header;
    uint8_t hop_limit;
    uint8_t src_ip[16];
    uint8_t dst_ip[16];
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t length;
    uint16_t checksum;
};
#pragma pack(pop)

static constexpr uint16_t ETHERTYPE_IPV4 = 0x0800;
static constexpr uint16_t ETHERTYPE_IPV6 = 0x86DD;
static constexpr uint8_t IPPROTO_TCP = 6;
static constexpr uint8_t IPPROTO_UDP = 17;

// -----------------------------
// Utility
// -----------------------------

static inline uint16_t bswap16(uint16_t x) { return __builtin_bswap16(x); }
static inline uint32_t bswap32(uint32_t x) { return __builtin_bswap32(x); }

static inline uint16_t ntoh16(uint16_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap16(x);
#else
    return x;
#endif
}

static inline uint32_t ntoh32(uint32_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap32(x);
#else
    return x;
#endif
}

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

// -----------------------------
// Flow key
// -----------------------------

struct FlowKey {
    uint8_t ip_version;   // 4 or 6
    uint8_t protocol;     // TCP/UDP/other
    uint16_t src_port;
    uint16_t dst_port;

    union {
        struct {
            uint32_t src_ip;
            uint32_t dst_ip;
        } v4;
        struct {
            std::array<uint8_t, 16> src_ip;
            std::array<uint8_t, 16> dst_ip;
        } v6;
    };

    bool operator==(const FlowKey& other) const noexcept {
        if (ip_version != other.ip_version || protocol != other.protocol ||
            src_port != other.src_port || dst_port != other.dst_port) {
            return false;
        }
        if (ip_version == 4) {
            return v4.src_ip == other.v4.src_ip && v4.dst_ip == other.v4.dst_ip;
        }
        return v6.src_ip == other.v6.src_ip && v6.dst_ip == other.v6.dst_ip;
    }
};

static inline uint64_t hash64(uint64_t x) {
    // SplitMix64
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t h = 0xcbf29ce484222325ULL;
    auto mix = [&](uint64_t v) {
        h ^= hash64(v);
        h *= 0x100000001b3ULL;
    };

    mix(k.ip_version);
    mix(k.protocol);
    mix(k.src_port);
    mix(k.dst_port);

    if (k.ip_version == 4) {
        mix(k.v4.src_ip);
        mix(k.v4.dst_ip);
    } else {
        const uint64_t* s = reinterpret_cast<const uint64_t*>(k.v6.src_ip.data());
        const uint64_t* d = reinterpret_cast<const uint64_t*>(k.v6.dst_ip.data());
        mix(s[0]); mix(s[1]);
        mix(d[0]); mix(d[1]);
    }
    return h;
}

// -----------------------------
// Flow record
// -----------------------------

struct FlowRecord {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    bool occupied = false;
};

// -----------------------------
// Fixed-size open-addressing flow table
// -----------------------------

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          table_(capacity_) {}

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t ts_ns) noexcept {
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < capacity_; ++probe) {
            FlowRecord& slot = table_[idx];
            if (!slot.occupied) {
                slot.occupied = true;
                slot.key = key;
                slot.packets = 0;
                slot.bytes = 0;
                slot.first_seen_ns = ts_ns;
                slot.last_seen_ns = ts_ns;
                return &slot;
            }
            if (slot.key == key) {
                slot.last_seen_ns = ts_ns;
                return &slot;
            }
            idx = (idx + 1) & mask_;
        }
        return nullptr; // table full
    }

    template <typename Fn>
    void expire_older_than(uint64_t cutoff_ns, Fn&& fn) {
        for (auto& slot : table_) {
            if (slot.occupied && slot.last_seen_ns < cutoff_ns) {
                fn(slot);
                slot.occupied = false;
            }
        }
    }

    template <typename Fn>
    void for_each(Fn&& fn) const {
        for (const auto& slot : table_) {
            if (slot.occupied) fn(slot);
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowRecord> table_;
};

// -----------------------------
// Packet parsing
// -----------------------------

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_bytes = 0;
    bool valid = false;
};

static inline ParsedPacket parse_packet(std::span<const uint8_t> pkt) noexcept {
    ParsedPacket out{};
    if (pkt.size() < sizeof(EthernetHeader)) return out;

    const auto* eth = reinterpret_cast<const EthernetHeader*>(pkt.data());
    uint16_t ethertype = ntoh16(eth->ethertype);

    size_t offset = sizeof(EthernetHeader);

    if (ethertype == ETHERTYPE_IPV4) {
        if (pkt.size() < offset + sizeof(IPv4Header)) return out;
        const auto* ip = reinterpret_cast<const IPv4Header*>(pkt.data() + offset);

        uint8_t ihl = ip->ver_ihl & 0x0F;
        uint8_t version = ip->ver_ihl >> 4;
        if (version != 4 || ihl < 5) return out;

        size_t ip_header_len = ihl * 4;
        if (pkt.size() < offset + ip_header_len) return out;

        uint8_t proto = ip->protocol;
        if (proto != IPPROTO_TCP && proto != IPPROTO_UDP) return out;

        offset += ip_header_len;

        if (proto == IPPROTO_TCP) {
            if (pkt.size() < offset + sizeof(TCPHeader)) return out;
            const auto* tcp = reinterpret_cast<const TCPHeader*>(pkt.data() + offset);
            uint8_t doff = (tcp->data_offset_reserved >> 4) & 0x0F;
            if (doff < 5) return out;
            offset += doff * 4;
            if (pkt.size() < offset) return out;

            out.key.ip_version = 4;
            out.key.protocol = proto;
            out.key.src_port = ntoh16(tcp->src_port);
            out.key.dst_port = ntoh16(tcp->dst_port);
            out.key.v4.src_ip = ntoh32(ip->src_ip);
            out.key.v4.dst_ip = ntoh32(ip->dst_ip);
            out.payload_bytes = static_cast<uint32_t>(pkt.size() - offset);
            out.valid = true;
            return out;
        } else {
            if (pkt.size() < offset + sizeof(UDPHeader)) return out;
            const auto* udp = reinterpret_cast<const UDPHeader*>(pkt.data() + offset);
            offset += sizeof(UDPHeader);
            if (pkt.size() < offset) return out;

            out.key.ip_version = 4;
            out.key.protocol = proto;
            out.key.src_port = ntoh16(udp->src_port);
            out.key.dst_port = ntoh16(udp->dst_port);
            out.key.v4.src_ip = ntoh32(ip->src_ip);
            out.key.v4.dst_ip = ntoh32(ip->dst_ip);
            out.payload_bytes = static_cast<uint32_t>(pkt.size() - offset);
            out.valid = true;
            return out;
        }
    } else if (ethertype == ETHERTYPE_IPV6) {
        if (pkt.size() < offset + sizeof(IPv6Header)) return out;
        const auto* ip6 = reinterpret_cast<const IPv6Header*>(pkt.data() + offset);

        uint8_t version = static_cast<uint8_t>(ntoh32(ip6->ver_tc_fl) >> 28);
        if (version != 6) return out;

        uint8_t proto = ip6->next_header;
        if (proto != IPPROTO_TCP && proto != IPPROTO_UDP) return out;

        offset += sizeof(IPv6Header);

        if (proto == IPPROTO_TCP) {
            if (pkt.size() < offset + sizeof(TCPHeader)) return out;
            const auto* tcp = reinterpret_cast<const TCPHeader*>(pkt.data() + offset);
            uint8_t doff = (tcp->data_offset_reserved >> 4) & 0x0F;
            if (doff < 5) return out;
            offset += doff * 4;
            if (pkt.size() < offset) return out;

            out.key.ip_version = 6;
            out.key.protocol = proto;
            out.key.src_port = ntoh16(tcp->src_port);
            out.key.dst_port = ntoh16(tcp->dst_port);
            std::memcpy(out.key.v6.src_ip.data(), ip6->src_ip, 16);
            std::memcpy(out.key.v6.dst_ip.data(), ip6->dst_ip, 16);
            out.payload_bytes = static_cast<uint32_t>(pkt.size() - offset);
            out.valid = true;
            return out;
        } else {
            if (pkt.size() < offset + sizeof(UDPHeader)) return out;
            const auto* udp = reinterpret_cast<const UDPHeader*>(pkt.data() + offset);
            offset += sizeof(UDPHeader);
            if (pkt.size() < offset) return out;

            out.key.ip_version = 6;
            out.key.protocol = proto;
            out.key.src_port = ntoh16(udp->src_port);
            out.key.dst_port = ntoh16(udp->dst_port);
            std::memcpy(out.key.v6.src_ip.data(), ip6->src_ip, 16);
            std::memcpy(out.key.v6.dst_ip.data(), ip6->dst_ip, 16);
            out.payload_bytes = static_cast<uint32_t>(pkt.size() - offset);
            out.valid = true;
            return out;
        }
    }

    return out;
}

// -----------------------------
// Analyzer
// -----------------------------

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_pow2)
        : flows_(table_pow2) {}

    void process_packet(std::span<const uint8_t> pkt, uint64_t ts_ns) noexcept {
        ParsedPacket parsed = parse_packet(pkt);
        if (!parsed.valid) return;

        FlowRecord* rec = flows_.find_or_insert(parsed.key, ts_ns);
        if (!rec) {
            dropped_++;
            return;
        }

        rec->packets++;
        rec->bytes += pkt.size();
        rec->last_seen_ns = ts_ns;
    }

    void expire(uint64_t idle_timeout_ns) {
        uint64_t cutoff = now_ns() - idle_timeout_ns;
        flows_.expire_older_than(cutoff, [&](const FlowRecord& rec) {
            // Replace with export to ring buffer / telemetry sink
            std::cout << "Expired flow: packets=" << rec.packets
                      << " bytes=" << rec.bytes << "\n";
        });
    }

    void dump_top_flows() const {
        std::vector<const FlowRecord*> active;
        active.reserve(1024);

        flows_.for_each([&](const FlowRecord& rec) {
            active.push_back(&rec);
        });

        std::sort(active.begin(), active.end(),
                  [](const FlowRecord* a, const FlowRecord* b) {
                      return a->bytes > b->bytes;
                  });

        size_t n = std::min<size_t>(10, active.size());
        for (size_t i = 0; i < n; ++i) {
            std::cout << "#" << i
                      << " packets=" << active[i]->packets
                      << " bytes=" << active[i]->bytes
                      << "\n";
        }
    }

    uint64_t dropped() const noexcept { return dropped_.load(std::memory_order_relaxed); }

private:
    FlowTable flows_;
    std::atomic<uint64_t> dropped_{0};
};

// -----------------------------
// Example driver
// -----------------------------

int main() {
    // 2^20 slots ~ 1,048,576 flows
    FlowAnalyzer analyzer(20);

    // Example packet buffer (replace with real capture input)
    std::vector<uint8_t> fake_packet(64, 0);

    // Fake Ethernet + IPv4 + UDP
    auto* eth = reinterpret_cast<EthernetHeader*>(fake_packet.data());
    eth->ethertype = bswap16(ETHERTYPE_IPV4);

    auto* ip = reinterpret_cast<IPv4Header*>(fake_packet.data() + sizeof(EthernetHeader));
    ip->ver_ihl = (4 << 4) | 5;
    ip->protocol = IPPROTO_UDP;
    ip->src_ip = bswap32(0x0A000001); // 10.0.0.1
    ip->dst_ip = bswap32(0x0A000002); // 10.0.0.2

    auto* udp = reinterpret_cast<UDPHeader*>(fake_packet.data() + sizeof(EthernetHeader) + sizeof(IPv4Header));
    udp->src_port = bswap16(12345);
    udp->dst_port = bswap16(53);

    uint64_t ts = now_ns();
    for (int i = 0; i < 100000; ++i) {
        analyzer.process_packet(fake_packet, ts + i);
    }

    analyzer.dump_top_flows();
    std::cout << "Dropped: " << analyzer.dropped() << "\n";

    return 0;
}
