#if defined(__GNUC__) || defined(__clang__)
#define likely(x)   __builtin_expect(!!(x), 1)
#define unlikely(x) __builtin_expect(!!(x), 0)
#else
#define likely(x)   (x)
#define unlikely(x) (x)
#endif

// -----------------------------
// Packet headers
// -----------------------------
#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

// -----------------------------
// Helpers
// -----------------------------
static inline uint16_t bswap16(uint16_t x) {
    return (x >> 8) | (x << 8);
}

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

static inline uint16_t ntoh16(uint16_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap16(x);
#else
    return x;
#endif
}

static inline uint32_t ntoh32(uint32_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap32(x);
#else
    return x;
#endif
}

// -----------------------------
// Flow key / stats
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast mix for 5-tuple
        uint64_t x = (uint64_t)k.src_ip << 32 | k.dst_ip;
        x ^= (uint64_t)k.src_port << 16 | k.dst_port;
        x ^= (uint64_t)k.proto * 0x9e3779b97f4a7c15ULL;
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return (size_t)x;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

// -----------------------------
// Sharded flow table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t shard_count = 64)
        : shards_(shard_count) {}

    void update(const FlowKey& key, uint32_t pkt_len, uint64_t now_ns) {
        auto& shard = shards_[FlowKeyHash{}(key) % shards_.size()];
        shard.update(key, pkt_len, now_ns);
    }

    template<typename Fn>
    void for_each_flow(Fn&& fn) {
        for (auto& shard : shards_) {
            shard.for_each_flow(std::forward<Fn>(fn));
        }
    }

    void expire(uint64_t now_ns, uint64_t idle_timeout_ns) {
        for (auto& shard : shards_) {
            shard.expire(now_ns, idle_timeout_ns);
        }
    }

private:
    struct Shard {
        std::unordered_map<FlowKey, FlowStats, FlowKeyHash> map;
        std::shared_mutex mutex;

        void update(const FlowKey& key, uint32_t pkt_len, uint64_t now_ns) {
            std::unique_lock lock(mutex);
            auto& s = map[key];
            if (s.packets == 0) {
                s.first_seen_ns = now_ns;
            }
            s.packets++;
            s.bytes += pkt_len;
            s.last_seen_ns = now_ns;
        }

        template<typename Fn>
        void for_each_flow(Fn&& fn) {
            std::shared_lock lock(mutex);
            for (auto& [k, v] : map) {
                fn(k, v);
            }
        }

        void expire(uint64_t now_ns, uint64_t idle_timeout_ns) {
            std::unique_lock lock(mutex);
            for (auto it = map.begin(); it != map.end(); ) {
                if (now_ns - it->second.last_seen_ns > idle_timeout_ns) {
                    it = map.erase(it);
                } else {
                    ++it;
                }
            }
        }
    };

    std::vector<Shard> shards_;
};

// -----------------------------
// Packet parser
// -----------------------------
class PacketParser {
public:
    // Returns true if packet is a valid IPv4 TCP/UDP packet and fills flow key.
    static bool parse(const uint8_t* data, size_t len, FlowKey& out_key, uint32_t& out_pkt_len) {
        if (unlikely(len < sizeof(EthHdr))) return false;

        const auto* eth = reinterpret_cast<const EthHdr*>(data);
        uint16_t ethertype = ntoh16(eth->ethertype);
        if (ethertype != 0x0800) return false; // IPv4 only

        if (unlikely(len < sizeof(EthHdr) + sizeof(Ipv4Hdr))) return false;
        const auto* ip = reinterpret_cast<const Ipv4Hdr*>(data + sizeof(EthHdr));

        uint8_t version = ip->ver_ihl >> 4;
        uint8_t ihl = ip->ver_ihl & 0x0F;
        if (version != 4 || ihl < 5) return false;

        size_t ip_hdr_len = ihl * 4;
        if (unlikely(len < sizeof(EthHdr) + ip_hdr_len)) return false;

        uint16_t total_len = ntoh16(ip->total_len);
        if (total_len < ip_hdr_len) return false;

        uint8_t proto = ip->protocol;
        if (proto != 6 && proto != 17) return false; // TCP/UDP only

        uint32_t src_ip = ntoh32(ip->src);
        uint32_t dst_ip = ntoh32(ip->dst);

        const uint8_t* l4 = data + sizeof(EthHdr) + ip_hdr_len;
        size_t l4_len = len - sizeof(EthHdr) - ip_hdr_len;

        if (proto == 6) {
            if (unlikely(l4_len < sizeof(TcpHdr))) return false;
            const auto* tcp = reinterpret_cast<const TcpHdr*>(l4);
            out_key.src_port = ntoh16(tcp->src_port);
            out_key.dst_port = ntoh16(tcp->dst_port);
        } else {
            if (unlikely(l4_len < sizeof(UdpHdr))) return false;
            const auto* udp = reinterpret_cast<const UdpHdr*>(l4);
            out_key.src_port = ntoh16(udp->src_port);
            out_key.dst_port = ntoh16(udp->dst_port);
        }

        out_key.src_ip = src_ip;
        out_key.dst_ip = dst_ip;
        out_key.proto = proto;
        out_pkt_len = total_len;
        return true;
    }
};

// -----------------------------
// Batch processor
// -----------------------------
struct PacketView {
    const uint8_t* data;
    size_t len;
    uint64_t timestamp_ns;
};

class Analyzer {
public:
    explicit Analyzer(size_t shard_count = 64)
        : flows_(shard_count) {}

    void process_batch(const std::vector<PacketView>& batch) {
        FlowKey key{};
        uint32_t pkt_len = 0;

        for (const auto& pkt : batch) {
            if (likely(PacketParser::parse(pkt.data, pkt.len, key, pkt_len))) {
                flows_.update(key, pkt_len, pkt.timestamp_ns);
            }
        }
    }

    void expire(uint64_t now_ns, uint64_t idle_timeout_ns) {
        flows_.expire(now_ns, idle_timeout_ns);
    }

    template<typename Fn>
    void for_each_flow(Fn&& fn) {
        flows_.for_each_flow(std::forward<Fn>(fn));
    }

private:
    FlowTable flows_;
};

