// Example usage
// -----------------------------
int main() {
    Analyzer analyzer(128);

    // Example: fake packet buffer
    std::vector<uint8_t> packet(64, 0);
    auto* eth = reinterpret_cast<EthHdr*>(packet.data());
    eth->ethertype = ntoh16(0x0800);

    auto* ip = reinterpret_cast<Ipv4Hdr*>(packet.data() + sizeof(EthHdr));
    ip->ver_ihl = (4 << 4) | 5;
    ip->protocol = 17;
    ip->total_len = ntoh16(64);
    ip->src = ntoh32(0x0A000001); // 10.0.0.1
    ip->dst = ntoh32(0x0A000002); // 10.0.0.2

    auto* udp = reinterpret_cast<UdpHdr*>(packet.data() + sizeof(EthHdr) + sizeof(Ipv4Hdr));
    udp->src_port = ntoh16(12345);
    udp->dst_port = ntoh16(53);

    std::vector<PacketView> batch;
    batch.push_back({packet.data(), packet.size(), 1000000000ULL});

    analyzer.process_batch(batch);

    analyzer.for_each_flow([](const FlowKey& k, const FlowStats& s) {
        std::cout << "Flow "
                  << ntoh32(k.src_ip) << ":" << k.src_port
                  << " -> " << ntoh32(k.dst_ip) << ":" << k.dst_port
                  << " proto=" << (int)k.proto
                  << " packets=" << s.packets
                  << " bytes=" << s.bytes
                  << "\n";
    });

    return 0;
}
