#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#include <array>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <optional>
#include <string_view>
#include <thread>
#include <vector>
#include <algorithm>

// -----------------------------
// Fast utilities
// -----------------------------

static inline uint64_t now_ns() noexcept {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

static inline uint32_t rotl32(uint32_t x, int r) noexcept {
    return (x << r) | (x >> (32 - r));
}

// A simple fast hash for 5-tuple keys.
// For production, consider xxHash / wyhash / cityhash.
static inline uint64_t hash64(uint64_t x) noexcept {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

// -----------------------------
// Packet / flow definitions
// -----------------------------

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    OTHER = 255
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Pack into 128-ish bits conceptually, then mix.
        uint64_t a = (uint64_t(k.src_ip) << 32) | k.dst_ip;
        uint64_t b = (uint64_t(k.src_port) << 48) |
                     (uint64_t(k.dst_port) << 32) |
                     (uint64_t(k.proto) << 24);
        return static_cast<size_t>(hash64(a ^ hash64(b)));
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes   = 0;
    uint64_t first_ns = 0;
    uint64_t last_ns  = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t last_touch_ns = 0;
    bool occupied = false;
};

// -----------------------------
// Cache-friendly open-addressing flow table
// -----------------------------

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowEntry* find_or_insert(const FlowKey& key, uint64_t ts_ns) noexcept {
        size_t idx = FlowKeyHash{}(key) & mask_;
        for (size_t probe = 0; probe < table_.size(); ++probe) {
            FlowEntry& e = table_[idx];
            if (!e.occupied) {
                e.occupied = true;
                e.key = key;
                e.stats = {};
                e.stats.first_ns = ts_ns;
                e.stats.last_ns = ts_ns;
                e.last_touch_ns = ts_ns;
                return &e;
            }
            if (e.key == key) {
                e.last_touch_ns = ts_ns;
                return &e;
            }
            idx = (idx + 1) & mask_;
        }
        return nullptr; // table full
    }

    template <typename Fn>
    void expire_older_than(uint64_t cutoff_ns, Fn&& fn) {
        for (auto& e : table_) {
            if (e.occupied && e.last_touch_ns < cutoff_ns) {
                fn(e);
                e.occupied = false;
            }
        }
    }

private:
    size_t mask_;
    std::vector<FlowEntry> table_;
};

// -----------------------------
// Packet parsing
// -----------------------------

#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};
#pragma pack(pop)

static constexpr uint16_t ETH_P_IPV4 = 0x0800;
static constexpr uint16_t ETH_P_VLAN = 0x8100;

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    uint64_t ts_ns = 0;
    bool valid = false;
};

static inline uint16_t read_be16(const void* p) noexcept {
    uint16_t v;
    std::memcpy(&v, p, sizeof(v));
    return ntohs(v);
}

static inline uint32_t read_be32(const void* p) noexcept {
    uint32_t v;
    std::memcpy(&v, p, sizeof(v));
    return ntohl(v);
}

static inline ParsedPacket parse_packet(const uint8_t* data, size_t len, uint64_t ts_ns) noexcept {
    ParsedPacket out;
    out.ts_ns = ts_ns;

    if (len < sizeof(EthHdr)) return out;

    const auto* eth = reinterpret_cast<const EthHdr*>(data);
    uint16_t ethertype = ntohs(eth->ethertype);
    size_t offset = sizeof(EthHdr);

    if (ethertype == ETH_P_VLAN) {
        if (len < offset + 4) return out;
        ethertype = read_be16(data + offset + 2);
        offset += 4;
    }

    if (ethertype != ETH_P_IPV4) return out;
    if (len < offset + sizeof(iphdr)) return out;

    const auto* ip = reinterpret_cast<const iphdr*>(data + offset);
    if (ip->version != 4) return out;

    const size_t ip_hlen = ip->ihl * 4;
    if (ip_hlen < sizeof(iphdr)) return out;
    if (len < offset + ip_hlen) return out;

    const uint32_t ip_total_len = ntohs(ip->tot_len);
    if (ip_total_len < ip_hlen) return out;

    const uint8_t proto = ip->protocol;
    if (proto != IPPROTO_TCP && proto != IPPROTO_UDP) return out;

    const uint8_t* l4 = data + offset + ip_hlen;
    size_t l4_len = len - (offset + ip_hlen);
    if (l4_len < 4) return out;

    FlowKey key{};
    key.src_ip = ntohl(ip->saddr);
    key.dst_ip = ntohl(ip->daddr);
    key.proto = proto;

    if (proto == IPPROTO_TCP) {
        if (l4_len < sizeof(tcphdr)) return out;
        const auto* tcp = reinterpret_cast<const tcphdr*>(l4);
        key.src_port = ntohs(tcp->source);
        key.dst_port = ntohs(tcp->dest);
        const size_t tcp_hlen = tcp->doff * 4;
        if (tcp_hlen < sizeof(tcphdr) || l4_len < tcp_hlen) return out;
        out.payload_len = (ip_total_len - ip_hlen - tcp_hlen);
    } else {
        if (l4_len < sizeof(udphdr)) return out;
        const auto* udp = reinterpret_cast<const udphdr*>(l4);
        key.src_port = ntohs(udp->source);
        key.dst_port = ntohs(udp->dest);
        const uint16_t udp_len = ntohs(udp->len);
        if (udp_len < sizeof(udphdr)) return out;
        out.payload_len = udp_len - sizeof(udphdr);
    }

    out.key = key;
    out.valid = true;
    return out;
}

// -----------------------------
// Analyzer
// -----------------------------

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2, uint64_t idle_timeout_ns)
        : table_(table_capacity_pow2), idle_timeout_ns_(idle_timeout_ns) {}

    void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) noexcept {
        auto pkt = parse_packet(data, len, ts_ns);
        if (!pkt.valid) return;

        FlowEntry* e = table_.find_or_insert(pkt.key, pkt.ts_ns);
        if (!e) {
            dropped_++;
            return;
        }

        e->stats.packets += 1;
        e->stats.bytes += pkt.payload_len;
        e->stats.last_ns = pkt.ts_ns;
    }

    template <typename Fn>
    void expire(Fn&& fn) {
        const uint64_t cutoff = now_ns() - idle_timeout_ns_;
        table_.expire_older_than(cutoff, std::forward<Fn>(fn));
    }

    uint64_t dropped() const noexcept { return dropped_.load(std::memory_order_relaxed); }

private:
    FlowTable table_;
    uint64_t idle_timeout_ns_;
    std::atomic<uint64_t> dropped_{0};
};

