static inline std::string ip_to_string(uint32_t ip_host_order) {
    in_addr addr{};
    addr.s_addr = htonl(ip_host_order);
    char buf[INET_ADDRSTRLEN];
    const char* s = inet_ntop(AF_INET, &addr, buf, sizeof(buf));
    return s ? std::string(s) : std::string("0.0.0.0");
}

static void export_flow(const FlowEntry& e) {
    std::cout
        << ip_to_string(e.key.src_ip) << ":" << e.key.src_port
        << " -> "
