        << " proto=" << int(e.key.proto)
        << " packets=" << e.stats.packets
        << " bytes=" << e.stats.bytes
        << " first_ns=" << e.stats.first_ns
        << " last_ns=" << e.stats.last_ns
        << "\n";
}

