#else
#define ALWAYS_INLINE inline
#define LIKELY(x)   (x)
#define UNLIKELY(x) (x)
#endif

// -----------------------------
// Packet parsing
// -----------------------------
#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TCPHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct UDPHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static constexpr uint16_t ETHERTYPE_IPV4 = 0x0800;
static constexpr uint8_t IPPROTO_TCP = 6;
static constexpr uint8_t IPPROTO_UDP = 17;

// -----------------------------
// Flow key / record
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_ts_ns = 0;
    uint64_t last_ts_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t hash = 0;
    bool occupied = false;
};

// -----------------------------
// Fast hash
// -----------------------------
ALWAYS_INLINE uint64_t mix64(uint64_t x) noexcept {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

ALWAYS_INLINE uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t x = 0;
    x ^= uint64_t(k.src_ip) * 0x9e3779b185ebca87ULL;
    x ^= uint64_t(k.dst_ip) * 0xc2b2ae3d27d4eb4fULL;
    x ^= uint64_t(k.src_port) << 16;
    x ^= uint64_t(k.dst_port) << 32;
    x ^= uint64_t(k.proto) << 48;
    return mix64(x);
}

// -----------------------------
// Sharded flow table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(capacity_pow2),
          mask_(capacity_pow2 - 1),
          entries_(capacity_pow2) {}

    ALWAYS_INLINE void update(const FlowKey& key, uint64_t bytes, uint64_t ts_ns) noexcept {
        const uint64_t h = hash_flow_key(key);
        size_t idx = size_t(h) & mask_;

        // Linear probing
        for (;;) {
            FlowEntry& e = entries_[idx];
            if (!e.occupied) {
                e.key = key;
                e.hash = h;
                e.occupied = true;
                e.stats.packets = 1;
                e.stats.bytes = bytes;
                e.stats.first_ts_ns = ts_ns;
                e.stats.last_ts_ns = ts_ns;
                ++size_;
                return;
            }
            if (e.hash == h && e.key == key) {
                e.stats.packets++;
                e.stats.bytes += bytes;
                e.stats.last_ts_ns = ts_ns;
                return;
            }
            idx = (idx + 1) & mask_;
        }
    }

    template <typename Fn>
    void age_and_export(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& fn) {
        for (auto& e : entries_) {
            if (!e.occupied) continue;
            if (now_ns - e.stats.last_ts_ns >= idle_timeout_ns) {
                fn(e.key, e.stats);
                e.occupied = false;
                e.stats = {};
                --size_;
            }
        }
    }

    size_t size() const noexcept { return size_; }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> entries_;
    std::atomic<size_t> size_{0};
};

// -----------------------------
// Analyzer
// -----------------------------
class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t shards_pow2, size_t table_capacity_pow2)
        : shard_mask_(shards_pow2 - 1) {
        shards_.reserve(shards_pow2);
        for (size_t i = 0; i < shards_pow2; ++i) {
            shards_.emplace_back(table_capacity_pow2);
        }
    }

    ALWAYS_INLINE void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) noexcept {
        if (UNLIKELY(len < sizeof(EthHdr))) return;

        const auto* eth = reinterpret_cast<const EthHdr*>(data);
        uint16_t ethertype = ntohs16(eth->ethertype);
        if (ethertype != ETHERTYPE_IPV4) return;

        const size_t ip_off = sizeof(EthHdr);
        if (UNLIKELY(len < ip_off + sizeof(IPv4Hdr))) return;

        const auto* ip = reinterpret_cast<const IPv4Hdr*>(data + ip_off);
        const uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
        if (UNLIKELY(ihl < 20 || len < ip_off + ihl)) return;

        if (ip->protocol != IPPROTO_TCP && ip->protocol != IPPROTO_UDP) return;

        FlowKey key{};
        key.src_ip = ip->src;
        key.dst_ip = ip->dst;
        key.proto = ip->protocol;

        const size_t l4_off = ip_off + ihl;
        if (ip->protocol == IPPROTO_TCP) {
            if (UNLIKELY(len < l4_off + sizeof(TCPHdr))) return;
            const auto* tcp = reinterpret_cast<const TCPHdr*>(data + l4_off);
            key.src_port = tcp->src_port;
            key.dst_port = tcp->dst_port;
        } else {
            if (UNLIKELY(len < l4_off + sizeof(UDPHdr))) return;
            const auto* udp = reinterpret_cast<const UDPHdr*>(data + l4_off);
            key.src_port = udp->src_port;
            key.dst_port = udp->dst_port;
        }

        const size_t shard = hash_flow_key(key) & shard_mask_;
        shards_[shard].update(key, len, ts_ns);
    }

    template <typename Fn>
    void age_and_export_all(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& fn) {
        for (auto& s : shards_) {
            s.age_and_export(now_ns, idle_timeout_ns, fn);
        }
    }

private:
    static ALWAYS_INLINE uint16_t ntohs16(uint16_t x) noexcept {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
        return __builtin_bswap16(x);
#else
        return x;
#endif
    }

    std::vector<FlowTable> shards_;
    size_t shard_mask_;
};

// -----------------------------
// Example usage
// -----------------------------
int main() {
    constexpr size_t shards = 64;
    constexpr size_t table_capacity = 1 << 20; // per shard, must be power of 2

    FlowAnalyzer analyzer(shards, table_capacity);

    // Example packet buffer would come from NIC/driver.
    std::vector<uint8_t> packet(64, 0);

    // Fake Ethernet + IPv4 + TCP headers for demonstration only.
    auto* eth = reinterpret_cast<EthHdr*>(packet.data());
    eth->ethertype = 0x0008; // network byte order for 0x0800 on little-endian demo

    auto* ip = reinterpret_cast<IPv4Hdr*>(packet.data() + sizeof(EthHdr));
    ip->ver_ihl = 0x45;
    ip->protocol = IPPROTO_TCP;
    ip->src = 0x0a000001; // 10.0.0.1
    ip->dst = 0x0a000002; // 10.0.0.2

    auto* tcp = reinterpret_cast<TCPHdr*>(packet.data() + sizeof(EthHdr) + 20);
    tcp->src_port = 0x3930; // demo
    tcp->dst_port = 0x5000; // demo

    uint64_t now_ns = std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()).count();

    analyzer.process_packet(packet.data(), packet.size(), now_ns);

    analyzer.age_and_export_all(now_ns + 10'000'000'000ULL, 5'000'000'000ULL,
        [](const FlowKey& key, const FlowStats& stats) {
            std::cout << "Expired flow: "
                      << key.src_ip << ":" << key.src_port
                      << " -> " << key.dst_ip << ":" << key.dst_port
                      << " proto=" << int(key.proto)
                      << " packets=" << stats.packets
                      << " bytes=" << stats.bytes << "\n";
        });

    return 0;
}
