struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
    uint8_t  pad[3]; // align to 16 bytes

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast 64-bit mix
        uint64_t x = 0;
        x ^= (uint64_t)k.src_ip * 0x9E3779B185EBCA87ULL;
        x ^= (uint64_t)k.dst_ip * 0xC2B2AE3D27D4EB4FULL;
        x ^= (uint64_t)k.src_port << 16;
        x ^= (uint64_t)k.dst_port << 32;
        x ^= (uint64_t)k.protocol << 48;

        // final avalanche
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return (size_t)x;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

// ============================
// Flow entry
// ============================

struct FlowEntry {
    FlowKey key;
    FlowStats stats;
    bool used = false;
};

// ============================
// Sharded flow table
// ============================

class FlowTable {
public:
    explicit FlowTable(size_t shards = 64, size_t per_shard_capacity = 1 << 16)
        : shards_(shards), tables_(shards) {
        for (auto& s : tables_) {
            s.reserve(per_shard_capacity);
        }
    }

    void update(const FlowKey& key, uint32_t bytes, uint64_t ts_ns) {
        auto& shard = tables_[shard_index(key)];
        std::lock_guard<std::mutex> lock(shard.mtx);

        auto it = shard.map.find(key);
        if (it == shard.map.end()) {
            FlowStats st;
            st.packets = 1;
            st.bytes = bytes;
            st.first_seen_ns = ts_ns;
            st.last_seen_ns = ts_ns;
            shard.map.emplace(key, st);
        } else {
            auto& st = it->second;
            st.packets++;
            st.bytes += bytes;
            st.last_seen_ns = ts_ns;
        }
    }

    template <typename Fn>
    void age_and_export(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& export_fn) {
        for (auto& shard : tables_) {
            std::lock_guard<std::mutex> lock(shard.mtx);
            for (auto it = shard.map.begin(); it != shard.map.end(); ) {
                if (now_ns - it->second.last_seen_ns >= idle_timeout_ns) {
                    export_fn(it->first, it->second);
                    it = shard.map.erase(it);
                } else {
                    ++it;
                }
            }
        }
    }

private:
    struct Shard {
        std::mutex mtx;
        std::unordered_map<FlowKey, FlowStats, FlowKeyHash> map;
    };

    size_t shards_;
    std::vector<Shard> tables_;

    size_t shard_index(const FlowKey& key) const noexcept {
        return FlowKeyHash{}(key) % shards_;
    }
};

// ============================
// Packet parsing
// ============================

static inline bool parse_flow_key(const uint8_t* data, size_t len, FlowKey& out_key, uint32_t& out_bytes) {
    if (len < sizeof(EthernetHeader)) return false;

    const auto* eth = reinterpret_cast<const EthernetHeader*>(data);
    uint16_t ethertype = __builtin_bswap16(eth->ethertype);
    size_t offset = sizeof(EthernetHeader);

    // IPv4 only
    if (ethertype != 0x0800) return false;
    if (len < offset + sizeof(IPv4Header)) return false;

    const auto* ip = reinterpret_cast<const IPv4Header*>(data + offset);
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20) return false;
    if (len < offset + ihl) return false;

    out_key.src_ip = ip->src_ip;
    out_key.dst_ip = ip->dst_ip;
    out_key.protocol = ip->protocol;

    offset += ihl;

    if (ip->protocol == 6) { // TCP
        if (len < offset + sizeof(TCPHeader)) return false;
        const auto* tcp = reinterpret_cast<const TCPHeader*>(data + offset);
        out_key.src_port = tcp->src_port;
        out_key.dst_port = tcp->dst_port;
    } else if (ip->protocol == 17) { // UDP
        if (len < offset + sizeof(UDPHeader)) return false;
        const auto* udp = reinterpret_cast<const UDPHeader*>(data + offset);
        out_key.src_port = udp->src_port;
        out_key.dst_port = udp->dst_port;
    } else {
        out_key.src_port = 0;
        out_key.dst_port = 0;
    }

    out_bytes = static_cast<uint32_t>(len);
    return true;
}

// ============================
// Bounded SPSC queue
// ============================

template <typename T, size_t CapacityPow2>
class SPSCQueue {
    static_assert((CapacityPow2 & (CapacityPow2 - 1)) == 0, "Capacity must be power of 2");

public:
    bool push(const T& v) {
        auto h = head_.load(std::memory_order_relaxed);
        auto next = (h + 1) & mask_;
        if (next == tail_.load(std::memory_order_acquire)) return false;
        buffer_[h] = v;
        head_.store(next, std::memory_order_release);
        return true;
    }

    bool pop(T& out) {
        auto t = tail_.load(std::memory_order_relaxed);
        if (t == head_.load(std::memory_order_acquire)) return false;
        out = buffer_[t];
        tail_.store((t + 1) & mask_, std::memory_order_release);
        return true;
    }

private:
    static constexpr size_t mask_ = CapacityPow2 - 1;
    std::array<T, CapacityPow2> buffer_{};
    alignas(64) std::atomic<size_t> head_{0};
    alignas(64) std::atomic<size_t> tail_{0};
};

// ============================
// Packet event
// ============================

struct PacketEvent {
    FlowKey key{};
    uint32_t bytes = 0;
    uint64_t ts_ns = 0;
};

// ============================
// Analyzer
// ============================

class NetworkFlowAnalyzer {
public:
    NetworkFlowAnalyzer()
        : flow_table_(64, 1 << 15), running_(false) {}

    void start() {
        running_.store(true, std::memory_order_release);

        worker_ = std::thread([this] { worker_loop(); });
        ager_ = std::thread([this] { aging_loop(); });
    }

    void stop() {
        running_.store(false, std::memory_order_release);
        if (worker_.joinable()) worker_.join();
        if (ager_.joinable()) ager_.join();
    }

    // Ingest raw packet bytes
    void ingest_packet(const uint8_t* data, size_t len) {
        PacketEvent ev;
        if (!parse_flow_key(data, len, ev.key, ev.bytes)) return;
        ev.ts_ns = now_ns();

        // Backpressure: drop if queue full
        if (!queue_.push(ev)) {
            dropped_.fetch_add(1, std::memory_order_relaxed);
        }
    }

    uint64_t dropped() const {
        return dropped_.load(std::memory_order_relaxed);
    }

private:
    void worker_loop() {
        PacketEvent ev;
        while (running_.load(std::memory_order_acquire)) {
            while (queue_.pop(ev)) {
                flow_table_.update(ev.key, ev.bytes, ev.ts_ns);
            }
            std::this_thread::yield();
        }

        // Drain remaining
        while (queue_.pop(ev)) {
            flow_table_.update(ev.key, ev.bytes, ev.ts_ns);
        }
    }

    void aging_loop() {
        using namespace std::chrono_literals;
        constexpr uint64_t idle_timeout_ns = 30ULL * 1000ULL * 1000ULL * 1000ULL; // 30s

        while (running_.load(std::memory_order_acquire)) {
            std::this_thread::sleep_for(1s);
            uint64_t ts = now_ns();
            flow_table_.age_and_export(ts, idle_timeout_ns,
                [](const FlowKey& key, const FlowStats& st) {
                    std::cout << "FLOW "
                              << "src_ip=" << key.src_ip
                              << " dst_ip=" << key.dst_ip
                              << " src_port=" << key.src_port
                              << " dst_port=" << key.dst_port
                              << " proto=" << (int)key.protocol
                              << " packets=" << st.packets
                              << " bytes=" << st.bytes
                              << "\n";
                });
        }
    }

    FlowTable flow_table_;
    SPSCQueue<PacketEvent, 1 << 16> queue_;
    std::atomic<bool> running_;
    std::atomic<uint64_t> dropped_{0};
    std::thread worker_;
    std::thread ager_;
};

// ============================
// Example usage
// ============================

int main() {
    NetworkFlowAnalyzer analyzer;
    analyzer.start();

    // Simulated packet buffer (not a real packet)
    std::vector<uint8_t> pkt(64, 0);
    auto* eth = reinterpret_cast<EthernetHeader*>(pkt.data());
    eth->ethertype = __builtin_bswap16(0x0800);

    auto* ip = reinterpret_cast<IPv4Header*>(pkt.data() + sizeof(EthernetHeader));
    ip->ver_ihl = 0x45;
    ip->protocol = 6;
    ip->src_ip = 0x0A000001; // 10.0.0.1
    ip->dst_ip = 0x0A000002; // 10.0.0.2

    auto* tcp = reinterpret_cast<TCPHeader*>(pkt.data() + sizeof(EthernetHeader) + sizeof(IPv4Header));
    tcp->src_port = 12345;
    tcp->dst_port = 80;

    for (int i = 0; i < 100000; ++i) {
        analyzer.ingest_packet(pkt.data(), pkt.size());
    }

    std::this_thread::sleep_for(std::chrono::seconds(2));
    analyzer.stop();

    std::cout << "Dropped packets: " << analyzer.dropped() << "\n";
    return 0;
}
