#include <array>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iostream>
#include <memory_resource>
#include <mutex>
#include <optional>
#include <thread>
#include <unordered_map>
#include <vector>

#if defined(__GNUC__) || defined(__clang__)
#define PREFETCH(addr) __builtin_prefetch((addr), 0, 1)
#else
#define PREFETCH(addr) ((void)0)
#endif

// -----------------------------
// Packet / Flow definitions
// -----------------------------

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    OTHER = 255
};

struct PacketView {
    const uint8_t* data;
    uint32_t len;
    uint64_t ts_ns;
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& o) const noexcept {
        return src_ip == o.src_ip &&
               dst_ip == o.dst_ip &&
               src_port == o.src_port &&
               dst_port == o.dst_port &&
               proto == o.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast 64-bit mix
        uint64_t x = 0;
        x ^= (uint64_t)k.src_ip * 0x9E3779B185EBCA87ULL;
        x ^= (uint64_t)k.dst_ip * 0xC2B2AE3D27D4EB4FULL;
        x ^= (uint64_t)k.src_port << 16;
        x ^= (uint64_t)k.dst_port << 32;
        x ^= (uint64_t)k.proto << 48;

        // final avalanche
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return (size_t)x;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_ts_ns = 0;
    uint64_t last_ts_ns = 0;
    uint32_t tcp_flags = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    uint64_t last_seen_ns = 0;
};

// -----------------------------
// Packet parsing (minimal IPv4)
// -----------------------------

#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t proto;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static inline uint16_t bswap16(uint16_t x) {
    return (uint16_t)((x >> 8) | (x << 8));
}

static inline uint32_t bswap32(uint32_t x) {
    return __builtin_bswap32(x);
}

static inline uint16_t ntoh16(uint16_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap16(x);
#else
    return x;
#endif
}

static inline uint32_t ntoh32(uint32_t x) {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap32(x);
#else
    return x;
#endif
}

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    uint8_t tcp_flags = 0;
    bool valid = false;
};

static inline ParsedPacket parse_ipv4_packet(const PacketView& p) {
    ParsedPacket out{};
    if (p.len < sizeof(EthHdr) + sizeof(Ipv4Hdr)) return out;

    const auto* eth = reinterpret_cast<const EthHdr*>(p.data);
    uint16_t ethertype = ntoh16(eth->ethertype);
    if (ethertype != 0x0800) return out; // IPv4 only

    const auto* ip = reinterpret_cast<const Ipv4Hdr*>(p.data + sizeof(EthHdr));
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20) return out;
    if (p.len < sizeof(EthHdr) + ihl) return out;

    uint32_t src_ip = ntoh32(ip->src);
    uint32_t dst_ip = ntoh32(ip->dst);
    uint8_t proto = ip->proto;

    const uint8_t* l4 = p.data + sizeof(EthHdr) + ihl;
    uint32_t l4_len = p.len - (sizeof(EthHdr) + ihl);

    FlowKey key{};
    key.src_ip = src_ip;
    key.dst_ip = dst_ip;
    key.proto = proto;

    if (proto == (uint8_t)L4Proto::TCP) {
        if (l4_len < sizeof(TcpHdr)) return out;
        const auto* tcp = reinterpret_cast<const TcpHdr*>(l4);
        key.src_port = ntoh16(tcp->src_port);
        key.dst_port = ntoh16(tcp->dst_port);
        out.tcp_flags = tcp->flags;
        out.payload_len = l4_len - ((tcp->data_offset_reserved >> 4) * 4);
    } else if (proto == (uint8_t)L4Proto::UDP) {
        if (l4_len < sizeof(UdpHdr)) return out;
        const auto* udp = reinterpret_cast<const UdpHdr*>(l4);
        key.src_port = ntoh16(udp->src_port);
        key.dst_port = ntoh16(udp->dst_port);
        out.payload_len = l4_len - sizeof(UdpHdr);
    } else {
        key.src_port = 0;
        key.dst_port = 0;
        out.payload_len = l4_len;
    }

    out.key = key;
    out.valid = true;
    return out;
}

// -----------------------------
// Sharded flow table
// -----------------------------

class FlowShard {
public:
    explicit FlowShard(size_t reserve = 1 << 16)
        : map_(reserve) {}

    void update(const ParsedPacket& pkt) {
        auto it = map_.find(pkt.key);
        if (it == map_.end()) {
            FlowEntry e;
            e.key = pkt.key;
            e.stats.packets = 1;
            e.stats.bytes = pkt.payload_len;
            e.stats.first_ts_ns = e.stats.last_ts_ns = current_ts_;
            e.last_seen_ns = current_ts_;
            map_.emplace(pkt.key, e);
            return;
        }

        auto& s = it->second.stats;
        s.packets++;
        s.bytes += pkt.payload_len;
        s.last_ts_ns = current_ts_;
        it->second.last_seen_ns = current_ts_;
        it->second.stats.tcp_flags |= pkt.tcp_flags;
    }

    void set_now(uint64_t ts_ns) {
        current_ts_ = ts_ns;
    }

    template <typename Fn>
    void expire(uint64_t older_than_ns, Fn&& fn) {
        for (auto it = map_.begin(); it != map_.end();) {
            if (it->second.last_seen_ns < older_than_ns) {
                fn(it->second);
                it = map_.erase(it);
            } else {
                ++it;
            }
        }
    }

    size_t size() const noexcept {
        return map_.size();
    }

private:
    std::unordered_map<FlowKey, FlowEntry, FlowKeyHash> map_;
    uint64_t current_ts_ = 0;
};

class FlowTable {
public:
    static constexpr size_t kShards = 64;

    FlowTable() {
        for (auto& s : shards_) {
            s = std::make_unique<FlowShard>(1 << 14);
        }
    }

    void update(const ParsedPacket& pkt, uint64_t ts_ns) {
        const size_t idx = shard_index(pkt.key);
        auto& shard = *shards_[idx];
        shard.set_now(ts_ns);
        shard.update(pkt);
    }

    template <typename Fn>
    void expire(uint64_t older_than_ns, Fn&& fn) {
        for (auto& s : shards_) {
            s->expire(older_than_ns, fn);
        }
    }

    size_t total_size() const {
        size_t n = 0;
        for (const auto& s : shards_) n += s->size();
        return n;
    }

private:
    static size_t shard_index(const FlowKey& k) {
        return FlowKeyHash{}(k) & (kShards - 1);
    }

    std::array<std::unique_ptr<FlowShard>, kShards> shards_;
};

// -----------------------------
// Analyzer pipeline
// -----------------------------

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(uint64_t flow_timeout_ns)
        : flow_timeout_ns_(flow_timeout_ns) {}

    void process_batch(const PacketView* packets, size_t count) {
        for (size_t i = 0; i < count; ++i) {
            const auto& p = packets[i];
            ParsedPacket parsed = parse_ipv4_packet(p);
            if (!parsed.valid) continue;
            table_.update(parsed, p.ts_ns);
        }
    }

    void expire_old(uint64_t now_ns) {
        const uint64_t cutoff = now_ns > flow_timeout_ns_ ? now_ns - flow_timeout_ns_ : 0;
        table_.expire(cutoff, [](const FlowEntry& e) {
            // Hook: export flow record, aggregate, log, etc.
            // Keep this path lightweight in production.
            (void)e;
        });
    }

    size_t flow_count() const {
        return table_.total_size();
    }

private:
    uint64_t flow_timeout_ns_;
    FlowTable table_;
};

// -----------------------------
// Example driver
// -----------------------------

int main() {
    FlowAnalyzer analyzer(std::chrono::seconds(30).count() * 1000000000ULL);

    // Example: process a batch of packets from a capture source.
    std::vector<PacketView> batch;
    batch.reserve(1024);

    // In real use, fill batch from AF_PACKET, DPDK, PF_RING, or libpcap.
    // Here we just show the API shape.

    analyzer.process_batch(batch.data(), batch.size());
    analyzer.expire_old(0);

    std::cout << "Active flows: " << analyzer.flow_count() << "\n";
    return 0;
}
