## C++20 flow analyzer core

```cpp
#include <array>
#include <atomic>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iostream>
#include <memory>
#include <optional>
#include <span>
#include <thread>
#include <unordered_map>
#include <vector>

// =========================
// Packet parsing structures
// =========================

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct IPv6Header {
    uint32_t ver_tc_fl;
    uint16_t payload_length;
    uint8_t next_header;
    uint8_t hop_limit;
    uint8_t src_ip[16];
    uint8_t dst_ip[16];
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static_assert(sizeof(EthernetHeader) == 14);
static_assert(sizeof(IPv4Header) == 20);
static_assert(sizeof(IPv6Header) == 40);
static_assert(sizeof(TCPHeader) == 20);
static_assert(sizeof(UDPHeader) == 8);

// =========================
// Flow key and stats
// =========================

struct FlowKey {
    uint8_t ip_version;   // 4 or 6
    uint8_t protocol;     // TCP/UDP/etc
    uint16_t src_port;
    uint16_t dst_port;

    // IPv4 uses first 4 bytes; IPv6 uses full 16 bytes
    std::array<uint8_t, 16> src_ip{};
    std::array<uint8_t, 16> dst_ip{};

    bool operator==(const FlowKey& other) const noexcept {
        return ip_version == other.ip_version &&
               protocol == other.protocol &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               src_ip == other.src_ip &&
               dst_ip == other.dst_ip;
    }
};

struct FlowKeyHash {
    static inline uint64_t mix64(uint64_t x) noexcept {
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return x;
    }

    size_t operator()(const FlowKey& k) const noexcept {
        uint64_t h = 0xcbf29ce484222325ULL;
        auto add = [&](const void* data, size_t len) {
            const uint8_t* p = static_cast<const uint8_t*>(data);
            for (size_t i = 0; i < len; ++i) {
                h ^= p[i];
                h *= 0x100000001b3ULL;
            }
        };

        add(&k.ip_version, sizeof(k.ip_version));
        add(&k.protocol, sizeof(k.protocol));
        add(&k.src_port, sizeof(k.src_port));
        add(&k.dst_port, sizeof(k.dst_port));
        add(k.src_ip.data(), k.src_ip.size());
        add(k.dst_ip.data(), k.dst_ip.size());

        return static_cast<size_t>(mix64(h));
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

// =========================
// Utility
// =========================

static inline uint16_t bswap16(uint16_t x) noexcept {
    return static_cast<uint16_t>((x >> 8) | (x << 8));
}

static inline uint32_t bswap32(uint32_t x) noexcept {
    return ((x & 0x000000FFu) << 24) |
           ((x & 0x0000FF00u) << 8)  |
           ((x & 0x00FF0000u) >> 8)  |
           ((x & 0xFF000000u) >> 24);
}

#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
static inline uint16_t ntoh16(uint16_t x) noexcept { return bswap16(x); }
static inline uint32_t ntoh32(uint32_t x) noexcept { return bswap32(x); }
#else
static inline uint16_t ntoh16(uint16_t x) noexcept { return x; }
static inline uint32_t ntoh32(uint32_t x) noexcept { return x; }
#endif

// =========================
// Flow analyzer
// =========================

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t expected_flows = 1 << 20)
        : flows_(expected_flows) {
        flows_.max_load_factor(0.7f);
    }

    void process_packet(std::span<const uint8_t> pkt, uint64_t now_ns) {
        if (pkt.size() < sizeof(EthernetHeader)) return;

        const auto* eth = reinterpret_cast<const EthernetHeader*>(pkt.data());
        uint16_t ethertype = ntoh16(eth->ethertype);

        size_t offset = sizeof(EthernetHeader);

        // VLAN support (single tag)
        if (ethertype == 0x8100 && pkt.size() >= offset + 4) {
            ethertype = ntoh16(*reinterpret_cast<const uint16_t*>(pkt.data() + offset + 2));
            offset += 4;
        }

        FlowKey key{};
        uint16_t payload_len = 0;

        if (ethertype == 0x0800) { // IPv4
            if (pkt.size() < offset + sizeof(IPv4Header)) return;
            const auto* ip = reinterpret_cast<const IPv4Header*>(pkt.data() + offset);

            uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
            if (ihl < 20 || pkt.size() < offset + ihl) return;

            key.ip_version = 4;
            key.protocol = ip->protocol;

            std::memcpy(key.src_ip.data(), &ip->src_ip, 4);
            std::memcpy(key.dst_ip.data(), &ip->dst_ip, 4);

            offset += ihl;

            if (ip->protocol == 6) { // TCP
                if (pkt.size() < offset + sizeof(TCPHeader)) return;
                const auto* tcp = reinterpret_cast<const TCPHeader*>(pkt.data() + offset);
                key.src_port = ntoh16(tcp->src_port);
                key.dst_port = ntoh16(tcp->dst_port);
            } else if (ip->protocol == 17) { // UDP
                if (pkt.size() < offset + sizeof(UDPHeader)) return;
                const auto* udp = reinterpret_cast<const UDPHeader*>(pkt.data() + offset);
                key.src_port = ntoh16(udp->src_port);
                key.dst_port = ntoh16(udp->dst_port);
            } else {
                key.src_port = 0;
                key.dst_port = 0;
            }

            payload_len = ntoh16(ip->total_length);
        }
        else if (ethertype == 0x86DD) { // IPv6
            if (pkt.size() < offset + sizeof(IPv6Header)) return;
            const auto* ip6 = reinterpret_cast<const IPv6Header*>(pkt.data() + offset);

            key.ip_version = 6;
            key.protocol = ip6->next_header;
            std::memcpy(key.src_ip.data(), ip6->src_ip, 16);
            std::memcpy(key.dst_ip.data(), ip6->dst_ip, 16);

            offset += sizeof(IPv6Header);

            if (ip6->next_header == 6) {
                if (pkt.size() < offset + sizeof(TCPHeader)) return;
                const auto* tcp = reinterpret_cast<const TCPHeader*>(pkt.data() + offset);
                key.src_port = ntoh16(tcp->src_port);
                key.dst_port = ntoh16(tcp->dst_port);
            } else if (ip6->next_header == 17) {
                if (pkt.size() < offset + sizeof(UDPHeader)) return;
                const auto* udp = reinterpret_cast<const UDPHeader*>(pkt.data() + offset);
                key.src_port = ntoh16(udp->src_port);
                key.dst_port = ntoh16(udp->dst_port);
            } else {
                key.src_port = 0;
                key.dst_port = 0;
            }

            payload_len = ntoh16(ip6->payload_length) + sizeof(IPv6Header);
        } else {
            return; // non-IP
        }

        auto& st = flows_[key];
        if (st.packets == 0) {
            st.first_seen_ns = now_ns;
        }
        st.last_seen_ns = now_ns;
        st.packets++;
        st.bytes += pkt.size(); // or payload_len if you want L3 bytes
    }

    void expire_old(uint64_t now_ns, uint64_t idle_timeout_ns) {
        for (auto it = flows_.begin(); it != flows_.end(); ) {
            if (now_ns - it->second.last_seen_ns > idle_timeout_ns) {
                it = flows_.erase(it);
            } else {
                ++it;
            }
        }
    }

    void print_summary() const {
        std::cout << "Active flows: " << flows_.size() << "\n";
    }

private:
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows_;
};

