#include <chrono>

// =========================
// Utility
// =========================

static inline uint64_t rdtsc_fallback_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

static inline uint64_t fnv1a64(const void* data, size_t len) {
    const uint8_t* p = static_cast<const uint8_t*>(data);
    uint64_t h = 1469598103934665603ULL;
    for (size_t i = 0; i < len; ++i) {
        h ^= p[i];
        h *= 1099511628211ULL;
    }
    return h;
}

// =========================
// Flow key
// =========================

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
    uint8_t  pad[3]{};

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    return fnv1a64(&k, sizeof(FlowKey));
}

// =========================
// Flow record
// =========================

struct FlowRecord {
    FlowKey key{};
    uint64_t packets{0};
    uint64_t bytes{0};
    uint64_t first_seen_ns{0};
    uint64_t last_seen_ns{0};
    bool occupied{false};
};

// =========================
// Fixed-size flat hash table
// =========================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(capacity_pow2),
          mask_(capacity_pow2 - 1),
          table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t now_ns) noexcept {
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < capacity_; ++probe) {
            FlowRecord& slot = table_[idx];

            if (!slot.occupied) {
                slot.occupied = true;
                slot.key = key;
                slot.packets = 0;
                slot.bytes = 0;
                slot.first_seen_ns = now_ns;
                slot.last_seen_ns = now_ns;
                return &slot;
            }

            if (slot.key == key) {
                return &slot;
            }

            idx = (idx + 1) & mask_;
        }

        return nullptr; // table full
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (auto& slot : table_) {
            if (slot.occupied) fn(slot);
        }
    }

    void age_out(uint64_t now_ns, uint64_t idle_timeout_ns) noexcept {
        for (auto& slot : table_) {
            if (slot.occupied && (now_ns - slot.last_seen_ns) > idle_timeout_ns) {
                slot.occupied = false;
            }
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowRecord> table_;
};

// =========================
// Packet parsing
// =========================

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len{0};
    bool valid{false};
};

static inline ParsedPacket parse_packet(const uint8_t* data, size_t len) noexcept {
    ParsedPacket out{};

    if (len < sizeof(ether_header)) return out;

    const ether_header* eth = reinterpret_cast<const ether_header*>(data);
    uint16_t eth_type = ntohs(eth->ether_type);

    if (eth_type != ETHERTYPE_IP) return out;

    size_t offset = sizeof(ether_header);
    if (len < offset + sizeof(iphdr)) return out;

    const iphdr* ip = reinterpret_cast<const iphdr*>(data + offset);
    if (ip->version != 4) return out;

    size_t ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(iphdr) || len < offset + ip_hdr_len) return out;

    uint8_t proto = ip->protocol;
    uint32_t src_ip = ip->saddr;
    uint32_t dst_ip = ip->daddr;

    uint16_t src_port = 0;
    uint16_t dst_port = 0;

    if (proto == IPPROTO_TCP) {
        if (len < offset + ip_hdr_len + sizeof(tcphdr)) return out;
        const tcphdr* tcp = reinterpret_cast<const tcphdr*>(data + offset + ip_hdr_len);
        src_port = ntohs(tcp->source);
        dst_port = ntohs(tcp->dest);
    } else if (proto == IPPROTO_UDP) {
        if (len < offset + ip_hdr_len + sizeof(udphdr)) return out;
        const udphdr* udp = reinterpret_cast<const udphdr*>(data + offset + ip_hdr_len);
        src_port = ntohs(udp->source);
        dst_port = ntohs(udp->dest);
    } else {
        // For non-TCP/UDP, still track by protocol with zero ports
        src_port = 0;
        dst_port = 0;
    }

    out.key = FlowKey{
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto
    };

    out.payload_len = ntohs(ip->tot_len);
    out.valid = true;
    return out;
}

// =========================
// Flow analyser
// =========================

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t table_capacity_pow2,
                          uint64_t idle_timeout_ns)
        : table_(table_capacity_pow2),
          idle_timeout_ns_(idle_timeout_ns) {}

    void ingest_packet(const uint8_t* data, size_t len, uint64_t now_ns) noexcept {
        ParsedPacket pkt = parse_packet(data, len);
        if (!pkt.valid) return;

        FlowRecord* rec = table_.find_or_insert(pkt.key, now_ns);
        if (!rec) {
            dropped_flows_.fetch_add(1, std::memory_order_relaxed);
            return;
        }

        rec->packets++;
        rec->bytes += pkt.payload_len;
        rec->last_seen_ns = now_ns;
    }

    void age(uint64_t now_ns) noexcept {
        table_.age_out(now_ns, idle_timeout_ns_);
    }

    void export_flows() {
        table_.for_each([](const FlowRecord& r) {
            std::cout
                << "proto=" << static_cast<int>(r.key.proto)
                << " src_ip=" << ip_to_string(r.key.src_ip)
                << ":" << r.key.src_port
                << " dst_ip=" << ip_to_string(r.key.dst_ip)
                << ":" << r.key.dst_port
                << " packets=" << r.packets
                << " bytes=" << r.bytes
                << " first_ns=" << r.first_seen_ns
                << " last_ns=" << r.last_seen_ns
                << "\n";
        });
    }

    uint64_t dropped_flows() const noexcept {
        return dropped_flows_.load(std::memory_order_relaxed);
    }

private:
    static std::string ip_to_string(uint32_t ip_be) {
        in_addr addr{};
        addr.s_addr = ip_be;
        char buf[INET_ADDRSTRLEN];
        const char* s = inet_ntop(AF_INET, &addr, buf, sizeof(buf));
        return s ? std::string(s) : std::string("0.0.0.0");
    }

    FlowTable table_;
    uint64_t idle_timeout_ns_;
    std::atomic<uint64_t> dropped_flows_{0};
};

// =========================
// Example driver
// =========================

int main() {
