#pragma pack(pop)

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    // Fast 64-bit mix; good enough for flow tables
    uint64_t x = 0;
    x ^= (uint64_t)k.src_ip * 0x9E3779B185EBCA87ULL;
    x ^= (uint64_t)k.dst_ip * 0xC2B2AE3D27D4EB4FULL;
    x ^= (uint64_t)k.src_port << 16;
    x ^= (uint64_t)k.dst_port << 32;
    x ^= (uint64_t)k.proto << 48;

    // final avalanche
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    bool occupied = false;
};

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : mask_(capacity_pow2 - 1), table_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
    }

    FlowStats* find_or_insert(const FlowKey& key, uint64_t ts_ns) noexcept {
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < table_.size(); ++probe) {
            FlowEntry& e = table_[idx];

            if (!e.occupied) {
                e.occupied = true;
                e.key = key;
                e.stats.packets = 0;
                e.stats.bytes = 0;
                e.stats.first_seen_ns = ts_ns;
                e.stats.last_seen_ns = ts_ns;
                return &e.stats;
            }

            if (e.key == key) {
                e.stats.last_seen_ns = ts_ns;
                return &e.stats;
            }

            idx = (idx + 1) & mask_;
        }

        return nullptr; // table full
    }

    template <typename Fn>
    void for_each(Fn&& fn) {
        for (auto& e : table_) {
            if (e.occupied) fn(e.key, e.stats);
        }
    }

    void expire_older_than(uint64_t cutoff_ns) noexcept {
        for (auto& e : table_) {
            if (e.occupied && e.stats.last_seen_ns < cutoff_ns) {
                e.occupied = false;
            }
        }
    }

private:
    size_t mask_;
    std::vector<FlowEntry> table_;
};

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
};

static inline std::optional<ParsedPacket> parse_packet(std::span<const uint8_t> pkt) {
    if (pkt.size() < sizeof(ether_header)) return std::nullopt;

    const auto* eth = reinterpret_cast<const ether_header*>(pkt.data());
    uint16_t eth_type = ntohs(eth->ether_type);
    size_t offset = sizeof(ether_header);

    if (eth_type != ETHERTYPE_IP) {
        return std::nullopt; // IPv4 only in this minimal version
    }

    if (pkt.size() < offset + sizeof(iphdr)) return std::nullopt;
    const auto* ip = reinterpret_cast<const ip*>(pkt.data() + offset);

    if (ip->ip_v != 4) return std::nullopt;
    size_t ip_hdr_len = static_cast<size_t>(ip->ip_hl) * 4;
    if (ip_hdr_len < sizeof(iphdr)) return std::nullopt;
    if (pkt.size() < offset + ip_hdr_len) return std::nullopt;

    uint8_t proto = ip->ip_p;
    uint32_t src_ip = ip->ip_src.s_addr;
    uint32_t dst_ip = ip->ip_dst.s_addr;

    uint16_t src_port = 0;
    uint16_t dst_port = 0;

    offset += ip_hdr_len;

    if (proto == IPPROTO_TCP) {
        if (pkt.size() < offset + sizeof(tcphdr)) return std::nullopt;
        const auto* tcp = reinterpret_cast<const tcphdr*>(pkt.data() + offset);
        src_port = ntohs(tcp->source);
        dst_port = ntohs(tcp->dest);
    } else if (proto == IPPROTO_UDP) {
        if (pkt.size() < offset + sizeof(udphdr)) return std::nullopt;
        const auto* udp = reinterpret_cast<const udphdr*>(pkt.data() + offset);
        src_port = ntohs(udp->source);
        dst_port = ntohs(udp->dest);
    } else {
        return std::nullopt;
    }

    uint32_t total_len = ntohs(ip->ip_len);
    if (total_len < ip_hdr_len) return std::nullopt;

    ParsedPacket out;
    out.key = FlowKey{
        .src_ip = src_ip,
        .dst_ip = dst_ip,
        .src_port = src_port,
        .dst_port = dst_port,
        .proto = proto
    };
    out.payload_len = total_len - static_cast<uint32_t>(ip_hdr_len);
    return out;
}

class FlowAnalyzer {
public:
