```cpp
#include <atomic>
#include <array>
#include <cstdint>
#include <cstring>
#include <vector>
#include <thread>
#include <chrono>
#include <optional>
#include <algorithm>
#include <iostream>

#if defined(__GNUC__) || defined(__clang__)
#define LIKELY(x)   __builtin_expect(!!(x), 1)
#define UNLIKELY(x) __builtin_expect(!!(x), 0)
#else
#define LIKELY(x)   (x)
#define UNLIKELY(x) (x)
#endif

// -----------------------------
// Packet parsing
// -----------------------------

#pragma pack(push, 1)
struct EthHdr {
    uint8_t  dst[6];
    uint8_t  src[6];
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t  ver_ihl;
    uint8_t  tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t  ttl;
    uint8_t  protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t  data_offset_reserved;
    uint8_t  flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static inline uint16_t bswap16(uint16_t x) { return (x >> 8) | (x << 8); }
static inline uint32_t bswap32(uint32_t x) {
    return ((x & 0x000000FFu) << 24) |
           ((x & 0x0000FF00u) << 8)  |
           ((x & 0x00FF0000u) >> 8)  |
           ((x & 0xFF000000u) >> 24);
}

#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
static inline uint16_t ntoh16(uint16_t x) { return bswap16(x); }
static inline uint32_t ntoh32(uint32_t x) { return bswap32(x); }
#else
static inline uint16_t ntoh16(uint16_t x) { return x; }
static inline uint32_t ntoh32(uint32_t x) { return x; }
#endif

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    // Canonicalize direction so both directions map to same flow.
    static FlowKey canonical(uint32_t a_ip, uint16_t a_port,
                             uint32_t b_ip, uint16_t b_port,
                             uint8_t proto) {
        FlowKey k{};
        if (a_ip < b_ip || (a_ip == b_ip && a_port <= b_port)) {
            k.src_ip = a_ip; k.src_port = a_port;
            k.dst_ip = b_ip; k.dst_port = b_port;
        } else {
            k.src_ip = b_ip; k.src_port = b_port;
            k.dst_ip = a_ip; k.dst_port = a_port;
        }
        k.proto = proto;
        return k;
    }
};

static inline uint64_t mix64(uint64_t x) {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline uint64_t hash_flow_key(const FlowKey& k) {
    uint64_t x = 0;
    x ^= uint64_t(k.src_ip) * 0x9e3779b185ebca87ULL;
    x ^= uint64_t(k.dst_ip) * 0xc2b2ae3d27d4eb4fULL;
    x ^= uint64_t(k.src_port) << 16;
    x ^= uint64_t(k.dst_port);
    x ^= uint64_t(k.proto) << 56;
    return mix64(x);
}

// -----------------------------
// Flow record
// -----------------------------

struct alignas(64) FlowRecord {
    FlowKey key{};
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns  = 0;
    uint64_t packets       = 0;
    uint64_t bytes         = 0;
    uint32_t tcp_flags     = 0;
    uint8_t  used          = 0;
    uint8_t  pad[7]{};

    void reset() {
        key = {};
        first_seen_ns = last_seen_ns = packets = bytes = 0;
        tcp_flags = 0;
        used = 0;
    }
};

// -----------------------------
// Sharded flow table
// -----------------------------

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(next_pow2(capacity_pow2)),
          mask_(capacity_ - 1),
          slots_(capacity_) {}

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t now_ns) {
        const uint64_t h = hash_flow_key(key);
        size_t idx = size_t(h) & mask_;

        for (size_t probe = 0; probe < capacity_; ++probe) {
            FlowRecord& slot = slots_[idx];
            if (!slot.used) {
                slot.key = key;
                slot.first_seen_ns = now_ns;
                slot.last_seen_ns = now_ns;
                slot.packets = 1;
                slot.bytes = 0;
                slot.tcp_flags = 0;
                slot.used = 1;
                return &slot;
            }
            if (keys_equal(slot.key, key)) {
                slot.last_seen_ns = now_ns;
                return &slot;
            }
            idx = (idx + 1) & mask_;
        }
        return nullptr; // table full
    }

    template <typename Fn>
    void age_out(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_evict) {
        for (auto& slot : slots_) {
            if (slot.used && (now_ns - slot.last_seen_ns > idle_timeout_ns)) {
                on_evict(slot);
                slot.reset();
            }
        }
    }

private:
    static bool keys_equal(const FlowKey& a, const FlowKey& b) {
        return a.src_ip == b.src_ip &&
               a.dst_ip == b.dst_ip &&
               a.src_port == b.src_port &&
               a.dst_port == b.dst_port &&
               a.proto == b.proto;
    }

    static size_t next_pow2(size_t x) {
        if (x < 2) return 2;
        --x;
        for (size_t i = 1; i < sizeof(size_t) * 8; i <<= 1) x |= x >> i;
        return x + 1;
    }

    size_t capacity_;
    size_t mask_;
    std::vector<FlowRecord> slots_;
};

// -----------------------------
// Analyzer
// -----------------------------

class NetworkFlowAnalyzer {
public:
    explicit NetworkFlowAnalyzer(size_t shards = 16, size_t table_capacity_per_shard = 1 << 20)
        : shard_count_(next_pow2(shards)),
          shard_mask_(shard_count_ - 1) {
        tables_.reserve(shard_count_);
        for (size_t i = 0; i < shard_count_; ++i) {
            tables_.emplace_back(table_capacity_per_shard);
        }
    }

    void process_packet(const uint8_t* data, size_t len, uint64_t now_ns) {
        if (UNLIKELY(len < sizeof(EthHdr))) return;

        const EthHdr* eth = reinterpret_cast<const EthHdr*>(data);
        uint16_t ethertype = ntoh16(eth->ethertype);

        size_t offset = sizeof(EthHdr);

        // VLAN support could be added here.

        if (ethertype != 0x0800) return; // IPv4 only for now
        if (UNLIKELY(len < offset + sizeof(Ipv4Hdr))) return;

        const Ipv4Hdr* ip = reinterpret_cast<const Ipv4Hdr*>(data + offset);
        uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
        if (UNLIKELY(ihl < 20 || len < offset + ihl)) return;

        uint8_t proto = ip->protocol;
        uint32_t src_ip = ntoh32(ip->src);
        uint32_t dst_ip = ntoh32(ip->dst);

        offset += ihl;

        uint16_t src_port = 0, dst_port = 0;
        uint32_t pkt_bytes = uint32_t(len);

        if (proto == 6) { // TCP
            if (UNLIKELY(len < offset + sizeof(TcpHdr))) return;
            const TcpHdr* tcp = reinterpret_cast<const TcpHdr*>(data + offset);
            src_port = ntoh16(tcp->src_port);
            dst_port = ntoh16(tcp->dst_port);
        } else if (proto == 17) { // UDP
            if (UNLIKELY(len < offset + sizeof(UdpHdr))) return;
            const UdpHdr* udp = reinterpret_cast<const UdpHdr*>(data + offset);
            src_port = ntoh16(udp->src_port);
            dst_port = ntoh16(udp->dst_port);
        } else {
            return; // ignore non-TCP/UDP
        }

        FlowKey key = FlowKey::canonical(src_ip, src_port, dst_ip, dst_port, proto);
        FlowTable& table = shard_for(key);

        FlowRecord* rec = table.find_or_insert(key, now_ns);
        if (LIKELY(rec)) {
            rec->packets += 1;
            rec->bytes += pkt_bytes;
            rec->last_seen_ns = now_ns;
        }
    }

    template <typename Fn>
    void age_all(uint64_t now_ns, uint64_t idle_timeout_ns, Fn&& on_evict) {
        for (auto& t : tables_) {
            t.age_out(now_ns, idle_timeout_ns, on_evict);
        }
    }

private:
    static size_t next_pow2(size_t x) {
        if (x < 2) return 2;
        --x;
        for (size_t i = 1; i < sizeof(size_t) * 8; i <<= 1) x |= x >> i;
        return x + 1;
    }

    FlowTable& shard_for(const FlowKey& key) {
        uint64_t h = hash_flow_key(key);
        return tables_[size_t(h) & shard_mask_];
    }

    size_t shard_count_;
    size_t shard_mask_;
    std::vector<FlowTable> tables_;
};

// -----------------------------
// Example usage
// -----------------------------

static uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(steady_clock::now().time_since_epoch()).count();
}

int main() {
    NetworkFlowAnalyzer analyzer(16, 1 << 18);

    // Example packet buffer would come from a capture engine.
    std::vector<uint8_t> packet(64, 0);

    // Fake Ethernet + IPv4 + TCP packet setup for demonstration only.
    auto* eth = reinterpret_cast<EthHdr*>(packet.data());
    eth->ethertype = bswap16(0x0800);

    auto* ip = reinterpret_cast<Ipv4Hdr*>(packet.data() + sizeof(EthHdr));
    ip->ver_ihl = 0x45;
    ip->protocol = 6;
    ip->src = bswap32(0x0A000001); // 10.0.0.1
    ip->dst = bswap32(0x0A000002); // 10.0.0.2

    auto* tcp = reinterpret_cast<TcpHdr*>(packet.data() + sizeof(EthHdr) + sizeof(Ipv4Hdr));
    tcp->src_port = bswap16(12345);
    tcp->dst_port = bswap16(443);

    analyzer.process_packet(packet.data(), packet.size(), now_ns());

    analyzer.age_all(now_ns(), 30ULL * 1000 * 1000 * 1000, [](const FlowRecord& rec) {
        std::cout << "Evicted flow: packets=" << rec.packets
                  << " bytes=" << rec.bytes << "\n";
    });

    return 0;
}
