## C++20 code

```cpp
#include <array>
#include <atomic>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <optional>
#include <vector>
#include <chrono>
#include <thread>
#include <algorithm>

// ============================
// Packet / Flow definitions
// ============================

#pragma pack(push, 1)
struct PacketView {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
    uint8_t  _pad;
    uint16_t length;
    uint64_t timestamp_ns;
};
#pragma pack(pop)

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    bool occupied = false;
    bool tombstone = false;
};

// ============================
// Fast hash
// ============================

static inline uint64_t mix64(uint64_t x) noexcept {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    uint64_t a = (uint64_t(k.src_ip) << 32) | k.dst_ip;
    uint64_t b = (uint64_t(k.src_port) << 48) |
                 (uint64_t(k.dst_port) << 32) |
                 (uint64_t(k.protocol) << 24);
    return mix64(a ^ mix64(b));
}

// ============================
// Flow table
// ============================

class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          table_(capacity_) {}

    // Insert or update a flow
    FlowStats& update(const PacketView& pkt) noexcept {
        FlowKey key{
            pkt.src_ip,
            pkt.dst_ip,
            pkt.src_port,
            pkt.dst_port,
            pkt.protocol
        };

        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;
        size_t first_tombstone = capacity_;

        for (;;) {
            FlowEntry& e = table_[idx];

            if (!e.occupied) {
                // Prefer first tombstone if found
                size_t target = (first_tombstone != capacity_) ? first_tombstone : idx;
                FlowEntry& t = table_[target];
                t.key = key;
                t.stats = {};
                t.stats.first_seen_ns = pkt.timestamp_ns;
                t.stats.last_seen_ns = pkt.timestamp_ns;
                t.stats.packets = 1;
                t.stats.bytes = pkt.length;
                t.occupied = true;
                t.tombstone = false;
                ++size_;
                return t.stats;
            }

            if (e.occupied && e.key == key) {
                e.stats.packets++;
                e.stats.bytes += pkt.length;
                e.stats.last_seen_ns = pkt.timestamp_ns;
                return e.stats;
            }

            if (e.tombstone && first_tombstone == capacity_) {
                first_tombstone = idx;
            }

            idx = (idx + 1) & mask_;
        }
    }

    // Remove expired flows
    size_t expire(uint64_t now_ns, uint64_t idle_timeout_ns) noexcept {
        size_t removed = 0;
        for (auto& e : table_) {
            if (e.occupied && (now_ns - e.stats.last_seen_ns >= idle_timeout_ns)) {
                e.occupied = false;
                e.tombstone = true;
                ++removed;
                --size_;
            }
        }
        return removed;
    }

    size_t size() const noexcept { return size_; }
    size_t capacity() const noexcept { return capacity_; }

    template <typename Fn>
    void for_each(Fn&& fn) const {
        for (const auto& e : table_) {
            if (e.occupied) fn(e.key, e.stats);
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowEntry> table_;
    std::atomic<size_t> size_{0};
};

// ============================
// Analyzer
// ============================

class NetworkFlowAnalyzer {
public:
    explicit NetworkFlowAnalyzer(size_t table_pow2, uint64_t idle_timeout_ns)
        : flows_(table_pow2), idle_timeout_ns_(idle_timeout_ns) {}

    void process_packet(const PacketView& pkt) noexcept {
        flows_.update(pkt);
        ++packets_seen_;
        bytes_seen_ += pkt.length;
    }

    void periodic_maintenance(uint64_t now_ns) noexcept {
        flows_.expire(now_ns, idle_timeout_ns_);
    }

    void print_summary() const {
        std::cout << "Packets: " << packets_seen_ << "\n";
        std::cout << "Bytes:   " << bytes_seen_ << "\n";
        std::cout << "Flows:   " << flows_.size() << "\n";
    }

    void dump_flows() const {
        flows_.for_each([](const FlowKey& k, const FlowStats& s) {
            std::cout << "Flow "
                      << k.src_ip << ":" << k.src_port
                      << " -> " << k.dst_ip << ":" << k.dst_port
                      << " proto=" << unsigned(k.protocol)
                      << " packets=" << s.packets
                      << " bytes=" << s.bytes
                      << " first=" << s.first_seen_ns
                      << " last=" << s.last_seen_ns
                      << "\n";
        });
    }

private:
    FlowTable flows_;
    uint64_t idle_timeout_ns_;
    uint64_t packets_seen_ = 0;
    uint64_t bytes_seen_ = 0;
};

// ============================
// Example usage / test harness
// ============================

static uint64_t now_ns() {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now().time_since_epoch()
    ).count();
}

int main() {
    // 2^20 entries ~ 1,048,576 flows
    NetworkFlowAnalyzer analyzer(/*table_pow2=*/20, /*idle_timeout_ns=*/30ULL * 1000 * 1000 * 1000);

    // Simulated packets
    std::vector<PacketView> packets;
    packets.reserve(1'000'000);

    uint64_t t0 = now_ns();
    for (uint32_t i = 0; i < 1'000'000; ++i) {
        packets.push_back(PacketView{
            .src_ip = 0x0A000001 + (i % 1024),
            .dst_ip = 0x0A000100 + (i % 2048),
            .src_port = static_cast<uint16_t>(1000 + (i % 40000)),
            .dst_port = 443,
            .protocol = 6,
            ._pad = 0,
            .length = static_cast<uint16_t>(64 + (i % 1400)),
            .timestamp_ns = t0 + i * 1000
        });
    }

    // Hot loop
    for (const auto& pkt : packets) {
        analyzer.process_packet(pkt);
    }

    analyzer.periodic_maintenance(now_ns());
    analyzer.print_summary();

    return 0;
}
