## C++17 implementation

```cpp
#include <cstdint>
#include <cstring>
#include <vector>
#include <array>
#include <atomic>
#include <chrono>
#include <iostream>
#include <optional>
#include <algorithm>

// -----------------------------
// Packet metadata
// -----------------------------
struct PacketMeta {
    uint32_t src_ip;     // IPv4 only for this example
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;   // TCP=6, UDP=17, etc.
    uint32_t length;     // packet length in bytes
    uint64_t timestamp_ns;
};

// -----------------------------
// Flow key
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Fast hash for FlowKey
static inline uint64_t hash_flow_key(const FlowKey& k) noexcept {
    // 64-bit mix, adapted for speed
    uint64_t x = 0;
    x ^= (uint64_t)k.src_ip * 0x9E3779B185EBCA87ULL;
    x ^= (uint64_t)k.dst_ip * 0xC2B2AE3D27D4EB4FULL;
    x ^= (uint64_t)k.src_port << 16;
    x ^= (uint64_t)k.dst_port << 32;
    x ^= (uint64_t)k.protocol << 48;

    // final avalanche
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

// -----------------------------
// Flow record
// -----------------------------
struct FlowRecord {
    FlowKey key{};
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    bool occupied = false;
};

// -----------------------------
// Open-addressing flow table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(1ULL << capacity_pow2),
          mask_(capacity_ - 1),
          table_(capacity_) {}

    FlowRecord* find_or_insert(const FlowKey& key, uint64_t now_ns) noexcept {
        uint64_t h = hash_flow_key(key);
        size_t idx = static_cast<size_t>(h) & mask_;

        for (size_t probe = 0; probe < capacity_; ++probe) {
            FlowRecord& slot = table_[idx];

            if (!slot.occupied) {
                slot.occupied = true;
                slot.key = key;
                slot.packets = 0;
                slot.bytes = 0;
                slot.first_seen_ns = now_ns;
                slot.last_seen_ns = now_ns;
                return &slot;
            }

            if (slot.key == key) {
                return &slot;
            }

            idx = (idx + 1) & mask_;
        }

        return nullptr; // table full
    }

    template <typename Fn>
    void evict_older_than(uint64_t cutoff_ns, Fn&& on_evict) {
        for (auto& slot : table_) {
            if (slot.occupied && slot.last_seen_ns < cutoff_ns) {
                on_evict(slot);
                slot = FlowRecord{};
            }
        }
    }

    size_t size() const noexcept {
        size_t n = 0;
        for (const auto& slot : table_) {
            if (slot.occupied) ++n;
        }
        return n;
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowRecord> table_;
};

// -----------------------------
// Analyzer
// -----------------------------
class NetworkFlowAnalyzer {
public:
    explicit NetworkFlowAnalyzer(size_t table_pow2, uint64_t flow_timeout_ns)
        : flows_(table_pow2), flow_timeout_ns_(flow_timeout_ns) {}

    void process_packet(const PacketMeta& pkt) noexcept {
        FlowKey key{
            pkt.src_ip,
            pkt.dst_ip,
            pkt.src_port,
            pkt.dst_port,
            pkt.protocol
        };

        FlowRecord* rec = flows_.find_or_insert(key, pkt.timestamp_ns);
        if (!rec) {
            // Table full: in production, count drops or trigger resize/eviction
            dropped_++;
            return;
        }

        rec->packets++;
        rec->bytes += pkt.length;
        rec->last_seen_ns = pkt.timestamp_ns;
    }

    void age_flows(uint64_t now_ns) {
        uint64_t cutoff = now_ns > flow_timeout_ns_ ? now_ns - flow_timeout_ns_ : 0;
        flows_.evict_older_than(cutoff, [&](const FlowRecord& rec) {
            // In production, export to telemetry / write to ring buffer / batch send
            expired_++;
            // Example output:
            // std::cout << "Expired flow: packets=" << rec.packets
            //           << " bytes=" << rec.bytes << "\n";
        });
    }

    uint64_t dropped() const noexcept { return dropped_; }
    uint64_t expired() const noexcept { return expired_; }

private:
    FlowTable flows_;
    uint64_t flow_timeout_ns_;
    uint64_t dropped_ = 0;
    uint64_t expired_ = 0;
};

// -----------------------------
// Example usage
// -----------------------------
int main() {
    // 2^20 slots ~ 1,048,576 flows
    NetworkFlowAnalyzer analyzer(/*table_pow2=*/20, /*flow_timeout_ns=*/30ULL * 1000 * 1000 * 1000);

    // Simulated packets
    for (uint64_t i = 0; i < 1000000; ++i) {
        PacketMeta pkt;
        pkt.src_ip = 0x0A000001; // 10.0.0.1
        pkt.dst_ip = 0x0A000002; // 10.0.0.2
        pkt.src_port = 12345;
        pkt.dst_port = 80;
        pkt.protocol = 6; // TCP
        pkt.length = 1500;
        pkt.timestamp_ns = i * 1000;

        analyzer.process_packet(pkt);

        if ((i % 100000) == 0) {
            analyzer.age_flows(pkt.timestamp_ns);
        }
    }

    std::cout << "Dropped packets: " << analyzer.dropped() << "\n";
    std::cout << "Expired flows: " << analyzer.expired() << "\n";
    return 0;
}
