#include <thread>
#include <vector>
#include <chrono>
#include <algorithm>

// =========================
// Packet / Flow definitions
// =========================

enum class L4Proto : uint8_t {
    TCP = 6,
    UDP = 17,
    ICMP = 1,
    OTHER = 255
};

struct PacketView {
    const uint8_t* data;
    size_t len;
    uint64_t ts_ns; // capture timestamp in nanoseconds
};

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast 64-bit mix
        uint64_t x = 0;
        x ^= uint64_t(k.src_ip) * 0x9E3779B185EBCA87ULL;
        x ^= uint64_t(k.dst_ip) * 0xC2B2AE3D27D4EB4FULL;
        x ^= uint64_t(k.src_port) << 16;
        x ^= uint64_t(k.dst_port) << 32;
        x ^= uint64_t(k.proto) << 48;

        // final avalanche
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return static_cast<size_t>(x);
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
    uint32_t tcp_flags = 0;
};

struct FlowEntry {
    FlowKey key{};
    FlowStats stats{};
    bool occupied = false;
};

// =========================
// Fast packet parsing
// =========================
// Assumes Ethernet + IPv4 + TCP/UDP/ICMP.
// For production, extend for VLAN, IPv6, tunnels, etc.

#pragma pack(push, 1)
struct EthHdr {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct Ipv4Hdr {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TcpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent;
};

struct UdpHdr {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t len;
    uint16_t checksum;
};
#pragma pack(pop)

static inline uint16_t bswap16(uint16_t x) noexcept {
    return __builtin_bswap16(x);
}
static inline uint32_t bswap32(uint32_t x) noexcept {
    return __builtin_bswap32(x);
}

static inline uint16_t ntoh16(uint16_t x) noexcept {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap16(x);
#else
    return x;
#endif
}

static inline uint32_t ntoh32(uint32_t x) noexcept {
#if __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__
    return bswap32(x);
#else
    return x;
#endif
}

struct ParsedPacket {
    FlowKey key{};
    uint32_t payload_len = 0;
    uint32_t tcp_flags = 0;
    bool valid = false;
};

static inline ParsedPacket parse_packet(const PacketView& pkt) noexcept {
    ParsedPacket out{};
    if (pkt.len < sizeof(EthHdr) + sizeof(Ipv4Hdr)) return out;

    const auto* eth = reinterpret_cast<const EthHdr*>(pkt.data);
    uint16_t ethertype = ntoh16(eth->ethertype);
    if (ethertype != 0x0800) return out; // IPv4 only

    const auto* ip = reinterpret_cast<const Ipv4Hdr*>(pkt.data + sizeof(EthHdr));
    uint8_t ihl = (ip->ver_ihl & 0x0F) * 4;
    if (ihl < 20) return out;
    if (pkt.len < sizeof(EthHdr) + ihl) return out;

    uint8_t proto = ip->protocol;
    uint32_t src_ip = ntoh32(ip->src);
    uint32_t dst_ip = ntoh32(ip->dst);

    const uint8_t* l4 = pkt.data + sizeof(EthHdr) + ihl;
    size_t l4_len = pkt.len - (sizeof(EthHdr) + ihl);

    FlowKey key{};
    key.src_ip = src_ip;
    key.dst_ip = dst_ip;
    key.proto = proto;

    if (proto == static_cast<uint8_t>(L4Proto::TCP)) {
        if (l4_len < sizeof(TcpHdr)) return out;
        const auto* tcp = reinterpret_cast<const TcpHdr*>(l4);
        key.src_port = ntoh16(tcp->src_port);
        key.dst_port = ntoh16(tcp->dst_port);
        out.tcp_flags = tcp->flags;
        uint8_t doff = ((tcp->data_offset_reserved >> 4) & 0x0F) * 4;
        if (doff < 20 || l4_len < doff) return out;
        out.payload_len = static_cast<uint32_t>(l4_len - doff);
    } else if (proto == static_cast<uint8_t>(L4Proto::UDP)) {
        if (l4_len < sizeof(UdpHdr)) return out;
        const auto* udp = reinterpret_cast<const UdpHdr*>(l4);
        key.src_port = ntoh16(udp->src_port);
        key.dst_port = ntoh16(udp->dst_port);
        out.payload_len = static_cast<uint32_t>(l4_len - sizeof(UdpHdr));
    } else {
        key.src_port = 0;
        key.dst_port = 0;
        out.payload_len = static_cast<uint32_t>(l4_len);
    }

    out.key = key;
    out.valid = true;
    return out;
}

// =========================
// Sharded flow table
// =========================

template <size_t CapacityPow2>
class FlowShard {
    static_assert((CapacityPow2 & (CapacityPow2 - 1)) == 0, "Capacity must be power of two");

public:
    FlowShard() : entries_(CapacityPow2) {}

    FlowEntry* find_or_insert(const FlowKey& key, uint64_t ts_ns) noexcept {
        const size_t mask = CapacityPow2 - 1;
        size_t idx = hasher_(key) & mask;

        for (size_t probe = 0; probe < CapacityPow2; ++probe) {
            FlowEntry& e = entries_[idx];
            if (!e.occupied) {
                e.key = key;
                e.stats.first_seen_ns = ts_ns;
                e.stats.last_seen_ns = ts_ns;
                e.occupied = true;
                return &e;
            }
            if (e.key == key) {
                return &e;
            }
            idx = (idx + 1) & mask;
        }
        return nullptr; // table full
    }

    template <typename ExpireFn>
    void expire(uint64_t now_ns, uint64_t idle_timeout_ns, ExpireFn&& fn) {
        for (auto& e : entries_) {
            if (!e.occupied) continue;
            if (now_ns - e.stats.last_seen_ns >= idle_timeout_ns) {
                fn(e);
                e.occupied = false;
            }
        }
    }

private:
    std::vector<FlowEntry> entries_;
    FlowKeyHash hasher_{};
};

template <size_t Shards, size_t CapacityPerShardPow2>
class FlowTable {
    static_assert((Shards & (Shards - 1)) == 0, "Shards must be power of two");

public:
    using Shard = FlowShard<CapacityPerShardPow2>;

    FlowEntry* update(const FlowKey& key, uint64_t ts_ns, uint32_t bytes, uint32_t tcp_flags) noexcept {
        size_t shard_idx = hasher_(key) & (Shards - 1);
        auto& shard = shards_[shard_idx];

        std::lock_guard<std::mutex> lock(mutexes_[shard_idx]);
        FlowEntry* e = shard.find_or_insert(key, ts_ns);
        if (!e) return nullptr;

        e->stats.packets += 1;
        e->stats.bytes += bytes;
        e->stats.last_seen_ns = ts_ns;
        e->stats.tcp_flags |= tcp_flags;
        return e;
    }

    template <typename ExpireFn>
    void expire_all(uint64_t now_ns, uint64_t idle_timeout_ns, ExpireFn&& fn) {
        for (size_t i = 0; i < Shards; ++i) {
            std::lock_guard<std::mutex> lock(mutexes_[i]);
            shards_[i].expire(now_ns, idle_timeout_ns, fn);
        }
    }

private:
    std::array<Shard, Shards> shards_{};
    std::array<std::mutex, Shards> mutexes_{};
    FlowKeyHash hasher_{};
};

// =========================
// Analyzer
// =========================

class NetworkFlowAnalyzer {
public:
    static constexpr size_t kShards = 64;
    static constexpr size_t kCapacityPerShard = 1 << 16; // 65536 entries/shard

    using Table = FlowTable<kShards, kCapacityPerShard>;

    explicit NetworkFlowAnalyzer(uint64_t idle_timeout_ns)
        : idle_timeout_ns_(idle_timeout_ns) {}

    void ingest(const PacketView& pkt) noexcept {
        ParsedPacket parsed = parse_packet(pkt);
        if (!parsed.valid) return;

        // Approximate bytes: full packet length
        table_.update(parsed.key, pkt.ts_ns, static_cast<uint32_t>(pkt.len), parsed.tcp_flags);
    }

    template <typename ExpireFn>
    void expire(uint64_t now_ns, ExpireFn&& fn) {
        table_.expire_all(now_ns, idle_timeout_ns_, std::forward<ExpireFn>(fn));
    }

private:
    Table table_;
    uint64_t idle_timeout_ns_;
};

