use ahash::AHasher;
use hashbrown::HashMap;
use parking_lot::RwLock;
use std::hash::{Hash, Hasher};
use std::net::IpAddr;
use std::sync::Arc;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Clone, Debug)]
pub struct FlowRecord {
    pub key: FlowKey,
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

impl FlowRecord {
    pub fn new(key: FlowKey, now: Instant, bytes: u64) -> Self {
        Self {
            key,
            packets: 1,
            bytes,
            first_seen: now,
            last_seen: now,
        }
    }

    pub fn update(&mut self, now: Instant, bytes: u64) {
        self.packets += 1;
        self.bytes += bytes;
        self.last_seen = now;
    }

    pub fn duration(&self) -> Duration {
        self.last_seen.duration_since(self.first_seen)
    }
}

pub struct Packet {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
    pub bytes: u64,
    pub timestamp: Instant,
}

impl Packet {
    pub fn flow_key(&self) -> FlowKey {
        FlowKey {
            src_ip: self.src_ip,
            dst_ip: self.dst_ip,
            src_port: self.src_port,
            dst_port: self.dst_port,
            protocol: self.protocol,
        }
    }
}

struct Shard {
    flows: RwLock<HashMap<FlowKey, FlowRecord, ahash::RandomState>>,
}

impl Shard {
    fn new() -> Self {
        Self {
            flows: RwLock::new(HashMap::with_hasher(ahash::RandomState::new())),
        }
    }
}

pub struct FlowAnalyser {
    shards: Vec<Arc<Shard>>,
    idle_timeout: Duration,
}

impl FlowAnalyser {
    pub fn new(num_shards: usize, idle_timeout: Duration) -> Self {
        assert!(num_shards.is_power_of_two(), "num_shards must be power of two");

        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(Arc::new(Shard::new()));
        }

        Self {
            shards,
            idle_timeout,
        }
    }

    #[inline]
    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & (self.shards.len() - 1)
    }

    pub fn ingest(&self, packet: Packet) {
        let key = packet.flow_key();
        let idx = self.shard_index(&key);
        let shard = &self.shards[idx];

        let mut map = shard.flows.write();
        match map.get_mut(&key) {
            Some(flow) => flow.update(packet.timestamp, packet.bytes),
            None => {
                map.insert(key, FlowRecord::new(key, packet.timestamp, packet.bytes));
            }
        }
    }

    pub fn expire_idle_flows(&self, now: Instant) -> Vec<FlowRecord> {
        let mut expired = Vec::new();

        for shard in &self.shards {
            let mut map = shard.flows.write();
            let timeout = self.idle_timeout;

            map.retain(|_, flow| {
                let idle = now.duration_since(flow.last_seen);
                if idle >= timeout {
                    expired.push(flow.clone());
                    false
                } else {
                    true
                }
            });
        }

        expired
    }

    pub fn flow_count(&self) -> usize {
        self.shards
            .iter()
            .map(|s| s.flows.read().len())
            .sum()
    }
}
