# Rust implementation

```rust
use std::collections::HashMap;
use std::hash::{BuildHasherDefault, Hasher};
use std::net::Ipv4Addr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

const SHARDS: usize = 64;
const FLOW_IDLE_TIMEOUT: Duration = Duration::from_secs(30);

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
#[repr(C)]
struct FlowKey {
    src_ip: u32,
    dst_ip: u32,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    _pad: u8,
}

#[derive(Clone, Copy, Debug, Default)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: u64,
    last_seen: u64,
    tcp_flags: u8,
}

#[derive(Default)]
struct FlowShard {
    map: HashMap<FlowKey, FlowStats, BuildHasherDefault<fxhash::FxHasher>>,
}

#[derive(Default)]
struct AnalyzerStats {
    packets_total: u64,
    packets_parsed: u64,
    packets_dropped: u64,
    flows_created: u64,
    flows_expired: u64,
}

struct FlowAnalyzer {
    shards: Vec<Mutex<FlowShard>>,
    stats: Mutex<AnalyzerStats>,
    idle_timeout: Duration,
}

impl FlowAnalyzer {
    fn new(idle_timeout: Duration) -> Self {
        let mut shards = Vec::with_capacity(SHARDS);
        for _ in 0..SHARDS {
            shards.push(Mutex::new(FlowShard::default()));
        }
        Self {
            shards,
            stats: Mutex::new(AnalyzerStats::default()),
            idle_timeout,
        }
    }

    fn shard_index(key: &FlowKey) -> usize {
        // Simple hash for shard selection; can be replaced with a faster custom hash.
        let mut h = fxhash::FxHasher::default();
        h.write_u32(key.src_ip);
        h.write_u32(key.dst_ip);
        h.write_u16(key.src_port);
        h.write_u16(key.dst_port);
        h.write_u8(key.proto);
        (h.finish() as usize) & (SHARDS - 1)
    }

    fn process_packet(&self, packet: &[u8], now: Instant) {
        {
            let mut s = self.stats.lock().unwrap();
            s.packets_total += 1;
        }

        if let Some((key, len, tcp_flags)) = parse_packet(packet) {
            let shard_idx = Self::shard_index(&key);
            let mut shard = self.shards[shard_idx].lock().unwrap();

            let entry = shard.map.entry(key).or_insert_with(|| {
                let mut s = self.stats.lock().unwrap();
                s.flows_created += 1;
                FlowStats {
                    first_seen: now.elapsed().as_nanos() as u64,
                    last_seen: now.elapsed().as_nanos() as u64,
                    ..Default::default()
                }
            });

            entry.packets += 1;
            entry.bytes += len as u64;
            entry.last_seen = now.elapsed().as_nanos() as u64;
            entry.tcp_flags |= tcp_flags;

            let mut s = self.stats.lock().unwrap();
            s.packets_parsed += 1;
        } else {
            let mut s = self.stats.lock().unwrap();
            s.packets_dropped += 1;
        }
    }

    fn expire_flows(&self, now: Instant) {
        let cutoff = now.elapsed().as_nanos() as u64
            - self.idle_timeout.as_nanos() as u64;

        for shard_mutex in &self.shards {
            let mut shard = shard_mutex.lock().unwrap();
            let before = shard.map.len();
            shard.map.retain(|_, v| v.last_seen >= cutoff);
            let expired = before - shard.map.len();
            if expired > 0 {
                let mut s = self.stats.lock().unwrap();
                s.flows_expired += expired as u64;
            }
        }
    }

    fn snapshot_stats(&self) -> AnalyzerStats {
        self.stats.lock().unwrap().clone()
    }
}

// -------------------- Packet parsing --------------------

fn parse_packet(packet: &[u8]) -> Option<(FlowKey, usize, u8)> {
    // Ethernet header: 14 bytes
    if packet.len() < 14 {
        return None;
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return None; // IPv4 only for now
    }

    let ip = &packet[14..];
    if ip.len() < 20 {
        return None;
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || ihl < 20 || ip.len() < ihl {
        return None;
    }

    let total_len = u16::from_be_bytes([ip[2], ip[3]]) as usize;
    if total_len < ihl || ip.len() < total_len {
        return None;
    }

    let proto = ip[9];
    let src_ip = u32::from_be_bytes([ip[12], ip[13], ip[14], ip[15]]);
    let dst_ip = u32::from_be_bytes([ip[16], ip[17], ip[18], ip[19]]);

    let l4 = &ip[ihl..total_len];
    match proto {
        6 => {
            // TCP
            if l4.len() < 20 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            let data_offset = ((l4[12] >> 4) as usize) * 4;
            if data_offset < 20 || l4.len() < data_offset {
                return None;
            }
            let flags = l4[13] & 0x3f;
            Some((
                FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                    _pad: 0,
                },
                total_len + 14,
                flags,
            ))
        }
        17 => {
            // UDP
            if l4.len() < 8 {
                return None;
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            Some((
                FlowKey {
                    src_ip,
                    dst_ip,
                    src_port,
                    dst_port,
                    proto,
                    _pad: 0,
                },
                total_len + 14,
                0,
            ))
        }
        _ => None,
    }
}

// -------------------- Mock packet source --------------------

fn mock_packets() -> Vec<Vec<u8>> {
    // Minimal synthetic Ethernet + IPv4 + TCP packet
    let mut pkt = vec![0u8; 14 + 20 + 20];
    pkt[12] = 0x08;
    pkt[13] = 0x00; // IPv4

    // IPv4 header
    let ip = &mut pkt[14..];
    ip[0] = 0x45; // version=4, ihl=5
    ip[2] = 0x00;
    ip[3] = 40; // total length
    ip[8] = 64;
    ip[9] = 6; // TCP
    ip[12..16].copy_from_slice(&Ipv4Addr::new(10, 0, 0, 1).octets());
    ip[16..20].copy_from_slice(&Ipv4Addr::new(10, 0, 0, 2).octets());

    // TCP header
    let tcp = &mut ip[20..];
    tcp[0..2].copy_from_slice(&12345u16.to_be_bytes());
    tcp[2..4].copy_from_slice(&80u16.to_be_bytes());
    tcp[12] = 0x50; // data offset=5
    tcp[13] = 0x18; // PSH+ACK

    vec![pkt]
}

fn main() {
    let analyzer = Arc::new(FlowAnalyzer::new(FLOW_IDLE_TIMEOUT));
    let start = Instant::now();

    for pkt in mock_packets() {
        analyzer.process_packet(&pkt, start);
    }

    analyzer.expire_flows(start + Duration::from_secs(31));

    let stats = analyzer.snapshot_stats();
    println!("Analyzer stats: {:?}", stats);
}
