# Rust implementation

```rust
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
struct FlowRecord {
    first_seen: Instant,
    last_seen: Instant,
    packets: u64,
    bytes: u64,
    tcp_syn: bool,
    tcp_fin: bool,
    tcp_rst: bool,
}

impl FlowRecord {
    fn new(now: Instant, bytes: usize, tcp_flags: Option<u8>) -> Self {
        let mut rec = Self {
            first_seen: now,
            last_seen: now,
            packets: 1,
            bytes: bytes as u64,
            tcp_syn: false,
            tcp_fin: false,
            tcp_rst: false,
        };
        if let Some(flags) = tcp_flags {
            rec.tcp_syn = flags & 0x02 != 0;
            rec.tcp_fin = flags & 0x01 != 0;
            rec.tcp_rst = flags & 0x04 != 0;
        }
        rec
    }

    fn update(&mut self, now: Instant, bytes: usize, tcp_flags: Option<u8>) {
        self.last_seen = now;
        self.packets += 1;
        self.bytes += bytes as u64;
        if let Some(flags) = tcp_flags {
            self.tcp_syn |= flags & 0x02 != 0;
            self.tcp_fin |= flags & 0x01 != 0;
            self.tcp_rst |= flags & 0x04 != 0;
        }
    }
}

#[derive(Debug)]
struct ParsedPacket<'a> {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
    tcp_flags: Option<u8>,
    payload: &'a [u8],
}

#[derive(Debug)]
enum ParseError {
    TooShort,
    NotIPv4,
    NotTCPUDP,
    Malformed,
}

fn parse_ethernet_ipv4(packet: &[u8]) -> Result<ParsedPacket<'_>, ParseError> {
    // Ethernet header: 14 bytes
    if packet.len() < 14 {
        return Err(ParseError::TooShort);
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return Err(ParseError::NotIPv4);
    }

    let ip = &packet[14..];
    if ip.len() < 20 {
        return Err(ParseError::TooShort);
    }

    let version_ihl = ip[0];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;
    if version != 4 || ihl < 20 || ip.len() < ihl {
        return Err(ParseError::Malformed);
    }

    let proto = ip[9];
    let src_ip = Ipv4Addr::new(ip[12], ip[13], ip[14], ip[15]);
    let dst_ip = Ipv4Addr::new(ip[16], ip[17], ip[18], ip[19]);

    let l4 = &ip[ihl..];
    match proto {
        6 => {
            if l4.len() < 20 {
                return Err(ParseError::TooShort);
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            let data_offset = ((l4[12] >> 4) as usize) * 4;
            if data_offset < 20 || l4.len() < data_offset {
                return Err(ParseError::Malformed);
            }
            let flags = l4[13];
            Ok(ParsedPacket {
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                proto,
                tcp_flags: Some(flags),
                payload: &l4[data_offset..],
            })
        }
        17 => {
            if l4.len() < 8 {
                return Err(ParseError::TooShort);
            }
            let src_port = u16::from_be_bytes([l4[0], l4[1]]);
            let dst_port = u16::from_be_bytes([l4[2], l4[3]]);
            Ok(ParsedPacket {
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                proto,
                tcp_flags: None,
                payload: &l4[8..],
            })
        }
        _ => Err(ParseError::NotTCPUDP),
    }
}

#[derive(Clone)]
struct ShardedFlowTable {
    shards: Arc<Vec<Mutex<HashMap<FlowKey, FlowRecord>>>>,
}

impl ShardedFlowTable {
    fn new(num_shards: usize) -> Self {
        let mut shards = Vec::with_capacity(num_shards);
        for _ in 0..num_shards {
            shards.push(Mutex::new(HashMap::with_capacity(1024)));
        }
        Self {
            shards: Arc::new(shards),
        }
    }

    fn shard_index(&self, key: &FlowKey) -> usize {
        use std::collections::hash_map::DefaultHasher;
        let mut hasher = DefaultHasher::new();
        key.hash(&mut hasher);
        (hasher.finish() as usize) % self.shards.len()
    }

    fn update(&self, key: FlowKey, now: Instant, bytes: usize, tcp_flags: Option<u8>) {
        let idx = self.shard_index(&key);
        let mut shard = self.shards[idx].lock().unwrap();
        if let Some(rec) = shard.get_mut(&key) {
            rec.update(now, bytes, tcp_flags);
        } else {
            shard.insert(key, FlowRecord::new(now, bytes, tcp_flags));
        }
    }

    fn snapshot(&self) -> Vec<(FlowKey, FlowRecord)> {
        let mut out = Vec::new();
        for shard in self.shards.iter() {
            let guard = shard.lock().unwrap();
            out.extend(guard.iter().map(|(k, v)| (*k, v.clone())));
        }
        out
    }
}

trait PacketSource {
    fn next_packet(&mut self) -> Option<Vec<u8>>;
}

struct DummySource {
    packets: Vec<Vec<u8>>,
    idx: usize,
}

impl DummySource {
    fn new(packets: Vec<Vec<u8>>) -> Self {
        Self { packets, idx: 0 }
    }
}

impl PacketSource for DummySource {
    fn next_packet(&mut self) -> Option<Vec<u8>> {
        if self.idx >= self.packets.len() {
            None
        } else {
            let pkt = self.packets[self.idx].clone();
            self.idx += 1;
            Some(pkt)
        }
    }
}

struct FlowAnalyzer<S: PacketSource> {
    source: S,
    table: ShardedFlowTable,
}

impl<S: PacketSource> FlowAnalyzer<S> {
    fn new(source: S, table: ShardedFlowTable) -> Self {
        Self { source, table }
    }

    fn run_once(&mut self) {
        while let Some(packet) = self.source.next_packet() {
            let now = Instant::now();
            if let Ok(parsed) = parse_ethernet_ipv4(&packet) {
                let key = normalize_flow_key(
                    parsed.src_ip,
                    parsed.dst_ip,
                    parsed.src_port,
                    parsed.dst_port,
                    parsed.proto,
                );
                self.table.update(key, now, packet.len(), parsed.tcp_flags);
            }
        }
    }
}

fn normalize_flow_key(
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
) -> FlowKey {
    // Canonicalize bidirectional flow key
    let a = (u32::from(src_ip), src_port);
    let b = (u32::from(dst_ip), dst_port);
    if a <= b {
        FlowKey {
            src_ip,
            dst_ip,
            src_port,
            dst_port,
            proto,
        }
    } else {
        FlowKey {
            src_ip: dst_ip,
            dst_ip: src_ip,
            src_port: dst_port,
            dst_port: src_port,
            proto,
        }
    }
}

fn main() {
    let table = ShardedFlowTable::new(16);
    let source = DummySource::new(vec![]);
    let mut analyzer = FlowAnalyzer::new(source, table.clone());

    analyzer.run_once();

    let snapshot = table.snapshot();
    println!("Captured {} flows", snapshot.len());
    for (k, v) in snapshot {
        println!(
            "{:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={}",
            k.src_ip, k.src_port, k.dst_ip, k.dst_port, k.proto, v.packets, v.bytes
        );
    }
}
