#include <chrono>
#include <mutex>
#include <shared_mutex>
#include <unordered_map>

namespace netflow {

using Clock = std::chrono::steady_clock;
using TimePoint = Clock::time_point;

enum class Protocol : uint8_t {
    TCP = 6,
    UDP = 17,
    ICMP = 1,
    OTHER = 255
};

struct PacketView {
    const uint8_t* data = nullptr;
    size_t len = 0;
    TimePoint ts{};

    // Parsed metadata
    uint32_t src_ip = 0;   // IPv4 only for initial implementation
    uint32_t dst_ip = 0;
    uint16_t src_port = 0;
    uint16_t dst_port = 0;
    Protocol proto = Protocol::OTHER;
    bool valid = false;
};

struct FlowKey {
    uint32_t ip_a = 0;
    uint32_t ip_b = 0;
    uint16_t port_a = 0;
    uint16_t port_b = 0;
    uint8_t proto = 0;

    bool operator==(const FlowKey& other) const noexcept {
        return ip_a == other.ip_a &&
               ip_b == other.ip_b &&
               port_a == other.port_a &&
               port_b == other.port_b &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast-ish mix for initial implementation
        uint64_t x = 0;
        x ^= (uint64_t)k.ip_a * 0x9e3779b185ebca87ULL;
        x ^= (uint64_t)k.ip_b * 0xc2b2ae3d27d4eb4fULL;
        x ^= (uint64_t)k.port_a << 16;
        x ^= (uint64_t)k.port_b << 32;
        x ^= (uint64_t)k.proto << 48;

        // final avalanche
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return static_cast<size_t>(x);
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    TimePoint first_seen{};
    TimePoint last_seen{};
};

struct FlowRecord {
    FlowKey key{};
    FlowStats stats{};
    bool initialized = false;
};

struct ExportedFlow {
    FlowKey key{};
    FlowStats stats{};
};

class FlowAnalyzer {
public:
    struct Config {
        size_t max_flows = 1'000'000;
        std::chrono::seconds inactive_timeout{30};
        std::chrono::seconds active_timeout{300};
        size_t export_batch_size = 4096;
    };

    explicit FlowAnalyzer(Config cfg);

    // Parse raw packet bytes into PacketView (IPv4 + TCP/UDP initial support)
    static PacketView parse_packet(const uint8_t* data, size_t len, TimePoint ts);

    // Main update path
    void process_packet(const PacketView& pkt);

    // Expire inactive/old flows and return completed flows
    std::vector<ExportedFlow> expire_flows(TimePoint now);

    // Snapshot current number of active flows
    size_t active_flow_count() const noexcept;

private:
    static FlowKey make_flow_key(uint32_t src_ip, uint32_t dst_ip,
                                 uint16_t src_port, uint16_t dst_port,
                                 Protocol proto);

    void update_flow(const FlowKey& key, size_t bytes, TimePoint ts);
    void evict_one_if_needed(TimePoint now);

private:
    Config cfg_;

    mutable std::shared_mutex mutex_;
    std::unordered_map<FlowKey, FlowRecord, FlowKeyHash> flows_;
};

} // namespace netflow
