#include "flow_analyzer.hpp"

#include <algorithm>
#include <stdexcept>

namespace netflow {

namespace {

#pragma pack(push, 1)
struct IPv4Header {
    uint8_t ver_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_frag;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src;
    uint32_t dst;
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t length;
    uint16_t checksum;
};
#pragma pack(pop)

static inline uint16_t read_be16(const void* p) {
    const auto* b = static_cast<const uint8_t*>(p);
    return (uint16_t(b[0]) << 8) | uint16_t(b[1]);
}

static inline uint32_t read_be32(const void* p) {
    const auto* b = static_cast<const uint8_t*>(p);
    return (uint32_t(b[0]) << 24) |
           (uint32_t(b[1]) << 16) |
           (uint32_t(b[2]) << 8)  |
           uint32_t(b[3]);
}

static inline uint32_t ntoh32(uint32_t x) {
    return ((x & 0x000000FFu) << 24) |
           ((x & 0x0000FF00u) << 8)  |
           ((x & 0x00FF0000u) >> 8)  |
           ((x & 0xFF000000u) >> 24);
}

static inline uint16_t ntoh16(uint16_t x) {
    return static_cast<uint16_t>((x >> 8) | (x << 8));
}

} // namespace

FlowAnalyzer::FlowAnalyzer(Config cfg)
    : cfg_(cfg) {
    flows_.reserve(cfg_.max_flows / 2);
}

PacketView FlowAnalyzer::parse_packet(const uint8_t* data, size_t len, TimePoint ts) {
    PacketView pkt;
    pkt.data = data;
    pkt.len = len;
    pkt.ts = ts;

    if (!data || len < sizeof(IPv4Header)) {
        return pkt;
    }

    const auto* ip = reinterpret_cast<const IPv4Header*>(data);
    const uint8_t version = ip->ver_ihl >> 4;
    const uint8_t ihl = ip->ver_ihl & 0x0F;
    const size_t ip_header_len = size_t(ihl) * 4;

    if (version != 4 || ihl < 5 || len < ip_header_len) {
        return pkt;
    }

    pkt.src_ip = ntoh32(ip->src);
    pkt.dst_ip = ntoh32(ip->dst);

    const uint8_t proto = ip->protocol;
    const uint8_t* l4 = data + ip_header_len;
    const size_t l4_len = len - ip_header_len;

    if (proto == static_cast<uint8_t>(Protocol::TCP)) {
        if (l4_len < sizeof(TCPHeader)) return pkt;
        const auto* tcp = reinterpret_cast<const TCPHeader*>(l4);
        pkt.src_port = ntoh16(tcp->src_port);
        pkt.dst_port = ntoh16(tcp->dst_port);
        pkt.proto = Protocol::TCP;
        pkt.valid = true;
        return pkt;
    }

    if (proto == static_cast<uint8_t>(Protocol::UDP)) {
        if (l4_len < sizeof(UDPHeader)) return pkt;
        const auto* udp = reinterpret_cast<const UDPHeader*>(l4);
        pkt.src_port = ntoh16(udp->src_port);
        pkt.dst_port = ntoh16(udp->dst_port);
        pkt.proto = Protocol::UDP;
        pkt.valid = true;
        return pkt;
    }

    // For non-TCP/UDP, still track by IP pair
    pkt.proto = static_cast<Protocol>(proto);
    pkt.valid = true;
    return pkt;
}

FlowKey FlowAnalyzer::make_flow_key(uint32_t src_ip, uint32_t dst_ip,
                                    uint16_t src_port, uint16_t dst_port,
                                    Protocol proto) {
    FlowKey k;
    k.proto = static_cast<uint8_t>(proto);

    // Normalize for bidirectional flow aggregation
    const bool swap =
        (src_ip > dst_ip) ||
        (src_ip == dst_ip && src_port > dst_port);

    if (swap) {
        k.ip_a = dst_ip;
        k.ip_b = src_ip;
        k.port_a = dst_port;
        k.port_b = src_port;
    } else {
        k.ip_a = src_ip;
        k.ip_b = dst_ip;
        k.port_a = src_port;
        k.port_b = dst_port;
    }

    return k;
}

void FlowAnalyzer::update_flow(const FlowKey& key, size_t bytes, TimePoint ts) {
    auto it = flows_.find(key);
    if (it == flows_.end()) {
        if (flows_.size() >= cfg_.max_flows) {
            evict_one_if_needed(ts);
        }

        FlowRecord rec;
        rec.key = key;
        rec.initialized = true;
        rec.stats.packets = 1;
        rec.stats.bytes = bytes;
        rec.stats.first_seen = ts;
        rec.stats.last_seen = ts;
        flows_.emplace(key, std::move(rec));
        return;
    }

    auto& st = it->second.stats;
    st.packets += 1;
    st.bytes += bytes;
    st.last_seen = ts;
}

void FlowAnalyzer::process_packet(const PacketView& pkt) {
    if (!pkt.valid) return;

    const size_t bytes = pkt.len;
    const FlowKey key = make_flow_key(pkt.src_ip, pkt.dst_ip, pkt.src_port, pkt.dst_port, pkt.proto);

    std::unique_lock lock(mutex_);
    update_flow(key, bytes, pkt.ts);
}

std::vector<ExportedFlow> FlowAnalyzer::expire_flows(TimePoint now) {
    std::vector<ExportedFlow> expired;
    expired.reserve(cfg_.export_batch_size);

    std::unique_lock lock(mutex_);

    for (auto it = flows_.begin(); it != flows_.end(); ) {
        const auto& st = it->second.stats;
        const auto inactive_age = now - st.last_seen;
        const auto active_age = now - st.first_seen;

        if (inactive_age >= cfg_.inactive_timeout || active_age >= cfg_.active_timeout) {
            expired.push_back(ExportedFlow{it->second.key, it->second.stats});
            it = flows_.erase(it);

            if (expired.size() >= cfg_.export_batch_size) {
                break;
            }
        } else {
            ++it;
        }
    }

    return expired;
}

void FlowAnalyzer::evict_one_if_needed(TimePoint now) {
    if (flows_.empty()) return;

    // Simple eviction policy for initial implementation:
    // remove the oldest inactive/least recently seen candidate.
    auto victim = flows_.begin();
    for (auto it = flows_.begin(); it != flows_.end(); ++it) {
        if (it->second.stats.last_seen < victim->second.stats.last_seen) {
            victim = it;
        }
    }

    flows_.erase(victim);
}

size_t FlowAnalyzer::active_flow_count() const noexcept {
    std::shared_lock lock(mutex_);
    return flows_.size();
}

} // namespace netflow
