# src/parser.rs

```rust
use crate::flow::FlowKey;
use std::net::Ipv4Addr;

#[derive(Debug)]
pub enum ParseError {
    Truncated,
    UnsupportedEthertype,
    UnsupportedIpVersion,
    UnsupportedProtocol,
}

pub fn parse_flow_key(packet: &[u8]) -> Result<(FlowKey, usize), ParseError> {
    // Ethernet header: 14 bytes
    if packet.len() < 14 {
        return Err(ParseError::Truncated);
    }

    let ethertype = u16::from_be_bytes([packet[12], packet[13]]);
    if ethertype != 0x0800 {
        return Err(ParseError::UnsupportedEthertype);
    }

    // IPv4 header
    let ip_offset = 14;
    if packet.len() < ip_offset + 20 {
        return Err(ParseError::Truncated);
    }

    let version_ihl = packet[ip_offset];
    let version = version_ihl >> 4;
    let ihl = (version_ihl & 0x0f) as usize * 4;

    if version != 4 {
        return Err(ParseError::UnsupportedIpVersion);
    }
    if packet.len() < ip_offset + ihl {
        return Err(ParseError::Truncated);
    }

    let proto = packet[ip_offset + 9];
    let src_ip = Ipv4Addr::new(
        packet[ip_offset + 12],
        packet[ip_offset + 13],
        packet[ip_offset + 14],
        packet[ip_offset + 15],
    );
    let dst_ip = Ipv4Addr::new(
        packet[ip_offset + 16],
        packet[ip_offset + 17],
        packet[ip_offset + 18],
        packet[ip_offset + 19],
    );

    let l4_offset = ip_offset + ihl;
    if packet.len() < l4_offset + 4 {
        return Err(ParseError::Truncated);
    }

    let (src_port, dst_port) = match proto {
        6 | 17 => {
            let src_port = u16::from_be_bytes([packet[l4_offset], packet[l4_offset + 1]]);
            let dst_port = u16::from_be_bytes([packet[l4_offset + 2], packet[l4_offset + 3]]);
            (src_port, dst_port)
        }
        _ => return Err(ParseError::UnsupportedProtocol),
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    Ok((key, packet.len()))
}
