use crate::flow::{FlowKey, FlowStats};
use dashmap::DashMap;
use std::time::{Duration, Instant};

pub struct FlowCollector {
    flows: DashMap<FlowKey, FlowStats>,
    idle_timeout: Duration,
}

impl FlowCollector {
    pub fn new(idle_timeout: Duration) -> Self {
        Self {
            flows: DashMap::new(),
            idle_timeout,
        }
    }

    pub fn ingest(&self, key: FlowKey, bytes: usize) {
        let now = Instant::now();

        if let Some(mut entry) = self.flows.get_mut(&key) {
            entry.update(now, bytes);
        } else {
            self.flows.insert(key, FlowStats::new(now, bytes));
        }
    }

    pub fn expire_idle(&self) -> Vec<(FlowKey, FlowStats)> {
        let now = Instant::now();
        let mut expired = Vec::new();

        let keys: Vec<FlowKey> = self
            .flows
            .iter()
            .filter_map(|entry| {
                if entry.value().age(now) >= self.idle_timeout {
                    Some(*entry.key())
                } else {
                    None
                }
            })
            .collect();

        for key in keys {
            if let Some((k, v)) = self.flows.remove(&key) {
                expired.push((k, v));
            }
        }

        expired
    }

    pub fn len(&self) -> usize {
        self.flows.len()
    }
}
```

