# src/main.rs

```rust
mod collector;
mod flow;
mod parser;

use anyhow::Result;
use collector::FlowCollector;
use parser::parse_flow_key;
use std::fs::File;
use std::io::{BufReader, Read};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

fn main() -> Result<()> {
    env_logger::init();

    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <packet_file>", args[0]);
        eprintln!("Packet file should contain raw Ethernet frames concatenated.");
        std::process::exit(1);
    }

    let packet_file = &args[1];
    let collector = Arc::new(FlowCollector::new(Duration::from_secs(30)));

    // Aging thread
    {
        let collector = Arc::clone(&collector);
        thread::spawn(move || loop {
            thread::sleep(Duration::from_secs(5));
            let expired = collector.expire_idle();
            if !expired.is_empty() {
                println!("Expired {} flows", expired.len());
                for (key, stats) in expired {
                    println!(
                        "FLOW {:?} packets={} bytes={}",
                        key, stats.packets, stats.bytes
                    );
                }
            }
        });
    }

    // Simple packet ingestion from file
    // NOTE: This assumes each packet is length-prefixed as:
    // [u32 big-endian length][packet bytes...]
    let file = File::open(packet_file)?;
    let mut reader = BufReader::new(file);

    loop {
        let mut len_buf = [0u8; 4];
        if reader.read_exact(&mut len_buf).is_err() {
            break;
        }

        let len = u32::from_be_bytes(len_buf) as usize;
        let mut packet = vec![0u8; len];
        reader.read_exact(&mut packet)?;

        match parse_flow_key(&packet) {
            Ok((key, bytes)) => {
                collector.ingest(key, bytes);
            }
            Err(_) => {
                // Ignore unsupported/truncated packets for now
            }
        }
    }

    println!("Final flow count: {}", collector.len());
    Ok(())
}
```

