```rust
use ahash::RandomState;
use hashbrown::HashMap;
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
#[repr(C)]
pub struct FlowKey {
    pub src_ip: u32,
    pub dst_ip: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub _pad: u8,
}

impl FlowKey {
    #[inline(always)]
    pub fn new(src_ip: Ipv4Addr, dst_ip: Ipv4Addr, src_port: u16, dst_port: u16, proto: u8) -> Self {
        Self {
            src_ip: u32::from(src_ip),
            dst_ip: u32::from(dst_ip),
            src_port,
            dst_port,
            proto,
            _pad: 0,
        }
    }
}

#[derive(Clone, Debug)]
pub struct FlowStats {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

impl FlowStats {
    #[inline(always)]
    pub fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    #[inline(always)]
    pub fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

pub struct FlowTable {
    flows: HashMap<FlowKey, FlowStats, RandomState>,
    idle_timeout: Duration,
    expire_scan_budget: usize,
}

impl FlowTable {
    pub fn with_capacity(capacity: usize, idle_timeout: Duration) -> Self {
        Self {
            flows: HashMap::with_capacity_and_hasher(capacity, RandomState::new()),
            idle_timeout,
            expire_scan_budget: 4096,
        }
    }

    #[inline(always)]
    pub fn process_packet(
        &mut self,
        src_ip: Ipv4Addr,
        dst_ip: Ipv4Addr,
        src_port: u16,
        dst_port: u16,
        proto: u8,
        packet_len: usize,
        now: Instant,
    ) {
        let key = FlowKey::new(src_ip, dst_ip, src_port, dst_port, proto);

        if let Some(stats) = self.flows.get_mut(&key) {
            stats.update(now, packet_len);
        } else {
            self.flows.insert(key, FlowStats::new(now, packet_len));
        }
    }

    pub fn expire_flows(&mut self, now: Instant) -> usize {
        let timeout = self.idle_timeout;
        let mut expired = 0usize;

        // Budgeted scan to avoid long pauses on large tables.
        // This is a simple initial implementation; more advanced versions
        // should use timing wheels or per-bucket expiration structures.
        let mut to_remove = Vec::new();
        to_remove.reserve(self.expire_scan_budget.min(self.flows.len()));

        for (k, v) in self.flows.iter() {
            if now.duration_since(v.last_seen) >= timeout {
                to_remove.push(*k);
                expired += 1;
                if expired >= self.expire_scan_budget {
                    break;
                }
            }
        }

        for k in to_remove {
            self.flows.remove(&k);
        }

        expired
    }

    pub fn len(&self) -> usize {
        self.flows.len()
    }

    pub fn is_empty(&self) -> bool {
        self.flows.is_empty()
    }
}

/// Example packet metadata coming from a capture engine.
#[derive(Clone, Copy, Debug)]
pub struct PacketMeta {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
    pub len: usize,
    pub ts: Instant,
}

pub struct Analyzer {
    table: FlowTable,
    packets_seen: u64,
    bytes_seen: u64,
    last_expire: Instant,
    expire_interval: Duration,
}

impl Analyzer {
    pub fn new(capacity: usize, idle_timeout: Duration, expire_interval: Duration) -> Self {
        let now = Instant::now();
        Self {
            table: FlowTable::with_capacity(capacity, idle_timeout),
            packets_seen: 0,
            bytes_seen: 0,
            last_expire: now,
            expire_interval,
        }
    }

    #[inline(always)]
    pub fn ingest(&mut self, pkt: PacketMeta) {
        self.packets_seen += 1;
        self.bytes_seen += pkt.len as u64;

        self.table.process_packet(
            pkt.src_ip,
            pkt.dst_ip,
            pkt.src_port,
            pkt.dst_port,
            pkt.proto,
            pkt.len,
            pkt.ts,
        );

        if pkt.ts.duration_since(self.last_expire) >= self.expire_interval {
            self.last_expire = pkt.ts;
            let expired = self.table.expire_flows(pkt.ts);
            if expired > 0 {
                println!("expired {} flows, active={}", expired, self.table.len());
            }
        }
    }

    pub fn stats(&self) -> (u64, u64, usize) {
        (self.packets_seen, self.bytes_seen, self.table.len())
    }
}

fn main() {
    let mut analyzer = Analyzer::new(
        1_000_000,
        Duration::from_secs(30),
        Duration::from_secs(1),
    );

    // Simulated packet stream
    let start = Instant::now();
    for i in 0..5_000_000u64 {
        let pkt = PacketMeta {
            src_ip: Ipv4Addr::new(10, 0, ((i >> 8) & 0xff) as u8, (i & 0xff) as u8),
            dst_ip: Ipv4Addr::new(192, 168, 1, ((i >> 16) & 0xff) as u8),
            src_port: (1000 + (i % 50000) as u16),
            dst_port: 443,
            proto: 6,
            len: 64 + (i as usize % 1400),
            ts: start + Duration::from_micros(i),
        };

        analyzer.ingest(pkt);
    }

    let (pkts, bytes, flows) = analyzer.stats();
    println!("packets={}, bytes={}, active_flows={}", pkts, bytes, flows);
}
