Below is an initial implementation of a **performance-oriented network flow analyser** in **Go**, designed to ingest packet metadata at high rate and aggregate it into bidirectional flows with low allocation overhead.

It is intentionally a **starter architecture** for gigabit-scale traffic:
- uses **fixed-size flow keys**
- uses a **sharded map** to reduce lock contention
- uses **periodic expiration**
- keeps per-flow stats in a compact struct
- avoids packet payload processing
- is suitable for feeding from a high-speed packet capture pipeline

---

## Design goals

- **High throughput**: minimize allocations and lock contention
- **Low latency**: fast flow lookup/update path
- **Scalable**: sharded state across CPU cores
- **Practical**: supports IPv4/IPv6, TCP/UDP/other
- **Extensible**: easy to plug into pcap, AF_PACKET, DPDK, eBPF, etc.

---

## Core implementation

```go
package flowanalyzer

import (
	"encoding/binary"
	"net"
	"sync"
	"sync/atomic"
	"time"
)

type Protocol uint8

const (
	ProtoOther Protocol = 0
	ProtoTCP   Protocol = 6
	ProtoUDP   Protocol = 17
	ProtoICMP  Protocol = 1
)

type FlowKey struct {
	// Canonicalized 5-tuple:
	// - IPs are stored in network byte order
	// - ports are ordered so that A->B and B->A map to same flow
	// - proto is included
	IPVersion uint8 // 4 or 6
	Proto     Protocol

	SrcPort uint16
	DstPort uint16

	// IPv4 uses first 4 bytes of each array; IPv6 uses all 16.
	SrcIP [16]byte
	DstIP [16]byte
}

type FlowStats struct {
	Packets uint64
	Bytes   uint64

	FirstSeenUnixNano uint64
	LastSeenUnixNano  uint64

	// Optional counters
	TCPFlags uint8
}

type Flow struct {
	Key   FlowKey
	Stats FlowStats
}

type shard struct {
	mu    sync.RWMutex
	flows map[FlowKey]*Flow
}

type Analyzer struct {
	shards    []shard
	shardMask uint64

	// Expiration
	ttlNanos uint64

	// Stats
	flowCount atomic.Uint64
}

func NewAnalyzer(shardCount int, ttl time.Duration) *Analyzer {
	if shardCount <= 0 {
		shardCount = 64
	}
	// Prefer power of two for fast masking
	n := 1
	for n < shardCount {
		n <<= 1
	}
	shardCount = n

	a := &Analyzer{
		shards:    make([]shard, shardCount),
		shardMask: uint64(shardCount - 1),
		ttlNanos:  uint64(ttl.Nanoseconds()),
	}
	for i := range a.shards {
		a.shards[i].flows = make(map[FlowKey]*Flow, 1024)
	}
	return a
}

func canonicalizeIPv4(src, dst net.IP, srcPort, dstPort uint16, proto Protocol) FlowKey {
	var key FlowKey
	key.IPVersion = 4
	key.Proto = proto

	s := src.To4()
	d := dst.To4()
	copy(key.SrcIP[:4], s)
	copy(key.DstIP[:4], d)

	// Canonicalize direction to make bidirectional flows identical.
	if lessEndpoint(key.DstIP[:4], dstPort, key.SrcIP[:4], srcPort) {
		key.SrcIP, key.DstIP = key.DstIP, key.SrcIP
		srcPort, dstPort = dstPort, srcPort
	}
	key.SrcPort = srcPort
	key.DstPort = dstPort
	return key
}

func canonicalizeIPv6(src, dst net.IP, srcPort, dstPort uint16, proto Protocol) FlowKey {
	var key FlowKey
	key.IPVersion = 6
	key.Proto = proto

	s := src.To16()
	d := dst.To16()
	copy(key.SrcIP[:], s)
	copy(key.DstIP[:], d)

	if lessEndpoint(key.DstIP[:], dstPort, key.SrcIP[:], srcPort) {
		key.SrcIP, key.DstIP = key.DstIP, key.SrcIP
		srcPort, dstPort = dstPort, srcPort
	}
	key.SrcPort = srcPort
	key.DstPort = dstPort
	return key
}

func lessEndpoint(ipA []byte, portA uint16, ipB []byte, portB uint16) bool {
	for i := 0; i < len(ipA) && i < len(ipB); i++ {
		if ipA[i] < ipB[i] {
			return true
		}
		if ipA[i] > ipB[i] {
			return false
		}
	}
	return portA < portB
}

func (a *Analyzer) shardFor(key FlowKey) *shard {
	// Fast hash: FNV-like mixing over fixed-size key bytes.
	// For production, consider xxhash or a custom SIMD-friendly hash.
	h := uint64(key.IPVersion) | uint64(key.Proto)<<8 | uint64(key.SrcPort)<<16 | uint64(key.DstPort)<<32
	for _, b := range key.SrcIP {
		h ^= uint64(b)
		h *= 1099511628211
	}
	for _, b := range key.DstIP {
		h ^= uint64(b)
		h *= 1099511628211
	}
	return &a.shards[h&a.shardMask]
}

func (a *Analyzer) ProcessPacket(
	srcIP, dstIP net.IP,
	srcPort, dstPort uint16,
	proto Protocol,
	packetLen int,
	ts time.Time,
) {
	var key FlowKey
	if srcIP.To4() != nil && dstIP.To4() != nil {
		key = canonicalizeIPv4(srcIP, dstIP, srcPort, dstPort, proto)
	} else {
		key = canonicalizeIPv6(srcIP, dstIP, srcPort, dstPort, proto)
	}

	s := a.shardFor(key)
	now := uint64(ts.UnixNano())

	s.mu.Lock()
	defer s.mu.Unlock()

	flow, ok := s.flows[key]
	if !ok {
		flow = &Flow{Key: key}
		flow.Stats.FirstSeenUnixNano = now
		s.flows[key] = flow
		a.flowCount.Add(1)
	}
	flow.Stats.Packets++
	flow.Stats.Bytes += uint64(packetLen)
	flow.Stats.LastSeenUnixNano = now
}

func (a *Analyzer) Expire(now time.Time) int {
	nowN := uint64(now.UnixNano())
	expired := 0

	for i := range a.shards {
		s := &a.shards[i]
		s.mu.Lock()
		for k, f := range s.flows {
			if nowN-f.Stats.LastSeenUnixNano > a.ttlNanos {
				delete(s.flows, k)
				expired++
				a.flowCount.Add(^uint64(0)) // decrement by 1
			}
		}
		s.mu.Unlock()
	}
	return expired
}

func (a *Analyzer) FlowCount() uint64 {
	return a.flowCount.Load()
}

func (f *Flow) SerializeBinary(dst []byte) []byte {
	// Minimal binary export format:
	// [version][proto][srcport][dstport][srcip][dstip][packets][bytes][first][last]
	// Caller provides buffer; append-based to reduce allocations.
	dst = append(dst, f.Key.IPVersion)
	dst = append(dst, byte(f.Key.Proto))

	var tmp [8]byte
	binary.BigEndian.PutUint16(tmp[:2], f.Key.SrcPort)
	dst = append(dst, tmp[:2]...)
	binary.BigEndian.PutUint16(tmp[:2], f.Key.DstPort)
	dst = append(dst, tmp[:2]...)

	if f.Key.IPVersion == 4 {
		dst = append(dst, f.Key.SrcIP[:4]...)
		dst = append(dst, f.Key.DstIP[:4]...)
	} else {
		dst = append(dst, f.Key.SrcIP[:]...)
		dst = append(dst, f.Key.DstIP[:]...)
	}

	binary.BigEndian.PutUint64(tmp[:], f.Stats.Packets)
	dst = append(dst, tmp[:]...)
	binary.BigEndian.PutUint64(tmp[:], f.Stats.Bytes)
	dst = append(dst, tmp[:]...)
	binary.BigEndian.PutUint64(tmp[:], f.Stats.FirstSeenUnixNano)
	dst = append(dst, tmp[:]...)
	binary.BigEndian.PutUint64(tmp[:], f.Stats.LastSeenUnixNano)
	dst = append(dst, tmp[:]...)

	return dst
}
```

