## Complete working version

```go
package main

import (
	"encoding/binary"
	"fmt"
	"hash/fnv"
	"log"
	"net"
	"os"
	"os/signal"
	"sync"
	"syscall"
	"time"
)

const (
	NumShards        = 64
	FlowIdleTimeout  = 30 * time.Second
	ReapInterval     = 5 * time.Second
	EtherTypeIPv4    = 0x0800
	EtherTypeIPv6    = 0x86DD
	IPProtocolTCP    = 6
	IPProtocolUDP    = 17
	DefaultQueueSize = 8192
)

type FlowKey struct {
	SrcIP   [16]byte
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	IPVer   uint8
}

type FlowStats struct {
	Packets   uint64
	Bytes     uint64
	FirstSeen time.Time
	LastSeen  time.Time
}

type FlowRecord struct {
	Key   FlowKey
	Stats FlowStats
}

type Packet struct {
	Data []byte
	Seen time.Time
}

type ParsedPacket struct {
	Packet
	Key FlowKey
	Len int
}

type Shard struct {
	in      chan ParsedPacket
	flows   map[FlowKey]*FlowRecord
	quit    chan struct{}
	wg      sync.WaitGroup
	timeout time.Duration
}

type Analyzer struct {
	shards []*Shard
}

func NewAnalyzer(numShards int, timeout time.Duration) *Analyzer {
	a := &Analyzer{
		shards: make([]*Shard, numShards),
	}
	for i := 0; i < numShards; i++ {
		s := &Shard{
			in:      make(chan ParsedPacket, DefaultQueueSize),
			flows:   make(map[FlowKey]*FlowRecord, 1<<14),
			quit:    make(chan struct{}),
			timeout: timeout,
		}
		a.shards[i] = s
		s.wg.Add(1)
		go s.run()
	}
	return a
}

func (a *Analyzer) Stop() {
	for _, s := range a.shards {
		close(s.quit)
	}
	for _, s := range a.shards {
		s.wg.Wait()
	}
}

func (a *Analyzer) Ingest(pkt Packet) {
	key, ok, plen := parseFlowKey(pkt.Data)
	if !ok {
		return
	}
	idx := shardIndex(key, len(a.shards))
	pp := ParsedPacket{
		Packet: pkt,
		Key:    key,
		Len:    plen,
	}
	select {
	case a.shards[idx].in <- pp:
	default:
		// Drop under pressure to preserve throughput.
	}
}

func (s *Shard) run() {
	defer s.wg.Done()

	ticker := time.NewTicker(ReapInterval)
	defer ticker.Stop()

	for {
		select {
		case p := <-s.in:
			s.updateFlow(p)
		case <-ticker.C:
			s.reapExpired(time.Now())
		case <-s.quit:
			s.flushAll()
			return
		}
	}
}

func (s *Shard) updateFlow(p ParsedPacket) {
	rec, ok := s.flows[p.Key]
	if !ok {
		rec = &FlowRecord{
			Key: p.Key,
			Stats: FlowStats{
				Packets:   1,
				Bytes:     uint64(p.Len),
				FirstSeen: p.Seen,
				LastSeen:  p.Seen,
			},
		}
		s.flows[p.Key] = rec
		return
	}

	rec.Stats.Packets++
	rec.Stats.Bytes += uint64(p.Len)
	rec.Stats.LastSeen = p.Seen
}

func (s *Shard) reapExpired(now time.Time) {
	for k, rec := range s.flows {
		if now.Sub(rec.Stats.LastSeen) > s.timeout {
			exportFlow(rec)
			delete(s.flows, k)
		}
	}
}

func (s *Shard) flushAll() {
	for k, rec := range s.flows {
		exportFlow(rec)
		delete(s.flows, k)
	}
}

func exportFlow(rec *FlowRecord) {
	fmt.Printf(
		"FLOW %s:%d -> %s:%d proto=%d ver=%d packets=%d bytes=%d first=%s last=%s\n",
		ipString(rec.Key.SrcIP, rec.Key.IPVer),
		rec.Key.SrcPort,
		ipString(rec.Key.DstIP, rec.Key.IPVer),
		rec.Key.DstPort,
		rec.Key.Proto,
		rec.Key.IPVer,
		rec.Stats.Packets,
		rec.Stats.Bytes,
		rec.Stats.FirstSeen.Format(time.RFC3339Nano),
		rec.Stats.LastSeen.Format(time.RFC3339Nano),
	)
}

func shardIndex(key FlowKey, n int) int {
	h := fnv.New64a()
	h.Write(key.SrcIP[:])
	h.Write(key.DstIP[:])

	var b [8]byte
	binary.LittleEndian.PutUint16(b[:2], key.SrcPort)
	binary.LittleEndian.PutUint16(b[2:4], key.DstPort)
	b[4] = key.Proto
	b[5] = key.IPVer
	h.Write(b[:6])

	return int(h.Sum64() % uint64(n))
}

func parseFlowKey(data []byte) (FlowKey, bool, int) {
	// Ethernet header: 14 bytes
	if len(data) < 14 {
		return FlowKey{}, false, 0
	}

	ethType := binary.BigEndian.Uint16(data[12:14])
	offset := 14

	var key FlowKey
	switch ethType {
	case EtherTypeIPv4:
		if len(data) < offset+20 {
			return FlowKey{}, false, 0
		}
		ihl := int(data[offset]&0x0F) * 4
		if ihl < 20 || len(data) < offset+ihl {
			return FlowKey{}, false, 0
		}
		proto := data[offset+9]
		key.IPVer = 4
		key.Proto = proto

		copy(key.SrcIP[:4], data[offset+12:offset+16])
		copy(key.DstIP[:4], data[offset+16:offset+20])

		l4 := offset + ihl
		if proto == IPProtocolTCP || proto == IPProtocolUDP {
			if len(data) < l4+4 {
				return FlowKey{}, false, 0
			}
			key.SrcPort = binary.BigEndian.Uint16(data[l4 : l4+2])
			key.DstPort = binary.BigEndian.Uint16(data[l4+2 : l4+4])
		}
		return key, true, len(data)

	case EtherTypeIPv6:
		if len(data) < offset+40 {
			return FlowKey{}, false, 0
		}
		nextHeader := data[offset+6]
		key.IPVer = 6
		key.Proto = nextHeader

		copy(key.SrcIP[:16], data[offset+8:offset+24])
		copy(key.DstIP[:16], data[offset+24:offset+40])

		l4 := offset + 40
		if nextHeader == IPProtocolTCP || nextHeader == IPProtocolUDP {
			if len(data) < l4+4 {
				return FlowKey{}, false, 0
			}
			key.SrcPort = binary.BigEndian.Uint16(data[l4 : l4+2])
			key.DstPort = binary.BigEndian.Uint16(data[l4+2 : l4+4])
		}
		return key, true, len(data)
	default:
		return FlowKey{}, false, 0
	}
}

func ipString(ip [16]byte, ver uint8) string {
	if ver == 4 {
		return net.IP(ip[:4]).String()
	}
	return net.IP(ip[:]).String()
}

func buildSyntheticIPv4TCPPacket(src, dst net.IP, sport, dport uint16) []byte {
	// Ethernet(14) + IPv4(20) + TCP(20) = 54 bytes
	p := make([]byte, 54)

	// Ethernet header
	copy(p[0:6], []byte{0, 1, 2, 3, 4, 5})
	copy(p[6:12], []byte{6, 7, 8, 9, 10, 11})
	binary.BigEndian.PutUint16(p[12:14], EtherTypeIPv4)

	// IPv4 header
	p[14] = 0x45
	p[15] = 0x00
	binary.BigEndian.PutUint16(p[16:18], 40) // IP payload length
	binary.BigEndian.PutUint16(p[18:20], 0)
	binary.BigEndian.PutUint16(p[20:22], 0)
	p[22] = 64
	p[23] = IPProtocolTCP
	copy(p[26:30], src.To4())
	copy(p[30:34], dst.To4())

	// TCP header
	binary.BigEndian.PutUint16(p[34:36], sport)
	binary.BigEndian.PutUint16(p[36:38], dport)
	binary.BigEndian.PutUint32(p[38:42], 1)
	binary.BigEndian.PutUint32(p[42:46], 1)
	p[46] = 0x50
	p[47] = 0x02
	binary.BigEndian.PutUint16(p[48:50], 65535)

	return p
}

func main() {
	analyzer := NewAnalyzer(NumShards, FlowIdleTimeout)

	// Synthetic traffic generator for testing.
	go func() {
		for i := 0; i < 500000; i++ {
			pkt := buildSyntheticIPv4TCPPacket(
				net.IPv4(10, 0, 0, byte(i%255)),
				net.IPv4(10, 0, 1, byte((i+1)%255)),
				uint16(1000+i%1000),
				80,
			)
			analyzer.Ingest(Packet{
				Data: pkt,
				Seen: time.Now(),
			})
		}
	}()

	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)
	<-sigCh

	log.Println("Shutting down...")
	analyzer.Stop()
}
