```rust
use ahash::AHasher;
use crossbeam::queue::SegQueue;
use parking_lot::Mutex;
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::net::IpAddr;
use std::sync::Arc;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
pub struct FlowKey {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
}

#[derive(Clone, Debug)]
pub struct FlowRecord {
    pub packets: u64,
    pub bytes: u64,
    pub first_seen: Instant,
    pub last_seen: Instant,
}

impl FlowRecord {
    pub fn new(now: Instant, bytes: u64) -> Self {
        Self {
            packets: 1,
            bytes,
            first_seen: now,
            last_seen: now,
        }
    }

    pub fn update(&mut self, now: Instant, bytes: u64) {
        self.packets += 1;
        self.bytes += bytes;
        self.last_seen = now;
    }
}

pub struct FlowShard {
    map: Mutex<HashMap<FlowKey, FlowRecord>>,
}

impl FlowShard {
    pub fn new(capacity: usize) -> Self {
        Self {
            map: Mutex::new(HashMap::with_capacity(capacity)),
        }
    }

    pub fn ingest(&self, key: FlowKey, now: Instant, bytes: u64) {
        let mut map = self.map.lock();
        match map.get_mut(&key) {
            Some(record) => record.update(now, bytes),
            None => {
                map.insert(key, FlowRecord::new(now, bytes));
            }
        }
    }

    pub fn expire(&self, cutoff: Instant) -> usize {
        let mut map = self.map.lock();
        let before = map.len();
        map.retain(|_, record| record.last_seen >= cutoff);
        before - map.len()
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowRecord)> {
        let map = self.map.lock();
        map.iter().map(|(k, v)| (*k, v.clone())).collect()
    }
}

pub struct FlowTable {
    shards: Vec<Arc<FlowShard>>,
    shard_mask: usize,
}

impl FlowTable {
    pub fn new(num_shards: usize, shard_capacity: usize) -> Self {
        assert!(num_shards.is_power_of_two(), "num_shards must be power of two");
        let shards = (0..num_shards)
            .map(|_| Arc::new(FlowShard::new(shard_capacity)))
            .collect::<Vec<_>>();

        Self {
            shards,
            shard_mask: num_shards - 1,
        }
    }

    fn shard_index(&self, key: &FlowKey) -> usize {
        let mut hasher = AHasher::default();
        key.hash(&mut hasher);
        (hasher.finish() as usize) & self.shard_mask
    }

    pub fn ingest(&self, key: FlowKey, now: Instant, bytes: u64) {
        let idx = self.shard_index(&key);
        self.shards[idx].ingest(key, now, bytes);
    }

    pub fn expire(&self, idle_timeout: Duration) -> usize {
        let cutoff = Instant::now() - idle_timeout;
        self.shards.iter().map(|s| s.expire(cutoff)).sum()
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowRecord)> {
        let mut out = Vec::new();
        for shard in &self.shards {
            out.extend(shard.snapshot());
        }
        out
    }
}

/// Simplified packet metadata for ingestion.
/// In a real implementation this would come from a parser/capture backend.
#[derive(Clone, Copy, Debug)]
pub struct PacketMeta {
    pub src_ip: IpAddr,
    pub dst_ip: IpAddr,
    pub src_port: u16,
    pub dst_port: u16,
    pub protocol: u8,
    pub bytes: u64,
}

impl PacketMeta {
    pub fn to_flow_key(&self) -> FlowKey {
        FlowKey {
            src_ip: self.src_ip,
            dst_ip: self.dst_ip,
            src_port: self.src_port,
            dst_port: self.dst_port,
            protocol: self.protocol,
        }
    }
}

pub struct Analyzer {
    flows: Arc<FlowTable>,
    expired_total: Arc<Mutex<u64>>,
    _event_queue: SegQueue<PacketMeta>,
}

impl Analyzer {
    pub fn new(num_shards: usize, shard_capacity: usize) -> Self {
        Self {
            flows: Arc::new(FlowTable::new(num_shards, shard_capacity)),
            expired_total: Arc::new(Mutex::new(0)),
            _event_queue: SegQueue::new(),
        }
    }

    pub fn ingest_packet(&self, packet: PacketMeta) {
        let now = Instant::now();
        self.flows.ingest(packet.to_flow_key(), now, packet.bytes);
    }

    pub fn expire_flows(&self, idle_timeout: Duration) {
        let expired = self.flows.expire(idle_timeout);
        *self.expired_total.lock() += expired as u64;
    }

    pub fn snapshot(&self) -> Vec<(FlowKey, FlowRecord)> {
        self.flows.snapshot()
    }

    pub fn expired_total(&self) -> u64 {
        *self.expired_total.lock()
    }
}

fn main() {
    let analyser = Analyzer::new(64, 1 << 16);

    // Example traffic
    let packets = vec![
        PacketMeta {
            src_ip: "10.0.0.1".parse().unwrap(),
            dst_ip: "10.0.0.2".parse().unwrap(),
            src_port: 12345,
            dst_port: 80,
            protocol: 6,
            bytes: 1500,
        },
        PacketMeta {
            src_ip: "10.0.0.1".parse().unwrap(),
            dst_ip: "10.0.0.2".parse().unwrap(),
            src_port: 12345,
            dst_port: 80,
            protocol: 6,
            bytes: 900,
        },
        PacketMeta {
            src_ip: "10.0.0.3".parse().unwrap(),
            dst_ip: "10.0.0.4".parse().unwrap(),
            src_port: 54321,
            dst_port: 443,
            protocol: 6,
            bytes: 1200,
        },
    ];

    for p in packets {
        analyser.ingest_packet(p);
    }

    analyser.expire_flows(Duration::from_secs(300));

    for (key, record) in analyser.snapshot() {
        println!(
            "{:?} packets={} bytes={} first_seen={:?} last_seen={:?}",
            key, record.packets, record.bytes, record.first_seen, record.last_seen
        );
    }

    println!("Expired total: {}", analyser.expired_total());
}
