## Initial C++20 implementation

```cpp
#include <arpa/inet.h>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <unordered_map>
#include <vector>
#include <chrono>
#include <optional>
#include <string>
#include <algorithm>

#pragma pack(push, 1)
struct EthernetHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};

struct IPv4Header {
    uint8_t version_ihl;
    uint8_t tos;
    uint16_t total_length;
    uint16_t identification;
    uint16_t flags_fragment;
    uint8_t ttl;
    uint8_t protocol;
    uint16_t checksum;
    uint32_t src_ip;
    uint32_t dst_ip;
};

struct TCPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t seq;
    uint32_t ack;
    uint8_t data_offset_reserved;
    uint8_t flags;
    uint16_t window;
    uint16_t checksum;
    uint16_t urgent_ptr;
};

struct UDPHeader {
    uint16_t src_port;
    uint16_t dst_port;
    uint16_t length;
    uint16_t checksum;
};
#pragma pack(pop)

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

struct FlowKeyHash {
    std::size_t operator()(const FlowKey& k) const noexcept {
        // Simple but decent hash for initial implementation
        std::size_t h = 1469598103934665603ULL;
        auto mix = [&](auto v) {
            using T = decltype(v);
            for (size_t i = 0; i < sizeof(T); ++i) {
                h ^= static_cast<uint8_t>((static_cast<uint64_t>(v) >> (i * 8)) & 0xff);
                h *= 1099511628211ULL;
            }
        };
        mix(k.src_ip);
        mix(k.dst_ip);
        mix(k.src_port);
        mix(k.dst_port);
        mix(k.protocol);
        return h;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key;
    FlowStats stats;
};

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(uint64_t inactive_timeout_ns = 30ULL * 1000 * 1000 * 1000)
        : inactive_timeout_ns_(inactive_timeout_ns) {
        flows_.reserve(1 << 20); // reserve for scale; tune as needed
    }

    void process_packet(const uint8_t* data, size_t len, uint64_t ts_ns) {
        if (len < sizeof(EthernetHeader)) return;

        const auto* eth = reinterpret_cast<const EthernetHeader*>(data);
        uint16_t ethertype = ntohs(eth->ethertype);

        if (ethertype != 0x0800) {
            // IPv4 only in this initial implementation
            return;
        }

        size_t offset = sizeof(EthernetHeader);
        if (len < offset + sizeof(IPv4Header)) return;

        const auto* ip = reinterpret_cast<const IPv4Header*>(data + offset);
        uint8_t version = ip->version_ihl >> 4;
        uint8_t ihl = ip->version_ihl & 0x0F;
        if (version != 4 || ihl < 5) return;

        size_t ip_header_len = ihl * 4;
        if (len < offset + ip_header_len) return;

        uint8_t proto = ip->protocol;
        uint32_t src_ip = ntohl(ip->src_ip);
        uint32_t dst_ip = ntohl(ip->dst_ip);

        offset += ip_header_len;

        uint16_t src_port = 0;
        uint16_t dst_port = 0;

        if (proto == 6) { // TCP
            if (len < offset + sizeof(TCPHeader)) return;
            const auto* tcp = reinterpret_cast<const TCPHeader*>(data + offset);
            src_port = ntohs(tcp->src_port);
            dst_port = ntohs(tcp->dst_port);
        } else if (proto == 17) { // UDP
            if (len < offset + sizeof(UDPHeader)) return;
            const auto* udp = reinterpret_cast<const UDPHeader*>(data + offset);
            src_port = ntohs(udp->src_port);
            dst_port = ntohs(udp->dst_port);
        } else {
            // For non-TCP/UDP, still track by protocol with zero ports
        }

        FlowKey key{src_ip, dst_ip, src_port, dst_port, proto};
        auto& entry = flows_[key];
        if (entry.stats.packets == 0) {
            entry.key = key;
            entry.stats.first_seen_ns = ts_ns;
        }
        entry.stats.packets++;
        entry.stats.bytes += len;
        entry.stats.last_seen_ns = ts_ns;
    }

    std::vector<FlowEntry> expire_inactive(uint64_t now_ns) {
        std::vector<FlowEntry> expired;
        for (auto it = flows_.begin(); it != flows_.end(); ) {
            if (now_ns > it->second.stats.last_seen_ns &&
                now_ns - it->second.stats.last_seen_ns >= inactive_timeout_ns_) {
                expired.push_back(it->second);
                it = flows_.erase(it);
            } else {
                ++it;
            }
        }
        return expired;
    }

    size_t flow_count() const noexcept {
        return flows_.size();
    }

private:
    uint64_t inactive_timeout_ns_;
    std::unordered_map<FlowKey, FlowEntry, FlowKeyHash> flows_;
};

static std::string ip_to_string(uint32_t ip_host_order) {
    in_addr addr{};
    addr.s_addr = htonl(ip_host_order);
    char buf[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &addr, buf, sizeof(buf));
    return std::string(buf);
}

static void print_flow(const FlowEntry& f) {
    std::cout << ip_to_string(f.key.src_ip) << ":" << f.key.src_port
              << " -> "
              << ip_to_string(f.key.dst_ip) << ":" << f.key.dst_port
              << " proto=" << static_cast<int>(f.key.protocol)
              << " packets=" << f.stats.packets
              << " bytes=" << f.stats.bytes
              << " first_ns=" << f.stats.first_seen_ns
              << " last_ns=" << f.stats.last_seen_ns
              << "\n";
}

// Example usage stub
int main() {
    FlowAnalyzer analyzer;

    // In a real system, packets would come from AF_PACKET/DPDK/eBPF/etc.
    // Here we just demonstrate the API.
    std::vector<uint8_t> fake_packet(64, 0);

    // You would fill fake_packet with a real Ethernet+IPv4+TCP/UDP frame.
    // analyzer.process_packet(fake_packet.data(), fake_packet.size(), timestamp_ns);

    auto expired = analyzer.expire_inactive(
        std::chrono::duration_cast<std::chrono::nanoseconds>(
            std::chrono::steady_clock::now().time_since_epoch()).count());

    for (const auto& flow : expired) {
        print_flow(flow);
    }

    std::cout << "Active flows: " << analyzer.flow_count() << "\n";
    return 0;
}
```

