### `main.go`

```go
package main

import (
	"encoding/binary"
	"fmt"
	"net"
	"sync"
	"sync/atomic"
	"time"
)

// -----------------------------
// Packet / Flow definitions
// -----------------------------

type FlowKey struct {
	SrcIP   [16]byte
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	IPVer   uint8 // 4 or 6
	_       uint16
}

type FlowStats struct {
	Packets      uint64
	Bytes        uint64
	FirstSeenNS  int64
	LastSeenNS   int64
	MinPktSize   uint32
	MaxPktSize   uint32
	TCPFlags     uint8
	_            [7]byte
}

type FlowEntry struct {
	Key   FlowKey
	Stats FlowStats
}

// -----------------------------
// Sharded flow table
// -----------------------------

const (
	numShards = 256
)

type shard struct {
	mu    sync.RWMutex
	flows map[FlowKey]*FlowEntry
}

type FlowTable struct {
	shards [numShards]shard
}

func NewFlowTable() *FlowTable {
	ft := &FlowTable{}
	for i := range ft.shards {
		ft.shards[i].flows = make(map[FlowKey]*FlowEntry, 1024)
	}
	return ft
}

func (ft *FlowTable) getShard(key *FlowKey) *shard {
	// Fast, simple hash from key bytes.
	// For production, replace with a stronger/faster hash if needed.
	h := uint32(key.Proto) ^ uint32(key.IPVer)
	h ^= uint32(key.SrcPort) << 1
	h ^= uint32(key.DstPort) << 2
	for i := 0; i < 16; i++ {
		h = h*16777619 ^ uint32(key.SrcIP[i])
		h = h*16777619 ^ uint32(key.DstIP[i])
	}
	return &ft.shards[h%numShards]
}

func (ft *FlowTable) Update(key FlowKey, pktLen uint32, nowNS int64, tcpFlags uint8) {
	s := ft.getShard(&key)
	s.mu.Lock()
	defer s.mu.Unlock()

	entry, ok := s.flows[key]
	if !ok {
		entry = &FlowEntry{
			Key: key,
			Stats: FlowStats{
				Packets:     0,
				Bytes:       0,
				FirstSeenNS: nowNS,
				LastSeenNS:  nowNS,
				MinPktSize:  pktLen,
				MaxPktSize:  pktLen,
				TCPFlags:    tcpFlags,
			},
		}
		s.flows[key] = entry
	}

	entry.Stats.Packets++
	entry.Stats.Bytes += uint64(pktLen)
	entry.Stats.LastSeenNS = nowNS
	if pktLen < entry.Stats.MinPktSize {
		entry.Stats.MinPktSize = pktLen
	}
	if pktLen > entry.Stats.MaxPktSize {
		entry.Stats.MaxPktSize = pktLen
	}
	entry.Stats.TCPFlags |= tcpFlags
}

func (ft *FlowTable) ExpireOlderThan(cutoffNS int64) []FlowEntry {
	expired := make([]FlowEntry, 0, 1024)

	for i := range ft.shards {
		s := &ft.shards[i]
		s.mu.Lock()
		for k, v := range s.flows {
			if v.Stats.LastSeenNS < cutoffNS {
				expired = append(expired, *v)
				delete(s.flows, k)
			}
		}
		s.mu.Unlock()
	}

	return expired
}

func (ft *FlowTable) Snapshot() []FlowEntry {
	out := make([]FlowEntry, 0, 1024)
	for i := range ft.shards {
		s := &ft.shards[i]
		s.mu.RLock()
		for _, v := range s.flows {
			out = append(out, *v)
		}
		s.mu.RUnlock()
	}
	return out
}

// -----------------------------
// Packet parsing
// -----------------------------

type PacketParser struct{}

func (p *PacketParser) ParseEthernet(frame []byte) (ethertype uint16, payload []byte, ok bool) {
	if len(frame) < 14 {
		return 0, nil, false
	}
	ethertype = binary.BigEndian.Uint16(frame[12:14])
	return ethertype, frame[14:], true
}

func (p *PacketParser) ParseIPv4(pkt []byte) (src, dst [16]byte, proto uint8, payload []byte, ok bool) {
	if len(pkt) < 20 {
		return src, dst, 0, nil, false
	}
	ihl := int(pkt[0]&0x0F) * 4
	if ihl < 20 || len(pkt) < ihl {
		return src, dst, 0, nil, false
	}
	proto = pkt[9]
	copy(src[12:], pkt[12:16])
	copy(dst[12:], pkt[16:20])
	return src, dst, proto, pkt[ihl:], true
}

func (p *PacketParser) ParseIPv6(pkt []byte) (src, dst [16]byte, proto uint8, payload []byte, ok bool) {
	if len(pkt) < 40 {
		return src, dst, 0, nil, false
	}
	proto = pkt[6]
	copy(src[:], pkt[8:24])
	copy(dst[:], pkt[24:40])
	return src, dst, proto, pkt[40:], true
}

func (p *PacketParser) ParseL4(proto uint8, pkt []byte) (srcPort, dstPort uint16, tcpFlags uint8, ok bool) {
	switch proto {
	case 6: // TCP
		if len(pkt) < 20 {
			return 0, 0, 0, false
		}
		srcPort = binary.BigEndian.Uint16(pkt[0:2])
		dstPort = binary.BigEndian.Uint16(pkt[2:4])
		tcpFlags = pkt[13]
		return srcPort, dstPort, tcpFlags, true
	case 17: // UDP
		if len(pkt) < 8 {
			return 0, 0, 0, false
		}
		srcPort = binary.BigEndian.Uint16(pkt[0:2])
		dstPort = binary.BigEndian.Uint16(pkt[2:4])
		return srcPort, dstPort, 0, true
	default:
		return 0, 0, 0, false
	}
}

// -----------------------------
// Analyzer
// -----------------------------

type Analyzer struct {
	table  *FlowTable
	parser PacketParser

	packetsIn  uint64
	packetsBad uint64
}

func NewAnalyzer() *Analyzer {
	return &Analyzer{
		table: NewFlowTable(),
	}
}

func (a *Analyzer) ProcessFrame(frame []byte) {
	atomic.AddUint64(&a.packetsIn, 1)

	ethertype, payload, ok := a.parser.ParseEthernet(frame)
	if !ok {
		atomic.AddUint64(&a.packetsBad, 1)
		return
	}

	var src, dst [16]byte
	var proto uint8

	switch ethertype {
	case 0x0800: // IPv4
		src, dst, proto, payload, ok = a.parser.ParseIPv4(payload)
	case 0x86DD: // IPv6
		src, dst, proto, payload, ok = a.parser.ParseIPv6(payload)
	default:
		atomic.AddUint64(&a.packetsBad, 1)
		return
	}
	if !ok {
		atomic.AddUint64(&a.packetsBad, 1)
		return
	}

	srcPort, dstPort, tcpFlags, ok := a.parser.ParseL4(proto, payload)
	if !ok {
		atomic.AddUint64(&a.packetsBad, 1)
		return
	}

	nowNS := time.Now().UnixNano()
	key := FlowKey{
		SrcIP:   src,
		DstIP:   dst,
		SrcPort: srcPort,
		DstPort: dstPort,
		Proto:   proto,
		IPVer:   map[bool]uint8{true: 4, false: 6}[ethertype == 0x0800],
	}

	a.table.Update(key, uint32(len(frame)), nowNS, tcpFlags)
}

func (a *Analyzer) StartExpiryLoop(ttl time.Duration, interval time.Duration, stop <-chan struct{}) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			cutoff := time.Now().Add(-ttl).UnixNano()
			expired := a.table.ExpireOlderThan(cutoff)
			if len(expired) > 0 {
				fmt.Printf("expired %d flows\n", len(expired))
			}
		case <-stop:
			return
		}
	}
}

// -----------------------------
// Demo / test harness
// -----------------------------

func makeIPv4TCPFrame(srcIP, dstIP net.IP, srcPort, dstPort uint16) []byte {
	frame := make([]byte, 14+20+20)
	// Ethernet header
	binary.BigEndian.PutUint16(frame[12:14], 0x0800)

	ip := frame[14:]
	ip[0] = 0x45
	ip[9] = 6
	copy(ip[12:16], srcIP.To4())
	copy(ip[16:20], dstIP.To4())

	tcp := frame[14+20:]
	binary.BigEndian.PutUint16(tcp[0:2], srcPort)
	binary.BigEndian.PutUint16(tcp[2:4], dstPort)
	tcp[13] = 0x18 // PSH+ACK
	return frame
}

func main() {
	analyzer := NewAnalyzer()
	stop := make(chan struct{})

	go analyzer.StartExpiryLoop(30*time.Second, 5*time.Second, stop)

	// Simulated traffic
	for i := 0; i < 100000; i++ {
		frame := makeIPv4TCPFrame(
			net.IPv4(10, 0, 0, byte(i%255)),
			net.IPv4(192, 168, 1, byte((i/255)%255)),
			uint16(10000+i%1000),
			443,
		)
		analyzer.ProcessFrame(frame)
	}

	close(stop)

	snapshot := analyzer.table.Snapshot()
	fmt.Printf("flows=%d packets=%d bad=%d\n",
		len(snapshot),
		atomic.LoadUint64(&analyzer.packetsIn),
		atomic.LoadUint64(&analyzer.packetsBad),
	)
}
```

