```cpp
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>

#include <atomic>
#include <array>
#include <chrono>
#include <cstdint>
#include <cstring>
#include <functional>
#include <iostream>
#include <mutex>
#include <shared_mutex>
#include <thread>
#include <unordered_map>
#include <vector>

using Clock = std::chrono::steady_clock;
using TimePoint = Clock::time_point;

static inline uint64_t now_ns() {
    return std::chrono::duration_cast<std::chrono::nanoseconds>(
               Clock::now().time_since_epoch())
        .count();
}

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const noexcept {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast-ish hash combine
        uint64_t x = 0xcbf29ce484222325ULL;
        auto mix = [&](uint64_t v) {
            x ^= v;
            x *= 0x100000001b3ULL;
        };
        mix(k.src_ip);
        mix(k.dst_ip);
        mix((uint64_t(k.src_port) << 16) | k.dst_port);
        mix(k.proto);
        return static_cast<size_t>(x);
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;

    void update(uint32_t len, uint64_t ts_ns) {
        if (packets == 0) {
            first_seen_ns = ts_ns;
        }
        last_seen_ns = ts_ns;
        ++packets;
        bytes += len;
    }
};

struct PacketView {
    const uint8_t* data;
    size_t len;
    uint64_t ts_ns;
};

class FlowShard {
public:
    explicit FlowShard(size_t capacity_hint = 1 << 16)
        : table_(capacity_hint) {}

    void add_packet(const FlowKey& key, uint32_t len, uint64_t ts_ns) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = table_.find(key);
        if (it == table_.end()) {
            FlowStats stats;
            stats.update(len, ts_ns);
            table_.emplace(key, stats);
        } else {
            it->second.update(len, ts_ns);
        }
    }

    template <typename Fn>
    void expire_inactive(uint64_t cutoff_ns, Fn&& on_expire) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto it = table_.begin(); it != table_.end();) {
            if (it->second.last_seen_ns < cutoff_ns) {
                on_expire(it->first, it->second);
                it = table_.erase(it);
            } else {
                ++it;
            }
        }
    }

    template <typename Fn>
    void snapshot(Fn&& fn) {
        std::lock_guard<std::mutex> lock(mutex_);
        for (const auto& kv : table_) {
            fn(kv.first, kv.second);
        }
    }

private:
    std::mutex mutex_;
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> table_;
};

class FlowAnalyzer {
public:
    static constexpr size_t kNumShards = 64;

    FlowAnalyzer()
        : shards_() {}

    void process_packet(const PacketView& pkt) {
        FlowKey key{};
        if (!parse_flow_key(pkt.data, pkt.len, key)) {
            return;
        }

        const size_t shard_idx = FlowKeyHash{}(key) & (kNumShards - 1);
        shards_[shard_idx].add_packet(key, static_cast<uint32_t>(pkt.len), pkt.ts_ns);
    }

    void expire_flows(uint64_t inactive_timeout_ns) {
        const uint64_t cutoff = now_ns() - inactive_timeout_ns;
        for (auto& shard : shards_) {
            shard.expire_inactive(cutoff, [](const FlowKey&, const FlowStats&) {
                // Hook for export/logging/metrics
            });
        }
    }

    void dump_all() {
        for (auto& shard : shards_) {
            shard.snapshot([](const FlowKey& k, const FlowStats& s) {
                std::cout
                    << ip_to_string(k.src_ip) << ":" << ntohs(k.src_port)
                    << " -> "
                    << ip_to_string(k.dst_ip) << ":" << ntohs(k.dst_port)
                    << " proto=" << unsigned(k.proto)
                    << " packets=" << s.packets
                    << " bytes=" << s.bytes
                    << " first_ns=" << s.first_seen_ns
                    << " last_ns=" << s.last_seen_ns
                    << "\n";
            });
        }
    }

private:
    std::array<FlowShard, kNumShards> shards_;

    static bool parse_flow_key(const uint8_t* data, size_t len, FlowKey& out) {
        if (len < sizeof(iphdr)) return false;

        const iphdr* ip = reinterpret_cast<const iphdr*>(data);
        if (ip->version != 4) return false;

        const size_t ip_hdr_len = ip->ihl * 4;
        if (ip_hdr_len < sizeof(iphdr) || len < ip_hdr_len) return false;

        out.src_ip = ip->saddr;
        out.dst_ip = ip->daddr;
        out.proto = ip->protocol;

        const uint8_t* l4 = data + ip_hdr_len;
        const size_t l4_len = len - ip_hdr_len;

        if (ip->protocol == IPPROTO_TCP) {
            if (l4_len < sizeof(tcphdr)) return false;
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(l4);
            out.src_port = tcp->source;
            out.dst_port = tcp->dest;
            return true;
        } else if (ip->protocol == IPPROTO_UDP) {
            if (l4_len < sizeof(udphdr)) return false;
            const udphdr* udp = reinterpret_cast<const udphdr*>(l4);
            out.src_port = udp->source;
            out.dst_port = udp->dest;
            return true;
        }

        // For non-TCP/UDP, use zero ports
        out.src_port = 0;
        out.dst_port = 0;
        return true;
    }

    static std::string ip_to_string(uint32_t ip_be) {
        char buf[INET_ADDRSTRLEN];
        in_addr addr{};
        addr.s_addr = ip_be;
        const char* res = inet_ntop(AF_INET, &addr, buf, sizeof(buf));
        return res ? std::string(res) : std::string("0.0.0.0");
    }
};

// Example packet source stub
class PacketSource {
public:
    virtual ~PacketSource() = default;
    virtual bool next(PacketView& out) = 0;
};

// Dummy source for testing
class SyntheticPacketSource : public PacketSource {
public:
    bool next(PacketView& out) override {
        return false; // no packets
    }
};

int main() {
    FlowAnalyzer analyzer;
    SyntheticPacketSource source;

    PacketView pkt{};
    while (source.next(pkt)) {
        analyzer.process_packet(pkt);
    }

    analyzer.expire_flows(30ULL * 1000 * 1000 * 1000); // 30s
    analyzer.dump_all();

    return 0;
}
