## Initial implementation

### `main.go`

```go
package main

import (
	"encoding/binary"
	"fmt"
	"net"
	"os"
	"os/signal"
	"sync"
	"sync/atomic"
	"syscall"
	"time"
)

const (
	numShards      = 256
	flowIdleTimeout = 30 * time.Second
	sweepInterval   = 5 * time.Second
	maxPacketSize   = 65535
)

type FlowKey struct {
	SrcIP   [16]byte
	DstIP   [16]byte
	SrcPort uint16
	DstPort uint16
	Proto   uint8
	IPVer   uint8
}

type FlowEntry struct {
	Key        FlowKey
	Packets    uint64
	Bytes      uint64
	FirstSeen  int64
	LastSeen   int64
	Expired    uint32
}

type shard struct {
	mu    sync.RWMutex
	flows map[FlowKey]*FlowEntry
}

type FlowTable struct {
	shards [numShards]shard
}

func NewFlowTable() *FlowTable {
	ft := &FlowTable{}
	for i := range ft.shards {
		ft.shards[i].flows = make(map[FlowKey]*FlowEntry, 1024)
	}
	return ft
}

func (ft *FlowTable) shardFor(key FlowKey) *shard {
	h := fnv64(key)
	return &ft.shards[h%numShards]
}

func (ft *FlowTable) Update(key FlowKey, pktLen int, ts int64) {
	s := ft.shardFor(key)

	// Fast path: read lock lookup
	s.mu.RLock()
	entry := s.flows[key]
	s.mu.RUnlock()

	if entry != nil {
		atomic.AddUint64(&entry.Packets, 1)
		atomic.AddUint64(&entry.Bytes, uint64(pktLen))
		atomic.StoreInt64(&entry.LastSeen, ts)
		return
	}

	// Slow path: create entry
	s.mu.Lock()
	entry = s.flows[key]
	if entry == nil {
		entry = &FlowEntry{
			Key:       key,
			Packets:   1,
			Bytes:     uint64(pktLen),
			FirstSeen: ts,
			LastSeen:  ts,
		}
		s.flows[key] = entry
	} else {
		atomic.AddUint64(&entry.Packets, 1)
		atomic.AddUint64(&entry.Bytes, uint64(pktLen))
		atomic.StoreInt64(&entry.LastSeen, ts)
	}
	s.mu.Unlock()
}

func (ft *FlowTable) Sweep(now int64, idleTimeout time.Duration, export func(*FlowEntry)) {
	cutoff := now - int64(idleTimeout)
	for i := range ft.shards {
		s := &ft.shards[i]
		s.mu.Lock()
		for k, e := range s.flows {
			last := atomic.LoadInt64(&e.LastSeen)
			if last < cutoff {
				if atomic.CompareAndSwapUint32(&e.Expired, 0, 1) {
					export(e)
				}
				delete(s.flows, k)
			}
		}
		s.mu.Unlock()
	}
}

func fnv64(key FlowKey) uint64 {
	const (
		offset64 = 1469598103934665603
		prime64  = 1099511628211
	)
	var h uint64 = offset64

	for _, b := range key.SrcIP {
		h ^= uint64(b)
		h *= prime64
	}
	for _, b := range key.DstIP {
		h ^= uint64(b)
		h *= prime64
	}

	h ^= uint64(key.SrcPort)
	h *= prime64
	h ^= uint64(key.DstPort)
	h *= prime64
	h ^= uint64(key.Proto)
	h *= prime64
	h ^= uint64(key.IPVer)
	h *= prime64

	return h
}

func parsePacket(pkt []byte) (FlowKey, int, bool) {
	// Minimal Ethernet parsing
	if len(pkt) < 14 {
		return FlowKey{}, 0, false
	}
	ethType := binary.BigEndian.Uint16(pkt[12:14])
	offset := 14

	var key FlowKey
	key.IPVer = 0

	switch ethType {
	case 0x0800: // IPv4
		if len(pkt) < offset+20 {
			return FlowKey{}, 0, false
		}
		ihl := int(pkt[offset]&0x0F) * 4
		if ihl < 20 || len(pkt) < offset+ihl {
			return FlowKey{}, 0, false
		}
		key.IPVer = 4
		key.Proto = pkt[offset+9]
		copy(key.SrcIP[:4], pkt[offset+12:offset+16])
		copy(key.DstIP[:4], pkt[offset+16:offset+20])

		l4 := offset + ihl
		switch key.Proto {
		case 6, 17: // TCP/UDP
			if len(pkt) < l4+4 {
				return FlowKey{}, 0, false
			}
			key.SrcPort = binary.BigEndian.Uint16(pkt[l4 : l4+2])
			key.DstPort = binary.BigEndian.Uint16(pkt[l4+2 : l4+4])
		default:
			// Non-TCP/UDP flows still tracked by IP proto only
		}
		return key, len(pkt), true

	case 0x86DD: // IPv6
		if len(pkt) < offset+40 {
			return FlowKey{}, 0, false
		}
		key.IPVer = 6
		key.Proto = pkt[offset+6]
		copy(key.SrcIP[:16], pkt[offset+8:offset+24])
		copy(key.DstIP[:16], pkt[offset+24:offset+40])

		l4 := offset + 40
		switch key.Proto {
		case 6, 17:
			if len(pkt) < l4+4 {
				return FlowKey{}, 0, false
			}
			key.SrcPort = binary.BigEndian.Uint16(pkt[l4 : l4+2])
			key.DstPort = binary.BigEndian.Uint16(pkt[l4+2 : l4+4])
		}
		return key, len(pkt), true
	default:
		return FlowKey{}, 0, false
	}
}

type Analyzer struct {
	table   *FlowTable
	packets chan []byte
	stop    chan struct{}
	wg      sync.WaitGroup
}

func NewAnalyzer(queueSize int) *Analyzer {
	return &Analyzer{
		table:   NewFlowTable(),
		packets: make(chan []byte, queueSize),
		stop:    make(chan struct{}),
	}
}

func (a *Analyzer) Start(workers int) {
	for i := 0; i < workers; i++ {
		a.wg.Add(1)
		go func() {
			defer a.wg.Done()
			for {
				select {
				case pkt := <-a.packets:
					key, pktLen, ok := parsePacket(pkt)
					if ok {
						a.table.Update(key, pktLen, time.Now().UnixNano())
					}
				case <-a.stop:
					return
				}
			}
		}()
	}

	a.wg.Add(1)
	go func() {
		defer a.wg.Done()
		ticker := time.NewTicker(sweepInterval)
		defer ticker.Stop()
		for {
			select {
			case <-ticker.C:
				now := time.Now().UnixNano()
				a.table.Sweep(now, flowIdleTimeout, func(e *FlowEntry) {
					fmt.Printf("EXPIRE flow=%+v packets=%d bytes=%d first=%d last=%d\n",
						e.Key, atomic.LoadUint64(&e.Packets), atomic.LoadUint64(&e.Bytes),
						atomic.LoadInt64(&e.FirstSeen), atomic.LoadInt64(&e.LastSeen))
				})
			case <-a.stop:
				return
			}
		}
	}()
}

func (a *Analyzer) Stop() {
	close(a.stop)
	a.wg.Wait()
}

func (a *Analyzer) Submit(pkt []byte) {
	// In production, avoid copying unless ownership is unclear.
	select {
	case a.packets <- pkt:
	default:
		// Drop under backpressure to preserve latency
	}
}

func main() {
	analyzer := NewAnalyzer(1 << 16)
	analyzer.Start(4)

	// Example: graceful shutdown
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGINT, syscall.SIGTERM)

	fmt.Println("Analyzer running. Press Ctrl+C to stop.")
	<-sigCh

	analyzer.Stop()
	fmt.Println("Stopped.")
}
```

