```rust
use ahash::RandomState;
use crossbeam_channel::{bounded, Receiver, Sender};
use hashbrown::HashMap;
use serde::Serialize;
use std::cmp::Ordering;
use std::net::{Ipv4Addr, Ipv6Addr};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
enum IpAddrKind {
    V4([u8; 4]),
    V6([u8; 16]),
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
struct FlowKey {
    src_ip: IpAddrKind,
    dst_ip: IpAddrKind,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
}

impl FlowKey {
    fn normalized(
        src_ip: IpAddrKind,
        dst_ip: IpAddrKind,
        src_port: u16,
        dst_port: u16,
        protocol: u8,
    ) -> Self {
        // Canonicalize bidirectional flows so A->B and B->A map to same entry.
        // Ordering is based on tuple comparison.
        let left = (src_ip, src_port);
        let right = (dst_ip, dst_port);

        match compare_endpoint(left, right) {
            Ordering::Less | Ordering::Equal => Self {
                src_ip,
                dst_ip,
                src_port,
                dst_port,
                protocol,
            },
            Ordering::Greater => Self {
                src_ip: dst_ip,
                dst_ip: src_ip,
                src_port: dst_port,
                dst_port: src_port,
                protocol,
            },
        }
    }
}

fn compare_endpoint(a: (IpAddrKind, u16), b: (IpAddrKind, u16)) -> Ordering {
    match compare_ip(a.0, b.0) {
        Ordering::Equal => a.1.cmp(&b.1),
        other => other,
    }
}

fn compare_ip(a: IpAddrKind, b: IpAddrKind) -> Ordering {
    match (a, b) {
        (IpAddrKind::V4(a4), IpAddrKind::V4(b4)) => a4.cmp(&b4),
        (IpAddrKind::V6(a6), IpAddrKind::V6(b6)) => a6.cmp(&b6),
        (IpAddrKind::V4(_), IpAddrKind::V6(_)) => Ordering::Less,
        (IpAddrKind::V6(_), IpAddrKind::V4(_)) => Ordering::Greater,
    }
}

#[derive(Debug, Clone)]
struct PacketMeta {
    ts: Instant,
    src_ip: IpAddrKind,
    dst_ip: IpAddrKind,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
    bytes: usize,
    packets: u64,
}

#[derive(Debug, Default, Serialize)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen_ms: u128,
    last_seen_ms: u128,
}

#[derive(Debug)]
struct FlowEntry {
    stats: FlowStats,
    last_seen: Instant,
}

#[derive(Debug, Serialize)]
struct ExportedFlow {
    src_ip: String,
    dst_ip: String,
    src_port: u16,
    dst_port: u16,
    protocol: u8,
    packets: u64,
    bytes: u64,
    first_seen_ms: u128,
    last_seen_ms: u128,
}

struct FlowTable {
    map: HashMap<FlowKey, FlowEntry, RandomState>,
    idle_timeout: Duration,
    start: Instant,
}

impl FlowTable {
    fn new(idle_timeout: Duration) -> Self {
        Self {
            map: HashMap::with_hasher(RandomState::new()),
            idle_timeout,
            start: Instant::now(),
        }
    }

    fn ingest(&mut self, pkt: PacketMeta) {
        let key = FlowKey::normalized(pkt.src_ip, pkt.dst_ip, pkt.src_port, pkt.dst_port, pkt.protocol);
        let now = pkt.ts;
        let elapsed_ms = now.duration_since(self.start).as_millis();

        let entry = self.map.entry(key).or_insert_with(|| FlowEntry {
            stats: FlowStats {
                packets: 0,
                bytes: 0,
                first_seen_ms: elapsed_ms,
                last_seen_ms: elapsed_ms,
            },
            last_seen: now,
        });

        entry.stats.packets += pkt.packets;
        entry.stats.bytes += pkt.bytes as u64;
        entry.stats.last_seen_ms = elapsed_ms;
        entry.last_seen = now;
    }

    fn expire(&mut self) -> Vec<ExportedFlow> {
        let now = Instant::now();
        let mut expired = Vec::new();

        self.map.retain(|key, entry| {
            let idle = now.duration_since(entry.last_seen);
            if idle >= self.idle_timeout {
                expired.push(self.export_flow(*key, entry));
                false
            } else {
                true
            }
        });

        expired
    }

    fn export_flow(&self, key: FlowKey, entry: &FlowEntry) -> ExportedFlow {
        ExportedFlow {
            src_ip: ip_to_string(key.src_ip),
            dst_ip: ip_to_string(key.dst_ip),
            src_port: key.src_port,
            dst_port: key.dst_port,
            protocol: key.protocol,
            packets: entry.stats.packets,
            bytes: entry.stats.bytes,
            first_seen_ms: entry.stats.first_seen_ms,
            last_seen_ms: entry.stats.last_seen_ms,
        }
    }
}

fn ip_to_string(ip: IpAddrKind) -> String {
    match ip {
        IpAddrKind::V4(v4) => Ipv4Addr::from(v4).to_string(),
        IpAddrKind::V6(v6) => Ipv6Addr::from(v6).to_string(),
    }
}

fn packet_ingest_loop(rx: Receiver<PacketMeta>, table: Arc<Mutex<FlowTable>>) {
    while let Ok(pkt) = rx.recv() {
        let mut guard = table.lock().unwrap();
        guard.ingest(pkt);
    }
}

fn expiration_loop(table: Arc<Mutex<FlowTable>>, export_tx: Sender<ExportedFlow>, interval: Duration) {
    loop {
        thread::sleep(interval);

        let expired = {
            let mut guard = table.lock().unwrap();
            guard.expire()
        };

        for flow in expired {
            let _ = export_tx.send(flow);
        }
    }
}

fn exporter_loop(rx: Receiver<ExportedFlow>) {
    while let Ok(flow) = rx.recv() {
        match serde_json::to_string(&flow) {
            Ok(json) => println!("{}", json),
            Err(e) => eprintln!("export error: {}", e),
        }
    }
}

fn main() {
    let table = Arc::new(Mutex::new(FlowTable::new(Duration::from_secs(30))));
    let (pkt_tx, pkt_rx) = bounded::<PacketMeta>(100_000);
    let (export_tx, export_rx) = bounded::<ExportedFlow>(100_000);

    {
        let table = Arc::clone(&table);
        thread::spawn(move || packet_ingest_loop(pkt_rx, table));
    }

    {
        let table = Arc::clone(&table);
        let export_tx = export_tx.clone();
        thread::spawn(move || expiration_loop(table, export_tx, Duration::from_secs(5)));
    }

    thread::spawn(move || exporter_loop(export_rx));

    // Demo traffic generator
    generate_demo_traffic(pkt_tx);
}

fn generate_demo_traffic(tx: Sender<PacketMeta>) {
    let start = Instant::now();

    for i in 0..1_000_000u64 {
        let pkt = PacketMeta {
            ts: Instant::now(),
            src_ip: IpAddrKind::V4([10, 0, 0, (i % 255) as u8]),
            dst_ip: IpAddrKind::V4([192, 168, 1, ((i / 255) % 255) as u8]),
            src_port: 10_000 + (i % 1000) as u16,
            dst_port: 80,
            protocol: 6,
            bytes: 1500,
            packets: 1,
        };

        if tx.send(pkt).is_err() {
            break;
        }
    }

    println!("generated traffic in {:?}", start.elapsed());
}
