## 2) Minimal C++ implementation

```cpp
// flow_analyser.cpp
#include <atomic>
#include <cstdint>
#include <cstring>
#include <iostream>
#include <vector>
#include <thread>
#include <chrono>
#include <array>

#if defined(__GNUC__) || defined(__clang__)
#define likely(x)   __builtin_expect(!!(x), 1)
#define unlikely(x) __builtin_expect(!!(x), 0)
#else
#define likely(x) (x)
#define unlikely(x) (x)
#endif

// -----------------------------
// Packet metadata
// -----------------------------
struct PacketView {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
    uint32_t bytes;
    uint64_t timestamp_ns;
};

// -----------------------------
// Flow key / value
// -----------------------------
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  protocol;
    uint8_t  pad[3]; // align to 16 bytes
};

struct FlowValue {
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ts;
    uint64_t last_ts;
};

// -----------------------------
// Hashing
// -----------------------------
static inline uint64_t mix64(uint64_t x) {
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline uint64_t hash_flow_key(const FlowKey& k) {
    uint64_t a = (uint64_t(k.src_ip) << 32) ^ k.dst_ip;
    uint64_t b = (uint64_t(k.src_port) << 48) ^ (uint64_t(k.dst_port) << 32) ^ k.protocol;
    return mix64(a ^ mix64(b));
}

static inline bool key_equals(const FlowKey& a, const FlowKey& b) {
    return std::memcmp(&a, &b, sizeof(FlowKey)) == 0;
}

// -----------------------------
// Fixed-size open addressing table
// -----------------------------
class FlowTable {
public:
    explicit FlowTable(size_t capacity_pow2)
        : capacity_(capacity_pow2),
          mask_(capacity_pow2 - 1),
          keys_(capacity_pow2),
          values_(capacity_pow2),
          occupied_(capacity_pow2) {
        if ((capacity_pow2 & (capacity_pow2 - 1)) != 0) {
            throw std::runtime_error("capacity must be power of two");
        }
        for (auto& f : occupied_) f.store(false, std::memory_order_relaxed);
    }

    void update(const PacketView& p) {
        FlowKey key{p.src_ip, p.dst_ip, p.src_port, p.dst_port, p.protocol, {0,0,0}};
        uint64_t h = hash_flow_key(key);
        size_t idx = size_t(h) & mask_;

        // Linear probing
        for (size_t probe = 0; probe < capacity_; ++probe) {
            bool expected = false;
            if (occupied_[idx].load(std::memory_order_acquire)) {
                if (key_equals(keys_[idx], key)) {
                    auto& v = values_[idx];
                    v.packets++;
                    v.bytes += p.bytes;
                    if (p.timestamp_ns < v.first_ts) v.first_ts = p.timestamp_ns;
                    if (p.timestamp_ns > v.last_ts)  v.last_ts = p.timestamp_ns;
                    return;
                }
            } else {
                // Try to claim slot
                if (occupied_[idx].compare_exchange_strong(expected, true,
                                                           std::memory_order_acq_rel)) {
                    keys_[idx] = key;
                    values_[idx] = FlowValue{1, p.bytes, p.timestamp_ns, p.timestamp_ns};
                    return;
                }
            }
            idx = (idx + 1) & mask_;
        }

        // Table full: drop or count overflow
        overflow_.fetch_add(1, std::memory_order_relaxed);
    }

    uint64_t overflow_count() const {
        return overflow_.load(std::memory_order_relaxed);
    }

    void dump_top(std::ostream& os, size_t limit = 20) const {
        size_t printed = 0;
        for (size_t i = 0; i < capacity_ && printed < limit; ++i) {
            if (occupied_[i].load(std::memory_order_relaxed)) {
                const auto& k = keys_[i];
                const auto& v = values_[i];
                os << "flow "
                   << k.src_ip << ":" << k.src_port
                   << " -> " << k.dst_ip << ":" << k.dst_port
                   << " proto=" << unsigned(k.protocol)
                   << " packets=" << v.packets
                   << " bytes=" << v.bytes
                   << " first=" << v.first_ts
                   << " last=" << v.last_ts
                   << "\n";
                ++printed;
            }
        }
    }

private:
    size_t capacity_;
    size_t mask_;
    std::vector<FlowKey> keys_;
    std::vector<FlowValue> values_;
    std::vector<std::atomic<bool>> occupied_;
    std::atomic<uint64_t> overflow_{0};
};

// -----------------------------
// Sharded analyser
// -----------------------------
class FlowAnalyser {
public:
    FlowAnalyser(size_t shards, size_t table_capacity_pow2)
        : shards_(shards) {
        tables_.reserve(shards_);
        for (size_t i = 0; i < shards_; ++i) {
            tables_.emplace_back(table_capacity_pow2);
        }
    }

    void process(const PacketView& p) {
        // Simple shard by src_ip; can use RSS hash in real deployments
        size_t shard = hash_flow_key(FlowKey{p.src_ip, p.dst_ip, p.src_port, p.dst_port, p.protocol, {0,0,0}}) % shards_;
        tables_[shard].update(p);
    }

    void dump(std::ostream& os) const {
        for (size_t i = 0; i < shards_; ++i) {
            os << "=== shard " << i << " ===\n";
            tables_[i].dump_top(os);
            os << "overflow=" << tables_[i].overflow_count() << "\n";
        }
    }

private:
    size_t shards_;
    std::vector<FlowTable> tables_;
};

// -----------------------------
// Demo / test harness
// -----------------------------
static PacketView make_packet(uint32_t s, uint32_t d, uint16_t sp, uint16_t dp, uint8_t proto, uint32_t bytes, uint64_t ts) {
    return PacketView{s, d, sp, dp, proto, bytes, ts};
}

int main() {
    constexpr size_t shards = 4;
    constexpr size_t table_size = 1 << 20; // 1,048,576 entries per shard

    FlowAnalyser analyser(shards, table_size);

    // Simulated traffic
    for (uint64_t i = 0; i < 5'000'000; ++i) {
        uint32_t src = 0x0A000001 + (i % 10000); // 10.0.0.1+
        uint32_t dst = 0x0A0000FF;
        uint16_t sp = uint16_t(10000 + (i % 2000));
        uint16_t dp = 443;
        uint8_t proto = 6; // TCP
        uint32_t bytes = 64 + (i % 1400);
        uint64_t ts = i * 1000;

        analyser.process(make_packet(src, dst, sp, dp, proto, bytes, ts));
    }

    analyser.dump(std::cout);
    return 0;
}
```

