# Code: `flow_analyser.cpp`

```cpp
#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <unordered_map>
#include <string>
#include <iostream>
#include <chrono>
#include <thread>
#include <mutex>

#pragma pack(push, 1)
struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_ts_us = 0;
    uint64_t last_ts_us = 0;
};
#pragma pack(pop)

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Fast-ish hash combine
        size_t h = 1469598103934665603ULL;
        auto mix = [&](uint64_t v) {
            h ^= v;
            h *= 1099511628211ULL;
        };
        mix(k.src_ip);
        mix(k.dst_ip);
        mix(k.src_port);
        mix(k.dst_port);
        mix(k.proto);
        return h;
    }
};

static inline uint64_t ts_to_us(const timeval& tv) {
    return static_cast<uint64_t>(tv.tv_sec) * 1000000ULL + static_cast<uint64_t>(tv.tv_usec);
}

class FlowAnalyser {
public:
    void process_packet(const pcap_pkthdr* header, const uint8_t* packet) {
        if (header->caplen < sizeof(ether_header)) return;

        const ether_header* eth = reinterpret_cast<const ether_header*>(packet);
        uint16_t eth_type = ntohs(eth->ether_type);
        if (eth_type != ETHERTYPE_IP) return;

        const uint8_t* ip_ptr = packet + sizeof(ether_header);
        size_t ip_avail = header->caplen - sizeof(ether_header);
        if (ip_avail < sizeof(iphdr)) return;

        const iphdr* ip = reinterpret_cast<const iphdr*>(ip_ptr);
        size_t ip_hdr_len = ip->ihl * 4;
        if (ip_hdr_len < sizeof(iphdr) || ip_avail < ip_hdr_len) return;

        if (ip->version != 4) return;

        uint8_t proto = ip->protocol;
        if (proto != IPPROTO_TCP && proto != IPPROTO_UDP) return;

        uint32_t src_ip = ip->saddr;
        uint32_t dst_ip = ip->daddr;

        const uint8_t* l4_ptr = ip_ptr + ip_hdr_len;
        size_t l4_avail = ip_avail - ip_hdr_len;

        uint16_t src_port = 0, dst_port = 0;
        if (proto == IPPROTO_TCP) {
            if (l4_avail < sizeof(tcphdr)) return;
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(l4_ptr);
            src_port = ntohs(tcp->source);
            dst_port = ntohs(tcp->dest);
        } else {
            if (l4_avail < sizeof(udphdr)) return;
            const udphdr* udp = reinterpret_cast<const udphdr*>(l4_ptr);
            src_port = ntohs(udp->source);
            dst_port = ntohs(udp->dest);
        }

        FlowKey key{src_ip, dst_ip, src_port, dst_port, proto};
        uint64_t now_us = ts_to_us(header->ts);

        auto& st = flows_[key];
        if (st.packets == 0) {
            st.first_ts_us = now_us;
        }
        st.packets++;
        st.bytes += header->len;
        st.last_ts_us = now_us;
    }

    void print_flows() const {
        std::cout << "---- Active flows: " << flows_.size() << " ----\n";
        for (const auto& kv : flows_) {
            const FlowKey& k = kv.first;
            const FlowStats& s = kv.second;

            char src[INET_ADDRSTRLEN];
            char dst[INET_ADDRSTRLEN];
            inet_ntop(AF_INET, &k.src_ip, src, sizeof(src));
            inet_ntop(AF_INET, &k.dst_ip, dst, sizeof(dst));

            std::cout
                << src << ":" << k.src_port
                << " -> " << dst << ":" << k.dst_port
                << " proto=" << static_cast<int>(k.proto)
                << " pkts=" << s.packets
                << " bytes=" << s.bytes
                << " first_us=" << s.first_ts_us
                << " last_us=" << s.last_ts_us
                << "\n";
        }
    }

private:
    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows_;
};

static void packet_handler(u_char* user, const pcap_pkthdr* header, const u_char* packet) {
    auto* analyser = reinterpret_cast<FlowAnalyser*>(user);
    analyser->process_packet(header, packet);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    const char* iface = argv[1];
    char errbuf[PCAP_ERRBUF_SIZE];

    pcap_t* handle = pcap_open_live(
        iface,
        65535,   // snaplen
        1,       // promiscuous
        1000,    // read timeout ms
        errbuf
    );

    if (!handle) {
        std::cerr << "pcap_open_live failed: " << errbuf << "\n";
        return 1;
    }

    // Reduce overhead by disabling packet direction filtering if not needed.
    // Optional: pcap_set_immediate_mode / pcap_set_buffer_size before activation
    // if using pcap_create/pcap_activate.

    FlowAnalyser analyser;

    std::cout << "Listening on " << iface << "...\n";

    // Simple loop; for higher performance, use pcap_dispatch in a dedicated thread.
    while (true) {
        int ret = pcap_dispatch(handle, 1024, packet_handler,
                                reinterpret_cast<u_char*>(&analyser));
        if (ret < 0) {
            std::cerr << "pcap_dispatch error: " << pcap_geterr(handle) << "\n";
            break;
        }

        // Periodic reporting
        static auto last_report = std::chrono::steady_clock::now();
        auto now = std::chrono::steady_clock::now();
        if (now - last_report >= std::chrono::seconds(5)) {
            analyser.print_flows();
            last_report = now;
        }
    }

    pcap_close(handle);
    return 0;
}
