Below is a **minimal working version** of a **performance-critical network flow analyser** designed for **gigabit-scale traffic**. It is intentionally compact, but structured so you can extend it into a production system.

### What it does
- Captures packets from a live interface using **libpcap**
- Extracts 5-tuple flow keys:
  - source IP
  - destination IP
  - source port
  - destination port
  - protocol
- Aggregates per-flow:
  - packet count
  - byte count
  - first/last seen timestamps
- Uses a **fixed-size hash table** for speed
- Avoids dynamic allocation per packet
- Designed for **high throughput** and low overhead

---

## C implementation

```c
// flow_analyzer.c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <time.h>

#define FLOW_TABLE_SIZE (1u << 20)   // 1,048,576 entries
#define FLOW_TABLE_MASK (FLOW_TABLE_SIZE - 1)

typedef struct {
    uint32_t src_ip, dst_ip;
    uint16_t src_port, dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    struct timeval first_seen;
    struct timeval last_seen;
    uint8_t used;
} flow_entry_t;

static flow_entry_t *flow_table;

static inline uint64_t hash_flow(const flow_key_t *k) {
    // Fast 64-bit mix
    uint64_t x = ((uint64_t)k->src_ip << 32) ^ k->dst_ip;
    x ^= ((uint64_t)k->src_port << 16) ^ k->dst_port;
    x ^= (uint64_t)k->proto;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return x;
}

static inline int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static inline void update_flow(const flow_key_t *key, uint32_t bytes, const struct timeval *ts) {
    uint64_t h = hash_flow(key);
    uint32_t idx = (uint32_t)h & FLOW_TABLE_MASK;

    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = &flow_table[(idx + i) & FLOW_TABLE_MASK];

        if (!e->used) {
            e->used = 1;
            e->key = *key;
            e->packets = 1;
            e->bytes = bytes;
            e->first_seen = *ts;
            e->last_seen = *ts;
            return;
        }

        if (flow_key_equal(&e->key, key)) {
            e->packets++;
            e->bytes += bytes;
            e->last_seen = *ts;
            return;
        }
    }

    // Table full: drop flow update
}

static void packet_handler(u_char *user, const struct pcap_pkthdr *h, const u_char *packet) {
    (void)user;

    // Ethernet header
    if (h->caplen < 14) return;
    const uint8_t *ptr = packet;
    uint16_t eth_type = ntohs(*(uint16_t *)(ptr + 12));
    ptr += 14;

    // IPv4 only
    if (eth_type != 0x0800) return;
    if (h->caplen < 14 + sizeof(struct ip)) return;

    const struct ip *iph = (const struct ip *)ptr;
    int ip_hdr_len = iph->ip_hl * 4;
    if (ip_hdr_len < 20) return;
    if (h->caplen < 14 + (size_t)ip_hdr_len) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    ptr += ip_hdr_len;

    if (iph->ip_p == IPPROTO_TCP) {
        if (h->caplen < 14 + (size_t)ip_hdr_len + sizeof(struct tcphdr)) return;
        const struct tcphdr *th = (const struct tcphdr *)ptr;
        key.src_port = th->source;
        key.dst_port = th->dest;
    } else if (iph->ip_p == IPPROTO_UDP) {
        if (h->caplen < 14 + (size_t)ip_hdr_len + sizeof(struct udphdr)) return;
        const struct udphdr *uh = (const struct udphdr *)ptr;
        key.src_port = uh->source;
        key.dst_port = uh->dest;
    } else {
        // Non-TCP/UDP flows tracked with ports = 0
        key.src_port = 0;
        key.dst_port = 0;
    }

    update_flow(&key, h->len, &h->ts);
}

static void print_top_flows(void) {
    printf("\n=== Flow table snapshot ===\n");
    for (uint32_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = &flow_table[i];
        if (!e->used) continue;

        struct in_addr s = { .s_addr = e->key.src_ip };
        struct in_addr d = { .s_addr = e->key.dst_ip };

        char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &s, src, sizeof(src));
        inet_ntop(AF_INET, &d, dst, sizeof(dst));

        printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu\n",
               src, ntohs(e->key.src_port),
               dst, ntohs(e->key.dst_port),
               e->key.proto,
               (unsigned long long)e->packets,
               (unsigned long long)e->bytes);
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_open_live(argv[1], 65535, 1, 1, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    // Reduce overhead by disabling packet buffering delays
    if (pcap_set_immediate_mode(handle, 1) != 0) {
        fprintf(stderr, "Warning: could not enable immediate mode\n");
    }

    flow_table = aligned_alloc(64, sizeof(flow_entry_t) * FLOW_TABLE_SIZE);
    if (!flow_table) {
        perror("aligned_alloc");
        pcap_close(handle);
        return 1;
    }
    memset(flow_table, 0, sizeof(flow_entry_t) * FLOW_TABLE_SIZE);

    printf("Capturing on %s...\n", argv[1]);
    int ret = pcap_loop(handle, -1, packet_handler, NULL);

    if (ret == -1) {
        fprintf(stderr, "pcap_loop error: %s\n", pcap_geterr(handle));
    }

    print_top_flows();

    free(flow_table);
    pcap_close(handle);
    return 0;
}
