## Minimal implementation

### `flow_analyzer.cpp`

```cpp
#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>

#include <cstdint>
#include <cstring>
#include <iostream>
#include <unordered_map>
#include <chrono>
#include <vector>

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        size_t h = std::hash<uint32_t>{}(k.src_ip);
        h ^= std::hash<uint32_t>{}(k.dst_ip) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint16_t>{}(k.src_port) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint16_t>{}(k.dst_port) + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= std::hash<uint8_t>{}(k.proto) + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ms = 0;
    uint64_t last_seen_ms = 0;
};

static std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows;
static uint64_t FLOW_TIMEOUT_MS = 10000; // 10 seconds

static uint64_t now_ms() {
    using namespace std::chrono;
    return duration_cast<milliseconds>(
        steady_clock::now().time_since_epoch()
    ).count();
}

static void print_ip(uint32_t ip) {
    struct in_addr addr{};
    addr.s_addr = ip;
    std::cout << inet_ntoa(addr);
}

static void expire_flows(uint64_t current_ms) {
    for (auto it = flows.begin(); it != flows.end(); ) {
        if (current_ms - it->second.last_seen_ms > FLOW_TIMEOUT_MS) {
            const auto& k = it->first;
            const auto& s = it->second;
            std::cout << "FLOW EXPIRED "
                      << "src="; print_ip(k.src_ip);
            std::cout << ":" << ntohs(k.src_port)
                      << " dst="; print_ip(k.dst_ip);
            std::cout << ":" << ntohs(k.dst_port)
                      << " proto=" << int(k.proto)
                      << " packets=" << s.packets
                      << " bytes=" << s.bytes
                      << "\n";
            it = flows.erase(it);
        } else {
            ++it;
        }
    }
}

static void handle_packet(const struct pcap_pkthdr* header, const u_char* packet) {
    if (header->caplen < sizeof(ether_header)) return;

    const ether_header* eth = reinterpret_cast<const ether_header*>(packet);
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char* ip_ptr = packet + sizeof(ether_header);
    if (header->caplen < sizeof(ether_header) + sizeof(iphdr)) return;

    const ip* iph = reinterpret_cast<const ip*>(ip_ptr);
    int ip_header_len = iph->ip_hl * 4;
    if (ip_header_len < 20) return;
    if (header->caplen < sizeof(ether_header) + (size_t)ip_header_len) return;

    uint8_t proto = iph->ip_p;
    if (proto != IPPROTO_TCP && proto != IPPROTO_UDP) return;

    uint16_t src_port = 0, dst_port = 0;
    const u_char* l4_ptr = ip_ptr + ip_header_len;

    if (proto == IPPROTO_TCP) {
        if (header->caplen < sizeof(ether_header) + (size_t)ip_header_len + sizeof(tcphdr)) return;
        const tcphdr* tcp = reinterpret_cast<const tcphdr*>(l4_ptr);
        src_port = tcp->source;
        dst_port = tcp->dest;
    } else {
        if (header->caplen < sizeof(ether_header) + (size_t)ip_header_len + sizeof(udphdr)) return;
        const udphdr* udp = reinterpret_cast<const udphdr*>(l4_ptr);
        src_port = udp->source;
        dst_port = udp->dest;
    }

    FlowKey key{
        iph->ip_src.s_addr,
        iph->ip_dst.s_addr,
        src_port,
        dst_port,
        proto
    };

    uint64_t ts_ms = (uint64_t)header->ts.tv_sec * 1000ULL + header->ts.tv_usec / 1000ULL;
    uint64_t pkt_bytes = header->len;

    auto& st = flows[key];
    if (st.packets == 0) st.first_seen_ms = ts_ms;
    st.packets++;
    st.bytes += pkt_bytes;
    st.last_seen_ms = ts_ms;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>\n";
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t* handle = pcap_open_live(argv[1], 65535, 1, 1000, errbuf);
    if (!handle) {
        std::cerr << "pcap_open_live failed: " << errbuf << "\n";
        return 1;
    }

    // Optional: capture only IPv4 TCP/UDP
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip and (tcp or udp)", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    std::cout << "Listening on " << argv[1] << "...\n";

    while (true) {
        struct pcap_pkthdr* header;
        const u_char* packet;
        int rc = pcap_next_ex(handle, &header, &packet);

        if (rc == 1) {
            handle_packet(header, packet);
        } else if (rc == 0) {
            // timeout
            expire_flows(now_ms());
        } else if (rc == -1) {
            std::cerr << "pcap error: " << pcap_geterr(handle) << "\n";
            break;
        } else if (rc == -2) {
            break;
        }

        // Periodic cleanup
        static uint64_t last_cleanup = 0;
        uint64_t t = now_ms();
        if (t - last_cleanup > 1000) {
            expire_flows(t);
            last_cleanup = t;
        }
    }

    pcap_close(handle);
    return 0;
}
