#include <time.h>

#define FLOW_TABLE_SIZE (1 << 20)   // 1,048,576 buckets
#define REPORT_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    struct timespec first_seen;
    struct timespec last_seen;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[FLOW_TABLE_SIZE];

static inline uint32_t hash_flow(const flow_key_t *k) {
    // Simple fast hash for 5-tuple
    uint32_t h = k->src_ip ^ (k->dst_ip * 2654435761u);
    h ^= ((uint32_t)k->src_port << 16) | k->dst_port;
    h ^= ((uint32_t)k->proto * 0x9e3779b1u);
    h ^= h >> 16;
    return h & (FLOW_TABLE_SIZE - 1);
}

static inline int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return a->src_ip == b->src_ip &&
           a->dst_ip == b->dst_ip &&
           a->src_port == b->src_port &&
           a->dst_port == b->dst_port &&
           a->proto == b->proto;
}

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static void print_ip(uint32_t ip) {
    struct in_addr addr;
    addr.s_addr = ip;
    printf("%s", inet_ntoa(addr));
}

static void report_flows(void) {
    printf("\n=== Flow report ===\n");
    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        for (flow_entry_t *e = flow_table[i]; e; e = e->next) {
            printf("Flow ");
            print_ip(e->key.src_ip);
            printf(":%u -> ", ntohs(e->key.src_port));
            print_ip(e->key.dst_ip);
            printf(":%u proto=%u packets=%lu bytes=%lu\n",
                   ntohs(e->key.dst_port),
                   e->key.proto,
                   (unsigned long)e->packets,
                   (unsigned long)e->bytes);
        }
    }
    printf("=== End report ===\n");
}

static void process_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    if (h->caplen < 14) return; // Ethernet header minimum

    const u_char *ptr = bytes;
    uint16_t eth_type = ntohs(*(uint16_t *)(ptr + 12));
    if (eth_type != 0x0800) return; // IPv4 only

    ptr += 14;
    if (h->caplen < 14 + sizeof(struct ip)) return;

    const struct ip *ip = (const struct ip *)ptr;
    int ip_hdr_len = ip->ip_hl * 4;
    if (ip_hdr_len < 20) return;
    if (h->caplen < 14 + ip_hdr_len) return;

    flow_key_t key;
    key.src_ip = ip->ip_src.s_addr;
    key.dst_ip = ip->ip_dst.s_addr;
    key.proto = ip->ip_p;
    key.src_port = 0;
    key.dst_port = 0;

    ptr += ip_hdr_len;
    size_t l4_len = h->caplen - (ptr - bytes);

    if (ip->ip_p == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)ptr;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->ip_p == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)ptr;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else {
        // For non-TCP/UDP, keep ports zero
    }

    uint32_t idx = hash_flow(&key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_key_equal(&e->key, &key)) {
            e->packets++;
            e->bytes += h->len;
            clock_gettime(CLOCK_MONOTONIC, &e->last_seen);
            return;
        }
        e = e->next;
    }

    // New flow
    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return;

    e->key = key;
    e->packets = 1;
    e->bytes = h->len;
    clock_gettime(CLOCK_MONOTONIC, &e->first_seen);
    e->last_seen = e->first_seen;

    e->next = flow_table[idx];
    flow_table[idx] = e;
}

int main(int argc, char **argv) {
    char errbuf[PCAP_ERRBUF_SIZE];
    const char *dev = NULL;
    pcap_t *handle;
    struct bpf_program fp;
    char filter_exp[] = "ip";
    bpf_u_int32 net = 0, mask = 0;

    if (argc > 1) {
        dev = argv[1];
    } else {
        dev = pcap_lookupdev(errbuf);
        if (!dev) {
            fprintf(stderr, "No default device found: %s\n", errbuf);
            return 1;
        }
    }

    signal(SIGINT, handle_sigint);

    if (pcap_lookupnet(dev, &net, &mask, errbuf) == -1) {
        net = 0;
        mask = 0;
    }

    handle = pcap_open_live(dev, 65535, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    if (pcap_compile(handle, &fp, filter_exp, 0, net) == -1) {
        fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(handle));
        pcap_freecode(&fp);
        pcap_close(handle);
        return 1;
    }

    pcap_freecode(&fp);

    printf("Listening on %s...\n", dev);

    time_t last_report = time(NULL);

    while (running) {
        int ret = pcap_dispatch(handle, 1024, process_packet, NULL);
        if (ret < 0) {
            fprintf(stderr, "pcap_dispatch error: %s\n", pcap_geterr(handle));
            break;
        }

        time_t now = time(NULL);
        if (now - last_report >= REPORT_INTERVAL_SEC) {
            report_flows();
            last_report = now;
        }
    }

    report_flows();
    pcap_close(handle);
    return 0;
}
