## Minimal C skeleton

```c
// flow_analyzer.c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/if.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <unistd.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define TABLE_SIZE (1 << 20)   // 1M buckets
#define IDLE_TIMEOUT_NS (10ULL * 1000000000ULL)

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *table[TABLE_SIZE];

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint32_t hash_flow(const flow_key_t *k) {
    uint32_t h = 2166136261u;
    h ^= k->src_ip;   h *= 16777619u;
    h ^= k->dst_ip;   h *= 16777619u;
    h ^= k->src_port; h *= 16777619u;
    h ^= k->dst_port; h *= 16777619u;
    h ^= k->proto;    h *= 16777619u;
    return h;
}

static inline int flow_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(flow_key_t)) == 0;
}

static flow_entry_t *lookup_or_create(const flow_key_t *k, uint64_t ts) {
    uint32_t idx = hash_flow(k) & (TABLE_SIZE - 1);
    flow_entry_t *e = table[idx];
    while (e) {
        if (flow_equal(&e->key, k)) return e;
        e = e->next;
    }
    e = calloc(1, sizeof(*e));
    if (!e) return NULL;
    e->key = *k;
    e->first_seen_ns = ts;
    e->last_seen_ns = ts;
    e->next = table[idx];
    table[idx] = e;
    return e;
}

static void export_and_remove_idle(uint64_t ts) {
    for (size_t i = 0; i < TABLE_SIZE; i++) {
        flow_entry_t **pp = &table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if (ts - e->last_seen_ns > IDLE_TIMEOUT_NS) {
                // Export flow summary
                printf("FLOW %u:%u -> %u:%u proto=%u packets=%llu bytes=%llu\n",
                       ntohl(e->key.src_ip), ntohs(e->key.src_port),
                       ntohl(e->key.dst_ip), ntohs(e->key.dst_port),
                       e->key.proto,
                       (unsigned long long)e->packets,
                       (unsigned long long)e->bytes);

                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

static void process_packet(const uint8_t *pkt, size_t len) {
    if (len < sizeof(struct ethhdr)) return;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP) return;

    const struct iphdr *ip = (const struct iphdr *)(pkt + sizeof(struct ethhdr));
    if ((uint8_t *)ip + sizeof(struct iphdr) > pkt + len) return;

    if (ip->version != 4) return;

    size_t ip_hlen = ip->ihl * 4;
    if (len < sizeof(struct ethhdr) + ip_hlen) return;

    flow_key_t k = {0};
    k.src_ip = ip->saddr;
    k.dst_ip = ip->daddr;
    k.proto = ip->protocol;

    const uint8_t *l4 = pkt + sizeof(struct ethhdr) + ip_hlen;
    if (ip->protocol == IPPROTO_TCP) {
        if (len < sizeof(struct ethhdr) + ip_hlen + sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        k.src_port = tcp->source;
        k.dst_port = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (len < sizeof(struct ethhdr) + ip_hlen + sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        k.src_port = udp->source;
        k.dst_port = udp->dest;
    } else {
        return;
    }

    uint64_t ts = now_ns();
    flow_entry_t *e = lookup_or_create(&k, ts);
    if (!e) return;

    e->packets++;
    e->bytes += len;
    e->last_seen_ns = ts;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "usage: %s <iface>\n", argv[0]);
        return 1;
    }

    const char *iface = argv[1];
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        return 1;
    }

    struct sockaddr_ll sll = {0};
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = if_nametoindex(iface);
    if (!sll.sll_ifindex) {
        perror("if_nametoindex");
        return 1;
    }

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        return 1;
    }

    uint8_t buf[2048];
    uint64_t last_aging = now_ns();

    for (;;) {
        ssize_t n = recv(fd, buf, sizeof(buf), 0);
        if (n > 0) {
            process_packet(buf, (size_t)n);
        }

        uint64_t ts = now_ns();
        if (ts - last_aging > 1000000000ULL) { // every 1s
            export_and_remove_idle(ts);
            last_aging = ts;
        }
    }

    close(fd);
    return 0;
}
