## `src/main.rs`

```rust
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use hashbrown::HashMap;
use pcap::{Capture, Device};
use std::hash::{Hash, Hasher};
use std::net::Ipv4Addr;
use std::time::{Duration, Instant};

#[derive(Clone, Copy, Debug, Eq)]
struct FlowKey {
    src_ip: Ipv4Addr,
    dst_ip: Ipv4Addr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: Instant,
    last_seen: Instant,
}

impl FlowStats {
    fn new(now: Instant, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: Instant, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

fn main() -> anyhow::Result<()> {
    let device = Device::lookup()?
        .ok_or_else(|| anyhow::anyhow!("No default capture device found"))?;

    println!("Capturing on device: {}", device.name);

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(128)
        .open()?;

    // Optional BPF filter to reduce load
    // cap.filter("ip", true)?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);
    let flow_timeout = Duration::from_secs(30);
    let mut last_cleanup = Instant::now();

    loop {
        match cap.next_packet() {
            Ok(packet) => {
                let now = Instant::now();

                if let Ok(sliced) = SlicedPacket::from_ethernet(packet.data) {
                    let (src_ip, dst_ip, proto) = match sliced.ip {
                        Some(InternetSlice::Ipv4(header, _)) => {
                            let src = Ipv4Addr::from(header.source());
                            let dst = Ipv4Addr::from(header.destination());
                            (src, dst, header.protocol())
                        }
                        _ => continue,
                    };

                    let (src_port, dst_port) = match sliced.transport {
                        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
                        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
                        _ => continue,
                    };

                    let key = FlowKey {
                        src_ip,
                        dst_ip,
                        src_port,
                        dst_port,
                        proto,
                    };

                    let entry = flows.entry(key).or_insert_with(|| FlowStats::new(now, packet.data.len()));
                    if entry.packets > 1 {
                        entry.update(now, packet.data.len());
                    }
                }

                if last_cleanup.elapsed() >= Duration::from_secs(5) {
                    cleanup_expired_flows(&mut flows, flow_timeout);
                    last_cleanup = Instant::now();
                }
            }
            Err(e) => {
                eprintln!("Capture error: {e}");
            }
        }
    }
}

fn cleanup_expired_flows(flows: &mut HashMap<FlowKey, FlowStats>, timeout: Duration) {
    let now = Instant::now();
    let mut expired = Vec::new();

    for (key, stats) in flows.iter() {
        if now.duration_since(stats.last_seen) > timeout {
            expired.push(*key);
        }
    }

    for key in expired {
        if let Some(stats) = flows.remove(&key) {
            println!(
                "FLOW {:?} packets={} bytes={} duration_ms={}",
                key,
                stats.packets,
                stats.bytes,
                stats.last_seen.duration_since(stats.first_seen).as_millis()
            );
        }
    }
}
```

