## 3) Minimal implementation in C

### `flow_analyzer.c`

```c
#define _GNU_SOURCE
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <net/ethernet.h>
#include <time.h>
#include <unistd.h>

#define FLOW_TABLE_SIZE 1048576   // power of two, tune for load
#define FLOW_IDLE_TIMEOUT 30      // seconds

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
} flow_key_t;

typedef struct flow_entry {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_seen_ns;
    uint64_t last_seen_ns;
    struct flow_entry *next;
} flow_entry_t;

static flow_entry_t *flow_table[FLOW_TABLE_SIZE];

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint32_t hash_flow(const flow_key_t *k) {
    // simple fast hash
    uint32_t h = 2166136261u;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        h ^= p[i];
        h *= 16777619u;
    }
    return h & (FLOW_TABLE_SIZE - 1);
}

static inline int flow_key_equal(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static flow_entry_t *flow_lookup_or_create(const flow_key_t *key, uint64_t ts_ns) {
    uint32_t idx = hash_flow(key);
    flow_entry_t *e = flow_table[idx];

    while (e) {
        if (flow_key_equal(&e->key, key)) return e;
        e = e->next;
    }

    e = (flow_entry_t *)calloc(1, sizeof(flow_entry_t));
    if (!e) return NULL;

    e->key = *key;
    e->first_seen_ns = ts_ns;
    e->last_seen_ns = ts_ns;
    e->next = flow_table[idx];
    flow_table[idx] = e;
    return e;
}

static void expire_flows(void) {
    uint64_t cutoff_ns = now_ns() - (uint64_t)FLOW_IDLE_TIMEOUT * 1000000000ULL;

    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t **pp = &flow_table[i];
        while (*pp) {
            flow_entry_t *e = *pp;
            if (e->last_seen_ns < cutoff_ns) {
                char src[INET_ADDRSTRLEN], dst[INET_ADDRSTRLEN];
                struct in_addr s = { .s_addr = e->key.src_ip };
                struct in_addr d = { .s_addr = e->key.dst_ip };

                inet_ntop(AF_INET, &s, src, sizeof(src));
                inet_ntop(AF_INET, &d, dst, sizeof(dst));

                printf("FLOW %s:%u -> %s:%u proto=%u packets=%lu bytes=%lu\n",
                       src, ntohs(e->key.src_port),
                       dst, ntohs(e->key.dst_port),
                       e->key.proto,
                       (unsigned long)e->packets,
                       (unsigned long)e->bytes);

                *pp = e->next;
                free(e);
            } else {
                pp = &e->next;
            }
        }
    }
}

static void handle_packet(u_char *user, const struct pcap_pkthdr *h, const u_char *bytes) {
    (void)user;

    uint64_t ts_ns = (uint64_t)h->ts.tv_sec * 1000000000ULL + (uint64_t)h->ts.tv_usec * 1000ULL;

    if (h->caplen < sizeof(struct ether_header)) return;

    const struct ether_header *eth = (const struct ether_header *)bytes;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const u_char *ptr = bytes + sizeof(struct ether_header);
    size_t remaining = h->caplen - sizeof(struct ether_header);

    if (remaining < sizeof(struct ip)) return;
    const struct ip *ip = (const struct ip *)ptr;

    size_t ip_hdr_len = ip->ip_hl * 4;
    if (ip_hdr_len < sizeof(struct ip) || remaining < ip_hdr_len) return;

    if (ip->ip_v != 4) return;

    flow_key_t key;
    memset(&key, 0, sizeof(key));
    key.src_ip = ip->ip_src.s_addr;
    key.dst_ip = ip->ip_dst.s_addr;
    key.proto = ip->ip_p;

    const u_char *l4 = ptr + ip_hdr_len;
    size_t l4_len = remaining - ip_hdr_len;

    if (ip->ip_p == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->ip_p == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->uh_sport;
        key.dst_port = udp->uh_dport;
    } else {
        return;
    }

    flow_entry_t *e = flow_lookup_or_create(&key, ts_ns);
    if (!e) return;

    e->packets++;
    e->bytes += h->len;
    e->last_seen_ns = ts_ns;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle = pcap_create(argv[1], errbuf);
    if (!handle) {
        fprintf(stderr, "pcap_create: %s\n", errbuf);
        return 1;
    }

    pcap_set_snaplen(handle, 96);
    pcap_set_promisc(handle, 1);
    pcap_set_timeout(handle, 1);
    pcap_set_immediate_mode(handle, 1);

    if (pcap_activate(handle) != 0) {
        fprintf(stderr, "pcap_activate: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }

    // Optional filter: only IP traffic
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip", 1, PCAP_NETMASK_UNKNOWN) == 0) {
        pcap_setfilter(handle, &fp);
        pcap_freecode(&fp);
    }

    printf("Listening on %s...\n", argv[1]);

    uint64_t last_expire = now_ns();

    while (1) {
        struct pcap_pkthdr *hdr;
        const u_char *data;
        int rc = pcap_next_ex(handle, &hdr, &data);

        if (rc == 1) {
            handle_packet(NULL, hdr, data);
        } else if (rc == 0) {
            // timeout
        } else if (rc == -1 || rc == -2) {
            break;
        }

        uint64_t t = now_ns();
        if (t - last_expire > 1000000000ULL) {
            expire_flows();
            last_expire = t;
        }
    }

    expire_flows();
    pcap_close(handle);
    return 0;
}
```

