## `flow_analyzer.cpp`

```cpp
#include <pcap.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>
#include <unistd.h>

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <ctime>

#include <unordered_map>
#include <string>
#include <iostream>

static constexpr size_t FLOW_TABLE_SIZE = 1 << 20;   // 1M buckets
static constexpr uint32_t FLOW_TIMEOUT_SEC = 30;

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        // Simple fast hash
        uint64_t x = k.src_ip;
        x ^= (uint64_t)k.dst_ip << 1;
        x ^= (uint64_t)k.src_port << 17;
        x ^= (uint64_t)k.dst_port << 33;
        x ^= (uint64_t)k.proto << 49;
        // mix
        x ^= x >> 33;
        x *= 0xff51afd7ed558ccdULL;
        x ^= x >> 33;
        x *= 0xc4ceb9fe1a85ec53ULL;
        x ^= x >> 33;
        return (size_t)x;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    time_t first_seen = 0;
    time_t last_seen = 0;
};

static std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows;

static void print_flow(const FlowKey& k, const FlowStats& s) {
    char src[INET_ADDRSTRLEN];
    char dst[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &k.src_ip, src, sizeof(src));
    inet_ntop(AF_INET, &k.dst_ip, dst, sizeof(dst));

    std::printf("%s:%u -> %s:%u proto=%u packets=%llu bytes=%llu duration=%lds\n",
                src, ntohs(k.src_port),
                dst, ntohs(k.dst_port),
                k.proto,
                (unsigned long long)s.packets,
                (unsigned long long)s.bytes,
                (long)(s.last_seen - s.first_seen));
}

static void expire_flows(time_t now) {
    for (auto it = flows.begin(); it != flows.end(); ) {
        if ((uint32_t)(now - it->second.last_seen) > FLOW_TIMEOUT_SEC) {
            print_flow(it->first, it->second);
            it = flows.erase(it);
        } else {
            ++it;
        }
    }
}

static void packet_handler(u_char* /*user*/, const struct pcap_pkthdr* h, const u_char* bytes) {
    // Ethernet header
    if (h->caplen < 14) return;

    const uint8_t* ptr = bytes;
    uint16_t eth_type = ntohs(*(uint16_t*)(ptr + 12));
    if (eth_type != 0x0800) return; // IPv4 only

    ptr += 14;
    if (h->caplen < 14 + sizeof(struct ip)) return;

    const struct ip* iph = (const struct ip*)ptr;
    int ip_header_len = iph->ip_hl * 4;
    if (ip_header_len < 20) return;
    if (h->caplen < 14 + (size_t)ip_header_len) return;

    if (iph->ip_v != 4) return;

    FlowKey key{};
    key.src_ip = iph->ip_src.s_addr;
    key.dst_ip = iph->ip_dst.s_addr;
    key.proto = iph->ip_p;

    const u_char* l4 = ptr + ip_header_len;
    uint16_t src_port = 0, dst_port = 0;

    if (key.proto == IPPROTO_TCP) {
        if (h->caplen < 14 + (size_t)ip_header_len + sizeof(struct tcphdr)) return;
        const struct tcphdr* th = (const struct tcphdr*)l4;
        src_port = th->source;
        dst_port = th->dest;
    } else if (key.proto == IPPROTO_UDP) {
        if (h->caplen < 14 + (size_t)ip_header_len + sizeof(struct udphdr)) return;
        const struct udphdr* uh = (const struct udphdr*)l4;
        src_port = uh->source;
        dst_port = uh->dest;
    } else {
        // For non-TCP/UDP, keep ports zero
    }

    key.src_port = src_port;
    key.dst_port = dst_port;

    auto& st = flows[key];
    if (st.packets == 0) {
        st.first_seen = h->ts.tv_sec;
    }
    st.last_seen = h->ts.tv_sec;
    st.packets++;
    st.bytes += h->len;

    // Lightweight periodic cleanup
    static uint64_t pkt_count = 0;
    if ((++pkt_count & 0xFFFF) == 0) {
        expire_flows(h->ts.tv_sec);
    }
}

int main(int argc, char** argv) {
    const char* dev = nullptr;
    char errbuf[PCAP_ERRBUF_SIZE];

    if (argc > 1) {
        dev = argv[1];
    } else {
        dev = pcap_lookupdev(errbuf);
        if (!dev) {
            std::fprintf(stderr, "pcap_lookupdev failed: %s\n", errbuf);
            return 1;
        }
    }

    std::printf("Capturing on %s\n", dev);

    pcap_t* handle = pcap_open_live(dev, 65535, 1, 1000, errbuf);
    if (!handle) {
        std::fprintf(stderr, "pcap_open_live failed: %s\n", errbuf);
        return 1;
    }

    // Capture only IPv4 packets to reduce overhead
    struct bpf_program fp;
    if (pcap_compile(handle, &fp, "ip", 1, PCAP_NETMASK_UNKNOWN) == -1) {
        std::fprintf(stderr, "pcap_compile failed: %s\n", pcap_geterr(handle));
        pcap_close(handle);
        return 1;
    }
    if (pcap_setfilter(handle, &fp) == -1) {
        std::fprintf(stderr, "pcap_setfilter failed: %s\n", pcap_geterr(handle));
        pcap_freecode(&fp);
        pcap_close(handle);
        return 1;
    }
    pcap_freecode(&fp);

    if (pcap_loop(handle, -1, packet_handler, nullptr) == -1) {
        std::fprintf(stderr, "pcap_loop failed: %s\n", pcap_geterr(handle));
    }

    // Flush remaining flows
    for (const auto& kv : flows) {
        print_flow(kv.first, kv.second);
    }

    pcap_close(handle);
    return 0;
}
```

