## `src/main.rs`

```rust
use etherparse::{InternetSlice, SlicedPacket, TransportSlice};
use hashbrown::HashMap;
use pcap::{Capture, Device};
use std::hash::{Hash, Hasher};
use std::net::IpAddr;
use std::time::{Duration, SystemTime};

#[derive(Clone, Debug, Eq)]
struct FlowKey {
    src_ip: IpAddr,
    dst_ip: IpAddr,
    src_port: u16,
    dst_port: u16,
    proto: u8,
}

impl PartialEq for FlowKey {
    fn eq(&self, other: &Self) -> bool {
        self.src_ip == other.src_ip
            && self.dst_ip == other.dst_ip
            && self.src_port == other.src_port
            && self.dst_port == other.dst_port
            && self.proto == other.proto
    }
}

impl Hash for FlowKey {
    fn hash<H: Hasher>(&self, state: &mut H) {
        self.src_ip.hash(state);
        self.dst_ip.hash(state);
        self.src_port.hash(state);
        self.dst_port.hash(state);
        self.proto.hash(state);
    }
}

#[derive(Clone, Debug)]
struct FlowStats {
    packets: u64,
    bytes: u64,
    first_seen: SystemTime,
    last_seen: SystemTime,
}

impl FlowStats {
    fn new(now: SystemTime, bytes: usize) -> Self {
        Self {
            packets: 1,
            bytes: bytes as u64,
            first_seen: now,
            last_seen: now,
        }
    }

    fn update(&mut self, now: SystemTime, bytes: usize) {
        self.packets += 1;
        self.bytes += bytes as u64;
        self.last_seen = now;
    }
}

fn parse_flow(packet: &[u8]) -> Option<(FlowKey, usize)> {
    let sliced = SlicedPacket::from_ethernet(packet).ok()?;

    let (src_ip, dst_ip, proto) = match sliced.ip {
        Some(InternetSlice::Ipv4(header, _)) => (
            IpAddr::V4(header.source_addr().into()),
            IpAddr::V4(header.destination_addr().into()),
            header.protocol() as u8,
        ),
        Some(InternetSlice::Ipv6(header, _)) => (
            IpAddr::V6(header.source_addr().into()),
            IpAddr::V6(header.destination_addr().into()),
            header.next_header() as u8,
        ),
        _ => return None,
    };

    let (src_port, dst_port) = match sliced.transport {
        Some(TransportSlice::Tcp(tcp)) => (tcp.source_port(), tcp.destination_port()),
        Some(TransportSlice::Udp(udp)) => (udp.source_port(), udp.destination_port()),
        _ => return None,
    };

    let key = FlowKey {
        src_ip,
        dst_ip,
        src_port,
        dst_port,
        proto,
    };

    Some((key, packet.len()))
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let device = Device::lookup()?
        .ok_or("No default capture device found")?;

    println!("Capturing on device: {}", device.name);

    let mut cap = Capture::from_device(device)?
        .promisc(true)
        .immediate_mode(true)
        .snaplen(65535)
        .open()?;

    let mut flows: HashMap<FlowKey, FlowStats> = HashMap::with_capacity(1 << 20);
    let mut last_report = SystemTime::now();

    loop {
        match cap.next_packet() {
            Ok(pkt) => {
                let now = SystemTime::now();

                if let Some((key, bytes)) = parse_flow(pkt.data) {
                    flows
                        .entry(key)
                        .and_modify(|s| s.update(now, bytes))
                        .or_insert_with(|| FlowStats::new(now, bytes));
                }

                if last_report.elapsed().unwrap_or(Duration::from_secs(0)) >= Duration::from_secs(5) {
                    report_top_flows(&flows, 10);
                    last_report = now;
                }
            }
            Err(e) => {
                eprintln!("Capture error: {e}");
            }
        }
    }
}

fn report_top_flows(flows: &HashMap<FlowKey, FlowStats>, top_n: usize) {
    let mut items: Vec<_> = flows.iter().collect();
    items.sort_by_key(|(_, stats)| std::cmp::Reverse(stats.bytes));

    println!("--- Top {} flows ---", top_n);
    for (i, (key, stats)) in items.into_iter().take(top_n).enumerate() {
        println!(
            "#{:02} {:?}:{:?} -> {:?}:{:?} proto={} packets={} bytes={} first_seen={:?} last_seen={:?}",
            i + 1,
            key.src_ip,
            key.src_port,
            key.dst_ip,
            key.dst_port,
            key.proto,
            stats.packets,
            stats.bytes,
            stats.first_seen,
            stats.last_seen
        );
    }
}
