```c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <net/if.h>
#include <netinet/in.h>
#include <poll.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <unistd.h>

#define RING_BLOCK_SIZE   (1 << 20)   // 1 MiB
#define RING_BLOCK_NR     64
#define RING_FRAME_SIZE   2048
#define RING_FRAME_NR     ((RING_BLOCK_SIZE * RING_BLOCK_NR) / RING_FRAME_SIZE)

#define FLOW_TABLE_SIZE   (1 << 20)   // must be power of two
#define REPORT_INTERVAL_S  5

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t  proto;
    uint8_t  pad[3];
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ns;
    uint64_t last_ns;
    uint8_t used;
} flow_entry_t;

static flow_entry_t *flow_table;

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint64_t hash_flow(const flow_key_t *k) {
    // simple fast hash
    uint64_t x = 1469598103934665603ULL;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        x ^= p[i];
        x *= 1099511628211ULL;
    }
    return x;
}

static inline int key_eq(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static flow_entry_t *flow_lookup_or_insert(const flow_key_t *k) {
    uint64_t h = hash_flow(k);
    uint32_t idx = (uint32_t)h & (FLOW_TABLE_SIZE - 1);

    for (;;) {
        flow_entry_t *e = &flow_table[idx];
        if (!e->used) {
            e->used = 1;
            e->key = *k;
            e->packets = 0;
            e->bytes = 0;
            e->first_ns = now_ns();
            e->last_ns = e->first_ns;
            return e;
        }
        if (key_eq(&e->key, k)) {
            return e;
        }
        idx = (idx + 1) & (FLOW_TABLE_SIZE - 1);
    }
}

static void report_flows(void) {
    printf("\n=== Flow report ===\n");
    for (size_t i = 0; i < FLOW_TABLE_SIZE; i++) {
        flow_entry_t *e = &flow_table[i];
        if (!e->used || e->packets == 0) continue;

        struct in_addr s, d;
        s.s_addr = e->key.src_ip;
        d.s_addr = e->key.dst_ip;

        char sbuf[INET_ADDRSTRLEN];
        char dbuf[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &s, sbuf, sizeof(sbuf));
        inet_ntop(AF_INET, &d, dbuf, sizeof(dbuf));

        printf("%s:%u -> %s:%u proto=%u pkts=%llu bytes=%llu\n",
               sbuf, ntohs(e->key.src_port),
               dbuf, ntohs(e->key.dst_port),
               e->key.proto,
               (unsigned long long)e->packets,
               (unsigned long long)e->bytes);
    }
}

static int setup_socket(const char *ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        exit(1);
    }

    int ifindex = if_nametoindex(ifname);
    if (!ifindex) {
        fprintf(stderr, "Invalid interface: %s\n", ifname);
        exit(1);
    }

    struct sockaddr_ll sll = {
        .sll_family = AF_PACKET,
        .sll_protocol = htons(ETH_P_ALL),
        .sll_ifindex = ifindex,
    };
    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        exit(1);
    }

    int ver = TPACKET_V3;
    if (setsockopt(fd, SOL_PACKET, PACKET_VERSION, &ver, sizeof(ver)) < 0) {
        perror("setsockopt PACKET_VERSION");
        exit(1);
    }

    struct tpacket_req3 req = {0};
    req.tp_block_size = RING_BLOCK_SIZE;
    req.tp_block_nr = RING_BLOCK_NR;
    req.tp_frame_size = RING_FRAME_SIZE;
    req.tp_frame_nr = RING_FRAME_NR;
    req.tp_retire_blk_tov = 60; // ms
    req.tp_feature_req_word = TP_FT_REQ_FILL_RXHASH;

    if (setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req)) < 0) {
        perror("setsockopt PACKET_RX_RING");
        exit(1);
    }

    return fd;
}

static void *setup_ring(int fd, size_t *ring_size_out) {
    size_t ring_size = RING_BLOCK_SIZE * RING_BLOCK_NR;
    void *ring = mmap(NULL, ring_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, fd, 0);
    if (ring == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }
    *ring_size_out = ring_size;
    return ring;
}

static void process_packet(const uint8_t *pkt, size_t len) {
    if (len < sizeof(struct ethhdr)) return;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    if (ntohs(eth->h_proto) != ETH_P_IP) return;

    const uint8_t *ip_ptr = pkt + sizeof(struct ethhdr);
    if ((size_t)(ip_ptr - pkt) + sizeof(struct iphdr) > len) return;

    const struct iphdr *ip = (const struct iphdr *)ip_ptr;
    if (ip->version != 4) return;

    size_t ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(struct iphdr)) return;
    if ((size_t)(ip_ptr - pkt) + ip_hdr_len > len) return;

    flow_key_t key = {0};
    key.src_ip = ip->saddr;
    key.dst_ip = ip->daddr;
    key.proto = ip->protocol;

    const uint8_t *l4 = ip_ptr + ip_hdr_len;
    size_t l4_len = len - (size_t)(l4 - pkt);

    if (ip->protocol == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        key.src_port = tcp->source;
        key.dst_port = tcp->dest;
    } else if (ip->protocol == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        key.src_port = udp->source;
        key.dst_port = udp->dest;
    } else {
        return;
    }

    flow_entry_t *e = flow_lookup_or_insert(&key);
    e->packets++;
    e->bytes += len;
    e->last_ns = now_ns();
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    flow_table = aligned_alloc(64, sizeof(flow_entry_t) * FLOW_TABLE_SIZE);
    if (!flow_table) {
        perror("aligned_alloc");
        return 1;
    }
    memset(flow_table, 0, sizeof(flow_entry_t) * FLOW_TABLE_SIZE);

    int fd = setup_socket(argv[1]);
    size_t ring_size = 0;
    uint8_t *ring = setup_ring(fd, &ring_size);

    struct pollfd pfd = {
        .fd = fd,
        .events = POLLIN,
    };

    uint64_t last_report = now_ns();

    while (1) {
        int ret = poll(&pfd, 1, 100);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            break;
        }

        if (ret > 0) {
            struct tpacket_block_desc *bd;
            for (uint32_t block = 0; block < RING_BLOCK_NR; block++) {
                bd = (struct tpacket_block_desc *)(ring + (block * RING_BLOCK_SIZE));
                if (!(bd->hdr.bh1.block_status & TP_STATUS_USER))
                    continue;

                uint8_t *base = (uint8_t *)bd;
                uint32_t num_pkts = bd->hdr.bh1.num_pkts;
                uint32_t offset = bd->hdr.bh1.offset_to_first_pkt;

                for (uint32_t i = 0; i < num_pkts; i++) {
                    struct tpacket3_hdr *tp = (struct tpacket3_hdr *)(base + offset);
                    const uint8_t *pkt = (const uint8_t *)tp + tp->tp_mac;
                    size_t len = tp->tp_snaplen;
                    process_packet(pkt, len);
                    offset += tp->tp_next_offset;
                }

                bd->hdr.bh1.block_status = TP_STATUS_KERNEL;
            }
        }

        uint64_t t = now_ns();
        if (t - last_report >= (uint64_t)REPORT_INTERVAL_S * 1000000000ULL) {
            report_flows();
            last_report = t;
        }
    }

    munmap(ring, ring_size);
    close(fd);
    free(flow_table);
    return 0;
}
