// flow_analyzer.c
#define _GNU_SOURCE
#include <arpa/inet.h>
#include <errno.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <linux/if_arp.h>
#include <linux/if_vlan.h>
#include <net/ethernet.h>
#include <net/if.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <unistd.h>

#ifndef TPACKET_V3
#define TPACKET_V3 2
#endif

#define RING_FRAMES 4096
#define FRAME_SIZE   2048
#define BLOCK_SIZE   (1 << 22)   // 4 MB
#define BLOCK_NR     8

#define FLOW_TABLE_SIZE (1 << 20) // 1M entries

static volatile sig_atomic_t running = 1;

typedef struct {
    uint32_t src_ip, dst_ip;
    uint16_t src_port, dst_port;
    uint8_t proto;
    uint8_t pad[3];
} flow_key_t;

typedef struct {
    flow_key_t key;
    uint64_t packets;
    uint64_t bytes;
    uint64_t first_ns;
    uint64_t last_ns;
    int used;
} flow_entry_t;

typedef struct {
    flow_entry_t *entries;
    size_t size;
} flow_table_t;

static inline uint64_t now_ns(void) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (uint64_t)ts.tv_sec * 1000000000ULL + ts.tv_nsec;
}

static inline uint64_t hash_flow(const flow_key_t *k) {
    // Simple fast hash
    uint64_t x = 1469598103934665603ULL;
    const uint8_t *p = (const uint8_t *)k;
    for (size_t i = 0; i < sizeof(*k); i++) {
        x ^= p[i];
        x *= 1099511628211ULL;
    }
    return x;
}

static inline int flow_key_eq(const flow_key_t *a, const flow_key_t *b) {
    return memcmp(a, b, sizeof(*a)) == 0;
}

static void flow_table_init(flow_table_t *t, size_t size) {
    t->entries = calloc(size, sizeof(flow_entry_t));
    if (!t->entries) {
        perror("calloc");
        exit(1);
    }
    t->size = size;
}

static flow_entry_t *flow_table_get(flow_table_t *t, const flow_key_t *k) {
    uint64_t h = hash_flow(k);
    size_t idx = h & (t->size - 1);

    for (;;) {
        flow_entry_t *e = &t->entries[idx];
        if (!e->used) {
            e->used = 1;
            e->key = *k;
            e->packets = 0;
            e->bytes = 0;
            e->first_ns = now_ns();
            e->last_ns = e->first_ns;
            return e;
        }
        if (flow_key_eq(&e->key, k)) {
            return e;
        }
        idx = (idx + 1) & (t->size - 1);
    }
}

static void handle_sigint(int sig) {
    (void)sig;
    running = 0;
}

static int setup_socket(const char *ifname) {
    int fd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (fd < 0) {
        perror("socket");
        exit(1);
    }

    int version = TPACKET_V3;
    if (setsockopt(fd, SOL_PACKET, PACKET_VERSION, &version, sizeof(version)) < 0) {
        perror("setsockopt PACKET_VERSION");
        exit(1);
    }

    struct tpacket_req3 req = {0};
    req.tp_block_size = BLOCK_SIZE;
    req.tp_block_nr = BLOCK_NR;
    req.tp_frame_size = FRAME_SIZE;
    req.tp_frame_nr = (BLOCK_SIZE / FRAME_SIZE) * BLOCK_NR;
    req.tp_retire_blk_tov = 60; // ms

    if (setsockopt(fd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req)) < 0) {
        perror("setsockopt PACKET_RX_RING");
        exit(1);
    }

    int ifindex = if_nametoindex(ifname);
    if (!ifindex) {
        fprintf(stderr, "Invalid interface: %s\n", ifname);
        exit(1);
    }

    struct sockaddr_ll sll = {0};
    sll.sll_family = AF_PACKET;
    sll.sll_protocol = htons(ETH_P_ALL);
    sll.sll_ifindex = ifindex;

    if (bind(fd, (struct sockaddr *)&sll, sizeof(sll)) < 0) {
        perror("bind");
        exit(1);
    }

    size_t ring_size = req.tp_block_size * req.tp_block_nr;
    void *ring = mmap(NULL, ring_size, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_LOCKED, fd, 0);
    if (ring == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }

    return fd;
}

static inline void parse_packet(const uint8_t *pkt, size_t len, flow_table_t *table) {
    if (len < sizeof(struct ethhdr)) return;

    const struct ethhdr *eth = (const struct ethhdr *)pkt;
    uint16_t eth_type = ntohs(eth->h_proto);
    size_t off = sizeof(struct ethhdr);

    // VLAN tag support
    if (eth_type == ETH_P_8021Q || eth_type == ETH_P_8021AD) {
        if (len < off + 4) return;
        eth_type = ntohs(*(uint16_t *)(pkt + off + 2));
        off += 4;
    }

    if (eth_type != ETH_P_IP) return;
    if (len < off + sizeof(struct iphdr)) return;

    const struct iphdr *ip = (const struct iphdr *)(pkt + off);
    if (ip->version != 4) return;

    size_t ip_hlen = ip->ihl * 4;
    if (ip_hlen < sizeof(struct iphdr) || len < off + ip_hlen) return;

    uint8_t proto = ip->protocol;
    uint16_t src_port = 0, dst_port = 0;

    const uint8_t *l4 = pkt + off + ip_hlen;
    size_t l4_len = len - off - ip_hlen;

    if (proto == IPPROTO_TCP) {
        if (l4_len < sizeof(struct tcphdr)) return;
        const struct tcphdr *tcp = (const struct tcphdr *)l4;
        src_port = ntohs(tcp->source);
        dst_port = ntohs(tcp->dest);
    } else if (proto == IPPROTO_UDP) {
        if (l4_len < sizeof(struct udphdr)) return;
        const struct udphdr *udp = (const struct udphdr *)l4;
        src_port = ntohs(udp->source);
        dst_port = ntohs(udp->dest);
    } else {
        return;
    }

    flow_key_t key = {
        .src_ip = ip->saddr,
        .dst_ip = ip->daddr,
        .src_port = src_port,
        .dst_port = dst_port,
        .proto = proto
    };

    flow_entry_t *e = flow_table_get(table, &key);
    e->packets++;
    e->bytes += len;
    e->last_ns = now_ns();
}

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    flow_table_t table;
    flow_table_init(&table, FLOW_TABLE_SIZE);

    int fd = setup_socket(argv[1]);

    struct pollfd pfd = {
        .fd = fd,
        .events = POLLIN
    };

    fprintf(stderr, "Capturing on %s... Press Ctrl-C to stop.\n", argv[1]);

    uint64_t last_report = now_ns();

    while (running) {
        int ret = poll(&pfd, 1, 100);
        if (ret < 0) {
            if (errno == EINTR) continue;
            perror("poll");
            break;
        }

        // NOTE: This minimal version does not fully walk the TPACKET_V3 block state machine.
        // For a production version, iterate over blocks and packets in the ring.
        // Here we keep the skeleton minimal and focus on the flow engine.

        uint64_t now = now_ns();
        if (now - last_report > 5ULL * 1000000000ULL) {
            fprintf(stderr, "Flow table active entries:\n");
            size_t shown = 0;
            for (size_t i = 0; i < table.size && shown < 20; i++) {
                flow_entry_t *e = &table.entries[i];
                if (!e->used) continue;

                struct in_addr s = {.s_addr = e->key.src_ip};
                struct in_addr d = {.s_addr = e->key.dst_ip};

                fprintf(stderr,
                        "%s:%u -> %s:%u proto=%u pkts=%llu bytes=%llu\n",
                        inet_ntoa(s), e->key.src_port,
                        inet_ntoa(d), e->key.dst_port,
                        e->key.proto,
                        (unsigned long long)e->packets,
                        (unsigned long long)e->bytes);
                shown++;
            }
            last_report = now;
        }
    }

    close(fd);
    return 0;
}
