# Minimal working implementation

## `flow_analyzer.cpp`

```cpp
#include <pcap.h>
#include <arpa/inet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <unistd.h>

#include <cstdint>
#include <cstring>
#include <iostream>
#include <unordered_map>
#include <chrono>
#include <vector>

#pragma pack(push, 1)
struct EthHeader {
    uint8_t dst[6];
    uint8_t src[6];
    uint16_t ethertype;
};
#pragma pack(pop)

struct FlowKey {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               dst_ip == other.dst_ip &&
               src_port == other.src_port &&
               dst_port == other.dst_port &&
               proto == other.proto;
    }
};

struct FlowKeyHash {
    size_t operator()(const FlowKey& k) const noexcept {
        size_t h = 1469598103934665603ULL;
        auto mix = [&](uint64_t v) {
            h ^= v;
            h *= 1099511628211ULL;
        };
        mix(k.src_ip);
        mix(k.dst_ip);
        mix(k.src_port);
        mix(k.dst_port);
        mix(k.proto);
        return h;
    }
};

struct FlowStats {
    uint64_t packets = 0;
    uint64_t bytes = 0;
    uint64_t first_seen_ns = 0;
    uint64_t last_seen_ns = 0;
};

struct FlowEntry {
    FlowKey key;
    FlowStats stats;
};

static inline uint64_t now_ns() {
    using namespace std::chrono;
    return duration_cast<nanoseconds>(
        steady_clock::now().time_since_epoch()
    ).count();
}

static inline std::string ip_to_string(uint32_t ip) {
    struct in_addr addr;
    addr.s_addr = ip;
    char buf[INET_ADDRSTRLEN];
    inet_ntop(AF_INET, &addr, buf, sizeof(buf));
    return std::string(buf);
}

class FlowAnalyzer {
public:
    explicit FlowAnalyzer(size_t reserve_flows = 1 << 20) {
        flows_.reserve(reserve_flows);
    }

    void process_packet(const uint8_t* packet, size_t len, uint64_t ts_ns) {
        if (len < sizeof(EthHeader)) return;

        const EthHeader* eth = reinterpret_cast<const EthHeader*>(packet);
        uint16_t ethertype = ntohs(eth->ethertype);

        // IPv4 only
        if (ethertype != 0x0800) return;

        const uint8_t* ip_ptr = packet + sizeof(EthHeader);
        if (len < sizeof(EthHeader) + sizeof(iphdr)) return;

        const iphdr* ip = reinterpret_cast<const iphdr*>(ip_ptr);
        size_t ip_header_len = ip->ihl * 4;
        if (ip_header_len < sizeof(iphdr)) return;
        if (len < sizeof(EthHeader) + ip_header_len) return;

        uint8_t proto = ip->protocol;
        if (proto != IPPROTO_TCP && proto != IPPROTO_UDP) return;

        const uint8_t* l4_ptr = ip_ptr + ip_header_len;
        size_t l4_len = len - sizeof(EthHeader) - ip_header_len;

        uint16_t src_port = 0, dst_port = 0;
        if (proto == IPPROTO_TCP) {
            if (l4_len < sizeof(tcphdr)) return;
            const tcphdr* tcp = reinterpret_cast<const tcphdr*>(l4_ptr);
            src_port = ntohs(tcp->source);
            dst_port = ntohs(tcp->dest);
        } else {
            if (l4_len < sizeof(udphdr)) return;
            const udphdr* udp = reinterpret_cast<const udphdr*>(l4_ptr);
            src_port = ntohs(udp->source);
            dst_port = ntohs(udp->dest);
        }

        FlowKey key {
            ip->saddr,
            ip->daddr,
            src_port,
            dst_port,
            proto
        };

        auto it = flows_.find(key);
        if (it == flows_.end()) {
            FlowStats stats;
            stats.packets = 1;
            stats.bytes = len;
            stats.first_seen_ns = ts_ns;
            stats.last_seen_ns = ts_ns;
            flows_.emplace(key, stats);
        } else {
            it->second.packets++;
            it->second.bytes += len;
            it->second.last_seen_ns = ts_ns;
        }
    }

    void expire_flows(uint64_t now_ns, uint64_t idle_timeout_ns) {
        for (auto it = flows_.begin(); it != flows_.end(); ) {
            if (now_ns - it->second.last_seen_ns > idle_timeout_ns) {
                print_flow(it->first, it->second);
                it = flows_.erase(it);
            } else {
                ++it;
            }
        }
    }

    void flush_all() {
        for (const auto& kv : flows_) {
            print_flow(kv.first, kv.second);
        }
        flows_.clear();
    }

private:
    void print_flow(const FlowKey& key, const FlowStats& stats) {
        std::cout
            << ip_to_string(key.src_ip) << ":" << key.src_port
            << " -> "
            << ip_to_string(key.dst_ip) << ":" << key.dst_port
            << " proto=" << int(key.proto)
            << " packets=" << stats.packets
            << " bytes=" << stats.bytes
            << " first_ns=" << stats.first_seen_ns
            << " last_ns=" << stats.last_seen_ns
            << "\n";
    }

    std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flows_;
};

static void packet_handler(u_char* user, const struct pcap_pkthdr* h, const u_char* bytes) {
    auto* analyzer = reinterpret_cast<FlowAnalyzer*>(user);
    uint64_t ts_ns = uint64_t(h->ts.tv_sec) * 1000000000ULL + uint64_t(h->ts.tv_usec) * 1000ULL;
    analyzer->process_packet(bytes, h->caplen, ts_ns);
}

int main(int argc, char* argv[]) {
    const char* dev = (argc > 1) ? argv[1] : "eth0";
    char errbuf[PCAP_ERRBUF_SIZE];

    pcap_t* handle = pcap_open_live(dev, 65535, 1, 1, errbuf);
    if (!handle) {
        std::cerr << "pcap_open_live failed: " << errbuf << "\n";
        return 1;
    }

    // Optional: reduce overhead by disabling name resolution
    pcap_set_timeout(handle, 1);

    FlowAnalyzer analyzer(1 << 20);

    std::cout << "Listening on " << dev << "...\n";

    const uint64_t idle_timeout_ns = 30ULL * 1000000000ULL; // 30s

    while (true) {
        int ret = pcap_dispatch(handle, 4096, packet_handler, reinterpret_cast<u_char*>(&analyzer));
        if (ret < 0) {
            std::cerr << "pcap_dispatch error: " << pcap_geterr(handle) << "\n";
            break;
        }

        analyzer.expire_flows(now_ns(), idle_timeout_ns);
    }

    analyzer.flush_all();
    pcap_close(handle);
    return 0;
}
```

