   ========================= */
static uint16_t MovingAverage_Update(uint16_t new_sample)
{
    /* Remove oldest sample from sum */
    buffer_sum -= sensor_buffer[buffer_index];

    /* Store new sample */
    sensor_buffer[buffer_index] = new_sample;
    buffer_sum += new_sample;

    /* Advance index */
    buffer_index++;
    if (buffer_index >= SENSOR_SAMPLE_COUNT) {
        buffer_index = 0;
        buffer_filled = true;
    }

    /* Return average */
    if (buffer_filled) {
        return (uint16_t)(buffer_sum / SENSOR_SAMPLE_COUNT);
    } else {
        /* Avoid dividing by full window before it's filled */
        uint8_t count = buffer_index;
        if (count == 0) count = 1;
        return (uint16_t)(buffer_sum / count);
    }
}

