    int16_t x;
    int16_t y;
    int16_t z;
} sensor_raw_t;

typedef struct {
    float x;
    float y;
    float z;
} sensor_filt_t;

/* =========================
   Simple moving average filter
   ========================= */

#define FILTER_WINDOW 8

typedef struct {
    float buf[FILTER_WINDOW];
    uint8_t index;
    uint8_t count;
    float sum;
} moving_avg_t;

static void moving_avg_init(moving_avg_t *f)
{
    memset(f, 0, sizeof(*f));
}

static float moving_avg_update(moving_avg_t *f, float sample)
{
    if (f->count < FILTER_WINDOW) {
        f->buf[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buf[f->index];
        f->buf[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return f->sum / (float)f->count;
}

/* =========================
   Sensor driver
   ========================= */

static bool sensor_write_reg(uint8_t reg, uint8_t value)
{
    return i2c_write(SENSOR_I2C_ADDR, reg, &value, 1);
}

static bool sensor_read_reg(uint8_t reg, uint8_t *value)
{
    return i2c_read(SENSOR_I2C_ADDR, reg, value, 1);
}

static bool sensor_init(void)
{
    uint8_t id = 0;

    if (!sensor_read_reg(SENSOR_REG_WHOAMI, &id)) {
        uart_write("Sensor WHOAMI read failed\r\n");
        return false;
    }

    if (id != SENSOR_EXPECTED_ID) {
