{
    uint8_t data[6];

    if (!i2c_read(SENSOR_I2C_ADDR, SENSOR_REG_DATA, data, 6)) {
        return false;
    }

    raw->x = (int16_t)((data[0] << 8) | data[1]);
    raw->y = (int16_t)((data[2] << 8) | data[3]);
    raw->z = (int16_t)((data[4] << 8) | data[5]);

    return true;
}

