    static bool initialized = false;

    if (!initialized) {
        moving_avg_init(&fx);
        moving_avg_init(&fy);
        moving_avg_init(&fz);
        initialized = true;
    }

    sensor_filt_t out;
    out.x = moving_avg_update(&fx, (float)raw->x * SENSOR_SCALE);
    out.y = moving_avg_update(&fy, (float)raw->y * SENSOR_SCALE);
    out.z = moving_avg_update(&fz, (float)raw->z * SENSOR_SCALE);

    return out;
}

