#define THRESHOLD_LOW             25.0f

/* =========================
   Types
   ========================= */
typedef struct {
    int16_t raw_x;
    int16_t raw_y;
    int16_t raw_z;
} sensor_raw_t;

typedef struct {
    float x;
    float y;
    float z;
} sensor_processed_t;

/* =========================
   Hardware abstraction stubs
   Replace these with MCU-specific code
   ========================= */
void SystemInit(void);
void DelayMs(uint32_t ms);
void Sensor_Init(void);
bool Sensor_ReadRaw(sensor_raw_t *data);
void UART_SendString(const char *s);

/* =========================
   Processing state
   ========================= */
static sensor_processed_t filtered = {0.0f, 0.0f, 0.0f};
static bool alarm_state = false;

/* =========================
   Utility functions
   ========================= */
static float low_pass_filter(float input, float prev_output, float alpha)
{
    return (alpha * input) + ((1.0f - alpha) * prev_output);
}

static float compute_magnitude(sensor_processed_t *v)
{
    return (v->x * v->x) + (v->y * v->y) + (v->z * v->z);
}

/* Example conversion from raw ADC/sensor counts to physical units */
static float convert_raw_to_units(int16_t raw)
{
    /* Adjust this for your sensor scaling */
    return (float)raw * 0.1f;
}

static void process_sensor_data(sensor_raw_t *raw, sensor_processed_t *out)
{
    float x = convert_raw_to_units(raw->raw_x);
    float y = convert_raw_to_units(raw->raw_y);
    float z = convert_raw_to_units(raw->raw_z);

    out->x = low_pass_filter(x, filtered.x, FILTER_ALPHA);
    out->y = low_pass_filter(y, filtered.y, FILTER_ALPHA);
    out->z = low_pass_filter(z, filtered.z, FILTER_ALPHA);

    filtered = *out;
}

static void evaluate_thresholds(sensor_processed_t *data)
{
    float mag_sq = compute_magnitude(data);

    if (!alarm_state && mag_sq > (THRESHOLD_HIGH * THRESHOLD_HIGH)) {
        alarm_state = true;
        UART_SendString("ALARM: sensor value high\r\n");
    } else if (alarm_state && mag_sq < (THRESHOLD_LOW * THRESHOLD_LOW)) {
        alarm_state = false;
        UART_SendString("ALARM cleared\r\n");
    }
}

