   Utility functions
   ========================= */
static void utoa_simple(uint32_t value, char *buf)
{
    char tmp[11];
    int i = 0, j = 0;

    if (value == 0) {
        buf[0] = '0';
        buf[1] = '\0';
        return;
    }

    while (value > 0 && i < 10) {
        tmp[i++] = (char)('0' + (value % 10));
        value /= 10;
    }

    while (i > 0) {
        buf[j++] = tmp[--i];
    }
    buf[j] = '\0';
}

static void i32toa_simple(int32_t value, char *buf)
{
    if (value < 0) {
        buf[0] = '-';
        utoa_simple((uint32_t)(-value), buf + 1);
    } else {
        utoa_simple((uint32_t)value, buf);
    }
}

/* =========================
   Moving average filter
   ========================= */
typedef struct {
    uint16_t samples[MOVING_AVG_WINDOW];
    uint8_t index;
    uint8_t count;
    uint32_t sum;
} MovingAverageFilter;

static void MovingAverage_Init(MovingAverageFilter *f)
{
    for (uint8_t i = 0; i < MOVING_AVG_WINDOW; i++) {
        f->samples[i] = 0;
    }
    f->index = 0;
    f->count = 0;
    f->sum = 0;
}

static uint16_t MovingAverage_Update(MovingAverageFilter *f, uint16_t sample)
{
    if (f->count < MOVING_AVG_WINDOW) {
        f->samples[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % MOVING_AVG_WINDOW;
    return (uint16_t)(f->sum / f->count);
}

/* =========================
   Calibration
   ========================= */
typedef struct {
    int32_t offset;
    float gain;
} SensorCalibration;

static int32_t Sensor_ApplyCalibration(uint16_t raw, const SensorCalibration *cal)
{
    return (int32_t)((raw + cal->offset) * cal->gain);
}

/* =========================
   Application state
   ========================= */
typedef enum {
    SENSOR_STATE_NORMAL = 0,
    SENSOR_STATE_HIGH,
    SENSOR_STATE_LOW
} SensorState;

int main(void)
{
    SystemInit();
    UART_Init();
    Timer_Init(SENSOR_SAMPLE_PERIOD_MS);

    MovingAverageFilter filter;
    MovingAverage_Init(&filter);

    SensorCalibration cal = {
        .offset = 0,
        .gain = 1.0f
    };

    uint32_t lastSampleTime = 0;
    SensorState state = SENSOR_STATE_NORMAL;

    UART_SendString("Firmware started\r\n");

    while (1) {
        uint32_t now = millis();

        if ((now - lastSampleTime) >= SENSOR_SAMPLE_PERIOD_MS) {
            lastSampleTime = now;

            /* 1) Read raw sensor */
            uint16_t raw = Sensor_ReadRaw();

            /* 2) Filter */
            uint16_t filtered = MovingAverage_Update(&filter, raw);

            /* 3) Calibrate / process */
            int32_t calibrated = Sensor_ApplyCalibration(filtered, &cal);

            /* 4) Threshold detection */
            if (calibrated > SENSOR_THRESHOLD_HIGH) {
                state = SENSOR_STATE_HIGH;
            } else if (calibrated < SENSOR_THRESHOLD_LOW) {
                state = SENSOR_STATE_LOW;
            } else {
                state = SENSOR_STATE_NORMAL;
            }

            /* 5) Debug output */
            char buf[64];
            char rawStr[16], filtStr[16], calStr[16];

            utoa_simple(raw, rawStr);
            utoa_simple(filtered, filtStr);
            i32toa_simple(calibrated, calStr);

            UART_SendString("Raw=");
            UART_SendString(rawStr);
            UART_SendString(" Filtered=");
            UART_SendString(filtStr);
            UART_SendString(" Cal=");
            UART_SendString(calStr);
            UART_SendString(" State=");

            switch (state) {
                case SENSOR_STATE_HIGH:
                    UART_SendString("HIGH");
                    break;
                case SENSOR_STATE_LOW:
                    UART_SendString("LOW");
                    break;
                default:
                    UART_SendString("NORMAL");
                    break;
            }

            UART_SendString("\r\n");
        }

        /* Optional: sleep / low-power mode here */
    }
}
