static void int_to_str(int32_t value, char *buf, uint8_t bufSize)
{
    char temp[12];
    uint8_t i = 0, j = 0;
    bool negative = false;

    if (bufSize == 0) return;

    if (value < 0) {
        negative = true;
        value = -value;
    }

    do {
        temp[i++] = (char)('0' + (value % 10));
        value /= 10;
    } while (value > 0 && i < sizeof(temp));

    if (negative && i < sizeof(temp)) {
        temp[i++] = '-';
    }

    if (i + 1 > bufSize) {
        buf[0] = '\0';
        return;
    }

    while (i > 0) {
        buf[j++] = temp[--i];
    }
    buf[j] = '\0';
}

