    const char *prefix1 = "Raw=";
    const char *prefix2 = " Filtered=";
    const char *suffix = "\r\n";

    for (const char *p = prefix1; *p && idx < sizeof(msg) - 1; p++) msg[idx++] = *p;
    for (const char *p = rawStr; *p && idx < sizeof(msg) - 1; p++) msg[idx++] = *p;
    for (const char *p = prefix2; *p && idx < sizeof(msg) - 1; p++) msg[idx++] = *p;
    for (const char *p = filtStr; *p && idx < sizeof(msg) - 1; p++) msg[idx++] = *p;
    for (const char *p = suffix; *p && idx < sizeof(msg) - 1; p++) msg[idx++] = *p;

    msg[idx] = '\0';
    HAL_UART_Send(msg);
}

