   Data processing
   ========================= */
static int16_t sampleBuffer[SAMPLE_WINDOW];
static uint8_t sampleIndex = 0;
static uint8_t sampleCount = 0;

static int16_t movingAverage(int16_t newSample)
{
    sampleBuffer[sampleIndex] = newSample;
    sampleIndex = (sampleIndex + 1) % SAMPLE_WINDOW;

    if (sampleCount < SAMPLE_WINDOW) {
        sampleCount++;
    }

    int32_t sum = 0;
    for (uint8_t i = 0; i < sampleCount; i++) {
        sum += sampleBuffer[i];
    }

    return (int16_t)(sum / sampleCount);
}

static bool sensorInit(void)
{
    /* Example config write */
    if (!I2C_WriteRegister(SENSOR_I2C_ADDR, SENSOR_REG_CONFIG, 0x01)) {
        return false;
    }

    return true;
}

