{
    uint8_t data[2];

    if (!I2C_ReadRegister(SENSOR_I2C_ADDR, SENSOR_REG_DATA, data, 2)) {
        return false;
    }

    /* Combine bytes: big-endian example */
    *value = (int16_t)((data[0] << 8) | data[1]);
    return true;
}

static void processSample(int16_t raw)
{
    int16_t filtered = movingAverage(raw);

    char msg[96];
    snprintf(msg, sizeof(msg), "Raw=%d, Filtered=%d\r\n", raw, filtered);
    UART_SendString(msg);

    if (filtered > THRESHOLD_VALUE) {
        UART_SendString("Threshold exceeded!\r\n");
    }
}

