static bool Sensor_ReadRaw(uint16_t *raw_value)
{
    uint8_t reg = 0x00;   /* sensor data register */
    uint8_t buf[2] = {0};

    if (raw_value == NULL) {
        return false;
    }

    if (!I2C_ReadRegister(SENSOR_I2C_ADDR, reg, buf, 2)) {
        return false;
    }

    *raw_value = ((uint16_t)buf[0] << 8) | buf[1];
    return true;
}
