## Example ring buffer for samples
If you want to collect multiple samples before processing:

```c
#define SAMPLE_BUFFER_SIZE 16

static uint16_t sample_buffer[SAMPLE_BUFFER_SIZE];
static volatile uint8_t write_index = 0;
static volatile uint8_t read_index = 0;

void on_adc_sample_ready(uint16_t sample)
{
    uint8_t next = (write_index + 1) % SAMPLE_BUFFER_SIZE;
    if (next != read_index) {
        sample_buffer[write_index] = sample;
        write_index = next;
    }
}

bool get_next_sample(uint16_t *sample)
{
    if (read_index == write_index) {
        return false;
    }

    *sample = sample_buffer[read_index];
    read_index = (read_index + 1) % SAMPLE_BUFFER_SIZE;
    return true;
}
```

