 * Sensor processing state
 * ========================= */
typedef struct {
    uint16_t raw;
    uint16_t filtered;
    uint16_t calibrated;
    bool high_threshold;
    bool low_threshold;
} SensorData_t;

static SensorData_t g_sensorData;

/* Moving average filter */
static uint16_t filter_buffer[FILTER_WINDOW_SIZE];
static uint8_t filter_index = 0;
static uint32_t filter_sum = 0;
static uint8_t filter_count = 0;

/* Calibration parameters */
static int16_t sensor_offset = 0;
static float sensor_scale = 1.0f;

/* =========================
 * Utility functions
 * ========================= */
static uint16_t apply_calibration(uint16_t raw)
{
    int32_t value = (int32_t)raw + sensor_offset;
    if (value < 0) value = 0;
    value = (int32_t)((float)value * sensor_scale);
    if (value > 65535) value = 65535;
    return (uint16_t)value;
}

static uint16_t moving_average_filter(uint16_t sample)
{
    filter_sum -= filter_buffer[filter_index];
    filter_buffer[filter_index] = sample;
    filter_sum += sample;

    filter_index = (filter_index + 1) % FILTER_WINDOW_SIZE;

    if (filter_count < FILTER_WINDOW_SIZE) {
        filter_count++;
    }

    return (uint16_t)(filter_sum / filter_count);
}

static void process_sensor_data(void)
{
    uint16_t raw = ADC_ReadRaw();
    uint16_t calibrated = apply_calibration(raw);
    uint16_t filtered = moving_average_filter(calibrated);

    g_sensorData.raw = raw;
    g_sensorData.calibrated = calibrated;
    g_sensorData.filtered = filtered;
    g_sensorData.high_threshold = (filtered >= SENSOR_THRESHOLD_HIGH);
    g_sensorData.low_threshold  = (filtered <= SENSOR_THRESHOLD_LOW);
}

static void report_sensor_data(void)
{
