{
    const int samples = 32;
    uint32_t sum = 0;

    for (int i = 0; i < samples; i++) {
        sum += ADC_ReadRaw();
        delay_ms(5);
    }

    uint16_t baseline = (uint16_t)(sum / samples);

    /* Example: set offset so baseline maps near zero */
    sensor_offset = -(int16_t)baseline;
    sensor_scale = 1.0f;
}

/* =========================
 * Main
 * ========================= */
int main(void)
{
    SystemClock_Config();
    GPIO_Init();
    ADC_Init();

    /* Initialize filter buffer */
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        filter_buffer[i] = 0;
    }

    calibrate_sensor();

    uint32_t last_sample_time = 0;

    while (1) {
        uint32_t now = millis();

        if ((now - last_sample_time) >= SENSOR_SAMPLE_PERIOD_MS) {
            last_sample_time = now;

            process_sensor_data();
            report_sensor_data();

            /* Example actions based on thresholds */
            if (g_sensorData.high_threshold) {
                /* Turn on indicator / trigger event */
            } else if (g_sensorData.low_threshold) {
                /* Handle low condition */
            }
        }

        /* Optional low-power wait or background tasks */
    }

    return 0;
}
