## `processing.c`
```c
#include "processing.h"

#define MOVING_AVG_WINDOW 8

static float samples[MOVING_AVG_WINDOW];
static uint8_t index_pos = 0;
static uint8_t count = 0;

void processing_init(void)
{
    for (uint8_t i = 0; i < MOVING_AVG_WINDOW; i++) {
        samples[i] = 0.0f;
    }
    index_pos = 0;
    count = 0;
}

float apply_calibration(float raw, calibration_t *cal)
{
    if (cal == 0) {
        return raw;
    }
    return (raw + cal->offset) * cal->scale;
}

float moving_average(float new_sample)
{
    samples[index_pos] = new_sample;
    index_pos = (index_pos + 1) % MOVING_AVG_WINDOW;

    if (count < MOVING_AVG_WINDOW) {
        count++;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < count; i++) {
        sum += samples[i];
    }

    return sum / (float)count;
}

bool threshold_exceeded(float value, float threshold)
{
    return value > threshold;
}
