/* Moving average filter buffer */
static uint16_t g_filterBuffer[FILTER_WINDOW_SIZE];
static uint8_t g_filterIndex = 0;
static uint32_t g_filterSum = 0;
static uint8_t g_filterCount = 0;

/* =========================
 * Filter function
 * ========================= */
static uint16_t Sensor_FilterMovingAverage(uint16_t sample)
{
    /* Remove oldest sample from sum */
    if (g_filterCount == FILTER_WINDOW_SIZE) {
        g_filterSum -= g_filterBuffer[g_filterIndex];
    } else {
        g_filterCount++;
    }

    /* Add new sample */
    g_filterBuffer[g_filterIndex] = sample;
    g_filterSum += sample;

    /* Advance circular index */
    g_filterIndex++;
    if (g_filterIndex >= FILTER_WINDOW_SIZE) {
        g_filterIndex = 0;
    }

    return (uint16_t)(g_filterSum / g_filterCount);
}

/* =========================
 * Sensor processing
 * ========================= */
