{
    uint16_t raw = ADC_ReadRaw();
    uint16_t filtered = Sensor_FilterMovingAverage(raw);

    g_sensorData.raw = raw;
    g_sensorData.filtered = filtered;

    g_sensorData.high_threshold = (filtered >= SENSOR_THRESHOLD_HIGH);
    g_sensorData.low_threshold  = (filtered <= SENSOR_THRESHOLD_LOW);

    if (g_sensorData.high_threshold || g_sensorData.low_threshold) {
        ProcessSensorEvent(filtered);
    }
}

