#define SENSOR_MAX_RAW             4095

/* Example calibration values */
#define SENSOR_OFFSET              0.0f
#define SENSOR_SCALE               1.0f

/* Thresholds in processed units */
#define SENSOR_THRESHOLD_HIGH      75.0f
#define SENSOR_THRESHOLD_LOW       10.0f

/* =========================
 * Hardware abstraction stubs
 * Replace with MCU-specific code
