    uint16_t raw;
    float filtered;
    float processed;
    bool valid;
} SensorData_t;

static SensorData_t g_sensor = {0};
static float g_filter_state = 0.0f;
static bool g_filter_initialized = false;

/* =========================
 * Processing functions
 * ========================= */
static float apply_low_pass_filter(float input)
{
    if (!g_filter_initialized) {
        g_filter_state = input;
        g_filter_initialized = true;
        return g_filter_state;
    }

    g_filter_state = (FILTER_ALPHA * input) + ((1.0f - FILTER_ALPHA) * g_filter_state);
    return g_filter_state;
}

static float calibrate_sensor(float raw_value)
{
    return (raw_value * SENSOR_SCALE) + SENSOR_OFFSET;
}

static void process_sensor_sample(void)
{
    uint16_t raw = Sensor_ReadRaw();

    if (raw < SENSOR_MIN_RAW || raw > SENSOR_MAX_RAW) {
        g_sensor.valid = false;
        return;
    }

    g_sensor.raw = raw;
    g_sensor.filtered = apply_low_pass_filter((float)raw);
    g_sensor.processed = calibrate_sensor(g_sensor.filtered);
    g_sensor.valid = true;
}

static void handle_sensor_events(void)
{
    if (!g_sensor.valid) {
        UART_Print("Sensor error or invalid reading\r\n");
        return;
    }

    if (g_sensor.processed > SENSOR_THRESHOLD_HIGH) {
        UART_Print("Warning: sensor above high threshold\r\n");
    } else if (g_sensor.processed < SENSOR_THRESHOLD_LOW) {
        UART_Print("Warning: sensor below low threshold\r\n");
    }
}

