typedef struct {
    uint16_t samples[FILTER_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    uint32_t sum;
} moving_average_t;

static void moving_average_init(moving_average_t *f)
{
    f->index = 0;
    f->count = 0;
    f->sum = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->samples[i] = 0;
    }
}

static uint16_t moving_average_update(moving_average_t *f, uint16_t sample)
{
    if (f->count < FILTER_WINDOW_SIZE) {
        f->samples[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW_SIZE;
    return (uint16_t)(f->sum / f->count);
}

