// Minimal sensor-reading firmware
// Works on Arduino-compatible boards

const int SENSOR_PIN = A0;
const int NUM_SAMPLES = 10;

int samples[NUM_SAMPLES];
int sampleIndex = 0;
long sampleSum = 0;

void setup() {
  Serial.begin(9600);
  pinMode(SENSOR_PIN, INPUT);

  // Initialize sample buffer
  for (int i = 0; i < NUM_SAMPLES; i++) {
    samples[i] = 0;
  }
}

int readSensor() {
  return analogRead(SENSOR_PIN);
}

int movingAverage(int newValue) {
  sampleSum -= samples[sampleIndex];
  samples[sampleIndex] = newValue;
  sampleSum += newValue;

  sampleIndex = (sampleIndex + 1) % NUM_SAMPLES;

  return sampleSum / NUM_SAMPLES;
}

void loop() {
  int rawValue = readSensor();
  int filteredValue = movingAverage(rawValue);

  Serial.print("Raw: ");
  Serial.print(rawValue);
  Serial.print(" | Filtered: ");
  Serial.println(filteredValue);

  delay(100);
}
```

