```c
#include <stdint.h>
#include <stdbool.h>

#define FILTER_SIZE 8

// ---- Hardware abstraction placeholders ----
void SystemInit(void);
void UART_Init(void);
void UART_SendString(const char *s);
uint16_t Sensor_ReadRaw(void);
void DelayMs(uint32_t ms);

// ---- Simple moving average filter ----
static uint16_t filter_buffer[FILTER_SIZE];
static uint8_t filter_index = 0;
static uint32_t filter_sum = 0;
static bool filter_filled = false;

uint16_t filter_update(uint16_t sample)
{
    filter_sum -= filter_buffer[filter_index];
    filter_buffer[filter_index] = sample;
    filter_sum += sample;

    filter_index = (filter_index + 1) % FILTER_SIZE;

    if (filter_index == 0) {
        filter_filled = true;
    }

    if (filter_filled) {
        return (uint16_t)(filter_sum / FILTER_SIZE);
    } else {
        return (uint16_t)(filter_sum / filter_index);
    }
}

int main(void)
{
    SystemInit();
    UART_Init();

    UART_SendString("Firmware start\r\n");

    while (1)
    {
        uint16_t raw = Sensor_ReadRaw();
        uint16_t filtered = filter_update(raw);

        char msg[64];
        // Minimal integer-to-string formatting
        // Replace with snprintf if available in your environment
        int n = 0;
        msg[n++] = 'R'; msg[n++] = 'a'; msg[n++] = 'w'; msg[n++] = ':';
        msg[n++] = ' ';

        // crude decimal conversion
        uint16_t value = raw;
        char temp[6];
        int i = 0;
        do {
            temp[i++] = '0' + (value % 10);
            value /= 10;
        } while (value > 0);

        while (i > 0) {
            msg[n++] = temp[--i];
        }

        msg[n++] = ' ';
        msg[n++] = 'F'; msg[n++] = 'i'; msg[n++] = 'l'; msg[n++] = 't';
        msg[n++] = ':';
        msg[n++] = ' ';

        value = filtered;
        i = 0;
        do {
            temp[i++] = '0' + (value % 10);
            value /= 10;
        } while (value > 0);

        while (i > 0) {
            msg[n++] = temp[--i];
        }

        msg[n++] = '\r';
        msg[n++] = '\n';
        msg[n] = '\0';

        UART_SendString(msg);

        DelayMs(100);
    }
}
```

