#include "main.h"
#include <stdio.h>
#include <string.h>

ADC_HandleTypeDef hadc1;
UART_HandleTypeDef huart2;

#define FILTER_SIZE 8

static uint16_t samples[FILTER_SIZE];
static uint8_t sample_index = 0;
static uint32_t sample_sum = 0;

void SystemClock_Config(void);
static void MX_GPIO_Init(void);
static void MX_ADC1_Init(void);
static void MX_USART2_UART_Init(void);

static uint16_t Read_ADC(void);
static uint16_t MovingAverage(uint16_t new_sample);
static void UART_Print(const char *msg);

int main(void)
{
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    MX_ADC1_Init();
    MX_USART2_UART_Init();

    memset(samples, 0, sizeof(samples));

    char buffer[64];

    while (1)
    {
        uint16_t raw = Read_ADC();
        uint16_t filtered = MovingAverage(raw);

        snprintf(buffer, sizeof(buffer), "Raw: %u, Filtered: %u\r\n", raw, filtered);
        UART_Print(buffer);

        HAL_Delay(500);
    }
}

static uint16_t Read_ADC(void)
{
    HAL_ADC_Start(&hadc1);
    HAL_ADC_PollForConversion(&hadc1, HAL_MAX_DELAY);
    uint16_t value = (uint16_t)HAL_ADC_GetValue(&hadc1);
    HAL_ADC_Stop(&hadc1);
    return value;
}

static uint16_t MovingAverage(uint16_t new_sample)
{
    sample_sum -= samples[sample_index];
    samples[sample_index] = new_sample;
    sample_sum += new_sample;

    sample_index = (sample_index + 1) % FILTER_SIZE;

    return (uint16_t)(sample_sum / FILTER_SIZE);
}

static void UART_Print(const char *msg)
{
    HAL_UART_Transmit(&huart2, (uint8_t *)msg, strlen(msg), HAL_MAX_DELAY);
}

