template <typename T>
T clamp(T v, T lo, T hi) {
    return std::max(lo, std::min(v, hi));
}

using Clock = std::chrono::steady_clock;
using Seconds = std::chrono::duration<double>;

// -----------------------------
// Sensor data
// -----------------------------
struct IMUData {
    double accel_x;   // m/s^2
    double accel_y;
    double accel_z;
    double gyro_x;    // rad/s
    double gyro_y;
    double gyro_z;
    bool valid;
};

