    int32_t ticks_left;
    int32_t ticks_right;
    bool valid;
};

struct SensorPacket {
    IMUData imu;
    EncoderData enc;
    double timestamp; // seconds
};

// -----------------------------
// State estimate
// -----------------------------
struct RobotState {
    double roll;      // rad
    double pitch;     // rad
    double yaw;       // rad
    double vel_left;  // m/s
    double vel_right; // m/s
    double x;         // m
    double y;         // m
