};

// -----------------------------
// Sensor fusion
// Complementary filter for roll/pitch
// -----------------------------
class SensorFusion {
public:
    RobotState update(const SensorPacket& s, double dt) {
        RobotState out = state_;

        if (s.imu.valid && dt > 1e-6) {
            // Accelerometer-based roll/pitch
            double ax = s.imu.accel_x;
            double ay = s.imu.accel_y;
            double az = s.imu.accel_z;

            double accel_roll  = std::atan2(ay, az);
            double accel_pitch = std::atan2(-ax, std::sqrt(ay * ay + az * az));

            // Gyro integration
            out.roll  = alpha_ * (out.roll  + s.imu.gyro_x * dt) + (1.0 - alpha_) * accel_roll;
            out.pitch = alpha_ * (out.pitch + s.imu.gyro_y * dt) + (1.0 - alpha_) * accel_pitch;
            out.yaw  += s.imu.gyro_z * dt;
        }

        if (s.enc.valid && dt > 1e-6) {
            // Simple differential drive velocity estimate
            constexpr double ticks_per_rev = 2048.0;
            constexpr double wheel_radius = 0.05; // m
            constexpr double gear_ratio = 1.0;

            double rev_left  = (s.enc.ticks_left  - prev_ticks_left_)  / (ticks_per_rev * gear_ratio);
            double rev_right = (s.enc.ticks_right - prev_ticks_right_) / (ticks_per_rev * gear_ratio);

            double dist_left  = rev_left  * 2.0 * M_PI * wheel_radius;
            double dist_right = rev_right * 2.0 * M_PI * wheel_radius;

            out.vel_left  = dist_left / dt;
            out.vel_right = dist_right / dt;

            // Basic dead-reckoning
            double v = 0.5 * (out.vel_left + out.vel_right);
            double heading = out.yaw;
            out.x += v * std::cos(heading) * dt;
            out.y += v * std::sin(heading) * dt;

            prev_ticks_left_ = s.enc.ticks_left;
            prev_ticks_right_ = s.enc.ticks_right;
        }

        state_ = out;
        return out;
    }

    void reset() {
        state_ = {};
        prev_ticks_left_ = 0;
        prev_ticks_right_ = 0;
    }

private:
    RobotState state_{};
    int32_t prev_ticks_left_ = 0;
    int32_t prev_ticks_right_ = 0;
    double alpha_ = 0.98; // gyro trust
};

// -----------------------------
// Main control loop
// -----------------------------
int main() {
    SensorInterface sensors;
    MotorInterface motors;
    SensorFusion fusion;

    // Example: control wheel speed to target velocity
    PID left_pid(2.0, 0.5, 0.02, -1.0, 1.0);
    PID right_pid(2.0, 0.5, 0.02, -1.0, 1.0);
    left_pid.setIntegralLimit(10.0);
    right_pid.setIntegralLimit(10.0);

    constexpr double loop_hz = 100.0;
    constexpr double dt_target = 1.0 / loop_hz;

    double target_left_vel = 0.5;   // m/s
    double target_right_vel = 0.5;  // m/s

    auto next_tick = Clock::now();

    for (int i = 0; i < 1000; ++i) {
        next_tick += std::chrono::duration_cast<Clock::duration>(Seconds(dt_target));

        auto loop_start = Clock::now();

        // 1) Read sensors
        SensorPacket packet = sensors.read();

        // 2) Compute actual dt
        static auto last_time = Clock::now();
        auto now = Clock::now();
        double dt = std::chrono::duration<double>(now - last_time).count();
        last_time = now;

        // 3) Fuse sensor data
        RobotState state = fusion.update(packet, dt);

        // 4) Compute control outputs
        double left_cmd = left_pid.update(target_left_vel, state.vel_left, dt);
        double right_cmd = right_pid.update(target_right_vel, state.vel_right, dt);

        // 5) Send motor commands
        motors.setPWM(left_cmd, right_cmd);

        // 6) Safety checks
        if (!packet.imu.valid || !packet.enc.valid) {
            std::cerr << "Sensor fault detected, stopping motors.\n";
            motors.stop();
            left_pid.reset();
            right_pid.reset();
            fusion.reset();
        }

        // 7) Maintain fixed loop rate
        auto loop_end = Clock::now();
        auto elapsed = loop_end - loop_start;

        if (Clock::now() < next_tick) {
            std::this_thread::sleep_until(next_tick);
        } else {
            std::cerr << "Warning: control loop overran deadline.\n";
            next_tick = Clock::now();
        }

        // Debug output
        std::cout << "State: x=" << state.x
                  << " y=" << state.y
                  << " yaw=" << state.yaw
                  << " vL=" << state.vel_left
                  << " vR=" << state.vel_right
                  << "\n";
    }

    motors.stop();
    return 0;
}
