Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accelerometer samples
- applies a simple low-pass filter
- computes signal magnitude
- maintains a rolling baseline
- flags anomalies when the current magnitude deviates too far from the baseline

It is designed to be lightweight for MCU use: no dynamic allocation, no floating-point requirement if you prefer fixed-point later, and small state.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detector
 * - Input: raw accelerometer samples (x, y, z)
 * - Output: anomaly flag
 *
 * Assumptions:
 * - Sample rate is fixed and known
 * - Units are consistent (e.g., mg or m/s^2)
 * - Gravity is present in the signal; baseline adapts to normal motion
 */

#define LPF_ALPHA_NUM   1   // low-pass filter alpha = 1/8
#define LPF_ALPHA_DEN   8

#define BASELINE_ALPHA_NUM  1  // baseline update alpha = 1/64
#define BASELINE_ALPHA_DEN  64

#define WINDOW_SIZE  32

typedef struct {
    float lpf_x;
    float lpf_y;
    float lpf_z;

    float baseline_mag;
    float mag_history[WINDOW_SIZE];
    uint8_t hist_idx;
    uint8_t hist_count;

    float anomaly_threshold;   // absolute deviation threshold
    float zscore_threshold;     // optional normalized threshold
    float variance;
} accel_anomaly_detector_t;

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

void accel_detector_init(accel_anomaly_detector_t *d,
                         float initial_baseline_mag,
                         float anomaly_threshold,
                         float zscore_threshold)
{
    d->lpf_x = 0.0f;
    d->lpf_y = 0.0f;
    d->lpf_z = 0.0f;

    d->baseline_mag = initial_baseline_mag;
    d->hist_idx = 0;
    d->hist_count = 0;
    d->variance = 0.0f;

    d->anomaly_threshold = anomaly_threshold;
    d->zscore_threshold = zscore_threshold;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->mag_history[i] = initial_baseline_mag;
    }
}

/*
 * Update rolling variance using a simple windowed recomputation.
 * For very small MCUs, you may replace this with an EWMA variance.
 */
static void recompute_variance(accel_anomaly_detector_t *d)
{
    if (d->hist_count < 2) {
        d->variance = 0.0f;
        return;
    }

    float mean = 0.0f;
    for (uint8_t i = 0; i < d->hist_count; i++) {
        mean += d->mag_history[i];
    }
    mean /= (float)d->hist_count;

    float var = 0.0f;
    for (uint8_t i = 0; i < d->hist_count; i++) {
        float diff = d->mag_history[i] - mean;
        var += diff * diff;
    }
    var /= (float)(d->hist_count - 1);

    d->variance = var;
}

/*
 * Process one accelerometer sample.
 * Returns true if anomaly detected.
 */
bool accel_detector_process(accel_anomaly_detector_t *d,
                            float raw_x, float raw_y, float raw_z,
                            float *out_mag,
                            float *out_baseline,
                            float *out_score)
{
    // 1) Low-pass filter
    d->lpf_x += ((raw_x - d->lpf_x) * (float)LPF_ALPHA_NUM) / (float)LPF_ALPHA_DEN;
    d->lpf_y += ((raw_y - d->lpf_y) * (float)LPF_ALPHA_NUM) / (float)LPF_ALPHA_DEN;
    d->lpf_z += ((raw_z - d->lpf_z) * (float)LPF_ALPHA_NUM) / (float)LPF_ALPHA_DEN;

    // 2) Magnitude
    float mag = fast_sqrtf(d->lpf_x * d->lpf_x +
                           d->lpf_y * d->lpf_y +
                           d->lpf_z * d->lpf_z);

    // 3) Update history
    d->mag_history[d->hist_idx] = mag;
    d->hist_idx = (d->hist_idx + 1) % WINDOW_SIZE;
    if (d->hist_count < WINDOW_SIZE) {
        d->hist_count++;
    }

    // 4) Update baseline slowly
    d->baseline_mag += ((mag - d->baseline_mag) * (float)BASELINE_ALPHA_NUM) / (float)BASELINE_ALPHA_DEN;

    // 5) Recompute variance for normalized scoring
    recompute_variance(d);

    // 6) Compute anomaly score
    float deviation = fast_absf(mag - d->baseline_mag);
    float stddev = (d->variance > 0.0f) ? fast_sqrtf(d->variance) : 0.0f;
    float zscore = (stddev > 1e-6f) ? (deviation / stddev) : 0.0f;

    if (out_mag) {
        *out_mag = mag;
    }
    if (out_baseline) {
        *out_baseline = d->baseline_mag;
    }
    if (out_score) {
        *out_score = zscore;
    }

    // 7) Decision logic
    bool anomaly = false;

    // Absolute deviation trigger
    if (deviation > d->anomaly_threshold) {
        anomaly = true;
    }

    // Normalized trigger
    if (zscore > d->zscore_threshold) {
        anomaly = true;
    }

    return anomaly;
}
```

