Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accelerometer samples
- applies a simple low-pass filter
- computes magnitude and rolling statistics
- flags anomalies when the current signal deviates significantly from the recent baseline

It is designed to be lightweight for microcontrollers.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE     32
#define LPF_ALPHA       0.2f
#define ANOMALY_ZTHRESH 3.0f
#define MIN_STDDEV      0.05f

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float lpf_x, lpf_y, lpf_z;
    bool initialized;
} lpf_state_t;

typedef struct {
    float buf[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;
    float sum;
    float sumsq;
} rolling_stats_t;

typedef struct {
    lpf_state_t lpf;
    rolling_stats_t mag_stats;
} anomaly_detector_t;

static void rolling_stats_init(rolling_stats_t *s) {
    s->idx = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        s->buf[i] = 0.0f;
    }
}

static void anomaly_detector_init(anomaly_detector_t *d) {
    d->lpf.initialized = false;
    d->lpf.lpf_x = d->lpf.lpf_y = d->lpf.lpf_z = 0.0f;
    rolling_stats_init(&d->mag_stats);
}

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float compute_magnitude(float x, float y, float z) {
    return fast_sqrtf(x*x + y*y + z*z);
}

static float lpf_update(lpf_state_t *s, float x, float y, float z, float *out_x, float *out_y, float *out_z) {
    if (!s->initialized) {
        s->lpf_x = x;
        s->lpf_y = y;
        s->lpf_z = z;
        s->initialized = true;
    } else {
        s->lpf_x = LPF_ALPHA * x + (1.0f - LPF_ALPHA) * s->lpf_x;
        s->lpf_y = LPF_ALPHA * y + (1.0f - LPF_ALPHA) * s->lpf_y;
        s->lpf_z = LPF_ALPHA * z + (1.0f - LPF_ALPHA) * s->lpf_z;
    }

    *out_x = s->lpf_x;
    *out_y = s->lpf_y;
    *out_z = s->lpf_z;

    return compute_magnitude(*out_x, *out_y, *out_z);
}

static void rolling_stats_update(rolling_stats_t *s, float value) {
    if (s->count < WINDOW_SIZE) {
        s->buf[s->idx] = value;
        s->sum += value;
        s->sumsq += value * value;
        s->idx = (s->idx + 1) % WINDOW_SIZE;
        s->count++;
    } else {
        float old = s->buf[s->idx];
        s->sum -= old;
        s->sumsq -= old * old;

        s->buf[s->idx] = value;
        s->sum += value;
        s->sumsq += value * value;
        s->idx = (s->idx + 1) % WINDOW_SIZE;
    }
}

static void rolling_stats_get(const rolling_stats_t *s, float *mean, float *stddev) {
    if (s->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    *mean = s->sum / (float)s->count;

    float var = (s->sumsq / (float)s->count) - (*mean * *mean);
    if (var < 0.0f) var = 0.0f;
    *stddev = fast_sqrtf(var);
}

static bool anomaly_detector_process(anomaly_detector_t *d, accel_sample_t sample) {
    float fx, fy, fz;
    float mag = lpf_update(&d->lpf, sample.x, sample.y, sample.z, &fx, &fy, &fz);

    // Warm-up period: collect baseline before flagging anomalies
    if (d->mag_stats.count < WINDOW_SIZE) {
        rolling_stats_update(&d->mag_stats, mag);
        return false;
    }

    float mean, stddev;
    rolling_stats_get(&d->mag_stats, &mean, &stddev);

    float deviation = fabsf(mag - mean);
    bool anomaly = (stddev >= MIN_STDDEV) && (deviation > ANOMALY_ZTHRESH * stddev);

    rolling_stats_update(&d->mag_stats, mag);
    return anomaly;
}

/* Example usage */
int main(void) {
    anomaly_detector_t detector;
    anomaly_detector_init(&detector);

    // Replace this with real sensor reads
    accel_sample_t stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.02f, 0.01f, 0.99f},
        {0.00f, 0.03f, 1.01f},
        {0.50f, 0.80f, 1.90f}, // possible anomaly
    };

    for (unsigned i = 0; i < sizeof(stream)/sizeof(stream[0]); i++) {
        bool anomaly = anomaly_detector_process(&detector, stream[i]);
        if (anomaly) {
            // Handle anomaly: log, raise interrupt, send packet, etc.
            // printf("Anomaly detected at sample %u\n", i);
        }
    }

    return 0;
}
