Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accelerometer samples
- applies a simple low-pass filter
- computes magnitude and short-window features
- maintains a running baseline
- flags anomalies when the current window deviates significantly from baseline

It is designed to be:
- fixed-memory
- integer-friendly
- easy to port to bare-metal or RTOS environments

---

## C code

```c
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detector
 * - 3-axis input: ax, ay, az
 * - low-pass filter
 * - sliding window feature extraction
 * - baseline mean/variance tracking
 * - anomaly decision based on z-score-like threshold
 */

#define WINDOW_SIZE        32
#define BASELINE_ALPHA_NUM  1   // baseline update rate numerator
#define BASELINE_ALPHA_DEN  64  // baseline update rate denominator

#define LPF_ALPHA_NUM       1
#define LPF_ALPHA_DEN       8

#define ANOMALY_Z_THRESHOLD 4.0f
#define MIN_BASELINE_SAMPLES 100

typedef struct {
    int32_t x;
    int32_t y;
    int32_t z;
} accel_raw_t;

typedef struct {
    float x;
    float y;
    float z;
} accel_filt_t;

typedef struct {
    accel_filt_t buf[WINDOW_SIZE];
    uint32_t idx;
    uint32_t count;
    float sum_mag;
    float sum_mag2;
} feature_window_t;

typedef struct {
    float mean;
    float m2;
    uint32_t n;
} running_stats_t;

typedef struct {
    accel_filt_t lpf_state;
    feature_window_t win;
    running_stats_t baseline;
    bool initialized;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float vec_mag(const accel_filt_t *v) {
    return fast_sqrtf(v->x * v->x + v->y * v->y + v->z * v->z);
}

static float lpf_update(float prev, float input) {
    // y[n] = y[n-1] + alpha * (x[n] - y[n-1])
    const float alpha = (float)LPF_ALPHA_NUM / (float)LPF_ALPHA_DEN;
    return prev + alpha * (input - prev);
}

static void running_stats_init(running_stats_t *s) {
    s->mean = 0.0f;
    s->m2 = 0.0f;
    s->n = 0;
}

static void running_stats_update(running_stats_t *s, float x) {
    s->n++;
    float delta = x - s->mean;
    s->mean += delta / (float)s->n;
    float delta2 = x - s->mean;
    s->m2 += delta * delta2;
}

static float running_stats_variance(const running_stats_t *s) {
    if (s->n < 2) return 0.0f;
    return s->m2 / (float)(s->n - 1);
}

static void feature_window_init(feature_window_t *w) {
    memset(w, 0, sizeof(*w));
}

static void anomaly_detector_init(anomaly_detector_t *d) {
    memset(d, 0, sizeof(*d));
    feature_window_init(&d->win);
    running_stats_init(&d->baseline);
    d->initialized = false;
}

static void feature_window_push(feature_window_t *w, const accel_filt_t *sample) {
    if (w->count < WINDOW_SIZE) {
        w->buf[w->idx] = *sample;
        w->count++;
        w->idx = (w->idx + 1) % WINDOW_SIZE;
        return;
    }

    w->buf[w->idx] = *sample;
    w->idx = (w->idx + 1) % WINDOW_SIZE;
}

static bool feature_window_full(const feature_window_t *w) {
    return w->count >= WINDOW_SIZE;
}

static void compute_window_features(const feature_window_t *w, float *mean_mag, float *std_mag) {
    float sum = 0.0f;
    float sum2 = 0.0f;

    for (uint32_t i = 0; i < w->count; i++) {
        float mag = vec_mag(&w->buf[i]);
        sum += mag;
        sum2 += mag * mag;
    }

    *mean_mag = sum / (float)w->count;
    float var = (sum2 / (float)w->count) - (*mean_mag * *mean_mag);
    if (var < 0.0f) var = 0.0f;
    *std_mag = fast_sqrtf(var);
}

/*
 * Process one raw accelerometer sample.
 *
 * Returns true if anomaly is detected.
 * During startup, detector learns baseline and will not flag anomalies
 * until enough samples are collected.
 */
bool anomaly_detector_process(anomaly_detector_t *d, const accel_raw_t *raw) {
    // Convert raw counts to filtered float values.
    // If you know sensor scale, replace with proper g or m/s^2 conversion.
    accel_filt_t in = {
        .x = (float)raw->x,
        .y = (float)raw->y,
        .z = (float)raw->z
    };

    if (!d->initialized) {
        d->lpf_state = in;
        d->initialized = true;
    } else {
        d->lpf_state.x = lpf_update(d->lpf_state.x, in.x);
        d->lpf_state.y = lpf_update(d->lpf_state.y, in.y);
        d->lpf_state.z = lpf_update(d->lpf_state.z, in.z);
    }

    feature_window_push(&d->win, &d->lpf_state);

    if (!feature_window_full(&d->win)) {
        return false;
    }

    float mean_mag, std_mag;
    compute_window_features(&d->win, &mean_mag, &std_mag);

    // Learn baseline during startup
    if (d->baseline.n < MIN_BASELINE_SAMPLES) {
        running_stats_update(&d->baseline, mean_mag);
        return false;
    }

    float baseline_mean = d->baseline.mean;
    float baseline_var = running_stats_variance(&d->baseline);
    float baseline_std = fast_sqrtf(baseline_var);

    // Avoid divide-by-zero
    if (baseline_std < 1e-6f) {
        baseline_std = 1e-6f;
    }

    float z = (mean_mag - baseline_mean) / baseline_std;
    if (z < 0.0f) z = -z;

    bool anomaly = (z > ANOMALY_Z_THRESHOLD);

    // Update baseline slowly only if not anomalous
    if (!anomaly) {
        float alpha = (float)BASELINE_ALPHA_NUM / (float)BASELINE_ALPHA_DEN;
        d->baseline.mean = (1.0f - alpha) * d->baseline.mean + alpha * mean_mag;

        // Simple variance tracking update
        float diff = mean_mag - d->baseline.mean;
        d->baseline.m2 = (1.0f - alpha) * d->baseline.m2 + alpha * (diff * diff);
        d->baseline.n++;
    }

    return anomaly;
}
