```c
/*
 * Embedded accelerometer anomaly detector
 * - Fixed-size, allocation-free
 * - Simple high-pass removal of gravity/DC
 * - Feature extraction over a sliding window
 * - Anomaly score based on energy + variance + jerk
 *
 * Intended for small MCUs. Adapt sample rate, thresholds, and window size
 * to your sensor and application.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

#define AXIS_COUNT          3
#define WINDOW_SIZE         32      // must be power of 2 for fast ring indexing if desired
#define SAMPLE_RATE_HZ      100.0f
#define HP_ALPHA            0.95f   // closer to 1.0 => slower DC removal
#define ENERGY_THRESH       2.5f
#define VAR_THRESH          1.2f
#define JERK_THRESH         15.0f
#define ANOMALY_SCORE_THRESH 1.0f

/* ---------------- Types ---------------- */

typedef struct {
    float x, y, z;
} vec3f_t;

typedef struct {
    vec3f_t raw;
    vec3f_t hp;        // high-pass filtered
    vec3f_t prev_hp;
    vec3f_t jerk;      // derivative of hp
    float magnitude;
} accel_sample_t;

typedef struct {
    float mag_window[WINDOW_SIZE];
    float hp_energy_window[WINDOW_SIZE];
    float jerk_window[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;
    vec3f_t prev_raw;
    vec3f_t prev_hp;
    bool initialized;
} anomaly_detector_t;

typedef struct {
    float mean_mag;
    float var_mag;
    float mean_energy;
    float mean_jerk;
    float score;
    bool anomaly;
} anomaly_result_t;

/* ---------------- Utility ---------------- */

static inline float f_absf(float x) { return (x < 0.0f) ? -x : x; }

static inline float vec3_mag(vec3f_t v) {
    return sqrtf(v.x * v.x + v.y * v.y + v.z * v.z);
}

static inline vec3f_t vec3_sub(vec3f_t a, vec3f_t b) {
    vec3f_t r = {a.x - b.x, a.y - b.y, a.z - b.z};
    return r;
}

static inline vec3f_t vec3_scale(vec3f_t v, float s) {
    vec3f_t r = {v.x * s, v.y * s, v.z * s};
    return r;
}

static inline vec3f_t vec3_add(vec3f_t a, vec3f_t b) {
    vec3f_t r = {a.x + b.x, a.y + b.y, a.z + b.z};
    return r;
}

/* ---------------- Detector API ---------------- */

void anomaly_detector_init(anomaly_detector_t *det)
{
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
        det->hp_energy_window[i] = 0.0f;
        det->jerk_window[i] = 0.0f;
    }
    det->idx = 0;
    det->count = 0;
    det->prev_raw = (vec3f_t){0.0f, 0.0f, 0.0f};
    det->prev_hp  = (vec3f_t){0.0f, 0.0f, 0.0f};
    det->initialized = false;
}

/*
 * Process one accelerometer sample.
 * Input units should be consistent (e.g., g or m/s^2).
 */
anomaly_result_t anomaly_detector_process(anomaly_detector_t *det, vec3f_t raw)
{
    anomaly_result_t out = {0};

    /* High-pass filter to remove DC/gravity */
    vec3f_t hp;
    if (!det->initialized) {
        hp = (vec3f_t){0.0f, 0.0f, 0.0f};
        det->prev_raw = raw;
        det->prev_hp = hp;
        det->initialized = true;
    } else {
        // y[n] = alpha * (y[n-1] + x[n] - x[n-1])
        vec3f_t delta = vec3_sub(raw, det->prev_raw);
        hp = vec3_scale(vec3_add(det->prev_hp, delta), HP_ALPHA);
        det->prev_raw = raw;
        det->prev_hp = hp;
    }

    /* Jerk = change in filtered acceleration */
    vec3f_t jerk_v = vec3_sub(hp, det->prev_hp);
    float jerk = vec3_mag(jerk_v) * SAMPLE_RATE_HZ;

    float mag = vec3_mag(hp);
    float energy = mag * mag;

    /* Update windows */
    det->mag_window[det->idx] = mag;
    det->hp_energy_window[det->idx] = energy;
    det->jerk_window[det->idx] = jerk;

    det->idx = (det->idx + 1) % WINDOW_SIZE;
    if (det->count < WINDOW_SIZE) det->count++;

    /* Compute features over window */
    float sum_mag = 0.0f, sum_mag2 = 0.0f;
    float sum_energy = 0.0f, sum_jerk = 0.0f;

    for (uint16_t i = 0; i < det->count; i++) {
        float m = det->mag_window[i];
        sum_mag += m;
        sum_mag2 += m * m;
        sum_energy += det->hp_energy_window[i];
        sum_jerk += det->jerk_window[i];
    }

    float n = (float)det->count;
    float mean_mag = (n > 0.0f) ? (sum_mag / n) : 0.0f;
    float var_mag = (n > 0.0f) ? ((sum_mag2 / n) - (mean_mag * mean_mag)) : 0.0f;
    float mean_energy = (n > 0.0f) ? (sum_energy / n) : 0.0f;
    float mean_jerk = (n > 0.0f) ? (sum_jerk / n) : 0.0f;

    /* Simple anomaly score */
    float score = 0.0f;
    if (mean_energy > ENERGY_THRESH) score += 0.5f;
    if (var_mag > VAR_THRESH)        score += 0.3f;
    if (mean_jerk > JERK_THRESH)     score += 0.4f;

    bool anomaly = (score >= ANOMALY_SCORE_THRESH);

    out.mean_mag = mean_mag;
    out.var_mag = var_mag;
    out.mean_energy = mean_energy;
    out.mean_jerk = mean_jerk;
    out.score = score;
    out.anomaly = anomaly;

    return out;
}

