    while (1) {
        vec3f_t sample = read_accelerometer(); // replace with your driver
        anomaly_result_t r = anomaly_detector_process(&det, sample);

        if (r.anomaly) {
            // trigger event, log, or notify
            printf("Anomaly detected: score=%.2f\n", r.score);
        }
    }
    return 0;
}
