Below is a compact embedded-friendly C example for an accelerometer anomaly-detection pipeline. It:

- reads 3-axis accelerometer samples,
- applies a simple low-pass filter,
- computes signal magnitude,
- maintains a rolling mean and variance,
- flags anomalies when the current magnitude deviates too far from the baseline.

It is written to be easy to port to bare-metal or RTOS environments.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

#define WINDOW_SIZE        32
#define ANOMALY_Z_THRESHOLD 3.0f
#define LPF_ALPHA          0.2f   // 0..1, higher = less smoothing

/* ---------------- Data Types ---------------- */

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} running_stats_t;

typedef struct {
    float x_filt;
    float y_filt;
    float z_filt;
    bool initialized;
} lpf_state_t;

typedef struct {
    float mag_window[WINDOW_SIZE];
    uint8_t index;
    uint8_t filled;
    running_stats_t stats;
    lpf_state_t lpf;
} anomaly_detector_t;

/* ---------------- Utility ---------------- */

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float vector_magnitude(const accel_sample_t *s) {
    return fast_sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/* Welford's online algorithm */
static void running_stats_init(running_stats_t *rs) {
    rs->mean = 0.0f;
    rs->m2 = 0.0f;
    rs->count = 0;
}

static void running_stats_update(running_stats_t *rs, float x) {
    rs->count++;
    float delta = x - rs->mean;
    rs->mean += delta / (float)rs->count;
    float delta2 = x - rs->mean;
    rs->m2 += delta * delta2;
}

static float running_stats_variance(const running_stats_t *rs) {
    if (rs->count < 2) return 0.0f;
    return rs->m2 / (float)(rs->count - 1);
}

static void lpf_init(lpf_state_t *s) {
    s->x_filt = 0.0f;
    s->y_filt = 0.0f;
    s->z_filt = 0.0f;
    s->initialized = false;
}

static accel_sample_t lpf_apply(lpf_state_t *s, accel_sample_t in) {
    if (!s->initialized) {
        s->x_filt = in.x;
        s->y_filt = in.y;
        s->z_filt = in.z;
        s->initialized = true;
    } else {
        s->x_filt = LPF_ALPHA * in.x + (1.0f - LPF_ALPHA) * s->x_filt;
        s->y_filt = LPF_ALPHA * in.y + (1.0f - LPF_ALPHA) * s->y_filt;
        s->z_filt = LPF_ALPHA * in.z + (1.0f - LPF_ALPHA) * s->z_filt;
    }

    accel_sample_t out = { s->x_filt, s->y_filt, s->z_filt };
    return out;
}

/* ---------------- Detector ---------------- */

void anomaly_detector_init(anomaly_detector_t *det) {
    det->index = 0;
    det->filled = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
    running_stats_init(&det->stats);
    lpf_init(&det->lpf);
}

/*
 * Returns true if anomaly detected.
 * Assumes samples arrive at a fixed rate.
 */
bool anomaly_detector_process(anomaly_detector_t *det, accel_sample_t raw) {
    /* 1) Filter */
    accel_sample_t filtered = lpf_apply(&det->lpf, raw);

    /* 2) Feature extraction */
    float mag = vector_magnitude(&filtered);

    /* 3) Update rolling window stats */
    if (det->filled < WINDOW_SIZE) {
        det->mag_window[det->index] = mag;
        det->filled++;
        running_stats_update(&det->stats, mag);
    } else {
        /* Recompute stats over the window for simplicity and robustness */
        det->mag_window[det->index] = mag;

        running_stats_init(&det->stats);
        for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
            running_stats_update(&det->stats, det->mag_window[i]);
        }
    }

    det->index = (det->index + 1) % WINDOW_SIZE;

    /* 4) Detect anomaly once window is warm */
    if (det->filled < WINDOW_SIZE) {
        return false;
    }

    float variance = running_stats_variance(&det->stats);
    float stddev = fast_sqrtf(variance);

    if (stddev < 1e-6f) {
        return false;
    }

    float z = (mag - det->stats.mean) / stddev;
    if (z > ANOMALY_Z_THRESHOLD || z < -ANOMALY_Z_THRESHOLD) {
        return true;
    }

    return false;
}
