Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It includes:

- sample ingestion
- high-pass removal of gravity/slow drift
- magnitude computation
- moving average / moving variance
- z-score anomaly detection
- simple state machine to reduce false positives

It is designed to be easy to port to bare-metal or RTOS environments.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32
#define HP_ALPHA            0.95f
#define ANOMALY_Z_THRESHOLD 3.5f
#define MIN_ANOMALY_COUNT   3
#define RECOVERY_COUNT      10

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef enum {
    PIPELINE_STATE_NORMAL = 0,
    PIPELINE_STATE_ANOMALY
} pipeline_state_t;

typedef struct {
    /* High-pass filter state */
    float hp_x;
    float hp_y;
    float hp_z;
    float lp_x;
    float lp_y;
    float lp_z;

    /* Ring buffer for magnitude */
    float mag_buf[WINDOW_SIZE];
    uint8_t mag_idx;
    uint8_t mag_count;

    /* Running statistics */
    float sum;
    float sum_sq;

    /* Detection state */
    pipeline_state_t state;
    uint8_t anomaly_streak;
    uint8_t recovery_streak;
} accel_pipeline_t;

/* =========================
 * Utility functions
 * ========================= */
static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float compute_magnitude(const accel_sample_t *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

/* =========================
 * Initialization
 * ========================= */
void accel_pipeline_init(accel_pipeline_t *p) {
    if (!p) return;

    p->hp_x = p->hp_y = p->hp_z = 0.0f;
    p->lp_x = p->lp_y = p->lp_z = 0.0f;

    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        p->mag_buf[i] = 0.0f;
    }

    p->mag_idx = 0;
    p->mag_count = 0;
    p->sum = 0.0f;
    p->sum_sq = 0.0f;

    p->state = PIPELINE_STATE_NORMAL;
    p->anomaly_streak = 0;
    p->recovery_streak = 0;
}

/* =========================
 * High-pass filter
 * Removes slow-changing component (gravity / drift)
 * ========================= */
static accel_sample_t high_pass_filter(accel_pipeline_t *p, const accel_sample_t *in) {
    accel_sample_t out = {0};

    /* One-pole low-pass estimate */
    p->lp_x = HP_ALPHA * p->lp_x + (1.0f - HP_ALPHA) * in->x;
    p->lp_y = HP_ALPHA * p->lp_y + (1.0f - HP_ALPHA) * in->y;
    p->lp_z = HP_ALPHA * p->lp_z + (1.0f - HP_ALPHA) * in->z;

    /* High-pass = input - low-pass */
    out.x = in->x - p->lp_x;
    out.y = in->y - p->lp_y;
    out.z = in->z - p->lp_z;

    return out;
}

/* =========================
 * Update running window stats
 * ========================= */
static void window_push(accel_pipeline_t *p, float value) {
    if (p->mag_count < WINDOW_SIZE) {
        p->mag_buf[p->mag_idx] = value;
        p->sum += value;
        p->sum_sq += value * value;
        p->mag_count++;
        p->mag_idx = (p->mag_idx + 1) % WINDOW_SIZE;
    } else {
        float old = p->mag_buf[p->mag_idx];
        p->sum -= old;
        p->sum_sq -= old * old;

        p->mag_buf[p->mag_idx] = value;
        p->sum += value;
        p->sum_sq += value * value;
        p->mag_idx = (p->mag_idx + 1) % WINDOW_SIZE;
    }
}

static void window_stats(const accel_pipeline_t *p, float *mean, float *stddev) {
    if (p->mag_count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    float n = (float)p->mag_count;
    *mean = p->sum / n;

    float variance = (p->sum_sq / n) - (*mean * *mean);
    if (variance < 0.0f) variance = 0.0f;
    *stddev = fast_sqrtf(variance);
}

/* =========================
 * Process one sample
 * Returns true if anomaly detected
 * ========================= */
bool accel_pipeline_process(accel_pipeline_t *p, const accel_sample_t *raw) {
    if (!p || !raw) return false;

    /* 1) Filter */
    accel_sample_t filtered = high_pass_filter(p, raw);

    /* 2) Feature extraction */
    float mag = compute_magnitude(&filtered);

    /* 3) Update statistics */
    window_push(p, mag);

    /* Need enough history before detection */
    if (p->mag_count < WINDOW_SIZE / 2) {
        return false;
    }

    float mean, stddev;
    window_stats(p, &mean, &stddev);

    /* Avoid division by zero */
    float z = 0.0f;
    if (stddev > 1e-6f) {
        z = (mag - mean) / stddev;
    }

    /* 4) State machine */
    bool anomaly_now = (z > ANOMALY_Z_THRESHOLD);

    switch (p->state) {
        case PIPELINE_STATE_NORMAL:
            if (anomaly_now) {
                p->anomaly_streak++;
                if (p->anomaly_streak >= MIN_ANOMALY_COUNT) {
                    p->state = PIPELINE_STATE_ANOMALY;
                    p->recovery_streak = 0;
                }
            } else {
                p->anomaly_streak = 0;
            }
            break;

        case PIPELINE_STATE_ANOMALY:
            if (!anomaly_now) {
                p->recovery_streak++;
                if (p->recovery_streak >= RECOVERY_COUNT) {
                    p->state = PIPELINE_STATE_NORMAL;
                    p->anomaly_streak = 0;
                }
            } else {
                p->recovery_streak = 0;
            }
            break;
    }

    return (p->state == PIPELINE_STATE_ANOMALY);
}

