/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 *  - Fixed-size ring buffer
 *  - Simple high-pass / detrend via moving average
 *  - Magnitude-based feature extraction
 *  - Exponential moving average baseline
 *  - Z-score-like anomaly score
 *  - Hysteresis / debounce for stable anomaly events
 *
 * Intended for small MCUs. No dynamic allocation, no floating-point required
 * if you enable the fixed-point path. This version uses float for clarity.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         32
#define BASELINE_ALPHA      0.02f
#define VAR_ALPHA           0.02f
#define ANOMALY_Z_THRESHOLD  3.5f
#define ANOMALY_DEBOUNCE     3
#define MIN_VARIANCE         1e-6f

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[WINDOW_SIZE];
    uint8_t head;
    uint8_t count;
    float sum_x;
    float sum_y;
    float sum_z;
} ring_buffer_t;

typedef struct {
    ring_buffer_t rb;

    float baseline_mean;
    float baseline_var;

    uint8_t anomaly_streak;
    bool anomaly_active;
} anomaly_detector_t;

static void ring_buffer_init(ring_buffer_t *rb) {
    rb->head = 0;
    rb->count = 0;
    rb->sum_x = 0.0f;
    rb->sum_y = 0.0f;
    rb->sum_z = 0.0f;
}

static void detector_init(anomaly_detector_t *det) {
    ring_buffer_init(&det->rb);
    det->baseline_mean = 0.0f;
    det->baseline_var = 1.0f;
    det->anomaly_streak = 0;
    det->anomaly_active = false;
}

static void ring_buffer_push(ring_buffer_t *rb, accel_sample_t s) {
    if (rb->count == WINDOW_SIZE) {
        accel_sample_t old = rb->buf[rb->head];
        rb->sum_x -= old.x;
        rb->sum_y -= old.y;
        rb->sum_z -= old.z;
    } else {
        rb->count++;
    }

    rb->buf[rb->head] = s;
    rb->sum_x += s.x;
    rb->sum_y += s.y;
    rb->sum_z += s.z;

    rb->head = (rb->head + 1) % WINDOW_SIZE;
}

static accel_sample_t ring_buffer_mean(const ring_buffer_t *rb) {
    accel_sample_t m = {0};
    if (rb->count == 0) return m;

    float inv = 1.0f / (float)rb->count;
    m.x = rb->sum_x * inv;
    m.y = rb->sum_y * inv;
    m.z = rb->sum_z * inv;
    return m;
}

static float accel_magnitude(const accel_sample_t *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

/*
 * Process one accelerometer sample.
 * Returns true if an anomaly is currently active.
 *
 * Typical usage:
 *   - Call this at the sensor sample rate.
 *   - If it returns true, log/flag the event.
 */
bool anomaly_detector_process(anomaly_detector_t *det, accel_sample_t sample) {
    // Update short-term window
    ring_buffer_push(&det->rb, sample);

    // Need enough samples to stabilize
    if (det->rb.count < WINDOW_SIZE / 2) {
        return false;
    }

    // Detrend using moving average of the window
    accel_sample_t mean = ring_buffer_mean(&det->rb);
    accel_sample_t detrended = {
        .x = sample.x - mean.x,
        .y = sample.y - mean.y,
        .z = sample.z - mean.z
    };

    // Feature: magnitude of detrended acceleration
    float feature = accel_magnitude(&detrended);

    // Update baseline mean/variance using EMA
    float delta = feature - det->baseline_mean;
    det->baseline_mean += BASELINE_ALPHA * delta;

    float delta2 = feature - det->baseline_mean;
    det->baseline_var = (1.0f - VAR_ALPHA) * det->baseline_var + VAR_ALPHA * (delta * delta2);
    if (det->baseline_var < MIN_VARIANCE) {
        det->baseline_var = MIN_VARIANCE;
    }

    float stddev = sqrtf(det->baseline_var);
    float z = fabsf(feature - det->baseline_mean) / stddev;

    // Debounced anomaly detection
    if (z > ANOMALY_Z_THRESHOLD) {
        if (det->anomaly_streak < 255) det->anomaly_streak++;
    } else {
        det->anomaly_streak = 0;
    }

    if (det->anomaly_streak >= ANOMALY_DEBOUNCE) {
        det->anomaly_active = true;
    } else if (det->anomaly_streak == 0) {
        det->anomaly_active = false;
    }

    return det->anomaly_active;
}

