## C code

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detector
 * - Fixed-point friendly structure
 * - No dynamic memory
 * - Suitable for periodic sampling in a timer/ISR/task
 */

#define WINDOW_SIZE        16
#define BASELINE_ALPHA     0.01f   // baseline update rate
#define VAR_ALPHA          0.01f   // variance update rate
#define ANOMALY_Z_THRESH   3.0f    // anomaly threshold in std devs
#define MIN_SAMPLES        32      // warm-up period before detection

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float mag_window[WINDOW_SIZE];
    uint8_t window_idx;
    uint8_t window_count;

    float baseline;
    float variance;
    uint32_t sample_count;

    bool initialized;
} anomaly_detector_t;

static float compute_magnitude(accel_sample_t s)
{
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static float moving_average_update(anomaly_detector_t *det, float new_value)
{
    det->mag_window[det->window_idx] = new_value;
    det->window_idx = (det->window_idx + 1) % WINDOW_SIZE;

    if (det->window_count < WINDOW_SIZE) {
        det->window_count++;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < det->window_count; i++) {
        sum += det->mag_window[i];
    }
    return sum / (float)det->window_count;
}

void anomaly_detector_init(anomaly_detector_t *det)
{
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
    det->window_idx = 0;
    det->window_count = 0;
    det->baseline = 0.0f;
    det->variance = 1.0f;   // avoid divide-by-zero at startup
    det->sample_count = 0;
    det->initialized = false;
}

/*
 * Returns true if anomaly detected.
 * Call this once per accelerometer sample.
 */
bool anomaly_detector_process(anomaly_detector_t *det, accel_sample_t sample)
{
    float mag = compute_magnitude(sample);
    float smooth_mag = moving_average_update(det, mag);

    det->sample_count++;

    // Warm-up: learn baseline without triggering anomalies
    if (det->sample_count <= MIN_SAMPLES) {
        if (!det->initialized) {
            det->baseline = smooth_mag;
            det->variance = 1.0f;
            det->initialized = true;
        } else {
            float diff = smooth_mag - det->baseline;
            det->baseline += BASELINE_ALPHA * diff;
            det->variance  += VAR_ALPHA * ((diff * diff) - det->variance);
        }
        return false;
    }

    // Compute deviation from baseline
    float diff = smooth_mag - det->baseline;
    float stddev = sqrtf(det->variance);
    float z = (stddev > 1e-6f) ? (diff / stddev) : 0.0f;

    bool anomaly = (fabsf(z) > ANOMALY_Z_THRESH);

    // Update model more slowly; optionally freeze updates on anomaly
    if (!anomaly) {
        det->baseline += BASELINE_ALPHA * diff;
        det->variance  += VAR_ALPHA * ((diff * diff) - det->variance);
    }

    return anomaly;
}
