- ingests 3-axis accelerometer samples
- computes magnitude
- applies a simple low-pass filter
- maintains a running mean and variance with Welford’s algorithm
- flags anomalies when a sample deviates too far from the baseline
- uses fixed-size buffers and no dynamic allocation

You can adapt thresholds and window sizes for your sensor and sampling rate.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/*
 * Embedded accelerometer anomaly detection pipeline
 * - No dynamic allocation
 * - Fixed-size state
 * - Suitable for MCU firmware
 */

#define LPF_ALPHA          0.10f   // Low-pass filter coefficient
#define MIN_BASELINE_SAMPLES 50    // Warm-up samples before anomaly checks
#define Z_SCORE_THRESHOLD   3.0f   // Anomaly threshold in standard deviations
#define MIN_STD_DEV         0.05f  // Prevent divide-by-zero / overly sensitive detection

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    // Low-pass filtered magnitude
    float filtered_mag;

    // Welford running statistics for baseline
    uint32_t count;
    float mean;
    float m2;

    // Optional: last anomaly score
    float last_z_score;

    // State
    bool initialized;
} anomaly_detector_t;

static inline float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

void anomaly_detector_init(anomaly_detector_t *det)
{
    det->filtered_mag = 0.0f;
    det->count = 0;
    det->mean = 0.0f;
    det->m2 = 0.0f;
    det->last_z_score = 0.0f;
    det->initialized = false;
}

static inline void welford_update(anomaly_detector_t *det, float x)
{
    det->count++;
    float delta = x - det->mean;
    det->mean += delta / (float)det->count;
    float delta2 = x - det->mean;
    det->m2 += delta * delta2;
}

static inline float welford_stddev(const anomaly_detector_t *det)
{
    if (det->count < 2) {
        return 0.0f;
    }
    float variance = det->m2 / (float)(det->count - 1);
    return sqrtf(variance);
}

/*
 * Process one accelerometer sample.
 *
 * Returns true if anomaly detected, false otherwise.
 *
 * Strategy:
 * 1) compute magnitude
 * 2) low-pass filter it
 * 3) during warm-up, build baseline only
 * 4) after warm-up, compute z-score against baseline
 * 5) update baseline with current sample if not anomalous
 */
bool anomaly_detector_process(anomaly_detector_t *det, const accel_sample_t *sample)
{
    float mag = accel_magnitude(sample);

    if (!det->initialized) {
        det->filtered_mag = mag;
        det->initialized = true;
    } else {
        det->filtered_mag = (LPF_ALPHA * mag) + ((1.0f - LPF_ALPHA) * det->filtered_mag);
    }

    // Warm-up phase: collect baseline statistics
    if (det->count < MIN_BASELINE_SAMPLES) {
        welford_update(det, det->filtered_mag);
        det->last_z_score = 0.0f;
        return false;
    }

    float stddev = welford_stddev(det);
    if (stddev < MIN_STD_DEV) {
        stddev = MIN_STD_DEV;
    }

    float z = (det->filtered_mag - det->mean) / stddev;
    if (z < 0.0f) {
        z = -z;
    }
    det->last_z_score = z;

    bool anomaly = (z > Z_SCORE_THRESHOLD);

    // Update baseline only if not anomalous
    if (!anomaly) {
        welford_update(det, det->filtered_mag);
    }

    return anomaly;
}

