#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32
#define LPF_ALPHA           0.2f
#define BASELINE_ALPHA      0.01f
#define VAR_ALPHA           0.01f
#define ANOMALY_Z_THRESHOLD  3.5f
#define MIN_VARIANCE         1e-4f

/* =========================
 * Data structures
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float mag_filtered;
    float baseline;
    float variance;
    float window[WINDOW_SIZE];
    uint8_t window_idx;
    uint8_t window_count;
    bool initialized;
} AnomalyDetector;

/* =========================
 * Utility functions
 * ========================= */
static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float accel_magnitude(const AccelSample *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

/* =========================
 * Initialization
 * ========================= */
void anomaly_detector_init(AnomalyDetector *det) {
    det->mag_filtered = 0.0f;
    det->baseline = 0.0f;
    det->variance = 1.0f;
    det->window_idx = 0;
    det->window_count = 0;
    det->initialized = false;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->window[i] = 0.0f;
    }
}

/* =========================
 * Update pipeline
 * Returns true if anomaly detected
 * ========================= */
bool anomaly_detector_update(AnomalyDetector *det, const AccelSample *sample) {
    float mag = accel_magnitude(sample);

    /* Low-pass filter */
    if (!det->initialized) {
        det->mag_filtered = mag;
        det->baseline = mag;
        det->variance = 1.0f;
        det->initialized = true;
    } else {
        det->mag_filtered = (LPF_ALPHA * mag) + ((1.0f - LPF_ALPHA) * det->mag_filtered);
    }

    /* Rolling window update */
    det->window[det->window_idx] = det->mag_filtered;
    det->window_idx = (det->window_idx + 1) % WINDOW_SIZE;
    if (det->window_count < WINDOW_SIZE) {
        det->window_count++;
    }

    /* Update baseline and variance using exponential moving averages */
    float error = det->mag_filtered - det->baseline;
    det->baseline += BASELINE_ALPHA * error;

    float error2 = det->mag_filtered - det->baseline;
    det->variance += VAR_ALPHA * ((error2 * error2) - det->variance);

    if (det->variance < MIN_VARIANCE) {
        det->variance = MIN_VARIANCE;
    }

    /* Z-score style anomaly check */
    float stddev = fast_sqrtf(det->variance);
    float z = fabsf(det->mag_filtered - det->baseline) / stddev;

    return (z > ANOMALY_Z_THRESHOLD);
}

/* =========================
 * Example usage
 * ========================= */
#ifdef EXAMPLE_MAIN
#include <stdio.h>

int main(void) {
    AnomalyDetector detector;
    anomaly_detector_init(&detector);

    /* Example stream of samples */
    AccelSample stream[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.50f, 0.40f, 1.80f},  /* likely anomaly */
        {0.01f, 0.02f, 1.00f},
    };

    for (int i = 0; i < (int)(sizeof(stream)/sizeof(stream[0])); i++) {
        bool anomaly = anomaly_detector_update(&detector, &stream[i]);
        printf("Sample %d: mag=%.3f baseline=%.3f var=%.3f anomaly=%s\n",
               i,
               detector.mag_filtered,
               detector.baseline,
               detector.variance,
               anomaly ? "YES" : "NO");
    }

    return 0;
}
#endif
