/*
 * Embedded accelerometer anomaly detection pipeline
 *
 * Features:
 * - Fixed-size ring buffer for streaming samples
 * - High-pass-ish detrending via running mean removal
 * - Feature extraction over a sliding window:
 *     * mean magnitude
 *     * RMS magnitude
 *     * peak-to-peak magnitude
 *     * variance magnitude
 * - Simple anomaly score using z-like normalization against baseline stats
 * - Designed for small MCUs: no dynamic allocation, no floating point required
 *
 * Notes:
 * - This is a template. Tune thresholds and baseline update rates for your device.
 * - Assumes accelerometer samples are already scaled to "mg" or another fixed-point unit.
 * - If your MCU has no FPU, keep everything in fixed-point as below.
 */

#include <stdint.h>
#include <stdbool.h>
#include <string.h>

#define AXIS_SCALE          1000    // Example: 1g = 1000 mg
#define WINDOW_SIZE         32
#define BASELINE_ALPHA_SHIFT 6      // baseline update rate: 1/64
#define MEAN_ALPHA_SHIFT     4      // running mean update rate: 1/16
#define ANOMALY_SCORE_TH     2500   // tune this
#define MIN_BASELINE_SAMPLES 64

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[WINDOW_SIZE];
    uint8_t head;
    uint8_t count;
} ringbuf_t;

typedef struct {
    // Running mean for detrending
    int32_t mean_x;
    int32_t mean_y;
    int32_t mean_z;

    // Sliding window stats on magnitude
    int32_t sum_mag;
    int64_t sum_mag_sq;
    int16_t mag_min;
    int16_t mag_max;

    ringbuf_t rb;

    // Baseline stats for anomaly detection
    int32_t baseline_mean;
    int32_t baseline_var;
    uint32_t baseline_count;

    // State
    bool initialized;
} anomaly_detector_t;

static int16_t i16_abs(int16_t v) {
    return (v < 0) ? (int16_t)(-v) : v;
}

static int32_t i32_abs(int32_t v) {
    return (v < 0) ? -v : v;
}

static int16_t clamp_i16(int32_t v) {
    if (v > 32767) return 32767;
    if (v < -32768) return -32768;
    return (int16_t)v;
}

static int16_t isqrt32(uint32_t x) {
    // Integer square root
    uint32_t op = x;
    uint32_t res = 0;
    uint32_t one = 1u << 30;

    while (one > op) one >>= 2;

    while (one != 0) {
        if (op >= res + one) {
            op -= res + one;
            res = (res >> 1) + one;
        } else {
            res >>= 1;
        }
        one >>= 2;
    }
    return (int16_t)res;
}

static void ringbuf_init(ringbuf_t *rb) {
    memset(rb, 0, sizeof(*rb));
}

static void detector_init(anomaly_detector_t *d) {
    memset(d, 0, sizeof(*d));
    ringbuf_init(&d->rb);
    d->initialized = true;
}

static void ringbuf_push(ringbuf_t *rb, accel_sample_t s) {
    rb->buf[rb->head] = s;
    rb->head = (uint8_t)((rb->head + 1) % WINDOW_SIZE);
    if (rb->count < WINDOW_SIZE) rb->count++;
}

static accel_sample_t ringbuf_get_oldest(const ringbuf_t *rb) {
    uint8_t idx = (uint8_t)((rb->head + WINDOW_SIZE - rb->count) % WINDOW_SIZE);
    return rb->buf[idx];
}

static int16_t magnitude_mg(accel_sample_t s) {
    // Approximate magnitude using integer sqrt of x^2+y^2+z^2
    int32_t xx = (int32_t)s.x * s.x;
    int32_t yy = (int32_t)s.y * s.y;
    int32_t zz = (int32_t)s.z * s.z;
    uint32_t sum = (uint32_t)(xx + yy + zz);
    return isqrt32(sum);
}

static void update_running_mean(anomaly_detector_t *d, accel_sample_t s) {
    // Exponential moving average: mean += (x - mean)/16
    d->mean_x += (((int32_t)s.x << 8) - d->mean_x) >> MEAN_ALPHA_SHIFT;
    d->mean_y += (((int32_t)s.y << 8) - d->mean_y) >> MEAN_ALPHA_SHIFT;
    d->mean_z += (((int32_t)s.z << 8) - d->mean_z) >> MEAN_ALPHA_SHIFT;
}

static accel_sample_t detrend_sample(const anomaly_detector_t *d, accel_sample_t s) {
    accel_sample_t out;
    out.x = clamp_i16((int32_t)s.x - (d->mean_x >> 8));
    out.y = clamp_i16((int32_t)s.y - (d->mean_y >> 8));
    out.z = clamp_i16((int32_t)s.z - (d->mean_z >> 8));
    return out;
}

static void recompute_window_stats(anomaly_detector_t *d) {
    d->sum_mag = 0;
    d->sum_mag_sq = 0;
    d->mag_min = 32767;
    d->mag_max = -32768;

    for (uint8_t i = 0; i < d->rb.count; i++) {
        uint8_t idx = (uint8_t)((d->rb.head + WINDOW_SIZE - d->rb.count + i) % WINDOW_SIZE);
        int16_t m = magnitude_mg(d->rb.buf[idx]);
        d->sum_mag += m;
        d->sum_mag_sq += (int64_t)m * m;
        if (m < d->mag_min) d->mag_min = m;
        if (m > d->mag_max) d->mag_max = m;
    }
}

static int32_t compute_anomaly_score(const anomaly_detector_t *d) {
    if (d->rb.count == 0) return 0;

    int32_t n = d->rb.count;
    int32_t mean = d->sum_mag / n;
    int64_t mean_sq = d->sum_mag_sq / n;
    int64_t var = mean_sq - ((int64_t)mean * mean);
    if (var < 0) var = 0;

    int32_t std = isqrt32((uint32_t)var);

    // Score combines deviation from baseline mean and current variability
    int32_t dev = i32_abs(mean - d->baseline_mean);
    int32_t var_dev = i32_abs(std - d->baseline_var);

    // Weighted score in fixed-point-ish units
    return (dev << 1) + var_dev + ((d->mag_max - d->mag_min) << 1);
}

static void update_baseline(anomaly_detector_t *d, int32_t window_mean, int32_t window_var) {
    if (d->baseline_count < MIN_BASELINE_SAMPLES) {
        // Bootstrap baseline
        d->baseline_mean = (d->baseline_mean * (int32_t)d->baseline_count + window_mean) /
                           (int32_t)(d->baseline_count + 1);
        d->baseline_var = (d->baseline_var * (int32_t)d->baseline_count + window_var) /
                          (int32_t)(d->baseline_count + 1);
        d->baseline_count++;
        return;
    }

    // Slow EMA update
    d->baseline_mean += (window_mean - d->baseline_mean) >> BASELINE_ALPHA_SHIFT;
    d->baseline_var  += (window_var  - d->baseline_var)  >> BASELINE_ALPHA_SHIFT;
}

typedef struct {
    bool anomaly;
    int32_t score;
    int32_t baseline_mean;
    int32_t baseline_var;
    int32_t window_mean;
    int32_t window_std;
} anomaly_result_t;

anomaly_result_t detector_process_sample(anomaly_detector_t *d, accel_sample_t raw) {
    anomaly_result_t res = {0};

    if (!d->initialized) {
        detector_init(d);
    }

    // Update detrending mean and remove it
    update_running_mean(d, raw);
    accel_sample_t x = detrend_sample(d, raw);

    // Push into window
    ringbuf_push(&d->rb, x);

    // Need enough samples to compute stable stats
    if (d->rb.count < WINDOW_SIZE) {
        res.anomaly = false;
        return res;
    }

    recompute_window_stats(d);

    int32_t n = d->rb.count;
    int32_t window_mean = d->sum_mag / n;
    int64_t mean_sq = d->sum_mag_sq / n;
    int64_t var = mean_sq - ((int64_t)window_mean * window_mean);
    if (var < 0) var = 0;
    int32_t window_std = isqrt32((uint32_t)var);

    update_baseline(d, window_mean, var);

    int32_t score = compute_anomaly_score(d);

    res.score = score;
    res.baseline_mean = d->baseline_mean;
    res.baseline_var = d->baseline_var;
    res.window_mean = window_mean;
    res.window_std = window_std;
    res.anomaly = (d->baseline_count >= MIN_BASELINE_SAMPLES) && (score > ANOMALY_SCORE_TH);

    return res;
}

/* Example usage:
 *
 * anomaly_detector_t detector;
 * detector_init(&detector);
 *
 * void on_accel_sample(int16_t ax, int16_t ay, int16_t az) {
 *     accel_sample_t s = { ax, ay, az };
 *     anomaly_result_t r = detector_process_sample(&detector, s);
 *     if (r.anomaly) {
 *         // Trigger event, log, or send telemetry
 *     }
 * }
 */

#ifdef TEST_MAIN
#include <stdio.h>

int main(void) {
    anomaly_detector_t det;
    detector_init(&det);

    // Simulated stream
    for (int i = 0; i < 200; i++) {
        accel_sample_t s = { 0, 0, AXIS_SCALE };
        if (i == 120) {
            s.x = 250;
            s.y = -300;
            s.z = 1700; // anomaly spike
        }
        anomaly_result_t r = detector_process_sample(&det, s);
        if (r.anomaly) {
            printf("Anomaly at sample %d: score=%ld\n", i, (long)r.score);
        }
    }
    return 0;
}
#endif
