- computes magnitude and a rolling baseline
- flags anomalies when the signal deviates significantly from the baseline

It is designed to be lightweight for microcontrollers.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE     32
#define ALPHA           0.1f     // Low-pass filter coefficient
#define THRESHOLD_MULT  3.0f     // Anomaly threshold multiplier
#define MIN_BASELINE    0.05f    // Avoid division by near-zero

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;

    float mag_window[WINDOW_SIZE];
    uint8_t window_idx;
    uint8_t window_count;

    float baseline_mean;
    float baseline_var;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    // Replace with platform sqrtf if available
    return sqrtf(x);
}

void anomaly_detector_init(anomaly_detector_t *det) {
    det->filtered_x = 0.0f;
    det->filtered_y = 0.0f;
    det->filtered_z = 0.0f;
    det->window_idx = 0;
    det->window_count = 0;
    det->baseline_mean = 0.0f;
    det->baseline_var = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
}

static float compute_magnitude(const accel_sample_t *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static float low_pass(float prev, float current) {
    return prev + ALPHA * (current - prev);
}

static void update_baseline(anomaly_detector_t *det, float mag) {
    // Simple rolling mean/variance update over fixed window
    det->mag_window[det->window_idx] = mag;
    det->window_idx = (det->window_idx + 1) % WINDOW_SIZE;

    if (det->window_count < WINDOW_SIZE) {
        det->window_count++;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < det->window_count; i++) {
        sum += det->mag_window[i];
    }
    det->baseline_mean = sum / det->window_count;

    float var_sum = 0.0f;
    for (uint8_t i = 0; i < det->window_count; i++) {
        float d = det->mag_window[i] - det->baseline_mean;
        var_sum += d * d;
    }
    det->baseline_var = var_sum / det->window_count;
}

bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *raw,
                              float *out_score) {
    // 1) Filter each axis
    det->filtered_x = low_pass(det->filtered_x, raw->x);
    det->filtered_y = low_pass(det->filtered_y, raw->y);
    det->filtered_z = low_pass(det->filtered_z, raw->z);

    // 2) Compute magnitude from filtered sample
    accel_sample_t filtered = {
        .x = det->filtered_x,
        .y = det->filtered_y,
        .z = det->filtered_z
    };
    float mag = compute_magnitude(&filtered);

    // 3) Update baseline
    update_baseline(det, mag);

    // 4) Compute anomaly score
    float stddev = fast_sqrtf(det->baseline_var);
    if (stddev < MIN_BASELINE) {
        stddev = MIN_BASELINE;
    }

    float score = fabsf(mag - det->baseline_mean) / stddev;
    if (out_score) {
        *out_score = score;
    }

    // 5) Decide anomaly
    return (score > THRESHOLD_MULT);
}
