Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accelerometer samples
- applies a simple low-pass filter
- computes signal magnitude
- maintains a rolling baseline
- flags anomalies when the current magnitude deviates too far from the baseline

This is designed to be lightweight for microcontrollers.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE     32
#define LPF_ALPHA       0.2f
#define ANOMALY_THRESH  2.5f   // tune for your sensor/noise profile

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float lpf_x;
    float lpf_y;
    float lpf_z;

    float mag_window[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;

    float sum_mag;
    float sum_sq_mag;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float magnitude3f(float x, float y, float z) {
    return fast_sqrtf(x*x + y*y + z*z);
}

void anomaly_detector_init(anomaly_detector_t *det) {
    det->lpf_x = 0.0f;
    det->lpf_y = 0.0f;
    det->lpf_z = 0.0f;
    det->idx = 0;
    det->count = 0;
    det->sum_mag = 0.0f;
    det->sum_sq_mag = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
}

static float low_pass(float prev, float input) {
    return prev + LPF_ALPHA * (input - prev);
}

// Returns true if anomaly detected
bool anomaly_detector_process(anomaly_detector_t *det, accel_sample_t s) {
    // 1) Low-pass filter
    det->lpf_x = low_pass(det->lpf_x, s.x);
    det->lpf_y = low_pass(det->lpf_y, s.y);
    det->lpf_z = low_pass(det->lpf_z, s.z);

    // 2) Compute magnitude
    float mag = magnitude3f(det->lpf_x, det->lpf_y, det->lpf_z);

    // 3) Update rolling window stats
    if (det->count < WINDOW_SIZE) {
        det->mag_window[det->idx] = mag;
        det->sum_mag += mag;
        det->sum_sq_mag += mag * mag;
        det->count++;
    } else {
        float old = det->mag_window[det->idx];
        det->sum_mag -= old;
        det->sum_sq_mag -= old * old;

        det->mag_window[det->idx] = mag;
        det->sum_mag += mag;
        det->sum_sq_mag += mag * mag;
    }

    det->idx = (det->idx + 1) % WINDOW_SIZE;

    // Need enough samples for stable baseline
    if (det->count < WINDOW_SIZE) {
        return false;
    }

    // 4) Compute baseline mean and stddev
    float mean = det->sum_mag / WINDOW_SIZE;
    float variance = (det->sum_sq_mag / WINDOW_SIZE) - (mean * mean);
    if (variance < 0.0f) variance = 0.0f;
    float stddev = fast_sqrtf(variance);

    // 5) Detect anomaly
    float deviation = fabsf(mag - mean);
    bool anomaly = (deviation > ANOMALY_THRESH * stddev);

    return anomaly;
}
