/* ---------------- Configuration ---------------- */

#define WINDOW_SIZE         32      // Rolling window for baseline stats
#define HPF_ALPHA           0.95f   // High-pass filter coefficient (0..1)
#define ANOMALY_Z_THRESHOLD 3.0f    // Number of std devs from mean to flag anomaly
#define MIN_STD_DEV         0.05f    // Prevent division by zero / overly sensitive detection

/* ---------------- Data Types ---------------- */

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    // High-pass filter state
    float prev_raw_x, prev_raw_y, prev_raw_z;
    float prev_hpf_x, prev_hpf_y, prev_hpf_z;

    // Rolling window of magnitudes
    float mag_window[WINDOW_SIZE];
    uint8_t window_index;
    uint8_t window_count;

    // Running statistics
    float mean;
    float m2; // sum of squares of differences from the mean (for variance)
} anomaly_detector_t;

/* ---------------- Utility ---------------- */

static float vector_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

/* High-pass filter:
   y[n] = alpha * (y[n-1] + x[n] - x[n-1]) */
static accel_sample_t high_pass_filter(anomaly_detector_t *det, const accel_sample_t *in)
{
    accel_sample_t out;

    out.x = HPF_ALPHA * (det->prev_hpf_x + in->x - det->prev_raw_x);
    out.y = HPF_ALPHA * (det->prev_hpf_y + in->y - det->prev_raw_y);
    out.z = HPF_ALPHA * (det->prev_hpf_z + in->z - det->prev_raw_z);

    det->prev_raw_x = in->x;
    det->prev_raw_y = in->y;
    det->prev_raw_z = in->z;

    det->prev_hpf_x = out.x;
    det->prev_hpf_y = out.y;
    det->prev_hpf_z = out.z;

    return out;
}

/* Update rolling mean/variance using Welford over a fixed-size window.
   For embedded simplicity, we recompute stats from the window when full.
   This is O(N) but N is small. */
static void recompute_stats(anomaly_detector_t *det)
{
    if (det->window_count == 0) {
        det->mean = 0.0f;
        det->m2 = 0.0f;
        return;
    }

    float mean = 0.0f;
    float m2 = 0.0f;

    for (uint8_t i = 0; i < det->window_count; i++) {
        float x = det->mag_window[i];
        float delta = x - mean;
        mean += delta / (i + 1);
        float delta2 = x - mean;
        m2 += delta * delta2;
    }

    det->mean = mean;
    det->m2 = m2;
}

static void detector_init(anomaly_detector_t *det)
{
    det->prev_raw_x = det->prev_raw_y = det->prev_raw_z = 0.0f;
    det->prev_hpf_x  = det->prev_hpf_y  = det->prev_hpf_z  = 0.0f;

    det->window_index = 0;
    det->window_count = 0;

    det->mean = 0.0f;
    det->m2 = 0.0f;

    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        det->mag_window[i] = 0.0f;
    }
}

/* Process one accelerometer sample.
   Returns true if anomaly detected. */
static bool detector_process_sample(anomaly_detector_t *det, const accel_sample_t *raw)
{
    // 1) Remove DC/gravity component
    accel_sample_t filtered = high_pass_filter(det, raw);

    // 2) Compute magnitude of filtered signal
    float mag = vector_magnitude(&filtered);

    // 3) Update rolling window
    det->mag_window[det->window_index] = mag;
    det->window_index = (det->window_index + 1) % WINDOW_SIZE;
    if (det->window_count < WINDOW_SIZE) {
        det->window_count++;
    }

    // 4) Recompute baseline stats
    recompute_stats(det);

    // 5) Compute anomaly score
    float variance = 0.0f;
    if (det->window_count > 1) {
        variance = det->m2 / (float)(det->window_count - 1);
    }

    float std_dev = sqrtf(variance);
    if (std_dev < MIN_STD_DEV) {
        std_dev = MIN_STD_DEV;
    }

    float z = fabsf(mag - det->mean) / std_dev;

    // 6) Flag anomaly
    return (z > ANOMALY_Z_THRESHOLD);
}

/* ---------------- Example Usage ---------------- */

