{
    anomaly_detector_t detector;
    detector_init(&detector);

    while (1) {
        accel_sample_t sample = read_accelerometer(); // platform-specific
        bool anomaly = detector_process_sample(&detector, &sample);

        if (anomaly) {
            // Handle anomaly: log, raise interrupt, send packet, etc.
        }
    }
}
*/
