Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- ingests 3-axis accelerometer samples
- applies a simple low-pass filter
- computes signal magnitude
- maintains a rolling baseline
- flags anomalies when the current magnitude deviates too far from baseline

It is designed to be lightweight for microcontrollers.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE     32
#define LPF_ALPHA       0.2f
#define ANOMALY_THRESH   2.5f   // tune for your sensor/noise profile

typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    float lpf_x;
    float lpf_y;
    float lpf_z;

    float mag_window[WINDOW_SIZE];
    uint8_t idx;
    uint8_t count;

    float baseline_mean;
    float baseline_var;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float magnitude3(float x, float y, float z) {
    return fast_sqrtf(x*x + y*y + z*z);
}

void anomaly_detector_init(anomaly_detector_t *d) {
    d->lpf_x = 0.0f;
    d->lpf_y = 0.0f;
    d->lpf_z = 0.0f;
    d->idx = 0;
    d->count = 0;
    d->baseline_mean = 0.0f;
    d->baseline_var = 0.0f;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->mag_window[i] = 0.0f;
    }
}

static void update_baseline(anomaly_detector_t *d) {
    if (d->count == 0) return;

    float sum = 0.0f;
    for (uint8_t i = 0; i < d->count; i++) {
        sum += d->mag_window[i];
    }
    d->baseline_mean = sum / d->count;

    float var_sum = 0.0f;
    for (uint8_t i = 0; i < d->count; i++) {
        float diff = d->mag_window[i] - d->baseline_mean;
        var_sum += diff * diff;
    }
    d->baseline_var = var_sum / d->count;
}

bool anomaly_detector_process(anomaly_detector_t *d, accel_sample_t raw, float *out_score) {
    // 1) Low-pass filter
    d->lpf_x = LPF_ALPHA * raw.x + (1.0f - LPF_ALPHA) * d->lpf_x;
    d->lpf_y = LPF_ALPHA * raw.y + (1.0f - LPF_ALPHA) * d->lpf_y;
    d->lpf_z = LPF_ALPHA * raw.z + (1.0f - LPF_ALPHA) * d->lpf_z;

    // 2) Compute magnitude
    float mag = magnitude3(d->lpf_x, d->lpf_y, d->lpf_z);

    // 3) Update rolling window
    d->mag_window[d->idx] = mag;
    d->idx = (d->idx + 1) % WINDOW_SIZE;
    if (d->count < WINDOW_SIZE) {
        d->count++;
    }

    // 4) Update baseline
    update_baseline(d);

    // 5) Compute anomaly score
    float stddev = fast_sqrtf(d->baseline_var + 1e-6f);
    float score = fabsf(mag - d->baseline_mean) / stddev;
    if (out_score) {
        *out_score = score;
    }

    // 6) Threshold
    return (d->count >= 8) && (score > ANOMALY_THRESH);
}
