Below is a compact embedded-friendly C implementation of an accelerometer anomaly-detection pipeline. It:

- reads 3-axis accelerometer samples
- applies a simple high-pass filter to remove gravity/DC offset
- computes signal magnitude
- maintains a running mean and variance with Welford’s algorithm
- flags anomalies when the current magnitude deviates too far from the baseline

This is suitable as a starting point for a microcontroller project.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define HPF_ALPHA          0.95f   // closer to 1.0 = slower DC removal
#define ANOMALY_Z_THRESH   4.0f    // anomaly if |x - mean| > z_thresh * stddev
#define MIN_SAMPLES        30      // wait for baseline to stabilize

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    // High-pass filter state
    float prev_x, prev_y, prev_z;
    float hpf_x, hpf_y, hpf_z;

    // Baseline statistics for magnitude
    uint32_t count;
    float mean;
    float m2;   // sum of squares of differences from the mean
} anomaly_detector_t;

/* =========================
 * Utility
 * ========================= */
static inline float fast_sqrtf(float x) {
    return sqrtf(x);
}

static inline float vector_magnitude(float x, float y, float z) {
    return fast_sqrtf(x*x + y*y + z*z);
}

/* =========================
 * Initialization
 * ========================= */
void anomaly_detector_init(anomaly_detector_t *det)
{
    det->prev_x = det->prev_y = det->prev_z = 0.0f;
    det->hpf_x = det->hpf_y = det->hpf_z = 0.0f;

    det->count = 0;
    det->mean = 0.0f;
    det->m2 = 0.0f;
}

/* =========================
 * High-pass filter
 * Removes slow drift / gravity component
 * ========================= */
static accel_sample_t high_pass_filter(anomaly_detector_t *det, accel_sample_t in)
{
    accel_sample_t out;

    // Simple 1st-order HPF:
    // y[n] = alpha * (y[n-1] + x[n] - x[n-1])
    out.x = HPF_ALPHA * (det->hpf_x + in.x - det->prev_x);
    out.y = HPF_ALPHA * (det->hpf_y + in.y - det->prev_y);
    out.z = HPF_ALPHA * (det->hpf_z + in.z - det->prev_z);

    det->prev_x = in.x;
    det->prev_y = in.y;
    det->prev_z = in.z;

    det->hpf_x = out.x;
    det->hpf_y = out.y;
    det->hpf_z = out.z;

    return out;
}

/* =========================
 * Welford running mean/variance
 * ========================= */
static void update_stats(anomaly_detector_t *det, float value)
{
    det->count++;
    float delta = value - det->mean;
    det->mean += delta / (float)det->count;
    float delta2 = value - det->mean;
    det->m2 += delta * delta2;
}

static float get_variance(const anomaly_detector_t *det)
{
    if (det->count < 2) return 0.0f;
    return det->m2 / (float)(det->count - 1);
}

static float get_stddev(const anomaly_detector_t *det)
{
    return fast_sqrtf(get_variance(det));
}

/* =========================
 * Main processing function
 * Returns true if anomaly detected
 * ========================= */
bool anomaly_detector_process(anomaly_detector_t *det, accel_sample_t raw)
{
    // 1) Filter raw accelerometer data
    accel_sample_t filtered = high_pass_filter(det, raw);

    // 2) Compute magnitude of filtered acceleration
    float mag = vector_magnitude(filtered.x, filtered.y, filtered.z);

    // 3) Establish/update baseline statistics
    //    For a stricter detector, you can stop updating stats during anomalies.
    if (det->count < MIN_SAMPLES) {
        update_stats(det, mag);
        return false;
    }

    float stddev = get_stddev(det);
    float threshold = det->mean + ANOMALY_Z_THRESH * stddev;

    bool anomaly = false;
    if (stddev > 0.0001f) {
        float deviation = fabsf(mag - det->mean);
        anomaly = (deviation > ANOMALY_Z_THRESH * stddev);
    }

    // 4) Update baseline only if not anomalous
    if (!anomaly) {
        update_stats(det, mag);
    }

    return anomaly;
}

/* =========================
 * Example usage
 * =========================
 * Replace read_accelerometer() with your sensor driver.
 */
extern bool read_accelerometer(accel_sample_t *out);

void sensor_task(void)
{
    static anomaly_detector_t detector;
    static bool initialized = false;

    if (!initialized) {
        anomaly_detector_init(&detector);
        initialized = true;
    }

    accel_sample_t sample;
    if (read_accelerometer(&sample)) {
        bool anomaly = anomaly_detector_process(&detector, sample);

        if (anomaly) {
            // Handle anomaly:
            // - log event
            // - raise interrupt/event
            // - send telemetry
            // - trigger safety action
        }
    }
}
