Below is a compact C implementation of an embedded accelerometer anomaly-detection pipeline. It is designed for low-memory systems and uses:

- a fixed-size ring buffer
- simple filtering
- feature extraction over a sliding window
- a lightweight anomaly score based on deviation from a running baseline

You can adapt the thresholds and window sizes to your sensor and sampling rate.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32
#define BASELINE_ALPHA      0.01f   // EWMA update rate
#define ANOMALY_Z_THRESHOLD  3.0f   // z-score threshold
#define MIN_VARIANCE         1e-6f

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[WINDOW_SIZE];
    uint8_t head;
    uint8_t count;
} ring_buffer_t;

typedef struct {
    float mean_mag;
    float var_mag;
    float mean_jerk;
    float var_jerk;
} baseline_t;

typedef struct {
    ring_buffer_t window;
    baseline_t baseline;
    float prev_mag;
    bool initialized;
} anomaly_detector_t;

/* =========================
 * Utility functions
 * ========================= */
static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float accel_magnitude(accel_sample_t s) {
    return fast_sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static float absf(float x) {
    return (x < 0.0f) ? -x : x;
}

/* =========================
 * Ring buffer
 * ========================= */
static void ring_init(ring_buffer_t *rb) {
    rb->head = 0;
    rb->count = 0;
}

static void ring_push(ring_buffer_t *rb, accel_sample_t s) {
    rb->buf[rb->head] = s;
    rb->head = (rb->head + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

static accel_sample_t ring_get(const ring_buffer_t *rb, uint8_t idx) {
    // idx = 0 is oldest sample
    uint8_t start = (rb->head + WINDOW_SIZE - rb->count) % WINDOW_SIZE;
    uint8_t pos = (start + idx) % WINDOW_SIZE;
    return rb->buf[pos];
}

/* =========================
 * Baseline update
 * ========================= */
static void ewma_update(float *mean, float *var, float x, float alpha) {
    float diff = x - *mean;
    *mean += alpha * diff;
    *var = (1.0f - alpha) * (*var + alpha * diff * diff);
}

/* =========================
 * Detector API
 * ========================= */
void anomaly_detector_init(anomaly_detector_t *det) {
    ring_init(&det->window);
    det->baseline.mean_mag = 0.0f;
    det->baseline.var_mag = 1.0f;
    det->baseline.mean_jerk = 0.0f;
    det->baseline.var_jerk = 1.0f;
    det->prev_mag = 0.0f;
    det->initialized = false;
}

/*
 * Feed one accelerometer sample.
 * Returns true if anomaly detected.
 */
bool anomaly_detector_update(anomaly_detector_t *det, accel_sample_t sample) {
    float mag = accel_magnitude(sample);
    float jerk = 0.0f;

    if (det->initialized) {
        jerk = absf(mag - det->prev_mag);
    } else {
        det->initialized = true;
    }
    det->prev_mag = mag;

    ring_push(&det->window, sample);

    // Warm-up phase: collect enough samples before detection
    if (det->window.count < WINDOW_SIZE) {
        ewma_update(&det->baseline.mean_mag, &det->baseline.var_mag, mag, BASELINE_ALPHA);
        ewma_update(&det->baseline.mean_jerk, &det->baseline.var_jerk, jerk, BASELINE_ALPHA);
        return false;
    }

    // Compute z-scores
    float std_mag = fast_sqrtf(det->baseline.var_mag + MIN_VARIANCE);
    float std_jerk = fast_sqrtf(det->baseline.var_jerk + MIN_VARIANCE);

    float z_mag = absf(mag - det->baseline.mean_mag) / std_mag;
    float z_jerk = absf(jerk - det->baseline.mean_jerk) / std_jerk;

    // Simple anomaly score
    float score = 0.7f * z_mag + 0.3f * z_jerk;

    bool anomaly = (score > ANOMALY_Z_THRESHOLD);

    // Update baseline only if not anomalous
    if (!anomaly) {
        ewma_update(&det->baseline.mean_mag, &det->baseline.var_mag, mag, BASELINE_ALPHA);
        ewma_update(&det->baseline.mean_jerk, &det->baseline.var_jerk, jerk, BASELINE_ALPHA);
    }

    return anomaly;
}

/* =========================
 * Example usage
 * ========================= */
