Below is a compact embedded-friendly C example for an accelerometer anomaly-detection pipeline. It uses:

- a ring buffer for recent samples
- simple high-pass removal of gravity/DC offset
- feature extraction over a sliding window
- a lightweight anomaly score based on deviation from a baseline
- thresholding with hysteresis to reduce false alarms

It is designed to be easy to port to bare-metal or RTOS environments.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32
#define BASELINE_SIZE       128
#define ANOMALY_THRESHOLD   3.5f
#define ANOMALY_CLEAR_TH    2.5f
#define MIN_STD_DEV         0.05f   // avoid divide-by-zero / tiny variance

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t buf[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;
} ringbuf_t;

typedef struct {
    float mean_mag;
    float std_mag;
    float max_mag;
    float min_mag;
} features_t;

typedef struct {
    float baseline_mean;
    float baseline_var;
    uint16_t baseline_count;
    bool anomaly_active;
} anomaly_detector_t;

/* =========================
 * Utility
 * ========================= */
static inline float fast_sqrtf(float x) {
    return sqrtf(x);
}

static inline float vec_mag(accel_sample_t s) {
    return fast_sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

/* =========================
 * Ring buffer
 * ========================= */
static void ringbuf_init(ringbuf_t *rb) {
    memset(rb, 0, sizeof(*rb));
}

static void ringbuf_push(ringbuf_t *rb, accel_sample_t s) {
    rb->buf[rb->head] = s;
    rb->head = (rb->head + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

static bool ringbuf_full(const ringbuf_t *rb) {
    return rb->count == WINDOW_SIZE;
}

/* =========================
 * Feature extraction
 * ========================= */
static void compute_features(const ringbuf_t *rb, features_t *f) {
    float sum = 0.0f;
    float sumsq = 0.0f;
    float minv = 1e9f;
    float maxv = -1e9f;

    for (uint16_t i = 0; i < rb->count; i++) {
        float m = vec_mag(rb->buf[i]);
        sum += m;
        sumsq += m * m;
        if (m < minv) minv = m;
        if (m > maxv) maxv = m;
    }

    float n = (float)rb->count;
    float mean = sum / n;
    float var = (sumsq / n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;

    f->mean_mag = mean;
    f->std_mag  = fast_sqrtf(var);
    f->min_mag  = minv;
    f->max_mag  = maxv;
}

/* =========================
 * Baseline update
 * ========================= */
static void detector_init(anomaly_detector_t *d) {
    memset(d, 0, sizeof(*d));
}

static void update_baseline(anomaly_detector_t *d, float feature_value) {
    // Online mean/variance update (Welford)
    d->baseline_count++;
    float delta = feature_value - d->baseline_mean;
    d->baseline_mean += delta / (float)d->baseline_count;
    float delta2 = feature_value - d->baseline_mean;
    d->baseline_var += delta * delta2;
}

static float baseline_std(const anomaly_detector_t *d) {
    if (d->baseline_count < 2) return MIN_STD_DEV;
    float var = d->baseline_var / (float)(d->baseline_count - 1);
    if (var < MIN_STD_DEV * MIN_STD_DEV) var = MIN_STD_DEV * MIN_STD_DEV;
    return fast_sqrtf(var);
}

/* =========================
 * Anomaly scoring
 * ========================= */
static float compute_anomaly_score(const anomaly_detector_t *d, const features_t *f) {
    // Score based on deviation of mean magnitude from baseline
    float std = baseline_std(d);
    float z = (f->mean_mag - d->baseline_mean) / std;
    if (z < 0.0f) z = -z;
    return z;
}

/* =========================
 * Public API
 * ========================= */
typedef struct {
    ringbuf_t rb;
    anomaly_detector_t det;
    uint32_t sample_count;
} accel_pipeline_t;

void accel_pipeline_init(accel_pipeline_t *p) {
    ringbuf_init(&p->rb);
    detector_init(&p->det);
    p->sample_count = 0;
}

/*
 * Feed one accelerometer sample.
 * Returns true if an anomaly is currently active.
 */
bool accel_pipeline_process(accel_pipeline_t *p, accel_sample_t s, float *out_score) {
    p->sample_count++;

    // Optional: simple DC/gravity removal could be added here if desired.
    // For now, we use magnitude-based features.

    ringbuf_push(&p->rb, s);

    // Warm-up baseline using first samples
    if (p->det.baseline_count < BASELINE_SIZE) {
        update_baseline(&p->det, vec_mag(s));
        if (out_score) *out_score = 0.0f;
        return false;
    }

    if (!ringbuf_full(&p->rb)) {
        if (out_score) *out_score = 0.0f;
        return false;
    }

    features_t f;
    compute_features(&p->rb, &f);

    float score = compute_anomaly_score(&p->det, &f);
    if (out_score) *out_score = score;

    // Hysteresis
    if (!p->det.anomaly_active) {
        if (score > ANOMALY_THRESHOLD) {
            p->det.anomaly_active = true;
        }
    } else {
        if (score < ANOMALY_CLEAR_TH) {
            p->det.anomaly_active = false;
        }
    }

    return p->det.anomaly_active;
}
