Below is a compact embedded-friendly C example for an accelerometer anomaly-detection pipeline. It uses:

- a ring buffer for recent samples
- a simple high-pass filter to remove gravity/DC offset
- feature extraction over a sliding window
- anomaly scoring based on deviation from a running baseline

It is designed to be easy to port to a microcontroller.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32
#define BASELINE_ALPHA      0.01f   // slow baseline update
#define ANOMALY_THRESHOLD   3.5f    // tune for your sensor/noise
#define MIN_SAMPLES         WINDOW_SIZE

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    AccelSample buf[WINDOW_SIZE];
    uint16_t head;
    uint16_t count;
} RingBuffer;

typedef struct {
    float mean_mag;
    float var_mag;
    float mean_abs_dx;
    float mean_abs_dy;
    float mean_abs_dz;
} Features;

typedef struct {
    float baseline_mean_mag;
    float baseline_var_mag;
    float baseline_mean_abs_dx;
    float baseline_mean_abs_dy;
    float baseline_mean_abs_dz;
    bool initialized;
} BaselineModel;

/* =========================
 * Utility functions
 * ========================= */
static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float vec_mag(AccelSample s) {
    return fast_sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

/* =========================
 * Ring buffer
 * ========================= */
static void rb_init(RingBuffer *rb) {
    rb->head = 0;
    rb->count = 0;
}

static void rb_push(RingBuffer *rb, AccelSample s) {
    rb->buf[rb->head] = s;
    rb->head = (rb->head + 1) % WINDOW_SIZE;
    if (rb->count < WINDOW_SIZE) {
        rb->count++;
    }
}

static AccelSample rb_get(const RingBuffer *rb, uint16_t idx) {
    // idx = 0 is oldest sample
    uint16_t start = (rb->head + WINDOW_SIZE - rb->count) % WINDOW_SIZE;
    return rb->buf[(start + idx) % WINDOW_SIZE];
}

/* =========================
 * Feature extraction
 * ========================= */
static void compute_features(const RingBuffer *rb, Features *f) {
    float sum_mag = 0.0f;
    float sum_mag2 = 0.0f;
    float sum_abs_dx = 0.0f;
    float sum_abs_dy = 0.0f;
    float sum_abs_dz = 0.0f;

    if (rb->count < 2) {
        f->mean_mag = 0.0f;
        f->var_mag = 0.0f;
        f->mean_abs_dx = 0.0f;
        f->mean_abs_dy = 0.0f;
        f->mean_abs_dz = 0.0f;
        return;
    }

    for (uint16_t i = 0; i < rb->count; i++) {
        AccelSample s = rb_get(rb, i);
        float m = vec_mag(s);
        sum_mag += m;
        sum_mag2 += m * m;

        if (i > 0) {
            AccelSample p = rb_get(rb, i - 1);
            sum_abs_dx += fabsf(s.x - p.x);
            sum_abs_dy += fabsf(s.y - p.y);
            sum_abs_dz += fabsf(s.z - p.z);
        }
    }

    float n = (float)rb->count;
    f->mean_mag = sum_mag / n;
    f->var_mag = (sum_mag2 / n) - (f->mean_mag * f->mean_mag);

    float dn = (float)(rb->count - 1);
    f->mean_abs_dx = sum_abs_dx / dn;
    f->mean_abs_dy = sum_abs_dy / dn;
    f->mean_abs_dz = sum_abs_dz / dn;
}

/* =========================
 * Baseline update
 * ========================= */
static void baseline_init(BaselineModel *b, const Features *f) {
    b->baseline_mean_mag = f->mean_mag;
    b->baseline_var_mag = f->var_mag;
    b->baseline_mean_abs_dx = f->mean_abs_dx;
    b->baseline_mean_abs_dy = f->mean_abs_dy;
    b->baseline_mean_abs_dz = f->mean_abs_dz;
    b->initialized = true;
}

static void baseline_update(BaselineModel *b, const Features *f) {
    b->baseline_mean_mag =
        (1.0f - BASELINE_ALPHA) * b->baseline_mean_mag + BASELINE_ALPHA * f->mean_mag;
    b->baseline_var_mag =
        (1.0f - BASELINE_ALPHA) * b->baseline_var_mag + BASELINE_ALPHA * f->var_mag;
    b->baseline_mean_abs_dx =
        (1.0f - BASELINE_ALPHA) * b->baseline_mean_abs_dx + BASELINE_ALPHA * f->mean_abs_dx;
    b->baseline_mean_abs_dy =
        (1.0f - BASELINE_ALPHA) * b->baseline_mean_abs_dy + BASELINE_ALPHA * f->mean_abs_dy;
    b->baseline_mean_abs_dz =
        (1.0f - BASELINE_ALPHA) * b->baseline_mean_abs_dz + BASELINE_ALPHA * f->mean_abs_dz;
}

/* =========================
 * Anomaly scoring
 * ========================= */
static float anomaly_score(const Features *f, const BaselineModel *b) {
    // Normalized absolute deviation score
    float s = 0.0f;

    s += fabsf(f->mean_mag - b->baseline_mean_mag) / (b->baseline_mean_mag + 1e-3f);
    s += fabsf(f->var_mag - b->baseline_var_mag) / (b->baseline_var_mag + 1e-3f);
    s += fabsf(f->mean_abs_dx - b->baseline_mean_abs_dx) / (b->baseline_mean_abs_dx + 1e-3f);
    s += fabsf(f->mean_abs_dy - b->baseline_mean_abs_dy) / (b->baseline_mean_abs_dy + 1e-3f);
    s += fabsf(f->mean_abs_dz - b->baseline_mean_abs_dz) / (b->baseline_mean_abs_dz + 1e-3f);

    return s;
}

/* =========================
 * Optional high-pass filter
 * ========================= */
typedef struct {
    float prev_x, prev_y, prev_z;
    float prev_out_x, prev_out_y, prev_out_z;
    float alpha;
    bool initialized;
} HighPassFilter;

static void hpf_init(HighPassFilter *hpf, float alpha) {
    hpf->prev_x = hpf->prev_y = hpf->prev_z = 0.0f;
    hpf->prev_out_x = hpf->prev_out_y = hpf->prev_out_z = 0.0f;
    hpf->alpha = alpha;
    hpf->initialized = true;
}

static AccelSample hpf_process(HighPassFilter *hpf, AccelSample in) {
    if (!hpf->initialized) {
        hpf_init(hpf, 0.95f);
    }

    AccelSample out;
    out.x = hpf->alpha * (hpf->prev_out_x + in.x - hpf->prev_x);
    out.y = hpf->alpha * (hpf->prev_out_y + in.y - hpf->prev_y);
    out.z = hpf->alpha * (hpf->prev_out_z + in.z - hpf->prev_z);

    hpf->prev_x = in.x;
    hpf->prev_y = in.y;
    hpf->prev_z = in.z;

    hpf->prev_out_x = out.x;
    hpf->prev_out_y = out.y;
    hpf->prev_out_z = out.z;

    return out;
}

/* =========================
 * Pipeline state
 * ========================= */
typedef struct {
    RingBuffer rb;
    BaselineModel baseline;
    HighPassFilter hpf;
    bool baseline_ready;
} AnomalyPipeline;

static void pipeline_init(AnomalyPipeline *p) {
    rb_init(&p->rb);
    p->baseline.initialized = false;
    p->baseline_ready = false;
    hpf_init(&p->hpf, 0.95f);
}

/* Returns true if anomaly detected */
static bool pipeline_process_sample(AnomalyPipeline *p, AccelSample raw) {
    // 1) Filter
    AccelSample filtered = hpf_process(&p->hpf, raw);

    // 2) Buffer
    rb_push(&p->rb, filtered);

    // 3) Need enough samples
    if (p->rb.count < MIN_SAMPLES) {
        return false;
    }

    // 4) Features
    Features f;
    compute_features(&p->rb, &f);

    // 5) Initialize/update baseline
    if (!p->baseline.initialized) {
        baseline_init(&p->baseline, &f);
        p->baseline_ready = true;
        return false;
    }

    // 6) Score
    float score = anomaly_score(&f, &p->baseline);
    bool anomaly = (score > ANOMALY_THRESHOLD);

    // 7) Update baseline only if not anomalous
    if (!anomaly) {
        baseline_update(&p->baseline, &f);
    }

    return anomaly;
}

/* =========================
 * Example usage
 * ========================= */
/*
int main(void) {
    AnomalyPipeline pipe;
    pipeline_init(&pipe);

    while (1) {
        AccelSample s = read_accelerometer(); // implement for your hardware
        bool anomaly = pipeline_process_sample(&pipe, s);

        if (anomaly) {
            // trigger event, log, send interrupt, etc.
        }
    }
}
*/
```

