Below is a compact embedded-friendly C example for an accelerometer anomaly-detection pipeline. It:

- reads 3-axis accelerometer samples,
- applies a simple low-pass filter,
- computes signal magnitude,
- maintains a running mean/variance,
- flags anomalies when the current magnitude deviates too far from the baseline.

This is designed to be easy to port to a microcontroller.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* ---------------- Configuration ---------------- */

#define LPF_ALPHA          0.10f   // Low-pass filter coefficient
#define BASELINE_WINDOW    64      // Number of samples for baseline warm-up
#define ANOMALY_Z_THRESH   3.5f    // Z-score threshold for anomaly detection
#define MIN_VARIANCE       1e-6f   // Prevent divide-by-zero

/* ---------------- Data Types ---------------- */

typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} running_stats_t;

typedef struct {
    float filtered_x;
    float filtered_y;
    float filtered_z;
    bool initialized;
} lpf_state_t;

typedef struct {
    lpf_state_t lpf;
    running_stats_t stats;
    uint32_t warmup_count;
    bool anomaly;
    float last_magnitude;
    float last_zscore;
} anomaly_detector_t;

/* ---------------- Utility ---------------- */

static float magnitude3f(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

static void running_stats_init(running_stats_t *s)
{
    s->mean = 0.0f;
    s->m2 = 0.0f;
    s->count = 0;
}

static void running_stats_update(running_stats_t *s, float x)
{
    s->count++;
    float delta = x - s->mean;
    s->mean += delta / (float)s->count;
    float delta2 = x - s->mean;
    s->m2 += delta * delta2;
}

static float running_stats_variance(const running_stats_t *s)
{
    if (s->count < 2) {
        return MIN_VARIANCE;
    }
    float var = s->m2 / (float)(s->count - 1);
    return (var < MIN_VARIANCE) ? MIN_VARIANCE : var;
}

/* ---------------- Filter ---------------- */

static accel_sample_t lpf_apply(lpf_state_t *st, accel_sample_t in)
{
    if (!st->initialized) {
        st->filtered_x = in.x;
        st->filtered_y = in.y;
        st->filtered_z = in.z;
        st->initialized = true;
    } else {
        st->filtered_x = st->filtered_x + LPF_ALPHA * (in.x - st->filtered_x);
        st->filtered_y = st->filtered_y + LPF_ALPHA * (in.y - st->filtered_y);
        st->filtered_z = st->filtered_z + LPF_ALPHA * (in.z - st->filtered_z);
    }

    accel_sample_t out = {
        .x = st->filtered_x,
        .y = st->filtered_y,
        .z = st->filtered_z
    };
    return out;
}

/* ---------------- Detector API ---------------- */

void anomaly_detector_init(anomaly_detector_t *det)
{
    det->lpf.initialized = false;
    det->lpf.filtered_x = 0.0f;
    det->lpf.filtered_y = 0.0f;
    det->lpf.filtered_z = 0.0f;

    running_stats_init(&det->stats);
    det->warmup_count = 0;
    det->anomaly = false;
    det->last_magnitude = 0.0f;
    det->last_zscore = 0.0f;
}

/*
 * Returns true if anomaly detected.
 * Call this once per new accelerometer sample.
 */
bool anomaly_detector_process(anomaly_detector_t *det, accel_sample_t raw)
{
    accel_sample_t filtered = lpf_apply(&det->lpf, raw);
    float mag = magnitude3f(filtered.x, filtered.y, filtered.z);

    det->last_magnitude = mag;

    /* Warm-up phase: build baseline statistics */
    if (det->warmup_count < BASELINE_WINDOW) {
        running_stats_update(&det->stats, mag);
        det->warmup_count++;
        det->anomaly = false;
        det->last_zscore = 0.0f;
        return false;
    }

    /* Compute z-score against baseline */
    float variance = running_stats_variance(&det->stats);
    float stddev = sqrtf(variance);
    float z = (mag - det->stats.mean) / stddev;
    if (z < 0.0f) {
        z = -z;
    }

    det->last_zscore = z;
    det->anomaly = (z > ANOMALY_Z_THRESH);

    /* Update baseline only if not anomalous */
    if (!det->anomaly) {
        running_stats_update(&det->stats, mag);
    }

    return det->anomaly;
}

/* ---------------- Example Usage ---------------- */

/*
 * Replace this with your platform-specific accelerometer read.
 * Units can be g, m/s^2, or raw counts, but keep them consistent.
 */
extern bool accel_read(accel_sample_t *out);

int main(void)
{
    anomaly_detector_t detector;
    anomaly_detector_init(&detector);

    while (1) {
        accel_sample_t sample;
        if (accel_read(&sample)) {
            bool anomaly = anomaly_detector_process(&detector, sample);

            if (anomaly) {
                /* Handle anomaly: log, raise interrupt, send packet, etc. */
                // e.g., gpio_set(ALARM_PIN, 1);
            }
        }
    }

    return 0;
}
```

