extern "C" {
#endif

#define PIPELINE_WINDOW_SIZE 32
#define PIPELINE_BASELINE_ALPHA 0.01f   // baseline smoothing factor
#define PIPELINE_ANOMALY_THRESHOLD 3.5f // tune per device/data
#define PIPELINE_SPIKE_THRESHOLD 2.0f    // immediate spike threshold

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float baseline_mag;
    float residual_window[PIPELINE_WINDOW_SIZE];
    uint8_t window_index;
    uint8_t window_count;
    float residual_sum;
    float residual_sq_sum;
    bool initialized;
} sensor_pipeline_t;

typedef struct {
    float magnitude;
    float baseline;
    float residual;
    float window_mean;
    float window_stddev;
    float anomaly_score;
    bool anomaly_detected;
} sensor_pipeline_result_t;

void sensor_pipeline_init(sensor_pipeline_t *p);

bool sensor_pipeline_process(
    sensor_pipeline_t *p,
    const accel_sample_t *sample,
    sensor_pipeline_result_t *result
);

