### `sensor_pipeline.c`

```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float compute_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

void sensor_pipeline_init(sensor_pipeline_t *p)
{
    if (!p) return;

    memset(p, 0, sizeof(*p));
    p->initialized = false;
}

static void window_push(sensor_pipeline_t *p, float value)
{
    if (p->window_count < PIPELINE_WINDOW_SIZE) {
        p->residual_window[p->window_index] = value;
        p->residual_sum += value;
        p->residual_sq_sum += value * value;
        p->window_count++;
        p->window_index = (p->window_index + 1) % PIPELINE_WINDOW_SIZE;
    } else {
        float old = p->residual_window[p->window_index];
        p->residual_sum -= old;
        p->residual_sq_sum -= old * old;

        p->residual_window[p->window_index] = value;
        p->residual_sum += value;
        p->residual_sq_sum += value * value;

        p->window_index = (p->window_index + 1) % PIPELINE_WINDOW_SIZE;
    }
}

static void window_stats(const sensor_pipeline_t *p, float *mean, float *stddev)
{
    if (p->window_count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    float n = (float)p->window_count;
    float m = p->residual_sum / n;
    float var = (p->residual_sq_sum / n) - (m * m);

    if (var < 0.0f) var = 0.0f;

    *mean = m;
    *stddev = sqrtf(var);
}

bool sensor_pipeline_process(
    sensor_pipeline_t *p,
    const accel_sample_t *sample,
    sensor_pipeline_result_t *result
)
{
    if (!p || !sample || !result) return false;

    float mag = compute_magnitude(sample->x, sample->y, sample->z);

    if (!p->initialized) {
        p->baseline_mag = mag;
        p->initialized = true;
    } else {
        // Exponential moving average baseline
        p->baseline_mag = (1.0f - PIPELINE_BASELINE_ALPHA) * p->baseline_mag
                        + PIPELINE_BASELINE_ALPHA * mag;
    }

    float residual = mag - p->baseline_mag;
    window_push(p, residual);

    float wmean, wstd;
    window_stats(p, &wmean, &wstd);

    // Simple anomaly score:
    // - normalized absolute residual
    // - plus window energy proxy
    float abs_residual = fabsf(residual);
    float anomaly_score = 0.0f;

    if (wstd > 1e-6f) {
        anomaly_score = abs_residual / wstd;
    } else {
        anomaly_score = abs_residual;
    }

    bool spike = abs_residual > PIPELINE_SPIKE_THRESHOLD;
    bool anomaly = (anomaly_score > PIPELINE_ANOMALY_THRESHOLD) || spike;

    result->magnitude = mag;
    result->baseline = p->baseline_mag;
    result->residual = residual;
    result->window_mean = wmean;
    result->window_stddev = wstd;
    result->anomaly_score = anomaly_score;
    result->anomaly_detected = anomaly;

    return true;
}
