Below is a solid **initial embedded C implementation** of a sensor-processing pipeline for **accelerometer anomaly detection**. It is designed to be:

- **streaming-friendly**
- **low memory**
- **fixed-size / embedded-oriented**
- easy to extend with filtering, calibration, and more advanced detection

It uses a simple pipeline:

1. **Acquire sample**
2. **Optional calibration / offset removal**
3. **Compute magnitude**
4. **Smooth with moving average**
5. **Detect anomaly using deviation from baseline**

---

## 1) Design overview

### Assumptions
- Accelerometer data arrives as `(ax, ay, az)` in raw or scaled units.
- Samples are processed one at a time.
- An anomaly is a sudden deviation in acceleration magnitude from a learned baseline.
- The system should avoid dynamic allocation.

### Detection strategy
We compute:

- `mag = sqrt(ax² + ay² + az²)`  
- `smoothed_mag = moving_average(mag)`
- `baseline = slow moving average of smoothed_mag`
- `deviation = abs(smoothed_mag - baseline)`

If `deviation > threshold`, flag anomaly.

This is a simple and practical starting point for embedded systems.

---

## 2) Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE         8
#define BASELINE_ALPHA      0.01f   // Slow baseline adaptation
#define ANOMALY_THRESHOLD   2.5f    // Tune for your sensor units
#define MIN_BASELINE_SAMPLES 32

typedef struct {
    float ax;
    float ay;
    float az;
} AccelSample;

typedef struct {
    float mag_window[WINDOW_SIZE];
    uint8_t window_index;
    uint8_t window_count;
    float window_sum;

    float baseline;
    uint32_t sample_count;

    // Optional calibration offsets
    float offset_x;
    float offset_y;
    float offset_z;
} SensorPipeline;

typedef struct {
    bool anomaly_detected;
    float magnitude;
    float smoothed_magnitude;
    float baseline;
    float deviation;
} DetectionResult;

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

static float compute_magnitude(const AccelSample *s) {
    return sqrtf((s->ax * s->ax) + (s->ay * s->ay) + (s->az * s->az));
}

void pipeline_init(SensorPipeline *p) {
    for (int i = 0; i < WINDOW_SIZE; i++) {
        p->mag_window[i] = 0.0f;
    }

    p->window_index = 0;
    p->window_count = 0;
    p->window_sum = 0.0f;

    p->baseline = 0.0f;
    p->sample_count = 0;

    p->offset_x = 0.0f;
    p->offset_y = 0.0f;
    p->offset_z = 0.0f;
}

void pipeline_set_offsets(SensorPipeline *p, float ox, float oy, float oz) {
    p->offset_x = ox;
    p->offset_y = oy;
    p->offset_z = oz;
}

static float moving_average_update(SensorPipeline *p, float value) {
    if (p->window_count < WINDOW_SIZE) {
        p->mag_window[p->window_index] = value;
        p->window_sum += value;
        p->window_count++;
    } else {
        p->window_sum -= p->mag_window[p->window_index];
        p->mag_window[p->window_index] = value;
        p->window_sum += value;
    }

    p->window_index = (p->window_index + 1) % WINDOW_SIZE;
    return p->window_sum / (float)p->window_count;
}

DetectionResult pipeline_process_sample(SensorPipeline *p, AccelSample raw) {
    DetectionResult result = {0};

    // Apply calibration offsets
    AccelSample s;
    s.ax = raw.ax - p->offset_x;
    s.ay = raw.ay - p->offset_y;
    s.az = raw.az - p->offset_z;

    // Compute magnitude
    result.magnitude = compute_magnitude(&s);

    // Smooth signal
    result.smoothed_magnitude = moving_average_update(p, result.magnitude);

    // Initialize baseline during startup
    if (p->sample_count == 0) {
        p->baseline = result.smoothed_magnitude;
    } else {
        // Slow baseline tracking
        p->baseline = (1.0f - BASELINE_ALPHA) * p->baseline +
                      BASELINE_ALPHA * result.smoothed_magnitude;
    }

    result.baseline = p->baseline;
    result.deviation = fast_absf(result.smoothed_magnitude - p->baseline);

    // Avoid false positives during warm-up
    if (p->sample_count >= MIN_BASELINE_SAMPLES) {
        if (result.deviation > ANOMALY_THRESHOLD) {
            result.anomaly_detected = true;
        }
    }

    p->sample_count++;
    return result;
}
```

