### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float compute_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

void sensor_pipeline_init(sensor_pipeline_t *p,
                          float *window_buffer,
                          uint16_t window_size,
                          float mean_threshold,
                          float variance_threshold,
                          float jerk_threshold,
                          float anomaly_score_threshold) {
    if (!p || !window_buffer || window_size == 0) {
        return;
    }

    memset(p, 0, sizeof(*p));
    p->window = window_buffer;
    p->window_size = window_size;
    p->mean_threshold = mean_threshold;
    p->variance_threshold = variance_threshold;
    p->jerk_threshold = jerk_threshold;
    p->anomaly_score_threshold = anomaly_score_threshold;

    for (uint16_t i = 0; i < window_size; i++) {
        p->window[i] = 0.0f;
    }
}

static void update_window_stats(sensor_pipeline_t *p, float value) {
    float old = p->window[p->index];

    // Remove old sample from sums
    p->sum -= old;
    p->sum_sq -= old * old;

    // Insert new sample
    p->window[p->index] = value;
    p->sum += value;
    p->sum_sq += value * value;

    p->index = (p->index + 1) % p->window_size;
    if (p->count < p->window_size) {
        p->count++;
    }
}

anomaly_result_t sensor_pipeline_process(sensor_pipeline_t *p,
                                         const accel_sample_t *sample) {
    anomaly_result_t result = {0};

    if (!p || !sample || p->window_size == 0) {
        return result;
    }

    // 1) Feature: magnitude
    float mag = compute_magnitude(sample->ax, sample->ay, sample->az);
    result.magnitude = mag;

    // 2) Update moving window stats
    update_window_stats(p, mag);

    float mean = 0.0f;
    float variance = 0.0f;

    if (p->count > 0) {
        mean = p->sum / (float)p->count;
        float mean_sq = p->sum_sq / (float)p->count;
        variance = mean_sq - (mean * mean);
        if (variance < 0.0f) {
            variance = 0.0f; // numerical safety
        }
    }

    result.mean = mean;
    result.variance = variance;

    // 3) Feature: jerk (change in magnitude)
    float jerk = 0.0f;
    if (p->has_prev) {
        jerk = fabsf(mag - p->prev_magnitude);
    }
    p->prev_magnitude = mag;
    p->has_prev = true;
    result.jerk = jerk;

    // 4) Simple anomaly scoring
    float score = 0.0f;

    float mean_dev = fabsf(mag - mean);
    if (mean_dev > p->mean_threshold) {
        score += 1.0f;
    }

    if (variance > p->variance_threshold) {
        score += 1.0f;
    }

    if (jerk > p->jerk_threshold) {
        score += 1.0f;
    }

    result.anomaly_score = score;
    result.anomaly = (score >= p->anomaly_score_threshold);

    return result;
}
```

