- **streaming-friendly**
- **low memory**
- **fixed-size**
- suitable as a starting point for **MCU/RTOS** integration

It includes:

1. **sample ingestion**
2. **simple preprocessing**
3. **feature extraction**
4. **baseline tracking**
5. **anomaly scoring**
6. **event callback hook**

---

## Design assumptions

- Input is 3-axis accelerometer data: `ax, ay, az`
- Sampling rate is fixed or approximately fixed
- An anomaly is detected when motion energy deviates significantly from a learned baseline
- This is an initial implementation, so it uses a lightweight statistical approach rather than ML

---

## Pipeline overview

For each sample:

1. Compute magnitude:  
   `mag = sqrt(ax² + ay² + az²)`

2. Remove gravity-ish offset using a slow baseline estimate

3. Compute a short-window feature:
   - mean absolute deviation / variance-like energy
   - peak magnitude
   - derivative energy

4. Compare against baseline statistics

5. Raise anomaly if score exceeds threshold for enough consecutive windows

---

## Embedded C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef ANOMALY_CONSECUTIVE_WINDOWS
#define ANOMALY_CONSECUTIVE_WINDOWS 3
#endif

#ifndef BASELINE_ALPHA
// Smaller = slower adaptation
#define BASELINE_ALPHA 0.01f
#endif

#ifndef VAR_ALPHA
#define VAR_ALPHA 0.02f
#endif

#ifndef ANOMALY_THRESHOLD
#define ANOMALY_THRESHOLD 3.0f
#endif

typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    float mean;
    float var;
    float min;
    float max;
} feature_stats_t;

typedef struct {
    // Ring buffer for magnitudes
    float mag_buf[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;

    // Baseline magnitude estimate
    float baseline_mag;

    // Baseline feature statistics
    float feature_mean;
    float feature_var;

    // Previous magnitude for derivative feature
    float prev_mag;

    // Consecutive anomaly counter
    uint8_t anomaly_streak;

    // Initialization flag
    bool initialized;
} anomaly_detector_t;

typedef void (*anomaly_callback_t)(const accel_sample_t *sample,
                                   float score,
                                   const feature_stats_t *features);

/* Utility: compute vector magnitude */
static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->ax * s->ax) + (s->ay * s->ay) + (s->az * s->az));
}

/* Initialize detector */
void anomaly_detector_init(anomaly_detector_t *det)
{
    memset(det, 0, sizeof(*det));
    det->initialized = true;
}

/* Update running mean/variance using exponential moving average */
static void update_ema_stats(float x, float alpha, float *mean, float *var)
{
    float delta = x - *mean;
    *mean += alpha * delta;
    *var = (1.0f - alpha) * (*var) + alpha * delta * delta;
}

/* Process one accelerometer sample.
   Returns true if anomaly is detected. */
bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *sample,
                              anomaly_callback_t cb)
{
    if (!det || !sample || !det->initialized) {
        return false;
    }

    float mag = accel_magnitude(sample);

    // Initialize baseline on first sample
    if (det->count == 0) {
        det->baseline_mag = mag;
        det->feature_mean = 0.0f;
        det->feature_var = 1e-3f;
        det->prev_mag = mag;
    }

    // Remove slow baseline to focus on dynamic motion
    float centered = mag - det->baseline_mag;

    // Short-term feature: energy-like measure
    float deriv = mag - det->prev_mag;
    float feature = fabsf(centered) + 0.5f * fabsf(deriv);

    // Update ring buffer
    det->mag_buf[det->idx] = feature;
    det->idx = (det->idx + 1) % WINDOW_SIZE;
    if (det->count < WINDOW_SIZE) {
        det->count++;
    }

    // Update slow baseline magnitude only when not strongly anomalous
    // This prevents the baseline from chasing spikes too quickly.
    if (det->count < WINDOW_SIZE / 2) {
        update_ema_stats(mag, BASELINE_ALPHA, &det->baseline_mag, &det->feature_var);
    }

    det->prev_mag = mag;

    // Need enough samples to evaluate
    if (det->count < WINDOW_SIZE) {
        return false;
    }

    // Compute window statistics
    feature_stats_t stats;
    stats.min = det->mag_buf[0];
    stats.max = det->mag_buf[0];
    stats.mean = 0.0f;
    stats.var = 0.0f;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        float x = det->mag_buf[i];
        stats.mean += x;
        if (x < stats.min) stats.min = x;
        if (x > stats.max) stats.max = x;
    }
    stats.mean /= (float)WINDOW_SIZE;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        float d = det->mag_buf[i] - stats.mean;
        stats.var += d * d;
    }
    stats.var /= (float)WINDOW_SIZE;

    // Compare against learned baseline
    // Use a z-score-like metric
    float baseline_std = sqrtf(det->feature_var + 1e-6f);
    float score = fabsf(stats.mean - det->feature_mean) / baseline_std;

    // Also incorporate variance spike
    float var_score = stats.var / (det->feature_var + 1e-6f);

    // Combined anomaly score
    float combined_score = score + 0.5f * var_score;

    bool anomaly = false;
    if (combined_score > ANOMALY_THRESHOLD) {
        det->anomaly_streak++;
        if (det->anomaly_streak >= ANOMALY_CONSECUTIVE_WINDOWS) {
            anomaly = true;
        }
    } else {
        det->anomaly_streak = 0;
    }

    // Update baseline feature stats only when not anomalous
    if (!anomaly) {
        update_ema_stats(stats.mean, VAR_ALPHA, &det->feature_mean, &det->feature_var);
    }

    if (anomaly && cb) {
        cb(sample, combined_score, &stats);
    }

    return anomaly;
}
```

