Below is a solid **initial embedded C implementation** of a sensor-processing pipeline for **accelerometer anomaly detection**. It is designed to be:

- **streaming / real-time**
- **low memory**
- **fixed-size**
- easy to port to an MCU
- suitable as a starting point for tuning

It uses:
1. **High-pass filtering** to remove gravity / slow drift
2. **Magnitude calculation**
3. **Sliding window statistics**
4. **Simple anomaly score** based on deviation from baseline

---

## 1) Pipeline overview

### Input
- Raw accelerometer samples: `ax, ay, az`
- Sample rate assumed fixed (e.g. 100 Hz)

### Processing stages
1. **Calibration / offset correction**  
   Optional, subtract bias from each axis.

2. **High-pass filter**  
   Removes DC component and slow movement.

3. **Magnitude computation**  
   `mag = sqrt(ax² + ay² + az²)`  
   For embedded efficiency, you can use squared magnitude if desired.

4. **Sliding window feature extraction**
   - mean
   - variance
   - peak-to-peak
   - energy

5. **Anomaly decision**
   - compare current window stats to baseline
   - flag anomaly if score exceeds threshold

---

## 2) Example C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define AXIS_COUNT          3
#define WINDOW_SIZE         32
#define BASELINE_WINDOWS    16

// Tune these for your sensor/sample rate
#define HP_ALPHA            0.95f
#define ANOMALY_THRESHOLD   3.0f

typedef struct {
    float x_prev;
    float y_prev;
} HighPassFilter;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float sum;
    float sum_sq;
    float min_val;
    float max_val;
} SlidingWindow;

typedef struct {
    float mean;
    float variance;
    float peak_to_peak;
    float energy;
} WindowFeatures;

typedef struct {
    HighPassFilter hp[AXIS_COUNT];
    SlidingWindow mag_window;

    // Baseline statistics
    float baseline_mean;
    float baseline_std;
    uint16_t baseline_count;

    bool baseline_ready;
} SensorPipeline;

typedef struct {
    bool anomaly;
    float score;
    WindowFeatures features;
} DetectionResult;

static void hp_init(HighPassFilter *f) {
    f->x_prev = 0.0f;
    f->y_prev = 0.0f;
}

static float hp_update(HighPassFilter *f, float x) {
    // Simple 1st-order high-pass filter:
    // y[n] = alpha * (y[n-1] + x[n] - x[n-1])
    float y = HP_ALPHA * (f->y_prev + x - f->x_prev);
    f->x_prev = x;
    f->y_prev = y;
    return y;
}

static void window_init(SlidingWindow *w) {
    memset(w->buffer, 0, sizeof(w->buffer));
    w->index = 0;
    w->count = 0;
    w->sum = 0.0f;
    w->sum_sq = 0.0f;
    w->min_val = 0.0f;
    w->max_val = 0.0f;
}

static void window_push(SlidingWindow *w, float value) {
    if (w->count < WINDOW_SIZE) {
        w->buffer[w->index] = value;
        w->sum += value;
        w->sum_sq += value * value;

        if (w->count == 0) {
            w->min_val = value;
            w->max_val = value;
        } else {
            if (value < w->min_val) w->min_val = value;
            if (value > w->max_val) w->max_val = value;
        }

        w->count++;
        w->index = (w->index + 1) % WINDOW_SIZE;
    } else {
        float old = w->buffer[w->index];
        w->buffer[w->index] = value;

        w->sum -= old;
        w->sum_sq -= old * old;
        w->sum += value;
        w->sum_sq += value * value;

        // Recompute min/max if needed
        if (old == w->min_val || old == w->max_val) {
            float min_v = w->buffer[0];
            float max_v = w->buffer[0];
            for (int i = 1; i < WINDOW_SIZE; i++) {
                if (w->buffer[i] < min_v) min_v = w->buffer[i];
                if (w->buffer[i] > max_v) max_v = w->buffer[i];
            }
            w->min_val = min_v;
            w->max_val = max_v;
        } else {
            if (value < w->min_val) w->min_val = value;
            if (value > w->max_val) w->max_val = value;
        }

        w->index = (w->index + 1) % WINDOW_SIZE;
    }
}

static WindowFeatures window_features(const SlidingWindow *w) {
    WindowFeatures f = {0};

    if (w->count == 0) return f;

    f.mean = w->sum / (float)w->count;
    float mean_sq = f.mean * f.mean;
    float avg_sq = w->sum_sq / (float)w->count;
    f.variance = (avg_sq > mean_sq) ? (avg_sq - mean_sq) : 0.0f;
    f.peak_to_peak = w->max_val - w->min_val;
    f.energy = avg_sq;

    return f;
}

static void pipeline_init(SensorPipeline *p) {
    for (int i = 0; i < AXIS_COUNT; i++) {
        hp_init(&p->hp[i]);
    }
    window_init(&p->mag_window);
    p->baseline_mean = 0.0f;
    p->baseline_std = 1.0f;
    p->baseline_count = 0;
    p->baseline_ready = false;
}

static void update_baseline(SensorPipeline *p, float feature_value) {
    // Simple running mean/std baseline over initial windows
    p->baseline_count++;

    float delta = feature_value - p->baseline_mean;
    p->baseline_mean += delta / (float)p->baseline_count;

    // Welford-style variance update using baseline_mean as running mean
    // For initial implementation, keep a simple approximation:
    float diff = feature_value - p->baseline_mean;
    float var = p->baseline_std * p->baseline_std;
    var = ((p->baseline_count - 1) * var + diff * diff) / (float)p->baseline_count;
    p->baseline_std = sqrtf(var + 1e-6f);

    if (p->baseline_count >= BASELINE_WINDOWS) {
        p->baseline_ready = true;
    }
}

DetectionResult pipeline_process_sample(SensorPipeline *p, float ax, float ay, float az) {
    DetectionResult result = {0};

    // 1) High-pass filter each axis
    float fx = hp_update(&p->hp[0], ax);
    float fy = hp_update(&p->hp[1], ay);
    float fz = hp_update(&p->hp[2], az);

    // 2) Magnitude
    float mag = sqrtf(fx * fx + fy * fy + fz * fz);

    // 3) Sliding window
    window_push(&p->mag_window, mag);

    // Need a full window before making decisions
    if (p->mag_window.count < WINDOW_SIZE) {
        return result;
    }

    // 4) Extract features
    result.features = window_features(&p->mag_window);

    // 5) Baseline / anomaly detection
    if (!p->baseline_ready) {
        update_baseline(p, result.features.mean);
        return result;
    }

    // Score based on deviation from baseline mean
    float z = (result.features.mean - p->baseline_mean) / (p->baseline_std + 1e-6f);
    result.score = fabsf(z);

    // Optional: incorporate variance and peak-to-peak
    float var_score = result.features.variance / (p->baseline_std * p->baseline_std + 1e-6f);
    float p2p_score = result.features.peak_to_peak / (p->baseline_std + 1e-6f);

    // Weighted anomaly score
    result.score = 0.6f * result.score + 0.25f * var_score + 0.15f * p2p_score;

    result.anomaly = (result.score > ANOMALY_THRESHOLD);
    return result;
}
```

