Below is a solid **initial embedded C implementation** of a sensor-processing pipeline for **accelerometer anomaly detection**. It is designed to be lightweight, streaming-friendly, and suitable as a starting point for MCU firmware.

## What it does
- Accepts raw accelerometer samples `(x, y, z)`
- Applies a simple **low-pass filter** to smooth noise
- Computes **magnitude**
- Maintains a **running baseline** and **variance estimate**
- Flags an anomaly when the current magnitude deviates too far from the baseline for a configurable number of samples

---

## Embedded C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define SENSOR_ALPHA            0.10f   // Low-pass filter coefficient
#define BASELINE_ALPHA           0.01f   // Baseline adaptation rate
#define VAR_ALPHA                0.01f   // Variance adaptation rate
#define ANOMALY_Z_THRESHOLD     3.0f     // Number of std devs from baseline
#define ANOMALY_HOLD_COUNT      5        // Consecutive samples required
#define MIN_VARIANCE            1e-6f

/* =========================
 * Data types
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
} accel_sample_t;

typedef struct {
    float x_filt;
    float y_filt;
    float z_filt;

    float baseline_mag;
    float variance_mag;

    uint8_t anomaly_count;
    bool initialized;
} anomaly_detector_t;

typedef struct {
    float magnitude;
    float baseline;
    float stddev;
    bool anomaly;
} anomaly_result_t;

/* =========================
 * Utility
 * ========================= */
static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float accel_magnitude(const accel_sample_t *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

/* =========================
 * API
 * ========================= */
void anomaly_detector_init(anomaly_detector_t *det)
{
    if (!det) return;

    det->x_filt = 0.0f;
    det->y_filt = 0.0f;
    det->z_filt = 0.0f;
    det->baseline_mag = 0.0f;
    det->variance_mag = 0.0f;
    det->anomaly_count = 0;
    det->initialized = false;
}

static float low_pass(float prev, float input, float alpha)
{
    return prev + alpha * (input - prev);
}

anomaly_result_t anomaly_detector_process(anomaly_detector_t *det, const accel_sample_t *raw)
{
    anomaly_result_t result = {0};

    if (!det || !raw) {
        return result;
    }

    /* First sample initializes state */
    if (!det->initialized) {
        det->x_filt = raw->x;
        det->y_filt = raw->y;
        det->z_filt = raw->z;

        accel_sample_t init = { det->x_filt, det->y_filt, det->z_filt };
        det->baseline_mag = accel_magnitude(&init);
        det->variance_mag = 0.0f;
        det->initialized = true;

        result.magnitude = det->baseline_mag;
        result.baseline = det->baseline_mag;
        result.stddev = 0.0f;
        result.anomaly = false;
        return result;
    }

    /* Filter raw axes */
    det->x_filt = low_pass(det->x_filt, raw->x, SENSOR_ALPHA);
    det->y_filt = low_pass(det->y_filt, raw->y, SENSOR_ALPHA);
    det->z_filt = low_pass(det->z_filt, raw->z, SENSOR_ALPHA);

    accel_sample_t filt = { det->x_filt, det->y_filt, det->z_filt };
    float mag = accel_magnitude(&filt);

    /* Update baseline and variance using exponential moving estimates */
    float delta = mag - det->baseline_mag;
    det->baseline_mag += BASELINE_ALPHA * delta;

    /* Exponential moving variance estimate */
    det->variance_mag = (1.0f - VAR_ALPHA) * det->variance_mag + VAR_ALPHA * (delta * delta);

    float variance = (det->variance_mag < MIN_VARIANCE) ? MIN_VARIANCE : det->variance_mag;
    float stddev = fast_sqrtf(variance);

    /* Anomaly decision */
    float z_score = fabsf(mag - det->baseline_mag) / stddev;
    bool is_anomaly_now = (z_score > ANOMALY_Z_THRESHOLD);

    if (is_anomaly_now) {
        if (det->anomaly_count < 255) {
            det->anomaly_count++;
        }
    } else {
        det->anomaly_count = 0;
    }

    bool anomaly = (det->anomaly_count >= ANOMALY_HOLD_COUNT);

    result.magnitude = mag;
    result.baseline = det->baseline_mag;
    result.stddev = stddev;
    result.anomaly = anomaly;

    return result;
}
```

