## 3) Example C implementation

This is a compact starting point suitable for MCU firmware.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define WINDOW_SIZE        32
#define BASELINE_ALPHA     0.01f   // slow adaptation
#define Z_THRESHOLD        3.0f
#define MIN_BASELINE_SAMPLES 100

typedef struct {
    float ax, ay, az;
} accel_sample_t;

typedef struct {
    float mean;
    float stddev;
    float peak_to_peak;
    float rms;
    float jerk_mean;
} feature_vector_t;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;
    float prev_mag;
    bool has_prev;
} window_t;

typedef struct {
    feature_vector_t mean;
    feature_vector_t var;
    uint32_t sample_count;
} baseline_t;

typedef struct {
    window_t window;
    baseline_t baseline;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float compute_magnitude(accel_sample_t s) {
    return fast_sqrtf(s.ax * s.ax + s.ay * s.ay + s.az * s.az);
}

static void window_init(window_t *w) {
    memset(w, 0, sizeof(*w));
}

static void baseline_init(baseline_t *b) {
    memset(b, 0, sizeof(*b));
}

static void detector_init(anomaly_detector_t *d) {
    window_init(&d->window);
    baseline_init(&d->baseline);
}

static void window_push(window_t *w, float value) {
    w->buffer[w->index] = value;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static bool window_full(const window_t *w) {
    return w->count == WINDOW_SIZE;
}

static feature_vector_t extract_features(const window_t *w) {
    feature_vector_t f = {0};

    if (w->count == 0) {
        return f;
    }

    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = w->buffer[0];
    float max_v = w->buffer[0];
    float jerk_sum = 0.0f;

    for (uint16_t i = 0; i < w->count; i++) {
        float v = w->buffer[i];
        sum += v;
        sum_sq += v * v;
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;

        if (i > 0) {
            jerk_sum += fabsf(w->buffer[i] - w->buffer[i - 1]);
        }
    }

    f.mean = sum / (float)w->count;
    f.rms = fast_sqrtf(sum_sq / (float)w->count);
    f.stddev = fast_sqrtf((sum_sq / (float)w->count) - (f.mean * f.mean));
    if (f.stddev < 0.0f) f.stddev = 0.0f;
    f.peak_to_peak = max_v - min_v;
    f.jerk_mean = (w->count > 1) ? (jerk_sum / (float)(w->count - 1)) : 0.0f;

    return f;
}

static void baseline_update(baseline_t *b, const feature_vector_t *x) {
    b->sample_count++;

    if (b->sample_count == 1) {
        b->mean = *x;
        memset(&b->var, 0, sizeof(b->var));
        return;
    }

    // Exponential moving average for mean and variance
    float a = BASELINE_ALPHA;

    #define UPDATE_FIELD(field) do { \
        float delta = x->field - b->mean.field; \
        b->mean.field += a * delta; \
        float diff = x->field - b->mean.field; \
        b->var.field = (1.0f - a) * b->var.field + a * diff * diff; \
    } while (0)

    UPDATE_FIELD(mean);
    UPDATE_FIELD(stddev);
    UPDATE_FIELD(peak_to_peak);
    UPDATE_FIELD(rms);
    UPDATE_FIELD(jerk_mean);

    #undef UPDATE_FIELD
}

static float z_score(float x, float mean, float var) {
    float std = fast_sqrtf(var);
    if (std < 1e-6f) {
        return 0.0f;
    }
    return fabsf(x - mean) / std;
}

static bool detect_anomaly(const feature_vector_t *f, const baseline_t *b) {
    if (b->sample_count < MIN_BASELINE_SAMPLES) {
        return false; // still learning normal behavior
    }

    float z_mean = z_score(f->mean, b->mean.mean, b->var.mean);
    float z_std  = z_score(f->stddev, b->mean.stddev, b->var.stddev);
    float z_p2p  = z_score(f->peak_to_peak, b->mean.peak_to_peak, b->var.peak_to_peak);
    float z_rms  = z_score(f->rms, b->mean.rms, b->var.rms);
    float z_jerk = z_score(f->jerk_mean, b->mean.jerk_mean, b->var.jerk_mean);

    // Simple rule: anomaly if any feature is too far from baseline
    if (z_mean > Z_THRESHOLD) return true;
    if (z_std  > Z_THRESHOLD) return true;
    if (z_p2p  > Z_THRESHOLD) return true;
    if (z_rms  > Z_THRESHOLD) return true;
    if (z_jerk > Z_THRESHOLD) return true;

    return false;
}

// Call this for each new accelerometer sample.
// Returns true if anomaly detected.
bool anomaly_detector_process(anomaly_detector_t *d, accel_sample_t s) {
    float mag = compute_magnitude(s);
    window_push(&d->window, mag);

    if (!window_full(&d->window)) {
        return false;
    }

    feature_vector_t f = extract_features(&d->window);
    bool anomaly = detect_anomaly(&f, &d->baseline);

    // Update baseline only if not anomalous
    if (!anomaly) {
        baseline_update(&d->baseline, &f);
    }

    return anomaly;
}
