#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#ifdef __cplusplus
extern "C" {
#endif

#define PIPELINE_WINDOW_SIZE   32
#define PIPELINE_ANOMALY_COUNT 3

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef enum {
    ANOMALY_NONE = 0,
    ANOMALY_SPIKE,
    ANOMALY_DROP,
    ANOMALY_VIBRATION
} anomaly_type_t;

typedef struct {
    bool anomaly_detected;
    anomaly_type_t type;
    int32_t score;
    int32_t baseline;
    int32_t filtered_value;
} anomaly_result_t;

typedef struct {
    int32_t mag_window[PIPELINE_WINDOW_SIZE];
    uint8_t window_index;
    uint8_t window_count;

    int32_t baseline;
    int32_t filtered;
    int32_t deviation;

    uint8_t anomaly_streak;
    int32_t threshold;
    int32_t vibration_threshold;
} sensor_pipeline_t;

void sensor_pipeline_init(sensor_pipeline_t *p);
anomaly_result_t sensor_pipeline_process_sample(sensor_pipeline_t *p, const accel_sample_t *sample);

#ifdef __cplusplus
}
#endif

#endif
