### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <stdlib.h>

static int32_t abs32(int32_t v) {
    return (v < 0) ? -v : v;
}

// Integer square root approximation for magnitude
static int32_t isqrt32(uint32_t x) {
    uint32_t op = x;
    uint32_t res = 0;
    uint32_t one = 1u << 30;

    while (one > op) {
        one >>= 2;
    }

    while (one != 0) {
        if (op >= res + one) {
            op -= res + one;
            res = (res >> 1) + one;
        } else {
            res >>= 1;
        }
        one >>= 2;
    }
    return (int32_t)res;
}

static int32_t accel_magnitude(const accel_sample_t *s) {
    int32_t x = s->x;
    int32_t y = s->y;
    int32_t z = s->z;

    uint32_t sum = (uint32_t)(x * x) + (uint32_t)(y * y) + (uint32_t)(z * z);
    return isqrt32(sum);
}

void sensor_pipeline_init(sensor_pipeline_t *p) {
    if (!p) return;

    for (int i = 0; i < PIPELINE_WINDOW_SIZE; i++) {
        p->mag_window[i] = 0;
    }

    p->window_index = 0;
    p->window_count = 0;
    p->baseline = 0;
    p->filtered = 0;
    p->deviation = 0;
    p->anomaly_streak = 0;

    // Tune these for your sensor scale and sampling rate
    p->threshold = 250;            // deviation threshold
    p->vibration_threshold = 120;   // repeated smaller deviations
}

static int32_t compute_mean(const int32_t *buf, uint8_t count) {
    if (count == 0) return 0;

    int64_t sum = 0;
    for (uint8_t i = 0; i < count; i++) {
        sum += buf[i];
    }
    return (int32_t)(sum / count);
}

anomaly_result_t sensor_pipeline_process_sample(sensor_pipeline_t *p, const accel_sample_t *sample) {
    anomaly_result_t result = {0};

    if (!p || !sample) {
        return result;
    }

    int32_t mag = accel_magnitude(sample);

    // Simple low-pass filter: filtered = 7/8 * filtered + 1/8 * mag
    if (p->window_count == 0) {
        p->filtered = mag;
    } else {
        p->filtered = (p->filtered * 7 + mag) / 8;
    }

    // Update rolling window
    p->mag_window[p->window_index] = p->filtered;
    p->window_index = (p->window_index + 1) % PIPELINE_WINDOW_SIZE;
    if (p->window_count < PIPELINE_WINDOW_SIZE) {
        p->window_count++;
    }

    // Baseline = mean of rolling window
    p->baseline = compute_mean(p->mag_window, p->window_count);

    // Deviation from baseline
    p->deviation = p->filtered - p->baseline;
    int32_t abs_dev = abs32(p->deviation);

    // Basic anomaly streak logic
    if (abs_dev > p->threshold) {
        p->anomaly_streak++;
    } else if (abs_dev < p->vibration_threshold) {
        if (p->anomaly_streak > 0) {
            p->anomaly_streak--;
        }
    }

    // Determine anomaly type
    if (p->anomaly_streak >= PIPELINE_ANOMALY_COUNT) {
        result.anomaly_detected = true;
        result.score = abs_dev;
        result.baseline = p->baseline;
        result.filtered_value = p->filtered;

        if (p->deviation > 0) {
            result.type = ANOMALY_SPIKE;
        } else {
            result.type = ANOMALY_DROP;
        }

        // Reset streak after event to avoid repeated firing
        p->anomaly_streak = 0;
    } else if (abs_dev > (p->threshold / 2) && p->window_count >= PIPELINE_WINDOW_SIZE / 2) {
        // Optional vibration-like condition
        result.anomaly_detected = false;
        result.type = ANOMALY_VIBRATION;
        result.score = abs_dev;
        result.baseline = p->baseline;
        result.filtered_value = p->filtered;
    } else {
        result.anomaly_detected = false;
        result.type = ANOMALY_NONE;
        result.score = abs_dev;
        result.baseline = p->baseline;
        result.filtered_value = p->filtered;
    }

    return result;
}
