    if (r->anomaly_detected) {
        printf("[ALERT] t=%lu type=%s score=%ld baseline=%ld filtered=%ld\n",
               (unsigned long)ts, type_str,
               (long)r->score, (long)r->baseline, (long)r->filtered_value);
    }
}

