## Design overview

### Pipeline stages
1. **Input**: raw accelerometer samples `(ax, ay, az)`
2. **Preprocessing**:
   - compute magnitude
   - remove slow drift using a running mean
3. **Windowing**:
   - maintain a fixed-size ring buffer of recent magnitudes
4. **Feature extraction**:
   - mean absolute deviation / variance-like energy
   - peak deviation
   - short-term spike count
5. **Decision**:
   - anomaly if score exceeds threshold for N consecutive windows
   - clear anomaly only after score stays low for M windows

---

## Embedded C implementation

```c
/*
 * accel_anomaly_pipeline.c
 *
 * Initial embedded sensor-processing pipeline for anomaly detection
 * from accelerometer data.
 *
 * Assumptions:
 * - Called once per accelerometer sample.
 * - Works with float for simplicity; can be ported to fixed-point later.
 * - Designed for small MCUs with limited RAM.
 */

#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#ifndef WINDOW_SIZE
#define WINDOW_SIZE 32
#endif

#ifndef BASELINE_ALPHA
#define BASELINE_ALPHA 0.01f   // running mean update rate
#endif

#ifndef ANOMALY_SCORE_THRESHOLD
#define ANOMALY_SCORE_THRESHOLD 3.0f
#endif

#ifndef ANOMALY_ENTER_COUNT
#define ANOMALY_ENTER_COUNT 3
#endif

#ifndef ANOMALY_EXIT_COUNT
#define ANOMALY_EXIT_COUNT 5
#endif

typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    // Baseline tracking
    float baseline_mag;

    // Ring buffer of detrended magnitudes
    float window[WINDOW_SIZE];
    uint16_t idx;
    uint16_t count;

    // Detection state
    uint8_t high_score_count;
    uint8_t low_score_count;
    bool anomaly_active;

    // Last computed metrics
    float last_mean;
    float last_variance;
    float last_peak;
    float last_score;
} accel_anomaly_ctx_t;

typedef struct {
    bool anomaly;
    float score;
    float mean;
    float variance;
    float peak;
} accel_anomaly_result_t;

static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->ax * s->ax) + (s->ay * s->ay) + (s->az * s->az));
}

void accel_anomaly_init(accel_anomaly_ctx_t *ctx)
{
    if (!ctx) return;

    ctx->baseline_mag = 0.0f;
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        ctx->window[i] = 0.0f;
    }
    ctx->idx = 0;
    ctx->count = 0;
    ctx->high_score_count = 0;
    ctx->low_score_count = 0;
    ctx->anomaly_active = false;

    ctx->last_mean = 0.0f;
    ctx->last_variance = 0.0f;
    ctx->last_peak = 0.0f;
    ctx->last_score = 0.0f;
}

static void compute_window_features(const accel_anomaly_ctx_t *ctx,
                                    float *mean,
                                    float *variance,
                                    float *peak)
{
    float sum = 0.0f;
    float sumsq = 0.0f;
    float max_abs = 0.0f;

    if (ctx->count == 0) {
        *mean = 0.0f;
        *variance = 0.0f;
        *peak = 0.0f;
        return;
    }

    for (uint16_t i = 0; i < ctx->count; i++) {
        float x = ctx->window[i];
        sum += x;
        sumsq += x * x;
        float ax = fabsf(x);
        if (ax > max_abs) {
            max_abs = ax;
        }
    }

    *mean = sum / (float)ctx->count;
    *variance = (sumsq / (float)ctx->count) - (*mean * *mean);
    if (*variance < 0.0f) {
        *variance = 0.0f; // numerical safety
    }
    *peak = max_abs;
}

static float compute_anomaly_score(float mean, float variance, float peak)
{
    /*
     * Simple heuristic score:
     * - variance indicates vibration/instability
     * - peak indicates sudden spikes
     * - mean indicates sustained offset
     *
     * Tune weights based on real data.
     */
    const float w_mean = 0.5f;
    const float w_var  = 1.0f;
    const float w_peak = 1.5f;

    return (w_mean * fabsf(mean)) + (w_var * variance) + (w_peak * peak);
}

accel_anomaly_result_t accel_anomaly_process(accel_anomaly_ctx_t *ctx,
                                             const accel_sample_t *sample)
{
    accel_anomaly_result_t result = {0};

    if (!ctx || !sample) {
        return result;
    }

    // 1) Compute magnitude
    float mag = accel_magnitude(sample);

    // 2) Update baseline using exponential moving average
    if (ctx->count == 0) {
        ctx->baseline_mag = mag;
    } else {
        ctx->baseline_mag = (1.0f - BASELINE_ALPHA) * ctx->baseline_mag
                          + BASELINE_ALPHA * mag;
    }

    // 3) Detrend
    float detrended = mag - ctx->baseline_mag;

    // 4) Store in ring buffer
    ctx->window[ctx->idx] = detrended;
    ctx->idx = (ctx->idx + 1) % WINDOW_SIZE;
    if (ctx->count < WINDOW_SIZE) {
        ctx->count++;
    }

    // 5) Extract features
    float mean, variance, peak;
    compute_window_features(ctx, &mean, &variance, &peak);

    // 6) Score
    float score = compute_anomaly_score(mean, variance, peak);

    // 7) Hysteresis-based decision
    if (score >= ANOMALY_SCORE_THRESHOLD) {
        ctx->high_score_count++;
        ctx->low_score_count = 0;
    } else {
        ctx->low_score_count++;
        ctx->high_score_count = 0;
    }

    if (!ctx->anomaly_active) {
        if (ctx->high_score_count >= ANOMALY_ENTER_COUNT) {
            ctx->anomaly_active = true;
        }
    } else {
        if (ctx->low_score_count >= ANOMALY_EXIT_COUNT) {
            ctx->anomaly_active = false;
        }
    }

    // 8) Save last metrics
    ctx->last_mean = mean;
    ctx->last_variance = variance;
    ctx->last_peak = peak;
    ctx->last_score = score;

    result.anomaly = ctx->anomaly_active;
    result.score = score;
    result.mean = mean;
    result.variance = variance;
    result.peak = peak;

    return result;
}
```

