    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float mean;
    float variance;
    float stddev;
    float min;
    float max;
} stats_t;

typedef struct {
    // Ring buffer for magnitudes
    float window[PIPELINE_WINDOW_SIZE];
    uint8_t index;
    uint8_t count;

    // Baseline stats
    float baseline_mean;
    float baseline_var;

    // Detection parameters
    float z_threshold;        // e.g. 3.0f
    float abs_threshold;      // absolute magnitude delta threshold
    uint8_t persistence_count; // number of consecutive anomalies required
    uint8_t persistence;

    // Optional calibration offsets
    float offset_x;
    float offset_y;
    float offset_z;

    // State
    bool initialized;
} sensor_pipeline_t;

void sensor_pipeline_init(sensor_pipeline_t *p);
void sensor_pipeline_set_calibration(sensor_pipeline_t *p, float ox, float oy, float oz);
void sensor_pipeline_set_thresholds(sensor_pipeline_t *p, float z_thresh, float abs_thresh, uint8_t persistence_count);

bool sensor_pipeline_process(sensor_pipeline_t *p, const accel_sample_t *sample, float *out_score);

#endif // SENSOR_PIPELINE_H
