### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float accel_magnitude(float x, float y, float z) {
    return sqrtf(x*x + y*y + z*z);
}

static void compute_stats(const float *data, uint8_t n, stats_t *out) {
    float sum = 0.0f;
    float sumsq = 0.0f;
    float minv = data[0];
    float maxv = data[0];

    for (uint8_t i = 0; i < n; i++) {
        float v = data[i];
        sum += v;
        sumsq += v * v;
        if (v < minv) minv = v;
        if (v > maxv) maxv = v;
    }

    float mean = sum / (float)n;
    float var = (sumsq / (float)n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;

    out->mean = mean;
    out->variance = var;
    out->stddev = sqrtf(var);
    out->min = minv;
    out->max = maxv;
}

void sensor_pipeline_init(sensor_pipeline_t *p) {
    memset(p, 0, sizeof(*p));
    p->z_threshold = 3.0f;
    p->abs_threshold = 0.75f;      // tune for your sensor scale
    p->persistence_count = 2;
    p->initialized = true;
}

void sensor_pipeline_set_calibration(sensor_pipeline_t *p, float ox, float oy, float oz) {
    p->offset_x = ox;
    p->offset_y = oy;
    p->offset_z = oz;
}

void sensor_pipeline_set_thresholds(sensor_pipeline_t *p, float z_thresh, float abs_thresh, uint8_t persistence_count) {
    p->z_threshold = z_thresh;
    p->abs_threshold = abs_thresh;
    p->persistence_count = persistence_count;
}

bool sensor_pipeline_process(sensor_pipeline_t *p, const accel_sample_t *sample, float *out_score) {
    if (!p || !sample || !p->initialized) {
        return false;
    }

    // 1) Calibration
    float x = sample->x - p->offset_x;
    float y = sample->y - p->offset_y;
    float z = sample->z - p->offset_z;

    // 2) Feature: magnitude
    float mag = accel_magnitude(x, y, z);

    // 3) Update rolling window
    p->window[p->index] = mag;
    p->index = (p->index + 1) % PIPELINE_WINDOW_SIZE;
    if (p->count < PIPELINE_WINDOW_SIZE) {
        p->count++;
    }

    // Need enough samples for stable stats
    if (p->count < PIPELINE_MIN_SAMPLES) {
        if (out_score) *out_score = 0.0f;
        return false;
    }

    // 4) Compute window stats
    stats_t stats;
    compute_stats(p->window, p->count, &stats);

    // 5) Baseline update:
    // Simple exponential moving average / variance update
    // Only update baseline when not anomalous to avoid contamination.
    if (p->baseline_mean == 0.0f && p->baseline_var == 0.0f) {
        p->baseline_mean = stats.mean;
        p->baseline_var = stats.variance;
    }

    float baseline_std = sqrtf(p->baseline_var);
    if (baseline_std < 1e-6f) baseline_std = 1e-6f;

    // 6) Anomaly score
    float delta = fabsf(stats.mean - p->baseline_mean);
    float zscore = delta / baseline_std;

    // Combine mean shift and variance spike
    float var_ratio = (p->baseline_var > 1e-6f) ? (stats.variance / p->baseline_var) : 1.0f;
    float score = zscore + 0.5f * (var_ratio - 1.0f);

    if (out_score) {
        *out_score = score;
    }

    // 7) Decision logic
    bool anomalous = (zscore > p->z_threshold) || (delta > p->abs_threshold) || (var_ratio > 3.0f);

    if (anomalous) {
        if (p->persistence < 255) p->persistence++;
    } else {
        p->persistence = 0;

        // Update baseline slowly when stable
        const float alpha = 0.02f;
        p->baseline_mean = (1.0f - alpha) * p->baseline_mean + alpha * stats.mean;
        p->baseline_var  = (1.0f - alpha) * p->baseline_var  + alpha * stats.variance;
    }

    return (p->persistence >= p->persistence_count);
}
