### Source: `anomaly_pipeline.c`
```c
#include "anomaly_pipeline.h"
#include <math.h>
#include <string.h>

static float compute_magnitude(const AccelSample *s)
{
    return sqrtf(s->ax * s->ax + s->ay * s->ay + s->az * s->az);
}

static void compute_features(const float *window, uint8_t n, FeatureSet *f)
{
    if (n == 0) {
        memset(f, 0, sizeof(*f));
        return;
    }

    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = window[0];
    float max_v = window[0];

    for (uint8_t i = 0; i < n; i++) {
        float x = window[i];
        sum += x;
        sum_sq += x * x;
        if (x < min_v) min_v = x;
        if (x > max_v) max_v = x;
    }

    f->mean = sum / n;
    f->variance = (sum_sq / n) - (f->mean * f->mean);
    if (f->variance < 0.0f) f->variance = 0.0f;
    f->stddev = sqrtf(f->variance);
    f->peak_to_peak = max_v - min_v;

    float energy = 0.0f;
    float max_abs_dev = 0.0f;
    for (uint8_t i = 0; i < n; i++) {
        float dev = window[i] - f->mean;
        float abs_dev = fabsf(dev);
        energy += window[i] * window[i];
        if (abs_dev > max_abs_dev) max_abs_dev = abs_dev;
    }

    f->energy = energy / n;
    f->max_abs_dev = max_abs_dev;
}

static float anomaly_score(const FeatureSet *f, const DetectorConfig *cfg)
{
    float score = 0.0f;

    if (f->variance > cfg->variance_threshold) {
        score += (f->variance - cfg->variance_threshold) / cfg->variance_threshold;
    }

    if (f->peak_to_peak > cfg->peak_threshold) {
        score += (f->peak_to_peak - cfg->peak_threshold) / cfg->peak_threshold;
    }

    // Optional: include energy or max deviation if desired
    if (f->max_abs_dev > 2.0f * cfg->peak_threshold) {
        score += 0.5f;
    }

    return score;
}

void AnomalyDetector_Init(AnomalyDetector *det, const DetectorConfig *cfg)
{
    memset(det, 0, sizeof(*det));
    det->cfg = *cfg;
    det->baseline = 0.0f;
}

bool AnomalyDetector_ProcessSample(AnomalyDetector *det, const AccelSample *sample, FeatureSet *out_features)
{
    // 1) Low-pass filter raw acceleration
    det->lp_ax = det->cfg.lp_alpha * sample->ax + (1.0f - det->cfg.lp_alpha) * det->lp_ax;
    det->lp_ay = det->cfg.lp_alpha * sample->ay + (1.0f - det->cfg.lp_alpha) * det->lp_ay;
    det->lp_az = det->cfg.lp_alpha * sample->az + (1.0f - det->cfg.lp_alpha) * det->lp_az;

    AccelSample filtered = {
        .ax = det->lp_ax,
        .ay = det->lp_ay,
        .az = det->lp_az
    };

    // 2) Magnitude
    float mag = compute_magnitude(&filtered);

    // 3) Baseline tracking (slow moving average)
    det->baseline = det->cfg.baseline_alpha * mag + (1.0f - det->cfg.baseline_alpha) * det->baseline;

    // 4) Detrended signal
    float signal = mag - det->baseline;

    // 5) Store in sliding window
    det->window[det->index] = signal;
    det->index = (det->index + 1) % WINDOW_SIZE;
    if (det->count < WINDOW_SIZE) {
        det->count++;
    }

    // 6) Only evaluate once window is full
    if (det->count < WINDOW_SIZE) {
        if (out_features) memset(out_features, 0, sizeof(*out_features));
        return false;
    }

    // Reconstruct ordered window for feature computation
    float ordered[WINDOW_SIZE];
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        uint8_t idx = (det->index + i) % WINDOW_SIZE;
        ordered[i] = det->window[idx];
    }

    FeatureSet features;
    compute_features(ordered, WINDOW_SIZE, &features);

    if (out_features) {
        *out_features = features;
    }

    // 7) Score and decision
    float score = anomaly_score(&features, &det->cfg);
    bool candidate = (score >= det->cfg.anomaly_threshold);

    if (candidate) {
        if (det->anomaly_count < 255) det->anomaly_count++;
    } else {
        det->anomaly_count = 0;
    }

    if (det->anomaly_count >= det->cfg.persistence) {
        det->anomaly_active = true;
    } else if (!candidate) {
        det->anomaly_active = false;
    }

    return det->anomaly_active;
}
