### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float f_abs(float x) {
    return (x < 0.0f) ? -x : x;
}

static float accel_magnitude(const accel_sample_t *s) {
    float x = (float)s->x;
    float y = (float)s->y;
    float z = (float)s->z;
    return sqrtf(x*x + y*y + z*z);
}

static void compute_features(const sample_window_t *w, feature_vector_t *fv) {
    memset(fv, 0, sizeof(*fv));

    if (w->count == 0) return;

    float sum[SP_AXES] = {0};
    float sumsq[SP_AXES] = {0};
    float minv[SP_AXES] = {0}, maxv[SP_AXES] = {0};
    float mag_sum = 0.0f, mag_sumsq = 0.0f;
    float jerk_sum = 0.0f;
    uint8_t i;

    for (i = 0; i < w->count; i++) {
        const accel_sample_t *s = &w->buffer[i];
        float v[SP_AXES] = {(float)s->x, (float)s->y, (float)s->z};
        float mag = accel_magnitude(s);

        if (i == 0) {
            for (int a = 0; a < SP_AXES; a++) {
                minv[a] = maxv[a] = v[a];
            }
        }

        for (int a = 0; a < SP_AXES; a++) {
            sum[a] += v[a];
            sumsq[a] += v[a] * v[a];
            if (v[a] < minv[a]) minv[a] = v[a];
            if (v[a] > maxv[a]) maxv[a] = v[a];
        }

        mag_sum += mag;
        mag_sumsq += mag * mag;

        if (i > 0) {
            const accel_sample_t *p = &w->buffer[i - 1];
            float dx = (float)s->x - (float)p->x;
            float dy = (float)s->y - (float)p->y;
            float dz = (float)s->z - (float)p->z;
            jerk_sum += sqrtf(dx*dx + dy*dy + dz*dz);
        }
    }

    float n = (float)w->count;
    for (int a = 0; a < SP_AXES; a++) {
        fv->mean[a] = sum[a] / n;
        float var = (sumsq[a] / n) - (fv->mean[a] * fv->mean[a]);
        fv->stddev[a] = (var > 0.0f) ? sqrtf(var) : 0.0f;
        fv->peak_to_peak[a] = maxv[a] - minv[a];
    }

    fv->mag_mean = mag_sum / n;
    float mag_var = (mag_sumsq / n) - (fv->mag_mean * fv->mag_mean);
    fv->mag_stddev = (mag_var > 0.0f) ? sqrtf(mag_var) : 0.0f;

    fv->jerk_mean = (w->count > 1) ? (jerk_sum / (n - 1.0f)) : 0.0f;
}

static float compute_anomaly_score(const feature_vector_t *fv, const anomaly_model_t *m) {
    float score = 0.0f;

    // Simple normalized deviation from baseline
    score += f_abs(fv->mag_mean - m->baseline_mag_mean) / (m->baseline_mag_mean + 1.0f);
    score += f_abs(fv->mag_stddev - m->baseline_mag_stddev) / (m->baseline_mag_stddev + 1.0f);
    score += f_abs(fv->jerk_mean - m->baseline_jerk_mean) / (m->baseline_jerk_mean + 1.0f);

    // Add a penalty for large axis excursions
    score += 0.001f * (fv->peak_to_peak[0] + fv->peak_to_peak[1] + fv->peak_to_peak[2]);

    return score;
}

void sp_init(sensor_pipeline_t *sp) {
    memset(sp, 0, sizeof(*sp));
    sp->model.anomaly_threshold = 2.5f; // initial tuning value
    sp->model.initialized = false;
}

bool sp_push_sample(sensor_pipeline_t *sp, accel_sample_t sample) {
    sample_window_t *w = &sp->window;

    if (w->count < SP_WINDOW_SIZE) {
        w->buffer[w->count++] = sample;
    } else {
        // shift left by one; simple initial implementation
        memmove(&w->buffer[0], &w->buffer[1], sizeof(accel_sample_t) * (SP_WINDOW_SIZE - 1));
        w->buffer[SP_WINDOW_SIZE - 1] = sample;
    }

    return (w->count == SP_WINDOW_SIZE);
}

bool sp_process_window(sensor_pipeline_t *sp, float *anomaly_score, bool *is_anomaly) {
    if (sp->window.count < SP_WINDOW_SIZE) {
        return false;
    }

    feature_vector_t fv;
    compute_features(&sp->window, &fv);

    if (!sp->model.initialized) {
        // Bootstrap baseline from first window
        sp->model.baseline_mag_mean = fv.mag_mean;
        sp->model.baseline_mag_stddev = fv.mag_stddev;
        sp->model.baseline_jerk_mean = fv.jerk_mean;
        sp->model.initialized = true;
    }

    float score = compute_anomaly_score(&fv, &sp->model);

    if (anomaly_score) *anomaly_score = score;
    if (is_anomaly) *is_anomaly = (score > sp->model.anomaly_threshold);

    return true;
}
