## 2) Embedded-friendly C implementation

This is written in portable C and can be dropped into firmware.

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

#define WINDOW_SIZE         32
#define CONSECUTIVE_LIMIT    3
#define EMA_ALPHA           0.02f   // baseline smoothing
#define Z_THRESHOLD         3.0f    // anomaly threshold in std dev units

typedef struct {
    float ax;
    float ay;
    float az;
} accel_sample_t;

typedef struct {
    float samples[WINDOW_SIZE];
    uint16_t index;
    uint16_t count;

    float baseline;      // slow-moving baseline of magnitude
    float mean;
    float stddev;
    float min_val;
    float max_val;

    float baseline_mean;
    float baseline_stddev;

    uint8_t anomaly_count;
    bool anomaly_detected;
} anomaly_detector_t;

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static float accel_magnitude(const accel_sample_t *s) {
    return fast_sqrtf(s->ax * s->ax + s->ay * s->ay + s->az * s->az);
}

void anomaly_detector_init(anomaly_detector_t *det) {
    memset(det, 0, sizeof(*det));
    det->min_val = 1e9f;
    det->max_val = -1e9f;
    det->baseline = 0.0f;
    det->baseline_mean = 0.0f;
    det->baseline_stddev = 1.0f;
}

static void compute_window_stats(anomaly_detector_t *det) {
    if (det->count == 0) return;

    float sum = 0.0f;
    float sum_sq = 0.0f;
    det->min_val = 1e9f;
    det->max_val = -1e9f;

    for (uint16_t i = 0; i < det->count; i++) {
        float x = det->samples[i];
        sum += x;
        sum_sq += x * x;
        if (x < det->min_val) det->min_val = x;
        if (x > det->max_val) det->max_val = x;
    }

    det->mean = sum / (float)det->count;
    float variance = (sum_sq / (float)det->count) - (det->mean * det->mean);
    if (variance < 0.0f) variance = 0.0f;
    det->stddev = fast_sqrtf(variance);
}

static float anomaly_score(const anomaly_detector_t *det) {
    // Simple z-score style score based on mean deviation from baseline
    float denom = det->baseline_stddev;
    if (denom < 1e-6f) denom = 1.0f;
    return fabsf(det->mean - det->baseline_mean) / denom;
}

void anomaly_detector_update(anomaly_detector_t *det, const accel_sample_t *sample) {
    float mag = accel_magnitude(sample);

    // Remove slow baseline drift
    if (det->count == 0) {
        det->baseline = mag;
        det->baseline_mean = mag;
        det->baseline_stddev = 1.0f;
    } else {
        det->baseline = (1.0f - EMA_ALPHA) * det->baseline + EMA_ALPHA * mag;
    }

    float detrended = mag - det->baseline;

    // Store in circular buffer
    det->samples[det->index] = detrended;
    det->index = (det->index + 1) % WINDOW_SIZE;
    if (det->count < WINDOW_SIZE) det->count++;

    // Need enough data before evaluating
    if (det->count < WINDOW_SIZE) {
        det->anomaly_detected = false;
        return;
    }

    compute_window_stats(det);

    // Update baseline statistics slowly when not anomalous
    float score = anomaly_score(det);

    if (score < Z_THRESHOLD) {
        // Adapt baseline only when signal looks normal
        det->baseline_mean = (1.0f - EMA_ALPHA) * det->baseline_mean + EMA_ALPHA * det->mean;

        // Update baseline stddev conservatively
        det->baseline_stddev = (1.0f - EMA_ALPHA) * det->baseline_stddev + EMA_ALPHA * det->stddev;

        if (det->baseline_stddev < 1e-3f) {
            det->baseline_stddev = 1e-3f;
        }

        det->anomaly_count = 0;
        det->anomaly_detected = false;
    } else {
        if (det->anomaly_count < 255) det->anomaly_count++;
        if (det->anomaly_count >= CONSECUTIVE_LIMIT) {
            det->anomaly_detected = true;
        }
    }
}

bool anomaly_detector_is_anomaly(const anomaly_detector_t *det) {
    return det->anomaly_detected;
}

float anomaly_detector_get_score(const anomaly_detector_t *det) {
    return anomaly_score(det);
}
```

