### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>

static float accel_magnitude(const accel_sample_t *s)
{
    return sqrtf((s->ax * s->ax) + (s->ay * s->ay) + (s->az * s->az));
}

void anomaly_detector_init(anomaly_detector_t *det,
                           float alpha,
                           float threshold,
                           uint8_t persist_limit)
{
    if (!det) return;

    det->baseline = 0.0f;
    det->alpha = alpha;
    det->threshold = threshold;
    det->persist_count = 0;
    det->persist_limit = persist_limit;
    det->initialized = false;
}

bool anomaly_detector_process(anomaly_detector_t *det,
                              const accel_sample_t *sample,
                              float *out_magnitude,
                              float *out_residual)
{
    if (!det || !sample) return false;

    float mag = accel_magnitude(sample);

    if (out_magnitude) {
        *out_magnitude = mag;
    }

    // First sample initializes baseline
    if (!det->initialized) {
        det->baseline = mag;
        det->initialized = true;
        if (out_residual) {
            *out_residual = 0.0f;
        }
        return false;
    }

    // Exponential moving average baseline
    det->baseline = (det->alpha * mag) + ((1.0f - det->alpha) * det->baseline);

    float residual = fabsf(mag - det->baseline);

    if (out_residual) {
        *out_residual = residual;
    }

    // Persistence logic
    if (residual > det->threshold) {
        if (det->persist_count < 255) {
            det->persist_count++;
        }
    } else {
        det->persist_count = 0;
    }

    return (det->persist_count >= det->persist_limit);
}
