#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#define SP_WINDOW_SIZE      64
#define SP_RING_SIZE        128
#define SP_FEATURE_COUNT     4

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} sp_sample_t;

typedef struct {
    float mean_mag;
    float std_mag;
    float p2p_mag;
    float rms_mag;
} sp_features_t;

typedef struct {
    float baseline_mean[SP_FEATURE_COUNT];
    float baseline_var[SP_FEATURE_COUNT];
    uint32_t baseline_count;

    float anomaly_threshold;   // e.g. 3.0f = 3-sigma style threshold
    bool baseline_ready;
} sp_model_t;

typedef struct {
    sp_sample_t ring[SP_RING_SIZE];
    uint16_t head;
    uint16_t tail;
    uint16_t count;

    sp_sample_t window[SP_WINDOW_SIZE];
    uint16_t window_count;

    sp_model_t model;
} sp_pipeline_t;

void sp_init(sp_pipeline_t *p);
bool sp_push_sample(sp_pipeline_t *p, const sp_sample_t *s);
bool sp_process(sp_pipeline_t *p, bool *anomaly_detected, float *score);

#endif
