### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float vec_mag(const sp_sample_t *s) {
    return sqrtf(s->x * s->x + s->y * s->y + s->z * s->z);
}

static void compute_features(const sp_sample_t *samples, uint16_t n, sp_features_t *f) {
    float sum = 0.0f;
    float sumsq = 0.0f;
    float minv = 1e30f;
    float maxv = -1e30f;

    for (uint16_t i = 0; i < n; i++) {
        float m = vec_mag(&samples[i]);
        sum += m;
        sumsq += m * m;
        if (m < minv) minv = m;
        if (m > maxv) maxv = m;
    }

    float mean = sum / (float)n;
    float var = (sumsq / (float)n) - (mean * mean);
    if (var < 0.0f) var = 0.0f;

    f->mean_mag = mean;
    f->std_mag  = sqrtf(var);
    f->p2p_mag  = maxv - minv;
    f->rms_mag  = sqrtf(sumsq / (float)n);
}

static void update_baseline(sp_model_t *m, const sp_features_t *f) {
    const float x[SP_FEATURE_COUNT] = {
        f->mean_mag,
        f->std_mag,
        f->p2p_mag,
        f->rms_mag
    };

    m->baseline_count++;

    for (int i = 0; i < SP_FEATURE_COUNT; i++) {
        float delta = x[i] - m->baseline_mean[i];
        m->baseline_mean[i] += delta / (float)m->baseline_count;
        float delta2 = x[i] - m->baseline_mean[i];
        m->baseline_var[i] += delta * delta2; // Welford
    }

    if (m->baseline_count >= 10) {
        m->baseline_ready = true;
    }
}

static float anomaly_score(const sp_model_t *m, const sp_features_t *f) {
    const float x[SP_FEATURE_COUNT] = {
        f->mean_mag,
        f->std_mag,
        f->p2p_mag,
        f->rms_mag
    };

    float score = 0.0f;

    for (int i = 0; i < SP_FEATURE_COUNT; i++) {
        float variance = (m->baseline_count > 1)
            ? (m->baseline_var[i] / (float)(m->baseline_count - 1))
            : 1e-6f;

        if (variance < 1e-6f) variance = 1e-6f;

        float z = (x[i] - m->baseline_mean[i]) / sqrtf(variance);
        score += z * z;
    }

    return sqrtf(score);
}

void sp_init(sp_pipeline_t *p) {
    memset(p, 0, sizeof(*p));
    p->model.anomaly_threshold = 3.0f;
}

bool sp_push_sample(sp_pipeline_t *p, const sp_sample_t *s) {
    if (p->count >= SP_RING_SIZE) {
        return false; // overflow
    }

    p->ring[p->head] = *s;
    p->head = (p->head + 1) % SP_RING_SIZE;
    p->count++;
    return true;
}

static bool pop_sample(sp_pipeline_t *p, sp_sample_t *out) {
    if (p->count == 0) return false;

    *out = p->ring[p->tail];
    p->tail = (p->tail + 1) % SP_RING_SIZE;
    p->count--;
    return true;
}

bool sp_process(sp_pipeline_t *p, bool *anomaly_detected, float *score) {
    *anomaly_detected = false;
    *score = 0.0f;

    // Fill window if possible
    while (p->window_count < SP_WINDOW_SIZE) {
        sp_sample_t s;
        if (!pop_sample(p, &s)) {
            return false; // not enough data yet
        }
        p->window[p->window_count++] = s;
    }

    sp_features_t feat;
    compute_features(p->window, SP_WINDOW_SIZE, &feat);

    if (!p->model.baseline_ready) {
        update_baseline(&p->model, &feat);
    } else {
        float s = anomaly_score(&p->model, &feat);
        *score = s;
        if (s > p->model.anomaly_threshold) {
            *anomaly_detected = true;
        }

        // Optional: slowly adapt baseline only when not anomalous
        if (!*anomaly_detected) {
            update_baseline(&p->model, &feat);
        }
    }

    // Slide window by half for overlap
    const uint16_t hop = SP_WINDOW_SIZE / 2;
    if (hop < p->window_count) {
        memmove(&p->window[0], &p->window[hop], (p->window_count - hop) * sizeof(sp_sample_t));
        p->window_count -= hop;
    } else {
        p->window_count = 0;
    }

    return true;
}
```

