## 3) Reference implementation in C-like pseudocode

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define ANOMALY_CONSECUTIVE_LIMIT 3
#define MIN_BASELINE_WINDOWS 20

typedef struct {
    float ax;
    float ay;
    float az;
    uint32_t timestamp_ms;
} AccelSample;

typedef struct {
    float mean_mag;
    float var_mag;
    float rms_mag;
    float peak_to_peak;
    float jerk_mean;
} WindowFeatures;

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} RunningStats;

typedef struct {
    AccelSample samples[WINDOW_SIZE];
    uint32_t index;
    bool full;
} SampleWindow;

typedef struct {
    RunningStats baseline_mean_mag;
    RunningStats baseline_var_mag;
    RunningStats baseline_rms_mag;
    RunningStats baseline_ptp;

    SampleWindow window;

    uint32_t anomaly_streak;
    bool anomaly_detected;
} AnomalyDetector;

/* ---------- Running statistics ---------- */
static void running_stats_init(RunningStats *s) {
    s->mean = 0.0f;
    s->m2 = 0.0f;
    s->count = 0;
}

static void running_stats_update(RunningStats *s, float x) {
    s->count++;
    float delta = x - s->mean;
    s->mean += delta / (float)s->count;
    float delta2 = x - s->mean;
    s->m2 += delta * delta2;
}

static float running_stats_variance(const RunningStats *s) {
    if (s->count < 2) return 0.0f;
    return s->m2 / (float)(s->count - 1);
}

/* ---------- Window ---------- */
static void window_init(SampleWindow *w) {
    w->index = 0;
    w->full = false;
}

static bool window_push(SampleWindow *w, AccelSample s) {
    w->samples[w->index++] = s;
    if (w->index >= WINDOW_SIZE) {
        w->index = 0;
        w->full = true;
        return true; // window ready
    }
    return false;
}

/* ---------- Feature extraction ---------- */
static WindowFeatures extract_features(const SampleWindow *w) {
    WindowFeatures f = {0};

    float sum_mag = 0.0f;
    float sum_mag2 = 0.0f;
    float min_mag = 1e9f;
    float max_mag = -1e9f;
    float sum_jerk = 0.0f;

    for (uint32_t i = 0; i < WINDOW_SIZE; i++) {
        float ax = w->samples[i].ax;
        float ay = w->samples[i].ay;
        float az = w->samples[i].az;

        float mag = sqrtf(ax*ax + ay*ay + az*az);

        sum_mag += mag;
        sum_mag2 += mag * mag;

        if (mag < min_mag) min_mag = mag;
        if (mag > max_mag) max_mag = mag;

        if (i > 0) {
            float pax = w->samples[i-1].ax;
            float pay = w->samples[i-1].ay;
            float paz = w->samples[i-1].az;

            float prev_mag = sqrtf(pax*pax + pay*pay + paz*paz);
            sum_jerk += fabsf(mag - prev_mag);
        }
    }

    f.mean_mag = sum_mag / (float)WINDOW_SIZE;
    f.var_mag = (sum_mag2 / (float)WINDOW_SIZE) - (f.mean_mag * f.mean_mag);
    if (f.var_mag < 0.0f) f.var_mag = 0.0f;
    f.rms_mag = sqrtf(sum_mag2 / (float)WINDOW_SIZE);
    f.peak_to_peak = max_mag - min_mag;
    f.jerk_mean = sum_jerk / (float)(WINDOW_SIZE - 1);

    return f;
}

/* ---------- Detector ---------- */
static void detector_init(AnomalyDetector *d) {
    running_stats_init(&d->baseline_mean_mag);
    running_stats_init(&d->baseline_var_mag);
    running_stats_init(&d->baseline_rms_mag);
    running_stats_init(&d->baseline_ptp);

    window_init(&d->window);
    d->anomaly_streak = 0;
    d->anomaly_detected = false;
}

static float z_score(float x, float mean, float var) {
    float std = sqrtf(var + 1e-6f);
    return (x - mean) / std;
}

static bool detector_process_sample(AnomalyDetector *d, AccelSample s) {
    if (!window_push(&d->window, s)) {
        return false; // not enough data yet
    }

    WindowFeatures f = extract_features(&d->window);

    // Build baseline first
    if (d->baseline_mean_mag.count < MIN_BASELINE_WINDOWS) {
        running_stats_update(&d->baseline_mean_mag, f.mean_mag);
        running_stats_update(&d->baseline_var_mag, f.var_mag);
        running_stats_update(&d->baseline_rms_mag, f.rms_mag);
        running_stats_update(&d->baseline_ptp, f.peak_to_peak);
        d->anomaly_detected = false;
        d->anomaly_streak = 0;
        return false;
    }

    // Simple anomaly score using z-scores
    float z_mean = fabsf(z_score(f.mean_mag,
                                 d->baseline_mean_mag.mean,
                                 running_stats_variance(&d->baseline_mean_mag)));

    float z_var = fabsf(z_score(f.var_mag,
                                d->baseline_var_mag.mean,
                                running_stats_variance(&d->baseline_var_mag)));

    float z_rms = fabsf(z_score(f.rms_mag,
                                d->baseline_rms_mag.mean,
                                running_stats_variance(&d->baseline_rms_mag)));

    float z_ptp = fabsf(z_score(f.peak_to_peak,
                                d->baseline_ptp.mean,
                                running_stats_variance(&d->baseline_ptp)));

    float score = z_mean + z_var + z_rms + z_ptp;

    // Thresholds can be tuned per device/use case
    const float ANOMALY_SCORE_THRESHOLD = 10.0f;

    if (score > ANOMALY_SCORE_THRESHOLD) {
        d->anomaly_streak++;
    } else {
        d->anomaly_streak = 0;
    }

    if (d->anomaly_streak >= ANOMALY_CONSECUTIVE_LIMIT) {
        d->anomaly_detected = true;
        return true; // anomaly event
    }

    // Slowly adapt baseline only when not anomalous
    running_stats_update(&d->baseline_mean_mag, f.mean_mag);
    running_stats_update(&d->baseline_var_mag, f.var_mag);
    running_stats_update(&d->baseline_rms_mag, f.rms_mag);
    running_stats_update(&d->baseline_ptp, f.peak_to_peak);

    d->anomaly_detected = false;
    return false;
}
```

