## 3) C implementation skeleton

This version is written in C for embedded use.

### `sensor_pipeline.h`
```c
#ifndef SENSOR_PIPELINE_H
#define SENSOR_PIPELINE_H

#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define BASELINE_ALPHA 0.01f
#define ANOMALY_Z_THRESHOLD 3.0f
#define SPIKE_THRESHOLD_G 2.5f   // adjust for your sensor range/use case

typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float mean;
    float variance;
    float stddev;
    float min;
    float max;
    float peak_to_peak;
} feature_set_t;

typedef struct {
    float window[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;

    float baseline_mean;
    float baseline_var;
    bool baseline_initialized;

    float last_mag;
} anomaly_detector_t;

void anomaly_detector_init(anomaly_detector_t *detector);
bool anomaly_detector_process(anomaly_detector_t *detector, const accel_sample_t *sample, feature_set_t *features_out);
float accel_magnitude(const accel_sample_t *sample);

#endif
```

---

### `sensor_pipeline.c`
```c
#include "sensor_pipeline.h"
#include <math.h>
#include <string.h>

static float fast_absf(float x) {
    return (x < 0.0f) ? -x : x;
}

float accel_magnitude(const accel_sample_t *sample) {
    return sqrtf(sample->x * sample->x +
                 sample->y * sample->y +
                 sample->z * sample->z);
}

void anomaly_detector_init(anomaly_detector_t *detector) {
    memset(detector, 0, sizeof(*detector));
    detector->baseline_initialized = false;
    detector->last_mag = 0.0f;
}

static void compute_features(const float *window, uint8_t count, feature_set_t *out) {
    float sum = 0.0f;
    float sum_sq = 0.0f;
    float min_v = window[0];
    float max_v = window[0];

    for (uint8_t i = 0; i < count; i++) {
        float v = window[i];
        sum += v;
        sum_sq += v * v;
        if (v < min_v) min_v = v;
        if (v > max_v) max_v = v;
    }

    float mean = sum / (float)count;
    float var = (sum_sq / (float)count) - (mean * mean);
    if (var < 0.0f) var = 0.0f;

    out->mean = mean;
    out->variance = var;
    out->stddev = sqrtf(var);
    out->min = min_v;
    out->max = max_v;
    out->peak_to_peak = max_v - min_v;
}

bool anomaly_detector_process(anomaly_detector_t *detector,
                              const accel_sample_t *sample,
                              feature_set_t *features_out) {
    float mag = accel_magnitude(sample);

    // Insert into ring buffer
    detector->window[detector->index] = mag;
    detector->index = (detector->index + 1) % WINDOW_SIZE;
    if (detector->count < WINDOW_SIZE) {
        detector->count++;
    }

    // Need enough samples before detection
    if (detector->count < WINDOW_SIZE) {
        detector->last_mag = mag;
        return false;
    }

    // Reconstruct ordered window for feature extraction
    float ordered[WINDOW_SIZE];
    for (uint8_t i = 0; i < WINDOW_SIZE; i++) {
        uint8_t idx = (detector->index + i) % WINDOW_SIZE;
        ordered[i] = detector->window[idx];
    }

    compute_features(ordered, WINDOW_SIZE, features_out);

    // Initialize baseline from first full window
    if (!detector->baseline_initialized) {
        detector->baseline_mean = features_out->mean;
        detector->baseline_var = features_out->variance;
        detector->baseline_initialized = true;
        detector->last_mag = mag;
        return false;
    }

    // Update baseline slowly
    detector->baseline_mean =
        (1.0f - BASELINE_ALPHA) * detector->baseline_mean +
        BASELINE_ALPHA * features_out->mean;

    detector->baseline_var =
        (1.0f - BASELINE_ALPHA) * detector->baseline_var +
        BASELINE_ALPHA * features_out->variance;

    float baseline_std = sqrtf(detector->baseline_var + 1e-6f);

    // Simple anomaly score:
    // 1) deviation from baseline mean
    // 2) sudden spike from previous sample
    float z = fast_absf(features_out->mean - detector->baseline_mean) / baseline_std;
    float spike = fast_absf(mag - detector->last_mag);

    detector->last_mag = mag;

    bool anomaly = false;

    if (z > ANOMALY_Z_THRESHOLD) {
        anomaly = true;
    }

    if (spike > SPIKE_THRESHOLD_G) {
        anomaly = true;
    }

    return anomaly;
}
```

