    Features baseline_var;   // variance estimate for normalization
    bool initialized;
    uint8_t anomaly_streak;
} AnomalyDetector;

static float accel_magnitude(const AccelSample *s) {
    return sqrtf(s->ax * s->ax + s->ay * s->ay + s->az * s->az);
}

static void window_init(WindowBuffer *w) {
    memset(w, 0, sizeof(*w));
}

static void detector_init(AnomalyDetector *d) {
    memset(d, 0, sizeof(*d));
}

static void window_push(WindowBuffer *w, float mag) {
    w->buffer[w->index] = mag;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static bool window_full(const WindowBuffer *w) {
    return w->count == WINDOW_SIZE;
}

static void compute_features(const WindowBuffer *w, Features *f) {
    float sum = 0.0f;
    float sumsq = 0.0f;
    float minv = w->buffer[0];
    float maxv = w->buffer[0];
    float jerk_sum = 0.0f;

    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        float x = w->buffer[i];
        sum += x;
        sumsq += x * x;
        if (x < minv) minv = x;
        if (x > maxv) maxv = x;

        if (i > 0) {
            jerk_sum += fabsf(w->buffer[i] - w->buffer[i - 1]);
        }
    }

    f->mean = sum / WINDOW_SIZE;
    f->rms = sqrtf(sumsq / WINDOW_SIZE);
    f->p2p = maxv - minv;
    f->jerk_mean = jerk_sum / (WINDOW_SIZE - 1);

    float var = 0.0f;
    for (uint16_t i = 0; i < WINDOW_SIZE; i++) {
        float d = w->buffer[i] - f->mean;
        var += d * d;
    }
    var /= WINDOW_SIZE;
    f->stddev = sqrtf(var);
}

static void update_baseline(AnomalyDetector *d, const Features *f) {
    if (!d->initialized) {
        d->baseline = *f;
        memset(&d->baseline_var, 0, sizeof(d->baseline_var));
        d->initialized = true;
        return;
    }

    #define EMA_UPDATE(field) \
        d->baseline.field = (1.0f - EMA_ALPHA) * d->baseline.field + EMA_ALPHA * f->field; \
        d->baseline_var.field = (1.0f - EMA_ALPHA) * d->baseline_var.field + EMA_ALPHA * ((f->field - d->baseline.field) * (f->field - d->baseline.field));

    EMA_UPDATE(mean);
    EMA_UPDATE(stddev);
    EMA_UPDATE(rms);
    EMA_UPDATE(p2p);
    EMA_UPDATE(jerk_mean);

    #undef EMA_UPDATE
}

static float normalized_diff(float value, float baseline, float variance) {
    float denom = sqrtf(variance) + 1e-6f;
    return fabsf(value - baseline) / denom;
}

static float score_features(const AnomalyDetector *d, const Features *f) {
    float score = 0.0f;

    score += normalized_diff(f->mean,      d->baseline.mean,      d->baseline_var.mean);
    score += normalized_diff(f->stddev,    d->baseline.stddev,    d->baseline_var.stddev);
    score += normalized_diff(f->rms,       d->baseline.rms,       d->baseline_var.rms);
    score += normalized_diff(f->p2p,       d->baseline.p2p,       d->baseline_var.p2p);
    score += normalized_diff(f->jerk_mean, d->baseline.jerk_mean, d->baseline_var.jerk_mean);

    return score / 5.0f;
}

bool anomaly_detector_process_sample(AnomalyDetector *d,
                                     WindowBuffer *w,
                                     const AccelSample *sample,
                                     bool *anomaly_out)
{
    float mag = accel_magnitude(sample);
    window_push(w, mag);

    *anomaly_out = false;

    if (!window_full(w)) {
        return false; // not enough data yet
    }

    Features f;
    compute_features(w, &f);

    if (!d->initialized) {
        update_baseline(d, &f);
        return true;
    }

    float score = score_features(d, &f);

    if (score > ANOMALY_THRESHOLD) {
        d->anomaly_streak++;
    } else {
        d->anomaly_streak = 0;
    }

    if (d->anomaly_streak >= CONSECUTIVE_LIMIT) {
        *anomaly_out = true;
    }

    // Update baseline only when not anomalous, to avoid contaminating it
    if (!*anomaly_out) {
        update_baseline(d, &f);
    }

    return true;
}
