# Embedded C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <string.h>

/* =========================
 * Configuration
 * ========================= */

#define WINDOW_SIZE             32
#define GRAVITY_ALPHA_NUM       1   // low-pass smoothing numerator
#define GRAVITY_ALPHA_DEN       32  // alpha = 1/32
#define ANOMALY_Z_THRESHOLD     3.0f
#define ANOMALY_PEAK_THRESHOLD  2.5f
#define MIN_SAMPLES_FOR_STATS   16

/* =========================
 * Types
 * ========================= */

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_sample_t;

typedef struct {
    float gx;
    float gy;
    float gz;
} gravity_estimate_t;

typedef struct {
    float buffer[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
    float sum_sq;
} rolling_stats_t;

typedef struct {
    gravity_estimate_t gravity;
    rolling_stats_t mag_stats;
    float last_magnitude;
    bool anomaly;
    uint32_t sample_count;
} anomaly_detector_t;

/* =========================
 * Utility
 * ========================= */

static float fast_sqrtf(float x) {
    if (x <= 0.0f) return 0.0f;
    return sqrtf(x);
}

static void rolling_stats_init(rolling_stats_t *rs) {
    memset(rs, 0, sizeof(*rs));
}

static void rolling_stats_push(rolling_stats_t *rs, float value) {
    if (rs->count < WINDOW_SIZE) {
        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sum_sq += value * value;
        rs->count++;
        rs->index = (rs->index + 1) % WINDOW_SIZE;
    } else {
        float old = rs->buffer[rs->index];
        rs->sum -= old;
        rs->sum_sq -= old * old;

        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sum_sq += value * value;
        rs->index = (rs->index + 1) % WINDOW_SIZE;
    }
}

static void rolling_stats_get(const rolling_stats_t *rs, float *mean, float *stddev) {
    if (rs->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    *mean = rs->sum / (float)rs->count;

    float variance = (rs->sum_sq / (float)rs->count) - (*mean * *mean);
    if (variance < 0.0f) variance = 0.0f;
    *stddev = fast_sqrtf(variance);
}

/* =========================
 * Detector API
 * ========================= */

void anomaly_detector_init(anomaly_detector_t *det) {
    memset(det, 0, sizeof(*det));

    det->gravity.gx = 0.0f;
    det->gravity.gy = 0.0f;
    det->gravity.gz = 0.0f;

    rolling_stats_init(&det->mag_stats);
    det->anomaly = false;
    det->sample_count = 0;
}

static void update_gravity_estimate(anomaly_detector_t *det, const accel_sample_t *s) {
    // Simple IIR low-pass filter to estimate gravity/bias
    // g = g + alpha * (x - g)
    const float alpha = (float)GRAVITY_ALPHA_NUM / (float)GRAVITY_ALPHA_DEN;

    det->gravity.gx += alpha * ((float)s->x - det->gravity.gx);
    det->gravity.gy += alpha * ((float)s->y - det->gravity.gy);
    det->gravity.gz += alpha * ((float)s->z - det->gravity.gz);
}

static float compute_linear_magnitude(const anomaly_detector_t *det, const accel_sample_t *s) {
    float lx = (float)s->x - det->gravity.gx;
    float ly = (float)s->y - det->gravity.gy;
    float lz = (float)s->z - det->gravity.gz;

    return fast_sqrtf(lx * lx + ly * ly + lz * lz);
}

bool anomaly_detector_process_sample(anomaly_detector_t *det, const accel_sample_t *sample) {
    det->sample_count++;

    // 1) Update gravity estimate
    update_gravity_estimate(det, sample);

    // 2) Compute linear acceleration magnitude
    float mag = compute_linear_magnitude(det, sample);
    det->last_magnitude = mag;

    // 3) Update rolling stats
    rolling_stats_push(&det->mag_stats, mag);

    // 4) Compute anomaly score once enough samples are available
    float mean = 0.0f, stddev = 0.0f;
    rolling_stats_get(&det->mag_stats, &mean, &stddev);

    bool anomaly = false;

    if (det->mag_stats.count >= MIN_SAMPLES_FOR_STATS && stddev > 0.001f) {
        float z = (mag - mean) / stddev;
        float peak_ratio = mag / (mean + 0.001f);

        if (z > ANOMALY_Z_THRESHOLD || peak_ratio > ANOMALY_PEAK_THRESHOLD) {
            anomaly = true;
        }
    }

    det->anomaly = anomaly;
    return anomaly;
}

bool anomaly_detector_is_anomaly(const anomaly_detector_t *det) {
    return det->anomaly;
}

float anomaly_detector_last_magnitude(const anomaly_detector_t *det) {
    return det->last_magnitude;
}

/* =========================
 * Example event hook
 * ========================= */

typedef void (*anomaly_event_cb_t)(uint32_t sample_index, float magnitude);

void anomaly_detector_process_stream(
    anomaly_detector_t *det,
    const accel_sample_t *samples,
    uint32_t count,
    anomaly_event_cb_t cb)
{
    for (uint32_t i = 0; i < count; i++) {
        if (anomaly_detector_process_sample(det, &samples[i])) {
            if (cb) {
                cb(det->sample_count, det->last_magnitude);
            }
        }
    }
}
