## Embedded C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

/* =========================
 * Configuration
 * ========================= */
#define WINDOW_SIZE         32
#define BASELINE_ALPHA      0.01f   // Slow baseline adaptation
#define FILTER_ALPHA        0.20f   // Low-pass filter strength
#define ANOMALY_Z_THRESHOLD  3.0f   // Z-score threshold
#define MIN_BASELINE_SAMPLES 50

/* =========================
 * Types
 * ========================= */
typedef struct {
    float x;
    float y;
    float z;
    uint32_t timestamp_ms;
} accel_sample_t;

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} running_stats_t;

typedef struct {
    float mag_filtered;
    float baseline_mean;
    float baseline_var;
    running_stats_t window_stats;
    float window[WINDOW_SIZE];
    uint8_t window_index;
    uint8_t window_count;
    uint32_t sample_count;
    bool anomaly_active;
} anomaly_detector_t;

/* =========================
 * Utility functions
 * ========================= */
static float fast_sqrtf(float x) {
    return sqrtf(x);
}

static float compute_magnitude(const accel_sample_t *s) {
    return fast_sqrtf((s->x * s->x) + (s->y * s->y) + (s->z * s->z));
}

static float low_pass_filter(float prev, float input, float alpha) {
    return prev + alpha * (input - prev);
}

static void running_stats_init(running_stats_t *stats) {
    stats->mean = 0.0f;
    stats->m2 = 0.0f;
    stats->count = 0;
}

static void running_stats_update(running_stats_t *stats, float x) {
    stats->count++;
    float delta = x - stats->mean;
    stats->mean += delta / (float)stats->count;
    float delta2 = x - stats->mean;
    stats->m2 += delta * delta2;
}

static float running_stats_variance(const running_stats_t *stats) {
    if (stats->count < 2) return 0.0f;
    return stats->m2 / (float)(stats->count - 1);
}

/* =========================
 * Detector API
 * ========================= */
void anomaly_detector_init(anomaly_detector_t *det) {
    det->mag_filtered = 0.0f;
    det->baseline_mean = 0.0f;
    det->baseline_var = 1.0f;
    running_stats_init(&det->window_stats);
    det->window_index = 0;
    det->window_count = 0;
    det->sample_count = 0;
    det->anomaly_active = false;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        det->window[i] = 0.0f;
    }
}

/* Optional callback hook for anomaly events */
__attribute__((weak))
void anomaly_event_callback(const accel_sample_t *sample, float score) {
    (void)sample;
    (void)score;
    /* User can override this in application code */
}

/* Process one accelerometer sample */
bool anomaly_detector_process(anomaly_detector_t *det, const accel_sample_t *sample) {
    det->sample_count++;

    /* 1) Feature extraction: magnitude */
    float mag = compute_magnitude(sample);

    /* 2) Filtering */
    if (det->sample_count == 1) {
        det->mag_filtered = mag;
    } else {
        det->mag_filtered = low_pass_filter(det->mag_filtered, mag, FILTER_ALPHA);
    }

    /* 3) Update rolling window */
    float old = det->window[det->window_index];
    det->window[det->window_index] = det->mag_filtered;
    det->window_index = (det->window_index + 1) % WINDOW_SIZE;

    if (det->window_count < WINDOW_SIZE) {
        det->window_count++;
    }

    /* 4) Update baseline during startup / normal operation */
    if (det->sample_count <= MIN_BASELINE_SAMPLES) {
        /* Bootstrap baseline */
        det->baseline_mean = low_pass_filter(det->baseline_mean, det->mag_filtered, BASELINE_ALPHA);
        float diff = det->mag_filtered - det->baseline_mean;
        det->baseline_var = low_pass_filter(det->baseline_var, diff * diff, BASELINE_ALPHA);
        return false;
    }

    /* 5) Compute deviation score */
    float baseline_std = fast_sqrtf(det->baseline_var + 1e-6f);
    float z_score = (det->mag_filtered - det->baseline_mean) / baseline_std;
    float abs_z = (z_score < 0.0f) ? -z_score : z_score;

    /* 6) Simple anomaly decision */
    bool anomaly = (abs_z > ANOMALY_Z_THRESHOLD);

    /* 7) Update baseline slowly only if not anomalous */
    if (!anomaly) {
        det->baseline_mean = low_pass_filter(det->baseline_mean, det->mag_filtered, BASELINE_ALPHA);
        float diff = det->mag_filtered - det->baseline_mean;
        det->baseline_var = low_pass_filter(det->baseline_var, diff * diff, BASELINE_ALPHA);
    }

    /* 8) State tracking and callback */
    if (anomaly && !det->anomaly_active) {
        det->anomaly_active = true;
        anomaly_event_callback(sample, abs_z);
    } else if (!anomaly) {
        det->anomaly_active = false;
    }

    return anomaly;
}
```

