## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define AXES 3

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    AccelSample buf[WINDOW_SIZE];
    int idx;
    int count;
} RingBuffer;

typedef struct {
    float mean_mag;
    float var_mag;
    bool initialized;
} BaselineModel;

static RingBuffer rb = {0};
static BaselineModel model = {0};

static float magnitude(AccelSample s) {
    return sqrtf(s.x*s.x + s.y*s.y + s.z*s.z);
}

static void rb_push(RingBuffer *r, AccelSample s) {
    r->buf[r->idx] = s;
    r->idx = (r->idx + 1) % WINDOW_SIZE;
    if (r->count < WINDOW_SIZE) r->count++;
}

static void compute_window_stats(RingBuffer *r, float *mean_mag, float *var_mag, float *ptp_mag) {
    float mags[WINDOW_SIZE];
    float sum = 0.0f;
    float minv = 1e9f, maxv = -1e9f;

    for (int i = 0; i < r->count; i++) {
        mags[i] = magnitude(r->buf[i]);
        sum += mags[i];
        if (mags[i] < minv) minv = mags[i];
        if (mags[i] > maxv) maxv = mags[i];
    }

    *mean_mag = sum / r->count;

    float var_sum = 0.0f;
    for (int i = 0; i < r->count; i++) {
        float d = mags[i] - *mean_mag;
        var_sum += d * d;
    }
    *var_mag = var_sum / r->count;
    *ptp_mag = maxv - minv;
}

static void update_baseline(BaselineModel *m, float window_mean_mag) {
    // Simple exponential moving average baseline
    const float alpha = 0.05f;
    if (!m->initialized) {
        m->mean_mag = window_mean_mag;
        m->var_mag = 0.0f;
        m->initialized = true;
    } else {
        float diff = window_mean_mag - m->mean_mag;
        m->mean_mag += alpha * diff;
        m->var_mag = (1.0f - alpha) * m->var_mag + alpha * diff * diff;
    }
}

static bool detect_anomaly(BaselineModel *m, float window_mean_mag, float window_var_mag, float ptp_mag) {
    if (!m->initialized) return false;

    // Thresholds tuned for minimal demo; adjust for your sensor/noise profile
    float mean_dev = fabsf(window_mean_mag - m->mean_mag);
    float std_est = sqrtf(m->var_mag + 1e-6f);

    bool mean_anomaly = mean_dev > (3.0f * std_est + 0.2f);
    bool var_anomaly  = window_var_mag > 2.0f;
    bool ptp_anomaly  = ptp_mag > 3.0f;

    return mean_anomaly || var_anomaly || ptp_anomaly;
}

// Call this for each new accelerometer sample
void process_sample(float ax, float ay, float az) {
    AccelSample s = {ax, ay, az};
    rb_push(&rb, s);

    if (rb.count < WINDOW_SIZE) {
        // Not enough data yet
        return;
    }

    float mean_mag, var_mag, ptp_mag;
    compute_window_stats(&rb, &mean_mag, &var_mag, &ptp_mag);

    // Learn baseline for the first few windows
    static int warmup_windows = 0;
    if (warmup_windows < 20) {
        update_baseline(&model, mean_mag);
        warmup_windows++;
        return;
    }

    bool anomaly = detect_anomaly(&model, mean_mag, var_mag, ptp_mag);

    // Update baseline only when not anomalous
    if (!anomaly) {
        update_baseline(&model, mean_mag);
    }

    if (anomaly) {
        printf("ANOMALY detected: mean=%.3f var=%.3f ptp=%.3f\n",
               mean_mag, var_mag, ptp_mag);
    }
}

int main(void) {
    // Example stream: mostly stable, then a spike
    float data[][3] = {
        {0.01f, 0.02f, 1.00f}, {0.00f, 0.01f, 0.99f}, {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f}, {0.00f, 0.01f, 1.00f}, {0.01f, 0.00f, 0.99f},
        {0.02f, 0.01f, 1.00f}, {0.00f, 0.02f, 1.01f}, {0.01f, 0.01f, 1.00f},
        {0.00f, 0.00f, 1.00f}, {0.01f, 0.02f, 1.00f}, {0.02f, 0.01f, 0.99f},
        {2.50f, 1.80f, 3.20f}, // anomaly
        {0.01f, 0.01f, 1.00f}
    };

    int n = sizeof(data) / sizeof(data[0]);
    for (int i = 0; i < n; i++) {
        process_sample(data[i][0], data[i][1], data[i][2]);
    }

    return 0;
}
