#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 1.5f   // tune this for your sensor/noise level

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} RollingMean;

void rolling_mean_init(RollingMean *rm) {
    rm->index = 0;
    rm->count = 0;
    rm->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        rm->buffer[i] = 0.0f;
    }
}

float rolling_mean_update(RollingMean *rm, float value) {
    if (rm->count < WINDOW_SIZE) {
        rm->buffer[rm->index] = value;
        rm->sum += value;
        rm->count++;
    } else {
        rm->sum -= rm->buffer[rm->index];
        rm->buffer[rm->index] = value;
        rm->sum += value;
    }

    rm->index = (rm->index + 1) % WINDOW_SIZE;
    return rm->sum / rm->count;
}

float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

bool detect_anomaly(float magnitude, float baseline) {
    float deviation = fabsf(magnitude - baseline);
    return deviation > ANOMALY_THRESHOLD;
}

