Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from **accelerometer data**. It is designed to be simple enough to port to a microcontroller, while still being functional.

## What it does
- Reads 3-axis accelerometer samples
- Computes a simple motion magnitude
- Applies a lightweight low-pass filter
- Maintains a rolling baseline
- Flags an anomaly when the signal deviates too much from baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define ALPHA 0.1f          // Low-pass filter strength
#define THRESHOLD 1.8f      // Anomaly threshold multiplier

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float filtered_mag;
    float baseline;
    float window[WINDOW_SIZE];
    int index;
    int count;
} AnomalyDetector;

static float magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

void detector_init(AnomalyDetector *d) {
    d->filtered_mag = 0.0f;
    d->baseline = 0.0f;
    d->index = 0;
    d->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->window[i] = 0.0f;
    }
}

bool detector_update(AnomalyDetector *d, AccelSample sample) {
    float mag = magnitude(sample);

    // Simple low-pass filter
    if (d->count == 0) {
        d->filtered_mag = mag;
    } else {
        d->filtered_mag = ALPHA * mag + (1.0f - ALPHA) * d->filtered_mag;
    }

    // Update rolling window
    d->window[d->index] = d->filtered_mag;
    d->index = (d->index + 1) % WINDOW_SIZE;
    if (d->count < WINDOW_SIZE) d->count++;

    // Compute baseline as mean of window
    float sum = 0.0f;
    for (int i = 0; i < d->count; i++) {
        sum += d->window[i];
    }
    d->baseline = sum / d->count;

    // Detect anomaly if filtered magnitude deviates significantly
    float deviation = fabsf(d->filtered_mag - d->baseline);

    // Simple adaptive threshold: anomaly if deviation exceeds threshold * baseline
    if (d->baseline > 0.001f && deviation > THRESHOLD * d->baseline) {
        return true;
    }

    return false;
}

int main(void) {
    AnomalyDetector detector;
    detector_init(&detector);

    // Example stream of accelerometer samples
    AccelSample data[] = {
        {0.01f, 0.02f, 0.98f},
        {0.00f, 0.01f, 1.00f},
        {0.02f, 0.00f, 0.99f},
        {0.01f, 0.02f, 1.01f},
        {0.50f, 0.40f, 1.80f},  // likely anomaly
        {0.02f, 0.01f, 1.00f},
        {0.01f, 0.02f, 0.99f}
    };

    int n = sizeof(data) / sizeof(data[0]);

    for (int i = 0; i < n; i++) {
        bool anomaly = detector_update(&detector, data[i]);
        printf("Sample %d: mag=%.3f filtered=%.3f baseline=%.3f %s\n",
               i,
               magnitude(data[i]),
               detector.filtered_mag,
               detector.baseline,
               anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
```

