Below is a **minimal working embedded-style sensor-processing pipeline** for **accelerometer anomaly detection**. It is designed to be simple enough to run on a microcontroller or in a constrained environment.

## What it does
- Reads 3-axis accelerometer samples
- Maintains a small sliding window
- Computes basic features:
  - mean magnitude
  - variance of magnitude
  - peak magnitude
- Flags an anomaly if the current window deviates too much from a learned baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define THRESHOLD_Z 3.0f

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float mag[WINDOW_SIZE];
    int idx;
    int count;
} Window;

typedef struct {
    float baseline_mean;
    float baseline_var;
    bool initialized;
} Model;

static float magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static void window_init(Window *w) {
    w->idx = 0;
    w->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->mag[i] = 0.0f;
    }
}

static void window_push(Window *w, float value) {
    w->mag[w->idx] = value;
    w->idx = (w->idx + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) w->count++;
}

static void compute_features(Window *w, float *mean, float *var, float *peak) {
    float sum = 0.0f;
    float maxv = 0.0f;

    for (int i = 0; i < w->count; i++) {
        sum += w->mag[i];
        if (w->mag[i] > maxv) maxv = w->mag[i];
    }

    *mean = sum / (float)w->count;

    float vsum = 0.0f;
    for (int i = 0; i < w->count; i++) {
        float d = w->mag[i] - *mean;
        vsum += d * d;
    }
    *var = vsum / (float)w->count;
    *peak = maxv;
}

static void model_update(Model *m, float mean, float var) {
    if (!m->initialized) {
        m->baseline_mean = mean;
        m->baseline_var = var;
        m->initialized = true;
        return;
    }

    // Simple exponential moving average baseline
    const float alpha = 0.01f;
    m->baseline_mean = (1.0f - alpha) * m->baseline_mean + alpha * mean;
    m->baseline_var  = (1.0f - alpha) * m->baseline_var  + alpha * var;
}

static bool detect_anomaly(Model *m, float mean, float var, float peak) {
    if (!m->initialized) return false;

    // Z-score-like deviation using baseline variance
    float std = sqrtf(m->baseline_var + 1e-6f);
    float z = fabsf(mean - m->baseline_mean) / std;

    // Simple rule: large mean deviation or unusually high peak
    if (z > THRESHOLD_Z) return true;
    if (peak > m->baseline_mean + 4.0f * std) return true;

    return false;
}

int main(void) {
    Window w;
    Model m = {0};
    window_init(&w);

    // Example stream: mostly normal data, then anomaly
    AccelSample stream[] = {
        {0.01f, 0.02f, 0.98f}, {0.00f, 0.01f, 1.00f}, {0.02f, 0.00f, 0.99f},
        {0.01f, 0.03f, 1.01f}, {0.00f, 0.02f, 0.97f}, {0.01f, 0.01f, 1.00f},
        {0.02f, 0.02f, 0.99f}, {0.00f, 0.01f, 1.02f}, {0.01f, 0.00f, 0.98f},
        {2.50f, 1.80f, 3.20f}, // anomaly
        {0.01f, 0.02f, 1.00f}
    };

    int n = sizeof(stream) / sizeof(stream[0]);

    for (int i = 0; i < n; i++) {
        float mag = magnitude(stream[i]);
        window_push(&w, mag);

        if (w.count < WINDOW_SIZE) {
            // Warm-up phase: build baseline
            if (w.count >= 8) {
                float mean, var, peak;
                compute_features(&w, &mean, &var, &peak);
                model_update(&m, mean, var);
            }
            continue;
        }

        float mean, var, peak;
        compute_features(&w, &mean, &var, &peak);

        bool anomaly = detect_anomaly(&m, mean, var, peak);

        if (anomaly) {
            printf("Anomaly detected at sample %d: mean=%.3f var=%.3f peak=%.3f\n",
                   i, mean, var, peak);
        } else {
            model_update(&m, mean, var);
        }
    }

    return 0;
}
