## What it does
- Reads accelerometer samples `(ax, ay, az)`
- Computes a simple feature: **magnitude**
- Maintains a short moving average and variance estimate
- Flags an anomaly when the current magnitude deviates too much from the recent baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 3.0f   // number of std devs from mean
#define MIN_SAMPLES 8

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float sumsq;
} MovingStats;

void stats_init(MovingStats *s) {
    s->index = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        s->buffer[i] = 0.0f;
    }
}

void stats_push(MovingStats *s, float x) {
    if (s->count < WINDOW_SIZE) {
        s->buffer[s->index] = x;
        s->sum += x;
        s->sumsq += x * x;
        s->count++;
    } else {
        float old = s->buffer[s->index];
        s->buffer[s->index] = x;
        s->sum += x - old;
        s->sumsq += x * x - old * old;
    }
    s->index = (s->index + 1) % WINDOW_SIZE;
}

float stats_mean(const MovingStats *s) {
    return (s->count > 0) ? (s->sum / s->count) : 0.0f;
}

float stats_stddev(const MovingStats *s) {
    if (s->count < 2) return 0.0f;
    float mean = stats_mean(s);
    float var = (s->sumsq / s->count) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    return sqrtf(var);
}

float accel_magnitude(float ax, float ay, float az) {
    return sqrtf(ax*ax + ay*ay + az*az);
}

bool detect_anomaly(MovingStats *stats, float mag) {
    if (stats->count < MIN_SAMPLES) {
        stats_push(stats, mag);
        return false; // not enough history yet
    }

    float mean = stats_mean(stats);
    float stddev = stats_stddev(stats);

    bool anomaly = false;
    if (stddev > 0.0001f) {
        float z = fabsf(mag - mean) / stddev;
        anomaly = (z > ANOMALY_THRESHOLD);
    }

    stats_push(stats, mag);
    return anomaly;
}

int main(void) {
    MovingStats stats;
    stats_init(&stats);

    // Example accelerometer stream: mostly stable, then a spike
    float samples[][3] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 1.00f},
        {0.01f, 0.00f, 0.99f},
        {0.02f, 0.01f, 1.00f},
        {0.01f, 0.01f, 1.00f},
        {0.00f, 0.02f, 1.01f},
        {2.50f, 1.80f, 3.20f}, // anomaly
        {0.01f, 0.01f, 1.00f}
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float ax = samples[i][0];
        float ay = samples[i][1];
        float az = samples[i][2];

        float mag = accel_magnitude(ax, ay, az);
        bool anomaly = detect_anomaly(&stats, mag);

        printf("Sample %d: mag=%.3f -> %s\n",
               i, mag, anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
