Below is a minimal working embedded-style sensor-processing pipeline for anomaly detection from accelerometer data. It is designed to be simple enough to run on a microcontroller, while still showing the full flow:

1. read accelerometer samples  
2. filter / preprocess  
3. extract features over a short window  
4. score anomaly  
5. trigger an alert

---

## 1) Pipeline overview

**Input:** 3-axis accelerometer samples `(ax, ay, az)`  
**Output:** anomaly flag when motion deviates from normal

### Simple anomaly idea
For a stationary or normal device, the acceleration magnitude should stay near a baseline, with limited variance.  
We compute:

- **magnitude**: `sqrt(ax² + ay² + az²)`
- **window mean**
- **window variance**
- **deviation from baseline**

If the window statistics exceed thresholds, flag an anomaly.

---

## 2) Minimal C implementation

This version is suitable as a starting point for embedded firmware.

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define BASELINE_MEAN 1.0f      // adjust for your sensor units (e.g., g)
#define MEAN_THRESHOLD 0.25f
#define VAR_THRESHOLD  0.08f

typedef struct {
    float mag_buffer[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
} AccelWindow;

typedef struct {
    float mean;
    float variance;
    bool anomaly;
} FeatureResult;

static float accel_magnitude(float ax, float ay, float az) {
    return sqrtf(ax * ax + ay * ay + az * az);
}

static void window_init(AccelWindow *w) {
    w->index = 0;
    w->count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->mag_buffer[i] = 0.0f;
    }
}

static void window_push(AccelWindow *w, float mag) {
    w->mag_buffer[w->index] = mag;
    w->index = (w->index + 1) % WINDOW_SIZE;
    if (w->count < WINDOW_SIZE) {
        w->count++;
    }
}

static FeatureResult compute_features(const AccelWindow *w) {
    FeatureResult result = {0};

    if (w->count == 0) {
        return result;
    }

    float sum = 0.0f;
    for (uint8_t i = 0; i < w->count; i++) {
        sum += w->mag_buffer[i];
    }
    result.mean = sum / w->count;

    float var_sum = 0.0f;
    for (uint8_t i = 0; i < w->count; i++) {
        float d = w->mag_buffer[i] - result.mean;
        var_sum += d * d;
    }
    result.variance = var_sum / w->count;

    float mean_dev = fabsf(result.mean - BASELINE_MEAN);

    if (mean_dev > MEAN_THRESHOLD || result.variance > VAR_THRESHOLD) {
        result.anomaly = true;
    }

    return result;
}

// Call this once per new accelerometer sample
bool process_accel_sample(AccelWindow *w, float ax, float ay, float az) {
    float mag = accel_magnitude(ax, ay, az);
    window_push(w, mag);

    // Wait until the window is full before deciding
    if (w->count < WINDOW_SIZE) {
        return false;
    }

    FeatureResult features = compute_features(w);
    return features.anomaly;
}
```

