Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from accelerometer data.

It is designed to be:
- **small**
- **streaming**
- **low-memory**
- **easy to port to MCU firmware**

It uses:
1. **3-axis accelerometer samples**
2. **simple feature extraction** over a short window
3. **baseline statistics**
4. **z-score anomaly detection**

---

## 1) Pipeline overview

**Input:** raw accelerometer samples `(ax, ay, az)`  
**Processing:**
- compute magnitude: `m = sqrt(ax² + ay² + az²)`
- maintain a fixed-size window
- compute window mean and variance
- compare against baseline mean/std
- flag anomaly if deviation is too large

**Output:** `anomaly = true/false`

---

## 2) Minimal C implementation

```c
#include <math.h>
#include <stdbool.h>
#include <stdint.h>

#define WINDOW_SIZE 32
#define BASELINE_ALPHA 0.01f
#define Z_THRESHOLD 3.0f

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float sumsq;

    // baseline model
    float baseline_mean;
    float baseline_var;
    bool baseline_initialized;
} AnomalyDetector;

void detector_init(AnomalyDetector *d) {
    d->index = 0;
    d->count = 0;
    d->sum = 0.0f;
    d->sumsq = 0.0f;
    d->baseline_mean = 0.0f;
    d->baseline_var = 1.0f;
    d->baseline_initialized = false;

    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->buffer[i] = 0.0f;
    }
}

static float fast_sqrt(float x) {
    return sqrtf(x);
}

// Add one accelerometer sample and return true if anomaly detected
bool detector_update(AnomalyDetector *d, float ax, float ay, float az) {
    // 1) Feature extraction: magnitude
    float mag = fast_sqrt(ax * ax + ay * ay + az * az);

    // 2) Update sliding window
    if (d->count < WINDOW_SIZE) {
        d->buffer[d->index] = mag;
        d->sum += mag;
        d->sumsq += mag * mag;
        d->count++;
    } else {
        float old = d->buffer[d->index];
        d->buffer[d->index] = mag;
        d->sum += mag - old;
        d->sumsq += mag * mag - old * old;
    }

    d->index = (d->index + 1) % WINDOW_SIZE;

    // Wait until window is full
    if (d->count < WINDOW_SIZE) {
        return false;
    }

    // 3) Compute window statistics
    float mean = d->sum / WINDOW_SIZE;
    float var = (d->sumsq / WINDOW_SIZE) - (mean * mean);
    if (var < 1e-6f) var = 1e-6f;
    float std = fast_sqrt(var);

    // 4) Initialize baseline from first full window
    if (!d->baseline_initialized) {
        d->baseline_mean = mean;
        d->baseline_var = var;
        d->baseline_initialized = true;
        return false;
    }

    float baseline_std = fast_sqrt(d->baseline_var);
    if (baseline_std < 1e-6f) baseline_std = 1e-6f;

    // 5) Z-score anomaly detection
    float z = (mean - d->baseline_mean) / baseline_std;
    bool anomaly = (z > Z_THRESHOLD) || (z < -Z_THRESHOLD);

    // 6) Slowly adapt baseline if not anomalous
    if (!anomaly) {
        d->baseline_mean = (1.0f - BASELINE_ALPHA) * d->baseline_mean + BASELINE_ALPHA * mean;
        d->baseline_var = (1.0f - BASELINE_ALPHA) * d->baseline_var + BASELINE_ALPHA * var;
    }

    return anomaly;
}
```

