Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from **accelerometer data**. It is designed to be simple enough to run on a microcontroller or in a small embedded runtime.

## What it does
- Reads 3-axis accelerometer samples
- Computes a simple feature: **magnitude**
- Maintains a rolling baseline using a small window
- Flags an anomaly when the current magnitude deviates too far from the baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 16
#define ANOMALY_THRESHOLD 2.5f   // tune for your sensor/noise level

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} RollingStats;

void init_stats(RollingStats *s) {
    s->index = 0;
    s->count = 0;
    s->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        s->buffer[i] = 0.0f;
    }
}

void update_stats(RollingStats *s, float value) {
    if (s->count < WINDOW_SIZE) {
        s->buffer[s->index] = value;
        s->sum += value;
        s->count++;
    } else {
        s->sum -= s->buffer[s->index];
        s->buffer[s->index] = value;
        s->sum += value;
    }
    s->index = (s->index + 1) % WINDOW_SIZE;
}

float mean_stats(const RollingStats *s) {
    if (s->count == 0) return 0.0f;
    return s->sum / (float)s->count;
}

float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

bool is_anomaly(float current, float baseline) {
    return fabsf(current - baseline) > ANOMALY_THRESHOLD;
}

int main(void) {
    // Example stream of accelerometer samples
    AccelSample samples[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.02f, 1.00f},
        {0.50f, 0.80f, 2.50f}, // anomaly
        {0.01f, 0.01f, 1.00f}
    };

    int n = sizeof(samples) / sizeof(samples[0]);
    RollingStats stats;
    init_stats(&stats);

    for (int i = 0; i < n; i++) {
        float mag = accel_magnitude(samples[i]);

        float baseline = mean_stats(&stats);
        bool anomaly = (stats.count >= WINDOW_SIZE / 2) && is_anomaly(mag, baseline);

        printf("Sample %d: mag=%.3f baseline=%.3f %s\n",
               i, mag, baseline, anomaly ? "ANOMALY" : "OK");

        update_stats(&stats, mag);
    }

    return 0;
}
```

