Below is a **minimal working embedded-style sensor-processing pipeline** for **accelerometer anomaly detection**. It is designed to be simple enough to run on a microcontroller or in a firmware-like environment.

## What it does
- Reads 3-axis accelerometer samples
- Computes a simple feature: **magnitude**
- Maintains a **rolling baseline**
- Flags an anomaly when the current magnitude deviates too much from the baseline

---

## Minimal pipeline design

### Stages
1. **Acquire sample**  
   Read `ax, ay, az`
2. **Preprocess**  
   Compute magnitude: `sqrt(ax² + ay² + az²)`
3. **Filter / baseline**  
   Update a moving average and moving variance
4. **Detect anomaly**  
   If `|magnitude - mean| > threshold * stddev`, raise anomaly
5. **Output event**  
   Send alert / log / trigger action

---

## Minimal C implementation

```c
#include <math.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>

#define WINDOW_SIZE 32
#define THRESHOLD_STDDEV 3.0f

typedef struct {
    float ax, ay, az;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
    float sumsq;
} RollingStats;

typedef struct {
    float mean;
    float stddev;
    bool anomaly;
} DetectionResult;

void rolling_stats_init(RollingStats *rs) {
    rs->index = 0;
    rs->count = 0;
    rs->sum = 0.0f;
    rs->sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        rs->buffer[i] = 0.0f;
    }
}

void rolling_stats_update(RollingStats *rs, float value) {
    if (rs->count < WINDOW_SIZE) {
        rs->buffer[rs->index] = value;
        rs->sum += value;
        rs->sumsq += value * value;
        rs->count++;
    } else {
        float old = rs->buffer[rs->index];
        rs->buffer[rs->index] = value;
        rs->sum += value - old;
        rs->sumsq += (value * value) - (old * old);
    }

    rs->index = (rs->index + 1) % WINDOW_SIZE;
}

void rolling_stats_compute(const RollingStats *rs, float *mean, float *stddev) {
    if (rs->count == 0) {
        *mean = 0.0f;
        *stddev = 0.0f;
        return;
    }

    *mean = rs->sum / rs->count;

    float variance = (rs->sumsq / rs->count) - (*mean * *mean);
    if (variance < 0.0f) variance = 0.0f;
    *stddev = sqrtf(variance);
}

float accel_magnitude(const AccelSample *s) {
    return sqrtf(s->ax * s->ax + s->ay * s->ay + s->az * s->az);
}

DetectionResult process_sample(RollingStats *baseline, const AccelSample *sample) {
    DetectionResult result = {0};

    float mag = accel_magnitude(sample);

    // Update baseline first
    rolling_stats_update(baseline, mag);
    rolling_stats_compute(baseline, &result.mean, &result.stddev);

    // Detect anomaly once enough samples exist
    if (baseline->count >= WINDOW_SIZE) {
        float deviation = fabsf(mag - result.mean);
        result.anomaly = (result.stddev > 0.0f) &&
                         (deviation > THRESHOLD_STDDEV * result.stddev);
    } else {
        result.anomaly = false;
    }

    return result;
}

// Example stub for sensor read
bool read_accelerometer(AccelSample *out) {
    // Replace with real sensor driver code
    static int i = 0;
    i++;

    // Normal samples
    out->ax = 0.02f;
    out->ay = -0.01f;
    out->az = 1.00f;

    // Inject anomaly every 100th sample
    if (i % 100 == 0) {
        out->ax = 2.5f;
        out->ay = 2.0f;
        out->az = 3.0f;
    }

    return true;
}

int main(void) {
    RollingStats baseline;
    rolling_stats_init(&baseline);

    while (1) {
        AccelSample sample;
        if (!read_accelerometer(&sample)) {
            continue;
        }

        DetectionResult result = process_sample(&baseline, &sample);

        if (result.anomaly) {
            printf("ANOMALY detected! mean=%.3f stddev=%.3f\n",
                   result.mean, result.stddev);
        }
    }

    return 0;
}
