Below is a **minimal working embedded-style sensor-processing pipeline** for **accelerometer anomaly detection**. It is designed to be simple enough to run on a microcontroller or be adapted to one.

## What it does
- Reads 3-axis accelerometer samples
- Computes a simple magnitude-based feature
- Maintains a rolling baseline
- Flags an anomaly when the current signal deviates too much from baseline

---

## Minimal pipeline design

### 1) Data acquisition
Read accelerometer samples at a fixed rate:
- `ax, ay, az`

### 2) Preprocessing
Compute magnitude:
- `mag = sqrt(ax*ax + ay*ay + az*az)`

For embedded simplicity, you can also use:
- `mag2 = ax*ax + ay*ay + az*az`
to avoid `sqrt()`.

### 3) Feature extraction
Use a short moving average and moving variance over a window.

### 4) Anomaly detection
If the current magnitude differs from the baseline by more than a threshold:
- `abs(mag - mean) > k * stddev`
then flag anomaly.

---

# Minimal C implementation

```c
#include <stdint.h>
#include <stdbool.h>
#include <math.h>

#define WINDOW_SIZE 16
#define THRESHOLD_K 3.0f

typedef struct {
    float buf[WINDOW_SIZE];
    int idx;
    int count;
    float sum;
    float sumsq;
} RollingStats;

typedef struct {
    RollingStats stats;
} AnomalyDetector;

static void stats_init(RollingStats *s) {
    s->idx = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        s->buf[i] = 0.0f;
    }
}

static void stats_update(RollingStats *s, float x) {
    if (s->count < WINDOW_SIZE) {
        s->buf[s->idx] = x;
        s->sum += x;
        s->sumsq += x * x;
        s->count++;
        s->idx = (s->idx + 1) % WINDOW_SIZE;
    } else {
        float old = s->buf[s->idx];
        s->sum -= old;
        s->sumsq -= old * old;

        s->buf[s->idx] = x;
        s->sum += x;
        s->sumsq += x * x;
        s->idx = (s->idx + 1) % WINDOW_SIZE;
    }
}

static float stats_mean(const RollingStats *s) {
    if (s->count == 0) return 0.0f;
    return s->sum / (float)s->count;
}

static float stats_stddev(const RollingStats *s) {
    if (s->count < 2) return 0.0f;
    float mean = stats_mean(s);
    float var = (s->sumsq / (float)s->count) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    return sqrtf(var);
}

void detector_init(AnomalyDetector *d) {
    stats_init(&d->stats);
}

bool detector_process_sample(AnomalyDetector *d, float ax, float ay, float az) {
    // Feature: magnitude
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    // If not enough history, just learn baseline
    if (d->stats.count < WINDOW_SIZE) {
        stats_update(&d->stats, mag);
        return false;
    }

    float mean = stats_mean(&d->stats);
    float stddev = stats_stddev(&d->stats);

    bool anomaly = false;
    if (stddev > 0.0001f) {
        if (fabsf(mag - mean) > THRESHOLD_K * stddev) {
            anomaly = true;
        }
    }

    // Update baseline after decision
    stats_update(&d->stats, mag);

    return anomaly;
}
```

