Below is a **minimal working embedded-style sensor-processing pipeline** for **accelerometer anomaly detection**. It is designed to be simple enough to run on a microcontroller, while still being realistic:

- reads 3-axis accelerometer samples
- computes a lightweight feature: **magnitude**
- maintains a short **baseline mean and variance**
- flags an anomaly when the current sample deviates too much from the baseline

## 1) Core idea

For each sample `(ax, ay, az)`:

1. Compute magnitude:
   \[
   m = \sqrt{ax^2 + ay^2 + az^2}
   \]
2. Update a running baseline over a window.
3. Compute z-score-like deviation:
   \[
   z = \frac{|m - \mu|}{\sigma + \epsilon}
   \]
4. If `z > threshold`, report anomaly.

This is intentionally minimal and suitable for embedded systems.

---

## 2) Minimal C implementation

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define ANOMALY_THRESHOLD 3.0f
#define EPSILON 1e-6f

typedef struct {
    float buffer[WINDOW_SIZE];
    uint8_t index;
    uint8_t count;
    float sum;
    float sumsq;
} RunningStats;

typedef struct {
    RunningStats stats;
} AnomalyDetector;

static void stats_init(RunningStats *s) {
    s->index = 0;
    s->count = 0;
    s->sum = 0.0f;
    s->sumsq = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        s->buffer[i] = 0.0f;
    }
}

static void stats_update(RunningStats *s, float x) {
    if (s->count < WINDOW_SIZE) {
        s->buffer[s->index] = x;
        s->sum += x;
        s->sumsq += x * x;
        s->count++;
    } else {
        float old = s->buffer[s->index];
        s->buffer[s->index] = x;
        s->sum += x - old;
        s->sumsq += x * x - old * old;
    }

    s->index = (s->index + 1) % WINDOW_SIZE;
}

static float stats_mean(const RunningStats *s) {
    if (s->count == 0) return 0.0f;
    return s->sum / (float)s->count;
}

static float stats_stddev(const RunningStats *s) {
    if (s->count < 2) return 0.0f;
    float mean = stats_mean(s);
    float var = (s->sumsq / (float)s->count) - (mean * mean);
    if (var < 0.0f) var = 0.0f;
    return sqrtf(var);
}

void detector_init(AnomalyDetector *d) {
    stats_init(&d->stats);
}

bool detector_process_sample(AnomalyDetector *d, float ax, float ay, float az) {
    // Compute magnitude
    float mag = sqrtf(ax * ax + ay * ay + az * az);

    // If not enough history, just build baseline
    if (d->stats.count < WINDOW_SIZE) {
        stats_update(&d->stats, mag);
        return false;
    }

    float mean = stats_mean(&d->stats);
    float stddev = stats_stddev(&d->stats);

    float z = fabsf(mag - mean) / (stddev + EPSILON);
    bool anomaly = (z > ANOMALY_THRESHOLD);

    // Update baseline after decision
    stats_update(&d->stats, mag);

    return anomaly;
}
