Below is a **minimal working embedded-style sensor-processing pipeline** for detecting anomalies from accelerometer data. It is intentionally simple and suitable as a starting point for a microcontroller project.

## What it does
- Reads 3-axis accelerometer samples
- Computes a simple magnitude-based feature
- Maintains a rolling baseline
- Flags an anomaly when the current reading deviates too much from the baseline

---

## Minimal C implementation

```c
#include <stdio.h>
#include <math.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define ANOMALY_THRESHOLD 2.5f   // tune this for your sensor/noise level

typedef struct {
    float x, y, z;
} AccelSample;

typedef struct {
    float buffer[WINDOW_SIZE];
    int index;
    int count;
    float sum;
} RollingWindow;

static void window_init(RollingWindow *w) {
    w->index = 0;
    w->count = 0;
    w->sum = 0.0f;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        w->buffer[i] = 0.0f;
    }
}

static void window_push(RollingWindow *w, float value) {
    if (w->count < WINDOW_SIZE) {
        w->buffer[w->index] = value;
        w->sum += value;
        w->count++;
    } else {
        w->sum -= w->buffer[w->index];
        w->buffer[w->index] = value;
        w->sum += value;
    }
    w->index = (w->index + 1) % WINDOW_SIZE;
}

static float window_mean(const RollingWindow *w) {
    return (w->count > 0) ? (w->sum / w->count) : 0.0f;
}

static float accel_magnitude(AccelSample s) {
    return sqrtf(s.x * s.x + s.y * s.y + s.z * s.z);
}

static bool detect_anomaly(RollingWindow *baseline, float magnitude) {
    float mean = window_mean(baseline);

    // Simple deviation check
    float deviation = fabsf(magnitude - mean);

    // Update baseline after checking
    window_push(baseline, magnitude);

    return (baseline->count >= WINDOW_SIZE) && (deviation > ANOMALY_THRESHOLD);
}

int main(void) {
    RollingWindow baseline;
    window_init(&baseline);

    // Example stream of accelerometer samples
    AccelSample samples[] = {
        {0.01f, 0.02f, 1.00f},
        {0.00f, 0.01f, 0.99f},
        {0.02f, 0.00f, 1.01f},
        {0.01f, 0.01f, 1.00f},
        {0.50f, 0.80f, 2.50f},  // likely anomaly
        {0.02f, 0.01f, 1.00f},
    };

    int n = sizeof(samples) / sizeof(samples[0]);

    for (int i = 0; i < n; i++) {
        float mag = accel_magnitude(samples[i]);
        bool anomaly = detect_anomaly(&baseline, mag);

        printf("Sample %d: mag=%.3f -> %s\n",
               i, mag, anomaly ? "ANOMALY" : "normal");
    }

    return 0;
}
```

