Below is a **minimal working embedded-style sensor-processing pipeline** for **accelerometer anomaly detection**. It is designed to be simple enough to run on a microcontroller or in a bare-metal/RTOS task.

## What it does
1. Reads 3-axis accelerometer samples
2. Computes a simple feature: **magnitude**
3. Maintains a **baseline mean and variance**
4. Flags an anomaly when the current magnitude deviates too far from the baseline

This is intentionally lightweight and suitable as a starting point.

---

## Minimal C implementation

```c
#include <math.h>
#include <stdint.h>
#include <stdbool.h>

#define WINDOW_SIZE 32
#define ANOMALY_Z_THRESHOLD 3.0f

typedef struct {
    float mean;
    float m2;
    uint32_t count;
} RunningStats;

typedef struct {
    float x;
    float y;
    float z;
} AccelSample;

typedef struct {
    RunningStats stats;
    float window[WINDOW_SIZE];
    uint8_t index;
    uint8_t filled;
} AnomalyDetector;

static void stats_init(RunningStats *s) {
    s->mean = 0.0f;
    s->m2 = 0.0f;
    s->count = 0;
}

static void stats_update(RunningStats *s, float x) {
    s->count++;
    float delta = x - s->mean;
    s->mean += delta / (float)s->count;
    float delta2 = x - s->mean;
    s->m2 += delta * delta2;
}

static float stats_variance(const RunningStats *s) {
    if (s->count < 2) return 0.0f;
    return s->m2 / (float)(s->count - 1);
}

static float accel_magnitude(const AccelSample *a) {
    return sqrtf(a->x * a->x + a->y * a->y + a->z * a->z);
}

void detector_init(AnomalyDetector *d) {
    stats_init(&d->stats);
    d->index = 0;
    d->filled = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        d->window[i] = 0.0f;
    }
}

bool detector_process_sample(AnomalyDetector *d, const AccelSample *sample) {
    float mag = accel_magnitude(sample);

    // Warm-up phase: collect baseline
    if (d->filled < WINDOW_SIZE) {
        d->window[d->index++] = mag;
        stats_update(&d->stats, mag);
        d->filled++;
        if (d->index >= WINDOW_SIZE) d->index = 0;
        return false; // no anomaly during warm-up
    }

    float mean = d->stats.mean;
    float var = stats_variance(&d->stats);
    float stddev = sqrtf(var);

    bool anomaly = false;
    if (stddev > 1e-6f) {
        float z = fabsf(mag - mean) / stddev;
        anomaly = (z > ANOMALY_Z_THRESHOLD);
    }

    // Update baseline using a rolling window (simple replacement)
    float old = d->window[d->index];
    d->window[d->index] = mag;
    d->index = (d->index + 1) % WINDOW_SIZE;

    // Recompute stats from scratch for simplicity
    stats_init(&d->stats);
    for (int i = 0; i < WINDOW_SIZE; i++) {
        stats_update(&d->stats, d->window[i]);
    }

    return anomaly;
}
```

---

## Example usage

