    s->actuator_on = false;
    s->last_update_ms = 0;
    s->min_toggle_interval_ms = min_toggle_interval_ms;
}

static void control_update(ControlState *s, uint16_t filtered_value, uint32_t now_ms) {
    /* Rate limit toggling to reduce wear and chatter */
    if ((now_ms - s->last_update_ms) < s->min_toggle_interval_ms) {
        return;
    }

    if (!s->actuator_on && filtered_value >= SENSOR_HIGH_LIMIT) {
        s->actuator_on = true;
        s->last_update_ms = now_ms;
        set_actuator(ACTUATOR_ON);
    } else if (s->actuator_on && filtered_value <= SENSOR_LOW_LIMIT) {
        s->actuator_on = false;
        s->last_update_ms = now_ms;
        set_actuator(ACTUATOR_OFF);
