typedef struct {
    uint16_t buffer[FILTER_WINDOW_SIZE];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAverageFilter;

static void filter_init(MovingAverageFilter *f)
{
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW_SIZE; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample)
{
    if (sample < SENSOR_MIN_VALID || sample > SENSOR_MAX_VALID) {
        /* Invalid sample: return last average without updating */
        if (f->count == 0) return 0;
        return (uint16_t)(f->sum / f->count);
    }

    if (f->count < FILTER_WINDOW_SIZE) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index++;
    if (f->index >= FILTER_WINDOW_SIZE) {
        f->index = 0;
    }

    return (uint16_t)(f->sum / f->count);
}

