extern void set_actuator(bool on);       // Control relay / motor / valve
extern uint32_t millis(void);            // System uptime in ms

// -------------------- Simple Moving Average Filter --------------------

typedef struct {
    uint16_t buffer[FILTER_WINDOW];
    uint8_t index;
    uint8_t count;
    uint32_t sum;
} MovingAverageFilter;

static void filter_init(MovingAverageFilter *f) {
    f->index = 0;
    f->count = 0;
    f->sum = 0;
    for (uint8_t i = 0; i < FILTER_WINDOW; i++) {
        f->buffer[i] = 0;
    }
}

static uint16_t filter_update(MovingAverageFilter *f, uint16_t sample) {
    if (f->count < FILTER_WINDOW) {
        f->buffer[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->buffer[f->index];
        f->buffer[f->index] = sample;
        f->sum += sample;
    }

    f->index = (f->index + 1) % FILTER_WINDOW;
    return (uint16_t)(f->sum / f->count);
}

// -------------------- Actuator State Machine --------------------

