    bool on;
} ActuatorState;

static void actuator_update(ActuatorState *a, uint16_t filtered_value) {
    // Hysteresis prevents rapid toggling near threshold
    if (!a->on && filtered_value >= SENSOR_HIGH_THRESHOLD) {
        a->on = true;
        set_actuator(true);
    } else if (a->on && filtered_value <= SENSOR_LOW_THRESHOLD) {
        a->on = false;
        set_actuator(false);
    }
}

// -------------------- Main Application --------------------

int main(void) {
    MovingAverageFilter filter;
    ActuatorState actuator = { .on = false };

    filter_init(&filter);
