// Replace these with platform-specific implementations.
extern uint16_t read_sensor_raw(uint8_t sensor_id);
extern void set_actuator(uint8_t actuator_id, bool on);
extern uint32_t millis(void);

// ---------------- Lightweight moving average filter ----------------
typedef struct {
    uint16_t samples[SENSOR_WINDOW];
    uint32_t sum;
    uint8_t index;
    uint8_t count;
} MovingAvgFilter;

static void filter_init(MovingAvgFilter *f) {
    f->sum = 0;
    f->index = 0;
    f->count = 0;
    for (uint8_t i = 0; i < SENSOR_WINDOW; i++) {
        f->samples[i] = 0;
    }
}

static uint16_t filter_update(MovingAvgFilter *f, uint16_t sample) {
    if (f->count < SENSOR_WINDOW) {
        f->samples[f->index] = sample;
        f->sum += sample;
        f->count++;
    } else {
        f->sum -= f->samples[f->index];
        f->samples[f->index] = sample;
        f->sum += sample;
    }

    f->index++;
    if (f->index >= SENSOR_WINDOW) {
        f->index = 0;
    }

    return (uint16_t)(f->sum / f->count);
}

// ---------------- Control logic ----------------
typedef struct {
    uint16_t high_threshold;
    uint16_t low_threshold;
    bool actuator_state;
} ControlChannel;

