    { .high_threshold = 700, .low_threshold = 500, .actuator_state = false },
    { .high_threshold = 800, .low_threshold = 600, .actuator_state = false }
};

// Example mapping: sensor 0 -> actuator 0, sensor 1 -> actuator 1
static uint8_t sensor_to_actuator(uint8_t sensor_id) {
    return (sensor_id < NUM_ACTUATORS) ? sensor_id : 0;
}

static void update_actuator_from_sensor(uint8_t sensor_id, uint16_t filtered_value) {
    uint8_t act_id = sensor_to_actuator(sensor_id);
    ControlChannel *ch = &g_control[act_id];

    // Hysteresis to prevent rapid toggling
    if (!ch->actuator_state && filtered_value >= ch->high_threshold) {
        ch->actuator_state = true;
        set_actuator(act_id, true);
    } else if (ch->actuator_state && filtered_value <= ch->low_threshold) {
        ch->actuator_state = false;
        set_actuator(act_id, false);
    }
}

// ---------------- Main loop ----------------
