    for (uint8_t i = 0; i < NUM_SENSORS; i++) {
        filter_init(&g_filters[i]);
    }

    for (uint8_t a = 0; a < NUM_ACTUATORS; a++) {
        g_control[a].actuator_state = false;
        set_actuator(a, false);
