    if (!f->initialized) {
        filter_init(f, raw);
        return raw;
    }

    int32_t delta = (int32_t)raw - (int32_t)f->filtered;
    f->filtered += (uint16_t)(delta >> FILTER_SHIFT);
    return f->filtered;
