        if (filtered_value >= ACTUATOR_ON_THRESH) {
            g_state.actuator_on = true;
            actuator_set(true);
        }
    } else {
        if (filtered_value <= ACTUATOR_OFF_THRESH) {
            g_state.actuator_on = false;
            actuator_set(false);
