{
    if (g_state.fault) {
        actuator_set(false);
        g_state.actuator_on = false;
        return;
    }

    // Hysteresis to avoid chatter
    if (!g_state.actuator_on && filtered >= ACTUATOR_ON_THRESH) {
        g_state.actuator_on = true;
        actuator_set(true);
    } else if (g_state.actuator_on && filtered <= ACTUATOR_OFF_THRESH) {
        g_state.actuator_on = false;
        actuator_set(false);
    }
}

/* ---------------- Fault Handling ---------------- */

static void check_fault(uint32_t now_ms)
{
    if ((now_ms - g_state.last_valid_ms) > FAULT_TIMEOUT_MS) {
        g_state.fault = true;
    }
}

/* ---------------- Main Loop ---------------- */

void edge_system_init(void)
{
    g_state.filtered = 0;
    g_state.actuator_on = false;
    g_state.last_valid_ms = millis();
    g_state.fault = false;
    actuator_set(false);
}

void edge_system_step(void)
{
    uint32_t now = millis();
    uint16_t raw = read_sensor_raw();

    // Basic range validation
    if (raw >= SENSOR_MIN_RAW && raw <= SENSOR_MAX_RAW) {
        g_state.last_valid_ms = now;
        g_state.fault = false;

        uint16_t filtered = ema_filter(raw);
        update_actuator(filtered);
    } else {
        // Invalid reading: keep last state, but monitor for timeout fault
        check_fault(now);
        update_actuator((uint16_t)g_state.filtered);
    }
}

/* ---------------- Example scheduler loop ---------------- */

int main(void)
{
    edge_system_init();

    while (1) {
        edge_system_step();

        // TODO: sleep/delay for LOOP_PERIOD_MS
        // platform_delay_ms(LOOP_PERIOD_MS);
    }

    return 0;
}
```

