from collections import deque
from time import time, sleep


class MovingAverageFilter:
    def __init__(self, window_size=5):
        self.window_size = window_size
        self.values = deque(maxlen=window_size)
        self.sum = 0.0

    def update(self, value):
        if len(self.values) == self.window_size:
            self.sum -= self.values[0]
        self.values.append(value)
        self.sum += value
        return self.sum / len(self.values)


class ThresholdFilter:
    def __init__(self, min_value=None, max_value=None):
        self.min_value = min_value
        self.max_value = max_value

    def update(self, value):
        if self.min_value is not None and value < self.min_value:
            return self.min_value
        if self.max_value is not None and value > self.max_value:
            return self.max_value
        return value


class Sensor:
    def __init__(self, name, read_fn, filters=None):
        self.name = name
        self.read_fn = read_fn
        self.filters = filters or []

    def read(self):
        value = self.read_fn()
        for f in self.filters:
            value = f.update(value)
        return value


class Actuator:
    def __init__(self, name, set_fn):
        self.name = name
        self.set_fn = set_fn
        self.state = None

    def set_state(self, state):
        if state != self.state:
            self.set_fn(state)
            self.state = state


class EdgeController:
    def __init__(self, sensors, actuators, rules):
        self.sensors = sensors
        self.actuators = actuators
        self.rules = rules

    def step(self):
        readings = {}
        for sensor in self.sensors:
            try:
                readings[sensor.name] = sensor.read()
            except Exception as e:
                readings[sensor.name] = None
                print(f"Sensor error [{sensor.name}]: {e}")

        for rule in self.rules:
            try:
                rule(readings, self.actuators)
            except Exception as e:
                print(f"Rule error: {e}")


# --- Example hardware stubs ---

def read_temperature():
    # Replace with ADC / I2C / sensor driver call
    return 20.0

def read_humidity():
    # Replace with actual sensor read
    return 55.0

def set_fan(on):
    print(f"FAN -> {'ON' if on else 'OFF'}")

def set_valve(open_):
    print(f"VALVE -> {'OPEN' if open_ else 'CLOSED'}")


# --- Example control rules ---

def temperature_rule(readings, actuators):
    temp = readings.get("temperature")
    if temp is None:
        return

    fan = actuators["fan"]
    if temp > 25.0:
        fan.set_state(True)
    elif temp < 23.0:
        fan.set_state(False)


def humidity_rule(readings, actuators):
    humidity = readings.get("humidity")
    if humidity is None:
        return

    valve = actuators["valve"]
    if humidity < 40.0:
        valve.set_state(True)
    elif humidity > 50.0:
        valve.set_state(False)


def main():
    sensors = [
        Sensor(
            "temperature",
            read_temperature,
            filters=[ThresholdFilter(min_value=-40, max_value=85), MovingAverageFilter(window_size=3)]
        ),
        Sensor(
            "humidity",
            read_humidity,
            filters=[ThresholdFilter(min_value=0, max_value=100), MovingAverageFilter(window_size=3)]
        ),
    ]

    actuators = {
        "fan": Actuator("fan", set_fan),
        "valve": Actuator("valve", set_valve),
    }

    controller = EdgeController(
        sensors=sensors,
        actuators=actuators,
        rules=[temperature_rule, humidity_rule]
    )

    while True:
        controller.step()
        sleep(1)


if __name__ == "__main__":
    main()
