#include <stdio.h>

#define WINDOW_SIZE 5

typedef struct {
    int values[WINDOW_SIZE];
    int index;
    int count;
    int sum;
} MovingAverageFilter;

void filter_init(MovingAverageFilter *f) {
    f->index = 0;
    f->count = 0;
    f->sum = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) f->values[i] = 0;
}

int filter_update(MovingAverageFilter *f, int value) {
    if (f->count < WINDOW_SIZE) {
        f->count++;
    } else {
        f->sum -= f->values[f->index];
    }

    f->values[f->index] = value;
    f->sum += value;
    f->index = (f->index + 1) % WINDOW_SIZE;

    return f->sum / f->count;
}

