<body>
  <div class="hud">
    Move: A/D or Arrow Keys<br>
    Jump: W / Space / Up<br>
    Restart: R
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {
      left: false,
      right: false,
      jump: false
    };

    const world = {
      width: 3200,
      height: 1200,
      gravity: 2200
    };

    const camera = {
      x: 0,
      y: 0
    };

    const player = {
      x: 100,
      y: 200,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      speed: 420,
      jumpPower: 820,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle"
    };

    const platforms = [
      { x: 0, y: 1120, w: 3200, h: 80 },   // ground
      { x: 200, y: 950, w: 220, h: 30 },
      { x: 520, y: 860, w: 220, h: 30 },
      { x: 860, y: 780, w: 220, h: 30 },
      { x: 1180, y: 700, w: 220, h: 30 },
      { x: 1500, y: 620, w: 220, h: 30 },
      { x: 1820, y: 740, w: 240, h: 30 },
      { x: 2160, y: 860, w: 240, h: 30 },
      { x: 2500, y: 960, w: 240, h: 30 },
      { x: 2800, y: 820, w: 220, h: 30 }
    ];

    const coins = [
      { x: 260, y: 900, collected: false },
      { x: 580, y: 810, collected: false },
      { x: 920, y: 730, collected: false },
      { x: 1240, y: 650, collected: false },
      { x: 1560, y: 570, collected: false },
      { x: 1900, y: 690, collected: false },
      { x: 2240, y: 810, collected: false },
      { x: 2580, y: 910, collected: false },
      { x: 2860, y: 770, collected: false }
    ];

    let score = 0;

    // --- Sprite sheet generation (simple animated character) ---
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 192;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawFrame(frame, flip = false) {
      const ox = frame * 64;
      sctx.clearRect(ox, 0, 64, 64);

      sctx.save();
      if (flip) {
        sctx.translate(ox + 64, 0);
        sctx.scale(-1, 1);
      } else {
        sctx.translate(ox, 0);
      }

      // body
      sctx.fillStyle = "#2d6cdf";
      sctx.fillRect(20, 22, 24, 28);

      // head
      sctx.fillStyle = "#ffd7b3";
      sctx.fillRect(22, 8, 20, 18);

      // eyes
      sctx.fillStyle = "#111";
      sctx.fillRect(27, 14, 3, 3);
      sctx.fillRect(35, 14, 3, 3);

      // legs/arms animation
      sctx.fillStyle = "#1b3f8b";
      if (frame === 0) {
        sctx.fillRect(16, 50, 8, 10);
        sctx.fillRect(40, 50, 8, 10);
        sctx.fillRect(12, 26, 8, 6);
        sctx.fillRect(44, 26, 8, 6);
      } else if (frame === 1) {
        sctx.fillRect(18, 50, 8, 10);
        sctx.fillRect(38, 50, 8, 10);
        sctx.fillRect(10, 30, 8, 6);
        sctx.fillRect(46, 22, 8, 6);
      } else {
        sctx.fillRect(20, 50, 8, 10);
        sctx.fillRect(36, 50, 8, 10);
        sctx.fillRect(12, 22, 8, 6);
        sctx.fillRect(44, 30, 8, 6);
      }

      sctx.restore();
    }

    // draw frames for both directions not needed; we flip at render time
    drawFrame(0);
    drawFrame(1);
    drawFrame(2);

    function resetGame() {
      player.x = 100;
      player.y = 200;
      player.vx = 0;
      player.vy = 0;
      player.onGround = false;
      player.facing = 1;
      player.animTime = 0;
      player.state = "idle";
      score = 0;
      coins.forEach(c => c.collected = false);
    }

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update(dt) {
      // input
      const moveLeft = keys.left;
      const moveRight = keys.right;
      const wantsJump = keys.jump;

      if (moveLeft && !moveRight) {
        player.vx = -player.speed;
        player.facing = -1;
      } else if (moveRight && !moveLeft) {
        player.vx = player.speed;
        player.facing = 1;
      } else {
        // friction
        player.vx *= Math.pow(0.0001, dt);
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      // jump
      if (wantsJump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // gravity
      player.vy += world.gravity * dt;

      // horizontal movement + collision
      player.x += player.vx * dt;
      resolveCollisions("x");

      // vertical movement + collision
      player.y += player.vy * dt;
      player.onGround = false;
      resolveCollisions("y");

      // bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > world.width) player.x = world.width - player.w;
      if (player.y > world.height + 200) resetGame();

      // animation state
      const moving = Math.abs(player.vx) > 20;
      if (!player.onGround) {
        player.state = "jump";
      } else if (moving) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));

      // coin collection
      for (const coin of coins) {
        if (!coin.collected) {
          const coinBox = { x: coin.x - 12, y: coin.y - 12, w: 24, h: 24 };
          if (rectsOverlap(player, coinBox)) {
            coin.collected = true;
            score++;
          }
        }
      }
    }

    function resolveCollisions(axis) {
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (axis === "x") {
            if (player.vx > 0) {
              player.x = p.x - player.w;
            } else if (player.vx < 0) {
              player.x = p.x + p.w;
            }
            player.vx = 0;
          } else {
            if (player.vy > 0) {
              player.y = p.y - player.h;
              player.vy = 0;
              player.onGround = true;
            } else if (player.vy < 0) {
              player.y = p.y + p.h;
              player.vy = 0;
            }
          }
        }
      }
    }

    function drawBackground() {
      // sky
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // distant hills
      ctx.save();
      ctx.translate(-camera.x * 0.2, 0);
      ctx.fillStyle = "#7ec08a";
      for (let i = 0; i < 12; i++) {
        ctx.beginPath();
        ctx.ellipse(i * 300 + 100, 980, 180, 90, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      // clouds
      ctx.save();
      ctx.translate(-camera.x * 0.1, -camera.y * 0.05);
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      const clouds = [
        [150, 120], [520, 80], [980, 140], [1450, 100], [2100, 130], [2700, 90]
      ];
      for (const [x, y] of clouds) {
        ctx.beginPath();
        ctx.arc(x, y, 28, 0, Math.PI * 2);
        ctx.arc(x + 28, y - 10, 36, 0, Math.PI * 2);
        ctx.arc(x + 60, y, 26, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        const x = p.x - camera.x;
        const y = p.y - camera.y;

        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(x, y, p.w, p.h);

        ctx.fillStyle = "#4caf50";
        ctx.fillRect(x, y, p.w, 8);
      }
    }

    function drawCoins(time) {
      for (const coin of coins) {
        if (coin.collected) continue;
        const bob = Math.sin(time * 0.004 + coin.x) * 4;
        const x = coin.x - camera.x;
        const y = coin.y - camera.y + bob;

        ctx.beginPath();
        ctx.fillStyle = "#ffd700";
        ctx.arc(x, y, 10, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = "#c99a00";
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    }

    function drawPlayer(time) {
      let frame = 0;
      if (player.state === "run") {
        frame = Math.floor(player.animTime * 12) % 3;
      } else if (player.state === "jump") {
        frame = 1;
      } else {
        frame = Math.floor(player.animTime * 2) % 2;
      }

      const sx = frame * 64;
      const sy = 0;
      const dx = player.x - camera.x;
      const dy = player.y - camera.y;

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(dx + player.w, dy);
        ctx.scale(-1, 1);
        ctx.drawImage(spriteCanvas, sx, sy, 64, 64, 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(spriteCanvas, sx, sy, 64, 64, dx, dy, player.w, player.h);
      }
      ctx.restore();
    }

    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(12, 12, 160, 44);
      ctx.fillStyle = "white";
      ctx.font = "18px sans-serif";
      ctx.fillText(`Score: ${score}/${coins.length}`, 24, 40);
    }

    let last = 0;
    function loop(ts) {
      const dt = Math.min(0.033, (ts - last) / 1000 || 0);
      last = ts;

      update(dt);

      drawBackground();
      drawPlatforms();
      drawCoins(ts);
      drawPlayer(ts);
      drawHUD();

      requestAnimationFrame(loop);
    }

    // input handling
    window.addEventListener("keydown", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = true;
      if (e.code === "KeyR") resetGame();
    });

    window.addEventListener("keyup", (e) => {
      if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
      if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
      if (e.code === "ArrowUp" || e.code === "KeyW" || e.code === "Space") keys.jump = false;
    });

    resetGame();
    requestAnimationFrame(loop);
  </script>
</body>
</html>
