<body>
  <div class="hud">
    Controls: A/D or Arrow Keys to move, Space/W/Up to jump
  </div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const WORLD = {
      width: 3000,
      height: 1200
    };

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    function clamp(v, min, max) {
      return Math.max(min, Math.min(max, v));
    }

    // --- Player ---
    const player = {
      x: 100,
      y: 200,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      speed: 0.55,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    // --- Platforms / Level ---
    const platforms = [
      { x: 0, y: 500, w: 700, h: 40 },
      { x: 780, y: 430, w: 220, h: 30 },
      { x: 1080, y: 360, w: 220, h: 30 },
      { x: 1380, y: 300, w: 220, h: 30 },
      { x: 1700, y: 420, w: 260, h: 30 },
      { x: 2050, y: 360, w: 240, h: 30 },
      { x: 2400, y: 300, w: 240, h: 30 },
      { x: 2750, y: 460, w: 250, h: 40 },

      // ground segments
      { x: 700, y: 560, w: 380, h: 40 },
      { x: 1000, y: 560, w: 380, h: 40 },
      { x: 1380, y: 560, w: 420, h: 40 },
      { x: 1800, y: 560, w: 500, h: 40 },
      { x: 2300, y: 560, w: 700, h: 40 }
    ];

    // Decorative coins / stars
    const stars = [
      { x: 820, y: 390, collected: false },
      { x: 1120, y: 320, collected: false },
      { x: 1420, y: 260, collected: false },
      { x: 1760, y: 380, collected: false },
      { x: 2100, y: 320, collected: false },
      { x: 2440, y: 260, collected: false }
    ];

    let score = 0;

    // --- Sprite sheet generation (simple animated character) ---
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 192; // 4 frames * 48
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawFrame(frameIndex) {
      const x = frameIndex * 48;
      sctx.clearRect(x, 0, 48, 64);

      // body colors
      const shirt = ["#ff5c5c", "#ff7a7a", "#ff5c5c", "#ff3d3d"][frameIndex];
      const pants = "#2d4b8f";
      const skin = "#f2c7a5";
      const hair = "#3a2a1a";

      // head
      sctx.fillStyle = skin;
      sctx.beginPath();
      sctx.arc(x + 24, 18, 12, 0, Math.PI * 2);
      sctx.fill();

      // hair
      sctx.fillStyle = hair;
      sctx.fillRect(x + 14, 8, 20, 8);

      // body
      sctx.fillStyle = shirt;
      sctx.fillRect(x + 16, 28, 16, 18);

      // arms
      sctx.fillStyle = skin;
      sctx.fillRect(x + 10, 30, 6, 14);
      sctx.fillRect(x + 32, 30, 6, 14);

      // legs animation
      sctx.fillStyle = pants;
      if (frameIndex % 2 === 0) {
        sctx.fillRect(x + 17, 46, 6, 14);
        sctx.fillRect(x + 25, 44, 6, 16);
      } else {
        sctx.fillRect(x + 17, 44, 6, 16);
        sctx.fillRect(x + 25, 46, 6, 14);
      }

      // shoes
      sctx.fillStyle = "#222";
      sctx.fillRect(x + 15, 58, 10, 4);
      sctx.fillRect(x + 23, 58, 10, 4);
    }

    for (let i = 0; i < 4; i++) drawFrame(i);

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer(dt) {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      // Horizontal movement
      if (left) {
        player.vx -= player.speed * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed * dt;
        player.facing = 1;
      }

      // Friction / damping
      player.vx *= player.onGround ? 0.86 : 0.98;

      // Clamp speed
      player.vx = clamp(player.vx, -7, 7);

      // Jump
      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Gravity
      player.vy += 0.7 * dt;
      player.vy = clamp(player.vy, -50, 18);

      // Move X and resolve collisions
      player.x += player.vx * dt;
      let playerBox = { x: player.x, y: player.y, w: player.w, h: player.h };

      for (const p of platforms) {
        if (rectsOverlap(playerBox, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
          playerBox.x = player.x;
        }
      }

      // Move Y and resolve collisions
      player.y += player.vy * dt;
      player.onGround = false;
      playerBox = { x: player.x, y: player.y, w: player.w, h: player.h };

      for (const p of platforms) {
        if (rectsOverlap(playerBox, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          playerBox.y = player.y;
        }
      }

      // Collect stars
      for (const star of stars) {
        if (!star.collected) {
          const dx = (player.x + player.w / 2) - star.x;
          const dy = (player.y + player.h / 2) - star.y;
          if (Math.hypot(dx, dy) < 32) {
            star.collected = true;
            score++;
          }
        }
      }

      // Keep player in world bounds
      player.x = clamp(player.x, 0, WORLD.width - player.w);
      if (player.y > WORLD.height) {
        player.x = 100;
        player.y = 200;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (Math.abs(player.vx) > 0.5 && player.onGround) {
        player.animTime += dt;
        if (player.animTime > 8) {
          player.frame = (player.frame + 1) % 4;
          player.animTime = 0;
        }
      } else {
        player.frame = 0;
      }
    }

    function drawBackground(cameraX, cameraY) {
      // parallax hills
      ctx.fillStyle = "#7ec850";
      for (let i = 0; i < 10; i++) {
        const x = (i * 300 - cameraX * 0.3) % 1200 - 200;
        ctx.beginPath();
        ctx.ellipse(x + 150, 470, 180, 90, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      const clouds = [
        { x: 200, y: 80 }, { x: 650, y: 120 }, { x: 1200, y: 70 },
        { x: 1800, y: 100 }, { x: 2400, y: 60 }
      ];
      for (const c of clouds) {
        const x = c.x - cameraX * 0.5;
        const y = c.y;
        ctx.beginPath();
        ctx.arc(x, y, 22, 0, Math.PI * 2);
        ctx.arc(x + 24, y - 10, 28, 0, Math.PI * 2);
        ctx.arc(x + 52, y, 20, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawWorld(cameraX, cameraY) {
      ctx.save();
      ctx.translate(-cameraX, -cameraY);

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#8b6b3f";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // Stars
      for (const star of stars) {
        if (!star.collected) {
          ctx.save();
          ctx.translate(star.x, star.y);
          ctx.fillStyle = "#ffd54a";
          ctx.beginPath();
          for (let i = 0; i < 5; i++) {
            const a = (Math.PI * 2 * i) / 5 - Math.PI / 2;
            const r = i % 2 === 0 ? 14 : 6;
            const px = Math.cos(a) * r;
            const py = Math.sin(a) * r;
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
          }
          ctx.closePath();
          ctx.fill();
          ctx.restore();
        }
      }

      // Player
      const frameX = player.frame * 48;
      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y);
      if (player.facing === -1) {
        ctx.scale(-1, 1);
      }
      ctx.drawImage(spriteCanvas, frameX, 0, 48, 64, -24, 0, 48, 64);
      ctx.restore();

      ctx.restore();
    }

    let last = performance.now();
    let cameraX = 0;
    let cameraY = 0;

    function loop(now) {
      const dt = Math.min(2, (now - last) / 16.6667);
      last = now;

      updatePlayer(dt);

      cameraX = clamp(player.x + player.w / 2 - canvas.width / 2, 0, WORLD.width - canvas.width);
      cameraY = clamp(player.y + player.h / 2 - canvas.height / 2, 0, WORLD.height - canvas.height);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground(cameraX, cameraY);
      drawWorld(cameraX, cameraY);

      // HUD text
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(12, 12, 180, 50);
      ctx.fillStyle = "white";
      ctx.font = "18px sans-serif";
      ctx.fillText(`Score: ${score}/${stars.length}`, 24, 42);

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
