<body>
  <div id="hud">Coins: <span id="coins">0</span></div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const coinText = document.getElementById("coins");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", (e) => keys[e.key.toLowerCase()] = false);

    // --- World ---
    const world = {
      width: 3000,
      height: 1000
    };

    const gravity = 0.7;

    const platforms = [
      { x: 0, y: 900, w: 3000, h: 100 },   // ground
      { x: 200, y: 750, w: 200, h: 25 },
      { x: 500, y: 650, w: 180, h: 25 },
      { x: 820, y: 560, w: 220, h: 25 },
      { x: 1200, y: 700, w: 250, h: 25 },
      { x: 1600, y: 620, w: 220, h: 25 },
      { x: 1950, y: 520, w: 220, h: 25 },
      { x: 2350, y: 680, w: 250, h: 25 }
    ];

    const coins = [
      { x: 260, y: 710, r: 12, collected: false },
      { x: 560, y: 610, r: 12, collected: false },
      { x: 900, y: 520, r: 12, collected: false },
      { x: 1280, y: 660, r: 12, collected: false },
      { x: 1680, y: 580, r: 12, collected: false },
      { x: 2020, y: 480, r: 12, collected: false },
      { x: 2450, y: 640, r: 12, collected: false }
    ];

    const goal = { x: 2850, y: 820, w: 30, h: 80 };

    // --- Player ---
    const player = {
      x: 50,
      y: 800,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0,
      score: 0
    };

    // --- Collision helpers ---
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function circleRectCollision(circle, rect) {
      const cx = Math.max(rect.x, Math.min(circle.x, rect.x + rect.w));
      const cy = Math.max(rect.y, Math.min(circle.y, rect.y + rect.h));
      const dx = circle.x - cx;
      const dy = circle.y - cy;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    // --- Physics update ---
    function updatePlayer() {
      // Horizontal movement
      if (keys["a"] || keys["arrowleft"]) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (keys["d"] || keys["arrowright"]) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Clamp horizontal speed
      player.vx = Math.max(-6, Math.min(6, player.vx));

      // Jump
      if ((keys["w"] || keys["arrowup"] || keys[" "]) && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Apply gravity
      player.vy += gravity;

      // Apply friction
      player.vx *= player.onGround ? 0.80 : 0.95;

      // Move horizontally and resolve collisions
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Move vertically and resolve collisions
      player.y += player.vy;
      player.onGround = false;

      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep player in world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height) {
        resetPlayer();
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.5;
      if (moving && player.onGround) {
        player.animTime += 1;
        if (player.animTime > 8) {
          player.frame = (player.frame + 1) % 4;
          player.animTime = 0;
        }
      } else {
        player.frame = 0;
        player.animTime = 0;
      }

      // Coin collection
      for (const c of coins) {
        if (!c.collected && circleRectCollision(c, player)) {
          c.collected = true;
          player.score++;
          coinText.textContent = player.score;
        }
      }

      // Goal
      if (rectsOverlap(player, goal)) {
        alert("You reached the goal! Coins collected: " + player.score);
        resetGame();
      }
    }

    function resetPlayer() {
      player.x = 50;
      player.y = 800;
      player.vx = 0;
      player.vy = 0;
    }

    function resetGame() {
      resetPlayer();
      player.score = 0;
      coinText.textContent = "0";
      for (const c of coins) c.collected = false;
    }

    // --- Drawing ---
    function drawPlatform(p) {
      ctx.fillStyle = "#6b4f2a";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#8b6a3d";
      ctx.fillRect(p.x, p.y, p.w, 6);
    }

    function drawCoin(c) {
      if (c.collected) return;
      ctx.beginPath();
      ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
      ctx.fillStyle = "#ffd700";
      ctx.fill();
      ctx.strokeStyle = "#c9a400";
      ctx.stroke();
    }

    function drawGoal(g) {
      ctx.fillStyle = "#444";
      ctx.fillRect(g.x, g.y, 6, g.h);
      ctx.fillStyle = "#ff4d4d";
      ctx.beginPath();
      ctx.moveTo(g.x + 6, g.y + 10);
      ctx.lineTo(g.x + 40, g.y + 25);
      ctx.lineTo(g.x + 6, g.y + 40);
      ctx.closePath();
      ctx.fill();
    }

    // Simple sprite animation using shapes
    function drawPlayer(p) {
      ctx.save();
      ctx.translate(p.x + p.w / 2, p.y + p.h / 2);
      ctx.scale(p.facing, 1);

      const bob = p.onGround && Math.abs(p.vx) > 0.5 ? Math.sin(Date.now() * 0.02) * 2 : 0;

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(0, p.h / 2 + 8, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = "#2d6cdf";
      ctx.fillRect(-16, -18 + bob, 32, 34);

      // Head
      ctx.fillStyle = "#f2c9a0";
      ctx.beginPath();
      ctx.arc(0, -30 + bob, 14, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = "#111";
      ctx.beginPath();
      ctx.arc(5, -33 + bob, 2.5, 0, Math.PI * 2);
      ctx.arc(-3, -33 + bob, 2.5, 0, Math.PI * 2);
      ctx.fill();

      // Legs animation
      ctx.strokeStyle = "#222";
      ctx.lineWidth = 4;
      ctx.lineCap = "round";

      const legSwing = p.onGround && Math.abs(p.vx) > 0.5 ? Math.sin(p.frame * Math.PI / 2) * 8 : 0;

      ctx.beginPath();
      ctx.moveTo(-8, 16 + bob);
      ctx.lineTo(-12 + legSwing * 0.2, 30 + bob);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(8, 16 + bob);
      ctx.lineTo(12 - legSwing * 0.2, 30 + bob);
      ctx.stroke();

      // Arms
      ctx.beginPath();
      ctx.moveTo(-16, -5 + bob);
      ctx.lineTo(-28, 8 + bob);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(16, -5 + bob);
      ctx.lineTo(28, 8 + bob);
      ctx.stroke();

      ctx.restore();
    }

    // --- Camera ---
    function getCamera() {
      const camX = Math.max(0, Math.min(world.width - canvas.width, player.x - canvas.width / 2));
      const camY = Math.max(0, Math.min(world.height - canvas.height, player.y - canvas.height / 2));
      return { x: camX, y: camY };
    }

    // --- Game loop ---
    function update() {
      updatePlayer();
    }

    function render() {
      const cam = getCamera();

      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background hills
      ctx.save();
      ctx.translate(-cam.x * 0.3, -cam.y * 0.1);
      ctx.fillStyle = "#7ec850";
      ctx.beginPath();
      ctx.arc(300, 850, 220, 0, Math.PI * 2);
      ctx.arc(900, 860, 260, 0, Math.PI * 2);
      ctx.arc(1600, 840, 240, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();

      ctx.save();
      ctx.translate(-cam.x, -cam.y);

      // Platforms
      for (const p of platforms) drawPlatform(p);

      // Coins
      for (const c of coins) drawCoin(c);

      // Goal
      drawGoal(goal);

      // Player
      drawPlayer(player);

      ctx.restore();

      // UI
      ctx.fillStyle = "white";
      ctx.font = "18px Arial";
      ctx.fillText("Move: A/D or Arrow Keys | Jump: W / Up / Space", 10, canvas.height - 20);
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
