    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // --- World ---
    const world = {
      width: 3000,
      height: 1200
    };

    const gravity = 1800;
    const moveSpeed = 420;
    const jumpSpeed = 760;

    const platforms = [
      { x: 0, y: 1100, w: 3000, h: 100 },   // ground
      { x: 250, y: 900, w: 220, h: 30 },
      { x: 600, y: 780, w: 220, h: 30 },
      { x: 950, y: 650, w: 220, h: 30 },
      { x: 1300, y: 820, w: 260, h: 30 },
      { x: 1700, y: 700, w: 240, h: 30 },
      { x: 2050, y: 560, w: 220, h: 30 },
      { x: 2400, y: 760, w: 260, h: 30 },
      { x: 2700, y: 620, w: 180, h: 30 }
    ];

    // --- Player ---
    const player = {
      x: 100,
      y: 900,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle"
    };

    // --- Generate a simple sprite sheet ---
    // 4 frames: idle/run1/run2/jump
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 192;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawFrame(frameIndex, pose) {
      const ox = frameIndex * 48;
      sctx.clearRect(ox, 0, 48, 64);

      // body
      sctx.fillStyle = "#ffcc66";
      sctx.fillRect(ox + 16, 18, 16, 24);

      // head
      sctx.fillStyle = "#ffd9b3";
      sctx.beginPath();
      sctx.arc(ox + 24, 14, 10, 0, Math.PI * 2);
      sctx.fill();

      // eyes
      sctx.fillStyle = "#222";
      sctx.fillRect(ox + 20, 12, 2, 2);
      sctx.fillRect(ox + 26, 12, 2, 2);

      // legs/arms based on pose
      sctx.strokeStyle = "#333";
      sctx.lineWidth = 4;
      sctx.lineCap = "round";

      // arms
      sctx.beginPath();
      sctx.moveTo(ox + 16, 24);
      sctx.lineTo(ox + 8, 32);
      sctx.moveTo(ox + 32, 24);
      sctx.lineTo(ox + 40, 32);
      sctx.stroke();

      // legs
      sctx.beginPath();
      if (pose === "idle") {
        sctx.moveTo(ox + 20, 42);
        sctx.lineTo(ox + 18, 54);
        sctx.moveTo(ox + 28, 42);
        sctx.lineTo(ox + 30, 54);
      } else if (pose === "run1") {
        sctx.moveTo(ox + 20, 42);
        sctx.lineTo(ox + 14, 54);
        sctx.moveTo(ox + 28, 42);
        sctx.lineTo(ox + 34, 52);
      } else if (pose === "run2") {
        sctx.moveTo(ox + 20, 42);
        sctx.lineTo(ox + 14, 52);
        sctx.moveTo(ox + 28, 42);
        sctx.lineTo(ox + 34, 54);
      } else if (pose === "jump") {
        sctx.moveTo(ox + 20, 42);
        sctx.lineTo(ox + 16, 50);
        sctx.moveTo(ox + 28, 42);
        sctx.lineTo(ox + 32, 50);
      }
      sctx.stroke();
    }

    drawFrame(0, "idle");
    drawFrame(1, "run1");
    drawFrame(2, "run2");
    drawFrame(3, "jump");

    const sprite = new Image();
    sprite.src = spriteCanvas.toDataURL();

    // --- Collision helpers ---
    function aabbIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // X axis
      entity.x += entity.vx * dt;
      for (const p of solids) {
        if (aabbIntersect(entity, p)) {
          if (entity.vx > 0) entity.x = p.x - entity.w;
          else if (entity.vx < 0) entity.x = p.x + p.w;
          entity.vx = 0;
        }
      }

      // Y axis
      entity.y += entity.vy * dt;
      for (const p of solids) {
        if (aabbIntersect(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    // --- Game loop ---
    let last = performance.now();
    let dt = 0;

    function update(now) {
      dt = Math.min((now - last) / 1000, 1 / 30);
      last = now;

      // Input
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      player.vx = move * moveSpeed;
      if (move !== 0) player.facing = Math.sign(move);

      // Jump
      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround && !player._jumpLock) {
        player.vy = -jumpSpeed;
        player.onGround = false;
        player._jumpLock = true;
      }
      if (!jumpPressed) player._jumpLock = false;

      // Physics
      player.vy += gravity * dt;
      if (player.vy > 2000) player.vy = 2000;

      resolveCollisions(player, platforms);

      // Animation state
      player.animTime += dt;
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 1) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));

      draw();
      requestAnimationFrame(update);
    }

    function drawBackground() {
      // sky
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // distant hills
      ctx.save();
      ctx.translate(-camera.x * 0.3, 0);
      ctx.fillStyle = "#7ec850";
      for (let i = 0; i < 10; i++) {
        const x = i * 400;
        ctx.beginPath();
        ctx.ellipse(x + 200, canvas.height - 120, 180, 80, 0, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();
    }

    function draw() {
      drawBackground();

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5b4636";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7a5c45";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // player animation frame selection
      let frame = 0;
      if (player.state === "idle") frame = 0;
      else if (player.state === "run") frame = Math.floor(player.animTime * 10) % 2 ? 1 : 2;
      else if (player.state === "jump") frame = 3;

      // draw player with facing flip
      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.drawImage(
        sprite,
        frame * 48, 0, 48, 64,
        -player.w / 2, -player.h / 2, player.w, player.h
      );
      ctx.restore();

      // world bounds outline
      ctx.strokeStyle = "rgba(0,0,0,0.15)";
      ctx.strokeRect(0, 0, world.width, world.height);

      ctx.restore();

      // debug info
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, canvas.height - 50, 220, 40);
      ctx.fillStyle = "white";
      ctx.fillText(`x: ${player.x.toFixed(0)} y: ${player.y.toFixed(0)}`, 20, canvas.height - 25);
    }

    requestAnimationFrame(update);
  </script>
</body>
</html>
