      { x: 1000, y: 650, w: 260, h: 30 },
      { x: 1450, y: 820, w: 280, h: 30 },
      { x: 1900, y: 720, w: 240, h: 30 },
      { x: 2300, y: 580, w: 260, h: 30 },
      { x: 2750, y: 760, w: 300, h: 30 },
      { x: 3250, y: 640, w: 260, h: 30 }
    ];

    const coins = [
      { x: 320, y: 850, r: 12, collected: false },
      { x: 720, y: 730, r: 12, collected: false },
      { x: 1080, y: 600, r: 12, collected: false },
      { x: 1540, y: 770, r: 12, collected: false },
      { x: 1980, y: 670, r: 12, collected: false },
      { x: 2380, y: 530, r: 12, collected: false },
