      x: 100,
      y: 900,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      speed: 420,
      jumpPower: 760,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0,
      score: 0
    };

    // --- Sprite sheet generation (procedural) ---
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 192;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawPlayerFrame(frameIndex) {
      const x = frameIndex * 48;
      sctx.clearRect(x, 0, 48, 64);

      // body
      sctx.fillStyle = "#2b2d42";
      sctx.fillRect(x + 16, 20, 16, 24);

      // head
      sctx.fillStyle = "#f2c14e";
      sctx.fillRect(x + 14, 8, 20, 16);

      // eyes
      sctx.fillStyle = "#000";
      sctx.fillRect(x + 19, 13, 3, 3);
      sctx.fillRect(x + 26, 13, 3, 3);

      // arms
      sctx.fillStyle = "#f2c14e";
      sctx.fillRect(x + 10, 22, 6, 4);
      sctx.fillRect(x + 32, 22, 6, 4);

      // legs vary by frame
      sctx.fillStyle = "#3a86ff";
      if (frameIndex === 0) {
        sctx.fillRect(x + 16, 44, 6, 12);
        sctx.fillRect(x + 26, 44, 6, 12);
      } else if (frameIndex === 1) {
        sctx.fillRect(x + 14, 44, 6, 12);
        sctx.fillRect(x + 28, 44, 6, 12);
      } else if (frameIndex === 2) {
        sctx.fillRect(x + 16, 44, 6, 12);
        sctx.fillRect(x + 24, 44, 6, 12);
      } else {
        sctx.fillRect(x + 18, 44, 6, 12);
        sctx.fillRect(x + 22, 44, 6, 12);
