      }

      // Keep inside world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height) {
        player.x = 100;
        player.y = 900;
        player.vx = 0;
        player.vy = 0;
      }

      // Coins
      for (const coin of coins) {
        if (!coin.collected && circleRectCollision(coin, player)) {
