        }
      }

      // Animation
      if (!player.onGround) {
        player.frame = 3; // jump frame
      } else if (Math.abs(player.vx) > 10) {
        player.animTime += dt * 12;
        player.frame = Math.floor(player.animTime) % 3;
      } else {
        player.frame = 0;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Camera
      const cameraX = Math.max(0, Math.min(world.width - canvas.width, player.x + player.w / 2 - canvas.width / 2));
      const cameraY = Math.max(0, Math.min(world.height - canvas.height, player.y + player.h / 2 - canvas.height / 2));

      ctx.save();
      ctx.translate(-cameraX, -cameraY);

      // Parallax clouds
      ctx.fillStyle = "rgba(255,255,255,0.5)";
      for (let i = 0; i < 10; i++) {
        const cx = (i * 420 + (cameraX * 0.3)) % (world.width + 500) - 200;
        const cy = 100 + (i % 3) * 60;
        ctx.beginPath();
        ctx.arc(cx, cy, 30, 0, Math.PI * 2);
        ctx.arc(cx + 30, cy - 10, 40, 0, Math.PI * 2);
        ctx.arc(cx + 60, cy, 28, 0, Math.PI * 2);
        ctx.fill();
      }

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5a3e2b";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7a5c45";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // Coins
      for (const coin of coins) {
        if (coin.collected) continue;
        ctx.beginPath();
        ctx.fillStyle = "#ffd700";
        ctx.arc(coin.x, coin.y, coin.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#b8860b";
        ctx.lineWidth = 3;
        ctx.stroke();
