      // Goal
      ctx.fillStyle = "#2ecc71";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#145a32";
      ctx.fillRect(goal.x + 10, goal.y + 10, 40, 20);

      // Player sprite
      const sx = player.frame * 48;
      const sy = 0;
      ctx.save();
      if (player.facing === -1) {
        ctx.translate(player.x + player.w, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(spriteCanvas, sx, sy, 48, 64, 0, 0, player.w, player.h);
      } else {
