        sctx.fillRect(xOffset + 26, 46, 8, 14);
      } else {
        sctx.fillRect(xOffset + 14, 46, 8, 12);
        sctx.fillRect(xOffset + 26, 46, 8, 12);
      }

      // arms
      sctx.fillStyle = "#f2c9a0";
      sctx.fillRect(xOffset + 8, 22, 6, 16);
      sctx.fillRect(xOffset + 34, 22, 6, 16);
    }

    drawPlayerFrame(0, 0);
    drawPlayerFrame(1, 48);
    drawPlayerFrame(2, 96);
    drawPlayerFrame(0, 144);

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function circleRectCollision(circle, rect) {
      const cx = Math.max(rect.x, Math.min(circle.x, rect.x + rect.w));
      const cy = Math.max(rect.y, Math.min(circle.y, rect.y + rect.h));
      const dx = circle.x - cx;
      const dy = circle.y - cy;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    let camera = { x: 0, y: 0 };

    function update(dt) {
      // Input
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      player.vx = move * player.speed;
      if (move !== 0) player.facing = move;

      const jumpPressed = keys["w"] || keys[" "] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity * dt;
      player.x += player.vx * dt;
      player.y += player.vy * dt;

      // Horizontal bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > world.width) player.x = world.width - player.w;

      // Collision with platforms
      player.onGround = false;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          const prevX = player.x - player.vx * dt;
          const prevY = player.y - player.vy * dt;

          // Resolve from top/bottom
          if (prevY + player.h <= p.y) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (prevY >= p.y + p.h) {
            player.y = p.y + p.h;
            player.vy = 0;
          } else if (prevX + player.w <= p.x) {
            player.x = p.x - player.w;
          } else if (prevX >= p.x + p.w) {
            player.x = p.x + p.w;
          }
        }
      }

      // Collect coins
      for (const coin of coins) {
        if (!coin.taken && circleRectCollision(coin, player)) {
          coin.taken = true;
          player.collected++;
        }
      }

      // Animation
      if (Math.abs(player.vx) > 0 && player.onGround) {
        player.frameTimer += dt;
        if (player.frameTimer >= player.frameRate) {
          player.frameTimer = 0;
          player.frame = (player.frame + 1) % 3;
        }
      } else {
        player.frame = 0;
      }

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background parallax hills
      ctx.save();
      ctx.translate(-camera.x * 0.3, -camera.y * 0.1);
      ctx.fillStyle = "#7ec850";
      for (let i = 0; i < 10; i++) {
        ctx.beginPath();
        ctx.arc(i * 350 + 100, 520, 180, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.restore();

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = p.h > 40 ? "#5c4033" : "#8d6e63";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "rgba(255,255,255,0.15)";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // Coins
      for (const coin of coins) {
        if (coin.taken) continue;
        ctx.beginPath();
        ctx.fillStyle = "#ffd700";
        ctx.arc(coin.x, coin.y, coin.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#c9a400";
        ctx.stroke();
      }

      // Goal
      ctx.fillStyle = "#ff4d6d";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#fff";
      ctx.fillRect(goal.x + 10, goal.y + 10, 20, 20);

      // Player sprite
      const sx = player.frame * 48;
      const sy = 0;
      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y);
      ctx.scale(player.facing, 1);
      ctx.drawImage(spriteCanvas, sx, sy, 48, 64, -player.w / 2, 0, player.w, player.h);
      ctx.restore();

      ctx.restore();

      // UI
      ctx.fillStyle = "white";
      ctx.font = "20px sans-serif";
      ctx.fillText(`Coins: ${player.collected}/${coins.length}`, 20, 40);

      const allCollected = coins.every(c => c.taken);
      if (allCollected && rectsIntersect(player, goal)) {
        ctx.fillStyle = "rgba(0,0,0,0.6)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "48px sans-serif";
        ctx.fillText("You Win!", canvas.width / 2 - 110, canvas.height / 2);
        ctx.font = "24px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2 - 110, canvas.height / 2 + 40);
      }
    }

    let lastTime = performance.now();
    function loop(now) {
      const dt = Math.min((now - lastTime) / 1000, 0.033);
      lastTime = now;
      update(dt);
      draw();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

