      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 16px;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      z-index: 10;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    <div>Move: A/D or Arrow Keys</div>
    <div>Jump: W / Space / Up</div>
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // -----------------------------
    // Input
    // -----------------------------
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
      if (["arrowup", " ", "w"].includes(e.key.toLowerCase())) e.preventDefault();
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // -----------------------------
    // World / Physics
    // -----------------------------
    const GRAVITY = 2200;
    const MOVE_SPEED = 420;
    const JUMP_FORCE = 850;
    const FRICTION = 0.82;

    const world = {
      width: 4000,
      height: 1200
    };

    const platforms = [
      { x: 0, y: 1100, w: 4000, h: 100 }, // ground
      { x: 250, y: 900, w: 250, h: 30 },
      { x: 650, y: 780, w: 220, h: 30 },
      { x: 1000, y: 650, w: 260, h: 30 },
      { x: 1450, y: 820, w: 300, h: 30 },
      { x: 1900, y: 700, w: 220, h: 30 },
      { x: 2300, y: 560, w: 260, h: 30 },
      { x: 2750, y: 760, w: 280, h: 30 },
      { x: 3200, y: 640, w: 260, h: 30 },
      { x: 3600, y: 850, w: 250, h: 30 }
    ];

    const coins = [
      { x: 330, y: 850, r: 12, collected: false },
      { x: 720, y: 730, r: 12, collected: false },
      { x: 1120, y: 600, r: 12, collected: false },
      { x: 1560, y: 770, r: 12, collected: false },
      { x: 2010, y: 650, r: 12, collected: false },
      { x: 2400, y: 510, r: 12, collected: false },
      { x: 2870, y: 710, r: 12, collected: false },
      { x: 3320, y: 590, r: 12, collected: false }
    ];

    // -----------------------------
    // Player
    // -----------------------------
    const player = {
      x: 100,
      y: 900,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      score: 0,
      animTime: 0,
      state: "idle"
    };

    // -----------------------------
    // Sprite Sheet Animation
    // Replace with your own sprite sheet if desired.
    // This demo uses a simple generated sprite sheet-like drawing.
    // -----------------------------
    const sprite = {
      frameWidth: 48,
      frameHeight: 64,
      frames: {
        idle: 4,
        run: 6,
        jump: 2
      }
    };

    function drawPlayer(ctx, p, cameraX, cameraY) {
      const x = p.x - cameraX;
      const y = p.y - cameraY;

      // Determine animation state
      let state = "idle";
      if (!p.onGround) state = "jump";
      else if (Math.abs(p.vx) > 20) state = "run";

      const frameCount = sprite.frames[state];
      const frame = Math.floor(p.animTime * 12) % frameCount;

      ctx.save();
      ctx.translate(x + p.w / 2, y + p.h / 2);

      // Flip based on facing direction
      ctx.scale(p.facing, 1);

      // Body shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(0, p.h / 2 - 4, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Draw a simple animated character
      // You can replace this with actual sprite sheet rendering:
      // ctx.drawImage(spriteSheet, sx, sy, sw, sh, dx, dy, dw, dh);

      // Head
      ctx.fillStyle = "#ffd6b0";
      ctx.beginPath();
      ctx.arc(0, -18, 14, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = "#4b7bec";
      ctx.fillRect(-14, -4, 28, 28);

      // Legs animation
      ctx.strokeStyle = "#2d3436";
      ctx.lineWidth = 5;
      ctx.lineCap = "round";

      const legSwing = state === "run" ? Math.sin(frame / frameCount * Math.PI * 2) * 8 : 0;
      const jumpLeg = state === "jump" ? 4 : 0;

      ctx.beginPath();
      ctx.moveTo(-8, 24);
      ctx.lineTo(-10 + legSwing, 40 + jumpLeg);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(8, 24);
      ctx.lineTo(10 - legSwing, 40 + jumpLeg);
      ctx.stroke();

      // Arms
      ctx.beginPath();
      ctx.moveTo(-14, 4);
      ctx.lineTo(-24, 16);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(14, 4);
      ctx.lineTo(24, 16);
      ctx.stroke();

      // Face
      ctx.fillStyle = "#2d3436";
      ctx.beginPath();
      ctx.arc(-5, -20, 2.5, 0, Math.PI * 2);
      ctx.arc(5, -20, 2.5, 0, Math.PI * 2);
      ctx.fill();

      ctx.restore();
    }

    // -----------------------------
    // Collision Helpers
    // -----------------------------
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolvePlatformCollision(entity, platform) {
      const prevBottom = entity.prevY + entity.h;
      const prevTop = entity.prevY;
      const prevRight = entity.prevX + entity.w;
      const prevLeft = entity.prevX;

      const currBottom = entity.y + entity.h;
      const currTop = entity.y;
      const currRight = entity.x + entity.w;
      const currLeft = entity.x;

      // Landing on top
      if (prevBottom <= platform.y && currBottom >= platform.y) {
        entity.y = platform.y - entity.h;
        entity.vy = 0;
        entity.onGround = true;
        return;
      }

      // Hitting from below
      if (prevTop >= platform.y + platform.h && currTop <= platform.y + platform.h) {
        entity.y = platform.y + platform.h;
        entity.vy = 0;
        return;
      }

      // Hitting from left
      if (prevRight <= platform.x && currRight >= platform.x) {
        entity.x = platform.x - entity.w;
        entity.vx = 0;
        return;
      }

      // Hitting from right
      if (prevLeft >= platform.x + platform.w && currLeft <= platform.x + platform.w) {
        entity.x = platform.x + platform.w;
        entity.vx = 0;
        return;
      }
    }

    // -----------------------------
    // Game Loop
    // -----------------------------
    let lastTime = 0;
    const camera = { x: 0, y: 0 };

    function update(dt) {
      player.prevX = player.x;
      player.prevY = player.y;
      player.onGround = false;

      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx = -MOVE_SPEED;
        player.facing = -1;
      } else if (right) {
        player.vx = MOVE_SPEED;
        player.facing = 1;
      } else {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      if (jump && player.onGround) {
        player.vy = -JUMP_FORCE;
      }

      // Physics
      player.vy += GRAVITY * dt;
      player.x += player.vx * dt;
      player.y += player.vy * dt;

      // World bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > world.width) {
        player.x = world.width - player.w;
        player.vx = 0;
      }
      if (player.y > world.height) {
        player.y = 900;
        player.x = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Platform collisions
      for (const platform of platforms) {
        const playerBox = { x: player.x, y: player.y, w: player.w, h: player.h };
        if (rectsOverlap(playerBox, platform)) {
          resolvePlatformCollision(player, platform);
        }
      }

      // Coins
      for (const coin of coins) {
        if (coin.collected) continue;
        const dx = (player.x + player.w / 2) - coin.x;
        const dy = (player.y + player.h / 2) - coin.y;
        const dist = Math.hypot(dx, dy);
        if (dist < coin.r + 24) {
          coin.collected = true;
          player.score += 1;
        }
      }

      // Animation timer
      player.animTime += dt;

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function drawBackground() {
      // Parallax hills
      ctx.fillStyle = "#7ec850";
      for (let i = 0; i < 20; i++) {
        const x = (i * 300 - camera.x * 0.3) % (world.width + 300) - 300;
        ctx.beginPath();
        ctx.arc(x + 150, 980 - camera.y * 0.1, 180, Math.PI, 0);
        ctx.fill();
      }

      // Clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      for (let i = 0; i < 12; i++) {
        const x = (i * 420 - camera.x * 0.15) % (world.width + 420) - 420;
        const y = 100 + (i % 4) * 60;
        ctx.beginPath();
        ctx.ellipse(x + 100, y, 40, 20, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 130, y - 10, 50, 25, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 160, y, 40, 20, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawPlatform(platform) {
      ctx.fillStyle = "#5d4037";
      ctx.fillRect(platform.x - camera.x, platform.y - camera.y, platform.w, platform.h);

      ctx.fillStyle = "#8d6e63";
      ctx.fillRect(platform.x - camera.x, platform.y - camera.y, platform.w, 8);
    }

    function drawCoin(coin) {
      if (coin.collected) return;
      const x = coin.x - camera.x;
      const y = coin.y - camera.y;

      ctx.save();
      ctx.translate(x, y);
      ctx.fillStyle = "#ffd700";
      ctx.beginPath();
      ctx.arc(0, 0, coin.r, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = "#ffec8b";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, coin.r - 4, 0, Math.PI * 2);
      ctx.stroke();

      ctx.restore();
    }

    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, 10, 160, 50);
      ctx.fillStyle = "white";
      ctx.font = "18px sans-serif";
      ctx.fillText(`Coins: ${player.score}`, 20, 40);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // Platforms
      for (const platform of platforms) drawPlatform(platform);

      // Coins
      for (const coin of coins) drawCoin(coin);

      // Player
      drawPlayer(ctx, player, camera.x, camera.y);

      // HUD
      drawHUD();
    }

    function loop(timestamp) {
      const dt = Math.min((timestamp - lastTime) / 1000, 0.033);
      lastTime = timestamp;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
