    // -----------------------------
    // Player
    // -----------------------------
    const player = {
      x: 80,
      y: 500,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle",
      lives: 3,
    };

    let score = 0;
    let cameraX = 0;
    let cameraY = 0;

    // -----------------------------
    // Sprite sheet generation
    // -----------------------------
    // We generate a simple sprite sheet on an offscreen canvas.
    const spriteSheet = document.createElement("canvas");
    spriteSheet.width = 192; // 4 frames * 48
    spriteSheet.height = 64;
    const sctx = spriteSheet.getContext("2d");

    function drawPlayerFrame(frameIndex) {
      const x = frameIndex * 48;
      const y = 0;

      sctx.clearRect(x, y, 48, 64);

      // body
      sctx.fillStyle = "#ffcc66";
      sctx.fillRect(x + 14, y + 18, 20, 24);

      // head
      sctx.fillStyle = "#ffd9b3";
      sctx.fillRect(x + 13, y + 4, 22, 18);

      // eyes
      sctx.fillStyle = "#222";
      sctx.fillRect(x + 18, y + 10, 3, 3);
      sctx.fillRect(x + 27, y + 10, 3, 3);

      // legs/arms based on frame
      sctx.fillStyle = "#2d5bff";
      if (frameIndex === 0) {
        sctx.fillRect(x + 12, y + 42, 8, 16);
        sctx.fillRect(x + 28, y + 42, 8, 16);
      } else if (frameIndex === 1) {
        sctx.fillRect(x + 10, y + 42, 8, 16);
        sctx.fillRect(x + 30, y + 42, 8, 16);
      } else if (frameIndex === 2) {
        sctx.fillRect(x + 12, y + 42, 8, 16);
        sctx.fillRect(x + 28, y + 42, 8, 16);
      } else {
        sctx.fillRect(x + 10, y + 42, 8, 16);
        sctx.fillRect(x + 30, y + 42, 8, 16);
      }

      // small outline
      sctx.strokeStyle = "#000";
      sctx.strokeRect(x + 13, y + 4, 22, 18);
      sctx.strokeRect(x + 14, y + 18, 20, 24);
    }

    for (let i = 0; i < 4; i++) drawPlayerFrame(i);

    // -----------------------------
    // Collision resolution
    // -----------------------------
    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // X axis
      entity.x += entity.vx * dt;
      for (const p of solids) {
        if (rectsOverlap(entity, p)) {
          if (entity.vx > 0) entity.x = p.x - entity.w;
          else if (entity.vx < 0) entity.x = p.x + p.w;
          entity.vx = 0;
        }
      }

      // Y axis
      entity.y += entity.vy * dt;
      for (const p of solids) {
        if (rectsOverlap(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    // -----------------------------
    // Game loop
    // -----------------------------
    let last = performance.now();
    let dt = 0;

    function update(delta) {
      dt = delta;

      // Player input
      let move = 0;
      if (keys["ArrowLeft"] || keys["KeyA"]) move -= 1;
      if (keys["ArrowRight"] || keys["KeyD"]) move += 1;

      if (move !== 0) player.facing = move;

      // Horizontal movement
      player.vx += move * MOVE_SPEED * dt * 6;
      if (move === 0 && player.onGround) {
        player.vx *= Math.pow(FRICTION, dt * 60);
      }
      player.vx = clamp(player.vx, -MOVE_SPEED, MOVE_SPEED);

      // Jump
      if ((keys["Space"] || keys["ArrowUp"] || keys["KeyW"]) && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY * dt;
      player.vy = clamp(player.vy, -99999, MAX_FALL_SPEED);

      // Move and collide
      resolveCollisions(player, platforms);

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 20) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;

      // Coins
      for (const c of coins) {
        if (!c.collected) {
          const coinBox = { x: c.x - c.r, y: c.y - c.r, w: c.r * 2, h: c.r * 2 };
          if (rectsOverlap(player, coinBox)) {
            c.collected = true;
            score++;
            coinText.textContent = score;
          }
        }
      }

      // Enemies
      for (const e of enemies) {
        e.x += e.vx * dt;
        if (e.x < e.minX) {
          e.x = e.minX;
          e.vx *= -1;
        }
        if (e.x > e.maxX) {
          e.x = e.maxX;
          e.vx *= -1;
        }

        if (rectsOverlap(player, e)) {
          // simple damage/reset
          player.lives--;
          resetPlayer();
          if (player.lives <= 0) {
            alert("Game Over! Refresh to play again.");
            player.lives = 3;
            score = 0;
            coinText.textContent = score;
            for (const c of coins) c.collected = false;
            resetPlayer();
          }
          break;
        }
      }

      // Camera follow
      cameraX = player.x + player.w / 2 - canvas.width / 2;
      cameraY = player.y + player.h / 2 - canvas.height / 2;
      cameraX = clamp(cameraX, -250, 2000 - canvas.width + 250);
      cameraY = clamp(cameraY, -100, 800 - canvas.height + 100);
    }

    function resetPlayer() {
      player.x = 80;
      player.y = 500;
      player.vx = 0;
      player.vy = 0;
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      ctx.save();
      ctx.translate(-cameraX, -cameraY);

      // Background parallax hills
      drawBackground();

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5c4b3a";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7d6a55";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // Coins
      for (const c of coins) {
        if (c.collected) continue;
        ctx.beginPath();
        ctx.fillStyle = "#ffd700";
        ctx.arc(c.x, c.y, c.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#b8860b";
        ctx.stroke();
      }

      // Enemies
      for (const e of enemies) {
        ctx.fillStyle = "#e74c3c";
        ctx.fillRect(e.x, e.y, e.w, e.h);
        ctx.fillStyle = "#fff";
        ctx.fillRect(e.x + 8, e.y + 10, 6, 6);
        ctx.fillRect(e.x + 26, e.y + 10, 6, 6);
      }

      // Player sprite animation
      let frame = 0;
      if (player.state === "idle") {
        frame = 0;
      } else if (player.state === "run") {
        frame = Math.floor(player.animTime * 12) % 4;
      } else if (player.state === "jump") {
        frame = 2;
      }

      ctx.save();
      if (player.facing === -1) {
        ctx.translate(player.x + player.w / 2, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(spriteSheet, frame * 48, 0, 48, 64, -24, 0, 48, 64);
      } else {
        ctx.drawImage(spriteSheet, frame * 48, 0, 48, 64, player.x, player.y, 48, 64);
      }
      ctx.restore();

      ctx.restore();

      // HUD lives
      ctx.fillStyle = "white";
      ctx.font = "18px sans-serif";
      ctx.fillText("Lives: " + player.lives, 10, 40);
    }

    function drawBackground() {
      // distant mountains
      ctx.fillStyle = "#7aa0b8";
      for (let i = -1; i < 8; i++) {
        const baseX = i * 400 + (cameraX * 0.2);
        ctx.beginPath();
        ctx.moveTo(baseX, 700);
        ctx.lineTo(baseX + 100, 520);
        ctx.lineTo(baseX + 200, 700);
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 6; i++) {
        const x = (i * 350 + (cameraX * 0.5)) % 2500 - 200;
        const y = 80 + (i % 3) * 60;
        drawCloud(x, y, 1 + (i % 2) * 0.3);
      }
    }

    function drawCloud(x, y, s) {
      ctx.beginPath();
      ctx.arc(x, y, 20 * s, 0, Math.PI * 2);
      ctx.arc(x + 22 * s, y - 10 * s, 26 * s, 0, Math.PI * 2);
      ctx.arc(x + 48 * s, y, 20 * s, 0, Math.PI * 2);
      ctx.arc(x + 24 * s, y + 8 * s, 24 * s, 0, Math.PI * 2);
      ctx.fill();
    }

    function loop(now) {
      const delta = Math.min((now - last) / 1000, 1 / 30);
      last = now;
      update(delta);
      draw();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

