```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #cfefff);
    }
    #hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 18px;
      text-shadow: 2px 2px 0 #000;
      user-select: none;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="hud">Coins: <span id="coins">0</span> | Use Arrow Keys / A-D to move, Space to jump</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const coinText = document.getElementById("coins");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      width: 3000,
      height: 1200
    };

    const gravity = 0.7;

    const player = {
      x: 100,
      y: 500,
      w: 40,
      h: 56,
      vx: 0,
      vy: 0,
      speed: 0.7,
      maxSpeed: 6,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      frame: 0,
      frameTimer: 0,
      coins: 0,
      alive: true
    };

    const platforms = [
      { x: 0, y: 1100, w: 3000, h: 100 },
      { x: 200, y: 900, w: 250, h: 30 },
      { x: 550, y: 780, w: 220, h: 30 },
      { x: 900, y: 680, w: 220, h: 30 },
      { x: 1250, y: 820, w: 280, h: 30 },
      { x: 1650, y: 720, w: 220, h: 30 },
      { x: 1950, y: 600, w: 220, h: 30 },
      { x: 2300, y: 760, w: 260, h: 30 },
      { x: 2600, y: 900, w: 220, h: 30 }
    ];

    const coins = [
      { x: 260, y: 850, r: 12, collected: false },
      { x: 620, y: 730, r: 12, collected: false },
      { x: 970, y: 630, r: 12, collected: false },
      { x: 1360, y: 770, r: 12, collected: false },
      { x: 1730, y: 670, r: 12, collected: false },
      { x: 2040, y: 550, r: 12, collected: false },
      { x: 2400, y: 710, r: 12, collected: false },
      { x: 2700, y: 850, r: 12, collected: false }
    ];

    const enemies = [
      { x: 650, y: 740, w: 40, h: 40, vx: 1.2, minX: 560, maxX: 740, alive: true },
      { x: 1700, y: 680, w: 40, h: 40, vx: 1.5, minX: 1660, maxX: 1840, alive: true },
      { x: 2350, y: 720, w: 40, h: 40, vx: 1.3, minX: 2320, maxX: 2520, alive: true }
    ];

    let camera = { x: 0, y: 0 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // Horizontal
      entity.x += entity.vx;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vx > 0) entity.x = s.x - entity.w;
          else if (entity.vx < 0) entity.x = s.x + s.w;
          entity.vx = 0;
        }
      }

      // Vertical
      entity.y += entity.vy;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    function updatePlayer() {
      if (!player.alive) return;

      const left = keys["arrowleft"] || keys["a"];
      const right = keys["arrowright"] || keys["d"];
      const jump = keys[" "] || keys["space"] || keys["arrowup"] || keys["w"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (!left && !right) {
        player.vx *= 0.82; // friction
      }

      player.vx = Math.max(-player.maxSpeed, Math.min(player.maxSpeed, player.vx));

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      player.vy += gravity;
      if (player.vy > 18) player.vy = 18;

      resolveCollisions(player, platforms);

      // Keep player in world bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > world.width) player.x = world.width - player.w;
      if (player.y > world.height + 200) {
        // respawn
        player.x = 100;
        player.y = 500;
        player.vx = 0;
        player.vy = 0;
      }

      // Coin collection
      for (const c of coins) {
        if (!c.collected) {
          const dx = (player.x + player.w / 2) - c.x;
          const dy = (player.y + player.h / 2) - c.y;
          if (Math.hypot(dx, dy) < 32) {
            c.collected = true;
            player.coins++;
            coinText.textContent = player.coins;
          }
        }
      }

      // Enemy collision
      for (const e of enemies) {
        if (!e.alive) continue;
        if (rectsOverlap(player, e)) {
          const playerBottomPrev = player.y + player.h - player.vy;
          const enemyTop = e.y;
          if (player.vy > 0 && playerBottomPrev <= enemyTop + 10) {
            // stomp enemy
            e.alive = false;
            player.vy = -10;
          } else {
            // hurt player: respawn
            player.x = 100;
            player.y = 500;
            player.vx = 0;
            player.vy = 0;
          }
        }
      }

      // Animation
      if (Math.abs(player.vx) > 0.5 && player.onGround) {
        player.frameTimer++;
        if (player.frameTimer > 8) {
          player.frame = (player.frame + 1) % 4;
          player.frameTimer = 0;
        }
      } else {
        player.frame = 0;
      }
    }

    function updateEnemies() {
      for (const e of enemies) {
        if (!e.alive) continue;
        e.x += e.vx;
        if (e.x < e.minX) {
          e.x = e.minX;
          e.vx *= -1;
        }
        if (e.x + e.w > e.maxX) {
          e.x = e.maxX - e.w;
          e.vx *= -1;
        }

        // simple gravity
        e.vy = (e.vy || 0) + gravity;
        if (e.vy > 16) e.vy = 16;
        resolveCollisions(e, platforms);
      }
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#5b4636";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
      ctx.fillStyle = "#7c5c45";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
    }

    function drawCoin(c) {
      if (c.collected) return;
      const x = c.x - camera.x;
      const y = c.y - camera.y;
      ctx.beginPath();
      ctx.arc(x, y, c.r, 0, Math.PI * 2);
      ctx.fillStyle = "#ffd54a";
      ctx.fill();
      ctx.strokeStyle = "#c99b00";
      ctx.lineWidth = 3;
      ctx.stroke();
    }

    function drawEnemy(e) {
      if (!e.alive) return;
      const x = e.x - camera.x;
      const y = e.y - camera.y;

      ctx.fillStyle = "#8b0000";
      ctx.fillRect(x, y, e.w, e.h);
      ctx.fillStyle = "#fff";
      ctx.fillRect(x + 8, y + 10, 8, 8);
      ctx.fillRect(x + 24, y + 10, 8, 8);
      ctx.fillStyle = "#000";
      ctx.fillRect(x + 11, y + 13, 3, 3);
      ctx.fillRect(x + 27, y + 13, 3, 3);
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // simple animated sprite-style drawing
      const bob = player.onGround ? Math.sin(player.frame * 0.8) * 1.5 : 0;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2 + bob);
      ctx.scale(player.facing, 1);

      // body
      ctx.fillStyle = "#2d6cdf";
      ctx.fillRect(-18, -18, 36, 34);

      // head
      ctx.fillStyle = "#f2c9a0";
      ctx.fillRect(-14, -34, 28, 18);

      // eyes
      ctx.fillStyle = "#000";
      ctx.fillRect(2, -28, 4, 4);
      ctx.fillRect(8, -28, 4, 4);

      // legs animation
      ctx.fillStyle = "#1b3f8b";
      if (player.onGround && Math.abs(player.vx) > 0.5) {
        const legOffset = player.frame % 2 === 0 ? 4 : -4;
        ctx.fillRect(-14, 16, 10, 18);
        ctx.fillRect(4, 16 + legOffset, 10, 18);
      } else {
        ctx.fillRect(-14, 16, 10, 18);
        ctx.fillRect(4, 16, 10, 18);
      }

      // arms
      ctx.fillStyle = "#f2c9a0";
      ctx.fillRect(-24, -12, 8, 18);
      ctx.fillRect(16, -12, 8, 18);

      ctx.restore();
    }

    function drawBackground() {
      // parallax hills
      ctx.fillStyle = "#6bbf59";
      for (let i = 0; i < 10; i++) {
        const hx = (i * 400 - (camera.x * 0.3) % 400) - 100;
        ctx.beginPath();
        ctx.arc(hx, canvas.height - 80, 140, Math.PI, 0);
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      for (let i = 0; i < 8; i++) {
        const cx = (i * 350 - (camera.x * 0.15) % 350) + 50;
        const cy = 80 + (i % 3) * 40;
        ctx.beginPath();
        ctx.arc(cx, cy, 25, 0, Math.PI * 2);
        ctx.arc(cx + 25, cy + 10, 30, 0, Math.PI * 2);
        ctx.arc(cx + 55, cy, 22, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // visible platforms
      for (const p of platforms) drawPlatform(p);
      for (const c of coins) drawCoin(c);
      for (const e of enemies) drawEnemy(e);
      drawPlayer();

      // world border indicator
      ctx.strokeStyle = "rgba(0,0,0,0.2)";
      ctx.strokeRect(-camera.x, -camera.y, world.width, world.height);
    }

    function loop() {
      updatePlayer();
      updateEnemies();
      updateCamera();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
