  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", (e) => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", (e) => keys[e.key.toLowerCase()] = false);

    const world = {
      width: 3000,
      height: 1200
    };

    const gravity = 0.7;
    const friction = 0.82;

    const player = {
      x: 100,
      y: 300,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      speed: 0.8,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      animTime: 0,
      animFrame: 0
    };

    const platforms = [
      { x: 0, y: 1100, w: 3000, h: 100 },
      { x: 200, y: 900, w: 220, h: 24 },
      { x: 500, y: 780, w: 220, h: 24 },
      { x: 860, y: 680, w: 220, h: 24 },
      { x: 1200, y: 600, w: 220, h: 24 },
      { x: 1550, y: 720, w: 260, h: 24 },
      { x: 1900, y: 850, w: 240, h: 24 },
      { x: 2250, y: 740, w: 220, h: 24 },
      { x: 2550, y: 620, w: 220, h: 24 }
    ];

    const coins = [
      { x: 250, y: 850, collected: false },
      { x: 560, y: 730, collected: false },
      { x: 920, y: 630, collected: false },
      { x: 1260, y: 550, collected: false },
      { x: 1640, y: 670, collected: false },
      { x: 1980, y: 800, collected: false },
      { x: 2320, y: 690, collected: false },
      { x: 2620, y: 570, collected: false }
    ];

    let score = 0;

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      player.vy += gravity;

      player.x += player.vx;
      collideX();

      player.y += player.vy;
      player.onGround = false;
      collideY();

      player.vx *= friction;

      // Clamp to world bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height) {
        player.x = 100;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.5;
      if (moving && player.onGround) {
        player.animTime += 1;
        if (player.animTime > 8) {
          player.animTime = 0;
          player.animFrame = (player.animFrame + 1) % 4;
        }
      } else {
        player.animFrame = 0;
      }

      // Coin collection
      for (const coin of coins) {
        if (!coin.collected) {
          const coinBox = { x: coin.x - 10, y: coin.y - 10, w: 20, h: 20 };
          const playerBox = { x: player.x, y: player.y, w: player.w, h: player.h };
          if (rectsOverlap(playerBox, coinBox)) {
            coin.collected = true;
            score++;
          }
        }
      }
    }

    function collideX() {
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }
    }

    function collideY() {
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }
    }

    function drawBackground(cameraX, cameraY) {
      // Parallax hills
      ctx.fillStyle = "#7ec850";
      for (let i = 0; i < 20; i++) {
        const x = (i * 220 - cameraX * 0.3) % (canvas.width + 300) - 150;
        ctx.beginPath();
        ctx.arc(x, canvas.height - 80, 140, Math.PI, 0);
        ctx.fill();
      }

      // Clouds
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      for (let i = 0; i < 8; i++) {
        const x = (i * 420 - cameraX * 0.15) % (canvas.width + 500) - 250;
        const y = 80 + (i % 3) * 50;
        drawCloud(x, y, 1 + (i % 2) * 0.3);
      }
    }

    function drawCloud(x, y, scale) {
      ctx.save();
      ctx.translate(x, y);
      ctx.scale(scale, scale);
      ctx.beginPath();
      ctx.arc(0, 20, 20, 0, Math.PI * 2);
      ctx.arc(20, 10, 25, 0, Math.PI * 2);
      ctx.arc(45, 20, 20, 0, Math.PI * 2);
      ctx.arc(20, 25, 22, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    function drawPlatform(p, cameraX, cameraY) {
      ctx.fillStyle = "#5b3a29";
      ctx.fillRect(p.x - cameraX, p.y - cameraY, p.w, p.h);

      ctx.fillStyle = "#7c4f36";
      ctx.fillRect(p.x - cameraX, p.y - cameraY, p.w, 6);
    }

    function drawCoin(coin, cameraX, cameraY) {
      if (coin.collected) return;
      const t = performance.now() * 0.005;
      const bob = Math.sin(t + coin.x) * 4;

      ctx.save();
      ctx.translate(coin.x - cameraX, coin.y - cameraY + bob);
      ctx.fillStyle = "#ffd700";
      ctx.beginPath();
      ctx.arc(0, 0, 10, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = "#f4b400";
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.arc(0, 0, 7, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
    }

    function drawPlayer(cameraX, cameraY) {
      const x = player.x - cameraX;
      const y = player.y - cameraY;

      // Simple sprite animation drawn procedurally
      // Frame layout: idle + 3 run frames
      const frame = player.animFrame;
      const legSwing = frame === 0 ? 0 : (frame === 1 ? 1 : frame === 2 ? 0 : -1);

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(0, player.h / 2 - 2, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = "#2b6cb0";
      ctx.fillRect(-14, -10, 28, 24);

      // Head
      ctx.fillStyle = "#f6c7a1";
      ctx.beginPath();
      ctx.arc(0, -24, 12, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(4, -27, 2, 2);
      ctx.fillRect(-2, -27, 2, 2);

      // Arms
      ctx.strokeStyle = "#f6c7a1";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-12, -2);
      ctx.lineTo(-20, 8 + legSwing);
      ctx.moveTo(12, -2);
      ctx.lineTo(20, 8 - legSwing);
      ctx.stroke();

      // Legs
      ctx.strokeStyle = "#1a202c";
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(-8, 14);
      ctx.lineTo(-10 + legSwing * 2, 28);
      ctx.moveTo(8, 14);
      ctx.lineTo(10 - legSwing * 2, 28);
      ctx.stroke();

      // Feet
      ctx.strokeStyle = "#111";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(-12 + legSwing * 2, 28);
      ctx.lineTo(-2 + legSwing * 2, 28);
      ctx.moveTo(2 - legSwing * 2, 28);
      ctx.lineTo(12 - legSwing * 2, 28);
      ctx.stroke();

      ctx.restore();
    }

    function drawHUD() {
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, 10, 160, 40);
      ctx.fillStyle = "white";
      ctx.font = "20px sans-serif";
      ctx.fillText(`Score: ${score}`, 20, 36);
    }

    function update() {
      updatePlayer();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      const cameraX = Math.max(0, Math.min(world.width - canvas.width, player.x - canvas.width / 2));
      const cameraY = Math.max(0, Math.min(world.height - canvas.height, player.y - canvas.height / 2));

      drawBackground(cameraX, cameraY);

      for (const p of platforms) drawPlatform(p, cameraX, cameraY);
      for (const coin of coins) drawCoin(coin, cameraX, cameraY);
      drawPlayer(cameraX, cameraY);
      drawHUD();

      // Goal marker
      ctx.fillStyle = "#ff4d4d";
      ctx.fillRect(2850 - cameraX, 980 - cameraY, 20, 120);
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(2870 - cameraX, 990 - cameraY, 60, 40);
      ctx.fillStyle = "#000";
      ctx.fillText("GOAL", 2878 - cameraX, 1015 - cameraY);
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

