```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or ←/→ | Jump: W / Space / ↑
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // World settings
    const GRAVITY = 1800;
    const MOVE_SPEED = 320;
    const JUMP_SPEED = 720;
    const FRICTION = 0.85;

    const world = {
      width: 4000,
      height: 1200
    };

    // Input
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // Platforms
    const platforms = [
      { x: 0, y: 1100, w: 4000, h: 100 }, // ground
      { x: 250, y: 950, w: 220, h: 30 },
      { x: 600, y: 850, w: 220, h: 30 },
      { x: 950, y: 760, w: 220, h: 30 },
      { x: 1300, y: 680, w: 220, h: 30 },
      { x: 1650, y: 600, w: 220, h: 30 },
      { x: 2050, y: 720, w: 260, h: 30 },
      { x: 2450, y: 820, w: 260, h: 30 },
      { x: 2900, y: 700, w: 260, h: 30 },
      { x: 3350, y: 620, w: 260, h: 30 }
    ];

    // Player
    const player = {
      x: 100,
      y: 900,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      state: "idle"
    };

    // Create a simple sprite sheet on an offscreen canvas
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 192;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawSpriteFrame(frame, colorBody, colorAccent) {
      const x = frame * 48;
      sctx.clearRect(x, 0, 48, 64);

      // Shadow/outline
      sctx.fillStyle = "#222";
      sctx.fillRect(x + 16, 10, 16, 16); // head
      sctx.fillRect(x + 14, 26, 20, 20); // torso
      sctx.fillRect(x + 10, 46, 10, 12); // left leg
      sctx.fillRect(x + 28, 46, 10, 12); // right leg
      sctx.fillRect(x + 6, 28, 8, 18); // left arm
      sctx.fillRect(x + 34, 28, 8, 18); // right arm

      // Body
      sctx.fillStyle = colorBody;
      sctx.fillRect(x + 17, 11, 14, 14);
      sctx.fillRect(x + 15, 27, 18, 18);
      sctx.fillRect(x + 11, 47, 8, 10);
      sctx.fillRect(x + 29, 47, 8, 10);

      // Accent
      sctx.fillStyle = colorAccent;
      sctx.fillRect(x + 18, 31, 12, 6);

      // Eyes
      sctx.fillStyle = "#fff";
      sctx.fillRect(x + 20, 16, 3, 3);
      sctx.fillRect(x + 25, 16, 3, 3);
    }

    // 4 frames: idle, walk1, walk2, jump
    drawSpriteFrame(0, "#4f8cff", "#ffd166");
    drawSpriteFrame(1, "#4f8cff", "#ffd166");
    drawSpriteFrame(2, "#4f8cff", "#ffd166");
    drawSpriteFrame(3, "#7c4dff", "#ffd166");

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update(dt) {
      // Horizontal input
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      if (move !== 0) {
        player.vx = move * MOVE_SPEED;
        player.facing = move;
      } else {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      // Jump
      const jumpPressed = keys[" "] || keys["w"] || keys["arrowup"];
      if (jumpPressed && player.onGround) {
        player.vy = -JUMP_SPEED;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY * dt;

      // Move and collide on X
      player.x += player.vx * dt;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Move and collide on Y
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // World bounds
      player.x = Math.max(0, Math.min(world.width - player.w, player.x));
      if (player.y > world.height) {
        player.x = 100;
        player.y = 900;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 20) {
        player.state = "walk";
      } else {
        player.state = "idle";
      }

      player.animTime += dt;
    }

    function getFrame() {
      if (player.state === "jump") return 3;
      if (player.state === "walk") {
        return Math.floor(player.animTime * 12) % 2 + 1; // frames 1-2
      }
      return 0;
    }

    function drawBackground(cameraX) {
      // Parallax hills
      ctx.fillStyle = "#7ec850";
      for (let i = 0; i < 20; i++) {
        const x = (i * 300 - cameraX * 0.2) % (canvas.width + 300) - 300;
        ctx.beginPath();
        ctx.arc(x + 150, canvas.height - 60, 140, Math.PI, 0);
        ctx.fill();
      }

      // Clouds
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      for (let i = 0; i < 10; i++) {
        const x = (i * 420 - cameraX * 0.4) % (canvas.width + 420) - 420;
        const y = 80 + (i % 3) * 40;
        ctx.beginPath();
        ctx.arc(x + 40, y, 20, 0, Math.PI * 2);
        ctx.arc(x + 60, y - 10, 28, 0, Math.PI * 2);
        ctx.arc(x + 90, y, 22, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      const cameraX = Math.max(
        0,
        Math.min(world.width - canvas.width, player.x - canvas.width / 2)
      );
      const cameraY = 0;

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground(cameraX);

      // Platforms
      for (const p of platforms) {
        const sx = p.x - cameraX;
        const sy = p.y - cameraY;

        ctx.fillStyle = "#5b3a29";
        ctx.fillRect(sx, sy, p.w, p.h);

        ctx.fillStyle = "#8b5a2b";
        ctx.fillRect(sx, sy, p.w, 8);

        ctx.fillStyle = "rgba(255,255,255,0.08)";
        ctx.fillRect(sx, sy, p.w, 2);
      }

      // Player sprite
      const frame = getFrame();
      const sx = frame * 48;
      const sy = 0;
      const dx = player.x - cameraX;
      const dy = player.y - cameraY;

      ctx.save();
      ctx.translate(dx + player.w / 2, dy + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-(dx + player.w / 2), -(dy + player.h / 2));

      ctx.drawImage(
        spriteCanvas,
        sx, sy, 48, 64,
        dx, dy, player.w, player.h
      );
      ctx.restore();

      // Debug ground line / world edge
      ctx.strokeStyle = "rgba(0,0,0,0.15)";
      ctx.beginPath();
      ctx.moveTo(-cameraX, 1100);
      ctx.lineTo(world.width - cameraX, 1100);
      ctx.stroke();
    }

    let last = performance.now();
    function loop(now) {
      const dt = Math.min(0.033, (now - last) / 1000);
      last = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }
    requestAnimationFrame(loop);
  </script>
</body>
</html>
