      // body
      sctx.fillStyle = color;
      sctx.fillRect(x + 12, y + 14, 24, 30);

      // head
      sctx.fillStyle = "#ffd7b3";
      sctx.fillRect(x + 14, y + 2, 20, 16);

      // eyes
      sctx.fillStyle = "#222";
      sctx.fillRect(x + eyeX, y + 8, 3, 3);
      sctx.fillRect(x + eyeX + 8, y + 8, 3, 3);

      // arms
      sctx.fillStyle = color;
      sctx.fillRect(x + 6, y + 18, 6, 18);
      sctx.fillRect(x + 36, y + 18, 6, 18);

      // legs
      sctx.fillRect(x + 14, y + 44, 8, 16 + legOffset);
      sctx.fillRect(x + 26, y + 44, 8, 16 - legOffset);
    }

    // idle row 0
    drawFrame(0, 0, "#ff4d4d", 1, 0);
    drawFrame(1, 0, "#ff5f5f", 1, 0);
    drawFrame(2, 0, "#ff4d4d", 1, 0);
    drawFrame(3, 0, "#ff5f5f", 1, 0);

    // run row 1
    drawFrame(0, 1, "#4dff88", 1, -4);
    drawFrame(1, 1, "#5fff95", 1, 4);
    drawFrame(2, 1, "#4dff88", 1, -2);
    drawFrame(3, 1, "#5fff95", 1, 2);

    // jump row 2
    drawFrame(0, 2, "#4d8dff", 1, 0);
    drawFrame(1, 2, "#5f9aff", 1, 0);
    drawFrame(2, 2, "#4d8dff", 1, 0);
    drawFrame(3, 2, "#5f9aff", 1, 0);

    function getAnimRow() {
      if (!player.onGround) return 2;
      if (Math.abs(player.vx) > 40) return 1;
      return 0;
    }

    function updateAnimation(dt) {
      const row = getAnimRow();
      player.animTime += dt;

      const speed = row === 1 ? 0.08 : 0.18;
      if (player.animTime >= speed) {
        player.animTime = 0;
        player.animFrame = (player.animFrame + 1) % 4;
      }

      if (row !== player.stateRow) {
        player.stateRow = row;
        player.animFrame = 0;
        player.animTime = 0;
      }
    }

    // --- Collision helpers ---
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisionsX(entity, solids) {
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vx > 0) {
            entity.x = s.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = s.x + s.w;
          }
          entity.vx = 0;
        }
      }
    }

    function resolveCollisionsY(entity, solids) {
      entity.onGround = false;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0,
      smooth: 0.08
    };

    // --- Game loop ---
    let last = performance.now();

    function update(dt) {
      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed * dt;
        player.facing = 1;
      }

      // Clamp horizontal speed
      player.vx = Math.max(-320, Math.min(320, player.vx));

      // Jump
      if (jump && player.onGround && !player.jumpHeld) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }
      player.jumpHeld = jump;

      // Physics
      player.vy += world.gravity * dt;
      player.x += player.vx * dt;
      resolveCollisionsX(player, platforms);

      player.y += player.vy * dt;
      resolveCollisionsY(player, platforms);

      // Friction
      if (player.onGround) {
        player.vx *= world.friction;
      } else {
        player.vx *= world.airFriction;
      }

      // Update animation
      updateAnimation(dt);

      // Camera follow
      const targetX = player.x + player.w / 2 - canvas.width / 2;
      const targetY = player.y + player.h / 2 - canvas.height / 2;
      camera.x += (targetX - camera.x) * camera.smooth;
      camera.y += (targetY - camera.y) * camera.smooth;

      // Prevent camera from going too far up
      camera.y = Math.max(-100, camera.y);
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#3a2f2f";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#5c4b4b";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
    }

    function drawPlayer() {
      const row = getAnimRow();
      const sx = player.animFrame * frameW;
      const sy = row * frameH;

      ctx.save();
      ctx.translate(player.x - camera.x + player.w / 2, player.y - camera.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(player.w / 2, player.h - 4, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // sprite
      ctx.drawImage(sheet, sx, sy, frameW, frameH, 0, 0, player.w, player.h);

      ctx.restore();
    }

    function drawBackground() {
      // parallax clouds
      ctx.fillStyle = "rgba(255,255,255,0.55)";
      for (let i = 0; i < 8; i++) {
        const x = (i * 260 - (camera.x * 0.25) % 260) - 40;
        const y = 60 + (i % 3) * 55;
        ctx.beginPath();
        ctx.ellipse(x, y, 40, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 28, y - 10, 34, 16, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 56, y, 42, 18, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      // distant hills
      ctx.fillStyle = "#7ec07e";
      for (let i = 0; i < 6; i++) {
        const x = (i * 420 - (camera.x * 0.12) % 420) - 100;
        ctx.beginPath();
        ctx.moveTo(x, canvas.height);
        ctx.quadraticCurveTo(x + 120, canvas.height - 180, x + 240, canvas.height);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // Platforms
      for (const p of platforms) drawPlatform(p);

      // Player
      drawPlayer();

      // Debug info
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, canvas.height - 70, 220, 50);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 20, canvas.height - 48);
      ctx.fillText(`vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 20, canvas.height - 28);
    }

    function loop(now) {
      const dt = Math.min((now - last) / 1000, 0.033);
      last = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

