```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      line-height: 1.4;
    }
  </style>
</head>
<body>
  <div class="hud">
    Controls: ← → to move, Space / ↑ to jump
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // -----------------------------
    // Input
    // -----------------------------
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.code] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.code] = false;
    });

    // -----------------------------
    // World / Physics constants
    // -----------------------------
    const GRAVITY = 0.7;
    const MOVE_SPEED = 5;
    const JUMP_FORCE = 14;
    const FRICTION = 0.8;

    const world = {
      width: 3000,
      height: 1200
    };

    // -----------------------------
    // Platforms
    // -----------------------------
    const platforms = [
      { x: 0, y: 700, w: 600, h: 50 },
      { x: 700, y: 620, w: 250, h: 40 },
      { x: 1050, y: 560, w: 250, h: 40 },
      { x: 1450, y: 650, w: 300, h: 40 },
      { x: 1850, y: 580, w: 220, h: 40 },
      { x: 2200, y: 500, w: 260, h: 40 },
      { x: 2550, y: 620, w: 300, h: 40 },
      { x: 0, y: 900, w: 3000, h: 100 } // ground
    ];

    // -----------------------------
    // Player
    // -----------------------------
    const player = {
      x: 100,
      y: 500,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      animFrame: 0,
      state: "idle"
    };

    // -----------------------------
    // Sprite sheet generation
    // -----------------------------
    // Creates a simple 4-frame animated character on an offscreen canvas.
    const spriteSheet = document.createElement("canvas");
    spriteSheet.width = 4 * 48;
    spriteSheet.height = 64;
    const sctx = spriteSheet.getContext("2d");

    function drawFrame(frameIndex) {
      const x = frameIndex * 48;
      sctx.clearRect(x, 0, 48, 64);

      // body
      sctx.fillStyle = "#ffcc66";
      sctx.fillRect(x + 16, 18, 16, 24);

      // head
      sctx.fillStyle = "#f2c9a0";
      sctx.fillRect(x + 14, 6, 20, 16);

      // eyes
      sctx.fillStyle = "#222";
      sctx.fillRect(x + 19, 12, 3, 3);
      sctx.fillRect(x + 26, 12, 3, 3);

      // legs / arms vary by frame
      sctx.strokeStyle = "#333";
      sctx.lineWidth = 4;
      sctx.lineCap = "round";

      // arms
      sctx.beginPath();
      sctx.moveTo(x + 16, 24);
      sctx.lineTo(x + 8 + (frameIndex % 2 ? 2 : 0), 34);
      sctx.stroke();

      sctx.beginPath();
      sctx.moveTo(x + 32, 24);
      sctx.lineTo(x + 40 - (frameIndex % 2 ? 2 : 0), 34);
      sctx.stroke();

      // legs
      sctx.beginPath();
      sctx.moveTo(x + 20, 42);
      sctx.lineTo(x + 14 + (frameIndex % 2 ? 3 : 0), 58);
      sctx.stroke();

      sctx.beginPath();
      sctx.moveTo(x + 28, 42);
      sctx.lineTo(x + 34 - (frameIndex % 2 ? 3 : 0), 58);
      sctx.stroke();
    }

    for (let i = 0; i < 4; i++) drawFrame(i);

    // -----------------------------
    // Collision helpers
    // -----------------------------
    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // Horizontal movement
      entity.x += entity.vx;
      for (const p of solids) {
        if (rectsIntersect(entity, p)) {
          if (entity.vx > 0) {
            entity.x = p.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = p.x + p.w;
          }
          entity.vx = 0;
        }
      }

      // Vertical movement
      entity.y += entity.vy;
      for (const p of solids) {
        if (rectsIntersect(entity, p)) {
          if (entity.vy > 0) {
            entity.y = p.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = p.y + p.h;
            entity.vy = 0;
          }
        }
      }
    }

    // -----------------------------
    // Camera
    // -----------------------------
    const camera = {
      x: 0,
      y: 0
    };

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    // -----------------------------
    // Game update
    // -----------------------------
    function update() {
      // Input
      if (keys["ArrowLeft"] || keys["KeyA"]) {
        player.vx = Math.max(player.vx - 0.8, -MOVE_SPEED);
        player.facing = -1;
      } else if (keys["ArrowRight"] || keys["KeyD"]) {
        player.vx = Math.min(player.vx + 0.8, MOVE_SPEED);
        player.facing = 1;
      } else {
        player.vx *= FRICTION;
        if (Math.abs(player.vx) < 0.1) player.vx = 0;
      }

      if ((keys["Space"] || keys["ArrowUp"] || keys["KeyW"]) && player.onGround) {
        player.vy = -JUMP_FORCE;
        player.onGround = false;
      }

      // Gravity
      player.vy += GRAVITY;
      if (player.vy > 20) player.vy = 20;

      // Physics + collisions
      resolveCollisions(player, platforms);

      // Animation state
      if (!player.onGround) {
        player.state = "jump";
      } else if (Math.abs(player.vx) > 0.5) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      // Animation timing
      player.animTime += 1;
      if (player.state === "run") {
        player.animFrame = Math.floor(player.animTime / 8) % 4;
      } else if (player.state === "jump") {
        player.animFrame = 2;
      } else {
        player.animFrame = 0;
      }

      updateCamera();
    }

    // -----------------------------
    // Rendering
    // -----------------------------
    function drawBackground() {
      // Parallax clouds
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const cloudOffset = camera.x * 0.3;
      ctx.fillStyle = "rgba(255,255,255,0.8)";
      for (let i = 0; i < 8; i++) {
        const x = ((i * 350) - cloudOffset) % (canvas.width + 400) - 200;
        const y = 60 + (i % 3) * 50;
        ctx.beginPath();
        ctx.arc(x, y, 25, 0, Math.PI * 2);
        ctx.arc(x + 25, y - 10, 30, 0, Math.PI * 2);
        ctx.arc(x + 55, y, 22, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of platforms) {
        const sx = p.x - camera.x;
        const sy = p.y - camera.y;

        ctx.fillStyle = "#5b3a29";
        ctx.fillRect(sx, sy, p.w, p.h);

        ctx.fillStyle = "#7c4f36";
        ctx.fillRect(sx, sy, p.w, 10);

        ctx.strokeStyle = "#3b2418";
        ctx.strokeRect(sx, sy, p.w, p.h);
      }
    }

    function drawPlayer() {
      const frameX = player.animFrame * 48;
      const sx = player.x - camera.x;
      const sy = player.y - camera.y;

      ctx.save();
      ctx.translate(sx + player.w / 2, sy + player.h / 2);

      if (player.facing === -1) {
        ctx.scale(-1, 1);
      }

      // Draw sprite centered
      ctx.drawImage(
        spriteSheet,
        frameX, 0, 48, 64,
        -player.w / 2, -player.h / 2, player.w, player.h
      );

      ctx.restore();
    }

    function drawWorldBounds() {
      ctx.strokeStyle = "rgba(0,0,0,0.15)";
      ctx.strokeRect(-camera.x, -camera.y, world.width, world.height);
    }

    function render() {
      drawBackground();
      drawWorldBounds();
      drawPlatforms();
      drawPlayer();

      // Simple debug text
      ctx.fillStyle = "#000";
      ctx.font = "16px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(0)} y: ${player.y.toFixed(0)}`, 20, canvas.height - 20);
    }

    // -----------------------------
    // Main loop
    // -----------------------------
    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
