```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or Arrow Keys | Jump: Space / W / Up
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    const world = {
      gravity: 0.7,
      friction: 0.82,
      width: 3000,
      height: 1200
    };

    const camera = {
      x: 0,
      y: 0
    };

    class Platform {
      constructor(x, y, w, h, color = "#4b5563") {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.color = color;
      }

      draw(ctx, camera) {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x - camera.x, this.y - camera.y, this.w, this.h);
      }
    }

    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.w = 40;
        this.h = 56;

        this.vx = 0;
        this.vy = 0;

        this.speed = 0.7;
        this.jumpPower = 14;
        this.onGround = false;

        this.facing = 1;
        this.animTime = 0;
        this.frame = 0;
      }

      update(platforms) {
        const left = keys["a"] || keys["arrowleft"];
        const right = keys["d"] || keys["arrowright"];
        const jump = keys[" "] || keys["w"] || keys["arrowup"];

        if (left) {
          this.vx -= this.speed;
          this.facing = -1;
        }
        if (right) {
          this.vx += this.speed;
          this.facing = 1;
        }

        // friction
        if (!left && !right) {
          this.vx *= world.friction;
        }

        // clamp horizontal speed
        this.vx = Math.max(-7, Math.min(7, this.vx));

        // jump
        if (jump && this.onGround) {
          this.vy = -this.jumpPower;
          this.onGround = false;
        }

        // gravity
        this.vy += world.gravity;

        // move horizontally
        this.x += this.vx;
        this.resolveCollisions(platforms, "x");

        // move vertically
        this.y += this.vy;
        this.onGround = false;
        this.resolveCollisions(platforms, "y");

        // world bounds
        this.x = Math.max(0, Math.min(world.width - this.w, this.x));
        if (this.y > world.height) {
          this.x = 100;
          this.y = 100;
          this.vx = 0;
          this.vy = 0;
        }

        // animation
        const moving = Math.abs(this.vx) > 0.5;
        if (moving && this.onGround) {
          this.animTime += 1;
          if (this.animTime > 8) {
            this.frame = (this.frame + 1) % 4;
            this.animTime = 0;
          }
        } else {
          this.frame = 0;
          this.animTime = 0;
        }
      }

      resolveCollisions(platforms, axis) {
        for (const p of platforms) {
          if (
            this.x < p.x + p.w &&
            this.x + this.w > p.x &&
            this.y < p.y + p.h &&
            this.y + this.h > p.y
          ) {
            if (axis === "x") {
              if (this.vx > 0) {
                this.x = p.x - this.w;
              } else if (this.vx < 0) {
                this.x = p.x + p.w;
              }
              this.vx = 0;
            } else if (axis === "y") {
              if (this.vy > 0) {
                this.y = p.y - this.h;
                this.vy = 0;
                this.onGround = true;
              } else if (this.vy < 0) {
                this.y = p.y + p.h;
                this.vy = 0;
              }
            }
          }
        }
      }

      draw(ctx, camera) {
        const x = this.x - camera.x;
        const y = this.y - camera.y;

        // shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)";
        ctx.beginPath();
        ctx.ellipse(x + this.w / 2, y + this.h + 6, 18, 6, 0, 0, Math.PI * 2);
        ctx.fill();

        // body animation frames
        const bob = this.onGround && Math.abs(this.vx) > 0.5 ? Math.sin(this.frame * 1.5) * 2 : 0;

        // legs
        ctx.fillStyle = "#2d3748";
        ctx.fillRect(x + 10, y + 38 + bob, 8, 18);
        ctx.fillRect(x + 22, y + 38 - bob, 8, 18);

        // torso
        ctx.fillStyle = "#ef4444";
        ctx.fillRect(x + 8, y + 18 + bob, 24, 22);

        // arms
        ctx.fillStyle = "#f59e0b";
        if (this.frame % 2 === 0) {
          ctx.fillRect(x + 2, y + 20 + bob, 8, 18);
          ctx.fillRect(x + 30, y + 20 - bob, 8, 18);
        } else {
          ctx.fillRect(x + 2, y + 22 - bob, 8, 18);
          ctx.fillRect(x + 30, y + 22 + bob, 8, 18);
        }

        // head
        ctx.fillStyle = "#fcd34d";
        ctx.beginPath();
        ctx.arc(x + 20, y + 12 + bob, 12, 0, Math.PI * 2);
        ctx.fill();

        // eyes
        ctx.fillStyle = "#111827";
        const eyeOffset = this.facing === 1 ? 3 : -3;
        ctx.beginPath();
        ctx.arc(x + 16 + eyeOffset, y + 10 + bob, 2, 0, Math.PI * 2);
        ctx.arc(x + 24 + eyeOffset, y + 10 + bob, 2, 0, Math.PI * 2);
        ctx.fill();

        // facing indicator
        ctx.strokeStyle = "#111827";
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.moveTo(x + 20, y + 14 + bob);
        ctx.lineTo(x + 20 + this.facing * 8, y + 14 + bob);
        ctx.stroke();
      }
    }

    const platforms = [
      new Platform(0, 700, 1200, 40, "#334155"),
      new Platform(1300, 760, 500, 40, "#334155"),
      new Platform(1900, 650, 350, 40, "#334155"),
      new Platform(2400, 580, 300, 40, "#334155"),
      new Platform(600, 560, 220, 30, "#475569"),
      new Platform(900, 470, 180, 30, "#475569"),
      new Platform(1600, 520, 180, 30, "#475569"),
      new Platform(2100, 430, 180, 30, "#475569")
    ];

    const player = new Player(100, 100);

    function drawBackground() {
      // simple parallax hills
      ctx.fillStyle = "#b7e4ff";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const layers = [
        { speed: 0.2, color: "#9bd18f", y: canvas.height * 0.75, amp: 30 },
        { speed: 0.4, color: "#7fbf7f", y: canvas.height * 0.82, amp: 45 }
      ];

      for (const layer of layers) {
        ctx.fillStyle = layer.color;
        ctx.beginPath();
        ctx.moveTo(0, canvas.height);
        for (let x = 0; x <= canvas.width + 100; x += 20) {
          const worldX = x + camera.x * layer.speed;
          const y = layer.y + Math.sin(worldX * 0.01) * layer.amp;
          ctx.lineTo(x, y);
        }
        ctx.lineTo(canvas.width, canvas.height);
        ctx.closePath();
        ctx.fill();
      }
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));
    }

    function drawWorldBounds() {
      ctx.strokeStyle = "rgba(255,255,255,0.15)";
      ctx.strokeRect(-camera.x, -camera.y, world.width, world.height);
    }

    function gameLoop() {
      player.update(platforms);
      updateCamera();

      drawBackground();
      drawWorldBounds();

      for (const p of platforms) {
        p.draw(ctx, camera);
      }

      player.draw(ctx, camera);

      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
