Below is a **single-file HTML/JavaScript** example of a simple **2D platformer** with:

- basic **physics simulation** (gravity, acceleration, friction, jumping)
- **collision detection** with platforms
- **sprite animation** using a simple generated sprite sheet
- camera following the player
- coins and a goal flag

You can save this as `platformer.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    #hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 18px;
      text-shadow: 0 2px 4px rgba(0,0,0,0.6);
      user-select: none;
    }
  </style>
</head>
<body>
  <div id="hud">Coins: <span id="coins">0</span></div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const coinDisplay = document.getElementById("coins");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", (e) => keys[e.key.toLowerCase()] = false);

    // --- World ---
    const world = {
      width: 3200,
      height: 1200
    };

    const gravity = 2200;
    const moveSpeed = 650;
    const jumpSpeed = 900;
    const friction = 0.82;

    const player = {
      x: 100,
      y: 300,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      coins: 0,
      animTime: 0,
      state: "idle" // idle, run, jump
    };

    const platforms = [
      { x: 0, y: 1100, w: 3200, h: 100 },
      { x: 200, y: 900, w: 300, h: 30 },
      { x: 600, y: 800, w: 250, h: 30 },
      { x: 1000, y: 700, w: 300, h: 30 },
      { x: 1450, y: 600, w: 250, h: 30 },
      { x: 1850, y: 750, w: 350, h: 30 },
      { x: 2350, y: 650, w: 250, h: 30 },
      { x: 2750, y: 850, w: 250, h: 30 }
    ];

    const coins = [
      { x: 260, y: 850, r: 12, collected: false },
      { x: 680, y: 750, r: 12, collected: false },
      { x: 1080, y: 650, r: 12, collected: false },
      { x: 1530, y: 550, r: 12, collected: false },
      { x: 1950, y: 700, r: 12, collected: false },
      { x: 2420, y: 600, r: 12, collected: false },
      { x: 2820, y: 800, r: 12, collected: false }
    ];

    const goal = { x: 3000, y: 760, w: 40, h: 140 };

    // --- Simple generated sprite sheet ---
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 192;
    spriteCanvas.height = 64;
    const sctx = spriteCanvas.getContext("2d");

    function drawFrame(frame, colorBody, colorAccent) {
      const ox = frame * 64;
      sctx.clearRect(ox, 0, 64, 64);

      // shadow
      sctx.fillStyle = "rgba(0,0,0,0.15)";
      sctx.beginPath();
      sctx.ellipse(ox + 32, 58, 16, 4, 0, 0, Math.PI * 2);
      sctx.fill();

      // body
      sctx.fillStyle = colorBody;
      sctx.fillRect(ox + 20, 18, 24, 28);

      // head
      sctx.fillStyle = "#f2c9a0";
      sctx.fillRect(ox + 22, 6, 20, 16);

      // eyes
      sctx.fillStyle = "#222";
      sctx.fillRect(ox + 26, 12, 3, 3);
      sctx.fillRect(ox + 35, 12, 3, 3);

      // accent
      sctx.fillStyle = colorAccent;
      sctx.fillRect(ox + 18, 20, 28, 6);

      // legs/arms vary by frame
      sctx.strokeStyle = "#333";
      sctx.lineWidth = 4;
      sctx.lineCap = "round";

      if (frame === 0) {
        sctx.beginPath();
        sctx.moveTo(ox + 24, 46); sctx.lineTo(ox + 18, 56);
        sctx.moveTo(ox + 40, 46); sctx.lineTo(ox + 46, 56);
        sctx.moveTo(ox + 20, 28); sctx.lineTo(ox + 12, 36);
        sctx.moveTo(ox + 44, 28); sctx.lineTo(ox + 52, 36);
        sctx.stroke();
      } else if (frame === 1) {
        sctx.beginPath();
        sctx.moveTo(ox + 24, 46); sctx.lineTo(ox + 22, 56);
        sctx.moveTo(ox + 40, 46); sctx.lineTo(ox + 50, 52);
        sctx.moveTo(ox + 20, 28); sctx.lineTo(ox + 14, 40);
        sctx.moveTo(ox + 44, 28); sctx.lineTo(ox + 50, 34);
        sctx.stroke();
      } else {
        sctx.beginPath();
        sctx.moveTo(ox + 24, 46); sctx.lineTo(ox + 14, 52);
        sctx.moveTo(ox + 40, 46); sctx.lineTo(ox + 42, 56);
        sctx.moveTo(ox + 20, 28); sctx.lineTo(ox + 10, 34);
        sctx.moveTo(ox + 44, 28); sctx.lineTo(ox + 52, 40);
        sctx.stroke();
      }
    }

    drawFrame(0, "#4f8cff", "#2d5fd3");
    drawFrame(1, "#5aa0ff", "#2d5fd3");
    drawFrame(2, "#4f8cff", "#2d5fd3");

    const spriteSheet = new Image();
    spriteSheet.src = spriteCanvas.toDataURL();

    // --- Collision helpers ---
    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // X axis
      entity.x += entity.vx * dt;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vx > 0) entity.x = s.x - entity.w;
          else if (entity.vx < 0) entity.x = s.x + s.w;
          entity.vx = 0;
        }
      }

      // Y axis
      entity.y += entity.vy * dt;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.vy = 0;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
            entity.vy = 0;
          }
        }
      }
    }

    // --- Camera ---
    const camera = { x: 0, y: 0 };

    // --- Game loop ---
    let last = performance.now();
    let dt = 0;

    function update(delta) {
      dt = delta;

      // Input
      let move = 0;
      if (keys["a"] || keys["arrowleft"]) move -= 1;
      if (keys["d"] || keys["arrowright"]) move += 1;

      if (move !== 0) player.facing = move;

      // Horizontal movement
      player.vx += move * moveSpeed * dt;
      if (move === 0 && player.onGround) {
        player.vx *= Math.pow(friction, dt * 60);
      }

      // Clamp speed
      player.vx = Math.max(-350, Math.min(350, player.vx));

      // Jump
      if ((keys["w"] || keys["arrowup"] || keys[" "]) && player.onGround) {
        player.vy = -jumpSpeed;
        player.onGround = false;
      }

      // Gravity
      player.vy += gravity * dt;
      player.vy = Math.min(player.vy, 1600);

      // Move and collide
      resolveCollisions(player, platforms);

      // Collect coins
      for (const c of coins) {
        if (!c.collected) {
          const dx = (player.x + player.w / 2) - c.x;
          const dy = (player.y + player.h / 2) - c.y;
          if (Math.hypot(dx, dy) < c.r + 24) {
            c.collected = true;
            player.coins++;
            coinDisplay.textContent = player.coins;
          }
        }
      }

      // Animation state
      if (!player.onGround) player.state = "jump";
      else if (Math.abs(player.vx) > 20) player.state = "run";
      else player.state = "idle";

      player.animTime += dt;

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;
      camera.x = Math.max(0, Math.min(world.width - canvas.width, camera.x));
      camera.y = Math.max(0, Math.min(world.height - canvas.height, camera.y));

      // Win condition
      if (rectsOverlap(player, goal)) {
        alert("You reached the goal! Refresh to play again.");
      }

      // Fall reset
      if (player.y > world.height + 300) {
        player.x = 100;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function drawBackground() {
      // Parallax clouds
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const cloudOffsets = [0.2, 0.4, 0.6];
      for (let i = 0; i < 12; i++) {
        const px = (i * 280 - camera.x * cloudOffsets[i % 3]) % (canvas.width + 300) - 150;
        const py = 60 + (i % 4) * 50;
        drawCloud(px, py, 1 + (i % 3) * 0.3);
      }

      // Distant hills
      ctx.fillStyle = "#7ec97e";
      for (let i = 0; i < 6; i++) {
        const x = (i * 600 - camera.x * 0.3) % (canvas.width + 700) - 200;
        ctx.beginPath();
        ctx.ellipse(x + 250, canvas.height - 120, 220, 90, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawCloud(x, y, scale) {
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      ctx.beginPath();
      ctx.ellipse(x, y, 30 * scale, 18 * scale, 0, 0, Math.PI * 2);
      ctx.ellipse(x + 25 * scale, y - 10 * scale, 35 * scale, 22 * scale, 0, 0, Math.PI * 2);
      ctx.ellipse(x + 55 * scale, y, 28 * scale, 16 * scale, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    function draw() {
      drawBackground();

      ctx.save();
      ctx.translate(-camera.x, -camera.y);

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5b4636";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7b5d45";
        ctx.fillRect(p.x, p.y, p.w, 8);
      }

      // Coins
      for (const c of coins) {
        if (c.collected) continue;
        ctx.save();
        ctx.translate(c.x, c.y);
        ctx.rotate(Math.sin(performance.now() * 0.006) * 0.2);
        ctx.fillStyle = "#ffd54a";
        ctx.beginPath();
        ctx.arc(0, 0, c.r, 0, Math.PI * 2);
        ctx.fill();
        ctx.strokeStyle = "#c99b00";
        ctx.lineWidth = 3;
        ctx.stroke();
        ctx.fillStyle = "#fff3a0";
        ctx.beginPath();
        ctx.arc(-4, -4, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.restore();
      }

      // Goal flag
      ctx.fillStyle = "#444";
      ctx.fillRect(goal.x, goal.y, 6, goal.h);
      ctx.fillStyle = "#ff4d4d";
      ctx.beginPath();
      ctx.moveTo(goal.x + 6, goal.y + 10);
      ctx.lineTo(goal.x + 50, goal.y + 25);
      ctx.lineTo(goal.x + 6, goal.y + 40);
      ctx.closePath();
      ctx.fill();

      // Player sprite animation
      let frame = 0;
      if (player.state === "run") {
        frame = Math.floor(player.animTime * 12) % 3;
      } else if (player.state === "jump") {
        frame = 1;
      } else {
        frame = 0;
      }

      ctx.save();
      if (player.facing < 0) {
        ctx.translate(player.x + player.w, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(spriteSheet, frame * 64, 0, 64, 64, 0, 0, 64, 64);
      } else {
        ctx.drawImage(spriteSheet, frame * 64, 0, 64, 64, player.x, player.y, 64, 64);
      }
      ctx.restore();

      ctx.restore();

      // Debug text
      ctx.fillStyle = "rgba(0,0,0,0.4)";
      ctx.fillRect(10, canvas.height - 70, 420, 60);
      ctx.fillStyle = "white";
      ctx.font = "16px sans-serif";
      ctx.fillText("Move: A/D or Arrow Keys", 20, canvas.height - 45);
      ctx.fillText("Jump: W / Up / Space", 20, canvas.height - 25);
    }

    function loop(now) {
      const delta = Math.min((now - last) / 1000, 0.033);
      last = now;
      update(delta);
      draw();
      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
