          else if (entity.vx < 0) entity.x = s.x + s.w;
          entity.vx = 0;
        }
      }

      // Y axis
      entity.y += entity.vy * dt;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
          }
          entity.vy = 0;
        }
      }
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    // --- Game loop ---
    let last = performance.now();
    let dt = 0;

    function update(delta) {
      dt = delta;

      // Input movement
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx = -player.speed;
        player.facing = -1;
      } else if (right) {
        player.vx = player.speed;
        player.facing = 1;
      } else {
        player.vx *= 0.82; // friction
        if (Math.abs(player.vx) < 5) player.vx = 0;
      }

      // Jump
      if (jump && player.onGround && !player._jumpHeld) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }
      player._jumpHeld = jump;

      // Gravity
      player.vy += world.gravity * dt;
      if (player.vy > 2000) player.vy = 2000;

      // Collisions
      resolveCollisions(player, platforms);

      // Animation state
      const moving = Math.abs(player.vx) > 20;
      player.state = player.onGround ? (moving ? "walk" : "idle") : "jump";
      player.animTime += delta;

      // Camera follow
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      camera.x = Math.max(0, Math.min(camera.x, world.width - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, world.height - canvas.height));
    }

    function drawBackground() {
      // sky gradient already on canvas background, but we can add clouds
      ctx.save();
      ctx.translate(-camera.x * 0.3, -camera.y * 0.1);

      for (let i = 0; i < 12; i++) {
        const x = i * 280 + 80;
        const y = 80 + (i % 3) * 60;
        ctx.fillStyle = "rgba(255,255,255,0.75)";
        ctx.beginPath();
        ctx.ellipse(x, y, 50, 22, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 30, y - 10, 40, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(x + 60, y, 55, 24, 0, 0, Math.PI * 2);
        ctx.fill();
      }

      ctx.restore();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        const x = p.x - camera.x;
        const y = p.y - camera.y;

        // top
        ctx.fillStyle = "#6b4f2a";
        ctx.fillRect(x, y, p.w, p.h);

        // grass top
        ctx.fillStyle = "#4caf50";
        ctx.fillRect(x, y, p.w, 8);

        // simple shading
        ctx.fillStyle = "rgba(255,255,255,0.08)";
        ctx.fillRect(x, y, p.w, 4);
      }
    }

    function drawPlayer() {
      const frame =
        player.state === "jump" ? 2 :
        player.state === "walk" ? (Math.floor(player.animTime / 100) % 4) :
        0;

      const sx = frame * 64;
      const sy = 0;

      ctx.save();
      ctx.translate(player.x - camera.x, player.y - camera.y);

      // flip if facing left
      if (player.facing === -1) {
        ctx.translate(player.w, 0);
        ctx.scale(-1, 1);
      }

      // draw sprite scaled to player size
      ctx.drawImage(spriteSheet, sx, sy, 64, 64, 0, 0, player.w, player.h);

      ctx.restore();
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();
      drawPlatforms();
      drawPlayer();

      // debug info
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, canvas.height - 60, 260, 40);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(0)} y: ${player.y.toFixed(0)} vx: ${player.vx.toFixed(0)} vy: ${player.vy.toFixed(0)}`, 20, canvas.height - 35);
    }

    function loop(now) {
      const delta = Math.min((now - last) / 1000, 0.033);
      last = now;

      update(delta);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
