<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: Arial, sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #cfefff);
    }
    #hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 18px;
      text-shadow: 1px 1px 2px black;
      z-index: 10;
    }
  </style>
</head>
<body>
  <div id="hud">Coins: <span id="coins">0</span> | Use Arrow Keys / A-D to move, Space to jump</div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");
    const coinText = document.getElementById("coins");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", (e) => keys[e.key.toLowerCase()] = false);

    // --- World ---
    const gravity = 0.6;
    const friction = 0.85;

    const world = {
      width: 3000,
      height: 1200
    };

    const platforms = [
      { x: 0, y: 1100, w: 3000, h: 100 },
      { x: 200, y: 950, w: 250, h: 30 },
      { x: 550, y: 850, w: 250, h: 30 },
      { x: 900, y: 750, w: 250, h: 30 },
      { x: 1250, y: 650, w: 250, h: 30 },
      { x: 1650, y: 800, w: 300, h: 30 },
      { x: 2100, y: 700, w: 250, h: 30 },
      { x: 2450, y: 600, w: 250, h: 30 },
    ];

    const coins = [
      { x: 260, y: 900, r: 12, collected: false },
      { x: 610, y: 800, r: 12, collected: false },
      { x: 960, y: 700, r: 12, collected: false },
      { x: 1310, y: 600, r: 12, collected: false },
      { x: 1710, y: 750, r: 12, collected: false },
      { x: 2160, y: 650, r: 12, collected: false },
      { x: 2510, y: 550, r: 12, collected: false },
    ];

    const enemies = [
      { x: 700, y: 820, w: 40, h: 40, vx: 1.2, minX: 560, maxX: 780 },
      { x: 1750, y: 760, w: 40, h: 40, vx: 1.5, minX: 1660, maxX: 1900 },
      { x: 2300, y: 660, w: 40, h: 40, vx: 1.3, minX: 2110, maxX: 2400 },
    ];

    // --- Player ---
    const player = {
      x: 100,
      y: 1000,
      w: 48,
      h: 64,
      vx: 0,
      vy: 0,
      speed: 0.8,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      frame: 0,
      frameTimer: 0,
      alive: true
    };

    let score = 0;
    let cameraX = 0;
    let cameraY = 0;

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function circleRectCollision(circle, rect) {
      const cx = Math.max(rect.x, Math.min(circle.x, rect.x + rect.w));
      const cy = Math.max(rect.y, Math.min(circle.y, rect.y + rect.h));
      const dx = circle.x - cx;
      const dy = circle.y - cy;
      return dx * dx + dy * dy < circle.r * circle.r;
    }

    function updatePlayer() {
      if (!player.alive) return;

      // Movement
      if (keys["a"] || keys["arrowleft"]) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (keys["d"] || keys["arrowright"]) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Jump
      if ((keys[" "] || keys["space"]) && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Apply friction and gravity
      player.vx *= friction;
      player.vy += gravity;

      // Clamp speed
      player.vx = Math.max(-7, Math.min(7, player.vx));
      player.vy = Math.min(20, player.vy);

      // Horizontal movement + collision
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical movement + collision
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Collect coins
      for (const c of coins) {
        if (!c.collected && circleRectCollision(c, player)) {
          c.collected = true;
          score++;
          coinText.textContent = score;
        }
      }

      // Enemy collision
      for (const e of enemies) {
        if (rectsOverlap(player, e)) {
          // Simple death/reset
          resetPlayer();
          break;
        }
      }

      // Fall off world
      if (player.y > world.height + 200) {
        resetPlayer();
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.5;
      if (moving && player.onGround) {
        player.frameTimer++;
        if (player.frameTimer > 8) {
          player.frame = (player.frame + 1) % 4;
          player.frameTimer = 0;
        }
      } else {
        player.frame = 0;
        player.frameTimer = 0;
      }
    }

    function resetPlayer() {
      player.x = 100;
      player.y = 1000;
      player.vx = 0;
      player.vy = 0;
      player.alive = true;
    }

    function updateEnemies() {
      for (const e of enemies) {
        e.x += e.vx;
        if (e.x < e.minX || e.x > e.maxX) {
          e.vx *= -1;
        }
      }
    }

    function updateCamera() {
      cameraX = player.x + player.w / 2 - canvas.width / 2;
      cameraY = player.y + player.h / 2 - canvas.height / 2;

      cameraX = Math.max(0, Math.min(world.width - canvas.width, cameraX));
      cameraY = Math.max(0, Math.min(world.height - canvas.height, cameraY));
    }

    // --- Drawing ---
    function drawPlatform(p) {
      ctx.fillStyle = "#5b3a29";
      ctx.fillRect(p.x - cameraX, p.y - cameraY, p.w, p.h);
      ctx.fillStyle = "#7c4f36";
      ctx.fillRect(p.x - cameraX, p.y - cameraY, p.w, 8);
    }

    function drawCoin(c) {
      if (c.collected) return;
      ctx.beginPath();
      ctx.arc(c.x - cameraX, c.y - cameraY, c.r, 0, Math.PI * 2);
      ctx.fillStyle = "#ffd700";
      ctx.fill();
      ctx.strokeStyle = "#b8860b";
      ctx.stroke();
    }

    function drawEnemy(e) {
      ctx.fillStyle = "#e74c3c";
      ctx.fillRect(e.x - cameraX, e.y - cameraY, e.w, e.h);
      ctx.fillStyle = "black";
      ctx.fillRect(e.x - cameraX + 8, e.y - cameraY + 10, 6, 6);
      ctx.fillRect(e.x - cameraX + 26, e.y - cameraY + 10, 6, 6);
    }

    function drawPlayer() {
      const x = player.x - cameraX;
      const y = player.y - cameraY;

      // Simple sprite animation using colored body parts
      const bob = player.onGround ? Math.sin(player.frame * 0.8) * 2 : 0;

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 8, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.fillStyle = "#3498db";
      ctx.fillRect(x + 10, y + 18 + bob, 28, 28);

      // Head
      ctx.fillStyle = "#f1c27d";
      ctx.fillRect(x + 12, y + 2 + bob, 24, 20);

      // Eyes
      ctx.fillStyle = "black";
      if (player.facing === 1) {
        ctx.fillRect(x + 26, y + 10 + bob, 3, 3);
        ctx.fillRect(x + 31, y + 10 + bob, 3, 3);
      } else {
        ctx.fillRect(x + 15, y + 10 + bob, 3, 3);
        ctx.fillRect(x + 20, y + 10 + bob, 3, 3);
      }

      // Legs animation
      ctx.fillStyle = "#2c3e50";
      if (player.onGround && Math.abs(player.vx) > 0.5) {
        const legOffset = player.frame % 2 === 0 ? 4 : -4;
        ctx.fillRect(x + 12, y + 46 + bob, 8, 16 + legOffset);
        ctx.fillRect(x + 28, y + 46 + bob, 8, 16 - legOffset);
      } else {
        ctx.fillRect(x + 12, y + 46 + bob, 8, 16);
        ctx.fillRect(x + 28, y + 46 + bob, 8, 16);
      }
    }

    function drawBackground() {
      // Parallax clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 12; i++) {
        const cx = (i * 300 - cameraX * 0.3) % (world.width + 300) - 100;
        const cy = 100 + (i % 4) * 60;
        ctx.beginPath();
        ctx.ellipse(cx, cy, 40, 20, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 30, cy + 5, 50, 25, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 60, cy, 40, 20, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      // Ground haze
      ctx.fillStyle = "#8fd18f";
      ctx.fillRect(0, canvas.height - 80, canvas.width, 80);

      for (const p of platforms) drawPlatform(p);
      for (const c of coins) drawCoin(c);
      for (const e of enemies) drawEnemy(e);
      drawPlayer();

      // Goal marker
      ctx.fillStyle = "#2ecc71";
      ctx.fillRect(2850 - cameraX, 500 - cameraY, 20, 600);
      ctx.fillStyle = "#ffffff";
      ctx.fillRect(2870 - cameraX, 520 - cameraY, 80, 50);
      ctx.fillStyle = "#000";
      ctx.fillText("GOAL", 2880 - cameraX, 550 - cameraY);
    }

    function gameLoop() {
      updatePlayer();
      updateEnemies();
      updateCamera();
      render();
      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
