      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    const TILE_SIZE = 48;
    const GRAVITY = 2200;
    const MOVE_ACCEL = 4200;
    const MAX_SPEED = 320;
    const FRICTION = 3200;
    const JUMP_VELOCITY = 820;

    const level = [
      "................................................",
      "................................................",
      "................................................",
      "................................................",
      "....................###.......................",
      "..............###..............................",
      "................................................",
      ".........###....................................",
      "................................................",
      "................................................",
      "....###.....................###................",
      "................................................",
      "####################....########################",
    ];

    const world = {
      width: level[0].length * TILE_SIZE,
      height: level.length * TILE_SIZE,
      platforms: []
    };

    for (let y = 0; y < level.length; y++) {
      for (let x = 0; x < level[y].length; x++) {
        if (level[y][x] === "#") {
          world.platforms.push({
            x: x * TILE_SIZE,
            y: y * TILE_SIZE,
            w: TILE_SIZE,
            h: TILE_SIZE
          });
        }
      }
    }

    const player = {
      x: 100,
      y: 100,
      w: 34,
      h: 44,
      vx: 0,
      vy: 0,
      onGround: false,
      facing: 1,
      animTime: 0,
      animFrame: 0
    };

    const camera = {
      x: 0,
      y: 0
    };

    function clamp(value, min, max) {
      return Math.max(min, Math.min(max, value));
    }

    function rectsIntersect(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer(dt) {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= MOVE_ACCEL * dt;
        player.facing = -1;
      }
      if (right) {
        player.vx += MOVE_ACCEL * dt;
        player.facing = 1;
      }

      if (!left && !right) {
        if (player.vx > 0) {
          player.vx = Math.max(0, player.vx - FRICTION * dt);
        } else if (player.vx < 0) {
          player.vx = Math.min(0, player.vx + FRICTION * dt);
        }
      }

      player.vx = clamp(player.vx, -MAX_SPEED, MAX_SPEED);

      if (jump && player.onGround) {
        player.vy = -JUMP_VELOCITY;
        player.onGround = false;
      }

      player.vy += GRAVITY * dt;

      // Horizontal movement and collision
      player.x += player.vx * dt;
      for (const p of world.platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vx > 0) {
            player.x = p.x - player.w;
          } else if (player.vx < 0) {
            player.x = p.x + p.w;
          }
          player.vx = 0;
        }
      }

      // Vertical movement and collision
      player.y += player.vy * dt;
      player.onGround = false;
      for (const p of world.platforms) {
        if (rectsIntersect(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep player within world bounds
      player.x = clamp(player.x, 0, world.width - player.w);
      player.y = clamp(player.y, 0, world.height - player.h);

      // Animation
      const moving = Math.abs(player.vx) > 10;
      if (moving && player.onGround) {
        player.animTime += dt;
        if (player.animTime > 0.12) {
          player.animTime = 0;
          player.animFrame = (player.animFrame + 1) % 4;
        }
      } else {
        player.animFrame = 0;
        player.animTime = 0;
      }
    }

    function updateCamera() {
      camera.x = clamp(
        player.x + player.w / 2 - canvas.width / 2,
        0,
        Math.max(0, world.width - canvas.width)
      );
      camera.y = clamp(
        player.y + player.h / 2 - canvas.height / 2,
        0,
        Math.max(0, world.height - canvas.height)
      );
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4b3f2f";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);

      ctx.fillStyle = "#6d5a42";
      ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 8);

      ctx.strokeStyle = "rgba(0,0,0,0.2)";
      ctx.strokeRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
    }

    function drawPlayer() {
      const x = player.x - camera.x;
      const y = player.y - camera.y;

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 6, 16, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body colors by animation frame
      const frameColors = ["#ffcc66", "#ffd98a", "#ffbf4d", "#ffd98a"];
      const bodyColor = frameColors[player.animFrame];

      // Body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(x, y, player.w, player.h);

      // Head
      ctx.fillStyle = "#f2c18d";
      ctx.fillRect(x + 6, y + 4, 22, 14);

      // Eyes
      ctx.fillStyle = "#222";
      const eyeX = player.facing === 1 ? x + 20 : x + 10;
      ctx.fillRect(eyeX, y + 9, 3, 3);

      // Legs
      ctx.fillStyle = "#3b2f2f";
      ctx.fillRect(x + 6, y + 34, 8, 10);
      ctx.fillRect(x + 20, y + 34, 8, 10);

      // Outline
      ctx.strokeStyle = "#1f1f1f";
      ctx.strokeRect(x, y, player.w, player.h);
    }

    function drawBackground() {
      // Simple parallax clouds
      const cloudOffset = camera.x * 0.3;
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 8; i++) {
        const cx = ((i * 260) - (cloudOffset % 260)) - 50;
        const cy = 60 + (i % 3) * 50;
        ctx.beginPath();
        ctx.ellipse(cx, cy, 40, 18, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 28, cy - 8, 32, 16, 0, 0, Math.PI * 2);
        ctx.ellipse(cx + 55, cy, 38, 18, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      // Draw platforms
      for (const p of world.platforms) {
        drawPlatform(p);
      }

      drawPlayer();

      // Debug info
      ctx.fillStyle = "rgba(0,0,0,0.5)";
      ctx.fillRect(10, canvas.height - 60, 250, 50);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 20, canvas.height - 35);
      ctx.fillText(`vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)}`, 20, canvas.height - 15);
    }

    let lastTime = performance.now();
    function gameLoop(now) {
      const dt = Math.min((now - lastTime) / 1000, 1 / 30);
      lastTime = now;

      updatePlayer(dt);
      updateCamera();
      render();

      requestAnimationFrame(gameLoop);
    }

    requestAnimationFrame(gameLoop);
  </script>
</body>
</html>
```

