Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer Prototype</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #cfefff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 8px;
      font-size: 14px;
      line-height: 1.4;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Controls: A/D or Arrow Keys = Move, Space/W/Up = Jump
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    // --- Input ---
    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.key.toLowerCase()] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.key.toLowerCase()] = false;
    });

    // --- World / Level ---
    const TILE_SIZE = 48;

    // 0 = empty, 1 = solid block
    const level = [
      "........................................................",
      "........................................................",
      "........................................................",
      "........................................................",
      ".......................###..............................",
      "........................................................",
      ".............###........................................",
      "........................................................",
      "....###.................................................",
      ".............................................###........",
      "........................................................",
      "..................###...................................",
      "........................................................",
      "###############################..............###########",
      "###############################..............###########"
    ];

    const world = [];
    for (let y = 0; y < level.length; y++) {
      for (let x = 0; x < level[y].length; x++) {
        if (level[y][x] === "#") {
          world.push({
            x: x * TILE_SIZE,
            y: y * TILE_SIZE,
            w: TILE_SIZE,
            h: TILE_SIZE
          });
        }
      }
    }

    // --- Player ---
    const player = {
      x: 100,
      y: 100,
      w: 34,
      h: 46,
      vx: 0,
      vy: 0,
      speed: 0.7,
      maxSpeed: 5,
      jumpPower: 14,
      gravity: 0.7,
      friction: 0.82,
      onGround: false,
      facing: 1,
      state: "idle",
      animTime: 0
    };

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    // --- Animation frames (simple placeholder sprite frames) ---
    // In a real game, replace these with image spritesheets.
    const animations = {
      idle: [
        { color: "#ffcc66", offsetY: 0 },
        { color: "#ffd27f", offsetY: 1 }
      ],
      run: [
        { color: "#ffb84d", offsetY: 0 },
        { color: "#ffcc66", offsetY: 2 },
        { color: "#ffd27f", offsetY: 0 },
        { color: "#ffcc66", offsetY: 2 }
      ],
      jump: [
        { color: "#ff9966", offsetY: -2 }
      ],
      fall: [
        { color: "#ff9966", offsetY: 2 }
      ]
    };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function resolveCollisions(entity, solids) {
      entity.onGround = false;

      // Horizontal
      entity.x += entity.vx;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vx > 0) {
            entity.x = s.x - entity.w;
          } else if (entity.vx < 0) {
            entity.x = s.x + s.w;
          }
          entity.vx = 0;
        }
      }

      // Vertical
      entity.y += entity.vy;
      for (const s of solids) {
        if (rectsOverlap(entity, s)) {
          if (entity.vy > 0) {
            entity.y = s.y - entity.h;
            entity.onGround = true;
          } else if (entity.vy < 0) {
            entity.y = s.y + s.h;
          }
          entity.vy = 0;
        }
      }
    }

    function updatePlayer() {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      // Horizontal movement
      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Clamp speed
      player.vx = Math.max(-player.maxSpeed, Math.min(player.maxSpeed, player.vx));

      // Jump
      if (jump && player.onGround && !player.jumpHeld) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }
      player.jumpHeld = jump;

      // Gravity
      player.vy += player.gravity;
      if (player.vy > 18) player.vy = 18;

      // Friction
      if (player.onGround) {
        player.vx *= player.friction;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      }

      resolveCollisions(player, world);

      // State selection
      if (!player.onGround) {
        player.state = player.vy < 0 ? "jump" : "fall";
      } else if (Math.abs(player.vx) > 0.3) {
        player.state = "run";
      } else {
        player.state = "idle";
      }

      player.animTime += 0.15;
    }

    function updateCamera() {
      camera.x = player.x + player.w / 2 - canvas.width / 2;
      camera.y = player.y + player.h / 2 - canvas.height / 2;

      // Clamp camera to level bounds
      const levelWidth = level[0].length * TILE_SIZE;
      const levelHeight = level.length * TILE_SIZE;

      camera.x = Math.max(0, Math.min(camera.x, levelWidth - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, levelHeight - canvas.height));
    }

    function drawWorld() {
      // Background parallax-ish hills
      ctx.fillStyle = "#7ec850";
      ctx.fillRect(0, canvas.height - 120, canvas.width, 120);

      // Tiles
      for (const s of world) {
        const x = s.x - camera.x;
        const y = s.y - camera.y;

        ctx.fillStyle = "#5b3a29";
        ctx.fillRect(x, y, s.w, s.h);

        ctx.fillStyle = "#7a4d35";
        ctx.fillRect(x + 4, y + 4, s.w - 8, s.h - 8);

        ctx.strokeStyle = "rgba(255,255,255,0.08)";
        ctx.strokeRect(x, y, s.w, s.h);
      }
    }

    function drawPlayer() {
      const anim = animations[player.state];
      const frame = anim[Math.floor(player.animTime) % anim.length];

      const x = player.x - camera.x;
      const y = player.y - camera.y + frame.offsetY;

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 6, 18, 6, 0, 0, Math.PI * 2);
      ctx.fill();

      // Body
      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      ctx.fillStyle = frame.color;
      ctx.fillRect(0, 0, player.w, player.h);

      // Head
      ctx.fillStyle = "#ffe0bd";
      ctx.fillRect(6, 6, player.w - 12, 14);

      // Eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(11, 11, 3, 3);
      ctx.fillRect(player.w - 14, 11, 3, 3);

      // Legs / motion detail
      ctx.fillStyle = "#333";
      if (player.state === "run") {
        const legOffset = Math.sin(player.animTime * 2) * 3;
        ctx.fillRect(8, 34, 6, 12 + legOffset);
        ctx.fillRect(20, 34, 6, 12 - legOffset);
      } else {
        ctx.fillRect(8, 34, 6, 12);
        ctx.fillRect(20, 34, 6, 12);
      }

      ctx.restore();
    }

    function drawDebug() {
      ctx.fillStyle = "rgba(0,0,0,0.35)";
      ctx.fillRect(10, canvas.height - 70, 260, 60);
      ctx.fillStyle = "white";
      ctx.font = "14px sans-serif";
      ctx.fillText(`x: ${player.x.toFixed(1)} y: ${player.y.toFixed(1)}`, 20, canvas.height - 45);
      ctx.fillText(`vx: ${player.vx.toFixed(1)} vy: ${player.vy.toFixed(1)} state: ${player.state}`, 20, canvas.height - 25);
    }

    function gameLoop() {
      updatePlayer();
      updateCamera();

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawWorld();
      drawPlayer();
      drawDebug();

      requestAnimationFrame(gameLoop);
    }

    gameLoop();
  </script>
</body>
</html>
