## `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

const TILE_SIZE = 32;
const GRAVITY = 2200;
const MOVE_SPEED = 420;
const JUMP_SPEED = 820;
const FRICTION = 0.82;
const AIR_FRICTION = 0.94;
const MAX_FALL_SPEED = 1400;

const keys = new Set();
window.addEventListener("keydown", (e) => keys.add(e.code));
window.addEventListener("keyup", (e) => keys.delete(e.code));

const level = [
  "................................................................",
  "................................................................",
  "................................................................",
  "................................................................",
  "................................................................",
  "....................###.........................................",
  "..............................................###...............",
  ".............###................................................",
  "....................................###..........................",
  ".........................###....................................",
  "..............P.................................................",
  "###############################..............###################",
  "###############################..............###################",
];

const world = {
  width: level[0].length,
  height: level.length,
  tiles: level.map(row => row.split(""))
};

function isSolidTile(tx, ty) {
  if (ty < 0 || ty >= world.height || tx < 0 || tx >= world.width) return false;
  return world.tiles[ty][tx] === "#";
}

function rectIntersectsTile(x, y, w, h, tx, ty) {
  const tileX = tx * TILE_SIZE;
  const tileY = ty * TILE_SIZE;
  return x < tileX + TILE_SIZE &&
         x + w > tileX &&
         y < tileY + TILE_SIZE &&
         y + h > tileY;
}

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 24;
    this.h = 32;
    this.vx = 0;
    this.vy = 0;
    this.onGround = false;
    this.facing = 1;
    this.animTime = 0;
    this.animFrame = 0;
  }

  update(dt) {
    const left = keys.has("ArrowLeft") || keys.has("KeyA");
    const right = keys.has("ArrowRight") || keys.has("KeyD");
    const jump = keys.has("Space") || keys.has("ArrowUp") || keys.has("KeyW");

    if (left && !right) {
      this.vx -= MOVE_SPEED * dt;
      this.facing = -1;
    } else if (right && !left) {
      this.vx += MOVE_SPEED * dt;
      this.facing = 1;
    } else {
      this.vx *= this.onGround ? FRICTION : AIR_FRICTION;
    }

    this.vx = Math.max(-MOVE_SPEED, Math.min(MOVE_SPEED, this.vx));

    if (jump && this.onGround && !this._jumpHeld) {
      this.vy = -JUMP_SPEED;
      this.onGround = false;
    }
    this._jumpHeld = jump;

    this.vy += GRAVITY * dt;
    this.vy = Math.min(this.vy, MAX_FALL_SPEED);

    this.moveAndCollide(dt);

    this.animTime += dt;
    if (Math.abs(this.vx) > 20 && this.onGround) {
      this.animFrame = Math.floor(this.animTime * 12) % 4;
    } else {
      this.animFrame = 0;
    }
  }

  moveAndCollide(dt) {
    // Horizontal
    this.x += this.vx * dt;
    let minTx = Math.floor(this.x / TILE_SIZE);
    let maxTx = Math.floor((this.x + this.w) / TILE_SIZE);
    let minTy = Math.floor(this.y / TILE_SIZE);
    let maxTy = Math.floor((this.y + this.h) / TILE_SIZE);

    for (let ty = minTy; ty <= maxTy; ty++) {
      for (let tx = minTx; tx <= maxTx; tx++) {
        if (!isSolidTile(tx, ty)) continue;
        if (rectIntersectsTile(this.x, this.y, this.w, this.h, tx, ty)) {
          const tileX = tx * TILE_SIZE;
          if (this.vx > 0) this.x = tileX - this.w;
          else if (this.vx < 0) this.x = tileX + TILE_SIZE;
          this.vx = 0;
        }
      }
    }

    // Vertical
    this.y += this.vy * dt;
    this.onGround = false;

    minTx = Math.floor(this.x / TILE_SIZE);
    maxTx = Math.floor((this.x + this.w) / TILE_SIZE);
    minTy = Math.floor(this.y / TILE_SIZE);
    maxTy = Math.floor((this.y + this.h) / TILE_SIZE);

    for (let ty = minTy; ty <= maxTy; ty++) {
      for (let tx = minTx; tx <= maxTx; tx++) {
        if (!isSolidTile(tx, ty)) continue;
        if (rectIntersectsTile(this.x, this.y, this.w, this.h, tx, ty)) {
          const tileY = ty * TILE_SIZE;
          if (this.vy > 0) {
            this.y = tileY - this.h;
            this.vy = 0;
            this.onGround = true;
          } else if (this.vy < 0) {
            this.y = tileY + TILE_SIZE;
            this.vy = 0;
          }
        }
      }
    }
  }

  draw(ctx, cameraX, cameraY) {
    const x = Math.floor(this.x - cameraX);
    const y = Math.floor(this.y - cameraY);

    // Simple animated sprite placeholder
    const frame = this.animFrame;
    const bob = this.onGround ? Math.sin(this.animTime * 10) * 1.5 : 0;

    // Shadow
    ctx.fillStyle = "rgba(0,0,0,0.2)";
    ctx.beginPath();
    ctx.ellipse(x + this.w / 2, y + this.h + 6, 12, 4, 0, 0, Math.PI * 2);
    ctx.fill();

    // Body
    ctx.fillStyle = "#2c3e50";
    ctx.fillRect(x, y + bob, this.w, this.h);

    // Face / direction indicator
    ctx.fillStyle = "#ecf0f1";
    const eyeX = this.facing === 1 ? x + 16 : x + 6;
    ctx.fillRect(eyeX, y + 8 + bob, 4, 4);

    // Legs animation
    ctx.fillStyle = "#e67e22";
    if (this.onGround && Math.abs(this.vx) > 20) {
      const legOffset = frame % 2 === 0 ? 0 : 4;
      ctx.fillRect(x + 4, y + 26 + bob, 6, 6);
      ctx.fillRect(x + 14 + legOffset, y + 26 + bob, 6, 6);
    } else {
      ctx.fillRect(x + 4, y + 26 + bob, 6, 6);
      ctx.fillRect(x + 14, y + 26 + bob, 6, 6);
    }
  }
}

const spawn = findSpawn();
const player = new Player(spawn.x, spawn.y);

function findSpawn() {
  for (let y = 0; y < world.height; y++) {
    for (let x = 0; x < world.width; x++) {
      if (world.tiles[y][x] === "P") {
        return { x: x * TILE_SIZE, y: y * TILE_SIZE - 32 };
      }
    }
  }
  return { x: 100, y: 100 };
}

let cameraX = 0;
let cameraY = 0;
let lastTime = performance.now();

function drawTile(x, y, type) {
  const px = x * TILE_SIZE - cameraX;
  const py = y * TILE_SIZE - cameraY;

  if (type === "#") {
    ctx.fillStyle = "#5d6d7e";
    ctx.fillRect(px, py, TILE_SIZE, TILE_SIZE);

    ctx.fillStyle = "#7f8c8d";
    ctx.fillRect(px + 2, py + 2, TILE_SIZE - 4, TILE_SIZE - 4);

    ctx.fillStyle = "rgba(255,255,255,0.08)";
    ctx.fillRect(px, py, TILE_SIZE, 4);
  }
}

function update(dt) {
  player.update(dt);

  cameraX = player.x + player.w / 2 - canvas.width / 2;
  cameraY = player.y + player.h / 2 - canvas.height / 2;

  const maxCameraX = world.width * TILE_SIZE - canvas.width;
  const maxCameraY = world.height * TILE_SIZE - canvas.height;
  cameraX = Math.max(0, Math.min(maxCameraX, cameraX));
  cameraY = Math.max(0, Math.min(maxCameraY, cameraY));
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Parallax clouds
  ctx.fillStyle = "rgba(255,255,255,0.35)";
  for (let i = 0; i < 8; i++) {
    const cx = (i * 220 - cameraX * 0.2) % (canvas.width + 260) - 130;
    const cy = 60 + (i % 3) * 50;
    ctx.beginPath();
    ctx.ellipse(cx, cy, 40, 18, 0, 0, Math.PI * 2);
    ctx.ellipse(cx + 28, cy + 4, 34, 15, 0, 0, Math.PI * 2);
    ctx.ellipse(cx - 28, cy + 6, 30, 14, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // Tiles
  for (let y = 0; y < world.height; y++) {
    for (let x = 0; x < world.width; x++) {
      const t = world.tiles[y][x];
      if (t === "#") drawTile(x, y, t);
    }
  }

  player.draw(ctx, cameraX, cameraY);

  // HUD
  ctx.fillStyle = "rgba(0,0,0,0.5)";
  ctx.fillRect(12, 12, 240, 54);
  ctx.fillStyle = "#fff";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys", 24, 34);
  ctx.fillText("Jump: Space / W / Up", 24, 54);
}

function loop(now) {
  const dt = Math.min(0.033, (now - lastTime) / 1000);
  lastTime = now;

  update(dt);
  render();

  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
```

