## `game.js`

```javascript
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

const GRAVITY = 1800;
const MOVE_SPEED = 300;
const JUMP_FORCE = 700;
const FRICTION = 0.85;
const DT_CAP = 1 / 30;

const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

class Platform {
  constructor(x, y, w, h) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
  }

  draw(ctx, cameraX = 0, cameraY = 0) {
    ctx.fillStyle = "#4b6b3c";
    ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);
    ctx.fillStyle = "#6f8f4f";
    ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, 8);
  }
}

class SpriteAnimation {
  constructor(image, frameWidth, frameHeight, frameCount, frameSpeed = 0.12) {
    this.image = image;
    this.frameWidth = frameWidth;
    this.frameHeight = frameHeight;
    this.frameCount = frameCount;
    this.frameSpeed = frameSpeed;
    this.currentFrame = 0;
    this.timer = 0;
  }

  update(dt) {
    this.timer += dt;
    if (this.timer >= this.frameSpeed) {
      this.timer = 0;
      this.currentFrame = (this.currentFrame + 1) % this.frameCount;
    }
  }

  draw(ctx, x, y, w, h, flip = false) {
    const sx = this.currentFrame * this.frameWidth;
    const sy = 0;

    ctx.save();
    if (flip) {
      ctx.translate(x + w, y);
      ctx.scale(-1, 1);
      ctx.drawImage(this.image, sx, sy, this.frameWidth, this.frameHeight, 0, 0, w, h);
    } else {
      ctx.drawImage(this.image, sx, sy, this.frameWidth, this.frameHeight, x, y, w, h);
    }
    ctx.restore();
  }
}

class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.w = 48;
    this.h = 64;

    this.vx = 0;
    this.vy = 0;
    this.onGround = false;
    this.facing = 1;

    this.animations = {
      idle: null,
      run: null,
      jump: null,
    };
    this.currentAnimation = null;
  }

  setAnimations(anims) {
    this.animations = anims;
    this.currentAnimation = this.animations.idle;
  }

  update(dt, platforms) {
    // Horizontal movement
    if (keys.left) {
      this.vx = -MOVE_SPEED;
      this.facing = -1;
    } else if (keys.right) {
      this.vx = MOVE_SPEED;
      this.facing = 1;
    } else {
      this.vx *= FRICTION;
      if (Math.abs(this.vx) < 1) this.vx = 0;
    }

    // Jump
    if (keys.jump && this.onGround) {
      this.vy = -JUMP_FORCE;
      this.onGround = false;
    }

    // Gravity
    this.vy += GRAVITY * dt;

    // Move and collide X
    this.x += this.vx * dt;
    this.resolveCollisionsX(platforms);

    // Move and collide Y
    this.y += this.vy * dt;
    this.onGround = false;
    this.resolveCollisionsY(platforms);

    // Animation state
    if (!this.onGround) {
      this.currentAnimation = this.animations.jump;
    } else if (Math.abs(this.vx) > 10) {
      this.currentAnimation = this.animations.run;
    } else {
      this.currentAnimation = this.animations.idle;
    }

    if (this.currentAnimation) this.currentAnimation.update(dt);
  }

  resolveCollisionsX(platforms) {
    for (const p of platforms) {
      if (this.intersects(p)) {
        if (this.vx > 0) {
          this.x = p.x - this.w;
        } else if (this.vx < 0) {
          this.x = p.x + p.w;
        }
        this.vx = 0;
      }
    }
  }

  resolveCollisionsY(platforms) {
    for (const p of platforms) {
      if (this.intersects(p)) {
        if (this.vy > 0) {
          this.y = p.y - this.h;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.h;
          this.vy = 0;
        }
      }
    }
  }

  intersects(p) {
    return (
      this.x < p.x + p.w &&
      this.x + this.w > p.x &&
      this.y < p.y + p.h &&
      this.y + this.h > p.y
    );
  }

  draw(ctx, cameraX = 0, cameraY = 0) {
    if (this.currentAnimation) {
      this.currentAnimation.draw(
        ctx,
        this.x - cameraX,
        this.y - cameraY,
        this.w,
        this.h,
        this.facing === -1
      );
    } else {
      ctx.fillStyle = "red";
      ctx.fillRect(this.x - cameraX, this.y - cameraY, this.w, this.h);
    }
  }
}

// --- Assets ---
function loadImage(src) {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.src = src;
  });
}

// --- Game setup ---
const platforms = [
  new Platform(0, 500, 2000, 40),
  new Platform(200, 400, 180, 20),
  new Platform(450, 340, 180, 20),
  new Platform(720, 280, 180, 20),
  new Platform(980, 380, 220, 20),
  new Platform(1280, 320, 220, 20),
];

const player = new Player(100, 300);

let cameraX = 0;
let cameraY = 0;

let lastTime = 0;

async function init() {
  // Replace these with your own sprite sheets
  const idleImg = await loadImage("assets/player_idle.png");
  const runImg = await loadImage("assets/player_run.png");
  const jumpImg = await loadImage("assets/player_jump.png");

  player.setAnimations({
    idle: new SpriteAnimation(idleImg, 48, 64, 4, 0.18),
    run: new SpriteAnimation(runImg, 48, 64, 6, 0.10),
    jump: new SpriteAnimation(jumpImg, 48, 64, 1, 0.20),
  });

  requestAnimationFrame(loop);
}

function loop(timestamp) {
  const dt = Math.min((timestamp - lastTime) / 1000, DT_CAP) || 0;
  lastTime = timestamp;

  update(dt);
  render();

  requestAnimationFrame(loop);
}

function update(dt) {
  player.update(dt, platforms);

  // Camera follows player
  cameraX = player.x - canvas.width / 2 + player.w / 2;
  cameraY = player.y - canvas.height / 2 + player.h / 2;

  // Clamp camera
  cameraX = Math.max(0, Math.min(cameraX, 2000 - canvas.width));
  cameraY = Math.max(0, Math.min(cameraY, 540 - canvas.height));
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Background hills / clouds
  drawBackground();

  // Platforms
  for (const p of platforms) {
    p.draw(ctx, cameraX, cameraY);
  }

  // Player
  player.draw(ctx, cameraX, cameraY);

  // HUD
  ctx.fillStyle = "#000";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 20, 30);
}

function drawBackground() {
  // simple parallax-like shapes
  ctx.fillStyle = "rgba(255,255,255,0.5)";
  ctx.beginPath();
  ctx.arc(120 - cameraX * 0.2, 90, 30, 0, Math.PI * 2);
  ctx.arc(150 - cameraX * 0.2, 90, 40, 0, Math.PI * 2);
  ctx.arc(180 - cameraX * 0.2, 90, 30, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "rgba(120, 200, 120, 0.35)";
  ctx.fillRect(0, 470, canvas.width, 70);
}

init().catch((err) => {
  console.error("Failed to initialize game:", err);
});
```

