Save this as `index.html` and open it in a browser:

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer Prototype</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 1px 2px black;
      font-size: 14px;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or ←/→ | Jump: Space / W / ↑
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", (e) => keys[e.key.toLowerCase()] = true);
    window.addEventListener("keyup", (e) => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 1800,
      cameraX: 0,
      cameraY: 0
    };

    class Platform {
      constructor(x, y, w, h) {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
      }

      draw() {
        ctx.fillStyle = "#4b3f2f";
        ctx.fillRect(this.x - world.cameraX, this.y - world.cameraY, this.w, this.h);
        ctx.fillStyle = "#6b5b45";
        ctx.fillRect(this.x - world.cameraX, this.y - world.cameraY, this.w, 8);
      }
    }

    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.w = 48;
        this.h = 64;
        this.vx = 0;
        this.vy = 0;
        this.speed = 420;
        this.jumpPower = 760;
        this.onGround = false;
        this.facing = 1;
        this.animTime = 0;
        this.state = "idle";
      }

      update(dt, platforms) {
        const left = keys["a"] || keys["arrowleft"];
        const right = keys["d"] || keys["arrowright"];
        const jump = keys[" "] || keys["w"] || keys["arrowup"];

        // Horizontal movement
        if (left) {
          this.vx = -this.speed;
          this.facing = -1;
        } else if (right) {
          this.vx = this.speed;
          this.facing = 1;
        } else {
          this.vx *= 0.82; // friction
          if (Math.abs(this.vx) < 10) this.vx = 0;
        }

        // Jump
        if (jump && this.onGround) {
          this.vy = -this.jumpPower;
          this.onGround = false;
        }

        // Gravity
        this.vy += world.gravity * dt;

        // Move X and resolve collisions
        this.x += this.vx * dt;
        for (const p of platforms) {
          if (this.intersects(p)) {
            if (this.vx > 0) this.x = p.x - this.w;
            else if (this.vx < 0) this.x = p.x + p.w;
            this.vx = 0;
          }
        }

        // Move Y and resolve collisions
        this.y += this.vy * dt;
        this.onGround = false;
        for (const p of platforms) {
          if (this.intersects(p)) {
            if (this.vy > 0) {
              this.y = p.y - this.h;
              this.vy = 0;
              this.onGround = true;
            } else if (this.vy < 0) {
              this.y = p.y + p.h;
              this.vy = 0;
            }
          }
        }

        // Animation state
        if (!this.onGround) {
          this.state = "jump";
        } else if (Math.abs(this.vx) > 20) {
          this.state = "run";
        } else {
          this.state = "idle";
        }

        this.animTime += dt;
      }

      intersects(obj) {
        return !(
          this.x + this.w < obj.x ||
          this.x > obj.x + obj.w ||
          this.y + this.h < obj.y ||
          this.y > obj.y + obj.h
        );
      }

      draw() {
        const x = this.x - world.cameraX;
        const y = this.y - world.cameraY;

        // Simple animated sprite placeholder
        const frame = Math.floor(this.animTime * 10) % 4;

        // Body
        ctx.save();
        ctx.translate(x + this.w / 2, y + this.h / 2);
        ctx.scale(this.facing, 1);
        ctx.translate(-this.w / 2, -this.h / 2);

        // Shadow
        ctx.fillStyle = "rgba(0,0,0,0.2)";
        ctx.beginPath();
        ctx.ellipse(this.w / 2, this.h + 8, 22, 8, 0, 0, Math.PI * 2);
        ctx.fill();

        // Sprite colors by state
        let bodyColor = "#ffcc66";
        let shirtColor = "#3366ff";
        let legColor = "#333333";

        if (this.state === "jump") {
          bodyColor = "#ffd27f";
          shirtColor = "#4d79ff";
        } else if (this.state === "run") {
          bodyColor = frame % 2 === 0 ? "#ffcc66" : "#ffd98a";
          shirtColor = frame % 2 === 0 ? "#3366ff" : "#2f5be0";
        }

        // Head
        ctx.fillStyle = bodyColor;
        ctx.fillRect(14, 6, 20, 18);
        ctx.fillRect(12, 18, 24, 18);

        // Torso
        ctx.fillStyle = shirtColor;
        ctx.fillRect(12, 28, 24, 18);

        // Legs
        ctx.fillStyle = legColor;
        if (this.state === "run") {
          if (frame % 2 === 0) {
            ctx.fillRect(12, 46, 10, 16);
            ctx.fillRect(26, 46, 10, 12);
          } else {
            ctx.fillRect(12, 46, 10, 12);
            ctx.fillRect(26, 46, 10, 16);
          }
        } else {
          ctx.fillRect(12, 46, 10, 16);
          ctx.fillRect(26, 46, 10, 16);
        }

        // Arms
        ctx.fillStyle = bodyColor;
        if (this.state === "run") {
          if (frame % 2 === 0) {
            ctx.fillRect(4, 30, 8, 14);
            ctx.fillRect(36, 30, 8, 10);
          } else {
            ctx.fillRect(4, 30, 8, 10);
            ctx.fillRect(36, 30, 8, 14);
          }
        } else {
          ctx.fillRect(4, 30, 8, 14);
          ctx.fillRect(36, 30, 8, 14);
        }

        // Eyes
        ctx.fillStyle = "#111";
        ctx.fillRect(18, 12, 3, 3);
        ctx.fillRect(27, 12, 3, 3);

        ctx.restore();
      }
    }

    const platforms = [
      new Platform(-200, 520, 1600, 80),
      new Platform(150, 420, 180, 20),
      new Platform(420, 360, 180, 20),
      new Platform(700, 300, 180, 20),
      new Platform(980, 380, 220, 20),
      new Platform(1280, 460, 180, 20),
      new Platform(1550, 400, 220, 20),
      new Platform(1850, 330, 180, 20),
    ];

    const player = new Player(100, 200);

    let lastTime = performance.now();

    function update(dt) {
      player.update(dt, platforms);

      // Camera follows player
      world.cameraX = player.x + player.w / 2 - canvas.width / 2;
      world.cameraY = player.y + player.h / 2 - canvas.height / 2;

      // Clamp camera
      world.cameraX = Math.max(-200, world.cameraX);
      world.cameraY = Math.max(-100, world.cameraY);
    }

    function drawBackground() {
      // Parallax clouds
      ctx.fillStyle = "#87ceeb";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const cloudOffset = world.cameraX * 0.2;
      for (let i = 0; i < 8; i++) {
        const x = (i * 260 - (cloudOffset % 260)) - 100;
        const y = 60 + (i % 3) * 40;
        drawCloud(x, y);
      }

      // Distant hills
      ctx.fillStyle = "#7fc97f";
      for (let i = 0; i < 6; i++) {
        const x = i * 400 - (world.cameraX * 0.5 % 400) - 100;
        ctx.beginPath();
        ctx.ellipse(x + 200, canvas.height - 80, 180, 90, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawCloud(x, y) {
      ctx.fillStyle = "rgba(255,255,255,0.85)";
      ctx.beginPath();
      ctx.ellipse(x + 30, y + 20, 30, 18, 0, 0, Math.PI * 2);
      ctx.ellipse(x + 60, y + 18, 38, 22, 0, 0, Math.PI * 2);
      ctx.ellipse(x + 95, y + 22, 28, 16, 0, 0, Math.PI * 2);
      ctx.fill();
    }

    function render() {
      drawBackground();

      // Platforms
      for (const p of platforms) p.draw();

      // Player
      player.draw();

      // Debug ground line
      ctx.strokeStyle = "rgba(0,0,0,0.1)";
      ctx.beginPath();
      ctx.moveTo(-1000 - world.cameraX, 520 - world.cameraY);
      ctx.lineTo(4000 - world.cameraX, 520 - world.cameraY);
      ctx.stroke();
    }

    function loop(now) {
      const dt = Math.min((now - lastTime) / 1000, 0.033);
      lastTime = now;

      update(dt);
      render();

      requestAnimationFrame(loop);
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

