## `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>2D Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1d1f27;
      width: 100%;
      height: 100%;
      font-family: sans-serif;
    }

    canvas {
      display: block;
      background: linear-gradient(#87ceeb, #dff6ff);
    }

    .hud {
      position: fixed;
      top: 12px;
      left: 12px;
      color: white;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      font-size: 14px;
      user-select: none;
      pointer-events: none;
    }
  </style>
</head>
<body>
  <div class="hud">
    Move: A/D or ←/→ | Jump: Space/W/↑
  </div>
  <canvas id="game"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    function resize() {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    }
    window.addEventListener("resize", resize);
    resize();

    const keys = {};
    window.addEventListener("keydown", (e) => {
      keys[e.code] = true;
    });
    window.addEventListener("keyup", (e) => {
      keys[e.code] = false;
    });

    const world = {
      gravity: 2200,
      friction: 0.82,
      airDrag: 0.98,
      cameraX: 0,
      cameraY: 0
    };

    class Platform {
      constructor(x, y, w, h, color = "#4b5563") {
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
        this.color = color;
      }

      draw(ctx, cameraX, cameraY) {
        ctx.fillStyle = this.color;
        ctx.fillRect(
          Math.floor(this.x - cameraX),
          Math.floor(this.y - cameraY),
          this.w,
          this.h
        );
      }
    }

    class Player {
      constructor(x, y) {
        this.x = x;
        this.y = y;
        this.w = 48;
        this.h = 64;

        this.vx = 0;
        this.vy = 0;

        this.speed = 650;
        this.jumpPower = 900;
        this.onGround = false;

        this.facing = 1; // 1 right, -1 left
        this.animTime = 0;
        this.state = "idle";

        // Simple sprite sheet-like animation using generated frames
        this.frames = {
          idle: this.makeFrames("#f59e0b", "#fbbf24", 4),
          run: this.makeFrames("#22c55e", "#86efac", 6),
          jump: this.makeFrames("#3b82f6", "#93c5fd", 2),
          fall: this.makeFrames("#ef4444", "#fca5a5", 2)
        };
      }

      makeFrames(primary, secondary, count) {
        const frames = [];
        for (let i = 0; i < count; i++) {
          const c = document.createElement("canvas");
          c.width = this.w;
          c.height = this.h;
          const g = c.getContext("2d");

          // body
          g.fillStyle = primary;
          g.fillRect(8, 10, 32, 44);

          // highlight
          g.fillStyle = secondary;
          g.fillRect(12, 14, 10, 10);

          // eyes
          g.fillStyle = "#111827";
          g.fillRect(18, 22, 4, 4);
          g.fillRect(28, 22, 4, 4);

          // legs/arms animation variation
          g.fillStyle = "#111827";
          const offset = i % 2 === 0 ? 0 : 4;
          g.fillRect(10, 50, 10, 4);
          g.fillRect(28, 50, 10, 4);
          g.fillRect(4, 22 + offset, 4, 12);
          g.fillRect(40, 22 - offset, 4, 12);

          frames.push(c);
        }
        return frames;
      }

      update(dt, platforms) {
        const left = keys["ArrowLeft"] || keys["KeyA"];
        const right = keys["ArrowRight"] || keys["KeyD"];
        const jump = keys["Space"] || keys["ArrowUp"] || keys["KeyW"];

        if (left) {
          this.vx -= this.speed * dt;
          this.facing = -1;
        }
        if (right) {
          this.vx += this.speed * dt;
          this.facing = 1;
        }

        if (!left && !right) {
          if (this.onGround) {
            this.vx *= world.friction;
          } else {
            this.vx *= world.airDrag;
          }
        }

        // Clamp horizontal speed
        this.vx = Math.max(-350, Math.min(350, this.vx));

        // Jump
        if (jump && this.onGround && !this.jumpPressed) {
          this.vy = -this.jumpPower;
          this.onGround = false;
        }
        this.jumpPressed = jump;

        // Apply gravity
        this.vy += world.gravity * dt;

        // Move and resolve collisions
        this.x += this.vx * dt;
        this.resolveCollisions(platforms, "x");

        this.y += this.vy * dt;
        this.resolveCollisions(platforms, "y");

        // Determine animation state
        if (!this.onGround) {
          this.state = this.vy < 0 ? "jump" : "fall";
        } else if (Math.abs(this.vx) > 40) {
          this.state = "run";
        } else {
          this.state = "idle";
        }

        this.animTime += dt;
      }

      resolveCollisions(platforms, axis) {
        this.onGround = false;

        for (const p of platforms) {
          if (
            this.x < p.x + p.w &&
            this.x + this.w > p.x &&
            this.y < p.y + p.h &&
            this.y + this.h > p.y
          ) {
            if (axis === "x") {
              if (this.vx > 0) {
                this.x = p.x - this.w;
              } else if (this.vx < 0) {
                this.x = p.x + p.w;
              }
              this.vx = 0;
            } else if (axis === "y") {
              if (this.vy > 0) {
                this.y = p.y - this.h;
                this.vy = 0;
                this.onGround = true;
              } else if (this.vy < 0) {
                this.y = p.y + p.h;
                this.vy = 0;
              }
            }
          }
        }
      }

      draw(ctx, cameraX, cameraY) {
        const frames = this.frames[this.state];
        const frameIndex = Math.floor(this.animTime * 10) % frames.length;
        const frame = frames[frameIndex];

        ctx.save();
        ctx.translate(Math.floor(this.x - cameraX), Math.floor(this.y - cameraY));

        if (this.facing === -1) {
          ctx.scale(-1, 1);
          ctx.drawImage(frame, -this.w, 0, this.w, this.h);
        } else {
          ctx.drawImage(frame, 0, 0, this.w, this.h);
        }

        ctx.restore();
      }
    }

    const platforms = [
      new Platform(-200, 520, 1800, 80, "#374151"),
      new Platform(150, 420, 160, 24, "#4b5563"),
      new Platform(380, 360, 160, 24, "#4b5563"),
      new Platform(620, 300, 160, 24, "#4b5563"),
      new Platform(900, 380, 220, 24, "#4b5563"),
      new Platform(1180, 460, 180, 24, "#4b5563"),
      new Platform(1450, 400, 200, 24, "#4b5563")
    ];

    const player = new Player(80, 200);

    function updateCamera() {
      const targetX = player.x + player.w / 2 - canvas.width / 2;
      const targetY = player.y + player.h / 2 - canvas.height / 2;

      world.cameraX += (targetX - world.cameraX) * 0.08;
      world.cameraY += (targetY - world.cameraY) * 0.08;

      // Keep camera from going too far above the world
      world.cameraY = Math.max(0, world.cameraY);
    }

    let lastTime = performance.now();

    function loop(now) {
      const dt = Math.min((now - lastTime) / 1000, 1 / 30);
      lastTime = now;

      player.update(dt, platforms);
      updateCamera();
      render();

      requestAnimationFrame(loop);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background parallax hills
      drawBackground();

      // Platforms
      for (const p of platforms) {
        p.draw(ctx, world.cameraX, world.cameraY);
      }

      // Player
      player.draw(ctx, world.cameraX, world.cameraY);

      // Ground shadow
      ctx.fillStyle = "rgba(0,0,0,0.15)";
      ctx.beginPath();
      ctx.ellipse(
        player.x - world.cameraX + player.w / 2,
        player.y - world.cameraY + player.h + 6,
        24,
        8,
        0,
        0,
        Math.PI * 2
      );
      ctx.fill();
    }

    function drawBackground() {
      const camX = world.cameraX * 0.3;
      const camY = world.cameraY * 0.15;

      // distant mountains
      ctx.fillStyle = "#93c5fd";
      for (let i = -1; i < 6; i++) {
        const baseX = i * 400 - (camX % 400);
        ctx.beginPath();
        ctx.moveTo(baseX, 500 - camY);
        ctx.lineTo(baseX + 100, 360 - camY);
        ctx.lineTo(baseX + 220, 500 - camY);
        ctx.closePath();
        ctx.fill();
      }

      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.75)";
      for (let i = 0; i < 5; i++) {
        const x = (i * 300 - (camX % 300)) + 100;
        const y = 80 + (i % 2) * 40;
        drawCloud(x, y);
      }
    }

    function drawCloud(x, y) {
      ctx.beginPath();
      ctx.arc(x, y, 20, 0, Math.PI * 2);
      ctx.arc(x + 20, y - 10, 26, 0, Math.PI * 2);
      ctx.arc(x + 45, y, 18, 0, Math.PI * 2);
      ctx.arc(x + 20, y + 10, 22, 0, Math.PI * 2);
      ctx.fill();
    }

    requestAnimationFrame(loop);
  </script>
</body>
</html>
```

