## 4) `game.js`

```javascript
const canvas = document.getElementById("gameCanvas");
const ctx = canvas.getContext("2d");

// =========================
// Input
// =========================
const keys = {
  left: false,
  right: false,
  jump: false,
};

window.addEventListener("keydown", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = true;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = true;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = true;
});

window.addEventListener("keyup", (e) => {
  if (e.code === "ArrowLeft" || e.code === "KeyA") keys.left = false;
  if (e.code === "ArrowRight" || e.code === "KeyD") keys.right = false;
  if (e.code === "Space" || e.code === "ArrowUp" || e.code === "KeyW") keys.jump = false;
});

// =========================
// Utility
// =========================
function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function rectsIntersect(a, b) {
  return (
    a.x < b.x + b.width &&
    a.x + a.width > b.x &&
    a.y < b.y + b.height &&
    a.y + a.height > b.y
  );
}

// =========================
// World / Level
// =========================
const gravity = 1800;
const platforms = [
  { x: 0, y: 500, width: 960, height: 40 },
  { x: 120, y: 400, width: 180, height: 20 },
  { x: 360, y: 330, width: 180, height: 20 },
  { x: 620, y: 260, width: 180, height: 20 },
  { x: 820, y: 180, width: 100, height: 20 },
];

// =========================
// Sprite Animation
// =========================
// For initial implementation, we use simple colored frames.
// Replace these with image sprites later.
class Animation {
  constructor(frames, frameDuration) {
    this.frames = frames;
    this.frameDuration = frameDuration;
    this.time = 0;
    this.currentFrame = 0;
  }

  update(dt) {
    this.time += dt;
    if (this.time >= this.frameDuration) {
      this.time = 0;
      this.currentFrame = (this.currentFrame + 1) % this.frames.length;
    }
  }

  getFrame() {
    return this.frames[this.currentFrame];
  }
}

// =========================
// Player
// =========================
class Player {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.width = 40;
    this.height = 56;

    this.vx = 0;
    this.vy = 0;

    this.speed = 420;
    this.jumpStrength = 720;
    this.onGround = false;

    this.facing = 1; // 1 = right, -1 = left

    this.animations = {
      idle: new Animation(["#ffcc66", "#ffd27f"], 0.25),
      run: new Animation(["#66ccff", "#4db8ff", "#66ccff"], 0.12),
      jump: new Animation(["#ff6666"], 0.2),
    };

    this.currentAnimation = this.animations.idle;
  }

  get bounds() {
    return {
      x: this.x,
      y: this.y,
      width: this.width,
      height: this.height,
    };
  }

  update(dt) {
    // Horizontal movement
    let move = 0;
    if (keys.left) move -= 1;
    if (keys.right) move += 1;

    if (move !== 0) {
      this.vx = move * this.speed;
      this.facing = move;
    } else {
      // friction
      const friction = this.onGround ? 0.82 : 0.96;
      this.vx *= friction;
      if (Math.abs(this.vx) < 5) this.vx = 0;
    }

    // Jump
    if (keys.jump && this.onGround) {
      this.vy = -this.jumpStrength;
      this.onGround = false;
    }

    // Gravity
    this.vy += gravity * dt;

    // Integrate position
    this.x += this.vx * dt;
    this.resolveHorizontalCollisions();

    this.y += this.vy * dt;
    this.onGround = false;
    this.resolveVerticalCollisions();

    // Keep inside world bounds
    this.x = clamp(this.x, 0, canvas.width - this.width);
    if (this.y > canvas.height + 200) {
      // respawn if falling off
      this.x = 80;
      this.y = 100;
      this.vx = 0;
      this.vy = 0;
    }

    // Animation selection
    if (!this.onGround) {
      this.currentAnimation = this.animations.jump;
    } else if (Math.abs(this.vx) > 20) {
      this.currentAnimation = this.animations.run;
    } else {
      this.currentAnimation = this.animations.idle;
    }

    this.currentAnimation.update(dt);
  }

  resolveHorizontalCollisions() {
    for (const p of platforms) {
      if (rectsIntersect(this.bounds, p)) {
        if (this.vx > 0) {
          this.x = p.x - this.width;
        } else if (this.vx < 0) {
          this.x = p.x + p.width;
        }
        this.vx = 0;
      }
    }
  }

  resolveVerticalCollisions() {
    for (const p of platforms) {
      if (rectsIntersect(this.bounds, p)) {
        if (this.vy > 0) {
          this.y = p.y - this.height;
          this.vy = 0;
          this.onGround = true;
        } else if (this.vy < 0) {
          this.y = p.y + p.height;
          this.vy = 0;
        }
      }
    }
  }

  draw(ctx) {
    const frameColor = this.currentAnimation.getFrame();

    // Body
    ctx.save();

    // Flip based on facing direction
    ctx.translate(this.x + this.width / 2, this.y + this.height / 2);
    ctx.scale(this.facing, 1);
    ctx.translate(-this.width / 2, -this.height / 2);

    // Shadow
    ctx.fillStyle = "rgba(0,0,0,0.15)";
    ctx.beginPath();
    ctx.ellipse(this.width / 2, this.height + 6, 18, 6, 0, 0, Math.PI * 2);
    ctx.fill();

    // Main sprite placeholder
    ctx.fillStyle = frameColor;
    ctx.fillRect(0, 0, this.width, this.height);

    // Face / details
    ctx.fillStyle = "#222";
    ctx.fillRect(10, 14, 6, 6);
    ctx.fillRect(24, 14, 6, 6);

    ctx.fillStyle = "#fff";
    ctx.fillRect(12, 38, 16, 6);

    ctx.restore();
  }
}

// =========================
// Game Setup
// =========================
const player = new Player(80, 100);

function drawPlatforms() {
  for (const p of platforms) {
    ctx.fillStyle = "#4b6b3c";
    ctx.fillRect(p.x, p.y, p.width, p.height);

    // top highlight
    ctx.fillStyle = "#6f8f57";
    ctx.fillRect(p.x, p.y, p.width, 5);
  }
}

function drawBackground() {
  // simple parallax-ish background hills
  ctx.fillStyle = "#b7e4c7";
  ctx.beginPath();
  ctx.arc(120, 520, 180, Math.PI, 0, true);
  ctx.arc(420, 520, 220, Math.PI, 0, true);
  ctx.arc(760, 520, 160, Math.PI, 0, true);
  ctx.fill();

  // clouds
  ctx.fillStyle = "rgba(255,255,255,0.75)";
  const clouds = [
    [120, 90], [340, 60], [680, 100], [820, 70]
  ];
  for (const [x, y] of clouds) {
    ctx.beginPath();
    ctx.arc(x, y, 18, 0, Math.PI * 2);
    ctx.arc(x + 20, y - 8, 24, 0, Math.PI * 2);
    ctx.arc(x + 44, y, 18, 0, Math.PI * 2);
    ctx.fill();
  }
}

// =========================
// Main Loop
// =========================
let lastTime = 0;

function update(timestamp) {
  const dt = Math.min((timestamp - lastTime) / 1000, 0.033);
  lastTime = timestamp;

  player.update(dt);
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawBackground();
  drawPlatforms();
  player.draw(ctx);

  // HUD
  ctx.fillStyle = "#111";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: Space/W/Up", 20, 30);
}

function loop(timestamp) {
  update(timestamp);
  render();
  requestAnimationFrame(loop);
}

requestAnimationFrame(loop);
```

