    window.addEventListener("keydown", (e) => keys.add(e.code));
    window.addEventListener("keyup", (e) => keys.delete(e.code));

    // --- World ---
    const TILE_SIZE = 48;
    const levelWidth = 60;
    const levelHeight = 20;

    // 0 = empty, 1 = solid
    const level = Array.from({ length: levelHeight }, () =>
      Array(levelWidth).fill(0)
    );

    // Ground
    for (let x = 0; x < levelWidth; x++) {
      level[levelHeight - 1][x] = 1;
      if (x % 7 === 0) level[levelHeight - 5][x] = 1;
    }

    // Some platforms
    for (let x = 5; x < 12; x++) level[14][x] = 1;
    for (let x = 16; x < 22; x++) level[12][x] = 1;
    for (let x = 26; x < 34; x++) level[10][x] = 1;
    for (let x = 38; x < 45; x++) level[13][x] = 1;
    for (let x = 48; x < 55; x++) level[9][x] = 1;

    function isSolidTile(tx, ty) {
      if (ty < 0 || ty >= levelHeight || tx < 0 || tx >= levelWidth) return false;
      return level[ty][tx] === 1;
    }

    function rectIntersectsTile(x, y, w, h, tx, ty) {
      const tileX = tx * TILE_SIZE;
      const tileY = ty * TILE_SIZE;
      return (
        x < tileX + TILE_SIZE &&
        x + w > tileX &&
        y < tileY + TILE_SIZE &&
        y + h > tileY
      );
    }

    // --- Player ---
    const player = {
      x: 100,
      y: 100,
      w: 34,
      h: 44,
      vx: 0,
      vy: 0,
      speed: 0.55,
      maxSpeed: 5.2,
      jumpPower: 13.5,
      gravity: 0.65,
      friction: 0.82,
      onGround: false,
      facing: 1,
      state: "idle",
      animTime: 0
    };

    // --- Animation frames ---
    // Simple procedural sprite frames drawn on canvas.
    const animations = {
      idle: [
        { body: "#ffcc66", shirt: "#4f7cff", leg: "#333" },
        { body: "#ffd27f", shirt: "#4f7cff", leg: "#333" }
      ],
      run: [
        { body: "#ffcc66", shirt: "#4f7cff", leg: "#333", legOffset: 0 },
        { body: "#ffd27f", shirt: "#4f7cff", leg: "#333", legOffset: 2 },
        { body: "#ffcc66", shirt: "#4f7cff", leg: "#333", legOffset: 4 },
        { body: "#ffd27f", shirt: "#4f7cff", leg: "#333", legOffset: 2 }
      ],
      jump: [
        { body: "#ffcc66", shirt: "#4f7cff", leg: "#333" }
      ],
      fall: [
        { body: "#ffcc66", shirt: "#4f7cff", leg: "#333" }
      ]
    };

    function getPlayerState() {
      if (!player.onGround) {
        return player.vy < 0 ? "jump" : "fall";
      }
      if (Math.abs(player.vx) > 0.5) return "run";
      return "idle";
    }

    function updatePlayer() {
      const left = keys.has("ArrowLeft") || keys.has("KeyA");
      const right = keys.has("ArrowRight") || keys.has("KeyD");
      const jump = keys.has("Space") || keys.has("ArrowUp") || keys.has("KeyW");

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      // Clamp horizontal speed
      player.vx = Math.max(-player.maxSpeed, Math.min(player.maxSpeed, player.vx));

      // Jump
      if (jump && player.onGround && !player._jumpHeld) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }
      player._jumpHeld = jump;

      // Gravity
      player.vy += player.gravity;

      // Horizontal movement + collision
      player.x += player.vx;
      resolveCollisions("x");

      // Vertical movement + collision
      player.y += player.vy;
      player.onGround = false;
      resolveCollisions("y");

      // Friction
      if (player.onGround) {
        player.vx *= player.friction;
        if (Math.abs(player.vx) < 0.05) player.vx = 0;
      } else {
        player.vx *= 0.99;
      }

      player.state = getPlayerState();
      player.animTime += 1;
    }

    function resolveCollisions(axis) {
      const minTx = Math.floor(player.x / TILE_SIZE) - 1;
      const maxTx = Math.floor((player.x + player.w) / TILE_SIZE) + 1;
      const minTy = Math.floor(player.y / TILE_SIZE) - 1;
      const maxTy = Math.floor((player.y + player.h) / TILE_SIZE) + 1;

      for (let ty = minTy; ty <= maxTy; ty++) {
        for (let tx = minTx; tx <= maxTx; tx++) {
          if (!isSolidTile(tx, ty)) continue;

          const tileX = tx * TILE_SIZE;
          const tileY = ty * TILE_SIZE;

          if (
            player.x < tileX + TILE_SIZE &&
            player.x + player.w > tileX &&
            player.y < tileY + TILE_SIZE &&
            player.y + player.h > tileY
          ) {
            if (axis === "x") {
              if (player.vx > 0) {
                player.x = tileX - player.w;
              } else if (player.vx < 0) {
                player.x = tileX + TILE_SIZE;
              }
              player.vx = 0;
            } else if (axis === "y") {
              if (player.vy > 0) {
                player.y = tileY - player.h;
                player.vy = 0;
                player.onGround = true;
              } else if (player.vy < 0) {
                player.y = tileY + TILE_SIZE;
                player.vy = 0;
              }
            }
          }
        }
      }
    }

    // --- Camera ---
    const camera = {
      x: 0,
      y: 0
    };

    function updateCamera() {
      const targetX = player.x + player.w / 2 - canvas.width / 2;
      const targetY = player.y + player.h / 2 - canvas.height / 2;

      camera.x += (targetX - camera.x) * 0.08;
      camera.y += (targetY - camera.y) * 0.08;

      camera.x = Math.max(0, Math.min(camera.x, levelWidth * TILE_SIZE - canvas.width));
      camera.y = Math.max(0, Math.min(camera.y, levelHeight * TILE_SIZE - canvas.height));
    }

    // --- Rendering ---
    function drawTile(x, y) {
      ctx.fillStyle = "#4b4f5c";
      ctx.fillRect(x, y, TILE_SIZE, TILE_SIZE);

      ctx.fillStyle = "#5f6474";
      ctx.fillRect(x + 4, y + 4, TILE_SIZE - 8, TILE_SIZE - 8);

      ctx.strokeStyle = "rgba(255,255,255,0.08)";
      ctx.strokeRect(x + 0.5, y + 0.5, TILE_SIZE - 1, TILE_SIZE - 1);
    }

    function drawPlayer() {
      const anim = animations[player.state];
      const frame = anim[Math.floor(player.animTime / 10) % anim.length];

      const x = player.x - camera.x;
      const y = player.y - camera.y;

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-x - player.w / 2, -y - player.h / 2);

      // Shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 4, 16, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // Legs
      ctx.fillStyle = frame.leg;
      const legOffset = frame.legOffset || 0;
      ctx.fillRect(x + 9, y + 30, 7, 14 - legOffset * 0.2);
      ctx.fillRect(x + 18, y + 30 + legOffset * 0.2, 7, 14 - legOffset * 0.2);

      // Body
      ctx.fillStyle = frame.shirt;
      ctx.fillRect(x + 7, y + 14, 20, 18);

      // Head
      ctx.fillStyle = frame.body;
      ctx.beginPath();
      ctx.arc(x + 17, y + 10, 10, 0, Math.PI * 2);
      ctx.fill();

      // Eyes
      ctx.fillStyle = "#111";
      ctx.fillRect(x + 13, y + 8, 2, 2);
      ctx.fillRect(x + 19, y + 8, 2, 2);

      // Arms
      ctx.strokeStyle = "#2d3d66";
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.moveTo(x + 8, y + 18);
      ctx.lineTo(x + 2, y + 24);
      ctx.moveTo(x + 26, y + 18);
      ctx.lineTo(x + 32, y + 24);
      ctx.stroke();

      ctx.restore();
    }

    function drawWorld() {
      const startX = Math.floor(camera.x / TILE_SIZE);
      const endX = Math.ceil((camera.x + canvas.width) / TILE_SIZE);
      const startY = Math.floor(camera.y / TILE_SIZE);
      const endY = Math.ceil((camera.y + canvas.height) / TILE_SIZE);

      for (let y = startY; y <= endY; y++) {
        for (let x = startX; x <= endX; x++) {
          if (isSolidTile(x, y)) {
            drawTile(x * TILE_SIZE - camera.x, y * TILE_SIZE - camera.y);
          }
        }
      }
    }

    function drawBackground() {
      // simple parallax hills
      ctx.fillStyle = "#b8e6ff";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.fillStyle = "#9ddc8f";
      for (let i = 0; i < 8; i++) {
        const hillX = (i * 300 - camera.x * 0.3) % (canvas.width + 300) - 150;
        ctx.beginPath();
        ctx.ellipse(hillX, canvas.height - 40, 180, 80, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      drawBackground();
      drawWorld();
      drawPlayer();
    }

    // --- Game Loop ---
    function loop() {
      updatePlayer();
      updateCamera();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

