- simple **sprite animation** using colored frame rectangles
- a few **platforms**
- a **goal** to reach

Save this as `index.html` and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Platformer</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      text-shadow: 0 1px 2px black;
      font-size: 16px;
    }
  </style>
</head>
<body>
  <div class="hud">Move: A/D or ←/→ | Jump: W / Space / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.6,
      friction: 0.85
    };

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 12,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    const platforms = [
      { x: 0, y: 500, w: 960, h: 40 },   // ground
      { x: 120, y: 420, w: 140, h: 20 },
      { x: 320, y: 360, w: 140, h: 20 },
      { x: 520, y: 300, w: 140, h: 20 },
      { x: 700, y: 240, w: 140, h: 20 },
      { x: 820, y: 160, w: 100, h: 20 }
    ];

    const goal = { x: 880, y: 110, w: 24, h: 50 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity;
      player.vx *= world.friction;

      // Horizontal movement
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          else if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical movement
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Keep player in bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;
      if (player.y > canvas.height) {
        player.x = 80;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.5;
      if (moving && player.onGround) {
        player.animTime += 1;
        if (player.animTime % 10 === 0) {
          player.frame = (player.frame + 1) % 4;
        }
      } else {
        player.frame = 0;
      }

      // Win condition
      if (rectsOverlap(player, goal)) {
        alert("You win!");
        player.x = 80;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function drawPlatform(p) {
      ctx.fillStyle = "#4b5563";
      ctx.fillRect(p.x, p.y, p.w, p.h);
      ctx.fillStyle = "#6b7280";
      ctx.fillRect(p.x, p.y, p.w, 4);
    }

    function drawPlayer() {
      // Simple sprite animation: 4-frame body color cycling
      const colors = ["#ffcc66", "#ffb84d", "#ff9933", "#ffb84d"];
      const x = player.x;
      const y = player.y;

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 6, 16, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // body
      ctx.fillStyle = colors[player.frame];
      ctx.fillRect(x, y, player.w, player.h);

      // face / direction marker
      ctx.fillStyle = "#222";
      if (player.facing === 1) {
        ctx.fillRect(x + 20, y + 14, 4, 4);
      } else {
        ctx.fillRect(x + 8, y + 14, 4, 4);
      }

      // legs
      ctx.fillStyle = "#333";
      ctx.fillRect(x + 6, y + 40, 6, 8);
      ctx.fillRect(x + 20, y + 40, 6, 8);
    }

    function drawGoal() {
      ctx.fillStyle = "#22c55e";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#facc15";
      ctx.fillRect(goal.x + 6, goal.y + 8, 12, 12);
    }

    function drawBackground() {
      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 5; i++) {
        const cx = 120 + i * 180;
        const cy = 70 + (i % 2) * 30;
        ctx.beginPath();
        ctx.arc(cx, cy, 18, 0, Math.PI * 2);
        ctx.arc(cx + 20, cy - 10, 22, 0, Math.PI * 2);
        ctx.arc(cx + 42, cy, 18, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();

      platforms.forEach(drawPlatform);
      drawGoal();
      drawPlayer();
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
