Below is a **minimal working 2D platformer** in **HTML + JavaScript** using the **Canvas API**. It includes:

- player movement
- gravity and jumping
- simple collision physics
- animated sprite-like player using colored frames
- platforms and a goal

Save this as **`index.html`** and open it in a browser.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Platformer</title>
  <style>
    html, body {
      margin: 0;
      padding: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    #ui {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 14px;
      text-shadow: 1px 1px 2px black;
    }
  </style>
</head>
<body>
  <div id="ui">Move: A/D or ←/→ | Jump: W / Space / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.6,
      friction: 0.85
    };

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 12,
      onGround: false,
      facing: 1,
      animTime: 0,
      frame: 0
    };

    const platforms = [
      { x: 0, y: 500, w: 960, h: 40 },
      { x: 150, y: 420, w: 180, h: 20 },
      { x: 380, y: 360, w: 160, h: 20 },
      { x: 600, y: 300, w: 160, h: 20 },
      { x: 780, y: 240, w: 120, h: 20 },
      { x: 50, y: 300, w: 100, h: 20 }
    ];

    const goal = { x: 860, y: 180, w: 30, h: 60 };
    let won = false;

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      if (won) return;

      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity;
      player.vx *= world.friction;

      player.x += player.vx;
      player.y += player.vy;

      player.onGround = false;

      // Collision with platforms
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          const prevX = player.x - player.vx;
          const prevY = player.y - player.vy;

          // Landing on top
          if (prevY + player.h <= p.y) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // Hitting from below
          else if (prevY >= p.y + p.h) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          // Hitting from left
          else if (prevX + player.w <= p.x) {
            player.x = p.x - player.w;
            player.vx = 0;
          }
          // Hitting from right
          else if (prevX >= p.x + p.w) {
            player.x = p.x + p.w;
            player.vx = 0;
          }
        }
      }

      // Keep in bounds
      player.x = Math.max(0, Math.min(canvas.width - player.w, player.x));
      if (player.y > canvas.height + 200) {
        player.x = 80;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Goal
      if (rectsOverlap(player, goal)) {
        won = true;
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.5;
      if (moving && player.onGround) {
        player.animTime += 1;
        player.frame = Math.floor(player.animTime / 8) % 4;
      } else {
        player.frame = 0;
      }
    }

    function drawPlayer() {
      // Simple sprite animation made from colored rectangles
      const colors = ["#2b6cb0", "#3182ce", "#63b3ed", "#90cdf4"];
      const c = colors[player.frame];

      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // body
      ctx.fillStyle = c;
      ctx.fillRect(8, 10, 16, 24);

      // head
      ctx.fillStyle = "#f6d6bd";
      ctx.fillRect(10, 0, 12, 12);

      // legs animation
      ctx.fillStyle = "#1a202c";
      if (player.frame % 2 === 0) {
        ctx.fillRect(8, 34, 6, 12);
        ctx.fillRect(18, 34, 6, 12);
      } else {
        ctx.fillRect(6, 34, 6, 12);
        ctx.fillRect(20, 34, 6, 12);
      }

      // eye
      ctx.fillStyle = "#000";
      ctx.fillRect(18, 4, 2, 2);

      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background clouds
      ctx.fillStyle = "rgba(255,255,255,0.6)";
      ctx.beginPath(); ctx.arc(120, 90, 25, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(150, 80, 35, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(180, 90, 25, 0, Math.PI * 2); ctx.fill();

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#4a5568";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#2d3748";
        ctx.fillRect(p.x, p.y, p.w, 4);
      }

      // Goal
      ctx.fillStyle = won ? "#48bb78" : "#f6e05e";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#fff";
      ctx.fillRect(goal.x + 8, goal.y + 10, 14, 14);

      // Player
      drawPlayer();

      if (won) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "white";
        ctx.font = "bold 48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
        ctx.font = "20px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 40);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
