const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

const keys = {};
addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

const GRAVITY = 0.6;
const MOVE_SPEED = 4;
const JUMP_SPEED = -12;

const player = {
  x: 100,
  y: 100,
  w: 32,
  h: 48,
  vx: 0,
  vy: 0,
  onGround: false,
  facing: 1,
  animFrame: 0,
  animTimer: 0
};

const platforms = [
  { x: 0, y: 500, w: 960, h: 40 },
  { x: 150, y: 400, w: 160, h: 20 },
  { x: 380, y: 330, w: 180, h: 20 },
  { x: 650, y: 260, w: 180, h: 20 },
  { x: 820, y: 180, w: 100, h: 20 }
];

const goal = { x: 860, y: 130, w: 30, h: 50 };

function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

function updatePlayer() {
  // Input
  player.vx = 0;
  if (keys["a"] || keys["arrowleft"]) {
    player.vx = -MOVE_SPEED;
    player.facing = -1;
  }
  if (keys["d"] || keys["arrowright"]) {
    player.vx = MOVE_SPEED;
    player.facing = 1;
  }

  if ((keys["w"] || keys[" "] || keys["arrowup"]) && player.onGround) {
    player.vy = JUMP_SPEED;
    player.onGround = false;
  }

  // Gravity
  player.vy += GRAVITY;

  // Horizontal movement
  player.x += player.vx;
  for (const p of platforms) {
    if (rectsOverlap(player, p)) {
      if (player.vx > 0) player.x = p.x - player.w;
      if (player.vx < 0) player.x = p.x + p.w;
    }
  }

  // Vertical movement
  player.y += player.vy;
  player.onGround = false;
  for (const p of platforms) {
    if (rectsOverlap(player, p)) {
      if (player.vy > 0) {
        player.y = p.y - player.h;
        player.vy = 0;
        player.onGround = true;
      } else if (player.vy < 0) {
        player.y = p.y + p.h;
        player.vy = 0;
      }
    }
  }

  // Keep in bounds
  player.x = Math.max(0, Math.min(canvas.width - player.w, player.x));
  if (player.y > canvas.height + 100) {
    player.x = 100;
    player.y = 100;
    player.vx = 0;
    player.vy = 0;
  }

  // Animation
  if (Math.abs(player.vx) > 0 || !player.onGround) {
    player.animTimer++;
    if (player.animTimer > 8) {
      player.animFrame = (player.animFrame + 1) % 4;
      player.animTimer = 0;
    }
  } else {
    player.animFrame = 0;
    player.animTimer = 0;
  }
}

function drawPlayer() {
  // Simple sprite animation using colored frames
  const x = player.x;
  const y = player.y;

  // body colors per frame
  const colors = ["#ffcc66", "#ffb347", "#ff9933", "#ffb347"];
  const bodyColor = colors[player.animFrame];

  ctx.save();
  ctx.translate(x + player.w / 2, y + player.h / 2);
  ctx.scale(player.facing, 1);
  ctx.translate(-player.w / 2, -player.h / 2);

  // shadow
  ctx.fillStyle = "rgba(0,0,0,0.2)";
  ctx.beginPath();
  ctx.ellipse(player.w / 2, player.h + 4, 14, 4, 0, 0, Math.PI * 2);
  ctx.fill();

  // head
  ctx.fillStyle = "#f2c9a0";
  ctx.fillRect(8, 4, 16, 16);

  // body
  ctx.fillStyle = bodyColor;
  ctx.fillRect(6, 20, 20, 18);

  // legs
  ctx.fillStyle = "#333";
  ctx.fillRect(7, 38, 6, 10);
  ctx.fillRect(19, 38, 6, 10);

  // eyes
  ctx.fillStyle = "#000";
  ctx.fillRect(12, 10, 2, 2);
  ctx.fillRect(18, 10, 2, 2);

  ctx.restore();
}

function drawPlatforms() {
  for (const p of platforms) {
    ctx.fillStyle = "#4b5563";
    ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.fillStyle = "#6b7280";
    ctx.fillRect(p.x, p.y, p.w, 4);
  }
}

function drawGoal() {
  ctx.fillStyle = "#22c55e";
  ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
  ctx.fillStyle = "#facc15";
  ctx.fillRect(goal.x + 8, goal.y + 8, 14, 14);
}

function drawUI() {
  ctx.fillStyle = "#111827";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: W / Space / Up", 16, 24);
}

function checkWin() {
  if (rectsOverlap(player, goal)) {
    ctx.fillStyle = "rgba(0,0,0,0.5)";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#fff";
    ctx.font = "48px sans-serif";
    ctx.fillText("You Win!", canvas.width / 2 - 110, canvas.height / 2);
    return true;
  }
  return false;
}

function loop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawPlatforms();
  drawGoal();
  updatePlayer();
  drawPlayer();
  drawUI();

  if (!checkWin()) {
    requestAnimationFrame(loop);
  }
}

loop();
</script>
