  { x: 520, y: 340, w: 120, h: 20 },
  { x: 680, y: 280, w: 100, h: 20 }
];

function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

function updatePlayer() {
  // Horizontal movement
  if (keys["a"] || keys["arrowleft"]) {
    player.vx -= player.speed;
    player.facing = -1;
