  ctx.fillRect(p.x, p.y, p.w, p.h);
  ctx.fillStyle = "#6b5b45";
  ctx.fillRect(p.x, p.y, p.w, 6);
}

function drawPlayer() {
  const x = player.x;
  const y = player.y;

  // Simple animated sprite frames using rectangles
  const frameColors = ["#ffcc66", "#ffb84d", "#ff9933", "#ffb84d"];
  const bodyColor = frameColors[player.animFrame];

  ctx.save();
  ctx.translate(x + player.w / 2, y + player.h / 2);
  ctx.scale(player.facing, 1);
  ctx.translate(-player.w / 2, -player.h / 2);

  // Shadow
  ctx.fillStyle = "rgba(0,0,0,0.2)";
  ctx.fillRect(6, player.h - 6, player.w - 12, 6);

  // Head
  ctx.fillStyle = "#f2c9a0";
  ctx.fillRect(10, 4, 12, 12);

  // Body
  ctx.fillStyle = bodyColor;
  ctx.fillRect(8, 16, 16, 18);

  // Legs animation
