  ctx.arc(520, 60, 18, 0, Math.PI * 2);
  ctx.arc(540, 50, 24, 0, Math.PI * 2);
  ctx.arc(565, 60, 18, 0, Math.PI * 2);
  ctx.fill();
}

function loop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawBackground();

  for (const p of platforms) drawPlatform(p);
  updatePlayer();
  drawPlayer();

  requestAnimationFrame(loop);
}

loop();
