<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Minimal Platformer</title>
  <style>
    body {
      margin: 0;
      overflow: hidden;
      background: #1e1e2e;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #cfefff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-size: 14px;
      text-shadow: 1px 1px 2px black;
    }
  </style>
</head>
<body>
  <div class="hud">Move: A/D or ←/→ | Jump: W / Space / ↑</div>
  <canvas id="game" width="800" height="450"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const gravity = 0.5;
    const friction = 0.85;

    const player = {
      x: 50,
      y: 300,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 11,
      onGround: false,
      facing: 1,
      animFrame: 0,
      animTimer: 0
    };

    const platforms = [
      { x: 0, y: 420, w: 800, h: 30 },
      { x: 120, y: 340, w: 140, h: 20 },
      { x: 320, y: 280, w: 140, h: 20 },
      { x: 520, y: 220, w: 140, h: 20 },
      { x: 680, y: 160, w: 100, h: 20 }
    ];

    const goal = { x: 730, y: 120, w: 24, h: 40 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys[" "] || keys["w"] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += gravity;
      player.vx *= friction;

      player.x += player.vx;
      player.y += player.vy;

      player.onGround = false;

      // Collision with platforms
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          const prevY = player.y - player.vy;
          const prevX = player.x - player.vx;

          // Landing on top
          if (prevY + player.h <= p.y) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // Hitting from below
          else if (prevY >= p.y + p.h) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          // Hit from left
          else if (prevX + player.w <= p.x) {
            player.x = p.x - player.w;
            player.vx = 0;
          }
          // Hit from right
          else if (prevX >= p.x + p.w) {
            player.x = p.x + p.w;
            player.vx = 0;
          }
        }
      }

      // Keep player in bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > canvas.width) {
        player.x = canvas.width - player.w;
        player.vx = 0;
      }
      if (player.y > canvas.height) {
        // reset if fallen
        player.x = 50;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.2;
      if (moving) {
        player.animTimer++;
        if (player.animTimer > 8) {
          player.animFrame = (player.animFrame + 1) % 4;
          player.animTimer = 0;
        }
      } else {
        player.animFrame = 0;
        player.animTimer = 0;
      }

      // Win condition
      if (rectsOverlap(player, goal)) {
        alert("You reached the goal!");
        player.x = 50;
        player.y = 300;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function drawPlayer() {
      // Simple sprite animation using colored frames
      const frameColors = ["#ffcc66", "#ff9966", "#ffcc66", "#ff9966"];
      const color = frameColors[player.animFrame];

      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // body
      ctx.fillStyle = color;
      ctx.fillRect(8, 12, 16, 24);

      // head
      ctx.fillStyle = "#ffe0bd";
      ctx.fillRect(10, 2, 12, 12);

      // legs animation
      ctx.fillStyle = "#333";
      if (player.animFrame % 2 === 0) {
        ctx.fillRect(8, 36, 6, 10);
        ctx.fillRect(18, 36, 6, 10);
      } else {
        ctx.fillRect(10, 36, 6, 10);
        ctx.fillRect(16, 36, 6, 10);
      }

      // eyes
      ctx.fillStyle = "#000";
      ctx.fillRect(13, 6, 2, 2);
      ctx.fillRect(17, 6, 2, 2);

      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background hills
      ctx.fillStyle = "rgba(0,0,0,0.08)";
      ctx.beginPath();
      ctx.arc(120, 430, 80, 0, Math.PI * 2);
      ctx.arc(320, 430, 120, 0, Math.PI * 2);
      ctx.arc(620, 430, 100, 0, Math.PI * 2);
      ctx.fill();

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#5c4b3b";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7c5f46";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }

      // Goal
      ctx.fillStyle = "#ffd700";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#fff";
      ctx.fillRect(goal.x + 6, goal.y + 8, 4, 4);

      drawPlayer();
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
