      friction: 0.85
    };

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 12,
      onGround: false,
      facing: 1,
      animTimer: 0,
      animFrame: 0
    };

    const platforms = [
      { x: 0,   y: 500, w: 960, h: 40 },
      { x: 120, y: 420, w: 140, h: 20 },
      { x: 320, y: 360, w: 160, h: 20 },
      { x: 560, y: 300, w: 140, h: 20 },
      { x: 760, y: 240, w: 120, h: 20 },
      { x: 680, y: 420, w: 160, h: 20 }
    ];

    const goal = { x: 860, y: 180, w: 24, h: 60 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function updatePlayer() {
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      player.vy += world.gravity;

      // Horizontal movement
      player.x += player.vx;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vx > 0) player.x = p.x - player.w;
          if (player.vx < 0) player.x = p.x + p.w;
          player.vx = 0;
        }
      }

      // Vertical movement
      player.y += player.vy;
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (player.vy > 0) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          } else if (player.vy < 0) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
        }
      }

      // Friction
      player.vx *= world.friction;

      // Clamp to screen
      player.x = Math.max(0, Math.min(canvas.width - player.w, player.x));
      player.y = Math.min(canvas.height - player.h, player.y);

      // Animation
      if (Math.abs(player.vx) > 0.2 && player.onGround) {
        player.animTimer++;
        if (player.animTimer % 8 === 0) {
          player.animFrame = (player.animFrame + 1) % 4;
        }
      } else {
        player.animFrame = 0;
      }

      // Win condition
      if (rectsOverlap(player, goal)) {
        alert("You reached the flag!");
        resetGame();
      }
    }

    function resetGame() {
      player.x = 80;
      player.y = 100;
      player.vx = 0;
      player.vy = 0;
    }

    function drawBackground() {
      // simple clouds
      ctx.fillStyle = "rgba(255,255,255,0.5)";
      ctx.beginPath(); ctx.arc(150, 80, 20, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(170, 70, 28, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(200, 80, 22, 0, Math.PI * 2); ctx.fill();

      ctx.beginPath(); ctx.arc(650, 100, 18, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(670, 90, 26, 0, Math.PI * 2); ctx.fill();
      ctx.beginPath(); ctx.arc(700, 100, 20, 0, Math.PI * 2); ctx.fill();
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#5b4636";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7c5c42";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }
    }

    function drawGoal() {
      ctx.fillStyle = "#2ecc71";
      ctx.fillRect(goal.x, goal.y, 6, goal.h);
      ctx.fillStyle = "#27ae60";
      ctx.beginPath();
      ctx.moveTo(goal.x + 6, goal.y + 8);
      ctx.lineTo(goal.x + 28, goal.y + 16);
      ctx.lineTo(goal.x + 6, goal.y + 24);
      ctx.closePath();
      ctx.fill();
    }

    function drawPlayer() {
      const x = player.x;
      const y = player.y;

      // simple 4-frame sprite animation using colored rectangles
      const frames = [
        { body: "#ffcc66", shirt: "#ff6666", leg: "#333333" },
        { body: "#ffd27f", shirt: "#ff7777", leg: "#222222" },
        { body: "#ffcc66", shirt: "#ff5555", leg: "#333333" },
        { body: "#ffd27f", shirt: "#ff7777", leg: "#222222" }
      ];
      const f = frames[player.animFrame];

      ctx.save();
      ctx.translate(x + player.w / 2, y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.fillRect(4, player.h - 6, player.w - 8, 6);

      // legs
      ctx.fillStyle = f.leg;
      ctx.fillRect(8, 32, 6, 14);
      ctx.fillRect(18, 32, 6, 14);

      // body
      ctx.fillStyle = f.shirt;
      ctx.fillRect(6, 16, 20, 18);

      // head
      ctx.fillStyle = f.body;
      ctx.fillRect(8, 2, 16, 16);

      // eye
      ctx.fillStyle = "#000";
      ctx.fillRect(19, 8, 2, 2);

      // arm
      ctx.fillStyle = f.shirt;
      ctx.fillRect(2, 18, 4, 10);

      ctx.restore();
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawGoal();
      drawPlatforms();
      drawPlayer();
    }

    function loop() {
      updatePlayer();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
