      background: rgba(0,0,0,0.35);
      padding: 8px 10px;
      border-radius: 6px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div class="hint">Move: A/D or ←/→ | Jump: W / Space / ↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const gravity = 0.6;
    const friction = 0.85;

    const player = {
      x: 100,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 12,
      onGround: false,
      facing: 1,
      animFrame: 0,
      animTimer: 0
    };

    const platforms = [
      { x: 0, y: 500, w: 960, h: 40 },   // ground
      { x: 120, y: 420, w: 160, h: 20 },
      { x: 340, y: 360, w: 160, h: 20 },
      { x: 560, y: 300, w: 160, h: 20 },
      { x: 760, y: 240, w: 120, h: 20 },
      { x: 420, y: 460, w: 100, h: 20 }
    ];

    const goal = { x: 860, y: 190, w: 30, h: 50 };

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += gravity;
      player.vx *= friction;

      player.x += player.vx;
      resolveCollisions("x");

      player.y += player.vy;
      player.onGround = false;
      resolveCollisions("y");

      // Keep inside screen
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;
      if (player.y > canvas.height) {
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (Math.abs(player.vx) > 0.5 && player.onGround) {
        player.animTimer++;
        if (player.animTimer > 8) {
          player.animFrame = (player.animFrame + 1) % 4;
          player.animTimer = 0;
        }
      } else {
        player.animFrame = 0;
        player.animTimer = 0;
      }

      // Win condition
      if (rectsOverlap(player, goal)) {
        alert("You reached the goal!");
        player.x = 100;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }
    }

    function resolveCollisions(axis) {
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          if (axis === "x") {
            if (player.vx > 0) player.x = p.x - player.w;
            else if (player.vx < 0) player.x = p.x + p.w;
            player.vx = 0;
          } else if (axis === "y") {
            if (player.vy > 0) {
              player.y = p.y - player.h;
              player.vy = 0;
              player.onGround = true;
            } else if (player.vy < 0) {
              player.y = p.y + p.h;
              player.vy = 0;
            }
          }
        }
      }
    }

    function drawBackground() {
      // simple parallax-ish hills
      ctx.fillStyle = "#9be27f";
      ctx.fillRect(0, 470, canvas.width, 70);

      ctx.fillStyle = "#7cc96b";
      for (let i = 0; i < 6; i++) {
        ctx.beginPath();
        ctx.arc(i * 180 + 60, 500, 70, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function drawPlatforms() {
      for (const p of platforms) {
        ctx.fillStyle = "#5b4636";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#7a5c45";
        ctx.fillRect(p.x, p.y, p.w, 6);
      }
    }

    function drawGoal() {
      ctx.fillStyle = "#ffd700";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#fff3a0";
      ctx.fillRect(goal.x + 6, goal.y + 6, goal.w - 12, goal.h - 12);
    }

    // Minimal animated sprite drawn with shapes
    function drawPlayer() {
      const x = player.x;
      const y = player.y;

      // body colors change by frame
      const frameColors = ["#ff4d4d", "#ff7a4d", "#ff4d4d", "#ffb84d"];
      const shirt = frameColors[player.animFrame];

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(x + player.w / 2, y + player.h + 4, 16, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // legs
      ctx.fillStyle = "#2b2b2b";
      const legOffset = player.animFrame % 2 === 0 ? 0 : 3;
      ctx.fillRect(x + 8, y + 34, 6, 14);
      ctx.fillRect(x + 18, y + 34 + legOffset, 6, 14);

      // body
      ctx.fillStyle = shirt;
      ctx.fillRect(x + 6, y + 16, 20, 20);

      // head
      ctx.fillStyle = "#f2c9a0";
      ctx.fillRect(x + 8, y + 2, 16, 16);

      // eyes
      ctx.fillStyle = "#111";
      if (player.facing === 1) {
        ctx.fillRect(x + 18, y + 8, 2, 2);
        ctx.fillRect(x + 22, y + 8, 2, 2);
      } else {
        ctx.fillRect(x + 10, y + 8, 2, 2);
        ctx.fillRect(x + 14, y + 8, 2, 2);
      }

      // arm
      ctx.fillStyle = "#f2c9a0";
      ctx.fillRect(x + (player.facing === 1 ? 24 : 2), y + 18, 4, 10);
    }

    function render() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      drawBackground();
      drawGoal();
      drawPlatforms();
      drawPlayer();
    }

    function loop() {
      update();
      render();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
