      background: #1e1e2e;
      overflow: hidden;
      height: 100%;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #dff6ff);
      image-rendering: pixelated;
    }
    .hud {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      font-family: sans-serif;
      text-shadow: 0 1px 2px black;
      user-select: none;
    }
  </style>
</head>
<body>
  <div class="hud">Move: A/D or ←/→ | Jump: W/Space/↑</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.7,
      friction: 0.85
    };

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.7,
      jumpPower: 13,
      onGround: false,
      facing: 1,
      frame: 0,
      frameTimer: 0
    };

    const platforms = [
      { x: 0,   y: 500, w: 960, h: 40 },
      { x: 120, y: 420, w: 160, h: 20 },
      { x: 340, y: 360, w: 160, h: 20 },
      { x: 560, y: 300, w: 160, h: 20 },
      { x: 760, y: 240, w: 120, h: 20 },
      { x: 220, y: 260, w: 100, h: 20 }
    ];

    const goal = { x: 860, y: 180, w: 30, h: 60 };
    let won = false;

    // Create simple sprite frames using an offscreen canvas
    function makeFrame(legOffset, armOffset, blink = false) {
      const c = document.createElement("canvas");
      c.width = 32;
      c.height = 48;
      const g = c.getContext("2d");

      // shadow
      g.fillStyle = "rgba(0,0,0,0.15)";
      g.beginPath();
      g.ellipse(16, 45, 10, 3, 0, 0, Math.PI * 2);
      g.fill();

      // body
      g.fillStyle = "#3b82f6";
      g.fillRect(10, 18, 12, 16);

      // head
      g.fillStyle = "#f2c9a0";
      g.fillRect(11, 6, 10, 10);

      // eyes
      g.fillStyle = "#111";
      if (!blink) {
        g.fillRect(13, 10, 1, 1);
        g.fillRect(17, 10, 1, 1);
      } else {
        g.fillRect(13, 10, 5, 1);
      }

      // arms
      g.strokeStyle = "#f2c9a0";
      g.lineWidth = 3;
      g.beginPath();
      g.moveTo(10, 22);
      g.lineTo(6, 26 + armOffset);
      g.moveTo(22, 22);
      g.lineTo(26, 26 - armOffset);
      g.stroke();

      // legs
      g.strokeStyle = "#1f2937";
      g.lineWidth = 4;
      g.beginPath();
      g.moveTo(13, 34);
      g.lineTo(11 + legOffset, 44);
      g.moveTo(19, 34);
      g.lineTo(21 - legOffset, 44);
      g.stroke();

      return c;
    }

    const frames = [
      makeFrame(0, 0),
      makeFrame(2, 1),
      makeFrame(0, 0, true),
      makeFrame(-2, -1)
    ];

    function rectsOverlap(a, b) {
      return (
        a.x < b.x + b.w &&
        a.x + a.w > b.x &&
        a.y < b.y + b.h &&
        a.y + a.h > b.y
      );
    }

    function update() {
      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }

      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity;
      player.vx *= world.friction;

      player.x += player.vx;
      player.y += player.vy;

      // World bounds
      if (player.x < 0) {
        player.x = 0;
        player.vx = 0;
      }
      if (player.x + player.w > canvas.width) {
        player.x = canvas.width - player.w;
        player.vx = 0;
      }

      // Platform collisions
      player.onGround = false;
      for (const p of platforms) {
        if (rectsOverlap(player, p)) {
          const prevY = player.y - player.vy;

          // Landing on top
          if (prevY + player.h <= p.y) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // Hitting from below
          else if (prevY >= p.y + p.h) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          // Side collision
          else {
            if (player.x + player.w / 2 < p.x + p.w / 2) {
              player.x = p.x - player.w;
            } else {
              player.x = p.x + p.w;
            }
            player.vx = 0;
          }
        }
      }

      // Goal
      if (rectsOverlap(player, goal)) {
        won = true;
      }

      // Animation
      const moving = Math.abs(player.vx) > 0.5 && player.onGround;
      if (moving) {
        player.frameTimer++;
        if (player.frameTimer > 8) {
          player.frame = (player.frame + 1) % frames.length;
          player.frameTimer = 0;
        }
      } else {
        player.frame = 0;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background clouds
      ctx.fillStyle = "rgba(255,255,255,0.6)";
      ctx.beginPath();
      ctx.ellipse(150, 90, 40, 18, 0, 0, Math.PI * 2);
      ctx.ellipse(180, 85, 50, 22, 0, 0, Math.PI * 2);
      ctx.ellipse(220, 92, 35, 16, 0, 0, Math.PI * 2);
      ctx.fill();

      // Platforms
      for (const p of platforms) {
        ctx.fillStyle = "#4b5563";
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#6b7280";
        ctx.fillRect(p.x, p.y, p.w, 4);
      }

      // Goal
      ctx.fillStyle = won ? "#22c55e" : "#f59e0b";
      ctx.fillRect(goal.x, goal.y, goal.w, goal.h);
      ctx.fillStyle = "#fff";
      ctx.fillRect(goal.x + 10, goal.y + 10, 10, 10);

      // Player sprite
      const sprite = frames[player.frame];
      ctx.save();
      if (player.facing === -1) {
        ctx.translate(player.x + player.w, player.y);
        ctx.scale(-1, 1);
        ctx.drawImage(sprite, 0, 0, player.w, player.h);
      } else {
        ctx.drawImage(sprite, player.x, player.y, player.w, player.h);
      }
      ctx.restore();

      // Win text
      if (won) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
        ctx.font = "20px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 40);
      }
    }

    function loop() {
      if (!won) update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

