      const colors = ["#ffcc66", "#ffb347", "#ff9933", "#ffcc99"];
      const bodyColor = colors[player.frame];

      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.translate(-player.w / 2, -player.h / 2);

      // shadow
      ctx.fillStyle = "rgba(0,0,0,0.2)";
      ctx.beginPath();
      ctx.ellipse(player.w / 2, player.h + 4, 14, 5, 0, 0, Math.PI * 2);
      ctx.fill();

      // body
      ctx.fillStyle = bodyColor;
      ctx.fillRect(6, 10, 20, 26);

      // head
      ctx.fillStyle = "#ffd7b3";
      ctx.fillRect(8, 0, 16, 14);

      // eyes
      ctx.fillStyle = "#222";
      ctx.fillRect(12, 5, 2, 2);
      ctx.fillRect(18, 5, 2, 2);

      // legs (animated)
      ctx.fillStyle = "#333";
      if (player.onGround && Math.abs(player.vx) > 0.5) {
        const legOffset = player.frame % 2 === 0 ? 0 : 4;
        ctx.fillRect(8, 36, 5, 10 - legOffset);
        ctx.fillRect(19, 36, 5, 10 - (4 - legOffset));
      } else {
        ctx.fillRect(8, 36, 5, 10);
        ctx.fillRect(19, 36, 5, 10);
      }

      // arm
      ctx.fillStyle = "#ffd7b3";
      ctx.fillRect(2, 14, 6, 4);
      ctx.fillRect(24, 14, 6, 4);

      ctx.restore();
    }

    function drawBackground() {
      // clouds
      ctx.fillStyle = "rgba(255,255,255,0.7)";
      for (let i = 0; i < 5; i++) {
        const x = (i * 220 + (Date.now() * 0.01)) % (canvas.width + 100) - 100;
        const y = 40 + i * 35;
        ctx.beginPath();
        ctx.arc(x, y, 18, 0, Math.PI * 2);
        ctx.arc(x + 20, y - 8, 24, 0, Math.PI * 2);
        ctx.arc(x + 45, y, 18, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function loop() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      drawBackground();

      for (const p of world.platforms) drawPlatform(p);
      updatePlayer();
      drawPlayer();

      requestAnimationFrame(loop);
    }

