</head>
<body>
<canvas id="game"></canvas>

<script>
const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener("resize", resize);
resize();

const keys = {};
window.addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
window.addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

const world = {
  gravity: 0.6,
  friction: 0.85
};

const player = {
  x: 100,
  y: 100,
  w: 32,
  h: 48,
  vx: 0,
  vy: 0,
  speed: 0.7,
  jumpPower: 12,
  onGround: false,
  facing: 1,
  animTime: 0
};

const platforms = [
  { x: -200, y: 500, w: 1200, h: 40 },
  { x: 250, y: 400, w: 120, h: 20 },
  { x: 450, y: 330, w: 120, h: 20 },
  { x: 650, y: 260, w: 120, h: 20 },
  { x: 850, y: 190, w: 120, h: 20 }
];

const camera = {
  x: 0,
  y: 0
};

function rectsOverlap(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

function updatePlayer() {
  // Horizontal movement
  if (keys["a"] || keys["arrowleft"]) {
    player.vx -= player.speed;
    player.facing = -1;
  }
  if (keys["d"] || keys["arrowright"]) {
    player.vx += player.speed;
    player.facing = 1;
  }

  // Jump
  if ((keys["w"] || keys["arrowup"] || keys[" "]) && player.onGround) {
    player.vy = -player.jumpPower;
    player.onGround = false;
  }

  // Physics
  player.vy += world.gravity;
  player.vx *= world.friction;

  // Move X and resolve collisions
  player.x += player.vx;
  for (const p of platforms) {
    if (rectsOverlap(player, p)) {
      if (player.vx > 0) player.x = p.x - player.w;
      else if (player.vx < 0) player.x = p.x + p.w;
      player.vx = 0;
    }
  }

  // Move Y and resolve collisions
  player.y += player.vy;
  player.onGround = false;
  for (const p of platforms) {
    if (rectsOverlap(player, p)) {
      if (player.vy > 0) {
        player.y = p.y - player.h;
        player.vy = 0;
        player.onGround = true;
      } else if (player.vy < 0) {
        player.y = p.y + p.h;
        player.vy = 0;
      }
    }
  }

  // Simple bounds
  if (player.y > 1000) {
    player.x = 100;
    player.y = 100;
    player.vx = 0;
    player.vy = 0;
  }

  player.animTime += Math.abs(player.vx) + (player.onGround ? 0.2 : 0.05);
}

function updateCamera() {
  camera.x = player.x - canvas.width / 2 + player.w / 2;
  camera.y = player.y - canvas.height / 2 + player.h / 2;
}

function drawPlatform(p) {
  ctx.fillStyle = "#4b5563";
  ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, p.h);
  ctx.fillStyle = "#6b7280";
  ctx.fillRect(p.x - camera.x, p.y - camera.y, p.w, 6);
}

function drawPlayer() {
  const x = player.x - camera.x;
  const y = player.y - camera.y;

  // Animation frames: simple squash/stretch based on time
  const walkFrame = Math.floor(player.animTime / 6) % 2;
  const bodyOffset = walkFrame ? 2 : 0;

  // Shadow
  ctx.fillStyle = "rgba(0,0,0,0.2)";
  ctx.beginPath();
  ctx.ellipse(x + player.w / 2, y + player.h + 6, 16, 5, 0, 0, Math.PI * 2);
  ctx.fill();

  // Body
  ctx.fillStyle = "#ffcc66";
  ctx.fillRect(x, y + bodyOffset, player.w, player.h - 10);

  // Head
  ctx.fillStyle = "#f4a261";
  ctx.fillRect(x + 4, y - 10 + bodyOffset, player.w - 8, 16);

  // Eyes
  ctx.fillStyle = "#111";
  const eyeX = player.facing === 1 ? x + 20 : x + 8;
  ctx.fillRect(eyeX, y - 4 + bodyOffset, 3, 3);

  // Legs animation
  ctx.fillStyle = "#264653";
  if (player.onGround && (keys["a"] || keys["d"] || keys["arrowleft"] || keys["arrowright"])) {
    if (walkFrame === 0) {
      ctx.fillRect(x + 4, y + 34, 8, 14);
      ctx.fillRect(x + 20, y + 30, 8, 18);
    } else {
      ctx.fillRect(x + 4, y + 30, 8, 18);
      ctx.fillRect(x + 20, y + 34, 8, 14);
    }
  } else {
    ctx.fillRect(x + 4, y + 34, 8, 14);
    ctx.fillRect(x + 20, y + 34, 8, 14);
  }
}

function drawBackground() {
  // Simple parallax hills
  ctx.fillStyle = "#9bd18f";
  for (let i = -1; i < 10; i++) {
    const hillX = i * 300 - (camera.x * 0.3 % 300);
    ctx.beginPath();
    ctx.arc(hillX + 150, canvas.height - 40, 120, Math.PI, 0);
    ctx.fill();
  }
}

function loop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  updatePlayer();
  updateCamera();

  drawBackground();

  for (const p of platforms) drawPlatform(p);
  drawPlayer();

  // HUD
  ctx.fillStyle = "#000";
  ctx.font = "16px sans-serif";
  ctx.fillText("Move: A/D or Arrow Keys | Jump: W / Up / Space", 20, 30);

  requestAnimationFrame(loop);
}

loop();
</script>
</body>
</html>
