      margin: 0;
      overflow: hidden;
      background: #1e1e2f;
      font-family: sans-serif;
    }
    canvas {
      display: block;
      margin: 0 auto;
      background: linear-gradient(#87ceeb, #cfefff);
    }
    #info {
      position: fixed;
      top: 10px;
      left: 10px;
      color: white;
      background: rgba(0,0,0,0.35);
      padding: 8px 12px;
      border-radius: 6px;
      font-size: 14px;
    }
  </style>
</head>
<body>
  <div id="info">Move: A/D or ←/→ | Jump: W / Space / ↑ | Reach the flag</div>
  <canvas id="game" width="960" height="540"></canvas>

  <script>
    const canvas = document.getElementById("game");
    const ctx = canvas.getContext("2d");

    const keys = {};
    addEventListener("keydown", e => keys[e.key.toLowerCase()] = true);
    addEventListener("keyup", e => keys[e.key.toLowerCase()] = false);

    const world = {
      gravity: 0.7,
      friction: 0.85
    };

    const player = {
      x: 80,
      y: 100,
      w: 32,
      h: 48,
      vx: 0,
      vy: 0,
      speed: 0.6,
      jumpPower: 14,
      onGround: false,
      facing: 1,
      frame: 0,
      frameTimer: 0
    };

    const platforms = [
      { x: 0,   y: 500, w: 960, h: 40 },
      { x: 120, y: 420, w: 160, h: 20 },
      { x: 340, y: 360, w: 160, h: 20 },
      { x: 560, y: 300, w: 160, h: 20 },
      { x: 760, y: 240, w: 120, h: 20 },
      { x: 220, y: 260, w: 100, h: 20 },
      { x: 420, y: 180, w: 100, h: 20 }
    ];

    const goal = { x: 860, y: 180, w: 20, h: 60 };
    let won = false;

    // Create simple animated sprite frames on an offscreen canvas
    const spriteCanvas = document.createElement("canvas");
    spriteCanvas.width = 128;
    spriteCanvas.height = 48;
    const sctx = spriteCanvas.getContext("2d");

    function drawSpriteFrame(legOffset, armOffset, blink = false) {
      sctx.clearRect(0, 0, spriteCanvas.width, spriteCanvas.height);

      // body
      sctx.fillStyle = "#2b4c7e";
      sctx.fillRect(12, 14, 16, 20);

      // head
      sctx.fillStyle = "#f2c9a0";
      sctx.fillRect(14, 2, 12, 12);

      // eyes
      sctx.fillStyle = blink ? "#f2c9a0" : "#000";
      sctx.fillRect(17, 7, 2, 2);
      sctx.fillRect(21, 7, 2, 2);

      // arms
      sctx.strokeStyle = "#f2c9a0";
      sctx.lineWidth = 3;
      sctx.beginPath();
      sctx.moveTo(12, 18);
      sctx.lineTo(6, 22 + armOffset);
      sctx.moveTo(28, 18);
      sctx.lineTo(34, 22 - armOffset);
      sctx.stroke();

      // legs
      sctx.strokeStyle = "#333";
      sctx.lineWidth = 4;
      sctx.beginPath();
      sctx.moveTo(16, 34);
      sctx.lineTo(12 + legOffset, 44);
      sctx.moveTo(24, 34);
      sctx.lineTo(28 - legOffset, 44);
      sctx.stroke();
    }

    const frames = [
      { leg: 0, arm: 0 },
      { leg: 3, arm: 2 },
      { leg: 0, arm: 0, blink: true },
      { leg: -3, arm: -2 }
    ];

    function update() {
      if (won) return;

      // Input
      const left = keys["a"] || keys["arrowleft"];
      const right = keys["d"] || keys["arrowright"];
      const jump = keys["w"] || keys[" "] || keys["arrowup"];

      if (left) {
        player.vx -= player.speed;
        player.facing = -1;
      }
      if (right) {
        player.vx += player.speed;
        player.facing = 1;
      }
      if (jump && player.onGround) {
        player.vy = -player.jumpPower;
        player.onGround = false;
      }

      // Physics
      player.vy += world.gravity;
      player.vx *= world.friction;

      player.x += player.vx;
      player.y += player.vy;

      player.onGround = false;

      // Collision detection
      for (const p of platforms) {
        if (
          player.x < p.x + p.w &&
          player.x + player.w > p.x &&
          player.y < p.y + p.h &&
          player.y + player.h > p.y
        ) {
          const prevBottom = player.y + player.h - player.vy;
          const prevTop = player.y - player.vy;
          const prevRight = player.x + player.w - player.vx;
          const prevLeft = player.x - player.vx;

          // Land on top
          if (prevBottom <= p.y) {
            player.y = p.y - player.h;
            player.vy = 0;
            player.onGround = true;
          }
          // Hit from below
          else if (prevTop >= p.y + p.h) {
            player.y = p.y + p.h;
            player.vy = 0;
          }
          // Hit from left
          else if (prevRight <= p.x) {
            player.x = p.x - player.w;
            player.vx = 0;
          }
          // Hit from right
          else if (prevLeft >= p.x + p.w) {
            player.x = p.x + p.w;
            player.vx = 0;
          }
        }
      }

      // World bounds
      if (player.x < 0) player.x = 0;
      if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;
      if (player.y > canvas.height) {
        player.x = 80;
        player.y = 100;
        player.vx = 0;
        player.vy = 0;
      }

      // Animation
      if (Math.abs(player.vx) > 0.5 && player.onGround) {
        player.frameTimer++;
        if (player.frameTimer > 8) {
          player.frame = (player.frame + 1) % frames.length;
          player.frameTimer = 0;
        }
      } else {
        player.frame = 0;
        player.frameTimer = 0;
      }

      // Win condition
      if (
        player.x < goal.x + goal.w &&
        player.x + player.w > goal.x &&
        player.y < goal.y + goal.h &&
        player.y + player.h > goal.y
      ) {
        won = true;
      }
    }

    function draw() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Background hills
      ctx.fillStyle = "#7ec850";
      ctx.fillRect(0, 470, canvas.width, 70);
      ctx.fillStyle = "#6ab04c";
      ctx.beginPath();
      ctx.arc(150, 500, 80, 0, Math.PI * 2);
      ctx.arc(350, 500, 100, 0, Math.PI * 2);
      ctx.arc(650, 500, 120, 0, Math.PI * 2);
      ctx.fill();

      // Platforms
      ctx.fillStyle = "#8b5a2b";
      for (const p of platforms) {
        ctx.fillRect(p.x, p.y, p.w, p.h);
        ctx.fillStyle = "#5c3b1f";
        ctx.fillRect(p.x, p.y, p.w, 4);
        ctx.fillStyle = "#8b5a2b";
      }

      // Goal flag
      ctx.fillStyle = "#444";
      ctx.fillRect(goal.x, goal.y - 20, 4, goal.h + 20);
      ctx.fillStyle = "#ff4d4d";
      ctx.beginPath();
      ctx.moveTo(goal.x + 4, goal.y - 18);
      ctx.lineTo(goal.x + 34, goal.y - 8);
      ctx.lineTo(goal.x + 4, goal.y + 2);
      ctx.closePath();
      ctx.fill();

      // Player sprite
      const f = frames[player.frame];
      drawSpriteFrame(f.leg, f.arm, f.blink);

      ctx.save();
      ctx.translate(player.x + player.w / 2, player.y + player.h / 2);
      ctx.scale(player.facing, 1);
      ctx.drawImage(spriteCanvas, -32, -24, 64, 48);
      ctx.restore();

      if (won) {
        ctx.fillStyle = "rgba(0,0,0,0.5)";
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = "#fff";
        ctx.font = "bold 48px sans-serif";
        ctx.textAlign = "center";
        ctx.fillText("You Win!", canvas.width / 2, canvas.height / 2);
        ctx.font = "20px sans-serif";
        ctx.fillText("Refresh to play again", canvas.width / 2, canvas.height / 2 + 40);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    loop();
  </script>
</body>
</html>
```

