      display: block;
    }
  </style>
</head>
<body>
  <div id="info">
    Drag to orbit • Scroll to zoom • Dynamic lights + shader animation
  </div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // Scene setup
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070d);
    scene.fog = new THREE.Fog(0x05070d, 10, 40);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 3, 8);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.05;

    // Lights
    const ambient = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambient);

    const directional = new THREE.DirectionalLight(0xffffff, 1.2);
    directional.position.set(5, 8, 3);
    scene.add(directional);

    const pointLight1 = new THREE.PointLight(0x00aaff, 2.5, 30);
    scene.add(pointLight1);

    const pointLight2 = new THREE.PointLight(0xff3366, 2.5, 30);
    scene.add(pointLight2);

    // Ground
    const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x111827,
      roughness: 0.95,
      metalness: 0.05
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -1.5;
    ground.receiveShadow = true;
    scene.add(ground);

    // Shader material for animated effect
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00aaff) },
        uColorB: { value: new THREE.Color(0xff3366) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormal;

        void main() {
          vUv = uv;
          vNormal = normal;

          vec3 pos = position;
          float wave = sin(pos.y * 8.0 + uTime * 2.0) * 0.08;
          pos += normal * wave;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec2 vUv;
        varying vec3 vNormal;

        void main() {
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 8.0);
          vec3 color = mix(uColorA, uColorB, vUv.y);
          color += pulse * 0.15;

          // Simple fake lighting from normal
          float light = dot(normalize(vNormal), normalize(vec3(0.3, 0.8, 0.6))) * 0.5 + 0.5;
          color *= light;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    // Objects
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1, 64, 64),
      shaderMaterial
    );
    sphere.position.set(-2.2, 0.2, 0);
    scene.add(sphere);

    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(0.9, 0.28, 180, 24),
      new THREE.MeshStandardMaterial({
        color: 0xffffff,
        metalness: 0.8,
        roughness: 0.2,
        emissive: 0x111111
      })
    );
    torus.position.set(2.2, 0.2, 0);
    scene.add(torus);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1.2, 1.2, 1.2),
      new THREE.MeshStandardMaterial({
        color: 0x88ccff,
        metalness: 0.4,
        roughness: 0.35
      })
    );
    box.position.set(0, 0.2, -2.5);
    scene.add(box);

    // Decorative particles
    const particleCount = 300;
    const particleGeo = new THREE.BufferGeometry();
    const particlePos = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
      const r = 12 * Math.random();
      const theta = Math.random() * Math.PI * 2;
      const y = (Math.random() - 0.5) * 8;
      particlePos[i * 3 + 0] = Math.cos(theta) * r;
      particlePos[i * 3 + 1] = y;
      particlePos[i * 3 + 2] = Math.sin(theta) * r;
    }

    particleGeo.setAttribute("position", new THREE.BufferAttribute(particlePos, 3));
    const particleMat = new THREE.PointsMaterial({
      color: 0xffffff,
      size: 0.05,
      transparent: true,
      opacity: 0.7
    });
    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Update shader time
      shaderMaterial.uniforms.uTime.value = t;

      // Animate lights
      pointLight1.position.set(Math.sin(t * 1.2) * 4, 2 + Math.sin(t * 2.0), Math.cos(t * 1.2) * 4);
      pointLight2.position.set(Math.cos(t * 0.9) * 4, 2 + Math.cos(t * 1.7), Math.sin(t * 0.9) * 4);

      // Rotate objects
      sphere.rotation.y = t * 0.4;
      torus.rotation.x = t * 0.6;
      torus.rotation.y = t * 0.8;
      box.rotation.x = t * 0.5;
      box.rotation.y = t * 0.7;

      // Particle drift
      particles.rotation.y = t * 0.03;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
