<body>
  <div id="info">
    <b>3D Scene Viewer</b><br/>
    Drag to orbit • Scroll to zoom<br/>
    Dynamic lights + animated shader
  </div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

    // --- Renderer ---
    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    document.body.appendChild(renderer.domElement);

    // --- Scene / Camera ---
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070d);
    scene.fog = new THREE.FogExp2(0x05070d, 0.03);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2.5, 7);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;
    controls.target.set(0, 1, 0);

    // --- Lights ---
    const ambient = new THREE.AmbientLight(0xffffff, 0.25);
    scene.add(ambient);

    const hemi = new THREE.HemisphereLight(0x88aaff, 0x223344, 0.7);
    scene.add(hemi);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
    dirLight.position.set(5, 8, 4);
    scene.add(dirLight);

    const pointLight1 = new THREE.PointLight(0x00d5ff, 30, 20, 2);
    pointLight1.position.set(3, 2, 0);
    scene.add(pointLight1);

    const pointLight2 = new THREE.PointLight(0xff4fd8, 25, 20, 2);
    pointLight2.position.set(-3, 1.5, 0);
    scene.add(pointLight2);

    // --- Ground ---
    const groundGeo = new THREE.PlaneGeometry(30, 30, 1, 1);
    const groundMat = new THREE.MeshStandardMaterial({
      color: 0x0b1020,
      metalness: 0.2,
      roughness: 0.95
    });
    const ground = new THREE.Mesh(groundGeo, groundMat);
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -0.01;
    scene.add(ground);

    // --- Custom Shader Material ---
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x00d5ff) },
        uColorB: { value: new THREE.Color(0xff4fd8) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vUv = uv;
          vNormal = normalize(normalMatrix * normal);

          vec3 pos = position;
          float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.08;
          pos += normal * wave;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vWorldPos = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vWorldPos;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 viewDir = normalize(cameraPosition - vWorldPos);

          float fresnel = pow(1.0 - max(dot(n, viewDir), 0.0), 3.0);
          float stripes = 0.5 + 0.5 * sin(vUv.y * 18.0 + uTime * 4.0);
          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 2.0);

          vec3 base = mix(uColorA, uColorB, stripes);
          vec3 color = base * (0.35 + 0.65 * pulse) + fresnel * 1.2;

          gl_FragColor = vec4(color, 1.0);
        }
      `,
      transparent: false
    });

    // --- Objects ---
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 200, 32),
      shaderMaterial
    );
    torus.position.set(0, 1.5, 0);
    scene.add(torus);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.7, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0xffffff,
        metalness: 0.9,
        roughness: 0.15,
        emissive: 0x111122,
        emissiveIntensity: 0.5
      })
    );
    sphere.position.set(-2.2, 1.0, 0.5);
    scene.add(sphere);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1.1, 1.1, 1.1),
      new THREE.MeshStandardMaterial({
        color: 0x8899ff,
        metalness: 0.4,
        roughness: 0.35
      })
    );
    box.position.set(2.2, 1.0, -0.5);
    scene.add(box);

    // --- Decorative particles ---
    const particleCount = 600;
    const particleGeo = new THREE.BufferGeometry();
    const positions = new Float32Array(particleCount * 3);

    for (let i = 0; i < particleCount; i++) {
      const r = 10 * Math.random();
      const theta = Math.random() * Math.PI * 2;
      const y = (Math.random() - 0.5) * 6;
      positions[i * 3 + 0] = Math.cos(theta) * r;
      positions[i * 3 + 1] = y;
      positions[i * 3 + 2] = Math.sin(theta) * r;
    }

    particleGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));
    const particleMat = new THREE.PointsMaterial({
      color: 0x88ccff,
      size: 0.03,
      transparent: true,
      opacity: 0.8
    });
    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);

    // --- Animation Loop ---
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Update shader time
      shaderMaterial.uniforms.uTime.value = t;

      // Animate lights
      pointLight1.position.x = Math.cos(t * 1.2) * 4.0;
      pointLight1.position.z = Math.sin(t * 1.2) * 4.0;
      pointLight1.position.y = 1.5 + Math.sin(t * 2.0) * 0.5;

      pointLight2.position.x = Math.cos(t * 0.9 + Math.PI) * 4.5;
      pointLight2.position.z = Math.sin(t * 0.9 + Math.PI) * 4.5;
      pointLight2.position.y = 1.2 + Math.cos(t * 1.7) * 0.4;

      // Animate objects
      torus.rotation.x = t * 0.4;
      torus.rotation.y = t * 0.7;

      sphere.rotation.y = t * 0.6;
      box.rotation.x = t * 0.5;
      box.rotation.y = t * 0.8;

      particles.rotation.y = t * 0.03;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // --- Resize ---
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
