    dirLight.position.set(5, 8, 3);
    scene.add(dirLight);

    const pointLight1 = new THREE.PointLight(0xff3366, 2.5, 30);
    const pointLight2 = new THREE.PointLight(0x33ccff, 2.5, 30);
    scene.add(pointLight1, pointLight2);

    // --- Floor ---
    const floorGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x11131a,
      metalness: 0.2,
      roughness: 0.9
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    scene.add(floor);

    // --- Custom Shader Material for main object ---
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x7c3aed) },
        uColorB: { value: new THREE.Color(0x22d3ee) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalMatrix * normal;
          vec3 pos = position;

          // subtle animated displacement
          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.08
                     + cos(pos.y * 5.0 + uTime * 1.5) * 0.05;
          pos += normal * wave;

          vPosition = (modelMatrix * vec4(pos, 1.0)).xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 N = normalize(vNormal);
          vec3 L = normalize(vec3(0.3, 0.8, 0.6));
          float diff = max(dot(N, L), 0.0);

          float fresnel = pow(1.0 - max(dot(N, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);
          float stripe = 0.5 + 0.5 * sin(vPosition.y * 8.0 + uTime * 4.0);

          vec3 base = mix(uColorA, uColorB, stripe);
          vec3 color = base * (0.25 + diff * 0.9) + fresnel * 0.7;

          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

    const mainObject = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1.1, 0.35, 220, 32),
      shaderMaterial
    );
    mainObject.position.y = 1.5;
    scene.add(mainObject);

    // --- Extra objects ---
    const sphereMat = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      metalness: 0.7,
      roughness: 0.2
    });

    const spheres = [];
    for (let i = 0; i < 6; i++) {
      const s = new THREE.Mesh(new THREE.SphereGeometry(0.25, 32, 32), sphereMat);
      const angle = (i / 6) * Math.PI * 2;
      s.position.set(Math.cos(angle) * 3.5, 0.4, Math.sin(angle) * 3.5);
      scene.add(s);
      spheres.push(s);
    }

    // --- Simple post effect: RGB shift / scanline style shader pass ---
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const RGBShiftShader = {
      uniforms: {
        tDiffuse: { value: null },
        amount: { value: 0.0015 },
        time: { value: 0 }
      },
      vertexShader: `
        varying vec2 vUv;
        void main() {
          vUv = uv;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform float amount;
        uniform float time;
        varying vec2 vUv;

        void main() {
          vec2 uv = vUv;
          float shift = amount * (0.5 + 0.5 * sin(time * 2.0));

          vec4 cr = texture2D(tDiffuse, uv + vec2( shift, 0.0));
          vec4 cg = texture2D(tDiffuse, uv);
          vec4 cb = texture2D(tDiffuse, uv - vec2( shift, 0.0));

          float scan = 0.96 + 0.04 * sin(uv.y * 900.0 + time * 20.0);
          gl_FragColor = vec4(cr.r, cg.g, cb.b, 1.0) * scan;
        }
      `
    };

    const rgbPass = new ShaderPass(RGBShiftShader);
    composer.addPass(rgbPass);

    // --- Animation loop ---
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      controls.update();

      // animate lights
      pointLight1.position.set(Math.sin(t * 1.2) * 4, 2.5 + Math.sin(t * 2.0), Math.cos(t * 1.2) * 4);
      pointLight2.position.set(Math.cos(t * 0.9) * 4, 2.0 + Math.cos(t * 1.7), Math.sin(t * 0.9) * 4);

      // animate object
      mainObject.rotation.y = t * 0.6;
      mainObject.rotation.x = Math.sin(t * 0.4) * 0.2;
      shaderMaterial.uniforms.uTime.value = t;

      // animate spheres
      spheres.forEach((s, i) => {
        s.position.y = 0.4 + Math.sin(t * 2.0 + i) * 0.15;
        s.rotation.y = t * 0.5;
      });

      rgbPass.uniforms.time.value = t;

      composer.render();
    }

    animate();

    // --- Resize ---
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      composer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
