          float fresnel = pow(1.0 - abs(n.z), 3.0);

          float wave = sin(vUv.y * 20.0 + uTime * 3.0) * 0.5 + 0.5;
          vec3 base = mix(uColorA, uColorB, wave);

          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 2.0);
          vec3 color = base + fresnel * 0.8 + pulse * 0.1;

          gl_FragColor = vec4(color, 1.0);
