    const floorGeo = new THREE.PlaneGeometry(40, 40, 128, 128);
    const floorMat = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x0b1020) },
        uColorB: { value: new THREE.Color(0x1d4ed8) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying float vWave;

        void main() {
          vUv = uv;
          vec3 p = position;

          float wave = sin((p.x * 2.0 + uTime * 1.5) * 0.8) * 0.08;
          wave += cos((p.y * 2.0 - uTime * 1.2) * 0.7) * 0.08;
          p.z += wave;

          vWave = wave;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(p, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec2 vUv;
        varying float vWave;

        void main() {
          float gridX = abs(fract(vUv.x * 20.0 - 0.5) - 0.5) / fwidth(vUv.x * 20.0);
          float gridY = abs(fract(vUv.y * 20.0 - 0.5) - 0.5) / fwidth(vUv.y * 20.0);
          float grid = 1.0 - min(min(gridX, gridY), 1.0);

          float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 8.0 + vUv.y * 8.0);
          vec3 base = mix(uColorA, uColorB, vUv.y * 0.5 + 0.5);
          base += pulse * 0.08;

          float glow = smoothstep(0.0, 0.12, abs(vWave)) * 0.15;
          vec3 color = base + grid * 0.12 + glow;

          gl_FragColor = vec4(color, 1.0);
        }
      `,
      side: THREE.DoubleSide
    });

    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = 0;
    scene.add(floor);

    // Objects
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(1, 0.35, 200, 32),
      new THREE.MeshStandardMaterial({
        color: 0x88ccff,
        metalness: 0.7,
        roughness: 0.15,
        emissive: 0x112244,
        emissiveIntensity: 0.6
      })
    );
    torus.position.set(0, 2, 0);
    scene.add(torus);

    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(0.7, 64, 64),
      new THREE.MeshStandardMaterial({
        color: 0xff7ad9,
        metalness: 0.2,
        roughness: 0.25,
        emissive: 0x330018,
        emissiveIntensity: 0.8
      })
    );
    sphere.position.set(-2.5, 1.2, 0.5);
    scene.add(sphere);

    const cube = new THREE.Mesh(
      new THREE.BoxGeometry(1.2, 1.2, 1.2),
      new THREE.MeshStandardMaterial({
        color: 0x9cff7a,
        metalness: 0.4,
        roughness: 0.3,
        emissive: 0x0b220b,
        emissiveIntensity: 0.7
      })
    );
    cube.position.set(2.5, 0.8, -0.5);
    scene.add(cube);

    // Subtle background stars
    const starCount = 1200;
    const starPositions = new Float32Array(starCount * 3);
    for (let i = 0; i < starCount; i++) {
      const r = 30 + Math.random() * 40;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(THREE.MathUtils.randFloatSpread(2));
      starPositions[i * 3 + 0] = r * Math.sin(phi) * Math.cos(theta);
      starPositions[i * 3 + 1] = r * Math.cos(phi) + 10;
      starPositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
    }
    const starsGeo = new THREE.BufferGeometry();
    starsGeo.setAttribute("position", new THREE.BufferAttribute(starPositions, 3));
    const starsMat = new THREE.PointsMaterial({ color: 0xaaccff, size: 0.06, sizeAttenuation: true });
    const stars = new THREE.Points(starsGeo, starsMat);
    scene.add(stars);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);
      const t = clock.getElapsedTime();

      controls.update();

      // Animate objects
      torus.rotation.x = t * 0.35;
      torus.rotation.y = t * 0.55;

      sphere.position.y = 1.2 + Math.sin(t * 2.0) * 0.25;
      sphere.rotation.y = t * 0.8;

      cube.rotation.x = t * 0.6;
      cube.rotation.y = t * 0.4;

      // Dynamic light motion
      movingLight.position.x = Math.sin(t * 1.2) * 4.5;
      movingLight.position.y = 2.5 + Math.sin(t * 2.0) * 1.2;
      movingLight.position.z = Math.cos(t * 1.2) * 4.5;

      // Shader time
      floorMat.uniforms.uTime.value = t;

      // Slight star drift
      stars.rotation.y = t * 0.02;

      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
