## `index.html`

```html
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>Real-Time 3D Scene Viewer</title>
  <style>
    html, body {
      margin: 0;
      width: 100%;
      height: 100%;
      overflow: hidden;
      background: #000;
      font-family: sans-serif;
    }
    #info {
      position: absolute;
      top: 12px;
      left: 12px;
      color: white;
      z-index: 10;
      background: rgba(0,0,0,0.35);
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 13px;
      user-select: none;
    }
    canvas { display: block; }
  </style>
</head>
<body>
  <div id="info">Drag to orbit • Scroll to zoom • Dynamic lighting + shader effects</div>

  <script type="module">
    import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
    import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';
    import { EffectComposer } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js';
    import { RenderPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js';
    import { UnrealBloomPass } from 'https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js';

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.1;
    document.body.appendChild(renderer.domElement);

    // Scene / Camera
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05060a);
    scene.fog = new THREE.FogExp2(0x05060a, 0.03);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2.5, 7);

    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.target.set(0, 1, 0);

    // Lights
    const ambient = new THREE.AmbientLight(0x404060, 0.35);
    scene.add(ambient);

    const hemi = new THREE.HemisphereLight(0x88aaff, 0x111122, 0.8);
    scene.add(hemi);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(5, 8, 4);
    scene.add(dirLight);

    const movingLight = new THREE.PointLight(0x66ccff, 60, 30, 2);
    movingLight.position.set(0, 3, 0);
    scene.add(movingLight);

    // Floor
    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(40, 40),
      new THREE.MeshStandardMaterial({
        color: 0x11131a,
        metalness: 0.2,
        roughness: 0.9
      })
    );
    floor.rotation.x = -Math.PI / 2;
    floor.receiveShadow = true;
    scene.add(floor);

    // Shader material for animated effect
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0x7c3aed) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalMatrix * normal;
          vec3 pos = position;

          // subtle wave deformation
          pos.y += sin(pos.x * 3.0 + uTime * 2.0) * 0.08;
          pos.y += cos(pos.z * 4.0 + uTime * 1.5) * 0.06;

          vPosition = (modelMatrix * vec4(pos, 1.0)).xyz;
          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 n = normalize(vNormal);
          vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));
          float diff = max(dot(n, lightDir), 0.0);

          float pulse = 0.5 + 0.5 * sin(uTime * 3.0 + vPosition.y * 6.0);
          vec3 base = mix(uColorA, uColorB, pulse);

          float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);
          vec3 color = base * (0.25 + diff * 0.9) + fresnel * 0.35;

          gl_FragColor = vec4(color, 1.0);
        }
      `,
      wireframe: false
    });

    // Objects
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1, 64, 64),
      shaderMaterial
    );
    sphere.position.set(-1.8, 1.2, 0);
    scene.add(sphere);

    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(0.8, 0.28, 180, 24),
      new THREE.MeshStandardMaterial({
        color: 0xffffff,
        metalness: 0.9,
        roughness: 0.15,
        emissive: 0x111122,
        emissiveIntensity: 0.4
      })
    );
    torus.position.set(1.8, 1.2, 0);
    scene.add(torus);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1.2, 1.2, 1.2),
      new THREE.MeshStandardMaterial({
        color: 0x88ffcc,
        metalness: 0.5,
        roughness: 0.3
      })
    );
    box.position.set(0, 0.8, -2.2);
    scene.add(box);

    // Post-processing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      0.9,   // strength
      0.5,   // radius
      0.15   // threshold
    );
    composer.addPass(bloomPass);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Dynamic light motion
      movingLight.position.x = Math.sin(t * 1.2) * 4.0;
      movingLight.position.z = Math.cos(t * 1.2) * 4.0;
      movingLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.8;

      // Object animation
      sphere.rotation.y = t * 0.6;
      torus.rotation.x = t * 0.7;
      torus.rotation.y = t * 1.1;
      box.rotation.x = t * 0.5;
      box.rotation.y = t * 0.8;

      // Shader time
      shaderMaterial.uniforms.uTime.value = t;

      controls.update();
      composer.render();
    }

    animate();

    // Resize handling
    window.addEventListener('resize', () => {
      const w = window.innerWidth;
      const h = window.innerHeight;

      camera.aspect = w / h;
      camera.updateProjectionMatrix();

      renderer.setSize(w, h);
      composer.setSize(w, h);
    });
  </script>
</body>
</html>
