    sphere1.position.set(-2.5, 0.2, 0);
    scene.add(sphere1);

    const sphere2 = new THREE.Mesh(new THREE.SphereGeometry(0.35, 32, 32), sphereMat);
    sphere2.position.set(2.2, 0.0, -1.2);
    scene.add(sphere2);

    // Post-processing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      1.2,  // strength
      0.5,  // radius
      0.2   // threshold
    );
    composer.addPass(bloomPass);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();

      // Dynamic light motion
      pointLight.position.x = Math.cos(t * 1.2) * 4.5;
      pointLight.position.z = Math.sin(t * 1.2) * 4.5;
