        radius: 2.8 + Math.random() * 1.5,
        speed: 0.5 + Math.random() * 1.5,
        offset: Math.random() * Math.PI * 2,
        height: 0.8 + Math.random() * 1.8
      });
    }

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      shaderMaterial.uniforms.uTime.value = t;

      // Dynamic light motion
      pointLight.position.x = Math.cos(t * 1.2) * 4.5;
      pointLight.position.z = Math.sin(t * 1.2) * 4.5;
      pointLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.8;

      // Object animation
      sphere.rotation.y = t * 0.35;
      sphere.rotation.x = Math.sin(t * 0.6) * 0.25;

      torus.rotation.x = t * 0.4;
      torus.rotation.y = t * 0.7;

      box.rotation.x = t * 0.5;
      box.rotation.y = t * 0.8;

      // Particle motion
      particles.forEach((p, i) => {
        const a = t * p.speed + p.offset;
        p.mesh.position.set(
          Math.cos(a) * p.radius,
          p.height + Math.sin(a * 2.0) * 0.25,
          Math.sin(a) * p.radius
        );
      });

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
```

