      line-height: 1.4;
    }
    canvas {
      display: block;
    }
  </style>
</head>
<body>
  <div id="info">
    <b>3D Scene Viewer</b><br/>
    Drag to orbit • Scroll to zoom
  </div>

  <script type="module">
    import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
    import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";
    import { EffectComposer } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/EffectComposer.js";
    import { RenderPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/RenderPass.js";
    import { UnrealBloomPass } from "https://unpkg.com/three@0.160.0/examples/jsm/postprocessing/UnrealBloomPass.js";

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    document.body.appendChild(renderer.domElement);

    // Scene / Camera
    const scene = new THREE.Scene();
    scene.background = new THREE.Color(0x05070d);
    scene.fog = new THREE.Fog(0x05070d, 10, 40);

    const camera = new THREE.PerspectiveCamera(
      60,
      window.innerWidth / window.innerHeight,
      0.1,
      100
    );
    camera.position.set(0, 2.5, 8);

    // Controls
    const controls = new OrbitControls(camera, renderer.domElement);
    controls.enableDamping = true;
    controls.dampingFactor = 0.06;

    // Lights
    const ambient = new THREE.AmbientLight(0x404060, 0.7);
    scene.add(ambient);

    const pointLight = new THREE.PointLight(0x66ccff, 2.5, 50, 2);
    pointLight.position.set(4, 3, 4);
    scene.add(pointLight);

    const dirLight = new THREE.DirectionalLight(0xffffff, 1.2);
    dirLight.position.set(-3, 5, 2);
    scene.add(dirLight);

    // Floor
    const floorGeo = new THREE.PlaneGeometry(50, 50);
    const floorMat = new THREE.MeshStandardMaterial({
      color: 0x11131a,
      roughness: 0.95,
      metalness: 0.0
    });
    const floor = new THREE.Mesh(floorGeo, floorMat);
    floor.rotation.x = -Math.PI / 2;
    floor.position.y = -1.5;
    scene.add(floor);

    // Custom shader material
    const shaderMat = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0xff3df2) }
      },
      vertexShader: `
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalMatrix * normal;
          vPosition = position;

          vec3 pos = position;
          pos += normal * sin(position.y * 8.0 + position.x * 4.0) * 0.08;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);
          float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 6.0);
          vec3 color = mix(uColorA, uColorB, wave);

          float glow = fresnel * 1.5;
          gl_FragColor = vec4(color + glow, 1.0);
        }
      `
    });

    // Main object
    const sphere = new THREE.Mesh(
      new THREE.IcosahedronGeometry(1.5, 5),
      shaderMat
    );
    sphere.position.y = 0.5;
    scene.add(sphere);

    // Secondary objects
    const torus = new THREE.Mesh(
      new THREE.TorusKnotGeometry(0.8, 0.25, 180, 24),
      new THREE.MeshStandardMaterial({
        color: 0xffffff,
        metalness: 0.9,
        roughness: 0.15,
        emissive: 0x111111
      })
    );
    torus.position.set(3, 0.5, 0);
    scene.add(torus);

    const box = new THREE.Mesh(
      new THREE.BoxGeometry(1, 1, 1),
      new THREE.MeshStandardMaterial({
        color: 0x88aaff,
        metalness: 0.4,
        roughness: 0.35
      })
    );
    box.position.set(-3, 0, 0);
    scene.add(box);

    // Post-processing
    const composer = new EffectComposer(renderer);
    composer.addPass(new RenderPass(scene, camera));

    const bloomPass = new UnrealBloomPass(
      new THREE.Vector2(window.innerWidth, window.innerHeight),
      1.1,  // strength
      0.5,  // radius
      0.2   // threshold
    );
    composer.addPass(bloomPass);

    // Animation loop
    const clock = new THREE.Clock();

    function animate() {
      requestAnimationFrame(animate);

      const t = clock.getElapsedTime();
      shaderMat.uniforms.uTime.value = t;

      // Dynamic lighting motion
      pointLight.position.x = Math.cos(t * 0.8) * 5;
      pointLight.position.z = Math.sin(t * 0.8) * 5;
      pointLight.position.y = 2.5 + Math.sin(t * 1.7) * 1.2;

      // Object animation
      sphere.rotation.y = t * 0.35;
      sphere.rotation.x = Math.sin(t * 0.4) * 0.2;

      torus.rotation.x = t * 0.6;
      torus.rotation.y = t * 0.4;

      box.rotation.x = t * 0.5;
      box.rotation.y = t * 0.7;

      controls.update();
      composer.render();
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      const w = window.innerWidth;
      const h = window.innerHeight;

      camera.aspect = w / h;
      camera.updateProjectionMatrix();

      renderer.setSize(w, h);
      composer.setSize(w, h);
    });
  </script>
</body>
</html>
