## 4) `main.js`

```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.getElementById("scene");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 8, 25);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 1.5, 5);

// Controls
const controls = new OrbitControls(camera, canvas);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.25);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffffff, 2.2);
keyLight.position.set(4, 6, 3);
scene.add(keyLight);

const fillLight = new THREE.PointLight(0x44aaff, 20, 20);
fillLight.position.set(-3, 2, 2);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff55aa, 15, 20);
rimLight.position.set(0, 3, -4);
scene.add(rimLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x0b1020,
  roughness: 1,
  metalness: 0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Shader material for the main object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0xf72585) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalMatrix * normal;
      vPosition = position;

      vec3 pos = position;
      float wave = sin(pos.y * 4.0 + uTime * 2.0) * 0.08;
      pos += normal * wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 n = normalize(vNormal);
      float fresnel = pow(1.0 - abs(n.z), 3.0);

      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 3.0);
      vec3 base = mix(uColorA, uColorB, pulse);

      vec3 color = base + fresnel * 0.8;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const geometry = new THREE.TorusKnotGeometry(1, 0.35, 180, 24);
const object = new THREE.Mesh(geometry, shaderMaterial);
object.position.y = 1.2;
scene.add(object);

// Secondary object for depth
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.5, 32, 32),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.2,
    metalness: 0.8,
  })
);
sphere.position.set(-2, 0.7, -1);
scene.add(sphere);

// Animated point light
const movingLight = new THREE.PointLight(0xffffff, 30, 15);
movingLight.position.set(0, 3, 0);
scene.add(movingLight);

// Clock
const clock = new THREE.Clock();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});

// Animation loop
function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Update shader time
  shaderMaterial.uniforms.uTime.value = t;

  // Animate objects
  object.rotation.x = t * 0.35;
  object.rotation.y = t * 0.6;

  sphere.rotation.y = t * 0.4;

  // Move light dynamically
  movingLight.position.x = Math.sin(t * 1.2) * 4;
  movingLight.position.z = Math.cos(t * 1.2) * 4;
  movingLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.5;

  // Subtle camera drift
  camera.position.x = Math.sin(t * 0.2) * 0.4;
  camera.position.y = 1.5 + Math.sin(t * 0.3) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}

animate();
```

