## 4) `main.js`

```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.getElementById("scene");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.25);
scene.add(ambient);

const hemi = new THREE.HemisphereLight(0x9fd3ff, 0x1a1a2a, 0.6);
scene.add(hemi);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(5, 8, 4);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0x66ccff, 40, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x0b1020,
  metalness: 0.2,
  roughness: 0.95,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Grid helper
const grid = new THREE.GridHelper(40, 40, 0x335577, 0x1a2233);
grid.position.y = 0.001;
scene.add(grid);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x7209b7) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalMatrix * normal;
      vec3 pos = position;

      // Simple animated displacement
      float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.08;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vPosition = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));

      float diff = max(dot(n, lightDir), 0.0);
      float fresnel = pow(1.0 - max(dot(n, normalize(-vPosition)), 0.0), 3.0);

      float pulse = 0.5 + 0.5 * sin(uTime * 2.5 + vPosition.y * 3.0);
      vec3 base = mix(uColorA, uColorB, pulse);

      vec3 color = base * (0.25 + diff * 0.9) + fresnel * 0.8;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const sphere = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.2, 5),
  shaderMaterial
);
sphere.position.set(0, 1.6, 0);
scene.add(sphere);

// Secondary objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.7, 0.22, 180, 24),
  new THREE.MeshStandardMaterial({
    color: 0xff7b00,
    metalness: 0.8,
    roughness: 0.25,
  })
);
torus.position.set(-2.5, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0x7cdbff,
    metalness: 0.4,
    roughness: 0.35,
  })
);
box.position.set(2.5, 1.0, 0);
scene.add(box);

// Floating particles
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const particlePos = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  particlePos[i * 3 + 0] = (Math.random() - 0.5) * 24;
  particlePos[i * 3 + 1] = Math.random() * 10;
  particlePos[i * 3 + 2] = (Math.random() - 0.5) * 24;
}

particleGeo.setAttribute("position", new THREE.BufferAttribute(particlePos, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.05,
  transparent: true,
  opacity: 0.8,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Update shader time
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Animate objects
  sphere.rotation.y = elapsed * 0.35;
  sphere.rotation.x = elapsed * 0.15;

  torus.rotation.x = elapsed * 0.7;
  torus.rotation.y = elapsed * 0.4;

  box.rotation.x = elapsed * 0.5;
  box.rotation.z = elapsed * 0.3;

  // Dynamic light motion
  pointLight.position.x = Math.sin(elapsed * 1.2) * 4.0;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4.0;
  pointLight.position.y = 2.0 + Math.sin(elapsed * 2.0) * 0.5;

  // Particle drift
  particles.rotation.y = elapsed * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

