import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

const canvas = document.getElementById("scene-canvas");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambientLight = new THREE.AmbientLight(0x8899ff, 0.35);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 2.0);
directionalLight.position.set(5, 8, 3);
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0x66ccff, 25, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11151f,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = false;
scene.add(ground);

// Objects
const sphereGeo = new THREE.SphereGeometry(1, 64, 64);
const sphereMat = new THREE.MeshStandardMaterial({
  color: 0x88aaff,
  roughness: 0.2,
  metalness: 0.7,
});
const sphere = new THREE.Mesh(sphereGeo, sphereMat);
sphere.position.set(-1.8, 1.2, 0);
scene.add(sphere);

const torusGeo = new THREE.TorusKnotGeometry(0.8, 0.28, 180, 24);
const torusMat = new THREE.MeshStandardMaterial({
  color: 0xff8844,
  roughness: 0.35,
  metalness: 0.8,
});
const torus = new THREE.Mesh(torusGeo, torusMat);
torus.position.set(1.8, 1.4, 0);
scene.add(torus);

// Shader effect: animated glowing plane
const shaderGeo = new THREE.PlaneGeometry(8, 8, 128, 128);
const shaderMat = new THREE.ShaderMaterial({
  transparent: true,
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0x7a5cff) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      vUv = uv;
      vec3 pos = position;

      float wave = sin((pos.x * 2.0) + uTime * 2.0) * 0.08;
      wave += cos((pos.y * 3.0) + uTime * 1.5) * 0.08;
      pos.z += wave;

      vWave = wave;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec2 vUv;
    varying float vWave;

    void main() {
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 8.0 + vUv.y * 6.0);
      vec3 color = mix(uColorA, uColorB, vUv.y);
      color += pulse * 0.15;
      float alpha = 0.25 + abs(vWave) * 1.5;
      gl_FragColor = vec4(color, alpha);
    }
  `,
});
const shaderPlane = new THREE.Mesh(shaderGeo, shaderMat);
shaderPlane.rotation.x = -Math.PI / 2;
shaderPlane.position.y = 0.02;
scene.add(shaderPlane);

// Floating particles
const particleCount = 500;
const particlePositions = new Float32Array(particleCount * 3);
for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 30;
  particlePositions[i * 3 + 1] = Math.random() * 10 + 0.5;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 30;
}
const particleGeo = new THREE.BufferGeometry();
particleGeo.setAttribute(
  "position",
  new THREE.BufferAttribute(particlePositions, 3)
);
const particleMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.05,
  transparent: true,
  opacity: 0.8,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  const elapsed = clock.getElapsedTime();

  // Dynamic lighting
  pointLight.position.x = Math.sin(elapsed * 1.2) * 3.5;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 3.5;
  pointLight.position.y = 2.0 + Math.sin(elapsed * 2.0) * 0.5;
  pointLight.intensity = 18 + Math.sin(elapsed * 3.0) * 6;

  directionalLight.position.x = Math.cos(elapsed * 0.4) * 6;
  directionalLight.position.z = Math.sin(elapsed * 0.4) * 6;

  // Object motion
  sphere.rotation.y += 0.01;
  sphere.rotation.x = Math.sin(elapsed * 0.8) * 0.2;

  torus.rotation.x += 0.008;
  torus.rotation.y += 0.012;

  // Shader animation
  shaderMat.uniforms.uTime.value = elapsed;

  // Particle drift
  particles.rotation.y = elapsed * 0.03;

  controls.update();
  renderer.render(scene, camera);
  requestAnimationFrame(animate);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
