import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

const canvas = document.getElementById("scene");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x6b7cff, 0.35);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffffff, 2.2);
keyLight.position.set(5, 8, 4);
scene.add(keyLight);

const fillLight = new THREE.PointLight(0x00d4ff, 20, 30);
fillLight.position.set(-4, 2, 3);
scene.add(fillLight);

const rimLight = new THREE.PointLight(0xff4fd8, 15, 30);
rimLight.position.set(0, 4, -6);
scene.add(rimLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x10131f,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -1;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0xff4fd8) },
  },
  vertexShader: `
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));
      float diff = max(dot(n, lightDir), 0.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 2.5 + vUv.x * 8.0);
      vec3 base = mix(uColorA, uColorB, wave);

      float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

      vec3 color = base * (0.25 + diff * 0.9) + fresnel * 0.35;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.35, 180, 24),
  shaderMaterial
);
torus.position.set(0, 1.2, 0);
scene.add(torus);

const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.6, 48, 48),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.15,
    metalness: 0.85,
  })
);
sphere.position.set(-2.2, 0.2, 0.5);
scene.add(sphere);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0x8899ff,
    roughness: 0.35,
    metalness: 0.4,
  })
);
box.position.set(2.2, 0.0, -0.5);
scene.add(box);

// Helper particles
const particlesCount = 500;
const positions = new Float32Array(particlesCount * 3);
for (let i = 0; i < particlesCount; i++) {
  positions[i * 3 + 0] = (Math.random() - 0.5) * 30;
  positions[i * 3 + 1] = Math.random() * 12;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 30;
}

const particlesGeo = new THREE.BufferGeometry();
particlesGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

const particlesMat = new THREE.PointsMaterial({
  color: 0xaaccff,
  size: 0.03,
  transparent: true,
  opacity: 0.7,
});

const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = t;

  torus.rotation.x = t * 0.4;
  torus.rotation.y = t * 0.7;

  sphere.position.y = 0.2 + Math.sin(t * 1.8) * 0.35;
  box.rotation.x = t * 0.5;
  box.rotation.y = t * 0.8;

  fillLight.position.x = Math.sin(t * 1.2) * 5;
  fillLight.position.z = Math.cos(t * 1.2) * 5;

  rimLight.intensity = 12 + Math.sin(t * 3.0) * 3;

  particles.rotation.y = t * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
