## 4) `main.js`

```js
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas / renderer
const canvas = document.getElementById("scene");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070c);
scene.fog = new THREE.Fog(0x05070c, 10, 30);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x8899ff, 0.25);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.0);
dirLight.position.set(5, 8, 4);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0x66ccff, 40, 20, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11151f,
  roughness: 1.0,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x9b5de5) },
    uLightPos: { value: pointLight.position.clone() },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);

      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    precision highp float;

    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform vec3 uLightPos;

    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(uLightPos - vWorldPos);
      vec3 V = normalize(cameraPosition - vWorldPos);
      vec3 H = normalize(L + V);

      float diff = max(dot(N, L), 0.0);
      float spec = pow(max(dot(N, H), 0.0), 64.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.x * 10.0 + vUv.y * 8.0);
      vec3 baseColor = mix(uColorA, uColorB, wave);

      // Fresnel rim
      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      vec3 color = baseColor * (0.15 + diff * 0.95);
      color += spec * vec3(1.0);
      color += fresnel * vec3(0.8, 0.9, 1.0) * 0.8;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1.2, 64, 64),
  shaderMaterial
);
sphere.position.y = 1.2;
scene.add(sphere);

// Secondary objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.7, 0.22, 180, 24),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    metalness: 0.8,
    roughness: 0.2,
  })
);
torus.position.set(-2.2, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0x88aaff,
    metalness: 0.3,
    roughness: 0.4,
  })
);
box.position.set(2.2, 0.5, 0);
scene.add(box);

// Simple particle stars
const starCount = 500;
const starGeo = new THREE.BufferGeometry();
const starPositions = new Float32Array(starCount * 3);

for (let i = 0; i < starCount; i++) {
  const r = 20 + Math.random() * 30;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);

  starPositions[i * 3 + 0] = r * Math.sin(phi) * Math.cos(theta);
  starPositions[i * 3 + 1] = r * Math.cos(phi);
  starPositions[i * 3 + 2] = r * Math.sin(phi) * Math.sin(theta);
}

starGeo.setAttribute("position", new THREE.BufferAttribute(starPositions, 3));
const stars = new THREE.Points(
  starGeo,
  new THREE.PointsMaterial({
    color: 0xffffff,
    size: 0.06,
    sizeAttenuation: true,
  })
);
scene.add(stars);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();
  shaderMaterial.uniforms.uTime.value = t;
  shaderMaterial.uniforms.uLightPos.value.copy(pointLight.position);

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(t * 0.8) * 3.5;
  pointLight.position.z = Math.cos(t * 0.8) * 3.5;
  pointLight.position.y = 2.5 + Math.sin(t * 1.7) * 0.8;

  // Object motion
  sphere.rotation.y = t * 0.6;
  sphere.rotation.x = Math.sin(t * 0.4) * 0.2;

  torus.rotation.x = t * 0.5;
  torus.rotation.y = t * 0.8;

  box.rotation.x = t * 0.7;
  box.rotation.y = t * 0.4;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

