## `main.js`

```js
import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

const canvas = document.getElementById('scene-canvas');

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.physicallyCorrectLights = true;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 10, 30);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(4, 3, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.0);
directional.position.set(5, 8, 3);
scene.add(directional);

const pointLight = new THREE.PointLight(0x66aaff, 40, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 1.0,
  metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
ground.receiveShadow = true;
scene.add(ground);

// Objects
const sphereGeo = new THREE.SphereGeometry(1, 64, 64);
const sphereMat = new THREE.MeshStandardMaterial({
  color: 0xddddff,
  roughness: 0.25,
  metalness: 0.8
});
const sphere = new THREE.Mesh(sphereGeo, sphereMat);
sphere.position.set(-1.8, 1, 0);
scene.add(sphere);

const boxGeo = new THREE.BoxGeometry(1.2, 1.2, 1.2);
const boxMat = new THREE.MeshStandardMaterial({
  color: 0xff8844,
  roughness: 0.4,
  metalness: 0.2
});
const box = new THREE.Mesh(boxGeo, boxMat);
box.position.set(1.8, 1, 0);
scene.add(box);

// Custom shader object
const shaderGeo = new THREE.TorusKnotGeometry(0.7, 0.25, 180, 24);

const shaderMat = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0.0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0xf72585) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalMatrix * normal;
      vec3 pos = position;

      // Subtle wave deformation
      float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.05;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vPosition = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(vec3(0.3, 0.8, 0.5));
      float diff = max(dot(N, L), 0.0);

      float pulse = 0.5 + 0.5 * sin(uTime * 3.0 + vPosition.y * 2.0);
      vec3 base = mix(uColorA, uColorB, pulse);

      vec3 color = base * (0.25 + diff * 0.95);
      gl_FragColor = vec4(color, 1.0);
    }
  `
});

const shaderMesh = new THREE.Mesh(shaderGeo, shaderMat);
shaderMesh.position.set(0, 2.2, 0);
scene.add(shaderMesh);

// Decorative lights
const lightRing = new THREE.Mesh(
  new THREE.TorusGeometry(2.8, 0.03, 16, 100),
  new THREE.MeshBasicMaterial({ color: 0x3355ff })
);
lightRing.rotation.x = Math.PI / 2;
lightRing.position.y = 0.02;
scene.add(lightRing);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Object motion
  sphere.rotation.y = t * 0.6;
  box.rotation.x = t * 0.7;
  box.rotation.y = t * 0.4;
  shaderMesh.rotation.x = t * 0.5;
  shaderMesh.rotation.y = t * 0.8;

  // Dynamic lighting
  pointLight.position.x = Math.sin(t * 1.2) * 3.5;
  pointLight.position.z = Math.cos(t * 1.2) * 3.5;
  pointLight.position.y = 1.5 + Math.sin(t * 2.0) * 0.5;

  shaderMat.uniforms.uTime.value = t;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

