```js
import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
import { OrbitControls } from 'https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js';

// Canvas
const canvas = document.getElementById('scene');

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
  powerPreference: 'high-performance',
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.25);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffffff, 2.2);
keyLight.position.set(5, 8, 4);
scene.add(keyLight);

const fillLight = new THREE.DirectionalLight(0x4d7cff, 0.8);
fillLight.position.set(-6, 2, -3);
scene.add(fillLight);

const pointLight = new THREE.PointLight(0xff4fd8, 20, 20, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x0b1020,
  roughness: 1.0,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Grid helper
const grid = new THREE.GridHelper(40, 40, 0x223355, 0x111827);
grid.position.y = 0.001;
scene.add(grid);

// Custom shader material for animated object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4d7cff) },
    uColorB: { value: new THREE.Color(0xff4fd8) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalMatrix * normal;
      vec3 pos = position;

      float wave = sin(pos.x * 3.0 + uTime * 2.0) * 0.08;
      wave += cos(pos.y * 4.0 + uTime * 1.5) * 0.06;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vPosition = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));

      float diff = max(dot(n, lightDir), 0.0);
      float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);

      float t = 0.5 + 0.5 * sin(uTime + vPosition.y * 2.0);
      vec3 base = mix(uColorA, uColorB, t);

      vec3 color = base * (0.25 + diff * 0.9) + fresnel * 0.6;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
  side: THREE.DoubleSide,
});

// Main object
const torusKnot = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1, 0.35, 256, 32),
  shaderMaterial
);
torusKnot.position.set(0, 1.5, 0);
scene.add(torusKnot);

// Secondary objects
const sphereMat = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  roughness: 0.15,
  metalness: 0.9,
});

const sphere1 = new THREE.Mesh(new THREE.SphereGeometry(0.45, 32, 32), sphereMat);
sphere1.position.set(-2.2, 1.0, 0.5);
scene.add(sphere1);

const sphere2 = new THREE.Mesh(new THREE.SphereGeometry(0.35, 32, 32), sphereMat);
sphere2.position.set(2.0, 0.8, -0.8);
scene.add(sphere2);

// Floating particles
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 20;
  particlePositions[i * 3 + 1] = Math.random() * 8;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}

particleGeo.setAttribute('position', new THREE.BufferAttribute(particlePositions, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0x88aaff,
  size: 0.04,
  transparent: true,
  opacity: 0.8,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(elapsed * 1.2) * 3.5;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 3.5;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 0.8;

  keyLight.position.x = 5 + Math.sin(elapsed * 0.4) * 1.5;
  keyLight.position.z = 4 + Math.cos(elapsed * 0.4) * 1.5;

  // Object motion
  torusKnot.rotation.x = elapsed * 0.35;
  torusKnot.rotation.y = elapsed * 0.6;

  sphere1.rotation.y = elapsed * 0.8;
  sphere2.rotation.x = elapsed * 0.7;

  particles.rotation.y = elapsed * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
