import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Renderer
const canvas = document.getElementById("scene");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x8899ff, 0.35);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0xffffff, 2.2);
keyLight.position.set(5, 8, 4);
scene.add(keyLight);

const fillLight = new THREE.PointLight(0x44aaff, 20, 30);
fillLight.position.set(-4, 2, -2);
scene.add(fillLight);

const movingLight = new THREE.PointLight(0xff8844, 25, 25);
movingLight.position.set(0, 3, 0);
scene.add(movingLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4f46e5) },
    uColorB: { value: new THREE.Color(0x22d3ee) },
  },
  vertexShader: `
    varying vec3 vPosition;
    varying vec3 vNormal;

    void main() {
      vPosition = position;
      vNormal = normal;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vPosition;
    varying vec3 vNormal;

    void main() {
      float wave = 0.5 + 0.5 * sin(uTime + vPosition.y * 4.0 + vPosition.x * 2.0);
      float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);
      vec3 color = mix(uColorA, uColorB, wave);
      color += fresnel * 0.35;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMaterial
);
sphere.position.set(-1.8, 1.2, 0);
scene.add(sphere);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.4, 1.4, 1.4),
  new THREE.MeshStandardMaterial({
    color: 0xf97316,
    roughness: 0.35,
    metalness: 0.7,
  })
);
box.position.set(2, 1, 0);
scene.add(box);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.28, 160, 24),
  new THREE.MeshStandardMaterial({
    color: 0xe5e7eb,
    roughness: 0.2,
    metalness: 1.0,
  })
);
torus.position.set(0, 1.4, -2);
scene.add(torus);

// Simple particle field
const particleCount = 500;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 30;
  particlePositions[i * 3 + 1] = Math.random() * 12;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 30;
}

particleGeo.setAttribute(
  "position",
  new THREE.BufferAttribute(particlePositions, 3)
);

const particleMat = new THREE.PointsMaterial({
  color: 0x99ccff,
  size: 0.05,
  transparent: true,
  opacity: 0.8,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = t;

  sphere.rotation.y = t * 0.6;
  sphere.rotation.x = Math.sin(t * 0.7) * 0.2;

  box.rotation.x = t * 0.5;
  box.rotation.y = t * 0.8;

  torus.rotation.x = t * 0.35;
  torus.rotation.y = t * 0.55;

  movingLight.position.x = Math.sin(t * 1.2) * 4;
  movingLight.position.z = Math.cos(t * 1.2) * 4;
  movingLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.8;

  particles.rotation.y = t * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
