import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

// -----------------------------
// Basic setup
// -----------------------------
const app = document.getElementById('app');

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1020);
scene.fog = new THREE.Fog(0x0b1020, 12, 40);

const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(4, 3, 8);

const renderer = new THREE.WebGLRenderer({
  antialias: true,
  powerPreference: 'high-performance',
});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
app.appendChild(renderer.domElement);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// -----------------------------
// Lights
// -----------------------------
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 1.2);
directional.position.set(5, 8, 3);
scene.add(directional);

const pointLight = new THREE.PointLight(0x66aaff, 40, 20, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

// Helper to visualize moving light
const lightSphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.08, 16, 16),
  new THREE.MeshBasicMaterial({ color: 0x66aaff })
);
scene.add(lightSphere);

// -----------------------------
// Floor
// -----------------------------
const floorGeometry = new THREE.PlaneGeometry(30, 30, 1, 1);
const floorMaterial = new THREE.MeshStandardMaterial({
  color: 0x22262f,
  roughness: 0.95,
  metalness: 0.05,
});
const floor = new THREE.Mesh(floorGeometry, floorMaterial);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

// Grid helper for depth reference
const grid = new THREE.GridHelper(30, 30, 0x334455, 0x223344);
grid.position.y = 0.001;
scene.add(grid);

// -----------------------------
// Shader object
// -----------------------------
const shaderUniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x4cc9f0) },
  uColorB: { value: new THREE.Color(0x9b5de5) },
};

const vertexShader = `
  varying vec2 vUv;
  varying vec3 vNormal;
  varying vec3 vWorldPos;

  void main() {
    vUv = uv;
    vNormal = normalize(normalMatrix * normal);

    vec4 worldPos = modelMatrix * vec4(position, 1.0);
    vWorldPos = worldPos.xyz;

    gl_Position = projectionMatrix * viewMatrix * worldPos;
  }
`;

const fragmentShader = `
  precision highp float;

  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;

  varying vec2 vUv;
  varying vec3 vNormal;
  varying vec3 vWorldPos;

  void main() {
    // Animated wave pattern
    float wave = sin(vUv.x * 10.0 + uTime * 2.0) * 0.5 + 0.5;
    float pulse = sin(uTime * 3.0 + vWorldPos.y * 4.0) * 0.5 + 0.5;

    vec3 baseColor = mix(uColorA, uColorB, wave);
    baseColor += 0.15 * pulse;

    // Simple fake rim lighting
    vec3 viewDir = normalize(cameraPosition - vWorldPos);
    float rim = 1.0 - max(dot(normalize(vNormal), viewDir), 0.0);
    rim = pow(rim, 2.0);

    vec3 finalColor = baseColor + rim * vec3(0.8, 0.9, 1.0);

    gl_FragColor = vec4(finalColor, 1.0);
  }
`;

const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: shaderUniforms,
  vertexShader,
  fragmentShader,
});

const objectGeometry = new THREE.TorusKnotGeometry(1, 0.35, 180, 24);
const object = new THREE.Mesh(objectGeometry, shaderMaterial);
object.position.set(0, 1.6, 0);
scene.add(object);

// -----------------------------
// Additional scene objects
// -----------------------------
const boxMaterial = new THREE.MeshStandardMaterial({
  color: 0x8899aa,
  metalness: 0.3,
  roughness: 0.4,
});

for (let i = 0; i < 8; i++) {
  const box = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.5, 0.5), boxMaterial);
  const angle = (i / 8) * Math.PI * 2;
  const radius = 4.5;
  box.position.set(Math.cos(angle) * radius, 0.25, Math.sin(angle) * radius);
  scene.add(box);
}

// -----------------------------
// Animation loop
// -----------------------------
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();
  shaderUniforms.uTime.value = elapsed;

  // Animate object
  object.rotation.y = elapsed * 0.6;
  object.rotation.x = Math.sin(elapsed * 0.4) * 0.25;

  // Move point light in a circle
  pointLight.position.x = Math.cos(elapsed * 0.8) * 3.5;
  pointLight.position.z = Math.sin(elapsed * 0.8) * 3.5;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 1.5) * 0.8;

  lightSphere.position.copy(pointLight.position);

  // Subtle directional light motion
  directional.position.x = Math.cos(elapsed * 0.2) * 6;
  directional.position.z = Math.sin(elapsed * 0.2) * 6;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// -----------------------------
// Resize handling
// -----------------------------
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

