    powerPreference: "high-performance",
  });
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.2;
  container.appendChild(renderer.domElement);

  // Controls
  controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.target.set(0, 1, 0);

  // Lights
  ambientLight = new THREE.AmbientLight(0x404060, 0.5);
  scene.add(ambientLight);

  dirLight = new THREE.DirectionalLight(0xffffff, 1.5);
  dirLight.position.set(5, 8, 4);
  scene.add(dirLight);

  pointLight = new THREE.PointLight(0x66ccff, 50, 30, 2);
  pointLight.position.set(0, 3, 0);
  scene.add(pointLight);

  // Floor
  const floorGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x11131a,
    roughness: 0.9,
    metalness: 0.1,
  });
  floor = new THREE.Mesh(floorGeo, floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = -1;
  floor.receiveShadow = false;
  scene.add(floor);

  // Main objects
  const sphereGeo = new THREE.SphereGeometry(1, 64, 64);
  const sphereMat = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.25,
    metalness: 0.7,
  });
  sphere = new THREE.Mesh(sphereGeo, sphereMat);
  sphere.position.set(-1.8, 1, 0);
  scene.add(sphere);

  const torusGeo = new THREE.TorusKnotGeometry(0.8, 0.25, 180, 32);
  const torusMat = new THREE.MeshStandardMaterial({
    color: 0x88aaff,
    roughness: 0.2,
    metalness: 0.8,
  });
  torus = new THREE.Mesh(torusGeo, torusMat);
  torus.position.set(1.8, 1, 0);
  scene.add(torus);

  // Shader effect object
  const shaderGeo = new THREE.IcosahedronGeometry(1.1, 5);
  const shaderMat = new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColorA: { value: new THREE.Color(0x00d4ff) },
      uColorB: { value: new THREE.Color(0x7a00ff) },
    },
    vertexShader: `
      uniform float uTime;
      varying vec3 vNormal;
      varying vec3 vPosition;

      void main() {
        vNormal = normalMatrix * normal;
        vPosition = position;

        vec3 displaced = position + normal * sin(uTime + position.y * 4.0) * 0.08;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(displaced, 1.0);
      }
    `,
    fragmentShader: `
      uniform float uTime;
      uniform vec3 uColorA;
      uniform vec3 uColorB;
      varying vec3 vNormal;
      varying vec3 vPosition;

      void main() {
        float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);
        float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 3.0);
        vec3 color = mix(uColorA, uColorB, pulse);
        color += fresnel * 0.8;
        gl_FragColor = vec4(color, 1.0);
      }
    `,
  });

  shaderMesh = new THREE.Mesh(shaderGeo, shaderMat);
  shaderMesh.position.set(0, 1.2, -2.5);
  scene.add(shaderMesh);

  // Decorative particles
  addParticles();

  clock = new THREE.Clock();

  window.addEventListener("resize", onWindowResize);
}

function addParticles() {
  const count = 500;
  const positions = new Float32Array(count * 3);

  for (let i = 0; i < count; i++) {
    positions[i * 3 + 0] = (Math.random() - 0.5) * 30;
    positions[i * 3 + 1] = Math.random() * 12;
    positions[i * 3 + 2] = (Math.random() - 0.5) * 30;
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

  const mat = new THREE.PointsMaterial({
    color: 0x88ccff,
    size: 0.04,
    transparent: true,
    opacity: 0.8,
  });

  const points = new THREE.Points(geo, mat);
  scene.add(points);
}

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Animate objects
  sphere.rotation.y = elapsed * 0.6;
  sphere.rotation.x = elapsed * 0.2;

  torus.rotation.x = elapsed * 0.5;
  torus.rotation.y = elapsed * 0.8;

  shaderMesh.rotation.y = elapsed * 0.4;
  shaderMesh.rotation.x = Math.sin(elapsed * 0.7) * 0.2;
  shaderMesh.material.uniforms.uTime.value = elapsed;

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(elapsed * 1.2) * 4;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4;
  pointLight.position.y = 2.5 + Math.sin(elapsed * 2.0) * 0.8;

  dirLight.position.x = Math.cos(elapsed * 0.3) * 6;
  dirLight.position.z = Math.sin(elapsed * 0.3) * 6;

  controls.update();
  renderer.render(scene, camera);
}

function onWindowResize() {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
}
```

