import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.getElementById("scene");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 35);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.0);
directional.position.set(5, 8, 3);
scene.add(directional);

const pointLight = new THREE.PointLight(0x66ccff, 40, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 0.95,
  metalness: 0.0
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
ground.receiveShadow = true;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0x7c3aed) }
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vPosition;
    varying vec3 vNormal;

    void main() {
      vPosition = position;
      vNormal = normal;

      vec3 pos = position;
      pos.y += sin(pos.x * 2.0 + uTime) * 0.08;
      pos.x += cos(pos.y * 3.0 + uTime * 1.5) * 0.04;

      gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vPosition;
    varying vec3 vNormal;

    void main() {
      float fresnel = pow(1.0 - abs(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0))), 2.0);
      float pulse = 0.5 + 0.5 * sin(uTime * 2.0 + vPosition.y * 8.0);
      vec3 color = mix(uColorA, uColorB, pulse);

      color += fresnel * 0.35;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
  wireframe: false
});

// Objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMaterial
);
sphere.position.set(-1.8, 1.2, 0);
scene.add(sphere);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.28, 180, 24),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    metalness: 0.8,
    roughness: 0.2,
    emissive: 0x111111
  })
);
torus.position.set(1.8, 1.3, 0);
scene.add(torus);

// Floating particles
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  const i3 = i * 3;
  particlePositions[i3 + 0] = (Math.random() - 0.5) * 20;
  particlePositions[i3 + 1] = Math.random() * 8;
  particlePositions[i3 + 2] = (Math.random() - 0.5) * 20;
}

particleGeo.setAttribute(
  "position",
  new THREE.BufferAttribute(particlePositions, 3)
);

const particleMat = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.04,
  transparent: true,
  opacity: 0.8
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Update shader time
  shaderMaterial.uniforms.uTime.value = elapsed;

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(elapsed * 0.8) * 3.5;
  pointLight.position.z = Math.cos(elapsed * 0.8) * 3.5;
  pointLight.position.y = 1.5 + Math.sin(elapsed * 1.6) * 0.8;

  directional.position.x = Math.cos(elapsed * 0.3) * 6;
  directional.position.z = Math.sin(elapsed * 0.3) * 6;

  // Object animation
  sphere.rotation.y = elapsed * 0.6;
  sphere.rotation.x = elapsed * 0.2;

  torus.rotation.x = elapsed * 0.4;
  torus.rotation.y = elapsed * 0.7;

  particles.rotation.y = elapsed * 0.05;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
