import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Renderer
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.getElementById("app").appendChild(renderer.domElement);

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x050816);
scene.fog = new THREE.Fog(0x050816, 10, 35);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.target.set(0, 1, 0);

// Lights
const ambientLight = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambientLight);

const directionalLight = new THREE.DirectionalLight(0xffffff, 2.2);
directionalLight.position.set(5, 8, 4);
scene.add(directionalLight);

const pointLight = new THREE.PointLight(0x66ccff, 20, 20, 2);
pointLight.position.set(-3, 2, 2);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x111827,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x00d4ff) },
    uColorB: { value: new THREE.Color(0x7c3aed) },
  },
  vertexShader: `
    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec2 vUv;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.6));
      float diffuse = max(dot(normalize(vNormal), lightDir), 0.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 2.5 + vUv.x * 8.0);
      vec3 baseColor = mix(uColorA, uColorB, wave);

      float rim = 1.0 - max(dot(normalize(vNormal), vec3(0.0, 0.0, 1.0)), 0.0);
      rim = pow(rim, 2.0);

      vec3 color = baseColor * (0.25 + diffuse * 0.85) + rim * 0.35;
      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Objects
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(1, 64, 64),
  shaderMaterial
);
sphere.position.set(-1.8, 1.2, 0);
scene.add(sphere);

const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.8, 0.25, 180, 24),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.25,
    metalness: 0.8,
  })
);
torus.position.set(2.0, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1.2, 1.2, 1.2),
  new THREE.MeshStandardMaterial({
    color: 0xffb703,
    roughness: 0.4,
    metalness: 0.2,
  })
);
box.position.set(0, 0.8, -2.2);
scene.add(box);

// Decorative particles
const particlesCount = 300;
const positions = new Float32Array(particlesCount * 3);

for (let i = 0; i < particlesCount; i++) {
  positions[i * 3 + 0] = (Math.random() - 0.5) * 30;
  positions[i * 3 + 1] = Math.random() * 12;
  positions[i * 3 + 2] = (Math.random() - 0.5) * 30;
}

const particlesGeo = new THREE.BufferGeometry();
particlesGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

const particlesMat = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.05,
  transparent: true,
  opacity: 0.7,
});

const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  shaderMaterial.uniforms.uTime.value = elapsed;

  sphere.rotation.y = elapsed * 0.6;
  sphere.rotation.x = Math.sin(elapsed * 0.4) * 0.2;

  torus.rotation.x = elapsed * 0.4;
  torus.rotation.y = elapsed * 0.7;

  box.rotation.x = elapsed * 0.5;
  box.rotation.y = elapsed * 0.3;

  pointLight.position.x = Math.sin(elapsed) * 4;
  pointLight.position.z = Math.cos(elapsed * 0.8) * 4;

  particles.rotation.y = elapsed * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
