```js
import * as THREE from "https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/controls/OrbitControls.js";

const canvas = document.getElementById("scene");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 8, 25);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2, 6);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.35);
scene.add(ambient);

const keyLight = new THREE.DirectionalLight(0x88ccff, 2.2);
keyLight.position.set(3, 5, 2);
scene.add(keyLight);

const fillLight = new THREE.PointLight(0xff66aa, 20, 20);
fillLight.position.set(-3, 1.5, 2);
scene.add(fillLight);

const movingLight = new THREE.PointLight(0x66ffcc, 25, 25);
movingLight.position.set(0, 3, 0);
scene.add(movingLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(30, 30);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11151f,
  roughness: 1,
  metalness: 0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Custom shader material
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0xf72585) },
    uLightPos: { value: new THREE.Vector3() },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vNormal = normalize(normalMatrix * normal);

      vec3 pos = position;
      float wave = sin(pos.y * 6.0 + uTime * 2.0) * 0.08;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vWorldPos = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform vec3 uLightPos;

    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(uLightPos - vWorldPos);
      float diff = max(dot(N, L), 0.0);

      float fresnel = pow(1.0 - max(dot(N, normalize(-vWorldPos)), 0.0), 3.0);
      float stripes = 0.5 + 0.5 * sin((vWorldPos.y + uTime * 0.8) * 12.0);

      vec3 base = mix(uColorA, uColorB, stripes);
      vec3 color = base * (0.2 + diff * 1.2) + fresnel * 0.8;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const geometry = new THREE.TorusKnotGeometry(1, 0.35, 256, 32);
const object = new THREE.Mesh(geometry, shaderMaterial);
object.position.y = 1.2;
scene.add(object);

// Optional helper object for reference
const sphere = new THREE.Mesh(
  new THREE.SphereGeometry(0.35, 32, 32),
  new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.2,
    metalness: 0.8,
  })
);
sphere.position.set(2.2, 0.5, 0);
scene.add(sphere);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Animate object
  object.rotation.y = t * 0.6;
  object.rotation.x = Math.sin(t * 0.4) * 0.2;

  // Animate lights
  movingLight.position.x = Math.sin(t * 1.2) * 3.5;
  movingLight.position.z = Math.cos(t * 1.2) * 3.5;
  movingLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.5;

  fillLight.position.x = Math.cos(t * 0.8) * 4.0;
  fillLight.position.z = Math.sin(t * 0.8) * 4.0;

  // Update shader uniforms
  shaderMaterial.uniforms.uTime.value = t;
  shaderMaterial.uniforms.uLightPos.value.copy(movingLight.position);

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

