import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Renderer
const canvas = document.getElementById("scene");
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x7aa7ff, 0.25);
scene.add(ambient);

const dirLight = new THREE.DirectionalLight(0xffffff, 2.5);
dirLight.position.set(5, 8, 4);
scene.add(dirLight);

const pointLight = new THREE.PointLight(0x00d4ff, 30, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

const movingLight = new THREE.PointLight(0xff4fd8, 20, 18, 2);
movingLight.position.set(-4, 1.5, 0);
scene.add(movingLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(50, 50);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x0b1020,
  roughness: 1,
  metalness: 0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Grid helper
const grid = new THREE.GridHelper(50, 50, 0x223355, 0x111827);
grid.position.y = 0;
scene.add(grid);

// Custom shader material for the main object
const uniforms = {
  uTime: { value: 0 },
  uColorA: { value: new THREE.Color(0x00d4ff) },
  uColorB: { value: new THREE.Color(0xff4fd8) },
};

const vertexShader = `
  uniform float uTime;
  varying vec3 vNormal;
  varying vec3 vPosition;

  void main() {
    vNormal = normalMatrix * normal;
    vPosition = position;

    vec3 pos = position;

    // Subtle animated displacement
    float wave = sin(pos.x * 3.0 + uTime * 2.0) * 0.08;
    wave += cos(pos.y * 4.0 + uTime * 1.5) * 0.05;
    pos += normal * wave;

    gl_Position = projectionMatrix * modelViewMatrix * vec4(pos, 1.0);
  }
`;

const fragmentShader = `
  uniform float uTime;
  uniform vec3 uColorA;
  uniform vec3 uColorB;

  varying vec3 vNormal;
  varying vec3 vPosition;

  void main() {
    vec3 n = normalize(vNormal);
    vec3 lightDir = normalize(vec3(0.4, 0.8, 0.6));

    float diffuse = max(dot(n, lightDir), 0.0);
    float fresnel = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.5);

    float stripe = 0.5 + 0.5 * sin(vPosition.y * 8.0 + uTime * 4.0);
    vec3 base = mix(uColorA, uColorB, stripe);

    vec3 color = base * (0.25 + diffuse * 1.2);
    color += fresnel * vec3(1.0, 1.0, 1.0) * 0.8;

    gl_FragColor = vec4(color, 1.0);
  }
`;

const shaderMat = new THREE.ShaderMaterial({
  uniforms,
  vertexShader,
  fragmentShader,
});

// Main object
const geometry = new THREE.TorusKnotGeometry(1, 0.35, 256, 32);
const object = new THREE.Mesh(geometry, shaderMat);
object.position.y = 1.5;
scene.add(object);

// Secondary objects
const sphereMat = new THREE.MeshStandardMaterial({
  color: 0x9fb7ff,
  metalness: 0.8,
  roughness: 0.2,
});

const sphere1 = new THREE.Mesh(new THREE.SphereGeometry(0.35, 32, 32), sphereMat);
sphere1.position.set(-2.2, 1.0, 0);
scene.add(sphere1);

const sphere2 = new THREE.Mesh(new THREE.SphereGeometry(0.25, 32, 32), sphereMat);
sphere2.position.set(2.0, 0.8, -1.2);
scene.add(sphere2);

// Small emissive particles
const particleCount = 150;
const particleGeo = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  const i3 = i * 3;
  positions[i3 + 0] = (Math.random() - 0.5) * 18;
  positions[i3 + 1] = Math.random() * 8;
  positions[i3 + 2] = (Math.random() - 0.5) * 18;
}

particleGeo.setAttribute("position", new THREE.BufferAttribute(positions, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.04,
  transparent: true,
  opacity: 0.8,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();
  uniforms.uTime.value = t;

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(t * 1.2) * 3.0;
  pointLight.position.z = Math.cos(t * 1.2) * 3.0;
  pointLight.position.y = 1.8 + Math.sin(t * 2.0) * 0.4;

  movingLight.position.x = Math.cos(t * 0.7) * 5.0;
  movingLight.position.z = Math.sin(t * 0.7) * 5.0;
  movingLight.position.y = 1.2 + Math.sin(t * 1.8) * 0.8;

  // Object animation
  object.rotation.y = t * 0.6;
  object.rotation.x = Math.sin(t * 0.4) * 0.2;

  sphere1.position.y = 1.0 + Math.sin(t * 1.5) * 0.2;
  sphere2.position.y = 0.8 + Math.cos(t * 1.2) * 0.15;

  particles.rotation.y = t * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
