  transparent: true,
  opacity: 0.75,
});

const particles = new THREE.Points(particlesGeo, particlesMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Update shader uniforms
  shaderMaterial.uniforms.uTime.value = t;
  shaderMaterial.uniforms.uLightPos.value.copy(pointLight.position);

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(t * 1.2) * 4.0;
  pointLight.position.z = Math.cos(t * 1.2) * 4.0;
  pointLight.position.y = 2.0 + Math.sin(t * 2.0) * 0.5;

  directional.position.x = Math.cos(t * 0.4) * 6.0;
  directional.position.z = Math.sin(t * 0.4) * 6.0;

  // Object motion
  sphere.rotation.y = t * 0.4;
  sphere.rotation.x = Math.sin(t * 0.7) * 0.2;

  torus.rotation.x = t * 0.6;
  torus.rotation.y = t * 0.9;

  box.rotation.x = t * 0.5;
  box.rotation.y = t * 0.8;

  particles.rotation.y = t * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

