## `main.js`

```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.querySelector("#app");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 8, 30);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 7);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.2);
directional.position.set(5, 8, 3);
scene.add(directional);

const pointLight = new THREE.PointLight(0x66ccff, 30, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x10131d,
  roughness: 1,
  metalness: 0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Grid helper
const grid = new THREE.GridHelper(40, 40, 0x223355, 0x111827);
grid.position.y = 0;
scene.add(grid);

// Custom shader material for the main object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x9b5de5) },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vWorldPos;

    void main() {
      vec3 n = normalize(vNormal);
      vec3 lightDir = normalize(vec3(0.4, 0.8, 0.2));
      float diff = max(dot(n, lightDir), 0.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vWorldPos.y * 3.0 + vWorldPos.x * 2.0);
      vec3 baseColor = mix(uColorA, uColorB, wave);

      vec3 color = baseColor * (0.2 + diff * 1.2);
      float rim = pow(1.0 - max(dot(n, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);
      color += rim * 0.25;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const sphere = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.2, 4),
  shaderMaterial
);
sphere.position.y = 1.5;
scene.add(sphere);

// Secondary objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.7, 0.22, 128, 16),
  new THREE.MeshStandardMaterial({
    color: 0xffd166,
    metalness: 0.7,
    roughness: 0.2,
  })
);
torus.position.set(-2.5, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0xef476f,
    metalness: 0.2,
    roughness: 0.5,
  })
);
box.position.set(2.5, 0.5, 0);
scene.add(box);

// Floating particles
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 20;
  particlePositions[i * 3 + 1] = Math.random() * 8;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}

particleGeo.setAttribute(
  "position",
  new THREE.BufferAttribute(particlePositions, 3)
);

const particleMat = new THREE.PointsMaterial({
  color: 0x88ccff,
  size: 0.05,
  transparent: true,
  opacity: 0.8,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Simple fullscreen shader overlay
const overlayScene = new THREE.Scene();
const overlayCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

const overlayMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
  },
  vertexShader: `
    void main() {
      gl_Position = vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform float uTime;

    void main() {
      vec2 uv = gl_FragCoord.xy / vec2(1280.0, 720.0);
      float vignette = smoothstep(0.9, 0.2, distance(uv, vec2(0.5)));
      float scan = 0.02 * sin(gl_FragCoord.y * 1.5 + uTime * 10.0);
      vec3 color = vec3(0.02, 0.04, 0.08) * vignette + scan;
      gl_FragColor = vec4(color, 0.18);
    }
  `,
  transparent: true,
  depthWrite: false,
});

const overlayQuad = new THREE.Mesh(
  new THREE.PlaneGeometry(2, 2),
  overlayMaterial
);
overlayScene.add(overlayQuad);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const elapsed = clock.getElapsedTime();

  // Animate uniforms
  shaderMaterial.uniforms.uTime.value = elapsed;
  overlayMaterial.uniforms.uTime.value = elapsed;

  // Animate objects
  sphere.rotation.y = elapsed * 0.4;
  sphere.rotation.x = Math.sin(elapsed * 0.3) * 0.2;

  torus.rotation.x = elapsed * 0.6;
  torus.rotation.y = elapsed * 0.3;

  box.rotation.x = elapsed * 0.5;
  box.rotation.y = elapsed * 0.7;

  // Move light dynamically
  pointLight.position.x = Math.sin(elapsed * 1.2) * 4;
  pointLight.position.z = Math.cos(elapsed * 1.2) * 4;
  pointLight.position.y = 2 + Math.sin(elapsed * 2.0) * 0.5;

  // Animate particles
  particles.rotation.y = elapsed * 0.05;

  controls.update();

  renderer.render(scene, camera);
  renderer.render(overlayScene, overlayCamera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();

  renderer.setSize(window.innerWidth, window.innerHeight);
});
```

