```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

const canvas = document.getElementById("scene-canvas");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 12, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(4, 3, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.06;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0xffffff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.0);
directional.position.set(5, 8, 3);
scene.add(directional);

const pointLight = new THREE.PointLight(0x66aaff, 25, 20, 2);
pointLight.position.set(0, 2, 0);
scene.add(pointLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11151f,
  roughness: 0.95,
  metalness: 0.0,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
scene.add(ground);

// Custom shader material for dynamic effect
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x7209b7) },
  },
  vertexShader: `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vNormal = normalMatrix * normal;
      vec3 pos = position;

      // Subtle animated displacement
      float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.08;
      wave += cos(pos.y * 5.0 + uTime * 1.5) * 0.05;
      pos += normal * wave;

      vec4 worldPos = modelMatrix * vec4(pos, 1.0);
      vPosition = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;

    varying vec3 vNormal;
    varying vec3 vPosition;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(vec3(0.4, 0.8, 0.2));
      float diff = max(dot(N, L), 0.0);

      float fresnel = pow(1.0 - max(dot(N, vec3(0.0, 0.0, 1.0)), 0.0), 2.0);
      float pulse = 0.5 + 0.5 * sin(uTime * 3.0 + vPosition.y * 2.0);

      vec3 base = mix(uColorA, uColorB, pulse);
      vec3 color = base * (0.25 + diff * 0.85) + fresnel * 0.35;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const sphere = new THREE.Mesh(
  new THREE.IcosahedronGeometry(1.2, 5),
  shaderMaterial
);
sphere.position.set(0, 1.5, 0);
scene.add(sphere);

// Secondary objects
const torus = new THREE.Mesh(
  new THREE.TorusKnotGeometry(0.7, 0.22, 180, 24),
  new THREE.MeshStandardMaterial({
    color: 0xffc857,
    metalness: 0.8,
    roughness: 0.25,
  })
);
torus.position.set(-2.2, 1.2, 0);
scene.add(torus);

const box = new THREE.Mesh(
  new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshStandardMaterial({
    color: 0x8ecae6,
    metalness: 0.4,
    roughness: 0.35,
  })
);
box.position.set(2.2, 0.5, 0);
scene.add(box);

// Simple floating particles
const particleCount = 250;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 18;
  particlePositions[i * 3 + 1] = Math.random() * 8;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 18;
}

particleGeo.setAttribute(
  "position",
  new THREE.BufferAttribute(particlePositions, 3)
);

const particleMat = new THREE.PointsMaterial({
  color: 0xffffff,
  size: 0.03,
  transparent: true,
  opacity: 0.8,
});

const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  controls.update();

  // Dynamic lighting motion
  pointLight.position.x = Math.sin(t * 0.8) * 3.5;
  pointLight.position.z = Math.cos(t * 0.8) * 3.5;
  pointLight.position.y = 2.0 + Math.sin(t * 1.3) * 0.5;

  directional.position.x = Math.cos(t * 0.3) * 6.0;
  directional.position.z = Math.sin(t * 0.3) * 6.0;

  // Object animation
  sphere.rotation.y = t * 0.35;
  sphere.rotation.x = Math.sin(t * 0.4) * 0.15;
  shaderMaterial.uniforms.uTime.value = t;

  torus.rotation.x = t * 0.5;
  torus.rotation.y = t * 0.8;

  box.rotation.x = t * 0.6;
  box.rotation.y = t * 0.4;

  particles.rotation.y = t * 0.03;

  renderer.render(scene, camera);
}

animate();

// Resize handling
window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
});
```

