## `main.js`

```js
import * as THREE from "https://unpkg.com/three@0.160.0/build/three.module.js";
import { OrbitControls } from "https://unpkg.com/three@0.160.0/examples/jsm/controls/OrbitControls.js";

// Canvas
const canvas = document.getElementById("scene");

// Renderer
const renderer = new THREE.WebGLRenderer({
  canvas,
  antialias: true,
  alpha: false,
});
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.physicallyCorrectLights = true;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;

// Scene
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x05070d);
scene.fog = new THREE.Fog(0x05070d, 10, 40);

// Camera
const camera = new THREE.PerspectiveCamera(
  60,
  window.innerWidth / window.innerHeight,
  0.1,
  100
);
camera.position.set(0, 2.5, 8);

// Controls
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.target.set(0, 1, 0);

// Lights
const ambient = new THREE.AmbientLight(0x88aaff, 0.25);
scene.add(ambient);

const directional = new THREE.DirectionalLight(0xffffff, 2.0);
directional.position.set(5, 8, 3);
scene.add(directional);

const pointLight = new THREE.PointLight(0x66ccff, 25, 30, 2);
pointLight.position.set(0, 3, 0);
scene.add(pointLight);

const movingLight = new THREE.PointLight(0xff6699, 18, 25, 2);
movingLight.position.set(-4, 2, 0);
scene.add(movingLight);

// Ground
const groundGeo = new THREE.PlaneGeometry(40, 40, 1, 1);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x11151f,
  metalness: 0.2,
  roughness: 0.9,
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.01;
ground.receiveShadow = false;
scene.add(ground);

// Custom shader material for the main object
const shaderMaterial = new THREE.ShaderMaterial({
  uniforms: {
    uTime: { value: 0 },
    uColorA: { value: new THREE.Color(0x4cc9f0) },
    uColorB: { value: new THREE.Color(0x9b5de5) },
    uLightPos: { value: new THREE.Vector3() },
  },
  vertexShader: `
    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);

      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPos = worldPos.xyz;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: `
    precision highp float;

    uniform float uTime;
    uniform vec3 uColorA;
    uniform vec3 uColorB;
    uniform vec3 uLightPos;

    varying vec3 vNormal;
    varying vec3 vWorldPos;
    varying vec2 vUv;

    void main() {
      vec3 N = normalize(vNormal);
      vec3 L = normalize(uLightPos - vWorldPos);
      vec3 V = normalize(cameraPosition - vWorldPos);
      vec3 H = normalize(L + V);

      float diff = max(dot(N, L), 0.0);
      float spec = pow(max(dot(N, H), 0.0), 64.0);

      float fresnel = pow(1.0 - max(dot(N, V), 0.0), 3.0);

      float wave = 0.5 + 0.5 * sin(uTime * 2.0 + vUv.y * 8.0 + vUv.x * 4.0);
      vec3 base = mix(uColorA, uColorB, wave);

      vec3 color = base * (0.18 + diff * 1.2);
      color += spec * vec3(1.0);
      color += fresnel * 0.35 * vec3(0.7, 0.9, 1.0);

      // subtle emissive pulse
      color += 0.08 * sin(uTime * 3.0 + vWorldPos.y * 2.0) * base;

      gl_FragColor = vec4(color, 1.0);
    }
  `,
});

// Main object
const torusKnot = new THREE.Mesh(
  new THREE.TorusKnotGeometry(1.2, 0.38, 220, 32),
  shaderMaterial
);
torusKnot.position.y = 1.4;
scene.add(torusKnot);

// Secondary objects
const sphereMat = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  metalness: 0.8,
  roughness: 0.15,
});

const spheres = [];
for (let i = 0; i < 6; i++) {
  const sphere = new THREE.Mesh(new THREE.SphereGeometry(0.18, 32, 32), sphereMat);
  const angle = (i / 6) * Math.PI * 2;
  sphere.position.set(Math.cos(angle) * 3.2, 1.2, Math.sin(angle) * 3.2);
  scene.add(sphere);
  spheres.push(sphere);
}

// Floating particles
const particleCount = 300;
const particleGeo = new THREE.BufferGeometry();
const particlePositions = new Float32Array(particleCount * 3);

for (let i = 0; i < particleCount; i++) {
  particlePositions[i * 3 + 0] = (Math.random() - 0.5) * 20;
  particlePositions[i * 3 + 1] = Math.random() * 10;
  particlePositions[i * 3 + 2] = (Math.random() - 0.5) * 20;
}
particleGeo.setAttribute("position", new THREE.BufferAttribute(particlePositions, 3));

const particleMat = new THREE.PointsMaterial({
  color: 0x99ccff,
  size: 0.04,
  transparent: true,
  opacity: 0.7,
});
const particles = new THREE.Points(particleGeo, particleMat);
scene.add(particles);

// Animation loop
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);

  const t = clock.getElapsedTime();

  // Update shader uniforms
  shaderMaterial.uniforms.uTime.value = t;
  shaderMaterial.uniforms.uLightPos.value.copy(pointLight.position);

  // Animate main object
  torusKnot.rotation.y = t * 0.45;
  torusKnot.rotation.x = Math.sin(t * 0.4) * 0.2;

  // Animate lights
  pointLight.position.x = Math.sin(t * 1.2) * 3.5;
  pointLight.position.z = Math.cos(t * 1.2) * 3.5;
  pointLight.position.y = 2.5 + Math.sin(t * 2.0) * 0.6;

  movingLight.position.x = Math.cos(t * 0.8) * 4.5;
  movingLight.position.z = Math.sin(t * 0.8) * 4.5;
  movingLight.position.y = 1.5 + Math.cos(t * 1.5) * 0.8;

  // Animate spheres
  spheres.forEach((s, i) => {
    const a = t * 0.6 + i;
    s.position.y = 1.2 + Math.sin(a * 2.0) * 0.25;
    s.scale.setScalar(1.0 + 0.15 * Math.sin(a * 3.0));
  });

  // Rotate particles slowly
  particles.rotation.y = t * 0.03;

  controls.update();
  renderer.render(scene, camera);
}

