    const directionalLight = new THREE.DirectionalLight(0xffffff, 1.2);
    directionalLight.position.set(-2, 3, 1);
    scene.add(directionalLight);

    // Geometry
    const geometry = new THREE.TorusKnotGeometry(0.8, 0.25, 128, 32);

    // Custom shader material
    const material = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 },
        uColorA: { value: new THREE.Color(0x00d4ff) },
        uColorB: { value: new THREE.Color(0xff4fd8) }
      },
      vertexShader: `
        uniform float uTime;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vNormal = normalMatrix * normal;
          vec3 pos = position;

          // Subtle vertex wobble
          float wave = sin(pos.x * 4.0 + uTime * 2.0) * 0.03;
          pos += normal * wave;

          vec4 worldPos = modelMatrix * vec4(pos, 1.0);
          vPosition = worldPos.xyz;

          gl_Position = projectionMatrix * viewMatrix * worldPos;
        }
      `,
      fragmentShader: `
        uniform float uTime;
        uniform vec3 uColorA;
        uniform vec3 uColorB;

        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vec3 N = normalize(vNormal);
          vec3 L = normalize(vec3(0.5, 1.0, 0.3));
          float diff = max(dot(N, L), 0.0);

          // Animated gradient
          float t = 0.5 + 0.5 * sin(uTime + vPosition.y * 2.0);
          vec3 base = mix(uColorA, uColorB, t);

          // Simple rim light
          vec3 V = normalize(-vPosition);
          float rim = pow(1.0 - max(dot(N, V), 0.0), 2.0);

          vec3 color = base * (0.25 + diff * 0.9) + rim * 0.8;
          gl_FragColor = vec4(color, 1.0);
        }
      `
    });

