    ground.position.y = -1;
    scene.add(ground);

    // Shader material
    const shaderMaterial = new THREE.ShaderMaterial({
      uniforms: {
        uTime: { value: 0.0 }
      },
      vertexShader: `
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          vUv = uv;
          vNormal = normalMatrix * normal;
          vPosition = position;

          gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
        }
      `,
      fragmentShader: `
        uniform float uTime;
        varying vec2 vUv;
        varying vec3 vNormal;
        varying vec3 vPosition;

        void main() {
          float wave = sin(vUv.x * 10.0 + uTime * 2.0) * 0.5 + 0.5;
          float glow = pow(1.0 - abs(vNormal.z), 2.0);

          vec3 baseColor = mix(vec3(0.1, 0.4, 1.0), vec3(1.0, 0.2, 0.6), wave);
          vec3 finalColor = baseColor + glow * 0.5;

          gl_FragColor = vec4(finalColor, 1.0);
        }
      `
    });

    // Main object
    const sphere = new THREE.Mesh(
      new THREE.SphereGeometry(1, 64, 64),
      shaderMaterial
    );
    scene.add(sphere);

    // Additional object for depth
    const cube = new THREE.Mesh(
      new THREE.BoxGeometry(0.8, 0.8, 0.8),
      new THREE.MeshStandardMaterial({
        color: 0x888888,
        metalness: 0.7,
        roughness: 0.2
      })
    );
    cube.position.set(2, 0, 0);
    scene.add(cube);

    // Animation loop
    function animate(time) {
      requestAnimationFrame(animate);

      shaderMaterial.uniforms.uTime.value = time * 0.001;

      sphere.rotation.y += 0.01;
      cube.rotation.x += 0.01;
      cube.rotation.y += 0.015;

      pointLight.position.x = Math.sin(time * 0.001) * 3;
      pointLight.position.z = Math.cos(time * 0.001) * 3;

      controls.update();
      renderer.render(scene, camera);
    }

    animate();

    // Resize handling
    window.addEventListener("resize", () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
      renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    });
  </script>
</body>
</html>
