### `PhysicsBody.cpp`
```cpp
#include "PhysicsBody.h"

namespace CustomPhysics
{
    void PhysicsBody::SetMass(float mass)
    {
        if (mass <= 0.0f)
        {
            m_mass = 0.0f;
            m_inverseMass = 0.0f;
            m_type = BodyType::Static;
            return;
        }

        m_mass = mass;
        m_inverseMass = 1.0f / mass;
    }

    void PhysicsBody::AddForce(const Vec3& force)
    {
        if (m_type != BodyType::Dynamic)
            return;

        m_accumulatedForce += force;
    }

    void PhysicsBody::ClearForces()
    {
        m_accumulatedForce = Vec3::Zero();
    }

    void PhysicsBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_type != BodyType::Dynamic || dt <= 0.0f)
            return;

        // a = F / m + gravity
        Vec3 acceleration = gravity;
        if (m_inverseMass > 0.0f)
            acceleration += m_accumulatedForce * m_inverseMass;

        // Semi-implicit Euler
        m_velocity += acceleration * dt;
        m_transform.position += m_velocity * dt;

        ClearForces();
    }
}
