## 2) Implementation

### `PhysicsPlugin.cpp`
```cpp
#include "PhysicsPlugin.h"
#include <algorithm>

namespace CustomPhysics
{
    void PhysicsWorld::IntegrateBody(RigidBody& body, float dt)
    {
        if (body.isStatic || body.invMass <= 0.0f)
            return;

        // Semi-implicit Euler integration
        Vec3 acceleration = gravity + body.forceAccum * body.invMass;
        body.velocity += acceleration * dt;
        body.position += body.velocity * dt;

        body.ClearForces();
    }

    void PhysicsWorld::ResolvePlaneCollisions(RigidBody& body)
    {
        // Simple point-body collision against planes
        for (const Plane& plane : planes)
        {
            float signedDistance = Dot(plane.normal, body.position) - plane.distance;

            if (signedDistance < 0.0f)
            {
                // Push out of plane
                body.position -= plane.normal * signedDistance;

                // Reflect velocity if moving into plane
                float vn = Dot(body.velocity, plane.normal);
                if (vn < 0.0f)
                {
                    body.velocity -= plane.normal * (1.0f + body.restitution) * vn;
                }
            }
        }
    }

    void PhysicsWorld::Step(float dt)
    {
        if (dt <= 0.0f)
            return;

        for (auto& bodyPtr : bodies)
        {
            RigidBody& body = *bodyPtr;
            IntegrateBody(body, dt);
            ResolvePlaneCollisions(body);
        }
    }

    bool PhysicsPlugin::Initialize()
    {
        if (initialized)
            return true;

        world.SetGravity({0.0f, -9.81f, 0.0f});
        initialized = true;
        return true;
    }

    void PhysicsPlugin::Shutdown()
    {
        initialized = false;
    }

    void PhysicsPlugin::Tick(float dt)
    {
        if (!initialized)
            return;

        world.Step(dt);
    }
}
