    if (body.useGravity) {
        body.linearVelocity += gravity * dt;
    }

    body.linearVelocity *= (1.0f - body.linearDamping);
    body.angularVelocity *= (1.0f - body.angularDamping);

    body.position += body.linearVelocity * dt;

