Use an accumulator to keep physics stable:

```cpp
void PhysicsWorld::Step(float frameDt) {
    accumulator += frameDt;
    while (accumulator >= fixedDt) {
        BroadPhase();
        NarrowPhase();
        SolveConstraints();
        Integrate(fixedDt);
        accumulator -= fixedDt;
    }
}
