### `PhysicsBody.cpp`
```cpp
#include "PhysicsBody.h"

namespace CustomPhysics
{
    PhysicsBody::PhysicsBody(uint64_t id, const PhysicsBodyDesc& desc)
        : m_id(id),
          m_position(desc.position),
          m_velocity(desc.velocity),
          m_accumulatedForce(desc.accumulatedForce),
          m_mass(desc.mass > 0.0f ? desc.mass : 1.0f),
          m_isStatic(desc.isStatic)
    {
    }

    uint64_t PhysicsBody::GetId() const { return m_id; }
    const Vec3& PhysicsBody::GetPosition() const { return m_position; }
    const Vec3& PhysicsBody::GetVelocity() const { return m_velocity; }

    void PhysicsBody::SetPosition(const Vec3& pos) { m_position = pos; }
    void PhysicsBody::SetVelocity(const Vec3& vel) { m_velocity = vel; }

    void PhysicsBody::ApplyForce(const Vec3& force)
    {
        if (!m_isStatic)
            m_accumulatedForce += force;
    }

    void PhysicsBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_isStatic)
            return;

        Vec3 totalForce = m_accumulatedForce + gravity * m_mass;
        Vec3 acceleration = (1.0f / m_mass) * totalForce;

        m_velocity += acceleration * dt;
        m_position += m_velocity * dt;

        // Clear forces after integration
        m_accumulatedForce = Vec3{};
    }
}
