void PhysicsWorld::Step(float dt)
{
    for (auto& body : bodies)
    {
        if (body.isStatic) continue;

        Vec3 acceleration{
            body.forceAccum.x / body.mass,
            body.forceAccum.y / body.mass,
            body.forceAccum.z / body.mass
        };

        body.velocity.x += acceleration.x * dt;
        body.velocity.y += acceleration.y * dt;
        body.velocity.z += acceleration.z * dt;

        body.position.x += body.velocity.x * dt;
        body.position.y += body.velocity.y * dt;
        body.position.z += body.velocity.z * dt;

        body.forceAccum = {0, 0, 0};
    }
}
