#include "PhysicsBody.h"
#include <algorithm>

namespace CustomPhysics
{
    PhysicsBody::PhysicsBody(uint32_t id) : m_id(id) {}

    uint32_t PhysicsBody::GetId() const { return m_id; }

    void PhysicsBody::SetTransform(const Transform& t) { m_transform = t; }
    const Transform& PhysicsBody::GetTransform() const { return m_transform; }

    void PhysicsBody::SetMass(float mass)
    {
        m_mass = std::max(0.0001f, mass);
        m_invMass = m_static ? 0.0f : 1.0f / m_mass;
    }

    float PhysicsBody::GetMass() const { return m_mass; }

    void PhysicsBody::SetVelocity(const Vec3& v) { m_velocity = v; }
    const Vec3& PhysicsBody::GetVelocity() const { return m_velocity; }

    void PhysicsBody::ApplyForce(const Vec3& force)
    {
        if (m_static) return;
        m_accumulatedForce += force;
    }

    void PhysicsBody::ApplyImpulse(const Vec3& impulse)
    {
        if (m_static) return;
        m_velocity += impulse * m_invMass;
    }

    void PhysicsBody::SetStatic(bool isStatic)
    {
        m_static = isStatic;
        m_invMass = (m_static || m_mass <= 0.0f) ? 0.0f : 1.0f / m_mass;
    }

    bool PhysicsBody::IsStatic() const { return m_static; }

    void PhysicsBody::SetShape(ShapeType type, const Vec3& dimensions)
    {
        m_shapeType = type;
        m_shapeDimensions = dimensions;
    }

    ShapeType PhysicsBody::GetShapeType() const { return m_shapeType; }
    Vec3 PhysicsBody::GetShapeDimensions() const { return m_shapeDimensions; }

    void PhysicsBody::Integrate(float dt, const Vec3& gravity)
    {
        if (m_static) return;

        Vec3 acceleration = gravity + (m_accumulatedForce * m_invMass);
        m_velocity += acceleration * dt;
        m_transform.position += m_velocity * dt;

        m_accumulatedForce = {0, 0, 0};
    }
}
