### `PhysicsWorld.cpp`
```cpp
#include "PhysicsWorld.h"
#include <algorithm>

int PhysicsWorld::CreateBody(const RigidBodyDesc& desc)
{
    m_bodies.emplace_back(desc);
    m_bodyToCollider.push_back(-1);
    return static_cast<int>(m_bodies.size() - 1);
}

int PhysicsWorld::CreateCollider(const ColliderDesc& desc)
{
    m_colliders.emplace_back(desc);
    return static_cast<int>(m_colliders.size() - 1);
}

void PhysicsWorld::AttachCollider(int bodyId, int colliderId)
{
    if (bodyId >= 0 && bodyId < static_cast<int>(m_bodyToCollider.size()))
        m_bodyToCollider[bodyId] = colliderId;
}

void PhysicsWorld::Step(float dt)
{
    for (auto& body : m_bodies)
        body.Integrate(dt, m_gravity);

    std::vector<Contact> contacts;
    DetectCollisions(contacts);
    ResolveContacts(contacts);
}

void PhysicsWorld::DetectCollisions(std::vector<Contact>& contacts)
{
    // Very simple O(n^2) broadphase for initial implementation.
    for (int i = 0; i < static_cast<int>(m_bodies.size()); ++i)
    {
        for (int j = i + 1; j < static_cast<int>(m_bodies.size()); ++j)
        {
            int colA = m_bodyToCollider[i];
            int colB = m_bodyToCollider[j];
            if (colA < 0 || colB < 0) continue;

            const auto& a = m_colliders[colA];
            const auto& b = m_colliders[colB];

            // Sphere-sphere only for starter version
            if (a.GetType() == ColliderType::Sphere && b.GetType() == ColliderType::Sphere)
            {
                Vec3 pa = m_bodies[i].GetPosition();
                Vec3 pb = m_bodies[j].GetPosition();
                float ra = a.GetDesc().radius;
                float rb = b.GetDesc().radius;

                Vec3 delta = pb - pa;
                float distSq = LengthSq(delta);
                float r = ra + rb;

                if (distSq < r * r)
                {
                    float dist = std::sqrt(std::max(distSq, 1e-6f));
                    Vec3 normal = delta * (1.0f / dist);
                    contacts.push_back({i, j, normal, r - dist});
                }
            }
        }
    }
}

void PhysicsWorld::ResolveContacts(const std::vector<Contact>& contacts)
{
    for (const auto& c : contacts)
    {
        auto& a = m_bodies[c.bodyA];
        auto& b = m_bodies[c.bodyB];

        float invMassA = a.GetInvMass();
        float invMassB = b.GetInvMass();
        float invMassSum = invMassA + invMassB;
        if (invMassSum <= 0.0f) continue;

        // Positional correction
        Vec3 correction = c.normal * (c.penetration / invMassSum);
        if (a.GetType() == BodyType::Dynamic)
            a.SetPosition(a.GetPosition() - correction * invMassA);
        if (b.GetType() == BodyType::Dynamic)
            b.SetPosition(b.GetPosition() + correction * invMassB);

        // Velocity impulse
        Vec3 relativeVel = b.GetVelocity() - a.GetVelocity();
        float velAlongNormal = Dot(relativeVel, c.normal);
        if (velAlongNormal > 0.0f) continue;

        float restitution = 0.2f;
        float j = -(1.0f + restitution) * velAlongNormal;
        j /= invMassSum;

        Vec3 impulse = c.normal * j;
        if (a.GetType() == BodyType::Dynamic)
            a.SetVelocity(a.GetVelocity() - impulse * invMassA);
        if (b.GetType() == BodyType::Dynamic)
            b.SetVelocity(b.GetVelocity() + impulse * invMassB);
    }
}
