void RigidBody::AddForce(const Vec3& force) {
    if (!isStatic) {
        accumulatedForce = accumulatedForce + force;
    }
}

void RigidBody::AddImpulse(const Vec3& impulse) {
    if (!isStatic && mass > 0.0f) {
        linearVelocity = linearVelocity + impulse * (1.0f / mass);
    }
}

void RigidBody::Integrate(float dt) {
    if (isStatic || mass <= 0.0f) return;

    Vec3 acceleration = accumulatedForce * (1.0f / mass);
    linearVelocity = linearVelocity + acceleration * dt;
    transform.position = transform.position + linearVelocity * dt;

    accumulatedForce = {0, 0, 0};
}

std::shared_ptr<RigidBody> PhysicsWorld::CreateRigidBody(const RigidBodyDesc& desc) {
    auto body = std::make_shared<RigidBody>(desc);
    bodies.push_back(body);
    return body;
}

void PhysicsWorld::DestroyRigidBody(const std::shared_ptr<RigidBody>& body) {
    bodies.erase(std::remove(bodies.begin(), bodies.end(), body), bodies.end());
}

