## 6) Force integration

```cpp
void PhysicsWorld::IntegrateForces(PhysicsBody& body, float dt)
{
    if (body.InvMass <= 0.0f)
        return;

    Vector3 acceleration = Gravity + body.ForceAccum * body.InvMass;
    body.LinearVelocity += acceleration * dt;

    body.LinearVelocity *= (1.0f - body.LinearDamping * dt);

    body.ForceAccum = Vector3(0, 0, 0);
    body.TorqueAccum = Vector3(0, 0, 0);
}
```

