## 7) Velocity integration

```cpp
void PhysicsWorld::IntegrateVelocity(PhysicsBody& body, float dt)
{
    body.Position += body.LinearVelocity * dt;

    // Simple angular integration placeholder
    body.Rotation = Normalize(
        body.Rotation + Quaternion(body.AngularVelocity * dt, 0.0f)
    );

    body.AngularVelocity *= (1.0f - body.AngularDamping * dt);
}
