Example sphere-sphere test:

```cpp
bool IntersectSphereSphere(
    const Vector3& aPos, float aRadius,
    const Vector3& bPos, float bRadius,
    Contact& outContact)
{
    Vector3 delta = bPos - aPos;
    float distSq = Dot(delta, delta);
    float radiusSum = aRadius + bRadius;

    if (distSq >= radiusSum * radiusSum)
        return false;

    float dist = std::sqrt(std::max(distSq, 1e-6f));
    outContact.Normal = delta / dist;
    outContact.Penetration = radiusSum - dist;
    outContact.ContactPoint = aPos + outContact.Normal * (aRadius - outContact.Penetration * 0.5f);
    return true;
}
```

