## 9) Impulse resolution

A simple collision response:

```cpp
void ResolveContact(PhysicsBody& a, PhysicsBody& b, const Contact& c)
{
    if (a.InvMass + b.InvMass <= 0.0f)
        return;

    Vector3 relativeVelocity = b.LinearVelocity - a.LinearVelocity;
    float velAlongNormal = Dot(relativeVelocity, c.Normal);

    if (velAlongNormal > 0.0f)
        return;

    float restitution = 0.2f;
    float j = -(1.0f + restitution) * velAlongNormal;
    j /= (a.InvMass + b.InvMass);

    Vector3 impulse = j * c.Normal;
    a.LinearVelocity -= impulse * a.InvMass;
    b.LinearVelocity += impulse * b.InvMass;

    // Positional correction
    const float percent = 0.8f;
    const float slop = 0.01f;
    float correctionMag = std::max(c.Penetration - slop, 0.0f) / (a.InvMass + b.InvMass) * percent;
    Vector3 correction = correctionMag * c.Normal;

    a.Position -= correction * a.InvMass;
    b.Position += correction * b.InvMass;
}
```

