## 5) Basic integration loop

A simple fixed-step update:

```cpp
void PhysicsWorld::Step(float dt)
{
    if (dt <= 0.0f)
        return;

    DetectCollisions();
    ResolveContacts();
    IntegrateBodies(dt);
    ClearForces();
}
```

A basic Euler integrator:

```cpp
void PhysicsWorld::IntegrateBodies(float dt)
{
    for (auto& body : bodies)
    {
        if (body.isStatic || !body.isAwake)
            continue;

        Vec3 acceleration{
            body.forceAccum.x * body.inverseMass,
            body.forceAccum.y * body.inverseMass,
            body.forceAccum.z * body.inverseMass
        };

        body.velocity.x += acceleration.x * dt;
        body.velocity.y += acceleration.y * dt;
        body.velocity.z += acceleration.z * dt;

        body.transform.position.x += body.velocity.x * dt;
        body.transform.position.y += body.velocity.y * dt;
        body.transform.position.z += body.velocity.z * dt;
    }
}
```

