### 3.1 Public API

```cpp
// PhysicsPlugin.h
#pragma once

#include <vector>
#include <functional>
#include <cstdint>

namespace CustomPhysics
{
    struct Vec3
    {
        float x, y, z;

        Vec3() : x(0), y(0), z(0) {}
        Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

        Vec3 operator+(const Vec3& rhs) const { return {x + rhs.x, y + rhs.y, z + rhs.z}; }
        Vec3 operator-(const Vec3& rhs) const { return {x - rhs.x, y - rhs.y, z - rhs.z}; }
        Vec3 operator*(float s) const { return {x * s, y * s, z * s}; }
        Vec3& operator+=(const Vec3& rhs) { x += rhs.x; y += rhs.y; z += rhs.z; return *this; }
    };

    inline float Dot(const Vec3& a, const Vec3& b)
    {
        return a.x * b.x + a.y * b.y + a.z * b.z;
    }

    inline float LengthSq(const Vec3& v)
    {
        return Dot(v, v);
    }

    enum class ShapeType
    {
        Sphere,
        Box
    };

    struct Shape
    {
        ShapeType type;
        Vec3 halfExtents; // for box
        float radius;     // for sphere
    };

    struct RigidBodyDesc
    {
        Vec3 position;
        Vec3 velocity;
        float mass = 1.0f;
        bool isStatic = false;
        Shape shape;
    };

    struct Contact
    {
        uint32_t bodyA;
        uint32_t bodyB;
        Vec3 normal;
        float penetration;
        Vec3 point;
    };

    using ContactCallback = std::function<void(const Contact&)>;

    class PhysicsWorld
    {
    public:
        PhysicsWorld();
        ~PhysicsWorld();

        uint32_t CreateBody(const RigidBodyDesc& desc);
        void DestroyBody(uint32_t bodyId);

        void SetGravity(const Vec3& gravity);
        void AddForce(uint32_t bodyId, const Vec3& force);

        void Step(float dt);
        void SetContactCallback(ContactCallback callback);

        const Vec3& GetBodyPosition(uint32_t bodyId) const;
        const Vec3& GetBodyVelocity(uint32_t bodyId) const;

    private:
        struct Body
        {
            uint32_t id;
            Vec3 position;
            Vec3 velocity;
            Vec3 forceAccum;
            float mass;
            float invMass;
            bool isStatic;
            Shape shape;
        };

        std::vector<Body> m_bodies;
        Vec3 m_gravity;
        ContactCallback m_contactCallback;

        Body* FindBody(uint32_t id);
        const Body* FindBody(uint32_t id) const;

        void Integrate(Body& body, float dt);
        void SolveCollisions();
        bool TestCollision(const Body& a, const Body& b, Contact& outContact) const;
        void ResolveContact(Body& a, Body& b, const Contact& contact);
    };

    // Engine/plugin entry points
    class PhysicsPlugin
    {
    public:
        bool Initialize();
        void Shutdown();
        PhysicsWorld* GetWorld();

    private:
        PhysicsWorld m_world;
        bool m_initialized = false;
    };
}
