### 3.2 Implementation

```cpp
// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"
#include <algorithm>
#include <cmath>

namespace CustomPhysics
{
    static uint32_t g_nextBodyId = 1;

    PhysicsWorld::PhysicsWorld()
        : m_gravity(0.0f, -9.81f, 0.0f)
    {
    }

    PhysicsWorld::~PhysicsWorld() = default;

    uint32_t PhysicsWorld::CreateBody(const RigidBodyDesc& desc)
    {
        Body body{};
        body.id = g_nextBodyId++;
        body.position = desc.position;
        body.velocity = desc.velocity;
        body.forceAccum = Vec3(0, 0, 0);
        body.mass = desc.isStatic ? 0.0f : std::max(desc.mass, 0.0001f);
        body.invMass = desc.isStatic ? 0.0f : 1.0f / body.mass;
        body.isStatic = desc.isStatic;
        body.shape = desc.shape;

        m_bodies.push_back(body);
        return body.id;
    }

    void PhysicsWorld::DestroyBody(uint32_t bodyId)
    {
        m_bodies.erase(
            std::remove_if(m_bodies.begin(), m_bodies.end(),
                [bodyId](const Body& b) { return b.id == bodyId; }),
            m_bodies.end());
    }

    void PhysicsWorld::SetGravity(const Vec3& gravity)
    {
        m_gravity = gravity;
    }

    void PhysicsWorld::AddForce(uint32_t bodyId, const Vec3& force)
    {
        Body* body = FindBody(bodyId);
        if (!body || body->isStatic) return;
        body->forceAccum += force;
    }

    void PhysicsWorld::SetContactCallback(ContactCallback callback)
    {
        m_contactCallback = std::move(callback);
    }

    const Vec3& PhysicsWorld::GetBodyPosition(uint32_t bodyId) const
    {
        const Body* body = FindBody(bodyId);
        static Vec3 zero{};
        return body ? body->position : zero;
    }

    const Vec3& PhysicsWorld::GetBodyVelocity(uint32_t bodyId) const
    {
        const Body* body = FindBody(bodyId);
        static Vec3 zero{};
        return body ? body->velocity : zero;
    }

    PhysicsWorld::Body* PhysicsWorld::FindBody(uint32_t id)
    {
        for (auto& b : m_bodies)
            if (b.id == id) return &b;
        return nullptr;
    }

    const PhysicsWorld::Body* PhysicsWorld::FindBody(uint32_t id) const
    {
        for (const auto& b : m_bodies)
            if (b.id == id) return &b;
        return nullptr;
    }

    void PhysicsWorld::Integrate(Body& body, float dt)
    {
        if (body.isStatic) return;

        Vec3 acceleration = m_gravity + body.forceAccum * body.invMass;
        body.velocity += acceleration * dt;
        body.position += body.velocity * dt;
        body.forceAccum = Vec3(0, 0, 0);
    }

    bool PhysicsWorld::TestCollision(const Body& a, const Body& b, Contact& outContact) const
    {
        // Initial implementation: sphere-sphere only
        if (a.shape.type != ShapeType::Sphere || b.shape.type != ShapeType::Sphere)
            return false;

        Vec3 delta = b.position - a.position;
        float distSq = LengthSq(delta);
        float radiusSum = a.shape.radius + b.shape.radius;

        if (distSq >= radiusSum * radiusSum)
            return false;

        float dist = std::sqrt(std::max(distSq, 0.000001f));
        Vec3 normal = delta * (1.0f / dist);
        float penetration = radiusSum - dist;

        outContact.bodyA = a.id;
        outContact.bodyB = b.id;
        outContact.normal = normal;
        outContact.penetration = penetration;
        outContact.point = a.position + normal * (a.shape.radius - penetration * 0.5f);
        return true;
    }

    void PhysicsWorld::ResolveContact(Body& a, Body& b, const Contact& contact)
    {
        if (a.isStatic && b.isStatic) return;

        Vec3 relativeVelocity = b.velocity - a.velocity;
        float velAlongNormal = Dot(relativeVelocity, contact.normal);

        if (velAlongNormal > 0.0f)
            return;

        float restitution = 0.2f;
        float invMassSum = a.invMass + b.invMass;
        if (invMassSum <= 0.0f) return;

        float j = -(1.0f + restitution) * velAlongNormal;
        j /= invMassSum;

        Vec3 impulse = contact.normal * j;

        if (!a.isStatic) a.velocity -= impulse * a.invMass;
        if (!b.isStatic) b.velocity += impulse * b.invMass;

        // Positional correction
        const float percent = 0.8f;
        const float slop = 0.01f;
        float correctionMag = std::max(contact.penetration - slop, 0.0f) / invMassSum * percent;
        Vec3 correction = contact.normal * correctionMag;

        if (!a.isStatic) a.position -= correction * a.invMass;
        if (!b.isStatic) b.position += correction * b.invMass;
    }

    void PhysicsWorld::SolveCollisions()
    {
        for (size_t i = 0; i < m_bodies.size(); ++i)
        {
            for (size_t j = i + 1; j < m_bodies.size(); ++j)
            {
                Contact contact{};
                if (TestCollision(m_bodies[i], m_bodies[j], contact))
                {
                    if (m_contactCallback)
                        m_contactCallback(contact);

                    ResolveContact(m_bodies[i], m_bodies[j], contact);
                }
            }
        }
    }

    void PhysicsWorld::Step(float dt)
    {
        // Basic fixed-step style integration assumed by caller
        for (auto& body : m_bodies)
            Integrate(body, dt);

        SolveCollisions();
    }

    bool PhysicsPlugin::Initialize()
    {
        m_initialized = true;
        return true;
    }

    void PhysicsPlugin::Shutdown()
    {
        m_initialized = false;
    }

    PhysicsWorld* PhysicsPlugin::GetWorld()
    {
        return m_initialized ? &m_world : nullptr;
    }
}
```

