class PhysicsPlugin {
public:
    bool Initialize(EngineContext* engine);
    void Shutdown();
    void Tick(float deltaTime);

private:
    PhysicsWorld world;
    bool initialized = false;
};

bool PhysicsPlugin::Initialize(EngineContext* engine) {
    world.SetGravity({0.0f, -9.81f, 0.0f});
    initialized = true;
    return true;
}

void PhysicsPlugin::Tick(float deltaTime) {
    if (!initialized) return;

    const float fixedStep = 1.0f / 60.0f;
    accumulator += deltaTime;

    while (accumulator >= fixedStep) {
        world.Step(fixedStep);
        accumulator -= fixedStep;
    }

    world.SyncTransformsToEngine();
}
```

