// PhysicsPlugin.h
#pragma once
#include <vector>

struct Vec3 {
    float x, y, z;
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass;
    bool isStatic;
};

class PhysicsPlugin {
public:
    void Initialize();
    void Shutdown();
    void AddBody(const RigidBody& body);
    void Step(float deltaTime);

    const std::vector<RigidBody>& GetBodies() const { return bodies; }

private:
    std::vector<RigidBody> bodies;
    Vec3 gravity = {0.0f, -9.81f, 0.0f};

