```cpp
// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"

void PhysicsPlugin::Initialize() {
    bodies.clear();
}

void PhysicsPlugin::Shutdown() {
    bodies.clear();
}

void PhysicsPlugin::AddBody(const RigidBody& body) {
    bodies.push_back(body);
}

Vec3 PhysicsPlugin::Add(Vec3 a, Vec3 b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

Vec3 PhysicsPlugin::Mul(Vec3 a, float s) {
    return {a.x * s, a.y * s, a.z * s};
}

void PhysicsPlugin::Step(float deltaTime) {
    for (auto& body : bodies) {
        if (body.isStatic) continue;

        // Acceleration = gravity + force / mass
        Vec3 acceleration = gravity;
        if (body.mass > 0.0f) {
            acceleration = Add(acceleration, Mul(body.force, 1.0f / body.mass));
        }

        // Semi-implicit Euler integration
        body.velocity = Add(body.velocity, Mul(acceleration, deltaTime));
        body.position = Add(body.position, Mul(body.velocity, deltaTime));

        // Simple ground collision at y = 0
        if (body.position.y < 0.0f) {
            body.position.y = 0.0f;
            if (body.velocity.y < 0.0f) {
                body.velocity.y *= -0.5f; // restitution
            }
        }

        // Clear forces after step
        body.force = {0.0f, 0.0f, 0.0f};
    }
}
