### `CustomPhysicsPlugin.cpp`
```cpp
#include "CustomPhysicsPlugin.h"

static CustomPhysicsPlugin GPhysics;

void CustomPhysicsPlugin::Initialize()
{
    bodies.clear();
}

void CustomPhysicsPlugin::Shutdown()
{
    bodies.clear();
}

void CustomPhysicsPlugin::Step(float deltaTime)
{
    const Vec3 gravity = { 0.0f, -9.81f, 0.0f };

    for (auto& body : bodies)
    {
        if (body.isStatic || body.mass <= 0.0f)
            continue;

        // Gravity
        body.force.x += gravity.x * body.mass;
        body.force.y += gravity.y * body.mass;
        body.force.z += gravity.z * body.mass;

        // Integrate acceleration -> velocity
        float invMass = 1.0f / body.mass;
        body.velocity.x += body.force.x * invMass * deltaTime;
        body.velocity.y += body.force.y * invMass * deltaTime;
        body.velocity.z += body.force.z * invMass * deltaTime;

        // Integrate velocity -> position
        body.position.x += body.velocity.x * deltaTime;
        body.position.y += body.velocity.y * deltaTime;
        body.position.z += body.velocity.z * deltaTime;

        // Clear forces
        body.force = { 0.0f, 0.0f, 0.0f };
    }
}

int CustomPhysicsPlugin::CreateBody(const PhysicsBody& body)
{
    bodies.push_back(body);
    return static_cast<int>(bodies.size() - 1);
}

void CustomPhysicsPlugin::ApplyForce(int bodyId, const Vec3& force)
{
    if (bodyId < 0 || bodyId >= static_cast<int>(bodies.size()))
        return;

    bodies[bodyId].force.x += force.x;
    bodies[bodyId].force.y += force.y;
    bodies[bodyId].force.z += force.z;
}

// C API wrappers
extern "C"
{
    CUSTOMPHYSICS_API void InitializePhysicsPlugin()
    {
        GPhysics.Initialize();
    }

    CUSTOMPHYSICS_API void ShutdownPhysicsPlugin()
    {
        GPhysics.Shutdown();
    }

    CUSTOMPHYSICS_API void StepPhysics(float deltaTime)
    {
        GPhysics.Step(deltaTime);
    }
}
