```cpp
// PhysicsPlugin.h
#pragma once
#include <vector>

struct Vec3 {
    float x, y, z;
};

struct RigidBody {
    Vec3 position{};
    Vec3 velocity{};
    Vec3 force{};
    float mass = 1.0f;
    bool isStatic = false;
};

class IPhysicsPlugin {
public:
    virtual ~IPhysicsPlugin() = default;
    virtual void Initialize() = 0;
    virtual void Shutdown() = 0;
    virtual void AddBody(RigidBody* body) = 0;
    virtual void RemoveBody(RigidBody* body) = 0;
