```cpp
// PhysicsPlugin.cpp
#include "PhysicsPlugin.h"
#include <algorithm>

static Vec3 operator+(const Vec3& a, const Vec3& b) {
    return {a.x + b.x, a.y + b.y, a.z + b.z};
}

static Vec3 operator*(const Vec3& v, float s) {
    return {v.x * s, v.y * s, v.z * s};
}

class MinimalPhysicsPlugin : public IPhysicsPlugin {
public:
    void Initialize() override {}
    void Shutdown() override { bodies.clear(); }

    void AddBody(RigidBody* body) override {
        if (body) bodies.push_back(body);
    }

    void RemoveBody(RigidBody* body) override {
        bodies.erase(std::remove(bodies.begin(), bodies.end(), body), bodies.end());
    }

    void Step(float dt) override {
        const Vec3 gravity{0.0f, -9.81f, 0.0f};

        for (auto* body : bodies) {
            if (!body || body->isStatic) continue;

            // Basic Euler integration
            Vec3 accel{
                body->force.x / body->mass + gravity.x,
                body->force.y / body->mass + gravity.y,
                body->force.z / body->mass + gravity.z
            };

            body->velocity = body->velocity + accel * dt;
            body->position = body->position + body->velocity * dt;

            // Clear forces
            body->force = {0, 0, 0};
        }
    }

private:
    std::vector<RigidBody*> bodies;
};

// Factory function for host engine
extern "C" IPhysicsPlugin* CreatePhysicsPlugin() {
    return new MinimalPhysicsPlugin();
}

extern "C" void DestroyPhysicsPlugin(IPhysicsPlugin* plugin) {
    delete plugin;
}
