## Example C++-style implementation

```cpp
// PhysicsPlugin.h
#pragma once
#include <vector>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float X, float Y, float Z) : x(X), y(Y), z(Z) {}

    Vec3 operator+(const Vec3& rhs) const { return Vec3(x + rhs.x, y + rhs.y, z + rhs.z); }
    Vec3 operator-(const Vec3& rhs) const { return Vec3(x - rhs.x, y - rhs.y, z - rhs.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }

    Vec3& operator+=(const Vec3& rhs) {
        x += rhs.x; y += rhs.y; z += rhs.z;
        return *this;
    }
};

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 force;
    float mass;
    bool isStatic;

    RigidBody()
        : position(), velocity(), force(), mass(1.0f), isStatic(false) {}
};

class PhysicsWorld {
public:
    void AddBody(const RigidBody& body) {
        bodies.push_back(body);
    }

    void Step(float dt) {
        const Vec3 gravity(0.0f, -9.81f, 0.0f);

        for (auto& body : bodies) {
            if (body.isStatic) continue;

            // Apply gravity
            body.force += gravity * body.mass;

            // Integrate
            Vec3 acceleration = body.force * (1.0f / body.mass);
            body.velocity += acceleration * dt;
            body.position += body.velocity * dt;

            // Simple ground collision
            if (body.position.y < 0.0f) {
                body.position.y = 0.0f;
                if (body.velocity.y < 0.0f) {
                    body.velocity.y *= -0.5f; // restitution
                }
            }

            // Clear forces
            body.force = Vec3(0, 0, 0);
        }
    }

    std::vector<RigidBody>& GetBodies() { return bodies; }

private:
    std::vector<RigidBody> bodies;
};
```

