#include "CustomPhysicsSubsystem.h"
#include "Engine/World.h"
#include "PhysicsEngine/BodyInstance.h"
#include "Components/PrimitiveComponent.h"

TStatId UCustomPhysicsSubsystem::GetStatId() const
{
    RETURN_QUICK_DECLARE_CYCLE_STAT(UCustomPhysicsSubsystem, STATGROUP_Tickables);
}

void UCustomPhysicsSubsystem::Tick(float DeltaTime)
{
    UWorld* World = GetWorld();
    if (!World) return;

    const FVector CustomGravity(0.0f, 0.0f, -980.0f); // cm/s^2

    for (TActorIterator<AActor> It(World); It; ++It)
    {
        AActor* Actor = *It;
        if (!Actor) continue;

        TArray<UPrimitiveComponent*> Components;
        Actor->GetComponents<UPrimitiveComponent>(Components);

        for (UPrimitiveComponent* Comp : Components)
        {
            if (!Comp || !Comp->IsSimulatingPhysics()) continue;

            FBodyInstance* Body = Comp->GetBodyInstance();
            if (!Body) continue;

            const float Mass = Body->GetBodyMass();
            Body->AddForce(CustomGravity * Mass, false, true);
        }
    }
}
