## C++ Example

```cpp
#include <iostream>
#include <vector>
#include <chrono>
#include <thread>
#include <cmath>
#include <algorithm>

struct Vec3 {
    float x, y, z;

    Vec3() : x(0), y(0), z(0) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}

    Vec3 operator+(const Vec3& other) const { return Vec3(x + other.x, y + other.y, z + other.z); }
    Vec3 operator-(const Vec3& other) const { return Vec3(x - other.x, y - other.y, z - other.z); }
    Vec3 operator*(float s) const { return Vec3(x * s, y * s, z * s); }
    Vec3 operator/(float s) const { return Vec3(x / s, y / s, z / s); }

    Vec3& operator+=(const Vec3& other) { x += other.x; y += other.y; z += other.z; return *this; }
    Vec3& operator-=(const Vec3& other) { x -= other.x; y -= other.y; z -= other.z; return *this; }
    Vec3& operator*=(float s) { x *= s; y *= s; z *= s; return *this; }
};

static inline float dot(const Vec3& a, const Vec3& b) {
    return a.x * b.x + a.y * b.y + a.z * b.z;
}

static inline float length(const Vec3& v) {
    return std::sqrt(dot(v, v));
}

static inline Vec3 normalize(const Vec3& v) {
    float len = length(v);
    if (len <= 1e-6f) return Vec3(0, 0, 0);
    return v / len;
}

struct RigidBody {
    Vec3 position;
    Vec3 velocity;
    Vec3 forceAccum;
    float mass;
    float invMass;
    float restitution;
    float radius; // simple sphere collider

    RigidBody(const Vec3& pos, float m, float r, float rest = 0.5f)
        : position(pos), velocity(0,0,0), forceAccum(0,0,0),
          mass(m), restitution(rest), radius(r)
    {
        invMass = (mass > 0.0f) ? 1.0f / mass : 0.0f;
    }

    void applyForce(const Vec3& f) {
        forceAccum += f;
    }

    void integrate(float dt) {
        if (invMass == 0.0f) return; // static body

        // Semi-implicit Euler
        Vec3 acceleration = forceAccum * invMass;
        velocity += acceleration * dt;
        position += velocity * dt;

        forceAccum = Vec3(0,0,0);
    }
};

struct PhysicsWorld {
    std::vector<RigidBody> bodies;
    Vec3 gravity = Vec3(0.0f, -9.81f, 0.0f);

    void step(float dt) {
        // Apply forces
        for (auto& body : bodies) {
            if (body.invMass > 0.0f) {
                body.applyForce(gravity * body.mass);
            }
        }

        // Integrate
        for (auto& body : bodies) {
            body.integrate(dt);
        }

        // Collision with ground plane y = 0
        for (auto& body : bodies) {
            resolveGroundCollision(body);
        }
    }

    void resolveGroundCollision(RigidBody& body) {
        float minY = body.radius;
        if (body.position.y < minY) {
            body.position.y = minY;

            // Reflect velocity along normal if moving downward
            if (body.velocity.y < 0.0f) {
                body.velocity.y = -body.velocity.y * body.restitution;

                // simple friction
                body.velocity.x *= 0.98f;
                body.velocity.z *= 0.98f;

                // sleep threshold
                if (std::fabs(body.velocity.y) < 0.05f) {
                    body.velocity.y = 0.0f;
                }
            }
        }
    }
};

int main() {
    PhysicsWorld world;
    world.bodies.emplace_back(Vec3(0.0f, 10.0f, 0.0f), 1.0f, 0.5f, 0.6f);
    world.bodies.emplace_back(Vec3(2.0f, 15.0f, 0.0f), 2.0f, 0.75f, 0.4f);

    using clock = std::chrono::high_resolution_clock;
    auto previous = clock::now();

    const float fixedDt = 1.0f / 120.0f;   // physics at 120 Hz
    const float maxFrameTime = 0.25f;       // avoid spiral of death
    float accumulator = 0.0f;

    while (true) {
        auto current = clock::now();
        std::chrono::duration<float> frameTime = current - previous;
        previous = current;

        float dt = std::min(frameTime.count(), maxFrameTime);
        accumulator += dt;

        // Fixed timestep physics
        while (accumulator >= fixedDt) {
            world.step(fixedDt);
            accumulator -= fixedDt;
        }

        // Render/interpolate here if needed
        // For this console demo, just print positions occasionally
        static float printTimer = 0.0f;
        printTimer += dt;
        if (printTimer >= 0.5f) {
            printTimer = 0.0f;
            std::cout << "Body 0: (" 
                      << world.bodies[0].position.x << ", "
                      << world.bodies[0].position.y << ", "
                      << world.bodies[0].position.z << ")\n";
            std::cout << "Body 1: (" 
                      << world.bodies[1].position.x << ", "
                      << world.bodies[1].position.y << ", "
                      << world.bodies[1].position.z << ")\n";
            std::cout << "----\n";
        }

        // Optional frame-rate cap to reduce CPU usage
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }

    return 0;
}
```

