## `src/infrastructure/corporate-api.client.ts`

```ts
import axios, { AxiosInstance } from "axios";
import { Injectable } from "@nestjs/common";
import { Env } from "../config/env";
import { UpstreamServiceError } from "../common/errors";
import { Customer, CustomerSchema, CreateCustomerInput } from "../domain/customer";

@Injectable()
export class CorporateApiClient {
  private readonly client: AxiosInstance;

  constructor(private readonly env: Env) {
    this.client = axios.create({
      baseURL: this.env.CORPORATE_API_BASE_URL,
      timeout: 5000,
      headers: {
        Authorization: `Bearer ${this.env.CORPORATE_API_TOKEN}`,
        "Content-Type": "application/json"
      }
    });
  }

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    try {
      const response = await this.client.post("/customers", input);
      return CustomerSchema.parse(response.data);
    } catch (err: any) {
      throw new UpstreamServiceError(
        `Failed to create customer in corporate system: ${err?.message ?? "unknown error"}`,
        "corporate-api"
      );
    }
  }

  async getCustomerByExternalId(externalId: string): Promise<Customer | null> {
    try {
      const response = await this.client.get(`/customers/by-external-id/${encodeURIComponent(externalId)}`);
      return CustomerSchema.parse(response.data);
    } catch (err: any) {
      if (err?.response?.status === 404) return null;
      throw new UpstreamServiceError(
        `Failed to fetch customer from corporate system: ${err?.message ?? "unknown error"}`,
        "corporate-api"
      );
    }
  }
}
```

