```ts
import { Injectable } from "@nestjs/common";
import { CorporateApiClient } from "../infrastructure/corporate-api.client";
import { CreateCustomerInput } from "../domain/customer";
import { DomainError } from "../common/errors";

@Injectable()
export class CustomerService {
  constructor(private readonly corporateApi: CorporateApiClient) {}

  async createCustomer(input: CreateCustomerInput) {
    const existing = await this.corporateApi.getCustomerByExternalId(input.externalId);
    if (existing) {
      throw new DomainError("Customer already exists", "CUSTOMER_EXISTS", 409);
    }
    return this.corporateApi.createCustomer(input);
  }

  async getCustomerByExternalId(externalId: string) {
    const customer = await this.corporateApi.getCustomerByExternalId(externalId);
    if (!customer) {
      throw new DomainError("Customer not found", "CUSTOMER_NOT_FOUND", 404);
    }
    return customer;
  }
}
