import { CanActivate, ExecutionContext, Injectable, UnauthorizedException } from "@nestjs/common";

@Injectable()
export class CorporateAuthGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const req = context.switchToHttp().getRequest<Request & { headers: Record<string, string | undefined> }>();
    const token = req.headers["x-corporate-token"];
    if (!token || token !== process.env.CORPORATE_INTERNAL_TOKEN) {
      throw new UnauthorizedException("Invalid corporate token");
    }
    return true;
  }
}
