## `src/integrations/corporate-api.client.ts`

```ts
import { Injectable } from '@nestjs/common';
import axios, { type AxiosInstance } from 'axios';
import { IntegrationError } from '../common/errors';
import type { CorporateEmployeeRecord } from '../employees/types/employee.types';

@Injectable()
export class CorporateApiClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.CORPORATE_API_BASE_URL,
      timeout: Number(process.env.REQUEST_TIMEOUT_MS ?? 5000),
      headers: {
        Authorization: `Bearer ${process.env.CORPORATE_API_TOKEN}`,
        'Content-Type': 'application/json'
      }
    });
  }

  async upsertEmployee(record: CorporateEmployeeRecord): Promise<void> {
    try {
      await this.client.put(`/employees/${encodeURIComponent(record.employee_id)}`, record);
    } catch (error: unknown) {
      throw new IntegrationError('Failed to upsert employee in corporate system', error);
    }
  }

  async getEmployee(employeeId: string): Promise<CorporateEmployeeRecord | null> {
    try {
      const response = await this.client.get<CorporateEmployeeRecord>(
        `/employees/${encodeURIComponent(employeeId)}`
      );
      return response.data;
    } catch (error: unknown) {
      if (axios.isAxiosError(error) && error.response?.status === 404) {
        return null;
      }
      throw new IntegrationError('Failed to fetch employee from corporate system', error);
    }
  }
}
