## `src/employees/employees.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { CorporateApiClient } from '../integrations/corporate-api.client';
import { DomainError } from '../common/errors';
import type { Employee } from './types/employee.types';
import type { SyncEmployeeDto } from './dto/sync-employee.dto';

@Injectable()
export class EmployeesService {
  constructor(private readonly corporateApiClient: CorporateApiClient) {}

  async syncEmployee(dto: SyncEmployeeDto): Promise<Employee> {
    if (!dto.employeeId.trim()) {
      throw new DomainError('employeeId cannot be empty');
    }

    const employee: Employee = {
      id: dto.employeeId,
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      departmentCode: dto.departmentCode,
      active: dto.active
    };

    await this.corporateApiClient.upsertEmployee({
      employee_id: employee.id,
      given_name: employee.firstName,
      family_name: employee.lastName,
      email_address: employee.email,
      dept_code: employee.departmentCode,
      is_active: employee.active
    });

    return employee;
  }

  async fetchEmployee(employeeId: string): Promise<Employee | null> {
    const record = await this.corporateApiClient.getEmployee(employeeId);
    if (!record) return null;

    return {
      id: record.employee_id,
      firstName: record.given_name,
      lastName: record.family_name,
      email: record.email_address,
      departmentCode: record.dept_code,
      active: record.is_active
    };
  }
}
```

