## `src/domain/user/user.service.ts`

```ts
import type { UserRepository } from "./user.repository.js";
import type { CreateUserInput, User } from "./user.types.js";
import { ConflictError, NotFoundError } from "../../shared/errors.js";
import { CorporateApiClient } from "../../infrastructure/integrations/corporate-api.client.js";
import { EventBusClient } from "../../infrastructure/integrations/event-bus.client.js";

export class UserService {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly corporateApiClient: CorporateApiClient,
    private readonly eventBusClient: EventBusClient
  ) {}

  async getUser(id: string): Promise<User> {
    const user = await this.userRepository.findById(id);
    if (!user) throw new NotFoundError("User not found");
    return user;
  }

  async createUser(input: CreateUserInput): Promise<User> {
    const existing = await this.userRepository.findByEmployeeId(input.employeeId);
    if (existing) {
      throw new ConflictError("User already exists", { employeeId: input.employeeId });
    }

    const user = await this.userRepository.create(input);

    await this.corporateApiClient.syncUser(user.employeeId, user.email, user.displayName);
    await this.eventBusClient.publish("user.created", {
      id: user.id,
      employeeId: user.employeeId,
      email: user.email,
      displayName: user.displayName
    });

    return user;
  }
}
```

