import type { FastifyInstance } from "fastify";
import { createUserSchema } from "../domain/user/user.types.js";
import { UserService } from "../domain/user/user.service.js";
import { requireAuth } from "../infrastructure/auth/oidc.middleware.js";

export async function userRoutes(app: FastifyInstance): Promise<void> {
  const userService = app.diContainer.userService as UserService;

  app.get("/users/:id", { preHandler: requireAuth }, async (request, reply) => {
    const { id } = request.params as { id: string };
    const user = await userService.getUser(id);
    return reply.send(user);
  });

  app.post("/users", { preHandler: requireAuth }, async (request, reply) => {
    const input = createUserSchema.parse(request.body);
    const user = await userService.createUser(input);
    return reply.code(201).send(user);
  });
}
