## `src/app.ts`

```ts
import Fastify from "fastify";
import cors from "@fastify/cors";
import helmet from "@fastify/helmet";
import { logger } from "./shared/logger.js";
import { AppError } from "./shared/errors.js";
import { userRoutes } from "./routes/user.routes.js";
import { PrismaUserRepository } from "./infrastructure/db/user.prisma.repository.js";
import { CorporateApiClient } from "./infrastructure/integrations/corporate-api.client.js";
import { EventBusClient } from "./infrastructure/integrations/event-bus.client.js";
import { UserService } from "./domain/user/user.service.js";

declare module "fastify" {
  interface FastifyInstance {
    diContainer: {
      userService: UserService;
    };
  }
}

export async function buildApp() {
  const app = Fastify({ logger });

  await app.register(cors);
  await app.register(helmet);

  const userRepository = new PrismaUserRepository();
  const corporateApiClient = new CorporateApiClient();
  const eventBusClient = new EventBusClient();

  app.decorate("diContainer", {
    userService: new UserService(userRepository, corporateApiClient, eventBusClient)
  });

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      return reply.status(error.statusCode).send({
        error: error.code,
        message: error.message,
        details: error.details
      });
    }

    logger.error({ error }, "Unhandled error");
    return reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });

  app.get("/health", async () => ({ status: "ok" }));

  await app.register(userRoutes, { prefix: "/api/v1" });

  return app;
}
```

