## 10) HTTP adapter: `src/customers/adapters/corporate-crm.http-adapter.ts`

```ts
import { HttpService } from '@nestjs/axios';
import { Injectable } from '@nestjs/common';
import { firstValueFrom } from 'rxjs';
import { IntegrationError } from '../../common/errors';
import type {
  CorporateCrmCustomerUpsert,
  CorporateCrmPort,
  CorporateCrmUpsertResult
} from '../ports/corporate-crm.port';

type CrmApiResponse = {
  id: string;
  updatedAt: string;
};

@Injectable()
export class CorporateCrmHttpAdapter implements CorporateCrmPort {
  constructor(private readonly http: HttpService) {}

  async upsertCustomer(input: CorporateCrmCustomerUpsert): Promise<CorporateCrmUpsertResult> {
    try {
      const response = await firstValueFrom(
        this.http.post<CrmApiResponse>('/customers/upsert', input, {
          headers: {
            'Content-Type': 'application/json'
          }
        })
      );

      return {
        success: true,
        crmCustomerId: response.data.id,
        updatedAt: response.data.updatedAt
      };
    } catch (cause: unknown) {
      throw new IntegrationError('Failed to upsert customer in corporate CRM', 'CorporateCRM', cause);
    }
  }
}
```

