```ts
import { Injectable } from '@nestjs/common';
import type { SyncCustomerDto } from './dto/sync-customer.dto';
import type { CorporateCrmPort } from './ports/corporate-crm.port';

export interface SyncCustomerResult {
  synced: boolean;
  crmCustomerId: string;
  updatedAt: string;
}

@Injectable()
export class CustomersService {
  constructor(private readonly crm: CorporateCrmPort) {}

  async syncCustomer(dto: SyncCustomerDto): Promise<SyncCustomerResult> {
    const fullName = `${dto.firstName} ${dto.lastName}`.trim();

    const result = await this.crm.upsertCustomer({
      externalId: dto.customerId,
      fullName,
      email: dto.email,
      regionCode: dto.regionCode
    });

    return {
      synced: result.success,
      crmCustomerId: result.crmCustomerId,
      updatedAt: result.updatedAt
    };
  }
}
```

