## `src/integrations/corporate-api.client.ts`

```ts
import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { CorporateCustomerSyncRequest, CorporateCustomerSyncResponse } from './corporate-api.types';

@Injectable()
export class CorporateApiClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      timeout: 5000
    });
  }

  configure(baseURL: string, token: string): void {
    this.client.defaults.baseURL = baseURL;
    this.client.defaults.headers.common.Authorization = `Bearer ${token}`;
  }

  async syncCustomer(
    payload: CorporateCustomerSyncRequest
  ): Promise<CorporateCustomerSyncResponse> {
    try {
      const response = await this.client.post<CorporateCustomerSyncResponse>(
        '/customers/sync',
        payload
      );
      return response.data;
    } catch (error) {
      throw new HttpException(
        'Failed to sync customer with corporate system',
        HttpStatus.BAD_GATEWAY
      );
    }
  }
}
```

