## `src/customers/customers.service.ts`

```ts
import { ConflictException, Injectable, OnModuleInit } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import { CustomersRepository } from './customers.repository';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CustomerResponseDto } from './dto/customer-response.dto';
import { CorporateApiClient } from '../integrations/corporate-api.client';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class CustomersService implements OnModuleInit {
  constructor(
    private readonly repo: CustomersRepository,
    private readonly corporateApi: CorporateApiClient,
    private readonly config: ConfigService
  ) {}

  onModuleInit(): void {
    const baseUrl = this.config.getOrThrow<string>('CORPORATE_API_BASE_URL');
    const token = this.config.getOrThrow<string>('CORPORATE_API_TOKEN');
    this.corporateApi.configure(baseUrl, token);
  }

  async create(dto: CreateCustomerDto): Promise<CustomerResponseDto> {
    const existing = await this.repo.findByEmail(dto.email);
    if (existing) {
      throw new ConflictException('Customer with this email already exists');
    }

    const record = {
      id: randomUUID(),
      name: dto.name,
      email: dto.email,
      createdAt: new Date()
    };

    await this.repo.save(record);

    await this.corporateApi.syncCustomer({
      externalId: record.id,
      name: record.name,
      email: record.email
    });

    return {
      id: record.id,
      name: record.name,
      email: record.email,
      createdAt: record.createdAt.toISOString()
    };
  }
}
```

