## 6) Environment validation: `src/common/config/env.schema.ts`

```ts
import { plainToInstance } from 'class-transformer';
import { IsEnum, IsInt, IsOptional, IsString, Min, validateSync } from 'class-validator';

class EnvVars {
  @IsString()
  NODE_ENV!: string;

  @IsInt()
  @Min(1)
  PORT!: number;

  @IsString()
  CORPORATE_AUTH_URL!: string;

  @IsString()
  CORPORATE_DIRECTORY_URL!: string;

  @IsOptional()
  @IsEnum(['debug', 'info', 'warn', 'error'])
  LOG_LEVEL?: 'debug' | 'info' | 'warn' | 'error';
}

export function validateEnv(config: Record<string, unknown>): Record<string, unknown> {
  const validated = plainToInstance(EnvVars, {
    ...config,
    PORT: config.PORT ? Number(config.PORT) : 3000
  });

  const errors = validateSync(validated, { skipMissingProperties: false });

  if (errors.length > 0) {
    throw new Error(`Environment validation failed: ${errors.toString()}`);
  }

  return config;
}
```

