import { Injectable } from '@nestjs/common';

export interface EmployeeRecord {
  readonly id: string;
  readonly firstName: string;
  readonly lastName: string;
  readonly email: string;
  readonly departmentCode: string;
  readonly createdAt: Date;
}

@Injectable()
export class EmployeeRepository {
  private readonly store = new Map<string, EmployeeRecord>();

  async save(employee: EmployeeRecord): Promise<EmployeeRecord> {
    this.store.set(employee.id, employee);
    return employee;
  }

  async findByEmail(email: string): Promise<EmployeeRecord | null> {
    for (const record of this.store.values()) {
      if (record.email.toLowerCase() === email.toLowerCase()) {
        return record;
      }
    }
    return null;
  }

  async findById(id: string): Promise<EmployeeRecord | null> {
    return this.store.get(id) ?? null;
  }
}
