## 11) Service layer: `src/modules/employee/employee.service.ts`

```ts
import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { CreateEmployeeDto } from './dto/create-employee.dto';
import { EmployeeResponseDto } from './dto/employee-response.dto';
import { EmployeeRepository } from './employee.repository';
import { CorporateDirectoryClient } from '../../integrations/corporate-directory/corporate-directory.client';

@Injectable()
export class EmployeeService {
  constructor(
    private readonly employeeRepository: EmployeeRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  async createEmployee(dto: CreateEmployeeDto): Promise<EmployeeResponseDto> {
    const existing = await this.employeeRepository.findByEmail(dto.email);
    if (existing) {
      throw new ConflictException('Employee with this email already exists');
    }

    const departmentExists = await this.corporateDirectoryClient.departmentExists(dto.departmentCode);
    if (!departmentExists) {
      throw new NotFoundException(`Department ${dto.departmentCode} not found in corporate directory`);
    }

    const record = await this.employeeRepository.save({
      id: randomUUID(),
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      departmentCode: dto.departmentCode,
      createdAt: new Date()
    });

    return new EmployeeResponseDto({
      id: record.id,
      firstName: record.firstName,
      lastName: record.lastName,
      email: record.email,
      departmentCode: record.departmentCode,
      createdAt: record.createdAt.toISOString()
    });
  }

  async getEmployeeById(id: string): Promise<EmployeeResponseDto> {
    const record = await this.employeeRepository.findById(id);
    if (!record) {
      throw new NotFoundException(`Employee ${id} not found`);
    }

    return new EmployeeResponseDto({
      id: record.id,
      firstName: record.firstName,
      lastName: record.lastName,
      email: record.email,
      departmentCode: record.departmentCode,
      createdAt: record.createdAt.toISOString()
    });
  }
}
