# 8) CRM client

## `src/integrations/crm/crm.client.ts`

```ts
import { Injectable, InternalServerErrorException, Logger } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { ConfigService } from '@nestjs/config';
import { CrmCustomerCreateRequest, CrmCustomerCreateResponse } from './crm.types';

@Injectable()
export class CrmClient {
  private readonly logger = new Logger(CrmClient.name);
  private readonly http: AxiosInstance;

  constructor(private readonly configService: ConfigService) {
    const baseURL = this.configService.get<string>('crm.baseUrl');
    const apiKey = this.configService.get<string>('crm.apiKey');

    if (!baseURL || !apiKey) {
      throw new Error('CRM configuration is missing');
    }

    this.http = axios.create({
      baseURL,
      timeout: 5000,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
    });
  }

  async upsertCustomer(
    payload: CrmCustomerCreateRequest,
  ): Promise<CrmCustomerCreateResponse> {
    try {
      const response = await this.http.post<CrmCustomerCreateResponse>('/customers/upsert', payload);
      return response.data;
    } catch (error) {
      this.logger.error(`CRM upsert failed: ${(error as Error).message}`);
      throw new InternalServerErrorException('Failed to sync customer with CRM');
    }
  }
}
```

