# 9) Service layer

## `src/customers/customers.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CustomerResponseDto } from './dto/customer-response.dto';
import { CrmClient } from '../integrations/crm/crm.client';
import { mapCustomerToCrmRequest } from '../integrations/crm/crm.mapper';

@Injectable()
export class CustomersService {
  constructor(private readonly crmClient: CrmClient) {}

  async createOrSyncCustomer(dto: CreateCustomerDto): Promise<CustomerResponseDto> {
    const crmRequest = mapCustomerToCrmRequest(dto);
    const crmResult = await this.crmClient.upsertCustomer(crmRequest);

    return {
      id: crmResult.id,
      externalId: dto.externalId,
      synced: true,
      crmStatus: crmResult.status,
      syncedAt: crmResult.syncedAt,
    };
  }
}
