```ts
import { Injectable } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { ExternalSystemError } from '../../common/errors';
import type { ErpCustomerPayload, ErpSyncResponse } from './erp.types';

@Injectable()
export class ErpClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.ERP_BASE_URL,
      timeout: 5000,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${process.env.ERP_API_KEY}`
      }
    });
  }

  async syncCustomer(payload: ErpCustomerPayload): Promise<ErpSyncResponse> {
    try {
      const response = await this.client.post<ErpSyncResponse>('/customers/sync', payload);
      return response.data;
    } catch (error) {
      throw new ExternalSystemError('Failed to sync customer with ERP', 'ERP', error);
    }
  }
}
```

