## Service layer

### `src/customers/customers.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { CustomersRepository } from './customers.repository';
import { ErpClient } from '../integrations/erp/erp.client';
import { NotFoundError } from '../common/errors';
import type { CreateCustomerDto } from './dto/create-customer.dto';
import type { CustomerResponseDto } from './dto/customer-response.dto';

export interface CustomerEntity {
  id: string;
  name: string;
  email: string;
  externalReference: string;
  createdAt: string;
}

@Injectable()
export class CustomersService {
  constructor(
    private readonly repository: CustomersRepository,
    private readonly erpClient: ErpClient
  ) {}

  async create(dto: CreateCustomerDto): Promise<CustomerResponseDto> {
    const entity = await this.repository.create({
      name: dto.name,
      email: dto.email,
      externalReference: dto.externalReference
    });

    await this.erpClient.syncCustomer({
      customerId: entity.id,
      name: entity.name,
      email: entity.email,
      externalReference: entity.externalReference
    });

    return {
      id: entity.id,
      name: entity.name,
      email: entity.email,
      externalReference: entity.externalReference,
      createdAt: entity.createdAt
    };
  }

  async getById(id: string): Promise<CustomerResponseDto> {
    const entity = await this.repository.findById(id);

    if (!entity) {
      throw new NotFoundError(`Customer ${id} not found`);
    }

    return {
      id: entity.id,
      name: entity.name,
      email: entity.email,
      externalReference: entity.externalReference,
      createdAt: entity.createdAt
    };
  }
}
```

