    this.client = axios.create({
      baseURL: env.CORPORATE_DIRECTORY_BASE_URL,
      timeout: 5000,
      headers: {
        "X-API-Key": env.CORPORATE_DIRECTORY_API_KEY,
        "Content-Type": "application/json"
      }
    });
  }

  async getEmployeeById(id: string): Promise<Employee> {
    try {
      const response = await this.client.get(`/employees/${id}`);
      return EmployeeSchema.parse(response.data);
    } catch (error) {
      throw new UpstreamError(
        `Failed to fetch employee from corporate directory: ${
          error instanceof Error ? error.message : "unknown error"
        }`
      );
    }
  }

  async createEmployee(payload: Omit<Employee, "id" | "active">): Promise<Employee> {
    try {
      const response = await this.client.post("/employees", payload);
      return EmployeeSchema.parse(response.data);
    } catch (error) {
      throw new UpstreamError(
        `Failed to create employee in corporate directory: ${
          error instanceof Error ? error.message : "unknown error"
        }`
      );
    }
  }
}
