import type { FastifyPluginAsync } from "fastify";
import { CreateEmployeeRequestSchema } from "../types/employee.js";
import { EmployeeService } from "../services/employeeService.js";
import { CorporateDirectoryClient } from "../services/corporateDirectoryClient.js";
import { AppError } from "../utils/errors.js";

export const employeeRoutes: FastifyPluginAsync = async (fastify) => {
  const service = new EmployeeService(new CorporateDirectoryClient());

  fastify.get("/employees/:id", async (request) => {
    const { id } = request.params as { id: string };
    return service.getEmployee(id);
  });

  fastify.post("/employees", async (request, reply) => {
    const parsed = CreateEmployeeRequestSchema.safeParse(request.body);
    if (!parsed.success) {
      throw new AppError(
        `Invalid request body: ${parsed.error.message}`,
        400,
        "VALIDATION_ERROR"
      );
    }

    const employee = await service.createEmployee(parsed.data);
    reply.code(201);
    return employee;
  });
};
