## 10) Service layer: `src/customers/customers.service.ts`

```ts
import { Inject, Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { DomainError } from '../common/errors/domain-error';
import type { Customer } from './entities/customer.entity';
import type { CustomerRepositoryPort } from './ports/customer-repository.port';
import type { IdentityProviderPort } from './ports/identity-provider.port';

export const CUSTOMER_REPOSITORY = Symbol('CUSTOMER_REPOSITORY');
export const IDENTITY_PROVIDER = Symbol('IDENTITY_PROVIDER');

@Injectable()
export class CustomersService {
  constructor(
    @Inject(CUSTOMER_REPOSITORY)
    private readonly customerRepository: CustomerRepositoryPort,

    @Inject(IDENTITY_PROVIDER)
    private readonly identityProvider: IdentityProviderPort
  ) {}

  async createCustomer(input: {
    firstName: string;
    lastName: string;
    email: string;
  }): Promise<Customer> {
    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) {
      throw new DomainError('Customer already exists', 'CUSTOMER_ALREADY_EXISTS', 409);
    }

    const identity = await this.identityProvider.createIdentity(input);

    const now = new Date();
    const customer: Customer = {
      id: randomUUID(),
      externalIdentityId: identity.identityId,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      status: 'ACTIVE',
      createdAt: now,
      updatedAt: now
    };

    return this.customerRepository.save(customer);
  }
}
```

