import { Injectable } from '@nestjs/common';
import axios, { type AxiosInstance } from 'axios';
import type { IdentityProviderPort } from '../ports/identity-provider.port';

@Injectable()
export class OktaIdentityProviderAdapter implements IdentityProviderPort {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      baseURL: process.env.OKTA_BASE_URL,
      headers: {
        Authorization: `SSWS ${process.env.OKTA_API_TOKEN}`,
        'Content-Type': 'application/json'
      },
      timeout: 5000
    });
  }

  async createIdentity(input: {
    email: string;
    firstName: string;
    lastName: string;
  }): Promise<{ identityId: string }> {
    const response = await this.client.post('/api/v1/users', {
      profile: {
        email: input.email,
        firstName: input.firstName,
        lastName: input.lastName,
        login: input.email
      }
    });

    return { identityId: response.data.id as string };
  }
}
