## 13) Repository adapter example: `src/customers/adapters/customer.repository.pg.ts`

This is a placeholder for a real DB implementation.

```ts
import { Injectable } from '@nestjs/common';
import type { Customer } from '../entities/customer.entity';
import type { CustomerRepositoryPort } from '../ports/customer-repository.port';

@Injectable()
export class InMemoryCustomerRepositoryAdapter implements CustomerRepositoryPort {
  private readonly store = new Map<string, Customer>();

  async findByEmail(email: string): Promise<Customer | null> {
    for (const customer of this.store.values()) {
      if (customer.email === email) return customer;
    }
    return null;
  }

  async save(customer: Customer): Promise<Customer> {
    this.store.set(customer.id, customer);
    return customer;
  }
}
```

