## 9) Service layer with typed orchestration

### `src/employees/employees.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { HrClient } from '../integrations/hr/hr.client';
import { ErpClient } from '../integrations/erp/erp.client';
import { EmployeesRepository } from './employees.repository';
import type { SyncEmployeeDto } from './dto/sync-employee.dto';
import type { EmployeeSyncResult } from './employees.types';
import { AppError } from '../common/errors/app-error';

@Injectable()
export class EmployeesService {
  constructor(
    private readonly hrClient: HrClient,
    private readonly erpClient: ErpClient,
    private readonly repository: EmployeesRepository
  ) {}

  async syncEmployee(dto: SyncEmployeeDto): Promise<EmployeeSyncResult> {
    const existing = await this.repository.findByEmployeeId(dto.employeeId);
    if (existing?.synced) {
      return existing;
    }

    const erpResponse = await this.erpClient.upsertEmployee({
      employeeId: dto.employeeId,
      fullName: `${dto.firstName} ${dto.lastName}`,
      email: dto.email,
      departmentCode: dto.departmentCode,
      isActive: dto.active
    });

    if (!erpResponse.success) {
      throw new AppError('ERP sync failed', 'ERP_SYNC_FAILED', 502, {
        employeeId: dto.employeeId
      });
    }

    const result: EmployeeSyncResult = {
      employeeId: dto.employeeId,
      synced: true,
      externalReferenceId: erpResponse.externalReferenceId
    };

    return this.repository.save(result);
  }

  async syncAllFromHr(): Promise<EmployeeSyncResult[]> {
    const hrData = await this.hrClient.fetchEmployees();

    const results: EmployeeSyncResult[] = [];
    for (const employee of hrData.data) {
      const result = await this.syncEmployee({
        employeeId: employee.employeeId,
        firstName: employee.firstName,
        lastName: employee.lastName,
        email: employee.email,
        departmentCode: employee.departmentCode,
        active: employee.active
      });
      results.push(result);
    }

    return results;
  }
}
```

