import { HttpService } from '@nestjs/axios';
import { Injectable, Inject } from '@nestjs/common';
import { firstValueFrom } from 'rxjs';
import { Env } from '../../config/env.schema';
import {
  CorporateCreateCustomerRequest,
  CorporateCreateCustomerResponse,
  CorporateCustomerRecord
} from './corporate-client.types';

@Injectable()
export class CorporateClientService {
  constructor(
    private readonly http: HttpService,
    @Inject('ENV') private readonly env: Env
  ) {}

  async fetchCustomer(employeeId: string): Promise<CorporateCustomerRecord | null> {
    const url = `${this.env.CORPORATE_API_BASE_URL}/customers/${encodeURIComponent(employeeId)}`;

    const res = await firstValueFrom(
      this.http.get<CorporateCustomerRecord>(url, {
        headers: {
          Authorization: `Bearer ${this.env.CORPORATE_API_TOKEN}`
        }
      })
    );

    return res.data ?? null;
  }

  async createCustomer(
    payload: CorporateCreateCustomerRequest
  ): Promise<CorporateCreateCustomerResponse> {
    const url = `${this.env.CORPORATE_API_BASE_URL}/customers`;

    const res = await firstValueFrom(
      this.http.post<CorporateCreateCustomerResponse>(url, payload, {
        headers: {
          Authorization: `Bearer ${this.env.CORPORATE_API_TOKEN}`,
          'Content-Type': 'application/json'
        }
      })
    );

    return res.data;
  }
}
