## `src/modules/customers/customers.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { DomainError } from '../../common/errors/domain-error';
import { CorporateClientService } from '../corporate/corporate-client.service';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { Customer } from './types/customer.types';

@Injectable()
export class CustomersService {
  private readonly customers = new Map<string, Customer>();

  constructor(private readonly corporateClient: CorporateClientService) {}

  async create(dto: CreateCustomerDto): Promise<Customer> {
    const existing = await this.corporateClient.fetchCustomer(dto.employeeId);

    if (existing && existing.email !== dto.email) {
      throw new DomainError(
        'Employee ID already exists with different email in corporate system',
        'CUSTOMER_CONFLICT',
        409
      );
    }

    const created = await this.corporateClient.createCustomer({
      employeeId: dto.employeeId,
      fullName: dto.fullName,
      email: dto.email,
      department: dto.department
    });

    const customer: Customer = {
      id: created.id ?? randomUUID(),
      employeeId: dto.employeeId,
      fullName: dto.fullName,
      email: dto.email,
      department: dto.department,
      createdAt: new Date().toISOString()
    };

    this.customers.set(customer.id, customer);
    return customer;
  }

  findById(id: string): Customer {
    const customer = this.customers.get(id);
    if (!customer) {
      throw new DomainError('Customer not found', 'CUSTOMER_NOT_FOUND', 404);
    }
    return customer;
  }
}
