```ts
import { Injectable, Logger } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import {
  CorporateCrmCreateCustomerRequest,
  CorporateCrmCreateCustomerResponse
} from './corporate-crm.types';

@Injectable()
export class CorporateCrmClient {
  private readonly logger = new Logger(CorporateCrmClient.name);
  private readonly http: AxiosInstance;

  constructor() {
    this.http = axios.create({
      timeout: 5000
    });
  }

  configure(baseURL: string, apiKey: string): void {
    this.http.defaults.baseURL = baseURL;
    this.http.defaults.headers.common['Authorization'] = `Bearer ${apiKey}`;
    this.http.defaults.headers.common['Content-Type'] = 'application/json';
  }

  async createCustomer(
    payload: CorporateCrmCreateCustomerRequest
  ): Promise<CorporateCrmCreateCustomerResponse> {
    this.logger.log(`Creating customer in corporate CRM: ${payload.externalId}`);

    const response = await this.http.post<CorporateCrmCreateCustomerResponse>(
      '/customers',
      payload
    );

    return response.data;
  }
}
```

