import { Injectable, BadGatewayException } from '@nestjs/common';
import { CorporateCrmClient } from '../integrations/corporate-crm/corporate-crm.client';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CustomerResponseDto } from './dto/customer-response.dto';

@Injectable()
export class CustomersService {
  constructor(private readonly crmClient: CorporateCrmClient) {}

  async createCustomer(input: CreateCustomerDto): Promise<CustomerResponseDto> {
    try {
      const crmResult = await this.crmClient.createCustomer({
        externalId: input.externalId,
        fullName: input.fullName,
        email: input.email
      });

      return {
        externalId: input.externalId,
        fullName: input.fullName,
        email: input.email,
        crmCustomerId: crmResult.crmCustomerId,
        crmStatus: crmResult.status
      };
    } catch (error) {
      throw new BadGatewayException('Failed to synchronize customer with corporate CRM');
    }
  }
}
