import { Injectable, InternalServerErrorException, UnauthorizedException } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { ConfigService } from '@nestjs/config';
import { CorporateCustomerLookupResponse } from './corporate-client.types';

@Injectable()
export class CorporateClientService {
  private readonly client: AxiosInstance;

  constructor(private readonly configService: ConfigService) {
    this.client = axios.create({
      baseURL: this.configService.getOrThrow<string>('CORPORATE_API_BASE_URL'),
      timeout: 5000,
      headers: {
        Authorization: `Bearer ${this.configService.getOrThrow<string>('CORPORATE_API_TOKEN')}`,
        'Content-Type': 'application/json'
      }
    });
  }

  async lookupCustomerByEmail(email: string): Promise<CorporateCustomerLookupResponse> {
    try {
      const { data } = await this.client.get<CorporateCustomerLookupResponse>(
        `/customers/lookup`,
        { params: { email } }
      );

      return data;
    } catch (error: any) {
      const status = error?.response?.status;

      if (status === 401 || status === 403) {
        throw new UnauthorizedException('Corporate system authentication failed');
      }

      throw new InternalServerErrorException('Failed to communicate with corporate system');
    }
  }
}
```

