# 7) Customers service

## `src/customers/customers.service.ts`

```ts
import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { CorporateClientService } from '../integrations/corporate/corporate-client.service';
import { CreateCustomerDto } from './dto/create-customer.dto';

@Injectable()
export class CustomersService {
  constructor(
    private readonly prisma: PrismaService,
    private readonly corporateClient: CorporateClientService
  ) {}

  async create(dto: CreateCustomerDto) {
    const existing = await this.prisma.customer.findUnique({
      where: { email: dto.email }
    });

    if (existing) {
      throw new ConflictException('Customer already exists');
    }

    const corporateRecord = await this.corporateClient.lookupCustomerByEmail(dto.email);

    const customer = await this.prisma.customer.create({
      data: {
        name: dto.name,
        email: dto.email,
        externalId: corporateRecord.externalId
      }
    });

    return customer;
  }

  async findById(id: string) {
    const customer = await this.prisma.customer.findUnique({
      where: { id }
    });

    if (!customer) {
      throw new NotFoundException('Customer not found');
    }

    return customer;
  }
}
```

