import { HttpService } from '@nestjs/axios';
import { Inject, Injectable } from '@nestjs/common';
import { firstValueFrom } from 'rxjs';
import { configuration } from '../config/configuration';

export interface CorporateCustomerPayload {
  customerId: string;
  email: string;
  fullName: string;
}

@Injectable()
export class CorporateApiClient {
  private readonly baseUrl = configuration().CORPORATE_API_BASE_URL;
  private readonly token = configuration().CORPORATE_API_TOKEN;

  constructor(private readonly httpService: HttpService) {}

  async syncCustomer(payload: CorporateCustomerPayload): Promise<void> {
    await firstValueFrom(
      this.httpService.post(
        `${this.baseUrl}/v1/customers/sync`,
        payload,
        {
          headers: {
            Authorization: `Bearer ${this.token}`,
            'Content-Type': 'application/json'
          },
          timeout: 5000
        }
      )
    );
  }
}
```

