## `src/customers/customers.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { DomainError } from '../common/errors';
import { CorporateApiClient } from '../integrations/corporate-api.client';
import { CustomersRepository, type CustomerRecord } from './customers.repository';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CustomerResponseDto } from './dto/customer-response.dto';

@Injectable()
export class CustomersService {
  constructor(
    private readonly repository: CustomersRepository,
    private readonly corporateApiClient: CorporateApiClient
  ) {}

  async create(input: CreateCustomerDto): Promise<CustomerResponseDto> {
    const existing = await this.repository.findByEmail(input.email);
    if (existing) {
      throw new DomainError('Customer already exists', 'CUSTOMER_EXISTS', 409);
    }

    const record: CustomerRecord = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: new Date()
    };

    await this.repository.save(record);

    await this.corporateApiClient.syncCustomer({
      customerId: record.id,
      email: record.email,
      fullName: `${record.firstName} ${record.lastName}`
    });

    return this.toResponse(record);
  }

  async getById(id: string): Promise<CustomerResponseDto> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new DomainError('Customer not found', 'CUSTOMER_NOT_FOUND', 404);
    }
    return this.toResponse(customer);
  }

  private toResponse(customer: CustomerRecord): CustomerResponseDto {
    return {
      id: customer.id,
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      createdAt: customer.createdAt.toISOString()
    };
  }
}
```

