import { Injectable, InternalServerErrorException } from '@nestjs/common';
import axios, { AxiosInstance } from 'axios';
import { ConfigService } from '@nestjs/config';

export interface CorporateEmployeeRecord {
  employeeId: string;
  fullName: string;
  departmentCode: string;
  active: boolean;
}

@Injectable()
export class CorporateIntegrationService {
  private readonly client: AxiosInstance;

  constructor(private readonly configService: ConfigService) {
    const baseURL = this.configService.get<string>('corporateApi.baseUrl');
    const token = this.configService.get<string>('corporateApi.token');

    if (!baseURL || !token) {
      throw new Error('Corporate API configuration is missing');
    }

    this.client = axios.create({
      baseURL,
      timeout: 5000,
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
    });
  }

  async fetchEmployeeRecord(employeeId: string): Promise<CorporateEmployeeRecord> {
    try {
      const response = await this.client.get<CorporateEmployeeRecord>(
        `/employees/${encodeURIComponent(employeeId)}`,
      );
      return response.data;
    } catch (error) {
      throw new InternalServerErrorException(
        `Failed to fetch employee record from corporate system: ${(error as Error).message}`,
      );
    }
  }
}
