```ts
import { HttpService } from '@nestjs/axios';
import { Injectable } from '@nestjs/common';
import { firstValueFrom } from 'rxjs';
import { IntegrationError } from '../common/errors';

export interface CorporateCustomerPayload {
  externalId: string;
  name: string;
  email: string;
}

export interface CorporateCustomerResponse {
  referenceId: string;
}

@Injectable()
export class CorporateApiClient {
  constructor(private readonly http: HttpService) {}

  async registerCustomer(payload: CorporateCustomerPayload): Promise<CorporateCustomerResponse> {
    try {
      const response = await firstValueFrom(
        this.http.post<CorporateCustomerResponse>('/customers/register', payload, {
          headers: {
            'Content-Type': 'application/json'
          }
        })
      );

      if (!response.data?.referenceId) {
        throw new Error('Missing referenceId in corporate response');
      }

      return response.data;
    } catch (error) {
      throw new IntegrationError('Failed to register customer with corporate system', error);
    }
  }
}
```

