## `src/customers/customers.service.ts`

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { NotFoundError } from '../common/errors';
import { CorporateApiClient } from '../integrations/corporate-api.client';
import { CustomersRepository } from './customers.repository';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { CustomerResponseDto } from './dto/customer-response.dto';

@Injectable()
export class CustomersService {
  constructor(
    private readonly repository: CustomersRepository,
    private readonly corporateApi: CorporateApiClient
  ) {}

  async create(dto: CreateCustomerDto): Promise<CustomerResponseDto> {
    const id = randomUUID();

    const corporate = await this.corporateApi.registerCustomer({
      externalId: id,
      name: dto.name,
      email: dto.email
    });

    const record = await this.repository.create({
      id,
      name: dto.name,
      email: dto.email,
      corporateReferenceId: corporate.referenceId
    });

    return {
      id: record.id,
      name: record.name,
      email: record.email,
      corporateReferenceId: record.corporateReferenceId
    };
  }

  async getById(id: string): Promise<CustomerResponseDto> {
    const record = await this.repository.findById(id);
    if (!record) {
      throw new NotFoundError(`Customer not found: ${id}`);
    }

    return {
      id: record.id,
      name: record.name,
      email: record.email,
      corporateReferenceId: record.corporateReferenceId
    };
  }
}
```

