import axios, { AxiosInstance } from 'axios';
import { AppError } from '../../common/errors/app-error';
import type { CrmCustomerPayload, CrmCustomerResponse } from './crm.types';

export class CrmClient {
  private readonly client: AxiosInstance;

  constructor(
    baseURL: string,
    apiKey: string,
  ) {
    this.client = axios.create({
      baseURL,
      timeout: 5000,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${apiKey}`,
      },
    });
  }

  async upsertCustomer(payload: CrmCustomerPayload): Promise<CrmCustomerResponse> {
    try {
      const response = await this.client.post<CrmCustomerResponse>('/customers/upsert', payload);
      return response.data;
    } catch (error: unknown) {
      throw new AppError(
        'CRM_UPSERT_FAILED',
        'Failed to upsert customer in CRM',
        502,
        error instanceof Error ? error.message : error,
      );
    }
  }
}
