import type { CustomerRepository } from '../persistence/customer.repository';
import type { CreateCustomerDto } from './dto/create-customer.dto';
import type { CustomerResponseDto } from './dto/customer-response.dto';

export class CustomersService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly crmClient: CrmClient,
  ) {}

  async create(dto: CreateCustomerDto): Promise<CustomerResponseDto> {
    const existing = await this.repository.findByExternalId(dto.externalId);
    if (existing) {
      throw new AppError('CUSTOMER_ALREADY_EXISTS', 'Customer already exists', 409);
    }

    const crmResult = await this.crmClient.upsertCustomer({
      externalId: dto.externalId,
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
    });

    const record = await this.repository.save({
      id: randomUUID(),
      externalId: dto.externalId,
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      crmId: crmResult.id,
    });

    return {
      id: record.id,
      externalId: record.externalId,
      firstName: record.firstName,
      lastName: record.lastName,
      email: record.email,
      crmId: record.crmId,
    };
  }

  async getByExternalId(externalId: string): Promise<CustomerResponseDto> {
    const customer = await this.repository.findByExternalId(externalId);
    if (!customer) {
      throw new AppError('CUSTOMER_NOT_FOUND', 'Customer not found', 404);
    }

    return {
      id: customer.id,
      externalId: customer.externalId,
      firstName: customer.firstName,
      lastName: customer.lastName,
      email: customer.email,
      crmId: customer.crmId,
    };
  }
}
```

