import axios, { AxiosInstance } from 'axios';
import { Injectable } from '@nestjs/common';

export interface CorporateCustomerPayload {
  externalId: string;
  name: string;
  email: string;
}

export interface CorporateCustomerResponse {
  id: string;
  status: 'active' | 'pending' | 'disabled';
}

@Injectable()
export class CorporateApiClient {
  private readonly client: AxiosInstance;

  constructor() {
    this.client = axios.create({
      timeout: 5000
    });
  }

  configure(baseURL: string, token: string): void {
    this.client.defaults.baseURL = baseURL;
    this.client.defaults.headers.common.Authorization = `Bearer ${token}`;
    this.client.defaults.headers.common['Content-Type'] = 'application/json';
  }

  async createCustomer(payload: CorporateCustomerPayload): Promise<CorporateCustomerResponse> {
    const response = await this.client.post<CorporateCustomerResponse>('/customers', payload);
    return response.data;
  }

  async getHealth(): Promise<boolean> {
    const response = await this.client.get('/health');
    return response.status === 200;
  }
}
