import { Injectable } from '@nestjs/common';
import { randomUUID } from 'uuid';
import { CorporateApiClient } from '../integrations/corporate-api.client';
import { CreateCustomerDto } from './dto/create-customer.dto';
import { Customer } from './types/customer';
import { DomainError } from '../common/errors/domain-error';

@Injectable()
export class CustomersService {
  constructor(private readonly corporateApiClient: CorporateApiClient) {}

  async createCustomer(dto: CreateCustomerDto): Promise<Customer> {
    try {
      const corporateResult = await this.corporateApiClient.createCustomer({
        externalId: dto.externalId,
        name: dto.name,
        email: dto.email
      });

      return {
        id: randomUUID(),
        externalId: dto.externalId,
        name: dto.name,
        email: dto.email,
        corporateStatus: corporateResult.status,
        createdAt: new Date().toISOString()
      };
    } catch (error: unknown) {
      throw new DomainError(
        'Failed to create customer in corporate system',
        'CORPORATE_CREATE_FAILED',
        502,
        {
          cause: error instanceof Error ? error.message : 'Unknown error'
        }
      );
    }
  }
}
