```ts
import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { EmployeesRepository } from './employees.repository';
import { CreateEmployeeDto } from './dto/employee.schemas';

@Injectable()
export class EmployeesService {
  constructor(private readonly repo: EmployeesRepository) {}

  async createEmployee(input: CreateEmployeeDto) {
    const existing = await this.repo.findByEmployeeNo(input.employeeNo);
    if (existing) {
      throw new ConflictException(`Employee ${input.employeeNo} already exists`);
    }

    return this.repo.create(input);
  }

  async getEmployeeByNo(employeeNo: string) {
    const employee = await this.repo.findByEmployeeNo(employeeNo);
    if (!employee) {
      throw new NotFoundException(`Employee ${employeeNo} not found`);
    }
    return employee;
  }

  async listEmployees() {
    return this.repo.list();
  }
}
```

