import { Injectable, Logger } from '@nestjs/common';
import axios from 'axios';
import { SapEmployeeSyncRequest } from './sap.types';

@Injectable()
export class SapClient {
  private readonly logger = new Logger(SapClient.name);

  constructor() {}

  async syncEmployee(payload: SapEmployeeSyncRequest): Promise<void> {
    const baseUrl = process.env.SAP_BASE_URL;
    const apiKey = process.env.SAP_API_KEY;

    if (!baseUrl || !apiKey) {
      this.logger.warn('SAP integration not configured; skipping sync');
      return;
    }

    await axios.post(`${baseUrl}/employees/sync`, payload, {
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json'
      },
      timeout: 5000
    });
  }
}
