## 7) Application layer

### `src/application/CustomerService.ts`

```ts
import { randomUUID } from "node:crypto";
import { Customer } from "../domain/entities/Customer.js";
import { DomainError } from "../domain/errors/DomainError.js";
import { CustomerRepository } from "../domain/ports/CustomerRepository.js";
import { CorporateDirectoryClient } from "../domain/ports/CorporateDirectoryClient.js";

export class CustomerService {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  async createFromEmployeeId(employeeId: string): Promise<Customer> {
    const existing = await this.customerRepository.findByEmployeeId(employeeId);
    if (existing) {
      throw new DomainError("Customer already exists for employeeId", "CUSTOMER_ALREADY_EXISTS");
    }

    const profile = await this.corporateDirectoryClient.getEmployeeProfile(employeeId);
    if (!profile) {
      throw new DomainError("Employee not found in corporate directory", "EMPLOYEE_NOT_FOUND");
    }

    const customer: Customer = {
      id: randomUUID(),
      employeeId: profile.employeeId,
      name: profile.name,
      email: profile.email,
      department: profile.department,
      createdAt: new Date()
    };

    await this.customerRepository.save(customer);
    return customer;
  }

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.customerRepository.findById(id);
    if (!customer) {
      throw new DomainError("Customer not found", "CUSTOMER_NOT_FOUND");
    }
    return customer;
  }
}
```

