## 8) Infrastructure layer

### `src/infrastructure/persistence/InMemoryCustomerRepository.ts`

```ts
import { Customer } from "../../domain/entities/Customer.js";
import { CustomerRepository } from "../../domain/ports/CustomerRepository.js";

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly byId = new Map<string, Customer>();
  private readonly byEmployeeId = new Map<string, string>();

  async save(customer: Customer): Promise<void> {
    this.byId.set(customer.id, customer);
    this.byEmployeeId.set(customer.employeeId, customer.id);
  }

  async findById(id: string): Promise<Customer | null> {
    return this.byId.get(id) ?? null;
  }

  async findByEmployeeId(employeeId: string): Promise<Customer | null> {
    const id = this.byEmployeeId.get(employeeId);
    return id ? this.byId.get(id) ?? null : null;
  }
}
```

### `src/infrastructure/corporate/HttpCorporateDirectoryClient.ts`

```ts
import { CorporateDirectoryClient, CorporateEmployeeProfile } from "../../domain/ports/CorporateDirectoryClient.js";

export class HttpCorporateDirectoryClient implements CorporateDirectoryClient {
  constructor(private readonly baseUrl: string) {}

  async getEmployeeProfile(employeeId: string): Promise<CorporateEmployeeProfile | null> {
    const response = await fetch(`${this.baseUrl}/employees/${encodeURIComponent(employeeId)}`);

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`Corporate directory request failed: ${response.status}`);
    }

    const data: unknown = await response.json();

    if (
      typeof data !== "object" ||
      data === null ||
      typeof (data as { employeeId?: unknown }).employeeId !== "string" ||
      typeof (data as { name?: unknown }).name !== "string" ||
      typeof (data as { email?: unknown }).email !== "string"
    ) {
      throw new Error("Invalid response from corporate directory");
    }

    const profile = data as CorporateEmployeeProfile;
    return profile;
  }
}
```

