### `src/interfaces/http/errorHandler.ts`

```ts
import { FastifyReply, FastifyRequest } from "fastify";
import { DomainError } from "../../domain/errors/DomainError.js";

export function errorHandler(
  error: unknown,
  _request: FastifyRequest,
  reply: FastifyReply
): void {
  if (error instanceof DomainError) {
    const statusCode =
      error.code === "CUSTOMER_NOT_FOUND" ? 404 :
      error.code === "EMPLOYEE_NOT_FOUND" ? 404 :
      error.code === "CUSTOMER_ALREADY_EXISTS" ? 409 :
      400;

    reply.status(statusCode).send({
      error: {
        code: error.code,
        message: error.message
      }
    });
    return;
  }

  console.error(error);
  reply.status(500).send({
    error: {
      code: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    }
  });
}
```

### `src/interfaces/http/routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { CustomerService } from "../../application/CustomerService.js";
import { createCustomerSchema } from "./schemas.js";

export async function registerRoutes(
  app: FastifyInstance,
  customerService: CustomerService
): Promise<void> {
  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.post("/customers", async (request, reply) => {
    const parsed = createCustomerSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: {
          code: "VALIDATION_ERROR",
          message: parsed.error.message
        }
      });
    }

    const customer = await customerService.createFromEmployeeId(parsed.data.employeeId);

    return reply.status(201).send({
      id: customer.id,
      employeeId: customer.employeeId,
      name: customer.name,
      email: customer.email,
      department: customer.department,
      createdAt: customer.createdAt.toISOString()
    });
  });

  app.get("/customers/:id", async (request, reply) => {
    const { id } = request.params as { id: string };
    const customer = await customerService.getCustomer(id);

    return reply.send({
      id: customer.id,
      employeeId: customer.employeeId,
      name: customer.name,
      email: customer.email,
      department: customer.department,
      createdAt: customer.createdAt.toISOString()
    });
  });
}
```

