# 8) Corporate system integration client: `src/integrations/corporateSystemClient.ts`

This is intentionally isolated so you can later swap in SOAP, REST, MQ, or mainframe adapters.

```ts
import { env } from "../config/env.js";
import { IntegrationError } from "../utils/errors.js";
import type { Customer } from "../models/customer.js";

export interface CorporateSystemClient {
  createCustomer(customer: Customer): Promise<{ externalReferenceId: string }>;
}

export class HttpCorporateSystemClient implements CorporateSystemClient {
  async createCustomer(customer: Customer): Promise<{ externalReferenceId: string }> {
    const response = await fetch(`${env.CORPORATE_SYSTEM_BASE_URL}/customers`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${env.CORPORATE_SYSTEM_API_KEY}`
      },
      body: JSON.stringify(customer)
    });

    if (!response.ok) {
      throw new IntegrationError(`Corporate system returned ${response.status}`);
    }

    const data: unknown = await response.json();

    if (
      typeof data !== "object" ||
      data === null ||
      !("externalReferenceId" in data) ||
      typeof (data as { externalReferenceId?: unknown }).externalReferenceId !== "string"
    ) {
      throw new IntegrationError("Invalid response from corporate system");
    }

    return { externalReferenceId: (data as { externalReferenceId: string }).externalReferenceId };
  }
}
```

