import type { CorporateSystemClient } from "../integrations/corporateSystemClient.js";
import type { CreateCustomerInput } from "../schemas/customerSchemas.js";
import type { Customer } from "../models/customer.js";
import { randomUUID } from "node:crypto";

export class CustomerService {
  constructor(private readonly corporateClient: CorporateSystemClient) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const customer: Customer = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email
    };

    const integrationResult = await this.corporateClient.createCustomer(customer);

    return {
      ...customer,
      externalReferenceId: integrationResult.externalReferenceId
    };
  }
