# 10) Controller: `src/controllers/customerController.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import { createCustomerSchema } from "../schemas/customerSchemas.js";
import { AppError } from "../utils/errors.js";
import type { CustomerService } from "../services/customerService.js";

export class CustomerController {
  constructor(private readonly customerService: CustomerService) {}

  createCustomer = async (
    request: FastifyRequest,
    reply: FastifyReply
  ): Promise<void> => {
    const parsed = createCustomerSchema.safeParse(request.body);

    if (!parsed.success) {
      throw new AppError("Invalid request body", 400, "VALIDATION_ERROR");
    }

    const customer = await this.customerService.createCustomer(parsed.data);

    reply.code(201).send(customer);
  };
}
```

