# 13) App bootstrap: `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import helmet from "@fastify/helmet";
import cors from "@fastify/cors";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customer.js";
import { HttpCorporateSystemClient } from "./integrations/corporateSystemClient.js";
import { CustomerService } from "./services/customerService.js";
import { CustomerController } from "./controllers/customerController.js";
import { AppError } from "./utils/errors.js";

export async function buildApp() {
  const app = Fastify({
    logger: true
  });

  await app.register(sensible);
  await app.register(helmet);
  await app.register(cors, { origin: true });

  const corporateClient = new HttpCorporateSystemClient();
  const customerService = new CustomerService(corporateClient);
  const customerController = new CustomerController(customerService);

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      reply.status(error.statusCode).send({
        error: error.code,
        message: error.message
      });
      return;
    }

    app.log.error(error);
    reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });

  await app.register(healthRoutes);
  await app.register(async (instance) => customerRoutes(instance, customerController));

  return app;
}
```

