## `src/employees/employees.service.ts`

This is the main business logic layer.

```ts
import { Injectable } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { CreateEmployeeDto } from './dto/create-employee.dto';
import { EmployeeResponseDto } from './dto/employee-response.dto';
import { EmployeeRepository } from './domain/employee.repository';
import { Employee } from './domain/employee';
import { DomainError } from '../common/errors/domain-error';
import { IdentityClient } from '../integrations/identity/identity.client';
import { HrClient } from '../integrations/hr/hr.client';
import { EventPublisher } from '../integrations/messaging/event-publisher';

@Injectable()
export class EmployeesService {
  constructor(
    private readonly repository: EmployeeRepository,
    private readonly identityClient: IdentityClient,
    private readonly hrClient: HrClient,
    private readonly eventPublisher: EventPublisher
  ) {}

  async create(dto: CreateEmployeeDto): Promise<EmployeeResponseDto> {
    const identityUser = await this.identityClient.getUserByEmail(dto.email);
    if (!identityUser || !identityUser.active) {
      throw new DomainError('Employee must exist in corporate identity system and be active', 'IDENTITY_USER_INVALID', 422);
    }

    const employeeId = randomUUID();

    const employee: Employee = {
      id: employeeId as Employee['id'],
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      department: dto.department,
      createdAt: new Date(),
      updatedAt: new Date()
    };

    const saved = await this.repository.save(employee);

    await this.eventPublisher.publish({
      type: 'employee.created',
      occurredAt: new Date().toISOString(),
      payload: {
        employeeId: saved.id,
        email: saved.email,
        department: saved.department,
        corporateId: identityUser.corporateId
      }
    });

    return this.toResponse(saved);
  }

  async getById(id: string): Promise<EmployeeResponseDto> {
    const employee = await this.repository.findById(id as Employee['id']);
    if (!employee) {
      throw new DomainError('Employee not found', 'EMPLOYEE_NOT_FOUND', 404);
    }

    const hrRecord = await this.hrClient.getEmployeeRecord(id);
    if (hrRecord && hrRecord.department !== employee.department) {
      // Example of enterprise consistency check
      throw new DomainError('Employee department mismatch with HR system', 'HR_CONSISTENCY_ERROR', 409);
    }

    return this.toResponse(employee);
  }

  private toResponse(employee: Employee): EmployeeResponseDto {
    return {
      id: employee.id,
      firstName: employee.firstName,
      lastName: employee.lastName,
      email: employee.email,
      department: employee.department,
      createdAt: employee.createdAt.toISOString(),
      updatedAt: employee.updatedAt.toISOString()
    };
  }
}
```

