# 10) Corporate integration clients

These are intentionally thin adapters so you can later swap implementations without changing business logic.

## src/integrations/sso.client.ts

```ts
import { request } from "undici";
import { env } from "../config/env.js";
import { IntegrationError } from "../domain/errors.js";

export class SsoClient {
  async validateToken(token: string): Promise<{ subject: string; roles: string[] }> {
    const res = await request(`${env.SSO_BASE_URL}/introspect`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ token })
    });

    if (res.statusCode !== 200) {
      throw new IntegrationError("SSO token validation failed");
    }

    const body = (await res.body.json()) as { active: boolean; sub: string; roles: string[] };

    if (!body.active) {
      throw new IntegrationError("Inactive token");
    }

    return { subject: body.sub, roles: body.roles ?? [] };
  }
}
```

