# 11) Service layer

## src/services/customer.service.ts

```ts
import { ConflictError, NotFoundError } from "../domain/errors.js";
import { CustomerRepository } from "../repositories/customer.repository.js";
import { ErpClient } from "../integrations/erp.client.js";
import { MessagingClient } from "../integrations/messaging.client.js";
import { CreateCustomerInput, UpdateCustomerInput } from "../schemas/customer.schema.js";

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly erp: ErpClient,
    private readonly messaging: MessagingClient
  ) {}

  async create(input: CreateCustomerInput) {
    const existing = await this.repo.findByEmail(input.email);
    if (existing) throw new ConflictError("Customer with this email already exists");

    const customer = await this.repo.create(input);

    await this.erp.syncCustomer({
      id: customer.id,
      email: customer.email,
      firstName: customer.firstName,
      lastName: customer.lastName
    });

    await this.messaging.publish({
      type: "customer.created",
      payload: customer
    });

    return customer;
  }

  async getById(id: string) {
    const customer = await this.repo.findById(id);
    if (!customer) throw new NotFoundError("Customer not found");
    return customer;
  }

  async update(id: string, input: UpdateCustomerInput) {
    await this.getById(id);
    return this.repo.update(id, input);
  }
}
```

