# 14) Routes

## src/routes/customer.routes.ts

```ts
import { FastifyInstance } from "fastify";
import {
  createCustomerSchema,
  updateCustomerSchema,
  customerResponseSchema
} from "../schemas/customer.schema.js";
import { CustomerService } from "../services/customer.service.js";
import { CustomerRepository } from "../repositories/customer.repository.js";
import { ErpClient } from "../integrations/erp.client.js";
import { MessagingClient } from "../integrations/messaging.client.js";

export async function customerRoutes(app: FastifyInstance) {
  const service = new CustomerService(
    new CustomerRepository(app.prisma),
    new ErpClient(),
    new MessagingClient()
  );

  app.post(
    "/customers",
    {
      schema: {
        body: createCustomerSchema,
        response: {
          201: customerResponseSchema
        }
      }
    },
    async (request, reply) => {
      const customer = await service.create(request.body);
      return reply.code(201).send(customer);
    }
  );

  app.get(
    "/customers/:id",
    {
      schema: {
        params: createCustomerSchema.pick({}).extend({ id: createCustomerSchema.shape.email }),
        response: {
          200: customerResponseSchema
        }
      }
    },
    async (request) => {
      const { id } = request.params as { id: string };
      return service.getById(id);
    }
  );

  app.patch(
    "/customers/:id",
    {
      schema: {
        body: updateCustomerSchema,
        response: {
          200: customerResponseSchema
        }
      }
    },
    async (request) => {
      const { id } = request.params as { id: string };
      return service.update(id, request.body);
    }
  );
}
```

