## 8) Use case

### `src/application/use-cases/create-customer.ts`

```ts
import { randomUUID } from "node:crypto";
import { CreateCustomerInput, Customer } from "../../domain/customer.js";
import { CustomerAlreadyExistsError, CorporateSystemUnavailableError } from "../../domain/errors.js";
import { CustomerRepository } from "../ports/customer-repository.js";
import { CorporateDirectory } from "../ports/corporate-directory.js";
import { ok, err, Result } from "../../shared/result.js";

export type CreateCustomerError =
  | CustomerAlreadyExistsError
  | CorporateSystemUnavailableError
  | Error;

export class CreateCustomerUseCase {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectory: CorporateDirectory
  ) {}

  async execute(input: CreateCustomerInput): Promise<Result<Customer, CreateCustomerError>> {
    const employeeValid = await this.corporateDirectory.isValidEmployee(input.employeeNumber);
    if (!employeeValid) {
      return err(new CorporateSystemUnavailableError());
    }

    const existing = await this.customerRepository.findByEmployeeNumber(input.employeeNumber);
    if (existing) {
      return err(new CustomerAlreadyExistsError(input.employeeNumber));
    }

    const customer: Customer = {
      id: randomUUID(),
      employeeNumber: input.employeeNumber,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: new Date()
    };

    const saved = await this.customerRepository.save(customer);
    return ok(saved);
  }
}
```

