## 9) Infrastructure: PostgreSQL repository

### `src/infrastructure/db/postgres-customer-repository.ts`

```ts
import { Pool } from "pg";
import { Customer, CustomerId } from "../../domain/customer.js";
import { CustomerRepository } from "../../application/ports/customer-repository.js";

export class PostgresCustomerRepository implements CustomerRepository {
  constructor(private readonly pool: Pool) {}

  async findByEmployeeNumber(employeeNumber: string): Promise<Customer | null> {
    const result = await this.pool.query(
      `SELECT id, employee_number, first_name, last_name, email, created_at
       FROM customers
       WHERE employee_number = $1
       LIMIT 1`,
      [employeeNumber]
    );

    if (result.rowCount === 0) return null;
    return this.mapRow(result.rows[0]);
  }

  async findById(id: CustomerId): Promise<Customer | null> {
    const result = await this.pool.query(
      `SELECT id, employee_number, first_name, last_name, email, created_at
       FROM customers
       WHERE id = $1
       LIMIT 1`,
      [id]
    );

    if (result.rowCount === 0) return null;
    return this.mapRow(result.rows[0]);
  }

  async save(customer: Customer): Promise<Customer> {
    await this.pool.query(
      `INSERT INTO customers (id, employee_number, first_name, last_name, email, created_at)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [
        customer.id,
        customer.employeeNumber,
        customer.firstName,
        customer.lastName,
        customer.email,
        customer.createdAt
      ]
    );

    return customer;
  }

  private mapRow(row: any): Customer {
    return {
      id: row.id,
      employeeNumber: row.employee_number,
      firstName: row.first_name,
      lastName: row.last_name,
      email: row.email,
      createdAt: new Date(row.created_at)
    };
  }
}
```

