## 11) HTTP layer

### `src/infrastructure/http/routes/customer-routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { CreateCustomerInputSchema } from "../../../domain/customer.js";
import { CreateCustomerUseCase } from "../../../application/use-cases/create-customer.js";

export async function customerRoutes(app: FastifyInstance, deps: { createCustomer: CreateCustomerUseCase }) {
  app.post("/customers", async (request, reply) => {
    const parsed = CreateCustomerInputSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        details: parsed.error.flatten()
      });
    }

    const result = await deps.createCustomer.execute(parsed.data);

    if (!result.ok) {
      if (result.error.name === "CustomerAlreadyExistsError") {
        return reply.status(409).send({ error: result.error.name, message: result.error.message });
      }
      return reply.status(500).send({ error: result.error.name, message: result.error.message });
    }

    return reply.status(201).send(result.value);
  });

  app.get("/health", async () => ({ status: "ok" }));
}
```

