import Fastify from "fastify";
import { Pool } from "pg";
import { env } from "./config/index.js";
import { logger } from "./shared/logger.js";
import { PostgresCustomerRepository } from "./infrastructure/db/postgres-customer-repository.js";
import { LdapCorporateDirectory } from "./infrastructure/corporate/ldap-corporate-directory.js";
import { CreateCustomerUseCase } from "./application/use-cases/create-customer.js";
import { customerRoutes } from "./infrastructure/http/routes/customer-routes.js";

export async function buildApp() {
  const app = Fastify({ logger });

  const pool = new Pool({ connectionString: env.DATABASE_URL });

  const customerRepository = new PostgresCustomerRepository(pool);
  const corporateDirectory = new LdapCorporateDirectory(env.CORPORATE_DIRECTORY_URL);
  const createCustomer = new CreateCustomerUseCase(customerRepository, corporateDirectory);

  await app.register(customerRoutes, { createCustomer });

  app.addHook("onClose", async () => {
    await pool.end();
  });

  return app;
}
```

