# 6) Service layer: `src/domain/customer.service.ts`

```ts
import { prisma } from "../db/prisma.js";
import { CustomerCreateInput, CustomerUpdateInput } from "./customer.js";
import { CorporateCrmAdapter } from "../integrations/corporate-crm.adapter.js";

export class CustomerService {
  constructor(private readonly crm: CorporateCrmAdapter) {}

  async create(input: CustomerCreateInput) {
    const created = await prisma.customer.create({
      data: {
        externalId: input.externalId,
        firstName: input.firstName,
        lastName: input.lastName,
        email: input.email,
        phone: input.phone ?? null
      }
    });

    // Best-effort sync to corporate CRM
    await this.crm.upsertCustomer({
      id: created.id,
      externalId: created.externalId ?? undefined,
      firstName: created.firstName,
      lastName: created.lastName,
      email: created.email,
      phone: created.phone ?? undefined
    });

    return created;
  }

  async getById(id: string) {
    return prisma.customer.findUnique({ where: { id } });
  }

  async list() {
    return prisma.customer.findMany({ orderBy: { createdAt: "desc" } });
  }

  async update(input: CustomerUpdateInput) {
    const updated = await prisma.customer.update({
      where: { id: input.id },
      data: {
        externalId: input.externalId,
        firstName: input.firstName,
        lastName: input.lastName,
        email: input.email,
        phone: input.phone ?? null
      }
    });

    await this.crm.upsertCustomer({
      id: updated.id,
      externalId: updated.externalId ?? undefined,
      firstName: updated.firstName,
      lastName: updated.lastName,
      email: updated.email,
      phone: updated.phone ?? undefined
    });

    return updated;
  }

  async delete(id: string) {
    return prisma.customer.delete({ where: { id } });
  }
}
