# 11) Routes: `src/routes/customer.routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerCreateInput, CustomerUpdateInput } from "../domain/customer.js";
import { CustomerService } from "../domain/customer.service.js";

export async function customerRoutes(app: FastifyInstance) {
  const service = new CustomerService(app.crm);

  app.get(
    "/customers",
    { preHandler: app.authenticate },
    async () => {
      return service.list();
    }
  );

  app.get(
    "/customers/:id",
    { preHandler: app.authenticate },
    async (request, reply) => {
      const params = z.object({ id: z.string().uuid() }).parse(request.params);
      const customer = await service.getById(params.id);

      if (!customer) {
        return reply.status(404).send({ message: "Customer not found" });
      }

      return customer;
    }
  );

  app.post(
    "/customers",
    { preHandler: app.authenticate },
    async (request) => {
      const input = CustomerCreateInput.parse(request.body);
      return service.create(input);
    }
  );

  app.put(
    "/customers/:id",
    { preHandler: app.authenticate },
    async (request) => {
      const params = z.object({ id: z.string().uuid() }).parse(request.params);
      const body = CustomerCreateInput.partial().parse(request.body);

      const input = CustomerUpdateInput.parse({
        id: params.id,
        ...body
      });

      return service.update(input);
    }
  );

  app.delete(
    "/customers/:id",
    { preHandler: app.authenticate },
    async (request, reply) => {
      const params = z.object({ id: z.string().uuid() }).parse(request.params);
      await service.delete(params.id);
      return reply.status(204).send();
    }
  );
}
```

