# 12) App bootstrap: `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import jwt from "@fastify/jwt";
import { env } from "./config/env.js";
import { logger } from "./utils/logger.js";
import { authHook } from "./middleware/auth.js";
import { customerRoutes } from "./routes/customer.routes.js";
import { CorporateCrmClient } from "./integrations/corporate-crm.client.js";
import { CorporateCrmAdapter } from "./integrations/corporate-crm.adapter.js";

export async function buildApp() {
  const app = Fastify({ logger });

  await app.register(sensible);
  await app.register(jwt, { secret: env.JWT_SECRET });

  app.decorate("authenticate", authHook);
  app.decorate("crm", new CorporateCrmAdapter(new CorporateCrmClient()));

  app.get("/health", async () => ({ status: "ok" }));

  await app.register(customerRoutes, { prefix: "/api/v1" });

  app.setErrorHandler((error, _request, reply) => {
    app.log.error(error);
    return reply.status(500).send({ message: "Internal Server Error" });
  });

  return app;
}
```

