# 9) Corporate system client abstraction

This is where you integrate with existing enterprise systems. The service depends on an interface-like abstraction so it can be mocked in tests and swapped later.

## src/clients/corporateSystemClient.ts

```ts
import { request } from "undici";
import { env } from "../config/env.js";
import { ExternalSystemError } from "../utils/errors.js";

export interface CorporateCustomerPayload {
  firstName: string;
  lastName: string;
  email: string;
  corporateId: string;
}

export interface CorporateCustomerResult {
  externalCustomerId: string;
}

export class CorporateSystemClient {
  async createCustomer(payload: CorporateCustomerPayload): Promise<CorporateCustomerResult> {
    try {
      const res = await request(`${env.CORPORATE_SYSTEM_BASE_URL}/customers`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          "x-api-key": env.CORPORATE_SYSTEM_API_KEY
        },
        body: JSON.stringify(payload)
      });

      if (res.statusCode < 200 || res.statusCode >= 300) {
        throw new ExternalSystemError(`Corporate system returned status ${res.statusCode}`);
      }

      const data = (await res.body.json()) as { externalCustomerId?: string };

      if (!data.externalCustomerId) {
        throw new ExternalSystemError("Corporate system response missing externalCustomerId");
      }

      return { externalCustomerId: data.externalCustomerId };
    } catch (error) {
      if (error instanceof ExternalSystemError) throw error;
      throw new ExternalSystemError();
    }
  }
}
```

