# 11) Controller

## src/controllers/customerController.ts

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import { CreateCustomerRequestSchema } from "../schemas/customerSchemas.js";
import { CustomerService } from "../services/customerService.js";

export class CustomerController {
  constructor(private readonly customerService: CustomerService) {}

  createCustomer = async (
    request: FastifyRequest,
    reply: FastifyReply
  ): Promise<void> => {
    const parsed = CreateCustomerRequestSchema.safeParse(request.body);

    if (!parsed.success) {
      reply.status(400).send({
        error: "VALIDATION_ERROR",
        message: parsed.error.flatten()
      });
      return;
    }

    const customer = await this.customerService.createCustomer(parsed.data);

    reply.status(201).send(customer);
  };
}
```

