  constructor(private readonly directoryClient: CorporateDirectoryClient) {}

  async getCustomerByEmployeeId(employeeId: string): Promise<Customer> {
    const employee = await this.directoryClient.getEmployeeById(employeeId);

    if (!employee) {
      throw new AppError(
        `Employee not found for employeeId=${employeeId}`,
        404,
        "EMPLOYEE_NOT_FOUND"
      );
    }

    return {
      id: `cust_${employee.employeeId}`,
      employeeId: employee.employeeId,
      fullName: employee.fullName,
      email: employee.email,
      department: employee.department
    };
  }
}
