### `src/infrastructure/integrations/CorporateDirectoryHttpClient.ts`

```ts
import { env } from "../../config/env.js";
import type {
  CorporateDirectoryClient,
  CorporateDirectoryEmployee
} from "../../domain/ports/CorporateDirectoryClient.js";
import { AppError } from "../../shared/errors/AppError.js";

export class CorporateDirectoryHttpClient implements CorporateDirectoryClient {
  async getEmployeeById(employeeId: string): Promise<CorporateDirectoryEmployee | null> {
    const url = new URL(`/employees/${encodeURIComponent(employeeId)}`, env.CORPORATE_DIRECTORY_BASE_URL);

    const response = await fetch(url, {
      method: "GET",
      headers: {
        "Authorization": `Bearer ${env.CORPORATE_DIRECTORY_API_KEY}`,
        "Accept": "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new AppError(
        `Corporate directory request failed with status ${response.status}`,
        502,
        "CORPORATE_DIRECTORY_UNAVAILABLE"
      );
    }

    const data: unknown = await response.json();

    if (
      typeof data !== "object" ||
      data === null ||
      !("employeeId" in data) ||
      !("fullName" in data) ||
      !("email" in data)
    ) {
      throw new AppError(
        "Invalid response from corporate directory",
        502,
        "CORPORATE_DIRECTORY_INVALID_RESPONSE"
      );
    }

    const record = data as Record<string, unknown>;

    return {
      employeeId: String(record.employeeId),
      fullName: String(record.fullName),
      email: String(record.email),
      department: typeof record.department === "string" ? record.department : undefined
    };
  }
}
```

