import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "../../../domain/services/CustomerService.js";

const paramsSchema = z.object({
  employeeId: z.string().min(1)
});

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const customerService = new CustomerService(app.directoryClient);

  app.get("/customers/:employeeId", async (request, reply) => {
    const parsed = paramsSchema.safeParse(request.params);

    if (!parsed.success) {
      return reply.status(400).send({
        error: "VALIDATION_ERROR",
        message: "Invalid employeeId parameter",
        details: parsed.error.flatten()
      });
    }

    const customer = await customerService.getCustomerByEmployeeId(parsed.data.employeeId);
    return reply.status(200).send(customer);
  });
}
