## 12) Fastify app setup

We attach the integration client to the app instance in a typed way.

### `src/app.ts`

```ts
import Fastify from "fastify";
import { env } from "./config/env.js";
import { CorporateDirectoryHttpClient } from "./infrastructure/integrations/CorporateDirectoryHttpClient.js";
import { healthRoutes } from "./infrastructure/http/routes/health.js";
import { customerRoutes } from "./infrastructure/http/routes/customers.js";
import { errorHandler } from "./infrastructure/http/errorHandler.js";

declare module "fastify" {
  interface FastifyInstance {
    directoryClient: CorporateDirectoryHttpClient;
  }
}

export function buildApp() {
  const app = Fastify({
    logger: true
  });

  app.decorate("directoryClient", new CorporateDirectoryHttpClient());

  app.setErrorHandler(errorHandler);

  app.register(healthRoutes);
  app.register(customerRoutes);

  app.get("/", async () => ({
    service: env.SERVICE_NAME,
    status: "running"
  }));

  return app;
}
