# 13) Service layer: `src/services/customer.service.ts`

```ts
import { ConflictError, NotFoundError } from "../domain/errors.js";
import { CustomerRepository } from "../repositories/customer.repository.js";
import { CorporateErpClient } from "../integrations/corporate-erp.client.js";
import { EventBusClient } from "../integrations/event-bus.client.js";
import type { CreateCustomerInput, CustomerResponse } from "../schemas/customer.schema.js";

export class CustomerService {
  constructor(
    private readonly customerRepository = new CustomerRepository(),
    private readonly erpClient = new CorporateErpClient(),
    private readonly eventBus = new EventBusClient()
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<CustomerResponse> {
    const existing = await this.customerRepository.findByEmail(input.email);
    if (existing) throw new ConflictError("Customer with this email already exists");

    const customer = await this.customerRepository.create({
      name: input.name,
      email: input.email
    });

    const erpResult = await this.erpClient.syncCustomer({
      id: customer.id,
      name: customer.name,
      email: customer.email
    });

    // In a real implementation, persist externalId in a separate update method
    await this.eventBus.publish("customer.created", {
      id: customer.id,
      name: customer.name,
      email: customer.email,
      externalId: erpResult.externalId
    });

    return {
      id: customer.id,
      externalId: erpResult.externalId,
      name: customer.name,
      email: customer.email,
      status: customer.status as "ACTIVE" | "INACTIVE",
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }

  async getCustomer(id: string): Promise<CustomerResponse> {
    const customer = await this.customerRepository.findById(id);
    if (!customer) throw new NotFoundError("Customer not found");

    return {
      id: customer.id,
      externalId: customer.externalId,
      name: customer.name,
      email: customer.email,
      status: customer.status as "ACTIVE" | "INACTIVE",
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }
}
```

