# 15) Routes: `src/routes/customer.routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { createCustomerSchema } from "../schemas/customer.schema.js";
import { CustomerService } from "../services/customer.service.js";
import { ConflictError, NotFoundError } from "../domain/errors.js";

export async function customerRoutes(app: FastifyInstance) {
  const service = new CustomerService();

  app.post("/customers", async (req, reply) => {
    const parsed = createCustomerSchema.parse(req.body);
    try {
      const customer = await service.createCustomer(parsed);
      return reply.code(201).send(customer);
    } catch (err) {
      if (err instanceof ConflictError) {
        return reply.code(409).send({ message: err.message });
      }
      throw err;
    }
  });

  app.get("/customers/:id", async (req, reply) => {
    const { id } = req.params as { id: string };

    try {
      const customer = await service.getCustomer(id);
      return reply.send(customer);
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.code(404).send({ message: err.message });
      }
      throw err;
    }
  });
}
```

