# 8) Infrastructure: corporate system integration

This is intentionally isolated behind a port so you can swap in:
- REST
- SOAP
- message bus
- database
- mainframe adapter
- vendor SDK

## `src/infrastructure/corporateSystemClient.ts`

```ts
import type { CorporateSystemPort } from "../application/ports.js";
import type { Customer } from "../domain/customer.js";
import { IntegrationError } from "../domain/errors.js";
import { config } from "../config/index.js";

export class CorporateSystemClient implements CorporateSystemPort {
  async fetchCustomerByExternalId(externalId: string): Promise<Customer | null> {
    const url = new URL(`/customers/${encodeURIComponent(externalId)}`, config.CORPORATE_SYSTEM_BASE_URL);

    const response = await fetch(url, {
      headers: {
        "Authorization": `Bearer ${config.CORPORATE_SYSTEM_API_KEY}`,
        "Accept": "application/json"
      }
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new IntegrationError(
        `Corporate system request failed: ${response.status} ${response.statusText}`
      );
    }

    const data: unknown = await response.json();

    // Minimal runtime validation for strict boundary safety
    if (
      typeof data !== "object" ||
      data === null ||
      !("id" in data) ||
      !("externalId" in data) ||
      !("name" in data) ||
      !("email" in data) ||
      !("status" in data)
    ) {
      throw new IntegrationError("Corporate system returned invalid payload");
    }

    const customer = data as Customer;

    if (customer.status !== "ACTIVE" && customer.status !== "INACTIVE") {
      throw new IntegrationError("Corporate system returned invalid customer status");
    }

    return customer;
  }
}
```

