# 9) HTTP layer

## `src/infrastructure/http/schemas.ts`

```ts
import { z } from "zod";

export const GetCustomerParamsSchema = z.object({
  externalId: z.string().min(1)
});

export const CustomerResponseSchema = z.object({
  id: z.string(),
  externalId: z.string(),
  name: z.string(),
  email: z.string().email(),
  status: z.enum(["ACTIVE", "INACTIVE"])
});

export type GetCustomerParams = z.infer<typeof GetCustomerParamsSchema>;
export type CustomerResponse = z.infer<typeof CustomerResponseSchema>;
```

## `src/infrastructure/http/errorHandler.ts`

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import { NotFoundError, IntegrationError } from "../../domain/errors.js";

export function errorHandler(
  error: Error,
  _request: FastifyRequest,
  reply: FastifyReply
): void {
  if (error instanceof NotFoundError) {
    reply.status(404).send({
      error: "NOT_FOUND",
      message: error.message
    });
    return;
  }

  if (error instanceof IntegrationError) {
    reply.status(502).send({
      error: "BAD_GATEWAY",
      message: "Upstream corporate system error"
    });
    return;
  }

  reply.status(500).send({
    error: "INTERNAL_SERVER_ERROR",
    message: "Unexpected server error"
  });
}
```

## `src/infrastructure/http/routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { CustomerService } from "../../application/customerService.js";
import { CorporateSystemClient } from "../corporateSystemClient.js";
import { GetCustomerParamsSchema, CustomerResponseSchema } from "./schemas.js";

export async function registerRoutes(app: FastifyInstance): Promise<void> {
  const corporateSystemClient = new CorporateSystemClient();
  const customerService = new CustomerService(corporateSystemClient);

  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/ready", async () => {
    return { status: "ready" };
  });

  app.get("/customers/:externalId", {
    schema: {
      params: GetCustomerParamsSchema,
      response: {
        200: CustomerResponseSchema,
        404: {
          type: "object",
          properties: {
            error: { type: "string" },
            message: { type: "string" }
          },
          required: ["error", "message"]
        }
      }
    }
  }, async (request, reply) => {
    const { externalId } = GetCustomerParamsSchema.parse(request.params);
    const customer = await customerService.getCustomerByExternalId(externalId);
    return reply.status(200).send(customer);
  });
}
```

