## 7) Corporate system client abstraction: `src/clients/corporateHrClient.ts`

This is where integration with an existing corporate HR system would live.

```ts
import { env } from "../config/env.js";
import { IntegrationError } from "../utils/errors.js";
import type { Employee } from "../models/employee.js";

export interface CorporateHrClient {
  getEmployeeById(id: string): Promise<Employee | null>;
}

export class HttpCorporateHrClient implements CorporateHrClient {
  async getEmployeeById(id: string): Promise<Employee | null> {
    const response = await fetch(`${env.HR_API_BASE_URL}/employees/${encodeURIComponent(id)}`, {
      headers: {
        Authorization: `Bearer ${env.HR_API_TOKEN}`,
        "Content-Type": "application/json"
      }
    });

    if (response.status === 404) return null;
    if (!response.ok) {
      throw new IntegrationError(`HR system returned ${response.status}`);
    }

    const data = (await response.json()) as Employee;
    return data;
  }
}
