# 8) Application service

## `src/application/customerService.ts`

```ts
import { randomUUID } from "node:crypto";
import type { AuditClient, CrmClient, CustomerRepository } from "./ports.js";
import type { Customer } from "../domain/customer.js";
import { NotFoundError, ValidationError } from "../domain/errors.js";

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly crm: CrmClient,
    private readonly audit: AuditClient
  ) {}

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.repo.findById(id);
    if (!customer) throw new NotFoundError(`Customer ${id} not found`);
    return customer;
  }

  async createCustomer(input: {
    firstName: string;
    lastName: string;
    email: string;
    department?: string;
    actor?: string;
  }): Promise<Customer> {
    if (!input.firstName || !input.lastName || !input.email) {
      throw new ValidationError("firstName, lastName, and email are required");
    }

    const now = new Date().toISOString();
    const customer: Customer = {
      id: randomUUID(),
      firstName: input.firstName.trim(),
      lastName: input.lastName.trim(),
      email: input.email.trim().toLowerCase(),
      department: input.department?.trim(),
      createdAt: now,
      updatedAt: now
    };

    await this.repo.save(customer);
    await this.crm.syncCustomer(customer);
    await this.audit.record({
      action: "customer.created",
      entityId: customer.id,
      actor: input.actor,
      timestamp: now,
      metadata: { email: customer.email }
    });

    return customer;
  }
}
```

