## `src/infrastructure/crmClient.ts`

```ts
import { request } from "undici";
import type { CrmClient } from "../application/ports.js";
import type { Customer } from "../domain/customer.js";
import { ExternalSystemError } from "../domain/errors.js";

export class HttpCrmClient implements CrmClient {
  constructor(private readonly baseUrl: string) {}

  async syncCustomer(customer: Customer): Promise<void> {
    const res = await request(`${this.baseUrl}/api/customers/sync`, {
      method: "POST",
      body: JSON.stringify(customer),
      headers: {
        "content-type": "application/json"
      }
    });

    if (res.statusCode >= 400) {
      throw new ExternalSystemError(`CRM sync failed with status ${res.statusCode}`);
    }
  }
}
```

