## `src/routes/customerRoutes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { CustomerService } from "../application/customerService.js";
import { getActorFromRequest } from "../infrastructure/auth.js";
import { ValidationError, NotFoundError } from "../domain/errors.js";

const createCustomerSchema = z.object({
  firstName: z.string().min(1),
  lastName: z.string().min(1),
  email: z.string().email(),
  department: z.string().optional()
});

export async function customerRoutes(app: FastifyInstance): Promise<void> {
  const service = app.customerService;

  app.get("/customers/:id", async (req, reply) => {
    try {
      const { id } = req.params as { id: string };
      const customer = await service.getCustomer(id);
      return reply.send(customer);
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.code(404).send({ error: err.message });
      }
      throw err;
    }
  });

  app.post("/customers", async (req, reply) => {
    try {
      const body = createCustomerSchema.parse(req.body);
      const actor = getActorFromRequest(req);

      const customer = await service.createCustomer({
        ...body,
        actor
      });

      return reply.code(201).send(customer);
    } catch (err) {
      if (err instanceof z.ZodError || err instanceof ValidationError) {
        return reply.code(400).send({
          error: "Validation failed",
          details: err instanceof z.ZodError ? err.flatten() : err.message
        });
      }
      throw err;
    }
  });
}
```

