# 12) App bootstrap

## `src/app.ts`

```ts
import Fastify from "fastify";
import jwt from "@fastify/jwt";
import swagger from "@fastify/swagger";
import swaggerUI from "@fastify/swagger-ui";
import { env } from "./config/env.js";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customerRoutes.js";
import { InMemoryCustomerRepository } from "./infrastructure/repository.js";
import { HttpCrmClient } from "./infrastructure/crmClient.js";
import { HttpAuditClient } from "./infrastructure/auditClient.js";
import { CustomerService } from "./application/customerService.js";

export async function buildApp() {
  const app = Fastify({
    logger: {
      level: env.LOG_LEVEL
    }
  });

  await app.register(jwt, {
    secret: env.JWT_SECRET
  });

  await app.register(swagger, {
    openapi: {
      info: {
        title: "Customer Profile Service",
        version: "0.1.0"
      }
    }
  });

  await app.register(swaggerUI, {
    routePrefix: "/docs"
  });

  const repo = new InMemoryCustomerRepository();
  const crm = new HttpCrmClient(env.CRM_BASE_URL);
  const audit = new HttpAuditClient(env.AUDIT_BASE_URL);

  app.decorate("customerService", new CustomerService(repo, crm, audit));

  await app.register(healthRoutes);
  await app.register(customerRoutes);

  return app;
}
```

