# 15) Recommended next step: PostgreSQL repository

Replace `InMemoryCustomerRepository` with a real repository:

```ts
export class PostgresCustomerRepository implements CustomerRepository {
  constructor(private readonly pool: Pool) {}

  async findById(id: string): Promise<Customer | null> {
    const result = await this.pool.query(
      "SELECT * FROM customers WHERE id = $1",
      [id]
    );
    return result.rows[0] ?? null;
  }

  async save(customer: Customer): Promise<void> {
    await this.pool.query(
      `INSERT INTO customers (id, first_name, last_name, email, department, created_at, updated_at)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       ON CONFLICT (id) DO UPDATE SET
         first_name = EXCLUDED.first_name,
         last_name = EXCLUDED.last_name,
         email = EXCLUDED.email,
         department = EXCLUDED.department,
         updated_at = EXCLUDED.updated_at`,
      [
        customer.id,
        customer.firstName,
        customer.lastName,
        customer.email,
        customer.department ?? null,
        customer.createdAt,
        customer.updatedAt
      ]
    );
  }
}
```

