# 8) Use case

## `src/application/use-cases/create-customer.ts`

```ts
import { randomUUID } from "node:crypto";
import { AppError } from "../../shared/errors.js";
import { Customer } from "../../domain/customer.js";
import { CustomerRepository } from "../ports/customer-repository.js";
import { CorporateDirectoryClient } from "../ports/corporate-directory-client.js";

export interface CreateCustomerInput {
  employeeNumber: string;
  firstName: string;
  lastName: string;
  email: string;
}

export class CreateCustomerUseCase {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  async execute(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.customerRepository.findByEmployeeNumber(input.employeeNumber);
    if (existing) {
      throw new AppError("Customer already exists", "CUSTOMER_ALREADY_EXISTS", 409);
    }

    const employee = await this.corporateDirectoryClient.verifyEmployee(input.employeeNumber);
    if (!employee.exists) {
      throw new AppError("Employee not found in corporate directory", "EMPLOYEE_NOT_FOUND", 404);
    }

    const now = new Date();
    return this.customerRepository.create({
      id: randomUUID(),
      employeeNumber: input.employeeNumber,
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: now,
      updatedAt: now
    });
  }
}
```

