export class PrismaCustomerRepository implements CustomerRepository {
  async create(customer: Omit<Customer, "createdAt" | "updatedAt">): Promise<Customer> {
    const created = await prisma.customer.create({
      data: {
        id: customer.id,
        employeeNumber: customer.employeeNumber,
        firstName: customer.firstName,
        lastName: customer.lastName,
        email: customer.email
      }
    });

    return Customer.parse(created);
  }

  async findByEmployeeNumber(employeeNumber: string): Promise<Customer | null> {
    const found = await prisma.customer.findUnique({
      where: { employeeNumber }
    });

    return found ? Customer.parse(found) : null;
  }
}
