# 13) Routes

## `src/interfaces/http/routes/customer-routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { CreateCustomerUseCase } from "../../../application/use-cases/create-customer.js";
import { createCustomerBodySchema } from "../schemas/customer-schemas.js";
import { requireAuth } from "../auth.js";
import { AppError } from "../../../shared/errors.js";

export async function customerRoutes(app: FastifyInstance) {
  const useCase = new CreateCustomerUseCase(
    app.di.customerRepository,
    app.di.corporateDirectoryClient
  );

  app.post(
    "/customers",
    {
      preHandler: requireAuth,
      schema: {
        body: {
          type: "object",
          required: ["employeeNumber", "firstName", "lastName", "email"],
          properties: {
            employeeNumber: { type: "string" },
            firstName: { type: "string" },
            lastName: { type: "string" },
            email: { type: "string", format: "email" }
          }
        }
      }
    },
    async (request, reply) => {
      const parsed = createCustomerBodySchema.safeParse(request.body);
      if (!parsed.success) {
        throw new AppError("Invalid request body", "VALIDATION_ERROR", 400);
      }

      const customer = await useCase.execute(parsed.data);

      return reply.code(201).send({
        ...customer,
        createdAt: customer.createdAt.toISOString(),
        updatedAt: customer.updatedAt.toISOString()
      });
    }
  );
}
```

