# 14) App bootstrap

## `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import jwt from "@fastify/jwt";
import { env } from "./config/env.js";
import { PrismaCustomerRepository } from "./infrastructure/repositories/prisma-customer-repository.js";
import { LdapDirectoryClient } from "./infrastructure/corporate/ldap-directory-client.js";
import { customerRoutes } from "./interfaces/http/routes/customer-routes.js";
import { AppError } from "./shared/errors.js";

declare module "fastify" {
  interface FastifyInstance {
    di: {
      customerRepository: PrismaCustomerRepository;
      corporateDirectoryClient: LdapDirectoryClient;
    };
  }
}

export async function buildApp() {
  const app = Fastify({
    logger: true
  });

  await app.register(sensible);
  await app.register(jwt, { secret: env.JWT_SECRET });

  app.di = {
    customerRepository: new PrismaCustomerRepository(),
    corporateDirectoryClient: new LdapDirectoryClient(env.CORPORATE_DIRECTORY_URL)
  };

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof AppError) {
      return reply.status(error.statusCode).send({
        error: error.code,
        message: error.message
      });
    }

    app.log.error(error);
    return reply.status(500).send({
      error: "INTERNAL_SERVER_ERROR",
      message: "An unexpected error occurred"
    });
  });

  app.get("/health", async () => ({ status: "ok" }));

  await app.register(customerRoutes, { prefix: "/api/v1" });

  return app;
}
```

