# 9) Business service

## `src/services/employee.service.ts`

```ts
import { prisma } from "../db/prisma.js";
import type { HrSystemClient } from "../integrations/hr-system.client.js";
import type { IdentityProviderClient } from "../integrations/identity-provider.client.js";
import type { EmployeeCreateInput } from "../domain/employee.schemas.js";

export class EmployeeService {
  constructor(
    private readonly hrClient: HrSystemClient,
    private readonly idpClient: IdentityProviderClient
  ) {}

  async createEmployee(input: EmployeeCreateInput) {
    const [hrRecord, emailOk] = await Promise.all([
      this.hrClient.getEmployeeRecord(input.employeeNo),
      this.idpClient.verifyCorporateEmail(input.email)
    ]);

    if (!hrRecord) {
      throw new Error("Employee number not found in HR system");
    }

    if (!emailOk) {
      throw new Error("Email is not a verified corporate email");
    }

    const employee = await prisma.employee.create({
      data: {
        employeeNo: input.employeeNo,
        firstName: input.firstName,
        lastName: input.lastName,
        email: input.email,
        department: hrRecord.department,
        title: hrRecord.title
      }
    });

    return {
      ...employee,
      createdAt: employee.createdAt.toISOString(),
      updatedAt: employee.updatedAt.toISOString()
    };
  }

  async getEmployeeById(id: string) {
    const employee = await prisma.employee.findUnique({ where: { id } });
    if (!employee) return null;

    return {
      ...employee,
      createdAt: employee.createdAt.toISOString(),
      updatedAt: employee.updatedAt.toISOString()
    };
  }
}
```

