import type { FastifyInstance } from "fastify";
import { EmployeeCreateSchema } from "../domain/employee.schemas.js";
import { EmployeeService } from "../services/employee.service.js";

export async function employeeRoutes(app: FastifyInstance) {
  const service = app.diContainer.employeeService as EmployeeService;

  app.post(
    "/employees",
    {
      schema: {
        body: {
          type: "object",
          required: ["employeeNo", "firstName", "lastName", "email", "department", "title"],
          properties: {
            employeeNo: { type: "string" },
            firstName: { type: "string" },
            lastName: { type: "string" },
            email: { type: "string" },
            department: { type: "string" },
            title: { type: "string" }
          }
        }
      }
    },
    async (request, reply) => {
      const input = EmployeeCreateSchema.parse(request.body);
      const employee = await service.createEmployee(input);
      return reply.code(201).send(employee);
    }
  );

  app.get("/employees/:id", async (request, reply) => {
    const { id } = request.params as { id: string };
    const employee = await service.getEmployeeById(id);

    if (!employee) {
      return reply.code(404).send({ error: { message: "Employee not found" } });
    }

    return reply.send(employee);
  });
}
