# 8) Customers service

## `src/modules/customers/customers.service.ts`

```ts
import { Injectable, ConflictException } from '@nestjs/common';
import { PrismaService } from '../../prisma/prisma.service';
import { type CreateCustomerInput, type CustomerResponse } from './schemas/customer.schema';

@Injectable()
export class CustomersService {
  constructor(private readonly prisma: PrismaService) {}

  async create(input: CreateCustomerInput): Promise<CustomerResponse> {
    const existing = await this.prisma.customer.findUnique({
      where: { email: input.email }
    });

    if (existing) {
      throw new ConflictException(`Customer with email ${input.email} already exists`);
    }

    const customer = await this.prisma.customer.create({
      data: {
        name: input.name,
        email: input.email,
        externalId: input.externalId
      }
    });

    return {
      id: customer.id,
      externalId: customer.externalId ?? undefined,
      name: customer.name,
      email: customer.email,
      status: customer.status,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }

  async findById(id: string): Promise<CustomerResponse | null> {
    const customer = await this.prisma.customer.findUnique({ where: { id } });
    if (!customer) return null;

    return {
      id: customer.id,
      externalId: customer.externalId ?? undefined,
      name: customer.name,
      email: customer.email,
      status: customer.status,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    };
  }
}
```

