## 8) Use case

### `src/application/use-cases/get-customer.ts`

```ts
import type { CustomerRepository } from "../ports/customer-repository.js";
import type { CorporateDirectoryClient } from "../ports/corporate-directory-client.js";
import { NotFoundError } from "../../domain/errors.js";
import type { CustomerId } from "../../domain/customer.js";

export interface GetCustomerInput {
  id: CustomerId;
}

export interface GetCustomerOutput {
  id: string;
  employeeNumber: string;
  fullName: string;
  email: string;
  department: string;
  active: boolean;
  corporateActive: boolean;
}

export class GetCustomerUseCase {
  constructor(
    private readonly customerRepository: CustomerRepository,
    private readonly corporateDirectoryClient: CorporateDirectoryClient
  ) {}

  async execute(input: GetCustomerInput): Promise<GetCustomerOutput> {
    const customer = await this.customerRepository.findById(input.id);

    if (!customer) {
      throw new NotFoundError(`Customer not found: ${input.id}`);
    }

    const corporateActive = await this.corporateDirectoryClient.isEmployeeActive(
      customer.employeeNumber
    );

    return {
      id: customer.id,
      employeeNumber: customer.employeeNumber,
      fullName: customer.fullName,
      email: customer.email,
      department: customer.department,
      active: customer.active,
      corporateActive
    };
  }
}
```

