## 12) HTTP routes

### `src/infrastructure/http/routes/customer-routes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { getCustomerParamsSchema, customerResponseSchema } from "../schemas/customer-schemas.js";
import { toCustomerId } from "../../../domain/customer.js";
import { NotFoundError } from "../../../domain/errors.js";
import type { GetCustomerUseCase } from "../../../application/use-cases/get-customer.js";

export async function customerRoutes(
  app: FastifyInstance,
  deps: { getCustomerUseCase: GetCustomerUseCase }
) {
  app.get("/customers/:id", async (request, reply) => {
    const params = getCustomerParamsSchema.parse(request.params);

    try {
      const result = await deps.getCustomerUseCase.execute({
        id: toCustomerId(params.id)
      });

      const validated = customerResponseSchema.parse(result);
      return reply.code(200).send(validated);
    } catch (error) {
      if (error instanceof NotFoundError) {
        return reply.code(404).send({
          error: "NOT_FOUND",
          message: error.message
        });
      }

      request.log.error({ error }, "Unhandled error in GET /customers/:id");
      return reply.code(500).send({
        error: "INTERNAL_SERVER_ERROR",
        message: "An unexpected error occurred"
      });
    }
  });
}
```

