import { env } from "../config/env.js";

export interface HrEmployeeRecord {
  employeeId: string;
  firstName: string;
  lastName: string;
  email: string;
  department: string;
  title: string;
}

export async function fetchEmployeeFromHrSystem(employeeId: string): Promise<HrEmployeeRecord | null> {
  const res = await fetch(`${env.HR_SYSTEM_BASE_URL}/employees/${encodeURIComponent(employeeId)}`, {
    headers: {
      "x-api-key": env.HR_SYSTEM_API_KEY
    }
  });

  if (res.status === 404) return null;
  if (!res.ok) {
    throw new Error(`HR system request failed with status ${res.status}`);
  }

  const data = (await res.json()) as HrEmployeeRecord;
  return data;
}
```

