## 12) Employee service layer

### `src/services/employeeService.ts`

```ts
import { prisma } from "../db/prisma.js";
import { CreateEmployeeInput, EmployeeSchema } from "../domain/employee.js";
import { fetchEmployeeFromHrSystem } from "../integrations/hrSystemClient.js";

export async function getEmployeeByEmployeeId(employeeId: string) {
  const employee = await prisma.employee.findUnique({
    where: { employeeId }
  });

  return employee ? EmployeeSchema.parse(employee) : null;
}

export async function createEmployee(input: CreateEmployeeInput) {
  const employee = await prisma.employee.create({
    data: input
  });

  return EmployeeSchema.parse(employee);
}

export async function syncEmployeeFromHr(employeeId: string) {
  const hrRecord = await fetchEmployeeFromHrSystem(employeeId);
  if (!hrRecord) return null;

  const employee = await prisma.employee.upsert({
    where: { employeeId: hrRecord.employeeId },
    create: hrRecord,
    update: hrRecord
  });

  return EmployeeSchema.parse(employee);
}
```

