## 14) Employee routes

### `src/routes/employees.ts`

```ts
import { FastifyInstance } from "fastify";
import { z } from "zod";
import { requireAuth } from "../middleware/auth.js";
import { CreateEmployeeSchema } from "../domain/employee.js";
import { createEmployee, getEmployeeByEmployeeId, syncEmployeeFromHr } from "../services/employeeService.js";

const paramsSchema = z.object({
  employeeId: z.string().min(1)
});

export async function employeeRoutes(app: FastifyInstance) {
  app.get("/employees/:employeeId", { preHandler: requireAuth }, async (request, reply) => {
    const { employeeId } = paramsSchema.parse(request.params);
    const employee = await getEmployeeByEmployeeId(employeeId);

    if (!employee) {
      return reply.status(404).send({ error: "Employee not found" });
    }

    return employee;
  });

  app.post("/employees", { preHandler: requireAuth }, async (request, reply) => {
    const input = CreateEmployeeSchema.parse(request.body);
    const employee = await createEmployee(input);
    return reply.status(201).send(employee);
  });

  app.post("/employees/:employeeId/sync", { preHandler: requireAuth }, async (request, reply) => {
    const { employeeId } = paramsSchema.parse(request.params);
    const employee = await syncEmployeeFromHr(employeeId);

    if (!employee) {
      return reply.status(404).send({ error: "Employee not found in HR system" });
    }

    return employee;
  });
}
```

