## 8) Repository layer

For the initial implementation, use an in-memory repository with a clean interface so it can later be swapped for PostgreSQL, Oracle, or a corporate data service.

### `src/repositories/customer.repository.ts`

```ts
import { Customer } from "../domain/customer.js";
import { NotFoundError } from "../domain/errors.js";

export interface CustomerRepository {
  findById(id: string): Promise<Customer | null>;
  save(customer: Customer): Promise<Customer>;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly store = new Map<string, Customer>();

  constructor(seed: Customer[] = []) {
    for (const customer of seed) {
      this.store.set(customer.id, customer);
    }
  }

  async findById(id: string): Promise<Customer | null> {
    return this.store.get(id) ?? null;
  }

  async save(customer: Customer): Promise<Customer> {
    this.store.set(customer.id, customer);
    return customer;
  }

  async requireById(id: string): Promise<Customer> {
    const customer = await this.findById(id);
    if (!customer) throw new NotFoundError(`Customer ${id} not found`);
    return customer;
  }
}
