## 10) Service layer

### `src/services/customer.service.ts`

```ts
import { Customer } from "../domain/customer.js";
import { CustomerRepository } from "../repositories/customer.repository.js";
import { CrmClient } from "../integrations/crm.client.js";
import { AuditClient } from "../integrations/audit.client.js";
import { NotFoundError } from "../domain/errors.js";
import { UpdateCustomerDto } from "../dto/customer.dto.js";

export interface UpdateCustomerContext {
  actorId: string;
}

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly crm: CrmClient,
    private readonly audit: AuditClient
  ) {}

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.repo.findById(id);
    if (!customer) throw new NotFoundError(`Customer ${id} not found`);
    return customer;
  }

  async updateCustomer(id: string, dto: UpdateCustomerDto, ctx: UpdateCustomerContext): Promise<Customer> {
    const existing = await this.getCustomer(id);

    const updated: Customer = {
      ...existing,
      ...dto,
      updatedAt: new Date().toISOString()
    };

    const saved = await this.repo.save(updated);

    await Promise.all([
      this.crm.syncCustomer(saved),
      this.audit.record({
        action: "CUSTOMER_UPDATED",
        actorId: ctx.actorId,
        entityType: "Customer",
        entityId: saved.id,
        timestamp: new Date().toISOString(),
        metadata: { changedFields: Object.keys(dto) }
      })
    ]);

    return saved;
  }
}
```

