```ts
import { FastifyInstance } from "fastify";
import { CustomerService } from "../services/customer.service.js";
import { CustomerIdParamsSchema, UpdateCustomerSchema } from "../dto/customer.dto.js";

export async function customerRoutes(app: FastifyInstance, service: CustomerService): Promise<void> {
  app.get(
    "/customers/:id",
    { preHandler: app.auth([app.verifyJwt]) },
    async (request, reply) => {
      const params = CustomerIdParamsSchema.parse(request.params);
      const customer = await service.getCustomer(params.id);
      return reply.send(customer);
    }
  );

  app.patch(
    "/customers/:id",
    { preHandler: app.auth([app.verifyJwt]) },
    async (request, reply) => {
      const params = CustomerIdParamsSchema.parse(request.params);
      const body = UpdateCustomerSchema.parse(request.body);
      const actorId = request.user?.sub ?? "unknown";

      const updated = await service.updateCustomer(params.id, body, { actorId });
      return reply.send(updated);
    }
  );
}
```

