# 8) Infrastructure: repository stub  
`src/infrastructure/db/customerRepository.ts`

This is a typed repository interface plus an in-memory implementation for initial development.

```ts
import type { Customer } from "../../domain/customer.js";

export interface CustomerRepository {
  findById(id: string): Promise<Customer | null>;
  findByExternalId(externalId: string): Promise<Customer | null>;
  save(customer: Customer): Promise<Customer>;
}

export class InMemoryCustomerRepository implements CustomerRepository {
  private readonly items = new Map<string, Customer>();

  async findById(id: string): Promise<Customer | null> {
    return this.items.get(id) ?? null;
  }

  async findByExternalId(externalId: string): Promise<Customer | null> {
    for (const customer of this.items.values()) {
      if (customer.externalId === externalId) return customer;
    }
    return null;
  }

  async save(customer: Customer): Promise<Customer> {
    this.items.set(customer.id, customer);
    return customer;
  }
}
```

