# 12) Application service  
`src/application/customerService.ts`

```ts
import { randomUUID } from "node:crypto";
import type { Customer } from "../domain/customer.js";
import { NotFoundError, ValidationError } from "../domain/errors.js";
import type { CustomerRepository } from "../infrastructure/db/customerRepository.js";
import type { LegacySystemClient } from "../infrastructure/corporate/legacySystemClient.js";
import type { EventPublisher } from "../infrastructure/messaging/eventPublisher.js";
import type { CreateCustomerInput } from "../schemas/customerSchemas.js";

export class CustomerService {
  constructor(
    private readonly repository: CustomerRepository,
    private readonly legacySystemClient: LegacySystemClient,
    private readonly eventPublisher: EventPublisher
  ) {}

  async createCustomer(input: CreateCustomerInput): Promise<Customer> {
    const existing = await this.repository.findByExternalId(input.externalId);
    if (existing) {
      throw new ValidationError("Customer with this externalId already exists");
    }

    const now = new Date();
    const customer: Customer = {
      id: randomUUID(),
      externalId: input.externalId,
      fullName: input.fullName,
      email: input.email,
      createdAt: now,
      updatedAt: now
    };

    const saved = await this.repository.save(customer);
    await this.legacySystemClient.syncCustomer(saved);
    await this.eventPublisher.publish("customer.created", {
      id: saved.id,
      externalId: saved.externalId,
      email: saved.email
    });

    return saved;
  }

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.repository.findById(id);
    if (!customer) {
      throw new NotFoundError("Customer not found");
    }
    return customer;
  }
}
```

