import type { FastifyInstance } from "fastify";
import { createCustomerSchema } from "../schemas/customerSchemas.js";
import { ValidationError } from "../domain/errors.js";
import type { CustomerService } from "../application/customerService.js";

export async function customerRoutes(app: FastifyInstance, service: CustomerService) {
  app.post("/customers", async (request, reply) => {
    const parsed = createCustomerSchema.safeParse(request.body);
    if (!parsed.success) {
      throw new ValidationError(parsed.error.message);
    }

    const customer = await service.createCustomer(parsed.data);

    return reply.code(201).send({
      id: customer.id,
      externalId: customer.externalId,
      fullName: customer.fullName,
      email: customer.email,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    });
  });

  app.get("/customers/:id", async (request, reply) => {
    const { id } = request.params as { id: string };
    const customer = await service.getCustomer(id);

    return reply.send({
      id: customer.id,
      externalId: customer.externalId,
      fullName: customer.fullName,
      email: customer.email,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    });
  });
}
