```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import jwt from "@fastify/jwt";
import { env } from "./config/env.js";
import { logger } from "./utils/logger.js";
import { InMemoryCustomerRepository } from "./infrastructure/db/customerRepository.js";
import { MockIdentityClient } from "./infrastructure/corporate/identityClient.js";
import { MockLegacySystemClient } from "./infrastructure/corporate/legacySystemClient.js";
import { ConsoleEventPublisher } from "./infrastructure/messaging/eventPublisher.js";
import { CustomerService } from "./application/customerService.js";
import { customerRoutes } from "./routes/customerRoutes.js";
import { NotFoundError, ValidationError, IntegrationError } from "./domain/errors.js";

export async function buildApp() {
  const app = Fastify({ logger });

  await app.register(sensible);
  await app.register(jwt, { secret: env.JWT_SECRET });

  const repository = new InMemoryCustomerRepository();
  const legacySystemClient = new MockLegacySystemClient();
  const eventPublisher = new ConsoleEventPublisher();
  const service = new CustomerService(repository, legacySystemClient, eventPublisher);

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof ValidationError) {
      return reply.code(400).send({ error: error.message });
    }
    if (error instanceof NotFoundError) {
      return reply.code(404).send({ error: error.message });
    }
    if (error instanceof IntegrationError) {
      return reply.code(502).send({ error: error.message });
    }

    app.log.error(error);
    return reply.code(500).send({ error: "Internal Server Error" });
  });

  app.get("/health", async () => ({ status: "ok" }));

  await customerRoutes(app, service);

  return app;
}
```

