## 10) src/services/employeeService.ts

```ts
import { NotFoundError } from "../errors.js";
import { CorporateHrClient } from "../integrations/corporateHrClient.js";
import type { Employee, SyncResult } from "../types.js";

export class EmployeeService {
  constructor(private readonly hrClient: CorporateHrClient) {}

  async getEmployee(id: string): Promise<Employee> {
    const employee = await this.hrClient.getEmployeeById(id);

    if (!employee) {
      throw new NotFoundError(`Employee ${id} not found`);
    }

    return employee;
  }

  async syncEmployees(): Promise<SyncResult> {
    const processedCount = await this.hrClient.syncEmployees();

    return {
      synced: true,
      processedCount
    };
  }
}
