## 12) src/routes/employees.ts

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { EmployeeSchema, SyncResultSchema } from "../types.js";
import { NotFoundError } from "../errors.js";
import { EmployeeService } from "../services/employeeService.js";
import { CorporateHrClient } from "../integrations/corporateHrClient.js";

const ParamsSchema = z.object({
  id: z.string().min(1)
});

export async function employeeRoutes(app: FastifyInstance): Promise<void> {
  const service = new EmployeeService(new CorporateHrClient());

  app.get("/v1/employees/:id", async (request, reply) => {
    const params = ParamsSchema.parse(request.params);

    try {
      const employee = await service.getEmployee(params.id);
      return reply.send(EmployeeSchema.parse(employee));
    } catch (error) {
      if (error instanceof NotFoundError) {
        return reply.code(404).send({ message: error.message });
      }
      throw error;
    }
  });

  app.post("/v1/employees/sync", async (_request, reply) => {
    const result = await service.syncEmployees();
    return reply.send(SyncResultSchema.parse(result));
  });
}
```

