## 5) Corporate integration client: `src/integrations/corporateClient.ts`

This is a minimal placeholder for integration with existing corporate systems such as ERP, IAM, CRM, or internal APIs.

```ts
import { env } from "../config/env.js";

export type CorporateUserRecord = {
  employeeId: string;
  fullName: string;
  department: string;
};

export async function fetchCorporateUser(employeeId: string): Promise<CorporateUserRecord | null> {
  const response = await fetch(`${env.CORPORATE_API_BASE_URL}/users/${encodeURIComponent(employeeId)}`, {
    method: "GET",
    headers: {
      Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
      "Content-Type": "application/json"
    }
  });

  if (response.status === 404) return null;
  if (!response.ok) {
    throw new Error(`Corporate API error: ${response.status} ${response.statusText}`);
  }

  const data: unknown = await response.json();

  // Minimal runtime validation without extra dependencies
  if (
    typeof data === "object" &&
    data !== null &&
    "employeeId" in data &&
    "fullName" in data &&
    "department" in data
  ) {
    const record = data as Record<string, unknown>;
    if (
      typeof record.employeeId === "string" &&
      typeof record.fullName === "string" &&
      typeof record.department === "string"
    ) {
      return {
        employeeId: record.employeeId,
        fullName: record.fullName,
        department: record.department
      };
    }
  }

  throw new Error("Invalid response shape from corporate system");
}
```

