## 6) Corporate integration client: `src/services/corporateClient.ts`

This is a minimal placeholder for integration with an existing corporate system.

```ts
import { env } from "../config/env.js";
import type { CorporateUser } from "../types/index.js";

export class CorporateClient {
  async getUser(userId: string): Promise<CorporateUser | null> {
    if (!env.CORPORATE_API_BASE_URL || !env.CORPORATE_API_TOKEN) {
      return null;
    }

    const res = await fetch(`${env.CORPORATE_API_BASE_URL}/users/${encodeURIComponent(userId)}`, {
      headers: {
        Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
        Accept: "application/json"
      }
    });

    if (res.status === 404) return null;
    if (!res.ok) {
      throw new Error(`Corporate API error: ${res.status}`);
    }

    const data: unknown = await res.json();

    // Minimal runtime validation without overengineering
    if (
      typeof data === "object" &&
      data !== null &&
      "id" in data &&
      "displayName" in data &&
      typeof (data as { id: unknown }).id === "string" &&
      typeof (data as { displayName: unknown }).displayName === "string"
    ) {
      const user = data as { id: string; displayName: string; department?: unknown };
      return {
        id: user.id,
        displayName: user.displayName,
        department: typeof user.department === "string" ? user.department : undefined
      };
    }

    throw new Error("Invalid corporate user payload");
  }
}
```

