import { CorporateUserSchema, type CorporateUser } from "../types/corporate.js";
import { env } from "../config/env.js";

export class CorporateClient {
  async getUserByEmployeeNumber(employeeNumber: string): Promise<CorporateUser> {
    const response = await fetch(
      `${env.CORPORATE_API_BASE_URL}/users/${encodeURIComponent(employeeNumber)}`,
      {
        headers: {
          Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
          "Content-Type": "application/json"
