import Fastify from "fastify";
import { healthRoutes } from "./routes/health.js";
import { CorporateClient } from "./services/corporateClient.js";

export function buildApp() {
  const app = Fastify({
    logger: true
  });

  const corporateClient = new CorporateClient();

  app.decorate("corporateClient", corporateClient);

  app.get("/employee/:employeeNumber", async (request, reply) => {
    const { employeeNumber } = request.params as { employeeNumber: string };

    try {
      const user = await corporateClient.getUserByEmployeeNumber(employeeNumber);
      return reply.send(user);
    } catch (error) {
      request.log.error({ error }, "Failed to fetch corporate user");
      return reply.status(502).send({
        error: "BAD_GATEWAY",
        message: "Failed to retrieve data from corporate system"
      });
    }
  });

  app.register(healthRoutes);

  return app;
}
