## 12) Service layer: `src/modules/employee/employee.service.ts`

```ts
import { EmployeeRepository } from "./employee.repo.js";
import { CorporateAdapter } from "../../integrations/corporate/corporate.adapter.js";
import { CreateEmployeeInput } from "./employee.schema.js";

export class EmployeeService {
  constructor(
    private readonly repo: EmployeeRepository,
    private readonly corporate: CorporateAdapter
  ) {}

  async createEmployee(input: CreateEmployeeInput) {
    const existing = await this.repo.findByEmployeeId(input.employeeId);
    if (existing) {
      throw new Error("Employee already exists");
    }

    const employee = await this.repo.create(input);

    await this.corporate.onEmployeeCreated({
      employeeId: employee.employeeId,
      email: employee.email
    });

    return employee;
  }
}
```

