## 13) Employee routes: `src/modules/employee/employee.routes.ts`

```ts
import { FastifyInstance } from "fastify";
import { createEmployeeSchema } from "./employee.schema.js";
import { EmployeeService } from "./employee.service.js";

export async function employeeRoutes(
  app: FastifyInstance,
  deps: { employeeService: EmployeeService }
) {
  app.post("/employees", async (request, reply) => {
    const parsed = createEmployeeSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        details: parsed.error.flatten()
      });
    }

    try {
      const employee = await deps.employeeService.createEmployee(parsed.data);

      return reply.status(201).send({
        id: employee.id,
        employeeId: employee.employeeId,
        firstName: employee.firstName,
        lastName: employee.lastName,
        email: employee.email,
        createdAt: employee.createdAt.toISOString(),
        updatedAt: employee.updatedAt.toISOString()
      });
    } catch (err) {
      const message = err instanceof Error ? err.message : "Unknown error";
      if (message === "Employee already exists") {
        return reply.status(409).send({ error: message });
      }
      request.log.error({ err }, "Failed to create employee");
      return reply.status(500).send({ error: "InternalServerError" });
    }
  });
}
```

