## 14) App composition: `src/app.ts`

```ts
import Fastify from "fastify";
import { logger } from "./logger.js";
import { healthRoutes } from "./routes/health.js";
import { employeeRoutes } from "./modules/employee/employee.routes.js";
import { PrismaClient } from "@prisma/client";
import { EmployeeRepository } from "./modules/employee/employee.repo.js";
import { CorporateClient } from "./integrations/corporate/corporate.client.js";
import { CorporateAdapter } from "./integrations/corporate/corporate.adapter.js";
import { EmployeeService } from "./modules/employee/employee.service.js";

export async function buildApp() {
  const app = Fastify({ logger });

  const prisma = new PrismaClient();
  const employeeRepo = new EmployeeRepository(prisma);
  const corporateClient = new CorporateClient();
  const corporateAdapter = new CorporateAdapter(corporateClient);
  const employeeService = new EmployeeService(employeeRepo, corporateAdapter);

  await app.register(healthRoutes);
  await app.register(async (instance) => {
    await employeeRoutes(instance, { employeeService });
  });

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  return app;
}
```

