# 9) Corporate integration adapter

This is the pattern you want for existing enterprise systems: keep external dependencies behind an interface.

## `src/integrations/corporate-hr.adapter.ts`

```ts
export type CorporateEmployeeRecord = {
  employeeId: string;
  fullName: string;
  department: string;
  email: string;
};

export interface CorporateHrClient {
  fetchEmployee(employeeId: string): Promise<CorporateEmployeeRecord | null>;
}

export class HttpCorporateHrClient implements CorporateHrClient {
  constructor(
    private readonly baseUrl: string,
    private readonly apiKey: string
  ) {}

  async fetchEmployee(employeeId: string): Promise<CorporateEmployeeRecord | null> {
    const res = await fetch(`${this.baseUrl}/employees/${employeeId}`, {
      headers: {
        "Authorization": `Bearer ${this.apiKey}`,
        "Accept": "application/json"
      }
    });

    if (res.status === 404) return null;
    if (!res.ok) {
      throw new Error(`Corporate HR API error: ${res.status}`);
    }

    const data: unknown = await res.json();

    // Minimal runtime validation without adding more libraries
    if (
      typeof data === "object" &&
      data !== null &&
      "employeeId" in data &&
      "fullName" in data &&
      "department" in data &&
      "email" in data
    ) {
      const record = data as Record<string, unknown>;
      return {
        employeeId: String(record.employeeId),
        fullName: String(record.fullName),
        department: String(record.department),
        email: String(record.email)
      };
    }

    throw new Error("Invalid response from Corporate HR API");
  }
}
```

