# 10) Service layer

## `src/services/user.service.ts`

```ts
import { ConflictError, NotFoundError } from "../utils/errors.js";
import { UserRepository } from "../repositories/user.repository.js";
import { CorporateHrClient } from "../integrations/corporate-hr.adapter.js";
import { User, UserCreateInput } from "../domain/user.js";

export class UserService {
  constructor(
    private readonly userRepository: UserRepository,
    private readonly hrClient: CorporateHrClient
  ) {}

  async onboardEmployee(employeeId: string): Promise<User> {
    const existing = await this.userRepository.findByEmployeeId(employeeId);
    if (existing) {
      throw new ConflictError(`User already exists for employeeId=${employeeId}`);
    }

    const hrRecord = await this.hrClient.fetchEmployee(employeeId);
    if (!hrRecord) {
      throw new NotFoundError(`Employee not found in corporate HR system: ${employeeId}`);
    }

    const input: UserCreateInput = {
      employeeId: hrRecord.employeeId,
      email: hrRecord.email,
      fullName: hrRecord.fullName,
      department: hrRecord.department
    };

    return this.userRepository.create(input);
  }

  async getByEmployeeId(employeeId: string): Promise<User> {
    const user = await this.userRepository.findByEmployeeId(employeeId);
    if (!user) {
      throw new NotFoundError(`User not found: ${employeeId}`);
    }
    return user;
  }
}
```

