# 12) App setup

## `src/app.ts`

```ts
import Fastify from "fastify";
import sensible from "@fastify/sensible";
import { PrismaClient } from "@prisma/client";
import { userRoutes } from "./routes/user.routes.js";
import { UserRepository } from "./repositories/user.repository.js";
import { HttpCorporateHrClient } from "./integrations/corporate-hr.adapter.js";
import { UserService } from "./services/user.service.js";
import { ConflictError, NotFoundError } from "./utils/errors.js";

export function buildApp() {
  const app = Fastify({ logger: true });

  app.register(sensible);

  const prisma = new PrismaClient();
  const userRepository = new UserRepository(prisma);

  const hrClient = new HttpCorporateHrClient(
    process.env.CORPORATE_HR_BASE_URL ?? "http://localhost:4000",
    process.env.CORPORATE_HR_API_KEY ?? "dev-key"
  );

  const userService = new UserService(userRepository, hrClient);

  app.setErrorHandler((error, _request, reply) => {
    if (error instanceof NotFoundError) {
      return reply.code(404).send({ error: error.message });
    }
    if (error instanceof ConflictError) {
      return reply.code(409).send({ error: error.message });
    }
    if (error instanceof Error && error.name === "ZodError") {
      return reply.code(400).send({ error: "Invalid request" });
    }

    app.log.error(error);
    return reply.code(500).send({ error: "Internal Server Error" });
  });

  app.get("/health", async () => ({ status: "ok" }));

  app.register(async (instance) => {
    await userRoutes(instance, userService);
  });

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  return app;
}
```

