# 10) `src/middleware/auth.ts`

This is a minimal corporate auth middleware stub. In a real enterprise setup, this would validate JWTs, SSO headers, or mTLS identity.

```ts
import type { FastifyReply, FastifyRequest } from "fastify";
import { authContextSchema, type AuthContext } from "../schemas.js";

declare module "fastify" {
  interface FastifyRequest {
    auth?: AuthContext;
  }
}

export async function authMiddleware(
  request: FastifyRequest,
  reply: FastifyReply
): Promise<void> {
  const userId = request.headers["x-user-id"];
  const rolesHeader = request.headers["x-user-roles"];

  if (typeof userId !== "string" || userId.length === 0) {
    reply.code(401).send({ error: "Unauthorized" });
    return;
  }

  const roles =
    typeof rolesHeader === "string" && rolesHeader.length > 0
      ? rolesHeader.split(",").map((r) => r.trim())
      : [];

  const parsed = authContextSchema.safeParse({ userId, roles });
  if (!parsed.success) {
    reply.code(401).send({ error: "Unauthorized" });
    return;
  }

  request.auth = parsed.data;
}
```

