import type { CreateEmployeeInput, Employee } from "../types.js";

export class EmployeeService {
  constructor(
    private readonly directory: EmployeeDirectory,
    private readonly auditLog: AuditLog
  ) {}

  async getEmployeeById(id: string): Promise<Employee | null> {
    return this.directory.getEmployeeById(id);
  }

  async createEmployee(input: CreateEmployeeInput, actor: string): Promise<Employee> {
    const employee = await this.directory.createEmployee(input);

    await this.auditLog.write({
      actor,
      action: "employee.created",
      resourceType: "employee",
      resourceId: employee.id,
      timestamp: new Date().toISOString()
    });

    return employee;
  }
}
