# 12) `src/routes/employees.ts`

```ts
import type { FastifyInstance } from "fastify";
import { createEmployeeSchema, employeeIdSchema, employeeSchema } from "../schemas.js";
import type { EmployeeService } from "../services/employeeService.js";

export async function employeeRoutes(
  app: FastifyInstance,
  service: EmployeeService
): Promise<void> {
  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/employees/:id", async (request, reply) => {
    const params = employeeIdSchema.safeParse(request.params.id);
    if (!params.success) {
      return reply.code(400).send({ error: "Invalid employee id" });
    }

    const employee = await service.getEmployeeById(params.data);
    if (!employee) {
      return reply.code(404).send({ error: "Employee not found" });
    }

    return employeeSchema.parse(employee);
  });

  app.post("/employees", async (request, reply) => {
    const body = createEmployeeSchema.safeParse(request.body);
    if (!body.success) {
      return reply.code(400).send({
        error: "Invalid request body",
        details: body.error.flatten()
      });
    }

    if (!request.auth) {
      return reply.code(401).send({ error: "Unauthorized" });
    }

    const employee = await service.createEmployee(body.data, request.auth.userId);
    return reply.code(201).send(employeeSchema.parse(employee));
  });
}
```

