```ts
import { config } from "../config.js";
import { logger } from "../utils/logger.js";
import { EmployeeResponseSchema, type EmployeeResponse } from "../types.js";

export async function fetchEmployeeFromCorporateSystem(employeeId: string): Promise<EmployeeResponse> {
  const url = `${config.CORPORATE_API_BASE_URL}/employees/${encodeURIComponent(employeeId)}`;

  const response = await fetch(url, {
    method: "GET",
    headers: {
      "Authorization": `Bearer ${config.CORPORATE_API_TOKEN}`,
      "Accept": "application/json"
    }
  });

  if (!response.ok) {
    logger.error("Corporate system request failed", {
      employeeId,
      status: response.status
    });
    throw new Error(`Corporate system returned ${response.status}`);
  }

  const data: unknown = await response.json();
  return EmployeeResponseSchema.parse(data);
}
