```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { EmployeeIdSchema } from "../schemas/employeeSchemas.js";
import type { EmployeeService } from "../services/employeeService.js";

const ParamsSchema = z.object({
  id: EmployeeIdSchema
});

export async function employeeRoutes(
  app: FastifyInstance,
  service: EmployeeService
): Promise<void> {
  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/employees/:id", async (request, reply) => {
    const parsed = ParamsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "BadRequest",
        message: parsed.error.message
      });
    }

    try {
      const employee = await service.getEmployee(parsed.data.id);
      return reply.send(employee);
    } catch (err) {
      request.log.error({ err }, "Failed to fetch employee");
      return reply.status(502).send({
        error: "UpstreamError",
        message: "Failed to retrieve employee from HR system"
      });
    }
  });
}
```

