## 11) Corporate system adapter: `src/integrations/corporate-system.adapter.ts`

This is a minimal integration abstraction for enterprise systems.

```ts
export interface CorporateSystemAdapter {
  syncCustomer(input: {
    customerId: string;
    name: string;
    email: string;
  }): Promise<{ externalId: string }>;
}

export class HttpCorporateSystemAdapter implements CorporateSystemAdapter {
  constructor(
    private readonly baseUrl: string,
    private readonly token: string
  ) {}

  async syncCustomer(input: {
    customerId: string;
    name: string;
    email: string;
  }): Promise<{ externalId: string }> {
    const response = await fetch(`${this.baseUrl}/customers/sync`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${this.token}`
      },
      body: JSON.stringify(input)
    });

    if (!response.ok) {
      throw new Error(`Corporate sync failed with status ${response.status}`);
    }

    const data: unknown = await response.json();

    if (
      typeof data === "object" &&
      data !== null &&
      "externalId" in data &&
      typeof (data as { externalId: unknown }).externalId === "string"
    ) {
      return { externalId: (data as { externalId: string }).externalId };
    }

    throw new Error("Invalid response from corporate system");
  }
}
```

