## 12) Customer service: `src/modules/customer/customer.service.ts`

This is where business logic lives.

```ts
import { PrismaClient } from "@prisma/client";
import type { CreateCustomerInput } from "./customer.schema.js";
import type { CorporateSystemAdapter } from "../../integrations/corporate-system.adapter.js";

export class CustomerService {
  constructor(
    private readonly prisma: PrismaClient,
    private readonly corporateAdapter: CorporateSystemAdapter
  ) {}

  async createCustomer(input: CreateCustomerInput) {
    const customer = await this.prisma.customer.create({
      data: {
        name: input.name,
        email: input.email
      }
    });

    const syncResult = await this.corporateAdapter.syncCustomer({
      customerId: customer.id,
      name: customer.name,
      email: customer.email
    });

    const updated = await this.prisma.customer.update({
      where: { id: customer.id },
      data: { externalId: syncResult.externalId }
    });

    return updated;
  }
}
```

