## 13) Customer route: `src/modules/customer/customer.route.ts`

```ts
import type { FastifyPluginAsync } from "fastify";
import { PrismaClient } from "@prisma/client";
import { CreateCustomerSchema } from "./customer.schema.js";
import { CustomerService } from "./customer.service.js";
import { HttpCorporateSystemAdapter } from "../../integrations/corporate-system.adapter.js";
import { config } from "../../config.js";

const prisma = new PrismaClient();

const corporateAdapter = new HttpCorporateSystemAdapter(
  config.corporateApiBaseUrl,
  config.corporateApiToken
);

const service = new CustomerService(prisma, corporateAdapter);

export const customerRoutes: FastifyPluginAsync = async (app) => {
  app.post("/", async (request, reply) => {
    const parsed = CreateCustomerSchema.safeParse(request.body);

    if (!parsed.success) {
      return reply.status(400).send({
        error: "ValidationError",
        details: parsed.error.flatten()
      });
    }

    const customer = await service.createCustomer(parsed.data);

    return reply.status(201).send({
      id: customer.id,
      externalId: customer.externalId,
      name: customer.name,
      email: customer.email,
      createdAt: customer.createdAt.toISOString(),
      updatedAt: customer.updatedAt.toISOString()
    });
  });
};
```

