import { randomUUID } from "node:crypto";
import type { CreateCustomerInput, Customer } from "../types.js";
import { customerRepository } from "../repositories/customerRepository.js";
import { crmClient } from "./crmClient.js";
import { auditClient } from "./auditClient.js";

export const customerService = {
  async createCustomer(input: CreateCustomerInput, actor: string): Promise<Customer> {
    const customer: Customer = {
      id: randomUUID(),
      firstName: input.firstName,
      lastName: input.lastName,
      email: input.email,
      createdAt: new Date().toISOString(),
      createdBy: actor
    };

    customerRepository.save(customer);
    await crmClient.syncCustomer(customer);
    await auditClient.log({
      action: "CUSTOMER_CREATED",
      actor,
      resourceId: customer.id,
      timestamp: new Date().toISOString()
    });

    return customer;
  },

  async getCustomerById(id: string): Promise<Customer | null> {
    return customerRepository.findById(id) ?? null;
  }
};
```

