## 14) `src/routes/customerRoutes.ts`

```ts
import type { FastifyInstance } from "fastify";
import { CreateCustomerSchema, CustomerIdSchema, CustomerSchema } from "../schemas/customer.js";
import { customerService } from "../services/customerService.js";
import { identityClient } from "../services/identityClient.js";

export async function customerRoutes(app: FastifyInstance) {
  app.get("/health", async () => {
    return { status: "ok" };
  });

  app.get("/customers/:id", async (request, reply) => {
    const parsed = CustomerIdSchema.safeParse(request.params.id);
    if (!parsed.success) {
      return reply.status(400).send({ error: "Invalid customer id" });
    }

    const customer = await customerService.getCustomerById(parsed.data);
    if (!customer) {
      return reply.status(404).send({ error: "Customer not found" });
    }

    return reply.send(CustomerSchema.parse(customer));
  });

  app.post("/customers", async (request, reply) => {
    const authHeader = request.headers.authorization;
    const user = await identityClient.getCurrentUser(authHeader);

    const parsed = CreateCustomerSchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    if (!user.roles.includes("customer.write")) {
      return reply.status(403).send({ error: "Forbidden" });
    }

    const customer = await customerService.createCustomer(parsed.data, user.userId);
    return reply.status(201).send(CustomerSchema.parse(customer));
  });
}
```

