import { NotFoundError } from "../errors.js";
import type { CorporateSystemClient } from "../integrations/corporateSystemClient.js";
import type { CustomerRepository } from "../repositories/customerRepository.js";
import type { Customer } from "../types.js";

export class CustomerService {
  constructor(
    private readonly repo: CustomerRepository,
    private readonly corporateClient: CorporateSystemClient
  ) {}

  async getCustomer(id: string): Promise<Customer> {
    const customer = await this.repo.findById(id);
    if (!customer) {
      throw new NotFoundError(`Customer ${id} not found`);
    }
    return customer;
  }

  async syncCustomer(externalId: string): Promise<Customer> {
    const customer = await this.corporateClient.fetchCustomerByExternalId(externalId);
    return this.repo.upsert(customer);
  }
}
