# 12) `src/routes/customers.ts`

```ts
import type { FastifyInstance } from "fastify";
import { GetCustomerParamsSchema, SyncCustomerBodySchema } from "../schemas/customerSchemas.js";
import { CustomerSchema } from "../schemas/customerSchemas.js";
import { NotFoundError } from "../errors.js";
import type { CustomerService } from "../services/customerService.js";

export async function customerRoutes(
  app: FastifyInstance,
  service: CustomerService
): Promise<void> {
  app.get("/customers/:id", async (request, reply) => {
    const params = GetCustomerParamsSchema.parse(request.params);
    try {
      const customer = await service.getCustomer(params.id);
      return reply.send(CustomerSchema.parse(customer));
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.code(404).send({ error: err.message });
      }
      throw err;
    }
  });

  app.post("/customers/sync", async (request, reply) => {
    const body = SyncCustomerBodySchema.parse(request.body);
    const customer = await service.syncCustomer(body.externalId);
    return reply.code(201).send(CustomerSchema.parse(customer));
  });
}
```

