import Fastify from "fastify";
import { healthRoutes } from "./routes/health.js";
import { customerRoutes } from "./routes/customers.js";
import { InMemoryCustomerRepository } from "./repositories/customerRepository.js";
import { MockCorporateSystemClient } from "./integrations/corporateSystemClient.js";
import { CustomerService } from "./services/customerService.js";
import type { Config } from "./config.js";

export function buildApp(config: Config) {
  const app = Fastify({ logger: true });

  const repo = new InMemoryCustomerRepository();
  const corporateClient = new MockCorporateSystemClient(config.CORPORATE_SYSTEM_BASE_URL);
  const service = new CustomerService(repo, corporateClient);

  app.setErrorHandler((error, _request, reply) => {
    app.log.error(error);

    if (error instanceof SyntaxError) {
      return reply.code(400).send({ error: "Invalid JSON" });
    }

    return reply.code(500).send({ error: "Internal Server Error" });
  });

  app.register(healthRoutes);
  app.register((instance) => customerRoutes(instance, service));

  return app;
}
