import { env } from "../config/env.js";
import type { CorporateUser } from "../types/index.js";

export async function fetchCorporateUser(userId: string): Promise<CorporateUser> {
  const response = await fetch(`${env.CORPORATE_API_BASE_URL}/users/${encodeURIComponent(userId)}`, {
    method: "GET",
    headers: {
      Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
      "Content-Type": "application/json"
    }
  });

  if (!response.ok) {
    throw new Error(`Corporate API error: ${response.status} ${response.statusText}`);
  }

  const data: unknown = await response.json();

  // Minimal runtime validation without adding more dependencies
  if (
    typeof data === "object" &&
    data !== null &&
    "id" in data &&
    "displayName" in data &&
    "department" in data
  ) {
    const user = data as CorporateUser;
    return user;
  }

  throw new Error("Invalid response from corporate API");
}
```

