## 13) Example of corporate-system usage

If you want to expose an endpoint that fetches a user from the corporate system, add this route:

### `src/routes/user.ts`

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { fetchCorporateUser } from "../services/corporateClient.js";

const paramsSchema = z.object({
  userId: z.string().min(1)
});

export async function userRoutes(app: FastifyInstance) {
  app.get("/users/:userId", async (request, reply) => {
    const parsed = paramsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({ error: "Invalid userId" });
    }

    const user = await fetchCorporateUser(parsed.data.userId);
    return reply.send(user);
  });
}
```

