    private readonly corporateHrClient: CorporateHrClient
  ) {}

  async createEmployee(input: EmployeeCreateInput) {
    const hrRecord = await this.corporateHrClient.fetchEmployeeStatus(input.employeeId);

    if (hrRecord.status !== "ACTIVE") {
      throw new Error("Employee is not active in corporate HR system");
    }

    return this.employeeRepository.create(input);
  }

  async getEmployeeByEmployeeId(employeeId: string) {
    return this.employeeRepository.findByEmployeeId(employeeId);
  }
}
