# 14) Employee route: `src/routes/employee.ts`

```ts
import type { FastifyInstance } from "fastify";
import { employeeCreateSchema } from "../schemas/employee.js";
import type { EmployeeService } from "../services/employeeService.js";

export async function employeeRoutes(
  app: FastifyInstance,
  deps: { employeeService: EmployeeService }
) {
  app.post("/employees", async (request, reply) => {
    const body = employeeCreateSchema.parse(request.body);
    const employee = await deps.employeeService.createEmployee(body);

    return reply.code(201).send(employee);
  });

  app.get("/employees/:employeeId", async (request, reply) => {
    const { employeeId } = request.params as { employeeId: string };
    const employee = await deps.employeeService.getEmployeeByEmployeeId(employeeId);

    if (!employee) {
      return reply.code(404).send({ message: "Employee not found" });
    }

    return employee;
  });
}
```

