# 15) App composition: `src/app.ts`

```ts
import Fastify from "fastify";
import { PrismaClient } from "@prisma/client";
import { loadConfig } from "./config.js";
import { logger } from "./logger.js";
import { healthRoutes } from "./routes/health.js";
import { employeeRoutes } from "./routes/employee.js";
import { EmployeeRepository } from "./repositories/employeeRepository.js";
import { CorporateHrClient } from "./integrations/corporateHrClient.js";
import { EmployeeService } from "./services/employeeService.js";

export async function buildApp() {
  const config = loadConfig();
  const app = Fastify({ logger });

  const prisma = new PrismaClient();
  const employeeRepository = new EmployeeRepository(prisma);
  const corporateHrClient = new CorporateHrClient(
    config.corporateHrBaseUrl,
    config.corporateHrApiKey
  );
  const employeeService = new EmployeeService(employeeRepository, corporateHrClient);

  app.decorate("config", config);

  app.addHook("onClose", async () => {
    await prisma.$disconnect();
  });

  await app.register(healthRoutes);
  await app.register(async (instance) => {
    await employeeRoutes(instance, { employeeService });
  });

  return app;
}
```

