```ts
import type { Customer, SyncResult } from "../types.js";
import { CustomerRepository } from "../repositories/customerRepository.js";
import { CorporateSystemClient } from "../integrations/corporateSystemClient.js";

export class CustomerService {
  constructor(
    private readonly repo = new CustomerRepository(),
    private readonly corporateClient = new CorporateSystemClient()
  ) {}

  async getCustomerById(id: string): Promise<Customer | null> {
    return this.repo.findById(id);
  }

  async syncCustomers(): Promise<SyncResult> {
    const customers = await this.corporateClient.fetchCustomers();

    for (const customer of customers) {
      await this.repo.upsert(customer);
    }

    return { synced: customers.length };
  }
}
