```ts
import { config } from "../config.js";
import { IntegrationError } from "../utils/errors.js";
import type { Customer } from "../types.js";

export async function fetchCustomerFromCorporateSystem(externalId: string): Promise<Customer> {
  const url = `${config.corporateSystemBaseUrl}/customers/${encodeURIComponent(externalId)}`;

  const response = await fetch(url, {
    method: "GET",
    headers: {
      "Authorization": `Bearer ${config.corporateSystemApiKey}`,
      "Accept": "application/json"
    }
  });

  if (!response.ok) {
    throw new IntegrationError(
      `Corporate system request failed with status ${response.status}`
    );
  }

  const data: unknown = await response.json();

  if (!isCustomer(data)) {
    throw new IntegrationError("Invalid customer payload from corporate system");
  }

  return data;
}

function isCustomer(value: unknown): value is Customer {
  if (typeof value !== "object" || value === null) return false;

  const v = value as Record<string, unknown>;
  return (
    typeof v.id === "string" &&
    typeof v.firstName === "string" &&
    typeof v.lastName === "string" &&
    typeof v.email === "string" &&
    typeof v.updatedAt === "string"
  );
}
```

