import type { Customer } from "../types.js";
import { NotFoundError } from "../utils/errors.js";
import { fetchCustomerFromCorporateSystem } from "../integrations/corporateSystemClient.js";

const inMemoryStore = new Map<string, Customer>();

export async function getCustomerById(id: string): Promise<Customer> {
  const customer = inMemoryStore.get(id);
  if (!customer) {
    throw new NotFoundError(`Customer ${id} not found`);
  }
  return customer;
}

export async function syncCustomer(externalId: string): Promise<Customer> {
  const customer = await fetchCustomerFromCorporateSystem(externalId);
  inMemoryStore.set(customer.id, customer);
  return customer;
}
