## 12) src/routes/customers.ts

```ts
import type { FastifyInstance } from "fastify";
import { z } from "zod";
import { getCustomerById, syncCustomer } from "../services/customerService.js";
import { NotFoundError } from "../utils/errors.js";

const customerIdParamsSchema = z.object({
  id: z.string().min(1)
});

const syncCustomerBodySchema = z.object({
  externalId: z.string().min(1)
});

export async function customerRoutes(app: FastifyInstance) {
  app.get("/customers/:id", async (request, reply) => {
    const parsed = customerIdParamsSchema.safeParse(request.params);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request params",
        details: parsed.error.flatten()
      });
    }

    try {
      const customer = await getCustomerById(parsed.data.id);
      return reply.send(customer);
    } catch (err) {
      if (err instanceof NotFoundError) {
        return reply.status(404).send({ error: err.message });
      }
      throw err;
    }
  });

  app.post("/customers/sync", async (request, reply) => {
    const parsed = syncCustomerBodySchema.safeParse(request.body);
    if (!parsed.success) {
      return reply.status(400).send({
        error: "Invalid request body",
        details: parsed.error.flatten()
      });
    }

    const customer = await syncCustomer(parsed.data.externalId);
    return reply.status(201).send({
      success: true,
      customer
    });
  });
}
```

