import { env } from "../config/env.js";

export interface CorporateUser {
  id: string;
  email: string;
  displayName: string;
}

export class CorporateClient {
  async getUserById(userId: string): Promise<CorporateUser> {
    const response = await fetch(
      `${env.CORPORATE_API_BASE_URL}/users/${encodeURIComponent(userId)}`,
      {
        method: "GET",
        headers: {
          Authorization: `Bearer ${env.CORPORATE_API_TOKEN}`,
          "Content-Type": "application/json"
        }
      }
    );

    if (!response.ok) {
      throw new Error(`Corporate API error: ${response.status} ${response.statusText}`);
    }

    const data: unknown = await response.json();

    // Minimal runtime validation without extra dependency
    if (
      typeof data === "object" &&
      data !== null &&
      "id" in data &&
      "email" in data &&
      "displayName" in data &&
      typeof (data as { id: unknown }).id === "string" &&
      typeof (data as { email: unknown }).email === "string" &&
      typeof (data as { displayName: unknown }).displayName === "string"
    ) {
      return data as CorporateUser;
    }

    throw new Error("Invalid corporate user payload");
  }
}
