```csharp
using EnterpriseService.Api.Data;
using EnterpriseService.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseService.Api.Services;

public class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<List<Employee>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Employees
            .AsNoTracking()
            .OrderBy(e => e.LastName)
            .ThenBy(e => e.FirstName)
            .ToListAsync(cancellationToken);
    }

    public async Task<Employee?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _db.Employees
            .AsNoTracking()
            .FirstOrDefaultAsync(e => e.Id == id, cancellationToken);
    }

    public async Task<Employee> CreateAsync(Employee employee, CancellationToken cancellationToken = default)
    {
        employee.Id = Guid.NewGuid();
        employee.CreatedAtUtc = DateTime.UtcNow;

        _db.Employees.Add(employee);
        await _db.SaveChangesAsync(cancellationToken);

        return employee;
    }

    public async Task<bool> UpdateAsync(Guid id, Employee employee, CancellationToken cancellationToken = default)
    {
        var existing = await _db.Employees.FirstOrDefaultAsync(e => e.Id == id, cancellationToken);
        if (existing is null) return false;

        existing.FirstName = employee.FirstName;
        existing.LastName = employee.LastName;
        existing.Email = employee.Email;
        existing.Department = employee.Department;
        existing.UpdatedAtUtc = DateTime.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var existing = await _db.Employees.FirstOrDefaultAsync(e => e.Id == id, cancellationToken);
        if (existing is null) return false;

        _db.Employees.Remove(existing);
        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }
}
