    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] Employee employee, CancellationToken ct)
    {
        if (id != employee.Id) return BadRequest("Route ID and body ID must match.");

        var updated = await _service.UpdateAsync(employee, ct);
        if (!updated) return NotFound();

        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await _service.DeleteAsync(id, ct);
        if (!deleted) return NotFound();

        return NoContent();
    }
}
