## 5) `Controllers/EmployeesController.cs`

```csharp
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class EmployeesController : ControllerBase
{
    private readonly AppDbContext _db;
    private readonly ILogger<EmployeesController> _logger;

    public EmployeesController(AppDbContext db, ILogger<EmployeesController> logger)
    {
        _db = db;
        _logger = logger;
    }

    [HttpGet]
    public async Task<ActionResult<IEnumerable<Employee>>> GetAll(CancellationToken ct)
    {
        var employees = await _db.Employees
            .AsNoTracking()
            .OrderBy(e => e.LastName)
            .ThenBy(e => e.FirstName)
            .ToListAsync(ct);

        return Ok(employees);
    }

    [HttpGet("{id:int}")]
    public async Task<ActionResult<Employee>> GetById(int id, CancellationToken ct)
    {
        var employee = await _db.Employees.AsNoTracking().FirstOrDefaultAsync(e => e.Id == id, ct);
        if (employee is null) return NotFound();

        return Ok(employee);
    }

    [HttpPost]
    public async Task<ActionResult<Employee>> Create([FromBody] Employee employee, CancellationToken ct)
    {
        var exists = await _db.Employees.AnyAsync(e => e.EmployeeNumber == employee.EmployeeNumber, ct);
        if (exists)
        {
            return Conflict(new { message = "EmployeeNumber already exists." });
        }

        employee.CreatedUtc = DateTime.UtcNow;
        _db.Employees.Add(employee);
        await _db.SaveChangesAsync(ct);

        _logger.LogInformation("Created employee {EmployeeNumber}", employee.EmployeeNumber);

        return CreatedAtAction(nameof(GetById), new { id = employee.Id }, employee);
    }

    [HttpPut("{id:int}")]
    public async Task<IActionResult> Update(int id, [FromBody] Employee updated, CancellationToken ct)
    {
        var employee = await _db.Employees.FirstOrDefaultAsync(e => e.Id == id, ct);
        if (employee is null) return NotFound();

        var duplicate = await _db.Employees.AnyAsync(
            e => e.EmployeeNumber == updated.EmployeeNumber && e.Id != id, ct);

        if (duplicate)
        {
            return Conflict(new { message = "EmployeeNumber already exists." });
        }

        employee.EmployeeNumber = updated.EmployeeNumber;
        employee.FirstName = updated.FirstName;
        employee.LastName = updated.LastName;
        employee.Department = updated.Department;

        await _db.SaveChangesAsync(ct);
        return NoContent();
    }

    [HttpDelete("{id:int}")]
    public async Task<IActionResult> Delete(int id, CancellationToken ct)
    {
        var employee = await _db.Employees.FirstOrDefaultAsync(e => e.Id == id, ct);
        if (employee is null) return NotFound();

        _db.Employees.Remove(employee);
        await _db.SaveChangesAsync(ct);

        return NoContent();
    }
}
```

