## 7) Application service: `EmployeeService.cs`

```csharp
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Application.Models;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Repositories;

namespace EnterpriseBackend.Application.Services;

public class EmployeeService : IEmployeeService
{
    private readonly IEmployeeRepository _repository;

    public EmployeeService(IEmployeeRepository repository)
    {
        _repository = repository;
    }

    public async Task<IEnumerable<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var employees = await _repository.GetAllAsync(cancellationToken);

        return employees.Select(e => new EmployeeDto
        {
            Id = e.Id,
            EmployeeNumber = e.EmployeeNumber,
            FullName = $"{e.FirstName} {e.LastName}",
            Email = e.Email
        });
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _repository.GetByIdAsync(id, cancellationToken);
        if (employee is null) return null;

        return new EmployeeDto
        {
            Id = employee.Id,
            EmployeeNumber = employee.EmployeeNumber,
            FullName = $"{employee.FirstName} {employee.LastName}",
            Email = employee.Email
        };
    }

    public async Task<EmployeeDto> CreateAsync(EmployeeDto employee, CancellationToken cancellationToken = default)
    {
        var parts = employee.FullName.Split(' ', 2, StringSplitOptions.RemoveEmptyEntries);
        var firstName = parts.Length > 0 ? parts[0] : string.Empty;
        var lastName = parts.Length > 1 ? parts[1] : string.Empty;

        var entity = new Employee
        {
            Id = Guid.NewGuid(),
            EmployeeNumber = employee.EmployeeNumber,
            FirstName = firstName,
            LastName = lastName,
            Email = employee.Email,
            CreatedAtUtc = DateTime.UtcNow
        };

        await _repository.AddAsync(entity, cancellationToken);

        return new EmployeeDto
        {
            Id = entity.Id,
            EmployeeNumber = entity.EmployeeNumber,
            FullName = $"{entity.FirstName} {entity.LastName}".Trim(),
            Email = entity.Email
        };
    }
}
