# 5) `Controllers/EmployeesController.cs`

```csharp
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class EmployeesController : ControllerBase
{
    private readonly AppDbContext _db;
    private readonly ILogger<EmployeesController> _logger;

    public EmployeesController(AppDbContext db, ILogger<EmployeesController> logger)
    {
        _db = db;
        _logger = logger;
    }

    [HttpGet]
    public async Task<ActionResult<IEnumerable<Employee>>> GetAll(CancellationToken cancellationToken)
    {
        var employees = await _db.Employees
            .AsNoTracking()
            .OrderBy(e => e.LastName)
            .ThenBy(e => e.FirstName)
            .ToListAsync(cancellationToken);

        return Ok(employees);
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<Employee>> GetById(Guid id, CancellationToken cancellationToken)
    {
        var employee = await _db.Employees.AsNoTracking()
            .FirstOrDefaultAsync(e => e.Id == id, cancellationToken);

        if (employee is null)
            return NotFound();

        return Ok(employee);
    }

    [HttpPost]
    public async Task<ActionResult<Employee>> Create([FromBody] Employee employee, CancellationToken cancellationToken)
    {
        if (await _db.Employees.AnyAsync(e => e.Email == employee.Email, cancellationToken))
            return Conflict(new { message = "An employee with this email already exists." });

        employee.Id = Guid.NewGuid();
        employee.CreatedAtUtc = DateTimeOffset.UtcNow;

        _db.Employees.Add(employee);
        await _db.SaveChangesAsync(cancellationToken);

        _logger.LogInformation("Created employee {EmployeeId}", employee.Id);

        return CreatedAtAction(nameof(GetById), new { id = employee.Id }, employee);
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, [FromBody] Employee updated, CancellationToken cancellationToken)
    {
        var employee = await _db.Employees.FirstOrDefaultAsync(e => e.Id == id, cancellationToken);
        if (employee is null)
            return NotFound();

        if (employee.Email != updated.Email &&
            await _db.Employees.AnyAsync(e => e.Email == updated.Email, cancellationToken))
        {
            return Conflict(new { message = "An employee with this email already exists." });
        }

        employee.FirstName = updated.FirstName;
        employee.LastName = updated.LastName;
        employee.Email = updated.Email;
        employee.Department = updated.Department;
        employee.UpdatedAtUtc = DateTimeOffset.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);

        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken cancellationToken)
    {
        var employee = await _db.Employees.FirstOrDefaultAsync(e => e.Id == id, cancellationToken);
        if (employee is null)
            return NotFound();

        _db.Employees.Remove(employee);
        await _db.SaveChangesAsync(cancellationToken);

        return NoContent();
    }
}
```

