## 8) `Services/CustomerService.cs`

```csharp
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Services;

public class CustomerService : ICustomerService
{
    private readonly AppDbContext _db;

    public CustomerService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<Customer>> GetAllAsync(CancellationToken ct = default)
    {
        return await _db.Customers
            .AsNoTracking()
            .OrderByDescending(c => c.CreatedUtc)
            .ToListAsync(ct);
    }

    public async Task<Customer?> GetByIdAsync(Guid id, CancellationToken ct = default)
    {
        return await _db.Customers
            .AsNoTracking()
            .FirstOrDefaultAsync(c => c.Id == id, ct);
    }

    public async Task<Customer> CreateAsync(Customer customer, CancellationToken ct = default)
    {
        customer.Id = Guid.NewGuid();
        customer.CreatedUtc = DateTime.UtcNow;

        _db.Customers.Add(customer);
        await _db.SaveChangesAsync(ct);

        return customer;
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken ct = default)
    {
        var customer = await _db.Customers.FirstOrDefaultAsync(c => c.Id == id, ct);
        if (customer is null) return false;

        _db.Customers.Remove(customer);
        await _db.SaveChangesAsync(ct);
        return true;
    }
}
