namespace EnterpriseBackend.Application.Customers;

public class CustomerService
{
    private readonly AppDbContext _db;

    public CustomerService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<List<CustomerDto>> GetAllAsync()
    {
        return await _db.Customers
            .OrderByDescending(c => c.CreatedUtc)
            .Select(c => new CustomerDto(c.Id, c.Name, c.Email, c.CreatedUtc))
            .ToListAsync();
    }

    public async Task<CustomerDto?> GetByIdAsync(Guid id)
    {
        return await _db.Customers
            .Where(c => c.Id == id)
            .Select(c => new CustomerDto(c.Id, c.Name, c.Email, c.CreatedUtc))
            .FirstOrDefaultAsync();
    }

    public async Task<CustomerDto> CreateAsync(CreateCustomerRequest request)
    {
        var entity = new Customer
        {
            Name = request.Name,
            Email = request.Email
        };

        _db.Customers.Add(entity);
        await _db.SaveChangesAsync();

        return new CustomerDto(entity.Id, entity.Name, entity.Email, entity.CreatedUtc);
    }

    public async Task<bool> UpdateAsync(Guid id, UpdateCustomerRequest request)
    {
        var entity = await _db.Customers.FirstOrDefaultAsync(c => c.Id == id);
        if (entity == null) return false;

        entity.Name = request.Name;
        entity.Email = request.Email;
        entity.UpdatedUtc = DateTime.UtcNow;

        await _db.SaveChangesAsync();
        return true;
    }

    public async Task<bool> DeleteAsync(Guid id)
    {
        var entity = await _db.Customers.FirstOrDefaultAsync(c => c.Id == id);
        if (entity == null) return false;

        _db.Customers.Remove(entity);
        await _db.SaveChangesAsync();
        return true;
    }
}
