## `EnterpriseBackend.Application/Services/EmployeeService.cs`

```csharp
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Application.Models;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Application.Services;

public sealed class EmployeeService : IEmployeeService
{
    private readonly EnterpriseDbContext _db;

    public EmployeeService(EnterpriseDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.Employees
            .AsNoTracking()
            .OrderBy(e => e.LastName)
            .ThenBy(e => e.FirstName)
            .Select(e => new EmployeeDto(e.Id, e.FirstName, e.LastName, e.Email, e.CreatedAtUtc))
            .ToListAsync(cancellationToken);
    }

    public async Task<EmployeeDto?> GetByIdAsync(int id, CancellationToken cancellationToken = default)
    {
        return await _db.Employees
            .AsNoTracking()
            .Where(e => e.Id == id)
            .Select(e => new EmployeeDto(e.Id, e.FirstName, e.LastName, e.Email, e.CreatedAtUtc))
            .FirstOrDefaultAsync(cancellationToken);
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken = default)
    {
        var entity = new Employee
        {
            FirstName = request.FirstName.Trim(),
            LastName = request.LastName.Trim(),
            Email = request.Email.Trim().ToLowerInvariant(),
            CreatedAtUtc = DateTime.UtcNow
        };

        _db.Employees.Add(entity);
        await _db.SaveChangesAsync(cancellationToken);

        return new EmployeeDto(entity.Id, entity.FirstName, entity.LastName, entity.Email, entity.CreatedAtUtc);
    }
}
