        return Ok(employees);
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<Employee>> GetById(Guid id, CancellationToken cancellationToken)
    {
        var employee = await _employeeService.GetByIdAsync(id, cancellationToken);
        if (employee is null)
            return NotFound();

        return Ok(employee);
    }

    [HttpPost]
    public async Task<ActionResult<Employee>> Create([FromBody] CreateEmployeeRequest request, CancellationToken cancellationToken)
    {
        var employee = new Employee
        {
            FirstName = request.FirstName,
            LastName = request.LastName,
            Email = request.Email
        };

        var created = await _employeeService.CreateAsync(employee, cancellationToken);

        _logger.LogInformation("Employee created: {EmployeeId}", created.Id);

        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }
}

public record CreateEmployeeRequest(string FirstName, string LastName, string Email);
