using EnterpriseBackend.Application.Abstractions;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Repositories;

public class EmployeeRepository : IEmployeeRepository
{
    private readonly EnterpriseDbContext _db;

    public EmployeeRepository(EnterpriseDbContext db)
    {
        _db = db;
    }

    public Task<Employee?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
        => _db.Employees.FirstOrDefaultAsync(e => e.Id == id, cancellationToken);

    public async Task<IReadOnlyList<Employee>> GetAllAsync(CancellationToken cancellationToken = default)
        => await _db.Employees.AsNoTracking().OrderBy(e => e.DisplayName).ToListAsync(cancellationToken);

    public async Task AddAsync(Employee employee, CancellationToken cancellationToken = default)
        => await _db.Employees.AddAsync(employee, cancellationToken);

    public Task SaveChangesAsync(CancellationToken cancellationToken = default)
        => _db.SaveChangesAsync(cancellationToken);
}
