## `EnterpriseBackend.Application/Services/WorkItemService.cs`

```csharp
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;

namespace EnterpriseBackend.Application.Services;

public class WorkItemService : IWorkItemService
{
    private readonly AppDbContext _db;

    public WorkItemService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<WorkItemDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await Task.FromResult(
            _db.WorkItems.Select(w => new WorkItemDto(
                w.Id, w.Title, w.Description, w.IsCompleted, w.CreatedAt, w.UpdatedAt)).AsEnumerable());
    }

    public async Task<WorkItemDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var item = await _db.WorkItems.FindAsync([id], cancellationToken);
        return item is null
            ? null
            : new WorkItemDto(item.Id, item.Title, item.Description, item.IsCompleted, item.CreatedAt, item.UpdatedAt);
    }

    public async Task<WorkItemDto> CreateAsync(string title, string? description, CancellationToken cancellationToken = default)
    {
        var item = new WorkItem
        {
            Title = title,
            Description = description
        };

        _db.WorkItems.Add(item);
        await _db.SaveChangesAsync(cancellationToken);

        return new WorkItemDto(item.Id, item.Title, item.Description, item.IsCompleted, item.CreatedAt, item.UpdatedAt);
    }

    public async Task<bool> CompleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var item = await _db.WorkItems.FindAsync([id], cancellationToken);
        if (item is null) return false;

        item.IsCompleted = true;
        item.UpdatedAt = DateTimeOffset.UtcNow;

        await _db.SaveChangesAsync(cancellationToken);
        return true;
    }
}
```

