using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;

namespace EnterpriseBackend.Application;

public sealed class EmployeeService : IEmployeeService
{
    private readonly AppDbContext _db;

    public EmployeeService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<EmployeeDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var employee = await _db.Employees.FindAsync([id], cancellationToken);
        return employee is null ? null : Map(employee);
    }

    public async Task<IReadOnlyList<EmployeeDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var employees = await _db.Employees
            .AsNoTracking()
            .ToListAsync(cancellationToken);

        return employees.Select(Map).ToList();
    }

    public async Task<EmployeeDto> CreateAsync(CreateEmployeeRequest request, CancellationToken cancellationToken = default)
    {
        var employee = new Employee(
            Guid.NewGuid(),
            request.FirstName,
            request.LastName,
            request.Email,
            request.Department);

        _db.Employees.Add(employee);
        await _db.SaveChangesAsync(cancellationToken);

        return Map(employee);
    }

    private static EmployeeDto Map(Employee e) =>
        new(e.Id, e.FirstName, e.LastName, e.Email, e.Department);
}
