            entity.Property(e => e.Email)
                .HasMaxLength(256)
                .IsRequired();

            entity.HasIndex(e => e.Email).IsUnique();

            entity.Property(e => e.Department)
                .HasMaxLength(100)
                .IsRequired();
        });
    }
