### `src/EnterpriseBackend.Application/Services/WorkItemService.cs`
```csharp
using EnterpriseBackend.Application.DTOs;
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;

namespace EnterpriseBackend.Application.Services;

public class WorkItemService
{
    private readonly IWorkItemRepository _repository;

    public WorkItemService(IWorkItemRepository repository)
    {
        _repository = repository;
    }

    public async Task<IReadOnlyList<WorkItemDto>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        var items = await _repository.GetAllAsync(cancellationToken);
        return items.Select(Map).ToList();
    }

    public async Task<WorkItemDto?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var item = await _repository.GetByIdAsync(id, cancellationToken);
        return item is null ? null : Map(item);
    }

    public async Task<WorkItemDto> CreateAsync(string title, string? description, CancellationToken cancellationToken = default)
    {
        var item = new WorkItem(title, description);
        await _repository.AddAsync(item, cancellationToken);
        return Map(item);
    }

    public async Task<bool> MarkCompletedAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var item = await _repository.GetByIdAsync(id, cancellationToken);
        if (item is null) return false;

        item.MarkCompleted();
        await _repository.UpdateAsync(item, cancellationToken);
        return true;
    }

    public async Task<bool> DeleteAsync(Guid id, CancellationToken cancellationToken = default)
    {
        var item = await _repository.GetByIdAsync(id, cancellationToken);
        if (item is null) return false;

        await _repository.DeleteAsync(item, cancellationToken);
        return true;
    }

    private static WorkItemDto Map(WorkItem item) =>
        new(item.Id, item.Title, item.Description, item.IsCompleted, item.CreatedAt, item.CompletedAt);
}
```

