### `src/EnterpriseBackend.Infrastructure/Repositories/WorkItemRepository.cs`
```csharp
using EnterpriseBackend.Application.Interfaces;
using EnterpriseBackend.Domain.Entities;
using EnterpriseBackend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Infrastructure.Repositories;

public class WorkItemRepository : IWorkItemRepository
{
    private readonly AppDbContext _db;

    public WorkItemRepository(AppDbContext db)
    {
        _db = db;
    }

    public async Task AddAsync(WorkItem item, CancellationToken cancellationToken = default)
    {
        _db.WorkItems.Add(item);
        await _db.SaveChangesAsync(cancellationToken);
    }

    public async Task DeleteAsync(WorkItem item, CancellationToken cancellationToken = default)
    {
        _db.WorkItems.Remove(item);
        await _db.SaveChangesAsync(cancellationToken);
    }

    public async Task<IReadOnlyList<WorkItem>> GetAllAsync(CancellationToken cancellationToken = default)
    {
        return await _db.WorkItems
            .AsNoTracking()
            .OrderByDescending(x => x.CreatedAt)
            .ToListAsync(cancellationToken);
    }

    public async Task<WorkItem?> GetByIdAsync(Guid id, CancellationToken cancellationToken = default)
    {
        return await _db.WorkItems.FirstOrDefaultAsync(x => x.Id == id, cancellationToken);
    }

    public async Task UpdateAsync(WorkItem item, CancellationToken cancellationToken = default)
    {
        _db.WorkItems.Update(item);
        await _db.SaveChangesAsync(cancellationToken);
    }
}
