## 4.7 Service Implementation: `WidgetService.cs`

```csharp
using Enterprise.Backend.Application.DTOs;
using Enterprise.Backend.Application.Interfaces;
using Enterprise.Backend.Domain.Entities;
using Enterprise.Backend.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace Enterprise.Backend.Infrastructure.Repositories;

public class WidgetService : IWidgetService
{
    private readonly AppDbContext _db;

    public WidgetService(AppDbContext db)
    {
        _db = db;
    }

    public async Task<IEnumerable<WidgetReadDto>> GetAllAsync()
    {
        return await _db.Widgets
            .AsNoTracking()
            .Select(w => new WidgetReadDto
            {
                Id = w.Id,
                Name = w.Name,
                Description = w.Description,
                CreatedUtc = w.CreatedUtc
            })
            .ToListAsync();
    }

    public async Task<WidgetReadDto?> GetByIdAsync(Guid id)
    {
        var widget = await _db.Widgets.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id);
        if (widget == null) return null;

        return new WidgetReadDto
        {
            Id = widget.Id,
            Name = widget.Name,
            Description = widget.Description,
            CreatedUtc = widget.CreatedUtc
        };
    }

    public async Task<WidgetReadDto> CreateAsync(WidgetCreateDto dto)
    {
        var entity = new Widget
        {
            Name = dto.Name,
            Description = dto.Description
        };

        _db.Widgets.Add(entity);
        await _db.SaveChangesAsync();

        return new WidgetReadDto
        {
            Id = entity.Id,
            Name = entity.Name,
            Description = entity.Description,
            CreatedUtc = entity.CreatedUtc
        };
    }

    public async Task<bool> DeleteAsync(Guid id)
    {
        var entity = await _db.Widgets.FirstOrDefaultAsync(x => x.Id == id);
        if (entity == null) return false;

        _db.Widgets.Remove(entity);
        await _db.SaveChangesAsync();
        return true;
    }
}
```

