    {
        _db = db;
    }

    [HttpGet]
    public async Task<ActionResult<IEnumerable<Ticket>>> GetAll()
    {
        var tickets = await _db.Tickets
            .OrderByDescending(t => t.CreatedAtUtc)
            .ToListAsync();

        return Ok(tickets);
