## 7) `Data/AppDbContext.cs`

```csharp
using EnterpriseBackend.Api.Models;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Data;

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    public DbSet<Employee> Employees => Set<Employee>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Employee>(entity =>
        {
            entity.HasKey(e => e.Id);
            entity.Property(e => e.EmployeeNumber).HasMaxLength(50).IsRequired();
            entity.Property(e => e.FullName).HasMaxLength(200).IsRequired();
            entity.Property(e => e.Department).HasMaxLength(100).IsRequired();
            entity.HasIndex(e => e.EmployeeNumber).IsUnique();
        });
    }
}
```

