```csharp
using System.Security.Cryptography;
using System.Text;
using EnterpriseBackend.Api.Data;
using EnterpriseBackend.Api.Models;
using EnterpriseBackend.Api.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace EnterpriseBackend.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class AuthController : ControllerBase
{
    private readonly AppDbContext _db;
    private readonly ITokenService _tokenService;

    public AuthController(AppDbContext db, ITokenService tokenService)
    {
        _db = db;
        _tokenService = tokenService;
    }

    [HttpPost("login")]
    public async Task<IActionResult> Login(LoginRequest request)
    {
        var user = await _db.Users.FirstOrDefaultAsync(u => u.Username == request.Username);
        if (user == null) return Unauthorized("Invalid credentials");

        var hashed = HashPassword(request.Password);
        if (user.PasswordHash != hashed) return Unauthorized("Invalid credentials");

        var token = _tokenService.CreateToken(user);
        return Ok(new { token });
    }

    [HttpPost("seed-admin")]
    public async Task<IActionResult> SeedAdmin()
    {
        var username = "admin";
        var password = "Admin123!";

        if (await _db.Users.AnyAsync(u => u.Username == username))
            return Ok("Admin already exists");

        _db.Users.Add(new User
        {
            Username = username,
            PasswordHash = HashPassword(password),
            Role = "Admin"
        });

        await _db.SaveChangesAsync();
        return Ok("Admin created");
    }

    private static string HashPassword(string password)
    {
        using var sha256 = SHA256.Create();
        var bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(password));
        return Convert.ToHexString(bytes);
    }
}
```

