using EnterpriseBackend.Models;

namespace EnterpriseBackend.Services;

public class EmployeeService : IEmployeeService
{
    private readonly List<Employee> _employees = new()
    {
        new Employee { Id = 1, FirstName = "Jane", LastName = "Doe", Email = "jane.doe@company.com", Department = "IT" },
        new Employee { Id = 2, FirstName = "John", LastName = "Smith", Email = "john.smith@company.com", Department = "Finance" }
    };

    public IEnumerable<Employee> GetAll() => _employees;

    public Employee? GetById(int id) => _employees.FirstOrDefault(e => e.Id == id);

    public Employee Create(Employee employee)
    {
        employee.Id = _employees.Count == 0 ? 1 : _employees.Max(e => e.Id) + 1;
        _employees.Add(employee);
        return employee;
    }
}
