```csharp
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using EnterpriseBackend.Models;
using EnterpriseBackend.Services;

namespace EnterpriseBackend.Controllers;

[ApiController]
[Route("api/[controller]")]
[Authorize]
public class EmployeesController : ControllerBase
{
    private readonly IEmployeeService _employeeService;
    private readonly ILogger<EmployeesController> _logger;

    public EmployeesController(IEmployeeService employeeService, ILogger<EmployeesController> logger)
    {
        _employeeService = employeeService;
        _logger = logger;
    }

    [HttpGet]
    public ActionResult<IEnumerable<Employee>> GetAll()
    {
        _logger.LogInformation("Fetching all employees");
        return Ok(_employeeService.GetAll());
    }

    [HttpGet("{id:int}")]
    public ActionResult<Employee> GetById(int id)
    {
        var employee = _employeeService.GetById(id);
        if (employee is null) return NotFound();

        return Ok(employee);
    }

    [HttpPost]
    public ActionResult<Employee> Create([FromBody] Employee employee)
    {
        if (string.IsNullOrWhiteSpace(employee.FirstName) ||
            string.IsNullOrWhiteSpace(employee.LastName) ||
            string.IsNullOrWhiteSpace(employee.Email))
        {
            return BadRequest("FirstName, LastName, and Email are required.");
        }

        var created = _employeeService.Create(employee);
        return CreatedAtAction(nameof(GetById), new { id = created.Id }, created);
    }
}
