use bytes::Bytes;
use http_body_util::Full;
use hyper::body::Incoming;
use hyper::service::service_fn;
use hyper::{Request, Response, StatusCode};
use hyper_util::rt::TokioExecutor;
use hyper_util::server::conn::auto::Builder as AutoBuilder;
use std::convert::Infallible;
use std::net::SocketAddr;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;
    println!("Listening on http://{}", addr);

    loop {
        tokio::select! {
            biased;

            _ = shutdown_signal() => {
                println!("Shutdown signal received.");
                break;
            }

            accept_result = listener.accept() => {
                let (stream, peer_addr) = match accept_result {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("Accept error: {}", e);
                        continue;
                    }
                };

                tokio::spawn(async move {
                    let io = hyper_util::rt::TokioIo::new(stream);

                    let service = service_fn(handle_request);

                    let builder = AutoBuilder::new(TokioExecutor::new());

                    if let Err(err) = builder.serve_connection(io, service).await {
                        eprintln!("Error serving {}: {}", peer_addr, err);
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_request(req: Request<Incoming>) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&hyper::Method::GET, "/") => text_response("Hello from a high-performance Rust server!"),
        (&hyper::Method::GET, "/health") => text_response("OK"),
        (&hyper::Method::GET, "/work") => {
            // Simulate lightweight async work
            tokio::task::yield_now().await;
            text_response("Work completed")
        }
        _ => not_found(),
    };

    Ok(response)
}

fn text_response(body: &str) -> Response<RespBody> {
    Response::new(Full::new(Bytes::from(body.to_owned())))
}

fn not_found() -> Response<RespBody> {
    let mut resp = Response::new(Full::new(Bytes::from("Not Found")));
    *resp.status_mut() = StatusCode::NOT_FOUND;
    resp
}

async fn shutdown_signal() {
    let _ = signal::ctrl_c().await;
}
```

