use std::{convert::Infallible, net::SocketAddr, time::Duration};

use bytes::Bytes;
use http_body_util::Full;
use hyper::{
    body::Incoming,
    service::service_fn,
    Request, Response, StatusCode,
};
use hyper_util::{
    rt::{TokioExecutor, TokioIo},
    server::conn::auto::Builder as AutoBuilder,
};
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;
    println!("Listening on http://{}", addr);

    let shutdown = shutdown_signal();

    tokio::pin!(shutdown);

    loop {
        tokio::select! {
            biased;

            _ = &mut shutdown => {
                println!("Shutdown signal received.");
                break;
            }

            accept_res = listener.accept() => {
                let (stream, peer_addr) = match accept_res {
                    Ok(v) => v,
                    Err(e) => {
                        eprintln!("Accept error: {}", e);
                        continue;
                    }
                };

                let io = TokioIo::new(stream);

                tokio::spawn(async move {
                    let service = service_fn(move |req: Request<Incoming>| async move {
                        handle_request(req, peer_addr).await
                    });

                    let builder = AutoBuilder::new(TokioExecutor::new());

                    if let Err(err) = builder.serve_connection(io, service).await {
                        eprintln!("Connection error ({}): {}", peer_addr, err);
                    }
                });
            }
        }
    }

    Ok(())
}

async fn handle_request(
    req: Request<Incoming>,
    peer_addr: SocketAddr,
) -> Result<Response<RespBody>, Infallible> {
    let path = req.uri().path();

    let response = match path {
        "/" => Response::new(Full::new(Bytes::from_static(b"Hello from a high-performance Rust server!\n"))),

        "/health" => Response::new(Full::new(Bytes::from_static(b"OK\n"))),

        "/slow" => {
            // Example of async work without blocking the runtime
            tokio::time::sleep(Duration::from_millis(50)).await;
            Response::new(Full::new(Bytes::from(format!(
                "Slow endpoint served for {}\n",
                peer_addr
            ))))
        }

        _ => {
            let mut not_found = Response::new(Full::new(Bytes::from_static(b"Not Found\n")));
            *not_found.status_mut() = StatusCode::NOT_FOUND;
            not_found
        }
    };

    Ok(response)
}

async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c().await.expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        use tokio::signal::unix::{signal, SignalKind};

        let mut sigterm = signal(SignalKind::terminate()).expect("failed to install SIGTERM handler");
        sigterm.recv().await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {},
        _ = terminate => {},
    }
}
