    println!("Listening on http://{}", addr);

    loop {
        let (stream, peer_addr) = listener.accept().await?;
        let io = TokioIo::new(stream);

        tokio::spawn(async move {
            let service = service_fn(move |req: Request<Incoming>| async move {
                handle_request(req, peer_addr).await
            });

            if let Err(err) = http1::Builder::new()
                .keep_alive(true)
                .serve_connection(io, service)
                .await
            {
                eprintln!("connection error: {err}");
            }
        });
    }
}

async fn handle_request(
    req: Request<Incoming>,
    peer_addr: SocketAddr,
) -> Result<Response<RespBody>, Infallible> {
    let path = req.uri().path();

    let response = match path {
        "/" => text_response("Hello from a high-performance Rust server!"),
        "/health" => text_response("OK"),
        "/info" => text_response(&format!("Your address: {}", peer_addr)),
        _ => {
            let mut resp = text_response("Not Found");
            *resp.status_mut() = StatusCode::NOT_FOUND;
            resp
        }
    };

    Ok(response)
}

fn text_response(text: &str) -> Response<RespBody> {
    Response::new(Full::new(Bytes::from(text.to_owned())))
}
