use std::convert::Infallible;
use std::net::SocketAddr;
use tokio::net::TcpListener;
use tokio::signal;

type RespBody = Full<Bytes>;

#[tokio::main(flavor = "multi_thread", worker_threads = 8)]
async fn main() -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let addr: SocketAddr = "0.0.0.0:8080".parse()?;
    let listener = TcpListener::bind(addr).await?;

    println!("Listening on http://{}", addr);

    let shutdown = async {
        signal::ctrl_c().await.expect("failed to install Ctrl+C handler");
        println!("Shutdown signal received");
    };

    tokio::select! {
        _ = run_server(listener) => {},
        _ = shutdown => {},
    }

    Ok(())
}

async fn run_server(listener: TcpListener) {
    loop {
        let (stream, peer_addr) = match listener.accept().await {
            Ok(v) => v,
            Err(e) => {
                eprintln!("accept error: {}", e);
                continue;
            }
        };

        tokio::spawn(async move {
            let io = hyper_util::rt::TokioIo::new(stream);

            let service = service_fn(move |req| handle_request(req, peer_addr));

            if let Err(err) = AutoBuilder::new(TokioExecutor::new())
                .serve_connection(io, service)
                .await
            {
                eprintln!("connection error ({}): {}", peer_addr, err);
            }
        });
    }
}

async fn handle_request(
    req: Request<Incoming>,
    peer_addr: SocketAddr,
) -> Result<Response<RespBody>, Infallible> {
    let response = match (req.method(), req.uri().path()) {
        (&Method::GET, "/") => text_response("Hello from a high-performance Rust server!"),
        (&Method::GET, "/health") => text_response("OK"),
        (&Method::GET, "/peer") => text_response(&format!("Your address: {}", peer_addr)),
        _ => not_found(),
    };

    Ok(response)
}

fn text_response(text: &str) -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::OK)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from(text.to_owned())))
        .unwrap()
}

fn not_found() -> Response<RespBody> {
    Response::builder()
        .status(StatusCode::NOT_FOUND)
        .header("content-type", "text/plain; charset=utf-8")
        .body(Full::new(Bytes::from("404 Not Found")))
        .unwrap()
}
